typedef struct alignas(16) {
    uint64_t low;
    uint64_t high;
} uint128_t;

template<>
inline bool cas(volatile uint128_t *src, uint128_t cmp, uint128_t with) {
    uint64_t cmp_low = cmp.low;
    uint64_t cmp_high = cmp.high;
    uint64_t with_low = with.low;
    uint64_t with_high = with.high;
    unsigned char result = 0;

    __asm__ __volatile__ (
        "lock cmpxchg16b %1\n\t"
        "setz %0\n\t"
        : "=q" (result), "+m" (*src)
        : "a" (cmp_low), "d" (cmp_high), "b" (with_low), "c" (with_high)
        : "cc", "memory"
    );

    return result;
}

