    IHTMLDOMNode* pChild = nullptr;
    pNode->get_firstChild(&pChild);

    while (pChild != nullptr) {
        TraverseDOMHelper(pChild);
        IHTMLDOMNode* pNext = nullptr;
        pChild->get_nextSibling(&pNext);
        pChild->Release();
        pChild = pNext;
    }
}

