__global__ void calc(int total, float *values, float *newvalues) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    // Ensure we do not exceed the total number of elements
    if (idx < total - 1) {
        float a = values[idx];

        // Each thread handles a segment of the inner loop
        for (int i = idx + 1; i < total; i++) {
            float b = values[i] - a;
