void copyAndOverlay(const uint8_t* aSourceRGB, const uint8_t* aOverlayRGBA, uint8_t* aDestinationRGB, int aWidth, int aHeight) {
    int numPixels = aWidth * aHeight;
    int numPixels16 = numPixels - (numPixels % 16); // Number of pixels that can be processed in 16-pixel chunks

    __m128i zero = _mm_set1_epi8(0); // Vector of zeros

    #pragma omp parallel for
    for (int i = 0; i < numPixels16; i += 16) {
        __m128i rgba0 = _mm_loadu_si128((__m128i const*)(aOverlayRGBA + i * 4));
        __m128i rgba1 = _mm_loadu_si128((__m128i const*)(aOverlayRGBA + i * 4 + 16));
        __m128i rgba2 = _mm_loadu_si128((__m128i const*)(aOverlayRGBA + i * 4 + 32));
        __m128i rgba3 = _mm_loadu_si128((__m128i const*)(aOverlayRGBA + i * 4 + 48));

        __m128i alpha0 = _mm_shuffle_epi32(rgba0, _MM_SHUFFLE(3, 3, 3, 3));
        __m128i alpha1 = _mm_shuffle_epi32(rgba1, _MM_SHUFFLE(3, 3, 3, 3));
        __m128i alpha2 = _mm_shuffle_epi32(rgba2, _MM_SHUFFLE(3, 3, 3, 3));
        __m128i alpha3 = _mm_shuffle_epi32(rgba3, _MM_SHUFFLE(3, 3, 3, 3));

        __m128i mask0 = _mm_cmpeq_epi8(alpha0, zero);
        __m128i mask1 = _mm_cmpeq_epi8(alpha1, zero);
        __m128i mask2 = _mm_cmpeq_epi8(alpha2, zero);
        __m128i mask3 = _mm_cmpeq_epi8(alpha3, zero);

        __m128i srcRGB0 = _mm_loadu_si128((__m128i const*)(aSourceRGB + i * 3));
        __m128i srcRGB1 = _mm_loadu_si128((__m128i const*)(aSourceRGB + i * 3 + 16));
        __m128i srcRGB2 = _mm_loadu_si128((__m128i const*)(aSourceRGB + i * 3 + 32));
        __m128i srcRGB3 = _mm_loadu_si128((__m128i const*)(aSourceRGB + i * 3 + 48));

        __m128i dstRGB0 = _mm_or_si128(_mm_andnot_si128(mask0, rgba0), _mm_and_si128(mask0, srcRGB0));
        __m128i dstRGB1 = _mm_or_si128(_mm_andnot_si128(mask1, rgba1), _mm_and_si128(mask1, srcRGB1));
        __m128i dstRGB2 = _mm_or_si128(_mm_andnot_si128(mask2, rgba2), _mm_and_si128(mask2, srcRGB2));
        __m128i dstRGB3 = _mm_or_si128(_mm_andnot_si128(mask3, rgba3), _mm_and_si128(mask3, srcRGB3));

        _mm_storeu_si128((__m128i*)(aDestinationRGB + i * 3), dstRGB0);
        _mm_storeu_si128((__m128i*)(aDestinationRGB + i * 3 + 16), dstRGB1);
        _mm_storeu_si128((__m128i*)(aDestinationRGB + i * 3 + 32), dstRGB2);
        _mm_storeu_si128((__m128i*)(aDestinationRGB + i * 3 + 48), dstRGB3);
    }

    // Handle the remaining pixels (if any)
    for (int i = numPixels16; i < numPixels; ++i) {
        if (aOverlayRGBA[i * 4 + 3] == 0) {
            aDestinationRGB[i * 3] = aSourceRGB[i * 3]; // R
            aDestinationRGB[i * 3 + 1] = aSourceRGB[i * 3 + 1]; // G
            aDestinationRGB[i * 3 + 2] = aSourceRGB[i * 3 + 2]; // B
        } else {
            aDestinationRGB[i * 3] = aOverlayRGBA[i * 4]; // R
            aDestinationRGB[i * 3 + 1] = aOverlayRGBA[i * 4 + 1]; // G
            aDestinationRGB[i * 3 + 2] = aOverlayRGBA[i * 4 + 2]; // B
        }
    }
}

uint64_t getTime() {
    struct timeval tNow;
    gettimeofday(&tNow, NULL);
    return (uint64_t)tNow.tv_sec * 1000000 + (uint64_t)tNow.tv_usec;
}

int main(int argc, char **argv) {
    const int _WIDTH_ = 1920;
    const int _HEIGHT_ = 1080;
    int pixels = _WIDTH_ * _HEIGHT_ * 3;
    uint8_t *rgba = new uint8_t[_WIDTH_ * _HEIGHT_ * 4];
    uint8_t *src = new uint8_t[pixels];
    uint8_t *dst = new uint8_t[pixels];

    uint64_t tStart = getTime();

    for (int t = 0; t < 1000; ++t) {
        copyAndOverlay(src, rgba, dst, _WIDTH_, _HEIGHT_);
    }

    printf("delta: %lu\n", (getTime() - tStart) / 1000);

    delete[] rgba;
    delete[] src;
    delete[] dst;

    return 0;
}

