    int len;
};

extern "C" DLLAPI int API_ReadFile(const wchar_t* filename, DataStruct** outData)
{
    // Example implementation: Allocate memory and read file
    FILE* file = nullptr;
    errno_t err = _wfopen_s(&file, filename, L"rb");
    if (err != 0 || file == nullptr)
    {
        return -1; // Error opening file
    }

    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    fseek(file, 0, SEEK_SET);

    *outData = new DataStruct();
    (*outData)->data = new unsigned char[fileSize];
    (*outData)->len = fileSize;

    size_t bytesRead = fread((*outData)->data, 1, fileSize, file);
    fclose(file);

    if (bytesRead != fileSize)
    {
        delete[] (*outData)->data;
        delete *outData;
        return -2; // Error reading file
    }

    return 0; // Success
}

