__global__ void gameOfLife(float* returnBuffer, int width, int height) {
    __shared__ float sharedData[32][32 + 2]; // 32x32 block with a 1-pixel border

    int x = blockIdx.x * blockDim.x + threadIdx.x;
    int y = blockIdx.y * blockDim.y + threadIdx.y;

    // Load data into shared memory with a 1-pixel border
    if (x < width && y < height) {
        sharedData[threadIdx.y + 1][threadIdx.x + 1] = tex2D(inputTex, x, y);
    }

    // Load border pixels
    if (threadIdx.x == 0 && x > 0) {
        sharedData[threadIdx.y + 1][0] = tex2D(inputTex, x - 1, y);
    }
    if (threadIdx.x == blockDim.x - 1 && x < width - 1) {
        sharedData[threadIdx.y + 1][blockDim.x + 1] = tex2D(inputTex, x + 1, y);
    }
    if (threadIdx.y == 0 && y > 0) {
        sharedData[0][threadIdx.x + 1] = tex2D(inputTex, x, y - 1);
    }
    if (threadIdx.y == blockDim.y - 1 && y < height - 1) {
        sharedData[blockDim.y + 1][threadIdx.x + 1] = tex2D(inputTex, x, y + 1);
    }

    __syncthreads();

    // Compute the number of neighbors
    float neighbors = 0;
    if (x > 0 && x < width - 1 && y > 0 && y < height - 1) {
        neighbors += sharedData[threadIdx.y][threadIdx.x];
        neighbors += sharedData[threadIdx.y][threadIdx.x + 1];
        neighbors += sharedData[threadIdx.y][threadIdx.x + 2];
        neighbors += sharedData[threadIdx.y + 1][threadIdx.x];
        neighbors += sharedData[threadIdx.y + 1][threadIdx.x + 2];
        neighbors += sharedData[threadIdx.y + 2][threadIdx.x];
        neighbors += sharedData[threadIdx.y + 2][threadIdx.x + 1];
        neighbors += sharedData[threadIdx.y + 2][threadIdx.x + 2];
    }

    // Apply the rules of Conway's Game of Life
    float p = sharedData[threadIdx.y + 1][threadIdx.x + 1];
    float final = 0;
    if (neighbors < 2 || neighbors > 3) final = 0;
    else if (p != 0) final = 1;
    else if (neighbors == 3) final = 1;

    if (x < width && y < height) {
        returnBuffer[x + y * width] = final;
    }
}

class JammingWeapon : Weapon
{
    float fJamChance;
    int iJamTimer;
    bool bJammed;

    Default
    {
        fJamChance = 0.05; // 5% chance of jamming
        iJamTimer = 70; // Jamming period in tics
        bJammed = false;
    }

    States
    {
    Ready:
        WEAP B 1 A_WeaponReady;
        Loop;

    Deselect:
        TNT1 A 0 A_JamCheck; // Add the jamming check
        WEAP C 1 A_Lower;
        Loop;

    Select:
        TNT1 A 0 A_JamCheck; // Add the jamming check
        WEAP C 1 A_Raise;
        Loop;

    Fire:
        WEAP A 0 Bright A_PlaySound("weapons/pistol", CHAN_WEAPON);
        TNT1 A 0 A_JamCheck; // Add the jamming check

        WEAP A 0 A_GunFlash;
        WEAP A 1 Bright;
        WEAP A 0 A_FireBullets(1, 1, 1, 5, "BulletPuff");

        WEAP A 0 A_ReFire;
        Goto Ready;

    Flash:
        TNT1 A 0 A_JamCheck; // Add the jamming check
        Goto LightDone;

    Jam:
        WEAP A 3 A_PlaySound("weapons/jam", CHAN_WEAPON);
        WEAP A 3;
        WEAP A 3;
        WEAP A 0 A_JamCooldown;
        Goto Ready;

    LightDone:
        TNT1 A 0 A_Light0;
        Stop;
    }

    override void PostBeginPlay()
    {
        Super.PostBeginPlay();
