int findMax(const std::vector<int>& arr) {
    if (arr.empty()) {
        throw std::invalid_argument("Array is empty");
    }
    int maxElement = arr[0];
    for (int element : arr) {
        if (element > maxElement) {
            maxElement = element;
        }
    }
    return maxElement;
}

