sampler2D inputTexture : register(s0);

// Constants related to CRT
float2 resolution = float2(1280, 720); // Set your target resolution
float curveAmount = 1.5; // Adjust this to control screen curvature effect

// Function to create CRT curvature
float2 barrelDistortion(float2 coords, float curvature)
{
    float2 center = float2(0.5, 0.5);
    coords = (coords - center) * (1.0 + curvature * (distance(coords, center)));
    coords += center;
    return coords;
}

float4 main(float2 TexCoord : TEXCOORD0) : COLOR
{
    // Apply barrel distortion for curvature
    float2 uv = barrelDistortion(TexCoord, curveAmount);

    // Check whether the current texture coordinate is within the valid range [0, 1]
    if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0)
        return float4(0.0, 0.0, 0.0, 1.0);

    // Get the color of the input texture at the distorted texture coordinates
    float4 color = tex2D(inputTexture, uv);

    // Compute the scanlines effect
    float scanlineIntensity = 0.1;
    float scanlineWidth = 2.0;
    float scanlinePeriod = 4.0;
    float lineIndex = floor(TexCoord.y * resolution.y);
    float scanline = (fmod(lineIndex, scanlinePeriod) < scanlineWidth) ? scanlineIntensity : 1.0;

    // Multiply the color by the scanline intensity
    color.rgb *= scanline;

    return color;
}

