#include <vector>
#include <string>

std::string convert(std::string s, int numRows, int numColumns, char defaultChar = 'X') {
    // Initialize the matrix with the default character
    std::vector<std::vector<char>> matrix(numRows, std::vector<char>(numColumns, defaultChar));

    // Directions for moving in the matrix: right, down, left, up
    int dx[] = {0, 1, 0, -1};
    int dy[] = {1, 0, -1, 0};

    int x = 0, y = 0; // Starting position
    int direction = 0; // Initial direction (right)
    int index = 0; // Index for the string s

    while (index < s.length()) {
        matrix[x][y] = s[index++];

        // Calculate the next position
        int nextX = x + dx[direction];
        int nextY = y + dy[direction];

        // Check if the next position is out of bounds or already filled
        if (nextX < 0 || nextX >= numRows || nextY < 0 || nextY >= numColumns || matrix[nextX][nextY] != defaultChar) {
            // Change direction
            direction = (direction + 1) % 4;
            nextX = x + dx[direction];
            nextY = y + dy[direction];
        }

        // Move to the next position
        x = nextX;
        y = nextY;
    }

    // Read the matrix in a spiral order
    std::string result;
    x = 0;
    y = 0;
    direction = 0;
    int visited[numRows][numColumns] = {0}; // Track visited cells

    while (true) {
        result += matrix[x][y];
        visited[x][y] = 1;

        // Calculate the next position
        int nextX = x + dx[direction];
        int nextY = y + dy[direction];

        // Check if the next position is out of bounds or already visited
        if (nextX < 0 || nextX >= numRows || nextY < 0 || nextY >= numColumns || visited[nextX][nextY]) {
            // Change direction
            direction = (direction + 1) % 4;
            nextX = x + dx[direction];
            nextY = y + dy[direction];

            // If the next position is still out of bounds or already visited, break the loop
            if (nextX < 0 || nextX >= numRows || nextY < 0 || nextY >= numColumns || visited[nextX][nextY]) {
                break;
            }
        }

        // Move to the next position
        x = nextX;
        y = nextY;
    }

    return result;
}

int main() {
    std::string s1 = "HELLOPROGRAMMING";
    int numRows1 = 5, numColumns1 = 4;
    std::cout << convert(s1, numRows1, numColumns1) << std::endl; // Output: "HELLOGRAMMINGPROGRAMLLE"

    std::string s2 = "HELLOPROGRAMMING";
    int numRows2 = 4, numColumns2 = 4;
    std::cout << convert(s2, numRows2, numColumns2) << std::endl; // Output: "HELLOGRAMMINGPRO"

    std::string s3 = "A";
    int numRows3 = 1, numColumns3 = 1;
    std::cout << convert(s3, numRows3, numColumns3) << std::endl; // Output: "A"

    std::string s4 = "HELLO";
    int numRows4 = 3, numColumns4 = 3;
    std::cout << convert(s4, numRows4, numColumns4, 'X') << std::endl; // Output: "HELXLOX"

    return 0;
}

__global__
void rgba_to_greyscale(const uchar4* const rgbaImage,
                       unsigned char* const greyImage,
                       int numRows, int numCols)
{
    int x = blockIdx.x * blockDim.x + threadIdx.x;
    int y = blockIdx.y * blockDim.y + threadIdx.y;

    if (x >= numCols || y >= numRows) {
        return;
    }

    int index = y * numCols + x;
    uchar4 rgba = rgbaImage[index];
    float channelSum = 0.299f * rgba.x + 0.587f * rgba.y + 0.114f * rgba.z;
    greyImage[index] = static_cast<unsigned char>(channelSum);
}

