   void avx_vcmulcc(cfloat* out, const cfloat* in1, const cfloat* in2, int n) {
       for (int i = 0; i < n; i += 8) {
           __m256 a = _mm256_loadu_ps((const float*)(in1 + i));
           __m256 b = _mm256_loadu_ps((const float*)(in2 + i));

           // Complex conjugate multiply
           __m256 real_a = _mm256_permute_ps(a, _MM_SHUFFLE(2, 3, 0, 1));
           __m256 imag_a = _mm256_permute_ps(a, _MM_SHUFFLE(3, 2, 1, 0));
           __m256 real_b = _mm256_permute_ps(b, _MM_SHUFFLE(2, 3, 0, 1));
           __m256 imag_b = _mm256_permute_ps(b, _MM_SHUFFLE(3, 2, 1, 0));

           __m256 real_out = _mm256_sub_ps(_mm256_mul_ps(real_a, real_b), _mm256_mul_ps(imag_a, imag_b));
           __m256 imag_out = _mm256_add_ps(_mm256_mul_ps(real_a, imag_b), _mm256_mul_ps(imag_a, real_b));

           _mm256_storeu_ps((float*)(out + i), _mm256_permute2f128_ps(real_out, imag_out, 0x20));
       }
   }

