// Function to display the chess board
void print_board() {
    cout << endl << "   a  b  c  d  e  f  g  h" << endl;
    for (int i = 0; i < 8; i++) {
        cout << i + 1 << "  ";
        for (int j = 0; j < 8; j++) {
            cout << board[i][j] << "  ";
        }
        cout << i + 1 << endl;
    }
    cout << "   a  b  c  d  e  f  g  h" << endl << endl;
}

// Function to make a move on the board
void make_move(int from_x, int from_y, int to_x, int to_y) {
    if (is_valid_move(from_x, from_y, to_x, to_y)) {
        swap(board[from_x][from_y], board[to_x][to_y]);
    }
}

int main() {
    bool white_to_move = true;
    while (!is_gameover(white_to_move)) {
        print_board();
        cout << "It is " << ((white_to_move) ? "white" : "black") << "'s turn" << endl;
        bool valid_move = false;
        while (!valid_move) {
            string move;
            cout << "Enter your move: ";
            getline(cin, move);
            if (move.size() == 4) {
                int from_x = move[0] - 'a', from_y = move[1] - '1', to_x = move[2] - 'a', to_y = move[3] - '1';
                if (is_valid_move(from_x, from_y, to_x, to_y) && ((isupper(board[from_x][from_y]) == white_to_move))) {
                    make_move(from_x, from_y, to_x, to_y);
                    valid_move = true;
                }
            }
            if (!valid_move) {
                cout << "Invalid move. Try again." << endl;
            }
        }
        white_to_move = !white_to_move;
    }
    print_board();
    if (is_checkmate(white_to_move)) {
        cout << ((white_to_move) ? "Black" : "White") << " wins by checkmate!" << endl;
    }
    else if (is_stalemate(white_to_move)) {
        cout << "The game is a draw by stalemate." << endl;
    }
    return 0;
}

#include <iostream>
#include <sstream>
#include <vector>
#include <string>

std::vector<std::string> explode(const std::string& str, char delimiter) {
    std::vector<std::string> tokens;
    std::string token;
    std::istringstream tokenStream(str);

    while (std::getline(tokenStream, token, delimiter)) {
        tokens.push_back(token);
    }

    return tokens;
}

int main() {
    std::string text = "apple,banana,cherry";
    char delimiter = ',';

    std::vector<std::string> tokens = explode(text, delimiter);

    for (const auto& token : tokens) {
        std::cout << token << std::endl;
    }

    return 0;
}

