namespace py = pybind11;

class Foo {
public:
    Foo() {
        a = 5;
    }

    ~Foo() {}

    int a;
};

class Bar {
public:
    Bar() {
        foos.push_back(std::make_shared<Foo>());
        foos.push_back(std::make_shared<Foo>());
    }
    ~Bar() {}

    std::vector<std::shared_ptr<Foo>> foos;
};

PYBIND11_MODULE(pybug, m) {
    py::class_<Foo, std::shared_ptr<Foo>> foo(m, "Foo", py::dynamic_attr());
    foo
        .def(py::init<>())
        .def_readwrite("a", &Foo::a);

    py::class_<Bar> bar(m, "Bar");
    bar
        .def(py::init<>())
        .def_property_readonly("foos", [](Bar &b) {
            static std::unordered_map<std::shared_ptr<Foo>, py::object> cache;
            py::list result;
            for (const auto &ptr : b.foos) {
                auto it = cache.find(ptr);
                if (it == cache.end()) {
                    py::object obj = py::cast(ptr, py::return_value_policy::reference);
                    cache[ptr] = obj;
                    result.append(obj);
                } else {
                    result.append(it->second);
                }
            }
            return result;
        });
}

