using namespace std;

// Function to parse and calculate the value of a given formula
string parseFormula(string formula, vector<pair<string, string>> variables) {
    stringstream ss;
    string result;
    ss << formula;

    string token;
    while (getline(ss, token, ' ')) {
        bool found = false;
        for (const auto& variable : variables) {
            if (token == variable.first) {
                token = variable.second;
                found = true;
                break;
            }
        }
        if (!found)
            break;
    }

    try {
        result = to_string(eval(token));
    }
    catch (...) {
        result = "Invalid formula";
    }

    return result;
}

// Function to evaluate a mathematical expression
double eval(string expr) {
    stringstream ss(expr);
    double result;
    ss >> result;
    char op;
    double operand;

    while (ss >> op >> operand) {
        switch (op) {
        case '+':
            result += operand;
            break;
        case '-':
            result -= operand;
            break;
        case '*':
            result *= operand;
            break;
        case '/':
            result /= operand;
            break;
        }
    }

    return result;
}

int main() {
    string inputFile = "formula.txt";
    ifstream file(inputFile);
    string line;
    vector<pair<string, string>> formulas;

    // Read formulas into a vector
    while (getline(file, line)) {
        size_t pos = line.find("=");
        if (pos != string::npos) {
            string formula = line.substr(pos + 1);
            string keywords = line.substr(0, pos - 1);
            formulas.push_back(make_pair(keywords, formula));
        }
    }
    file.close();

    // Prompt user for input
    string input;
    cout << "Enter the required calculation (e.g., work in Joules, if voltage=5V, I=1A, t=10 seconds): ";
    getline(cin, input);

    // Extract formula keywords and variable values
    vector<pair<string, string>> variables;
    stringstream ss(input);
    string keywords;
    string variable;
    while (getline(ss, variable, ',')) {
        size_t pos = variable.find("=");
        if (pos != string::npos) {
            string keyword = variable.substr(0, pos);
            string value = variable.substr(pos + 1);
            variables.push_back(make_pair(keyword, value));
        }
        else {
            keywords += variable;
        }
    }

    // Find matching formula and calculate the result
    for (const auto& formula : formulas) {
        if (formula.first.find(keywords) != string::npos) {
            string result = parseFormula(formula.second, variables);
            cout << formula.first << ": " << result << endl;
        }
    }

    return 0;
}

#include <stdio.h>
#include <string.h>
#include <sys/mman.h>

void* allocate_executable_memory(size_t size) {
    void *ptr = mmap(
        0,
        size,
        PROT_READ | PROT_WRITE | PROT_EXEC,
        MAP_PRIVATE | MAP_ANONYMOUS,
        -1,
        0
    );
    if (ptr == (void*)(-1)) {
        perror("mmap");
        return nullptr;
    }
    return ptr;
};

void emit_code_into_memory(size_t code_length, const uint8_t *code, void *memory) {
    memcpy(reinterpret_cast<uint8_t*>(memory), code, code_length);
};

typedef void (*JittedFunc)();

int main() {
    uint8_t code[] = {
        0x48, 0xc7, 0xc0, 0x01, 0x00, 0x00, 0x00,  // mov rax, 1 (sys_write)
        0x48, 0xc7, 0xc7, 0x01, 0x00, 0x00, 0x00,  // mov rdi, 1 (stdout)
        0x48, 0xc7, 0xc6, 0x01, 0x00, 0x00, 0x00,  // mov rsi, message
        0x48, 0xc7, 0xc2, 0x01, 0x00, 0x00, 0x00,  // mov rdx, 1 (message length)
        0x0f, 0x05,                                // syscall
        0x48, 0xc7, 0xc0, 0x3c, 0x00, 0x00, 0x00,  // mov rax, 60 (sys_exit)
        0x48, 0x31, 0xff,                          // xor rdi, rdi (exit code 0)
        0x0f, 0x05                                 // syscall
    };

    void *memory = allocate_executable_memory(sizeof(code));
    emit_code_into_memory(sizeof(code), code, memory);
    JittedFunc func = reinterpret_cast<JittedFunc>(memory);
    func();

    return 0;
};

