    BinaryHeap heap;
    heap.insert(3);
    heap.insert(2);
    heap.insert(15);
    heap.insert(5);
    heap.insert(4);
    heap.insert(45);

    while (!heap.isEmpty()) {
        std::cout << heap.extractMin() << " ";
    }

    return 0;
}

