using namespace std;

struct City {
    int id;
    double x, y;
};

double distance(City &a, City &b) {
    return sqrt(pow(a.x - b.x, 2) + pow(a.y - b.y, 2));
}

double pathLength(const vector<City> &path) {
    double total = 0.0;
    for (size_t i = 0; i < path.size(); ++i) {
        total += distance(path[i], path[(i + 1) % path.size()]);
    }
    return total;
}

vector<vector<double>> calculateDistanceMatrix(const vector<City> &cities) {
    int n = cities.size();
    vector<vector<double>> dist(n, vector<double>(n));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            dist[i][j] = distance(cities[i], cities[j]);
        }
    }
    return dist;
}

vector<int> crossover(const vector<int> &parent1, const vector<int> &parent2) {
    int n = parent1.size();
    int start = rand() % n;
    int end = rand() % n;
    if (start > end) swap(start, end);

    vector<int> child(n, -1);
    for (int i = start; i <= end; ++i) {
        child[i] = parent1[i];
    }

    for (int i = 0, j = 0; i < n; ++i) {
        if (find(child.begin(), child.end(), parent2[i]) == child.end()) {
            while (child[j] != -1) j++;
            child[j] = parent2[i];
        }
    }
    return child;
}

void mutate(vector<int> &individual, double mutationRate) {
    for (int i = 0; i < individual.size(); ++i) {
        if (rand() / double(RAND_MAX) < mutationRate) {
            int j = rand() % individual.size();
            swap(individual[i], individual[j]);
        }
    }
}

vector<int> geneticAlgorithm(const vector<City> &cities, int popSize, double mutationRate, int generations) {
    int n = cities.size();
    vector<vector<int>> population(popSize, vector<int>(n));
    for (int i = 0; i < popSize; ++i) {
        for (int j = 0; j < n; ++j) {
            population[i][j] = j;
        }
        random_shuffle(population[i].begin(), population[i].end());
    }

    for (int gen = 0; gen < generations; ++gen) {
        vector<pair<double, vector<int>>> fitnessPairs;
        for (const auto &individual : population) {
            fitnessPairs.push_back({pathLength(cities, individual), individual});
        }
        sort(fitnessPairs.begin(), fitnessPairs.end());

        vector<vector<int>> newPopulation;
        for (int i = 0; i < popSize / 2; ++i) {
            newPopulation.push_back(fitnessPairs[i].second);
        }

        while (newPopulation.size() < popSize) {
            int parent1 = rand() % newPopulation.size();
            int parent2 = rand() % newPopulation.size();
            vector<int> child = crossover(newPopulation[parent1], newPopulation[parent2]);
            mutate(child, mutationRate);
            newPopulation.push_back(child);
        }

        population = newPopulation;
    }

    return fitnessPairs[0].second; // Return the best individual
}

int main() {
    vector<City> cities = {{0, 0, 0}, {1, 1, 2}, {2, 3, 1}, {3, 5, 5}, {4, 6, 2}};
    int popSize = 100;
    double mutationRate = 0.01;
    int generations = 1000;

    vector<int> bestPath = geneticAlgorithm(cities, popSize, mutationRate, generations);
    cout << "Best Path: ";
    for (int city : bestPath) {
        cout << cities[city].id << " ";
    }
    cout << "\nPath Length: " << pathLength(cities, bestPath) << endl;

    return 0;
}

