using T = uint32_t; // or uint64_t

T shift(T x, T y, T n)
{
    return _shrd(x, y, n);
}

// Note: _shrd is a 32-bit operation. For 64-bit, use _shrdq.

__inline__ __device__ uint32_t per_byte_bit_left_rotate(uint32_t input, uint8_t amount) {
    uint32_t result = 0;
    uint32_t mask = (1 << amount) - 1;

    for (int i = 0; i < 4; ++i) {
        uint8_t byte = (input >> (8 * i)) & 0xFF;
        uint8_t rotated = ((byte << amount) & 0xFF) | (byte >> (8 - amount));
        result |= rotated << (8 * i);
    }

    return result;
}

#include <vector>
using namespace std;

void merge(vector<int>& nums1, int m, vector<int>& nums2, int n) {
    int i = m - 1; // Pointer for nums1
    int j = n - 1; // Pointer for nums2
    int k = m + n - 1; // Pointer for the end of the merged array

    // Merge in reverse order
    while (i >= 0 && j >= 0) {
        if (nums1[i] > nums2[j]) {
            nums1[k] = nums1[i];
            // Skip duplicates in nums1
            while (i > 0 && nums1[i] == nums1[i - 1]) i--;
            i--;
        } else if (nums1[i] < nums2[j]) {
            nums1[k] = nums2[j];
            // Skip duplicates in nums2
            while (j > 0 && nums2[j] == nums2[j - 1]) j--;
            j--;
        } else {
            nums1[k] = nums1[i];
            k--;
            nums1[k] = nums2[j];
            // Skip duplicates in both nums1 and nums2
            while (i > 0 && nums1[i] == nums1[i - 1]) i--;
            i--;
            while (j > 0 && nums2[j] == nums2[j - 1]) j--;
            j--;
        }
        k--;
    }

    // Copy remaining elements from nums2, if any
    while (j >= 0) {
        nums1[k] = nums2[j];
        // Skip duplicates in nums2
        while (j > 0 && nums2[j] == nums2[j - 1]) j--;
        j--;
        k--;
    }

    // Ensure the resulting vector has no more than m + n elements
    nums1.resize(m + n);
}

// Example usage
int main() {
    vector<int> nums1 = {1, 2, 3, 0, 0, 0};
    int m = 3;
    vector<int> nums2 = {2, 5, 6};
    int n = 3;
    merge(nums1, m, nums2, n);
    for (int num : nums1) {
        cout << num << " ";
    }
    return 0;
}

