#include <SFML/Graphics.hpp>
#include <SFML/Window.hpp>
#include <SFML/System.hpp>

const int WINDOW_WIDTH = 800;
const int WINDOW_HEIGHT = 600;
const float PADDLE_SPEED = 5.0f;
const float BALL_RADIUS = 10.0f;
const float BALL_SPEED = 3.0f;

class Paddle {
public:
    sf::RectangleShape shape;
    float speed;

    Paddle(float x, float y, float w, float h, float s) {
        shape.setPosition(x, y);
        shape.setSize({w, h});
        shape.setFillColor(sf::Color::White);
        speed = s;
    }

    void moveUp() {
        sf::Vector2f position = shape.getPosition();
        if (position.y > 0) {
            shape.move(0, -speed);
        }
    }

    void moveDown() {
        sf::Vector2f position = shape.getPosition();
        if (position.y + shape.getSize().y < WINDOW_HEIGHT) {
            shape.move(0, speed);
        }
    }
};

class Ball {
public:
    sf::CircleShape shape;
    sf::Vector2f direction;
    float speed;

    Ball(float x, float y, float r) {
        shape.setPosition(x, y);
        shape.setRadius(r);
        shape.setFillColor(sf::Color::White);
        direction = {1.0f, 1.0f};
        speed = BALL_SPEED;
    }

    void update() {
        sf::Vector2f position = shape.getPosition();
        position += direction * speed;
        if (position.x <= 0 || position.x + 2 * BALL_RADIUS >= WINDOW_WIDTH) {
            direction.x = -direction.x;
        }
        if (position.y <= 0 || position.y + 2 * BALL_RADIUS >= WINDOW_HEIGHT) {
            direction.y = -direction.y;
        }
        shape.setPosition(position);
    }
};

int main() {
    sf::RenderWindow window(sf::VideoMode(WINDOW_WIDTH, WINDOW_HEIGHT), "Pong");

    Paddle player1(50, WINDOW_HEIGHT / 2 - 50, 20, 100, PADDLE_SPEED);
    Paddle player2(WINDOW_WIDTH - 70, WINDOW_HEIGHT / 2 - 50, 20, 100, PADDLE_SPEED);
    Ball ball(WINDOW_WIDTH / 2 - BALL_RADIUS, WINDOW_HEIGHT / 2 - BALL_RADIUS, BALL_RADIUS);

    while (window.isOpen()) {
        sf::Event event;
        while (window.pollEvent(event)) {
            if (event.type == sf::Event::Closed)
                window.close();
        }

        if (sf::Keyboard::isKeyPressed(sf::Keyboard::W)) player1.moveUp();
        if (sf::Keyboard::isKeyPressed(sf::Keyboard::S)) player1.moveDown();
        // AI for player2
        if (ball.shape.getPosition().y > player2.shape.getPosition().y + 50) player2.moveDown();
        if (ball.shape.getPosition().y < player2.shape.getPosition().y + 50) player2.moveUp();

        ball.update();

        window.clear(sf::Color::Black);
        window.draw(player1.shape);
        window.draw(player2.shape);
        window.draw(ball.shape);
        window.display();
    }

    return 0;
}

