#include <iostream>

class PriorityQueue {
public:
    PriorityQueue();
    ~PriorityQueue();
    void enqueue(int value, int priority);
    int dequeue();
    bool isEmpty() const;
    void display() const;
private:
    struct Node {
        int value;
        int priority;
        Node* next;
    };
    Node* front;
};

PriorityQueue::PriorityQueue() {
    front = nullptr;
}

PriorityQueue::~PriorityQueue() {
    while (!isEmpty()) {
        dequeue();
    }
}

void PriorityQueue::enqueue(int value, int priority) {
    Node* newNode = new Node;
    newNode->value = value;
    newNode->priority = priority;
    newNode->next = nullptr;

    if (isEmpty() || priority > front->priority) {
        newNode->next = front;
        front = newNode;
    } else {
        Node* temp = front;
        while (temp->next != nullptr && temp->next->priority >= priority) {
            temp = temp->next;
        }
        newNode->next = temp->next;
        temp->next = newNode;
    }
}

int PriorityQueue::dequeue() {
    if (isEmpty()) {
        throw "The priority queue is empty, can't dequeue.";
    }

    Node* temp = front;
    int value = front->value;
    front = front->next;
    delete temp;
    return value;
}

bool PriorityQueue::isEmpty() const {
    return front == nullptr;
}

void PriorityQueue::display() const {
    Node* temp = front;
    while (temp != nullptr) {
        std::cout << temp->value << " (priority: " << temp->priority << ") -> ";
        temp = temp->next;
    }
    std::cout << "end" << std::endl;
}

int main() {
    PriorityQueue pq;

    pq.enqueue(10, 3);
    pq.enqueue(5, 1);
    pq.enqueue(3, 4);
    pq.enqueue(20, 2);

    pq.display();

    std::cout << "Dequeued: " << pq.dequeue() << std::endl;
    std::cout << "Dequeued: " << pq.dequeue() << std::endl;

    pq.display();

    return 0;
}

#include <iostream>
#include <vector>
#include <string>

void printLCS(const std::string& X, const std::string& Y, int m, int n, std::vector<std::vector<int>>& b) {
    if (m == 0 || n == 0) return;
    if (b[m][n] == 1) {  // 1 indicates X[m-1] == Y[n-1]
        printLCS(X, Y, m - 1, n - 1, b);
        std::cout << X[m - 1];
    } else if (b[m][n] == 2) {  // 2 indicates c[m-1][n] >= c[m][n-1]
        printLCS(X, Y, m - 1, n, b);
    } else {  // 3 indicates c[m-1][n] < c[m][n-1]
        printLCS(X, Y, m, n - 1, b);
    }
}

std::string findLCS(const std::string& X, const std::string& Y) {
    int m = X.length();
    int n = Y.length();
    std::vector<std::vector<int>> c(m + 1, std::vector<int>(n + 1, 0));
    std::vector<std::vector<int>> b(m + 1, std::vector<int>(n + 1, 0));

    for (int i = 1; i <= m; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (X[i - 1] == Y[j - 1]) {
                c[i][j] = c[i - 1][j - 1] + 1;
                b[i][j] = 1;  // X[i-1] == Y[j-1]
            } else if (c[i - 1][j] >= c[i][j - 1]) {
                c[i][j] = c[i - 1][j];
                b[i][j] = 2;  // c[i-1][j] >= c[i][j-1]
            } else {
                c[i][j] = c[i][j - 1];
                b[i][j] = 3;  // c[i-1][j] < c[i][j-1]
            }
        }
    }

    std::cout << "The longest common subsequence is: ";
    printLCS(X, Y, m, n, b);
    std::cout << std::endl;

    return X;  // Return X or Y, the function is mainly for printing the LCS
}

int main() {
    std::string X = "ABCBDAB";
    std::string Y = "BDCAB";
    findLCS(X, Y);
    return 0;
}

