// Define a city as a pair of coordinates
struct City {
    int x, y;
};

// Calculate the Euclidean distance between two cities
double distance(const City& a, const City& b) {
    return std::sqrt(std::pow(a.x - b.x, 2) + std::pow(a.y - b.y, 2));
}

// Calculate the total distance of a route
double route_distance(const std::vector<City>& cities, const std::vector<int>& route) {
    double total_distance = 0.0;
    for (size_t i = 0; i < route.size(); ++i) {
        total_distance += distance(cities[route[i]], cities[route[(i + 1) % route.size()]]);
    }
    return total_distance;
}

// Generate a random route
std::vector<int> generate_random_route(size_t num_cities) {
    std::vector<int> route(num_cities);
    for (size_t i = 0; i < num_cities; ++i) {
        route[i] = i;
    }
    std::random_shuffle(route.begin(), route.end());
    return route;
}

// Ordered crossover
std::vector<int> ordered_crossover(const std::vector<int>& parent1, const std::vector<int>& parent2) {
    size_t start = std::rand() % parent1.size();
    size_t end = std::rand() % parent1.size();
    if (start > end) std::swap(start, end);

    std::vector<int> child(parent1.size(), -1);
    for (size_t i = start; i <= end; ++i) {
        child[i] = parent1[i];
    }

    size_t index = (end + 1) % parent1.size();
    for (size_t i = 0; i < parent2.size(); ++i) {
        if (std::find(child.begin(), child.end(), parent2[i]) == child.end()) {
            child[index] = parent2[i];
            index = (index + 1) % parent1.size();
        }
    }
    return child;
}

// Mutation: swap two cities in the route
void mutate(std::vector<int>& route, double mutation_rate) {
    for (size_t i = 0; i < route.size(); ++i) {
        if (std::rand() / static_cast<double>(RAND_MAX) < mutation_rate) {
            size_t j = std::rand() % route.size();
            std::swap(route[i], route[j]);
        }
    }
}

// Selection: tournament selection
std::vector<int> select_route(const std::vector<std::vector<int>>& population, const std::vector<City>& cities) {
    size_t tournament_size = 5;
    std::vector<int> best_route = population[0];
    double best_fitness = route_distance(cities, best_route);

    for (size_t i = 0; i < tournament_size; ++i) {
        size_t idx = std::rand() % population.size();
        double fitness = route_distance(cities, population[idx]);
        if (fitness < best_fitness) {
            best_fitness = fitness;
            best_route = population[idx];
        }
    }
    return best_route;
}

// Genetic Algorithm
std::vector<int> genetic_algorithm(const std::vector<City>& cities, size_t population_size, size_t generations, double mutation_rate) {
    std::vector<std::vector<int>> population(population_size);
    for (size_t i = 0; i < population_size; ++i) {
        population[i] = generate_random_route(cities.size());
    }

    for (size_t generation = 0; generation < generations; ++generation) {
        std::vector<std::vector<int>> new_population(population_size);

        for (size_t i = 0; i < population_size; ++i) {
            std::vector<int> parent1 = select_route(population, cities);
            std::vector<int> parent2 = select_route(population, cities);
            std::vector<int> child = ordered_crossover(parent1, parent2);
            mutate(child, mutation_rate);
            new_population[i] = child;
        }

        population = new_population;
    }

    std::vector<int> best_route = population[0];
    double best_fitness = route_distance(cities, best_route);

    for (const auto& route : population) {
        double fitness = route_distance(cities, route);
        if (fitness < best_fitness) {
            best_fitness = fitness;
            best_route = route;
        }
    }

    return best_route;
}

int main() {
    std::vector<City> cities = {
        {0, 0}, {1, 2}, {3, 1}, {5, 2}, {2, 4}, {4, 5}, {6, 3}, {7, 1}, {8, 2}, {9, 4}
    };

    size_t population_size = 100;
    size_t generations = 1000;
    double mutation_rate = 0.01;

    std::vector<int> best_route = genetic_algorithm(cities, population_size, generations, mutation_rate);

    std::cout << "Best Route: ";
    for (int city : best_route) {
        std::cout << city << " ";
    }
    std::cout << std::endl;

    double best_fitness = route_distance(cities, best_route);
    std::cout << "Best Fitness (Total Distance): " << best_fitness << std::endl;

    return 0;
}

