// A map to store the native objects
std::map<long, RFEthernetDetector*> handleMap;

// Function to generate a unique handle
long generateHandle() {
    static long nextHandle = 1;
    return nextHandle++;
}

// Native constructor
JNIEXPORT jlong JNICALL Java_RFEthernetDetector_init(JNIEnv *env, jobject thisObj, jint portNumber) {
    RFEthernetDetector *rfDetector = new RFEthernetDetector(static_cast<WORD>(portNumber));
    long handle = generateHandle();
    handleMap[handle] = rfDetector;
    return handle;
}

// Native method to perform some action
JNIEXPORT void JNICALL Java_RFEthernetDetector_doSomething(JNIEnv *env, jobject thisObj) {
    jlong handle = env->GetLongField(thisObj, env->GetFieldID(env->GetObjectClass(thisObj), "nativeHandle", "J"));
    RFEthernetDetector *rfDetector = handleMap[handle];
    rfDetector->doSomething();
}

// Native method to clean up resources
