  void* Ptr;
};

struct TVersionizedPointerStorage {
  char data[2 * sizeof(TVersionizedPointer)];
};

TVersionizedPointer* GetVersionizedPointer(TVersionizedPointerStorage& PointerStorage) {
  const size_t vp_size = sizeof(TVersionizedPointer);
  void* alignedAddress = reinterpret_cast<void*>(reinterpret_cast<std::intptr_t>(&PointerStorage) + (vp_size - 1));
