// Helper function to print an array of EmailAddress
void PrintEmailAddressArray(SAFEARRAY* pArray)
{
    if (pArray == nullptr)
    {
        std::wcout << L"Array is null" << std::endl;
        return;
    }

    long lLBound, lUBound;
    SafeArrayGetLBound(pArray, 1, &lLBound);
    SafeArrayGetUBound(pArray, 1, &lUBound);

    for (long i = lLBound; i <= lUBound; i++)
    {
        EmailAddress* pEmail = nullptr;
        HRESULT hr = SafeArrayGetElement(pArray, &i, &pEmail);
        if (SUCCEEDED(hr))
        {
            std::wcout << L"Address: " << pEmail->Address << L", Name: " << pEmail->Name << std::endl;
        }
    }
}

