int OnCalculate(const int rates_total, const int prev_calculated, const datetime &time[], const double &open[], const double &high[], const double &low[], const double &close[], const long &tick_volume[], const long &volume[], const int &spread[])
  {
   if(rates_total < Lookback)
      return(0);

   ArraySetAsSeries(SupportBuffer,true);
   ArraySetAsSeries(ResistanceBuffer,true);

   for(int i = Lookback; i < rates_total && !IsStopped(); i++)
     {
      // Calculate support from the lowest lows
      double support = low[i];
      for(int j = 1; j < Lookback; j++)
        {
         if(low[i-j] < support)
            support = low[i-j];
        }
      SupportBuffer[i] = support;

      // Calculate resistance from the highest highs
      double resistance = high[i];
      for(int j = 1; j < Lookback; j++)
        {
         if(high[i-j] > resistance)
            resistance = high[i-j];
        }
      ResistanceBuffer[i] = resistance;
     }

   return rates_total;
  }

