class Employee {
public:
    // Constructor
    Employee(int id = 0, const std::string& name = "", const std::string& position = "", double salary = 0.0)
        : id(id), name(name), position(position), salary(salary) {}

    // Destructor
    ~Employee() {}

    // Getters
    int getId() const { return id; }
    std::string getName() const { return name; }
    std::string getPosition() const { return position; }
    double getSalary() const { return salary; }

    // Setters
    void setId(int id) { this->id = id; }
    void setName(const std::string& name) { this->name = name; }
    void setPosition(const std::string& position) { this->position = position; }
    void setSalary(double salary) { this->salary = salary; }

    // Method to load data from the database
    static std::vector<std::shared_ptr<Employee>> loadEmployeesFromDatabase(const std::string& dbPath) {
        sqlite3* db;
        int rc = sqlite3_open(dbPath.c_str(), &db);
        if (rc) {
            std::cerr << "Can't open database: " << sqlite3_errmsg(db) << std::endl;
            return {};
        }

        std::vector<std::shared_ptr<Employee>> employees;
        std::string sql = "SELECT id, name, position, salary FROM employees;";

        sqlite3_stmt* stmt;
        rc = sqlite3_prepare_v2(db, sql.c_str(), -1, &stmt, nullptr);
        if (rc != SQLITE_OK) {
            std::cerr << "Failed to prepare statement: " << sqlite3_errmsg(db) << std::endl;
            sqlite3_close(db);
            return {};
        }

        while (sqlite3_step(stmt) == SQLITE_ROW) {
            int id = sqlite3_column_int(stmt, 0);
            std::string name = reinterpret_cast<const char*>(sqlite3_column_text(stmt, 1));
            std::string position = reinterpret_cast<const char*>(sqlite3_column_text(stmt, 2));
            double salary = sqlite3_column_double(stmt, 3);

            employees.push_back(std::make_shared<Employee>(id, name, position, salary));
        }

        sqlite3_finalize(stmt);
        sqlite3_close(db);

        return employees;
    }

private:
    int id;
    std::string name;
    std::string position;
    double salary;
};

int main() {
    // Example usage
    std::vector<std::shared_ptr<Employee>> employees = Employee::loadEmployeesFromDatabase("example.db");

    for (const auto& employee : employees) {
        std::cout << "ID: " << employee->getId() << ", Name: " << employee->getName()
                  << ", Position: " << employee->getPosition() << ", Salary: " << employee->getSalary() << std::endl;
    }

    return 0;
}

