namespace py = pybind11;

class Matrix3D {
public:
    std::vector<std::vector<std::vector<double>>> data;
    int n, m, p;

    // Constructor
    Matrix3D(int n, int m, int p) : n(n), m(m), p(p) {
        data.resize(n, std::vector<std::vector<double>>(m, std::vector<double>(p, 0.0)));
    }

    // Overloaded operator() for element access
    double& operator()(int i, int j, int k) {
        return data[i][j][k];
    }

    // Function to convert Matrix3D to a NumPy array
    py::array_t<double> to_numpy() const {
        py::array_t<double> np_array({n, m, p});
        auto r = np_array.mutable_unchecked<3>();
        for (size_t i = 0; i < n; ++i) {
            for (size_t j = 0; j < m; ++j) {
                for (size_t k = 0; k < p; ++k) {
                    r(i, j, k) = data[i][j][k];
                }
            }
        }
        return np_array;
    }

    // Function to convert a NumPy array to Matrix3D
    static Matrix3D from_numpy(const py::array_t<double>& np_array) {
        auto r = np_array.unchecked<3>();
        Matrix3D matrix(r.shape(0), r.shape(1), r.shape(2));
        for (size_t i = 0; i < r.shape(0); ++i) {
            for (size_t j = 0; j < r.shape(1); ++j) {
                for (size_t k = 0; k < r.shape(2); ++k) {
                    matrix.data[i][j][k] = r(i, j, k);
                }
            }
        }
        return matrix;
    }
};

