#include <complex>
#include <cmath>
#include <vector>

// Function to solve the cubic equation ax^3 + bx^2 + cx + d = 0
std::vector<std::complex<double>> solveCubic(double a, double b, double c, double d) {
    if (a == 0) {
        throw std::invalid_argument("Coefficient 'a' must not be zero for a cubic equation.");
    }

    // Normalize the equation
    double b_over_a = b / a;
    double c_over_a = c / a;
    double d_over_a = d / a;

    // Convert to the depressed cubic form: t^3 + pt + q = 0
    double p = c_over_a - (b_over_a * b_over_a) / 3.0;
    double q = d_over_a + (2.0 * b_over_a * b_over_a * b_over_a) / 27.0 - (b_over_a * c_over_a) / 3.0;

    // Calculate discriminant
    double discriminant = (q * q) / 4.0 + (p * p * p) / 27.0;

    std::vector<std::complex<double>> roots;

    if (discriminant > 0) {
        // One real root and two complex roots
        double u = cbrt(-q / 2.0 + sqrt(discriminant));
        double v = cbrt(-q / 2.0 - sqrt(discriminant));
        double real_root = u + v - b_over_a / 3.0;
        roots.push_back(real_root);

        std::complex<double> complex_root1 = std::complex<double>(-0.5 * (u + v) - b_over_a / 3.0, sqrt(3) * 0.5 * (u - v));
        std::complex<double> complex_root2 = std::complex<double>(-0.5 * (u + v) - b_over_a / 3.0, -sqrt(3) * 0.5 * (u - v));
        roots.push_back(complex_root1);
        roots.push_back(complex_root2);
    } else if (discriminant == 0) {
        // All roots are real and at least two are equal
        double u = cbrt(-q / 2.0);
        double real_root1 = 2 * u - b_over_a / 3.0;
        double real_root2 = -u - b_over_a / 3.0;
        roots.push_back(real_root1);
        roots.push_back(real_root2);
        roots.push_back(real_root2);
    } else {
        // All roots are real and unequal
        double r = sqrt(-p / 3.0);
        double theta = acos(-q / (2.0 * r * r * r));
        double k = 2.0 * r;
        double root1 = k * cos(theta / 3.0) - b_over_a / 3.0;
        double root2 = k * cos((theta + 2.0 * M_PI) / 3.0) - b_over_a / 3.0;
        double root3 = k * cos((theta + 4.0 * M_PI) / 3.0) - b_over_a / 3.0;
        roots.push_back(root1);
        roots.push_back(root2);
        roots.push_back(root3);
    }

    return roots;
}

int main() {
    double a = 1.0, b = -6.0, c = 11.0, d = -6.0; // Example coefficients for x^3 - 6x^2 + 11x - 6 = 0
    std::vector<std::complex<double>> roots = solveCubic(a, b, c, d);

    std::cout << "The roots of the cubic equation are:" << std::endl;
    for (const auto& root : roots) {
        std::cout << root << std::endl;
    }

    return 0;
}

