#include <v8.h>
#include <libplatform/libplatform.h>
#include <iostream>

using v8::Context;
using v8::Function;
using v8::FunctionCallbackInfo;
using v8::FunctionTemplate;
using v8::Isolate;
using v8::Local;
using v8::Number;
using v8::Object;
using v8::Persistent;
using v8::PropertyCallbackInfo;
using v8::String;
using v8::Value;

// C++ class representing the generator
class MyGenerator {
public:
  MyGenerator(int start, int end) : current(start), end(end) {}

  bool hasNext() const {
    return current < end;
  }

  int next() {
    return current++;
  }

private:
  int current;
  int end;
};

// C++ function to create a new generator instance
void New(const FunctionCallbackInfo<Value>& args) {
  Isolate* isolate = args.GetIsolate();
  Local<Context> context = isolate->GetCurrentContext();

  if (args.IsConstructCall()) {
    int start = args[0]->IntegerValue(context).ToChecked();
    int end = args[1]->IntegerValue(context).ToChecked();

    MyGenerator* gen = new MyGenerator(start, end);
    args.This()->SetInternalField(0, External::New(isolate, gen));

    args.GetReturnValue().Set(args.This());
  } else {
    Local<Function> cons = Local<Function>::New(isolate, constructor);
    Local<Value> argv[2] = { args[0], args[1] };
    args.GetReturnValue().Set(cons->NewInstance(context, 2, argv).ToLocalChecked());
  }
}

// C++ function to implement the `next` method
void Next(const FunctionCallbackInfo<Value>& args) {
  Isolate* isolate = args.GetIsolate();
  Local<Context> context = isolate->GetCurrentContext();
  MyGenerator* gen = static_cast<MyGenerator*>(args.This()->GetInternalField(0).As<External>()->Value());

  if (gen->hasNext()) {
    int value = gen->next();
    Local<Object> result = Object::New(isolate);
    result->Set(context, String::NewFromUtf8(isolate, "value").ToLocalChecked(), Number::New(isolate, value));
    result->Set(context, String::NewFromUtf8(isolate, "done").ToLocalChecked(), Boolean::New(isolate, false));
    args.GetReturnValue().Set(result);
  } else {
    Local<Object> result = Object::New(isolate);
    result->Set(context, String::NewFromUtf8(isolate, "value").ToLocalChecked(), Undefined(isolate));
    result->Set(context, String::NewFromUtf8(isolate, "done").ToLocalChecked(), Boolean::New(isolate, true));
    args.GetReturnValue().Set(result);
  }
}

// C++ function to implement the `Symbol.iterator` method
void GetIterator(const PropertyCallbackInfo<Value>& args) {
  Isolate* isolate = args.GetIsolate();
  Local<Context> context = isolate->GetCurrentContext();
  args.GetReturnValue().Set(args.Holder());
}

// Persistent reference to the constructor
Persistent<Function> MyGenerator::constructor;

void Initialize(Local<Object> exports) {
  Isolate* isolate = exports->GetIsolate();

  // Prepare constructor template
  Local<FunctionTemplate> tpl = FunctionTemplate::New(isolate, New);
  tpl->SetClassName(String::NewFromUtf8(isolate, "MyGenerator").ToLocalChecked());
  tpl->InstanceTemplate()->SetInternalFieldCount(1);

  // Prototype
  NODE_SET_PROTOTYPE_METHOD(tpl, "next", Next);
  tpl->InstanceTemplate()->Set(String::NewFromUtf8(isolate, Symbol::GetIterator(isolate)).ToLocalChecked(), FunctionTemplate::New(isolate, GetIterator)->GetFunction(context).ToLocalChecked());

  constructor.Reset(isolate, tpl->GetFunction(context).ToLocalChecked());
  exports->Set(context, String::NewFromUtf8(isolate, "MyGenerator").ToLocalChecked(), tpl->GetFunction(context).ToLocalChecked());
}

