// Function to print the longest common subsequence
void printLCS(string &X, string &Y, vector<vector<int>> &dp) {
    int m = X.size();
    int n = Y.size();
    string lcs;

    int i = m, j = n;
    while (i > 0 && j > 0) {
        if (X[i-1] == Y[j-1]) {
            lcs.push_back(X[i-1]);
            i--;
            j--;
        } else if (dp[i-1][j] > dp[i][j-1]) {
            i--;
        } else {
            j--;
        }
    }

    reverse(lcs.begin(), lcs.end());
    cout << "Longest Common Subsequence: " << lcs << endl;
}

// Function to find the length of the longest common subsequence
int findLCSLength(string &X, string &Y) {
    int m = X.size();
    int n = Y.size();

    vector<vector<int>> dp(m + 1, vector<int>(n + 1, 0));

    // Build the dp table in bottom-up fashion
    for (int i = 1; i <= m; i++) {
        for (int j = 1; j <= n; j++) {
            if (X[i-1] == Y[j-1]) {
                dp[i][j] = dp[i-1][j-1] + 1;
            } else {
                dp[i][j] = max(dp[i-1][j], dp[i][j-1]);
            }
        }
    }

    // Print the LCS
    printLCS(X, Y, dp);

    return dp[m][n];
}

int main() {
    string X, Y;
    cout << "Enter the first string: ";
    cin >> X;
    cout << "Enter the second string: ";
    cin >> Y;

    int lcsLength = findLCSLength(X, Y);
    cout << "Length of the Longest Common Subsequence: " << lcsLength << endl;

    return 0;
}

