__global__ void processImageKernel(unsigned char* output, int width, int height) {
    int X = blockIdx.x * blockDim.x + threadIdx.x;
    int Y = blockIdx.y * blockDim.y + threadIdx.y;

    if (X < width && Y < height) {
        unsigned char red = tex2D(tex, X, Y * 3 + 0); // Red channel
        unsigned char green = tex2D(tex, X, Y * 3 + 1); // Green channel
        unsigned char blue = tex2D(tex, X, Y * 3 + 2); // Blue channel

        // Process the pixel (e.g., store it in the output array)
        output[(Y * width + X) * 3 + 0] = red;
        output[(Y * width + X) * 3 + 1] = green;
        output[(Y * width + X) * 3 + 2] = blue;
    }
}

