int brightness[] = {128, 0, 128, 0}; // PWM values (0-255)
int patternLength = sizeof(pattern) / sizeof(pattern[0]);

// Variables to store user input
String inputPattern = "";
String inputDelays = "";
String inputBrightness = "";

void setup() {
  // Initialize the LED pin as an output
  pinMode(ledPin, OUTPUT);

  // Start the serial communication
  Serial.begin(9600);
  Serial.println("LED Blink Pattern Controller");
  Serial.println("Enter new pattern, delays, and brightness values separated by commas.");
  Serial.println("Example: 1,0,1,0,500,1000,500,1000,128,0,128,0");
}

void loop() {
  // Check for user input
  if (Serial.available() > 0) {
    String input = Serial.readStringUntil('\n');
    parseInput(input);
  }

  // Blink the LED according to the current pattern
  for (int i = 0; i < patternLength; i++) {
    analogWrite(ledPin, brightness[i]);
    delay(delays[i]);
  }
}

void parseInput(String input) {
  // Split the input string into parts
  String parts[12];
  int partCount = 0;
  int index = 0;

  while (index < input.length()) {
    int commaIndex = input.indexOf(',', index);
    if (commaIndex == -1) {
      parts[partCount] = input.substring(index);
      partCount++;
      break;
    }
    parts[partCount] = input.substring(index, commaIndex);
    partCount++;
    index = commaIndex + 1;
  }

  // Update the pattern, delays, and brightness
  if (partCount >= 3 && partCount % 3 == 0) {
    patternLength = partCount / 3;
    for (int i = 0; i < patternLength; i++) {
      pattern[i] = parts[i * 3].toInt();
      delays[i] = parts[i * 3 + 1].toInt();
      brightness[i] = parts[i * 3 + 2].toInt();
    }
    Serial.println("Pattern updated successfully!");
  } else {
    Serial.println("Invalid input. Please enter a valid pattern, delays, and brightness values.");
  }
}

#include <iostream>
#include <string>
#include <vector>
#include <cctype>
#include <unordered_map>

enum class TokenType {
    INT, FLOAT, IDENTIFIER, ASSIGN, PLUS, MINUS, MUL, DIV, LPAREN, RPAREN, SEMICOLON, EOF_TOKEN,
    IF, WHILE, FUNCTION, COMMA, LBRACE, RBRACE, ERROR
};

struct Token {
    TokenType type;
    std::string value;
    int line;
    int column;
};

class Lexer {
public:
    Lexer(const std::string& input) : input(input), pos(0), line(1), column(1) {}

    Token nextToken();

private:
    std::string input;
    size_t pos;
    int line;
    int column;

    char currentChar();
    void advance();
    void skipWhitespace();
    Token numberToken();
    Token identifierToken();
    Token keywordOrIdentifierToken(const std::string& text);
};

char Lexer::currentChar() {
    return pos < input.length() ? input[pos] : '\0';
}

void Lexer::advance() {
    if (currentChar() == '\n') {
        line++;
        column = 1;
    } else {
        column++;
    }
    pos++;
}

void Lexer::skipWhitespace() {
    while (std::isspace(currentChar())) {
        advance();
    }
}

Token Lexer::numberToken() {
    std::string numberStr;
    while (std::isdigit(currentChar()) || currentChar() == '.') {
        numberStr += currentChar();
        advance();
    }
    if (numberStr.find('.') != std::string::npos) {
        return {TokenType::FLOAT, numberStr, line, column};
    } else {
        return {TokenType::INT, numberStr, line, column};
    }
}

Token Lexer::identifierToken() {
    std::string identStr;
    while (std::isalnum(currentChar()) || currentChar() == '_') {
        identStr += currentChar();
        advance();
    }
    return keywordOrIdentifierToken(identStr);
}

Token Lexer::keywordOrIdentifierToken(const std::string& text) {
    static const std::unordered_map<std::string, TokenType> keywords = {
        {"if", TokenType::IF},
        {"while", TokenType::WHILE},
        {"function", TokenType::FUNCTION}
    };

    auto it = keywords.find(text);
    if (it != keywords.end()) {
        return {it->second, text, line, column};
    }
    return {TokenType::IDENTIFIER, text, line, column};
}

Token Lexer::nextToken() {
    skipWhitespace();

    if (pos >= input.length()) {
        return {TokenType::EOF_TOKEN, "", line, column};
    }

    char ch = currentChar();
    if (std::isdigit(ch)) {
        return numberToken();
    }

    if (std::isalpha(ch) || ch == '_') {
        return identifierToken();
    }

    advance();
    switch (ch) {
        case '+': return {TokenType::PLUS, "+", line, column};
        case '-': return {TokenType::MINUS, "-", line, column};
        case '*': return {TokenType::MUL, "*", line, column};
        case '/': return {TokenType::DIV, "/", line, column};
        case '(': return {TokenType::LPAREN, "(", line, column};
        case ')': return {TokenType::RPAREN, ")", line, column};
        case ';': return {TokenType::SEMICOLON, ";", line, column};
        case ',': return {TokenType::COMMA, ",", line, column};
        case '{': return {TokenType::LBRACE, "{", line, column};
        case '}': return {TokenType::RBRACE, "}", line, column};
        default: return {TokenType::ERROR, std::string(1, ch), line, column};
    }
}

