typedef unsigned long U32;

extern "C" __declspec(dllexport) int ReadFile(LPSTR Path, U32** DataPtr, U32* Count)
{
    FILE *fp;
    U32 *Data;
    CString tempStr(Path);
    long fSize;

    if (!(fp = fopen(tempStr, "rb"))) {
        return 0;
    }

    // Obtain File Size
    fseek(fp, 0, SEEK_END);
    fSize = ftell(fp);
    rewind(fp);

    // Ensure fSize is a multiple of sizeof(U32)
    if (fSize % sizeof(U32) != 0) {
        fclose(fp);
        return -3; // File size is not a multiple of sizeof(U32)
    }

    // Allocate memory
    Data = (U32 *)malloc(fSize);
    if (Data == NULL) {
        fclose(fp);
        return -1;
    }

    // Copy file into the buffer
    *Count = fread(Data, sizeof(U32), fSize / sizeof(U32), fp);
    if (*Count == 0) {
        fclose(fp);
        free(Data);
        return -2;
    }

    *DataPtr = Data;
    fclose(fp);
    return 1;
}

