// CUDA Kernel
__global__ void process3DArray(float *d_c, int dimX, int dimY, int dimZ) {
    int x = blockIdx.x * blockDim.x + threadIdx.x;
    int y = blockIdx.y * blockDim.y + threadIdx.y;
    int z = blockIdx.z * blockDim.z + threadIdx.z;

    if (x < dimX && y < dimY && z < dimZ) {
        // Example operation: set each element to the sum of its indices
        d_c[z * dimX * dimY + y * dimX + x] = x + y + z;
    }
}

int main() {
    int dimX = 2, dimY = 2, dimZ = 2;
    int size = dimX * dimY * dimZ * sizeof(float);

    // Allocate host memory
    float *h_c = (float *)malloc(size);

    // Allocate device memory
    float *d_c;
    cudaMalloc((void **)&d_c, size);

    // Copy host memory to device
    cudaMemcpy(d_c, h_c, size, cudaMemcpyHostToDevice);

    // Define block and grid dimensions
    dim3 threadsPerBlock(16, 16, 16);
    dim3 blocksPerGrid((dimX + threadsPerBlock.x - 1) / threadsPerBlock.x,
                       (dimY + threadsPerBlock.y - 1) / threadsPerBlock.y,
                       (dimZ + threadsPerBlock.z - 1) / threadsPerBlock.z);

    // Launch kernel
    process3DArray<<<blocksPerGrid, threadsPerBlock>>>(d_c, dimX, dimY, dimZ);

    // Copy device memory back to host
    cudaMemcpy(h_c, d_c, size, cudaMemcpyDeviceToHost);

    // Print results
    for (int z = 0; z < dimZ; z++) {
        for (int y = 0; y < dimY; y++) {
            for (int x = 0; x < dimX; x++) {
                std::cout << "h_c[" << z << "][" << y << "][" << x << "] = " << h_c[z * dimX * dimY + y * dimX + x] << std::endl;
            }
        }
    }

    // Free memory
    free(h_c);
    cudaFree(d_c);

    return 0;
}

