#include <iostream>
#include <thread>
#include <vector>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <functional>

class TaskScheduler {
public:
    TaskScheduler() : stop(false) {}

    // Schedule a task to run at a specific interval
    void schedule(std::function<void()> task, std::chrono::milliseconds interval) {
        {
            std::unique_lock<std::mutex> lock(mutex);
            tasks.push({task, interval, std::chrono::steady_clock::now()});
        }
        cv.notify_one();
    }

    // Start the scheduler
    void start() {
        for (int i = 0; i < num_threads; ++i) {
            workers.emplace_back(&TaskScheduler::run, this);
        }
    }

    // Stop the scheduler
    void stop_scheduler() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            stop = true;
        }
        cv.notify_all();
        for (std::thread &worker : workers) {
            worker.join();
        }
    }

private:
    struct TaskInfo {
        std::function<void()> task;
        std::chrono::milliseconds interval;
        std::chrono::steady_clock::time_point next_run;
    };

    void run() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex);
            cv.wait(lock, [this] { return stop || !tasks.empty(); });

            if (stop && tasks.empty()) {
                return;
            }

            auto now = std::chrono::steady_clock::now();
            while (!tasks.empty() && tasks.top().next_run <= now) {
                TaskInfo task_info = tasks.top();
                tasks.pop();

                lock.unlock();
                task_info.task();
                lock.lock();

                if (!stop) {
                    task_info.next_run += task_info.interval;
                    tasks.push(task_info);
                }
            }

            if (!tasks.empty()) {
                auto next_run_time = tasks.top().next_run;
                auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(next_run_time - now);
                cv.wait_for(lock, duration);
            }
        }
    }

    std::vector<std::thread> workers;
    std::mutex mutex;
    std::condition_variable cv;
    std::priority_queue<TaskInfo, std::vector<TaskInfo>, std::function<bool(TaskInfo, TaskInfo)>> tasks{
        [](const TaskInfo &a, const TaskInfo &b) { return a.next_run > b.next_run; }
    };
    bool stop;
    const int num_threads = 4; // Number of worker threads
};

// Example task
void print_message(const std::string &message) {
    std::cout << message << std::endl;
}

int main() {
    TaskScheduler scheduler;
    scheduler.schedule(std::bind(print_message, "Task 1"), std::chrono::milliseconds(1000));
    scheduler.schedule(std::bind(print_message, "Task 2"), std::chrono::milliseconds(500));

    scheduler.start();

    std::this_thread::sleep_for(std::chrono::seconds(10));

    scheduler.stop_scheduler();

    return 0;
}

#include <iostream>

// Definition for singly-linked list.
struct ListNode {
    int val;
    ListNode *next;
    ListNode(int x) : val(x), next(NULL) {}
};

bool hasCycle(ListNode *head) {
    if (head == NULL || head->next == NULL) {
        return false; // No cycle if the list is empty or has only one node
    }

    ListNode *tortoise = head;
    ListNode *hare = head;

    while (hare != NULL && hare->next != NULL) {
        tortoise = tortoise->next; // Move tortoise by one step
        hare = hare->next->next;   // Move hare by two steps

        if (tortoise == hare) {
            return true; // Cycle detected
        }
    }

    return false; // No cycle detected
}

int main() {
    // Example usage:
    ListNode *node1 = new ListNode(1);
    ListNode *node2 = new ListNode(2);
    ListNode *node3 = new ListNode(3);
    ListNode *node4 = new ListNode(4);

    node1->next = node2;
    node2->next = node3;
    node3->next = node4;
    node4->next = node2; // Creating a cycle

    if (hasCycle(node1)) {
        std::cout << "Cycle detected." << std::endl;
    } else {
        std::cout << "No cycle detected." << std::endl;
    }

    // Clean up memory
    delete node1;
    delete node2;
    delete node3;
    delete node4;

    return 0;
}

class IRGenerator {
public:
    std::string generateAssembly(Node* n) {
        std::string assembly = "";
        std::string ir = lowerToIR(n);
        assembly = emitAssembly(ir);
        return assembly;
    }

private:
    std::string lowerToIR(Node* n) {
        if (n->type == Node::IF) {
            std::string ir = "";
            ir += lowerToIR(n->getChild(0));  // Condition
            ir += "if ";
            ir += n->getChild(0)->value;  // Simplified condition
            ir += " goto .true" + std::to_string(nLabels++) + "\n";
            ir += "goto .false" + std::to_string(nLabels - 1) + "\n";
            ir += ".true" + std::to_string(nLabels - 1) + ":\n";
            ir += lowerToIR(n->getChild(1));  // True block
            ir += ".false" + std::to_string(nLabels - 1) + ":\n";
            return ir;
        }
        // Handle other node types similarly
        return "";
    }

    std::string emitAssembly(const std::string& ir) {
        std::string assembly = "";
        // Convert IR to assembly
        for (const std::string& line : split(ir, '\n')) {
            if (line.find("if") != std::string::npos) {
                assembly += "cmp ...\n";
                assembly += "jnz .true" + extractLabel(line) + "\n";
                assembly += "jmp .false" + extractLabel(line) + "\n";
            } else if (line.find("goto") != std::string::npos) {
                assembly += "jmp " + extractLabel(line) + "\n";
            } else if (line.find(".true") != std::string::npos || line.find(".false") != std::string::npos) {
                assembly += line + ":\n";
            } else {
                assembly += line + "\n";
            }
        }
        return assembly;
    }

    std::vector<std::string> split(const std::string& s, char delimiter) {
        std::vector<std::string> tokens;
        std::string token;
        std::istringstream tokenStream(s);
        while (getline(tokenStream, token, delimiter)) {
            tokens.push_back(token);
        }
        return tokens;
    }

    std::string extractLabel(const std::string& line) {
        // Extract the label from the line
        return line.substr(line.find_last_of(" ") + 1);
    }

    int nLabels = 0;
};

template<typename Key, typename T, typename Compare, typename Allocator, typename Predicate>
inline void generic_remove(std::map<Key, T, Compare, Allocator> &container, const Predicate &pred)
{
    for (auto it = container.begin(); it != container.end();)
    {
        if (pred(it->second))
        {
            it = container.erase(it);
        }
        else
        {
            ++it;
        }
    }
}

#include <unwind.h>
#include <dlfcn.h>
#include <iostream>
