struct BacktraceState {
    void** current;
    void** end;
};

static _Unwind_Reason_Code unwind_callback(struct _Unwind_Context* context, void* arg) {
    BacktraceState* state = static_cast<BacktraceState*>(arg);
    uintptr_t pc = _Unwind_GetIP(context);
    if (pc) {
        if (state->current == state->end) {
            return _URC_END_OF_STACK;
        } else {
            *state->current++ = reinterpret_cast<void*>(pc);
        }
    }
    return _URC_NO_REASON;
}

void capture_backtrace(void** buffer, size_t max_frames) {
    BacktraceState state = {buffer, buffer + max_frames};
    _Unwind_Backtrace(unwind_callback, &state);
}

void print_backtrace() {
    const size_t max_frames = 64;
    void* buffer[max_frames];
    char** symbols;

    capture_backtrace(buffer, max_frames);
    symbols = backtrace_symbols(buffer, max_frames);

    if (symbols) {
        for (size_t i = 0; i < max_frames && symbols[i]; ++i) {
            std::cout << symbols[i] << std::endl;
        }
        free(symbols);
    }
}

void signal_handler(int signal) {
    std::cout << "Signal received: " << signal << std::endl;
    print_backtrace();
}

int main() {
    signal(SIGSEGV, signal_handler);

    // Simulate a segmentation fault
