}

typedef struct {
    float re;
    float im;
} dcmplx;

dcmplx ComplexConv(int len, dcmplx *hat, dcmplx *buf)
{
    dcmplx xout = {0.0, 0.0};

    asm volatile (
        "vdup.32 q0, #0\n\t"  // Initialize q0 with zeros (xout.re, xout.im)
        "mov r3, #0\n\t"
        ".loop:\n\t"
        "vldr s11, [%[hat], #4]\n\t"  // Load hat[i].im
        "vldr s13, [%[hat]]\n\t"      // Load hat[i].re
        "vneg.f32 s11, s11\n\t"       // Conjugate hat[i].im
        "vldr s15, [%[buf], #4]\n\t"  // Load buf[i].im
        "vldr s12, [%[buf]]\n\t"      // Load buf[i].re
        "vmul.f32 s14, s15, s13\n\t"  // Multiply hat[i].re * buf[i].im
        "vmul.f32 s15, s11, s15\n\t"  // Multiply hat[i].im * buf[i].im
        "adds %[hat], #8\n\t"         // Increment hat pointer
        "vmla.f32 s14, s11, s12\n\t"  // Multiply and accumulate hat[i].im * buf[i].re
        "vnmls.f32 s15, s12, s13\n\t" // Multiply and subtract hat[i].re * buf[i].re
        "adds %[buf], #8\n\t"         // Increment buf pointer
        "vadd.f32 s1, s1, s14\n\t"    // Accumulate real part
        "vadd.f32 s0, s0, s15\n\t"    // Accumulate imaginary part
        "adds r3, r3, #1\n\t"         // Increment loop counter
        "cmp r3, %[len]\n\t"          // Compare loop counter with len
        "bne .loop\n\t"
        : [xout]"=w"(xout)            // Output constraint for xout
        : [hat]"r"(hat), [buf]"r"(buf), [len]"r"(len)
        : "r3", "s11", "s12", "s13", "s14", "s15", "cc"
    );

    return xout;
}

#include <iostream>
