bool isVowel(char ch) {
    ch = std::tolower(ch); // Convert to lowercase to handle both uppercase and lowercase vowels
    return ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u';
}

std::string removeVowels(const std::string& input) {
    std::string result;
    for (char ch : input) {
        if (!isVowel(ch)) {
            result += ch;
        }
    }
    return result;
}

int main() {
