LRESULT CALLBACK WndProc(HWND hwnd, UINT msg, WPARAM wParam, LPARAM lParam)
{
    static bool isPasswordPromptVisible = false;

    switch (msg)
    {
    case WM_HOTKEY:
        if (wParam == 1)
        {
            ShowPasswordPrompt(hwnd);
        }
        break;
    case WM_KEYDOWN:
    case WM_SYSKEYDOWN:
    case WM_LBUTTONDOWN:
    case WM_RBUTTONDOWN:
        if (!isPasswordPromptVisible)
        {
            ShowPasswordPrompt(hwnd);
        }
        break;
    case WM_CLOSE:
        if (isPasswordPromptVisible)
        {
            return 0;
        }
        // Fall through to default if not visible
    default:
        return DefWindowProc(hwnd, msg, wParam, lParam);
    }

    return 0;
}

void ShowPasswordPrompt(HWND hwnd)
{
    isPasswordPromptVisible = true;
    if (DialogBox(GetModuleHandle(NULL), MAKEINTRESOURCE(IDD_PASSWORD_DIALOG), hwnd, PasswordDialogProc) == IDOK)
    {
        PostQuitMessage(0);
    }
    isPasswordPromptVisible = false;
}

INT_PTR CALLBACK PasswordDialogProc(HWND hDlg, UINT message, WPARAM wParam, LPARAM lParam)
{
    switch (message)
    {
    case WM_INITDIALOG:
        return (INT_PTR)TRUE;
    case WM_COMMAND:
        if (LOWORD(wParam) == IDOK || LOWORD(wParam) == IDCANCEL)
        {
            if (LOWORD(wParam) == IDOK)
            {
                char password[100];
                GetDlgItemText(hDlg, IDC_PASSWORD, password, 100);
                if (std::string(password) == "your_password")
                {
                    EndDialog(hDlg, IDOK);
                }
                else
                {
                    MessageBox(hDlg, "Incorrect password.", "Error", MB_OK | MB_ICONERROR);
                }
            }
            else
            {
                EndDialog(hDlg, IDCANCEL);
            }
            return (INT_PTR)TRUE;
        }
        break;
    }
    return (INT_PTR)FALSE;
}

