// Function to convert big-endian to little-endian for 8-byte integers
uint64_t ntohll(uint64_t value) {
    return ((value & 0x00000000FFFFFFFF) << 32) |
           ((value & 0xFFFFFFFF00000000) >> 32);
}

int main (int argc, char* argv[]) {
