    std::vector<char>::iterator it = bytes.begin();

    char longBytes[8];
    std::copy(&(*it), &(*it) + 8, longBytes);
    uint64_t value = *((uint64_t*)longBytes);

    value = ntohll(value); // Convert from big-endian to little-endian

    std::cout << "Size: " << value << std::endl;
}

