std::string disassembly(uint8_t *bytearray, long size, uint64_t startAddress) {
    csh handle;
    cs_insn *insn;
    size_t count;
    std::string output;

    if (cs_open(CS_ARCH_X86, CS_MODE_64, &handle) == CS_ERR_OK) {
        // Set the count to 0 to disassemble as many instructions as possible
        count = cs_disasm(handle, bytearray, size, startAddress, 0, &insn);
        if (count > 0) {
            for (size_t j = 0; j < count; j++) {
                char buffer[512];
                int i = sprintf(buffer, "0x%" PRIx64 ":\t%s\t\t%s\n", insn[j].address, insn[j].mnemonic, insn[j].op_str);
                output += buffer;
            }
            cs_free(insn, count);
        } else {
            output = "ERROR: Failed to disassemble given code!\n";
        }
    } else {
        output = "ERROR: Failed to open Capstone handle!\n";
    }

    cs_close(&handle);
    return output;
}

#include <Python.h>
