using namespace std;

vector<int> findLongestSubarrayWithSum(const vector<int>& nums, int targetSum) {
    int start = 0, end = 0, currentSum = 0;
    int maxLength = 0, maxStart = -1;

    while (end < nums.size()) {
        currentSum += nums[end];

        while (currentSum > targetSum && start <= end) {
            currentSum -= nums[start];
            start++;
        }

        if (currentSum == targetSum) {
            if (end - start + 1 > maxLength) {
                maxLength = end - start + 1;
                maxStart = start;
            }
        }

        end++;
    }

    if (maxStart == -1) return {};
    return vector<int>(nums.begin() + maxStart, nums.begin() + maxStart + maxLength);
}

int main() {
    vector<int> nums = {1, 2, 3, 4, 5};
    int targetSum = 9;
    vector<int> result = findLongestSubarrayWithSum(nums, targetSum);
    for (int num : result) {
        cout << num << " ";
    }
    return 0;
}

