int main() {
    // Load the input image
    cv::Mat inputImage = cv::imread("input.png", cv::IMREAD_GRAYSCALE);

    // Define the affine transformation matrix
    cv::Point2f srcTri[3];
    cv::Point2f dstTri[3];

    srcTri[0] = cv::Point2f(0, 0);
    srcTri[1] = cv::Point2f(inputImage.cols - 1, 0);
    srcTri[2] = cv::Point2f(0, inputImage.rows - 1);

    dstTri[0] = cv::Point2f(0, 0);
    dstTri[1] = cv::Point2f(inputImage.cols * 2 - 1, 0);
    dstTri[2] = cv::Point2f(0, inputImage.rows * 2 - 1);

    cv::Mat warpMat = cv::getAffineTransform(srcTri, dstTri);

    // Create the output image with higher resolution
    cv::Mat outputImage;
    cv::warpAffine(inputImage, outputImage, warpMat, cv::Size(inputImage.cols * 2, inputImage.rows * 2), cv::INTER_CUBIC);

    // Save the output image
    cv::imwrite("output.png", outputImage);

    return 0;
}

