#include <iostream>

template <int N>
void asmFunction() {
    // Determine the clobber list based on the template parameter
    const char* clobber_list = nullptr;

    if constexpr (N == 1) {
        clobber_list = "rax";
    } else if constexpr (N == 2) {
        clobber_list = "rbx";
    } else if constexpr (N == 3) {
        clobber_list = "rcx";
    } else {
        clobber_list = "rdx";
    }

    // Use the clobber list in the asm block
    __asm__ __volatile__(
        "mov %1, %%rax\n"
        "add %%rax, %%rax\n"
        : /* output operands */
        : "r" (N) /* input operands */
        : clobber_list /* clobber list */
    );
}

int main() {
    asmFunction<1>();
    asmFunction<2>();
    asmFunction<3>();
    asmFunction<4>();

    return 0;
}

