#define OLED_RESET -1
#define SCREEN_ADDRESS 0x3C
#define CHANNEL 1
#define BUFFER_SIZE 1024
Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, OLED_RESET);
void OnDataRecv(const uint8_t *mac_addr, const uint8_t *data, int data_len);

uint8_t dataBuffer[BUFFER_SIZE];
unsigned int bufferHead = 0;
unsigned int bufferTail = 0;
unsigned int currentDataSize = 0;

void InitESPNow() {
  WiFi.disconnect();
  if (esp_now_init() == ESP_OK) {
    Serial.println("ESPNow Init Success");
  } else {
    Serial.println("ESPNow Init Failed");
    ESP.restart();
  }
}

void configDeviceAP() {
  const char SSID[] = "Slave_1";
  if (!WiFi.softAP(SSID, "Slave_1_Password", CHANNEL, 0)) {
    Serial.println("AP Config failed.");
    ESP.restart();
  } else {
    Serial.print("AP Config Success. Broadcasting with AP: ");
    Serial.println(SSID);
    Serial.print("AP CHANNEL ");
    Serial.println(WiFi.channel());
  }
}

void setup() {
  Serial.begin(115200);
  WiFi.mode(WIFI_AP);
  configDeviceAP();
  InitESPNow();
  esp_now_register_recv_cb(OnDataRecv);
  if (!display.begin(SSD1306_SWITCHCAPVCC, SCREEN_ADDRESS)) {
    Serial.println(F("SSD1306 allocation failed"));
    while (true); // Infinite loop
  }
  display.clearDisplay();
}

void OnDataRecv(const uint8_t *mac_addr, const uint8_t *data, int data_len) {
    char macStr[18];
    snprintf(macStr, sizeof(macStr), "%02x:%02x:%02x:%02x:%02x:%02x",
             mac_addr[0], mac_addr[1], mac_addr[2], mac_addr[3], mac_addr[4], mac_addr[5]);
    Serial.print("Data Received from : ");
    Serial.println(macStr);
    Serial.println();

    for (int i = 0; i < data_len; i++) {
        bufferHead = (bufferHead + 1) % BUFFER_SIZE;
        dataBuffer[bufferHead] = data[i];

        if (bufferHead == bufferTail) {
            bufferTail = (bufferTail + 1) % BUFFER_SIZE;
        }

        currentDataSize++;
    }

    Serial.println("Databuffer on data receive:");
    for (int i = 0; i < currentDataSize; i++) {
        Serial.print(dataBuffer[i], HEX);
        Serial.print(" ");
        if ((i + 1) % 16 == 0) {
            Serial.println();
        }
    }

    Wire.beginTransmission(SCREEN_ADDRESS);
    for (int i = 0; i < currentDataSize; i++) {
        Wire.write(dataBuffer[i]);
    }
    Wire.endTransmission();

    // Reset currentDataSize to 0
    currentDataSize = 0;
}

