    for (j = 0; j < 3; j++) {
        cardEntry tmpStruct;
        sprintf(z, "Card Name: %d", i);
        tmpStruct.cardName = z;
        tmpStruct.vThreshold = 1.00;
        tmpStruct.gsize = 0;
        tmpStruct.fav = 1;
        for (i = 0; i < 3; i++) {
            PriceEntry ss;
            ss.cardPrice = i + 1;
            ss.Edition = i;
            ss.Rarity = i - 1;
            sprintf(z, "This is struct %d", i);
            ss.PriceDate = z;
            tmpStruct.cardPrices.push_back(ss);
        }
        tmpStruct.pesize = tmpStruct.cardPrices.size();
        Cards.push_back(tmpStruct);
    }
}

void serializePriceEntries(const vector<PriceEntry>& entries, vector<uint8_t>& buffer) {
    for (const auto& entry : entries) {
        // Serialize each field
        memcpy(&buffer[buffer.size()], &entry.cardPrice, sizeof(entry.cardPrice));
        buffer.resize(buffer.size() + sizeof(entry.cardPrice));

        size_t dateSize = entry.PriceDate.size();
        memcpy(&buffer[buffer.size()], &dateSize, sizeof(dateSize));
        buffer.resize(buffer.size() + sizeof(dateSize));

        memcpy(&buffer[buffer.size()], entry.PriceDate.c_str(), dateSize);
        buffer.resize(buffer.size() + dateSize);

        memcpy(&buffer[buffer.size()], &entry.Edition, sizeof(entry.Edition));
        buffer.resize(buffer.size() + sizeof(entry.Edition));

        memcpy(&buffer[buffer.size()], &entry.Rarity, sizeof(entry.Rarity));
        buffer.resize(buffer.size() + sizeof(entry.Rarity));
    }
}

void deserializePriceEntries(const uint8_t* buffer, size_t bufferSize, vector<PriceEntry>& entries) {
    size_t pos = 0;
    while (pos < bufferSize) {
        PriceEntry entry;
        memcpy(&entry.cardPrice, &buffer[pos], sizeof(entry.cardPrice));
        pos += sizeof(entry.cardPrice);

        size_t dateSize;
        memcpy(&dateSize, &buffer[pos], sizeof(dateSize));
        pos += sizeof(dateSize);

        entry.PriceDate = string((const char*)&buffer[pos], dateSize);
        pos += dateSize;

        memcpy(&entry.Edition, &buffer[pos], sizeof(entry.Edition));
        pos += sizeof(entry.Edition);

        memcpy(&entry.Rarity, &buffer[pos], sizeof(entry.Rarity));
        pos += sizeof(entry.Rarity);

        entries.push_back(entry);
    }
}

int SaveCards() {
    int retval;
    int CardCounter = 0;
    int PriceEntries = 0;
    char tmpQuery[256] = {0};

    int q_cnt = 5, q_size = 256;

    sqlite3_stmt *stmt;
    sqlite3 *handle;

    retval = sqlite3_open("sampledb.sqlite3", &handle);

    if (retval) {
        printf("Database connection failed\n");
        return -1;
    }
    printf("Connection successful\n");

    char create_table[] = "CREATE TABLE IF NOT EXISTS Cards (CardName TEXT, PriceData BLOB, PriceNum NUMERIC, Threshold NUMERIC, Fav NUMERIC);";

    retval = sqlite3_exec(handle, create_table, 0, 0, 0);
    if (retval) {
        printf("could not prepare statement: %s\n", sqlite3_errmsg(handle));
        return -1;
    }

    for (CardCounter = 0; CardCounter < Cards.size(); CardCounter++) {
        vector<uint8_t> buffer;
        serializePriceEntries(Cards[CardCounter].cardPrices, buffer);

        char Query[512] = {0};
        sprintf(Query, "INSERT INTO Cards (CardName, PriceData, PriceNum, Threshold, Fav) VALUES('%s', ?, %d, %f, %d)",
            Cards[CardCounter].cardName.c_str(),
            Cards[CardCounter].pesize,
            Cards[CardCounter].vThreshold,
            Cards[CardCounter].fav);

        sqlite3_prepare_v2(handle, Query, -1, &stmt, NULL);
        sqlite3_bind_blob(stmt, 1, &buffer[0], buffer.size(), SQLITE_STATIC);

        retval = sqlite3_step(stmt);
        if (retval != SQLITE_DONE) {
            printf("Could not prepare statement: %s\n", sqlite3_errmsg(handle));
        }

        sqlite3_finalize(stmt);
    }

    sqlite3_close(handle);
    return 0;
}

