// Function to determine the winner of a Rock-Paper-Scissors game
std::string determineWinner(const std::string& player1, const std::string& player2) {
    // Normalize the input to lowercase for case-insensitivity
    std::string p1 = player1;
    std::string p2 = player2;
    std::transform(p1.begin(), p1.end(), p1.begin(), ::tolower);
    std::transform(p2.begin(), p2.end(), p2.begin(), ::tolower);

    // Determine the winner based on the moves
    if (p1 == p2) {
        return "It's a tie!";
    } else if (p1 == "rock") {
        return (p2 == "scissors") ? "Player 1 wins!" : "Player 2 wins!";
    } else if (p1 == "paper") {
        return (p2 == "rock") ? "Player 1 wins!" : "Player 2 wins!";
    } else if (p1 == "scissors") {
        return (p2 == "paper") ? "Player 1 wins!" : "Player 2 wins!";
    } else {
        return "Invalid move!";
    }
}

