vector<int> fibonacci(int n) {
    vector<int> fibs;
    if (n <= 0) return fibs;
    fibs.push_back(0);
    if (n == 1) return fibs;
    fibs.push_back(1);
    for (int i = 2; i < n; i++) {
        fibs.push_back(fibs[i - 1] + fibs[i - 2]);
    }
    return fibs;
}

