// Define a literal
using Literal = int;
using Clause = std::vector<Literal>;
using Formula = std::vector<Clause>;

// Define a SAT solver
class SATSolver {
public:
    SATSolver(const Formula& formula) : formula(formula), n_vars(0) {
        for (const auto& clause : formula) {
            for (Literal lit : clause) {
                n_vars = std::max(n_vars, std::abs(lit));
            }
        }
        assignment.resize(n_vars + 1, 0); // 0 means unassigned, 1 means true, -1 means false
    }

    bool solve() {
        return solve_recursive(1);
    }

    void print_solution() const {
        for (int i = 1; i <= n_vars; ++i) {
            if (assignment[i] == 1) {
                std::cout << "x" << i << " = true ";
            } else if (assignment[i] == -1) {
                std::cout << "x" << i << " = false ";
            }
        }
        std::cout << std::endl;
    }

private:
    Formula formula;
    int n_vars;
    std::vector<int> assignment;

    bool solve_recursive(int var) {
        if (var > n_vars) {
            return is_satisfied();
        }

        // Try assigning true
        assignment[var] = 1;
        if (solve_recursive(var + 1)) {
            return true;
        }

        // Try assigning false
        assignment[var] = -1;
        if (solve_recursive(var + 1)) {
            return true;
        }

        // Backtrack
        assignment[var] = 0;
        return false;
    }

    bool is_satisfied() const {
        for (const auto& clause : formula) {
            bool clause_satisfied = false;
            for (Literal lit : clause) {
                if (lit > 0) {
                    if (assignment[lit] == 1) {
                        clause_satisfied = true;
                        break;
                    }
                } else {
                    if (assignment[-lit] == -1) {
                        clause_satisfied = true;
                        break;
                    }
                }
            }
            if (!clause_satisfied) {
                return false;
            }
        }
        return true;
    }
};

int main() {
    // Example formula: (x1 OR x2) AND (NOT x1 OR x3)
    Formula formula = {
        {1, 2},
        {-1, 3}
    };

    SATSolver solver(formula);
    if (solver.solve()) {
        std::cout << "The formula is satisfiable. Solution: ";
        solver.print_solution();
    } else {
        std::cout << "The formula is unsatisfiable." << std::endl;
    }

    return 0;
}

