using Entity = std::size_t;

class EntityManager {
public:
    EntityManager() : id_(0) {}

    Entity createEntity() {
        return id_++;
    }
private:
    Entity id_;
};

template <typename T>
class ComponentManager {
public:
    void addComponent(Entity e, const T& component) {
        components_[e] = component;
    }

    T* getComponent(Entity e) {
        auto it = components_.find(e);
        return it != components_.end() ? &(it->second) : nullptr;
    }

private:
    std::unordered_map<Entity, T> components_;
};

int main() {
    EntityManager entityManager;
    ComponentManager<Position> positionManager;
    ComponentManager<Velocity> velocityManager;

    Entity entity = entityManager.createEntity();
    Position pos(10, 20);
    positionManager.addComponent(entity, pos);

    Position* myPos = positionManager.getComponent(entity);

    if (myPos) {
        std::cout << "Entity(" << entity << ") position: (" << myPos->x() << "," << myPos->y() << ")\n";
    } else {
        std::cout << "Entity(" << entity << ") has no Position.\n";
    }

    Velocity* myVel = velocityManager.getComponent(entity);

    if (myVel) {
        std::cout << "Entity(" << entity << ") velocity: (" << myVel->x() << "," << myVel->y() << ")\n";
    } else {
        std::cout << "Entity(" << entity << ") has no Velocity.\n";
    }

    return 0;
}

