#include <iostream>
#include <vector>
#include <cstdlib> // for rand() and srand()
#include <ctime>   // for time()

using namespace std;

// Function to swap two elements
void swap(int &a, int &b) {
    int temp = a;
    a = b;
    b = temp;
}

// Partition function for quickselect
int partition(vector<int> &arr, int left, int right, int pivotIndex) {
    int pivotValue = arr[pivotIndex];
    swap(arr[pivotIndex], arr[right]); // Move pivot to end
    int storeIndex = left;
    for (int i = left; i < right; ++i) {
        if (arr[i] < pivotValue) {
            swap(arr[i], arr[storeIndex]);
            ++storeIndex;
        }
    }
    swap(arr[right], arr[storeIndex]); // Move pivot to its final place
    return storeIndex;
}

// Quickselect function
int quickselect(vector<int> &arr, int left, int right, int k) {
    if (left == right) // If the list contains only one element,
        return arr[left]; // return that element

    // Select a random pivotIndex between left and right
    srand(time(0));
    int pivotIndex = left + rand() % (right - left + 1);

    pivotIndex = partition(arr, left, right, pivotIndex);

    // The pivot is in its final sorted position
    if (k == pivotIndex)
        return arr[k];
    else if (k < pivotIndex)
        return quickselect(arr, left, pivotIndex - 1, k);
    else
        return quickselect(arr, pivotIndex + 1, right, k);
}

// Function to find the median
int findMedian(vector<int> &arr) {
    int n = arr.size();
    if (n == 0)
        throw invalid_argument("Array cannot be empty.");
    if (n % 2 == 0)
        throw invalid_argument("Array size must be odd.");

    int medianIndex = (n - 1) / 2;
    return quickselect(arr, 0, n - 1, medianIndex);
}

int main() {
    vector<int> arr = {12, 3, 5, 7, 4, 19, 26};
    try {
        int median = findMedian(arr);
        cout << "The median is: " << median << endl;
    } catch (const invalid_argument &e) {
        cout << e.what() << endl;
    }
    return 0;
}

extern "C" {
    #include <cuda_runtime.h>

    __global__ void addKernel(float *c, const float *a, const float *b, int n) {
        int i = threadIdx.x;
        if (i < n) {
            c[i] = a[i] + b[i];
        }
    }

    void add(float *c, const float *a, const float *b, int n) {
        float *d_a, *d_b, *d_c;
        cudaMalloc(&d_a, n * sizeof(float));
        cudaMalloc(&d_b, n * sizeof(float));
        cudaMalloc(&d_c, n * sizeof(float));

        cudaMemcpy(d_a, a, n * sizeof(float), cudaMemcpyHostToDevice);
        cudaMemcpy(d_b, b, n * sizeof(float), cudaMemcpyHostToDevice);

        addKernel<<<1, n>>>(d_c, d_a, d_b, n);

        cudaMemcpy(c, d_c, n * sizeof(float), cudaMemcpyDeviceToHost);

        cudaFree(d_a);
        cudaFree(d_b);
        cudaFree(d_c);
    }
}

#include <iostream>
#include <vector>
#include <string>
#include <algorithm>

// Function to compare suffixes
bool suffixComp(const std::string &text, int i, int j, int p) {
    if (i + p == text.size()) return false;
    if (j + p == text.size()) return true;
    return text[i + p] < text[j + p];
}

// Function to build the suffix array
std::vector<int> buildSuffixArray(const std::string &text) {
    int n = text.size();
    std::vector<int> suffixArray(n);
    for (int i = 0; i < n; ++i) suffixArray[i] = i;

    std::vector<int> rank(n);
    for (int i = 0; i < n; ++i) rank[i] = text[i];

    for (int p = 1; p < n; p *= 2) {
        std::sort(suffixArray.begin(), suffixArray.end(), [&](int i, int j) {
            return rank[i] < rank[j] || (rank[i] == rank[j] && suffixComp(text, i, j, p));
        });

        std::vector<int> newRank(n);
        newRank[suffixArray[0]] = 0;
        for (int i = 1; i < n; ++i) {
            newRank[suffixArray[i]] = newRank[suffixArray[i - 1]] + (suffixComp(text, suffixArray[i - 1], suffixArray[i], p) ? 1 : 0);
        }
        rank = newRank;
    }

    return suffixArray;
}

// Function to build the LCP array
std::vector<int> buildLCPArray(const std::string &text, const std::vector<int> &suffixArray) {
    int n = text.size();
    std::vector<int> rank(n);
    for (int i = 0; i < n; ++i) rank[suffixArray[i]] = i;

    std::vector<int> lcp(n, 0);
    for (int i = 0, k = 0; i < n; ++i, k = std::max(k - 1, 0)) {
        if (rank[i] == n - 1) {
            k = 0;
            continue;
        }
        int j = suffixArray[rank[i] + 1];
        while (i + k < n && j + k < n && text[i + k] == text[j + k]) ++k;
        lcp[rank[i]] = k;
    }

    return lcp;
}

// Function to find the longest common substring
std::string longestCommonSubstring(const std::vector<std::string> &strings) {
    std::string combined = "";
    for (const auto &str : strings) {
        combined += str + "$";
    }

    std::vector<int> suffixArray = buildSuffixArray(combined);
    std::vector<int> lcpArray = buildLCPArray(combined, suffixArray);

    int maxLCP = 0;
    int maxIndex = 0;
    for (int i = 1; i < lcpArray.size(); ++i) {
        if (lcpArray[i] > maxLCP) {
            maxLCP = lcpArray[i];
            maxIndex = i;
        }
    }

    if (maxLCP == 0) return "";

    return combined.substr(suffixArray[maxIndex], maxLCP);
}

int main() {
    std::vector<std::string> strings = {"flower", "flow", "flight"};
    std::string result = longestCommonSubstring(strings);
    if (result.empty()) {
        std::cout << "No common substring found." << std::endl;
    } else {
        std::cout << "Longest common substring: " << result << std::endl;
    }
    return 0;
}

