__global__ void myKernel(const char* text, int* m, int num_chars) {
    __shared__ int D[PADDED_SIZE]; // PADDED_SIZE = (NUM_THREADS + 1) * sizeof(int)
    int tid = threadIdx.x;
    int bid = blockIdx.x;
    int global_id = tid + bid * blockDim.x;

    if (global_id < num_chars) {
        // Initialize shared memory
        D[tid * (PADDED_SIZE / NUM_THREADS)] = 0;

        // Process the text
        for (int i = 0; i < num_chars; i++) {
            // Update shared memory
            D[tid * (PADDED_SIZE / NUM_THREADS)] += text[global_id];

            // Check condition and update global memory
            if (D[tid * (PADDED_SIZE / NUM_THREADS)] > SOME_THRESHOLD) {
                m[global_id] = 1;
            }
        }
    }
}

