std::string longestString(const std::vector<std::string>& strings) {
    if (strings.empty()) {
        return "";
    }
    const std::string* longest = &strings[0];
    for (const std::string& str : strings) {
        if (str.length() > longest->length()) {
            longest = &str;
        }
    }
    return *longest;
}

