#include <iostream>
#include <vector>
#include <string>

std::string longestCommonSubstring(const std::string& s1, const std::string& s2) {
    int m = s1.length();
    int n = s2.length();
    std::vector<std::vector<int>> dp(m + 1, std::vector<int>(n + 1, 0));
    int maxLength = 0;
    int endIndex = -1;

    // Fill the DP table
    for (int i = 1; i <= m; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (s1[i - 1] == s2[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1] + 1;
                if (dp[i][j] > maxLength) {
                    maxLength = dp[i][j];
                    endIndex = i - 1; // Note: i-1 because the end index is 0-based
                }
            } else {
                dp[i][j] = 0;
            }
        }
    }

    // Extract the longest common substring
    if (maxLength > 0) {
        return s1.substr(endIndex - maxLength + 1, maxLength);
    }

    return ""; // No common substring found
}

int main() {
    std::string s1 = "ABABC";
    std::string s2 = "BABC";
    std::string result = longestCommonSubstring(s1, s2);
    std::cout << "Longest Common Substring: " << result << std::endl;
    return 0;
}

