enum class Piece {
    None,  // Empty square
    WhitePawn,
    WhiteRook,
    WhiteKnight,
    WhiteBishop,
    WhiteQueen,
    WhiteKing,
    BlackPawn,
    BlackRook,
    BlackKnight,
    BlackBishop,
    BlackQueen,
    BlackKing
};

class Chessboard {
public:
    Chessboard() {
        initializeBoard();
    }

    void initializeBoard() {
        // Initialize the board with the standard starting position
        board.fill(Piece::None);

        // Place white pieces
        board[0][0] = board[0][7] = Piece::WhiteRook;
        board[0][1] = board[0][6] = Piece::WhiteKnight;
        board[0][2] = board[0][5] = Piece::WhiteBishop;
        board[0][3] = Piece::WhiteQueen;
        board[0][4] = Piece::WhiteKing;
        for (int i = 0; i < 8; ++i) {
            board[1][i] = Piece::WhitePawn;
        }

        // Place black pieces
        board[7][0] = board[7][7] = Piece::BlackRook;
        board[7][1] = board[7][6] = Piece::BlackKnight;
        board[7][2] = board[7][5] = Piece::BlackBishop;
        board[7][3] = Piece::BlackQueen;
        board[7][4] = Piece::BlackKing;
        for (int i = 0; i < 8; ++i) {
            board[6][i] = Piece::BlackPawn;
        }
    }

    void displayBoard() const {
        for (int i = 0; i < 8; ++i) {
            for (int j = 0; j < 8; ++j) {
                std::cout << pieceToString(board[i][j]) << " ";
            }
            std::cout << std::endl;
        }
    }

    bool movePiece(int fromRow, int fromCol, int toRow, int toCol) {
        if (fromRow < 0 || fromRow >= 8 || fromCol < 0 || fromCol >= 8 ||
            toRow < 0 || toRow >= 8 || toCol < 0 || toCol >= 8) {
            std::cerr << "Invalid move: Out of bounds" << std::endl;
            return false;
        }

        if (board[fromRow][fromCol] == Piece::None) {
            std::cerr << "Invalid move: No piece at the source position" << std::endl;
            return false;
        }

        // Simple move without checks for valid moves or captures
        board[toRow][toCol] = board[fromRow][fromCol];
        board[fromRow][fromCol] = Piece::None;

        return true;
    }

private:
    std::array<std::array<Piece, 8>, 8> board;

    std::string pieceToString(Piece piece) const {
        switch (piece) {
            case Piece::None: return ".";
            case Piece::WhitePawn: return "P";
            case Piece::WhiteRook: return "R";
            case Piece::WhiteKnight: return "N";
            case Piece::WhiteBishop: return "B";
            case Piece::WhiteQueen: return "Q";
            case Piece::WhiteKing: return "K";
            case Piece::BlackPawn: return "p";
            case Piece::BlackRook: return "r";
            case Piece::BlackKnight: return "n";
            case Piece::BlackBishop: return "b";
            case Piece::BlackQueen: return "q";
            case Piece::BlackKing: return "k";
            default: return "?";
        }
    }
};

int main() {
    Chessboard chessboard;
    chessboard.displayBoard();

    // Example move
    chessboard.movePiece(1, 0, 2, 0);
    chessboard.displayBoard();

    return 0;
}

