LRESULT CALLBACK WndProc(HWND hwnd, UINT msg, WPARAM wParam, LPARAM lParam);

int WINAPI WinMain(HINSTANCE hInstance, HINSTANCE hPrevInstance, LPSTR lpCmdLine, int nCmdShow) {
    WNDCLASS wc = {0};
    wc.lpfnWndProc = WndProc;
    wc.hInstance = hInstance;
    wc.lpszClassName = L"CustomTitleBarWindow";
    RegisterClass(&wc);

    HWND hwnd = CreateWindowEx(0, L"CustomTitleBarWindow", L"Custom Title Bar", WS_OVERLAPPEDWINDOW,
                               CW_USEDEFAULT, CW_USEDEFAULT, 800, 600, NULL, NULL, hInstance, NULL);
    ShowWindow(hwnd, nCmdShow);

    MSG msg;
    while (GetMessage(&msg, NULL, 0, 0)) {
        TranslateMessage(&msg);
        DispatchMessage(&msg);
    }

    return 0;
}

LRESULT CALLBACK WndProc(HWND hwnd, UINT msg, WPARAM wParam, LPARAM lParam) {
    static MARGINS margins = {-1};
    static HBRUSH hBrush = CreateSolidBrush(RGB(255, 255, 255));

    switch (msg) {
    case WM_NCCALCSIZE:
        if (wParam == TRUE) {
            // Adjust the size of the non-client area
            NCCALCSIZE_PARAMS* lpncsp = (NCCALCSIZE_PARAMS*)lParam;
            lpncsp->rgrc[0].top += 30; // Increase the height of the title bar
            return WVR_REDRAW;
        }
        break;

    case WM_NCPAINT:
        {
            HRGN hRgn = (HRGN)wParam;
            HDC hdc = GetWindowDC(hwnd);
            RECT rect;
            GetWindowRect(hwnd, &rect);
            rect.bottom = rect.top + 30; // Title bar height

            // Draw the custom button
            RECT buttonRect = {rect.right - 50, rect.top, rect.right, rect.top + 30};
            HBRUSH buttonBrush = CreateSolidBrush(RGB(200, 200, 255));
            FillRect(hdc, &buttonRect, buttonBrush);
            DeleteObject(buttonBrush);

            // Draw the glow effect
            for (int i = 1; i <= 10; i++) {
                RECT glowRect = {buttonRect.left - i, buttonRect.top - i, buttonRect.right + i, buttonRect.bottom + i};
                HBRUSH glowBrush = CreateSolidBrush(RGB(255, 255, 255 - i * 15));
                FrameRect(hdc, &glowRect, glowBrush);
                DeleteObject(glowBrush);
            }

            ReleaseDC(hwnd, hdc);
        }
        return 0;

    case WM_NCLBUTTONDOWN:
        if (LOWORD(lParam) >= 750 && LOWORD(lParam) <= 800 && HIWORD(lParam) >= 0 && HIWORD(lParam) <= 30) {
            // Handle button click
            MessageBox(hwnd, L"Button Clicked!", L"Info", MB_OK);
            return 0;
        }
        break;

    case WM_CREATE:
        DwmExtendFrameIntoClientArea(hwnd, &margins);
        break;

    case WM_DESTROY:
        PostQuitMessage(0);
        break;

    default:
        return DefWindowProc(hwnd, msg, wParam, lParam);
    }

    return 0;
}

#include <openssl/aes.h>
#include <openssl/evp.h>
#include <string>
#include <vector>

std::string decrypt(const std::vector<uint8_t>& cipherText, const std::vector<uint8_t>& key, const std::vector<uint8_t>& iv)
{
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        // Handle error
        return "";
    }

    if (EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), nullptr, key.data(), iv.data()) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        // Handle error
        return "";
    }

    std::vector<uint8_t> plainText(cipherText.size() + AES_BLOCK_SIZE);
    int len;
    if (EVP_DecryptUpdate(ctx, plainText.data(), &len, cipherText.data(), cipherText.size()) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        // Handle error
        return "";
    }

    int finalLen;
    if (EVP_DecryptFinal_ex(ctx, plainText.data() + len, &finalLen) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        // Handle error
        return "";
    }

    EVP_CIPHER_CTX_free(ctx);

    plainText.resize(len + finalLen);
    return std::string(plainText.begin(), plainText.end());
}

