#include <iostream>
#include <vector>
#include <queue>
using namespace std;

const int MAX_N = 200;

bool isBipartite(int n, vector<vector<int>>& graph) {
    vector<int> color(n, -1); // -1: not colored, 0: color 1, 1: color 2

    for (int i = 0; i < n; ++i) {
        if (color[i] == -1) {
            color[i] = 0;
            queue<int> q;
            q.push(i);

            while (!q.empty()) {
                int u = q.front();
                q.pop();

                for (int v : graph[u]) {
                    if (color[v] == -1) {
                        color[v] = 1 - color[u];
                        q.push(v);
                    } else if (color[v] == color[u]) {
                        return false;
                    }
                }
            }
        }
    }
    return true;
}

int main() {
    int n, k;
    while (cin >> n && n != 0) {
        cin >> k;
        vector<vector<int>> graph(n);

        for (int i = 0; i < k; ++i) {
            int a, b;
            cin >> a >> b;
            a--; b--; // Convert to 0-based index
            graph[a].push_back(b);
            graph[b].push_back(a);
        }

        if (isBipartite(n, graph)) {
            cout << "Possible" << endl;
        } else {
            cout << "Not possible" << endl;
        }
    }

    return 0;
}

#include <Poco/Crypto/Cipher.h>
