#include <vector>

std::vector<unsigned char> EVP_BytesToKey(const std::string& password, const std::string& salt, int keySize, int ivSize)
{
    Poco::Crypto::MD5Engine md5;
    std::vector<unsigned char> data(password.begin(), password.end());
    data.insert(data.end(), salt.begin(), salt.end());

    std::vector<unsigned char> derivedKey;
    int counter = 1;
    while (derivedKey.size() < keySize + ivSize)
    {
        md5.update(data);
        std::vector<unsigned char> hash = md5.digest();
        derivedKey.insert(derivedKey.end(), hash.begin(), hash.end());

        for (size_t i = 0; i < password.size(); ++i)
        {
            data[i] = data[i] ^ counter;
        }
        counter++;
    }

    return derivedKey;
}

