double calculateMean(const std::vector<double>& numbers) {
    if (numbers.empty()) {
        throw std::invalid_argument("The list must not be empty.");
    }
    return std::accumulate(numbers.begin(), numbers.end(), 0.0) / numbers.size();
}

double calculateVariance(const std::vector<double>& numbers, double mean) {
    double sum = 0.0;
    for (double x : numbers) {
        sum += (x - mean) * (x - mean);
    }
    return sum / numbers.size();
}

double calculateStandardDeviation(const std::vector<double>& numbers) {
    if (numbers.size() < 2) {
        throw std::invalid_argument("The list must contain at least two numbers.");
    }
    double mean = calculateMean(numbers);
    double variance = calculateVariance(numbers, mean);
    return std::sqrt(variance);
}

int main() {
    try {
        std::vector<double> numbers = {2.5, 3.5, 4.0, 5.5, -1.0, 0.25};
        double std_dev = calculateStandardDeviation(numbers);
        std::cout << "The standard deviation is: " << std_dev << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }
    return 0;
}

