    Vector3D normalized_v1 = v1.normalize();
    std::cout << "Normalized v1: ";
    normalized_v1.print();

    Vector3D sum_v1_v2 = v1.add(v2);
    std::cout << "v1 + v2: ";
    sum_v1_v2.print();

    return 0;
}

