// Function to calculate the Euclidean distance between two points
double distance(const std::vector<double>& p1, const std::vector<double>& p2) {
    double dx = p1[0] - p2[0];
    double dy = p1[1] - p2[1];
    double dz = p1[2] - p2[2];
    return std::sqrt(dx * dx + dy * dy + dz * dz);
}

// Function to calculate the total energy of the system (negative of minimum distance)
double total_energy(const std::vector<std::vector<double>>& points) {
    double min_dist = std::numeric_limits<double>::max();
    for (size_t i = 0; i < points.size(); ++i) {
        for (size_t j = i + 1; j < points.size(); ++j) {
            double dist = distance(points[i], points[j]);
            if (dist < min_dist) {
                min_dist = dist;
            }
        }
    }
    return -min_dist; // We want to maximize the minimum distance
}

// Function to generate a random point on the unit sphere
std::vector<double> random_point_on_sphere() {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::normal_distribution<> dist(0.0, 1.0);

    double x = dist(gen);
    double y = dist(gen);
    double z = dist(gen);
    double norm = std::sqrt(x * x + y * y + z * z);
    return {x / norm, y / norm, z / norm};
}

// Function to perform a small random perturbation on a point
std::vector<double> perturb_point(const std::vector<double>& point, double perturbation) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_real_distribution<> dist(-perturbation, perturbation);

    std::vector<double> perturbed_point = point;
    for (auto& coord : perturbed_point) {
        coord += dist(gen);
    }
    double norm = std::sqrt(perturbed_point[0] * perturbed_point[0] +
                            perturbed_point[1] * perturbed_point[1] +
                            perturbed_point[2] * perturbed_point[2]);
    for (auto& coord : perturbed_point) {
        coord /= norm;
    }
    return perturbed_point;
}

// Simulated annealing algorithm to optimize point distribution
std::vector<std::vector<double>> optimize_points(int N, double initial_temperature, double cooling_rate, int max_iterations) {
    std::vector<std::vector<double>> points;
    for (int i = 0; i < N; ++i) {
        points.push_back(random_point_on_sphere());
    }

    double temperature = initial_temperature;
    for (int iteration = 0; iteration < max_iterations; ++iteration) {
        std::vector<std::vector<double>> new_points = points;
        for (auto& point : new_points) {
            point = perturb_point(point, 0.1);
        }

        double current_energy = total_energy(points);
        double new_energy = total_energy(new_points);

        double acceptance_probability = std::exp((current_energy - new_energy) / temperature);

        if (new_energy < current_energy || (std::rand() / static_cast<double>(RAND_MAX)) < acceptance_probability) {
            points = new_points;
        }

        temperature *= cooling_rate;
    }

    return points;
}

int main() {
    int N = 5; // Number of points
    double initial_temperature = 1.0;
    double cooling_rate = 0.99;
    int max_iterations = 10000;

    std::vector<std::vector<double>> points = optimize_points(N, initial_temperature, cooling_rate, max_iterations);

    for (const auto& point : points) {
        std::cout << "Point: (" << point[0] << ", " << point[1] << ", " << point[2] << ")\n";
    }

    return 0;
}

#include <cmath>
#include <memory>

class Kernel {
public:
    virtual ~Kernel() = default;
    virtual double covarianceFunction(double X, double Y) const = 0;
    virtual std::unique_ptr<Kernel> clone() const = 0;
};

class GaussianKernel : public Kernel {
public:
    GaussianKernel(double sigma, double scale) : m_sigma(sigma), m_scale(scale) {}
    GaussianKernel(double sigma) : m_sigma(sigma), m_scale(1) {}

    double covarianceFunction(double X, double Y) const override {
        return m_scale * std::exp(-std::norm(X - Y) / (m_sigma * m_sigma));
    }

    std::unique_ptr<Kernel> clone() const override {
        return std::make_unique<GaussianKernel>(*this);
    }

private:
    double m_sigma;
    double m_scale;
};

class CompoundKernel : public Kernel {
public:
    CompoundKernel(std::unique_ptr<Kernel> a, std::unique_ptr<Kernel> b)
        : a_(std::move(a)), b_(std::move(b)) {}

    double covarianceFunction(double X, double Y) const override {
        return a_->covarianceFunction(X, Y) + b_->covarianceFunction(X, Y);
    }

    std::unique_ptr<Kernel> clone() const override {
        return std::make_unique<CompoundKernel>(a_->clone(), b_->clone());
    }

private:
    std::unique_ptr<Kernel> a_;
    std::unique_ptr<Kernel> b_;
};

// Example usage
int main() {
    auto kernel1 = std::make_unique<GaussianKernel>(1.0, 1.0);
    auto kernel2 = std::make_unique<GaussianKernel>(2.0, 1.0);
    auto compoundKernel = std::make_unique<CompoundKernel>(std::move(kernel1), std::move(kernel2));

    double X = 0.5;
    double Y = 0.7;
    double covariance = compoundKernel->covarianceFunction(X, Y);

    // Use the covariance value as needed
    return 0;
}

#include <iostream>
#include <cmath> // For sqrt and pow functions

class Vector2D {
public:
    // Constructor
    Vector2D(double x = 0.0, double y = 0.0) : x(x), y(y) {}

    // Accessors (getters)
    double getX() const { return x; }
    double getY() const { return y; }

    // Mutators (setters)
    void setX(double newX) { x = newX; }
    void setY(double newY) { y = newY; }

    // Vector addition
    Vector2D operator+(const Vector2D& other) const {
        return Vector2D(x + other.x, y + other.y);
    }

    // Vector subtraction
    Vector2D operator-(const Vector2D& other) const {
        return Vector2D(x - other.x, y - other.y);
    }

    // Scalar multiplication
    Vector2D operator*(double scalar) const {
        return Vector2D(x * scalar, y * scalar);
    }

    // Dot product
    double dot(const Vector2D& other) const {
        return x * other.x + y * other.y;
    }

    // Magnitude (length) of the vector
    double magnitude() const {
        return std::sqrt(x * x + y * y);
    }

    // Normalized vector (unit vector)
    Vector2D normalize() const {
        double mag = magnitude();
        if (mag > 0) {
            return Vector2D(x / mag, y / mag);
        }
        return *this; // Return the original vector if it's a zero vector
    }

private:
    double x, y;
};

// Function to print a Vector2D
void printVector(const Vector2D& v) {
    std::cout << "Vector: (" << v.getX() << ", " << v.getY() << ")" << std::endl;
}

int main() {
    Vector2D v1(3.0, 4.0);
    Vector2D v2(1.0, 2.0);

    Vector2D v3 = v1 + v2;
    Vector2D v4 = v1 - v2;
    Vector2D v5 = v1 * 2.0;
    double dotProduct = v1.dot(v2);
    double magnitude = v1.magnitude();
    Vector2D normalized = v1.normalize();

    printVector(v1);
    printVector(v2);
    printVector(v3); // v1 + v2
    printVector(v4); // v1 - v2
    printVector(v5); // v1 * 2.0
    std::cout << "Dot Product: " << dotProduct << std::endl;
    std::cout << "Magnitude: " << magnitude << std::endl;
    printVector(normalized);

    return 0;
}

