// Definition for singly-linked list.
struct ListNode {
    int val;
    ListNode *next;
    ListNode(int x) : val(x), next(nullptr) {}
};

class Solution {
public:
    bool hasCycle(ListNode *head) {
        if (head == nullptr || head->next == nullptr) {
            return false;
        }

        ListNode *slow = head;
        ListNode *fast = head;

        while (fast != nullptr && fast->next != nullptr) {
            slow = slow->next;
            fast = fast->next->next;

            if (slow == fast) {
                return true; // Cycle detected
            }
        }

        return false; // No cycle
    }
};

// Function to create a linked list with a cycle for testing
ListNode* createLinkedListWithCycle() {
    ListNode *node1 = new ListNode(1);
    ListNode *node2 = new ListNode(2);
    ListNode *node3 = new ListNode(3);
    ListNode *node4 = new ListNode(4);

    node1->next = node2;
    node2->next = node3;
    node3->next = node4;
    node4->next = node2; // Creating a cycle

    return node1;
}

int main() {
    Solution solution;

    // Test with a linked list with a cycle
    ListNode *headWithCycle = createLinkedListWithCycle();
    cout << "List with cycle: " << (solution.hasCycle(headWithCycle) ? "Yes" : "No") << endl;

    // Test with a linked list without a cycle
    ListNode *headWithoutCycle = new ListNode(1);
    headWithoutCycle->next = new ListNode(2);
    headWithoutCycle->next->next = new ListNode(3);
    cout << "List without cycle: " << (solution.hasCycle(headWithoutCycle) ? "Yes" : "No") << endl;

    return 0;
}

__global__ void gameOfLife(float* returnBuffer, int width, int height) {
    __shared__ float sharedData[32][32];

    int x = blockIdx.x * blockDim.x + threadIdx.x;
    int y = blockIdx.y * blockDim.y + threadIdx.y;

    // Load data into shared memory
    if (x < width && y < height) {
        sharedData[threadIdx.y + 1][threadIdx.x + 1] = tex2D(inputTex, x, y);
    }

    __syncthreads();

    // Check if the thread is within the inner block
    if (threadIdx.x > 0 && threadIdx.x < 31 && threadIdx.y > 0 && threadIdx.y < 31) {
        float p = sharedData[threadIdx.y][threadIdx.x];
        float neighbors = 0;

        neighbors += sharedData[threadIdx.y][threadIdx.x - 1];
        neighbors += sharedData[threadIdx.y][threadIdx.x + 1];
        neighbors += sharedData[threadIdx.y - 1][threadIdx.x];
        neighbors += sharedData[threadIdx.y + 1][threadIdx.x];
        neighbors += sharedData[threadIdx.y - 1][threadIdx.x - 1];
        neighbors += sharedData[threadIdx.y - 1][threadIdx.x + 1];
        neighbors += sharedData[threadIdx.y + 1][threadIdx.x - 1];
        neighbors += sharedData[threadIdx.y + 1][threadIdx.x + 1];

        float final = 0;
        if (neighbors < 2 || neighbors > 3) {
            final = 0;
        } else if (p != 0 || neighbors == 3) {
            final = 1;
        }

        if (x < width && y < height) {
            returnBuffer[x + y * width] = final;
        }
    }
}

