bool isPrime(int n) {
    if (n <= 1) return false; // 1 and numbers less than 1 are not prime
    for (int i = 2; i * i <= n; i++) {
        if (n % i == 0) return false; // Found a divisor, not a prime number
    }
    return true; // No divisors found, it's a prime number
}

