void printFibonacci(int n) {
    long long first = 0, second = 1, next;

    if (n <= 0) {
        cout << "Please enter a positive integer." << endl;
        return;
    }

    cout << "Fibonacci Series up to " << n << " numbers:" << endl;

    for (int i = 1; i <= n; ++i) {
        if (i == 1) {
            cout << first << ", ";
            continue;
        }
        if (i == 2) {
            cout << second << ", ";
            continue;
        }
        next = first + second;
        first = second;
        second = next;
        cout << next;
        if (i < n) cout << ", ";
    }
    cout << endl;
}

