// Function to compute the hash using SSE
uint32_t computeHash(const uint32_t* data, size_t length) {
    __m128i hash = _mm_set1_epi32(0);
    for (size_t i = 0; i < length / 4; i++) {
        __m128i chunk = _mm_loadu_si128((__m128i*)&data[i * 4]);
        hash = _mm_xor_si128(hash, chunk);
    }
    uint32_t result;
    _mm_storeu_si128((__m128i*)&result, hash);
    return result;
}

