// Function to wrap script tags in CDATA sections
QString wrapScriptTagsInCdata(const QString &html) {
    QString modifiedHtml = html;
    int start = 0;
    while ((start = modifiedHtml.indexOf("<script", start)) != -1) {
        int end = modifiedHtml.indexOf("</script>", start);
        if (end == -1) break; // Incomplete script tag

        QString scriptContent = modifiedHtml.mid(start, end - start + 9);
        QString wrappedScript = "<script type=\"text/javascript\">\n"
                                "    //<![CDATA[\n"
                                "    " + scriptContent + "\n"
                                "    //]]>\n"
                                "</script>";
        modifiedHtml.replace(start, end - start + 9, wrappedScript);
        start += wrappedScript.length();
    }
    return modifiedHtml;
}

int main() {
    QString mainHtml;

    {
        QFile file("main.html");
        if (!file.open(QIODevice::ReadOnly)) {
            qDebug() << "Error reading file main.html";
            return -1;
        }
        QTextStream stream(&file);
        mainHtml = stream.readAll();
        file.close();
    }

    // Preprocess the HTML to wrap script tags in CDATA sections
    QString modifiedHtml = wrapScriptTagsInCdata(mainHtml);

    QDomDocument doc;
    QString errStr;
    int errLine = 0, errCol = 0;
    if (!doc.setContent(modifiedHtml, &errStr, &errLine, &errCol)) {
        qDebug() << errStr << "L:" << errLine << ":" << errCol;
        return -1;
    }

    std::function<void(const QDomElement&, int)> printTags =
    [&printTags](const QDomElement& elem, int tab) {
        QString space(3 * tab, ' ');
        QDomNode n = elem.firstChild();
        for (; !n.isNull(); n = n.nextSibling()) {
            QDomElement e = n.toElement();
            if (e.isNull()) continue;

            qDebug() << space + e.tagName();
            printTags(e, tab + 1);
        }
    };
    printTags(doc.documentElement(), 0);

    return 0;
}

