const std::string CounterFile = "counter.dat";
const std::string MutexName = "Global\\SharedCounterMutex";

class CounterManager
{
private:
    HANDLE mutex;

public:
    CounterManager()
    {
        mutex = CreateMutex(NULL, FALSE, MutexName.c_str());
    }

    ~CounterManager()
    {
        CloseHandle(mutex);
    }

    int IncrementCounter()
    {
        WaitForSingleObject(mutex, INFINITE);
        int counter = 0;
        std::ifstream file(CounterFile);
        if (file.is_open())
        {
            file >> counter;
            file.close();
        }
        counter++;
        std::ofstream fileOut(CounterFile);
        if (fileOut.is_open())
        {
            fileOut << counter;
            fileOut.close();
        }
        ReleaseMutex(mutex);
        return counter;
    }

    int DecrementCounter()
    {
        WaitForSingleObject(mutex, INFINITE);
        int counter = 0;
        std::ifstream file(CounterFile);
        if (file.is_open())
        {
            file >> counter;
            file.close();
        }
        counter--;
        std::ofstream fileOut(CounterFile);
        if (fileOut.is_open())
        {
            fileOut << counter;
            fileOut.close();
        }
        ReleaseMutex(mutex);
        return counter;
    }
};

#include <iostream>
#include <string>
#include <vector>
#include <iterator>

class FileStructGenerator {
public:
    class Iterator {
    public:
        using value_type = std::string;
        using reference = std::string&;
        using pointer = std::string*;
        using difference_type = std::ptrdiff_t;
        using iterator_category = std::input_iterator_tag;

        Iterator(FileStructGenerator& gen, bool end = false) : gen_(gen), end_(end) {
            if (!end_) {
                current_ = gen_.next();
            }
        }

        Iterator& operator++() {
            if (!end_) {
                current_ = gen_.next();
            }
            return *this;
        }

        Iterator operator++(int) {
            Iterator tmp = *this;
            ++(*this);
            return tmp;
        }

        bool operator==(const Iterator& other) const {
            return end_ == other.end_;
        }

        bool operator!=(const Iterator& other) const {
            return !(*this == other);
        }

        const std::string& operator*() const {
            return current_;
        }

        const std::string* operator->() const {
            return &current_;
        }

    private:
        FileStructGenerator& gen_;
        std::string current_;
        bool end_;
    };

    FileStructGenerator(const std::string& filename) : filename_(filename), bad_line_number_(filename.find("more") != std::string::npos ? 5 : 6) {
        current_state_ = 0;
    }

    Iterator begin() {
        return Iterator(*this);
    }

    Iterator end() {
        return Iterator(*this, true);
    }

private:
    std::string filename_;
    int bad_line_number_;
    int current_state_;

    std::string next() {
        switch (current_state_) {
            case 0:
                current_state_ = 1;
                return "data";
            case 1:
                for (int i = 0; i < bad_line_number_; ++i) {
                    current_state_++;
                    return "unused";
                }
                current_state_ = bad_line_number_ + 1;
                // Fall through to the next case
            case bad_line_number_ + 1:
                current_state_++;
                return "data";
            default:
                return "data"; // This will loop indefinitely, similar to the Python `while True` loop
        }
    }
};

// Example usage
int main() {
    FileStructGenerator gen("example_more.txt");

    for (const auto& value : gen) {
        std::cout << value << std::endl;
    }

    return 0;
}

