/* Define the Iterator object */
typedef struct {
    PyObject_HEAD
    size_t max;
    size_t current;
} IterObject;

static void IterObject_dealloc(IterObject* self) {
    Py_TYPE(self)->tp_free((PyObject*)self);
}

static PyObject* IterObject_iter(IterObject* self) {
    Py_INCREF(self);
    return (PyObject*)self;
}

static PyObject* IterObject_next(IterObject* self) {
    if (self->current >= self->max) {
        PyErr_SetNone(PyExc_StopIteration);
        return NULL;
    }
    PyObject* result = PyLong_FromSize_t(self->current);
    self->current++;
    return result;
}

