PyMODINIT_FUNC PyInit_sequence(void) {
    PyObject* m;

    IterObjectType.tp_new = PyType_GenericNew;
    if (PyType_Ready(&IterObjectType) < 0)
        return NULL;

    Sequence_Type.tp_new = PyType_GenericNew;
    if (PyType_Ready(&Sequence_Type) < 0)
        return NULL;

    m = PyModule_Create(&sequence_module);
    if (m == NULL)
