LRESULT CALLBACK WndProc(HWND hwnd, UINT msg, WPARAM wParam, LPARAM lParam);

int WINAPI WinMain(HINSTANCE hInstance, HINSTANCE hPrevInstance, LPSTR lpCmdLine, int nCmdShow) {
    WNDCLASS wc = {0};
    wc.lpfnWndProc = WndProc;
    wc.hInstance = hInstance;
    wc.hbrBackground = CreateSolidBrush(RGB(255, 255, 255));
    wc.lpszClassName = "MyWndClass";
    RegisterClass(&wc);

    HWND hwnd = CreateWindow(
        "MyWndClass",
        "Draggable and Transparent Window",
        WS_OVERLAPPEDWINDOW,
        CW_USEDEFAULT, CW_USEDEFAULT, 400, 300,
        NULL, NULL, hInstance, NULL
    );
    SetWindowLong(hwnd, GWL_EXSTYLE, GetWindowLong(hwnd, GWL_EXSTYLE) | WS_EX_LAYERED);

    ShowWindow(hwnd, nCmdShow);

    MSG msg = {0};
    while (GetMessage(&msg, NULL, 0, 0)) {
        TranslateMessage(&msg);
        DispatchMessage(&msg);
    }
    return msg.wParam;
}

LRESULT CALLBACK WndProc(HWND hwnd, UINT msg, WPARAM wParam, LPARAM lParam) {
    static POINT offset;
    static BOOL dragging = FALSE;
    switch (msg) {
        case WM_DESTROY:
            PostQuitMessage(0);
            break;
        case WM_LBUTTONDOWN:
            offset.x = GET_X_LPARAM(lParam);
            offset.y = GET_Y_LPARAM(lParam);
            dragging = TRUE;
            SetLayeredWindowAttributes(hwnd, 0, 200, LWA_ALPHA);
            SetCursor(LoadCursor(NULL, IDC_SIZEALL));
            break;
        case WM_MOUSEMOVE:
            if (dragging) {
                int x = GET_X_LPARAM(lParam) - offset.x;
                int y = GET_Y_LPARAM(lParam) - offset.y;
                SetWindowPos(hwnd, NULL, x, y, 0, 0, SWP_NOSIZE | SWP_NOZORDER | SWP_NOACTIVATE);
            }
            break;
        case WM_LBUTTONUP:
            dragging = FALSE;
            SetLayeredWindowAttributes(hwnd, 0, 255, LWA_ALPHA);
            SetCursor(LoadCursor(NULL, IDC_ARROW));
            break;
        default:
            return DefWindowProc(hwnd, msg, wParam, lParam);
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <climits>

using namespace std;

vector<int> minCostTapas(vector<int>& calorias, int M) {
    int n = calorias.size();
    vector<vector<int>> dp(n + 1, vector<int>(M + 1, INT_MAX));
    vector<vector<int>> chosen(n + 1, vector<int>(M + 1, 0));

    dp[0][0] = 0;
    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j <= M; ++j) {
            if (calorias[i - 1] > j) {
                dp[i][j] = dp[i - 1][j];
                chosen[i][j] = chosen[i - 1][j];
            } else {
                int includeTapas = 1 + dp[i - 1][j - calorias[i - 1]];
                int excludeTapas = dp[i - 1][j];
                if (includeTapas <= excludeTapas) {
                    dp[i][j] = includeTapas;
                    chosen[i][j] = i;
                } else {
                    dp[i][j] = excludeTapas;
                    chosen[i][j] = chosen[i - 1][j];
                }
            }
        }
    }

    int targetCalories = M;
    while (chosen[n][targetCalories] == 0) {
        --targetCalories;
    }

    vector<int> tapasElegidas;
    int i = n;
    int j = targetCalories;
    while (i > 0 && j >= 0) {
        if (chosen[i][j] == i) {
            tapasElegidas.push_back(i - 1);
            j -= calorias[i - 1];
        }
        --i;
    }

    return tapasElegidas;
}

int main() {
    vector<int> calorias = {3, 5, 10, 13, 15, 16};
    int M = 45;
    vector<int> tapas_para_pedir = minCostTapas(calorias, M);

    cout << "Tapas para pedir:\n";
    for (int index : tapas_para_pedir) {
        cout << "Tapa " << index + 1 << ": " << calorias[index] << " calorias\n";
    }

    return 0;
}

