    Node* tail;
    Node* minNode;
    Node* maxNode;

public:
    DoublyLinkedList() : head(nullptr), tail(nullptr), minNode(nullptr), maxNode(nullptr) {}

    void insert(int value) {
        Node* newNode = new Node(value);

        if (head == nullptr) {
            head = tail = minNode = maxNode = newNode;
        } else {
            newNode->prev = tail;
            tail->next = newNode;
            tail = newNode;

            if (value < minNode->value) {
                minNode = newNode;
            }
            if (value > maxNode->value) {
                maxNode = newNode;
            }
        }
    }

    void remove(int value) {
        Node* current = head;
        while (current != nullptr) {
            if (current->value == value) {
                if (current->prev) {
                    current->prev->next = current->next;
                } else {
                    head = current->next;
                }

                if (current->next) {
                    current->next->prev = current->prev;
                } else {
                    tail = current->prev;
                }

                if (minNode == current) {
                    minNode = findMinNode();
                }
                if (maxNode == current) {
                    maxNode = findMaxNode();
                }

                delete current;
                return;
            }
            current = current->next;
        }
    }

    int getMin() const {
        return minNode ? minNode->value : std::numeric_limits<int>::max();
    }

    int getMax() const {
        return maxNode ? maxNode->value : std::numeric_limits<int>::min();
    }

private:
    Node* findMinNode() const {
        Node* minNode = head;
        Node* current = head;
        while (current != nullptr) {
            if (current->value < minNode->value) {
                minNode = current;
            }
            current = current->next;
        }
        return minNode;
    }

    Node* findMaxNode() const {
        Node* maxNode = head;
        Node* current = head;
        while (current != nullptr) {
            if (current->value > maxNode->value) {
                maxNode = current;
            }
            current = current->next;
        }
        return maxNode;
    }
};

int main() {
    DoublyLinkedList list;
    list.insert(10);
    list.insert(5);
    list.insert(15);
    list.insert(3);

    std::cout << "Min: " << list.getMin() << std::endl; // Output: Min: 3
    std::cout << "Max: " << list.getMax() << std::endl; // Output: Max: 15

    list.remove(15);
    std::cout << "Max after removing 15: " << list.getMax() << std::endl; // Output: Max: 10

    return 0;
}

#include <immintrin.h>
#include <iostream>

bool atomic_cmpxchg128(__int128* ptr, __int128 expected, __int128 new_value) {
    __int128 old_value = *ptr;
    __int128 current_value = expected;

    __asm__ __volatile__(
        "lock cmpxchg16b %1\n"
        : "=a"(current_value), "=m"(*ptr)
        : "a"(expected), "b"((uint64_t)new_value), "c"((uint64_t)(new_value >> 64)), "d"((uint64_t)(expected >> 64)), "m"(*ptr)
        : "memory"
    );

    return old_value == expected;
}

int main() {
    __int128 data128 = 0x0123456789abcdef123456789abcdef123456789abcdef123456789abcdef;
    __int128 expected = 0x0123456789abcdef123456789abcdef123456789abcdef123456789abcdef;
    __int128 new_value = 0x1122334455667788112233445566778811223344556677881122334455667788;

    bool success = atomic_cmpxchg128(&data128, expected, new_value);

    std::cout << "Comparison and exchange " << (success ? "succeeded" : "failed") << std::endl;
    std::cout << "Data128: " << std::hex << data128 << std::endl;

    return 0;
}

