__global__ void convertGRBG(uchar4 *d_output, uint width, uint height) {
    int x = blockIdx.x * blockDim.x + threadIdx.x;
    int y = blockIdx.y * blockDim.y + threadIdx.y;

    if (x < width && y < height) {
        // Load the Bayer pattern data from global memory
        uchar bayer = tex2D(tex, x, y);

        // Perform demosaicing
        uchar4 pixel;
        // Example demosaicing logic (simplified)
        if (y % 2 == 0) {
            if (x % 2 == 0) {
                // GR
                pixel.x = bayer; // R
                pixel.y = (tex2D(tex, x, y - 1) + tex2D(tex, x, y + 1) + tex2D(tex, x - 1, y) + tex2D(tex, x + 1, y)) / 4; // G
                pixel.z = (tex2D(tex, x - 1, y - 1) + tex2D(tex, x - 1, y + 1) + tex2D(tex, x + 1, y - 1) + tex2D(tex, x + 1, y + 1)) / 4; // B
            } else {
                // BG
                pixel.x = (tex2D(tex, x - 1, y) + tex2D(tex, x + 1, y)) / 2; // R
                pixel.y = (tex2D(tex, x, y - 1) + tex2D(tex, x, y + 1)) / 2; // G
                pixel.z = bayer; // B
            }
        } else {
            if (x % 2 == 0) {
                // GB
                pixel.x = (tex2D(tex, x, y - 1) + tex2D(tex, x, y + 1)) / 2; // R
                pixel.y = (tex2D(tex, x - 1, y) + tex2D(tex, x + 1, y)) / 2; // G
                pixel.z = bayer; // B
            } else {
                // RG
                pixel.x = bayer; // R
                pixel.y = (tex2D(tex, x, y - 1) + tex2D(tex, x, y + 1) + tex2D(tex, x - 1, y) + tex2D(tex, x + 1, y)) / 4; // G
                pixel.z = (tex2D(tex, x - 1, y - 1) + tex2D(tex, x - 1, y + 1) + tex2D(tex, x + 1, y - 1) + tex2D(tex, x + 1, y + 1)) / 4; // B
            }
        }

        // Store the result in global memory
        d_output[y * width + x] = pixel;
    }
}

