const int BOARD_SIZE = 10;
const std::vector<int> SHIP_SIZES = {5, 4, 3, 3, 2};

enum class CellStatus { Empty, Ship, Hit, Miss };

class Board {
private:
    std::vector<std::vector<CellStatus>> grid;

public:
    Board() : grid(BOARD_SIZE, std::vector<CellStatus>(BOARD_SIZE, CellStatus::Empty)) {}

    void placeShip(int size, int row, int col, bool isHorizontal) {
        if (isHorizontal) {
            for (int i = 0; i < size; ++i) {
                grid[row][col + i] = CellStatus::Ship;
            }
        } else {
            for (int i = 0; i < size; ++i) {
                grid[row + i][col] = CellStatus::Ship;
            }
        }
    }

    bool isValidPlacement(int size, int row, int col, bool isHorizontal) {
        if (isHorizontal) {
            if (col + size > BOARD_SIZE) return false;
            for (int i = 0; i < size; ++i) {
                if (grid[row][col + i] != CellStatus::Empty) return false;
            }
        } else {
            if (row + size > BOARD_SIZE) return false;
            for (int i = 0; i < size; ++i) {
                if (grid[row + i][col] != CellStatus::Empty) return false;
            }
        }
        return true;
    }

    bool fire(int row, int col) {
        if (grid[row][col] == CellStatus::Ship) {
            grid[row][col] = CellStatus::Hit;
            return true;
        } else {
            grid[row][col] = CellStatus::Miss;
            return false;
        }
    }

    bool isGameOver() const {
        for (const auto& row : grid) {
            for (const auto& cell : row) {
                if (cell == CellStatus::Ship) return false;
            }
        }
        return true;
    }

    void display() const {
        for (const auto& row : grid) {
            for (const auto& cell : row) {
                switch (cell) {
                    case CellStatus::Empty: std::cout << "."; break;
                    case CellStatus::Ship: std::cout << "S"; break;
                    case CellStatus::Hit: std::cout << "X"; break;
                    case CellStatus::Miss: std::cout << "O"; break;
                }
            }
            std::cout << std::endl;
        }
    }
};

class Player {
private:
    Board board;
    std::string name;

public:
    Player(const std::string& name) : name(name) {}

    void placeShips() {
        std::cout << name << ", place your ships:\n";
        for (int size : SHIP_SIZES) {
            int row, col;
            bool isHorizontal;
            do {
                std::cout << "Place a ship of size " << size << " (row col horizontal): ";
                std::cin >> row >> col >> isHorizontal;
            } while (!board.isValidPlacement(size, row, col, isHorizontal));
            board.placeShip(size, row, col, isHorizontal);
        }
    }

    bool fireAt(Player& opponent) {
        int row, col;
        std::cout << name << ", fire at (row col): ";
        std::cin >> row >> col;
        return opponent.board.fire(row, col);
    }

    bool isGameOver() const {
        return board.isGameOver();
    }

    void displayBoard() const {
        std::cout << name << "'s board:\n";
        board.display();
    }
};

