#include <ctime>
#include <cstdlib>
#include <algorithm>

const int STATES = 4; // 2x2 grid
const int ACTIONS = 4; // up, down, left, right
const double ALPHA = 0.1; // Learning rate
const double GAMMA = 0.9; // Discount factor
const double EPSILON = 0.1; // Epsilon for epsilon-greedy strategy

std::vector<std::vector<double>> Q(STATES, std::vector<double>(ACTIONS, 0.0));

// Function to simulate the environment
int nextState(int currentState, int action) {
    // Simplified state transition
    switch (action) {
        case 0: return (currentState > 1) ? currentState - 2 : currentState; // Up
        case 1: return (currentState < 2) ? currentState + 2 : currentState; // Down
        case 2: return (currentState % 2 != 0) ? currentState - 1 : currentState; // Left
        case 3: return (currentState % 2 == 0) ? currentState + 1 : currentState; // Right
        default: return currentState;
    }
}

double reward(int nextState) {
    return (nextState == 3) ? 100 : 0; // Reward for reaching the goal
}

// Epsilon-greedy action selection
int selectAction(int state) {
    if (rand() / static_cast<double>(RAND_MAX) < EPSILON) {
        return rand() % ACTIONS; // Explore
    } else {
        return std::distance(Q[state].begin(), std::max_element(Q[state].begin(), Q[state].end())); // Exploit
    }
}

void updateQ(int state, int action, int nextState) {
    double maxQ = *std::max_element(Q[nextState].begin(), Q[nextState].end());
    Q[state][action] += ALPHA * (reward(nextState) + GAMMA * maxQ - Q[state][action]);
}

int main() {
    srand(time(0));
    int currentState = 0;
    for (int i = 0; i < 1000; ++i) { // Number of iterations
        int action = selectAction(currentState);
        int nextState = nextState(currentState, action);
        updateQ(currentState, action, nextState);
        currentState = nextState;
        if (currentState == 3) { // Reset to start if goal is reached
            currentState = 0;
        }
    }

    // Print the Q table
    for (const auto &row : Q) {
        for (double value : row) {
            std::cout << value << " ";
        }
        std::cout << std::endl;
    }

    return 0;
}

