#include <iostream>
#include <vector>
#include <string>
using namespace std;
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int b, w, x, y;
    if (!(cin >> b >> w >> x >> y)) return 0;
    char c1, c2; // c1 = background, c2 = island
    int M; // Number of islands of C2
    int K; // Number of holes of C1 inside C2 islands
    // We choose the background color to be the one with the smaller cost coefficient
    // to minimize the total cost (since background typically uses more tiles).
    // If x < y, Black (@) is cheaper -> Background = @
    // If x >= y, White (.) is cheaper -> Background = .

    if (x < y) {
        c1 = '@';
        c2 = '.';
        // We need 'w' white components (islands).
        // We need 'b' black components. 
        // Background counts as 1 black component.
        // We need b - 1 additional black components (holes inside white islands).
        M = w;
        K = b - 1;
    } else {
        c1 = '.';
        c2 = '@';
        // We need 'b' black components (islands).
        // We need 'w' white components.
        // Background counts as 1 white component.
        // We need w - 1 additional white components (holes inside black islands).
        M = b;
        K = w - 1;
    }
    vector<string> grid;
    if (K == 0) {
        // Case A: No holes needed. We just need M simple islands.
        // A grid of height 2 is sufficient.
        // Row 0 contains the islands separated by background.
        // Row 1 is full background to keep the background connected.
        // Pattern: [Separator] [Island] [Separator] [Island] ...

        string r0 = "", r1 = "";

        // Initial separator
        r0 += c1;
        r1 += c1;

        for (int i = 0; i < M; ++i) {
            r0 += c2; // Island
            r1 += c1; // Background

            r0 += c1; // Separator
            r1 += c1; // Background
        }
        grid.push_back(r0);
        grid.push_back(r1);
    } else {
        // Case B: We need K holes.
        // We construct 1 "Complex Island" that contains all K holes, 
        // and M-1 "Simple Islands".
        // A grid of height 4 is used.
        // Row 3 is full background for connectivity.
        // Rows 0-2 contain the islands.

        string r0 = "", r1 = "", r2 = "", r3 = "";

        // Initial separator column
        r0 += c1; r1 += c1; r2 += c1; r3 += c1;

        // 1. Complex Island containing K holes
        // This island spans 3 rows (0, 1, 2).
        // Row 1 contains alternating C2 and C1. The C1s are the holes.
        // Width required: 2*K + 1
        for (int k = 0; k < 2 * K + 1; ++k) {
            r0 += c2;
            if (k % 2 == 0) r1 += c2; else r1 += c1; // C1 here is a hole
            r2 += c2;
            r3 += c1;
        }

        // Separator column
        r0 += c1; r1 += c1; r2 += c1; r3 += c1;

        // 2. Remaining M-1 simple islands
        for (int i = 0; i < M - 1; ++i) {
            // Simple island just needs to be an isolated C2.
            // We place it in Row 1, surrounded by C1 in R0, R2 and separators.
            r0 += c1;
            r1 += c2;
            r2 += c1;
            r3 += c1;

            // Separator column
            r0 += c1; r1 += c1; r2 += c1; r3 += c1;
        }

        grid.push_back(r0);
        grid.push_back(r1);
        grid.push_back(r2);
        grid.push_back(r3);
    }
    cout << grid.size() << " " << grid[0].size() << "\n";
    for (const string& row : grid) {
        cout << row << "\n";
    }
    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
// Global variable for n to be accessible in ask function for boundary checks
long long n_global;
// Function to ask a query and handle response 0, which terminates the program.
int ask(long long x, long long y) {
    // Ensure queries are within the valid range [1, n].
    if (x < 1) x = 1;
    if (x > n_global) x = n_global;
    if (y < 1) y = 1;
    if (y > n_global) y = n_global;
    std::cout << x << " " << y << std::endl;
    int response;
    std::cin >> response;
    if (response == 0) {
        exit(0);
    }
    return response;
}
int main() {
    // Fast I/O
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);
    std::cin >> n_global;
    long long a_low = 1, a_high = n_global;
    long long b_low = 1, b_high = n_global;
    while (true) {
        // If both ranges have been narrowed down to a single value, we have found the answer.
        if (a_low == a_high && b_low == b_high) {
            ask(a_low, b_low);
            // The ask function with response 0 will terminate the program.
            // This part of the code should not be reached.
            break;
        }
        // If one of the numbers is found, we can perform a simple binary search for the other.
        // This is a "safe" binary search because the ambiguity of response 3 is resolved.
        if (a_low == a_high) { // a is known
            long long mid_b = b_low + (b_high - b_low) / 2;
            int response = ask(a_low, mid_b);
            if (response == 2) { // y < b (mid_b < b)
                b_low = mid_b + 1;
            } else { // Response must be 3 (x > a or y > b). Since x=a, it must be y > b (mid_b > b).
                b_high = mid_b - 1;
            }
            continue;
        }
        if (b_low == b_high) { // b is known
            long long mid_a = a_low + (a_high - a_low) / 2;
            int response = ask(mid_a, b_low);
            if (response == 1) { // x < a (mid_a < a)
                a_low = mid_a + 1;
            } else { // Response must be 3 (x > a or y > b). Since y=b, it must be x > a (mid_a > a).
                a_high = mid_a - 1;
            }
            continue;
        }
        // If neither number is known, we query the midpoints of the current ranges.
        long long mid_a = a_low + (a_high - a_low) / 2;
        long long mid_b = b_low + (b_high - b_low) / 2;

        int response = ask(mid_a, mid_b);

        if (response == 1) { // x < a
            a_low = mid_a + 1;
        } else if (response == 2) { // y < b
            b_low = mid_b + 1;
        } else { // response == 3: x > a or y > b
            // This case is ambiguous. We don't know whether to shrink the range for 'a' or 'b'.
            // A plausible heuristic is to shrink the dimension with the larger search range.
            // This is not guaranteed to be correct in all cases, but it is a strong strategy
            // to prune the search space.
            if (a_high - a_low >= b_high - b_low) {
                a_high = mid_a - 1;
            } else {
                b_high = mid_b - 1;
            }
        }
    }
    return 0;
}

