DimrExe::~DimrExe (void) {
    if (this->done)
        return;
    // to do:  (void) FreeLibrary(handle);
    freeLib();
    this->log->Write (DEBUG, my_rank, "dimr shutting down normally");
#ifndef _WIN32
    free (this->exeName);
#else
    delete [] this->exeName;
#endif
    delete this->clock;
    free (this->exePath);
    delete this->log;
    delete [] this->mainArgs;
    delete [] this->library;
    this->done = true;
}
