    Lab lab2 = Lab::FromRgb(rgb);
    EXPECT_FLOAT_EQ(lab1.l(), lab2.l());
    EXPECT_FLOAT_EQ(lab1.a(), lab2.a());
    EXPECT_FLOAT_EQ(lab1.b(), lab2.b());
}
