    Rgb rgb2 = Rgb::FromLab(lab);
    EXPECT_FLOAT_EQ(rgb1.r(), rgb2.r());
    EXPECT_FLOAT_EQ(rgb1.g(), rgb2.g());
    EXPECT_FLOAT_EQ(rgb1.b(), rgb2.b());
}
