    EXPECT_NEAR(c.l(), 80.0f, 1e-6f);
    EXPECT_NEAR(c.a(), 5.0f, 1e-6f);
}
TEST(Color, LabLerp) {
    Lab a(0.0f, 0.0f, 0.0f);
    Lab b(100.0f, 50.0f, -50.0f);
    Lab mid = Lab::Lerp(a, b, 0.5f);
    EXPECT_NEAR(mid.l(), 50.0f, 1e-6f);
    EXPECT_NEAR(mid.a(), 25.0f, 1e-6f);
}
