}
TEST_CASE("tree_printing", "[trees][tree-printing]") {
	auto t = tree{{none, 1, 2, none},
	              {0, none, none, 1},
	              {0, 3, 4, none},
	              {2, none, none, 3},
	              {2, none, none, 4}};
	const auto names = name_map{"root", "foo", "", "bar", "baz"};
	std::ostringstream stream;
	stream << as_newick(t, names);
