    TAG_JOIN_LOCAL,
    TAG_JOIN_GLOBAL,
    TAG_FINAL,
    TAG_FINAL_ACK
    } MessageTag;
typedef struct {
    int         magic;          // sanity check
    MessageTag  tag;
    int         nodeID;         // ID of slave node
    int         numNodes;
    } MasterSlaveMessage;
typedef struct {
    int         magic;          // sanity check
    MessageTag  tag;
    int         numJoins;       // global number of joins
    struct {
        char        handle [Stream::MAXHANDLE]; // lead stream identity
        } join [DD::MAXJOINS];
    } JoinExchangeMessage;
