masterStreamError (
    char * reason
    ) {
    throw new Exception("MASTER Stream ERROR: %s", reason);
    }
static void
slaveStreamError (
    char * reason
    ) {
    throw new Exception("SLAVE Stream ERROR: %s", reason);
    }
