#include <iostream>
#include <vector>
#include <string>
#include <numeric>
#include <algorithm>
#include <random>
#include <iomanip>
// Use a fixed seed for deterministic behavior of the randomized algorithm
std::mt19937 rng(42);
void solve() {
    int n;
    int m;
    std::cin >> n >> m;
    // Weights for the multiplicative weights update algorithm
    std::vector<long double> weights(n, 1.0L);
    // Keep track of mistakes for each participant to handle the b=0 case
    std::vector<int> mistakes(n, 0);
    for (int k = 0; k < m; ++k) {
        std::string s;
        std::cin >> s;
        int my_guess;
        // Find the minimum number of mistakes any participant has made so far.
        int min_mistakes = *std::min_element(mistakes.begin(), mistakes.end());
        // Hybrid Strategy:
        // If there is at least one "perfect" expert (0 mistakes so far), follow them.
        // This guarantees we make 0 mistakes if the best participant makes 0 mistakes (b=0).
        if (min_mistakes == 0) {
            int first_perfect_idx = -1;
            for (int i = 0; i < n; ++i) {
                if (mistakes[i] == 0) {
                    first_perfect_idx = i;
                    break;
                }
            }
            my_guess = s[first_perfect_idx] - '0';
        } else {
            // Otherwise, use Randomized Weighted Majority.
            long double weight_for_0 = 0.0L;
            long double weight_for_1 = 0.0L;
            for (int i = 0; i < n; ++i) {
                if (s[i] == '0') {
                    weight_for_0 += weights[i];
                } else {
                    weight_for_1 += weights[i];
                }
            }
            long double total_weight = weight_for_0 + weight_for_1;

            // Handle the unlikely case where all weights decay to zero.
            if (total_weight == 0.0L) {
                my_guess = 0; // Default guess
            } else {
                long double prob_1 = weight_for_1 / total_weight;
                std::uniform_real_distribution<long double> dist(0.0L, 1.0L);
                if (dist(rng) < prob_1) {
                    my_guess = 1;
                } else {
                    my_guess = 0;
                }
            }
        }
        std::cout << my_guess << std::endl;
        int outcome;
        std::cin >> outcome;
        // Update mistakes and weights based on the actual outcome
        for (int i = 0; i < n; ++i) {
            if ((s[i] - '0') != outcome) {
                mistakes[i]++;
                // Penalize wrong experts by halving their weight.
                weights[i] *= 0.5L;
            }
        }
    }
}
int main() {
    // Fast I/O
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);
    solve();
    return 0;
}

#include "test/jemalloc_test.h"
#include "jemalloc/internal/fxp.h"
static double
fxp2double(fxp_t a) {
	double intpart = (double)(a >> 16);
	double fracpart = (double)(a & ((1U << 16) - 1)) / (1U << 16);
	return intpart + fracpart;
}
/* Is a close to b? */
static bool
double_close(double a, double b) {
	/*
	 * Our implementation doesn't try for precision.  Correspondingly, don't
	 * enforce it too strenuously here; accept values that are close in
	 * either relative or absolute terms.
	 */
	return fabs(a - b) < 0.01 || fabs(a - b) / a < 0.01;
}
static bool
fxp_close(fxp_t a, fxp_t b) {
	return double_close(fxp2double(a), fxp2double(b));
}
static fxp_t
xparse_fxp(const char *str) {
	fxp_t result;
	bool err = fxp_parse(&result, str, NULL);
	assert_false(err, "Invalid fxp string: %s", str);
	return result;
}
static void
expect_parse_accurate(const char *str, const char *parse_str) {
	double true_val = strtod(str, NULL);
	fxp_t fxp_val;
	char *end;
	bool err = fxp_parse(&fxp_val, parse_str, &end);
	expect_false(err, "Unexpected parse failure");
	expect_ptr_eq(parse_str + strlen(str), end,
	    "Didn't parse whole string");
	expect_true(double_close(fxp2double(fxp_val), true_val),
	    "Misparsed %s", str);
}
static void
parse_valid_trial(const char *str) {
	/* The value it parses should be correct. */
	expect_parse_accurate(str, str);
	char buf[100];
	snprintf(buf, sizeof(buf), "%swith_some_trailing_text", str);
	expect_parse_accurate(str, buf);
	snprintf(buf, sizeof(buf), "%s with a space", str);
	expect_parse_accurate(str, buf);
	snprintf(buf, sizeof(buf), "%s,in_a_malloc_conf_string:1", str);
	expect_parse_accurate(str, buf);
}
