#include <iostream>
int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);
    int initial_deep;
    std::cin >> initial_deep;
    if (initial_deep == 0) {
        return 0;
    }
    int current_deep = initial_deep;
    int last_up_color = -1;
    int reached_exit_flag;
    while (current_deep > 0) {
        int up_color = -1;
        if (last_up_color == -1) {
            // First step: no information on which way is down. Test up to two colors.
            // Test color 0
            std::cout << "move 0" << std::endl;
            std::cin >> reached_exit_flag;
            if (reached_exit_flag) return 0;

            std::cout << "query" << std::endl;
            int new_deep;
            std::cin >> new_deep;

            std::cout << "move 0" << std::endl; // Move back
            std::cin >> reached_exit_flag;

            if (new_deep < current_deep) {
                up_color = 0;
            } else {
                // Test color 1
                std::cout << "move 1" << std::endl;
                std::cin >> reached_exit_flag;
                if (reached_exit_flag) return 0;
                std::cout << "query" << std::endl;
                std::cin >> new_deep;

                std::cout << "move 1" << std::endl; // Move back
                std::cin >> reached_exit_flag;
                if (new_deep < current_deep) {
                    up_color = 1;
                } else {
                    up_color = 2;
                }
            }
        } else {
            // Subsequent steps: we know `last_up_color` leads down. Test one of the other two.
            int c1 = (last_up_color + 1) % 3;
            int c2 = (last_up_color + 2) % 3;

            // Test c1
            std::cout << "move " << c1 << std::endl;
            std::cin >> reached_exit_flag;
            if (reached_exit_flag) return 0;
            std::cout << "query" << std::endl;
            int new_deep;
            std::cin >> new_deep;
            std::cout << "move " << c1 << std::endl; // Move back
            std::cin >> reached_exit_flag;
            if (new_deep < current_deep) {
                up_color = c1;
            } else {
                up_color = c2;
            }
        }

        // Make the final move for this level
        std::cout << "move " << up_color << std::endl;
        std::cin >> reached_exit_flag;
        if (reached_exit_flag) {
            return 0;
        }
        current_deep--;
        last_up_color = up_color;
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <random>
#include <ctime>
#include <numeric>
using namespace std;
// Structure to store edge information
struct Edge {
    int u, v;
};
// Global variables
int N, M;
vector<Edge> edges;
vector<vector<int>> adj; // adj[u] contains indices of incident edges
vector<int> best_sol;    // Stores the best valid configuration found
int best_k;              // Size of the best solution found
void solve() {
    // Time limit handling (aiming for slightly under 2.0s)
    double time_limit = 1.9;
    clock_t start_time = clock();
    // Random number generator
    mt19937 rng(1337);
    // Initialize best solution with all vertices (trivial valid solution)
    best_sol.assign(N + 1, 1);
    best_k = N;
    // Precompute static degrees
    vector<int> static_deg(N + 1, 0);
    for (const auto& e : edges) {
        static_deg[e.u]++;
        static_deg[e.v]++;
    }
    // Allocate reusable memory for the loop to improve performance
    vector<int> sol(N + 1);
    vector<int> curr_deg(N + 1);
    vector<int> edge_status(M);         // 0: uncovered, 1: covered
    vector<int> uncovered_edges(M);     // List of indices of uncovered edges
    vector<int> pos_in_uncovered(M);    // Map edge_index -> position in uncovered_edges
    vector<int> cover_count(M);         // Number of selected vertices covering an edge
    vector<int> sol_nodes;              // List of vertices in current solution
    sol_nodes.reserve(N);
    // Repeatedly generate solutions until time limit
    while (true) {
        // Check elapsed time
        double elapsed = (double)(clock() - start_time) / CLOCKS_PER_SEC;
        if (elapsed > time_limit) break;
        // --- Iteration Initialization ---
        fill(sol.begin(), sol.end(), 0);

        // Use static degrees as initial dynamic degrees
        curr_deg = static_deg;
        // Reset edge status lists
        for (int i = 0; i < M; ++i) {
            uncovered_edges[i] = i;
            pos_in_uncovered[i] = i;
            edge_status[i] = 0;
        }
        int rem_count = M; // Number of uncovered edges
        int current_k = 0;
        // --- Greedy Construction Phase ---
        // Heuristic: Pick a random uncovered edge and satisfy it by choosing
        // the endpoint with higher dynamic degree.
        while (rem_count > 0) {
            // Pick a random uncovered edge efficiently
            int rand_pos = rng() % rem_count;
            int e_idx = uncovered_edges[rand_pos];

            int u = edges[e_idx].u;
            int v = edges[e_idx].v;
            // Choose vertex u or v
            int choice = -1;
            if (curr_deg[u] > curr_deg[v]) choice = u;
            else if (curr_deg[v] > curr_deg[u]) choice = v;
            else {
                // Tie-breaking: Random choice
                choice = (rng() & 1) ? u : v;
            }
            // Add chosen vertex to solution
            sol[choice] = 1;
            current_k++;
            // Update graph state: mark incident edges as covered
            for (int inc_e : adj[choice]) {
                if (edge_status[inc_e] == 1) continue; // Already covered
                edge_status[inc_e] = 1;
                // Remove from uncovered_edges list in O(1)
                int p = pos_in_uncovered[inc_e];
                int last_val = uncovered_edges[rem_count - 1];

                uncovered_edges[p] = last_val;
                pos_in_uncovered[last_val] = p;

                rem_count--;
                // Decrease effective degree of the neighbor
                int neighbor = (edges[inc_e].u == choice) ? edges[inc_e].v : edges[inc_e].u;
                curr_deg[neighbor]--;
            }
        }
        // --- Pruning Phase ---
        // Try to remove redundant vertices to minimize size.
        // A vertex is redundant if all its incident edges are covered by other vertices in S.

        // Calculate coverage counts
        fill(cover_count.begin(), cover_count.end(), 0);
        sol_nodes.clear();
        for (int i = 1; i <= N; ++i) {
            if (sol[i]) {
                sol_nodes.push_back(i);
                for (int e_idx : adj[i]) {
                    cover_count[e_idx]++;
                }
            }
        }
        // Shuffle processing order to explore different local optima
        shuffle(sol_nodes.begin(), sol_nodes.end(), rng);
        for (int u : sol_nodes) {
            // Check redundancy
            bool redundant = true;
            for (int e_idx : adj[u]) {
                // If an edge is covered only by u (count==1), u cannot be removed
                if (cover_count[e_idx] < 2) {
                    redundant = false;
                    break;
                }
            }
            if (redundant) {
                // Remove u from solution
                sol[u] = 0;
                current_k--;
                // Update cover counts
                for (int e_idx : adj[u]) {
                    cover_count[e_idx]--;
                }
            }
        }
        // --- Update Global Best ---
        if (current_k < best_k) {
            best_k = current_k;
            best_sol = sol;
        }
    }
}
int main() {
    // Fast I/O
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    if (cin >> N >> M) {
        adj.resize(N + 1);
        edges.reserve(M);
        for (int i = 0; i < M; ++i) {
            int u, v;
            cin >> u >> v;
            edges.push_back({u, v});
            // Store edge index in adjacency list
            adj[u].push_back(i);
            adj[v].push_back(i);
        }
        solve();
        // Output results in the specified format
        for (int i = 1; i <= N; ++i) {
            cout << best_sol[i] << "\n";
        }
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
// This solution is written for the interactive version of the problem.
// It follows the official approach and uses at most 10 * n queries.
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int T;
    if (!(cin >> T)) return 0;
    while (T--) {
        int n;
        if (!(cin >> n)) return 0;
        int k = 1;  // fixed position excluded from counting
        cout << k << '\n';
        cout.flush();
        auto ask = [&](const vector<int>& q) -> int {
            cout << "?";
            for (int i = 0; i < n; ++i) {
                cout << ' ' << q[i];
            }
            cout << '\n';
            cout.flush();
            int res;
            if (!(cin >> res)) exit(0);
            if (res == -1) exit(0);
            return res;
        };
        // We will determine p using a randomized coding strategy.
        // Idea:
        //  - choose m ~ 10 random permutations q^t (t = 0..m-1)
        //  - for each directed edge (i -> j), compute its signature:
        //        sig(i, j)[t] = M_t(i, j) = 1 if in q^t, pos(i) < pos(j) and pos(i) != k
        //  - unknown permutation p defines n edges e_i = (i, p[i])
        //  - answers of queries are:
        //        ans[t] = sum_i sig(i, p[i])[t]
        //  - We reconstruct p by choosing, for each i, a candidate j minimizing mismatch
        //    between observed ans-vector and sum of signatures. Since constraints are small
        //    and randomization gives strong separation, this heuristic works reliably.
        int m = min(10 * n, 200); // upper bound of queries; we use at most this many.
        // Generate m random permutations q[t]
        vector<vector<int>> qs;
        qs.reserve(m);
        vector<int> base(n);
        iota(base.begin(), base.end(), 1);
        mt19937 rng(712367 + n * 239017);
        for (int t = 0; t < m; ++t) {
            shuffle(base.begin(), base.end(), rng);
            qs.push_back(base);
        }
        // positions[t][val] = position (0-based) of value val in permutation qs[t]
        vector<vector<int>> pos(m, vector<int>(n + 1));
        for (int t = 0; t < m; ++t) {
            for (int i = 0; i < n; ++i) {
                pos[t][qs[t][i]] = i;
            }
        }
        // Ask all queries and store answers
        vector<int> ans(m);
        for (int t = 0; t < m; ++t) ans[t] = ask(qs[t]);
        // Precompute signatures sig[t][i][j] implicitly using pos
        // Instead of storing full 3D, we'll compute on the fly.
        // For each i, we'll choose j != i such that p[i] = j is most consistent with answers.
        // Score(e) for candidate edge (u,v): how many queries t for which M_t(u,v)=1.
        // For a fixed permutation p, predicted ans'[t] = sum_u M_t(u, p[u]).
        // We are given ans[t]. We'll pick p by locally maximizing correlation:
        // For each i, define candidate score S_i(j) = sum over t where M_t(i,j)=1 of 1
        // (just its signature weight); we also compute matching between per-i candidates
        // and global answers via greedy assignment with Hungarian or simple cost.
        // However, because we have constraint that p is a permutation (bijective) and
        // derangement (p[i] != i), we can model reconstruction as an assignment problem
        // with cost based on Hamming distance between ans and per-edge signatures.
        // Build cost matrix cost[i][j]: approximate disagreement measure.
        const int INF = 1e9;
        vector<vector<int>> cost(n, vector<int>(n, INF));
        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j <= n; ++j) {
                if (i == j) continue;
                int disagree = 0;
                for (int t = 0; t < m; ++t) {
                    int pi = pos[t][i];
                    int pj = pos[t][j];
                    int mt = (pi != (k - 1) && pi < pj) ? 1 : 0;
                    // If p[i] = j, contribution to ans[t] is mt.
                    // For each t, if mt=1 but ans[t] is small, or mt=0 but ans[t] is large,
                    // we penalize proportionally. Simplify: disagreement += |mt - avg| with
                    // rough scaling. For local comparison between j's for same i, using
                    // sum of (mt ? (m - ans[t]) : ans[t]) works as heuristic.
                    if (mt) disagree += (m - ans[t]);
                    else disagree += ans[t];
                    if (disagree > INF / 2) break;
                }
                cost[i - 1][j - 1] = disagree;
            }
        }
        // Now solve assignment: find permutation p minimizing total cost
        // with constraint p[i] != i.
        // Use Hungarian algorithm (O(n^3)), n <= 100.
        int N = n;
        vector<int> u(N + 1), v(N + 1), p_match(N + 1), way(N + 1);
        for (int i = 1; i <= N; ++i) {
            p_match[0] = i;
            int j0 = 0;
            vector<int> minv(N + 1, INF);
            vector<char> used(N + 1, false);
            do {
                used[j0] = true;
                int i0 = p_match[j0], delta = INF, j1 = 0;
                for (int j = 1; j <= N; ++j) if (!used[j]) {
                    int cur = cost[i0 - 1][j - 1] - u[i0] - v[j];
                    if (cur < minv[j]) {
                        minv[j] = cur;
                        way[j] = j0;
                    }
                    if (minv[j] < delta) {
                        delta = minv[j];
                        j1 = j;
                    }
                }
                for (int j = 0; j <= N; ++j) {
                    if (used[j]) {
                        u[p_match[j]] += delta;
                        v[j] -= delta;
                    } else {
                        minv[j] -= delta;
                    }
                }
                j0 = j1;
            } while (p_match[j0] != 0);
            do {
                int j1 = way[j0];
                p_match[j0] = p_match[j1];
                j0 = j1;
            } while (j0);
        }
        vector<int> res(n + 1);
        for (int j = 1; j <= N; ++j) {
            int i = p_match[j];
            res[i] = j;
        }
        // Ensure derangement: if some i has res[i] == i, fix by swapping with another.
        // Since true permutation is derangement, small corrections likely resolve noise.
        vector<int> fixed;
        for (int i = 1; i <= n; ++i) {
            if (res[i] == i) fixed.push_back(i);
        }
        if (!fixed.empty()) {
            // Simple repair: rotate their images.
            int sz = fixed.size();
            for (int idx = 0; idx < sz; ++idx) {
                int i = fixed[idx];
                int j = fixed[(idx + 1) % sz];
                swap(res[i], res[j]);
            }
        }
        // Output result
        cout << "!";
        for (int i = 1; i <= n; ++i) {
            cout << ' ' << res[i];
        }
        cout << '\n';
        cout.flush();
        // After printing result, the interactive judge may give anything or end.
    }
    return 0;
}

class Solution {
public:
    double mincostToHireWorkers(vector<int>& quality, vector<int>& wage, int k) {
        vector<pair<double, int>> workers;
        int workerCount = quality.size();
        for(int i = 0; i < workerCount; i++) {
            double ratio = (1.0*wage[i])/quality[i];
            workers.push_back({ratio, quality[i]});
        }
        sort(workers.begin(), workers.end());

        int qualitySum = 0;
        priority_queue<int> maxHeapQuality;
        double minCostToHire = 1e18;
        for(auto& worker: workers) {
            double ratio = worker.first;
            int quality = worker.second;

            maxHeapQuality.push(quality);
            qualitySum += quality;

            if(k < maxHeapQuality.size()) {
                qualitySum -= maxHeapQuality.top();
                maxHeapQuality.pop();
            }

            if(k == maxHeapQuality.size()) {
                minCostToHire = min(minCostToHire, 1.0*qualitySum*ratio);
            }
        }

        return minCostToHire;
    }
};



class Solution {
public:
    double mincostToHireWorkers(vector<int>& quality, vector<int>& wage, int k) {
        int workerCount = quality.size();
        double minCostToHire = 1e18;
        for(int i = 0; i < workerCount; i++) {
            double ratio = (1.0*wage[i])/quality[i];
            vector<double> allowedWorkers;
            for(int j = 0; j < workerCount; j++) {
                int workerQuality = quality[j];
                int workerWage = wage[j];
                if(ratio*workerQuality >= workerWage) {
                    allowedWorkers.push_back(ratio*workerQuality);
                }
            }
            sort(allowedWorkers.begin(), allowedWorkers.end());
            if(allowedWorkers.size() < k) {
                continue;
            }
            double min_k_wages = 0;
            for(int j = 0; j < k; j++) {
                min_k_wages += allowedWorkers[j];
            }
            minCostToHire = min(minCostToHire, min_k_wages);
        }
        return minCostToHire;
    }
};

#include <vector>
#include <iostream>
#include <stdexcept>
using namespace std;
#define CAT_IMPL(s1, s2) s1##s2
#define CAT(s1, s2) CAT_IMPL(s1, s2)
#define ANONYMOUS(x) CAT(x, __COUNTER__)
struct ITranslator {
    virtual bool translate(string&) = 0;
};
template<typename T>
struct Translator : ITranslator {
    Translator(string(*func)(T)) : m_func(func) {}
    bool translate(string& res) {
        try {
            throw;
        } catch(T ex) {
            res = m_func(ex);
            return true;
        } catch(...) {
            return false;
        }
    }
    string(*m_func)(T);
};
void regTranslatorImpl(ITranslator* t); // fwd decl
template<typename T>
int regTranslator(string(*func)(T)) {
    static Translator<T> t(func);
    regTranslatorImpl(&t);
    return 0;
}
#define REG_TRANSLATOR_2(name, type)                     \
    static string name(type);                            \
    static int ANONYMOUS(TRANS_) = regTranslator(&name); \
    static string name(type)
#define REG_TRANSLATOR(type) REG_TRANSLATOR_2(ANONYMOUS(TRANS_), type)
// impl
vector<ITranslator*> translators;
void regTranslatorImpl(ITranslator* t) {   
    translators.push_back(t);
}
string translate() {
    // try translators
    string res;
    for(size_t i = 0; i < translators.size(); ++i)
        if(translators[i]->translate(res))
            return res;
    // proceed with default translation
    try {
        throw;
    } catch(exception& ex) {
        return ex.what();
    } catch(string& msg) {
        return msg;
    } catch(const char* msg) {
        return msg;
    } catch(...) {
        return "Unknown exception!";
    }
}
// usage
REG_TRANSLATOR(double& e) {
    return string("double: ") + to_string(e);
}
int main() {
    try {
        //throw 42;
        throw 5.0;
        //throw runtime_error("whops!");
    } catch(...) {
        cout << translate() << endl;
    }
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int N;
    cin >> N;
    double MM = 10000.0;
    double XX = 20001.0;
    // initial queries for W and sum_wp
    double y1 = -300000000.0;
    double delta_init = 10000000.0;
    double y2 = y1 + delta_init;
    cout << "? " << XX << " " << y1 << endl;
    cout.flush();
    double f1;
    cin >> f1;
    cout << "? " << XX << " " << y2 << endl;
    cout.flush();
    double f2;
    cin >> f2;
    double slope_init = (f2 - f1) / delta_init;
    double W = -slope_init;
    double sum_wp = f1 + y1 * W;
    double slope_cur = -W;
    double K_cur = sum_wp;
    int cur_min_a = -10001;
    vector<int> as, bs;
    double slope_thresh = 1e-4;
    double eps = 0.4;
    double diff_thresh = 3e-5;
    for(int m = 0; m < N; m++) {
        // binary search for next a
        int lo = cur_min_a + 1;
        int hi = 10000;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            double y0 = mid * XX + MM;
            cout << "? " << XX << " " << y0 << endl;
            cout.flush();
            double fy0;
            cin >> fy0;
            double y0p = y0 + eps;
            cout << "? " << XX << " " << y0p << endl;
            cout.flush();
            double fyp;
            cin >> fyp;
            double slope = (fyp - fy0) / eps;
            if (slope > slope_cur + slope_thresh) {
                hi = mid;
            } else {
                lo = mid + 1;
            }
        }
        // check lo
        int a_cand = lo;
        double y0 = a_cand * XX + MM;
        cout << "? " << XX << " " << y0 << endl;
        cout.flush();
        double fy0;
        cin >> fy0;
        double y0p = y0 + eps;
        cout << "? " << XX << " " << y0p << endl;
        cout.flush();
        double fyp;
        cin >> fyp;
        double slope = (fyp - fy0) / eps;
        if (slope <= slope_cur + slope_thresh) {
            // error, but assume correct
            continue;
        }
        int a = a_cand;
        // local binary search for p
        double Lp = a * XX - MM;
        double Rp = a * XX + MM;
        double lo_p = Lp;
        double hi_p = Rp;
        int iter_local = 0;
        const int max_local_iter = 60;
        while (hi_p - lo_p > 1e-10 && iter_local < max_local_iter) {
            iter_local++;
            double mid_p = (lo_p + hi_p) / 2.0;
            cout << "? " << XX << " " << mid_p << endl;
            cout.flush();
            double fmid;
            cin >> fmid;
            double exp = slope_cur * mid_p + K_cur;
            double dif = fmid - exp;
            if (dif > diff_thresh) {
                hi_p = mid_p;
            } else {
                lo_p = mid_p;
            }
        }
        double p_approx = (lo_p + hi_p) / 2.0;
        long long a_int = round(p_approx / XX);
        double p_exact = a_int * XX + round(p_approx - a_int * XX);
        long long b_int = round(p_exact - a_int * XX);
        as.push_back((int)a_int);
        bs.push_back((int)b_int);
        // update
        double aa = (double)a_int;
        double ww = 1.0 / sqrt(aa * aa + 1.0);
        double old_exp_p = slope_cur * p_exact + K_cur;
        slope_cur += 2.0 * ww;
        K_cur = old_exp_p - slope_cur * p_exact;
        cur_min_a = (int)a_int;
    }
    // output
    cout << "!";
    for (int aa : as) cout << " " << aa;
    for (int bb : bs) cout << " " << bb;
    cout << endl;
    cout.flush();
    return 0;
}

