#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int b, w, x, y;
    if (!(cin >> b >> w >> x >> y)) return 0;
    // Special case: 1D optimal if |b-w| <= 1
    if (abs(b - w) <= 1) {
        int r = 1, c = b + w;
        cout << r << " " << c << "\n";
        bool startBlack = (b >= w);
        int cb = 0, cw = 0;
        for (int i = 0; i < c; ++i) {
            bool putBlack = ( (i % 2 == 0) ? startBlack : !startBlack );
            if (putBlack) {
                if (cb < b) {
                    cout << '@';
                    cb++;
                } else {
                    cout << '.';
                    cw++;
                }
            } else {
                if (cw < w) {
                    cout << '.';
                    cw++;
                } else {
                    cout << '@';
                    cb++;
                }
            }
        }
        cout << "\n";
        return 0;
    }
    // General construction with 5 rows:
    // Upper 2 rows: white base with b black islands on row 0 at even columns.
    // Row 2: black separator (with one white cell to connect a white island).
    // Lower 2 rows: black base with w white islands on row 3 at even columns.
    int W = max(2*b - 1, 2*w - 1);
    int R = 5;
    vector<string> g(R, string(W, '@'));
    // Initialize:
    // Rows 0-1 white
    for (int c = 0; c < W; ++c) g[0][c] = g[1][c] = '.';
    // Row 2 black by default (already '@')
    // Rows 3-4 black by default (already '@')
    // Place black islands in upper section (row 0 at even columns)
    for (int i = 0; i < b; ++i) {
        int col = 2*i;
        g[0][col] = '@';
        // ensure separator columns (odd) in upper remain white
        if (col + 1 < W) {
            g[0][col+1] = '.';
            g[1][col+1] = '.';
        }
    }
    // Place white islands in lower section (row 3 at even columns)
    for (int i = 0; i < w; ++i) {
        int col = 2*i;
        g[3][col] = '.';
        // separators odd columns remain black (already '@')
    }
    // Connect one black island to black base: set row 1 at a black island column to '@'
    int k1;
    if (b == 1) {
        // Use column 0 (only island) for black connection
        k1 = 0;
    } else {
        // rightmost black island column
        k1 = 2*(b-1);
    }
    g[1][k1] = '@';
    // Connect one white island to upper white base through row 2 white cell at a (different) island column
    int k2;
    if (b == 1) {
        // Ensure different column from k1=0; need w>=2 (since |b-w|>1 implies w>=3 actually when b=1)
        k2 = (w >= 2 ? 2 : 0);
    } else {
        // choose the leftmost white island at column 0
        k2 = 0;
        if (k2 == k1) {
            // if by chance equal (when k1==0), shift to next available white island column if exists
            if (w >= 2) k2 = 2;
            else {
                // fallback: increase width to allow separate column (rare, e.g., b>1,w=1 and k1==0)
                // Expand grid by 2 columns to the right
                int oldW = W;
                W += 2;
                for (int r = 0; r < R; ++r) g[r].resize(W, '@');
                g[0].replace(oldW, 2, "..");
                g[1].replace(oldW, 2, "..");
                // row2 '@@' already
                // rows3-4 '@@' already
                k2 = oldW; // new even column
                g[3][k2] = '.';
            }
        }
    }
    // Ensure k2 within bounds and corresponds to a white island column
    if (k2 >= W) {
        // Shouldn't happen due to above handling, but guard
        k2 = (w >= 1 ? 2*(w-1) : 0);
        if (k2 >= W) k2 = 0;
    }
    // Make separator at k2 white to connect that white island to upper white base
    g[2][k2] = '.';
    // Output
    cout << R << " " << W << "\n";
    for (int r = 0; r < R; ++r) {
        cout << g[r] << "\n";
    }
    return 0;
}

#include "benchmark/benchmark.h"
#include "spdlog/spdlog.h"
#include "spdlog/pattern_formatter.h"
void bench_formatter(benchmark::State &state, std::string pattern) {
    auto formatter = spdlog::details::make_unique<spdlog::pattern_formatter>(pattern);
    spdlog::memory_buf_t dest;
    std::string logger_name = "logger-name";
    const char *text =
        "Hello. This is some message with length of 80                                   ";
    spdlog::source_loc source_loc{"a/b/c/d/myfile.cpp", 123, "some_func()"};
    spdlog::details::log_msg msg(source_loc, logger_name, spdlog::level::info, text);
    for (auto _ : state) {
        dest.clear();
        formatter->format(msg, dest);
        benchmark::DoNotOptimize(dest);
    }
}
void bench_formatters() {
    // basic patterns(single flag)
    std::string all_flags = "+vtPnlLaAbBcCYDmdHIMSefFprRTXzEisg@luioO%";
    std::vector<std::string> basic_patterns;
    for (auto &flag : all_flags) {
        auto pattern = std::string("%") + flag;
        benchmark::RegisterBenchmark(pattern.c_str(), &bench_formatter, pattern);
        //        pattern = std::string("%16") + flag;
        //        benchmark::RegisterBenchmark(pattern.c_str(), &bench_formatter, pattern);
        //
        //        // bench center padding
        //        pattern = std::string("%=16") + flag;
        //        benchmark::RegisterBenchmark(pattern.c_str(), &bench_formatter, pattern);
    }
    // complex patterns
    std::vector<std::string> patterns = {
        "[%D %X] [%l] [%n] %v",
        "[%Y-%m-%d %H:%M:%S.%e] [%l] [%n] %v",
        "[%Y-%m-%d %H:%M:%S.%e] [%l] [%n] [%t] %v",
    };
    for (auto &pattern : patterns) {
        benchmark::RegisterBenchmark(pattern.c_str(), &bench_formatter, pattern)
            ->Iterations(2500000);
    }
}
int main(int argc, char *argv[]) {
    spdlog::set_pattern("[%^%l%$] %v");
    if (argc != 2) {
        spdlog::error("Usage: {} <pattern> (or \"all\" to bench all)", argv[0]);
        exit(1);
    }
    std::string pattern = argv[1];
    if (pattern == "all") {
        bench_formatters();
    } else {
        benchmark::RegisterBenchmark(pattern.c_str(), &bench_formatter, pattern);
    }
    benchmark::Initialize(&argc, argv);
    benchmark::RunSpecifiedBenchmarks();
}

#include "llvm/ADT/Statistic.h"
#include "llvm/CodeGen/LivePhysRegs.h"
#include "llvm/CodeGen/MachineFrameInfo.h"
#include "llvm/CodeGen/MachineFunction.h"
#include "llvm/CodeGen/MachineFunctionPass.h"
#include "llvm/CodeGen/TargetSubtargetInfo.h"
#include "llvm/InitializePasses.h"
#include "llvm/Pass.h"
#include "llvm/Support/CommandLine.h"
#include "llvm/Support/Debug.h"
#include "llvm/Support/raw_ostream.h"
using namespace llvm;
#define DEBUG_TYPE "stackmaps"
static cl::opt<bool> EnablePatchPointLiveness(
    "enable-patchpoint-liveness", cl::Hidden, cl::init(true),
    cl::desc("Enable PatchPoint Liveness Analysis Pass"));
STATISTIC(NumStackMapFuncVisited, "Number of functions visited");
STATISTIC(NumStackMapFuncSkipped, "Number of functions skipped");
STATISTIC(NumBBsVisited,          "Number of basic blocks visited");
STATISTIC(NumBBsHaveNoStackmap,   "Number of basic blocks with no stackmap");
STATISTIC(NumStackMaps,           "Number of StackMaps visited");
namespace {
/// This pass calculates the liveness information for each basic block in
/// a function and attaches the register live-out information to a patchpoint
/// intrinsic if present.
///
/// This pass can be disabled via the -enable-patchpoint-liveness=false flag.
/// The pass skips functions that don't have any patchpoint intrinsics. The
/// information provided by this pass is optional and not required by the
/// aformentioned intrinsic to function.
class StackMapLiveness : public MachineFunctionPass {
  const TargetRegisterInfo *TRI = nullptr;
  LivePhysRegs LiveRegs;
public:
  static char ID;
  /// Default construct and initialize the pass.
  StackMapLiveness();
  /// Tell the pass manager which passes we depend on and what
  /// information we preserve.
  void getAnalysisUsage(AnalysisUsage &AU) const override;
  MachineFunctionProperties getRequiredProperties() const override {
    return MachineFunctionProperties().set(
        MachineFunctionProperties::Property::NoVRegs);
  }
  /// Calculate the liveness information for the given machine function.
  bool runOnMachineFunction(MachineFunction &MF) override;
private:
  /// Performs the actual liveness calculation for the function.
  bool calculateLiveness(MachineFunction &MF);
  /// Add the current register live set to the instruction.
  void addLiveOutSetToMI(MachineFunction &MF, MachineInstr &MI);
  /// Create a register mask and initialize it with the registers from
  /// the register live set.
  uint32_t *createRegisterMask(MachineFunction &MF) const;
};
} // namespace
char StackMapLiveness::ID = 0;
char &llvm::StackMapLivenessID = StackMapLiveness::ID;
INITIALIZE_PASS(StackMapLiveness, "stackmap-liveness",
                "StackMap Liveness Analysis", false, false)
/// Default construct and initialize the pass.
StackMapLiveness::StackMapLiveness() : MachineFunctionPass(ID) {
  initializeStackMapLivenessPass(*PassRegistry::getPassRegistry());
}
/// Tell the pass manager which passes we depend on and what information we
/// preserve.
void StackMapLiveness::getAnalysisUsage(AnalysisUsage &AU) const {
  // We preserve all information.
  AU.setPreservesAll();
  AU.setPreservesCFG();
  MachineFunctionPass::getAnalysisUsage(AU);
}
/// Calculate the liveness information for the given machine function.
bool StackMapLiveness::runOnMachineFunction(MachineFunction &MF) {
  if (!EnablePatchPointLiveness)
    return false;
  LLVM_DEBUG(dbgs() << "********** COMPUTING STACKMAP LIVENESS: "
                    << MF.getName() << " **********\n");
  TRI = MF.getSubtarget().getRegisterInfo();
  ++NumStackMapFuncVisited;
  // Skip this function if there are no patchpoints to process.
  if (!MF.getFrameInfo().hasPatchPoint()) {
    ++NumStackMapFuncSkipped;
    return false;
  }
  return calculateLiveness(MF);
}
/// Performs the actual liveness calculation for the function.
bool StackMapLiveness::calculateLiveness(MachineFunction &MF) {
  bool HasChanged = false;
  // For all basic blocks in the function.
  for (auto &MBB : MF) {
    LLVM_DEBUG(dbgs() << "****** BB " << MBB.getName() << " ******\n");
    LiveRegs.init(*TRI);
    // FIXME: This should probably be addLiveOuts().
    LiveRegs.addLiveOutsNoPristines(MBB);
    bool HasStackMap = false;
    // Reverse iterate over all instructions and add the current live register
    // set to an instruction if we encounter a patchpoint instruction.
    for (MachineInstr &MI : llvm::reverse(MBB)) {
      if (MI.getOpcode() == TargetOpcode::PATCHPOINT) {
        addLiveOutSetToMI(MF, MI);
        HasChanged = true;
        HasStackMap = true;
        ++NumStackMaps;
      }
      LLVM_DEBUG(dbgs() << "   " << LiveRegs << "   " << MI);
      LiveRegs.stepBackward(MI);
    }
    ++NumBBsVisited;
    if (!HasStackMap)
      ++NumBBsHaveNoStackmap;
  }
  return HasChanged;
}
/// Add the current register live set to the instruction.
void StackMapLiveness::addLiveOutSetToMI(MachineFunction &MF,
                                         MachineInstr &MI) {
  uint32_t *Mask = createRegisterMask(MF);
  MachineOperand MO = MachineOperand::CreateRegLiveOut(Mask);
  MI.addOperand(MF, MO);
}
/// Create a register mask and initialize it with the registers from the
/// register live set.
uint32_t *StackMapLiveness::createRegisterMask(MachineFunction &MF) const {
  // The mask is owned and cleaned up by the Machine Function.
  uint32_t *Mask = MF.allocateRegMask();
  for (auto Reg : LiveRegs)
    Mask[Reg / 32] |= 1U << (Reg % 32);
  // Give the target a chance to adjust the mask.
  TRI->adjustStackMapLiveOutMask(Mask);
  return Mask;
}

