void XmlBtPolarWriter::writeXMLBtPolar(BoatPolar *pBtPolar)
{
    if(!pBtPolar) return;
    setAutoFormatting(true);
    writeStartDocument();
    {
        writeDTD("<!DOCTYPE flow5>");
        writeStartElement("XflBoatPolar");
        {
            writeAttribute("version", "1.0");
            writeUnits();
            writeBtPolarData(pBtPolar);
        }
        writeEndElement();
    }
    writeEndDocument();
