  int testSum {0};
  for (int* elem: makeRange(SmartPtrIteratorAdapter(data.begin()), SmartPtrIteratorAdapter(data.end())))
  {
    testSum += *elem;
  }
  // then
  EXPECT_EQ(testSum, std::accumulate(initData.begin(), initData.end(), 0));
}
