//-----------------------------------------------------------------------------
void tglDrawCircle(const TPointD &center, double radius) {
  if (radius <= 0) return;
  double pixelSize = sqrt( tglGetPixelSize2() );
  int slices = std::max(3, computeSlices(radius, pixelSize));
  double step = M_2PI / (double)slices;
  double c = cos(step), s = sin(step);
  glPushMatrix();
  glTranslated(center.x, center.y, 0.0);
  glBegin(GL_LINE_STRIP);
  double x = radius, y = 0.0;
  glVertex2d(x, y);
  for(int i = slices - 1; i; --i) {
    double xx = x;
    x = c*xx - s*y;
    y = s*xx + c*y;
    glVertex2d(x, y);
  }
  glVertex2d(radius, 0.0);
  glEnd();
  glPopMatrix();
}
//-----------------------------------------------------------------------------
void tglDrawDisk(const TPointD &c, double r) {
  if (r <= 0) return;
  double pixelSize = 1;
  int slices       = 60;
  if (slices <= 0) slices = computeSlices(r, pixelSize) >> 1;
  glPushMatrix();
  glTranslated(c.x, c.y, 0.0);
  GLUquadric *quadric = gluNewQuadric();
  gluDisk(quadric, 0, r, slices, 1);
  gluDeleteQuadric(quadric);
  glPopMatrix();
}
