#include <iostream>
#include <vector>
#include <numeric>
#include <algorithm>
// Calculates the change in the sum of squared differences for an operation (i, j)
long long calculate_delta_s2(long long Ai, long long Bi, long long Aj, long long Bj) {
    long long di = Ai - Bi;
    long long dj = Aj - Bj;
    long long Ai_new = Aj - 1;
    long long Aj_new = Ai + 1;
    long long di_new = Ai_new - Bi;
    long long dj_new = Aj_new - Bj;
    return di_new * di_new + dj_new * dj_new - di * di - dj * dj;
}
int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);
    int n;
    std::cin >> n;
    std::vector<long long> a(n), b(n);
    long long sum_a = 0, sum_b = 0;
    for (int i = 0; i < n; ++i) {
        std::cin >> a[i];
        sum_a += a[i];
    }
    for (int i = 0; i < n; ++i) {
        std::cin >> b[i];
        sum_b += b[i];
    }
    if (sum_a != sum_b) {
        std::cout << "No" << std::endl;
        return 0;
    }
    std::vector<std::pair<int, int>> ops;

    // Safety break; based on constraints and problem type, this limit should be sufficient.
    for (int k = 0; k < 40000; ++k) {
        bool done = true;
        for (int i = 0; i < n; ++i) {
            if (a[i] != b[i]) {
                done = false;
                break;
            }
        }
        if (done) {
            break;
        }
        long long best_delta = 0;
        int best_i = -1, best_j = -1;
        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                long long delta = calculate_delta_s2(a[i], b[i], a[j], b[j]);
                if (delta < best_delta) {
                    best_delta = delta;
                    best_i = i;
                    best_j = j;
                }
            }
        }

        if (best_i != -1) {
            ops.push_back({best_i + 1, best_j + 1});
            long long temp_ai = a[best_i];
            long long temp_aj = a[best_j];
            a[best_i] = temp_aj - 1;
            a[best_j] = temp_ai + 1;
        } else {
            // If A != B, there must be a way to decrease sum of squares.
            // If we are in a local minimum where all deltas are non-negative,
            // this strategy fails. However, for this problem, it's likely
            // always possible to find a negative delta unless A=B.
            break; 
        }
    }
    bool possible = true;
    for (int i = 0; i < n; ++i) {
        if (a[i] != b[i]) {
            possible = false;
            break;
        }
    }
    if (possible) {
        std::cout << "Yes" << std::endl;
        std::cout << ops.size() << std::endl;
        for (const auto& p : ops) {
            std::cout << p.first << " " << p.second << std::endl;
        }
    } else {
        std::cout << "No" << std::endl;
    }
    return 0;
}

#define UCLN_TYPE_IS_COMMON
#include "ucln_imp.h"
static cleanupFunc *gCommonCleanupFunctions[UCLN_COMMON_COUNT];
static cleanupFunc *gLibCleanupFunctions[UCLN_COMMON];
/************************************************
 The cleanup order is important in this function.
 Please be sure that you have read ucln.h
 ************************************************/
U_CAPI void U_EXPORT2
u_cleanup()
{
    UTRACE_ENTRY_OC(UTRACE_U_CLEANUP);
    icu::umtx_lock(nullptr);     /* Force a memory barrier, so that we are sure to see   */
    icu::umtx_unlock(nullptr);   /*   all state left around by any other threads.        */
    ucln_lib_cleanup();
    cmemory_cleanup();       /* undo any heap functions set by u_setMemoryFunctions(). */
    UTRACE_EXIT();           /* Must be before utrace_cleanup(), which turns off tracing. */
/*#if U_ENABLE_TRACING*/
    utrace_cleanup();
/*#endif*/
}
U_CAPI void U_EXPORT2 ucln_cleanupOne(ECleanupLibraryType libType) 
{
    if (gLibCleanupFunctions[libType])
    {
        gLibCleanupFunctions[libType]();
        gLibCleanupFunctions[libType] = nullptr;
    }
}
U_CFUNC void
ucln_common_registerCleanup(ECleanupCommonType type,
                            cleanupFunc *func)
{
    // Thread safety messiness: From ticket 10295, calls to registerCleanup() may occur
    // concurrently. Although such cases should be storing the same value, they raise errors
    // from the thread sanity checker. Doing the store within a mutex avoids those.
    // BUT that can trigger a recursive entry into std::call_once() in umutex.cpp when this code,
    // running from the call_once function, tries to grab the ICU global mutex, which
    // re-enters the mutex init path. So, work-around by special casing UCLN_COMMON_MUTEX, not
    // using the ICU global mutex for it.
    //
    // No other point in ICU uses std::call_once().
    U_ASSERT(UCLN_COMMON_START < type && type < UCLN_COMMON_COUNT);
    if (type == UCLN_COMMON_MUTEX) {
        gCommonCleanupFunctions[type] = func;
    } else if (UCLN_COMMON_START < type && type < UCLN_COMMON_COUNT)  {
        icu::Mutex m;     // See ticket 10295 for discussion.
        gCommonCleanupFunctions[type] = func;
    }
#if !UCLN_NO_AUTO_CLEANUP && (defined(UCLN_AUTO_ATEXIT) || defined(UCLN_AUTO_LOCAL))
    ucln_registerAutomaticCleanup();
#endif
}
// Note: ucln_registerCleanup() is called with the ICU global mutex locked.
//       Be aware if adding anything to the function.
//       See ticket 10295 for discussion.
U_CAPI void U_EXPORT2
ucln_registerCleanup(ECleanupLibraryType type,
                     cleanupFunc *func)
{
    U_ASSERT(UCLN_START < type && type < UCLN_COMMON);
    if (UCLN_START < type && type < UCLN_COMMON)
    {
        gLibCleanupFunctions[type] = func;
    }
}
U_CFUNC UBool ucln_lib_cleanup() {
    int32_t libType = UCLN_START;
    int32_t commonFunc = UCLN_COMMON_START;
    for (libType++; libType<UCLN_COMMON; libType++) {
        ucln_cleanupOne(static_cast<ECleanupLibraryType>(libType));
    }
    for (commonFunc++; commonFunc<UCLN_COMMON_COUNT; commonFunc++) {
        if (gCommonCleanupFunctions[commonFunc])
        {
            gCommonCleanupFunctions[commonFunc]();
            gCommonCleanupFunctions[commonFunc] = nullptr;
        }
    }
#if !UCLN_NO_AUTO_CLEANUP && (defined(UCLN_AUTO_ATEXIT) || defined(UCLN_AUTO_LOCAL))
    ucln_unRegisterAutomaticCleanup();
#endif
    return true;
}

