    Level*                  level,
    int                     x,
    int                     y,
    int                     z,
    std::shared_ptr<Player> player,
    int                     clickedFace,
    float                   clickX,
    float                   clickY,
    float                   clickZ,
    bool                    soundOnly
) {
    if (level->isClientSide) {
        return true;
    }
    player->startRepairing(x, y, z);
    return true;
}
