    LevelSource*                level,
    int                         x,
    int                         y,
    int                         z,
    int                         forceData,
    std::shared_ptr<TileEntity> forceEntity
) {
    int dir = level->getData(x, y, z) & 3;
    if (dir == Direction::EAST || dir == Direction::WEST) {
        setShape(0, 0, 2 / 16.0f, 1, 1, 1 - 2 / 16.0f);
    } else {
        setShape(2 / 16.0f, 0, 0, 1 - 2 / 16.0f, 1, 1);
    }
