HRESULT CScene_FullscreenProgress::OnTimer( XUIMessageTimer *pTimer, BOOL& bHandled )
{
	int code = thread->GetExitCode();
    DWORD exitcode = *((DWORD *)&code);
	//app.DebugPrintf("CScene_FullscreenProgress Timer %d\n",pTimer->nId);
