				default:
					exitReasonStringId = IDS_CONNECTION_FAILED;
				}
				Minecraft *pMinecraft=Minecraft::GetInstance();
				pMinecraft->progressRenderer->progressStartNoAbort( exitReasonStringId );*/
				//app.NavigateBack(m_CompletionData->iPad);
				UINT uiIDA[1];
