#include <iostream>
#include <string>
#include "ocs2_double_integrator/DoubleIntegratorInterface.h"
#include <ocs2_core/cost/QuadraticStateCost.h>
#include <ocs2_core/cost/QuadraticStateInputCost.h>
#include <ocs2_core/dynamics/LinearSystemDynamics.h>
#include <ocs2_core/initialization/DefaultInitializer.h>
#include <ocs2_core/misc/LoadData.h>
// Boost
#include <boost/filesystem/operations.hpp>
#include <boost/filesystem/path.hpp>
namespace ocs2 {
namespace double_integrator {
/******************************************************************************************************/
/******************************************************************************************************/
/******************************************************************************************************/
DoubleIntegratorInterface::DoubleIntegratorInterface(const std::string& taskFile, const std::string& libraryFolder, bool verbose) {
  // check that task file exists
  boost::filesystem::path taskFilePath(taskFile);
  if (boost::filesystem::exists(taskFilePath)) {
    std::cerr << "[DoubleIntegratorInterface] Loading task file: " << taskFilePath << std::endl;
  } else {
    throw std::invalid_argument("[DoubleIntegratorInterface] Task file not found: " + taskFilePath.string());
  }
  // create library folder if it does not exist
  boost::filesystem::path libraryFolderPath(libraryFolder);
  boost::filesystem::create_directories(libraryFolderPath);
  std::cerr << "[DoubleIntegratorInterface] Generated library path: " << libraryFolderPath << std::endl;
  // Default initial condition and final goal
  loadData::loadEigenMatrix(taskFile, "initialState", initialState_);
  loadData::loadEigenMatrix(taskFile, "finalGoal", finalGoal_);
  // DDP-MPC settings
  ddpSettings_ = ddp::loadSettings(taskFile, "ddp", verbose);
  mpcSettings_ = mpc::loadSettings(taskFile, "mpc", verbose);
  /*
   * ReferenceManager & SolverSynchronizedModule
   */
  referenceManagerPtr_.reset(new ReferenceManager);
  /*
   * Optimal control problem
   */
  // Cost
  matrix_t Q(STATE_DIM, STATE_DIM);
  matrix_t R(INPUT_DIM, INPUT_DIM);
  matrix_t Qf(STATE_DIM, STATE_DIM);
  loadData::loadEigenMatrix(taskFile, "Q", Q);
  loadData::loadEigenMatrix(taskFile, "R", R);
  loadData::loadEigenMatrix(taskFile, "Q_final", Qf);
  std::cerr << "Q:  \n" << Q << "\n";
  std::cerr << "R:  \n" << R << "\n";
  std::cerr << "Q_final:\n" << Qf << "\n";
  problem_.costPtr->add("cost", std::make_unique<QuadraticStateInputCost>(Q, R));
  problem_.finalCostPtr->add("finalCost", std::make_unique<QuadraticStateCost>(Qf));
  // Dynamics
  const matrix_t A = (matrix_t(STATE_DIM, STATE_DIM) << 0.0, 1.0, 0.0, 0.0).finished();
  const matrix_t B = (matrix_t(STATE_DIM, INPUT_DIM) << 0.0, 1.0).finished();
  problem_.dynamicsPtr.reset(new LinearSystemDynamics(A, B));
  // Rollout
  auto rolloutSettings = rollout::loadSettings(taskFile, "rollout", verbose);
  rolloutPtr_.reset(new TimeTriggeredRollout(*problem_.dynamicsPtr, rolloutSettings));
  // Initialization
  linearSystemInitializerPtr_.reset(new DefaultInitializer(INPUT_DIM));
}
}  // namespace double_integrator
}  // namespace ocs2

#include <uibase/delayedfilewriter.h>
#include <uibase/log.h>
using namespace MOBase;
DelayedFileWriterBase::DelayedFileWriterBase(int delay) : m_TimerDelay(delay), m_Timer()
{
  QObject::connect(&m_Timer, &QTimer::timeout, this, &DelayedFileWriter::timerExpired);
  m_Timer.setSingleShot(true);
}
DelayedFileWriterBase::~DelayedFileWriterBase()
{
  if (m_Timer.isActive()) {
    log::error("delayed file save timer active at shutdown");
  }
}
void DelayedFileWriterBase::write()
{
  m_Timer.start(m_TimerDelay);
}
void DelayedFileWriterBase::cancel()
{
  m_Timer.stop();
}
void DelayedFileWriterBase::writeImmediately(bool ifOnTimer)
{
  if (!ifOnTimer || m_Timer.isActive()) {
    m_Timer.stop();
    doWrite();
  }
}
void DelayedFileWriterBase::timerExpired()
{
  doWrite();
}
DelayedFileWriter::DelayedFileWriter(DelayedFileWriter::WriterFunc func, int delay)
    : DelayedFileWriterBase(delay), m_Func(func)
{}
void DelayedFileWriter::doWrite()
{
  m_Func();
}

namespace ap::url {
//-------------------------------------------------------------------------
/// @details
/// 	Finds the mapper of the giver protocol
///	@param[in] type
///		The protocol to find
///	@param[out]	pMapper
///		Receives a ptr to the mapper
//-------------------------------------------------------------------------
ErrorOr<UrlConfig::MapperPtr> UrlConfig::getMapper(const iTextView type) {
    // Find the mapper
    auto mapper = m_UrlConfig.find(type);
    // If we couldn't find it
    if (mapper == m_UrlConfig.end())
        return APERR(Ec::InvalidSchema, "The url protocol", type,
                     "was not found");
    // Return it
    return &mapper->second;
}
//-------------------------------------------------------------------------
/// @details
/// 	Get the capabilities bitflags of a protocol
//-------------------------------------------------------------------------
Error UrlConfig::getCaps(const iTextView protocol, uint32_t &caps) {
    // Find the mapper
    auto mapper = getMapper(protocol);
    if (!mapper) return mapper.ccode();
    // Return the capabilities
    caps = (*mapper)->capabilities;
    return {};
}
//-------------------------------------------------------------------------
/// @details
/// 	Map a url to its path - removing the protocol, and any
///		prefixes it may have
//-------------------------------------------------------------------------
Error UrlConfig::toPath(const Url &fromUrl, file::Path &toPath) {
    auto protocol = fromUrl.protocol();
    // Find the mapper
    auto mapper = getMapper(protocol);
    if (!mapper) return mapper.ccode();
    // If we don't have a conversion for it
    if (!(*mapper)->toPath)
        return APERR(Ec::InvalidSchema, "The protocol", protocol,
                     "has no toPath");
    // Convert it
    return (*mapper)->toPath(fromUrl, toPath);
}
