/// @details
/// 	Map a protocol/path to a url and add any prefixes the
///		url may require
//-------------------------------------------------------------------------
Error UrlConfig::toUrl(const iTextView fromProtocol, const file::Path &fromPath,
                       Url &toUrl) {
    // Find the mapper
    auto mapper = getMapper(fromProtocol);
    if (!mapper) return mapper.ccode();
