class PrimeHandler {
public:
    // Check if a number is prime
    bool isPrime(int n)
    {
        if(n <= 1) return false;
        if(n <= 3) return true;
        if(n % 2 == 0 || n % 3 == 0) return false;
        for(int i = 5; i * i <= n; i += 6)
        {
            if(n % i == 0 || n % (i + 2) == 0) return false;
        }
        return true;
    }

    // Generate a list of prime numbers up to a certain number
    std::vector<int> generatePrimes(int limit)
    {
        std::vector<int> primes;
        for(int num = 2; num <= limit; ++num)
        {
            if(isPrime(num))
            {
                primes.push_back(num);
            }
        }
        return primes;
    }

    // Find the nth prime number
    int nthPrime(int n)
    {
        if(n <= 0) return -1; // Invalid input
        int count = 0;
        int num = 2;
        while(true)
        {
            if(isPrime(num))
            {
                ++count;
                if(count == n) return num;
            }
            ++num;
        }
    }
};

// Function to test the PrimeHandler class
void testPrimeHandler()
{
    PrimeHandler ph;

    // Test isPrime
    assert(ph.isPrime(2) == true);
    assert(ph.isPrime(3) == true);
    assert(ph.isPrime(4) == false);
    assert(ph.isPrime(5) == true);
    assert(ph.isPrime(17) == true);
    assert(ph.isPrime(18) == false);

    // Test generatePrimes
    std::vector<int> primesUpTo10 = ph.generatePrimes(10);
    assert(primesUpTo10 == std::vector<int>({2, 3, 5, 7}));

    // Test nthPrime
    assert(ph.nthPrime(1) == 2);
    assert(ph.nthPrime(2) == 3);
    assert(ph.nthPrime(3) == 5);
    assert(ph.nthPrime(4) == 7);
    assert(ph.nthPrime(5) == 11);

    std::cout << "All tests passed successfully!" << std::endl;
}

int main()
{
    testPrimeHandler();
    return 0;

}

