// Managed stream buffer implementation
class ManagedStreamBuf : public std::streambuf
{
public:
    // Constructor
    ManagedStreamBuf(System::IO::Stream^ stream)
    {
        m_stream = stream;
        setp(buffer, buffer + sizeof(buffer) - 1);
    }

    // Destructor
    ~ManagedStreamBuf()
    {
        sync();
    }

protected:
    // Overflow function
    int_type overflow(int_type ch) override
    {
        if (ch != traits_type::eof())
        {
            buffer[pptr() - pbase()] = ch;
            if (sync() == -1)
            {
                return traits_type::eof();
            }
        }
        return ch;
    }

    // Synchronization function
    int sync() override
    {
        if (pptr() > pbase())
        {
            pin_ptr<unsigned char> pin = &buffer[0];
            array<unsigned char>^ bufferArray = gcnew array<unsigned char>(pptr() - pbase());
            Marshal::Copy(IntPtr(pin), bufferArray, 0, bufferArray->Length);
            m_stream->Write(bufferArray, 0, bufferArray->Length);
            pbump(-static_cast<int>(bufferArray->Length));
        }
        return 0;
    }

private:
    System::IO::Stream^ m_stream;
    unsigned char buffer[1024];
};

