// Bubble sort implementation
void bubbleSort(std::vector<int> &arr)
{
    bool swapped;
    int size = arr.size();
    for(int i=0;i<size-1;i++)
    {
        swapped = false;
        for(int j=0;j<size-i-1;j++)
        {
            if(arr[j] > arr[j+1])
            {
                std::swap(arr[j], arr[j+1]);
                swapped = true;
            }
        }
        // Early exit if no swaps occurred
        if(!swapped) break;
    }
}

