void TraverseDOM(IHTMLDocument2* pDoc)
{
    if (pDoc == nullptr) return;

    IHTMLElementCollection* pBodyCollection = nullptr;
    pDoc->get_body(&pBodyCollection);

    if (pBodyCollection == nullptr) return;

    long length = 0;
    pBodyCollection->get_length(&length);

    for (long i = 0; i < length; i++)
    {
        IHTMLDOMNode* pNode = nullptr;
        pBodyCollection->item(i, &pNode);

        if (pNode == nullptr) continue;

        BSTR text = nullptr;
        pNode->get_nodeValue(&text);

        if (text != nullptr)
        {
            // Do something with the text
            wprintf(L"Text Node: %s\n", text);
            SysFreeString(text);
        }

        IHTMLDOMNode* pChild = nullptr;
        pNode->get_firstChild(&pChild);

        while (pChild != nullptr)
        {
            TraverseDOMHelper(pChild);
            IHTMLDOMNode* pNext = nullptr;
            pChild->get_nextSibling(&pNext);
            pChild->Release();
            pChild = pNext;
        }

        pNode->Release();
    }

    pBodyCollection->Release();
}

void TraverseDOMHelper(IHTMLDOMNode* pNode)
{
    if (pNode == nullptr) return;

    BSTR text = nullptr;
    pNode->get_nodeValue(&text);

    if (text != nullptr)
    {
        // Do something with the text
        wprintf(L"Text Node: %s\n", text);
        SysFreeString(text);
    }

    IHTMLDOMNode* pChild = nullptr;
    pNode->get_firstChild(&pChild);

    while (pChild != nullptr)
    {
        TraverseDOMHelper(pChild);
        IHTMLDOMNode* pNext = nullptr;
        pChild->get_nextSibling(&pNext);
        pChild->Release();
        pChild = pNext;
    }
}

