// Transpose a 4x4 matrix using AVX-512 instructions
void transpose_4x4_zmm(__m512i& zmm0, __m512i& zmm1, __m512i& zmm2, __m512i& zmm3)
{
    // Step 1: Shuffle to interleave rows
    __m512i t0 = _mm512_shuffle_i32x4(zmm0, zmm1, 0x44);
    __m512i t1 = _mm512_shuffle_i32x4(zmm0, zmm1, 0xEE);
    __m512i t2 = _mm512_shuffle_i32x4(zmm2, zmm3, 0x44);
    __m512i t3 = _mm512_shuffle_i32x4(zmm2, zmm3, 0xEE);

    // Step 2: Permute to complete the transpose
    zmm0 = _mm512_permutex2var_epi32(t0, _mm512_setr_epi32(0, 4, 1, 5, 2, 6, 3, 7, 8, 12, 9, 13, 10, 14, 11, 15), t2);
    zmm1 = _mm512_permutex2var_epi32(t0, _mm512_setr_epi32(0, 4, 1, 5, 2, 6, 3, 7, 8, 12, 9, 13, 10, 14, 11, 15), t3);
    zmm2 = _mm512_permutex2var_epi32(t1, _mm512_setr_epi32(0, 4, 1, 5, 2, 6, 3, 7, 8, 12, 9, 13, 10, 14, 11, 15), t2);
    zmm3 = _mm512_permutex2var_epi32(t1, _mm512_setr_epi32(0, 4, 1, 5, 2, 6, 3, 7, 8, 12, 9, 13, 10, 14, 11, 15), t3);
}

