// Base64 encoding function
std::string base64_encode(const unsigned char* input, size_t length)
{
    BIO *bio, *b64;
    BUF_MEM *bufferPtr;

    b64 = BIO_new(BIO_f_base64());
    bio = BIO_new(BIO_s_mem());
    bio = BIO_push(b64, bio);

    // Ignore newlines - write everything in one line
    BIO_set_flags(bio, BIO_FLAGS_BASE64_NO_NL);
    BIO_write(bio, input, length);
    BIO_flush(bio);
    BIO_get_mem_ptr(bio, &bufferPtr);
    BIO_set_close(bio, BIO_NOCLOSE);
    BIO_free_all(bio);

    std::string output(bufferPtr->data, bufferPtr->length);
    BUF_MEM_free(bufferPtr);

    return output;
}

// AES-256-CBC encryption function
std::string aes_encrypt(const std::string& plaintext, const std::string& key, const std::string& iv)
{
    unsigned char *ciphertext = new unsigned char[plaintext.length() + AES_BLOCK_SIZE];
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), nullptr, (const unsigned char*)key.c_str(), (const unsigned char*)iv.c_str());
    EVP_EncryptUpdate(ctx, ciphertext, &plaintext.length(), (const unsigned char*)plaintext.c_str(), plaintext.length());
    int len;
    EVP_EncryptFinal_ex(ctx, ciphertext + plaintext.length(), &len);
    plaintext.length() += len;
    EVP_CIPHER_CTX_free(ctx);

    std::string ciphertextBase64 = base64_encode(ciphertext, plaintext.length());
    delete[] ciphertext;

    return ciphertextBase64;
}

