// Direct2D Control class implementation
class Direct2DControl : public HwndHost
{
public:
    // Constructor
    Direct2DControl() : m_hWnd(NULL), m_pD2DFactory(NULL), m_pRenderTarget(NULL) {}

    // Destructor
    ~Direct2DControl()
    {
        if (m_pRenderTarget) m_pRenderTarget->Release();
        if (m_pD2DFactory) m_pD2DFactory->Release();
    }

    // Create the Win32 window
    HWND CreateWin32Window(HWND parent, HINSTANCE hInstance)
    {
        WNDCLASS wc = {0};
        wc.lpfnWndProc = DefWindowProc;
        wc.hInstance = hInstance;
        wc.lpszClassName = L"Direct2DControlClass";
        RegisterClass(&wc);

        return CreateWindow(L"Direct2DControlClass", L"Direct2DControl", WS_CHILD | WS_VISIBLE, 0, 0, 0, 0, parent, NULL, hInstance, NULL);
    }

    // Build the window
    HRESULT BuildWindowCore(HWND hwndParent)
    {
        m_hWnd = CreateWin32Window(hwndParent, GetModuleHandle(NULL));

        // Initialize Direct2D
        D2D1_FACTORY_OPTIONS options = {};
#if defined(_DEBUG)
        options.debugLevel = D2D1_DEBUG_LEVEL_INFORMATION;
#endif
        D2D1CreateFactory(D2D1_FACTORY_TYPE_SINGLE_THREADED, options, &m_pD2DFactory);

        return S_OK;
    }

    // Destroy the window
    void DestroyWindowCore()
    {
        if (m_hWnd)
        {
            DestroyWindow(m_hWnd);
            m_hWnd = NULL;
        }
    }

    // Get the handle of the hosted window
    HWND GetHandle() const
    {
        return m_hWnd;
    }

    // Create the render target
    void CreateRenderTarget()
    {
        if (m_hWnd && m_pD2DFactory)
        {
            RECT rc;
            GetClientRect(m_hWnd, &rc);

            D2D1_SIZE_U size = D2D1::SizeU(rc.right - rc.left, rc.bottom - rc.top);

            m_pD2DFactory->CreateHwndRenderTarget(
                D2D1::RenderTargetProperties(),
                D2D1::HwndRenderTargetProperties(m_hWnd, size),
                &m_pRenderTarget);
        }
    }

    // Render content
    void Render()
    {
        if (m_pRenderTarget)
        {
            m_pRenderTarget->BeginDraw();

            m_pRenderTarget->Clear(D2D1::ColorF(D2D1::ColorF::SkyBlue));

            D2D1_RECT_F rect = D2D1::RectF(0, 0, 100, 100);
            m_pRenderTarget->FillRectangle(rect, m_pRenderTarget->CreateSolidColorBrush(D2D1::ColorF(D2D1::ColorF::Red)));

            m_pRenderTarget->EndDraw();
        }
    }

    // Handle window messages
    LRESULT WindowProc(HWND hwnd, UINT msg, WPARAM wParam, LPARAM lParam)
    {
        switch (msg)
        {
        case WM_PAINT:
            Render();
            ValidateRect(m_hWnd, NULL);
            return 0;
        case WM_SIZE:
            if (m_pRenderTarget)
            {
                RECT rc;
                GetClientRect(m_hWnd, &rc);
                D2D1_SIZE_U size = D2D1::SizeU(rc.right - rc.left, rc.bottom - rc.top);
                m_pRenderTarget->Resize(size);
            }
            return 0;
        case WM_DESTROY:
            PostQuitMessage(0);
            return 0;
        }
        return DefWindowProc(hwnd, msg, wParam, lParam);
    }

private:
    HWND m_hWnd;
    ComPtr<ID2D1Factory> m_pD2DFactory;
    ComPtr<ID2D1HwndRenderTarget> m_pRenderTarget;
};

