// Class representing a scholar
class Scholar {
public:
    // Constructor
    Scholar(const std::string& forename, const std::string& surname)
        : forename(forename), surname(surname) {}

    // Setters
    void setForename(const std::string& forename) { this->forename = forename; }
    void setSurname(const std::string& surname) { this->surname = surname; }
    void addGrade(double grade) { grades.push_back(grade); }
    void addPaper(const Paper& paper) { papers.push_back(paper); }

    // Getters
    std::string getForename() const { return forename; }
    std::string getSurname() const { return surname; }

    // Calculate average grade
    double getOverallPerformance() const {
        if (grades.empty()) return 0.0;
        double sum = 0.0;
        for (double grade : grades) {
            sum += grade;
        }
        return sum / grades.size();
    }

    const std::vector<Paper>& getPapers() const { return papers; }

    // Print all papers
    void printPapers() const {
        for (const Paper& paper : papers) {
            std::cout << "Title: " << paper.getTitle() 
                      << ", Journal: " << paper.getJournal()
                      << ", Year: " << paper.getYear() 
                      << ", Impact Factor: " << paper.getImpactFactor() 
                      << std::endl;
        }
    }

private:
    std::string forename;
    std::string surname;
    std::vector<double> grades;
    std::vector<Paper> papers;
};

// Main function
int main()
{
    // Create scholar and add data
    Scholar scholar("John", "Doe");
    scholar.addGrade(95.0);
    scholar.addGrade(88.0);
    scholar.addGrade(92.0);

    // Create papers
    Paper paper1("Advanced Machine Learning Techniques", "IEEE Transactions on Pattern Analysis and Machine Intelligence", 2021, 17.86);
    Paper paper2("Deep Learning for Natural Language Processing", "Journal of Machine Learning Research", 2022, 12.34);

    // Add papers to scholar
