    scholar.addPaper(paper2);

    // Output scholar information
    std::cout << "Scholar: " << scholar.getForename() << " " << scholar.getSurname() << std::endl;
    std::cout << "Overall Performance: " << scholar.getOverallPerformance() << std::endl;
    std::cout << "Papers:" << std::endl;
    scholar.printPapers();

    return 0;
}

