void deriveKeyAndIV(const std::string& password, const std::string& salt, std::string& key, std::string& iv)
{
    Poco::Crypto::CipherFactory& factory = Poco::Crypto::CipherFactory::defaultFactory();
    Poco::Crypto::CipherKey cipherKey("md5", password, salt, 1);

