int main()
{
    std::string fileToDecrypt = "encrypted_file";
    std::string password = "REDACTED_CREDENTIAL";

    // Open encrypted file for reading in binary mode
    std::ifstream file(fileToDecrypt, std::ios::binary);
    if (!file)
    {
        std::cerr << "Failed to open file for reading." << std::endl;
        return 1;
    }

    // Read entire file content into buffer
    std::string buffer((std::istreambuf_iterator<char>(file)), std::istreambuf_iterator<char>());
    file.close();

    // Verify file format (should start with "Salted__")
    if (buffer.substr(0, 8) != "Salted__")
    {
        std::cerr << "Invalid file format." << std::endl;
        return 1;
    }

    // Extract salt and encrypted data from buffer
    std::string salt = buffer.substr(8, 8);
    std::string encryptedData = buffer.substr(16);

    // Derive key and IV from password and salt
    std::string key, iv;
    deriveKeyAndIV(password, salt, key, iv);

    // Create cipher for AES-128-CBC decryption
    Poco::Crypto::CipherFactory& factory = Poco::Crypto::CipherFactory::defaultFactory();
    Poco::Crypto::CipherKey cipherKey("aes-128-cbc", key, iv);
    Poco::AutoPtr<Poco::Crypto::Cipher> cipher = factory.createCipher(cipherKey);

    // Decrypt the data (base64 encoded)
    std::string decryptedData = cipher->decryptString(encryptedData, Poco::Crypto::Cipher::ENC_BASE64);

    // Output decrypted data
    std::cout << "Decrypted data: " << decryptedData << std::endl;

    return 0;
}

