// Function to print Fibonacci sequence
void printFibonacci(int n)
{
    if (n <= 0)
    {
        cout << "Please enter a positive integer." << endl;
        return;
    }

    long long first = 0, second = 1, next;

    for (int i = 1; i <= n; ++i)
    {
        if (i == 1)
        {
            cout << first << " ";
            continue;
        }
        if (i == 2)
        {
            cout << second << " ";
            continue;
        }
        next = first + second;
        first = second;
        second = next;
        cout << next << " ";
    }
    cout << endl;
}

