// Monitors changes in a variable
void monitor_changes(int* variable_to_monitor)
{
    int last_value = *variable_to_monitor;
    while(1)
    {
        int cur_value = *variable_to_monitor;
        if(cur_value != last_value)
        {
            printf("Value has changed!");
