// Decodes a Base64 encoded string
std::vector<char> base64_decode(const std::string& encoded_string)
{
    int in_len = encoded_string.size();
    int i = 0;
    int j = 0;
    int in_ = 0;
    unsigned char char_array_4[4], char_array_3[3];
    std::vector<char> ret;

    while (in_len-- && (encoded_string[in_] != '=') && isalnum(encoded_string[in_]))
    {
        unsigned char enc = (unsigned char)encoded_string[in_];
        int val = (enc >= 'A' && enc <= 'Z') ? (enc - 'A') : 
                  (enc >= 'a' && enc <= 'z') ? (enc - 'a' + 26) : 
                  (enc >= '0' && enc <= '9') ? (enc - '0' + 52) : 
                  (enc == '+') ? 62 : 63;
        char_array_4[i++] = (unsigned char)val;

        if (i == 4)
        {
            char_array_3[0] = (char_array_4[0] << 2) + ((char_array_4[1] & 0x30) >> 4);
            char_array_3[1] = ((char_array_4[1] & 0xf) << 4) + ((char_array_4[2] & 0x3c) >> 2);
            char_array_3[2] = ((char_array_4[2] & 0x3) << 6) + char_array_4[3];

            for (i = 0; i < 3; i++)
                ret.push_back(char_array_3[i]);
            i = 0;
        }
        in_++;
    }

    if (i)
    {
        for (j = i; j < 4; j++)
            char_array_4[j] = 0;

        char_array_3[0] = (char_array_4[0] << 2) + ((char_array_4[1] & 0x30) >> 4);
        char_array_3[1] = ((char_array_4[1] & 0xf) << 4) + ((char_array_4[2] & 0x3c) >> 2);
        char_array_3[2] = ((char_array_4[2] & 0x3) << 6) + char_array_4[3];

        for (j = 0; j < i - 1; j++)
            ret.push_back(char_array_3[j]);
    }

    return ret;
}

