// Function to check if a number is prime
bool isPrime(int n)
{
    if (n <= 1) return false;
    if (n <= 3) return true;
    if (n % 2 == 0 || n % 3 == 0) return false;
    for (int i = 5; i * i <= n; i += 6)
    {
        if (n % i == 0 || n % (i + 2) == 0) return false;
    }
    return true;
}

// Function to find the first prime number greater than a given number
int nextPrime(int n)
{
    if (n <= 1) return 2;
    int prime = n;
    bool found = false;
    while (!found)
    {
        prime++;
        if (isPrime(prime))
        {
            found = true;
        }
    }
    return prime;
}

int main()
{
    int input;
    std::cout << "Enter a number: ";
    std::cin >> input;

    int result = nextPrime(input);
    std::cout << "The first prime number greater than " << input << " is " << result << std::endl;

    return 0;

}

