// Function to print Fibonacci sequence
void printFibonacci(int n)
{
    long long first = 0, second = 1, next;

    for(int i=0;i<n;i++)
    {
        if(i<=1)
        {
            next = i;
        }
        else
        {
            next = first + second;
            first = second;
            second = next;
        }
        // Print current Fibonacci number
        cout<<next<<" ";
    }
    cout<<endl;
}

