        // Determine which bit to set: prefer bit 1 if set, otherwise bit 0
        u64 index = (map & 1) ? 1 : 0;
        auto mask = u64(1) << index;

        // Atomically set the bit and get previous value
        auto previous =
            __atomic_fetch_or(&mData, mask, __ATOMIC_SEQ_CST);

        // Check if the bit was previously unset (acquisition succeeded)
        if ((previous & mask) == 0)
        {
            return index;
        }
    }
}

