// Main function to measure CPU time
int main()
{
    double avg = 0.0;
    int N = (int) 1e6;
    int tally = 0;

    struct rusage usage;
    struct timeval ustart, ustop, sstart, sstop;

    getrusage(RUSAGE_SELF, &usage);
    ustart = usage.ru_utime;
    sstart = usage.ru_stime;

    for(int k=0; k<10; k++)
    {
        ustart = usage.ru_utime;
        sstart = usage.ru_stime;

        // Empty loop for timing
        for(int i=0; i<N; i++) continue;

        getrusage(RUSAGE_SELF, &usage);
        ustop = usage.ru_utime;
        sstop = usage.ru_stime;

        // Calculate elapsed time and accumulate average
        avg += ((ustop.tv_sec + ustop.tv_usec / 1e6 + sstop.tv_sec + sstop.tv_usec / 1e6) - 
                (ustart.tv_sec + ustart.tv_usec / 1e6 + sstart.tv_sec + sstart.tv_usec / 1e6)) / 10.0;
    }

    // Output the average CPU time
    std::cout<<avg<<'\n';

    return 0;
}

