// Loads shader source from asset file
std::string loadShaderSource(AAssetManager* assetManager, const std::string& filename)
{
    // Open asset file for reading
    AAsset* asset = AAssetManager_open(assetManager, filename.c_str(), AASSET_MODE_STREAMING);
    if (!asset)
    {
        return "";
    }

    // Get asset length and read contents
    off_t length = AAsset_getLength(asset);
    std::vector<char> buffer(length + 1);
    AAsset_read(asset, buffer.data(), length);
    buffer[length] = '\0'; // Null-terminate the string
    AAsset_close(asset);

    // Return as std::string
    return std::string(buffer.data());
}

