#include <iostream>
#include <vector>
#include <mutex>
#include <cuda_runtime.h>

// Custom memory allocator for CUDA
class CustomAllocator {
public:
    // Constructor initializes the allocator with block size and count
    CustomAllocator(size_t block_size, size_t num_blocks) 
        : block_size_(block_size), num_blocks_(num_blocks) 
    {
        // Allocate a large block of memory on GPU
        cudaMalloc(&pool_, block_size * num_blocks);

        // Initialize metadata for each block
        metadata_.resize(num_blocks);
        for (size_t i = 0; i < num_blocks; ++i) {
            metadata_[i].is_free = true;
            metadata_[i].index = i;
        }
        free_list_head_ = 0;
    }

    // Destructor frees the allocated GPU memory
    ~CustomAllocator() {
        cudaFree(pool_);
    }

    // Allocates a block of memory from the pool
    void* allocate() {
        std::lock_guard<std::mutex> lock(mutex_);

        if (free_list_head_ == -1) {
            throw std::bad_alloc();
        }

        int index = free_list_head_;
        free_list_head_ = metadata_[index].next_free;

        metadata_[index].is_free = false;
        return static_cast<char*>(pool_) + index * block_size_;
    }

    // Deallocates a previously allocated block
    void deallocate(void* ptr) {
        std::lock_guard<std::mutex> lock(mutex_);

        size_t index = (static_cast<char*>(ptr) - static_cast<char*>(pool_)) / block_size_;

        metadata_[index].is_free = true;
        metadata_[index].next_free = free_list_head_;
        free_list_head_ = index;
    }

private:
    size_t block_size_;
    size_t num_blocks_;
    void* pool_;
    std::vector<struct BlockMetadata> metadata_;
    int free_list_head_ = 0;
    std::mutex mutex_;

    struct BlockMetadata {
        bool is_free;
        int index;
        int next_free = -1;
    };
};

// Main function demonstrating usage
int main()
{
    CustomAllocator allocator(256, 1024);

    void* ptr1 = allocator.allocate();
    void* ptr2 = allocator.allocate();

    allocator.deallocate(ptr1);
    allocator.deallocate(ptr2);

    return 0;
}

