typedef __vector unsigned char uint8x16_p;

// Fast load 8 bytes into vector register using lxvd2x instruction
uint8x16_p VectorFastLoad8(const void* p)
{
    long offset = 0;
    uint8x16_p res;

    // Inline assembly to load vector from memory
    __asm(
        "lxvd2x %x0, %1, %2"
        : "=wa" (res)
        : "r" (p), "r" (offset / 4)
    );

    return res;
}

