#include <Eigen/Dense>

using namespace Eigen;

// Ray structure definition
struct Ray {
    Vector3f origin;
    Vector3f direction;
    Ray(Vector3f o, Vector3f d) : origin(o), direction(d) {}
};

// Sphere structure definition
struct Sphere {
    Vector3f center;
    float radius;
    Vector3f color;
    Sphere(Vector3f c, float r, Vector3f col) : center(c), radius(r), color(col) {}

    // Intersection test between ray and sphere
    bool intersect(const Ray& ray, float& t) const {
        Vector3f L = center - ray.origin;
        float tca = L.dot(ray.direction);
        if (tca < 0) return false;
        float d2 = L.squaredNorm() - tca * tca;
        float r2 = radius * radius;
        if (d2 > r2) return false;
        float thc = std::sqrt(r2 - d2);
        t = tca - thc;
        return true;
    }
};

// Trace function to compute lighting at intersection point
Vector3f trace(const Ray& ray, const std::vector<Sphere>& spheres) {
    float closest_t = std::numeric_limits<float>::max();
    const Sphere* closest_sphere = nullptr;

    for (const auto& sphere : spheres) {
        float t;
        if (sphere.intersect(ray, t) && t < closest_t) {
            closest_t = t;
            closest_sphere = &sphere;
        }
    }

    if (closest_sphere) {
        Vector3f hit_point = ray.origin + ray.direction * closest_t;
        Vector3f normal = (hit_point - closest_sphere->center).normalized();
        Vector3f light_dir = Vector3f(1, -1, -1).normalized();
        float diffuse = std::max(0.0f, normal.dot(light_dir));
        return closest_sphere->color * diffuse;
    }

    // Background color
    return Vector3f(0, 0, 0);
}

int main()
{
    int width = 800, height = 600;
    std::vector<Vector3f> image(width * height, Vector3f(0, 0, 0));

    Vector3f camera_pos(0, 0, -5);
    Vector3f screen_center(0, 0, 0);
    float screen_width = 2.0f, screen_height = 2.0f * height / width;

    std::vector<Sphere> spheres = {
        Sphere(Vector3f(0, 0, 0), 1, Vector3f(1, 0, 0)),
        Sphere(Vector3f(1, 0, 0), 1, Vector3f(0, 1, 0)),
        Sphere(Vector3f(-1, 0, 0), 1, Vector3f(0, 0, 1))
    };

    // Rasterize the scene
    for (int y = 0; y < height; ++y) {
        for (int x = 0; x < width; ++x) {
            float u = (2 * (x + 0.5) / width - 1) * screen_width;
            float v = (1 - 2 * (y + 0.5) / height) * screen_height;
            Vector3f screen_point(screen_center + Vector3f(u, v, 0));
            Ray ray(camera_pos, (screen_point - camera_pos).normalized());
            image[y * width + x] = trace(ray, spheres);
        }
    }

    // Output pixel data in PPM format
    for (int y = 0; y < height; ++y) {
        for (int x = 0; x < width; ++x) {
            Vector3f color = image[y * width + x];
            std::cout << (int)(255 * std::min(1.0f, color[0])) << " "
                      << (int)(255 * std::min(1.0f, color[1])) << " "
                      << (int)(255 * std::min(1.0f, color[2])) << "\n";
        }
    }

    return 0;
}

#include <iostream>
     #include <list>

     // Class to maintain min and max values in a linked list
     class MinMaxLinkedList {
     private:
         std::list<int> list;
         std::list<int>::iterator minIt, maxIt;

     public:
         // Constructor initializes iterators to end
         MinMaxLinkedList() : minIt(list.end()), maxIt(list.end()) {}

         // Insert a value into the list and update min/max iterators
         void insert(int value) {
             list.push_back(value);
             auto it = --list.end();
             if (minIt == list.end() || *it < *minIt) minIt = it;
             if (maxIt == list.end() || *it > *maxIt) maxIt = it;
         }

         // Remove a value from the list and update min/max iterators if needed
         void remove(int value) {
             auto it = std::find(list.begin(), list.end(), value);
             if (it != list.end()) {
                 if (it == minIt) {
                     if (it != list.begin()) minIt = std::prev(it);
                     else minIt = list.end();
                 }
                 if (it == maxIt) {
                     if (it != --list.end()) maxIt = std::next(it);
                     else maxIt = list.end();
                 }
                 list.erase(it);
             }
         }

         // Get minimum value, returns -1 if empty
         int getMin() const {
             return minIt != list.end() ? *minIt : -1;
         }

         // Get maximum value, returns -1 if empty
         int getMax() const {
             return maxIt != list.end() ? *maxIt : -1;
         }
     };

     // Main function demonstrating usage
     int main()
     {
         MinMaxLinkedList ll;
         ll.insert(5);
         ll.insert(3);
         ll.insert(7);
         std::cout << "Min: " << ll.getMin() << std::endl; // 3
         std::cout << "Max: " << ll.getMax() << std::endl; // 7
         ll.remove(3);
         std::cout << "Min: " << ll.getMin() << std::endl; // 5
         return 0;

     }

