// Convert cv::Mat to numpy array
boost::python::object mat_to_numpy(const cv::Mat& mat)
{
    npy_intp dims[2] = {mat.rows, mat.cols};
    PyObject* py_array = PyArray_SimpleNew(2, dims, NPY_FLOAT64);
    std::memcpy(PyArray_DATA(py_array), mat.ptr<double>(), mat.total() * mat.elemSize());
    return boost::python::object(boost::python::handle<>(boost::python::borrowed(py_array)));
}

// Convert numpy array to cv::Mat
cv::Mat numpy_to_mat(boost::python::object& py_array)
{
    PyArrayObject* array = reinterpret_cast<PyArrayObject*>(py_array.ptr());
    npy_intp* dims = PyArray_DIMS(array);
    cv::Mat mat(dims[0], dims[1], CV_64F, PyArray_DATA(array));
    return mat;
}

