#include <boost/python.hpp>
#include <vector>

// Base abstract class A
struct A {
    std::vector<int> numbers;

    virtual void a() = 0;
};

// Base abstract class B
struct B {
    virtual void b(const A& a) = 0;
};

namespace py = boost::python;

// Wrapper for A to support Python overrides
struct A_wrapper : A, py::wrapper<A> {
    void a() {
        this->get_override("a")();
    }
};

// Wrapper for B to support Python overrides
struct B_wrapper : B, py::wrapper<B> {
    void b(const A& a) {
        this->get_override("b")(a);
    }
};

// To-Python converter for A
struct A_to_python {
    static PyObject* convert(const A& a) {
        py::object pyA = py::object(py::ptr(new A_wrapper(a)));
        return pyA.ptr();
    }
};

BOOST_PYTHON_MODULE(example)
{
    typedef std::vector<int> int_vec_t;

    // Expose std::vector<int> as IntList to Python
    py::class_<int_vec_t>("IntList")
        .def(py::vector_indexing_suite<int_vec_t>());

    // Expose A class (abstract) with pure virtual method
    py::class_<A_wrapper, boost::noncopyable>("A")
        .def_readwrite("numbers", &A::numbers)
        .def("a", py::pure_virtual(&A::a));

    // Expose B class (abstract) with pure virtual method
    py::class_<B_wrapper, boost::noncopyable>("B")
        .def("b", py::pure_virtual(&B::b));

    // Register custom to-Python converter for A
    py::to_python_converter<A, A_to_python>();
}

#include <iostream>
#include <vector>
#include <cmath>

// Computes the cost function for linear regression
double compute_cost(const std::vector<double>& x, const std::vector<double>& y, double theta0, double theta1)
{
    int m = x.size();
    double cost = 0.0;
    for(int i=0;i<m;++i)
    {
        double h = theta0 + theta1 * x[i];
        cost += std::pow(h - y[i], 2);
    }
    return cost / (2 * m);
}

// Performs gradient descent to optimize theta parameters
void gradient_descent(const std::vector<double>& x, const std::vector<double>& y, double& theta0, double& theta1, double alpha, int num_iterations)
{
    int m = x.size();
    for(int iter=0;iter<num_iterations;++iter)
    {
        double grad0 = 0.0;
        double grad1 = 0.0;
        for(int i=0;i<m;++i)
        {
            double h = theta0 + theta1 * x[i];
            grad0 += (h - y[i]);
            grad1 += (h - y[i]) * x[i];
        }
        theta0 -= alpha * grad0 / m;
        theta1 -= alpha * grad1 / m;

        // Optionally print the cost to monitor convergence
        double cost = compute_cost(x, y, theta0, theta1);
        std::cout<<"Iteration "<<iter<<" - Cost: "<<cost<<std::endl;
    }
}

int main()
{
    std::vector<double> x = {1, 2, 3, 4, 5};
    std::vector<double> y = {2, 4, 5, 4, 5};

    double theta0 = 0.0;
    double theta1 = 0.0;
    double alpha = 0.01;
    int num_iterations = 1000;

    gradient_descent(x, y, theta0, theta1, alpha, num_iterations);

    std::cout<<"Final theta0: "<<theta0<<", theta1: "<<theta1<<std::endl;

    return 0;

}

