using namespace std;

// Time measurement function
pair<double, double> timeit(int size, int n=30)
{
    double total_clocks = 0;
    double total_sum = 0;
    for(int i=0;i<n;i++)
    {
        xt::xtensor<double, 1> a = xt::random::rand({size}, 0., 1.);
        int start = clock();

        // Compute sum with parallel execution
        double s = xt::sum(a, xt::evaluation_strategy::immediate, xt::parallelExecution())();

        int end = clock();
        total_sum += s; 
        total_clocks += end-start;
    }
    return pair<double, double>(total_clocks/CLOCKS_PER_SEC/n, total_sum); 
}

int main(int argc, char *argv[])
{
    for(int i=5;i<8;i++)
    {
        int size = pow(10, i);
        pair<double, double> ret = timeit(size);
        cout<<"size: "<<size<< " \t " <<ret.first<<" sec\t"<<ret.second<<endl;
    }
    return 0;

}

