int main()
{
    int M, N;
    cin >> M >> N;

    vector<vector<char>> board(M, vector<char>(N));
    for(int i = 0; i < M; i++)
    {
        for(int j = 0; j < N; j++)
        {
            cin >> board[i][j];
        }
    }

    int singleCells = 0;
    for(int i = 0; i < M; i++)
    {
        for(int j = 0; j < N; j++)
        {
            if(board[i][j] == 'O')
            {
                int count = 0;
                if(i - 1 >= 0 && board[i - 1][j] == 'O')
                {
                    count++;
                }
                if(i + 1 < M && board[i + 1][j] == 'O')
                {
                    count++;
                }
                if(j - 1 >= 0 && board[i][j - 1] == 'O')
                {
                    count++;
                }
                if(j + 1 < N && board[i][j + 1] == 'O')
                {
                    count++;
                }
                if(count <= 1)
                {
                    singleCells++;
                }
            }
        }
    }

    // Output the result
