// Computes the average of a vector of integers
double average(const std::vector<int>& numbers)
{
    // Handle empty vector case
    if(numbers.empty())
    {
        return 0;
    }
    int sum = 0;
    // Iterate through each number and accumulate sum
    for(int number : numbers)
    {
        sum += number;
    }
    // Cast to double for precise division
    return static_cast<double>(sum) / numbers.size();
}

int main()
{
    std::vector<int> numbers = {10,20,30,40,50};
    // Output the computed average
    std::cout<<"The average is: "<<average(numbers)<<std::endl;
    return 0;

}

