#include <iostream>

// Priority Queue implementation using linked list
class PriorityQueue {
public:
    PriorityQueue();
    ~PriorityQueue();
    void enqueue(int value, int priority);
    int dequeue();
    bool isEmpty() const;
    void display() const;

private:
    struct Node {
        int value;
        int priority;
        Node* next;
    };
    Node* front;
};

// Constructor initializes empty queue
PriorityQueue::PriorityQueue()
{
    front = nullptr;
}

// Destructor removes all remaining nodes
PriorityQueue::~PriorityQueue()
{
    while (!isEmpty())
    {
        dequeue();
    }
}

// Add element with given value and priority
void PriorityQueue::enqueue(int value, int priority)
{
    Node* newNode = new Node;
    newNode->value = value;
    newNode->priority = priority;
    newNode->next = nullptr;

    if (isEmpty() || priority > front->priority)
    {
        newNode->next = front;
        front = newNode;
    }
    else
    {
        Node* temp = front;
        while (temp->next != nullptr && temp->next->priority >= priority)
        {
            temp = temp->next;
        }
        newNode->next = temp->next;
        temp->next = newNode;
    }
}

// Remove and return highest priority element
int PriorityQueue::dequeue()
{
    if (isEmpty())
    {
        throw "The priority queue is empty, can't dequeue.";
    }

    Node* temp = front;
    int value = front->value;
    front = front->next;
    delete temp;
    return value;
}

// Check if queue is empty
bool PriorityQueue::isEmpty() const
{
    return front == nullptr;
}

// Display all elements in order of priority
void PriorityQueue::display() const
{
    Node* temp = front;
    while (temp != nullptr)
    {
        std::cout << temp->value << " (priority: " << temp->priority << ") -> ";
        temp = temp->next;
    }
    std::cout << "end" << std::endl;
}

// Test the priority queue
