{
    PriorityQueue pq;

    pq.enqueue(10, 3);
    pq.enqueue(5, 1);
    pq.enqueue(3, 4);
    pq.enqueue(20, 2);

    pq.display();

    std::cout << "Dequeued: " << pq.dequeue() << std::endl;
    std::cout << "Dequeued: " << pq.dequeue() << std::endl;

    pq.display();

    return 0;
}

#include <iostream>
