// Buffer class for Python output stream
class PyOStreamBuffer : public std::streambuf {
public:
    // Constructor initializes buffer and file pointer
    PyOStreamBuffer(PyFileObject* file) : file(file)
    {
        setp(buffer, buffer + sizeof(buffer) - 1);
    }

protected:
    // Handle overflow characters
    int overflow(int c) override
    {
        if (c != EOF)
        {
            PyFile_WriteString((char*)&c, 1, (PyObject*)file);
        }
        return 0;
    }

    // Synchronize buffer with Python file
    int sync() override
    {
        PyFile_WriteString(pbase(), pptr() - pbase(), (PyObject*)file);
        pbump(-1 * (pptr() - pbase()));
        return 0;
    }

private:
    PyFileObject* file;
    char buffer[1024];
};

// Output stream class wrapping Python file object
class PyOStream : public std::ostream {
public:
    // Constructor creates buffer and initializes ostream
    PyOStream(PyFileObject* file) : std::ostream(new PyOStreamBuffer(file)) {}

    // Destructor cleans up buffer
    ~PyOStream()
    {
        delete rdbuf();
    }
};

