// TimeSpan class represents a duration in seconds
class TimeSpan {
public:
    // Constructor initializes total seconds
    TimeSpan(int days, int hours, int minutes, int seconds)
        : total_seconds_(days * 24 * 3600 + hours * 3600 + minutes * 60 + seconds) {}

    // Returns the total number of seconds
    int TotalSeconds() const {
        return total_seconds_;
    }

private:
    int total_seconds_;
};

// DateTime class wraps a time point with additional functionality
class DateTime {
public:
    // Constructor creates a DateTime from individual components
    DateTime(int year, int month, int day, int hour, int minute, int second)
        : time_point_(std::chrono::system_clock::from_time_t(std::mktime(&time_t_))) {
        time_t_.tm_year = year - 1900;
        time_t_.tm_mon = month - 1;
        time_t_.tm_mday = day;
        time_t_.tm_hour = hour;
        time_t_.tm_min = minute;
        time_t_.tm_sec = second;
    }

    // Converts DateTime to string representation
    std::string ToString() const {
        std::tm* time_info = std::localtime(std::chrono::system_clock::to_time_t(time_point_).to_time_t());
        char buffer[80];
        std::strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", time_info);
        return std::string(buffer);
    }

    // Subtracts two DateTimes to get a TimeSpan difference
    TimeSpan operator-(const DateTime& other) const {
        auto duration = time_point_ - other.time_point_;
        auto total_seconds = std::chrono::duration_cast<std::chrono::seconds>(duration).count();
        return TimeSpan(0, 0, 0, total_seconds);
    }

private:
    std::chrono::system_clock::time_point time_point_;
    std::tm time_t_;
};

// Main function demonstrating DateTime and TimeSpan usage
int main()
{
    DateTime now(2023, 10, 1, 12, 0, 0);
    DateTime later(2023, 10, 2, 14, 30, 0);

    std::cout << "Now: " << now.ToString() << std::endl;
    std::cout << "Later: " << later.ToString() << std::endl;

    TimeSpan difference = later - now;
    std::cout << "Difference in seconds: " << difference.TotalSeconds() << std::endl;

    return 0;
}

