        intent.callObjectMethod("setAction", "(Ljava/lang/String;)Landroid/content/Intent;",
                                QAndroidJniObject::fromString("android.intent.action.GET_CONTENT").object());
        intent.callObjectMethod("setType", "(Ljava/lang/String;)Landroid/content/Intent;",
                                QAndroidJniObject::fromString("*/*").object());

        QtAndroid::startActivity(intent.object<jobject>(), 1, this);
    }

    // Handle activity result
    void handleActivityResult(int receiverRequestCode, int resultCode, const QAndroidJniObject &data) override
    {
        if (receiverRequestCode == 1 && resultCode == -1)
        {
            QAndroidJniObject uri = data.callObjectMethod("getData", "()Landroid/net/Uri;");
            if (uri.isValid())
            {
                QAndroidJniObject contentResolver = QtAndroid::androidActivity().callObjectMethod("getContentResolver", "()Landroid/content/ContentResolver;");
                QAndroidJniObject cursor = contentResolver.callObjectMethod("query", "(Landroid/net/Uri;[Ljava/lang/String;Ljava/lang/String;[Ljava/lang/String;Ljava/lang/String;)Landroid/database/Cursor;",
                                                                             uri.object<jobject>(), nullptr, nullptr, nullptr, nullptr);

                if (cursor.isValid())
                {
                    cursor.callMethod<jboolean>("moveToFirst", "()Z");
                    QAndroidJniObject columnName = QAndroidJniObject::getStaticObjectField("android/provider/OpenableColumns", "DISPLAY_NAME", "Ljava/lang/String;");
                    jint columnIndex = cursor.callMethod<jint>("getColumnIndex", "(Ljava/lang/String;)I", columnName.object<jstring>());
                    QAndroidJniObject fileName = cursor.callObjectMethod("getString", "(I)Ljava/lang/String;", columnIndex);
                    qDebug() << "Selected file:" << fileName.toString();
                }
            }
        }
    }
};

