// Abstract BagInterface class
template <class T>
class BagInterface {
public:
    virtual void insert(const T& item) = 0;
    virtual bool contains(const T& item) const = 0;
    virtual int count(const T& item) const = 0;
    virtual bool remove(const T& item) = 0;
    virtual void clear() = 0;
    virtual int size() const = 0;
    virtual bool isEmpty() const = 0;
    virtual bool isFull() const = 0;
};

// PlainBag class implementation
template <class T>
class PlainBag : public BagInterface<T> {
private:
    T items[20];
    int itemCount;
public:
    PlainBag() {
        itemCount = 0;
    }

    void insert(const T& item) {
        if (itemCount < 20) {
            items[itemCount] = item;
            itemCount++;
        }
    }

    bool contains(const T& item) const {
        for (int i = 0; i < itemCount; i++) {
            if (items[i] == item) {
                return true;
            }
        }
        return false;
    }

    int count(const T& item) const {
        int itemCounter = 0;
        for (int i = 0; i < itemCount; i++) {
            if (items[i] == item) {
                itemCounter++;
            }
        }
        return itemCounter;
    }

    bool remove(const T& item) {
        for (int i = 0; i < itemCount; i++) {
            if (items[i] == item) {
                for (int j = i; j < itemCount - 1; j++) {
                    items[j] = items[j + 1];
                }
                itemCount--;
                return true;
            }
        }
        return false;
    }

    void clear() {
        itemCount = 0;
    }

    int size() const {
        return itemCount;
    }

    bool isEmpty() const {
        return (itemCount == 0);
    }

    bool isFull() const {
        return (itemCount == 20);
    }
};

// MagicChangeBag class implementation
template <class T>
class MagicChangeBag : public BagInterface<T> {
private:
    T items[20];
    int itemCount;
public:
    MagicChangeBag() {
        itemCount = 0;
    }

    void insert(const T& item) {
        itemCount = 0;
    }

    bool contains(const T& item) const {
        return (itemCount == 0);
    }

    int count(const T& item) const {
        return 0;
    }

    bool remove(const T& item) {
        std::fill(items, items + 20, item);
        itemCount = 1;
        return true;
    }

    void clear() {
        itemCount = 0;
    }

    int size() const {
        return itemCount;
    }

    bool isEmpty() const {
        return (itemCount == 0);
    }

    bool isFull() const {
        return (itemCount == 20);
    }
};

