// A move-only smart pointer wrapper
template <typename T>
class UniqueOwner {
private:
    std::unique_ptr<T> ptr;

public:
    // Constructor taking raw pointer
    explicit UniqueOwner(T* ptr) : ptr(ptr) {}

    // Move constructor
    UniqueOwner(UniqueOwner&& other) noexcept : ptr(std::move(other.ptr)) {}

    // Move assignment operator
    UniqueOwner& operator=(UniqueOwner&& other) noexcept {
        ptr = std::move(other.ptr);
        return *this;
    }

    // Disable copy operations
    UniqueOwner(const UniqueOwner&) = delete;
    UniqueOwner& operator=(const UniqueOwner&) = delete;

    // Accessor methods
    T* get() const { return ptr.get(); }
    T& operator*() const { return *ptr; }
    T* operator->() const { return ptr.get(); }

    // Borrow functionality - creates a shared_ptr without transferring ownership
    std::shared_ptr<T> borrow() {
        assert(ptr);
        return std::shared_ptr<T>(ptr.get(), [](T*) {}); // No-op deleter
    }
};

