// Finite State Machine structure
struct FSM {
    int initial_state;
    set<int> accepted_states;
    unordered_map<int, unordered_map<char, int>> transition;

    // Check if the input string is accepted by the FSM
    bool accepts(const string& input) {
        int current_state = initial_state;
        for (char symbol : input) {
            if (transition[current_state].find(symbol) == transition[current_state].end()) {
                return false; // No transition for the symbol
            }
            current_state = transition[current_state][symbol];
        }
        // Check if final state is an accepted state
        return accepted_states.find(current_state) != accepted_states.end();
    }
};

