using json = nlohmann::json;

// Structure representing a temperature entry
struct TemperatureEntry {
    std::string location;
    double celsius;
    double altitude;
    int hour;
    std::string season;
};

// Structure representing the result after conversion
struct TemperatureResult {
    std::string location;
    double fahrenheit;
};

// Adjusts temperature based on altitude
double adjustForAltitude(double celsius, double altitude) {
    return celsius - 0.0065 * altitude;
}

// Adjusts temperature based on time of day
double adjustForTime(double celsius, int hour) {
    if (hour >= 6 && hour < 12) {
        return celsius - 1;
    } else if (hour >= 18 && hour < 24) {
        return celsius - 2;
    }
    return celsius;
}

// Adjusts temperature based on season
double adjustForSeason(double celsius, const std::string& season) {
    if (season == "summer") {
        return celsius + 2;
    } else if (season == "winter") {
        return celsius - 2;
    }
    return celsius;
}

// Converts Celsius to Fahrenheit
double celsiusToFahrenheit(double celsius) {
    return celsius * 9/5 + 32;
}

// Processes all entries and returns converted results
std::vector<TemperatureResult> convertTemperatures(const std::vector<TemperatureEntry>& data) {
    std::vector<TemperatureResult> results;
    for (const auto& entry : data) {
        double celsius = entry.celsius;
        double altitude = entry.altitude;
        int hour = entry.hour;
        std::string season = entry.season;

        double celsiusAdjusted = adjustForAltitude(celsius, altitude);
        double celsiusTimeAdjusted = adjustForTime(celsiusAdjusted, hour);
        double celsiusFinal = adjustForSeason(celsiusTimeAdjusted, season);

        double fahrenheit = celsiusToFahrenheit(celsiusFinal);
        results.push_back({entry.location, fahrenheit});
    }
    return results;
}

// Outputs results in JSON format
void outputJson(const std::vector<TemperatureResult>& results) {
    json j = results;
    std::ofstream file("results.json");
    file << std::setw(4) << j << std::endl;
}

// Outputs results in CSV format
void outputCsv(const std::vector<TemperatureResult>& results) {
    std::ofstream file("results.csv");
    file << "location,fahrenheit\n";
    for (const auto& result : results) {
        file << result.location << "," << result.fahrenheit << "\n";
    }
}

// Main function
int main()
{
    std::vector<TemperatureEntry> data = {
        {"New York", 20, 10, 10, "summer"},
        {"Los Angeles", 25, 50, 18, "winter"}
    };

    std::vector<TemperatureResult> results = convertTemperatures(data);
    outputJson(results);
    outputCsv(results);

    return 0;

}

