LoadLibraryFunc real_LoadLibrary = (LoadLibraryFunc)GetProcAddress(GetModuleHandleA("kernel32.dll"), "LoadLibraryA");
GetProcAddressFunc real_GetProcAddress = (GetProcAddressFunc)GetProcAddress(GetModuleHandleA("kernel32.dll"), "GetProcAddress");

// Hooked LoadLibraryA function
HMODULE WINAPI MyLoadLibraryA(LPCSTR lpLibFileName)
{
    HMODULE hModule = real_LoadLibrary(lpLibFileName);
    if (hModule)
    {
        OutputDebugStringA("Loaded library: ");
        OutputDebugStringA(lpLibFileName);
