}

// Hooked GetProcAddress function
FARPROC WINAPI MyGetProcAddress(HMODULE hModule, LPCSTR lpProcName)
{
    FARPROC procAddr = real_GetProcAddress(hModule, lpProcName);
    if (procAddr)
    {
        OutputDebugStringA("Resolved function: ");
        OutputDebugStringA(lpProcName);
        OutputDebugStringA("\n");
    }
    return procAddr;
}

// DLL entry point
BOOL APIENTRY DllMain(HMODULE hModule, DWORD ul_reason_for_call, LPVOID lpReserved)
{
    switch (ul_reason_for_call)
    {
    case DLL_PROCESS_ATTACH:
        // Attach hooks using Detours
        DetourTransactionBegin();
        DetourUpdateThread(GetCurrentThread());
        DetourAttach(&(PVOID&)real_LoadLibrary, MyLoadLibraryA);
        DetourAttach(&(PVOID&)real_GetProcAddress, MyGetProcAddress);
        DetourTransactionCommit();
        break;

    case DLL_PROCESS_DETACH:
        // Detach hooks using Detours
        DetourTransactionBegin();
        DetourUpdateThread(GetCurrentThread());
        DetourDetach(&(PVOID&)real_LoadLibrary, MyLoadLibraryA);
        DetourDetach(&(PVOID&)real_GetProcAddress, MyGetProcAddress);
        DetourTransactionCommit();
        break;
    }
    return TRUE;
}

