// Function to handle RC input changes
void onRCInputChange()
{
    static unsigned long lastPulseTime = 0;
    static int lastMode = -1;

    // Read the pulse duration of the receiver input signal
    unsigned long pulseDuration = pulseInLong(RC_INPUT_PIN, HIGH, 20000);

    if (pulseDuration != 0)
    {
        if (pulseDuration > 1100 && pulseDuration < 1400)
        {
            mode = 0; // Position 1 on the switch
        }
        else if (pulseDuration > 1500 && pulseDuration < 1800)
        {
            mode = 1; // Position 2 on the switch
        }
        else if (pulseDuration > 1900 && pulseDuration < 2100)
        {
            mode = 2; // Position 3 on the switch
        }

        // Only update the mode if it has changed
        if (lastMode != mode)
        {
            lastMode = mode;

            // Reset the fire simulation
            memset(heat, 0, sizeof(heat));
        }

        lastPulseTime = millis();
    }

    // If no pulse has been received for more than 1 second, assume the switch is off
    if (millis() - lastPulseTime > 1000)
    {
        mode = 0; // Position 1 on the switch
        lastMode = mode;

        // Reset the fire simulation
        memset(heat, 0, sizeof(heat));
    }
}

