   // Main function for shared memory image handling
   int main()
   {
       // Create a shared memory file
       const char* shm_name = "/cv_image_shm";
       int shm_fd = shm_open(shm_name, O_CREAT | O_RDWR, 0666);
       if (shm_fd == -1)
       {
           perror("shm_open");
           return 1;
       }

       // Set the size of the shared memory segment
       const int img_width = 640;
       const int img_height = 480;
       const int img_channels = 3;
       const size_t img_size = img_width * img_height * img_channels;
       ftruncate(shm_fd, img_size);

       // Map the shared memory segment to the address space
       void* img_data = mmap(0, img_size, PROT_WRITE, MAP_SHARED, shm_fd, 0);
       if (img_data == MAP_FAILED)
       {
           perror("mmap");
           return 1;
       }

       // Capture an image using OpenCV
       cv::Mat image(img_height, img_width, CV_8UC3, img_data);
       cv::VideoCapture cap(0);
       if (!cap.isOpened())
       {
           std::cerr << "Error opening video stream" << std::endl;
           return 1;
       }
       cap >> image;

       // Close the shared memory file descriptor
       munmap(img_data, img_size);
       close(shm_fd);

       return 0;

   }

