using namespace std;

// Define a structure for the graph
struct Edge {
    int to;      // Destination node
    int weight;  // Weight of the edge
};

// Function to add an edge to the graph
void addEdge(vector<vector<Edge>>& graph, int from, int to, int weight) {
    graph[from].push_back({to, weight});
}

// Dijkstra's algorithm to find the shortest path
vector<int> dijkstra(const vector<vector<Edge>>& graph, int start, int end) {
    int n = graph.size();
    vector<int> dist(n, numeric_limits<int>::max());
    vector<int> prev(n, -1);
    dist[start] = 0;

    // Priority queue to store (distance, node) pairs
    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;
    pq.push({0, start});

    while (!pq.empty()) {
        int u = pq.top().second;
        int d = pq.top().first;
        pq.pop();

        // If we reached the end node, break
        if (u == end) break;

        // If a shorter path to u has already been found, skip it
        if (d > dist[u]) continue;

        // Relax all edges from u
        for (const Edge& edge : graph[u]) {
            int v = edge.to;
            int weight = edge.weight;
            if (dist[u] + weight < dist[v]) {
                dist[v] = dist[u] + weight;
                prev[v] = u;
                pq.push({dist[v], v});
            }
        }
    }

    // Reconstruct the path
    vector<int> path;
    for (int at = end; at != -1; at = prev[at]) {
        path.push_back(at);
    }
    reverse(path.begin(), path.end());

    return path;
}

int main()
{
    // Example graph
    int n = 5;  // Number of nodes
    vector<vector<Edge>> graph(n);

    // Add edges
    addEdge(graph, 0, 1, 10);
    addEdge(graph, 0, 2, 5);
    addEdge(graph, 1, 2, 2);
    addEdge(graph, 1, 3, 1);
    addEdge(graph, 2, 1, 3);
    addEdge(graph, 2, 3, 9);
    addEdge(graph, 2, 4, 2);
    addEdge(graph, 3, 4, 4);

    // Find the shortest path from node 0 to node 4
    vector<int> path = dijkstra(graph, 0, 4);

    // Print the path
    cout << "Shortest path: ";
    for (int node : path) {
        cout << node << " ";
    }
    cout << endl;

    return 0;

}

