// LED configuration
#define LED_PIN 6
#define NUM_LEDS 22
#define BUTTON_PIN 2

Adafruit_NeoPixel strip = Adafruit_NeoPixel(NUM_LEDS, LED_PIN, NEO_GRB + NEO_KHZ800);

const int buttonPin = BUTTON_PIN;
int buttonState = 0;
int mode = 0;

void setup()
{
    strip.begin();
    strip.show();

    pinMode(buttonPin, INPUT_PULLUP);
}

void loop()
{
    buttonState = digitalRead(buttonPin);

    if (buttonState == LOW)
    {
        mode++;

        if (mode > 2)
        {
            mode = 0;
        }

        delay(200);
    }

    switch (mode)
    {
        case 0:
            flameEffect(255, 100, 0); // Normal fire color (Mode A)
            break;
        case 1:
            flameEffect(0, 255, 0); // Green/yellow flame with more green than yellow (Mode B)
            break;
        case 2:
            flameEffect(0, 0, 255); // Blue/white flame (Mode C)
            break;
    }
}

// Flame effect function
void flameEffect(int red, int green, int blue)
{
    for (int i = 0; i < NUM_LEDS; i++)
    {
        int flicker = random(70, 255);
        strip.setPixelColor(i, flicker * red / 255, flicker * green / 255, flicker * blue / 255);
    }
    strip.show();
    delay(random(25, 50));
}

