// Calculates the inverse square root using fast approximation
float InvSqrt(float x)
{
    float halfx = 0.5f * x;
    int i = *(int*)&x;  // evil floating point bit level hacking
    i = 0x5f3759df - (i >> 1);  // what the fuck?
    x = *(float*)&i;
    // Newton's method refinement
    x = x * (1.5f - (halfx * x * x));
    return x;
}

#include <iostream>

// Creates and processes an image using CUDA texture memory
int main()
{
    // Assume width and height are defined somewhere before this
    int width = 640;
    int height = 480;

    IplImage *image = cvCreateImage(cvSize(width, height), IPL_DEPTH_8U, 3);
    unsigned char* imageDataArray = (unsigned char*)image->imageData;

    texture<unsigned char, 2, cudaReadModeElementType> tex;
    cudaChannelFormatDesc channelDesc = cudaCreateChannelDesc(8, 8, 8, 0, cudaChannelFormatKindUnsigned); 
    cudaArray *cuArray = NULL;
    cudaMallocArray(&cuArray, &channelDesc, width, height);

    cudaMemcpy2DToArray(cuArray, 0, 0, imageDataArray, image->widthstep, width * 3, height, cudaMemcpyHostToDevice);
    cudaBindTextureToArray(tex, cuArray, channelDesc);

    __global__ void processImageKernel(unsigned char* output, int width, int height) {
        int X = blockIdx.x * blockDim.x + threadIdx.x;
        int Y = blockIdx.y * blockDim.y + threadIdx.y;

        if (X < width && Y < height) {
            unsigned char red   = tex2D(tex, X, Y * 3 + 0); // Red channel
            unsigned char green = tex2D(tex, X, Y * 3 + 1); // Green channel
            unsigned char blue  = tex2D(tex, X, Y * 3 + 2); // Blue channel

            // Process the pixel (e.g., store it in the output array)
            output[(Y * width + X) * 3 + 0] = red;
            output[(Y * width + X) * 3 + 1] = green;
            output[(Y * width + X) * 3 + 2] = blue;
        }
    }

    // Allocate and initialize output array
    unsigned char* d_output;
    cudaMalloc(&d_output, width * height * 3 * sizeof(unsigned char));

    // Define block and grid dimensions
    dim3 blockSize(16, 16);
    dim3 gridSize((width + blockSize.x - 1) / blockSize.x, (height + blockSize.y - 1) / blockSize.y);

    // Launch the kernel
    processImageKernel<<<gridSize, blockSize>>>(d_output, width, height);

    // Copy the result back to host
    unsigned char* h_output = new unsigned char[width * height * 3];
    cudaMemcpy(h_output, d_output, width * height * 3 * sizeof(unsigned char), cudaMemcpyDeviceToHost);

    // Clean up
    cudaFree(d_output);
    cudaFreeArray(cuArray);
    cudaUnbindTexture(tex);

    // Use h_output as needed
    delete[] h_output;

    return 0;
}

