// Expression base class
class Expression {
public:
    virtual ~Expression() {}
    virtual double evaluate() const = 0;
};

// Number leaf node
class Number : public Expression {
private:
    double value;
public:
    Number(double val) : value(val) {}
    double evaluate() const override { return value; }
};

// Binary operation node
class BinaryExpression : public Expression {
private:
    Expression* left;
    Expression* right;
    char op;
public:
    BinaryExpression(Expression* l, char o, Expression* r) : left(l), op(o), right(r) {}
    ~BinaryExpression() {
        delete left;
        delete right;
    }
    double evaluate() const override {
        double lval = left->evaluate();
        double rval = right->evaluate();
        switch (op) {
            case '+': return lval + rval;
            case '-': return lval - rval;
            case '*': return lval * rval;
            case '/': return lval / rval;
            default: throw std::runtime_error("Unknown operator");
        }
    }
};

template <>
class Vector {
public:
    // Accessors for specific indices
    double at<1>() const { return data[0]; }
    double at<2>() const { return data[1]; }
    double at<4>() const { return data[2]; }
    double at<8>() const { return data[3]; }

    // Specialized dot product implementation
    double dot(const Vector& other) const {
        return at<1>() * other.at<1>() +
               at<2>() * other.at<2>() +
               at<4>() * other.at<4>() +
               at<8>() * other.at<8>();
    }

private:
    double data[4];
};

