#include <RTClib.h>

RTC_DS3231 rtc;

const int alarmHour = 7;
const int alarmMinute = 0;
const int buzzerPin = 8;

// Setup function initializes the system
void setup()
{
    Serial.begin(9600);

    // Initialize RTC
    if (!rtc.begin()) 
    {
        Serial.println("Couldn't find RTC");
        while (1);
    }

    // Check if RTC lost power and set time accordingly
    if (rtc.lostPower()) 
    {
        Serial.println("RTC lost power, let's set the time!");
        rtc.adjust(DateTime(F(__DATE__), F(__TIME__)));
    }

    pinMode(buzzerPin, OUTPUT);
}

// Main loop runs continuously
void loop()
{
    DateTime now = rtc.now();

    // Display current time
    Serial.print("Current time: ");
    Serial.print(now.hour(), DEC);
    Serial.print(':');
    Serial.print(now.minute(), DEC);
    Serial.print(':');
    Serial.print(now.second(), DEC);
    Serial.println();

    // Check if it's alarm time
    if (now.hour() == alarmHour && now.minute() == alarmMinute)
    {
        Serial.println("Alarm time!");
        digitalWrite(buzzerPin, HIGH);
        delay(10000); // Buzz for 10 seconds
        digitalWrite(buzzerPin, LOW);
    }

    delay(1000); // Wait a second before checking the time again
}

