// MathClampAssembler class for clamping integer values
class MathClampAssembler : public CodeStubAssembler {
 public:
  // Constructor
  MathClampAssembler(Zone* zone, Isolate* isolate)
      : CodeStubAssembler(zone, isolate, Code::STUB, kNoCallSiteDetails) {}

  // Clamp value between min and max
  Node* Clamp(Node* value, Node* min, Node* max) {
    // Compare value with min
    Node* value_ge_min = this->Int32GreaterThanOrEqual(value, min);

    // If value is less than min, set value to min
    Node* clamped_value = this->ChangeInt32ToInt32(
        this->SelectInt32(this->BooleanNot(value_ge_min), min, value));

    // Compare clamped_value with max
    Node* clamped_value_le_max = this->Int32LessThanOrEqual(clamped_value, max);

    // If clamped_value is greater than max, set clamped_value to max
    Node* final_clamped_value = this->ChangeInt32ToInt32(
        this->SelectInt32(this->BooleanNot(clamped_value_le_max), max, clamped_value));

    return final_clamped_value;
  }
};

