#define maxObjects 1024

struct VEC2_f {
    float x, y;

    VEC2_f(float x, float y) : x(x), y(y) {}
    VEC2_f() : x(0.0f), y(0.0f) {}
};

struct OBJR {
    VEC2_f pos, vel;
    int ID = -1;
    std::shared_ptr<bitmap_image> Lbmp;

    OBJR(std::shared_ptr<bitmap_image> Lbmp, VEC2_f pos, VEC2_f vel) : Lbmp(Lbmp), pos(pos), vel(vel) {}

    OBJR(std::shared_ptr<bitmap_image> Lbmp, float x, float y, float vx, float vy) : Lbmp(Lbmp), pos(x, y), vel(vx, vy) {}

    int getID() const { return ID; }
};

std::vector<std::shared_ptr<OBJR>> objRID;
int IDCOUNTER = 0;
bool running = true;
HWND con;
HDC dc;
COLORREF color;

// Initialize an object and add it to the list
void objInit(std::shared_ptr<OBJR> Lobj)
{
    if(objRID.size() > maxObjects)
    {
        objRID.pop_back();
        Lobj->ID = maxObjects;
    }
    Lobj->ID = IDCOUNTER++;
    objRID.push_back(Lobj);
}

void input() {}

void update() {}

// Linear interpolation for position based on velocity and interpolation factor
VEC2_f interpolate(float interpolation, VEC2_f pos, VEC2_f vel)
{
    return VEC2_f(pos.x + (vel.x * interpolation), pos.y + (vel.y * interpolation));
}

// Render a bitmap at the specified interpolated position
void renderBitmap(std::shared_ptr<bitmap_image> Lbmp, VEC2_f Ipos)
{
    unsigned int h, w;
    rgb_t colorT;
    h = Lbmp->height();
    w = Lbmp->width();

    for(unsigned int y = 0; y < h; y++)
    {
        for(unsigned int x = 0; x < w; x++)
        {
            colorT = Lbmp->get_pixel(x, y);
            color = RGB(colorT.red, colorT.green, colorT.blue);
            SetPixelV(dc, x + Ipos.x, y + Ipos.y, color);
        }
    }
}

// Render a single object using interpolation
void renderOBJR(float interpolation, std::shared_ptr<OBJR> obj)
{
    renderBitmap(obj->Lbmp, interpolate(interpolation, obj->pos, obj->vel));
}

// Render all objects
void render(float interpolation)
{
    for(const auto& obj : objRID)
    {
        renderOBJR(interpolation, obj);
    }
}

// Resize window to fixed dimensions
void resizeWindow()
{
    RECT r;
    GetWindowRect(con, &r);
    MoveWindow(con, r.left, r.top, 800, 600, true);
}

// Initialization function
int init()
{
    con = GetConsoleWindow();
    dc = GetDC(con);
    resizeWindow();
    return 0;
}

// Main game loop
int loop()
{
    const int TPS = 60;
    const int SKIP_TICKS = 1000 / TPS;
    const int FRAMESKIP = 1;

    DWORD next_tick = GetTickCount();
    float interpolation;
    int loop_count;

    while(running)
    {
        loop_count = 0;
        while(GetTickCount() > next_tick && loop_count < FRAMESKIP)
        {
            input();
            update();

            next_tick += SKIP_TICKS;
            loop_count++;
        }
        interpolation = float(GetTickCount() + SKIP_TICKS - next_tick) / float(SKIP_TICKS);
        render(interpolation);
    }
    return 0;
}

// Cleanup function
int deInit()
{
    ReleaseDC(con, dc);
    return 0;
}

