// Function to check if two strings are anagrams
bool areAnagrams(std::string s1, std::string s2)
{
    // If lengths differ, they can't be anagrams
    if(s1.length() != s2.length())
    {
        return false;
    }
    // Sort both strings
    std::sort(s1.begin(), s1.end());
    std::sort(s2.begin(), s2.end());
    // Compare sorted strings
    return s1 == s2;
}

int main()
{
    std::string s1 = "listen";
    std::string s2 = "silent";
    // Output whether the strings are anagrams
    std::cout<<std::boolalpha<<areAnagrams(s1, s2)<<std::endl;
    return 0;

}

typedef unsigned long U32;

// Exported function to read file data
extern "C" __declspec(dllexport) int ReadFile(LPSTR Path, U32** DataPtr, U32* Count)
{
    FILE *fp;
    U32 *Data;
    CString tempStr(Path);
    long fSize;

    // Open file in binary mode
    if (!(fp = fopen(tempStr, "rb")))
    {
        return 0;
    }

    // Obtain File Size
    fseek(fp, 0, SEEK_END);
    fSize = ftell(fp);
    rewind(fp);

    // Ensure fSize is a multiple of sizeof(U32)
    if (fSize % sizeof(U32) != 0)
    {
        fclose(fp);
        return -3; // File size is not a multiple of sizeof(U32)
    }

    // Allocate memory
    Data = (U32 *)malloc(fSize);
    if (Data == NULL)
    {
        fclose(fp);
        return -1;
    }

    // Copy file into the buffer
    *Count = fread(Data, sizeof(U32), fSize / sizeof(U32), fp);
    if (*Count == 0)
    {
        fclose(fp);
        free(Data);
        return -2;
    }

    *DataPtr = Data;
    fclose(fp);
    return 1;
}

#include <iostream>
#include <vector>
#include <string>

// Function to find the longest common subsequence
std::string longestCommonSubsequence(const std::string& X, const std::string& Y)
{
    int m = X.length();
    int n = Y.length();

    // Create a 2D DP table
    std::vector<std::vector<int>> dp(m + 1, std::vector<int>(n + 1, 0));

    // Fill the DP table
    for(int i=1;i<=m;++i)
    {
        for(int j=1;j<=n;++j)
        {
            if(X[i-1] == Y[j-1])
            {
                dp[i][j] = dp[i-1][j-1] + 1;
            }
            else
            {
                dp[i][j] = std::max(dp[i-1][j], dp[i][j-1]);
            }
        }
    }

    // Reconstruct the LCS
    std::string lcs;
    int i = m, j = n;
    while(i > 0 && j > 0)
    {
        if(X[i-1] == Y[j-1])
        {
            lcs = X[i-1] + lcs;
            --i;
            --j;
        }
        else if(dp[i-1][j] > dp[i][j-1])
        {
            --i;
        }
        else
        {
            --j;
        }
    }

    return lcs;
}

// Main function to test the LCS function
int main()
{
    std::string X = "ABCBDAB";
    std::string Y = "BDCAB";

    std::string lcs = longestCommonSubsequence(X, Y);
    std::cout<<"The longest common subsequence of \""<<X<<"\" and \""<<Y<<"\" is: "<<lcs<<std::endl;

    return 0;

}

