#ifndef ATOMIC_UTILS_H
#define ATOMIC_UTILS_H

#include <cstddef>

// Atomic utility class for lock-free operations
class AtomicUtils
{
public:
    /**
     * check if the value at addr is equal to oldval, if so replace it with newval
     * and return the oldval
     */
    static size_t compareAndExchange(volatile size_t* addr, size_t oldval, size_t newval)
    {
        size_t ret;
        __asm__ volatile(
            "lock cmpxchgq %2, %1\n\t"
            : "=a"(ret), "+m"(*addr)
            : "r"(newval), "0"(oldval)
            : "memory"
        );
        return ret;
    }
};

#endif

