#include <cstdint>
#include <atomic>

// Constants and definitions
static constexpr std::uint64_t NO_INDEX = ~std::uint64_t(0);

class AtomicBitMap {
public:
    // Returns a mask with all bits set (fully occupied)
    static constexpr std::uint64_t occupied() noexcept {
        return ~std::uint64_t(0);
    }

    // Acquires a free bit index atomically
    std::uint64_t acquire() noexcept {
        while (true) {
            auto map = mData.load(std::memory_order_relaxed);
            if (map == occupied()) {
                return NO_INDEX;
            }

            std::uint64_t index = __builtin_ctzl(~map);
            auto previous =
                mData.fetch_or(bit(index), std::memory_order_acq_rel);
            if ((previous & bit(index)) == 0) {
                return index;
            }
        }
    }

private:
    // Generates a bitmask for the given index
    static constexpr std::uint64_t bit(std::uint64_t index) noexcept {
        return std::uint64_t(1) << index;
    }

    std::atomic_uint64_t mData{ 0 };
};

// Main function
int main()
{
    AtomicBitMap map;
    return map.acquire();
}

