// TaskScheduler class for scheduling tasks at intervals
class TaskScheduler {
public:
    TaskScheduler() : stop(false) {}

    // Schedule a task to run at a specific interval
    void schedule(std::function<void()> task, std::chrono::milliseconds interval)
    {
        {
            std::unique_lock<std::mutex> lock(mutex);
            tasks.push({task, interval, std::chrono::steady_clock::now()});
        }
        cv.notify_one();
    }

    // Start the scheduler
    void start()
    {
        for (int i = 0; i < num_threads; ++i) {
            workers.emplace_back(&TaskScheduler::run, this);
        }
    }

    // Stop the scheduler
    void stop_scheduler()
    {
        {
            std::unique_lock<std::mutex> lock(mutex);
            stop = true;
        }
        cv.notify_all();
        for (std::thread &worker : workers) {
            worker.join();
        }
    }

private:
    struct TaskInfo {
        std::function<void()> task;
        std::chrono::milliseconds interval;
        std::chrono::steady_clock::time_point next_run;
    };

    void run()
    {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex);
            cv.wait(lock, [this] { return stop || !tasks.empty(); });

            if (stop && tasks.empty()) {
                return;
            }

            auto now = std::chrono::steady_clock::now();
            while (!tasks.empty() && tasks.top().next_run <= now) {
                TaskInfo task_info = tasks.top();
                tasks.pop();

                lock.unlock();
                task_info.task();
                lock.lock();

                if (!stop) {
                    task_info.next_run += task_info.interval;
                    tasks.push(task_info);
                }
            }

            if (!tasks.empty()) {
                auto next_run_time = tasks.top().next_run;
                auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(next_run_time - now);
                cv.wait_for(lock, duration);
            }
        }
    }

    std::vector<std::thread> workers;
    std::mutex mutex;
    std::condition_variable cv;
    std::priority_queue<TaskInfo, std::vector<TaskInfo>, std::function<bool(TaskInfo, TaskInfo)>> tasks{
        [](const TaskInfo &a, const TaskInfo &b) { return a.next_run > b.next_run; }
    };
    bool stop;
    const int num_threads = 4; // Number of worker threads
};

// Example task function
void print_message(const std::string &message)
{
    std::cout << message << std::endl;
}

int main()
{
    TaskScheduler scheduler;
    scheduler.schedule(std::bind(print_message, "Task 1"), std::chrono::milliseconds(1000));
    scheduler.schedule(std::bind(print_message, "Task 2"), std::chrono::milliseconds(500));

    scheduler.start();

    std::this_thread::sleep_for(std::chrono::seconds(10));

    scheduler.stop_scheduler();

    return 0;

}

