class IRGenerator {
public:
    // Generates assembly code from a node
    std::string generateAssembly(Node* n)
    {
        std::string assembly = "";
        std::string ir = lowerToIR(n);
        assembly = emitAssembly(ir);
        return assembly;
    }

private:
    // Converts AST node to intermediate representation
    std::string lowerToIR(Node* n)
    {
        if (n->type == Node::IF) {
            std::string ir = "";
            ir += lowerToIR(n->getChild(0));  // Process condition
            ir += "if ";
            ir += n->getChild(0)->value;    // Extract condition value
            ir += " goto .true" + std::to_string(nLabels++) + "\n";
            ir += "goto .false" + std::to_string(nLabels - 1) + "\n";
            ir += ".true" + std::to_string(nLabels - 1) + ":\n";
            ir += lowerToIR(n->getChild(1));  // Process true block
            ir += ".false" + std::to_string(nLabels - 1) + ":\n";
            return ir;
        }
        // Handle other node types as needed
        return "";
    }

    // Emits assembly from intermediate representation
    std::string emitAssembly(const std::string& ir)
    {
        std::string assembly = "";
        // Convert IR to assembly line by line
        for (const std::string& line : split(ir, '\n')) {
            if (line.find("if") != std::string::npos) {
                assembly += "cmp ...\n";
                assembly += "jnz .true" + extractLabel(line) + "\n";
                assembly += "jmp .false" + extractLabel(line) + "\n";
            } else if (line.find("goto") != std::string::npos) {
                assembly += "jmp " + extractLabel(line) + "\n";
            } else if (line.find(".true") != std::string::npos || line.find(".false") != std::string::npos) {
                assembly += line + ":\n";
            } else {
                assembly += line + "\n";
            }
        }
        return assembly;
    }

    // Splits a string by a delimiter character
    std::vector<std::string> split(const std::string& s, char delimiter)
    {
        std::vector<std::string> tokens;
        std::string token;
        std::istringstream tokenStream(s);
        while (getline(tokenStream, token, delimiter)) {
            tokens.push_back(token);
        }
        return tokens;
    }

    // Extracts the label portion from an IR line
    std::string extractLabel(const std::string& line)
    {
        // Find last space and extract everything after it
        return line.substr(line.find_last_of(" ") + 1);
    }

    int nLabels = 0;
};

