typedef struct {
    float re;
    float im;
} dcmplx;

// Complex convolution function using inline assembly
dcmplx ComplexConv(int len, dcmplx *hat, dcmplx *buf)
{
    int    i;
    dcmplx    z, xout;

    // Initialize output to zero
    xout.re = xout.im = 0.0;

    asm volatile (
        "movs r3, #0\n\t"
        ".loop:\n\t"
        "vldr s11, [%[hat], #4]\n\t"
        "vldr s13, [%[hat]]\n\t"
        "vneg.f32 s11, s11\n\t"
        "vldr s15, [%[buf], #4]\n\t"
        "vldr s12, [%[buf]]\n\t"
        "vmul.f32 s14, s15, s13\n\t"
        "vmul.f32 s15, s11, s15\n\t"
        "adds %[hat], #8\n\t"
        "vmla.f32 s14, s11, s12\n\t"
        "vnmls.f32 s15, s12, s13\n\t"
        "adds %[buf], #8\n\t"
        "vadd.f32 s1, s1, s14\n\t"
        "vadd.f32 s0, s0, s15\n\t"
        "adds r3, r3, #1\n\t"
        "cmp r3, r0\n\t"
        "bne .loop\n\t"
        "vstr s1, [%[xout], #4]\n\t"
        "vstr s0, [%[xout]]\n\t"
        : [xout]"+r"(xout), [hat]"+r"(hat), [buf]"+r"(buf)
        : "r"(len)
        : "s0", "s1", "s11", "s12", "s13", "s14", "s15", "r3", "cc", "memory"
    );

    return xout;
}

