    std::string tmp;
    ss >> tmp; // Skip the "cpu" label
    while (ss >> tmp)
    {
        values.push_back(std::stol(tmp));
    }
    return values;
}

// Calculates CPU usage based on previous and current readings
double calculateCPUUsage(const std::vector<long>& prev, const std::vector<long>& curr)
{
    long prevTotal = 0, currTotal = 0;
    for(int i=0;i<prev.size();++i)
    {
        prevTotal += prev[i];
        currTotal += curr[i];
    }
    long totalDiff = currTotal - prevTotal;

    long prevIdle = prev[3];
    long currIdle = curr[3];
    long idleDiff = currIdle - prevIdle;

    return (1.0 - (idleDiff / static_cast<double>(totalDiff))) * 100.0;
}

// Prints current CPU usage percentage
void printCPUUsage()
{
    auto prev = readCPUUsage();
    std::this_thread::sleep_for(std::chrono::seconds(1));
    auto curr = readCPUUsage();
    double usage = calculateCPUUsage(prev, curr);
    std::cout << "CPU Usage: " << usage << "%" << std::endl;
}

