// Function to compute the base-2 logarithm of an integer
static inline int log2(int x)
{
#if defined(__x86_64__) || defined(__i386__)
    // x86 and x86_64 architecture
    int ret;
    asm("bsr %1, %0\n"
        : "=r"(ret)
        : "r"(x)
        : "cc");
    return ret;
#elif defined(__arm__) || defined(__aarch64__)
    // ARM and AArch64 architecture
    if (x == 0) return -1; // Handle the case where x is 0
    int ret;
    asm("clz %0, %1\n"
        : "=r"(ret)
        : "r"(x));
    return 31 - ret;
#else
    // Fallback to a portable C++ implementation
    if (x == 0) return -1; // Handle the case where x is 0
    int ret = 0;
    while ((x >> ret) > 1) {
        ret++;
    }
    return ret;
#endif
}

