// Structure to hold a 2D point
struct point  
{  
    double x, y;  
};

// Kernel function to set point coordinates
__global__ void MyFunc(point* d_a)  
{  
    if (threadIdx.x == 0 && threadIdx.y == 0)
    {  
        d_a->x = 100.0;  
        d_a->y = 100.0;    
    }
}  

int main()  
{  
    // Allocate host memory
    point *a = (point*)malloc(sizeof(point));  
    a->x = 10.0;   
    a->y = 10.0;    

    // Allocate device memory
    point *d_a;  
    cudaMalloc((void**)&d_a, sizeof(point));  

    // Copy data from host to device
    cudaMemcpy(d_a, a, sizeof(point), cudaMemcpyHostToDevice);  

    // Define grid and block dimensions
    dim3 dimblock(16, 16);  
    dim3 dimgrid(1, 1);  

    // Launch kernel
    MyFunc<<<dimgrid, dimblock>>>(d_a);  

    // Ensure kernel completion before copying back results
    cudaDeviceSynchronize();  

    // Copy result back to host
    cudaMemcpy(a, d_a, sizeof(point), cudaMemcpyDeviceToHost);    
    std::cout << a->x << " " << a->y << std::endl;

    // Free allocated memory
    cudaFree(d_a);
    free(a);

    return 0;
}

