#include <cuda_runtime.h>
#include <iostream>

// Kernel function to read from texture and write to output
__global__ void textureKernel(cudaTextureObject_t texObj, float *output, int width, int height)
{
    int x = blockIdx.x * blockDim.x + threadIdx.x;
    int y = blockIdx.y * blockDim.y + threadIdx.y;

    if(x < width && y < height)
    {
        float value = tex2D<float>(texObj, x, y);
        output[y * width + x] = value;
    }
}

int main()
{
    // Device data pointers
    float *d_data;
    cudaTextureObject_t texObj;
    float *d_output;

    // Example dimensions for the texture
    int width = 256;
    int height = 256;

    // Allocate device memory for input and output
    size_t size = width * height * sizeof(float);
    cudaMalloc(&d_data, size);
    cudaMalloc(&d_output, size);

    // Initialize device data (set to zero for this example)
    cudaMemset(d_data, 0, size);

    // Setup resource descriptor for linear memory
    cudaResourceDesc resourceDesc;
    memset(&resourceDesc, 0, sizeof(resourceDesc));
    resourceDesc.resType = cudaResourceTypeLinear;
    resourceDesc.res.linear.devPtr = d_data;
    resourceDesc.res.linear.desc.f = cudaChannelFormatKindFloat;
    resourceDesc.res.linear.desc.x = 32; // 32 bits per channel (float)
    resourceDesc.res.linear.sizeInBytes = size;

    // Setup texture descriptor
    cudaTextureDesc textureDesc;
    memset(&textureDesc, 0, sizeof(textureDesc));
    textureDesc.readMode = cudaReadModeElementType;
    textureDesc.addressMode[0] = cudaAddressModeClamp;
    textureDesc.addressMode[1] = cudaAddressModeClamp;
    textureDesc.filterMode = cudaFilterModeLinear;

    // Create CUDA texture object
    cudaCreateTextureObject(&texObj, &resourceDesc, &textureDesc, NULL);

    // Define kernel launch configuration
    dim3 blockSize(16, 16);
    dim3 gridSize((width + blockSize.x - 1) / blockSize.x, (height + blockSize.y - 1) / blockSize.y);

    // Launch the kernel
    textureKernel<<<gridSize, blockSize>>>(texObj, d_output, width, height);
    cudaDeviceSynchronize();

    // Copy results back to host
    float *h_output = new float[width * height];
    cudaMemcpy(h_output, d_output, size, cudaMemcpyDeviceToHost);

    // Cleanup resources
    cudaDestroyTextureObject(texObj);
    cudaFree(d_data);
    cudaFree(d_output);
    delete[] h_output;

    return 0;
}

