#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <limits>

// 3D point structure
struct Point3D {
    double x, y, z;

    Point3D(double x, double y, double z) : x(x), y(y), z(z) {}

    // Calculate Euclidean distance to another point
    double distanceTo(const Point3D &other) const {
        return std::sqrt((x - other.x) * (x - other.x) +
                         (y - other.y) * (y - other.y) +
                         (z - other.z) * (z - other.z));
    }
};

// Comparison functions for sorting
bool compareX(const Point3D &p1, const Point3D &p2) {
    return p1.x < p2.x;
}

bool compareY(const Point3D &p1, const Point3D &p2) {
    return p1.y < p2.y;
}

bool compareZ(const Point3D &p1, const Point3D &p2) {
    return p1.z < p2.z;
}

// Helper function to find minimum of two doubles
double min(double a, double b) {
    return (a < b) ? a : b;
}

// Brute force closest pair algorithm for small n
double bruteForce(std::vector<Point3D> &points, int n) {
    double min_dist = std::numeric_limits<double>::max();
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            double dist = points[i].distanceTo(points[j]);
            if (dist < min_dist) {
                min_dist = dist;
            }
        }
    }
    return min_dist;
}

// Find closest points in the strip
double stripClosest(std::vector<Point3D> &strip, int size, double d) {
    double min_dist = d;

    // Check points within vertical distance d
    for (int i = 0; i < size; ++i) {
        for (int j = i + 1; j < size && (strip[j].y - strip[i].y) < min_dist; ++j) {
            double dist = strip[i].distanceTo(strip[j]);
            if (dist < min_dist) {
                min_dist = dist;
            }
        }
    }
    return min_dist;
}

// Recursive utility function for divide and conquer
double closestUtil(std::vector<Point3D> &Px, std::vector<Point3D> &Py, int n) {
    // Base case: use brute force for small number of points
    if (n <= 3) return bruteForce(Px, n);

    // Divide points
    int mid = n / 2;
    Point3D midPoint = Px[mid];

    // Split Py into left and right based on x-coordinate
    std::vector<Point3D> Pyl, Pyr;
    for (int i = 0; i < n; i++) {
        if (Py[i].x <= midPoint.x) Pyl.push_back(Py[i]);
        else Pyr.push_back(Py[i]);
    }

    // Recursively find minimum distance in left and right halves
    double dl = closestUtil(Px, Pyl, mid);
    double dr = closestUtil(Px, Pyr, n - mid);

    // Find smaller of the two distances
    double d = min(dl, dr);

    // Build strip of points within distance d of the dividing line
    std::vector<Point3D> strip;
    for (int i = 0; i < n; i++) {
        if (std::abs(Py[i].x - midPoint.x) < d) {
            strip.push_back(Py[i]);
        }
    }

    // Find closest points in strip and return overall minimum
    return min(d, stripClosest(strip, strip.size(), d));
}

// Main function to find closest pair of points
double closest(std::vector<Point3D> &points, int n) {
    std::vector<Point3D> Px = points;
    std::vector<Point3D> Py = points;

    // Sort points by x and y coordinates
    std::sort(Px.begin(), Px.end(), compareX);
    std::sort(Py.begin(), Py.end(), compareY);

    return closestUtil(Px, Py, n);
}

// Main entry point
int main() {
    // Test points
    std::vector<Point3D> points = {{2, 3, 4}, {12, 30, 40}, {40, 50, 60}, {5, 1, 2}, {12, 10, 3}};
    int n = points.size();

    // Output result
    std::cout << "The smallest distance is " << closest(points, n) << std::endl;
    return 0;
}

