// Disassembles the given byte array using Capstone
std::string disassembly(uint8_t *bytearray, long size, uint64_t startAddress)
{
    csh handle;
    cs_insn *insn;
    size_t count;
    std::string output;

    if(cs_open(CS_ARCH_X86,CS_MODE_64,&handle)==CS_ERR_OK)
    {
        // Set the count to 0 to disassemble as many instructions as possible
        count = cs_disasm(handle, bytearray, size, startAddress, 0, &insn);
        if(count > 0)
        {
            for(size_t j=0;j<count;j++)
            {
                char buffer[512];
                int i = sprintf(buffer,"0x%" PRIx64 ":\t%s\t\t%s\n",insn[j].address,insn[j].mnemonic,insn[j].op_str);
                output += buffer;
            }
            cs_free(insn,count);
        }
        else
        {
            output = "ERROR: Failed to disassemble given code!\n";
        }
    }
    else
    {
        output = "ERROR: Failed to open Capstone handle!\n";
    }

    cs_close(&handle);
    return output;

}

#include <Python.h>
#include <string>
#include <unordered_map>

// A simple in-memory module storage
std::unordered_map<std::string, std::string> memory_modules;

// Custom module loader
extern "C" PyObject* custom_module_loader(PyObject* self, PyObject* args)
{
    PyObject* name_obj;
    if (!PyArg_ParseTuple(args, "O", &name_obj))
    {
        return nullptr;
    }

    const char* name = PyUnicode_AsUTF8(name_obj);
    if (name == nullptr)
    {
        return nullptr;
    }

    auto it = memory_modules.find(name);
    if (it == memory_modules.end())
    {
        PyErr_Format(PyExc_ImportError, "No module named '%s' found in memory", name);
        return nullptr;
    }

    const std::string& code = it->second;
    PyObject* module = PyModule_New(name);
    if (module == nullptr)
    {
        return nullptr;
    }

    if (PyRun_String(code.c_str(), Py_file_input, module->ob_dict, module->ob_dict) == nullptr)
    {
        Py_DECREF(module);
        return nullptr;
    }

    return module;
}

// Register the custom module loader
extern "C" void register_custom_loader()
{
    PyObject* meta_path = PySys_GetObject("meta_path");
    if (meta_path == nullptr)
    {
        return;
    }

    PyObject* loader = PyCFunction_NewEx(&PyCFunctionDef{
        (char*)"custom_module_loader",
        (PyCFunction)custom_module_loader,
        nullptr,
        nullptr
    }, nullptr);

    if (loader != nullptr)
    {
        PyList_Insert(meta_path, 0, loader);
        Py_DECREF(loader);
    }
}

// Example usage
int main()
{
    Py_Initialize();

    // Add a module to memory
    memory_modules["mymodule"] = R"(
def hello():
    return "Hello from mymodule!"
)";

    // Register the custom loader
    register_custom_loader();

    // Import the module
    PyObject* module = PyImport_ImportModule("mymodule");
    if (module == nullptr)
    {
        PyErr_Print();
        return 1;
    }

    // Call a function from the module
    PyObject* hello_func = PyObject_GetAttrString(module, "hello");
    if (hello_func == nullptr)
    {
        PyErr_Print();
        return 1;
    }

    PyObject* result = PyObject_CallObject(hello_func, nullptr);
    if (result == nullptr)
    {
        PyErr_Print();
        return 1;
    }

    const char* message = PyUnicode_AsUTF8(result);
    if (message == nullptr)
    {
        return 1;
    }

    std::cout << "Result: " << message << std::endl;

    Py_DECREF(module);
    Py_DECREF(hello_func);
    Py_DECREF(result);

    Py_Finalize();
    return 0;
}

#include <QObject>
#include <QQmlListProperty>
#include <QList>

// MyObject class definition
class MyObject : public QObject {
        Q_OBJECT
        // Property declaration for QML integration
        Q_PROPERTY(QQmlListProperty<int> keys READ getKeys NOTIFY keysChanged)

    public:
        // Constructor with optional parent
        MyObject(QObject *parent = nullptr) : QObject(parent) {}

        // Getter method for the keys property
        QQmlListProperty<int> getKeys() {
            return QQmlListProperty<int>(this, this, &MyObject::appendKey, &MyObject::countKeys, &MyObject::keyAt, &MyObject::clearKeys);
        }

    signals:
        // Signal emitted when keys change
        void keysChanged();

    private:
        // Internal storage for keys
        QList<int> m_keys;

        // Static callback for appending a key
        static void appendKey(QQmlListProperty<int> *property, int key) {
            MyObject *obj = qobject_cast<MyObject *>(property->object);
            if (obj) {
                obj->m_keys.append(key);
                emit obj->keysChanged();
            }
        }

        // Static callback for getting the count of keys
        static int countKeys(QQmlListProperty<int> *property) {
            MyObject *obj = qobject_cast<MyObject *>(property->object);
            return obj ? obj->m_keys.size() : 0;
        }

        // Static callback for accessing a key at a specific index
        static int keyAt(QQmlListProperty<int> *property, int index) {
            MyObject *obj = qobject_cast<MyObject *>(property->object);
            return obj ? obj->m_keys.at(index) : 0;
        }

        // Static callback for clearing all keys
        static void clearKeys(QQmlListProperty<int> *property) {
            MyObject *obj = qobject_cast<MyObject *>(property->object);
            if (obj) {
                obj->m_keys.clear();
                emit obj->keysChanged();
            }
        }
    };

#include <iostream>
#include <vector>
using namespace std;

// Function to find the longest subarray with given sum
vector<int> findLongestSubarrayWithSum(const vector<int>& nums, int targetSum)
{
    int start = 0, end = 0, currentSum = 0;
    int maxLength = 0, maxStart = -1;

    while (end < nums.size())
    {
        currentSum += nums[end];

        // Shrink window if sum exceeds target
        while (currentSum > targetSum && start <= end)
        {
            currentSum -= nums[start];
            start++;
        }

        // Check if current window matches target sum
        if (currentSum == targetSum)
        {
            if (end - start + 1 > maxLength)
            {
                maxLength = end - start + 1;
                maxStart = start;
            }
        }

        end++;
    }

    // Return empty vector if no valid subarray found
    if (maxStart == -1) return {};
    return vector<int>(nums.begin() + maxStart, nums.begin() + maxStart + maxLength);
}

int main()
{
    vector<int> nums = {1, 2, 3, 4, 5};
    int targetSum = 9;
    vector<int> result = findLongestSubarrayWithSum(nums, targetSum);

    // Print the result
    for (int num : result)
    {
        cout << num << " ";
    }
    return 0;

}

