// Define the structure for the BST node
struct TreeNode {
    int value;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int val) : value(val), left(nullptr), right(nullptr) {}
};

// Function to insert a new node into the BST
TreeNode* insert(TreeNode* root, int value)
{
    if(root == nullptr)
    {
        return new TreeNode(value);
    }
    if(value < root->value)
    {
        root->left = insert(root->left, value);
    }
    else if(value > root->value)
    {
        root->right = insert(root->right, value);
    }
    return root;
}

// Function to perform post-order traversal and print the elements
void postOrderTraversal(TreeNode* root)
{
    if(root == nullptr)
    {
        return;
    }
    postOrderTraversal(root->left);  // Traverse left subtree
    postOrderTraversal(root->right); // Traverse right subtree
    cout << root->value << " ";      // Visit root node
}

// Main function to test the BST and post-order traversal
int main()
{
    TreeNode* root = nullptr;

    // Insert elements into the BST
    root = insert(root, 50);
    root = insert(root, 30);
    root = insert(root, 20);
    root = insert(root, 40);
    root = insert(root, 70);
    root = insert(root, 60);
    root = insert(root, 80);

    // Perform post-order traversal and print the elements
    cout << "Post-Order Traversal: ";
    postOrderTraversal(root);
    cout << endl;

    return 0;

}

