// Mutex for safe printing and other shared resources
std::mutex mtx;

// Standard quicksort implementation
void quicksort(std::vector<int>& arr, int left, int right)
{
    if (left < right)
    {
        int pivot = arr[(left + right) / 2];
        int i = left, j = right;

        while (i <= j)
        {
            while (arr[i] < pivot) i++;
            while (arr[j] > pivot) j--;
            if (i <= j)
            {
                std::swap(arr[i], arr[j]);
                i++;
                j--;
            }
        }

        if (left < j)
        {
            quicksort(arr, left, j);
        }
        if (i < right)
        {
            quicksort(arr, i, right);
        }
    }
}

// Parallel quicksort using async for divide-and-conquer
void parallel_quicksort(std::vector<int>& arr, int left, int right, int threshold)
{
    if (right - left < threshold)
    {
        quicksort(arr, left, right);
    }
    else
    {
        int pivot = arr[(left + right) / 2];
        int i = left, j = right;

        while (i <= j)
        {
            while (arr[i] < pivot) i++;
            while (arr[j] > pivot) j--;
            if (i <= j)
            {
                std::swap(arr[i], arr[j]);
                i++;
                j--;
            }
        }

        std::future<void> left_future;
        std::future<void> right_future;

        if (left < j)
        {
            left_future = std::async(std::launch::async, parallel_quicksort, std::ref(arr), left, j, threshold);
        }
        if (i < right)
        {
            right_future = std::async(std::launch::async, parallel_quicksort, std::ref(arr), i, right, threshold);
        }

        if (left_future.valid())
        {
            left_future.get();
        }
        if (right_future.valid())
        {
            right_future.get();
        }
    }
}

int main()
{
    std::vector<int> arr = {3, 6, 8, 10, 1, 2, 1};
    int threshold = 10; // Threshold to switch to single-threaded quicksort

    std::cout << "Original array: ";
    for (int num : arr)
    {
        std::cout << num << " ";
    }
    std::cout << std::endl;

    parallel_quicksort(arr, 0, arr.size() - 1, threshold);

    std::cout << "Sorted array: ";
    for (int num : arr)
    {
        std::cout << num << " ";
    }
    std::cout << std::endl;

    return 0;
}

