#include <iostream>
#include <map>
#include <sstream>
#include <string>

// Parses a Python-style string dictionary into a C++ map
std::map<std::string, std::string> parsePythonStrDict(const std::string &strDict)
{
    std::map<std::string, std::string> parsedDict;

    std::size_t start = strDict.find('{');
    std::size_t end = strDict.rfind('}');
    std::string keyValuePairs = strDict.substr(start + 1, end - start - 1);

    std::stringstream ss(keyValuePairs);
    std::string keyValuePair;

    while (std::getline(ss, keyValuePair, ','))
    {
        std::size_t colonPos = keyValuePair.find(':');
        std::string key = keyValuePair.substr(0, colonPos);
        std::string value = keyValuePair.substr(colonPos + 1);

        // Trim whitespace and quotes from key
        key = key.substr(key.find_first_not_of(" '\"{"));
        key = key.substr(0, key.find_last_not_of(" '\"}") + 1);
        // Trim whitespace and quotes from value
        value = value.substr(value.find_first_not_of(" '\""));
        value = value.substr(0, value.find_last_not_of(" '\"") + 1);

        parsedDict[key] = value;
    }

    return parsedDict;
}

int main()
{
    std::string pythonStrDict = "{'item1': 1, 'item2': 2.0, 'item3': 'a string', 'item4': 'another string'}";

    std::map<std::string, std::string> myMap = parsePythonStrDict(pythonStrDict);

    for (const auto &item : myMap)
    {
        std::cout << item.first << ": " << item.second << std::endl;
    }

    return 0;
}

#include <iostream>
#include <unordered_set>

// Node structure for XOR linked list
struct Node {
    int value;
    Node* both; // XOR of next and prev

    Node(int val) : value(val), both(nullptr) {}
};

// XOR Linked List implementation
struct XORLinkedList {
    Node* head;
    Node* tail;

    XORLinkedList() : head(nullptr), tail(nullptr) {}

    // Helper function to compute XOR of two node pointers
    Node* XOR(Node* a, Node* b) {
        return reinterpret_cast<Node*>(reinterpret_cast<uintptr_t>(a) ^ reinterpret_cast<uintptr_t>(b));
    }

    // Add a new node with given value at the end
    void add(int value) {
        Node* newNode = new Node(value);
        if (!head) {
            head = tail = newNode;
            return;
        }
        Node* prevNode = tail;
        Node* nextNode = XOR(tail->both, nullptr);
        tail->both = XOR(newNode, nextNode);
        newNode->both = XOR(prevNode, nullptr);
        tail = newNode;
    }

    // Reverse the XOR linked list in-place
    void reverse() {
        Node* curr = head;
        Node* prev = nullptr;
        Node* next = nullptr;

        while (curr) {
            next = XOR(prev, curr->both);
            curr->both = XOR(prev, next);
            prev = curr;
            curr = next;
        }

        head = prev; // last node is now the head
    }

    // Print all elements of the list
    void print() {
        Node* curr = head;
        Node* prev = nullptr;
        Node* next;

        while (curr) {
            std::cout << curr->value << " ";
            next = XOR(prev, curr->both);
            prev = curr;
            curr = next;
        }
        std::cout << std::endl;
    }
};

// Main function demonstrating XOR linked list operations
int main() {
    XORLinkedList list;
    list.add(1);
    list.add(2);
    list.add(3);
    list.print(); // 1 2 3

    list.reverse();
    list.print(); // 3 2 1

    return 0;
}

#include <opencv2/opencv.hpp>
#include <iostream>

// Main function for image affine transformation
int main()
{
    // Load the input image
    cv::Mat inputImage = cv::imread("input.png", cv::IMREAD_GRAYSCALE);

    // Define the affine transformation matrix
    cv::Point2f srcTri[3];
    cv::Point2f dstTri[3];

    srcTri[0] = cv::Point2f(0, 0);
    srcTri[1] = cv::Point2f(inputImage.cols - 1, 0);
    srcTri[2] = cv::Point2f(0, inputImage.rows - 1);

    dstTri[0] = cv::Point2f(0, 0);
    dstTri[1] = cv::Point2f(inputImage.cols * 2 - 1, 0);
    dstTri[2] = cv::Point2f(0, inputImage.rows * 2 - 1);

    cv::Mat warpMat = cv::getAffineTransform(srcTri, dstTri);

    // Create the output image with higher resolution
    cv::Mat outputImage;
    cv::warpAffine(inputImage, outputImage, warpMat, cv::Size(inputImage.cols * 2, inputImage.rows * 2), cv::INTER_CUBIC);

    // Save the output image
    cv::imwrite("output.png", outputImage);

    return 0;

}

