// Connects the subscriber socket to the given address
bool ZmqSocketWrapper::connectSubscriber(const std::string& address)
{
    m_address = address;
    m_pSocket = zsock_new_sub(address.c_str(), "");

    zmq_pollitem_t items[] = { { (void*)zsock_handle(m_pSocket), 0, ZMQ_POLLIN, 0 } };
    int rc = zmq_poll(items, 1, 1000); // Wait for 1 second

    if(rc == -1)
    {
        int errorCode = zmq_errno();
        printf("zmq_poll failed: %s\n", zmq_strerror(errorCode));
        return false;
    }

    if(rc == 0)
    {
        printf("Timeout occurred, no connection to %s\n", address.c_str());
        return false;
    }

    // Connection successful
    return true;

}

