    reader->Update();

    // Define cutting plane
    vtkPlane* plane = vtkPlane::New();
    plane->SetOrigin(0, 0, 0);
    plane->SetNormal(0, 0, 1);

    // Create cutter
    vtkCutter* cutter = vtkCutter::New();
    cutter->SetCutFunction(plane);
