// Generates random data: unsorted and sorted versions
std::vector<std::vector<int>> generate_data(int num_samples, int list_size)
{
    std::vector<std::vector<int>> data;
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(1, 100);

    for(int i=0; i<num_samples; ++i)
    {
        std::vector<int> unsorted_list(list_size);
        for(int j=0; j<list_size; ++j)
        {
            unsorted_list[j] = dis(gen);
        }
        std::vector<int> sorted_list = unsorted_list;
        std::sort(sorted_list.begin(), sorted_list.end());
        data.push_back(unsorted_list);
        data.push_back(sorted_list);
    }
    return data;

}

