// Returns two NumPy arrays containing matrix data
std::pair<pybind11::array_t<float>, pybind11::array_t<float>> get_matrices(const std::vector<float>& x)
{
    const size_t N = x.size();
    const size_t I = 5;
    const size_t J = 3;
    const size_t K = 2;
    const size_t M = 4; // Matrix size

    // Allocate contiguous memory for the matrices
    std::vector<float> mat_a_data(N * I * M * M);
    std::vector<float> mat_b_data(N * J * K * M * M);

    // Fill the data
    for (size_t n = 0; n < N; ++n)
    {
        for (size_t i = 0; i < I; ++i)
        {
            Eigen::Matrix4f mat = get_dummy(); // Replace with actual computation
            for (size_t m = 0; m < M; ++m)
            {
                for (size_t nn = 0; nn < M; ++nn)
                {
                    mat_a_data[n * I * M * M + i * M * M + m * M + nn] = mat(m, nn);
                }
            }
        }

        for (size_t j = 0; j < J; ++j)
        {
            for (size_t k = 0; k < K; ++k)
            {
                Eigen::Matrix4f mat = get_dummy(); // Replace with actual computation
                for (size_t m = 0; m < M; ++m)
                {
                    for (size_t nn = 0; nn < M; ++nn)
                    {
                        mat_b_data[n * J * K * M * M + j * K * M * M + k * M * M + m * M + nn] = mat(m, nn);
                    }
                }
            }
        }
    }

    // Create NumPy arrays from the contiguous data
    pybind11::array_t<float> mat_a_array = pybind11::array_t<float>(
        {N, I, M, M},
        {I * M * M * sizeof(float), M * M * sizeof(float), M * sizeof(float), sizeof(float)},
        mat_a_data.data()
    );

    pybind11::array_t<float> mat_b_array = pybind11::array_t<float>(
        {N, J, K, M, M},
        {J * K * M * M * sizeof(float), K * M * M * sizeof(float), M * M * sizeof(float), M * sizeof(float), sizeof(float)},
        mat_b_data.data()
    );

    return std::make_pair(mat_a_array, mat_b_array);
}

PYBIND11_MODULE(example, m)
{
    m.def("get_matrices", &get_matrices, pybind11::return_value_policy::reference);
}

