// Syscall wrapper template
template <typename Ret = long, typename T1>
Ret syscall(long num, T1 arg1)
{
    long _num = num;
    T1 _arg1 = arg1;
    Ret _ret;

    __asm__ __volatile__(_syscallOper
        : "=r"(_ret)
        : [_num] "r" (_num), [_arg1] "r" (_arg1)
        : _syscallClob);

    return _ret;
}

// Entry point
extern "C" void _start()
{
    syscall(__NR_exit, 0);
}

extern "C" {
    #include <cuda_runtime.h>

    // CUDA kernel to add two arrays
    __global__ void addKernel(float *c, const float *a, const float *b, int n)
    {
        int i = threadIdx.x;
        if(i < n)
        {
            c[i] = a[i] + b[i];
        }
    }

    // Host function to manage CUDA memory and kernel launch
    void add(float *c, const float *a, const float *b, int n)
    {
        float *d_a, *d_b, *d_c;

        cudaMalloc(&d_a, n * sizeof(float));
        cudaMalloc(&d_b, n * sizeof(float));
        cudaMalloc(&d_c, n * sizeof(float));

        cudaMemcpy(d_a, a, n * sizeof(float), cudaMemcpyHostToDevice);
        cudaMemcpy(d_b, b, n * sizeof(float), cudaMemcpyHostToDevice);

        addKernel<<<1, n>>>(d_c, d_a, d_b, n);

        cudaMemcpy(c, d_c, n * sizeof(float), cudaMemcpyDeviceToHost);

        cudaFree(d_a);
        cudaFree(d_b);
        cudaFree(d_c);
    }
}

