// Function to display prime numbers up to n
void displayPrimes(int n)
{
    vector<bool> isPrime(n + 1, true);
    // Mark 0 and 1 as non-prime
    isPrime[0] = isPrime[1] = false;

    for(int p = 2; p * p <= n; p++)
    {
        if(isPrime[p] == true)
        {
            // Mark multiples of p as non-prime
            for(int i = p * p; i <= n; i += p)
            {
                isPrime[i] = false;
            }
        }
    }

    cout << "Prime numbers less than or equal to " << n << " are: ";
    for(int p = 2; p <= n; p++)
    {
        if(isPrime[p])
        {
            cout << p << " ";
        }
    }
    cout << endl;
}

int main()
{
    int n;
    cout << "Enter a number: ";
    cin >> n;

    displayPrimes(n);

    return 0;
}

