// Lists network computers using Shell API
void ListNetworkComputers()
{
    HRESULT hr = CoInitializeEx(NULL, COINIT_APARTMENTTHREADED);
    if (SUCCEEDED(hr))
    {
        IShellItem* pShellItem = NULL;
        hr = SHGetKnownFolderItem(FOLDERID_NetworkFolder, KF_FLAG_DEFAULT, NULL, IID_IShellItem, (void**)&pShellItem);
        if (SUCCEEDED(hr) && pShellItem)
        {
            IEnumShellItems* pEnum = NULL;
            hr = pShellItem->BindToHandler(NULL, BHID_EnumItems, IID_IEnumShellItems, (void**)&pEnum);
            if (SUCCEEDED(hr) && pEnum)
            {
                IShellItem* pItem = NULL;
                while (S_OK == pEnum->Next(1, &pItem, NULL))
                {
                    PWSTR pszName = NULL;
                    if (SUCCEEDED(pItem->GetDisplayName(SIGDN_NORMALDISPLAY, &pszName)) && pszName)
                    {
                        std::wcout << L"Computer: " << pszName << std::endl;
                        CoTaskMemFree(pszName);
                    }
                    pItem->Release();
                }
                pEnum->Release();
            }
            pShellItem->Release();
        }
        CoUninitialize();
    }
}

int main()
{
    // Entry point - invoke network computer listing
    ListNetworkComputers();
    return 0;

}

