// Generates Fibonacci sequence up to n terms
void generateFibonacci(int n)
{
    if(n <= 0)
    {
        cout << "Please enter a positive integer." << endl;
        return;
    }

    int t1 = 0, t2 = 1, nextTerm = 0;

    for(int i = 1; i <= n; ++i)
    {
        // Prints the first two terms.
        if(i == 1)
        {
            cout << t1 << ", ";
            continue;
        }
        if(i == 2)
        {
            cout << t2 << ", ";
            continue;
        }
        nextTerm = t1 + t2;
        t1 = t2;
        t2 = nextTerm;
        cout << nextTerm;
        if(i < n)
        {
            cout << ", ";
        }
    }
}

int main()
{
    int n;
    cout << "Enter the number of terms: ";
    cin >> n;

    generateFibonacci(n);

    return 0;

}

