#include <immintrin.h>

// Transpose an 8x8 matrix of doubles using AVX-512 intrinsics
void Transpose(double* in, double* out)
{
    // Load rows
    __m512d row0 = _mm512_load_pd(in + 0 * 8);  //  0  1  2  3  4  5  6  7
    __m512d row1 = _mm512_load_pd(in + 1 * 8);  //  8  9 10 11 12 13 14 15
    __m512d row2 = _mm512_load_pd(in + 2 * 8);  // 16 17 18 19 20 21 22 23
    __m512d row3 = _mm512_load_pd(in + 3 * 8);  // 24 25 26 27 28 29 30 31
    __m512d row4 = _mm512_load_pd(in + 4 * 8);  // 32 33 34 35 36 37 38 39
    __m512d row5 = _mm512_load_pd(in + 5 * 8);  // 40 41 42 43 44 45 46 47
    __m512d row6 = _mm512_load_pd(in + 6 * 8);  // 48 49 50 51 52 53 54 55
    __m512d row7 = _mm512_load_pd(in + 7 * 8);  // 56 57 58 59 60 61 62 63

    // Unpack low and high pairs
    __m512d __t0 = _mm512_unpacklo_pd(row0, row1);  // 0  8  2  10  4 12  6 14
    __m512d __t1 = _mm512_unpackhi_pd(row0, row1);  // 1  9  3  11  5 13  7 15
    __m512d __t2 = _mm512_unpacklo_pd(row2, row3);  // 16 24 18 26 20 28 22 30
    __m512d __t3 = _mm512_unpackhi_pd(row2, row3);  // 17 25 19 27 21 29 23 31
    __m512d __t4 = _mm512_unpacklo_pd(row4, row5);  // 32 40 34 42 36 44 38 46
    __m512d __t5 = _mm512_unpackhi_pd(row4, row5);  // 33 41 35 43 37 45 39 47
    __m512d __t6 = _mm512_unpacklo_pd(row6, row7);  // 48 56 50 58 52 60 54 62
    __m512d __t7 = _mm512_unpackhi_pd(row6, row7);  // 49 57 51 59 53 61 55 63

    // Permute using variable index
    __m512d __tt0 = _mm512_permutex2var_pd(
        __t0, _mm512_setr_epi64(0, 1, 8, 9, 4, 5, 12, 13), __t2);
    __m512d __tt1 = _mm512_permutex2var_pd(
        __t0, _mm512_setr_epi64(2, 3, 10, 11, 6, 7, 14, 15), __t2);
    __m512d __tt2 = _mm512_permutex2var_pd(
        __t1, _mm512_setr_epi64(0, 1, 8, 9, 4, 5, 12, 13), __t3);
    __m512d __tt3 = _mm512_permutex2var_pd(
        __t1, _mm512_setr_epi64(2, 3, 10, 11, 6, 7, 14, 15), __t3);
    __m512d __tt4 = _mm512_permutex2var_pd(
        __t4, _mm512_setr_epi64(0, 1, 8, 9, 4, 5, 12, 13), __t6);
    __m512d __tt5 = _mm512_permutex2var_pd(
        __t4, _mm512_setr_epi64(2, 3, 10, 11, 6, 7, 14, 15), __t6);
    __m512d __tt6 = _mm512_permutex2var_pd(
        __t5, _mm512_setr_epi64(0, 1, 8, 9, 4, 5, 12, 13), __t7);
    __m512d __tt7 = _mm512_permutex2var_pd(
        __t5, _mm512_setr_epi64(2, 3, 10, 11, 6, 7, 14, 15), __t7);

    // Use mask moves to replace shuffles
    {
        __m512d v = _mm512_shuffle_f64x2(__tt0, __tt4, 0x4e);  // 4 12 20 28 32 40 48 56
        __m512d mask0 = _mm512_setr_epi64(0x0000000000000000, 0x0000000000000000, 0xFFFFFFFFFFFFFFFF, 0xFFFFFFFFFFFFFFFF);
        __m512d mask4 = _mm512_setr_epi64(0xFFFFFFFFFFFFFFFF, 0xFFFFFFFFFFFFFFFF, 0x0000000000000000, 0x0000000000000000);
        __m512d __t0 = _mm512_mask_mov_pd(__tt0, mask0, v);
        __m512d __t4 = _mm512_mask_mov_pd(__tt4, mask4, v);
    }

    {
        __m512d v = _mm512_shuffle_f64x2(__tt1, __tt5, 0x4e);  // 6 14 22 30 34 42 50 58
        __m512d mask1 = _mm512_setr_epi64(0x0000000000000000, 0x0000000000000000, 0xFFFFFFFFFFFFFFFF, 0xFFFFFFFFFFFFFFFF);
        __m512d mask5 = _mm512_setr_epi64(0xFFFFFFFFFFFFFFFF, 0xFFFFFFFFFFFFFFFF, 0x0000000000000000, 0x0000000000000000);
        __m512d __t2 = _mm512_mask_mov_pd(__tt1, mask1, v);
        __m512d __t6 = _mm512_mask_mov_pd(__tt5, mask5, v);
    }

    {
        __m512d v = _mm512_shuffle_f64x2(__tt2, __tt6, 0x4e);  // 5 13 21 29 33 41 49 57
        __m512d mask2 = _mm512_setr_epi64(0x0000000000000000, 0x0000000000000000, 0xFFFFFFFFFFFFFFFF, 0xFFFFFFFFFFFFFFFF);
        __m512d mask6 = _mm512_setr_epi64(0xFFFFFFFFFFFFFFFF, 0xFFFFFFFFFFFFFFFF, 0x0000000000000000, 0x0000000000000000);
        __m512d __t1 = _mm512_mask_mov_pd(__tt2, mask2, v);
        __m512d __t5 = _mm512_mask_mov_pd(__tt6, mask6, v);
    }

    {
        __m512d v = _mm512_shuffle_f64x2(__tt3, __tt7, 0x4e);  // 7 15 23 31 35 43 51 59
        __m512d mask3 = _mm512_setr_epi64(0x0000000000000000, 0x0000000000000000, 0xFFFFFFFFFFFFFFFF, 0xFFFFFFFFFFFFFFFF);
        __m512d mask7 = _mm512_setr_epi64(0xFFFFFFFFFFFFFFFF, 0xFFFFFFFFFFFFFFFF, 0x0000000000000000, 0x0000000000000000);
        __m512d __t3 = _mm512_mask_mov_pd(__tt3, mask3, v);
        __m512d __t7 = _mm512_mask_mov_pd(__tt7, mask7, v);
    }

    // Store results
    _mm512_store_pd(out + 0 * 8, __t0);
    _mm512_store_pd(out + 1 * 8, __t1);
    _mm512_store_pd(out + 2 * 8, __t2);
    _mm512_store_pd(out + 3 * 8, __t3);
    _mm512_store_pd(out + 4 * 8, __t4);
    _mm512_store_pd(out + 5 * 8, __t5);
    _mm512_store_pd(out + 6 * 8, __t6);
    _mm512_store_pd(out + 7 * 8, __t7);
}

