#include <immintrin.h>

// Function to calculate attributes using SIMD
void calculate_attributes(float* array, float* c, float* d, int n)
{
    __m256 vec_a, vec_b, vec_e, vec_c, vec_d;
    for(int i=0;i<n;i+=8)
    {
        // Load vectors from array
        vec_a = _mm256_loadu_ps(&array[i * 3 + 0]);
        vec_b = _mm256_loadu_ps(&array[i * 3 + 1]);
        vec_e = _mm256_loadu_ps(&array[i * 3 + 2]);

        // Perform calculations using SIMD instructions
        vec_c = _mm256_add_ps(vec_a, vec_b);
        vec_d = _mm256_sub_ps(vec_a, vec_e);

        // Store results
        _mm256_storeu_ps(&c[i], vec_c);
        _mm256_storeu_ps(&d[i], vec_d);
    }
}

