#include <cuda_runtime.h>
#include <iostream>

// CUDA multiplication function
extern "C" {
    void cudaMultiply(int* a, int* b, int* c, int size)
    {
        int* dev_a, * dev_b, * dev_c;

        // Allocate device memory
        cudaMalloc((void**)&dev_a, size * sizeof(int));
        cudaMalloc((void**)&dev_b, size * sizeof(int));
        cudaMalloc((void**)&dev_c, size * sizeof(int));

        // Copy data from host to device
        cudaMemcpy(dev_a, a, size * sizeof(int), cudaMemcpyHostToDevice);
        cudaMemcpy(dev_b, b, size * sizeof(int), cudaMemcpyHostToDevice);

        // Configure kernel launch parameters
        dim3 dimBlock(256);
        dim3 dimGrid((size + dimBlock.x - 1) / dimBlock.x);

        // Launch the kernel
        multiply<<<dimGrid, dimBlock>>>(dev_a, dev_b, dev_c, size);

        // Copy result back to host
        cudaMemcpy(c, dev_c, size * sizeof(int), cudaMemcpyDeviceToHost);

        // Free device memory
        cudaFree(dev_a);
        cudaFree(dev_b);
        cudaFree(dev_c);
    }

    // Kernel function for element-wise multiplication
    __global__ void multiply(int* a, int* b, int* c, int size)
    {
        int idx = blockIdx.x * blockDim.x + threadIdx.x;
        if (idx < size)
        {
            c[idx] = a[idx] * b[idx];
        }
    }
}

