// Convert 64-bit integer from network to host byte order
int64_t ntohll(int64_t value)
{
    return (static_cast<int64_t>(ntohl(static_cast<uint32_t>(value))) << 32) |
           ntohl(static_cast<uint32_t>(value >> 32));
}

// Convert 64-bit integer from host to network byte order
int64_t htonll(int64_t value)
{
    return (static_cast<int64_t>(htonl(static_cast<uint32_t>(value))) << 32) |
           htonl(static_cast<uint32_t>(value >> 32));
}

