// Lists available COM ports by querying the Windows registry
std::vector<std::string> listComPorts()
{
    HKEY hKey;
    LONG result = RegOpenKeyEx(HKEY_LOCAL_MACHINE, TEXT("HARDWARE\\DEVICEMAP\\SERIALCOMM"), 0, KEY_READ, &hKey);
    if (result != ERROR_SUCCESS)
    {
        return {};
    }

    std::vector<std::string> com_ports;
    char valueName[1024];
    char valueData[1024];
    DWORD valueNameSize = 1024;
    DWORD valueDataSize = 1024;
    DWORD valueType;

    for (int i = 0; ; i++)
    {
        valueNameSize = 1024;
        valueDataSize = 1024;
        result = RegEnumValue(hKey, i, valueName, &valueNameSize, NULL, &valueType, (BYTE*)valueData, &valueDataSize);
        if (result != ERROR_SUCCESS)
        {
            break;
        }
        if (valueType == REG_SZ)
        {
            com_ports.push_back(std::string(valueData));
        }
    }

    RegCloseKey(hKey);
    return com_ports;
}

