// Structure representing a vertex with 3D coordinates
struct Vertex {
    float x, y, z;
};

// Structure representing a triangular face
struct Face {
    int v1, v2, v3;
};

// Reads vertices from an OBJ file
std::vector<Vertex> readVertices(const std::string& filename)
{
    std::vector<Vertex> vertices;
    std::ifstream file(filename);
    if (!file.is_open()) {
        std::cerr << "Failed to open file: " << filename << std::endl;
        return vertices;
    }

    std::string line;
    while (std::getline(file, line)) {
        if (line.substr(0, 2) == "v ") {
            Vertex vertex;
            std::sscanf(line.c_str(), "v %f %f %f", &vertex.x, &vertex.y, &vertex.z);
            vertices.push_back(vertex);
        }
    }
    return vertices;
}

// Reads faces from an OBJ file
std::vector<Face> readFaces(const std::string& filename)
{
    std::vector<Face> faces;
    std::ifstream file(filename);
    if (!file.is_open()) {
        std::cerr << "Failed to open file: " << filename << std::endl;
        return faces;
    }

    std::string line;
    while (std::getline(file, line)) {
        if (line.substr(0, 2) == "f ") {
            Face face;
            std::sscanf(line.c_str(), "f %d %d %d", &face.v1, &face.v2, &face.v3);
            faces.push_back(face);
        }
    }
    return faces;
}

#include <iostream>
#include <string>
#include <stack>
#include <cctype>
#include <cmath>
#include <stdexcept>

// Function to check if a character is an operator
bool isOperator(char c) {
    return c == '+' || c == '-' || c == '*' || c == '/' || c == '^';
}

// Function to get the precedence of an operator
int precedence(char op) {
    switch (op) {
        case '+':
        case '-':
            return 1;
        case '*':
        case '/':
            return 2;
        case '^':
            return 3;
        default:
            return 0;
    }
}

// Function to convert infix to postfix
std::string infixToPostfix(const std::string& infix) {
    std::stack<char> stack;
    std::string postfix;
    for (char c : infix) {
        if (std::isdigit(c)) {
            postfix += c;
        } else if (isOperator(c)) {
            while (!stack.empty() && precedence(stack.top()) >= precedence(c)) {
                postfix += stack.top();
                stack.pop();
            }
            stack.push(c);
        } else if (c == '(') {
            stack.push(c);
        } else if (c == ')') {
            while (!stack.empty() && stack.top() != '(') {
                postfix += stack.top();
                stack.pop();
            }
            if (stack.empty() || stack.top() != '(') {
                throw std::runtime_error("Mismatched parentheses");
            }
            stack.pop();
        }
    }
    while (!stack.empty()) {
        if (stack.top() == '(') {
            throw std::runtime_error("Mismatched parentheses");
        }
        postfix += stack.top();
        stack.pop();
    }
    return postfix;
}

// Function to evaluate a postfix expression
double evaluatePostfix(const std::string& postfix) {
    std::stack<double> stack;
    for (char c : postfix) {
        if (std::isdigit(c)) {
            stack.push(c - '0');
        } else if (isOperator(c)) {
            if (stack.size() < 2) {
                throw std::runtime_error("Invalid expression");
            }
            double b = stack.top(); stack.pop();
            double a = stack.top(); stack.pop();
            switch (c) {
                case '+': stack.push(a + b); break;
                case '-': stack.push(a - b); break;
                case '*': stack.push(a * b); break;
                case '/': 
                    if (b == 0) throw std::runtime_error("Division by zero");
                    stack.push(a / b); 
                    break;
                case '^': stack.push(std::pow(a, b)); break;
            }
        }
    }
    if (stack.size() != 1) {
        throw std::runtime_error("Invalid expression");
    }
    return stack.top();
}

// Function to evaluate a mathematical expression from a string
double evaluateExpression(const std::string& expression) {
    std::string postfix = infixToPostfix(expression);
    return evaluatePostfix(postfix);
}

// Main function
int main()
{
    std::string expression = "3 + 5 * (2 - 4)";
    try {
        double result = evaluateExpression(expression);
        // Output the result
        std::cout << "Result: " << result << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }
    return 0;

}

