// Abstract predicate class for testing conditions on type T
template <class T>
class Predicate
{
public:
    // Pure virtual test method - must be implemented by derived classes
    virtual bool test(T) = 0;

    // Virtual destructor to ensure proper cleanup of derived objects
    virtual ~Predicate() = default;
};

// Template function that tests a value against a predicate
template <class T>
bool testIf(T t, const Predicate<T>& predicate)
{
    return predicate.test(t);
}

