// Function to find minimum and maximum values in a vector
std::pair<int, int> findMinMax(const std::vector<int>& arr)
{
    if (arr.empty())
    {
        throw std::invalid_argument("Array is empty");
    }

    // Initialize min and max with extreme values
    int minVal = std::numeric_limits<int>::max();
    int maxVal = std::numeric_limits<int>::min();

    // Iterate through the array to find min and max
    for(int num : arr)
    {
        if(num < minVal)
        {
            minVal = num;
        }
        if(num > maxVal)
        {
            maxVal = num;
        }
    }

    return {minVal, maxVal};
}

int main()
{
    std::vector<int> array = {3, 1, 4, 1, 5, 9, 2, 6, 5, 3, 5};
    auto [minVal, maxVal] = findMinMax(array);

    // Output results
    std::cout << "Minimum: " << minVal << std::endl;
    std::cout << "Maximum: " << maxVal << std::endl;

    return 0;

}

