// 3D Vector class
class Vector3D {
public:
    // Constructor
    Vector3D(double x = 0.0, double y = 0.0, double z = 0.0) : x(x), y(y), z(z) {}

    // Destructor
    ~Vector3D() {}

    // Accessor methods
    double getX() const { return x; }
    double getY() const { return y; }
    double getZ() const { return z; }

    // Mutator methods
    void setX(double x) { this->x = x; }
    void setY(double y) { this->y = y; }
    void setZ(double z) { this->z = z; }

    // Method to scale the vector
    Vector3D scale(double scalar) const {
        return Vector3D(x * scalar, y * scalar, z * scalar);
    }

    // Method to normalize the vector
    Vector3D normalize() const {
        double length = std::sqrt(x * x + y * y + z * z);
        if (length > 0.0) {
            return Vector3D(x / length, y / length, z / length);
        }
        return *this; // Return the original vector if its length is zero
    }

    // Method to add another vector to this vector
    Vector3D add(const Vector3D& other) const {
        return Vector3D(x + other.x, y + other.y, z + other.z);
    }

    // Method to print the vector
    void print() const {
        std::cout << "Vector3D(" << x << ", " << y << ", " << z << ")" << std::endl;
    }

private:
    double x, y, z;
};

// Example usage
int main()
{
    Vector3D v1(1.0, 2.0, 3.0);
    Vector3D v2(4.0, 5.0, 6.0);

    std::cout << "v1: ";
    v1.print();

    std::cout << "v2: ";
    v2.print();

    Vector3D scaled_v1 = v1.scale(2.0);
