// Define the structure for the tree node
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    // Constructor to initialize node with value and null children
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

// Function to check if two trees are mirror images
bool isMirror(TreeNode* t1, TreeNode* t2)
{
    // Both nodes are null -> symmetric
    if (t1 == nullptr && t2 == nullptr) return true;
    // One is null, other isn't -> not symmetric
    if (t1 == nullptr || t2 == nullptr) return false;
    // Values must match and subtrees must be mirrors
    return (t1->val == t2->val)
           && isMirror(t1->right, t2->left)
           && isMirror(t1->left, t2->right);
}

// Function to check if the tree is symmetric
bool isSymmetric(TreeNode* root)
{
    // A tree is symmetric if it's a mirror of itself
    return isMirror(root, root);
}

// Function to create a tree node (for testing purposes)
TreeNode* createNode(int val)
{
    return new TreeNode(val);
}

