#define mtxSize 1024
#define blockSize 16

// Kernel function for matrix multiplication with progress tracking
__global__ void matrixMulKernel(const float* A, const float* B, float* C, int N, int* progress)
{
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < N && col < N)
    {
        float tmp = 0.0f;
        for (int idx = 0; idx < N; ++idx)
        {
            tmp += A[row * N + idx] * B[idx * N + col];
        }
        C[row * N + col] = tmp;

        // Update progress counter atomically
        atomicAdd(progress, 1);
    }
}

// Display progress percentage to stdout
void displayProgress(int progress, int total)
{
    int rate_tmp = (progress * 100) / total;
    fprintf(stdout, "Progress : %d.%d %%\r", rate_tmp / 100, rate_tmp % 100);
    fflush(stdout);
}

// Main function
int main()
{
    float *h_A, *h_B, *h_C, *d_A, *d_B, *d_C;
    int *h_progress, *d_progress;
    size_t size = mtxSize * mtxSize * sizeof(float);
    size_t progressSize = sizeof(int);

    // Allocate memory on the host
    h_A = (float*)malloc(size);
    h_B = (float*)malloc(size);
    h_C = (float*)malloc(size);
    h_progress = (int*)malloc(progressSize);

    // Initialize matrices with ones (for simplicity)
    for (int i = 0; i < mtxSize * mtxSize; ++i)
    {
        h_A[i] = 1.0f;
        h_B[i] = 1.0f;
        h_C[i] = 0.0f;
    }

    // Allocate memory on the device
    CHECK_CUDA(cudaMalloc(&d_A, size));
    CHECK_CUDA(cudaMalloc(&d_B, size));
    CHECK_CUDA(cudaMalloc(&d_C, size));
    CHECK_CUDA(cudaMalloc(&d_progress, progressSize));

    // Copy data from host to device
    CHECK_CUDA(cudaMemcpy(d_A, h_A, size, cudaMemcpyHostToDevice));
    CHECK_CUDA(cudaMemcpy(d_B, h_B, size, cudaMemcpyHostToDevice));
    CHECK_CUDA(cudaMemcpy(d_progress, h_progress, progressSize, cudaMemcpyHostToDevice));

    // Define grid and block dimensions
    dim3 dimBlock(blockSize, blockSize);
    dim3 dimGrid((mtxSize + blockSize - 1) / blockSize, (mtxSize + blockSize - 1) / blockSize);

    // Create CUDA stream
    cudaStream_t stream;
    CHECK_CUDA(cudaStreamCreate(&stream));

    // Total number of elements to process
    int totalElements = mtxSize * mtxSize;
    int progressInterval = totalElements / 100; // Update progress every 1%

    // Launch kernels in a loop and check progress
    for (int i = 0; i < totalElements; i += progressInterval)
    {
        matrixMulKernel<<<dimGrid, dimBlock, 0, stream>>>(d_A, d_B, d_C, mtxSize, d_progress);
        CHECK_CUDA(cudaStreamSynchronize(stream));

        // Copy progress from device to host
        CHECK_CUDA(cudaMemcpy(h_progress, d_progress, progressSize, cudaMemcpyDeviceToHost));
        displayProgress(*h_progress, totalElements);
    }

    // Final synchronization
    CHECK_CUDA(cudaStreamSynchronize(stream));

    // Copy result from device to host
    CHECK_CUDA(cudaMemcpy(h_C, d_C, size, cudaMemcpyDeviceToHost));

    // Free memory
    free(h_A);
    free(h_B);
    free(h_C);
    free(h_progress);
    CHECK_CUDA(cudaFree(d_A));
    CHECK_CUDA(cudaFree(d_B));
    CHECK_CUDA(cudaFree(d_C));
    CHECK_CUDA(cudaFree(d_progress));
    CHECK_CUDA(cudaStreamDestroy(stream));

    return 0;
}

