// Definition for singly-linked list.
struct ListNode {
    int val;
    ListNode *next;
    ListNode(int x) : val(x), next(nullptr) {}
};

class Solution {
public:
    // Detects if a cycle exists in the linked list
    bool hasCycle(ListNode *head) {
        if (head == nullptr || head->next == nullptr) {
            return false;
        }

        ListNode *slow = head;
        ListNode *fast = head;

        while (fast != nullptr && fast->next != nullptr) {
            slow = slow->next;
            fast = fast->next->next;

            if (slow == fast) {
                return true; // Cycle detected
            }
        }

        return false; // No cycle
    }
};

// Function to create a linked list with a cycle for testing
ListNode* createLinkedListWithCycle() {
    ListNode *node1 = new ListNode(1);
    ListNode *node2 = new ListNode(2);
    ListNode *node3 = new ListNode(3);
    ListNode *node4 = new ListNode(4);

    node1->next = node2;
    node2->next = node3;
    node3->next = node4;
    node4->next = node2; // Creating a cycle

    return node1;
}

int main() {
    Solution solution;

    // Test with a linked list with a cycle
    ListNode *headWithCycle = createLinkedListWithCycle();
    cout << "List with cycle: " << (solution.hasCycle(headWithCycle) ? "Yes" : "No") << endl;

    // Test with a linked list without a cycle
    ListNode *headWithoutCycle = new ListNode(1);
    headWithoutCycle->next = new ListNode(2);
    headWithoutCycle->next->next = new ListNode(3);
    cout << "List without cycle: " << (solution.hasCycle(headWithoutCycle) ? "Yes" : "No") << endl;

    return 0;

}

