// Returns precedence of operator
int precedence(char op)
{
    if (op == '+' || op == '-') return 1;
    if (op == '*' || op == '/') return 2;
    return 0;
}

// Checks if character is an operator
bool isOperator(char c)
{
    return c == '+' || c == '-' || c == '*' || c == '/';
}

// Checks if character is an operand (letter or digit)
bool isOperand(char c)
{
    return std::isalpha(c) || std::isdigit(c);
}

// Converts infix expression to postfix
std::string infixToPostfix(const std::string& infix)
{
    std::stack<char> stack;
    std::string postfix;

    for (char c : infix)
    {
        if (isOperand(c))
        {
            postfix += c;
        }
        else if (c == '(')
        {
            stack.push(c);
        }
        else if (c == ')')
        {
            while (!stack.empty() && stack.top() != '(')
            {
                postfix += stack.top();
                stack.pop();
            }
            stack.pop();  // Pop '('
        }
        else if (isOperator(c))
        {
            while (!stack.empty() && precedence(c) <= precedence(stack.top()))
            {
                postfix += stack.top();
                stack.pop();
            }
            stack.push(c);
        }
    }

    while (!stack.empty())
    {
        postfix += stack.top();
        stack.pop();
    }

    return postfix;
}

