// Checks if a number is prime
bool isPrime(int n)
{
    // 1 and numbers less than 1 are not prime
    if(n <= 1) return false;
    for(int i=2; i*i<=n; i++)
    {
        // Found a divisor, not a prime number
        if(n % i == 0) return false;
    }
    // No divisors found, it's a prime number
    return true;
}

int main()
{
    cout << "Prime numbers between 1 and 10 are: ";
    for(int i=1; i<=10; i++)
    {
        if(isPrime(i))
        {
            cout << i << " ";
        }
    }
    // Print newline
    cout << endl;
    return 0;

}

