int _tmain(int argc, _TCHAR* argv[])
{
    HCRYPTPROV hProv;
    HCRYPTKEY hKeyPair1, hSessionKey1;
    HCRYPTHASH hHash1;
    DWORD dwLength;
    BOOL fReturn;
    BYTE pbData[1024];
    BYTE pbSessionKey[1024];
    DWORD dwSessionKeyLen = sizeof(pbSessionKey);

    // Acquire a cryptographic provider context handle.
    if (!CryptAcquireContext(&hProv, NULL, MS_ENHANCED_PROV, PROV_RSA_FULL, 0))
    {
        if (GetLastError() == NTE_BAD_KEYSET)
            fReturn = CryptAcquireContext(&hProv, NULL, MS_ENHANCED_PROV, PROV_RSA_FULL, CRYPT_NEWKEYSET);
        else
            fReturn = FALSE;
        if (!fReturn)
            goto ErrorExit;
    }

    // Create a Diffie-Hellman key pair.
    fReturn = CryptGenKey(hProv, CALG_DH_EPHEM, DHKEYSIZE << 16, &hKeyPair1);
    if (!fReturn)
        goto ErrorExit;

    // Create a hash object.
    fReturn = CryptCreateHash(hProv, CALG_SHA1, 0, 0, &hHash1);
    if (!fReturn)
        goto ErrorExit;

    // Create a session key from the hash of the shared secret.
    fReturn = CryptDeriveKey(hProv, CALG_RC4, hHash1, 0, &hSessionKey1);
    if (!fReturn)
        goto ErrorExit;

    // Export the session key in a raw format.
    fReturn = CryptExportKey(hSessionKey1, 0, PLAINTEXTKEYBLOB, 0, pbSessionKey, &dwSessionKeyLen);
    if (!fReturn)
        goto ErrorExit;

    // Print the session key in hex format.
    for(DWORD i=0;i<dwSessionKeyLen;++i)
    {
        printf("%02x",pbSessionKey[i]);
    }
    printf("\n");

    // Encrypt the data.
    dwLength = sizeof(g_rgbData);
    fReturn = CryptEncrypt(hSessionKey1, 0, TRUE, 0, g_rgbData, &dwLength, sizeof(g_rgbData));
    if (!fReturn)
        goto ErrorExit;

    // Print the encrypted data in hex format.
    for(DWORD i=0;i<dwLength;++i)
    {
        printf("%02x",g_rgbData[i]);
    }
    printf("\n");

ErrorExit:
    if(hSessionKey1) CryptDestroyKey(hSessionKey1);
    if(hKeyPair1) CryptDestroyKey(hKeyPair1);
    if(hHash1) CryptDestroyHash(hHash1);
    if(hProv) CryptReleaseContext(hProv,0);

    return 0;
}

