// Function to find the largest element in a vector
int findLargestElement(const std::vector<int>& arr)
{
    // Check if array is empty
    if(arr.empty())
    {
        throw std::invalid_argument("Array is empty");
    }
    int largest = arr[0];
    // Iterate through all elements
    for(int num : arr)
    {
        if(num > largest)
        {
            largest = num;
        }
    }
    return largest;
}

