// Function to find the longest common substring
pair<int, pair<int, int>> findLongestCommonSubstring(const string& s1, const string& s2)
{
    int n = s1.length();
    int m = s2.length();

    // Create a 2D DP table
    vector<vector<int>> dp(n + 1, vector<int>(m + 1, 0));

    // Variables to store the length of the longest common substring and its starting indices
    int maxLength = 0;
    int endIdxS1 = -1;
    int endIdxS2 = -1;

    // Fill the DP table
    for(int i=1;i<=n;++i)
    {
        for(int j=1;j<=m;++j)
        {
            if(s1[i-1] == s2[j-1])
            {
                dp[i][j] = dp[i-1][j-1] + 1;
                if(dp[i][j] > maxLength)
                {
                    maxLength = dp[i][j];
                    endIdxS1 = i - 1;
                    endIdxS2 = j - 1;
                }
            }
            else
            {
                dp[i][j] = 0;
            }
        }
    }

    // Calculate the starting indices
    int startIdxS1 = endIdxS1 - maxLength + 1;
    int startIdxS2 = endIdxS2 - maxLength + 1;

    return {maxLength, {startIdxS1, startIdxS2}};
}

int main()
{
    string s1, s2;
    cout << "Enter the first string: ";
    cin >> s1;
    cout << "Enter the second string: ";
    cin >> s2;

    auto result = findLongestCommonSubstring(s1, s2);
    int maxLength = result.first;
    int startIdxS1 = result.second.first;
    int startIdxS2 = result.second.second;

    if(maxLength > 0)
    {
        cout << "Longest common substring: " << s1.substr(startIdxS1, maxLength) << endl;
        cout << "Starting index in the first string: " << startIdxS1 << endl;
        cout << "Starting index in the second string: " << startIdxS2 << endl;
    }
    else
    {
        cout << "No common substring found." << endl;
    }

    return 0;

}

#include <immintrin.h> // For AVX intrinsics

// Reorders the input array into the output array using AVX vectorized operations
void reorder(float* output, const float* input, size_t length)
{
    size_t i = 0;
    while (i < length)
    {
        // Check if the next 8 floats are contiguous and valid
        if (input[i] != 0 && input[i + 1] != 0 && input[i + 2] != 0 && input[i + 3] != 0 &&
            input[i + 4] != 0 && input[i + 5] != 0 && input[i + 6] != 0 && input[i + 7] != 0)
        {
            // Load 8 floats from input
            __m256 vec = _mm256_loadu_ps(&input[i]);
            // Store 8 floats to output
            _mm256_storeu_ps(&output[i], vec);
            i += 8;
        }
        else
        {
            // Handle non-contiguous or '0'-valued elements
            output[i] = input[i];
            i++;
        }
    }
}

int medianOfThree(vector<int> &arr, int l, int r)
{
    int mid = l + (r - l) / 2;
    if(arr[l] > arr[mid]) swap(arr[l], arr[mid]);
    if(arr[l] > arr[r]) swap(arr[l], arr[r]);
    if(arr[mid] > arr[r]) swap(arr[mid], arr[r]);
    swap(arr[mid], arr[r]);
    return arr[r];
}

