// Disables SetUnhandledExceptionFilter by patching its implementation
bool DisableSetUnhandledExceptionFilter()
{
    // Patch bytes: XOR RAX,RAX; RET;
    const BYTE PatchBytes[5] = { 0x48, 0x33, 0xC0, 0xC3 };

    // Get handle to kernel32.dll
    HMODULE hLib = GetModuleHandle(_T("kernel32.dll"));
    if (hLib == NULL)
        return false;

    // Get address of SetUnhandledExceptionFilter
    BYTE* pTarget = (BYTE*)GetProcAddress(hLib, "SetUnhandledExceptionFilter");
    if (pTarget == 0)
        return false;

    // Apply the patch
    if (!WriteMemory(pTarget, PatchBytes, sizeof(PatchBytes)))
        return false;

    // Flush instruction cache to ensure changes take effect
    FlushInstructionCache(GetCurrentProcess(), pTarget, sizeof(PatchBytes));

    return true;
}

// Writes memory with appropriate protection changes
static bool WriteMemory(BYTE* pTarget, const BYTE* pSource, DWORD Size)
{
    // Validate input parameters
    if (pTarget == 0)
        return false;
    if (pSource == 0)
        return false;
    if (Size == 0)
        return false;
    if (IsBadReadPtr(pSource, Size))
        return false;

    // Change memory protection to allow writing
    DWORD OldProtect = 0;
    if (!VirtualProtect(pTarget, Size, PAGE_EXECUTE_READWRITE, &OldProtect))
        return false;

    // Perform the actual memory copy
    memcpy(pTarget, pSource, Size);

    // Restore original memory protection
    DWORD Temp = 0;
    if (!VirtualProtect(pTarget, Size, OldProtect, &Temp))
        return false;

    return true;
}

