// Function to calculate the number of digits in an integer
int numDigits(int n)
{
    if (n == 0) return 1; // Special case for 0
    n = abs(n); // Handle negative numbers
    return floor(log10(n) + 1);
}

// Comparator function to sort based on the number of digits
bool compare(int a, int b)
{
    int lenA = numDigits(a);
    int lenB = numDigits(b);
    if (lenA == lenB)
    {
        return a < b; // If lengths are the same, sort by value
    }
    return lenA < lenB; // Otherwise, sort by length
}

// Function to sort the vector based on the length of the numbers
vector<int> sort_length(vector<int> arr)
{
    sort(arr.begin(), arr.end(), compare);
    return arr;
}

// Function to test the sort_length function
void test_sort_length()
{
    vector<int> test1 = {123, 21, 2, 1000, 100};
    vector<int> expected1 = {2, 21, 100, 123, 1000};
    assert(sort_length(test1) == expected1);

    vector<int> test2 = {-21, -1000, -2, -100, -123};
    vector<int> expected2 = {-2, -21, -100, -123, -1000};
    assert(sort_length(test2) == expected2);

    vector<int> test3 = {100, 10, 2, 300, 400};
    vector<int> expected3 = {2, 10, 100, 300, 400};
    assert(sort_length(test3) == expected3);

    cout << "All tests passed successfully." << endl;
}

int main()
{
    test_sort_length();
    return 0;
}

