// File and mutex constants
const std::string CounterFile = "counter.dat";
const std::string MutexName = "Global\\SharedCounterMutex";

// Manages shared counter with mutex synchronization
class CounterManager
{
private:
    HANDLE mutex;

public:
    // Constructor: creates the mutex
    CounterManager()
    {
        mutex = CreateMutex(NULL, FALSE, MutexName.c_str());
    }

    // Destructor: closes the mutex handle
    ~CounterManager()
    {
        CloseHandle(mutex);
    }

    // Increments the counter in a thread-safe manner
    int IncrementCounter()
    {
        WaitForSingleObject(mutex, INFINITE);
        int counter = 0;
        std::ifstream file(CounterFile);
        if (file.is_open())
        {
            file >> counter;
            file.close();
        }
        counter++;
        std::ofstream fileOut(CounterFile);
        if (fileOut.is_open())
        {
            fileOut << counter;
            fileOut.close();
        }
        ReleaseMutex(mutex);
        return counter;
    }

    // Decrements the counter in a thread-safe manner
    int DecrementCounter()
    {
        WaitForSingleObject(mutex, INFINITE);
        int counter = 0;
        std::ifstream file(CounterFile);
        if (file.is_open())
        {
            file >> counter;
            file.close();
        }
        counter--;
        std::ofstream fileOut(CounterFile);
        if (fileOut.is_open())
        {
            fileOut << counter;
            fileOut.close();
        }
        ReleaseMutex(mutex);
        return counter;
    }
};

