// Checks if a number is prime
bool is_prime(int n)
{
    if(n <= 1) return false;
    for(int i=2; i*i<=n; ++i)
    {
        if(n % i == 0) return false;
    }
    return true;
}

int main()
{
    // Prints all prime numbers from 2 to 100
    for(int i=2; i<=100; ++i)
    {
        if(is_prime(i))
        {
            std::cout<<i<<std::endl;
        }
    }
    return 0;

}

