// Swaps two integers using pointers
void swap(int* m, int* n)
{
    int t = *m;
    *m = *n;
    *n = t;
}

// Sorts three integers in descending order
void Descend(int &a, int &b, int &c)
{
    if(a < b)
    {
        swap(&a, &b);
    }
    if(a < c)
    {
        swap(&a, &c);
    }
    if(b < c)
    {
        swap(&b, &c);
    }
}

