// Doubly Linked List class
class DoublyLinkedList {
private:
    Node* head;
    Node* tail;
    Node* minNode;
    Node* maxNode;

public:
    // Constructor
    DoublyLinkedList() : head(nullptr), tail(nullptr), minNode(nullptr), maxNode(nullptr) {}

    // Insert a new value into the list
    void insert(int value) {
        Node* newNode = new Node(value);

        if (head == nullptr) {
            head = tail = minNode = maxNode = newNode;
        } else {
            newNode->prev = tail;
            tail->next = newNode;
            tail = newNode;

            if (value < minNode->value) {
                minNode = newNode;
            }
            if (value > maxNode->value) {
                maxNode = newNode;
            }
        }
    }

    // Remove a value from the list
    void remove(int value) {
        Node* current = head;
        while (current != nullptr) {
            if (current->value == value) {
                if (current->prev) {
                    current->prev->next = current->next;
                } else {
                    head = current->next;
                }

                if (current->next) {
                    current->next->prev = current->prev;
                } else {
                    tail = current->prev;
                }

                if (minNode == current) {
                    minNode = findMinNode();
                }
                if (maxNode == current) {
                    maxNode = findMaxNode();
                }

                delete current;
                return;
            }
            current = current->next;
        }
    }

    // Get minimum value
    int getMin() const {
        return minNode ? minNode->value : std::numeric_limits<int>::max();
    }

    // Get maximum value
    int getMax() const {
        return maxNode ? maxNode->value : std::numeric_limits<int>::min();
    }

private:
    // Helper function to find minimum node
    Node* findMinNode() const {
        Node* minNode = head;
        Node* current = head;
        while (current != nullptr) {
            if (current->value < minNode->value) {
                minNode = current;
            }
            current = current->next;
        }
        return minNode;
    }

    // Helper function to find maximum node
    Node* findMaxNode() const {
        Node* maxNode = head;
        Node* current = head;
        while (current != nullptr) {
            if (current->value > maxNode->value) {
                maxNode = current;
            }
            current = current->next;
        }
        return maxNode;
    }
};

// Main function
int main()
{
    DoublyLinkedList list;
    list.insert(10);
    list.insert(5);
    list.insert(15);
    list.insert(3);

    std::cout << "Min: " << list.getMin() << std::endl; // Output: Min: 3
    std::cout << "Max: " << list.getMax() << std::endl; // Output: Max: 15

    list.remove(15);
    std::cout << "Max after removing 15: " << list.getMax() << std::endl; // Output: Max: 10

    return 0;
}

#include <immintrin.h>
