    Q_PROPERTY(int theInt READ theInt WRITE setTheInt NOTIFY theIntChanged)

public:
    // Constructor: initializes the web channel and sets initial values
    hfbDisplayWidget(QWidget * parent) : QWebEngineView(parent)
