    Q_INVOKABLE int getInt(QVariant n)
    {
        int N = n.toInt();

        QString js = QString("PrintLog('c++ getInt(%1) fired!')").arg(N);
        setTheString(js);
        setTheInt(N);

        page()->runJavaScript(js, [=](const QVariant &rslt){
            qDebug() << js << " -> " << rslt;
        });
        return N * 100;
    }

    // Method callable from JavaScript: adds 0.12345 to input after logging
    Q_INVOKABLE double getDouble(QVariant d)
    {
        double D = d.toDouble();

        QString js = QString("PrintLog('c++ getDouble(%1) fired!')").arg(D);
        page()->runJavaScript(js, [=](const QVariant &rslt){
            qDebug() << js << " -> " << rslt;
        });

        return (D + 0.12345);
    }

    // Method callable from JavaScript: wraps input string in a message after logging
    Q_INVOKABLE QString getString(QVariant s)
    {
        QString S = s.toString();

        QString js = QString("PrintLog('c++ getString(%1) fired!')").arg(S);
        page()->runJavaScript(js, [=](const QVariant &rslt){
            qDebug() << js << " -> " << rslt;
        });

        return (QString("c++ called with:'") + S + QString("'"));
    }

    // Getter for theString property
    QString theString() const { return _theString; }

    // Setter for theString property with change detection and signal emission
    void setTheString(const QString &value)
    {
        if (_theString != value) {
            _theString = value;
            emit theStringChanged();
        }
    }

    // Getter for theInt property
    int theInt() const { return _theInt; }

    // Setter for theInt property with change detection and signal emission
    void setTheInt(int value)
    {
        if (_theInt != value) {
            _theInt = value;
            emit theIntChanged();
        }
    }

signals:
    // Notification signals for property changes
    void theStringChanged();
    void theIntChanged();

private:
    // Private member variables backing the properties
    QString _theString;
    int _theInt;
};

#include <cuda_runtime.h>

// Kernel function to convert Bayer pattern (GRBG) to RGB
__global__ void convertGRBG(uchar4 *d_output, uint width, uint height)
{
    int x = blockIdx.x * blockDim.x + threadIdx.x;
    int y = blockIdx.y * blockDim.y + threadIdx.y;

    if(x < width && y < height)
    {
        // Load the Bayer pattern data from global memory
        uchar bayer = tex2D(tex, x, y);

        // Perform demosaicing
        uchar4 pixel;
        // Example demosaicing logic (simplified)
        if(y % 2 == 0)
        {
            if(x % 2 == 0)
            {
                // GR
                pixel.x = bayer; // R
                pixel.y = (tex2D(tex, x, y - 1) + tex2D(tex, x, y + 1) + tex2D(tex, x - 1, y) + tex2D(tex, x + 1, y)) / 4; // G
                pixel.z = (tex2D(tex, x - 1, y - 1) + tex2D(tex, x - 1, y + 1) + tex2D(tex, x + 1, y - 1) + tex2D(tex, x + 1, y + 1)) / 4; // B
            }
            else
            {
                // BG
                pixel.x = (tex2D(tex, x - 1, y) + tex2D(tex, x + 1, y)) / 2; // R
                pixel.y = (tex2D(tex, x, y - 1) + tex2D(tex, x, y + 1)) / 2; // G
                pixel.z = bayer; // B
            }
        }
        else
        {
            if(x % 2 == 0)
            {
                // GB
                pixel.x = (tex2D(tex, x, y - 1) + tex2D(tex, x, y + 1)) / 2; // R
                pixel.y = (tex2D(tex, x - 1, y) + tex2D(tex, x + 1, y)) / 2; // G
                pixel.z = bayer; // B
            }
            else
            {
                // RG
                pixel.x = bayer; // R
                pixel.y = (tex2D(tex, x, y - 1) + tex2D(tex, x, y + 1) + tex2D(tex, x - 1, y) + tex2D(tex, x + 1, y)) / 4; // G
                pixel.z = (tex2D(tex, x - 1, y - 1) + tex2D(tex, x - 1, y + 1) + tex2D(tex, x + 1, y - 1) + tex2D(tex, x + 1, y + 1)) / 4; // B
            }
        }

        // Store the result in global memory
        d_output[y * width + x] = pixel;
    }
}

// Wrapper function to launch the kernel
void kernel_wrapper(int imageWidth, int imageHeight, dim3 blockSize, dim3 gridSize, uchar4 *d_output)
{
    convertGRBG<<<gridSize, blockSize>>>(d_output, imageWidth, imageHeight);
    cudaDeviceSynchronize();
}

