// Calculates the average of a vector of integers
double calculateAverage(const std::vector<int>& numbers)
{
    if(numbers.empty())
    {
        return 0;
    }
    int sum = 0;
    for(int number : numbers)
    {
        sum += number;
    }
    // Return the average as a double
    return static_cast<double>(sum) / numbers.size();
}

