// FileParser class for caching file contents
class FileParser {
public:
    // Singleton pattern - get single instance
    static FileParser& getInstance() {
        static FileParser instance;
        return instance;
    }

    // Parse and cache file content
    void parseFile(const std::string& filePath) {
        if (dataCache.find(filePath) == dataCache.end()) {
            std::ifstream file(filePath);
            std::string data;
            if (file.is_open()) {
                std::string line;
                while (std::getline(file, line)) {
                    data += line + "\n";
                }
                file.close();
                dataCache[filePath] = data;
            }
        }
    }

    // Get cached data for a file
    const std::string& getData(const std::string& filePath) {
        return dataCache[filePath];
    }

private:
    // Private constructor for singleton
    FileParser() {}
    // Cache storing file paths and their contents
    std::unordered_map<std::string, std::string> dataCache;
};

// JNI function to parse file from Java
extern "C" {
    JNIEXPORT void JNICALL Java_com_example_FileParser_nativeParseFile(JNIEnv* env, jobject obj, jstring filePath) {
        const char* path = env->GetStringUTFChars(filePath, nullptr);
        FileParser::getInstance().parseFile(path);
        env->ReleaseStringUTFChars(filePath, path);
    }

    // JNI function to retrieve parsed data
    JNIEXPORT jstring JNICALL Java_com_example_FileParser_nativeGetData(JNIEnv* env, jobject obj, jstring filePath) {
        const char* path = env->GetStringUTFChars(filePath, nullptr);
        std::string data = FileParser::getInstance().getData(path);
        env->ReleaseStringUTFChars(filePath, path);
        return env->NewStringUTF(data.c_str());
    }
}

