// 3D point structure
struct Point3D {
    double x, y, z;
    Point3D(double x = 0.0, double y = 0.0, double z = 0.0) : x(x), y(y), z(z) {}

    // Dot product operator
    double operator*(const Point3D& other) const {
        return x * other.x + y * other.y + z * other.z;
    }

    // Subtraction operator
    Point3D operator-(const Point3D& other) const {
        return Point3D(x - other.x, y - other.y, z - other.z);
    }

    // Scalar multiplication
    Point3D operator*(double scalar) const {
        return Point3D(x * scalar, y * scalar, z * scalar);
    }
};

// Hermite curve structure
struct HermiteCurve {
    Point3D point1, point2, vector1, vector2;
    HermiteCurve(Point3D p1, Point3D p2, Point3D v1, Point3D v2) : point1(p1), point2(p2), vector1(v1), vector2(v2) {}

    Point3D point(double t) const {
        double t2 = t * t;
        double t3 = t2 * t;
        double a = 2 * t3 - 3 * t2 + 1;
        double b = -2 * t3 + 3 * t2;
        double c = t3 - 2 * t2 + t;
        double d = t3 - t2;
        Point3D p = a * point1 + b * point2 + c * vector1 + d * vector2;
        return p;
    }
};

// Solves cubic equation and returns maximum root
double cubicEquation(double a, double b, double c, double d) {
    double delta = b * b - 3 * a * c;
    double q = (-b + sqrt(delta)) / 2.0;
    double r = (-b - sqrt(delta)) / 2.0;
    double t1 = q / a;
    double t2 = r / a;
    double t3 = (-b / (3 * a));
    return fmax(t1, fmax(t2, t3));
}

// Computes intersection of two Hermite curves
Point3D hermiteIntersection(const HermiteCurve& curve1, const HermiteCurve& curve2) {
    Point3D A = curve1.point1 - curve2.point1;
    Point3D B = curve2.point2 - curve2.point1 - curve1.point2 + curve1.point1;
    Point3D C = curve1.point2 - curve1.point1 - curve2.vector1;
    Point3D D = curve2.vector1;

    double a = 9 * (B * B) + 12 * (A * C);
    double b = 27 * (A * A) + 18 * (A * B) + 4 * (B * B) + 6 * (A * C) - 18 * (B * D);
    double c = 2 * (B * B * B) + 9 * (A * B * B) + 27 * (A * A * C) + 36 * (A * B * C) - 72 * (B * C * D);
    double d = -1 * (A.getNorm() + 3 * (B * B) + 6 * (A * C) - 3 * (B * D)) * (B * B) + 3 * A * B * C - 3 * B * B * D + 27 * (A * A * D) - 72 * (A * C * D);

    double t = cubicEquation(a, b, c, d);

    return curve1.point(t);
}

int main() {
    // Define control points and vectors for first curve
    Point3D p1a(0, 0, 0), p1b(1, 1, 1), v1a(1, 0, 0), v1b(0, 1, 0);

    // Define control points and vectors for second curve
    Point3D p2a(1, 0, 0), p2b(0, 1, 1), v2a(-1, 0, 0), v2b(0, -1, 0);

    HermiteCurve curve1(p1a, p1b, v1a, v1b);
    HermiteCurve curve2(p2a, p2b, v2a, v2b);

    Point3D intersection = hermiteIntersection(curve1, curve2);
    cout << "Intersection: " << intersection.x << ", " << intersection.y << ", " << intersection.z << endl;

    return 0;
}

