#include <fstream>
#include <iostream>
#include <omp.h>
#include <vector>

#include "bench_utils.h"
#include "superkmeans/common.h"
#include "superkmeans/hierarchical_superkmeans.h"
#include "superkmeans/superkmeans.h"

int main(int argc, char* argv[])
{
    std::string dataset = (argc > 1) ? std::string(argv[1]) : std::string("yahoo");

    auto it = bench_utils::DATASET_PARAMS.find(dataset);
    if (it == bench_utils::DATASET_PARAMS.end())
    {
        std::cerr << "Unknown dataset '" << dataset << "'\n";
        return 1;
    }

    const size_t n = it->second.first;
    const size_t d = it->second.second;
    const size_t n_clusters = 40000; // bench_utils::get_default_n_clusters(n);
    int n_iters = 5;
    float sampling_fraction = 1.0;

    std::string filename = bench_utils::get_data_path(dataset);

    const size_t THREADS = omp_get_max_threads();
    omp_set_num_threads(THREADS);

    std::cout << "=== Assign Benchmark ===" << std::endl;
    std::cout << "Dataset: " << dataset << " (n=" << n << ", d=" << d << ")\n";
    std::cout << "n_clusters=" << n_clusters << " n_iters=" << n_iters
              << " sampling_fraction=" << sampling_fraction << "\n";

    std::vector<float> data;
    try
    {
        data.reserve(n * d);
    }
    catch (const std::bad_alloc& e)
    {
        std::cerr << "Failed to allocate data vector for n*d = " << (n * d) << ": " << e.what()
                  << "\n";
        return 1;
    }

    std::ifstream file(filename, std::ios::binary);
    if (!file)
    {
        std::cerr << "Failed to open " << filename << std::endl;
        return 1;
    }

    file.read(reinterpret_cast<char*>(data.data()), n * d * sizeof(float));
    file.close();

    // --- Training ---
    skmeans::HierarchicalSuperKMeansConfig config;
    config.iters_mesoclustering = 3;
    config.iters_fineclustering = 5;
    config.iters_refinement = 0;
    config.verbose = false;
    config.n_threads = THREADS;
    config.unrotate_centroids = true;
    config.early_termination = false;
    config.sampling_fraction = sampling_fraction;
    config.use_blas_only = false;

    auto is_angular = std::find(
        bench_utils::ANGULAR_DATASETS.begin(), bench_utils::ANGULAR_DATASETS.end(), dataset
    );
    if (is_angular != bench_utils::ANGULAR_DATASETS.end())
    {
        std::cout << "Using spherical k-means" << std::endl;
        config.angular = true;
    }

    auto kmeans =
        skmeans::HierarchicalSuperKMeans<skmeans::Quantization::f32, skmeans::DistanceFunction::l2>(
            n_clusters, d, config
        );

    bench_utils::TicToc timer_train;
    timer_train.Tic();
    auto centroids = kmeans.Train(data.data(), n);
    timer_train.Toc();

    std::cout << "\nTraining completed in " << timer_train.GetMilliseconds() << " ms" << std::endl;

    // --- FastAssign (GEMM+PRUNING fast path) ---
    bench_utils::TicToc timer_fast;
    timer_fast.Tic();
    auto assignments_fast = kmeans.FastAssign(data.data(), centroids.data(), n, n_clusters);
    timer_fast.Toc();

    double fast_ms = timer_fast.GetMilliseconds();
    std::cout << "\nFastAssign: " << fast_ms << " ms" << std::endl;

    // --- Assign (brute force) ---
    bench_utils::TicToc timer_brute;
    timer_brute.Tic();
    auto assignments_brute = kmeans.Assign(data.data(), centroids.data(), n, n_clusters);
    timer_brute.Toc();

    double brute_ms = timer_brute.GetMilliseconds();
    std::cout << "Assign:     " << brute_ms << " ms" << std::endl;

    // --- Compare ---
    double speedup = brute_ms / fast_ms;
    size_t matches = 0;

    for (size_t i = 0; i < n; ++i)
    {
        if (assignments_fast[i] == assignments_brute[i])
        {
            ++matches;
        }
    }

    double match_pct = 100.0 * static_cast<double>(matches) / static_cast<double>(n);
    std::cout << "\nSpeedup: " << speedup << "x" << std::endl;
    std::cout << "Agreement: " << match_pct << "% (" << matches << "/" << n << ")" << std::endl;

    return 0;
}

#include <execinfo.h>
#include <errno.h>
#include <unistd.h>
#include <wait.h>
#include "Assert.h"
#include "../Filesystem.h"

namespace Gorgon :: Utils {

	// Backtrace function for crash handling
	void CrashHandler::Backtrace() 
	{
		// Allocate memory for backtrace storage
		void **trace=(void**)malloc((depth+skip+2)*sizeof(void*));
		int traced=backtrace(trace, depth+skip+2);

		char **messages = (char **)NULL;
		messages = backtrace_symbols(trace, traced);
		auto console = StdConsole();

		// Lambda to process and print each stack frame
		auto report=[&](int i) 
		{
			std::string message=messages[i];

			// Extract mangled function name from symbol
			auto mangledbegin=message.find_first_of('(');
			auto mangledend=message.find_first_of("+)", mangledbegin);

			std::string name=message.substr(mangledbegin+1, mangledend-mangledbegin-1);

			// Demangle the function name
			std::string demangled = demangle(name);

			// Create pipe for communication with child process
			int fd[2];
			if(pipe(fd)) return; //error

			// Fork to run addr2line in child process
			if(int pid=fork()) 
			{
				if(pid<0) return;
				wait(nullptr);

				close(fd[1]);
				char line[1024];

				auto len = read(fd[0], line, 1024);
				if(len<=0) return;
				line[len]=0;

				close(fd[0]);

				std::string data=line;

				// Parse filename:linenum from addr2line output
				auto pos=data.find_first_of(':');
				auto end=data.find_first_of(' ', pos);
				if(end==data.npos) end=data.length();

				std::string filename;
				try 
				{
					filename=Filesystem::Canonical(data.substr(0, pos));
				}
				catch(...) 
				{
					filename=data.substr(0, pos);
				}

				int linenum = String::To<int>(data.substr(pos+1, end-pos-1));

				//last directory before filename
				std::string dir=Filesystem::GetDirectory(filename);
				if(*dir.rbegin()=='/') 
				{
					dir.erase(dir.end()-1);
				}
				dir=Filesystem::GetFilename(dir);
				filename=Filesystem::GetFilename(filename);

				// Output formatted stack trace entry
				console.SetColor(Console::Magenta);
				if((i-skip-1)==1) 
				{
					console.SetBold();
				}
				std::cout<<"  ["<<(i-skip-1)<<"] ";
				console.SetBold(false);
				console.SetColor(Console::Default);

				if(!demangled.empty()) 
				{
					std::cout<<"In function ";
					console.SetColor(Console::Yellow);
					std::cout<<demangled<<" ";
				}
				else if(!name.empty()) 
				{
					std::cout<<"In function ";
					console.SetColor(Console::Yellow);
					std::cout<<name<<" ";
				}
				console.SetColor(Console::Default);
				std::cout<<"at ";

				if((i-skip-1)==1) 
				{
					console.SetColor(Console::Red);
				}
				std::cout<<"..."<<dir<<"/"<<filename;
				console.SetBold();
				std::cout<<":"<<linenum<<std::endl;
				console.Reset();
			}
			else 
			{
				errno=0;
				char ptr[40];
				sprintf(ptr, "%p", trace[i]);

				close(fd[0]);
				dup2 (fd[1], STDOUT_FILENO);
				dup2 (fd[1], STDERR_FILENO);

				// Execute addr2line to get source location
				execlp("addr2line", "addr2line", ptr, "-e", Filesystem::ExePath().c_str(),nullptr);

				perror("Addr2line is not installed.");

				exit(0);
			}
		};

#ifdef TEST
		for(int i=2;i<skip+2;i++) 
		{
			report(i);
		}
#endif			

		for(int i=skip+2; i<traced; i++) 
		{
			report(i);
		}
	}

