typedef double RealT;

// Loss function for optimization: linear objective with parameters
template<typename Real>
class LossEx16 : public ROL::StdObjective<Real> {
public:
  Real value( const std::vector<Real> &x, Real &tol ) override {
    std::vector<Real> p = ROL::StdObjective<Real>::getParameter();
    return std::inner_product(x.begin(), x.end(), p.begin(), static_cast<Real>(0));
  }

  void gradient( std::vector<Real> &g, const std::vector<Real> &x, Real &tol ) override {
    std::vector<Real> p = ROL::StdObjective<Real>::getParameter();
    g.assign(p.begin(), p.end());
  }

  void hessVec( std::vector<Real> &hv, const std::vector<Real> &v, const std::vector<Real> &x, Real &tol ) override {
    std::fill(hv.begin(), hv.end(), static_cast<Real>(0));
  }
};

// Budget constraint: sum of variables equals 1
template<typename Real>
class BudgetEx16 : public ROL::StdConstraint<Real> {
public:
  void value( std::vector<Real> &c, const std::vector<Real> &x, Real &tol ) override {
    c[0] = std::accumulate(x.begin(), x.end(), static_cast<Real>(0)) - static_cast<Real>(1);
  }

  void applyJacobian( std::vector<Real> &jv, const std::vector<Real> &v, const std::vector<Real> &x, Real &tol ) override {
    jv[0] = std::accumulate(v.begin(), v.end(), static_cast<Real>(0));
  }

  void applyAdjointJacobian( std::vector<Real> &ajv, const std::vector<Real> &v, const std::vector<Real> &x, Real &tol ) override {
    std::fill(ajv.begin(), ajv.end(), v[0]);
  }

  void applyAdjointHessian( std::vector<Real> &ahuv, const std::vector<Real> &u, const std::vector<Real> &v, const std::vector<Real> &x, Real &tol ) override {
    std::fill(ahuv.begin(), ahuv.end(), static_cast<Real>(0));
  }
};

// Helper function to print solution vector
void printSolution(const std::vector<RealT> &x,
                   std::ostream & outStream) {
  size_t dim = x.size();
  outStream << std::endl;
  outStream << "x = (";
  for ( size_t i = 0; i < dim-1; i++ ) {
    outStream << x[i] << ", ";
  }
  outStream << x[dim-1] << ")\n";
  outStream << std::endl;
}

int main(int argc, char* argv[]) {
  // feenableexcept(FE_DIVBYZERO | FE_INVALID | FE_OVERFLOW);  // Exception handling disabled
  ROL::GlobalMPISession mpiSession(&argc, &argv);

  // Control output verbosity based on command-line arguments
  int iprint     = argc - 1;
  bool print     = iprint > 0;
  ROL::Ptr<std::ostream> outStream;
  ROL::nullstream bhs; // outputs nothing
  if (iprint > 0)
    outStream = ROL::makePtrFromRef(std::cout);
  else
    outStream = ROL::makePtrFromRef(bhs);

  int errorFlag  = 0;

  try {
    /**********************************************************************************************/
    /************************* CONSTRUCT ROL ALGORITHM ********************************************/
    /**********************************************************************************************/
    // Load parameter list from XML file
    std::string filename = "input_16.xml";
    auto parlist = ROL::getParametersFromXmlFile(filename);
    ROL::ParameterList list = *parlist;
    list.sublist("General").set("Output Level", print ? 1 : 0);

    /**********************************************************************************************/
    /************************* CONSTRUCT SOL COMPONENTS *******************************************/
    /**********************************************************************************************/
    // Initialize decision variable vector
    size_t dim = 10;
    ROL::Ptr<ROL::StdVector<RealT>> x = ROL::makePtr<ROL::StdVector<RealT>>(dim, 0);

    // Generate random sampling bounds for Monte Carlo
    int nsamp = 1000;
    RealT offset(0);
    std::vector<std::vector<RealT>> bounds;
    for (size_t i = 0; i < dim; ++i) {
      RealT li = -static_cast<RealT>(rand()) / static_cast<RealT>(RAND_MAX);
      RealT ui =  static_cast<RealT>(rand()) / static_cast<RealT>(RAND_MAX);
      bounds.push_back({li, ui});
      *outStream << "  Asset "        << i << ":"
                 << "  Lower Bound: " << li
                 << "  Upper Bound: " << ui << std::endl;
      offset += ui / static_cast<RealT>(dim);
    }
    offset *= static_cast<RealT>(0.35);

    // Setup batch manager and sampler
    ROL::Ptr<ROL::BatchManager<RealT>> bman = ROL::makePtr<ROL::BatchManager<RealT>>();
    ROL::Ptr<ROL::SampleGenerator<RealT>> sampler =
        ROL::makePtr<ROL::MonteCarloGenerator<RealT>>(nsamp, bounds, bman);

    // Build loss function and constraint components
    ROL::Ptr<ROL::Objective<RealT>> loss = ROL::makePtr<LossEx16<RealT>>();
    loss->setParameter(sampler->getMyPoint(0));

    ROL::Ptr<ROL::Constraint<RealT>> losscon =
        ROL::makePtr<ROL::ConstraintFromObjective<RealT>>(loss);
    ROL::Ptr<ROL::SingletonVector<RealT>> mul_losscon =
        ROL::makePtr<ROL::SingletonVector<RealT>>(0);
    ROL::Ptr<ROL::SingletonVector<RealT>> u_losscon =
        ROL::makePtr<ROL::SingletonVector<RealT>>(offset);
    ROL::Ptr<ROL::BoundConstraint<RealT>> bnd_losscon =
        ROL::makePtr<ROL::Bounds<RealT>>(*u_losscon, false);

    // Budget constraint setup
    ROL::Ptr<ROL::Constraint<RealT>> budget = ROL::makePtr<BudgetEx16<RealT>>();
    ROL::Ptr<ROL::StdVector<RealT>> mul_budget =
        ROL::makePtr<ROL::StdVector<RealT>>(1, 0);

    // Construct stochastic optimization problem
    ROL::Ptr<ROL::StochasticProblem<RealT>> problem =
        ROL::makePtr<ROL::StochasticProblem<RealT>>(loss, x);
    problem->addLinearConstraint("Budget", budget, mul_budget);
    problem->addLinearConstraint("Loss", losscon, mul_losscon, bnd_losscon);

    // Validate and verify deterministic problem setup
    problem->finalize(false, true, *outStream);
    problem->check(true, *outStream);

    std::vector<std::pair<std::string, std::vector<RealT>>> sol;

    // Case 1: Risk-neutral (Variance-based) Markowitz portfolio
    problem->edit();
    ROL::ParameterList objlist;
    objlist.sublist("SOL").sublist("Objective").set("Type", "Deviation");
    objlist.sublist("SOL").sublist("Objective").sublist("Deviation Measure")
        .set("Name", "Variance");
    problem->makeObjectiveStochastic(objlist, sampler);

    ROL::ParameterList conlist;
    conlist.sublist("SOL").sublist("Loss").set("Type", "Risk Neutral");
    problem->makeLinearConstraintStochastic("Loss", conlist, sampler, bman);

    problem->finalize(false, true, *outStream);
    problem->check(true, *outStream);

    ROL::Ptr<ROL::Solver<RealT>> solver =
        ROL::makePtr<ROL::Solver<RealT>>(problem, *parlist);
    solver->solve(*outStream);
    errorFlag += (solver->getAlgorithmState()->statusFlag == ROL::EXITSTATUS_CONVERGED ? 0 : 1);
    printSolution(*x->getVector(), *outStream);

    ROL::Ptr<ROL::Vector<RealT>> xm = x->clone(); xm->set(*x);
    sol.push_back({"Risk Neutral", *x->getVector()});

    // Case 2: Mean Value (Expected Value) formulation
    problem->edit();
    problem->resetStochasticLinearConstraint("Loss");
    conlist.sublist("SOL").sublist("Loss").set("Type", "Mean Value");
    problem->makeLinearConstraintStochastic("Loss", conlist, sampler);
    problem->finalize(false, true, *outStream);
    problem->check(true, *outStream);

    solver = ROL::makePtr<ROL::Solver<RealT>>(problem, *parlist);
    solver->solve(*outStream);
    errorFlag += (solver->getAlgorithmState()->statusFlag == ROL::EXITSTATUS_CONVERGED ? 0 : 1);
    printSolution(*x->getVector(), *outStream);

    xm->axpy(-1.0, *x);
    errorFlag += (xm->norm() > 100.0 * std::sqrt(ROL::ROL_EPSILON<RealT>()) ? 1 : 0);
    sol.push_back({"Mean Value", *x->getVector()});

    // Case 3: bPOE with CVaR risk measure
    problem->edit();
    conlist.sublist("SOL").sublist("Loss").set("Type", "Risk Averse");
    conlist.sublist("SOL").sublist("Loss").sublist("Risk Measure").set("Name", "CVaR");
    conlist.sublist("SOL").sublist("Loss").sublist("Risk Measure").sublist("CVaR")
        .set("Confidence Level", 0.95);
    conlist.sublist("SOL").sublist("Loss").sublist("Risk Measure").sublist("CVaR")
        .set("Convex Combination Parameter", 1.0);
    conlist.sublist("SOL").sublist("Loss").sublist("Risk Measure").sublist("CVaR")
        .set("Smoothing Parameter", 1e-4);
    conlist.sublist("SOL").sublist("Loss").sublist("Risk Measure").sublist("CVaR")
        .sublist("Distribution").set("Name", "Parabolic");
    conlist.sublist("SOL").sublist("Loss").sublist("Risk Measure").sublist("CVaR")
        .sublist("Distribution").sublist("Parabolic")
        .set("Lower Bound", -0.5);
    conlist.sublist("SOL").sublist("Loss").sublist("Risk Measure").sublist("CVaR")
        .sublist("Distribution").sublist("Parabolic")
        .set("Upper Bound", 0.5);

    problem->removeLinearConstraint("Loss");
    problem->addConstraint("Loss", losscon, mul_losscon, bnd_losscon);
    problem->makeConstraintStochastic("Loss", conlist, sampler);

    problem->finalize(false, true, *outStream);
    problem->check(true, *outStream);

    solver = ROL::makePtr<ROL::Solver<RealT>>(problem, *parlist);
    solver->solve(*outStream);
    errorFlag += (solver->getAlgorithmState()->statusFlag == ROL::EXITSTATUS_CONVERGED ? 0 : 1);
    printSolution(*x->getVector(), *outStream);
    sol.push_back({"bPOE", *x->getVector()});

    // Output final solutions in formatted table
    *outStream << std::endl << std::scientific << std::setprecision(6);
    for (auto it = sol.begin(); it != sol.end(); ++it) {
      *outStream << "  ";
      *outStream << std::setw(20) << std::left << std::get<0>(*it);
      for (const auto& xi : std::get<1>(*it))
        *outStream << std::setw(18) << std::left << xi;
      *outStream << std::endl;
    }
    *outStream << std::endl;

  } catch (std::logic_error& err) {
    *outStream << err.what() << "\n";
    errorFlag = -1000;
  } // end try-catch

  if (errorFlag != 0)
    std::cout << "End Result: TEST FAILED\n";
  else
    std::cout << "End Result: TEST PASSED\n";

  return 0;
}

