#include "test/jemalloc_test.h"

// Test for sz_psz2ind function
TEST_BEGIN(test_sz_psz2ind)
{
    /*
     * Testing page size classes which reside prior to the regular group
     * with all size classes divisible by page size.
     * For x86_64 Linux, it's 4096, 8192, 12288, 16384, with corresponding
     * pszind 0, 1, 2 and 3.
     */
    for (size_t i = 0; i < SC_NGROUP; i++) {
        for (size_t psz = i * PAGE + 1; psz <= (i + 1) * PAGE; psz++) {
            pszind_t ind = sz_psz2ind(psz);
            expect_zu_eq(ind, i, "Got %u as sz_psz2ind of %zu", ind,
                psz);
        }
    }

    sc_data_t data;
    memset(&data, 0, sizeof(data));
    sc_data_init(&data);

    /*
     * 'base' is the base of the first regular group with all size classes
     * divisible by page size.
     * For x86_64 Linux, it's 16384, and base_ind is 36.
     */
    size_t base_psz = 1 << (SC_LG_NGROUP + LG_PAGE);
    size_t base_ind = 0;
    while (base_ind < SC_NSIZES &&
        reg_size_compute(data.sc[base_ind].lg_base,
            data.sc[base_ind].lg_delta,
            data.sc[base_ind].ndelta) < base_psz) {
        base_ind++;
    }
    expect_zu_eq(
        reg_size_compute(data.sc[base_ind].lg_base,
            data.sc[base_ind].lg_delta, data.sc[base_ind].ndelta),
        base_psz, "Size class equal to %zu not found", base_psz);

    /*
     * Test different sizes falling into groups after the 'base'. The
     * increment is PAGE / 3 for the execution speed purpose.
     */
    base_ind -= SC_NGROUP;
    for (size_t psz = base_psz; psz <= 64 * 1024 * 1024; psz += PAGE / 3) {
        pszind_t ind = sz_psz2ind(psz);
        sc_t gt_sc = data.sc[ind + base_ind];
        expect_zu_gt(psz,
            reg_size_compute(gt_sc.lg_base, gt_sc.lg_delta,
                gt_sc.ndelta),
            "Got %u as sz_psz2ind of %zu", ind, psz);
        sc_t le_sc = data.sc[ind + base_ind + 1];
        expect_zu_le(psz,
            reg_size_compute(le_sc.lg_base, le_sc.lg_delta,
                le_sc.ndelta),
            "Got %u as sz_psz2ind of %zu", ind, psz);
    }

    pszind_t max_ind = sz_psz2ind(SC_LARGE_MAXCLASS + 1);
    expect_lu_eq(max_ind, SC_NPSIZES,
        "Got %u as sz_psz2ind of %llu", max_ind, SC_LARGE_MAXCLASS);
}
TEST_END

int
main(void)
{
    return test(test_sz_psz2ind);
}

#include <iostream>
#include <vector>
#include <numeric>
#include <algorithm>
#include <random>
#include <chrono>

using namespace std;

// Main function for Max-Cut approximation using Local Search
int main()
{
    // Optimize I/O operations for speed
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    // Adjacency list to store the graph
    // Using 1-based indexing for vertices
    vector<vector<int>> adj(n + 1);
    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    // Best solution found so far
    // Initialize with all 0s
    vector<int> best_s(n + 1, 0);
    long long max_cut_size = -1;

    // Time management
    // Set a time limit slightly under typical limits (usually 1s or 2s)
    // 0.90 seconds is generally safe for 1s limits
    double time_limit = 0.90;
    auto start_time = chrono::high_resolution_clock::now();

    // Random number generator using steady_clock
    mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());

    // Processing order vector
    vector<int> p(n);
    iota(p.begin(), p.end(), 1);
    vector<int> current_s(n + 1);

    // Main optimization loop (Randomized Local Search)
    // We run multiple restarts until the time limit is reached
    while (true) {
        // Random initialization of the partition
        for (int i = 1; i <= n; ++i) {
            current_s[i] = rng() & 1;
        }

        // Hill Climbing / Local Search
        // Ideally, in a local optimum, every vertex has at least as many neighbors
        // in the other set as in its own set.
        bool improved = true;
        while (improved) {
            improved = false;

            // Iterate vertices in random order to avoid bias and cycles
            shuffle(p.begin(), p.end(), rng);

            for (int u : p) {
                int same_set_neighbors = 0;
                int diff_set_neighbors = 0;
                for (int v : adj[u]) {
                    if (current_s[u] == current_s[v]) {
                        same_set_neighbors++;
                    } else {
                        diff_set_neighbors++;
                    }
                }

                // If moving u to the other set increases the number of cut edges
                // (i.e. currently has more neighbors in the same set than the other)
                // then flip it.
                if (same_set_neighbors > diff_set_neighbors) {
                    current_s[u] ^= 1;
                    improved = true;
                }
            }
        }

        // Calculate the cut size for the current stable partition
        long long current_cut = 0;
        for (int u = 1; u <= n; ++u) {
            // Count cut edges: iterate over vertices in set 0 and check neighbors in set 1
            // This counts each cut edge exactly once (from the endpoint in set 0)
            if (current_s[u] == 0) {
                for (int v : adj[u]) {
                    if (current_s[v] == 1) {
                        current_cut++;
                    }
                }
            }
        }

        // Update best solution found
        if (current_cut > max_cut_size) {
            max_cut_size = current_cut;
            best_s = current_s;
        }

        // Check if time limit exceeded
        auto curr_time = chrono::high_resolution_clock::now();
        chrono::duration<double> elapsed = curr_time - start_time;
        if (elapsed.count() > time_limit) break;
    }

    // Output the result
    for (int i = 1; i <= n; ++i) {
        cout << best_s[i] << (i == n ? "" : " ");
    }
    cout << "\n";

    return 0;
}

#include <iostream>
#include <magic_enum/magic_enum.hpp>
#include <magic_enum/magic_enum_iostream.hpp>

// Define an enum class for colors with specific underlying values
enum class Color : int { RED = -10, BLUE = 0, GREEN = 10 };

// Template function to convert enum value to its underlying integer type
template <typename E>
auto to_integer(magic_enum::Enum<E> value) {
  // magic_enum::Enum<E> - C++17 Concept for enum type.
  return static_cast<magic_enum::underlying_type_t<E>>(value);
}

int main()
{
    // Enum variable to string name.
    Color c1 = Color::RED;
    auto c1_name = magic_enum::enum_name(c1);
    std::cout << c1_name << std::endl; // RED

    // String enum name sequence.
    constexpr auto names = magic_enum::enum_names<Color>();
    std::cout << "Color names:";
    for (const auto& n : names) {
        std::cout << " " << n;
    }
    std::cout << std::endl;
    // Color names: RED BLUE GREEN

    // String name to enum value.
    auto c2 = magic_enum::enum_cast<Color>("BLUE");
    if (c2.has_value()) {
        std::cout << "BLUE = " << to_integer(c2.value()) << std::endl; // BLUE = 0
    }

    // Case insensitive enum_cast.
    c2 = magic_enum::enum_cast<Color>("blue", magic_enum::case_insensitive);
    if (c2.has_value()) {
        std::cout << "BLUE = " << to_integer(c2.value()) << std::endl; // BLUE = 0
    }

    // Integer value to enum value.
    auto c3 = magic_enum::enum_cast<Color>(10);
    if (c3.has_value()) {
        std::cout << "GREEN = " << magic_enum::enum_integer(c3.value()) << std::endl; // GREEN = 10
    }

    // Enum value to integer value.
    auto c4_integer = magic_enum::enum_integer(Color::RED);
    std::cout << "RED = " << c4_integer << std::endl; // RED = -10

    using magic_enum::iostream_operators::operator<<; // out-of-the-box ostream operator for all enums.

    // Ostream operator for enum.
    std::cout << "Color: " << c1 << " " << c2 << " " << c3 << std::endl; // Color: RED BLUE GREEN

    // Number of enum values.
    std::cout << "Color enum size: " << magic_enum::enum_count<Color>() << std::endl; // Color size: 3

    // Indexed access to enum value.
    std::cout << "Color[0] = " << magic_enum::enum_value<Color>(0) << std::endl; // Color[0] = RED

    // Enum value sequence.
    constexpr auto values = magic_enum::enum_values<Color>();
    std::cout << "Colors values:";
    for (const auto c : values) {
        std::cout << " " << c; // Ostream operator for enum.
    }
    std::cout << std::endl;
    // Color values: RED BLUE GREEN

    enum class Flags { A = 1, B = 2, C = 4, D = 8 };
    using namespace magic_enum::bitwise_operators; // out-of-the-box bitwise operators for all enums.

    // Support operators: ~, |, &, ^, |=, &=, ^=.
    Flags flag = Flags::A | Flags::C;
    std::cout << flag << std::endl; // 5

    enum color { red, green, blue };

    // Checks whether type is an Unscoped enumeration.
    static_assert(magic_enum::is_unscoped_enum_v<color>);
    static_assert(!magic_enum::is_unscoped_enum_v<Color>);
    static_assert(!magic_enum::is_unscoped_enum_v<Flags>);

    // Checks whether type is an Scoped enumeration.
    static_assert(!magic_enum::is_scoped_enum_v<color>);
    static_assert(magic_enum::is_scoped_enum_v<Color>);
    static_assert(magic_enum::is_scoped_enum_v<Flags>);

    // Enum pair (value enum, string enum name) sequence.
    constexpr auto entries = magic_enum::enum_entries<Color>();
    std::cout << "Colors entries:";
    for (const auto& e : entries) {
        std::cout << " " << e.second << " = " << static_cast<int>(e.first);
    }
    std::cout << std::endl;
    // Color entries: RED = -10 BLUE = 0 GREEN = 10

    return 0;
}

