	bool err = fxp_parse(&result, str, &end);
	expect_true(err, "Expected a parse error on: %s", str);
	expect_ptr_eq((void *)0x123, end,
	    "Parse error shouldn't change results");
	expect_u32_eq(result, FXP_INIT_INT(333),
	    "Parse error shouldn't change results");
}

