// A modified jenkins_one_at_a_time_hash initialized by non-zero,
// so that simple_hash(0) != 0. See also
// https://en.wikipedia.org/wiki/Jenkins_hash_function
static uint32_t simple_hash(const uint8_t *Data, size_t Size)
{
    uint32_t Hash = 0x12039854;
    for(uint32_t i=0;i<Size;i++)
    {
        Hash += Data[i];
        Hash += (Hash << 10);
        Hash ^= (Hash >> 6);
    }
    Hash += (Hash << 3);
    Hash ^= (Hash >> 11);
    Hash += (Hash << 15);
    return Hash;
}

extern "C" int LLVMFuzzerTestOneInput(const uint8_t *Data, size_t Size)
{
    if(Size < 14)
        return 0;

    uint32_t Hash = simple_hash(&Data[0], Size - 4);
    uint32_t Want = reinterpret_cast<const uint32_t *>(&Data[Size - 4])[0];

    if(Hash != Want)
        return 0;

    // Found a collision!
    fprintf(stderr, "BINGO; simple_hash defeated: %x == %x\n", (unsigned int)Hash,
            (unsigned int)Want);
    exit(1);

    return 0;
}

#include "group_sum_matrix.h"

// Computes the group sum matrix
template <typename T>
IGL_INLINE void igl::group_sum_matrix(
  const Eigen::Matrix<int,Eigen::Dynamic,1> & G,
  const int k,
  Eigen::SparseMatrix<T>& A)
{
  // number of vertices
  int n = G.rows();
  assert(k > G.maxCoeff());

  A.resize(k,n);

  // builds A such that A(i,j) = 1 where i corresponds to group i and j
  // corresponds to vertex j
  // Loop over vertices
  for(int j = 0; j < n; j++)
  {
    A.insert(G(j), j) = 1;
  }

  A.makeCompressed();
}

// Overload without explicit group count
template <typename T>
IGL_INLINE void igl::group_sum_matrix(
  const Eigen::Matrix<int,Eigen::Dynamic,1> & G,
  Eigen::SparseMatrix<T>& A)
{
  return group_sum_matrix(G, G.maxCoeff()+1, A);
}

