#include "transport.h"

enum p2pType { P2P_DIRECT, P2P_INTERMEDIATE, P2P_IPC, P2P_CUMEM };

extern int useMemcpy;

struct ncclP2pBuff {
  void *directPtr;
  size_t size;
  ncclIpcDesc ipcDesc;
};

struct ncclP2pRequest {
  size_t size;
  int refcount;
};

struct p2pIpcExpInfo {
  ncclIpcDesc ipcDesc;
  bool legacyIpcCap;
  int impFd;
  size_t size;
  uintptr_t offset;
};

struct p2pShm {
  struct ncclSendMem sendMem;
  struct ncclRecvMem recvMem;
};

struct p2pShmProxyInfo {
  // Shared memory between proxy and receiving GPU
  struct p2pShm *shm;
  struct p2pShm *devShm;
  ncclShmIpcDesc_t desc;
  // Intermediate step for sender
  struct ncclRecvMem *ceRecvMem;
  char *ceDevBuff;
  // Receiver buffer
  char *recvFifo;
  // Used by CE memcpy progress only
  uint64_t step;
  hipStream_t stream;
  hipEvent_t events[NCCL_STEPS];
};

struct p2pConnectInfo {
  int rank;
  int read;
  struct ncclP2pBuff p2pBuff;
  // Used by CE memcpy
  ncclShmIpcDesc_t desc;
};

struct p2pResources {
  enum p2pType type;
  union {
    struct ncclSendMem *sendDevMem;
    struct ncclRecvMem *recvDevMem;
  };
  void *sendMemIpc;
  int sendMemSameProc;
  void *recvMemIpc;
  int recvMemSameProc;
  // CE memcpy support
  struct p2pShmProxyInfo proxyInfo;
  struct p2pShm *shm;
  struct p2pShm *devShm;
  int shmSize;
  ncclShmHandle_t handle;
  ncclShmIpcDesc_t desc;
  uint32_t *next_hdp_reg; // Next GPU in ring (for p2p transport use only)
};

struct ncclIpcCleanupCallback {
  struct ncclCommCallback base;
  struct ncclComm *comm;
  struct ncclReg *reg;
};

