// Decides equality of natural numbers
bool Opaque::nat_eq_dec(const unsigned int n, const unsigned int x)
{
    if (n <= 0)
    {
        if (x <= 0)
        {
            return true;
        }
        else
        {
            unsigned int _x = x - 1;
            return false;
        }
    }
    else
    {
        unsigned int n0 = n - 1;
        if (x <= 0)
        {
            return false;
        }
        else
        {
            unsigned int n1 = x - 1;
            if (nat_eq_dec(n0, n1))
            {
                return true;
            }
            else
            {
                return false;
            }
        }
    }
}

// Wrapper for nat_eq_dec
bool Opaque::are_equal(const unsigned int n, const unsigned int m)
{
    if (nat_eq_dec(n, m))
    {
        return true;
    }
    else
    {
        return false;
    }
}

