int main()
{
    int n;
    cin >> n;

    // Find smallest integer k such that k^2 >= n
    int k = 0;
    while(k * k < n) ++k;

    double L = k;

    // Output with fixed precision
    cout << fixed << setprecision(6) << L << endl;

    // Generate coordinates for each point
    for(int i = 0; i < n; ++i)
    {
        int row = i / k;
        int col = i % k;

        double x = col + 0.5;
        double y = row + 0.5;

        cout << x << " " << y << " " << 0.0 << endl;
    }

    return 0;
}

