#include <bits/stdc++.h>
using namespace std;
using ll = long long;

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    if(!(cin >> T)) return 0;

    while(T--)
    {
        int n, m;
        ll c;
        cin >> n >> m >> c;

        vector<ll> a(n+1), b(m+1);
        for(int i=1; i<=n; i++) cin >> a[i];
        for(int i=1; i<=m; i++) cin >> b[i];

        // prefix sums of a
        vector<ll> P(n+1, 0);
        for(int i=1; i<=n; i++) P[i] = P[i-1] + a[i];

        // thresholds t_k
        vector<ll> t(m+1, 0);
        for(int i=1; i<=m; i++) t[i] = t[i-1] + b[i];

        // helper K(x) = max k s.t. t[k] <= x
        auto K = [&](ll x)->int{
            if(x < 0) return 0;
            int k = upper_bound(t.begin(), t.end(), x) - t.begin() - 1;
            if(k < 0) k = 0;
            if(k > m) k = m;
            return k;
        };

        // Divide and conquer optimization (assumes monotone opt index)
        vector<ll> dp(n+1, LLONG_MIN/4);
        dp[0] = 0; // base case: no days processed yet

        vector<ll> dp2(n+1, LLONG_MIN/4);
        function<void(int,int,int,int)> dc = [&](int L, int R, int optL, int optR){
            if(L > R) return;
            int mid = (L + R) >> 1;
            ll best = LLONG_MIN/4;
            int bestPos = optL;
            int jlim = min(mid-1, optR);

            for(int j = optL; j <= jlim; ++j){
                ll val = dp[j] + (ll)K(P[mid] - P[j]) - c;
                if(val > best){
                    best = val;
                    bestPos = j;
                }
            }

            dp2[mid] = best;
            dc(L, mid-1, optL, bestPos);
            dc(mid+1, R, bestPos, optR);
        };

        // Base: dp2[0] should be 0 (no days, no segments)
        dp2[0] = 0;
        // Compute dp2[1..n]
        dc(1, n, 0, n-1);

        // The answer is dp2[n]
        cout << dp2[n] << "\n";
    }

    return 0;
}

