// Fuzzer entry point
extern "C" int LLVMFuzzerTestOneInput(const uint8_t *Data, size_t Size)
{
    // Lambda function to check input
    auto C = [&] {
        if (Size >= 2 && Data[0] == 'H')
        {
            std::cout << "BINGO; Found the target, exiting\n";
            abort();
        }
    };

    // Create multiple threads
    std::thread T[] = {
        std::thread(C),
        std::thread(C),
        std::thread(C),
        std::thread(C),
        std::thread(C),
        std::thread(C)
    };

    // Join all threads
    for (auto &X : T)
        X.join();

    return 0;
}

