// A simple window class
class SimpleWindow : public BWindow
{
public:
	SimpleWindow(BRect frame)
		:
		BWindow(frame, "A Haiku Window", B_TITLED_WINDOW, B_QUIT_ON_WINDOW_CLOSE)
	{
	}

