// Handles the burial UI state
void uiBurialHandle(InputState& in)
{
    // Check if select or encoder press was triggered
    if (!(in.selectOnce || in.encoderPressOnce))
    {
        uiDrainKb(in);
        clearInputLatch();
        return;
    }

    // Show farewell message and force UI update
    ui_showMessage("Rest in peace...");
    forceRenderUIOnce();
    delay(950);

    // Reset death dirge sound latch
    soundResetDeathDirgeLatch();

    // Delete pet data
    saveManagerDeletePetOnly();

    // Short delay before restart
    delay(50);

    // Restart ESP
    ESP.restart();
}

