TEST_F(TestGenericClientCompat, shared_ptr_type_is_valid) {
  compat::GenericServiceClient::SharedPtr client =
      compat::create_generic_service_client(
          node_.get(), "/test/type_alias_service", "std_srvs/srv/Trigger"
      );
