TEST_F(TestGenericClientCompat, can_cast_to_client_base) {
  auto client = compat::create_generic_service_client(
      node_.get(), "/test/cast_service", "std_srvs/srv/Trigger"
  );
  ASSERT_NE(client, nullptr);

