#include <vector>
using namespace std;

// Solution class to reverse string in-place
class Solution {
public:
    // Reverses the character vector
    void reverseString(vector<char>& s) {
        int left = 0, right = s.size() - 1;
        while (left < right) {
            swap(s[left], s[right]);
            left++;
            right--;
        }
    }
};

