    sendCommand(QByteArray::fromHex("AA023737"));
}

#include <vector>
#include <algorithm>

using namespace std;

class Solution {
public:
    vector<int> sortByBits(vector<int>& arr) {
        // Sort by number of 1 bits, then by value if tie
        sort(arr.begin(), arr.end(), [](int a, int b) {
            int ca = __builtin_popcount(a);
            int cb = __builtin_popcount(b);

            if (ca == cb) 
                return a < b;      // tie-breaker: smaller value first
            return ca < cb;        // sort primarily by bit count
        });

        return arr;
    }
};

