// Performs safe subtraction with underflow protection
unsigned int NatSubUnderflowSafe::sub_checked(const unsigned int _x0,
                                              const unsigned int _x1)
{
    // Check for underflow: if (_x0 - _x1) > _x0, then underflow occurred
    return (((_x0 - _x1) > _x0 ? 0 : (_x0 - _x1)));
}

// Alternative subtraction implementation
unsigned int NatSubUnderflowSafe::sub_alt(const unsigned int a,
                                          const unsigned int b)
{
    // Check for underflow: if (b - a) > b, then underflow occurred
    return (((b - a) > b ? 0 : (b - a)));
}

