#define LOCTEXT_NAMESPACE "GitSourceControl"

FName FGitConnectWorker::GetName() const
{
	return "Connect";
}

bool FGitConnectWorker::Execute(FGitSourceControlCommand& InCommand)
{
	check(InCommand.Operation->GetName() == GetName());

	// Check Git Availability
	if (0 < InCommand.PathToGitBinary.Len() && GitSourceControlUtils::CheckGitAvailability(InCommand.PathToGitBinary))
	{
		// Now update the status of assets in Content/ directory and also Config files
		TArray<FString> ProjectDirs;
		ProjectDirs.Add(FPaths::ConvertRelativePathToFull(FPaths::ProjectContentDir()));
		ProjectDirs.Add(FPaths::ConvertRelativePathToFull(FPaths::ProjectConfigDir()));

		InCommand.bCommandSuccessful = GitSourceControlUtils::RunUpdateStatus(
			InCommand.PathToGitBinary,
			InCommand.PathToRepositoryRoot,
			ProjectDirs,
			InCommand.ErrorMessages,
			States
		);

		if (!InCommand.bCommandSuccessful || InCommand.ErrorMessages.Num() > 0)
		{
			StaticCastSharedRef<FConnect>(InCommand.Operation)->SetErrorText(
				LOCTEXT("NotAGitRepository", "Failed to enable Git source control. You need to initialize the project as a Git repository first.")
			);
			InCommand.bCommandSuccessful = false;
		}
	}
	else
	{
		StaticCastSharedRef<FConnect>(InCommand.Operation)->SetErrorText(
			LOCTEXT("GitNotFound", "Failed to enable Git source control. You need to install Git and specify a valid path to git executable.")
		);
		InCommand.bCommandSuccessful = false;
	}

	return InCommand.bCommandSuccessful;
}

