#undef LOCTEXT_NAMESPACE

#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

const int N = 30;
int b[N][N]; // ball numbers

struct Swap {
    int x1, y1, x2, y2;
};

vector<Swap> swaps;

// Perform a swap and record it
void perform_swap(int x1, int y1, int x2, int y2)
{
    swaps.push_back({x1, y1, x2, y2});
    swap(b[x1][y1], b[x2][y2]);
}

int main()
{
    // Input: read the ball numbers into the triangular array
    for (int x = 0; x < N; ++x)
    {
        for (int y = 0; y <= x; ++y)
        {
            cin >> b[x][y];
        }
    }

    int total_swaps = 0;
    const int MAX_SWAPS = 10000;
    bool changed = true;

    // Heapify process: repeatedly sift down elements until no more swaps needed or limit reached
    while (changed && total_swaps < MAX_SWAPS)
    {
        changed = false;

        // Bottom-up pass: process from second-last row up to the top
        for (int x = N-2; x >= 0; --x)
        {
            for (int y = 0; y <= x; ++y)
            {
                // Sift down the element at position (x, y)
                int cx = x, cy = y;

                while (cx < N-1)
                {
                    int cur = b[cx][cy];
                    int left = b[cx+1][cy];
                    int right = b[cx+1][cy+1];

                    // Check if heap property is satisfied
                    if (cur < left && cur < right)
                    {
                        break;
                    }

                    // Choose the smaller child to swap with
                    int swap_x, swap_y;
                    if (left < right)
                    {
                        swap_x = cx + 1;
                        swap_y = cy;
                    }
                    else
                    {
                        swap_x = cx + 1;
                        swap_y = cy + 1;
                    }

                    perform_swap(cx, cy, swap_x, swap_y);
                    total_swaps++;
                    changed = true;

                    if (total_swaps >= MAX_SWAPS)
                    {
                        break;
                    }

                    // Move down to the child node
                    cx = swap_x;
                    cy = swap_y;
                }

                if (total_swaps >= MAX_SWAPS)
                {
                    break;
                }
            }

            if (total_swaps >= MAX_SWAPS)
            {
                break;
            }
        }
    }

    // Output the result
    cout << swaps.size() << endl;
    for (const Swap& s : swaps)
    {
        cout << s.x1 << " " << s.y1 << " " << s.x2 << " " << s.y2 << endl;
    }

    return 0;
}

