#include <bpf/bpf.h>

// Structure representing a cgroup
struct cgroup {
    int id;
};

// Arguments passed to the tracepoint
struct trace_cgroup_args {
    unsigned long cgrp;
    unsigned long path;
};

// Tracepoint handler for cgroup_mkdir
SEC("raw_tracepoint/cgroup_mkdir")
int trace_cgroup_mkdir(struct trace_cgroup_args* ctx)
{
    // Cast the cgroup pointer from context
    struct cgroup* cgrp = (struct cgroup*)ctx->cgrp;

    // Check if cgrp is valid
    if (!cgrp) {
        return 0;
    }

    // Read the cgroup ID using BPF core functionality
    int id = BPF_CORE_READ(cgrp, id);

    // Print debug information
    BPF_PRINTK("cgroup_mkdir, id: %d, path: %s\n", id, (const char*)ctx->path);

    return 0;
}

