#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

// Main function to solve the problem
int main()
{
    int R, H;
    cin >> R >> H; // R=75, H=1 in the official test, but we read anyway.

    // Moduli for the tests. Their sum is 30.
    vector<int> moduli = {13, 7, 5, 3, 2};

    // Send all robots at once.
    for (int m : moduli)
    {
        for (int r = 0; r < m; ++r)
        {
            // Collect all positions p such that p % m == r.
            vector<int> positions;
            for (int p = 1; p <= 1000; ++p)
            {
                if (p % m == r)
                {
                    positions.push_back(p);
                }
            }

            // Output the query for this robot.
            cout << "? " << positions.size();
            for (int pos : positions)
            {
                cout << " " << pos;
            }
            cout << endl;
            cout.flush();
        }
    }

    // Wait for the results.
    cout << "@" << endl;
    cout.flush();

    int L;
    cin >> L;
    vector<int> responses(L);
    for (int i = 0; i < L; ++i)
    {
        cin >> responses[i];
    }

    // Decode: split responses according to the moduli.
    vector<vector<int>> positive_sets(moduli.size()); // residues with answer 1 for each modulus
    int idx = 0;
    for (int i = 0; i < moduli.size(); ++i)
    {
        int m = moduli[i];
        for (int r = 0; r < m; ++r)
        {
            if (responses[idx + r] == 1)
            {
                positive_sets[i].push_back(r);
            }
        }
        idx += m;
    }

    // Precompute residues for all numbers 1..1000 for each modulus.
    vector<vector<int>> num_res(1001, vector<int>(moduli.size()));
    for (int p = 1; p <= 1000; ++p)
    {
        for (int i = 0; i < moduli.size(); ++i)
        {
            num_res[p][i] = p % moduli[i];
        }
    }

    // Brute-force search over all unordered pairs (i,j), i <= j.
    int a = -1, b = -1;
    for (int i = 1; i <= 1000; ++i)
    {
        for (int j = i; j <= 1000; ++j)
        {
            bool ok = true;
            for (int mi = 0; mi < moduli.size(); ++mi)
            {
                int m = moduli[mi];
                int ri = num_res[i][mi];
                int rj = num_res[j][mi];

                // Check that for every residue r, (ri==r or rj==r) equals whether r is in positive_sets[mi].
                for (int r = 0; r < m; ++r)
                {
                    bool covered = (ri == r) || (rj == r);
                    bool expected = false;
                    for (int rr : positive_sets[mi])
                    {
                        if (rr == r)
                        {
                            expected = true;
                            break;
                        }
                    }
                    if (covered != expected)
                    {
                        ok = false;
                        break;
                    }
                }
                if (!ok)
                {
                    break;
                }
            }
            if (ok)
            {
                a = i;
                b = j;
                break;
            }
        }
        if (a != -1)
        {
            break;
        }
    }

    // Output the answer.
    cout << "! " << a << " " << b << endl;
    cout.flush();

    return 0;
}

#include "llvm/Transforms/IPO/EmbedBitcodePass.h"
#include "llvm/Bitcode/BitcodeWriter.h"
#include "llvm/Bitcode/BitcodeWriterPass.h"
#include "llvm/IR/PassManager.h"
#include "llvm/Pass.h"
#include "llvm/Support/ErrorHandling.h"
#include "llvm/Support/MemoryBufferRef.h"
#include "llvm/Support/raw_ostream.h"
#include "llvm/TargetParser/Triple.h"
#include "llvm/Transforms/IPO/ThinLTOBitcodeWriter.h"
#include "llvm/Transforms/Utils/ModuleUtils.h"
#include <memory>
#include <string>

using namespace llvm;

// Embeds bitcode into the module
PreservedAnalyses EmbedBitcodePass::run(Module &M, ModuleAnalysisManager &AM)
{
    // Check if bitcode is already embedded
    if (M.getGlobalVariable("llvm.embedded.module", /*AllowInternal=*/true))
        report_fatal_error("Can only embed the module once",
                           /*gen_crash_diag=*/false);

    Triple T(M.getTargetTriple());

    // Verify object format
    if (T.getObjectFormat() != Triple::ELF)
        report_fatal_error(
            "EmbedBitcode pass currently only supports ELF object format",
            /*gen_crash_diag=*/false);

    std::string Data;
    raw_string_ostream OS(Data);

    // Write bitcode based on mode
    if (IsThinLTO)
        ThinLTOBitcodeWriterPass(OS, /*ThinLinkOS=*/nullptr).run(M, AM);
    else
        BitcodeWriterPass(OS, /*ShouldPreserveUseListOrder=*/false, EmitLTOSummary)
            .run(M, AM);

    // Embed the buffer into the module
    embedBufferInModule(M, MemoryBufferRef(Data, "ModuleData"), ".llvm.lto");

    return PreservedAnalyses::all();
}

