    FFBEngine engine;

    // 1. NaN/Inf input
    ASSERT_NEAR(engine.ApplySafetySlew(std::numeric_limits<double>::quiet_NaN(), 0.0025, false), 0.0, 0.001);
    ASSERT_NEAR(engine.ApplySafetySlew(std::numeric_limits<double>::infinity(), 0.0025, false), 0.0, 0.001);

