    dt->shared->u.atomic.u.f.mpos = 0; \
    dt->shared->u.atomic.u.f.msize = 52; \
    dt->shared->u.atomic.u.f.norm = H5T_NORM_IMPLIED; \
    dt->shared->u.atomic.u.f.pad = H5T_PAD_ZERO; \
}

#define H5T_INIT_TYPE_DOUBLELE_CORE { \
