// Encrypts characters using the provided encryption key
void encrypt_chars(int len, char enc_key)
{
    char ch;

    for (int idx = 0; idx < len; ++idx)
    {
        ch = OChars[idx];
        __asm
        {
            push eax
            push ecx

            movzx ecx, ch
            push ecx
            lea eax, enc_key
            push eax
            call encrypt4
            add esp, 8
            mov ch, al

            pop ecx
            pop eax
        }
        EChars[idx] = ch;
    }
    return;
}

#include <cstdint>
#include <cstddef>

typedef struct __attribute__((aligned(16))) {
    uint64_t lower;
    uint64_t upper;
} uint128_value;

template<>
inline bool compare_and_swap(volatile uint128_value *destination, uint128_value expected, uint128_value replacement) {
    uint64_t exp_low = expected.lower;
    uint64_t exp_high = expected.upper;
    uint64_t rep_low = replacement.lower;
    uint64_t rep_high = replacement.upper;
    unsigned char success_flag = 0;

    __asm__ __volatile__ (
        "lock cmpxchg16b %2\n\t"
        "setz %0\n\t"
        : "=q" (success_flag), "+m" (*destination)
        : "a" (exp_low), "d" (exp_high), "b" (rep_low), "c" (rep_high)
        : "cc", "memory"
    );

    return success_flag;
}

