#include <streambuf>
#include <iostream>
#include <cliext/streambuf>

ref class ManagedBufferWrapper : public std::streambuf
{
public:
    ManagedBufferWrapper(System::IO::Stream^ output)
    {
        m_outputStream = output;
        setp(m_internalBuffer, m_internalBuffer + sizeof(m_internalBuffer) - 1);
    }

    ~ManagedBufferWrapper()
    {
        flush();
    }

protected:
    int_type overflow(int_type character) override
    {
        if (character != traits_type::eof())
        {
            m_internalBuffer[pptr() - pbase()] = static_cast<char>(character);
            if (flush() == -1)
            {
                return traits_type::eof();
            }
        }
        return character;
    }

    int flush() override
    {
        if (pptr() > pbase())
        {
            pin_ptr<unsigned char> pinnedPtr = &m_internalBuffer[0];
            array<unsigned char>^ managedBuffer = gcnew array<unsigned char>(pptr() - pbase());
            System::Runtime::InteropServices::Marshal::Copy(IntPtr(pinnedPtr), managedBuffer, 0, managedBuffer->Length);
            m_outputStream->Write(managedBuffer, 0, managedBuffer->Length);
            pbump(-static_cast<int>(managedBuffer->Length));
        }
        return 0;
    }

private:
    System::IO::Stream^ m_outputStream;
    unsigned char m_internalBuffer[2048];
};

#include <iostream>
#include <vector>

// Perform bubble sort on the input vector
void bubbleSort(std::vector<int> &data) {
  bool changed;
  int length = data.size();
  for (int index = 0; index < length - 1; index++) {
    changed = false;
    for (int position = 0; position < length - index - 1; position++) {
      if (data[position] > data[position + 1]) {
        std::swap(data[position], data[position + 1]);
        changed = true;
      }
    }
    if (!changed) break;
  }
}

