#include <stdio.h>
#include <stdlib.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include "/content/common.h"

#define ARRAY_DIM 1024
#define BLOCK_SIZE 32

// Bitonic sort implementation
__device__ void bitonicSort(int* array, int step, gap, direction) {
  int idx, tempVal;

  if ((step & gap) == 0) {
    idx = threadIdx.x / step;
    if ((idx & gap) == 0) {
      if (direction == 1) {
        if (array[idx * step + gap] > array[idx * step + gap + step / 2]) {
          tempVal = array[idx * step + gap];
          array[idx * step + gap] = array[idx * step + gap + step / 2];
          array[idx * step + gap + step / 2] = tempVal;
        }
      } else {
        if (array[idx * step + gap] < array[idx * step + gap + step / 2]) {
          tempVal = array[idx * step + gap];
          array[idx * step + gap] = array[idx * step + gap + step / 2];
          array[idx * step + gap + step / 2] = tempVal;
        }
      }
    }
  }
}

__global__ void sortPass(int* array, int cols, int rows) {
  int threadRow = blockIdx.x * blockDim.x + threadIdx.x;
  if (threadRow < rows) {
    // Sort the subsequence of integers using bitonic sort
    for (int step = 2; step <= cols; step *= 2) {
      for (int gap = step / 2; gap > 0; gap /= 2) {
        bitonicSort(array + threadRow * cols, step, gap, 1);
      }
    }
  }
}

__global__ void mergePass(int* array, int cols, int rows, int passNum) {
  int threadRow = blockIdx.x * blockDim.x + threadIdx.x;
  if (threadRow < rows) {
    // Calculate the indices for merging the previously sorted halves
    int blockSize = cols / (1 << passNum);
    int blockId = threadRow / blockSize;
    int indexInBlock = threadRow % blockSize;

    // Calculate the starting indices for the two halves to be merged
    int leftStart = blockId * blockSize;
    int rightStart = leftStart + blockSize / 2;

    // Merge the two sorted halves into a single sorted subsequence
    for (int step = blockSize / 2; step >= 1; step /= 2) {
      int gap = indexInBlock % step;
      int leftIdx = leftStart + indexInBlock - gap;
      int rightIdx = rightStart + indexInBlock - gap;

      if (leftIdx < cols && rightIdx < cols) {
        if (array[leftIdx] > array[rightIdx]) {
          int tempVal = array[leftIdx];
          array[leftIdx] = array[rightIdx];
          array[rightIdx] = tempVal;
        }
      } 
      __syncthreads();
    }
  }
}

bool checkSorted(int* array, int size) {
  for (int i = 0; i < size - 1; i++) {
    if (array[i] > array[i + 1])
      return false;
  }
  return true;
}

