  int* deviceArray;
  CHECK(cudaMalloc((void**)&deviceArray, totalElements * sizeof(int)));

  // Copy data to GPU
  CHECK(cudaMemcpy(deviceArray, hostArray, totalElements * sizeof(int), cudaMemcpyHostToDevice));

  /* run the computational kernel */
  dim3 block(BLOCK_SIZE, 1, 1);

  // Launch the sorting kernels in iterations
  int width = ARRAY_DIM;
  int height = ARRAY_DIM;
  for (int iteration = 1; iteration <= 10; iteration++) {
    unsigned int gridDimX = (height + BLOCK_SIZE - 1) / BLOCK_SIZE;
    dim3 grid(gridDimX, 1, 1);

    sortPass<<<grid, block>>>(deviceArray, width, height);
    CHECK (cudaDeviceSynchronize ());                            // wait for kernel to finish
    CHECK (cudaGetLastError ());                                 // check for kernel errors

    // Merge the previously sorted halves
    mergePass<<<grid, block>>>(deviceArray, width, height, iteration);
    CHECK (cudaDeviceSynchronize ());                            // wait for kernel to finish
    CHECK (cudaGetLastError ());                                 // check for kernel errors

    // Update the width and height for the next iteration
    width *= 2;
    height /= 2;
  }

  // Copy sorted data back to CPU
  cudaMemcpy(hostArray, deviceArray, totalElements * sizeof(int), cudaMemcpyDeviceToHost);

  // Check if the array is sorted
  bool isOrdered = checkSorted(hostArray, totalElements);

  // Print the sorted data
  for (int i = 0; i < totalElements; i++) {
    printf("%d ", hostArray[i]);
    if( i == 10 ) break;
  }
  printf("\n");

  // Print the result of the ordering check
  if (isOrdered) {
    printf("The array is ordered.\n");
  } else {
    printf("The array is not ordered.\n");
  }

  // Free GPU memory
  cudaFree(deviceArray);

  // Free CPU memory
  free(hostArray);

