#include "MyDomTraversal.h"
#include <mshtml.h>

void ProcessDocument(IHTMLDocument2* document) {
    if (document == nullptr) return;

    IHTMLElementCollection* bodyElements = nullptr;
    document->get_body(&bodyElements);

    if (bodyElements == nullptr) return;

    long count = 0;
    bodyElements->get_length(&count);

    for (long index = 0; index < count; ++index) {
        IHTMLDOMNode* node = nullptr;
        bodyElements->item(index, &node);

        if (node == nullptr) continue;

        BSTR content = nullptr;
        node->get_nodeValue(&content);

        if (content != nullptr) {
            // Process the text content
            wprintf(L"Text Node: %s\n", content);
            SysFreeString(content);
        }

        IHTMLDOMNode* childNode = nullptr;
        node->get_firstChild(&childNode);

        while (childNode != nullptr) {
            ProcessNodeRecursively(childNode);
            IHTMLDOMNode* nextSibling = nullptr;
            childNode->get_nextSibling(&nextSibling);
            childNode->Release();
            childNode = nextSibling;
        }

        node->Release();
    }

    bodyElements->Release();
}

void ProcessNodeRecursively(IHTMLDOMNode* node) {
    if (node == nullptr) return;

    BSTR content = nullptr;
    node->get_nodeValue(&content);

    if (content != nullptr) {
        // Process the text content
        wprintf(L"Text Node: %s\n", content);
        SysFreeString(content);
    }

    IHTMLDOMNode* childNode = nullptr;
    node->get_firstChild(&childNode);

    while (childNode != nullptr) {
        ProcessNodeRecursively(childNode);
        IHTMLDOMNode* nextSibling = nullptr;
        childNode->get_nextSibling(&nextSibling);
        childNode->Release();
        childNode = nextSibling;
    }
}

