// Transpose a 4x4 matrix stored in ZMM registers using AVX-512 instructions
void transpose_4x4_avx512(__m512i& reg_a, __m512i& reg_b, __m512i& reg_c, __m512i& reg_d) {
    // First stage: shuffle to interleave 32-bit elements from pairs of registers
    __m512i temp_a = _mm512_shuffle_i32x4(reg_a, reg_b, 0x44);
    __m512i temp_b = _mm512_shuffle_i32x4(reg_a, reg_b, 0xEE);
    __m512i temp_c = _mm512_shuffle_i32x4(reg_c, reg_d, 0x44);
    __m512i temp_d = _mm512_shuffle_i32x4(reg_c, reg_d, 0xEE);

    // Second stage: permute with index vector to complete the transpose operation
    const __m512i idx = _mm512_setr_epi32(0, 4, 1, 5, 2, 6, 3, 7, 8, 12, 9, 13, 10, 14, 11, 15);

    reg_a = _mm512_permutex2var_epi32(temp_a, idx, temp_c);
    reg_b = _mm512_permutex2var_epi32(temp_a, idx, temp_d);
    reg_c = _mm512_permutex2var_epi32(temp_b, idx, temp_c);
    reg_d = _mm512_permutex2var_epi32(temp_b, idx, temp_d);
}

