struct InsertInlineAsmTransform : public FunctionPass {
  static char ID;
  InsertInlineAsmTransform() : FunctionPass(ID) {}

  bool runOnFunction(Function &func) override {
    IRBuilder<> builder(&func.getEntryBlock(), func.getEntryBlock().begin());

    // Inline assembly template for byte swapping operation
    const char *asmCode = "bswap $0";
    const char *regConstraints = "=r,r";
    Type *outputType = Type::getInt32Ty(func.getContext());
    std::vector<Type *> paramTypes = {Type::getInt32Ty(func.getContext())};
    FunctionType *functionSignature = FunctionType::get(outputType, paramTypes, false);

    // Construct the inline assembly object
    InlineAsm *inlineAsmObj = InlineAsm::get(functionSignature, asmCode, regConstraints, false, false);

    // Prepare the input argument (constant value)
    Value *inputValue = ConstantInt::get(Type::getInt32Ty(func.getContext()), 5678);
    CallInst *callSite = builder.CreateCall(inlineAsmObj, inputValue, "byte_swapped_val");

    return true;
  }
};

