__global__ void compute(int count, float *input, float *output) {
    int tid = blockIdx.x * blockDim.x + threadIdx.x;

    // Check bounds to prevent out-of-bounds access
    if (tid < count - 1) {
        float val = input[tid];

        // Process remaining elements in the segment
        for (int j = tid + 1; j < count; j++) {
            float diff = input[j] - val;
            float squared = diff * diff;

            if (squared < 25) {
                // Use atomic operation to safely update shared memory
                atomicExch(&output[j], squared);
            }
        }
    }
}

