void blendImages(const uint8_t* inputFrame, const uint8_t* overlayData, uint8_t* outputFrame, int imgWidth, int imgHeight) {
    int totalPixels = imgWidth * imgHeight;
    int alignedPixels = totalPixels - (totalPixels % 16); // Pixels processed in 16-pixel batches

    __m128i nullVec = _mm_set1_epi8(0); // Vector filled with zeros

    #pragma omp parallel for
    for (int idx = 0; idx < alignedPixels; idx += 16) {
        __m128i overlayA = _mm_loadu_si128((__m128i const*)(overlayData + idx * 4));
        __m128i overlayB = _mm_loadu_si128((__m128i const*)(overlayData + idx * 4 + 16));
        __m128i overlayC = _mm_loadu_si128((__m128i const*)(overlayData + idx * 4 + 32));
        __m128i overlayD = _mm_loadu_si128((__m128i const*)(overlayData + idx * 4 + 48));

        __m128i alphaA = _mm_shuffle_epi32(overlayA, _MM_SHUFFLE(3, 3, 3, 3));
        __m128i alphaB = _mm_shuffle_epi32(overlayB, _MM_SHUFFLE(3, 3, 3, 3));
        __m128i alphaC = _mm_shuffle_epi32(overlayC, _MM_SHUFFLE(3, 3, 3, 3));
        __m128i alphaD = _mm_shuffle_epi32(overlayD, _MM_SHUFFLE(3, 3, 3, 3));

        __m128i checkA = _mm_cmpeq_epi8(alphaA, nullVec);
        __m128i checkB = _mm_cmpeq_epi8(alphaB, nullVec);
        __m128i checkC = _mm_cmpeq_epi8(alphaC, nullVec);
        __m128i checkD = _mm_cmpeq_epi8(alphaD, nullVec);

        __m128i frameA = _mm_loadu_si128((__m128i const*)(inputFrame + idx * 3));
        __m128i frameB = _mm_loadu_si128((__m128i const*)(inputFrame + idx * 3 + 16));
        __m128i frameC = _mm_loadu_si128((__m128i const*)(inputFrame + idx * 3 + 32));
        __m128i frameD = _mm_loadu_si128((__m128i const*)(inputFrame + idx * 3 + 48));

        __m128i resultA = _mm_or_si128(_mm_andnot_si128(checkA, overlayA), _mm_and_si128(checkA, frameA));
        __m128i resultB = _mm_or_si128(_mm_andnot_si128(checkB, overlayB), _mm_and_si128(checkB, frameB));
        __m128i resultC = _mm_or_si128(_mm_andnot_si128(checkC, overlayC), _mm_and_si128(checkC, frameC));
        __m128i resultD = _mm_or_si128(_mm_andnot_si128(checkD, overlayD), _mm_and_si128(checkD, frameD));

        _mm_storeu_si128((__m128i*)(outputFrame + idx * 3), resultA);
        _mm_storeu_si128((__m128i*)(outputFrame + idx * 3 + 16), resultB);
        _mm_storeu_si128((__m128i*)(outputFrame + idx * 3 + 32), resultC);
        _mm_storeu_si128((__m128i*)(outputFrame + idx * 3 + 48), resultD);
    }

    // Process leftover pixels individually
    for (int idx = alignedPixels; idx < totalPixels; ++idx) {
        if (overlayData[idx * 4 + 3] == 0) {
            outputFrame[idx * 3] = inputFrame[idx * 3];       // R
            outputFrame[idx * 3 + 1] = inputFrame[idx * 3 + 1]; // G
            outputFrame[idx * 3 + 2] = inputFrame[idx * 3 + 2]; // B
        } else {
            outputFrame[idx * 3] = overlayData[idx * 4];      // R
            outputFrame[idx * 3 + 1] = overlayData[idx * 4 + 1]; // G
            outputFrame[idx * 3 + 2] = overlayData[idx * 4 + 2]; // B
        }
    }
}

uint64_t getCurrentTime() {
    struct timeval currentTime;
    gettimeofday(&currentTime, NULL);
    return (uint64_t)currentTime.tv_sec * 1000000 + (uint64_t)currentTime.tv_usec;
}

int main(int argc, char **argv) {
    const int SCREEN_WIDTH = 1920;
    const int SCREEN_HEIGHT = 1080;
    int bufferSize = SCREEN_WIDTH * SCREEN_HEIGHT * 3;
    uint8_t *overlayBuffer = new uint8_t[SCREEN_WIDTH * SCREEN_HEIGHT * 4];
    uint8_t *sourceBuffer = new uint8_t[bufferSize];
    uint8_t *resultBuffer = new uint8_t[bufferSize];

    uint64_t startTime = getCurrentTime();

    for (int loop = 0; loop < 1000; ++loop) {
        blendImages(sourceBuffer, overlayBuffer, resultBuffer, SCREEN_WIDTH, SCREEN_HEIGHT);
    }

    printf("elapsed: %lu\n", (getCurrentTime() - startTime) / 1000);

    delete[] overlayBuffer;
    delete[] sourceBuffer;
    delete[] resultBuffer;

    return 0;
}

