    std::vector<int> twoSum(std::vector<int>& values, int goal) {
        std::unordered_map<int, int> valueIndexMap;

        for (int index = 0; index < values.size(); ++index) {
            int needed = goal - values[index];
            if (valueIndexMap.find(needed) != valueIndexMap.end()) {
                return {valueIndexMap[needed], index};
            }
            valueIndexMap[values[index]] = index;
        }

        return {}; // Return an empty vector if no pair is found
    }
};

int main() {
    Solution solver;
    std::vector<int> data = {2, 7, 11, 15};
    int targetValue = 9;
    std::vector<int> output = solver.twoSum(data, targetValue);

    std::cout << "Positions: " << output[0] << ", " << output[1] << std::endl;

    return 0;
}

#include <openssl/aes.h>
