std::string base64_encode_data(const unsigned char* data, size_t size) {
    BIO *bio_enc, *b64_encoder;
    BUF_MEM *bufferPtr;

    b64_encoder = BIO_new(BIO_f_base64());
    bio_enc = BIO_new(BIO_s_mem());
    bio_enc = BIO_push(b64_encoder, bio_enc);

    BIO_set_flags(bio_enc, BIO_FLAGS_BASE64_NO_NL); // Ignore newlines - write everything in one line
    BIO_write(bio_enc, data, size);
    BIO_flush(bio_enc);
    BIO_get_mem_ptr(bio_enc, &bufferPtr);
    BIO_set_close(bio_enc, BIO_NOCLOSE);
    BIO_free_all(bio_enc);

    std::string result(bufferPtr->data, bufferPtr->length);
    BUF_MEM_free(bufferPtr);

    return result;
}

std::string perform_aes_encryption(const std::string& plain_text, const std::string& encryption_key, const std::string& initialization_vector) {
    size_t cipher_len = plain_text.length() + AES_BLOCK_SIZE;
    unsigned char *cipher_text = new unsigned char[cipher_len];
    EVP_CIPHER_CTX *context = EVP_CIPHER_CTX_new();

    EVP_EncryptInit_ex(context, EVP_aes_256_cbc(), nullptr, 
                       (const unsigned char*)encryption_key.c_str(), 
                       (const unsigned char*)initialization_vector.c_str());

    int out_len;
    EVP_EncryptUpdate(context, cipher_text, &out_len, 
                      (const unsigned char*)plain_text.c_str(), 
                      plain_text.length());

    int final_len;
    EVP_EncryptFinal_ex(context, cipher_text + out_len, &final_len);
    cipher_len = out_len + final_len;

    EVP_CIPHER_CTX_free(context);

    std::string encoded_cipher = base64_encode_data(cipher_text, cipher_len);
    delete[] cipher_text;

    return encoded_cipher;
}

