#include <atomic>

using u64 = unsigned long long;

struct Bucket {
    u64 mLeaves[16] = {};
};

struct BucketMap {
    u64 acquire() noexcept {
        while (true) {
            u64 currentMap = mData.load(std::memory_order_relaxed);

            u64 slotIndex = (currentMap & 1) ? 1 : 0;
            auto bitMask = u64(1) << slotIndex;

            auto oldValue =
                mData.fetch_or(bitMask, std::memory_order_relaxed);
            if ((oldValue & bitMask) == 0) {
                return slotIndex;
            }
        }
    }

    __attribute__((noinline)) Bucket acquireBucket() noexcept {
        acquire();
        return Bucket();
    }

    std::atomic<u64> mData{ 1 };
};

int main() {
    BucketMap bucketMap;
    bucketMap.acquireBucket();
    return 0;
}

