struct BufferInfo
{
    unsigned char* buffer;
    int size;
};

extern "C" DLLAPI int API_LoadFile(const wchar_t* filepath, BufferInfo** result)
{
    // Example implementation: Allocate memory and read file
    FILE* handle = nullptr;
    errno_t status = _wfopen_s(&handle, filepath, L"rb");
    if (status != 0 || handle == nullptr)
    {
        return -1; // Error opening file
    }

    fseek(handle, 0, SEEK_END);
    long length = ftell(handle);
    fseek(handle, 0, SEEK_SET);

    *result = new BufferInfo();
    (*result)->buffer = new unsigned char[length];
    (*result)->size = length;

    size_t amountRead = fread((*result)->buffer, 1, length, handle);
    fclose(handle);

    if (amountRead != static_cast<size_t>(length))
    {
        delete[] (*result)->buffer;
        delete *result;
        return -2; // Error reading file
    }

    return 0; // Success
}

extern "C" DLLAPI void API_ReleaseBuffer(BufferInfo* info)
{
    if (info != nullptr)
    {
        delete[] info->buffer;
        delete info;
    }
}

