class JammingWeapon : Weapon
{
    float fJamProbability;
    int iCooldownCounter;
    bool bIsJammed;

    Default
    {
        fJamProbability = 0.08; // 8% chance of jamming
        iCooldownCounter = 65; // Jamming period in tics
        bIsJammed = false;
    }

    States
    {
    Ready:
        WEAP B 1 A_WeaponReady;
        Loop;

    Deselect:
        TNT1 A 0 A_CheckJamStatus; // Check for jam status
        WEAP C 1 A_Lower;
        Loop;

    Select:
        TNT1 A 0 A_CheckJamStatus; // Check for jam status
        WEAP C 1 A_Raise;
        Loop;

    Fire:
        WEAP A 0 Bright A_PlaySound("weapons/pistol", CHAN_WEAPON);
        TNT1 A 0 A_CheckJamStatus; // Check for jam status

        WEAP A 0 A_GunFlash;
        WEAP A 1 Bright;
        WEAP A 0 A_FireBullets(1, 1, 1, 5, "BulletPuff");

        WEAP A 0 A_ReFire;
        Goto Ready;

    Flash:
        TNT1 A 0 A_CheckJamStatus; // Check for jam status
        Goto LightDone;

    JammedState:
        WEAP A 3 A_PlaySound("weapons/jam", CHAN_WEAPON);
        WEAP A 3;
        WEAP A 3;
        WEAP A 0 A_CooldownUpdate;
        Goto Ready;

    LightDone:
        TNT1 A 0 A_Light0;
        Stop;
    }

    override void PostBeginPlay()
    {
        Super.PostBeginPlay();
    }

    private state void A_CheckJamStatus()
    {
        if (bIsJammed)
            Goto JammedState;

        if (random() < fJamProbability)
        {
            bIsJammed = true;
            Goto JammedState;
        }
    }

    private state void A_CooldownUpdate()
    {
        iCooldownCounter--;
        if (iCooldownCounter <= 0)
        {
            bIsJammed = false;
            iCooldownCounter = 65;
        }
    }
}

