using namespace Microsoft::WRL;
using namespace D2D1;

class RenderControl : public HwndHost
{
public:
    RenderControl() : m_windowHandle(NULL), m_d2dFactory(NULL), m_renderTarget(NULL) {}

    ~RenderControl()
    {
        if (m_renderTarget) m_renderTarget->Release();
        if (m_d2dFactory) m_d2dFactory->Release();
    }

    // Create the Win32 window
    HWND CreateNativeWindow(HWND parent, HINSTANCE hInstance)
    {
        WNDCLASS wc = {0};
        wc.lpfnWndProc = DefWindowProc;
        wc.hInstance = hInstance;
        wc.lpszClassName = L"RenderingSurfaceClass";
        RegisterClass(&wc);

        return CreateWindow(L"RenderingSurfaceClass", L"RenderingSurface", WS_CHILD | WS_VISIBLE, 0, 0, 0, 0, parent, NULL, hInstance, NULL);
    }

    // Build the window
    HRESULT BuildWindowCore(HWND hwndParent)
    {
        m_windowHandle = CreateNativeWindow(hwndParent, GetModuleHandle(NULL));

        // Initialize Direct2D
        D2D1_FACTORY_OPTIONS settings = {};
#if defined(_DEBUG)
        settings.debugLevel = D2D1_DEBUG_LEVEL_INFORMATION;
#endif
        D2D1CreateFactory(D2D1_FACTORY_TYPE_SINGLE_THREADED, settings, &m_d2dFactory);

        return S_OK;
    }

    // Destroy the window
    void DestroyWindowCore()
    {
        if (m_windowHandle)
        {
            DestroyWindow(m_windowHandle);
            m_windowHandle = NULL;
        }
    }

    // Get the handle of the hosted window
    HWND GetHandle() const
    {
        return m_windowHandle;
    }

    // Create the render target
    void CreateRenderTarget()
    {
        if (m_windowHandle && m_d2dFactory)
        {
            RECT area;
            GetClientRect(m_windowHandle, &area);

            D2D1_SIZE_U dimensions = D2D1::SizeU(area.right - area.left, area.bottom - area.top);

            m_d2dFactory->CreateHwndRenderTarget(
                D2D1::RenderTargetProperties(),
                D2D1::HwndRenderTargetProperties(m_windowHandle, dimensions),
                &m_renderTarget);
        }
    }

    // Render
    void DrawContent()
    {
        if (m_renderTarget)
        {
            m_renderTarget->BeginDraw();

            m_renderTarget->Clear(D2D1::ColorF(D2D1::ColorF::SkyBlue));

            D2D1_RECT_F box = D2D1::RectF(0, 0, 100, 100);
            ComPtr<ID2D1SolidColorBrush> brush;
            m_renderTarget->CreateSolidColorBrush(D2D1::ColorF(D2D1::ColorF::Red), &brush);
            m_renderTarget->FillRectangle(box, brush.Get());

            m_renderTarget->EndDraw();
        }
    }

    // Handle window messages
    LRESULT WindowProc(HWND hwnd, UINT message, WPARAM wParam, LPARAM lParam)
    {
        switch (message)
        {
        case WM_PAINT:
            DrawContent();
            ValidateRect(m_windowHandle, NULL);
            return 0;
        case WM_SIZE:
            if (m_renderTarget)
            {
                RECT area;
                GetClientRect(m_windowHandle, &area);
                D2D1_SIZE_U dimensions = D2D1::SizeU(area.right - area.left, area.bottom - area.top);
                m_renderTarget->Resize(dimensions);
            }
            return 0;
        case WM_DESTROY:
            PostQuitMessage(0);
            return 0;
        }
        return DefWindowProc(hwnd, message, wParam, lParam);
    }

private:
    HWND m_windowHandle;
    ComPtr<ID2D1Factory> m_d2dFactory;
    ComPtr<ID2D1HwndRenderTarget> m_renderTarget;
};

