// Function to create and populate a Java HashMap from native code
jobject createRosterMap(JNIEnv* env) {
    jclass hashmap_class = env->FindClass("java/util/HashMap");
    jclass boolean_class = env->FindClass("java/lang/Boolean");
    jmethodID hashmap_constructor = env->GetMethodID(hashmap_class, "<init>", "()V");
    jmethodID boolean_constructor = env->GetMethodID(boolean_class, "<init>", "(Z)V");  // Boolean constructor with boolean parameter
    jmethodID put_method = env->GetMethodID(hashmap_class, "put", "(Ljava/lang/Object;Ljava/lang/Object;)Ljava/lang/Object;");
    jobject result_map = env->NewObject(hashmap_class, hashmap_constructor);

    std::map<std::string, RosterItem>* roster_data = GetRosterMap();
    if (!roster_data || roster_data->empty()) {
        return result_map;
    }

    for (auto it = roster_data->begin(); it != roster_data->end(); ++it) {
        jstring entry_key = env->NewStringUTF(it->second.name.c_str());
        jboolean friend_status = it->second.isfriend;
        jobject boolean_wrapper = env->NewObject(boolean_class, boolean_constructor, friend_status);
        env->CallObjectMethod(result_map, put_method, entry_key, boolean_wrapper);
    }

    return result_map;
}

