int getMaxValue(const std::vector<int>& inputArray) {
    if (inputArray.empty()) {
        throw std::invalid_argument("Input array is empty");
    }
    int currentMax = inputArray[0];
    for (int value : inputArray) {
        if (value > currentMax) {
