// Constants for CRT simulation
float2 screenResolution = float2(1280, 720); // Display resolution
float curvatureFactor = 1.5; // Controls the strength of screen curvature

// Function to apply barrel distortion for curved screen effect
float2 applyCurvature(float2 uvCoords, float curvature)
{
    float2 centerPoint = float2(0.5, 0.5);
    uvCoords = (uvCoords - centerPoint) * (1.0 + curvature * (distance(uvCoords, centerPoint)));
    uvCoords += centerPoint;
    return uvCoords;
}

float4 main(float2 TexCoord : TEXCOORD0) : COLOR
{
    // Apply barrel distortion to simulate screen curvature
    float2 uv = applyCurvature(TexCoord, curvatureFactor);

    // Validate texture coordinates are within bounds [0, 1]
    if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0)
        return float4(0.0, 0.0, 0.0, 1.0);

    // Sample the input texture at the distorted coordinates
    float4 pixelColor = tex2D(inputTexture, uv);

    // Generate scanline effect
    float scanDarkness = 0.1;
    float scanBarWidth = 2.0;
    float scanSpacing = 4.0;
    float rowNumber = floor(TexCoord.y * screenResolution.y);
    float scanlineFactor = (fmod(rowNumber, scanSpacing) < scanBarWidth) ? scanDarkness : 1.0;

    // Apply scanline modulation to RGB channels
    pixelColor.rgb *= scanlineFactor;

    return pixelColor;
}

