// Structure representing a vertex with position and color
struct Vertex {
    glm::vec3 position;
    glm::vec3 color;
};

class Terrain {
private:
    std::vector<Vertex> vertices;
    std::vector<unsigned int> indices;
    float** heightMap;  // Assuming this exists in the class
    int worldSize;      // Assuming this exists in the class

public:
    void ConvertHeightMapToMeshData();
};

void Terrain::ConvertHeightMapToMeshData()
{
    // Reset the arrays for new mesh data
    vertices.erase(vertices.begin(), vertices.end());
    indices.erase(indices.begin(), indices.end());

    // Create vertex data from height map
    for (int row = 0; row < worldSize; ++row)
    {
        for (int col = 0; col < worldSize; ++col)
        {
            Vertex point;
            point.position = glm::vec3(static_cast<float>(row), heightMap[row][col], static_cast<float>(col));

            // Determine shading based on elevation - adjust multiplier as needed
            float shadeValue = heightMap[row][col] * 0.25f + 0.75f; // Adjusted normalization
            point.color = glm::vec3(shadeValue, shadeValue, shadeValue);

            vertices.push_back(point);
        }
    }

    // Build index buffer using triangle primitives
    for (int row = 0; row < worldSize - 1; ++row)
    {
        for (int col = 0; col < worldSize - 1; ++col)
        {
            int upperLeft = row * worldSize + col;
            int upperRight = upperLeft + 1;
            int lowerLeft = (row + 1) * worldSize + col;
            int lowerRight = lowerLeft + 1;

            // First triangle of the quad
            indices.push_back(upperLeft);
            indices.push_back(lowerRight);
            indices.push_back(lowerLeft);

            // Second triangle completing the quad
            indices.push_back(upperLeft);
            indices.push_back(upperRight);
            indices.push_back(lowerRight);
        }
    }
}

#include "greenwald_khanna.h"

// Compute quantile values for given percentiles using GK algorithm
std::vector<double> ComputeQuantiles(const std::vector<double>& input_data, const std::vector<double>& percentile_list, double accuracy)
{
    greenwald_khanna<double> gk(accuracy);
    for (double item : input_data)
    {
        gk.insert(item);
    }
    std::vector<double> output;
    for (double p : percentile_list)
    {
