// Generate two random integers between 0 and 9 as a Python tuple
static PyObject* GenerateRandomPair(PyObject* self, PyObject* args)
{
    srand(static_cast<unsigned int>(time(NULL)));
    int first_random = rand() % 10;
    int second_random = rand() % 10;

    PyObject *py_result = Py_BuildValue("ii", first_random, second_random);
