// Generate two random integers between 0 and 9 as a Python list
static PyObject* GenerateRandomList(PyObject* self, PyObject* args)
{
    srand(static_cast<unsigned int>(time(NULL)));
    int first_value = rand() % 10;
    int second_value = rand() % 10;

    PyObject *item1 = PyInt_FromLong(first_value);
    PyObject *item2 = PyInt_FromLong(second_value);

    PyObject *list_result = PyList_New(2);
    PyList_SetItem(list_result, 0, item1);
    PyList_SetItem(list_result, 1, item2);

