// Function to normalize whitespace in a string
std::string normalizeWhitespace(const std::string& text) {
    if (text.empty()) return text;

    std::string output;
    bool previousWasSpace = false; // Flag to track if the last character was a space

    for (size_t index = 0; index < text.length(); ++index) {
        if (std::isspace(text[index])) {
            if (!previousWasSpace && !output.empty()) {
                output += ' '; // Add a single space only if not already in a space sequence
            }
            previousWasSpace = true;
        } else {
            output += text[index];
            previousWasSpace = false;
        }
    }

    // Remove trailing space if present
    if (!output.empty() && output.back() == ' ') {
        output.pop_back();
    }

    return output;
}

