// Function to fill and read a matrix in spiral pattern
std::string transform(std::string input, int rows, int cols, char placeholder = 'X') {
    // Create the grid filled with placeholder character
    std::vector<std::vector<char>> grid(rows, std::vector<char>(cols, placeholder));

    // Movement vectors: right, down, left, up
    int moveX[] = {0, 1, 0, -1};
    int moveY[] = {1, 0, -1, 0};

    int curX = 0, curY = 0; // Current coordinates
    int dir = 0; // Current direction index
    int pos = 0; // Position in input string

    // Fill the grid in spiral order
    while (pos < input.length()) {
        grid[curX][curY] = input[pos++];

        // Compute next position
        int futureX = curX + moveX[dir];
        int futureY = curY + moveY[dir];

        // If next position is invalid or already occupied, turn clockwise
        if (futureX < 0 || futureX >= rows || futureY < 0 || futureY >= cols || grid[futureX][futureY] != placeholder) {
            dir = (dir + 1) % 4;
            futureX = curX + moveX[dir];
            futureY = curY + moveY[dir];
        }

        // Update current position
        curX = futureX;
        curY = futureY;
    }

    // Read the grid in spiral order
    std::string output;
    curX = 0;
    curY = 0;
    dir = 0;
    bool visited[rows][cols] = {{false}}; // Mark visited cells

    while (true) {
        output += grid[curX][curY];
        visited[curX][curY] = true;

        // Calculate next cell in spiral
        int nextX = curX + moveX[dir];
        int nextY = curY + moveY[dir];

        // Check boundaries and visited status
        if (nextX < 0 || nextX >= rows || nextY < 0 || nextY >= cols || visited[nextX][nextY]) {
            dir = (dir + 1) % 4;
            nextX = curX + moveX[dir];
            nextY = curY + moveY[dir];

            // If still invalid, we've completed the spiral
            if (nextX < 0 || nextX >= rows || nextY < 0 || nextY >= cols || visited[nextX][nextY]) {
                break;
            }
        }

        curX = nextX;
        curY = nextY;
    }

    return output;
}

int main() {
    std::string text1 = "HELLOPROGRAMMING";
    int row1 = 5, col1 = 4;
    std::cout << transform(text1, row1, col1) << std::endl; // Expected: "HELLOGRAMMINGPROGRAMLLE"

    std::string text2 = "HELLOPROGRAMMING";
    int row2 = 4, col2 = 4;
    std::cout << transform(text2, row2, col2) << std::endl; // Expected: "HELLOGRAMMINGPRO"

    std::string text3 = "A";
    int row3 = 1, col3 = 1;
    std::cout << transform(text3, row3, col3) << std::endl; // Expected: "A"

    std::string text4 = "HELLO";
    int row4 = 3, col4 = 3;
    std::cout << transform(text4, row4, col4, 'X') << std::endl; // Expected: "HELXLOX"

    return 0;
}

#include <cuda_runtime.h>

__global__
void convert_rgba_to_gray(const uchar4* const inputImage,
                          unsigned char* const outputImage,
                          int height, int width)
{
    int col = blockIdx.x * blockDim.x + threadIdx.x;
    int row = blockIdx.y * blockDim.y + threadIdx.y;

    if (col >= width || row >= height) {
        return;
    }

    int position = row * width + col;
    uchar4 pixel = inputImage[position];
    float weightedSum = 0.299f * pixel.x + 0.587f * pixel.y + 0.114f * pixel.z;
    outputImage[position] = static_cast<unsigned char>(weightedSum);
}

void host_rgba_to_gray(const uchar4 * const host_rgbaImage,
                       uchar4 * const device_rgbaImage,
                       unsigned char* const device_grayImage,
                       size_t rows,
                       size_t cols)
{
    const dim3 threadsPerBlock(16, 16, 1);  // Threads per block
    const dim3 blocksPerGrid((cols + threadsPerBlock.x - 1) / threadsPerBlock.x, 
                             (rows + threadsPerBlock.y - 1) / threadsPerBlock.y, 1);  // Grid dimensions

    convert_rgba_to_gray<<<blocksPerGrid, threadsPerBlock>>>(device_rgbaImage,
                                                             device_grayImage,
                                                             rows,
                                                             cols);

    cudaDeviceSynchronize();
    checkCudaErrors(cudaGetLastError());
}

