// Function to display the Fibonacci sequence up to n terms
void showFibonacciSequence(int count) {
    if (count <= 0) {
        cout << "Please enter a positive integer." << endl;
        return;
    }

    long long term1 = 0, term2 = 1, nextTerm;

    for (int index = 1; index <= count; ++index) {
        if (index == 1) {
            cout << term1 << " ";
            continue;
        }
        if (index == 2) {
            cout << term2 << " ";
            continue;
        }
        nextTerm = term1 + term2;
        term1 = term2;
        term2 = nextTerm;
        cout << nextTerm << " ";
    }
    cout << endl;
}

