// Function to find the k smallest elements in the array
std::vector<int> find_min_k(std::vector<int>& data, int limit) {
    std::multiset<int> collection;
    for (int value : data) {
        collection.insert(value);
        if (collection.size() > limit) {
            collection.erase(std::prev(collection.end()));
        }
    }
    return std::vector<int>(collection.begin(), collection.end());
}

