// Evaluate polynomial with coefficients stored in array
float EvaluatePolynomial(int degree, int coefficients[], float value) 
{   
    int index;
    float result = 0.0f;

    if(degree == 0)
    {
        result = coefficients[0];
    }
    else
    {
        result = coefficients[0];
        for(index = 1; index <= degree; index++)
        {
            result = result + coefficients[index] * value;
            value = value * value;
        }
    }

    return result;  // Return computed polynomial value
}

