std::vector<char> base64_decode(const std::string& input) {
    int length = input.size();
    int pos = 0;
    int index = 0;
    int count = 0;
    unsigned char buffer4[4], buffer3[3];
    std::vector<char> result;

    while (length-- && (input[count] != '=') && std::isalnum(input[count])) {
        unsigned char ch = static_cast<unsigned char>(input[count]);
        int value = (ch >= 'A' && ch <= 'Z') ? (ch - 'A') : 
                    (ch >= 'a' && ch <= 'z') ? (ch - 'a' + 26) : 
                    (ch >= '0' && ch <= '9') ? (ch - '0' + 52) : 
                    (ch == '+') ? 62 : 63;

        buffer4[pos++] = static_cast<unsigned char>(value);

        if (pos == 4) {
            buffer3[0] = (buffer4[0] << 2) | ((buffer4[1] & 0x30) >> 4);
            buffer3[1] = ((buffer4[1] & 0x0F) << 4) | ((buffer4[2] & 0x3C) >> 2);
            buffer3[2] = ((buffer4[2] & 0x03) << 6) | buffer4[3];

            for (pos = 0; pos < 3; pos++)
                result.push_back(static_cast<char>(buffer3[pos]));

            pos = 0;
        }
        count++;
    }

    if (pos > 0) {
        for (index = pos; index < 4; index++)
            buffer4[index] = 0;

        buffer3[0] = (buffer4[0] << 2) | ((buffer4[1] & 0x30) >> 4);
        buffer3[1] = ((buffer4[1] & 0x0F) << 4) | ((buffer4[2] & 0x3C) >> 2);
        buffer3[2] = ((buffer4[2] & 0x03) << 6) | buffer4[3];

        for (index = 0; index < pos - 1; index++)
            result.push_back(static_cast<char>(buffer3[index]));
    }

    return result;
}

