// Custom thread class for executing Python scripts in a separate thread
class ScriptRunner : public QThread {
    Q_OBJECT

public:
    ScriptRunner(QObject *parent = nullptr) : QThread(parent) {}

signals:
    void executionFinished(const QString &output);

protected:
    void run() override {
        Py_Initialize();
        PyRun_SimpleString("import sys");
        PyRun_SimpleString("sys.path.append('./')");

        PyObject *module = PyImport_ImportModule("your_module");
        if (module != NULL) {
            PyObject *function = PyObject_GetAttrString(module, "your_function");
            if (function && PyCallable_Check(function)) {
                PyObject *arguments = PyTuple_New(1);
                PyObject *inputValue = PyUnicode_FromString("your_argument");
                PyTuple_SetItem(arguments, 0, inputValue);

                PyObject *result = PyObject_CallObject(function, arguments);
                if (result != NULL) {
                    const char *output = PyUnicode_AsUTF8(result);
                    QMetaObject::invokeMethod(this, [this, output]() {
                        emit executionFinished(QString(output));
                    }, Qt::QueuedConnection);
                }

                Py_DECREF(arguments);
                Py_DECREF(function);
            }
            Py_DECREF(module);
        }

        Py_Finalize();
    }
};

// Main application window with UI elements for Python script interaction
class ApplicationWindow : public QWidget {
    Q_OBJECT

public:
    ApplicationWindow(QWidget *parent = nullptr) : QWidget(parent) {
        QVBoxLayout *mainLayout = new QVBoxLayout(this);

        outputDisplay = new QTextEdit(this);
        inputField = new QLineEdit(this);
        executeButton = new QPushButton("Execute Python", this);

        mainLayout->addWidget(outputDisplay);
        mainLayout->addWidget(inputField);
        mainLayout->addWidget(executeButton);

        connect(executeButton, &QPushButton::clicked, this, &ApplicationWindow::startScriptExecution);
    }

private slots:
    void startScriptExecution() {
        scriptThread = new ScriptRunner(this);
        connect(scriptThread, &ScriptRunner::executionFinished, this, &ApplicationWindow::handleOutput);

        // Temporarily disable user inputs during execution
        inputField->setEnabled(false);
        executeButton->setEnabled(false);

        scriptThread->start();
    }

    void handleOutput(const QString &output) {
        outputDisplay->append(output);

        // Re-enable controls after execution completes
        inputField->setEnabled(true);
        executeButton->setEnabled(true);

        // Clean up the thread object
        scriptThread->deleteLater();
    }

private:
    QTextEdit *outputDisplay;
    QLineEdit *inputField;
    QPushButton *executeButton;
    ScriptRunner *scriptThread;
};

