#include <cuda_runtime.h>
#include <iostream>

#define MATRIX_SIZE 1000

__global__ void matrixMultiplication(float *inputMatrixA, float *inputMatrixB, float *outputMatrix, int size) {
    int rowIndex = blockIdx.y * blockDim.y + threadIdx.y;
    int colIndex = blockIdx.x * blockDim.x + threadIdx.x;

    if (rowIndex < size && colIndex < size) {
        float accumulator = 0.0f;
        for (int k = 0; k < size; k++) {
            accumulator += inputMatrixA[rowIndex * size + k] * inputMatrixB[k * size + colIndex];
        }
        outputMatrix[rowIndex * size + colIndex] = accumulator;
    }
}

int main() {
    float *host_A, *host_B, *host_C;
    float *device_A, *device_B, *device_C;

    // Allocate memory on the host
    host_A = (float*)malloc(MATRIX_SIZE * MATRIX_SIZE * sizeof(float));
    host_B = (float*)malloc(MATRIX_SIZE * MATRIX_SIZE * sizeof(float));
    host_C = (float*)malloc(MATRIX_SIZE * MATRIX_SIZE * sizeof(float));

    // Initialize matrices with constant values
    for (int index = 0; index < MATRIX_SIZE * MATRIX_SIZE; index++) {
        host_A[index] = 1.0f;
        host_B[index] = 2.0f;
    }

    // Allocate memory on the GPU device
    cudaMalloc(&device_A, MATRIX_SIZE * MATRIX_SIZE * sizeof(float));
    cudaMalloc(&device_B, MATRIX_SIZE * MATRIX_SIZE * sizeof(float));
    cudaMalloc(&device_C, MATRIX_SIZE * MATRIX_SIZE * sizeof(float));

    // Transfer data from host to device
    cudaMemcpy(device_A, host_A, MATRIX_SIZE * MATRIX_SIZE * sizeof(float), cudaMemcpyHostToDevice);
    cudaMemcpy(device_B, host_B, MATRIX_SIZE * MATRIX_SIZE * sizeof(float), cudaMemcpyHostToDevice);

    // Configure execution configuration
    dim3 blockSize(16, 16);
    dim3 gridSize((MATRIX_SIZE + blockSize.x - 1) / blockSize.x, (MATRIX_SIZE + blockSize.y - 1) / blockSize.y);

    // Launch the kernel
    matrixMultiplication<<<gridSize, blockSize>>>(device_A, device_B, device_C, MATRIX_SIZE);

    // Copy result back from device to host
    cudaMemcpy(host_C, device_C, MATRIX_SIZE * MATRIX_SIZE * sizeof(float), cudaMemcpyDeviceToHost);

    // Release device memory
    cudaFree(device_A);
    cudaFree(device_B);
    cudaFree(device_C);

    // Release host memory
    free(host_A);
    free(host_B);
    free(host_C);

    return 0;
}

