            return AsyncOperation{std::coroutine_handle<handler>::from_promise(*this)}; 
        }
        std::suspend_never first_suspend() { return {}; }
        std::suspend_never last_suspend() noexcept { return {}; }
        void set_result() {}
        void handle_error() { std::terminate(); }
    };

    bool completed() const { return m_coro.done(); }
    void run() { m_coro.resume(); }
    void stop() { m_coro.promise().m_paused = true; }

private:
    std::coroutine_handle<handler> m_coro;

    AsyncOperation(std::coroutine_handle<handler> coro) : m_coro(coro) {}
    ~AsyncOperation() { if (m_coro) m_coro.destroy(); }

    friend struct handler;
};

AsyncOperation process_task() {
    while (true) {
        std::cout << "Task executing\n";
        co_await std::suspend_always{};
        std::cout << "Task continuing\n";
    }
}

int main() {
    AsyncOperation operation = process_task();
    operation.run();
    operation.stop();
    operation.run();
    return 0;
}

