// Function to compute the length of the longest increasing subsequence
int findLISLength(vector<int>& arr) {
    if (arr.empty()) return 0;

    vector<int> tails;
    for (int value : arr) {
        auto pos = lower_bound(tails.begin(), tails.end(), value);
        if (pos == tails.end()) {
            tails.push_back(value);
        } else {
            *pos = value;
        }
    }
    return tails.size();
}

int main() {
    vector<int> data = {10, 9, 2, 5, 3, 7, 101, 18};
    int result = findLISLength(data);
    cout << "Length of the longest increasing subsequence is: " << result << endl;
    return 0;
}

