// Determine whether a number is prime
bool checkPrime(int num) {
    if (num <= 1) return false;
    if (num <= 3) return true;
    if (num % 2 == 0 || num % 3 == 0) return false;
    for (int j = 5; j * j <= num; j += 6) {
        if (num % j == 0 || num % (j + 2) == 0) return false;
    }
    return true;
}

// Locate the smallest prime number larger than a given value
int findNextPrime(int val) {
    if (val <= 1) return 2;
    int candidate = val;
    bool success = false;
    while (!success) {
        candidate++;
        if (checkPrime(candidate)) {
            success = true;
        }
    }
    return candidate;
}

int main() {
    int userInput;
    std::cout << "Enter a number: ";
    std::cin >> userInput;

    int output = findNextPrime(userInput);
    std::cout << "The first prime number greater than " << userInput << " is " << output << std::endl;

    return 0;
}

