#include <immintrin.h>

// Perform complex conjugate multiplication using AVX instructions
void avx_vcmulcc(cfloat* output, const cfloat* inputA, const cfloat* inputB, int count) {
    for (int index = 0; index < count; index += 8) {
        __m256 operand1 = _mm256_loadu_ps((const float*)(inputA + index));
        __m256 operand2 = _mm256_loadu_ps((const float*)(inputB + index));

        // Extract real and imaginary parts with appropriate permutations
        __m256 real_part1 = _mm256_permute_ps(operand1, _MM_SHUFFLE(2, 3, 0, 1));
        __m256 imag_part1 = _mm256_permute_ps(operand1, _MM_SHUFFLE(3, 2, 1, 0));
        __m256 real_part2 = _mm256_permute_ps(operand2, _MM_SHUFFLE(2, 3, 0, 1));
        __m256 imag_part2 = _mm256_permute_ps(operand2, _MM_SHUFFLE(3, 2, 1, 0));

        // Compute real part: (a_real * b_real) - (a_imag * b_imag)
        __m256 result_real = _mm256_sub_ps(_mm256_mul_ps(real_part1, real_part2), 
                                           _mm256_mul_ps(imag_part1, imag_part2));

        // Compute imaginary part: (a_real * b_imag) + (a_imag * b_real)
        __m256 result_imag = _mm256_add_ps(_mm256_mul_ps(real_part1, imag_part2), 
                                           _mm256_mul_ps(imag_part1, real_part2));

        // Store the result by combining real and imaginary parts
        _mm256_storeu_ps((float*)(output + index), 
                         _mm256_permute2f128_ps(result_real, result_imag, 0x20));
    }
}

