// Acquire a free slot by finding the first unset bit
std::uint64_t obtain() noexcept {
    while (true) {
        std::uint64_t current = mData;

        std::uint64_t position = (current & 1) ? 1 : 0;
        auto selection = std::uint64_t(1) << position;

        auto prior =
            __atomic_fetch_or(&mData, selection, __ATOMIC_SEQ_CST);
        if ((prior & selection) == 0) {
            return position;
        }
    }
}

