// Display the chessboard with coordinates
void show_grid() {
    cout << endl << "   a  b  c  d  e  f  g  h" << endl;
    for (int row = 0; row < 8; row++) {
        cout << row + 1 << "  ";
        for (int col = 0; col < 8; col++) {
            cout << grid[row][col] << "  ";
        }
        cout << row + 1 << endl;
    }
    cout << "   a  b  c  d  e  f  g  h" << endl << endl;
}

// Execute a move if it's valid
void execute_move(int start_row, int start_col, int end_row, int end_col) {
    if (check_validity(start_row, start_col, end_row, end_col)) {
        swap(grid[start_row][start_col], grid[end_row][end_col]);
    }
}

int main() {
    bool is_white_turn = true;
    while (!match_ended(is_white_turn)) {
        show_grid();
        cout << "Current player: " << ((is_white_turn) ? "white" : "black") << endl;
        bool move_accepted = false;
        while (!move_accepted) {
            string input;
            cout << "Enter your move (e.g., e2e4): ";
            getline(cin, input);
            if (input.length() == 4) {
                int start_row = input[0] - 'a';
                int start_col = input[1] - '1';
                int end_row = input[2] - 'a';
                int end_col = input[3] - '1';

                if (check_validity(start_row, start_col, end_row, end_col) && 
                    ((isupper(grid[start_row][start_col]) == is_white_turn))) {
                    execute_move(start_row, start_col, end_row, end_col);
                    move_accepted = true;
                }
            }
            if (!move_accepted) {
                cout << "Move not allowed. Please try again." << endl;
            }
        }
        is_white_turn = !is_white_turn;
    }
    show_grid();
    if (checkmate_detected(!is_white_turn)) {
        cout << ((is_white_turn) ? "Black" : "White") << " wins by checkmate!" << endl;
    }
    else if (stalemate_detected(!is_white_turn)) {
        cout << "Game ends in a draw due to stalemate." << endl;
    }
    return 0;
}

