#include <sys/resource.h>
#include <iostream>

// Measure average CPU time over 10 iterations 
int main() {
    double total_time = 0.0;
    int iterations = (int) 1e6;
    int count = 0;

    struct rusage process_usage;
    struct timeval user_start, user_stop, sys_start, sys_stop;

    getrusage(RUSAGE_SELF, &process_usage);
    user_start = process_usage.ru_utime;
    sys_start = process_usage.ru_stime;

    for (int loop=0; loop<10; loop++) {
        user_start = process_usage.ru_utime;
        sys_start = process_usage.ru_stime;

        for (int j=0; j<iterations; j++) continue;

        getrusage(RUSAGE_SELF, &process_usage);
        user_stop = process_usage.ru_utime;
        sys_stop = process_usage.ru_stime;

        double user_time = (user_stop.tv_sec + user_stop.tv_usec / 1e6) - (user_start.tv_sec + user_start.tv_usec / 1e6);
        double system_time = (sys_stop.tv_sec + sys_stop.tv_usec / 1e6) - (sys_start.tv_sec + sys_start.tv_usec / 1e6);

        total_time += (user_time + system_time) / 10.0;
    }

    std::cout << total_time << '\n';

    return 0;
}

