#include <iostream>
#include <vector>
#include <mutex>
#include <cuda_runtime.h>

// Custom memory allocator for GPU using CUDA
class DeviceMemoryPool {
public:
    DeviceMemoryPool(size_t chunk_size, size_t chunk_count) : chunk_size_(chunk_size), chunk_count_(chunk_count) {
        // Allocate a contiguous GPU memory block
        cudaMalloc(&memory_pool_, chunk_size * chunk_count);

        // Setup bookkeeping structures
        block_info_.resize(chunk_count);
        for (size_t i = 0; i < chunk_count; ++i) {
            block_info_[i].is_available = true;
            block_info_[i].id = static_cast<int>(i);
        }
        available_head_ = 0;
    }

    ~DeviceMemoryPool() {
        cudaFree(memory_pool_);
    }

    void* acquire() {
        std::lock_guard<std::mutex> guard(lock_);

        if (available_head_ == -1) {
            throw std::bad_alloc();
        }

        int slot_id = available_head_;
        available_head_ = block_info_[slot_id].next_slot;

        block_info_[slot_id].is_available = false;
        return static_cast<char*>(memory_pool_) + slot_id * chunk_size_;
    }

    void release(void* address) {
        std::lock_guard<std::mutex> guard(lock_);

        size_t slot_index = (static_cast<char*>(address) - static_cast<char*>(memory_pool_)) / chunk_size_;

        block_info_[slot_index].is_available = true;
        block_info_[slot_index].next_slot = available_head_;
        available_head_ = static_cast<int>(slot_index);
    }

private:
    size_t chunk_size_;
    size_t chunk_count_;
    void* memory_pool_;
    std::vector<struct SlotInfo> block_info_;
    int available_head_ = 0;
    std::mutex lock_;

    struct SlotInfo {
        bool is_available;
        int id;
        int next_slot = -1;
    };
};

int main() {
    DeviceMemoryPool pool(256, 1024);

    void* block_a = pool.acquire();
    void* block_b = pool.acquire();

    pool.release(block_a);
    pool.release(block_b);

    return 0;
}

