#include <cuda_runtime.h>
#include <thrust/device_vector.h>
#include <thrust/sort.h>
#include <thrust/execution_policy.h>

struct Vector2D {
    float x, y;
};

struct TreeNode {
    int beginIdx, endIdx;  // Range of points in the array
    int splitDim;          // Splitting dimension (0 for x, 1 for y)
    float threshold;       // Splitting value
    int childLeft, childRight; // Indices of left and right children
};

__global__ void constructKdTreeKernel(Vector2D* dataPoints, TreeNode* treeNodes, int* workStack, int* stackTop, int* nodeCounter) {
    int threadId = blockIdx.x * blockDim.x + threadIdx.x;
    if (threadId >= *stackTop) return;

    int currentNode = workStack[threadId];
    TreeNode& node = treeNodes[currentNode];
    int leftBound = node.beginIdx;
    int rightBound = node.endIdx;
    int dim = node.splitDim;

    // Sort points along the current dimension
    thrust::sort(thrust::device, dataPoints + leftBound, dataPoints + rightBound, [dim] __device__ (const Vector2D& a, const Vector2D& b) {
        return (dim == 0) ? a.x < b.x : a.y < b.y;
    });

    // Locate the median point
    int mid = (leftBound + rightBound) / 2;
    float splitValue = (dim == 0) ? dataPoints[mid].x : dataPoints[mid].y;

    // Allocate new nodes for children
    int leftChild = atomicAdd(nodeCounter, 1);
    int rightChild = atomicAdd(nodeCounter, 1);

    treeNodes[leftChild] = {leftBound, mid, 1 - dim, 0, -1, -1};
    treeNodes[rightChild] = {mid + 1, rightBound, 1 - dim, 0, -1, -1};

    node.threshold = splitValue;
    node.childLeft = leftChild;
    node.childRight = rightChild;

    // Push children onto the work stack
    workStack[*stackTop] = leftChild;
    workStack[++*stackTop] = rightChild;
}

void buildKdTreeStructure(Vector2D* d_points, int pointCount, TreeNode* d_nodes, int maxCapacity) {
    // Setup initial root node
    TreeNode rootNode = {0, pointCount, 0, 0, -1, -1};
    cudaMemcpy(d_nodes, &rootNode, sizeof(TreeNode), cudaMemcpyHostToDevice);

    // Allocate device memory for stack and counters
    int* d_workStack;
    cudaMalloc(&d_workStack, maxCapacity * sizeof(int));
    int* d_stackPointer;
    cudaMalloc(&d_stackPointer, sizeof(int));
    int* d_nodeAllocator;
    cudaMalloc(&d_nodeAllocator, sizeof(int));

    int currentStackSize = 1;
    int nextNodeId = 1;

    cudaMemcpy(d_workStack, &rootNode, sizeof(TreeNode), cudaMemcpyHostToDevice);
    cudaMemcpy(d_stackPointer, &currentStackSize, sizeof(int), cudaMemcpyHostToDevice);
    cudaMemcpy(d_nodeAllocator, &nextNodeId, sizeof(int), cudaMemcpyHostToDevice);

    // Kernel configuration
    int threadsPerBlock = 256;
    int blocksPerGrid = (maxCapacity + threadsPerBlock - 1) / threadsPerBlock;

    // Iteratively build the tree
    while (currentStackSize > 0) {
        constructKdTreeKernel<<<blocksPerGrid, threadsPerBlock>>>(d_points, d_nodes, d_workStack, d_stackPointer, d_nodeAllocator);
        cudaDeviceSynchronize();

        // Retrieve updated stack size and next node ID
        cudaMemcpy(&currentStackSize, d_stackPointer, sizeof(int), cudaMemcpyDeviceToHost);
        cudaMemcpy(&nextNodeId, d_nodeAllocator, sizeof(int), cudaMemcpyDeviceToHost);
    }

    cudaFree(d_workStack);
    cudaFree(d_stackPointer);
    cudaFree(d_nodeAllocator);
}

