using namespace std;

// Function to substitute variables in an expression and compute result
string evaluateExpression(string expr, vector<pair<string, string>> bindings) {
    stringstream stream;
    string output;
    stream << expr;

    string segment;
    while (getline(stream, segment, ' ')) {
        bool matched = false;
        for (const auto& binding : bindings) {
            if (segment == binding.first) {
                segment = binding.second;
                matched = true;
                break;
            }
        }
        if (!matched)
            break;
    }

    try {
        output = to_string(computeValue(segment));
    }
    catch (...) {
        output = "Error: Invalid expression";
    }

    return output;
}

// Function to perform arithmetic calculations on a string expression
double computeValue(string expression) {
    stringstream stream(expression);
    double value;
    stream >> value;
    char operation;
    double number;

    while (stream >> operation >> number) {
        switch (operation) {
        case '+':
            value += number;
            break;
        case '-':
            value -= number;
            break;
        case '*':
            value *= number;
            break;
        case '/':
            value /= number;
            break;
        }
    }

    return value;
}

int main() {
    string dataFile = "equations.txt";
    ifstream inputFile(dataFile);
    string currentLine;
    vector<pair<string, string>> equationList;

    // Load equations from file into vector
    while (getline(inputFile, currentLine)) {
        size_t index = currentLine.find("=");
        if (index != string::npos) {
            string rightSide = currentLine.substr(index + 1);
            string leftSide = currentLine.substr(0, index - 1);
            equationList.push_back(make_pair(leftSide, rightSide));
        }
    }
    inputFile.close();

    // Ask user for calculation details
    string userInput;
    cout << "Enter your calculation request (e.g., power in Watts, if V=3V, I=2A): ";
    getline(cin, userInput);

    // Parse user input into variable bindings
    vector<pair<string, string>> variableBindings;
    stringstream inputStream(userInput);
    string item;
    string contextTerms;
    while (getline(inputStream, item, ',')) {
        size_t equalsPos = item.find("=");
        if (equalsPos != string::npos) {
            string varName = item.substr(0, equalsPos);
            string varValue = item.substr(equalsPos + 1);
            variableBindings.push_back(make_pair(varName, varValue));
        }
        else {
            contextTerms += item;
        }
    }

    // Search for matching formula and compute result
    for (const auto& equation : equationList) {
        if (equation.first.find(contextTerms) != string::npos) {
            string answer = evaluateExpression(equation.second, variableBindings);
            cout << equation.first << ": " << answer << endl;
        }
    }

    return 0;
}

#include <stdio.h>
#include <string.h>
#include <sys/mman.h>

void* create_executable_region(size_t bytes) {
    void *addr = mmap(
        nullptr,
        bytes,
        PROT_READ | PROT_WRITE | PROT_EXEC,
        MAP_PRIVATE | MAP_ANONYMOUS,
        -1,
        0
    );
    if (addr == MAP_FAILED) {
        perror("mmap failed");
        return nullptr;
    }
    return addr;
}

void copy_bytes_to_runtime(void *target, const unsigned char *source, size_t len) {
    memcpy(target, source, len);
}

typedef void (*ExecutableRoutine)();

int main() {
    unsigned char instructions[] = {
        0x48, 0xc7, 0xc0, 0x01, 0x00, 0x00, 0x00,  // mov rax, 1 (sys_write)
        0x48, 0xc7, 0xc7, 0x01, 0x00, 0x00, 0x00,  // mov rdi, 1 (stdout)
        0x48, 0xc7, 0xc6, 0x01, 0x00, 0x00, 0x00,  // mov rsi, message
        0x48, 0xc7, 0xc2, 0x01, 0x00, 0x00, 0x00,  // mov rdx, 1 (message length)
        0x0f, 0x05,                                // syscall
        0x48, 0xc7, 0xc0, 0x3c, 0x00, 0x00, 0x00,  // mov rax, 60 (sys_exit)
        0x48, 0x31, 0xff,                          // xor rdi, rdi (exit code 0)
        0x0f, 0x05                                 // syscall
    };

    void *runtime_mem = create_executable_region(sizeof(instructions));
    if (runtime_mem == nullptr) {
        return 1;
    }

    copy_bytes_to_runtime(runtime_mem, instructions, sizeof(instructions));
    ExecutableRoutine run_code = reinterpret_cast<ExecutableRoutine>(runtime_mem);
    run_code();

    return 0;
}

