#include <vector>
#include <stdexcept>

class MinPriorityQueue {
public:
    MinPriorityQueue() = default;

    // Add a new item to the priority queue
    void add(int val) {
        data.push_back(val);
        bubbleUp(data.size() - 1);
    }

    // Remove and return the smallest item from the priority queue
    int removeMin() {
        if (data.empty()) {
            throw std::runtime_error("Priority queue is empty");
        }

        int minVal = data[0];
        data[0] = data.back();
        data.pop_back();
        bubbleDown(0);

        return minVal;
    }

    // View the smallest item without removing it
    int peek() const {
        if (data.empty()) {
            throw std::runtime_error("Priority queue is empty");
        }
        return data[0];
    }

    // Determine if the priority queue has no elements
    bool isEmpty() const {
        return data.empty();
    }

    // Return the count of items in the priority queue
    size_t count() const {
        return data.size();
    }

private:
    std::vector<int> data;

    // Move the element at position idx upward until heap property is restored
    void bubbleUp(int idx) {
        while (idx > 0) {
            int parentIdx = (idx - 1) / 2;
            if (data[idx] < data[parentIdx]) {
                std::swap(data[idx], data[parentIdx]);
                idx = parentIdx;
            } else {
                break;
            }
        }
    }

    // Move the element at position idx downward until heap property is restored
    void bubbleDown(int idx) {
        int n = data.size();
        while (2 * idx + 1 < n) {
            int leftChild = 2 * idx + 1;
            int rightChild = 2 * idx + 2;
            int minIdx = idx;

            if (leftChild < n && data[leftChild] < data[minIdx]) {
                minIdx = leftChild;
            }

            if (rightChild < n && data[rightChild] < data[minIdx]) {
                minIdx = rightChild;
            }

            if (minIdx != idx) {
                std::swap(data[idx], data[minIdx]);
                idx = minIdx;
            } else {
                break;
            }
        }
    }
};

// Demonstration of the priority queue functionality
int main() {
    MinPriorityQueue pq;
    pq.add(3);
    pq.add(2);
    pq.add(15);
    pq.add(5);
    pq.add(4);
    pq.add(45);

    while (!pq.isEmpty()) {
        std::cout << pq.removeMin() << " ";
    }

    return 0;
}

