#include <iostream>
#include <vector>
#include <algorithm>
#include <random>
#include <cmath>
#include <limits>

using namespace std;

struct Location {
    int identifier;
    double longitude, latitude;
};

double computeDistance(Location &p1, Location &p2) {
    return sqrt(pow(p1.longitude - p2.longitude, 2) + pow(p1.latitude - p2.latitude, 2));
}

double tourCost(const vector<Location> &route, const vector<int> &order) {
    double accumulated = 0.0;
    int size = route.size();
    for (int i = 0; i < size; ++i) {
        int nextIndex = (i + 1) % size;
        accumulated += computeDistance(route[order[i]], route[order[nextIndex]]);
    }
    return accumulated;
}

vector<vector<double>> buildDistanceTable(const vector<Location> &points) {
    int count = points.size();
    vector<vector<double>> matrix(count, vector<double>(count, 0.0));
    for (int i = 0; i < count; ++i) {
        for (int j = 0; j < count; ++j) {
            matrix[i][j] = computeDistance(points[i], points[j]);
        }
    }
    return matrix;
}

vector<int> combine(const vector<int> &mom, const vector<int> &dad) {
    int length = mom.size();
    int leftBound = rand() % length;
    int rightBound = rand() % length;
    if (leftBound > rightBound) swap(leftBound, rightBound);

    vector<int> offspring(length, -1);
    for (int pos = leftBound; pos <= rightBound; ++pos) {
        offspring[pos] = mom[pos];
    }

    int idx = 0;
    for (int val : dad) {
        if (find(offspring.begin(), offspring.end(), val) == offspring.end()) {
            while (offspring[idx] != -1) idx++;
            offspring[idx] = val;
        }
    }
    return offspring;
}

void perturb(vector<int> &solution, double changeProbability) {
    for (int position = 0; position < solution.size(); ++position) {
        if (rand() / double(RAND_MAX) < changeProbability) {
            int swapPosition = rand() % solution.size();
            swap(solution[position], solution[swapPosition]);
        }
    }
}

vector<int> evolutionarySearch(const vector<Location> &places, int populationCount, double mutationChance, int iterationLimit) {
    int dimension = places.size();
    vector<vector<int>> currentPopulation(populationCount, vector<int>(dimension));

    // Initialize population with random permutations
    for (int k = 0; k < populationCount; ++k) {
        for (int m = 0; m < dimension; ++m) {
            currentPopulation[k][m] = m;
        }
        random_shuffle(currentPopulation[k].begin(), currentPopulation[k].end());
    }

    vector<pair<double, vector<int>>> evaluatedSet;

    for (int epoch = 0; epoch < iterationLimit; ++epoch) {
        evaluatedSet.clear();
        for (const auto &candidate : currentPopulation) {
            evaluatedSet.emplace_back(tourCost(places, candidate), candidate);
        }
        sort(evaluatedSet.begin(), evaluatedSet.end());

        vector<vector<int>> nextGeneration;
        int survivors = populationCount / 2;
        for (int index = 0; index < survivors; ++index) {
            nextGeneration.push_back(evaluatedSet[index].second);
        }

        while (nextGeneration.size() < populationCount) {
            int fatherIdx = rand() % nextGeneration.size();
            int motherIdx = rand() % nextGeneration.size();
            vector<int> progeny = combine(nextGeneration[fatherIdx], nextGeneration[motherIdx]);
            perturb(progeny, mutationChance);
            nextGeneration.push_back(progeny);
        }

        currentPopulation = nextGeneration;
    }

    return evaluatedSet[0].second; // Return best solution found
}

int main() {
    vector<Location> locations = {{0, 0.0, 0.0}, {1, 1.0, 2.0}, {2, 3.0, 1.0}, {3, 5.0, 5.0}, {4, 6.0, 2.0}};
    int populationSize = 100;
    double mutationProbability = 0.01;
    int maxGenerations = 1000;

    vector<int> optimalRoute = evolutionarySearch(locations, populationSize, mutationProbability, maxGenerations);
    cout << "Optimal Route: ";
    for (int cityIndex : optimalRoute) {
        cout << locations[cityIndex].identifier << " ";
    }
    cout << "\nTotal Distance: " << tourCost(locations, optimalRoute) << endl;

    return 0;
}

