using namespace Eigen;

struct LightRay {
    Vector3f start_point;
    Vector3f dir;
    LightRay(Vector3f s, Vector3f d) : start_point(s), dir(d) {}
};

struct Ball {
    Vector3f position;
    float size;
    Vector3f shade;
    Ball(Vector3f p, float r, Vector3f col) : position(p), size(r), shade(col) {}

    bool hit(const LightRay& ray, float& dist) const {
        Vector3f vec_to_center = position - ray.start_point;
        float proj_len = vec_to_center.dot(ray.dir);
        if (proj_len < 0) return false;
        float dist_sq = vec_to_center.squaredNorm() - proj_len * proj_len;
        float radius_sq = size * size;
        if (dist_sq > radius_sq) return false;
        float depth = std::sqrt(radius_sq - dist_sq);
        dist = proj_len - depth;
        return true;
    }
};

Vector3f compute_shading(const LightRay& ray, const std::vector<Ball>& objects) {
    float min_distance = std::numeric_limits<float>::max();
    const Ball* nearest_object = nullptr;

    for (const auto& obj : objects) {
        float distance;
        if (obj.hit(ray, distance) && distance < min_distance) {
            min_distance = distance;
            nearest_object = &obj;
        }
    }

    if (nearest_object) {
        Vector3f impact_point = ray.start_point + ray.dir * min_distance;
        Vector3f surface_normal = (impact_point - nearest_object->position).normalized();
        Vector3f illumination_direction = Vector3f(-1, 1, 1).normalized();
        float intensity = std::max(0.0f, surface_normal.dot(illumination_direction));
        return nearest_object->shade * intensity;
    }

    return Vector3f(0, 0, 0); // Default background color
}

int main() {
    int img_width = 800, img_height = 600;
    std::vector<Vector3f> buffer(img_width * img_height, Vector3f(0, 0, 0));

    Vector3f eye_position(0, 0, -5);
    Vector3f image_plane_center(0, 0, 0);
    float plane_width = 2.0f, plane_height = 2.0f * img_height / img_width;

    std::vector<Ball> scene_objects = {
        Ball(Vector3f(0, 0, 0), 1, Vector3f(1, 0, 0)),
        Ball(Vector3f(1, 0, 0), 1, Vector3f(0, 1, 0)),
        Ball(Vector3f(-1, 0, 0), 1, Vector3f(0, 0, 1))
    };

    for (int row = 0; row < img_height; ++row) {
        for (int col = 0; col < img_width; ++col) {
            float u_coord = (2 * (col + 0.5) / img_width - 1) * plane_width;
            float v_coord = (1 - 2 * (row + 0.5) / img_height) * plane_height;
            Vector3f pixel_position(image_plane_center + Vector3f(u_coord, v_coord, 0));
            LightRay ray(eye_position, (pixel_position - eye_position).normalized());
            buffer[row * img_width + col] = compute_shading(ray, scene_objects);
        }
    }

    // Output the rendered image data
    for (int row = 0; row < img_height; ++row) {
        for (int col = 0; col < img_width; ++col) {
            Vector3f pixel_color = buffer[row * img_width + col];
            std::cout << (int)(255 * std::min(1.0f, pixel_color[0])) << " "
                      << (int)(255 * std::min(1.0f, pixel_color[1])) << " "
                      << (int)(255 * std::min(1.0f, pixel_color[2])) << "\n";
        }
    }

    return 0;
}

#include <iostream>
#include <list>

class MinMaxTracker {
private:
    std::list<int> data;
    std::list<int>::iterator minPos, maxPos;

public:
    MinMaxTracker() : minPos(data.end()), maxPos(data.end()) {}

    void addValue(int val) {
        data.push_back(val);
        auto pos = --data.end();
        if (minPos == data.end() || *pos < *minPos) minPos = pos;
        if (maxPos == data.end() || *pos > *maxPos) maxPos = pos;
    }

    void deleteValue(int val) {
        auto pos = std::find(data.begin(), data.end(), val);
        if (pos != data.end()) {
            if (pos == minPos) {
                if (pos != data.begin()) minPos = std::prev(pos);
                else minPos = data.end();
            }
            if (pos == maxPos) {
                if (pos != --data.end()) maxPos = std::next(pos);
                else maxPos = data.end();
            }
            data.erase(pos);
        }
    }

    int findMinimum() const {
        return minPos != data.end() ? *minPos : -1;
    }

    int findMaximum() const {
        return maxPos != data.end() ? *maxPos : -1;
    }
};

int main() {
    MinMaxTracker tracker;
    tracker.addValue(5);
    tracker.addValue(3);
    tracker.addValue(7);
    std::cout << "Min: " << tracker.findMinimum() << std::endl; // 3
    std::cout << "Max: " << tracker.findMaximum() << std::endl; // 7
    tracker.deleteValue(3);
    std::cout << "Min: " << tracker.findMinimum() << std::endl; // 5
    return 0;
}

