// Transform cv::Mat into numpy array representation
boost::python::object convert_mat_to_numpy(const cv::Mat& image) {
    npy_intp shape[2] = {image.rows, image.cols};
    PyObject* result_array = PyArray_SimpleNew(2, shape, NPY_FLOAT64);
    std::memcpy(PyArray_DATA(result_array), image.ptr<double>(), image.total() * image.elemSize());
    return boost::python::object(boost::python::handle<>(boost::python::borrowed(result_array)));
}

// Transform numpy array into cv::Mat structure
cv::Mat convert_numpy_to_mat(boost::python::object& source_array) {
    PyArrayObject* converted_array = reinterpret_cast<PyArrayObject*>(source_array.ptr());
    npy_intp* dimensions = PyArray_DIMS(converted_array);
    cv::Mat matrix(dimensions[0], dimensions[1], CV_64F, PyArray_DATA(converted_array));
    return matrix;
}

