// Base abstract class with pure virtual method
class BaseInterface {
public:
    std::vector<int> data_values;

    virtual void process() = 0;
};

// Another interface with dependency on BaseInterface
class HandlerInterface {
public:
    virtual void handle(const BaseInterface& ref) = 0;
};

namespace py = boost::python;

// Wrapper for BaseInterface to support Python overrides
class BaseInterface_wrapper : public BaseInterface, public py::wrapper<BaseInterface> {
public:
    void process() override {
        this->get_override("process")();
    }
};

// Wrapper for HandlerInterface to support Python overrides
class HandlerInterface_wrapper : public HandlerInterface, public py::wrapper<HandlerInterface> {
public:
    void handle(const BaseInterface& ref) override {
        this->get_override("handle")(ref);
    }
};

// Converter from C++ BaseInterface to Python object
struct BaseInterface_to_python_converter {
    static PyObject* convert(const BaseInterface& obj) {
        py::object py_obj = py::object(py::ptr(new BaseInterface_wrapper(obj)));
        return py_obj.ptr();
    }
};

BOOST_PYTHON_MODULE(module_example) {
    using int_vector_type = std::vector<int>;

    // Expose vector<int> as a Python list-like type
    py::class_<int_vector_type>("IntSequence")
        .def(py::vector_indexing_suite<int_vector_type>());

    // Expose BaseInterface wrapper
    py::class_<BaseInterface_wrapper, boost::noncopyable>("BaseInterface")
        .def_readwrite("data_values", &BaseInterface::data_values)
        .def("process", py::pure_virtual(&BaseInterface::process));

    // Expose HandlerInterface wrapper
    py::class_<HandlerInterface_wrapper, boost::noncopyable>("HandlerInterface")
        .def("handle", py::pure_virtual(&HandlerInterface::handle));

    // Register custom converter for BaseInterface
    py::to_python_converter<BaseInterface, BaseInterface_to_python_converter>();
}

