// Compute mean squared error for linear hypothesis
double calculate_error(const std::vector<double>& inputs, const std::vector<double>& outputs, double intercept, double slope) {
    int n = inputs.size();
    double error_sum = 0.0;
    for (int idx = 0; idx < n; ++idx) {
        double predicted = intercept + slope * inputs[idx];
        error_sum += std::pow(predicted - outputs[idx], 2);
    }
    return error_sum / (2.0 * n);
}

// Perform gradient descent optimization
void optimize_parameters(const std::vector<double>& inputs, const std::vector<double>& outputs, 
                        double& intercept, double& slope, double learning_rate, int max_epochs) {
    int n = inputs.size();
    for (int epoch = 0; epoch < max_epochs; ++epoch) {
        double grad_intercept = 0.0;
        double grad_slope = 0.0;

        for (int idx = 0; idx < n; ++idx) {
            double prediction = intercept + slope * inputs[idx];
            double error = prediction - outputs[idx];
            grad_intercept += error;
            grad_slope += error * inputs[idx];
        }

        intercept -= learning_rate * grad_intercept / n;
        slope -= learning_rate * grad_slope / n;

        // Track cost function value during training
        double current_error = calculate_error(inputs, outputs, intercept, slope);
        std::cout << "Epoch " << epoch << " - Error: " << current_error << std::endl;
    }
}

int main() {
    std::vector<double> feature_values = {1, 2, 3, 4, 5};
    std::vector<double> target_values = {2, 4, 5, 4, 5};

    double intercept_init = 0.0;
    double slope_init = 0.0;
    double learning_rate = 0.01;
    int training_iterations = 1000;

    optimize_parameters(feature_values, target_values, intercept_init, slope_init, 
                       learning_rate, training_iterations);

    std::cout << "Optimized intercept: " << intercept_init 
              << ", slope: " << slope_init << std::endl;

    return 0;
}

