using namespace std;

// Function to measure execution time for sum operation
pair<double, double> benchmark_reduction(int array_size, int iterations=30) {
    double elapsed_time = 0.0;
    double accumulated_result = 0.0;

    for (int j = 0; j < iterations; j++) {
        xt::xtensor<double, 1> data = xt::random::rand({array_size}, 0.0, 1.0);
        int begin_time = clock();

        double result = xt::sum(data, xt::evaluation_strategy::immediate, xt::parallelExecution())();

        int finish_time = clock();
        accumulated_result += result;
        elapsed_time += finish_time - begin_time;
    }

    return make_pair(elapsed_time / CLOCKS_PER_SEC / iterations, accumulated_result);
}

int main(int argc, char *argv[]) {
    for (int exp = 5; exp < 8; exp++) {
        int dimension = static_cast<int>(pow(10, exp));
        pair<double, double> outcome = benchmark_reduction(dimension);
        cout << "dimension: " << dimension << " \t " << outcome.first << " sec\t" << outcome.second << endl;
    }
    return 0;
}

