// Template function for conditional vector operations
template<bool Condition>
void perform_vector_calc()
{
    float output_arr[4] = {2.0f, 2.0f, 2.0f, 2.0f};
    float input_arr[4]  = {3.0f, 5.0f, 7.0f, 9.0f};
    float* out_ptr = output_arr;
    float* in_ptr  = input_arr;

    asm volatile (
        "vld1.32    {q2}, [%[input]]   \n"
        "vld1.32    {q3}, [%[output]]  \n"
        "vadd.f32   q2, q2, q3         \n"
        "vadd.f32   q2, q2, q3         \n"

        // Branch based on condition flag
        "start_check: \n"
        "cmp %[cond], #1 \n"
        "beq apply_extra \n"
        "b skip_extra \n"
        "apply_extra: \n"
        "vadd.f32   q2, q2, q3         \n"
        "skip_extra: \n"

        "vst1.32    {q2}, [%[output]]  \n"
        : [input]"+r"(in_ptr),
          [output]"+r"(out_ptr)
        : [cond]"r"(Condition)
        : "q2", "q3", "q4", "q5", "memory"
    );

    for (int idx = 0; idx < 4; ++idx)
    {
        std::cout << output_arr[idx] << ", ";
    }
    std::cout << std::endl;
}

