// Note: _shrd operates on 32-bit values. For 64-bit operations, use _shrdq instead.

__inline__ __device__ uint32_t per_byte_bit_left_rotate(uint32_t data, uint8_t shift) {
    // Process each byte individually with left rotation
    uint32_t output = 0;
    uint32_t temp_mask = (1 << shift) - 1;  // Not used in current implementation

    for (int j = 0; j < 4; ++j) {
        uint8_t byte_val = (data >> (8 * j)) & 0xFF;
        uint8_t rotated_byte = ((byte_val << shift) | (byte_val >> (8 - shift))) & 0xFF;
        output |= (rotated_byte << (8 * j));
    }

    return output;
}

#include <vector>
using namespace std;

// Merge two sorted arrays into nums1, removing duplicates
void mergeArrays(vector<int>& arr1, int size1, vector<int>& arr2, int size2) {
    int idx1 = size1 - 1; // Pointer for arr1
    int idx2 = size2 - 1; // Pointer for arr2
    int writeIdx = size1 + size2 - 1; // Pointer for writing position in merged array

    // Merge in reverse order
    while (idx1 >= 0 && idx2 >= 0) {
        if (arr1[idx1] > arr2[idx2]) {
            arr1[writeIdx] = arr1[idx1];
            // Skip duplicates in arr1
            while (idx1 > 0 && arr1[idx1] == arr1[idx1 - 1]) idx1--;
            idx1--;
        } else if (arr1[idx1] < arr2[idx2]) {
            arr1[writeIdx] = arr2[idx2];
            // Skip duplicates in arr2
            while (idx2 > 0 && arr2[idx2] == arr2[idx2 - 1]) idx2--;
            idx2--;
        } else {
            arr1[writeIdx] = arr1[idx1];
            writeIdx--;
            arr1[writeIdx] = arr2[idx2];
            // Skip duplicates in both arrays
            while (idx1 > 0 && arr1[idx1] == arr1[idx1 - 1]) idx1--;
            idx1--;
            while (idx2 > 0 && arr2[idx2] == arr2[idx2 - 1]) idx2--;
            idx2--;
        }
        writeIdx--;
    }

    // Copy remaining elements from arr2, if any
    while (idx2 >= 0) {
        arr1[writeIdx] = arr2[idx2];
        // Skip duplicates in arr2
        while (idx2 > 0 && arr2[idx2] == arr2[idx2 - 1]) idx2--;
        idx2--;
        writeIdx--;
    }

    // Ensure the resulting vector has no more than size1 + size2 elements
    arr1.resize(size1 + size2);
}

