int main() {
    vector<int> arr1 = {1, 2, 3, 0, 0, 0};
    int len1 = 3;
    vector<int> arr2 = {2, 5, 6};
    int len2 = 3;
    mergeArrays(arr1, len1, arr2, len2);
    for (int val : arr1) {
        cout << val << " ";
    }
    return 0;
}

