// Computes the factorial of a non-negative integer
long long computeFactorial(int value) {
    if (value < 0) {
        throw std::invalid_argument("Factorial is not defined for negative numbers");
    }
    if (value == 0 || value == 1) {
        return 1;
    }
    return value * computeFactorial(value - 1);
}

// Validates the factorial computation
void validateFactorial() {
    assert(computeFactorial(0) == 1);
    assert(computeFactorial(1) == 1);
    assert(computeFactorial(5) == 120);
    assert(computeFactorial(10) == 3628800);
    std::cout << "All validation checks passed successfully." << std::endl;
}

int main() {
    try {
        validateFactorial();
    } catch (const std::exception& err) {
        std::cerr << "Exception: " << err.what() << std::endl;
    }
    return 0;
}

