   // Perform matrix multiplication on CPU: C = A * B
   void matrixMultiplyCPU(float* inputMatrix1, float* inputMatrix2, float* outputMatrix, int dimension) {
       for (int row = 0; row < dimension; row++) {
           for (int col = 0; col < dimension; col++) {
               float accumulator = 0.0f;
               for (int k = 0; k < dimension; k++) {
                   accumulator += inputMatrix1[row * dimension + k] * inputMatrix2[k * dimension + col];
               }
               outputMatrix[row * dimension + col] = accumulator;
           }
       }
   }

   int main() {
       int size = 1024;
       std::vector<float> matrixA(size * size, 1.0f);
       std::vector<float> matrixB(size * size, 1.0f);
       std::vector<float> resultMatrix(size * size, 0.0f);

       auto startTime = std::chrono::high_resolution_clock::now();
       matrixMultiplyCPU(matrixA.data(), matrixB.data(), resultMatrix.data(), size);
       auto endTime = std::chrono::high_resolution_clock::now();

       std::chrono::duration<double> elapsed = endTime - startTime;
       std::cout << "CPU Execution Time: " << elapsed.count() << " seconds" << std::endl;

       return 0;
   }

