#include <SFML/Graphics.hpp>
#include <SFML/Window.hpp>
#include <SFML/System.hpp>

const int SCREEN_X = 800;
const int SCREEN_Y = 600;
const float PADDLE_VEL = 5.0f;
const float BALL_SIZE = 10.0f;
const float BALL_VEL = 3.0f;

class Racket {
public:
    sf::RectangleShape rect;
    float velocity;

    Racket(float x, float y, float width, float height, float v) {
        rect.setPosition(x, y);
        rect.setSize({width, height});
        rect.setFillColor(sf::Color::White);
        velocity = v;
    }

    void goUp() {
        sf::Vector2f pos = rect.getPosition();
        if (pos.y > 0) {
            rect.move(0, -velocity);
        }
    }

    void goDown() {
        sf::Vector2f pos = rect.getPosition();
        if (pos.y + rect.getSize().y < SCREEN_Y) {
            rect.move(0, velocity);
        }
    }
};

class Sphere {
public:
    sf::CircleShape form;
    sf::Vector2f motion;
    float velocity;

    Sphere(float x, float y, float r) {
        form.setPosition(x, y);
        form.setRadius(r);
        form.setFillColor(sf::Color::White);
        motion = {1.0f, 1.0f};
        velocity = BALL_VEL;
    }

    void refresh() {
        sf::Vector2f pos = form.getPosition();
        pos += motion * velocity;
        if (pos.x <= 0 || pos.x + 2 * BALL_SIZE >= SCREEN_X) {
            motion.x = -motion.x;
        }
        if (pos.y <= 0 || pos.y + 2 * BALL_SIZE >= SCREEN_Y) {
            motion.y = -motion.y;
        }
        form.setPosition(pos);
    }
};

int main() {
    sf::RenderWindow display(sf::VideoMode(SCREEN_X, SCREEN_Y), "Pong");

    Racket leftRacket(50, SCREEN_Y / 2 - 50, 20, 100, PADDLE_VEL);
    Racket rightRacket(SCREEN_X - 70, SCREEN_Y / 2 - 50, 20, 100, PADDLE_VEL);
    Sphere ball(SCREEN_X / 2 - BALL_SIZE, SCREEN_Y / 2 - BALL_SIZE, BALL_SIZE);

    while (display.isOpen()) {
        sf::Event action;
        while (display.pollEvent(action)) {
            if (action.type == sf::Event::Closed)
                display.close();
        }

        if (sf::Keyboard::isKeyPressed(sf::Keyboard::W)) leftRacket.goUp();
        if (sf::Keyboard::isKeyPressed(sf::Keyboard::S)) leftRacket.goDown();
        // Simple AI for the right paddle
        if (ball.form.getPosition().y > rightRacket.rect.getPosition().y + 50) rightRacket.goDown();
        if (ball.form.getPosition().y < rightRacket.rect.getPosition().y + 50) rightRacket.goUp();

        ball.refresh();

        display.clear(sf::Color::Black);
        display.draw(leftRacket.rect);
        display.draw(rightRacket.rect);
        display.draw(ball.form);
        display.display();
    }

    return 0;
}

