#include <string>

// Recursive helper function to reconstruct and print the LCS
void displayLCS(const std::string& str1, const std::string& str2, int len1, int len2, std::vector<std::vector<int>>& direction) {
    if (len1 == 0 || len2 == 0) return;

    if (direction[len1][len2] == 1) {  // Characters match
        displayLCS(str1, str2, len1 - 1, len2 - 1, direction);
        std::cout << str1[len1 - 1];
    } else if (direction[len1][len2] == 2) {  // Move up
        displayLCS(str1, str2, len1 - 1, len2, direction);
    } else {  // Move left
        displayLCS(str1, str2, len1, len2 - 1, direction);
    }
}

std::string computeLCS(const std::string& firstString, const std::string& secondString) {
    int length1 = firstString.size();
    int length2 = secondString.size();

    // DP table for lengths of LCS
    std::vector<std::vector<int>> dpTable(length1 + 1, std::vector<int>(length2 + 1, 0));
    // Table to track direction: 1=diagonal, 2=up, 3=left
    std::vector<std::vector<int>> dirTable(length1 + 1, std::vector<int>(length2 + 1, 0));

    // Fill the DP tables
    for (int i = 1; i <= length1; ++i) {
        for (int j = 1; j <= length2; ++j) {
            if (firstString[i - 1] == secondString[j - 1]) {
                dpTable[i][j] = dpTable[i - 1][j - 1] + 1;
                dirTable[i][j] = 1;  // Diagonal move (match)
            } else if (dpTable[i - 1][j] >= dpTable[i][j - 1]) {
                dpTable[i][j] = dpTable[i - 1][j];
                dirTable[i][j] = 2;  // Up move
            } else {
                dpTable[i][j] = dpTable[i][j - 1];
                dirTable[i][j] = 3;  // Left move
            }
        }
    }

    std::cout << "Longest Common Subsequence: ";
    displayLCS(firstString, secondString, length1, length2, dirTable);
    std::cout << std::endl;

    return firstString;  // Return one of the input strings
}

int main() {
    std::string input1 = "ABCBDAB";
    std::string input2 = "BDCAB";
    computeLCS(input1, input2);
    return 0;
}

