#include <vector>
#include <algorithm>
#include <random>
#include <cmath>
#include <limits>

// Define a city as a pair of coordinates
struct Location {
    int x, y;
};

// Calculate the Euclidean distance between two cities
double euclidean_distance(const Location& a, const Location& b) {
    return std::sqrt(std::pow(a.x - b.x, 2) + std::pow(a.y - b.y, 2));
}

// Calculate the total distance of a route
double path_length(const std::vector<Location>& locations, const std::vector<int>& path) {
    double total = 0.0;
    for (size_t i = 0; i < path.size(); ++i) {
        total += euclidean_distance(locations[path[i]], locations[path[(i + 1) % path.size()]]);
    }
    return total;
}

// Generate a random route
std::vector<int> create_random_path(size_t num_locations) {
    std::vector<int> path(num_locations);
    for (size_t i = 0; i < num_locations; ++i) {
        path[i] = static_cast<int>(i);
    }
    std::random_shuffle(path.begin(), path.end());
    return path;
}

// Ordered crossover
std::vector<int> ordered_crossover(const std::vector<int>& parent_a, const std::vector<int>& parent_b) {
    size_t start_idx = std::rand() % parent_a.size();
    size_t end_idx = std::rand() % parent_a.size();
    if (start_idx > end_idx) std::swap(start_idx, end_idx);

    std::vector<int> offspring(parent_a.size(), -1);
    for (size_t i = start_idx; i <= end_idx; ++i) {
        offspring[i] = parent_a[i];
    }

    size_t insert_pos = (end_idx + 1) % parent_a.size();
    for (size_t i = 0; i < parent_b.size(); ++i) {
        if (std::find(offspring.begin(), offspring.end(), parent_b[i]) == offspring.end()) {
            offspring[insert_pos] = parent_b[i];
            insert_pos = (insert_pos + 1) % parent_a.size();
        }
    }
    return offspring;
}

// Mutation: swap two cities in the route
void apply_mutation(std::vector<int>& path, double mutation_probability) {
    for (size_t i = 0; i < path.size(); ++i) {
        if (static_cast<double>(std::rand()) / RAND_MAX < mutation_probability) {
            size_t j = std::rand() % path.size();
            std::swap(path[i], path[j]);
        }
    }
}

// Selection: tournament selection
std::vector<int> tournament_select(const std::vector<std::vector<int>>& population, const std::vector<Location>& locations) {
    size_t tournament_participants = 5;
    std::vector<int> champion = population[0];
    double best_score = path_length(locations, champion);

    for (size_t i = 0; i < tournament_participants; ++i) {
        size_t idx = std::rand() % population.size();
        double score = path_length(locations, population[idx]);
        if (score < best_score) {
            best_score = score;
            champion = population[idx];
        }
    }
    return champion;
}

// Genetic Algorithm
std::vector<int> run_genetic_algorithm(const std::vector<Location>& locations, size_t pop_size, size_t max_generations, double mutation_chance) {
    std::vector<std::vector<int>> current_population(pop_size);
    for (size_t i = 0; i < pop_size; ++i) {
        current_population[i] = create_random_path(locations.size());
    }

    for (size_t gen = 0; gen < max_generations; ++gen) {
        std::vector<std::vector<int>> next_generation(pop_size);

        for (size_t i = 0; i < pop_size; ++i) {
            std::vector<int> p1 = tournament_select(current_population, locations);
            std::vector<int> p2 = tournament_select(current_population, locations);
            std::vector<int> child = ordered_crossover(p1, p2);
            apply_mutation(child, mutation_chance);
            next_generation[i] = child;
        }

        current_population = next_generation;
    }

    std::vector<int> best_solution = current_population[0];
    double best_score = path_length(locations, best_solution);

    for (const auto& sol : current_population) {
        double score = path_length(locations, sol);
        if (score < best_score) {
            best_score = score;
            best_solution = sol;
        }
    }

    return best_solution;
}

int main() {
    std::vector<Location> locations = {
        {0, 0}, {1, 2}, {3, 1}, {5, 2}, {2, 4}, {4, 5}, {6, 3}, {7, 1}, {8, 2}, {9, 4}
    };

    size_t pop_size = 100;
    size_t max_generations = 1000;
    double mutation_chance = 0.01;

    std::vector<int> optimal_path = run_genetic_algorithm(locations, pop_size, max_generations, mutation_chance);

    std::cout << "Optimal Path: ";
    for (int loc : optimal_path) {
        std::cout << loc << " ";
    }
    std::cout << std::endl;

    double optimal_score = path_length(locations, optimal_path);
    std::cout << "Optimal Score (Total Distance): " << optimal_score << std::endl;

    return 0;
}

