// Container to hold native device instances
std::map<long, RFEthernetDetector*> objectRegistry;

// Helper to assign unique identifiers
long createIdentifier() {
    static long nextId = 1001;
    return nextId++;
}

// JNI entry point for object initialization
JNIEXPORT jlong JNICALL Java_RFEthernetDetector_init(JNIEnv *env, jobject instance, jint port) {
    RFEthernetDetector *detector = new RFEthernetDetector(static_cast<WORD>(port));
    long id = createIdentifier();
    objectRegistry[id] = detector;
    return id;
}

// JNI entry point for executing device operations
JNIEXPORT void JNICALL Java_RFEthernetDetector_performAction(JNIEnv *env, jobject instance) {
    jlong id = env->GetLongField(instance, env->GetFieldID(env->GetObjectClass(instance), "nativePtr", "J"));
    RFEthernetDetector *detector = objectRegistry[id];
    detector->executeOperation();
}

// JNI entry point for resource deallocation
JNIEXPORT void JNICALL Java_RFEthernetDetector_release(JNIEnv *env, jobject instance, jlong id) {
    RFEthernetDetector *detector = objectRegistry[id];
    delete detector;
    objectRegistry.erase(id);
}

