#include <Python.h>
#include <iostream>
#include <streambuf>

class PyOutputStreamBuffer : public std::streambuf {
public:
    PyOutputStreamBuffer(PyFileObject* pyFile) : file(pyFile) {
        setp(internalBuffer, internalBuffer + sizeof(internalBuffer) - 1);
    }

protected:
    int overflow(int character) override {
        if (character != EOF) {
            PyFile_WriteString((char*)&character, 1, (PyObject*)file);
        }
        return 0;
    }

    int sync() override {
        PyFile_WriteString(pbase(), pptr() - pbase(), (PyObject*)file);
        pbump(-static_cast<int>(pptr() - pbase()));
        return 0;
    }

private:
    PyFileObject* file;
    char internalBuffer[2048];
};

class PyOutputStream : public std::ostream {
public:
    PyOutputStream(PyFileObject* pyFile) : std::ostream(new PyOutputStreamBuffer(pyFile)) {}

    ~PyOutputStream() {
        delete rdbuf();
    }
};

