  void* Address;
};

struct SVersionedPtrBuffer {
  char storage[2 * sizeof(SVersionedPtr)];
};

SVersionedPtr* AcquireVersionedPointer(SVersionedPtrBuffer& Buffer) {
  const size_t ptr_size = sizeof(SVersionedPtr);
  void* alignedAddr = reinterpret_cast<void*>(reinterpret_cast<std::intptr_t>(&Buffer) + (ptr_size - 1));
