    TimeDuration(int d, int h, int m, int s)
        : seconds_(d * 24 * 3600 + h * 3600 + m * 60 + s) {}

    int GetTotalSeconds() const {
        return seconds_;
    }

private:
    int seconds_;
};

class Timestamp {
public:
    Timestamp(int y, int mon, int day, int hr, int min, int sec)
        : point_(std::chrono::system_clock::from_time_t(std::mktime(&tm_))) {
        tm_.tm_year = y - 1900;
        tm_.tm_mon = mon - 1;
        tm_.tm_mday = day;
        tm_.tm_hour = hr;
        tm_.tm_min = min;
        tm_.tm_sec = sec;
    }

    std::string Format() const {
        std::time_t t = std::chrono::system_clock::to_time_t(point_);
        std::tm* info = std::localtime(&t);
        char buf[80];
        std::strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", info);
        return std::string(buf);
    }

    TimeDuration operator-(const Timestamp& other) const {
        auto dur = point_ - other.point_;
        auto secs = std::chrono::duration_cast<std::chrono::seconds>(dur).count();
        return TimeDuration(0, 0, 0, secs);
    }

private:
    std::chrono::system_clock::time_point point_;
    std::tm tm_;
};

int main() {
    Timestamp current(2023, 10, 1, 12, 0, 0);
    Timestamp future(2023, 10, 2, 14, 30, 0);

    std::cout << "Current: " << current.Format() << std::endl;
    std::cout << "Future: " << future.Format() << std::endl;

    TimeDuration span = future - current;
    std::cout << "Interval in seconds: " << span.GetTotalSeconds() << std::endl;

    return 0;
}

