// Helper function to print an array of EmailAddress
void DisplayEmailAddressArray(SAFEARRAY* pArray)
{
    if (pArray == nullptr)
    {
        std::wcout << L"Array is null" << std::endl;
        return;
    }

    long lowerBound, upperBound;
    SafeArrayGetLBound(pArray, 1, &lowerBound);
    SafeArrayGetUBound(pArray, 1, &upperBound);

    for (long index = lowerBound; index <= upperBound; index++)
    {
        EmailAddress* pEmail = nullptr;
        HRESULT result = SafeArrayGetElement(pArray, &index, &pEmail);
        if (SUCCEEDED(result))
        {
            std::wcout << L"Address: " << pEmail->Address << L", Name: " << pEmail->Name << std::endl;
        }
    }
