int main(int argc, char* argv[]) {
    int index;

    // Allocate memory for arrays of varying sizes
    int* DataBlockA = new int[16384];       // 3 smaller blocks (2^14)
    int* DataBlockB = new int[32768];       //                  (2^15)
    int* DataBlockC = new int[65536];       //                  (2^16)

    for (index = 0; index < 16384; ++index) { DataBlockA[index] = 0; }
    for (index = 0; index < 32768; ++index) { DataBlockB[index] = 0; }
    for (index = 0; index < 65536; ++index) { DataBlockC[index] = 0; }

    int* DataBlockD = new int[16777216];    // 3 larger blocks   (2^24)
    int* DataBlockE = new int[33554432];    //                  (2^25)
    int* DataBlockF = new int[67108864];    //                  (2^26)

    for (index = 0; index < 16777216; ++index) { DataBlockD[index] = 0; }
    for (index = 0; index < 33554432; ++index) { DataBlockE[index] = 0; }
    for (index = 0; index < 67108864; ++index) { DataBlockF[index] = 0; }

    int limit;

    clock_t begin, end;
    cout << "Iterations: "; cin >> limit;

    int counterA = 0, counterB = 0, counterC = 0;
    int counterD = 0, counterE = 0, counterF = 0;

    begin = clock();
    for (index = 0; index < limit; ++index) {
        counterA++;
        counterB++;
        counterC++;
    }
    DataBlockA[1] = counterA;
    DataBlockB[1] = counterB;
    DataBlockC[1] = counterC;
    end = clock();
    cout << "Duration: " << static_cast<float>(end - begin) / CLOCKS_PER_SEC << " seconds.\n";

    begin = clock();
    for (index = 0; index < limit; ++index) {
        counterD++;
        counterE++;
        counterF++;
    }
    DataBlockD[1] = counterD;
    DataBlockE[1] = counterE;
    DataBlockF[1] = counterF;
    end = clock();
    cout << "Duration: " << static_cast<float>(end - begin) / CLOCKS_PER_SEC << " seconds.\n";

    delete[] DataBlockA; DataBlockA = nullptr;
    delete[] DataBlockB; DataBlockB = nullptr;
    delete[] DataBlockC; DataBlockC = nullptr;
    delete[] DataBlockD; DataBlockD = nullptr;
    delete[] DataBlockE; DataBlockE = nullptr;
    delete[] DataBlockF; DataBlockF = nullptr;

    getchar();
    return 0;
}

