class DocumentSelector : public QAndroidActivityResultReceiver {
    Q_OBJECT
public:
    DocumentSelector(QObject *parent = nullptr) : QAndroidActivityResultReceiver(parent) {}

    void selectDocument() {
        QAndroidJniObject intent("android/content/Intent");
        intent.callObjectMethod("setAction", "(Ljava/lang/String;)Landroid/content/Intent;",
                                QAndroidJniObject::fromString("android.intent.action.GET_CONTENT").object());
        intent.callObjectMethod("setType", "(Ljava/lang/String;)Landroid/content/Intent;",
                                QAndroidJniObject::fromString("*/*").object());

        QtAndroid::startActivity(intent.object<jobject>(), 100, this);
    }

    void handleActivityResult(int requestCode, int result, const QAndroidJniObject &resultData) override {
        if (requestCode == 100 && result == -1) {
            QAndroidJniObject uri = resultData.callObjectMethod("getData", "()Landroid/net/Uri;");
            if (uri.isValid()) {
                QAndroidJniObject resolver = QtAndroid::androidActivity().callObjectMethod("getContentResolver", "()Landroid/content/ContentResolver;");
                QAndroidJniObject cursor = resolver.callObjectMethod("query", "(Landroid/net/Uri;[Ljava/lang/String;Ljava/lang/String;[Ljava/lang/String;Ljava/lang/String;)Landroid/database/Cursor;",
                                                                      uri.object<jobject>(), nullptr, nullptr, nullptr, nullptr);

                if (cursor.isValid()) {
                    cursor.callMethod<jboolean>("moveToFirst", "()Z");
                    QAndroidJniObject fieldName = QAndroidJniObject::getStaticObjectField("android/provider/OpenableColumns", "DISPLAY_NAME", "Ljava/lang/String;");
                    jint fieldIndex = cursor.callMethod<jint>("getColumnIndex", "(Ljava/lang/String;)I", fieldName.object<jstring>());
                    QAndroidJniObject documentName = cursor.callObjectMethod("getString", "(I)Ljava/lang/String;", fieldIndex);
                    qDebug() << "Chosen file:" << documentName.toString();
                }
            }
        }
    }
};

