// Load binary file content into a string tensor
static Status LoadFileContent(Env* pEnv, const string& sPath, Tensor* result) {
    uint64 fileSize = 0;
    TF_RETURN_IF_ERROR(pEnv->GetFileSize(sPath, &fileSize));

    string buffer;
    buffer.resize(fileSize);

    std::unique_ptr<RandomAccessFile> fileReader;
    TF_RETURN_IF_ERROR(pEnv->NewRandomAccessFile(sPath, &fileReader));

    StringPiece data;
    TF_RETURN_IF_ERROR(fileReader->Read(0, fileSize, &data, &buffer[0]));

    result->scalar<string>()() = data.as_string();
    return Status::OK();
}

// Read and preprocess an image from file: decode PNG, resize, normalize
Status LoadAndPreprocessImage(const string& imagePath, int targetWidth, int targetHeight,
                              float normalizationMean, float normalizationScale,
                              std::vector<Tensor>* outputTensors) {
    Tensor inputTensor(DT_STRING, TensorShape());
    TF_RETURN_IF_ERROR(LoadFileContent(Env::Default(), imagePath, &inputTensor));

    auto rootScope = Scope::NewRootScope();
    auto inputNode = ops::Placeholder(rootScope.WithOpName("image_input"), DT_STRING);
    std::vector<std::pair<string, Tensor>> feedDict = { {"image_input", inputTensor} };

    auto decodedImage = ops::DecodePng(rootScope.WithOpName("png_decoder"), inputNode, 
                                       ops::DecodePng::Channels(3));
    auto floatImage = ops::Cast(rootScope.WithOpName("type_conversion"), decodedImage, DT_FLOAT);
    auto expanded = ops::ExpandDims(rootScope, floatImage, 0);
    auto resized = ops::ResizeBilinear(rootScope, expanded, 
                                       ops::Const(rootScope.WithOpName("target_size"), { targetHeight, targetWidth }));
    auto normalized = ops::Sub(rootScope, resized, ops::Const(rootScope, normalizationMean));
    auto finalOutput = ops::Div(rootScope.WithOpName("final_preprocess"), normalized, 
                                ops::Const(rootScope, normalizationScale));

    GraphDef graphProto;
    TF_RETURN_IF_ERROR(rootScope.ToGraphDef(&graphProto));

    Session* session;
    TF_RETURN_IF_ERROR(NewSession(SessionOptions(), &session));
    TF_RETURN_IF_ERROR(session->Create(graphProto));
    TF_RETURN_IF_ERROR(session->Run({ feedDict }, { "final_preprocess" }, {}, outputTensors));
    TF_RETURN_IF_ERROR(session->Close());
    delete session;
    return Status::OK();
}

int main(int argc, char* argv[]) {
    tensorflow::port::InitMain(argv[0], &argc, &argv);

    GraphDef modelGraph;
    Status status = ReadBinaryProto(Env::Default(), "models/model_graph.pb", &modelGraph);
    if (!status.ok()) {
        std::cerr << "Failed to load graph: " << status.ToString() << std::endl;
        return -1;
    }
    std::cout << "Model graph loaded successfully\n";

    std::vector<Tensor> preprocessedImages;
    status = LoadAndPreprocessImage("input_image.png", 224, 224, 127.5f, 255.0f, &preprocessedImages);
    if (!status.ok()) {
        std::cerr << "Image preprocessing failed: " << status.ToString() << std::endl;
        return -1;
    }
    std::cout << "Image preprocessing completed\n";

    Session* inferenceSession;
    status = NewSession(SessionOptions(), &inferenceSession);
    if (!status.ok()) {
        std::cerr << "Session creation failed: " << status.ToString() << std::endl;
        return -1;
    }

    status = inferenceSession->Create(modelGraph);
    if (!status.ok()) {
        std::cerr << "Graph creation in session failed: " << status.ToString() << std::endl;
        delete inferenceSession;
        return -1;
    }

    std::vector<Tensor> results;
    status = inferenceSession->Run(
        { { "input_layer", preprocessedImages[0] } }, 
        { "output_layer/Relu" }, 
        {}, 
        &results
    );
    if (!status.ok()) {
        std::cerr << "Inference run failed: " << status.ToString() << std::endl;
        delete inferenceSession;
        return -1;
    }

    // Display inference results
    for (const auto& resultTensor : results) {
        std::cout << "Result shape: " << resultTensor.shape().DebugString() << "\n";
        int printCount = std::min(10, static_cast<int>(resultTensor.NumElements()));
        for (int idx = 0; idx < printCount; ++idx) {
            std::cout << resultTensor.flat<float>()(idx) << " ";
        }
        std::cout << "\n";
    }

    inferenceSession->Close();
    delete inferenceSession;
    return 0;
}

