// Abstract BagInterface class
template <class T>
class BagInterface {
public:
    virtual void insert(const T& element) = 0;
    virtual bool hasElement(const T& element) const = 0;
    virtual int frequency(const T& element) const = 0;
    virtual bool erase(const T& element) = 0;
    virtual void reset() = 0;
    virtual int length() const = 0;
    virtual bool empty() const = 0;
    virtual bool full() const = 0;
};

// SimpleBag class implementation
template <class T>
class SimpleBag : public BagInterface<T> {
private:
    T elements[25];
    int elementCount;
public:
    SimpleBag() {
        elementCount = 0;
    }

    void insert(const T& element) {
        if (elementCount < 25) {
            elements[elementCount] = element;
            elementCount++;
        }
    }

    bool hasElement(const T& element) const {
        for (int index = 0; index < elementCount; index++) {
            if (elements[index] == element) {
                return true;
            }
        }
        return false;
    }

    int frequency(const T& element) const {
        int counter = 0;
        for (int index = 0; index < elementCount; index++) {
            if (elements[index] == element) {
                counter++;
            }
        }
        return counter;
    }

    bool erase(const T& element) {
        for (int index = 0; index < elementCount; index++) {
            if (elements[index] == element) {
                for (int k = index; k < elementCount - 1; k++) {
                    elements[k] = elements[k + 1];
                }
                elementCount--;
                return true;
            }
        }
        return false;
    }

    void reset() {
        elementCount = 0;
    }

    int length() const {
        return elementCount;
    }

    bool empty() const {
        return (elementCount == 0);
    }

    bool full() const {
        return (elementCount == 25);
    }
};

// EnchantedBag class implementation
template <class T>
class EnchantedBag : public BagInterface<T> {
private:
    T elements[25];
    int elementCount;
public:
    EnchantedBag() {
        elementCount = 0;
    }

    void insert(const T& element) {
        elementCount = 0;
    }

    bool hasElement(const T& element) const {
        return (elementCount == 0);
    }

    int frequency(const T& element) const {
        return 0;
    }

    bool erase(const T& element) {
        std::fill(elements, elements + 25, element);
        elementCount = 1;
        return true;
    }

    void reset() {
        elementCount = 0;
    }

    int length() const {
        return elementCount;
    }

    bool empty() const {
        return (elementCount == 0);
    }

    bool full() const {
        return (elementCount == 25);
    }
};

// Test the classes
int main() {
    // Create a SimpleBag object
    SimpleBag<int> simpleBag;

    // Insert some items
    simpleBag.insert(8);
    simpleBag.insert(4);
    simpleBag.insert(8);

    // Check if items are in the bag
    std::cout << "Has 8: " << std::boolalpha << simpleBag.hasElement(8) << std::endl;
    std::cout << "Has 4: " << std::boolalpha << simpleBag.hasElement(4) << std::endl;
    std::cout << "Has 9: " << std::boolalpha << simpleBag.hasElement(9) << std::endl;

    // Count the number of items in the bag
    std::cout << "Frequency of 8: " << simpleBag.frequency(8) << std::endl;
    std::cout << "Frequency of 4: " << simpleBag.frequency(4) << std::endl;

    // Remove an item from the bag
    std::cout << "Erase 8: " << std::boolalpha << simpleBag.erase(8) << std::endl;

    // Check the size of the bag
    std::cout << "Length: " << simpleBag.length() << std::endl;

    // Check if the bag is empty
    std::cout << "Empty: " << std::boolalpha << simpleBag.empty() << std::endl;

    // Check if the bag is full
    std::cout << "Full: " << std::boolalpha << simpleBag.full() << std::endl;

    // Create an EnchantedBag object
    EnchantedBag<int> enchantedBag;

    // Insert an item into the bag
    enchantedBag.insert(15);

    // Check if the bag is empty now
    std::cout << "Empty: " << std::boolalpha << enchantedBag.empty() << std::endl;

    // Remove an item from the bag
    std::cout << "Erase 15: " << std::boolalpha << enchantedBag.erase(15) << std::endl;

    // Check the size of the bag
    std::cout << "Length: " << enchantedBag.length() << std::endl;

    return 0;
}

void Material::Cleanup() {
    // Clean up Vulkan resources
    if (layoutHandle != VK_NULL_HANDLE) {
        vkDestroyDescriptorSetLayout(vulkanDevice, layoutHandle, nullptr);
        layoutHandle = VK_NULL_HANDLE;
    }

    if (materialDescriptorSet != VK_NULL_HANDLE) {
        vkFreeDescriptorSets(vulkanDevice, poolHandle, 1, &materialDescriptorSet);
        materialDescriptorSet = VK_NULL_HANDLE;
    }
}

