// Perform binary search on a sorted vector
int findElement(const std::vector<int>& data, int value) {
    int start = 0;
    int end = data.size() - 1;

    while (start <= end) {
        int middle = start + (end - start) / 2;

        if (data[middle] == value) {
            return middle;
        } else if (data[middle] < value) {
            start = middle + 1;
        } else {
            end = middle - 1;
        }
    }

    return -1; // Element not found
}

#include <memory>
#include <cassert>

template <typename Type>
class ExclusiveHolder {
private:
    std::unique_ptr<Type> owner;

public:
    explicit ExclusiveHolder(Type* rawPtr) : owner(rawPtr) {}

    // Transfer-only semantics
    ExclusiveHolder(ExclusiveHolder&& source) noexcept : owner(std::move(source.owner)) {}
    ExclusiveHolder& operator=(ExclusiveHolder&& source) noexcept {
        owner = std::move(source.owner);
        return *this;
    }

    // Prohibit copying
    ExclusiveHolder(const ExclusiveHolder&) = delete;
    ExclusiveHolder& operator=(const ExclusiveHolder&) = delete;

    // Observation methods
    Type* access() const { return owner.get(); }
    Type& dereference() const { return *owner; }
    Type* arrowAccess() const { return owner.get(); }

    // Shared access with lifetime safety check
    std::shared_ptr<Type> share() {
        assert(owner);
        return std::shared_ptr<Type>(owner.get(), [](Type*) {}); // Empty deleter
    }
};

