double LowerBuffer[];
double UpperBuffer[];

input int Periods = 150; // Number of bars to analyze for support and resistance levels

void OnInit()
  {
   SetIndexBuffer(0,LowerBuffer,INDICATOR_DATA);
   SetIndexBuffer(1,UpperBuffer,INDICATOR_DATA);
   PlotIndexSetInteger(0,PLOT_DRAW_BEGIN, Periods);
   PlotIndexSetInteger(1,PLOT_DRAW_BEGIN, Periods);

   PlotIndexSetInteger(0,PLOT_LINE_COLOR, clrBlue);  // Support line color
   PlotIndexSetInteger(1,PLOT_LINE_COLOR, clrOrange);    // Resistance line color

   SetIndexStyle(0,DRAW_LINE, STYLE_SOLID, 2, clrBlue);
   SetIndexStyle(1,DRAW_LINE, STYLE_SOLID, 2, clrOrange);
  }

int OnCalculate(const int total_bars, const int prev_calculated, const datetime &times[], const double &opens[], const double &highs[], const double &lows[], const double &closes[], const long &volumes[], const long &tick_volumes[], const int &spreads[])
  {
   if(total_bars < Periods)
      return(0);

   ArraySetAsSeries(LowerBuffer,true);
   ArraySetAsSeries(UpperBuffer,true);

   for(int index = Periods; index < total_bars && !IsStopped(); index++)
     {
      // Find the minimum low in the lookback period
      double min_low = lows[index];
      for(int k = 1; k < Periods; k++)
        {
         if(lows[index-k] < min_low)
            min_low = lows[index-k];
        }
      LowerBuffer[index] = min_low;

      // Find the maximum high in the lookback period
      double max_high = highs[index];
      for(int k = 1; k < Periods; k++)
        {
         if(highs[index-k] > max_high)
            max_high = highs[index-k];
        }
      UpperBuffer[index] = max_high;
     }

   return total_bars;
  }

#include <arm_neon.h>

// Perform byte-swapping on array of 32-bit values using NEON
void process_data(uint32_t *input, uint32_t *output) {
    // Load 4 uint32_t values as uint8x16_t vector
    uint8x16_t data_vector = vreinterpretq_u8_u32(vld1q_u32(input));

    // Reverse bytes within each 32-bit element
    uint8x16_t reversed = vrev32q_u8(data_vector);

    // Store result back as uint32_t vector
    vst1q_u32(output, vreinterpretq_u32_u8(reversed));
}

