using namespace std;

// Deterministic finite automaton implementation
struct Automaton {
    int start_state;
    set<int> final_states;
    unordered_map<int, unordered_map<char, int>> delta;

    bool validate(const string& sequence) {
        int state = start_state;
        for (char ch : sequence) {
            if (delta[state].find(ch) == delta[state].end()) {
                return false; // Transition undefined for current symbol
            }
            state = delta[state][ch];
        }
        return final_states.find(state) != final_states.end();
    }
};

