struct ConvertedResult {
    std::string city;
    double tempF;
};

double correctElevationEffect(double celsius, double elevation) {
    return celsius - 0.0065 * elevation;
}

double adjustTimeFactor(double celsius, int hour) {
    if (hour >= 6 && hour < 12) {
        return celsius - 1;
    } else if (hour >= 18 && hour < 24) {
        return celsius - 2;
    }
    return celsius;
}

double adjustSeasonalFactor(double celsius, const std::string& season) {
    if (season == "summer") {
        return celsius + 2;
    } else if (season == "winter") {
        return celsius - 2;
    }
    return celsius;
}

double convertTo Fahrenheit(double celsius) {
    return celsius * 9/5 + 32;
}

std::vector<ConvertedResult> processTemperatureData(const std::vector<WeatherReading>& readings) {
    std::vector<ConvertedResult> processed;
    for (const auto& item : readings) {
        double tempC = item.tempC;
        double elev = item.elevation;
        int hour = item.timeOfDay;
        std::string season = item.period;

        double adjustedC = correctElevationEffect(tempC, elev);
        double timeAdjustedC = adjustTimeFactor(adjustedC, hour);
        double finalC = adjustSeasonalFactor(timeAdjustedC, season);

        double tempF = convertTo Fahrenheit(finalC);
        processed.push_back({item.city, tempF});
    }
    return processed;
}

void writeJsonOutput(const std::vector<ConvertedResult>& output) {
    json j = output;
    std::ofstream outFile("output.json");
    outFile << std::setw(4) << j << std::endl;
}

void writeCsvOutput(const std::vector<ConvertedResult>& output) {
    std::ofstream outFile("output.csv");
    outFile << "city,tempF\n";
    for (const auto& entry : output) {
        outFile << entry.city << "," << entry.tempF << "\n";
    }
}

int main() {
    std::vector<WeatherReading> input = {
        {"Chicago", 18, 20, 14, "summer"},
        {"Miami", 30, 5, 20, "winter"}
    };

    std::vector<ConvertedResult> processedData = processTemperatureData(input);
    writeJsonOutput(processedData);
    writeCsvOutput(processedData);

    return 0;
}

