// Function to find two indices whose values sum to the target
std::vector<int> findPair(std::vector<int>& data, int goal) {
    std::unordered_map<int, int> valueToIndex;

    for (int index = 0; index < data.size(); ++index) {
        int needed = goal - data[index];

        if (valueToIndex.find(needed) != valueToIndex.end()) {
            return {valueToIndex[needed], index};
        }

        valueToIndex[data[index]] = index;
    }

    return {};
}

