// Determine whether a given integer is a prime number
bool checkPrime(int value) {
    if (value <= 1) return false;
    if (value <= 3) return true;
    if (value % 2 == 0 || value % 3 == 0) return false;
    for (int j = 5; j * j <= value; j += 6) {
        if (value % j == 0 || value % (j + 2) == 0) return false;
    }
    return true;
}

// Compute the sum of all digits in a positive integer
int digitSum(int value) {
    int result = 0;
    while (value > 0) {
        result += value % 10;
        value /= 10;
    }
    return result;
}

// Identify the largest prime in the input vector and return the sum of its digits
int maxPrimeDigitSum(const std::vector<int>& numbers) {
    int maxPrime = -1;
    for (int val : numbers) {
        if (checkPrime(val) && val > maxPrime) {
            maxPrime = val;
        }
    }
    return maxPrime != -1 ? digitSum(maxPrime) : 0;
}

