class StaffMember {
public:
    // Constructor
    StaffMember(int identifier = 0, const std::string& fullName = "", const std::string& role = "", double wage = 0.0)
        : identifier(identifier), fullName(fullName), role(role), wage(wage) {}

    // Destructor
    ~StaffMember() {}

    // Getters
    int getIdentifier() const { return identifier; }
    std::string getFullName() const { return fullName; }
    std::string getRole() const { return role; }
    double getWage() const { return wage; }

    // Setters
    void setIdentifier(int identifier) { this->identifier = identifier; }
    void setFullName(const std::string& fullName) { this->fullName = fullName; }
    void setRole(const std::string& role) { this->role = role; }
    void setWage(double wage) { this->wage = wage; }

    // Method to load data from the database
    static std::vector<std::shared_ptr<StaffMember>> fetchStaffFromDatabase(const std::string& databasePath) {
        sqlite3* db;
        int status = sqlite3_open(databasePath.c_str(), &db);
        if (status) {
            std::cerr << "Unable to open database: " << sqlite3_errmsg(db) << std::endl;
            return {};
        }

        std::vector<std::shared_ptr<StaffMember>> staffList;
        std::string query = "SELECT id, name, position, salary FROM employees;";

        sqlite3_stmt* statement;
        status = sqlite3_prepare_v2(db, query.c_str(), -1, &statement, nullptr);
        if (status != SQLITE_OK) {
            std::cerr << "Statement preparation failed: " << sqlite3_errmsg(db) << std::endl;
            sqlite3_close(db);
            return {};
        }

        while (sqlite3_step(statement) == SQLITE_ROW) {
            int identifier = sqlite3_column_int(statement, 0);
            std::string fullName = reinterpret_cast<const char*>(sqlite3_column_text(statement, 1));
            std::string role = reinterpret_cast<const char*>(sqlite3_column_text(statement, 2));
            double wage = sqlite3_column_double(statement, 3);

            staffList.push_back(std::make_shared<StaffMember>(identifier, fullName, role, wage));
        }

        sqlite3_finalize(statement);
        sqlite3_close(db);

        return staffList;
    }

private:
    int identifier;
    std::string fullName;
    std::string role;
    double wage;
};

