// Function pointer types for original API functions
typedef HMODULE (WINAPI *LoadLibFunc)(LPCSTR);
typedef FARPROC (WINAPI *GetProcAddrFunc)(HMODULE, LPCSTR);

// Store original function addresses
LoadLibFunc orig_LoadLibrary = (LoadLibFunc)GetProcAddress(GetModuleHandleA("kernel32.dll"), "LoadLibraryA");
GetProcAddrFunc orig_GetProcAddress = (GetProcAddrFunc)GetProcAddress(GetModuleHandleA("kernel32.dll"), "GetProcAddress");

// Hooked LoadLibraryA implementation
HMODULE WINAPI HookedLoadLibraryA(LPCSTR libFileName)
{
    HMODULE moduleHandle = orig_LoadLibrary(libFileName);
    if (moduleHandle)
    {
        OutputDebugStringA("Library loaded: ");
        OutputDebugStringA(libFileName);
        OutputDebugStringA("\n");
    }
    return moduleHandle;
}

// Hooked GetProcAddress implementation
FARPROC WINAPI HookedGetProcAddress(HMODULE hModule, LPCSTR procName)
{
    FARPROC address = orig_GetProcAddress(hModule, procName);
    if (address)
    {
        OutputDebugStringA("Function resolved: ");
        OutputDebugStringA(procName);
        OutputDebugStringA("\n");
    }
    return address;
}

// DLL entry point
BOOL APIENTRY DllMain(HMODULE hModule, DWORD reason, LPVOID lpReserved)
{
    switch (reason)
    {
    case DLL_PROCESS_ATTACH:
        DetourTransactionBegin();
        DetourUpdateThread(GetCurrentThread());
        DetourAttach(&(PVOID&)orig_LoadLibrary, HookedLoadLibraryA);
        DetourAttach(&(PVOID&)orig_GetProcAddress, HookedGetProcAddress);
        DetourTransactionCommit();
        break;

    case DLL_PROCESS_DETACH:
        DetourTransactionBegin();
        DetourUpdateThread(GetCurrentThread());
        DetourDetach(&(PVOID&)orig_LoadLibrary, HookedLoadLibraryA);
        DetourDetach(&(PVOID&)orig_GetProcAddress, HookedGetProcAddress);
        DetourTransactionCommit();
        break;
    }
    return TRUE;
}

