namespace py = pybind11;

class ThreeDArray {
public:
    std::vector<std::vector<std::vector<double>>> storage;
    int dim_x, dim_y, dim_z;

    // Constructor
    ThreeDArray(int x, int y, int z) : dim_x(x), dim_y(y), dim_z(z) {
        storage.resize(dim_x, std::vector<std::vector<double>>(dim_y, std::vector<double>(dim_z, 0.0)));
    }

    // Overloaded operator() for element access
    double& at(int i, int j, int k) {
        return storage[i][j][k];
    }

    // Function to convert ThreeDArray to a NumPy array
    py::array_t<double> to_numpy_array() const {
        py::array_t<double> np_arr({dim_x, dim_y, dim_z});
        auto view = np_arr.mutable_unchecked<3>();
        for (size_t idx = 0; idx < dim_x; ++idx) {
            for (size_t idy = 0; idy < dim_y; ++idy) {
                for (size_t idz = 0; idz < dim_z; ++idz) {
                    view(idx, idy, idz) = storage[idx][idy][idz];
                }
            }
        }
        return np_arr;
    }

    // Function to convert a NumPy array to ThreeDArray
    static ThreeDArray from_numpy_array(const py::array_t<double>& np_arr) {
        auto view = np_arr.unchecked<3>();
        ThreeDArray arr(view.shape(0), view.shape(1), view.shape(2));
        for (size_t idx = 0; idx < view.shape(0); ++idx) {
            for (size_t idy = 0; idy < view.shape(1); ++idy) {
                for (size_t idz = 0; idz < view.shape(2); ++idz) {
                    arr.storage[idx][idy][idz] = view(idx, idy, idz);
                }
            }
        }
        return arr;
    }
};

