using namespace std;

// Determine whether an integer is prime
bool checkPrime(int value) {
    if (value <= 1)
        return false;

    if (value == 2)
        return true;

    if (value % 2 == 0)
        return false;

    for (int j = 3; j <= sqrt(value); j += 2) {
        if (value % j == 0)
            return false;
    }

    return true;
}

// Locate the prime with the greatest digit count in the collection
int getLongestPrime(vector<int> numbers) {
    int maxLen = 0;
    int bestPrime = 0;

    for (int idx = 0; idx < numbers.size(); idx++) {
        if (checkPrime(numbers[idx])) {
            int count = 0;
            int temp = numbers[idx];
            while (temp != 0) {
                count++;
                temp /= 10;
            }

            if (count > maxLen) {
                maxLen = count;
                bestPrime = numbers[idx];
            }
        }
    }

    if (bestPrime == 0)
        return -1; // Indicates no primes were found

    return bestPrime;
}

int main() {
