#include <complex>
#include <cmath>
#include <vector>

// Function to find the roots of a cubic equation: px^3 + qx^2 + rx + s = 0
std::vector<std::complex<double>> findCubicRoots(double p, double q, double r, double s) {
    if (p == 0.0) {
        throw std::invalid_argument("Leading coefficient 'p' cannot be zero in a cubic equation.");
    }

    // Normalize coefficients by dividing through by p
    double q_div_p = q / p;
    double r_div_p = r / p;
    double s_div_p = s / p;

    // Transform to depressed cubic form: t^3 + mt + n = 0
    double m = r_div_p - (q_div_p * q_div_p) / 3.0;
    double n = s_div_p + (2.0 * q_div_p * q_div_p * q_div_p) / 27.0 - (q_div_p * r_div_p) / 3.0;

    // Compute discriminant
    double delta = (n * n) / 4.0 + (m * m * m) / 27.0;

    std::vector<std::complex<double>> solutions;

    if (delta > 0) {
        // One real root and two complex conjugate roots
        double cube_u = cbrt(-n / 2.0 + sqrt(delta));
        double cube_v = cbrt(-n / 2.0 - sqrt(delta));
        double real_solution = cube_u + cube_v - q_div_p / 3.0;
        solutions.push_back(real_solution);

        std::complex<double> complex_sol1 = std::complex<double>(-0.5 * (cube_u + cube_v) - q_div_p / 3.0, sqrt(3.0) * 0.5 * (cube_u - cube_v));
        std::complex<double> complex_sol2 = std::complex<double>(-0.5 * (cube_u + cube_v) - q_div_p / 3.0, -sqrt(3.0) * 0.5 * (cube_u - cube_v));
        solutions.push_back(complex_sol1);
        solutions.push_back(complex_sol2);
    } else if (delta == 0.0) {
        // All roots real, at least two equal
        double cube_val = cbrt(-n / 2.0);
        double sol1 = 2.0 * cube_val - q_div_p / 3.0;
        double sol2 = -cube_val - q_div_p / 3.0;
        solutions.push_back(sol1);
        solutions.push_back(sol2);
        solutions.push_back(sol2);
    } else {
        // Three distinct real roots
        double radius = sqrt(-m / 3.0);
        double angle = acos(-n / (2.0 * radius * radius * radius));
        double factor = 2.0 * radius;

        double root_a = factor * cos(angle / 3.0) - q_div_p / 3.0;
        double root_b = factor * cos((angle + 2.0 * M_PI) / 3.0) - q_div_p / 3.0;
        double root_c = factor * cos((angle + 4.0 * M_PI) / 3.0) - q_div_p / 3.0;

        solutions.push_back(root_a);
        solutions.push_back(root_b);
        solutions.push_back(root_c);
    }

    return solutions;
}

int main() {
    double p = 1.0, q = -6.0, r = 11.0, s = -6.0; // Coefficients for x^3 - 6x^2 + 11x - 6 = 0
    std::vector<std::complex<double>> roots = findCubicRoots(p, q, r, s);

    std::cout << "The solutions to the cubic equation are:" << std::endl;
    for (const auto& solution : roots) {
        std::cout << solution << std::endl;
    }

    return 0;
}

