template<std::size_t BitCount>
struct big_int;

template <std::size_t BitCount, std::size_t Words, bool IsFinal = Words == big_int<BitCount>::word_count>
struct add_helper {
    static inline void perform(big_int<BitCount> &lhs, const big_int<BitCount> &rhs) {
        add_helper<BitCount, big_int<BitCount>::word_count>::perform(lhs, rhs);
    }
};

template<std::size_t BitCount, std::size_t Words>
struct add_helper<BitCount, Words, 1> {
    static inline void perform(big_int<BitCount> &lhs, const big_int<BitCount> &rhs) {
        uint64_t carry = 0;
        for (std::size_t idx = 0; idx < Words; ++idx) {
            uint64_t result = lhs[idx] + rhs[idx] + carry;
            lhs[idx] = result;
            carry = (result < lhs[idx]) ? 1 : 0;
        }
    }
};

template<std::size_t BitCount, std::size_t Words>
struct add_helper<BitCount, Words, 0> {
    static inline void perform(big_int<BitCount> &lhs, const big_int<BitCount> &rhs) {
        uint64_t carry = 0;
        for (std::size_t idx = 0; idx < Words; ++idx) {
            uint64_t result = lhs[idx] + rhs[idx] + carry;
            lhs[idx] = result;
            carry = (result < lhs[idx]) ? 1 : 0;
        }
    }
};

template<std::size_t BitCount>
struct big_int {
    typedef uint64_t word_type;
    static const std::size_t bit_count = BitCount;
    static const std::size_t word_count = (BitCount + std::numeric_limits<word_type>::digits - 1) / std::numeric_limits<word_type>::digits;
    using storage = std::array<uint64_t, word_count>;

    typedef typename storage::iterator iterator;

    iterator start() { return storage_.begin(); }
    iterator finish() { return storage_.end(); }

    explicit big_int(word_type initial = word_type()) {
        assert(-1l >> 1 == -1l);
        std::fill(start(), finish(), word_type());
        storage_[0] = initial;
    }

    inline word_type& at(std::size_t index) { return storage_[index]; }
    inline const word_type& at(std::size_t index) const { return storage_[index]; }

    big_int& operator+=(const big_int& operand) {
        add_helper<bit_count, word_count>::perform(*this, operand);
        return *this;
    }

    big_int& operator~() {
        std::transform(start(), finish(), start(), std::bit_not<word_type>());
        return *this;
    }

    void dump_raw(std::ostream& stream) const {
        stream << "(";
        for (std::size_t pos = word_count - 1; pos > 0; --pos)
            stream << storage_[pos] << " ";
        stream << storage_[0];
        stream << ")";
    }

    void display(std::ostream& stream) const {
        assert(false && " TO DO ! \n");
    }

private:
    storage storage_;
};

template <std::size_t BitCount>
std::ostream& operator<< (std::ostream& stream, big_int<BitCount> const& value) {
    if (stream.flags() & std::ios_base::hex)
        value.dump_raw(stream);
    else
        value.display(stream);
    return stream;
}

int main(int argc, const char * argv[]) {
    big_int<256> x; // Initialize to zero
    big_int<256> y(1);

    ~x; // Invert all bits: all zeros become ones

    std::cout << " x: " << std::hex << x << std::endl;
    std::cout << " expected: (ffffffffffffffff ffffffffffffffff ffffffffffffffff ffffffffffffffff) " << std::endl;

    x += y; // Add one, should cause carry propagation

    std::cout << " x+=y: " << x << std::endl;
    std::cout << " expected: (0 0 0 0) " << std::endl; // Result after overflow

    return 0;
}

