// Custom generator class implementation
class SequenceGenerator {
public:
  SequenceGenerator(int begin, int limit) : index(begin), stop(limit) {}

  bool hasMore() const {
    return index < stop;
  }

  int advance() {
    return index++;
  }

private:
  int index;
  int stop;
};

// Factory function for creating generator instances
void CreateInstance(const FunctionCallbackInfo<Value>& info) {
  Isolate* isolate = info.GetIsolate();
  Local<Context> context = isolate->GetCurrentContext();

  if (info.IsConstructCall()) {
    int startValue = info[0]->IntegerValue(context).ToChecked();
    int endValue = info[1]->IntegerValue(context).ToChecked();

    SequenceGenerator* gen = new SequenceGenerator(startValue, endValue);
    info.This()->SetInternalField(0, External::New(isolate, gen));

    info.GetReturnValue().Set(info.This());
  } else {
    Local<Function> factory = Local<Function>::New(isolate, constructorRef);
    Local<Value> parameters[2] = { info[0], info[1] };
    info.GetReturnValue().Set(factory->NewInstance(context, 2, parameters).ToLocalChecked());
  }
}

// Implementation of the iterator's next() method
void IteratorNext(const FunctionCallbackInfo<Value>& info) {
  Isolate* isolate = info.GetIsolate();
  Local<Context> context = isolate->GetCurrentContext();
  SequenceGenerator* gen = static_cast<SequenceGenerator*>(info.This()->GetInternalField(0).As<External>()->Value());

  if (gen->hasMore()) {
    int current = gen->advance();
    Local<Object> output = Object::New(isolate);
    output->Set(context, String::NewFromUtf8(isolate, "value").ToLocalChecked(), Number::New(isolate, current));
    output->Set(context, String::NewFromUtf8(isolate, "done").ToLocalChecked(), Boolean::New(isolate, false));
    info.GetReturnValue().Set(output);
  } else {
    Local<Object> output = Object::New(isolate);
    output->Set(context, String::NewFromUtf8(isolate, "value").ToLocalChecked(), Undefined(isolate));
    output->Set(context, String::NewFromUtf8(isolate, "done").ToLocalChecked(), Boolean::New(isolate, true));
    info.GetReturnValue().Set(output);
  }
}

// Implementation of @@iterator method (returns self)
void GetIteratorMethod(const PropertyCallbackInfo<Value>& info) {
  info.GetReturnValue().Set(info.Holder());
}

// Persistent handle to store the constructor
Persistent<Function> SequenceGenerator::constructorRef;

// Module initialization function
void SetupModule(Local<Object> moduleExports) {
  Isolate* isolate = moduleExports->GetIsolate();
  Local<Context> context = isolate->GetCurrentContext();

  // Create function template for the generator
  Local<FunctionTemplate> generatorTemplate = FunctionTemplate::New(isolate, CreateInstance);
  generatorTemplate->SetClassName(String::NewFromUtf8(isolate, "SequenceGenerator").ToLocalChecked());
  generatorTemplate->InstanceTemplate()->SetInternalFieldCount(1);

  // Add methods to prototype
  NODE_SET_PROTOTYPE_METHOD(generatorTemplate, "next", IteratorNext);

  // Set up @@iterator symbol
  Local<String> iteratorSymbol = String::NewFromUtf8(isolate, Symbol::GetIterator(isolate)).ToLocalChecked();
  generatorTemplate->InstanceTemplate()->Set(iteratorSymbol, 
      FunctionTemplate::New(isolate, GetIteratorMethod)->GetFunction(context).ToLocalChecked());

  // Store constructor and export
  constructorRef.Reset(isolate, generatorTemplate->GetFunction(context).ToLocalChecked());
  moduleExports->Set(context, String::NewFromUtf8(isolate, "SequenceGenerator").ToLocalChecked(), 
      generatorTemplate->GetFunction(context).ToLocalChecked());
}

// Register the native addon
NODE_MODULE(addon_module, SetupModule)

