// Initialize reciprocal values for arithmetic coding
void aricoder::initialize() {
    // Compute scaled reciprocals for each symbol
    for (int j = 0; j < num_symbols; ++j) {
        symbols[j].reciprocal = (1 << 31) / (symbols[j].scale * 2);
    }
}

void aricoder::encode(symbol* sym) {
    unsigned int range_plus_one = ((chigh - clow) + 1);
    cstep = (range_plus_one * sym->reciprocal) >> 31;
    chigh = clow + (cstep * sym->high_count) - 1;
    clow = clow + (cstep * sym->low_count);

    // Handle overflow conditions
    while ((clow >= CODER_LIMIT050) || (chigh < CODER_LIMIT050)) {
        if (chigh < CODER_LIMIT050) {
            write_zero();
            write_nrbits_as_one();
        } else {
            write_one();
            clow &= (CODER_LIMIT050 - 1);
            chigh &= (CODER_LIMIT050 - 1);
            write_nrbits_as_zeros();
        }
        clow <<= 1;
        chigh = (chigh << 1) | 1;
    }

    // Handle mid-range expansion
    while ((clow >= CODER_LIMIT025) && (chigh < CODER_LIMIT075)) {
        ++nrbits;
        clow &= (CODER_LIMIT025 - 1);
        chigh ^= (CODER_LIMIT025 + CODER_LIMIT050);
        clow <<= 1;
        chigh = (chigh << 1) | 1;
    }
}

