using namespace std;

// Function to print the longest common subsequence
void displayLCS(string &str1, string &str2, vector<vector<int>> &table) {
    int len1 = str1.length();
    int len2 = str2.length();
    string result;

    int i = len1, j = len2;
    while (i > 0 && j > 0) {
        if (str1[i-1] == str2[j-1]) {
            result += str1[i-1];
            i--;
            j--;
        } else if (table[i-1][j] > table[i][j-1]) {
            i--;
        } else {
            j--;
        }
    }

    reverse(result.begin(), result.end());
    cout << "Longest Common Subsequence: " << result << endl;
}

// Function to find the length of the longest common subsequence
int computeLCSLength(string &str1, string &str2) {
    int len1 = str1.length();
    int len2 = str2.length();

    vector<vector<int>> dp(len1 + 1, vector<int>(len2 + 1, 0));

    // Build the dp table in bottom-up fashion
    for (int i = 1; i <= len1; i++) {
        for (int j = 1; j <= len2; j++) {
            if (str1[i-1] == str2[j-1]) {
                dp[i][j] = dp[i-1][j-1] + 1;
            } else {
                dp[i][j] = max(dp[i-1][j], dp[i][j-1]);
            }
        }
    }

    // Print the LCS
    displayLCS(str1, str2, dp);

    return dp[len1][len2];
}

int main() {
    string input1, input2;
    cout << "Enter the first string: ";
    cin >> input1;
    cout << "Enter the second string: ";
    cin >> input2;

    int lcsLength = computeLCSLength(input1, input2);
    cout << "Length of the Longest Common Subsequence: " << lcsLength << endl;

    return 0;
}

