using namespace std;

// Structure representing a connection in the graph
struct Connection {
    int destination;  // Target node
    int cost;         // Cost of traversing the edge
};

// Function to insert a directed edge into the adjacency list
void insertEdge(vector<vector<Connection>>& adjacencyList, int source, int target, int expense) {
    adjacencyList[source].emplace_back(target, expense);
}

// Implementation of Dijkstra's algorithm for shortest path computation
vector<int> computeShortestPath(const vector<vector<Connection>>& adjacencyList, int origin, int destination) {
    int numberOfNodes = adjacencyList.size();
    vector<int> distances(numberOfNodes, numeric_limits<int>::max());
    vector<int> predecessors(numberOfNodes, -1);
    distances[origin] = 0;

    // Min-heap priority queue storing (distance, node)
    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> minHeap;
    minHeap.emplace(0, origin);

    while (!minHeap.empty()) {
        int currentNode = minHeap.top().second;
        int currentDistance = minHeap.top().first;
        minHeap.pop();

        // Early exit if destination reached
        if (currentNode == destination) break;

        // Skip if outdated distance entry
        if (currentDistance > distances[currentNode]) continue;

        // Explore neighbors and relax edges
        for (const Connection& conn : adjacencyList[currentNode]) {
            int neighbor = conn.destination;
            int edgeCost = conn.cost;
            if (distances[currentNode] + edgeCost < distances[neighbor]) {
                distances[neighbor] = distances[currentNode] + edgeCost;
                predecessors[neighbor] = currentNode;
                minHeap.emplace(distances[neighbor], neighbor);
            }
        }
    }

    // Reconstruct path from destination back to origin
    vector<int> reconstructedPath;
    for (int current = destination; current != -1; current = predecessors[current]) {
        reconstructedPath.push_back(current);
    }
    reverse(reconstructedPath.begin(), reconstructedPath.end());

    return reconstructedPath;
}

int main() {
    // Graph definition: 6 nodes labeled 0 through 5
    int nodeCount = 6;
    vector<vector<Connection>> adjacencyList(nodeCount);

    // Populate graph with weighted directed edges
    insertEdge(adjacencyList, 0, 1, 7);
    insertEdge(adjacencyList, 0, 2, 9);
    insertEdge(adjacencyList, 0, 5, 14);
    insertEdge(adjacencyList, 1, 2, 10);
    insertEdge(adjacencyList, 1, 3, 15);
    insertEdge(adjacencyList, 2, 3, 11);
    insertEdge(adjacencyList, 2, 5, 2);
    insertEdge(adjacencyList, 3, 4, 6);
    insertEdge(adjacencyList, 4, 5, 9);

    // Compute shortest path from node 0 to node 4
    vector<int> optimalPath = computeShortestPath(adjacencyList, 0, 4);

    // Output the resulting path
    cout << "Optimal route: ";
    for (int vertex : optimalPath) {
        cout << vertex << " ";
    }
    cout << endl;

    return 0;
}

