float InverseSquareRoot(float number) {
    float halfValue = 0.5f * number;
    int tempInt = *(int*)&number;  // bit-level manipulation for fast inverse sqrt
    tempInt = 0x5f3759df - (tempInt >> 1);  // initial approximation magic number
    number = *(float*)&tempInt;
    number = number * (1.5f - (halfValue * number * number));  // Newton-Raphson iteration
    return number;
}

