// Allocate and process image data using CUDA texture memory
int main() {
    int imgWidth = 640;
    int imgHeight = 480;

    // Simulate image creation (in real code this would use OpenCV)
    unsigned char* hostImageData = new unsigned char[imgWidth * imgHeight * 3];
    for (int i = 0; i < imgWidth * imgHeight * 3; ++i) {
        hostImageData[i] = static_cast<unsigned char>(i % 256);
    }

    // Texture declaration and setup
    texture<unsigned char, 2, cudaReadModeElementType> texRef;
    cudaChannelFormatDesc desc = cudaCreateChannelDesc(8, 8, 8, 0, cudaChannelFormatKindUnsigned);

    cudaArray* cuMemArray = nullptr;
    cudaMallocArray(&cuMemArray, &desc, imgWidth, imgHeight);

    cudaMemcpy2DToArray(cuMemArray, 0, 0, hostImageData, imgWidth * 3, 
                        imgWidth * 3, imgHeight, cudaMemcpyHostToDevice);
    cudaBindTextureToArray(texRef, cuMemArray, desc);

    // Kernel to process image data
    __global__ void imageKernel(unsigned char* devOutput, int w, int h) {
        int x = blockIdx.x * blockDim.x + threadIdx.x;
        int y = blockIdx.y * blockDim.y + threadIdx.y;

        if (x < w && y < h) {
            unsigned char r = tex2D(texRef, x, y);     // Red component
            unsigned char g = tex2D(texRef, x, y + 1); // Green component  
            unsigned char b = tex2D(texRef, x, y + 2); // Blue component

            int idx = (y * w + x) * 3;
            devOutput[idx + 0] = r;
            devOutput[idx + 1] = g;
            devOutput[idx + 2] = b;
        }
    }

    // Device memory allocation for output
    unsigned char* deviceResult;
    cudaMalloc(&deviceResult, imgWidth * imgHeight * 3 * sizeof(unsigned char));

    // Configure execution parameters
    dim3 threadsPerBlock(16, 16);
    dim3 blocksPerGrid((imgWidth + 15) / 16, (imgHeight + 15) / 16);

    // Launch kernel
    imageKernel<<<blocksPerGrid, threadsPerBlock>>>(deviceResult, imgWidth, imgHeight);

    // Copy results back to host
    unsigned char* hostResult = new unsigned char[imgWidth * imgHeight * 3];
    cudaMemcpy(hostResult, deviceResult, imgWidth * imgHeight * 3 * sizeof(unsigned char), 
               cudaMemcpyDeviceToHost);

    // Cleanup resources
    cudaFree(deviceResult);
    cudaFreeArray(cuMemArray);
    cudaUnbindTexture(texRef);

    // Release host memory
    delete[] hostImageData;
    delete[] hostResult;

    return 0;
}

// Set the LED output pin
const int ledOutput = 10;

// Define the initial blinking sequence and related parameters
int blinkSequence[] = {0, 1, 0, 1}; // 0 for off, 1 for on
int timeDelays[] = {600, 900, 600, 900}; // delay durations in milliseconds
int lightIntensity[] = {200, 0, 200, 0}; // PWM levels (0-255)
int sequenceSize = sizeof(blinkSequence) / sizeof(blinkSequence[0]);

// Storage for user-provided configuration data
String userPattern = "";
String userDelays = "";
String userBrightness = "";

void setup() {
  // Configure the LED pin as an output
  pinMode(ledOutput, OUTPUT);

  // Initialize serial communication
  Serial.begin(9600);
  Serial.println("LED Blink Sequence Manager");
  Serial.println("Provide updated pattern, timing, and intensity values separated by commas.");
  Serial.println("Format: 0,1,0,1,600,900,600,900,200,0,200,0");
}

void loop() {
  // Monitor for incoming serial data
  if (Serial.available() > 0) {
    String receivedData = Serial.readStringUntil('\n');
    processInput(receivedData);
  }

  // Execute the current LED blinking sequence
  for (int idx = 0; idx < sequenceSize; idx++) {
    analogWrite(ledOutput, lightIntensity[idx]);
    delay(timeDelays[idx]);
  }
}

void processInput(String data) {
  // Break down the input string into manageable segments
  String segments[12];
  int segmentCount = 0;
  int startPos = 0;

  while (startPos < data.length()) {
    int nextComma = data.indexOf(',', startPos);
    if (nextComma == -1) {
      segments[segmentCount] = data.substring(startPos);
      segmentCount++;
      break;
    }
    segments[segmentCount] = data.substring(startPos, nextComma);
    segmentCount++;
    startPos = nextComma + 1;
  }

  // Apply new settings if input format is correct
  if (segmentCount >= 3 && segmentCount % 3 == 0) {
    sequenceSize = segmentCount / 3;
    for (int j = 0; j < sequenceSize; j++) {
      blinkSequence[j] = segments[j * 3].toInt();
      timeDelays[j] = segments[j * 3 + 1].toInt();
      lightIntensity[j] = segments[j * 3 + 2].toInt();
    }
    Serial.println("Blink sequence updated successfully!");
  } else {
    Serial.println("Incorrect input. Please provide valid pattern, timing, and intensity values.");
  }
}

#include <iostream>
#include <string>
#include <vector>
#include <cctype>
#include <unordered_map>

enum class TokenType {
    INT, FLOAT, IDENTIFIER, ASSIGN, PLUS, MINUS, MUL, DIV, LPAREN, RPAREN, SEMICOLON, EOF_TOKEN,
    IF, WHILE, FUNCTION, COMMA, LBRACE, RBRACE, ERROR
};

struct TokenData {
    TokenType kind;
    std::string literal;
    int row;
    int col;
};

class Scanner {
public:
    Scanner(const std::string& source) : source(source), index(0), row(1), col(1) {}

    TokenData getNextToken();

private:
    std::string source;
    size_t index;
    int row;
    int col;

    char peekChar();
    void moveNext();
    void ignoreWhitespace();
    TokenData parseNumber();
    TokenData parseName();
    TokenData checkReservedWord(const std::string& word);
};

char Scanner::peekChar() {
    return index < source.length() ? source[index] : '\0';
}

void Scanner::moveNext() {
    if (peekChar() == '\n') {
        row++;
        col = 1;
    } else {
        col++;
    }
    index++;
}

void Scanner::ignoreWhitespace() {
    while (std::isspace(peekChar())) {
        moveNext();
    }
}

TokenData Scanner::parseNumber() {
    std::string numStr;
    while (std::isdigit(peekChar()) || peekChar() == '.') {
        numStr += peekChar();
        moveNext();
    }
    if (numStr.find('.') != std::string::npos) {
        return {TokenType::FLOAT, numStr, row, col};
    } else {
        return {TokenType::INT, numStr, row, col};
    }
}

TokenData Scanner::parseName() {
    std::string nameStr;
    while (std::isalnum(peekChar()) || peekChar() == '_') {
        nameStr += peekChar();
        moveNext();
    }
    return checkReservedWord(nameStr);
}

TokenData Scanner::checkReservedWord(const std::string& word) {
    static const std::unordered_map<std::string, TokenType> reserved = {
        {"if", TokenType::IF},
        {"while", TokenType::WHILE},
        {"function", TokenType::FUNCTION}
    };

    auto iter = reserved.find(word);
    if (iter != reserved.end()) {
        return {iter->second, word, row, col};
    }
    return {TokenType::IDENTIFIER, word, row, col};
}

TokenData Scanner::getNextToken() {
    ignoreWhitespace();

    if (index >= source.length()) {
        return {TokenType::EOF_TOKEN, "", row, col};
    }

    char ch = peekChar();
    if (std::isdigit(ch)) {
        return parseNumber();
    }

    if (std::isalpha(ch) || ch == '_') {
        return parseName();
    }

    moveNext();
    switch (ch) {
        case '+': return {TokenType::PLUS, "+", row, col};
        case '-': return {TokenType::MINUS, "-", row, col};
        case '*': return {TokenType::MUL, "*", row, col};
        case '/': return {TokenType::DIV, "/", row, col};
        case '(': return {TokenType::LPAREN, "(", row, col};
        case ')': return {TokenType::RPAREN, ")", row, col};
        case ';': return {TokenType::SEMICOLON, ";", row, col};
        case ',': return {TokenType::COMMA, ",", row, col};
        case '{': return {TokenType::LBRACE, "{", row, col};
        case '}': return {TokenType::RBRACE, "}", row, col};
        default: return {TokenType::ERROR, std::string(1, ch), row, col};
    }
