class AbstractExpression {
public:
    virtual ~AbstractExpression() {}
    virtual double compute() const = 0;
};

class Literal : public AbstractExpression {
private:
    double numValue;
public:
    Literal(double val) : numValue(val) {}
    double compute() const override { return numValue; }
};

class CompoundExpression : public AbstractExpression {
private:
    AbstractExpression* operand1;
    AbstractExpression* operand2;
    char operation;
public:
    CompoundExpression(AbstractExpression* op1, char oper, AbstractExpression* op2) 
        : operand1(op1), operation(oper), operand2(op2) {}
    ~CompoundExpression() {
        delete operand1;
        delete operand2;
    }
    double compute() const override {
        double leftVal = operand1->compute();
        double rightVal = operand2->compute();
        switch (operation) {
            case '+': return leftVal + rightVal;
            case '-': return leftVal - rightVal;
            case '*': return leftVal * rightVal;
            case '/': return leftVal / rightVal;
            default: throw std::runtime_error("Unsupported operator");
        }
    }
};

