// A 4-dimensional vector implementation
class Vec4D {
public:
    double get<1>() const { return elements[0]; }
    double get<2>() const { return elements[1]; }
    double get<4>() const { return elements[2]; }
    double get<8>() const { return elements[3]; }

    // Compute dot product with another vector
    double multiply(const Vec4D& rhs) const {
        return get<1>() * rhs.get<1>() +
               get<2>() * rhs.get<2>() +
               get<4>() * rhs.get<4>() +
               get<8>() * rhs.get<8>();
    }

private:
    double elements[4];
};

