// Determine if a character is an arithmetic operator
bool isArithmeticOperator(char c) {
    return c == '+' || c == '-' || c == '*' || c == '/';
}

// Determine if a character is part of a numeric value
bool isNumericChar(char c) {
    return std::isdigit(c) || c == '.';
}

// Return the precedence level of an operator
int getPrecedence(char op) {
    if (op == '+' || op == '-') return 1;
    if (op == '*' || op == '/') return 2;
    return 0;
}

// Transform infix notation to postfix notation
std::string convertToPostfix(const std::string &infixExpr) {
    std::stack<char> opStack;
    std::string postfixResult;
    std::stringstream ss(infixExpr);
    std::string currentToken;

    while (ss >> currentToken) {
        if (isNumericChar(currentToken[0])) {
            postfixResult += currentToken + " ";
        } else if (isArithmeticOperator(currentToken[0])) {
            while (!opStack.empty() && getPrecedence(opStack.top()) >= getPrecedence(currentToken[0])) {
                postfixResult += opStack.top();
                opStack.pop();
                postfixResult += " ";
            }
            opStack.push(currentToken[0]);
        } else if (currentToken[0] == '(') {
            opStack.push(currentToken[0]);
        } else if (currentToken[0] == ')') {
            while (!opStack.empty() && opStack.top() != '(') {
                postfixResult += opStack.top();
                opStack.pop();
                postfixResult += " ";
            }
            if (!opStack.empty() && opStack.top() == '(') {
                opStack.pop();
            }
        }
    }

    while (!opStack.empty()) {
        postfixResult += opStack.top();
        opStack.pop();
        postfixResult += " ";
    }

    return postfixResult;
}

// Compute the result of a postfix expression
double computePostfix(const std::string &postfixExpr) {
    std::stack<double> valueStack;
    std::istringstream iss(postfixExpr);
    std::string token;

    while (iss >> token) {
        if (isNumericChar(token[0])) {
            valueStack.push(std::stod(token));
        } else if (isArithmeticOperator(token[0])) {
            double secondOperand = valueStack.top(); valueStack.pop();
            double firstOperand = valueStack.top(); valueStack.pop();
            switch (token[0]) {
                case '+': valueStack.push(firstOperand + secondOperand); break;
                case '-': valueStack.push(firstOperand - secondOperand); break;
                case '*': valueStack.push(firstOperand * secondOperand); break;
                case '/': valueStack.push(firstOperand / secondOperand); break;
            }
        }
    }

    return valueStack.top();
}

int main() {
    std::string infixExpression = "3 + 4 * 2 / ( 1 - 5 )";
    std::string postfixExpression = convertToPostfix(infixExpression);
    double finalResult = computePostfix(postfixExpression);

    std::cout << "Infix Expression: " << infixExpression << std::endl;
    std::cout << "Postfix Expression: " << postfixExpression << std::endl;
    std::cout << "Computed Result: " << finalResult << std::endl;

    return 0;
}

