RTC_DS3231 clock;

const int wakeHour = 7;
const int wakeMinute = 0;
const int speakerPin = 8;

void setup() {
  Serial.begin(9600);
  if (!clock.begin()) {
    Serial.println("Couldn't find RTC");
    while (1);
  }
  if (clock.lostPower()) {
    Serial.println("RTC lost power, let's set the time!");
    clock.adjust(DateTime(F(__DATE__), F(__TIME__)));
  }
  pinMode(speakerPin, OUTPUT);
}

void loop() {
  DateTime current = clock.now();
  Serial.print("Current time: ");
  Serial.print(current.hour(), DEC);
  Serial.print(':');
  Serial.print(current.minute(), DEC);
  Serial.print(':');
  Serial.print(current.second(), DEC);
  Serial.println();

  if (current.hour() == wakeHour && current.minute() == wakeMinute) {
    Serial.println("Alarm time!");
    digitalWrite(speakerPin, HIGH);
    delay(10000); // Buzz for 10 seconds
    digitalWrite(speakerPin, LOW);
  }
  delay(1000); // Wait a second before checking the time again
}

