class MathClampAssembler : public CodeStubAssembler {
 public:
  MathClampAssembler(Zone* zone, Isolate* isolate)
      : CodeStubAssembler(zone, isolate, Code::STUB, kNoCallSiteDetails) {}

  Node* Clamp(Node* input_value, Node* lower_bound, Node* upper_bound) {
    // Compare input_value with lower_bound
    Node* input_meets_lower = this->Int32GreaterThanOrEqual(input_value, lower_bound);

    // If input_value is less than lower_bound, set it to lower_bound
    Node* adjusted_value = this->ChangeInt32ToInt32(
        this->SelectInt32(this->BooleanNot(input_meets_lower), lower_bound, input_value));

    // Compare adjusted_value with upper_bound
    Node* adjusted_within_upper = this->Int32LessThanOrEqual(adjusted_value, upper_bound);

    // If adjusted_value exceeds upper_bound, set it to upper_bound
    Node* result_clamped_value = this->ChangeInt32ToInt32(
        this->SelectInt32(this->BooleanNot(adjusted_within_upper), upper_bound, adjusted_value));

    return result_clamped_value;
  }
};

