const int fieldHeight = 20;
const int fieldWidth = 40;

void renderField(const char field[][fieldWidth], int heroRow) {
    for (int row = 0; row < fieldHeight; ++row) {
        for (int col = 0; col < fieldWidth; ++col) {
            if (row == heroRow && col == fieldWidth / 2) {
                std::cout << 'H';
            } else {
                std::cout << field[row][col];
            }
        }
        std::cout << "\n";
    }
}

void updateHeroPosition(int &heroY, char key) {
    if (key == 'j' && heroY > 0) {
        --heroY;
    } else if (key == 'k' && heroY < fieldHeight - 1) {
        ++heroY;
    }
}

int main() {
    srand(time(0));

    char arena[fieldHeight][fieldWidth] = {};

    for (int r = 0; r < fieldHeight; ++r) {
        for (int c = 0; c < fieldWidth; ++c) {
            if (c == 0 || c == fieldWidth - 1) {
                arena[r][c] = '#';
            } else {
                arena[r][c] = ' ';
            }
        }
    }

    int heroY = fieldHeight / 2;
    int rounds = 3;
    int progress = 0;

    while (rounds > 0) {
        system("clear"); // For Windows use: system("cls");

        renderField(arena, heroY);

        char cmd;
        std::cin >> cmd;
        updateHeroPosition(heroY, cmd);

        int drift = rand() % 3 - 1;
        if (heroY + drift >= 0 && heroY + drift < fieldHeight) {
            heroY += drift;
        }

        if (++progress >= fieldWidth) {
            --rounds;
            progress = 0;
        }

        usleep(50000); // Sleep for 50 milliseconds
    }

    std::cout << "Well done! You completed the challenge!\n";

    return 0;
}

