void registerEntity(std::shared_ptr<GAME_OBJECT> entity) {
    if (entityList.size() >= MAX_ENTITIES) {
        entityList.erase(entityList.begin());
        entity->uniqueID = MAX_ENTITIES - 1;
    }
    entity->uniqueID = ID_GENERATOR++;
    entityList.push_back(entity);
