    width = img->width();

    for (unsigned int row = 0; row < height; ++row) {
        for (unsigned int col = 0; col < width; ++col) {
            pixelValue = img->get_pixel(col, row);
            pixelColor = RGB(pixelValue.red, pixelValue.green, pixelValue.blue);
            SetPixelV(deviceContext, col + screenPos.x, row + screenPos.y, pixelColor);
        }
    }
}

