int gameLoop() {
    const int TARGET_UPDATES_PER_SECOND = 60;
    const int TIME_PER_TICK = 1000 / TARGET_UPDATES_PER_SECOND;
    const int MAX_STEPS = 1;

    DWORD nextUpdate = GetTickCount();
    float timeFactor;
    int stepCount;

    while (isGameRunning) {
        stepCount = 0;
        while (GetTickCount() > nextUpdate && stepCount < MAX_STEPS) {
            handleInput();
            updateGameState();
            nextUpdate += TIME_PER_TICK;
            stepCount++;
        }
        timeFactor = static_cast<float>(GetTickCount() + TIME_PER_TICK - nextUpdate) / static_cast<float>(TIME_PER_TICK);
