#include <iostream>
using namespace std;

// Define the Node structure
struct Node {
    int value;
    Node* link;
};

// Function to create a new node
Node* newNode(int value) {
    Node* created = new Node();
    if (!created) {
        cout << "Memory allocation failed\n";
        return NULL;
    }
    created->value = value;
    created->link = NULL;
    return created;
}

// Function to insert a new node at the beginning of the list
void pushFront(Node** start, int value) {
    Node* fresh = newNode(value);
    fresh->link = *start;
    *start = fresh;
}

// Function to insert a new node at the end of the list
void pushBack(Node** start, int value) {
    Node* fresh = newNode(value);
    if (*start == NULL) {
        *start = fresh;
        return;
    }
    Node* runner = *start;
    while (runner->link != NULL) {
        runner = runner->link;
    }
    runner->link = fresh;
}

// Function to insert a new node at a specific position in the list
void insertAt(Node** start, int value, int pos) {
    if (pos == 1) {
        pushFront(start, value);
        return;
    }
    Node* fresh = newNode(value);
    Node* runner = *start;
    for (int idx = 1; runner != NULL && idx < pos - 1; idx++) {
        runner = runner->link;
    }
    if (runner == NULL) {
        cout << "Invalid position\n";
        return;
    }
    fresh->link = runner->link;
    runner->link = fresh;
}

// Function to print the list
void displayList(Node* start) {
    Node* runner = start;
    while (runner != NULL) {
        cout << runner->value << " ";
        runner = runner->link;
    }
    cout << endl;
}

// Function to delete a node from the list
void removeNode(Node** start, int target) {
    Node* runner = *start, *previous = NULL;
    if (runner != NULL && runner->value == target) {
        *start = runner->link;
        delete runner;
        return;
    }
    while (runner != NULL && runner->value != target) {
        previous = runner;
        runner = runner->link;
    }
    if (runner == NULL) {
        cout << "Value not found\n";
        return;
    }
    previous->link = runner->link;
    delete runner;
}

// Main function
int main() {
    Node* head = NULL;

    pushBack(&head, 10);
    pushBack(&head, 20);
    pushFront(&head, 5);
    insertAt(&head, 15, 2);

    cout << "Linked list: ";
    displayList(head);

    removeNode(&head, 15);
    cout << "After removing 15: ";
    displayList(head);

    return 0;
}

#include <vector>
#include <cmath>
#include <random>
#include <complex>

struct WirelessSignal {
  double transmitPower; // dBm
  double carrierFreq;
  double channelBandwidth;
};

class FullbandSpectrumSynthesizer {
public:
  // Constructor
  FullbandSpectrumSynthesizer(double lowFreq, double highFreq, double samplingRate, double backgroundLevel, double qualityFactor, std::vector<WirelessSignal> signalList) :
    m_lowFreq(lowFreq), m_highFreq(highFreq), m_samplingRate(samplingRate), m_backgroundLevel(backgroundLevel), m_qualityFactor(qualityFactor), m_signalList(signalList) {}

  // Synthesize the power spectrum across the specified frequency band
  std::vector<double> synthesize() {
    // Configure frequency grid
    double deltaF = m_samplingRate / m_spectrumLength;
    std::vector<double> frequencyGrid(m_spectrumLength);
    for (size_t idx = 0; idx < frequencyGrid.size(); ++idx) {
      frequencyGrid[idx] = m_lowFreq + idx * deltaF;
    }

    // Initialize with background noise
    std::vector<double> background = createBackgroundNoise(frequencyGrid);

    // Add contributions from each signal
    for (const WirelessSignal& txSignal : m_signalList) {
      std::vector<double> signalContribution = createSignalSpectrum(txSignal, frequencyGrid);
      for (size_t idx = 0; idx < m_spectrumLength; ++idx) {
        m_fullSpectrum[idx] += signalContribution[idx];
      }
    }

    // Incorporate background noise into final spectrum
    for (size_t idx = 0; idx < m_spectrumLength; ++idx) {
      m_fullSpectrum[idx] += background[idx];
    }

    return m_fullSpectrum;
  }

private:
  double m_lowFreq; // Lower bound of frequency range
  double m_highFreq; // Upper bound of frequency range
  double m_samplingRate; // Sampling frequency
  double m_backgroundLevel; // Background noise in dBm
  double m_qualityFactor; // SNR in dB
  std::vector<WirelessSignal> m_signalList; // Collection of signals to synthesize
  size_t m_spectrumLength = 1024; // Number of frequency bins
  std::vector<double> m_fullSpectrum = std::vector<double>(m_spectrumLength, m_backgroundLevel); // Pre-allocated spectrum buffer

  // Create power spectrum for a single wireless signal
  std::vector<double> createSignalSpectrum(const WirelessSignal& txSignal, const std::vector<double>& freqGrid) {
    std::vector<double> signalSpectrum(m_spectrumLength, 0.0);
    for (size_t idx = 0; idx < m_spectrumLength; ++idx) {
      double currentFreq = freqGrid[idx];
      if (currentFreq >= txSignal.carrierFreq - txSignal.channelBandwidth / 2 && 
          currentFreq <= txSignal.carrierFreq + txSignal.channelBandwidth / 2) {
        // Signal present in this bin
        double rawPower = dBmToWatt(txSignal.transmitPower);
        double noiseComponent = rawPower / dBToLinear(m_qualityFactor);

        // Generate complex baseband representation
        std::complex<double> signalComplex = buildSignalComplex(rawPower, currentFreq);

        // Add noise contribution
        std::complex<double> noiseComplex = buildNoiseComplex(noiseComponent);
        std::complex<double> combined = signalComplex + noiseComplex;

        // Compute magnitude squared (power)
        double combinedPower = std::abs(combined);
        double combinedDbm = wattTodBm(combinedPower);

        // Normalize to PSD and adjust units
        double psdValue = wattTodBm(combinedPower / m_samplingRate) - 30;

        signalSpectrum[idx] = psdValue;
      }
    }
    return signalSpectrum;
  }

  // Create background noise floor
  std::vector<double> createBackgroundNoise(const std::vector<double>& freqGrid) {
    std::vector<double> noiseFloor(m_spectrumLength);
    double baseNoise = dBmToWatt(m_backgroundLevel);
    for (size_t idx = 0; idx < m_spectrumLength; ++idx) {
      double instantaneousNoise = computeNoiseMagnitude(baseNoise);
      double psd = wattTodBm(instantaneousNoise / m_samplingRate) - 30;
      noiseFloor[idx] = psd;
    }
    return noiseFloor;
  }

  // Generate noise sample with specified power
  double computeNoiseMagnitude(double powerLevel) {
    std::normal_distribution<double> distribution(0.0, std::sqrt(powerLevel));
    double realPart = distribution(m_randomEngine);
    double imagPart = distribution(m_randomEngine);
    std::complex<double> noiseSample(realPart, imagPart);
    return std::norm(noiseSample);
  }

  // Build complex signal representation
  std::complex<double> buildSignalComplex(double powerLevel, double centerFreq) {
    double randomPhase = m_uniformDist(m_randomEngine) * 2.0 * M_PI;
    double amplitude = std::sqrt(dBmToWatt(powerLevel));
    double realComponent = amplitude * std::cos(2.0 * M_PI * centerFreq / m_samplingRate + randomPhase);
    double imagComponent = amplitude * std::sin(2.0 * M_PI * centerFreq / m_samplingRate + randomPhase);
    return std::complex<double>(realComponent, imagComponent);
  }

  // Build complex noise representation
  std::complex<double> buildNoiseComplex(double noisePower) {
    std::normal_distribution<double> distribution(0.0, std::sqrt(dBmToWatt(noisePower)));
    double realPart = distribution(m_randomEngine);
    double imagPart = distribution(m_randomEngine);
    return std::complex<double>(realPart, imagPart);
  }

  // Convert dBm to watts
  double dBmToWatt(double dBmInput) {
    return std::pow(10.0, dBmInput / 10.0 - 3.0);
  }

  // Convert watts to dBm
  double wattTodBm(double wattInput) {
    return 10.0 * std::log10(wattInput * 1000.0);
  }

  // Convert decibels to linear ratio
  double dBToLinear(double dBInput) {
    return std::pow(10.0, dBInput / 10.0);
  }

  std::mt19937 m_randomEngine; // Mersenne Twister RNG
  std::uniform_real_distribution<double> m_uniformDist{0.0, 1.0}; // Phase generator
};

