}

#include <cstdio>
#include <cstdlib>

typedef unsigned long U32;

extern "C" __declspec(dllexport) int LoadBinaryData(LPSTR FilePath, U32** BufferPtr, U32* ElementCount)
{
    FILE *fileHandle;
    U32 *buffer;
    CString tempPath(FilePath);
    long fileSize;

    if (!(fileHandle = fopen(tempPath, "rb"))) {
        return 0;
    }

    // Determine file size
    fseek(fileHandle, 0, SEEK_END);
    fileSize = ftell(fileHandle);
    rewind(fileHandle);

    // Validate file size alignment
    if (fileSize % sizeof(U32) != 0) {
        fclose(fileHandle);
        return -3; // File size is not aligned to U32 boundaries
    }

    // Allocate memory for the buffer
    buffer = (U32 *)malloc(fileSize);
    if (buffer == NULL) {
        fclose(fileHandle);
        return -1;
    }

    // Read file contents into buffer
    *ElementCount = fread(buffer, sizeof(U32), fileSize / sizeof(U32), fileHandle);
    if (*ElementCount == 0) {
        fclose(fileHandle);
        free(buffer);
        return -2;
    }

    *BufferPtr = buffer;
    fclose(fileHandle);
    return 1;
}

#include <iostream>
