// Function to compute the longest common subsequence of two strings
std::string findLongestCommonSubsequence(const std::string& firstStr, const std::string& secondStr) {
    int len1 = firstStr.size();
    int len2 = secondStr.size();

    // Initialize a 2D table for dynamic programming
    std::vector<std::vector<int>> dpTable(len1 + 1, std::vector<int>(len2 + 1, 0));

    // Populate the DP table
    for (int row = 1; row <= len1; ++row) {
        for (int col = 1; col <= len2; ++col) {
            if (firstStr[row - 1] == secondStr[col - 1]) {
                dpTable[row][col] = dpTable[row - 1][col - 1] + 1;
            } else {
                dpTable[row][col] = std::max(dpTable[row - 1][col], dpTable[row][col - 1]);
            }
        }
    }

    // Backtrack to build the LCS string
    std::string result;
    int i = len1, j = len2;
    while (i > 0 && j > 0) {
        if (firstStr[i - 1] == secondStr[j - 1]) {
            result = firstStr[i - 1] + result;
            --i;
            --j;
        } else if (dpTable[i - 1][j] > dpTable[i][j - 1]) {
            --i;
        } else {
            --j;
        }
    }

    return result;
}

// Entry point to demonstrate the LCS functionality
int main() {
    std::string strA = "ABCBDAB";
    std::string strB = "BDCAB";

    std::string lcsResult = findLongestCommonSubsequence(strA, strB);
    std::cout << "The longest common subsequence of \"" << strA << "\" and \"" << strB << "\" is: " << lcsResult << std::endl;

    return 0;
}

