     * Atomically compare and exchange a value at the given address
     */
    static size_t atomicCompareAndSwap(volatile size_t* target, size_t expected, size_t desired)
    {
        size_t previous;
        __asm__ volatile(
            "lock cmpxchgq %2, %1\n\t"
            : "=a"(previous), "+m"(*target)
