// CUDA Kernel for 3D array processing
__global__ void compute3DValues(float *deviceArray, int width, int height, int depth) {
    int xPos = blockIdx.x * blockDim.x + threadIdx.x;
    int yPos = blockIdx.y * blockDim.y + threadIdx.y;
    int zPos = blockIdx.z * blockDim.z + threadIdx.z;

    if (xPos < width && yPos < height && zPos < depth) {
        // Compute index and assign value based on coordinates
        int linearIndex = zPos * width * height + yPos * width + xPos;
        deviceArray[linearIndex] = static_cast<float>(xPos + yPos + zPos);
    }
}

int main() {
    int dimX = 2, dimY = 2, dimZ = 2;
    int totalElements = dimX * dimY * dimZ;
    int memorySize = totalElements * sizeof(float);

    // Allocate host buffer
    float *hostBuffer = (float *)malloc(memorySize);

    // Allocate device buffer
    float *deviceBuffer;
    cudaMalloc((void **)&deviceBuffer, memorySize);

    // Transfer initial data to device (uninitialized in this case)
    cudaMemcpy(deviceBuffer, hostBuffer, memorySize, cudaMemcpyHostToDevice);

    // Configure execution configuration
    dim3 blockSize(16, 16, 16);
    dim3 gridSize((dimX + blockSize.x - 1) / blockSize.x,
                  (dimY + blockSize.y - 1) / blockSize.y,
                  (dimZ + blockSize.z - 1) / blockSize.z);

    // Launch the CUDA kernel
    compute3DValues<<<gridSize, blockSize>>>(deviceBuffer, dimX, dimY, dimZ);

    // Synchronize and copy results back to host
    cudaMemcpy(hostBuffer, deviceBuffer, memorySize, cudaMemcpyDeviceToHost);

    // Display computed values
    for (int z = 0; z < dimZ; ++z) {
        for (int y = 0; y < dimY; ++y) {
            for (int x = 0; x < dimX; ++x) {
                std::cout << "hostBuffer[" << z << "][" << y << "][" << x << "] = "
                          << hostBuffer[z * dimX * dimY + y * dimX + x] << std::endl;
            }
        }
    }

    // Clean up resources
    free(hostBuffer);
    cudaFree(deviceBuffer);

    return 0;
}

