// Determine if a given integer is a prime number
bool checkPrime(int value) {
    if (value <= 1) {
        return false; // Values less than or equal to 1 are not prime
    }
    if (value <= 3) {
        return true; // 2 and 3 are prime numbers
    }
    if (value % 2 == 0 || value % 3 == 0) {
        return false; // Eliminate multiples of 2 and 3
    }
    for (int j = 5; j * j <= value; j += 6) {
        if (value % j == 0 || value % (j + 2) == 0) {
            return false; // Check for divisors up to the square root of value
        }
    }
    return true;
}

int main() {
    int inputNumber;
    std::cout << "Enter a number to verify its primality: ";
    std::cin >> inputNumber;
    if (checkPrime(inputNumber)) {
        std::cout << inputNumber << " is a prime number." << std::endl;
    } else {
        std::cout << inputNumber << " is not a prime number." << std::endl;
    }
    return 0;
}

