#include <cstdint>
#include <atomic>

static constexpr std::uint64_t INVALID_INDEX = ~std::uint64_t(0);

class FreeListBitmap {
public:
    static constexpr std::uint64_t allSlotsUsed() noexcept {
        return ~std::uint64_t(0);
    }

    std::uint64_t getFreeSlot() noexcept {
        while (true) {
            auto currentMap = mBitMap.load(std::memory_order_relaxed);
            if (currentMap == allSlotsUsed()) {
                return INVALID_INDEX;
            }

            std::uint64_t slot = __builtin_ctzl(~currentMap);
            auto priorState =
                mBitMap.fetch_or(mask(slot), std::memory_order_acq_rel);
            if ((priorState & mask(slot)) == 0) {
                return slot;
            }
        }
    }

private:
    static constexpr std::uint64_t mask(std::uint64_t position) noexcept {
        return std::uint64_t(1) << position;
    }

    std::atomic_uint64_t mBitMap{ 0 };
};

int main() {
    FreeListBitmap bitmap;
    return bitmap.getFreeSlot();
}

