// Check if a number is prime
bool isPrime(int value) {
    if (value <= 1) return false;
    for (int j = 2; j <= std::sqrt(value); j++) {
        if (value % j == 0) return false;
    }
    return true;
}

// Calculate the sum of the first n prime numbers
int sumOfFirstNPrimes(int limit) {
    int currentCount = 0;
    int runningSum = 0;
    int candidate = 2;
    while (currentCount < limit) {
        if (isPrime(candidate)) {
            runningSum += candidate;
            currentCount++;
        }
        candidate++;
    }
    return runningSum;
}

int main() {
    std::cout << sumOfFirstNPrimes(10) << std::endl;
    return 0;
}

