#include <mutex>
#include <condition_variable>
#include <chrono>
#include <functional>

class JobDispatcher {
public:
    JobDispatcher() : terminated(false) {}

    // Add a job to be executed periodically
    void add_job(std::function<void()> job, std::chrono::milliseconds period) {
        {
            std::lock_guard<std::mutex> guard(queue_mutex);
            job_queue.push({job, period, std::chrono::steady_clock::now()});
        }
        condition.notify_one();
    }

    // Begin processing jobs
    void initialize() {
        for (int index = 0; index < thread_count; ++index) {
            threads.emplace_back(&JobDispatcher::process, this);
        }
    }

    // Terminate the dispatcher and wait for all threads
    void shutdown() {
        {
            std::lock_guard<std::mutex> guard(queue_mutex);
            terminated = true;
        }
        condition.notify_all();
        for (std::thread &worker_thread : threads) {
            worker_thread.join();
        }
    }

private:
    struct JobDescriptor {
        std::function<void()> job;
        std::chrono::milliseconds period;
        std::chrono::steady_clock::time_point scheduled_time;
    };

    void process() {
        while (true) {
            std::unique_lock<std::mutex> lock(queue_mutex);
            condition.wait(lock, [this] { return terminated || !job_queue.empty(); });

            if (terminated && job_queue.empty()) {
                return;
            }

            auto current_time = std::chrono::steady_clock::now();
            while (!job_queue.empty() && job_queue.top().scheduled_time <= current_time) {
                JobDescriptor descriptor = job_queue.top();
                job_queue.pop();

                lock.unlock();
                descriptor.job();
                lock.lock();

                if (!terminated) {
                    descriptor.scheduled_time += descriptor.period;
                    job_queue.push(descriptor);
                }
            }

            if (!job_queue.empty()) {
                auto next_execution = job_queue.top().scheduled_time;
                auto wait_duration = std::chrono::duration_cast<std::chrono::milliseconds>(next_execution - current_time);
                condition.wait_for(lock, wait_duration);
            }
        }
    }

    std::vector<std::thread> threads;
    std::mutex queue_mutex;
    std::condition_variable condition;
    std::priority_queue<JobDescriptor, std::vector<JobDescriptor>, std::function<bool(JobDescriptor, JobDescriptor)>> job_queue{
        [](const JobDescriptor &first, const JobDescriptor &second) { return first.scheduled_time > second.scheduled_time; }
    };
    bool terminated;
    const int thread_count = 4; // Number of worker threads
};

// Sample job function
void display_notification(const std::string &text) {
    std::cout << text << std::endl;
}

int main() {
    JobDispatcher dispatcher;
    dispatcher.add_job(std::bind(display_notification, "Job A"), std::chrono::milliseconds(1000));
    dispatcher.add_job(std::bind(display_notification, "Job B"), std::chrono::milliseconds(500));

    dispatcher.initialize();

    std::this_thread::sleep_for(std::chrono::seconds(10));

    dispatcher.shutdown();

    return 0;
}

#include <iostream>

// Definition for singly-linked list.
struct Node {
    int data;
    Node *link;
    Node(int x) : data(x), link(NULL) {}
};

bool detectLoop(Node *start) {
    if (start == NULL || start->link == NULL) {
        return false; // No loop if the list is empty or has only one node
    }

    Node *slow = start;
    Node *fast = start;

    while (fast != NULL && fast->link != NULL) {
        slow = slow->link;         // Move slow pointer by one step
        fast = fast->link->link;   // Move fast pointer by two steps

        if (slow == fast) {
            return true; // Loop detected
        }
    }

    return false; // No loop detected
}

int main() {
    // Example usage:
    Node *first = new Node(10);
    Node *second = new Node(20);
    Node *third = new Node(30);
    Node *fourth = new Node(40);

    first->link = second;
    second->link = third;
    third->link = fourth;
    fourth->link = second; // Creating a loop

    if (detectLoop(first)) {
        std::cout << "Loop found." << std::endl;
    } else {
        std::cout << "No loop found." << std::endl;
    }

    // Clean up memory
    delete first;
    delete second;
    delete third;
    delete fourth;

    return 0;
}

#include <iostream>
#include <sstream>
#include <vector>

class CodeEmitter {
public:
    std::string produceMachineCode(TreeNode* node) {
        std::string machineCode = "";
        std::string intermediate = translateToIR(node);
        machineCode = generateFromIR(intermediate);
        return machineCode;
    }

private:
    std::string translateToIR(TreeNode* node) {
        if (node->kind == TreeNode::CONDITIONAL) {
            std::string ir = "";
            ir += translateToIR(node->getChild(0));  // Evaluate condition
            ir += "branch ";
            ir += node->getChild(0)->data;  // Simplified condition expression
            ir += " .then" + std::to_string(labelCounter++) + "\n";
            ir += "jump .else" + std::to_string(labelCounter - 1) + "\n";
            ir += ".then" + std::to_string(labelCounter - 1) + ":\n";
            ir += translateToIR(node->getChild(1));  // True branch body
            ir += ".else" + std::to_string(labelCounter - 1) + ":\n";
            return ir;
        }
        // Handle remaining node kinds analogously
        return "";
    }

    std::string generateFromIR(const std::string& ir) {
        std::string machineCode = "";
        // Transform IR into assembly instructions
        for (const std::string& instruction : tokenize(ir, '\n')) {
            if (instruction.find("branch") != std::string::npos) {
                machineCode += "test ...\n";
                machineCode += "jnz .then" + retrieveLabel(instruction) + "\n";
                machineCode += "jmp .else" + retrieveLabel(instruction) + "\n";
            } else if (instruction.find("jump") != std::string::npos) {
                machineCode += "jmp " + retrieveLabel(instruction) + "\n";
            } else if (instruction.find(".then") != std::string::npos || instruction.find(".else") != std::string::npos) {
                machineCode += instruction + ":\n";
            } else {
                machineCode += instruction + "\n";
            }
        }
        return machineCode;
    }

    std::vector<std::string> tokenize(const std::string& text, char separator) {
        std::vector<std::string> segments;
        std::string segment;
        std::istringstream lineStream(text);
        while (getline(lineStream, segment, separator)) {
            segments.push_back(segment);
        }
        return segments;
    }

    std::string retrieveLabel(const std::string& line) {
        // Extract the label suffix from the line
        return line.substr(line.rfind(' ') + 1);
    }

    int labelCounter = 0;
};

#include <map>

// Erase elements from the map whose mapped values satisfy the given condition
template<typename KeyType, typename ValueType, typename Comparator, typename Alloc, typename UnaryPredicate>
inline void erase_if_value_matches(std::map<KeyType, ValueType, Comparator, Alloc>& data, const UnaryPredicate& condition)
{
    for (auto iter = data.begin(); iter != data.end();)
    {
        if (condition(iter->second))
        {
            iter = data.erase(iter);
        }
        else
        {
            ++iter;
        }
    }
}

#include <unwind.h>
