struct StackTraceContext {
    void** position;
    void** limit;
};

static _Unwind_Reason_Code stack_unwinder(struct _Unwind_Context* ctx, void* param) {
    StackTraceContext* context = static_cast<StackTraceContext*>(param);
    uintptr_t instruction_ptr = _Unwind_GetIP(ctx);
    if (instruction_ptr) {
        if (context->position == context->limit) {
            return _URC_END_OF_STACK;
        } else {
            *(context->position++) = reinterpret_cast<void*>(instruction_ptr);
        }
    }
    return _URC_NO_REASON;
}

void collect_stack_trace(void** storage, size_t max_depth) {
    StackTraceContext ctx = {storage, storage + max_depth};
    _Unwind_Backtrace(stack_unwinder, &ctx);
}

void display_stack_trace() {
    const size_t max_entries = 64;
    void* array[max_entries];
    char** names;

    collect_stack_trace(array, max_entries);
    names = backtrace_symbols(array, max_entries);

    if (names) {
        for (size_t idx = 0; idx < max_entries && names[idx]; ++idx) {
            std::cout << names[idx] << std::endl;
        }
        free(names);
    }
}

void exception_handler(int sig_number) {
    std::cout << "Exception caught: signal " << sig_number << std::endl;
    display_stack_trace();
}

