dcmplx ComplexConv(int count, dcmplx *src, dcmplx *temp)
{
    int    idx;
    dcmplx    acc, result;

    result.real = result.imag = 0.0f;
    asm volatile (
        "movs r3, #0\n\t"
        ".loop:\n\t"
        "vldr s11, [%[src], #4]\n\t"
        "vldr s13, [%[src]]\n\t"
        "vneg.f32 s11, s11\n\t"
        "vldr s15, [%[temp], #4]\n\t"
        "vldr s12, [%[temp]]\n\t"
        "vmul.f32 s14, s15, s13\n\t"
        "vmul.f32 s15, s11, s15\n\t"
        "adds %[src], #8\n\t"
        "vmla.f32 s14, s11, s12\n\t"
        "vnmls.f32 s15, s12, s13\n\t"
        "adds %[temp], #8\n\t"
        "vadd.f32 s1, s1, s14\n\t"
        "vadd.f32 s0, s0, s15\n\t"
        "adds r3, r3, #1\n\t"
        "cmp r3, r0\n\t"
        "bne .loop\n\t"
        "vstr s1, [%[result], #4]\n\t"
        "vstr s0, [%[result]]\n\t"
        : [result]"+r"(result), [src]"+r"(src), [temp]"+r"(temp)
