std::vector<long> fetchCPUStats() {
    std::ifstream inputFile("/proc/stat");
    std::string currentLine;
    std::getline(inputFile, currentLine);
    std::istringstream stream(currentLine);
    std::vector<long> dataPoints;
    std::string buffer;
    stream >> buffer; // Discard the "cpu" identifier
    while (stream >> buffer) {
        dataPoints.push_back(std::stol(buffer));
    }
    return dataPoints;
}

double computeCPUUtilization(const std::vector<long>& earlier, const std::vector<long>& later) {
    long sumEarlier = 0, sumLater = 0;
    for (int index = 0; index < earlier.size(); ++index) {
        sumEarlier += earlier[index];
        sumLater += later[index];
    }
    long overallChange = sumLater - sumEarlier;

    long idleEarlier = earlier[3];
    long idleLater = later[3];
    long idleChange = idleLater - idleEarlier;

    return (1.0 - (idleChange / static_cast<double>(overallChange))) * 100.0;
}

void displayCPUUsage() {
    auto initialSample = fetchCPUStats();
    std::this_thread::sleep_for(std::chrono::seconds(1));
    auto finalSample = fetchCPUStats();
    double percentage = computeCPUUtilization(initialSample, finalSample);
    std::cout << "CPU Load: " << percentage << "%" << std::endl;
}

