bool isVowel(char letter) {
    letter = std::tolower(letter); // Convert to lowercase to handle both uppercase and lowercase vowels
    return letter == 'a' || letter == 'e' || letter == 'i' || letter == 'o' || letter == 'u';
}

std::string stripVowels(const std::string& text) {
    std::string filtered;
    for (char letter : text) {
        if (!isVowel(letter)) {
            filtered += letter;
        }
    }
    return filtered;
}

