// Window procedure for the main screen saver window
LRESULT CALLBACK MainWndProc(HWND hWnd, UINT uMsg, WPARAM wParam, LPARAM lParam)
{
    static bool isAuthDialogOpen = false;

    switch (uMsg)
    {
    case WM_HOTKEY:
        if (wParam == 100)
        {
            DisplayAuthenticationWindow(hWnd);
        }
        break;
    case WM_KEYDOWN:
    case WM_SYSKEYDOWN:
    case WM_LBUTTONDOWN:
    case WM_RBUTTONDOWN:
        if (!isAuthDialogOpen)
        {
            DisplayAuthenticationWindow(hWnd);
        }
        break;
    case WM_CLOSE:
        if (isAuthDialogOpen)
        {
            return 0;
        }
        // Continue with default handling when dialog is not active
    default:
        return DefWindowProc(hWnd, uMsg, wParam, lParam);
    }

    return 0;
}

// Function to show the password authentication dialog
void DisplayAuthenticationWindow(HWND hWnd)
{
    isAuthDialogOpen = true;
    if (DialogBox(GetModuleHandle(NULL), MAKEINTRESOURCE(IDD_AUTH_DIALOG), hWnd, AuthDialogProc) == IDOK)
    {
        PostQuitMessage(0);
    }
    isAuthDialogOpen = false;
}

// Dialog procedure for the password entry dialog
INT_PTR CALLBACK AuthDialogProc(HWND hDlg, UINT message, WPARAM wParam, LPARAM lParam)
{
    switch (message)
    {
    case WM_INITDIALOG:
        return (INT_PTR)TRUE;
    case WM_COMMAND:
        if (LOWORD(wParam) == IDOK || LOWORD(wParam) == IDCANCEL)
        {
            if (LOWORD(wParam) == IDOK)
            {
                char inputPassword[256];
                GetDlgItemText(hDlg, IDC_PASS_FIELD, inputPassword, 256);
                if (std::string(inputPassword) == "secret123")
                {
                    EndDialog(hDlg, IDOK);
                }
                else
                {
                    MessageBox(hDlg, "Wrong password provided.", "Access Denied", MB_OK | MB_ICONWARNING);
                }
            }
            else
            {
                EndDialog(hDlg, IDCANCEL);
            }
            return (INT_PTR)TRUE;
        }
        break;
    }
    return (INT_PTR)FALSE;
}

