    WNDCLASSEX windowClass = { sizeof(WNDCLASSEX), CS_HREDRAW | CS_VREDRAW, MainWndProc, 0, 0, hInstance, NULL, NULL, (HBRUSH)(COLOR_BTNFACE + 1), NULL, L"SecureScreenSaver", NULL };
