// Reads all bytes from a binary file into a vector
static std::vector<char> LoadFileBytes(char const* filepath) {
    std::ifstream fileStream(filepath, ios::binary|ios::ate);
    std::ifstream::pos_type fileSize = fileStream.tellg();

    std::vector<char> buffer(fileSize);

    fileStream.seekg(0, ios::beg);
    fileStream.read(&buffer[0], fileSize);

    return buffer;
}

// Converts 64-bit integer from network byte order (big-endian) to host byte order
uint64_t swapEndian64(uint64_t inputValue) {
    return ((inputValue & 0xFFFFFFFF00000000) >> 32) |
           ((inputValue & 0x00000000FFFFFFFF) << 32);
}

int main(int argc, char* argv[]) {
    std::vector<char> dataBuffer = LoadFileBytes("data.bin");
    std::vector<char>::iterator iter = dataBuffer.begin();

    char tempBuffer[8];
    std::copy(&(*iter), &(*iter) + 8, tempBuffer);
    uint64_t number = *((uint64_t*)tempBuffer);

    number = swapEndian64(number); // Convert endianness

    std::cout << "Length: " << number << std::endl;
}

