template<typename Type>
struct compare_entries : public std::binary_function<Type, Type, bool>
{
    bool operator()(const Type &first, const Type &second) const
    {
        if(first._expense != second._expense) {
            return second._expense < first._expense;
        } else {
            return first._identifier < second._identifier;
        }
    }
