#include <stdint.h>

// Function to compute the base-2 logarithm of an integer
static inline int logBase2(int value) {
#if defined(__x86_64__) || defined(__i386__)
    // x86 and x86_64 architecture
    int result;
    asm ( "bsr %1, %0\n"
          : "=r"(result)
          : "r" (value)
          : "cc"
    );
    return result;
#elif defined(__arm__) || defined(__aarch64__)
    // ARM and AArch64 architecture
    if (value == 0) return -1; // Handle the case where value is 0
    int result;
    asm ( "clz %0, %1\n"
          : "=r"(result)
          : "r" (value)
    );
    return 31 - result;
#else
    // Fallback to a portable C++ implementation
    if (value == 0) return -1; // Handle the case where value is 0
    int exponent = 0;
    while ((value >> exponent) > 1) {
        exponent++;
    }
    return exponent;
#endif
}

