// Structure to hold 2D coordinates
struct coordinate  
{  
    double x_val, y_val;  
};

__global__ void computeCoordinates(coordinate* device_coords)  
{  
    // Only the first thread in the grid updates the values
    if (threadIdx.x == 0 && threadIdx.y == 0)
    {  
        device_coords->x_val = 200.0;  
        device_coords->y_val = 200.0;    
    }
}  

int main()  
{  
    // Allocate host memory for a single coordinate
    coordinate *host_coords = (coordinate*)malloc(sizeof(coordinate));  
    host_coords->x_val = 50.0;   
    host_coords->y_val = 50.0;    

    // Allocate device memory
    coordinate *device_coords;  
    cudaMalloc((void**)&device_coords, sizeof(coordinate));  

    // Copy data from host to device
    cudaMemcpy(device_coords, host_coords, sizeof(coordinate), cudaMemcpyHostToDevice);  

    // Define kernel launch configuration
    dim3 block_dim(8, 8);  
    dim3 grid_dim(1, 1);  

    // Launch the CUDA kernel
    computeCoordinates<<<grid_dim, block_dim>>>(device_coords);  

    // Wait for GPU operations to complete
    cudaDeviceSynchronize();  

    // Copy result back to host
    cudaMemcpy(host_coords, device_coords, sizeof(coordinate), cudaMemcpyDeviceToHost);    
    std::cout << host_coords->x_val << " " << host_coords->y_val << std::endl;

    // Clean up allocated memory
    cudaFree(device_coords);
    free(host_coords);

    return 0;
}

