#include <cuda_runtime.h>
#include <iostream>

// Kernel function to read from texture and write to output array
__global__ void textureReadKernel(cudaTextureObject_t texObject, float *resultBuffer, int imgWidth, int imgHeight) {
    int pixelX = blockIdx.x * blockDim.x + threadIdx.x;
    int pixelY = blockIdx.y * blockDim.y + threadIdx.y;

    if (pixelX < imgWidth && pixelY < imgHeight) {
        float sampleValue = tex2D<float>(texObject, pixelX, pixelY);
        resultBuffer[pixelY * imgWidth + pixelX] = sampleValue;
    }
}

int main() {
    // Device memory pointers
    float *d_inputData;
    cudaTextureObject_t textureObject;
    float *d_resultData;

    // Image dimensions
    int columns = 256;
    int rows = 256;

    // Allocate device memory
    size_t bytes = columns * rows * sizeof(float);
    cudaMalloc(&d_inputData, bytes);
    cudaMalloc(&d_resultData, bytes);

    // Initialize input data (zero-fill for demonstration)
    cudaMemset(d_inputData, 0, bytes);

    // Resource descriptor for linear texture
    cudaResourceDesc resDesc;
    memset(&resDesc, 0, sizeof(resDesc));
    resDesc.resType = cudaResourceTypeLinear;
    resDesc.res.linear.devPtr = d_inputData;
    resDesc.res.linear.desc.f = cudaChannelFormatKindFloat;
    resDesc.res.linear.desc.x = 32; // 32-bit floating point per channel
    resDesc.res.linear.sizeInBytes = bytes;

    // Texture descriptor settings
    cudaTextureDesc texDesc;
    memset(&texDesc, 0, sizeof(texDesc));
    texDesc.readMode = cudaReadModeElementType;
    texDesc.addressMode[0] = cudaAddressModeClamp;
    texDesc.addressMode[1] = cudaAddressModeClamp;
    texDesc.filterMode = cudaFilterModeLinear;

    // Create CUDA texture object
    cudaCreateTextureObject(&textureObject, &resDesc, &texDesc, NULL);

    // Thread block and grid configuration
    dim3 threadsPerBlock(16, 16);
    dim3 blocksPerGrid((columns + threadsPerBlock.x - 1) / threadsPerBlock.x,
                       (rows + threadsPerBlock.y - 1) / threadsPerBlock.y);

    // Launch the kernel
    textureReadKernel<<<blocksPerGrid, threadsPerBlock>>>(textureObject, d_resultData, columns, rows);
    cudaDeviceSynchronize();

    // Transfer results back to host
    float *h_result = new float[columns * rows];
    cudaMemcpy(h_result, d_resultData, bytes, cudaMemcpyDeviceToHost);

    // Cleanup resources
    cudaDestroyTextureObject(textureObject);
    cudaFree(d_inputData);
    cudaFree(d_resultData);
    delete[] h_result;

    return 0;
}

