struct Vector3D {
    double a, b, c;

    Vector3D(double a, double b, double c) : a(a), b(b), c(c) {}

    double distanceFrom(const Vector3D &other) const {
        return std::sqrt((a - other.a) * (a - other.a) +
                         (b - other.b) * (b - other.b) +
                         (c - other.c) * (c - other.c));
    }
};

bool sortByA(const Vector3D &v1, const Vector3D &v2) {
    return v1.a < v2.a;
}

bool sortByB(const Vector3D &v1, const Vector3D &v2) {
    return v1.b < v2.b;
}

bool sortByC(const Vector3D &v1, const Vector3D &v2) {
    return v1.c < v2.c;
}

double smaller(double x, double y) {
    return (x < y) ? x : y;
}

double exhaustiveSearch(std::vector<Vector3D> &coords, int count) {
    double smallest = std::numeric_limits<double>::max();
    for (int i = 0; i < count; ++i) {
        for (int j = i + 1; j < count; ++j) {
            double dist = coords[i].distanceFrom(coords[j]);
            if (dist < smallest) {
                smallest = dist;
            }
        }
    }
    return smallest;
}

double nearPlane(std::vector<Vector3D> &boundary, int boundarySize, double threshold) {
    double currentMin = threshold;

    for (int i = 0; i < boundarySize; ++i) {
        for (int j = i + 1; j < boundarySize && (boundary[j].b - boundary[i].b) < currentMin; ++j) {
            double dist = boundary[i].distanceFrom(boundary[j]);
            if (dist < currentMin) {
                currentMin = dist;
            }
        }
    }
    return currentMin;
}

double recursiveClosest(std::vector<Vector3D> &sortedByA, std::vector<Vector3D> &sortedByB, int size) {
    if (size <= 3) return exhaustiveSearch(sortedByA, size);

    int centerIndex = size / 2;
    Vector3D centerPoint = sortedByA[centerIndex];

    std::vector<Vector3D> leftGroup, rightGroup;
    for (int i = 0; i < size; ++i) {
        if (sortedByB[i].a <= centerPoint.a) {
            leftGroup.push_back(sortedByB[i]);
        } else {
            rightGroup.push_back(sortedByB[i]);
        }
    }

    double leftDist = recursiveClosest(sortedByA, leftGroup, centerIndex);
    double rightDist = recursiveClosest(sortedByA, rightGroup, size - centerIndex);

    double minDistance = smaller(leftDist, rightDist);

    std::vector<Vector3D> middleStrip;
    for (int i = 0; i < size; ++i) {
        if (std::abs(sortedByB[i].a - centerPoint.a) < minDistance) {
            middleStrip.push_back(sortedByB[i]);
        }
    }

    return smaller(minDistance, nearPlane(middleStrip, middleStrip.size(), minDistance));
}

double findMinimumDistance(std::vector<Vector3D> &coordinates, int totalPoints) {
    std::vector<Vector3D> byA = coordinates;
    std::vector<Vector3D> byB = coordinates;

    std::sort(byA.begin(), byA.end(), sortByA);
    std::sort(byB.begin(), byB.end(), sortByB);

    return recursiveClosest(byA, byB, totalPoints);
}

int main() {
    std::vector<Vector3D> dataPoints = {{2, 3, 4}, {12, 30, 40}, {40, 50, 60}, {5, 1, 2}, {12, 10, 3}};
    int count = dataPoints.size();
    std::cout << "The shortest distance is " << findMinimumDistance(dataPoints, count) << std::endl;
    return 0;
}

