// 3D vector structure with basic operations
struct Vector3D {
    float r, g, b;

    Vector3D() : r(0), g(0), b(0) {}
    Vector3D(float x, float y, float z) : r(x), g(y), b(z) {}

    Vector3D operator+(const Vector3D& v) const { return Vector3D(r + v.r, g + v.g, b + v.b); }
    Vector3D operator-(const Vector3D& v) const { return Vector3D(r - v.r, g - v.g, b - v.b); }
    Vector3D operator*(float scale) const { return Vector3D(r * scale, g * scale, b * scale); }
    Vector3D operator/(float scale) const { return Vector3D(r / scale, g / scale, b / scale); }

    float dotProduct(const Vector3D& v) const { return r * v.r + g * v.g + b * v.b; }
    Vector3D crossProduct(const Vector3D& v) const { 
        return Vector3D(g * v.b - b * v.g, b * v.r - r * v.b, r * v.g - g * v.r); 
    }
    float magnitude() const { return std::sqrt(r * r + g * g + b * b); }
    Vector3D normalized() const { return *this / magnitude(); }
};

