    RGBColor operator+(const RGBColor& c) const { return RGBColor(red + c.red, green + c.green, blue + c.blue); }
    RGBColor operator*(float factor) const { return RGBColor(red * factor, green * factor, blue * factor); }
    RGBColor operator*(const RGBColor& c) const { return RGBColor(red * c.red, green * c.green, blue * c.blue); }
};

