std::string disassemble_bytes(uint8_t *data, size_t len, uint64_t baseAddr) {
    csh cs_handle;
    cs_insn *instructions;
    size_t instruction_count;
    std::string result;

    if (cs_open(CS_ARCH_X86, CS_MODE_64, &cs_handle) == CS_ERR_OK) {
        // Disassemble all available instructions
        instruction_count = cs_disasm(cs_handle, data, len, baseAddr, 0, &instructions);
        if (instruction_count > 0) {
            for (size_t idx = 0; idx < instruction_count; idx++) {
                char line[1024];
                int written = snprintf(line, sizeof(line), "0x%" PRIx64 ":\t%s\t\t%s\n", 
                                       instructions[idx].address, 
                                       instructions[idx].mnemonic, 
                                       instructions[idx].op_str);
                result.append(line, written);
            }
            cs_free(instructions, instruction_count);
        } else {
            result = "DISASM_ERROR: Unable to decode provided byte sequence!\n";
        }
    } else {
        result = "INIT_ERROR: Could not initialize Capstone disassembler!\n";
    }

    cs_close(&cs_handle);
    return result;
}

#include <Python.h>
