// Alternative in-memory module storage using std::map instead of unordered_map
std::map<std::string, std::string> cached_modules;

// Custom module loader with modified function name and variable names
extern "C" PyObject* load_module_from_memory(PyObject* self, PyObject* args) {
    PyObject* module_name;
    if (!PyArg_ParseTuple(args, "O", &module_name)) {
        return nullptr;
    }

    const char* name_str = PyUnicode_AsUTF8(module_name);
    if (name_str == nullptr) {
        return nullptr;
    }

    auto search = cached_modules.find(name_str);
    if (search == cached_modules.end()) {
        PyErr_Format(PyExc_ImportError, "Module '%s' not available in memory", name_str);
        return nullptr;
    }

    const std::string& source_code = search->second;
    PyObject* new_module = PyModule_New(name_str);
    if (new_module == nullptr) {
        return nullptr;
    }

    if (PyRun_String(source_code.c_str(), Py_file_input, new_module->ob_dict, new_module->ob_dict) == nullptr) {
        Py_DECREF(new_module);
        return nullptr;
    }

    return new_module;
}

// Function to register the custom loader with different naming
extern "C" void install_custom_importer() {
    PyObject* meta_path_list = PySys_GetObject("meta_path");
    if (meta_path_list == nullptr) {
        return;
    }

    PyObject* loader_instance = PyCFunction_NewEx(&PyCFunctionDef{
        (char*)"memory_loader",
        (PyCFunction)load_module_from_memory,
        nullptr,
        nullptr
    }, nullptr);

    if (loader_instance != nullptr) {
        PyList_Insert(meta_path_list, 0, loader_instance);
        Py_DECREF(loader_instance);
    }
}

// Example usage with modified structure and comments
int main() {
    Py_Initialize();

    // Insert a sample module into memory
    cached_modules["sample_lib"] = R"(
def greet():
    return "Greetings from sample_lib!"
)";

    // Install our custom importer mechanism
    install_custom_importer();

    // Attempt to import the embedded module
    PyObject* imported_module = PyImport_ImportModule("sample_lib");
    if (imported_module == nullptr) {
        PyErr_Print();
        return 1;
    }

    // Retrieve and invoke a function from the loaded module
    PyObject* greet_function = PyObject_GetAttrString(imported_module, "greet");
    if (greet_function == nullptr) {
        PyErr_Print();
        return 1;
    }

    PyObject* output_value = PyObject_CallObject(greet_function, nullptr);
    if (output_value == nullptr) {
        PyErr_Print();
        return 1;
    }

    const char* message_text = PyUnicode_AsUTF8(output_value);
    if (message_text == nullptr) {
        return 1;
    }

    std::cout << "Output: " << message_text << std::endl;

    Py_DECREF(imported_module);
    Py_DECREF(greet_function);
    Py_DECREF(output_value);

    Py_Finalize();
    return 0;
}

#include <QObject>
#include <QQmlListProperty>
