class MyObject : public QObject {
        Q_OBJECT
        Q_PROPERTY(QQmlListProperty<int> dataItems READ getDataItems NOTIFY dataItemsChanged)

    public:
        MyObject(QObject *parent = nullptr) : QObject(parent) {}

        QQmlListProperty<int> getDataItems() {
            return QQmlListProperty<int>(this, this, &MyObject::addItem, &MyObject::itemCount, &MyObject::getItemAt, &MyObject::removeAllItems);
        }

    signals:
        void dataItemsChanged();

    private:
        QList<int> m_data;

        static void addItem(QQmlListProperty<int> *prop, int value) {
            MyObject *instance = qobject_cast<MyObject *>(prop->object);
            if (instance) {
                instance->m_data.append(value);
                emit instance->dataItemsChanged();
            }
        }

        static int itemCount(QQmlListProperty<int> *prop) {
            MyObject *instance = qobject_cast<MyObject *>(prop->object);
            return instance ? instance->m_data.size() : 0;
        }

        static int getItemAt(QQmlListProperty<int> *prop, int idx) {
            MyObject *instance = qobject_cast<MyObject *>(prop->object);
            return instance ? instance->m_data.at(idx) : 0;
        }

        static void removeAllItems(QQmlListProperty<int> *prop) {
            MyObject *instance = qobject_cast<MyObject *>(prop->object);
            if (instance) {
                instance->m_data.clear();
                emit instance->dataItemsChanged();
            }
        }
    };

