// Find the longest contiguous subarray that sums to the given target
vector<int> locateLongestSubsequenceWithTotal(const vector<int>& arr, int desiredSum) {
    int left = 0, right = 0, runningSum = 0;
    int bestLength = 0, bestStartIndex = -1;

    while (right < arr.size()) {
        runningSum += arr[right];

        // Shrink window if sum exceeds target
        while (runningSum > desiredSum && left <= right) {
            runningSum -= arr[left];
            left++;
        }

        // Check if current window matches target sum
        if (runningSum == desiredSum) {
            int currentLength = right - left + 1;
            if (currentLength > bestLength) {
                bestLength = currentLength;
                bestStartIndex = left;
            }
        }

        right++;
    }

    if (bestStartIndex == -1) return {};
    return vector<int>(arr.begin() + bestStartIndex, arr.begin() + bestStartIndex + bestLength);
}

int main() {
    vector<int> data = {1, 2, 3, 4, 5};
    int goalSum = 9;
    vector<int> output = locateLongestSubsequenceWithTotal(data, goalSum);
    for (int value : output) {
        cout << value << " ";
    }
    return 0;
}

