// Structure representing a node in the binary search tree
struct BinaryNode {
    int data;
    BinaryNode* leftChild;
    BinaryNode* rightChild;
    BinaryNode(int val) : data(val), leftChild(nullptr), rightChild(nullptr) {}
};

// Inserts a value into the binary search tree
BinaryNode* addNode(BinaryNode* node, int value) {
    if (node == nullptr) {
        return new BinaryNode(value);
    }
    if (value < node->data) {
        node->leftChild = addNode(node->leftChild, value);
    } else if (value > node->data) {
        node->rightChild = addNode(node->rightChild, value);
    }
    return node;
}

// Performs post-order traversal: left, right, root
void displayPostOrder(BinaryNode* node) {
    if (node == nullptr) {
        return;
    }
    displayPostOrder(node->leftChild);   // Explore left subtree
    displayPostOrder(node->rightChild);  // Explore right subtree
    cout << node->data << " ";           // Process current node
}

// Entry point for testing BST insertion and post-order traversal
int main() {
    BinaryNode* rootNode = nullptr;

    // Build the BST by inserting values
    rootNode = addNode(rootNode, 50);
    rootNode = addNode(rootNode, 30);
    rootNode = addNode(rootNode, 20);
    rootNode = addNode(rootNode, 40);
    rootNode = addNode(rootNode, 70);
    rootNode = addNode(rootNode, 60);
    rootNode = addNode(rootNode, 80);

    // Output the post-order traversal result
    cout << "Post-Order Traversal: ";
    displayPostOrder(rootNode);
    cout << endl;

    return 0;
}

