#define STEPS_PER_REVOLUTION 2048
#define MIN_ROTATION 10

// Pin assignments for the stepper motors
const int m1PinA = 2;
const int m1PinB = 3;
const int m1PinC = 4;
const int m1PinD = 5;
const int m2PinA = 6;
const int m2PinB = 7;
const int m2PinC = 8;
const int m2PinD = 9;
const int m3PinA = 10;
const int m3PinB = 11;
const int m3PinC = 12;
const int m3PinD = 13;

// Stepper motor instances and angular positions
Stepper engine1(STEPS_PER_REVOLUTION, m1PinA, m1PinC, m1PinB, m1PinD);
Stepper engine2(STEPS_PER_REVOLUTION, m2PinA, m2PinC, m2PinB, m2PinD);
Stepper engine3(STEPS_PER_REVOLUTION, m3PinA, m3PinC, m3PinB, m3PinD);
int pos1 = 0;
int pos2 = 0;

// Light sensor configuration
const int photoResistorPin = A0;
const int lightThreshold = 0;

void setup() {
  // Initialize speed and initial orientation of the motors
  engine1.setSpeed(5);
  engine2.setSpeed(5);
  engine3.setSpeed(5);

  engine1.step(STEPS_PER_REVOLUTION / 36 * MIN_ROTATION);
  pos1 += MIN_ROTATION;
  engine2.step(-STEPS_PER_REVOLUTION / 36 * MIN_ROTATION);
  pos2 -= MIN_ROTATION;
}

void loop() {
  // Adjust engine3 to find minimum illumination
  int sensorReading = analogRead(photoResistorPin);
  while (sensorReading > lightThreshold) {
    engine3.step(1);
    delay(10);
    sensorReading = analogRead(photoResistorPin);
  }

  // Fine-tune engine1 for optimal light level
  while (pos1 >= 0 && analogRead(photoResistorPin) > lightThreshold) {
    engine1.step(-STEPS_PER_REVOLUTION / 36);
    pos1--;
    delay(10);
  }

  // Fine-tune engine2 for optimal light level
  while (pos2 <= 360 && analogRead(photoResistorPin) > lightThreshold) {
    engine2.step(STEPS_PER_REVOLUTION / 36);
    pos2++;
    delay(10);
  }

  // Final adjustment of engine2 to reach zero light reading
  while (analogRead(photoResistorPin) > lightThreshold) {
    engine2.step(STEPS_PER_REVOLUTION / 36);
    pos2++;
    delay(10);
  }

  // Output final angular positions
  Serial.print("Engine1 position: ");
  Serial.println(pos1);
  Serial.print("Engine2 position: ");
  Serial.println(pos2);
}

