std::mutex print_mutex; // Mutex for safe printing and other shared resources

void sort_partition(std::vector<int>& data, int start, int end) {
    if (start < end) {
        int pivot_value = data[(start + end) / 2];
        int left_index = start;
        int right_index = end;

        while (left_index <= right_index) {
            while (data[left_index] < pivot_value) left_index++;
            while (data[right_index] > pivot_value) right_index--;
            if (left_index <= right_index) {
                std::swap(data[left_index], data[right_index]);
                left_index++;
                right_index--;
            }
        }

        if (start < right_index) {
            sort_partition(data, start, right_index);
        }
        if (left_index < end) {
            sort_partition(data, left_index, end);
        }
    }
}

void parallel_sort(std::vector<int>& data, int start, int end, int cutoff) {
    if (end - start < cutoff) {
        sort_partition(data, start, end);
    } else {
        int pivot_value = data[(start + end) / 2];
        int left_index = start;
        int right_index = end;

        while (left_index <= right_index) {
            while (data[left_index] < pivot_value) left_index++;
            while (data[right_index] > pivot_value) right_index--;
            if (left_index <= right_index) {
                std::swap(data[left_index], data[right_index]);
                left_index++;
                right_index--;
            }
        }

        std::future<void> left_task;
        std::future<void> right_task;

        if (start < right_index) {
            left_task = std::async(std::launch::async, parallel_sort, std::ref(data), start, right_index, cutoff);
        }
        if (left_index < end) {
            right_task = std::async(std::launch::async, parallel_sort, std::ref(data), left_index, end, cutoff);
        }

        if (left_task.valid()) {
            left_task.get();
        }
        if (right_task.valid()) {
            right_task.get();
        }
    }
}

int main() {
    std::vector<int> numbers = {5, 9, 3, 7, 2, 8, 4};
    int cutoff_size = 10; // Threshold to switch to single-threaded quicksort

    std::cout << "Unsorted list: ";
    for (int value : numbers) {
        std::cout << value << " ";
    }
    std::cout << std::endl;

    parallel_sort(numbers, 0, numbers.size() - 1, cutoff_size);

    std::cout << "Sorted list: ";
    for (int value : numbers) {
        std::cout << value << " ";
    }
    std::cout << std::endl;

    return 0;
}

