#include <iostream>
#include <unordered_set>

struct TreeNode {
    int data;
    TreeNode* link; // XOR of left and right child

    TreeNode(int val) : data(val), link(nullptr) {}
};

struct DualDirectionList {
    TreeNode* start;
    TreeNode* end;

    DualDirectionList() : start(nullptr), end(nullptr) {}

    TreeNode* computeXOR(TreeNode* x, TreeNode* y) {
        return reinterpret_cast<TreeNode*>(reinterpret_cast<uintptr_t>(x) ^ reinterpret_cast<uintptr_t>(y));
    }

    void insert(int value) {
        TreeNode* newNode = new TreeNode(value);
        if (!start) {
            start = end = newNode;
            return;
        }
        TreeNode* previousNode = end;
        TreeNode* followingNode = computeXOR(end->link, nullptr);
        end->link = computeXOR(newNode, followingNode);
        newNode->link = computeXOR(previousNode, nullptr);
        end = newNode;
    }

    void invert() {
        TreeNode* current = start;
        TreeNode* previous = nullptr;
        TreeNode* successor = nullptr;

        while (current) {
            successor = computeXOR(previous, current->link);
            current->link = computeXOR(previous, successor);
            previous = current;
            current = successor;
        }

        start = previous; // last node becomes the new start
    }

    void display() {
        TreeNode* current = start;
        TreeNode* previous = nullptr;
        TreeNode* next;

        while (current) {
            std::cout << current->data << " ";
            next = computeXOR(previous, current->link);
            previous = current;
            current = next;
        }
        std::cout << std::endl;
    }
};

int main() {
    DualDirectionList sequence;
    sequence.insert(1);
    sequence.insert(2);
    sequence.insert(3);
    sequence.display(); // 1 2 3

    sequence.invert();
    sequence.display(); // 3 2 1

    return 0;
}

#include <opencv2/opencv.hpp>
#include <iostream>

int main() {
    // Read the source image in grayscale mode
    cv::Mat sourceImg = cv::imread("source.jpg", cv::IMREAD_GRAYSCALE);

    // Set up source and destination points for affine transformation
    cv::Point2f srcPoints[3];
    cv::Point2f dstPoints[3];

    srcPoints[0] = cv::Point2f(0, 0);
    srcPoints[1] = cv::Point2f(sourceImg.cols - 1, 0);
    srcPoints[2] = cv::Point2f(0, sourceImg.rows - 1);

    dstPoints[0] = cv::Point2f(0, 0);
    dstPoints[1] = cv::Point2f(sourceImg.cols * 2 - 1, 0);
    dstPoints[2] = cv::Point2f(0, sourceImg.rows * 2 - 1);

    // Compute the affine transform matrix
    cv::Mat transformMatrix = cv::getAffineTransform(srcPoints, dstPoints);

    // Prepare the output image with doubled dimensions
    cv::Mat resultImg;
    cv::warpAffine(sourceImg, resultImg, transformMatrix, cv::Size(sourceImg.cols * 2, sourceImg.rows * 2), cv::INTER_CUBIC);

    // Write the transformed image to file
    cv::imwrite("result.png", resultImg);

    return 0;
}

