// Determine whether a given integer is a prime number
bool checkPrime(int value) {
    if (value <= 1) {
        return false;
    }
    if (value <= 3) {
        return true;
    }
    if (value % 2 == 0 || value % 3 == 0) {
        return false;
    }
    for (int j = 5; j * j <= value; j += 6) {
        if (value % j == 0 || value % (j + 2) == 0) {
            return false;
        }
    }
    return true;
}

// Display all prime numbers within a specified range
void showPrimes(int lower, int upper) {
    for (int num = lower; num <= upper; num++) {
        if (checkPrime(num)) {
            std::cout << num << " ";
        }
    }
    std::cout << std::endl;
}

