// Returns the fixed address used for accumulator operations
uint16_t getAccumulatorAddress() { return 0xFFFF; }

// Retrieves the next instruction byte as immediate operand
uint16_t getImmediateAddress() { return fetch_next_byte(); }

// Reads two bytes to form an absolute memory address
uint16_t getAbsoluteAddress() { return fetch_next_word(); }

// Gets zero-page address by masking fetched byte to 8 bits
uint16_t getZeroPageAddress() { return fetch_next_byte() & 0xFF; }

// Zero-page address with X register offset (wraps within page)
uint16_t getZeroPageXAddress() { return (fetch_next_byte() + X) & 0xFF; }

// Zero-page address with Y register offset (wraps within page)
uint16_t getZeroPageYAddress() { return (fetch_next_byte() + Y) & 0xFF; }

// Absolute address with X register added
uint16_t getAbsoluteXAddress() { return (fetch_next_word() + X) & 0xFFFF; }

// Absolute address with Y register added
uint16_t getAbsoluteYAddress() { return (fetch_next_word() + Y) & 0xFFFF; }

// Implied addressing - no additional address calculation needed
uint16_t getImpliedAddress() { return 0x0000; }

// Relative branch offset calculated from signed displacement + PC
uint16_t getRelativeAddress() { return static_cast<int8_t>(fetch_next_byte()) + PC; }

// Indirect addressing with X index (pre-indexed)
uint16_t getIndirectXAddress() { 
    uint8_t base = fetch_next_byte() + X;
    return static_cast<uint16_t>(*(reinterpret_cast<uint8_t*>(base))); 
}

// Indirect addressing with Y index (post-indexed)
uint16_t getIndirectYAddress() { 
    uint8_t base = fetch_next_byte();
    return static_cast<uint16_t>(*(reinterpret_cast<uint8_t*>(base))) + Y; 
}

// Absolute indirect addressing (vector lookup)
uint16_t getAbsoluteIndirectAddress() { 
    uint16_t vector = fetch_next_word();
    return *(reinterpret_cast<uint16_t*>(vector)); 
}

#include <iostream>

// Inline assembly routine with compile-time register selection
template <int Value>
void inlineAssemblyRoutine() {
    // Select target register based on input value
    const char* register_list = nullptr;

    if constexpr (Value == 3) {
        register_list = "rcx";
    } else if constexpr (Value == 1) {
        register_list = "rax";
    } else if constexpr (Value == 4) {
        register_list = "rdx";
    } else {
        register_list = "rbx";
    }

    // Execute inline assembly with specified clobbered register
    __asm__ __volatile__(
        "mov %1, %%rax\n\t"
        "add %%rax, %%rax\n\t"
        : /* outputs */
        : "r" (Value) /* inputs */
        : register_list /* clobbers */
    );
}

int main() {
    inlineAssemblyRoutine<3>();
    inlineAssemblyRoutine<1>();
    inlineAssemblyRoutine<4>();
    inlineAssemblyRoutine<2>();

    return 0;
}

