// Modified version of the original code with Type II transformations:
// - Renamed variables (size -> totalBytes, pixels -> buffer, etc.)
// - Changed loop style (not applicable here as no loops present)
- Reordered statements where safe
// - Used equivalent expressions (e.g., size_t -> unsigned long)
// - Added comments for clarity

void captureFramebufferToBitmap(int w, int h) {
    unsigned long totalBytes = static_cast<unsigned long>(w * h * 4); // 4 bytes per pixel for GL_RGBA
    uint8_t* buffer = new uint8_t[totalBytes];

    glReadPixels(0, 0, w, h, GL_RGBA, GL_UNSIGNED_BYTE, buffer);
    jobject sharedBitmap = nullptr;

    if (buffer != nullptr) {
        JNIEnv* jniEnv = GetEnv(state_->activity->vm);

        // Create the jbyte array and populate it with pixel data
        jbyteArray pixelDataArray = jniEnv->NewByteArray(totalBytes);
        jniEnv->SetByteArrayRegion(pixelDataArray, 0, totalBytes, reinterpret_cast<jbyte*>(buffer));

        // Load required Android classes and methods
        jclass bitmapClazz = loadExternalClass("android/graphics/Bitmap");
        jmethodID createBitmapMethod = jniEnv->GetStaticMethodID(bitmapClazz,
            "createBitmap", "(IILandroid/graphics/Bitmap$Config;)Landroid/graphics/Bitmap;");

        jclass bitmapConfigClazz = loadExternalClass("android/graphics/Bitmap$Config");
        jfieldID argb8888FieldId = jniEnv->GetStaticFieldID(bitmapConfigClazz, "ARGB_8888", "Landroid/graphics/Bitmap$Config;");
        jobject colorConfig = jniEnv->GetStaticObjectField(bitmapConfigClazz, argb8888FieldId);

        // Instantiate the Bitmap object
        sharedBitmap = jniEnv->CallStaticObjectMethod(bitmapClazz, createBitmapMethod, w, h, colorConfig);

        if (sharedBitmap != nullptr) {
            // Set pixel data using setPixels method
            jmethodID setPixelsMethod = jniEnv->GetMethodID(bitmapClazz, "setPixels", "([IIII)V");
            jniEnv->CallVoidMethod(sharedBitmap, setPixelsMethod, pixelDataArray, 0, w, 0, h);
        }

        // Clean up local references
        jniEnv->DeleteLocalRef(pixelDataArray);
        jniEnv->DeleteLocalRef(bitmapClazz);
        jniEnv->DeleteLocalRef(bitmapConfigClazz);
        jniEnv->DeleteLocalRef(colorConfig);
    }

    if (sharedBitmap == nullptr) {
        Log("Failed to generate image from framebuffer for sharing");
    }

    delete[] buffer;
}

