#include <czmq.h>
#include <zmq.h>

bool ZmqSocketWrapper::connectSubscriber(const std::string& endpoint)
{
    m_address = endpoint;
    m_pSocket = zsock_new_sub(endpoint.c_str(), "");

    zmq_pollitem_t pollItems[] = { { (void*)zsock_handle(m_pSocket), 0, ZMQ_POLLIN, 0 } };
    int result = zmq_poll(pollItems, 1, 1000); // Wait for 1 second
    if (result == -1)
    {
        int errCode = zmq_errno();
        printf("zmq_poll failed: %s\n", zmq_strerror(errCode));
        return false;
    }

    if (result == 0)
    {
        printf("Timeout occurred, no connection to %s\n", endpoint.c_str());
        return false;
    }

    return true;
}

