#define WIDTH 128
#define HEIGHT 64
#define RESET_PIN -1
#define I2C_ADDR 0x3C
#define WIFI_CHANNEL 1
#define MAX_BUFFER 1024

Adafruit_SSD1306 oled(WIDTH, HEIGHT, &Wire, RESET_PIN);

void handleIncomingData(const uint8_t *sender_mac, const uint8_t *payload, int length);

uint8_t ringBuffer[MAX_BUFFER];
unsigned int writeIndex = 0;
unsigned int readIndex = 0;
unsigned int bytesReceived = 0;

void initializeESPNow() {
  WiFi.disconnect();
  if (esp_now_init() == ESP_OK) {
    Serial.println("ESPNow initialized successfully");
  } else {
    Serial.println("ESPNow initialization failed");
    ESP.restart();
  }
}

void setupAccessPoint() {
  const char AP_NAME[] = "Slave_1";
  if (!WiFi.softAP(AP_NAME, "Slave_1_Password", WIFI_CHANNEL, 0)) {
    Serial.println("Failed to configure Access Point.");
    ESP.restart();
  } else {
    Serial.print("Access Point configured successfully. SSID: ");
    Serial.println(AP_NAME);
    Serial.print("Channel used: ");
    Serial.println(WiFi.channel());
  }
}

void setup() {
  Serial.begin(115200);
  WiFi.mode(WIFI_AP);
  setupAccessPoint();
  initializeESPNow();
  esp_now_register_recv_cb(handleIncomingData);

  if (!oled.begin(SSD1306_SWITCHCAPVCC, I2C_ADDR)) {
    Serial.println(F("OLED display allocation error"));
    while (true); // Halt execution
  }
  oled.clearDisplay();
}

void handleIncomingData(const uint8_t *sender_mac, const uint8_t *payload, int length) {
    char macAddress[18];
    snprintf(macAddress, sizeof(macAddress), "%02x:%02x:%02x:%02x:%02x:%02x",
             sender_mac[0], sender_mac[1], sender_mac[2], sender_mac[3], sender_mac[4], sender_mac[5]);
    Serial.print("Message received from device: ");
    Serial.println(macAddress);
    Serial.println();

    for (int idx = 0; idx < length; idx++) {
        writeIndex = (writeIndex + 1) % MAX_BUFFER;
        ringBuffer[writeIndex] = payload[idx];

        if (writeIndex == readIndex) {
            readIndex = (readIndex + 1) % MAX_BUFFER;
        }

        bytesReceived++;
    }

    Serial.println("Contents of data buffer after reception:");
    for (int k = 0; k < bytesReceived; k++) {
        Serial.print(ringBuffer[k], HEX);
        Serial.print(" ");
        if ((k + 1) % 16 == 0) {
            Serial.println();
        }
    }

    Wire.beginTransmission(I2C_ADDR);
    for (int j = 0; j < bytesReceived; j++) {
        Wire.write(ringBuffer[j]);
    }
    Wire.endTransmission();

    // Clear the count for next packet
    bytesReceived = 0;
}

