#include <vtkSTLReader.h>
#include <vtkPlane.h>
#include <vtkCutter.h>
#include <vtkPolyDataMapper.h>
#include <vtkActor.h>
#include <vtkRenderer.h>
#include <vtkRenderWindow.h>
#include <vtkRenderWindowInteractor.h>

int main() {
    // Create and configure the STL reader
    vtkSTLReader* modelReader = vtkSTLReader::New();
    modelReader->SetFileName("sample_part.stl");
    modelReader->Update();

    // Define the cutting plane
    vtkPlane* crossSectionPlane = vtkPlane::New();
    crossSectionPlane->SetOrigin(0.0, 0.0, 0.0);
    crossSectionPlane->SetNormal(0.0, 0.0, 1.0);

    // Set up the cutter to intersect the model with the plane
    vtkCutter* sectionCutter = vtkCutter::New();
    sectionCutter->SetCutFunction(crossSectionPlane);
    sectionCutter->SetInputConnection(modelReader->GetOutputPort());

    // Map the cut data to graphics primitives
    vtkPolyDataMapper* sectionMapper = vtkPolyDataMapper::New();
    sectionMapper->SetInputConnection(sectionCutter->GetOutputPort());

    // Create an actor to represent the cut section
    vtkActor* sectionActor = vtkActor::New();
    sectionActor->SetMapper(sectionMapper);

    // Configure the rendering environment
    vtkRenderer* sceneRenderer = vtkRenderer::New();
    sceneRenderer->AddActor(sectionActor);

    vtkRenderWindow* displayWindow = vtkRenderWindow::New();
    displayWindow->AddRenderer(sceneRenderer);

    vtkRenderWindowInteractor* userInteraction = vtkRenderWindowInteractor::New();
    userInteraction->SetRenderWindow(displayWindow);

    // Begin interaction
    userInteraction->Start();

    // Clean up all VTK objects
    modelReader->Delete();
    crossSectionPlane->Delete();
    sectionCutter->Delete();
    sectionMapper->Delete();
    sectionActor->Delete();
    sceneRenderer->Delete();
    displayWindow->Delete();
    userInteraction->Delete();

    return 0;
}

#include <pybind11/pybind11.h>
#include <memory>

namespace py = pybind11;

// Base class for inheritance hierarchy
struct Parent { };

// Derived class inheriting from Parent
struct Child : public Parent { };

// Container class that accepts shared_ptr to Parent
struct Manager {
    void accept(const std::shared_ptr<Parent>& obj) { }
};

// Pybind11 module definition
PYBIND11_MODULE(ModuleExample, mod) {
    // Bind the Parent class with shared_ptr support
    py::class_<Parent, std::shared_ptr<Parent>>(mod, "Parent").def(py::init<>());

    // Bind the Child class, inheriting from Parent
    py::class_<Child, std::shared_ptr<Child>, Parent>(mod, "Child").def(py::init<>());

    // Bind the Manager class with shared_ptr support
    py::class_<Manager, std::shared_ptr<Manager>>(mod, "Manager")
        .def(py::init<>())
        .def("accept", &Manager::accept)
        .def("accept", [](Manager& instance, const std::shared_ptr<Child>& obj) {
            instance.accept(obj);  // Implicit conversion from shared_ptr<Child> to shared_ptr<Parent>
        });
}

