// Helper function to convert std::string or const char* to LPWSTR
LPWSTR getWString(const std::wstring& input, const wchar_t* fallback, const wchar_t*& outBuffer) {
    if (!input.empty()) {
        size_t len = input.length() + 1;
        outBuffer = new wchar_t[len];
        wcscpy_s((wchar_t*)outBuffer, len, input.c_str());
        return (LPWSTR)outBuffer;
    } else {
        outBuffer = nullptr;
        return (LPWSTR)fallback;
    }
}

