                AppendMenu(menuHandle, MF_POPUP | MF_STRING, (uintptr_t)subMenuHandle, winConstructMenuText().c_str());
        }
    }
    else if (menuItemType == item_type_id) {
        unsigned int menuFlags = MF_STRING;

        menuFlags |= (menuItemStatus.checked) ? MF_CHECKED : MF_UNCHECKED;
        menuFlags |= (menuItemStatus.enabled) ? MF_ENABLED : (MF_DISABLED | MF_GRAYED);

        // Convert menu text to wide string
        LPWSTR menuText = getWString(winConstructMenuText(), L"", (const wchar_t*&)tempBuffer);
        if (wcscmp(menuText, L"") != 0)
            AppendMenuW(menuHandle, menuFlags, (uintptr_t)(baseId + minMenuId), menuText);
        else
            AppendMenu(menuHandle, menuFlags, (uintptr_t)(baseId + minMenuId), winConstructMenuText().c_str());
    }

    if (tempBuffer != nullptr) {
        delete[] tempBuffer;
        tempBuffer = nullptr;
    }
}

