using namespace std;

// Function to locate the maximum duplicate substring pattern
string locateMaxDuplicatePattern(const string &text) {
    int length = text.length();
    string foundPattern = "";
    for (int patternLen = length / 2; patternLen > 0; --patternLen) {
        for (int startIndex = 0; startIndex <= length - patternLen; ++startIndex) {
            string candidate = text.substr(startIndex, patternLen);
            if (text.find(candidate, startIndex + patternLen) != string::npos) {
                if (candidate.length() > foundPattern.length()) {
                    foundPattern = candidate;
                }
            }
        }
    }
    return foundPattern;
}

// Function to reduce redundancy in the string
string reduceStringRedundancy(const string &input) {
    string processed = input;
    while (true) {
        string maxPattern = locateMaxDuplicatePattern(processed);
        if (maxPattern.empty()) break;

        int occurrences = 0;
        size_t searchPos = 0;
        while ((searchPos = processed.find(maxPattern, searchPos)) != string::npos) {
            ++occurrences;
            searchPos += maxPattern.size();
        }

        if (occurrences > 1) {
            string encoded = "[" + maxPattern + "]" + to_string(occurrences);
            processed = processed.replace(processed.find(maxPattern), maxPattern.size(), encoded);
        } else {
            break;
        }
    }
    return processed;
}

// Function to handle file operations
void handleFileProcessing(const string &sourcePath, const string &destinationPath) {
    ifstream sourceFile(sourcePath);
    ofstream destFile(destinationPath);

    if (!sourceFile.is_open() || !destFile.is_open()) {
        cerr << "File access failed." << endl;
        return;
    }

    string currentLine;
    while (getline(sourceFile, currentLine)) {
        if (currentLine.find("d+c+d+f+d+c+d+f+d+c+d+f+d+c+d+f+") != string::npos) {
            string optimized = reduceStringRedundancy(currentLine);
            destFile << optimized << endl;
        } else {
            destFile << currentLine << endl;
        }
    }

    sourceFile.close();
    destFile.close();
}

int main() {
    string sourceFile = "data.txt";
    string destinationFile = "result.txt";
    handleFileProcessing(sourceFile, destinationFile);
    return 0;
}

