using namespace std;

// Binary tree node definition
struct TreeNode {
    int value;
    TreeNode* leftChild;
    TreeNode* rightChild;
    TreeNode(int v) : value(v), leftChild(nullptr), rightChild(nullptr) {}
};

// Binary Search Tree implementation
class BinarySearchTree {
public:
    TreeNode* head;
    BinarySearchTree() : head(nullptr) {}

    void add(int val) {
        head = insertIntoTree(head, val);
    }

    void removeValue(int val) {
        head = removeFromTree(head, val);
    }

    void inOrderDisplay() {
        displayInOrder(head);
        cout << endl;
    }

    void preOrderDisplay() {
        displayPreOrder(head);
        cout << endl;
    }

    void postOrderDisplay() {
        displayPostOrder(head);
        cout << endl;
    }

private:
    TreeNode* insertIntoTree(TreeNode* node, int val) {
        if (node == nullptr) {
            return new TreeNode(val);
        }
        if (val < node->value) {
            node->leftChild = insertIntoTree(node->leftChild, val);
        } else if (val > node->value) {
            node->rightChild = insertIntoTree(node->rightChild, val);
        }
        return node;
    }

    TreeNode* findMinimum(TreeNode* node) {
        TreeNode* current = node;
        while (current && current->leftChild != nullptr) {
            current = current->leftChild;
        }
        return current;
    }

    TreeNode* removeFromTree(TreeNode* node, int val) {
        if (node == nullptr) {
            return node;
        }
        if (val < node->value) {
            node->leftChild = removeFromTree(node->leftChild, val);
        } else if (val > node->value) {
            node->rightChild = removeFromTree(node->rightChild, val);
        } else {
            if (node->leftChild == nullptr) {
                TreeNode* successor = node->rightChild;
                delete node;
                return successor;
            } else if (node->rightChild == nullptr) {
                TreeNode* predecessor = node->leftChild;
                delete node;
                return predecessor;
            }
            TreeNode* temp = findMinimum(node->rightChild);
            node->value = temp->value;
            node->rightChild = removeFromTree(node->rightChild, temp->value);
        }
        return node;
    }

    void displayInOrder(TreeNode* node) {
        if (node != nullptr) {
            displayInOrder(node->leftChild);
            cout << node->value << " ";
            displayInOrder(node->rightChild);
        }
    }

    void displayPreOrder(TreeNode* node) {
        if (node != nullptr) {
            cout << node->value << " ";
            displayPreOrder(node->leftChild);
            displayPreOrder(node->rightChild);
        }
    }

    void displayPostOrder(TreeNode* node) {
        if (node != nullptr) {
            displayPostOrder(node->leftChild);
            displayPostOrder(node->rightChild);
            cout << node->value << " ";
        }
    }
};

int main() {
    BinarySearchTree bst;
    bst.add(50);
    bst.add(30);
    bst.add(20);
    bst.add(40);
    bst.add(70);
    bst.add(60);
    bst.add(80);

    cout << "Inorder traversal: ";
    bst.inOrderDisplay();

    cout << "Preorder traversal: ";
    bst.preOrderDisplay();

    cout << "Postorder traversal: ";
    bst.postOrderDisplay();

    cout << "Delete 20: ";
    bst.removeValue(20);
    bst.inOrderDisplay();

    cout << "Delete 30: ";
    bst.removeValue(30);
    bst.inOrderDisplay();

    cout << "Delete 50: ";
    bst.removeValue(50);
    bst.inOrderDisplay();

    return 0;
}

