    float threshold;
    int favorite;
};

vector<GameCard> cardDatabase;

void LoadCards() {
    int index = 0;
    int innerIndex = 0;
    char buffer[64] = {0};
    for (innerIndex = 0; innerIndex < 4; innerIndex++) {
        GameCard newCard;
        sprintf(buffer, "Card %d", index);
        newCard.name = buffer;
        newCard.threshold = 2.50f;
        newCard.groupSize = 10;
        newCard.favorite = 0;
        for (index = 0; index < 4; index++) {
            CardPriceData pData;
            pData.price = index * 1.5f;
            pData.edition = index + 1;
            pData.rarity = index % 3;
            sprintf(buffer, "Date entry %d", index);
            pData.date = buffer;
            newCard.prices.push_back(pData);
        }
        newCard.priceCount = newCard.prices.size();
        cardDatabase.push_back(newCard);
    }
}

void encodePriceData(const vector<CardPriceData>& data, vector<unsigned char>& output) {
    for (const auto& item : data) {
        // Encode each field sequentially
        memcpy(&output[output.size()], &item.price, sizeof(item.price));
        output.resize(output.size() + sizeof(item.price));

        size_t dateStringLength = item.date.length();
        memcpy(&output[output.size()], &dateStringLength, sizeof(dateStringLength));
        output.resize(output.size() + sizeof(dateStringLength));

        memcpy(&output[output.size()], item.date.c_str(), dateStringLength);
        output.resize(output.size() + dateStringLength);

        memcpy(&output[output.size()], &item.edition, sizeof(item.edition));
        output.resize(output.size() + sizeof(item.edition));

        memcpy(&output[output.size()], &item.rarity, sizeof(item.rarity));
        output.resize(output.size() + sizeof(item.rarity));
    }
}

void decodePriceData(const unsigned char* input, size_t inputSize, vector<CardPriceData>& result) {
    size_t position = 0;
    while (position < inputSize) {
        CardPriceData record;
        memcpy(&record.price, &input[position], sizeof(record.price));
        position += sizeof(record.price);

        size_t dateStringLength;
        memcpy(&dateStringLength, &input[position], sizeof(dateStringLength));
        position += sizeof(dateStringLength);

        record.date = string(reinterpret_cast<const char*>(&input[position]), dateStringLength);
        position += dateStringLength;

        memcpy(&record.edition, &input[position], sizeof(record.edition));
        position += sizeof(record.edition);

        memcpy(&record.rarity, &input[position], sizeof(record.rarity));
        position += sizeof(record.rarity);

        result.push_back(record);
    }
}

int StoreCards() {
    int status;
    int cardIndex = 0;
    int priceCount = 0;
    char tempQuery[128] = {0};

    int maxQueries = 7, queryBufferLength = 512;

    sqlite3_stmt *statement;
    sqlite3 *database;

    status = sqlite3_open("gamecards.db", &database);

    if (status) {
        printf("Failed to connect to database\n");
        return -1;
    }
    printf("Database connection established\n");

    char createTableSQL[] = "CREATE TABLE IF NOT EXISTS Cards (Name TEXT, PriceInfo BLOB, PriceCount NUMERIC, Threshold NUMERIC, Favorite NUMERIC);";

    status = sqlite3_exec(database, createTableSQL, 0, 0, 0);
    if (status) {
        printf("Table creation failed: %s\n", sqlite3_errmsg(database));
        return -1;
    }

    for (cardIndex = 0; cardIndex < cardDatabase.size(); cardIndex++) {
        vector<unsigned char> blobBuffer;
        encodePriceData(cardDatabase[cardIndex].prices, blobBuffer);

        char sql[512] = {0};
        sprintf(sql, "INSERT INTO Cards (Name, PriceInfo, PriceCount, Threshold, Favorite) VALUES('%s', ?, %d, %f, %d)",
            cardDatabase[cardIndex].name.c_str(),
            cardDatabase[cardIndex].priceCount,
            cardDatabase[cardIndex].threshold,
            cardDatabase[cardIndex].favorite);

        sqlite3_prepare_v2(database, sql, -1, &statement, NULL);
        sqlite3_bind_blob(statement, 1, &blobBuffer[0], blobBuffer.size(), SQLITE_STATIC);

        status = sqlite3_step(statement);
        if (status != SQLITE_DONE) {
            printf("Insert operation failed: %s\n", sqlite3_errmsg(database));
        }

        sqlite3_finalize(statement);
    }

    sqlite3_close(database);
    return 0;
}

int main() {
    LoadCards();
    StoreCards();
    return 0;
}

