// Function to decide the winner in a Rock-Paper-Scissors match
std::string decideOutcome(const std::string& firstChoice, const std::string& secondChoice) {
    // Convert inputs to lowercase for case-insensitive comparison
    std::string choice1 = firstChoice;
    std::string choice2 = secondChoice;
    std::transform(choice1.begin(), choice1.end(), choice1.begin(), ::tolower);
    std::transform(choice2.begin(), choice2.end(), choice2.begin(), ::tolower);

    // Compare moves to find the result
    if (choice1 == choice2) {
        return "Draw!";
    } else if (choice1 == "rock") {
        return (choice2 == "scissors") ? "First player wins!" : "Second player wins!";
    } else if (choice1 == "paper") {
        return (choice2 == "rock") ? "First player wins!" : "Second player wins!";
    } else if (choice1 == "scissors") {
        return (choice2 == "paper") ? "First player wins!" : "Second player wins!";
    } else {
        return "Invalid input!";
    }
}

