// Function to add two digit strings
void sumNumbers(char *num1, const char *num2, int size) {
    int carry = 0;
    for (int idx = size - 1; idx >= 0; --idx) {
        int temp_sum = num1[idx] + num2[idx] - '0' + carry;
        num1[idx] = temp_sum % 10 + '0';
        carry = temp_sum / 10;
    }
}

