#include <iostream>
#include <vector>
#include <unordered_set>

// Define a literal type alias
using Literal = int;
using Clause = std::vector<Literal>;
using Formula = std::vector<Clause>;

// Implement a SAT solver class
class SATSolver {
public:
    SATSolver(const Formula& inputFormula) : formula(inputFormula), variableCount(0) {
        // Determine the number of variables from the formula
        for (const auto& clause : formula) {
            for (Literal literal : clause) {
                variableCount = std::max(variableCount, std::abs(literal));
            }
        }
        // Initialize assignment array: 0 = unassigned, 1 = true, -1 = false
        assignment.resize(variableCount + 1, 0);
    }

    bool solve() {
        return solveBacktrack(1);
    }

    void displayAssignment() const {
        for (int i = 1; i <= variableCount; ++i) {
            if (assignment[i] == 1) {
                std::cout << "x" << i << " = true ";
            } else if (assignment[i] == -1) {
                std::cout << "x" << i << " = false ";
            }
        }
        std::cout << std::endl;
    }

private:
    Formula formula;
    int variableCount;
    std::vector<int> assignment;

    bool solveBacktrack(int currentVar) {
        // Base case: all variables assigned
        if (currentVar > variableCount) {
            return checkSatisfaction();
        }

        // Try assigning true to current variable
        assignment[currentVar] = 1;
        if (solveBacktrack(currentVar + 1)) {
            return true;
        }

        // Try assigning false to current variable
        assignment[currentVar] = -1;
        if (solveBacktrack(currentVar + 1)) {
            return true;
        }

        // Backtrack: reset assignment and return failure
        assignment[currentVar] = 0;
        return false;
    }

    bool checkSatisfaction() const {
        for (const auto& clause : formula) {
            bool clauseIsTrue = false;
            for (Literal literal : clause) {
                if (literal > 0) {
                    if (assignment[literal] == 1) {
                        clauseIsTrue = true;
                        break;
                    }
                } else {
                    if (assignment[-literal] == -1) {
                        clauseIsTrue = true;
                        break;
                    }
                }
            }
            if (!clauseIsTrue) {
                return false;
            }
        }
        return true;
    }
};

int main() {
    // Example formula: (x1 OR x2) AND (NOT x1 OR x3)
    Formula testFormula = {
        {1, 2},
        {-1, 3}
    };

    SATSolver solver(testFormula);
    if (solver.solve()) {
        std::cout << "The formula is satisfiable. Solution: ";
        solver.displayAssignment();
    } else {
        std::cout << "The formula is unsatisfiable." << std::endl;
    }

    return 0;
}

