// Optimized kernel for copying data using shared memory tiling
__global__ void optimized_data_transfer(float *destination, const float *source) {
    __shared__ float buffer[BLOCK_SIZE][BLOCK_SIZE];

    int col = blockIdx.x * BLOCK_SIZE + threadIdx.x;
    int row = blockIdx.y * BLOCK_SIZE + threadIdx.y;
    int pitch = gridDim.x * BLOCK_SIZE;

    // Transfer from global memory to shared memory tile
    buffer[threadIdx.y][threadIdx.x] = source[row * pitch + col];
