                        tensor_b_storage[b * dim_j * dim_k * matrix_dim * matrix_dim + 
                                         j_idx * dim_k * matrix_dim * matrix_dim + 
                                         k_idx * matrix_dim * matrix_dim + 
                                         row * matrix_dim + col] = temp(row, col);
                    }
                }
            }
        }
    }

    // Construct NumPy arrays with appropriate strides
    pybind11::array_t<float> tensor_a_array = pybind11::array_t<float>(
        {batch_size, dim_i, matrix_dim, matrix_dim},
        {dim_i * matrix_dim * matrix_dim * sizeof(float), 
         matrix_dim * matrix_dim * sizeof(float), 
         matrix_dim * sizeof(float), 
         sizeof(float)},
        tensor_a_storage.data()
    );

    pybind11::array_t<float> tensor_b_array = pybind11::array_t<float>(
        {batch_size, dim_j, dim_k, matrix_dim, matrix_dim},
        {dim_j * dim_k * matrix_dim * matrix_dim * sizeof(float), 
         dim_k * matrix_dim * matrix_dim * sizeof(float), 
         matrix_dim * matrix_dim * sizeof(float), 
         matrix_dim * sizeof(float), 
         sizeof(float)},
        tensor_b_storage.data()
    );

    return std::make_pair(tensor_a_array, tensor_b_array);
}

PYBIND11_MODULE(modified_example, m) {
    m.def("generate_tensor_data", &generate_tensor_data, pybind11::return_value_policy::reference);
}

