using ObjectId = std::size_t;

class ObjectRegistry {
public:
    ObjectRegistry() : nextId_(0) {}

    ObjectId spawnObject() {
        return nextId_++;
    }
private:
    ObjectId nextId_;
};

template <typename Type>
class DataStore {
public:
    void store(ObjectId id, const Type& data) {
        storage_[id] = data;
    }

    Type* fetch(ObjectId id) {
        auto iterator = storage_.find(id);
        return iterator != storage_.end() ? &(iterator->second) : nullptr;
    }

private:
    std::unordered_map<ObjectId, Type> storage_;
};

int main() {
    ObjectRegistry registry;
    DataStore<Location> locationStore;
    DataStore<Speed> speedStore;

    ObjectId obj = registry.spawnObject();
    Location loc(30, 40);
    locationStore.store(obj, loc);

    Location* retrievedLoc = locationStore.fetch(obj);

    if (retrievedLoc) {
        std::cout << "Object(" << obj << ") coordinates: (" << retrievedLoc->getX() << "," << retrievedLoc->getY() << ")\n";
    } else {
        std::cout << "Object(" << obj << ") lacks Location data.\n";
    }

    Speed* retrievedSpeed = speedStore.fetch(obj);

    if (retrievedSpeed) {
        std::cout << "Object(" << obj << ") motion: (" << retrievedSpeed->getX() << "," << retrievedSpeed->getY() << ")\n";
    } else {
        std::cout << "Object(" << obj << ") lacks Speed data.\n";
    }

    return 0;
}

