using namespace std;

// Function to exchange two values
void exchange(int &x, int &y) {
    int buffer = x;
    x = y;
    y = buffer;
}

// Partition function used in selection algorithm
int splitArray(vector<int> &data, int start, int end, int pivotPos) {
    int pivotVal = data[pivotPos];
    exchange(data[pivotPos], data[end]); // Move pivot to the end
    int boundary = start;
    for (int idx = start; idx < end; ++idx) {
        if (data[idx] < pivotVal) {
            exchange(data[idx], data[boundary]);
            ++boundary;
        }
    }
    exchange(data[end], data[boundary]); // Place pivot in correct position
    return boundary;
}

// Selection algorithm to find k-th smallest element
int selectKth(vector<int> &data, int start, int end, int k) {
    if (start == end) // If only one element remains
        return data[start]; // Return that element

    // Choose a random pivot position
    srand(time(0));
    int pivotPos = start + rand() % (end - start + 1);

    pivotPos = splitArray(data, start, end, pivotPos);

    // Check where the pivot ended up
    if (k == pivotPos)
        return data[k];
    else if (k < pivotPos)
        return selectKth(data, start, pivotPos - 1, k);
    else
        return selectKth(data, pivotPos + 1, end, k);
}

// Function to compute the median of an array
int getMedian(vector<int> &data) {
    int size = data.size();
    if (size == 0)
        throw invalid_argument("Input vector must not be empty.");
    if (size % 2 == 0)
        throw invalid_argument("Vector length must be odd for median calculation.");

    int midIndex = (size - 1) / 2;
    return selectKth(data, 0, size - 1, midIndex);
}

int main() {
    vector<int> numbers = {12, 3, 5, 7, 4, 19, 26};
    try {
        int medianValue = getMedian(numbers);
        cout << "The median is: " << medianValue << endl;
    } catch (const invalid_argument &err) {
        cout << err.what() << endl;
    }
    return 0;
}

extern "C" {
    #include <cuda_runtime.h>

    __global__ void vectorAddKernel(float *result, const float *inputA, const float *inputB, int size) {
        int index = threadIdx.x;
        if (index < size) {
            result[index] = inputA[index] + inputB[index];
        }
    }

    void performVectorAddition(float *hostOutput, const float *hostInput1, const float *hostInput2, int length) {
        float *deviceInput1, *deviceInput2, *deviceOutput;
        cudaMalloc(&deviceInput1, length * sizeof(float));
        cudaMalloc(&deviceInput2, length * sizeof(float));
        cudaMalloc(&deviceOutput, length * sizeof(float));

        cudaMemcpy(deviceInput1, hostInput1, length * sizeof(float), cudaMemcpyHostToDevice);
        cudaMemcpy(deviceInput2, hostInput2, length * sizeof(float), cudaMemcpyHostToDevice);

        vectorAddKernel<<<1, length>>>(deviceOutput, deviceInput1, deviceInput2, length);

        cudaMemcpy(hostOutput, deviceOutput, length * sizeof(float), cudaMemcpyDeviceToHost);

        cudaFree(deviceInput1);
        cudaFree(deviceInput2);
        cudaFree(deviceOutput);
    }
}

#include <iostream>
#include <vector>
#include <string>
#include <algorithm>

// Helper function to compare two suffixes up to length p
bool compareSuffixes(const std::string &inputText, int pos1, int pos2, int len) {
    if (pos1 + len == inputText.length()) return false;
    if (pos2 + len == inputText.length()) return true;
    return inputText[pos1 + len] < inputText[pos2 + len];
}

// Constructs suffix array using prefix doubling method
std::vector<int> constructSuffixArray(const std::string &input) {
    int size = input.length();
    std::vector<int> suffixes(size);
    for (int idx = 0; idx < size; ++idx) suffixes[idx] = idx;

    std::vector<int> ranks(size);
    for (int idx = 0; idx < size; ++idx) ranks[idx] = input[idx];

    for (int step = 1; step < size; step *= 2) {
        std::sort(suffixes.begin(), suffixes.end(), [&](int a, int b) {
            return ranks[a] < ranks[b] || (ranks[a] == ranks[b] && compareSuffixes(input, a, b, step));
        });

        std::vector<int> updatedRanks(size);
        updatedRanks[suffixes[0]] = 0;
        for (int idx = 1; idx < size; ++idx) {
            updatedRanks[suffixes[idx]] = updatedRanks[suffixes[idx - 1]] + 
                (compareSuffixes(input, suffixes[idx - 1], suffixes[idx], step) ? 1 : 0);
        }
        ranks = updatedRanks;
    }

    return suffixes;
}

// Builds LCP (Longest Common Prefix) array from suffix array
std::vector<int> computeLCP(const std::string &input, const std::vector<int> &suffixes) {
    int n = input.length();
    std::vector<int> rank(n);
    for (int i = 0; i < n; ++i) rank[suffixes[i]] = i;

    std::vector<int> lcp(n, 0);
    for (int i = 0, height = 0; i < n; ++i, height = std::max(height - 1, 0)) {
        if (rank[i] == n - 1) {
            height = 0;
            continue;
        }
        int j = suffixes[rank[i] + 1];
        while (i + height < n && j + height < n && input[i + height] == input[j + height]) ++height;
        lcp[rank[i]] = height;
    }

    return lcp;
}

// Finds the longest common substring among multiple strings
std::string findLongestCommon(const std::vector<std::string> &words) {
    std::string merged = "";
    for (const auto &word : words) {
        merged += word + "#";
    }

    std::vector<int> suffixArray = constructSuffixArray(merged);
    std::vector<int> lcpArray = computeLCP(merged, suffixArray);

    int bestLength = 0;
    int bestPosition = 0;
    for (int i = 1; i < lcpArray.size(); ++i) {
        if (lcpArray[i] > bestLength) {
            bestLength = lcpArray[i];
            bestPosition = i;
        }
    }

    if (bestLength == 0) return "";

    return merged.substr(suffixArray[bestPosition], bestLength);
}

int main() {
    std::vector<std::string> testStrings = {"flower", "flow", "flight"};
    std::string commonPart = findLongestCommon(testStrings);
    if (commonPart.empty()) {
        std::cout << "No common substring detected." << std::endl;
    } else {
        std::cout << "Longest common substring: " << commonPart << std::endl;
    }
    return 0;
}

