// Function to print all prime numbers up to a given limit using Sieve of Eratosthenes
void showPrimes(int limit) {
    vector<bool> primeFlag(limit + 1, true);
    primeFlag[0] = primeFlag[1] = false; // 0 and 1 are not prime

    for (int divisor = 2; divisor * divisor <= limit; divisor++) {
        if (primeFlag[divisor]) {
            for (int multiple = divisor * divisor; multiple <= limit; multiple += divisor) {
                primeFlag[multiple] = false;
            }
        }
    }

    cout << "Prime numbers up to " << limit << ": ";
    for (int num = 2; num <= limit; num++) {
        if (primeFlag[num]) {
            cout << num << " ";
        }
    }
    cout << endl;
}

int main() {
    int value;
    cout << "Enter an upper bound: ";
    cin >> value;

    showPrimes(value);

    return 0;
}

