// Enumerate network computers using Windows Shell API
void DisplayNetworkMachines()
{
    HRESULT result = CoInitializeEx(NULL, COINIT_APARTMENTTHREADED);
    if (SUCCEEDED(result))
    {
        IShellItem* shellItem = NULL;
        result = SHGetKnownFolderItem(FOLDERID_NetworkFolder, KF_FLAG_DEFAULT, NULL, IID_IShellItem, (void**)&shellItem);
        if (SUCCEEDED(result) && shellItem)
        {
            IEnumShellItems* enumerator = NULL;
            result = shellItem->BindToHandler(NULL, BHID_EnumItems, IID_IEnumShellItems, (void**)&enumerator);
            if (SUCCEEDED(result) && enumerator)
            {
                IShellItem* currentItem = NULL;
                while (S_OK == enumerator->Next(1, &currentItem, NULL))
                {
                    PWSTR displayName = NULL;
                    if (SUCCEEDED(currentItem->GetDisplayName(SIGDN_NORMALDISPLAY, &displayName)) && displayName)
                    {
                        std::wcout << L"Machine: " << displayName << std::endl;
                        CoTaskMemFree(displayName);
                    }
                    currentItem->Release();
                }
                enumerator->Release();
            }
            shellItem->Release();
        }
        CoUninitialize();
    }
}

