class SoundExAlgorithm {
public:
    std::pair<std::string, std::string> transform(const std::string& input) {
        std::string mainForm, altForm;
        // Simplified phonetic encoding logic
        for (char ch : input) {
            char lowerChar = tolower(ch);
            switch (lowerChar) {
                case 'b': mainForm += 'b'; altForm += 'b'; break;
                case 'c': mainForm += 'k'; altForm += 's'; break;
                case 'd': mainForm += 't'; altForm += 't'; break;
                case 'f': mainForm += 'f'; altForm += 'f'; break;
                case 'g': mainForm += 'k'; altForm += 'j'; break;
                case 'h': mainForm += 'h'; altForm += 'h'; break;
                case 'j': mainForm += 'j'; altForm += 'j'; break;
                case 'k': mainForm += 'k'; altForm += 'k'; break;
                case 'l': mainForm += 'l'; altForm += 'l'; break;
                case 'm': mainForm += 'm'; altForm += 'm'; break;
                case 'n': mainForm += 'n'; altForm += 'n'; break;
                case 'p': mainForm += 'p'; altForm += 'p'; break;
                case 'q': mainForm += 'k'; altForm += 'k'; break;
                case 'r': mainForm += 'r'; altForm += 'r'; break;
                case 's': mainForm += 's'; altForm += 's'; break;
                case 't': mainForm += 't'; altForm += 't'; break;
                case 'v': mainForm += 'f'; altForm += 'f'; break;
                case 'w': mainForm += 'w'; altForm += 'w'; break;
                case 'x': mainForm += 'ks'; altForm += 'ks'; break;
                case 'y': mainForm += 'y'; altForm += 'y'; break;
                case 'z': mainForm += 's'; altForm += 's'; break;
                default: mainForm += 'a'; altForm += 'a'; break;
            }
        }
        return {mainForm, altForm};
    }
};

int main() {
    SoundExAlgorithm sa;
    std::string termA = "Smith";
    std::string termB = "Smythe";

    auto result1 = sa.transform(termA);
    auto result2 = sa.transform(termB);

    std::cout << "Input A: " << termA << " -> " << result1.first << " / " << result1.second << std::endl;
    std::cout << "Input B: " << termB << " -> " << result2.first << " / " << result2.second << std::endl;

    if (result1.first == result2.first || result1.second == result2.second) {
        std::cout << "The terms sound alike." << std::endl;
    } else {
        std::cout << "The terms do not sound alike." << std::endl;
    }

    return 0;
}

