#include <cuda_runtime.h>
#include <iostream>
#include <cmath>

#define TILE_DIM 16

__global__ void calculatePairwiseDistances(float *inputX, float *inputY, float *outputD, int rowsX, int colsY) {
    __shared__ float Y_shared[TILE_DIM * 128];

    int rowX = blockIdx.x;
    int colY_start = blockIdx.y * TILE_DIM + threadIdx.x;
    int colY_end = colY_start + TILE_DIM;

    // Copy Y tile into shared memory
    for (int idx = colY_start; idx < colY_end && idx < colsY; idx++) {
        for (int dim = 0; dim < 128; dim++) {
            Y_shared[(idx - colY_start) * 128 + dim] = inputY[idx * 128 + dim];
        }
    }
    __syncthreads();

    // Compute squared Euclidean distances
    for (int idx = colY_start; idx < colY_end && idx < colsY; idx++) {
        float dist_sq = 0.0f;
        for (int d = 0; d < 128; d++) {
            float diff = inputX[rowX * 128 + d] - Y_shared[(idx - colY_start) * 128 + d];
            dist_sq += diff * diff;
        }
        outputD[rowX * colsY + idx] = sqrtf(dist_sq);
    }
}

int main() {
    int numPointsA = 1000;
    int numPointsB = 1000;
    size_t memSizeX = numPointsA * 128 * sizeof(float);
    size_t memSizeY = numPointsB * 128 * sizeof(float);
    size_t memSizeOut = numPointsA * numPointsB * sizeof(float);

    float *hostX = new float[numPointsA * 128];
    float *hostY = new float[numPointsB * 128];
    float *hostOut = new float[numPointsA * numPointsB];

    // Seed random values for host arrays
    for (int i = 0; i < numPointsA * 128; i++) {
        hostX[i] = static_cast<float>(rand()) / RAND_MAX;
    }
    for (int i = 0; i < numPointsB * 128; i++) {
        hostY[i] = static_cast<float>(rand()) / RAND_MAX;
    }

    float *devX, *devY, *devOut;
    cudaMalloc(&devX, memSizeX);
    cudaMalloc(&devY, memSizeY);
    cudaMalloc(&devOut, memSizeOut);

    cudaMemcpy(devX, hostX, memSizeX, cudaMemcpyHostToDevice);
    cudaMemcpy(devY, hostY, memSizeY, cudaMemcpyHostToDevice);

    dim3 blockSize(TILE_DIM, 1);
    dim3 gridSize((numPointsB + TILE_DIM - 1) / TILE_DIM, numPointsA);

    calculatePairwiseDistances<<<gridSize, blockSize>>>(devX, devY, devOut, numPointsA, numPointsB);

    cudaMemcpy(hostOut, devOut, memSizeOut, cudaMemcpyDeviceToHost);

