// Function to print Fibonacci sequence up to n terms
void printFibonacciSeries(int count) {
    if (count <= 0) {
        cout << "Please enter a positive integer." << endl;
        return;
    }

    int first = 0, second = 1, next = 0;

    for (int index = 1; index <= count; ++index) {
        // Outputs the first two terms.
        if (index == 1) {
            cout << first << ", ";
            continue;
        }
        if (index == 2) {
            cout << second << ", ";
            continue;
        }
        next = first + second;
        first = second;
        second = next;
        cout << next;
        if (index < count) {
            cout << ", ";
        }
    }
}

int main() {
    int terms;
    cout << "Enter the number of terms: ";
    cin >> terms;

    printFibonacciSeries(terms);

    return 0;
}

