#include <immintrin.h>

// Transpose an 8x8 matrix of doubles using AVX-512 intrinsics
void MatrixTranspose(double* input, double* output) {
  // Load 8 rows of 8 double values each
  __m512d r0 = _mm512_load_pd(input + 0 * 8);
  __m512d r1 = _mm512_load_pd(input + 1 * 8);
  __m512d r2 = _mm512_load_pd(input + 2 * 8);
  __m512d r3 = _mm512_load_pd(input + 3 * 8);
  __m512d r4 = _mm512_load_pd(input + 4 * 8);
  __m512d r5 = _mm512_load_pd(input + 5 * 8);
  __m512d r6 = _mm512_load_pd(input + 6 * 8);
  __m512d r7 = _mm512_load_pd(input + 7 * 8);

  // Interleave low and high elements between pairs of rows
  __m512d t0 = _mm512_unpacklo_pd(r0, r1);
  __m512d t1 = _mm512_unpackhi_pd(r0, r1);
  __m512d t2 = _mm512_unpacklo_pd(r2, r3);
  __m512d t3 = _mm512_unpackhi_pd(r2, r3);
  __m512d t4 = _mm512_unpacklo_pd(r4, r5);
  __m512d t5 = _mm512_unpackhi_pd(r4, r5);
  __m512d t6 = _mm512_unpacklo_pd(r6, r7);
  __m512d t7 = _mm512_unpackhi_pd(r6, r7);

  // Permute elements within vectors to prepare for final transposition
  __m512d u0 = _mm512_permutex2var_pd(t0, _mm512_setr_epi64(0, 1, 8, 9, 4, 5, 12, 13), t2);
  __m512d u1 = _mm512_permutex2var_pd(t0, _mm512_setr_epi64(2, 3, 10, 11, 6, 7, 14, 15), t2);
  __m512d u2 = _mm512_permutex2var_pd(t1, _mm512_setr_epi64(0, 1, 8, 9, 4, 5, 12, 13), t3);
  __m512d u3 = _mm512_permutex2var_pd(t1, _mm512_setr_epi64(2, 3, 10, 11, 6, 7, 14, 15), t3);
  __m512d u4 = _mm512_permutex2var_pd(t4, _mm512_setr_epi64(0, 1, 8, 9, 4, 5, 12, 13), t6);
  __m512d u5 = _mm512_permutex2var_pd(t4, _mm512_setr_epi64(2, 3, 10, 11, 6, 7, 14, 15), t6);
  __m512d u6 = _mm512_permutex2var_pd(t5, _mm512_setr_epi64(0, 1, 8, 9, 4, 5, 12, 13), t7);
  __m512d u7 = _mm512_permutex2var_pd(t5, _mm512_setr_epi64(2, 3, 10, 11, 6, 7, 14, 15), t7);

  // Combine partial results using mask-based moves instead of full shuffles
  {
    __m512d vec = _mm512_shuffle_f64x2(u0, u4, 0x4e);
    __m512d m0 = _mm512_setr_epi64(0x0000000000000000, 0x0000000000000000, 0xFFFFFFFFFFFFFFFF, 0xFFFFFFFFFFFFFFFF);
    __m512d m4 = _mm512_setr_epi64(0xFFFFFFFFFFFFFFFF, 0xFFFFFFFFFFFFFFFF, 0x0000000000000000, 0x0000000000000000);
    __m512d v0 = _mm512_mask_mov_pd(u0, m0, vec);
    __m512d v4 = _mm512_mask_mov_pd(u4, m4, vec);
  }

  {
    __m512d vec = _mm512_shuffle_f64x2(u1, u5, 0x4e);
    __m512d m1 = _mm512_setr_epi64(0x0000000000000000, 0x0000000000000000, 0xFFFFFFFFFFFFFFFF, 0xFFFFFFFFFFFFFFFF);
    __m512d m5 = _mm512_setr_epi64(0xFFFFFFFFFFFFFFFF, 0xFFFFFFFFFFFFFFFF, 0x0000000000000000, 0x0000000000000000);
    __m512d v1 = _mm512_mask_mov_pd(u1, m1, vec);
    __m512d v5 = _mm512_mask_mov_pd(u5, m5, vec);
  }

  {
    __m512d vec = _mm512_shuffle_f64x2(u2, u6, 0x4e);
    __m512d m2 = _mm512_setr_epi64(0x0000000000000000, 0x0000000000000000, 0xFFFFFFFFFFFFFFFF, 0xFFFFFFFFFFFFFFFF);
    __m512d m6 = _mm512_setr_epi64(0xFFFFFFFFFFFFFFFF, 0xFFFFFFFFFFFFFFFF, 0x0000000000000000, 0x0000000000000000);
    __m512d v2 = _mm512_mask_mov_pd(u2, m2, vec);
    __m512d v6 = _mm512_mask_mov_pd(u6, m6, vec);
  }

  {
    __m512d vec = _mm512_shuffle_f64x2(u3, u7, 0x4e);
    __m512d m3 = _mm512_setr_epi64(0x0000000000000000, 0x0000000000000000, 0xFFFFFFFFFFFFFFFF, 0xFFFFFFFFFFFFFFFF);
    __m512d m7 = _mm512_setr_epi64(0xFFFFFFFFFFFFFFFF, 0xFFFFFFFFFFFFFFFF, 0x0000000000000000, 0x0000000000000000);
    __m512d v3 = _mm512_mask_mov_pd(u3, m3, vec);
    __m512d v7 = _mm512_mask_mov_pd(u7, m7, vec);
  }

  // Store the transposed rows to the output buffer
  _mm512_store_pd(output + 0 * 8, v0);
  _mm512_store_pd(output + 1 * 8, v1);
  _mm512_store_pd(output + 2 * 8, v2);
  _mm512_store_pd(output + 3 * 8, v3);
  _mm512_store_pd(output + 4 * 8, v4);
  _mm512_store_pd(output + 5 * 8, v5);
  _mm512_store_pd(output + 6 * 8, v6);
  _mm512_store_pd(output + 7 * 8, v7);
}

