// CUDA kernel for character processing with shared memory accumulation
__global__ void processTextData(const char* inputString, int* outputArray, int totalElements) {
    __shared__ int buffer[ALIGNED_SIZE]; // ALIGNED_SIZE = (THREAD_COUNT + 1) * sizeof(int)

    int threadIndex = threadIdx.x;
    int blockIndex = blockIdx.x;
    int absoluteIndex = threadIndex + blockIndex * blockDim.x;

    if (absoluteIndex < totalElements) {
        // Initialize shared memory location for this thread
        buffer[threadIndex * (ALIGNED_SIZE / THREAD_COUNT)] = 0;

        // Iterate through all characters for accumulation
        for (int j = 0; j < totalElements; j++) {
            // Accumulate character value into shared memory
            buffer[threadIndex * (ALIGNED_SIZE / THREAD_COUNT)] = 
                buffer[threadIndex * (ALIGNED_SIZE / THREAD_COUNT)] + inputString[absoluteIndex];

            // Compare accumulated value against threshold and write result
            if (buffer[threadIndex * (ALIGNED_SIZE / THREAD_COUNT)] > CRITICAL_VALUE) {
                outputArray[absoluteIndex] = 1;
            }
        }
    }
}

