namespace tensorflow {

class PrivacyPreservingProcessOp : public OpKernel {
 public:
  explicit PrivacyPreservingProcessOp(OpKernelConstruction* context)
      : OpKernel(context) {
    OP_REQUIRES_OK(context, context->GetAttr("party_id", &party_id_));
    OP_REQUIRES_OK(context, context->GetAttr("privacy_budget", &privacy_budget_));
  }

  void Compute(OpKernelContext* context) override {
    // Fetch the input tensor
    const Tensor& source_tensor = context->input(0);

    // Determine output tensor shape from input shape
    TensorShape result_shape(source_tensor.shape());
    Tensor* result_tensor = nullptr;
    OP_REQUIRES_OK(context, context->allocate_output(0, result_shape, &result_tensor));

    if (party_id_ == "client") {
      // Client simply forwards the data unchanged
      *result_tensor = source_tensor;
    } else if (party_id_ == "server") {
      // Server adds Laplacian noise for differential privacy
      float scale_param = 1.0 / privacy_budget_;
      InjectNoise(context, source_tensor, result_tensor, scale_param);
    } else {
      OP_REQUIRES(context, false, errors::InvalidArgument("Unknown party identifier: ", party_id_));
    }
  }

 private:
  void InjectNoise(OpKernelContext* context, const Tensor& source_tensor,
                   Tensor* result_tensor, float scale_param) {
    auto source_flat = source_tensor.flat<float>();
    auto result_flat = result_tensor->flat<float>();

    // Setup random number generation for noise injection
    std::random_device rng;
    std::normal_distribution<float> noise_dist(0.0, scale_param);

    for (size_t idx = 0; idx < source_flat.size(); ++idx) {
      float perturbation = noise_dist(rng);
      result_flat(idx) = source_flat(idx) + perturbation;
    }
  }

  string party_id_;
  float privacy_budget_;
};

REGISTER_KERNEL_BUILDER(Name("PrivacyPreservingProcess").Device(DEVICE_CPU), PrivacyPreservingProcessOp);

