struct TreeNode {
    int value;
    int depth;
    TreeNode* leftChild;
    TreeNode* rightChild;
};

// Function to compute the depth of a subtree
int getDepth(TreeNode* T) {
    if (T == nullptr)
        return 0;
    return T->depth;
}

// Function to allocate and initialize a new tree node
TreeNode* createNode(int value) {
    TreeNode* newNodePtr = new TreeNode();
    newNodePtr->value = value;
    newNodePtr->leftChild = nullptr;
    newNodePtr->rightChild = nullptr;
    newNodePtr->depth = 1; // Newly inserted node starts at leaf level
    return newNodePtr;
}

// Perform a right rotation on the subtree rooted at 'parent'
TreeNode* rotateRight(TreeNode* parent) {
    TreeNode* child = parent->leftChild;
    TreeNode* subtree = child->rightChild;

    // Reconnect nodes after rotation
    child->rightChild = parent;
    parent->leftChild = subtree;

    // Recalculate depths
    parent->depth = std::max(getDepth(parent->leftChild), getDepth(parent->rightChild)) + 1;
    child->depth = std::max(getDepth(child->leftChild), getDepth(child->rightChild)) + 1;

    // New root of the subtree
    return child;
}

// Perform a left rotation on the subtree rooted at 'parent'
TreeNode* rotateLeft(TreeNode* parent) {
    TreeNode* child = parent->rightChild;
    TreeNode* subtree = child->leftChild;

    // Reconnect nodes after rotation
    child->leftChild = parent;
    parent->rightChild = subtree;

    // Recalculate depths
    parent->depth = std::max(getDepth(parent->leftChild), getDepth(parent->rightChild)) + 1;
    child->depth = std::max(getDepth(child->leftChild), getDepth(child->rightChild)) + 1;

    // New root of the subtree
    return child;
}

// Compute balance factor: height(left) - height(right)
int getBalanceFactor(TreeNode* node) {
    if (node == nullptr)
        return 0;
    return getDepth(node->leftChild) - getDepth(node->rightChild);
}

// Insert a value into the AVL tree and maintain balance
TreeNode* addValue(TreeNode* root, int value) {
    // Standard BST insertion
    if (root == nullptr)
        return createNode(value);

    if (value < root->value)
        root->leftChild = addValue(root->leftChild, value);
    else if (value > root->value)
        root->rightChild = addValue(root->rightChild, value);
    else // Duplicate values not permitted
        return root;

    // Update depth of current node
    root->depth = 1 + std::max(getDepth(root->leftChild), getDepth(root->rightChild));

    // Check balance factor
    int balance = getBalanceFactor(root);

    // Left-Left imbalance
    if (balance > 1 && value < root->leftChild->value)
        return rotateRight(root);

    // Right-Right imbalance
    if (balance < -1 && value > root->rightChild->value)
        return rotateLeft(root);

    // Left-Right imbalance
    if (balance > 1 && value > root->leftChild->value) {
        root->leftChild = rotateLeft(root->leftChild);
        return rotateRight(root);
    }

    // Right-Left imbalance
    if (balance < -1 && value < root->rightChild->value) {
        root->rightChild = rotateRight(root->rightChild);
        return rotateLeft(root);
    }

    // Return unchanged node if balanced
    return root;
}

