// Find the longest string in a vector of strings
std::string findMaxString(const std::vector<std::string>& words) {
    if (words.empty()) {
        return "";
    }
    const std::string* maxStr = &words[0];
    for (const std::string& word : words) {
        if (word.size() > maxStr->size()) {
            maxStr = &word;
        }
    }
    return *maxStr;
}

