// Continuously monitor a memory location for changes
void watch_for_modifications(int* target_address) {
    int previous_value = *target_address;
    while (true) {
        int current_value = *target_address;
        if (current_value != previous_value) {
            printf("detected modification!\n");
            previous_value = current_value;
        }
        _mm_pause(); // Insert a pause instruction to hint the processor
    }
}

