#include <iostream>
#include <stdexcept>

template <typename T>
class DynamicArray {
private:
    T* elements;
    size_t count;
    size_t max_capacity;

    // Internal method to expand storage
    void expandStorage(size_t new_capacity) {
        T* fresh_data = new T[new_capacity];
        for (size_t idx = 0; idx < count; ++idx) {
            fresh_data[idx] = elements[idx];
        }
        delete[] elements;
        elements = fresh_data;
        max_capacity = new_capacity;
    }

public:
    // Default constructor
    DynamicArray() : elements(nullptr), count(0), max_capacity(0) {}

    // Destructor
    ~DynamicArray() {
        delete[] elements;
    }

    // Copy constructor
    DynamicArray(const DynamicArray& source) : count(source.count), max_capacity(source.max_capacity) {
        elements = new T[max_capacity];
        for (size_t idx = 0; idx < count; ++idx) {
            elements[idx] = source.elements[idx];
        }
    }

    // Copy assignment operator
    DynamicArray& operator=(const DynamicArray& source) {
        if (this != &source) {
            delete[] elements;
            count = source.count;
            max_capacity = source.max_capacity;
            elements = new T[max_capacity];
            for (size_t idx = 0; idx < count; ++idx) {
                elements[idx] = source.elements[idx];
            }
        }
        return *this;
    }

    // Move constructor
    DynamicArray(DynamicArray&& source) noexcept : elements(source.elements), count(source.count), max_capacity(source.max_capacity) {
        source.elements = nullptr;
        source.count = 0;
        source.max_capacity = 0;
    }

    // Move assignment operator
    DynamicArray& operator=(DynamicArray&& source) noexcept {
        if (this != &source) {
            delete[] elements;
            elements = source.elements;
            count = source.count;
            max_capacity = source.max_capacity;
            source.elements = nullptr;
            source.count = 0;
            source.max_capacity = 0;
        }
        return *this;
    }

    // Access operators
    T& operator[](size_t position) {
        return elements[position];
    }

    const T& operator[](size_t position) const {
        return elements[position];
    }

    T& getAt(size_t position) {
        if (position >= count) {
            throw std::out_of_range("Position out of bounds");
        }
        return elements[position];
    }

    const T& getAt(size_t position) const {
        if (position >= count) {
            throw std::out_of_range("Position out of bounds");
        }
        return elements[position];
    }

    T& firstElement() {
        return elements[0];
    }

    const T& firstElement() const {
        return elements[0];
    }

    T& lastElement() {
        return elements[count - 1];
    }

    const T& lastElement() const {
        return elements[count - 1];
    }

    // Utility functions
    size_t length() const {
        return count;
    }

    size_t storageSize() const {
        return max_capacity;
    }

    bool isEmpty() const {
        return count == 0;
    }

    // Modify array size
    void adjustSize(size_t new_length) {
        if (new_length > max_capacity) {
            expandStorage(new_length);
        }
        count = new_length;
    }

    void append(const T& item) {
        if (count == max_capacity) {
            if (max_capacity == 0) {
                expandStorage(1);
            } else {
                expandStorage(max_capacity * 2);
            }
        }
        elements[count++] = item;
    }

    // Iterator support
    T* start() {
        return elements;
    }

    const T* start() const {
        return elements;
    }

    T* finish() {
        return elements + count;
    }

    const T* finish() const {
        return elements + count;
    }
};

// Demonstration of usage
int main() {
    DynamicArray<int> arr;
    arr.append(10);
    arr.append(20);
    arr.append(30);

    for (int val : arr) {
        std::cout << val << " ";
    }
    std::cout << std::endl;

    std::cout << "Length: " << arr.length() << std::endl;
    std::cout << "Storage: " << arr.storageSize() << std::endl;

    arr.adjustSize(5);
    arr[3] = 40;
    arr[4] = 50;

    for (int val : arr) {
        std::cout << val << " ";
    }
    std::cout << std::endl;

    return 0;
}

#include <Wire.h>
#include <esp_now.h>
#include <WiFi.h>

#define LCD_I2C_ADDR 0x3C
#define MAX_BUFFER 512
#define ESP_NOW_CHAN 0

typedef struct __attribute__((packed)) {
  uint8_t payload[MAX_BUFFER];
  size_t len;
} FrameData;

QueueHandle_t frameQueue;

void onDataRecv(const uint8_t* srcMac, const uint8_t* buf, int bufLen) {
  FrameData incomingFrame;
  memcpy(&incomingFrame, buf, sizeof(incomingFrame));
  xQueueSendFromISR(frameQueue, &incomingFrame, NULL);
}

void setup() {
  Serial.begin(115200);

  // Initialize I2C for interfacing with the microcontroller
  Wire.begin();

  // Setup ESP-NOW protocol
  if (esp_now_init() != ESP_OK) {
    Serial.println("ESP-NOW init failed");
    return;
  }

  // Set up receive callback
  esp_now_register_recv_cb(onDataRecv);

  // Create queue for frame storage
  frameQueue = xQueueCreate(1, sizeof(FrameData));

  // Configure ESP-NOW peer device
  esp_now_peer_info_t peerInfo;
  memcpy(peerInfo.peer_addr, (uint8_t[]){0xDE, 0xAD, 0xBE, 0xEF, 0xAB, 0xCD}, 6); // MAC of second ESP32
  peerInfo.channel = ESP_NOW_CHAN;
  peerInfo.encrypt = false;

  if (esp_now_add_peer(&peerInfo) != ESP_OK) {
    Serial.println("Unable to register ESP-NOW peer");
    return;
  }

  Serial.println("Initialization finished");
}

void loop() {
  FrameData frame;

  // Acquire screen data via I2C from RP2040
  Wire.beginTransmission(LCD_I2C_ADDR);
  Wire.write(0x00); // Starting register
  Wire.endTransmission(false);

  Wire.requestFrom(LCD_I2C_ADDR, MAX_BUFFER);
  frame.len = Wire.readBytes(frame.payload, MAX_BUFFER);

  // Queue frame for transmission
  if (xQueueSend(frameQueue, &frame, portMAX_DELAY) != pdPASS) {
    Serial.println("Buffering error: could not store frame");
  }

  delay(1000); // Update interval
}

#include <iostream>
using namespace std;

struct Node {
    int data;
    Node *link;
    Node(int x) : data(x), link(NULL) {}
};

// Function to detect a cycle in a linked list
bool hasLoop(Node *start) {
    if (start == NULL || start->link == NULL) {
        return false;
    }

    Node *slow = start;
    Node *fast = start->link;

    while (fast != NULL && fast->link != NULL) {
        if (slow == fast) {
            return true;  // Loop detected
        }
        slow = slow->link;        // Advance slow pointer by one node
        fast = fast->link->link;  // Advance fast pointer by two nodes
    }

    return false;  // No loop found
}

// Function to create a linked list with a loop for testing
Node* buildListWithLoop() {
    Node *head = new Node(10);
    head->link = new Node(20);
    head->link->link = new Node(30);
    head->link->link->link = new Node(40);
    head->link->link->link->link = head->link;  // Form a loop
    return head;
}

// Function to verify the loop detection mechanism
void validateLoopDetection() {
    Node *head = buildListWithLoop();
    if (hasLoop(head)) {
        cout << "Loop identified in the linked structure." << endl;
    } else {
        cout << "No loop found in the linked structure." << endl;
    }
}

int main() {
    validateLoopDetection();
    return 0;
}

