#include <immintrin.h>

// Compute derived attributes using SIMD operations
void compute_attributes(float* input_data, float* output_sum, float* output_diff, int length) {
    __m256 vector_x, vector_y, vector_z, vector_p, vector_q;
    for (int index = 0; index < length; index += 8) {
        vector_x = _mm256_loadu_ps(&input_data[index * 3 + 0]);
        vector_y = _mm256_loadu_ps(&input_data[index * 3 + 1]);
        vector_z = _mm256_loadu_ps(&input_data[index * 3 + 2]);

        // Vector arithmetic using AVX instructions
        vector_p = _mm256_add_ps(vector_x, vector_y);
        vector_q = _mm256_sub_ps(vector_x, vector_z);

        _mm256_storeu_ps(&output_sum[index], vector_p);
        _mm256_storeu_ps(&output_diff[index], vector_q);
    }
}

