// Transpose a 2D matrix by swapping rows and columns
vector<vector<int>> transpose(const vector<vector<int>>& inputGrid) {
    int rowCount = inputGrid.size();
    int colCount = inputGrid[0].size();

    vector<vector<int>> resultGrid(colCount, vector<int>(rowCount));

    for (int rowIdx = 0; rowIdx < rowCount; ++rowIdx) {
        for (int colIdx = 0; colIdx < colCount; ++colIdx) {
            resultGrid[colIdx][rowIdx] = inputGrid[rowIdx][colIdx];
        }
    }

    return resultGrid;
}

