// Find the longest common substring between two strings
std::string maxCommonSubstr(const std::string& str1, const std::string& str2) {
    int len1 = str1.size();
    int len2 = str2.size();
    std::vector<std::vector<int>> table(len1 + 1, std::vector<int>(len2 + 1, 0));
    int bestLength = 0;
    int lastPos = -1;

    // Build the DP table
    for (int row = 1; row <= len1; ++row) {
        for (int col = 1; col <= len2; ++col) {
            if (str1[row - 1] == str2[col - 1]) {
                table[row][col] = table[row - 1][col - 1] + 1;
                if (table[row][col] > bestLength) {
                    bestLength = table[row][col];
                    lastPos = row - 1; // Store end index (0-based)
                }
            } else {
                table[row][col] = 0;
            }
        }
    }

    // Extract the substring if found
    if (bestLength > 0) {
        return str1.substr(lastPos - bestLength + 1, bestLength);
    }

    return ""; // No common substring exists
}

int main() {
    std::string text1 = "ABABC";
    std::string text2 = "BABC";
    std::string output = maxCommonSubstr(text1, text2);
    std::cout << "Longest Common Substring: " << output << std::endl;
    return 0;
}

