enum class ChessPiece {
    Empty,       // Empty square
    WhitePawn,
    WhiteRook,
    WhiteKnight,
    WhiteBishop,
    WhiteQueen,
    WhiteKing,
    BlackPawn,
    BlackRook,
    BlackKnight,
    BlackBishop,
    BlackQueen,
    BlackKing
};

class Board {
public:
    Board() {
        setupBoard();
    }

    void setupBoard() {
        // Set up the board with the standard starting position
        grid.fill(ChessPiece::Empty);

        // Place white pieces
        grid[0][0] = grid[0][7] = ChessPiece::WhiteRook;
        grid[0][1] = grid[0][6] = ChessPiece::WhiteKnight;
        grid[0][2] = grid[0][5] = ChessPiece::WhiteBishop;
        grid[0][3] = ChessPiece::WhiteQueen;
        grid[0][4] = ChessPiece::WhiteKing;
        for (int col = 0; col < 8; ++col) {
            grid[1][col] = ChessPiece::WhitePawn;
        }

        // Place black pieces
        grid[7][0] = grid[7][7] = ChessPiece::BlackRook;
        grid[7][1] = grid[7][6] = ChessPiece::BlackKnight;
        grid[7][2] = grid[7][5] = ChessPiece::BlackBishop;
        grid[7][3] = ChessPiece::BlackQueen;
        grid[7][4] = ChessPiece::BlackKing;
        for (int col = 0; col < 8; ++col) {
            grid[6][col] = ChessPiece::BlackPawn;
        }
    }

    void printBoard() const {
        for (int row = 0; row < 8; ++row) {
            for (int col = 0; col < 8; ++col) {
                std::cout << pieceToSymbol(grid[row][col]) << " ";
            }
            std::cout << std::endl;
        }
    }

    bool executeMove(int startRow, int startCol, int endRow, int endCol) {
        if (startRow < 0 || startRow >= 8 || startCol < 0 || startCol >= 8 ||
            endRow < 0 || endRow >= 8 || endCol < 0 || endCol >= 8) {
            std::cerr << "Error: Move out of bounds" << std::endl;
            return false;
        }

        if (grid[startRow][startCol] == ChessPiece::Empty) {
            std::cerr << "Error: No piece at source position" << std::endl;
            return false;
        }

        // Perform the move without validation
        grid[endRow][endCol] = grid[startRow][startCol];
        grid[startRow][startCol] = ChessPiece::Empty;

        return true;
    }

private:
    std::array<std::array<ChessPiece, 8>, 8> grid;

    std::string pieceToSymbol(ChessPiece piece) const {
        switch (piece) {
            case ChessPiece::Empty: return ".";
            case ChessPiece::WhitePawn: return "P";
            case ChessPiece::WhiteRook: return "R";
            case ChessPiece::WhiteKnight: return "N";
            case ChessPiece::WhiteBishop: return "B";
            case ChessPiece::WhiteQueen: return "Q";
            case ChessPiece::WhiteKing: return "K";
            case ChessPiece::BlackPawn: return "p";
            case ChessPiece::BlackRook: return "r";
            case ChessPiece::BlackKnight: return "n";
            case ChessPiece::BlackBishop: return "b";
            case ChessPiece::BlackQueen: return "q";
            case ChessPiece::BlackKing: return "k";
            default: return "?";
        }
    }
};

int main() {
    Board gameBoard;
    gameBoard.printBoard();

    // Example move
    gameBoard.executeMove(1, 0, 2, 0);
    gameBoard.printBoard();

    return 0;
}

#include <windows.h>
#include <dwmapi.h>

LRESULT CALLBACK WindowProcedure(HWND hWnd, UINT message, WPARAM wParam, LPARAM lParam);

int WINAPI WinMain(HINSTANCE hInstance, HINSTANCE hPrevInstance, LPSTR lpCmdLine, int nShowCmd) {
    WNDCLASS wc = {0};
    wc.lpfnWndProc = WindowProcedure;
    wc.hInstance = hInstance;
    wc.lpszClassName = L"CustomFrameWindow";
    RegisterClass(&wc);

    HWND hwnd = CreateWindowEx(0, L"CustomFrameWindow", L"Custom Frame Example", WS_OVERLAPPEDWINDOW,
                               CW_USEDEFAULT, CW_USEDEFAULT, 1024, 768, NULL, NULL, hInstance, NULL);
    ShowWindow(hwnd, nShowCmd);

    MSG message;
    while (GetMessage(&message, NULL, 0, 0)) {
        TranslateMessage(&message);
        DispatchMessage(&message);
    }

    return static_cast<int>(message.wParam);
}

LRESULT CALLBACK WindowProcedure(HWND hwnd, UINT msg, WPARAM wParam, LPARAM lParam) {
    static MARGINS extendedMargins = {-1};
    static HBRUSH windowBrush = CreateSolidBrush(RGB(240, 240, 240));

    switch (msg) {
    case WM_NCCALCSIZE:
        if (wParam != FALSE) {
            NCCALCSIZE_PARAMS* ncParams = reinterpret_cast<NCCALCSIZE_PARAMS*>(lParam);
            ncParams->rgrc[0].top += 40; // Extend title bar area
            return WVR_REDRAW;
        }
        break;

    case WM_NCPAINT:
        {
            HRGN region = reinterpret_cast<HRGN>(wParam);
            HDC dc = GetWindowDC(hwnd);
            RECT windowRect;
            GetWindowRect(hwnd, &windowRect);
            windowRect.bottom = windowRect.top + 40; // Custom title bar height

            // Draw custom control area
            RECT controlRect = {windowRect.right - 60, windowRect.top, windowRect.right, windowRect.top + 40};
            HBRUSH controlBrush = CreateSolidBrush(RGB(180, 220, 255));
            FillRect(dc, &controlRect, controlBrush);
            DeleteObject(controlBrush);

            // Simulate a soft glow effect around the control
            for (int step = 1; step <= 8; step++) {
                RECT glowRect = {controlRect.left - step, controlRect.top - step, 
                                 controlRect.right + step, controlRect.bottom + step};
                HBRUSH glowBrush = CreateSolidBrush(RGB(255, 255, 255 - step * 20));
                FrameRect(dc, &glowRect, glowBrush);
                DeleteObject(glowBrush);
            }

            ReleaseDC(hwnd, dc);
        }
        return 0;

    case WM_NCLBUTTONDOWN:
        if (LOWORD(lParam) >= 964 && LOWORD(lParam) <= 1024 && HIWORD(lParam) >= 0 && HIWORD(lParam) <= 40) {
            MessageBox(hwnd, L"Action Triggered!", L"Notification", MB_ICONINFORMATION | MB_OK);
            return 0;
        }
        break;

    case WM_CREATE:
        DwmExtendFrameIntoClientArea(hwnd, &extendedMargins);
        break;

    case WM_DESTROY:
        PostQuitMessage(0);
        break;

    default:
        return DefWindowProc(hwnd, msg, wParam, lParam);
    }

    return 0;
}

#include <openssl/aes.h>
#include <openssl/evp.h>
#include <string>
#include <vector>

std::string performDecryption(const std::vector<uint8_t>& encryptedData, const std::vector<uint8_t>& secretKey, const std::vector<uint8_t>& initializationVector)
{
    EVP_CIPHER_CTX* context = EVP_CIPHER_CTX_new();
    if (!context) {
        // Error handling for context allocation failure
        return "";
    }

    if (EVP_DecryptInit_ex(context, EVP_aes_256_cbc(), nullptr, secretKey.data(), initializationVector.data()) != 1) {
        EVP_CIPHER_CTX_free(context);
        // Error handling for decryption initialization failure
        return "";
    }

    std::vector<uint8_t> decryptedBuffer(encryptedData.size() + AES_BLOCK_SIZE);
    int processedLength;
    if (EVP_DecryptUpdate(context, decryptedBuffer.data(), &processedLength, encryptedData.data(), encryptedData.size()) != 1) {
        EVP_CIPHER_CTX_free(context);
        // Error handling for decryption update failure
        return "";
    }

    int finalBlockLength;
    if (EVP_DecryptFinal_ex(context, decryptedBuffer.data() + processedLength, &finalBlockLength) != 1) {
        EVP_CIPHER_CTX_free(context);
        // Error handling for final decryption step failure
        return "";
    }

    EVP_CIPHER_CTX_free(context);

    decryptedBuffer.resize(processedLength + finalBlockLength);
    return std::string(decryptedBuffer.begin(), decryptedBuffer.end());
}

