#include <cuda_runtime.h>
#include <iostream>

extern "C" {
    void performCudaMultiplication(int* input1, int* input2, int* result, int length) {
        int* device_input1, * device_input2, * device_result;
        cudaMalloc((void**)&device_input1, length * sizeof(int));
        cudaMalloc((void**)&device_input2, length * sizeof(int));
        cudaMalloc((void**)&device_result, length * sizeof(int));

        cudaMemcpy(device_input1, input1, length * sizeof(int), cudaMemcpyHostToDevice);
        cudaMemcpy(device_input2, input2, length * sizeof(int), cudaMemcpyHostToDevice);

        dim3 blockSize(256);
        dim3 gridSize((length + blockSize.x - 1) / blockSize.x);

        kernelMultiply<<<gridSize, blockSize>>>(device_input1, device_input2, device_result, length);

        cudaMemcpy(result, device_result, length * sizeof(int), cudaMemcpyDeviceToHost);

        cudaFree(device_input1);
        cudaFree(device_input2);
        cudaFree(device_result);
    }

    __global__ void kernelMultiply(int* dataA, int* dataB, int* dataC, int count) {
        int index = blockIdx.x * blockDim.x + threadIdx.x;
        if (index < count) {
            dataC[index] = dataA[index] * dataB[index];
        }
    }
}

