// Convert 64-bit integer from network to host byte order
int64_t networkToHostLongLong(int64_t input) {
    uint32_t highPart = static_cast<uint32_t>(input >> 32);
    uint32_t lowPart = static_cast<uint32_t>(input);

    uint32_t convertedHigh = ntohl(lowPart);
    uint32_t convertedLow = ntohl(highPart);

    return (static_cast<int64_t>(convertedHigh) << 32) | convertedLow;
}

// Convert 64-bit integer from host to network byte order
int64_t hostToNetworkLongLong(int64_t input) {
    uint32_t highPart = static_cast<uint32_t>(input >> 32);
    uint32_t lowPart = static_cast<uint32_t>(input);

    uint32_t convertedHigh = htonl(lowPart);
    uint32_t convertedLow = htonl(highPart);

    return (static_cast<int64_t>(convertedHigh) << 32) | convertedLow;
}

