const int MAX_NODES = 200;

bool checkBipartite(int nodes, vector<vector<int>>& adjList) {
    vector<int> nodeColor(nodes, -1); // -1: uncolored, 0: first group, 1: second group

    for (int idx = 0; idx < nodes; ++idx) {
        if (nodeColor[idx] == -1) {
            nodeColor[idx] = 0;
            queue<int> bfsQueue;
            bfsQueue.push(idx);

            while (!bfsQueue.empty()) {
                int current = bfsQueue.front();
                bfsQueue.pop();

                for (int neighbor : adjList[current]) {
                    if (nodeColor[neighbor] == -1) {
                        nodeColor[neighbor] = 1 - nodeColor[current];
                        bfsQueue.push(neighbor);
                    } else if (nodeColor[neighbor] == nodeColor[current]) {
                        return false;
                    }
                }
            }
        }
    }
    return true;
}

int main() {
    int numNodes, numEdges;
    while (cin >> numNodes && numNodes != 0) {
        cin >> numEdges;
        vector<vector<int>> adjacencyList(numNodes);

        for (int i = 0; i < numEdges; ++i) {
            int u, v;
            cin >> u >> v;
            u--; v--; // Convert to 0-based indexing
            adjacencyList[u].push_back(v);
            adjacencyList[v].push_back(u);
        }

        if (checkBipartite(numNodes, adjacencyList)) {
            cout << "Possible" << endl;
        } else {
            cout << "Not possible" << endl;
        }
    }

    return 0;
}

