std::vector<unsigned char> deriveKeyFromPassword(const std::string& passPhrase, const std::string& saltBytes, int keyLen, int ivLen)
{
    Poco::Crypto::MD5Engine hashEngine;
    std::vector<unsigned char> inputData(passPhrase.begin(), passPhrase.end());
    inputData.insert(inputData.end(), saltBytes.begin(), saltBytes.end());

    std::vector<unsigned char> resultKey;
    int iterationCount = 1;
    while (resultKey.size() < keyLen + ivLen)
    {
        hashEngine.update(inputData);
        std::vector<unsigned char> digestValue = hashEngine.digest();
        resultKey.insert(resultKey.end(), digestValue.begin(), digestValue.end());

        for (size_t idx = 0; idx < passPhrase.size(); ++idx)
        {
            inputData[idx] = inputData[idx] ^ iterationCount;
        }
        iterationCount++;
    }

    return resultKey;
}

