    inputFile.read(fileBuffer.data(), fileSize);

    std::string encryptedData(fileBuffer.begin(), fileBuffer.end());
    std::string saltValue = encryptedData.substr(8, 8);

    std::vector<unsigned char> keyMaterial = deriveKeyFromPassword(PASSWORD, saltValue, 128, 128 / 8);

    std::vector<unsigned char> aesKey(keyMaterial.begin(), keyMaterial.begin() + 16);
    std::vector<unsigned char> initializationVector(keyMaterial.begin() + 16, keyMaterial.begin() + 32);

    Poco::Crypto::CipherFactory& engine = Poco::Crypto::CipherFactory::defaultFactory();
    Poco::Crypto::CipherKey cipherParams("aes-128-cbc", aesKey, initializationVector);

