    while (std::getline(input, line_content)) {
        if (line_content.substr(0, 2) == "v ") {
            Point3D point;
            std::sscanf(line_content.c_str(), "v %f %f %f", &point.x_coord, &point.y_coord, &point.z_coord);
            points.push_back(point);
        }
    }
    return points;
}

