// Determine whether a character is an arithmetic operator
bool isArithmeticOperator(char symbol) {
    return symbol == '+' || symbol == '-' || symbol == '*' || symbol == '/' || symbol == '^';
}

// Retrieve the precedence level of an operator
int getPrecedence(char op) {
    switch (op) {
        case '+':
        case '-':
            return 1;
        case '*':
        case '/':
            return 2;
        case '^':
            return 3;
        default:
            return 0;
    }
}

// Transform an infix expression string into postfix notation
std::string convertInfixToPostfix(const std::string& infixExpr) {
    std::stack<char> operatorStack;
    std::string postfixResult;
    for (char ch : infixExpr) {
        if (std::isdigit(ch)) {
            postfixResult += ch;
        } else if (isArithmeticOperator(ch)) {
            while (!operatorStack.empty() && getPrecedence(operatorStack.top()) >= getPrecedence(ch)) {
                postfixResult += operatorStack.top();
                operatorStack.pop();
            }
            operatorStack.push(ch);
        } else if (ch == '(') {
            operatorStack.push(ch);
        } else if (ch == ')') {
            while (!operatorStack.empty() && operatorStack.top() != '(') {
                postfixResult += operatorStack.top();
                operatorStack.pop();
            }
            if (operatorStack.empty() || operatorStack.top() != '(') {
                throw std::runtime_error("Parentheses mismatch");
            }
            operatorStack.pop();
        }
    }
    while (!operatorStack.empty()) {
        if (operatorStack.top() == '(') {
            throw std::runtime_error("Parentheses mismatch");
        }
        postfixResult += operatorStack.top();
        operatorStack.pop();
    }
    return postfixResult;
}

// Compute the result of a postfix expression
double computePostfix(const std::string& postfixExpr) {
    std::stack<double> valueStack;
    for (char ch : postfixExpr) {
        if (std::isdigit(ch)) {
            valueStack.push(ch - '0');
        } else if (isArithmeticOperator(ch)) {
            if (valueStack.size() < 2) {
                throw std::runtime_error("Malformed expression");
            }
            double operand2 = valueStack.top(); valueStack.pop();
            double operand1 = valueStack.top(); valueStack.pop();
            switch (ch) {
                case '+': valueStack.push(operand1 + operand2); break;
                case '-': valueStack.push(operand1 - operand2); break;
                case '*': valueStack.push(operand1 * operand2); break;
                case '/': 
                    if (operand2 == 0.0) throw std::runtime_error("Division by zero");
                    valueStack.push(operand1 / operand2); 
                    break;
                case '^': valueStack.push(std::pow(operand1, operand2)); break;
            }
        }
    }
    if (valueStack.size() != 1) {
        throw std::runtime_error("Malformed expression");
    }
    return valueStack.top();
}

// Main evaluation function: takes an infix string and returns its numeric value
double calculateExpression(const std::string& expr) {
    std::string postfixForm = convertInfixToPostfix(expr);
    return computePostfix(postfixForm);
}

int main() {
    std::string inputExpression = "3 + 5 * (2 - 4)";
    try {
        double computedValue = calculateExpression(inputExpression);
        std::cout << "Computed Value: " << computedValue << std::endl;
    } catch (const std::exception& ex) {
        std::cerr << "Exception: " << ex.what() << std::endl;
    }
    return 0;
}

