// Compute the average of a vector of numbers
double computeAverage(const std::vector<double>& values) {
    if (values.empty()) {
        throw std::invalid_argument("The collection cannot be empty.");
    }
    return std::accumulate(values.begin(), values.end(), 0.0) / values.size();
}

// Compute the variance given the mean
double computeVariance(const std::vector<double>& values, double avg) {
    double accumulator = 0.0;
    for (double val : values) {
        accumulator += (val - avg) * (val - avg);
    }
    return accumulator / values.size();
}

// Compute the standard deviation
double computeStdDeviation(const std::vector<double>& values) {
    if (values.size() < 2) {
        throw std::invalid_argument("The collection must have at least two elements.");
    }
    double avg = computeAverage(values);
    double var = computeVariance(values, avg);
    return std::sqrt(var);
}

int main() {
    try {
        std::vector<double> data = {1.5, 2.5, 3.0, 4.5, -0.5, 0.75};
        double stddev = computeStdDeviation(data);
        std::cout << "The standard deviation is: " << stddev << std::endl;
    } catch (const std::exception& err) {
        std::cerr << "Exception: " << err.what() << std::endl;
    }
    return 0;
}

