#include <iostream>
#include <cmath>

class ThreeDVector {
public:
    // Constructor
    ThreeDVector(double a = 0.0, double b = 0.0, double c = 0.0) : x(a), y(b), z(c) {}

    // Destructor
    ~ThreeDVector() {}

    // Getter methods
    double getX() const { return x; }
    double getY() const { return y; }
    double getZ() const { return z; }

    // Setter methods
    void setX(double a) { this->x = a; }
    void setY(double b) { this->y = b; }
    void setZ(double c) { this->z = c; }

    // Scale the vector by a factor
    ThreeDVector multiplyByScalar(double factor) const {
        return ThreeDVector(x * factor, y * factor, z * factor);
    }

    // Normalize the vector (make unit length)
    ThreeDVector unitVector() const {
        double magnitude = std::sqrt(x * x + y * y + z * z);
        if (magnitude > 0.0) {
            return ThreeDVector(x / magnitude, y / magnitude, z / magnitude);
        }
        return *this; // Return self if magnitude is zero
    }

    // Add another vector to this one
    ThreeDVector combine(const ThreeDVector& rhs) const {
        return ThreeDVector(x + rhs.x, y + rhs.y, z + rhs.z);
    }

    // Display the vector
    void show() const {
        std::cout << "ThreeDVector(" << x << ", " << y << ", " << z << ")" << std::endl;
    }

private:
    double x, y, z;
};

// Demonstration of usage
int main() {
    ThreeDVector vecA(1.0, 2.0, 3.0);
    ThreeDVector vecB(4.0, 5.0, 6.0);

    std::cout << "vecA: ";
    vecA.show();

    std::cout << "vecB: ";
    vecB.show();

    ThreeDVector scaledVecA = vecA.multiplyByScalar(2.0);
    std::cout << "vecA multiplied by 2.0: ";
    scaledVecA.show();

    ThreeDVector normalizedVecA = vecA.unitVector();
    std::cout << "Normalized vecA: ";
    normalizedVecA.show();

    ThreeDVector combinedVec = vecA.combine(vecB);
    std::cout << "vecA + vecB: ";
    combinedVec.show();

    return 0;
}

