    BinaryNode(int x) : data(x), leftChild(nullptr), rightChild(nullptr) {}
};

// Helper function to determine if two subtrees are mirror images of each other
bool checkMirror(BinaryNode* nodeA, BinaryNode* nodeB) {
    if (nodeA == nullptr && nodeB == nullptr) return true;
    if (nodeA == nullptr || nodeB == nullptr) return false;
    return (nodeA->data == nodeB->data) 
           && checkMirror(nodeA->leftChild, nodeB->rightChild) 
           && checkMirror(nodeA->rightChild, nodeB->leftChild);
}

// Main function to verify if the entire tree is symmetric around its center
bool isTreeSymmetric(BinaryNode* root) {
    return checkMirror(root, root);
}

// Utility function to allocate and initialize a new tree node
BinaryNode* newNode(int value) {
    return new BinaryNode(value);
}

