std::unordered_map<std::string, std::string> extractQueryParameters(const std::string& urlString)
{
    std::unordered_map<std::string, std::string> paramMap;

    // Locate the query string part
    size_t queryStart = urlString.find("?");
    if (queryStart != std::string::npos) {
        std::string queryString = urlString.substr(queryStart + 1);

        // Process each key-value pair separated by '&'
        size_t idx = 0;
        while (idx < queryString.size()) {
            size_t ampersandPos = queryString.find("&", idx);
            if (ampersandPos == std::string::npos)
                ampersandPos = queryString.size();

            std::string segment = queryString.substr(idx, ampersandPos - idx);

            // Extract key and value from the segment
            size_t equalsSign = segment.find("=");
            if (equalsSign != std::string::npos) {
                std::string paramKey = segment.substr(0, equalsSign);
                std::string paramValue = segment.substr(equalsSign + 1);

                // Perform basic URL decoding: replace %20 with space
                size_t encodedSpace = paramValue.find("%20");
                while (encodedSpace != std::string::npos) {
                    paramValue.replace(encodedSpace, 3, " ");
                    encodedSpace = paramValue.find("%20", encodedSpace + 1);
                }

                paramMap[paramKey] = paramValue;
            }

            idx = ampersandPos + 1;
        }
    }

    return paramMap;
}

int main()
{
    std::string url = "http://www.example.com?name=Jane%20Smith&dept=Engineering&location=Los%20Angeles";

    std::unordered_map<std::string, std::string> parsedData = extractQueryParameters(url);

    // Display all extracted parameters
    for (const auto& entry : parsedData) {
        std::cout << entry.first << ": " << entry.second << std::endl;
    }

    return 0;
}

