#define matrixDim 1024
#define threadBlock 16

__global__ void matMulKernel(const float* X, const float* Y, float* Z, int dim, int* counter) {
    int yIdx = blockIdx.y * blockDim.y + threadIdx.y;
    int xIdx = blockIdx.x * blockDim.x + threadIdx.x;

    if (yIdx < dim && xIdx < dim) {
        float accum = 0.0f;
        for (int k = 0; k < dim; ++k) {
            accum += X[yIdx * dim + k] * Y[k * dim + xIdx];
        }
        Z[yIdx * dim + xIdx] = accum;

        atomicAdd(counter, 1);
    }
}

void showProgress(int done, int total) {
    int percent = (done * 100) / total;
    fprintf(stdout, "Completion : %d.%d %%\r", percent / 100, percent % 100);
    fflush(stdout);
}

int main() {
    float *host_X, *host_Y, *host_Z, *dev_X, *dev_Y, *dev_Z;
    int *host_counter, *dev_counter;
    size_t memSize = matrixDim * matrixDim * sizeof(float);
    size_t intSize = sizeof(int);

    // Allocate host memory
    host_X = (float*)malloc(memSize);
    host_Y = (float*)malloc(memSize);
    host_Z = (float*)malloc(memSize);
    host_counter = (int*)malloc(intSize);

    // Initialize matrices with ones
    for (int idx = 0; idx < matrixDim * matrixDim; ++idx) {
        host_X[idx] = 1.0f;
        host_Y[idx] = 1.0f;
        host_Z[idx] = 0.0f;
    }

    // Allocate device memory
    CUDA_CHECK(cudaMalloc(&dev_X, memSize));
    CUDA_CHECK(cudaMalloc(&dev_Y, memSize));
    CUDA_CHECK(cudaMalloc(&dev_Z, memSize));
    CUDA_CHECK(cudaMalloc(&dev_counter, intSize));

    // Transfer data to device
    CUDA_CHECK(cudaMemcpy(dev_X, host_X, memSize, cudaMemcpyHostToDevice));
    CUDA_CHECK(cudaMemcpy(dev_Y, host_Y, memSize, cudaMemcpyHostToDevice));
    CUDA_CHECK(cudaMemcpy(dev_counter, host_counter, intSize, cudaMemcpyHostToDevice));

    // Configure grid and block dimensions
    dim3 blockDims(threadBlock, threadBlock);
    dim3 gridDims((matrixDim + threadBlock - 1) / threadBlock, (matrixDim + threadBlock - 1) / threadBlock);

    // Create CUDA stream
    cudaStream_t stream;
    CUDA_CHECK(cudaStreamCreate(&stream));

    // Compute progress tracking parameters
    int numElements = matrixDim * matrixDim;
    int stepSize = numElements / 100; // Update every 1%

    // Launch kernels iteratively with progress monitoring
    for (int processed = 0; processed < numElements; processed += stepSize) {
        matMulKernel<<<gridDims, blockDims, 0, stream>>>(dev_X, dev_Y, dev_Z, matrixDim, dev_counter);
        CUDA_CHECK(cudaStreamSynchronize(stream));

        // Retrieve current progress from device
        CUDA_CHECK(cudaMemcpy(host_counter, dev_counter, intSize, cudaMemcpyDeviceToHost));
        showProgress(*host_counter, numElements);
    }

    // Ensure final kernel completion
    CUDA_CHECK(cudaStreamSynchronize(stream));

    // Copy results back to host
    CUDA_CHECK(cudaMemcpy(host_Z, dev_Z, memSize, cudaMemcpyDeviceToHost));

    // Cleanup resources
    free(host_X);
    free(host_Y);
    free(host_Z);
    free(host_counter);
    CUDA_CHECK(cudaFree(dev_X));
    CUDA_CHECK(cudaFree(dev_Y));
    CUDA_CHECK(cudaFree(dev_Z));
    CUDA_CHECK(cudaFree(dev_counter));
    CUDA_CHECK(cudaStreamDestroy(stream));

    return 0;
}

