using namespace std;

class Solution {
public:
    vector<string> filterComments(vector<string>& input) {
        vector<string> output;
        bool inside_block = false;
        string buffer;

        for (const string& row : input) {
            if (!inside_block) {
                buffer.clear();
            }

            for (size_t pos = 0; pos < row.length(); ++pos) {
                if (inside_block) {
                    if (pos + 1 < row.size() && row[pos] == '*' && row[pos + 1] == '/') {
                        inside_block = false;
                        pos++; // Skip the closing '/'
                    }
                } else {
                    if (pos + 1 < row.size() && row[pos] == '/' && row[pos + 1] == '*') {
                        inside_block = true;
                        pos++; // Skip the '*'
                    } else if (pos + 1 < row.size() && row[pos] == '/' && row[pos + 1] == '/') {
                        break; // Ignore remaining characters on this line
                    } else {
                        buffer += row[pos];
                    }
                }
            }

            if (!inside_block && !buffer.empty()) {
                output.push_back(buffer);
            }
        }

        return output;
    }
};

