// Compute Euclidean distance between two 3D points
double compute_distance(const std::vector<double>& pt1, const std::vector<double>& pt2) {
    double diff_x = pt1[0] - pt2[0];
    double diff_y = pt1[1] - pt2[1];
    double diff_z = pt1[2] - pt2[2];
    return std::sqrt(diff_x * diff_x + diff_y * diff_y + diff_z * diff_z);
}

// Compute system energy as negative of smallest pairwise distance
double compute_system_energy(const std::vector<std::vector<double>>& locations) {
    double smallest_distance = std::numeric_limits<double>::max();
    for (size_t idx1 = 0; idx1 < locations.size(); ++idx1) {
        for (size_t idx2 = idx1 + 1; idx2 < locations.size(); ++idx2) {
            double current_dist = compute_distance(locations[idx1], locations[idx2]);
            if (current_dist < smallest_distance) {
                smallest_distance = current_dist;
            }
        }
    }
    return -smallest_distance; // Minimize negative value to maximize minimum distance
}

// Generate a uniformly random point on unit sphere surface
std::vector<double> generate_random_point_on_sphere() {
    std::random_device dev;
    std::mt19937 engine(dev());
    std::normal_distribution<> normal_dist(0.0, 1.0);

    double coord_x = normal_dist(engine);
    double coord_y = normal_dist(engine);
    double coord_z = normal_dist(engine);
    double magnitude = std::sqrt(coord_x * coord_x + coord_y * coord_y + coord_z * coord_z);
    return {coord_x / magnitude, coord_y / magnitude, coord_z / magnitude};
}

// Apply small random perturbation and re-normalize to unit sphere
std::vector<double> apply_perturbation(const std::vector<double>& original_point, double magnitude) {
    std::random_device dev;
    std::mt19937 engine(dev());
    std::uniform_real_distribution<> uniform_dist(-magnitude, magnitude);

    std::vector<double> modified_point = original_point;
    for (auto& component : modified_point) {
        component += uniform_dist(engine);
    }

    double length = std::sqrt(modified_point[0] * modified_point[0] +
                              modified_point[1] * modified_point[1] +
                              modified_point[2] * modified_point[2]);
    for (auto& component : modified_point) {
        component /= length;
    }
    return modified_point;
}

// Simulated annealing optimization for point distribution
std::vector<std::vector<double>> find_optimal_points(int count, double start_temp, double decay_factor, int max_steps) {
    std::vector<std::vector<double>> current_points;
    for (int i = 0; i < count; ++i) {
        current_points.push_back(generate_random_point_on_sphere());
    }

    double current_temperature = start_temp;
    for (int step = 0; step < max_steps; ++step) {
        std::vector<std::vector<double>> candidate_points = current_points;
        for (auto& loc : candidate_points) {
            loc = apply_perturbation(loc, 0.1);
        }

        double old_energy = compute_system_energy(current_points);
        double new_energy = compute_system_energy(candidate_points);

        double prob = std::exp((old_energy - new_energy) / current_temperature);

        if (new_energy < old_energy || (static_cast<double>(std::rand()) / RAND_MAX) < prob) {
            current_points = candidate_points;
        }

        current_temperature *= decay_factor;
    }

    return current_points;
}

int main() {
    int num_points = 5;
    double initial_temp = 1.0;
    double cooling_factor = 0.99;
    int total_iterations = 10000;

    std::vector<std::vector<double>> optimized_locations = find_optimal_points(num_points, initial_temp, cooling_factor, total_iterations);

    for (const auto& location : optimized_locations) {
        std::cout << "Location: (" << location[0] << ", " << location[1] << ", " << location[2] << ")\n";
    }

    return 0;
}

