class BaseKernel {
public:
    virtual ~BaseKernel() = default;
    virtual double computeCovariance(double input1, double input2) const = 0;
    virtual std::unique_ptr<BaseKernel> clone() const = 0;
};

class RBFKernel : public BaseKernel {
public:
    RBFKernel(double bandwidth, double amplitude) : m_bandwidth(bandwidth), m_amplitude(amplitude) {}
    RBFKernel(double bandwidth) : m_bandwidth(bandwidth), m_amplitude(1.0) {}

    double computeCovariance(double input1, double input2) const override {
        return m_amplitude * std::exp(-std::norm(input1 - input2) / (m_bandwidth * m_bandwidth));
    }

    std::unique_ptr<BaseKernel> clone() const override {
        return std::make_unique<RBFKernel>(*this);
    }

private:
    double m_bandwidth;
    double m_amplitude;
};

class SumKernel : public BaseKernel {
public:
    SumKernel(std::unique_ptr<BaseKernel> first, std::unique_ptr<BaseKernel> second)
        : firstPart(std::move(first)), secondPart(std::move(second)) {}

    double computeCovariance(double input1, double input2) const override {
        return firstPart->computeCovariance(input1, input2) + secondPart->computeCovariance(input1, input2);
    }

    std::unique_ptr<BaseKernel> clone() const override {
        return std::make_unique<SumKernel>(firstPart->clone(), secondPart->clone());
    }

private:
    std::unique_ptr<BaseKernel> firstPart;
    std::unique_ptr<BaseKernel> secondPart;
};

