class Point2D {
public:
    // Constructor
    Point2D(double a = 0.0, double b = 0.0) : x(a), y(b) {}

    // Accessors (getters)
    double getX() const { return x; }
    double getY() const { return y; }

    // Mutators (setters)
    void setX(double newX) { x = newX; }
    void setY(double newY) { y = newY; }

    // Vector addition
    Point2D operator+(const Point2D& other) const {
        return Point2D(x + other.x, y + other.y);
    }

    // Vector subtraction
    Point2D operator-(const Point2D& other) const {
        return Point2D(x - other.x, y - other.y);
    }

    // Scalar multiplication
    Point2D operator*(double factor) const {
        return Point2D(x * factor, y * factor);
    }

    // Dot product
    double dot(const Point2D& other) const {
        return x * other.x + y * other.y;
    }

    // Magnitude (length) of the vector
    double length() const {
        return std::sqrt(x * x + y * y);
    }

    // Normalized vector (unit vector)
    Point2D unit() const {
        double len = length();
        if (len > 0) {
            return Point2D(x / len, y / len);
        }
        return *this; // Return the original vector if it's a zero vector
    }

private:
    double x, y;
};

// Function to print a Point2D
void displayPoint(const Point2D& p) {
    std::cout << "Point: (" << p.getX() << ", " << p.getY() << ")" << std::endl;
}

