    Point2D p4 = p1 - p2;
    Point2D p5 = p1 * 2.0;
    double innerProduct = p1.dot(p2);
    double dist = p1.length();
    Point2D unitVector = p1.unit();

    displayPoint(p1);
    displayPoint(p2);
    displayPoint(p3); // p1 + p2
    displayPoint(p4); // p1 - p2
    displayPoint(p5); // p1 * 2.0
    std::cout << "Dot Product: " << innerProduct << std::endl;
