        Node *slowPtr = start;
        Node *fastPtr = start;

        while (fastPtr != nullptr && fastPtr->link != nullptr) {
            slowPtr = slowPtr->link;
            fastPtr = fastPtr->link->link;

            if (slowPtr == fastPtr) {
                return true; // Loop detected
            }
        }

        return false; // No loop
    }
};

