#include <cuda_runtime.h>

// CUDA kernel to compute one generation of Conway's Game of Life
__global__ void gameOfLife(float* outputBuffer, int imgWidth, int imgHeight) {
    __shared__ float tileData[32][32];

    int col = blockIdx.x * blockDim.x + threadIdx.x;
    int row = blockIdx.y * blockDim.y + threadIdx.y;

    // Load texel data into shared memory with halo padding
    if (col < imgWidth && row < imgHeight) {
        tileData[threadIdx.y + 1][threadIdx.x + 1] = tex2D(inputTex, col, row);
    }

    __syncthreads();

    // Only process threads inside the valid inner region
    if (threadIdx.x > 0 && threadIdx.x < 31 && threadIdx.y > 0 && threadIdx.y < 31) {
        float cellState = tileData[threadIdx.y][threadIdx.x];
        float neighborCount = 0.0f;

        // Sum all eight neighbors
        neighborCount += tileData[threadIdx.y][threadIdx.x - 1];
        neighborCount += tileData[threadIdx.y][threadIdx.x + 1];
        neighborCount += tileData[threadIdx.y - 1][threadIdx.x];
        neighborCount += tileData[threadIdx.y + 1][threadIdx.x];
        neighborCount += tileData[threadIdx.y - 1][threadIdx.x - 1];
        neighborCount += tileData[threadIdx.y - 1][threadIdx.x + 1];
        neighborCount += tileData[threadIdx.y + 1][threadIdx.x - 1];
        neighborCount += tileData[threadIdx.y + 1][threadIdx.x + 1];

        float nextState = 0.0f;
        if (neighborCount < 2.0f || neighborCount > 3.0f) {
            nextState = 0.0f;  // Dies from underpopulation or overpopulation
        } else if (cellState != 0.0f || neighborCount == 3.0f) {
            nextState = 1.0f;  // Survives or is born
        }

        // Write result back to global memory if within bounds
        if (col < imgWidth && row < imgHeight) {
            outputBuffer[col + row * imgWidth] = nextState;
        }
    }
}

