extern "C" {

JNIEXPORT jbyteArray JNICALL
Java_com_android_camera3_camera_hardware_session_output_photo_yuv_YuvJniInterface_scale420YuvByteArray(
        JNIEnv *env, jclass /*clazz*/, jbyteArray yuvInput_, jint in_width, jint in_height,
        jint dst_width, jint dst_height) {

    jbyte *inputBuffer = env->GetByteArrayElements(yuvInput_, NULL);

    // Determine buffer sizes
    int src_length = env->GetArrayLength(yuvInput_);
    int dst_length = dst_height * dst_width * 3 / 2;

    // Initialize input frame structure
    input_frame_data.frame_width = in_width;
    input_frame_data.frame_height = in_height;
    input_frame_data.buffer = (uint8_t *) inputBuffer;
    input_frame_data.plane_y = input_frame_data.buffer;
    input_frame_data.stride_y = in_width;
    input_frame_data.plane_u = input_frame_data.plane_y + in_width * in_height;
    input_frame_data.plane_v = input_frame_data.plane_u + in_width * in_height / 4;
    input_frame_data.stride_u = in_width / 2;
    input_frame_data.stride_v = in_width / 2;

    // Initialize output frame structure
    delete[] output_frame_data.buffer;
    output_frame_data.frame_width = dst_width;
    output_frame_data.frame_height = dst_height;
    output_frame_data.buffer = new uint8_t[dst_length];
    output_frame_data.plane_y = output_frame_data.buffer;
    output_frame_data.stride_y = dst_width;
    output_frame_data.plane_u = output_frame_data.plane_y + dst_width * dst_height;
    output_frame_data.plane_v = output_frame_data.plane_u + dst_width * dst_height / 4;
    output_frame_data.stride_u = dst_width / 2;
    output_frame_data.stride_v = dst_width / 2;

    libyuv::FilterMode scaling_filter = libyuv::FilterModeEnum::kFilterBilinear;

    int status = I420Scale(
            input_frame_data.plane_y, input_frame_data.stride_y,
            input_frame_data.plane_u, input_frame_data.stride_u,
            input_frame_data.plane_v, input_frame_data.stride_v,
            input_frame_data.frame_width, input_frame_data.frame_height,
            output_frame_data.plane_y, output_frame_data.stride_y,
            output_frame_data.plane_u, output_frame_data.stride_u,
            output_frame_data.plane_v, output_frame_data.stride_v,
            output_frame_data.frame_width, output_frame_data.frame_height,
            scaling_filter);
    LOGD("Scaling completed with status: %d", status);

    // Prepare and return result
    jbyteArray resultArray = env->NewByteArray(dst_length);
    env->SetByteArrayRegion(resultArray, 0, dst_length, (jbyte *)output_frame_data.buffer);

    env->ReleaseByteArrayElements(yuvInput_, inputBuffer, 0);

    return resultArray;
}

