// Initialize EGL context and surfaces for OpenGL ES rendering
int InitializeEGLContext() {
    ANativeWindow *renderWindow = (ANativeWindow*)displaySurface;

    EGLint temp, visualFormat;

    display = eglGetDisplay(EGL_DEFAULT_DISPLAY);

    if (!eglInitialize(display, nullptr, nullptr)) {
        LogError("Failed to initialize EGL: " + GetEglError());
        return -1;
    }

    EGLint mainContextAttrs[] = {
        EGL_CONTEXT_CLIENT_VERSION, 2, EGL_NONE
    };

    const EGLint surfaceConfigAttrs[] = {
        EGL_SURFACE_TYPE, EGL_WINDOW_BIT,
        EGL_RENDERABLE_TYPE, EGL_OPENGL_ES2_BIT,
        EGL_BLUE_SIZE, 8,
        EGL_GREEN_SIZE, 8,
        EGL_RED_SIZE, 8,
        EGL_ALPHA_SIZE, 8,
        EGL_BUFFER_SIZE, 32,
        EGL_DEPTH_SIZE, 24,
        EGL_NONE
    };

    EGLint configCount;
    EGLConfig mainConfig;

    if (!eglChooseConfig(display, surfaceConfigAttrs, &mainConfig, 1, &configCount)) {
        LogError("Failed to select main EGL config: " + GetEglError());
        return -1;
    }

    if (!eglGetConfigAttrib(display, mainConfig, EGL_NATIVE_VISUAL_ID, &visualFormat)) {
        LogError("Unable to retrieve native visual ID: " + GetEglError());
        return -1;
    }

    ANativeWindow_setBuffersGeometry(renderWindow, 0, 0, visualFormat);

    mainSurface = eglCreateWindowSurface(display, mainConfig, renderWindow, NULL);
    if (mainSurface == EGL_NO_SURFACE) {
        LogError("Failed to create window surface: " + GetEglError());
        return -1;
    }

    mainContext = eglCreateContext(display, mainConfig, EGL_NO_CONTEXT, mainContextAttrs);
    if (mainContext == EGL_NO_CONTEXT) {
        LogError("Failed to create main OpenGL context: " + GetEglError());
        return -1;
    }

    const EGLint pbufferConfigAttrs[] = {
        EGL_SURFACE_TYPE, EGL_PBUFFER_BIT,
        EGL_RENDERABLE_TYPE, EGL_OPENGL_ES2_BIT,
        EGL_BLUE_SIZE, 8,
        EGL_GREEN_SIZE, 8,
        EGL_RED_SIZE, 8,
        EGL_ALPHA_SIZE, 8,
        EGL_DEPTH_SIZE, 0,
        EGL_STENCIL_SIZE, 0,
        EGL_NONE
    };

    EGLint pbufferAttrs[] = {
        EGL_WIDTH, 1,
        EGL_HEIGHT, 1,
        EGL_TEXTURE_TARGET, EGL_NO_TEXTURE,
        EGL_TEXTURE_FORMAT, EGL_NO_TEXTURE,
        EGL_NONE
    };

    EGLint auxConfigCount;
    EGLConfig auxConfig;

    if (!eglChooseConfig(display, pbufferConfigAttrs, &auxConfig, 1, &auxConfigCount)) {
        LogError("Failed to select auxiliary EGL config: " + GetEglError());
        return -1;
    }

    auxSurface = eglCreatePbufferSurface(display, auxConfig, pbufferAttrs);
    if (auxSurface == EGL_NO_SURFACE) {
        LogError("Failed to create pbuffer surface: " + GetEglError());
        return -1;
    }

    auxContext = eglCreateContext(display, auxConfig, mainContext, mainContextAttrs);
    if (auxContext == EGL_NO_CONTEXT) {
        LogError("Failed to create auxiliary context: " + GetEglError());
        return -1;
    }

    if (!eglMakeCurrent(display, mainSurface, mainSurface, mainContext)) {
        LogError("Could not activate main EGL context: " + GetEglError());
        return -1;
    }

    return 0;
}

