#include <iostream>

// Sorts an array using quicksort algorithm
void sortArray(int data[], int start, int end) {
    if (start < end) {
        // Divide: find pivot position
        int pivotPos = separate(data, start, end);

        // Conquer: recursively sort subarrays
        sortArray(data, start, pivotPos - 1);
        sortArray(data, pivotPos + 1, end);
    }
}

// Partitions array around a pivot element
int separate(int data[], int left, int right) {
    int pivotValue = data[right];  // choose last element as pivot
    int smallerIndex = (left - 1);  // track position of smaller elements

    for (int currentIndex = left; currentIndex <= right - 1; currentIndex++) {
        // If current element should be on left side of pivot
        if (data[currentIndex] <= pivotValue) {
            smallerIndex++;  // move boundary of smaller elements
            std::swap(data[smallerIndex], data[currentIndex]);
        }
    }
    std::swap(data[smallerIndex + 1], data[right]);
    return (smallerIndex + 1);
}

