int getPrecedence(char op) {
    if (op == '+' || op == '-') return 1;
    if (op == '*' || op == '/') return 2;
    return 0;
}

bool isMathOperator(char symbol) {
    return symbol == '+' || symbol == '-' || symbol == '*' || symbol == '/';
}

bool isVariableOrDigit(char ch) {
    return std::isalpha(ch) || std::isdigit(ch);
}

std::string convertInfixToPostfix(const std::string& expression) {
    std::stack<char> operatorStack;
    std::string result;
    for (char currentChar : expression) {
        if (isVariableOrDigit(currentChar)) {
            result += currentChar;
        } else if (currentChar == '(') {
            operatorStack.push(currentChar);
        } else if (currentChar == ')') {
            while (!operatorStack.empty() && operatorStack.top() != '(') {
                result += operatorStack.top();
                operatorStack.pop();
            }
            operatorStack.pop();  // Remove '(' from stack
        } else if (isMathOperator(currentChar)) {
            while (!operatorStack.empty() && getPrecedence(currentChar) <= getPrecedence(operatorStack.top())) {
                result += operatorStack.top();
                operatorStack.pop();
            }
            operatorStack.push(currentChar);
        }
    }
    while (!operatorStack.empty()) {
        result += operatorStack.top();
        operatorStack.pop();
    }
    return result;
}

