int _tmain(int argc, _TCHAR* argv[])
{
    HCRYPTPROV hProvider;
    HCRYPTKEY hKeyPair, hSessionKey;
    HCRYPTHASH hHash;
    DWORD bufferSize;
    BOOL success;
    BYTE buffer[1024];
    BYTE sessionKeyBuffer[1024];
    DWORD sessionKeySize = sizeof(sessionKeyBuffer);

    // Acquire cryptographic provider context
    if (!CryptAcquireContext(&hProvider, NULL, MS_ENHANCED_PROV, PROV_RSA_FULL, 0))
    {
        if (GetLastError() == NTE_BAD_KEYSET)
            success = CryptAcquireContext(&hProvider, NULL, MS_ENHANCED_PROV, PROV_RSA_FULL, CRYPT_NEWKEYSET);
        else
            success = FALSE;
        if (!success)
            goto Cleanup;
    }

    // Generate Diffie-Hellman key pair
    success = CryptGenKey(hProvider, CALG_DH_EPHEM, KEY_LENGTH << 16, &hKeyPair);
    if (!success)
        goto Cleanup;

    // Create SHA-1 hash object
    success = CryptCreateHash(hProvider, CALG_SHA1, 0, 0, &hHash);
    if (!success)
        goto Cleanup;

    // Derive session key from hash
    success = CryptDeriveKey(hProvider, CALG_RC4, hHash, 0, &hSessionKey);
    if (!success)
        goto Cleanup;

    // Export session key in plaintext format
    success = CryptExportKey(hSessionKey, 0, PLAINTEXTKEYBLOB, 0, sessionKeyBuffer, &sessionKeySize);
    if (!success)
        goto Cleanup;

    // Output session key in hexadecimal
    for (DWORD idx = 0; idx < sessionKeySize; ++idx)
    {
        printf("%02x", sessionKeyBuffer[idx]);
    }
    printf("\n");

    // Encrypt test data
    bufferSize = sizeof(testData);
    success = CryptEncrypt(hSessionKey, 0, TRUE, 0, testData, &bufferSize, sizeof(testData));
    if (!success)
        goto Cleanup;

    // Output encrypted data in hexadecimal
    for (DWORD idx = 0; idx < bufferSize; ++idx)
    {
        printf("%02x", testData[idx]);
    }
    printf("\n");

Cleanup:
    if (hSessionKey) CryptDestroyKey(hSessionKey);
    if (hKeyPair) CryptDestroyKey(hKeyPair);
    if (hHash) CryptDestroyHash(hHash);
    if (hProvider) CryptReleaseContext(hProvider, 0);

    return 0;
}

