// Function to display Fibonacci sequence up to n terms
void showFibonacci(int count) {
    long long prev = 0, curr = 1, nextTerm;

    if (count <= 0) {
        cout << "Please enter a positive integer." << endl;
        return;
    }

    cout << "Fibonacci Sequence up to " << count << " terms:" << endl;

    for (int index = 1; index <= count; ++index) {
        if (index == 1) {
            cout << prev << ", ";
            continue;
        }
        if (index == 2) {
            cout << curr << ", ";
            continue;
        }
        nextTerm = prev + curr;
        prev = curr;
        curr = nextTerm;
        cout << nextTerm;
        if (index < count) cout << ", ";
    }
    cout << endl;
}

