// Function to find the longest common substring between two strings
pair<int, pair<int, int>> getLongestCommonSubstr(const string& str1, const string& str2) {
    int len1 = str1.size();
    int len2 = str2.size();

    // Initialize DP table with zeros
    vector<vector<int>> table(len1 + 1, vector<int>(len2 + 1, 0));

    // Track maximum length and ending positions
    int maxLen = 0;
    int endPos1 = -1;
    int endPos2 = -1;

    // Fill the DP table
    for (int i = 1; i <= len1; ++i) {
        for (int j = 1; j <= len2; ++j) {
            if (str1[i - 1] == str2[j - 1]) {
                table[i][j] = table[i - 1][j - 1] + 1;
                if (table[i][j] > maxLen) {
                    maxLen = table[i][j];
                    endPos1 = i - 1;
                    endPos2 = j - 1;
                }
            } else {
                table[i][j] = 0;
            }
        }
    }

    // Compute starting indices from ending positions
    int startPos1 = endPos1 - maxLen + 1;
    int startPos2 = endPos2 - maxLen + 1;

    return {maxLen, {startPos1, startPos2}};
}

int main() {
    string input1, input2;
    cout << "Input first string: ";
    cin >> input1;
    cout << "Input second string: ";
    cin >> input2;

    auto outcome = getLongestCommonSubstr(input1, input2);
    int length = outcome.first;
    int start1 = outcome.second.first;
    int start2 = outcome.second.second;

    if (length > 0) {
        cout << "Longest common substring: " << input1.substr(start1, length) << endl;
        cout << "Start position in first string: " << start1 << endl;
        cout << "Start position in second string: " << start2 << endl;
    } else {
        cout << "No common substring detected." << endl;
    }

    return 0;
}

#include <immintrin.h> // For AVX intrinsics

// Reorder function with vectorized load/store for non-zero blocks
void reorder(float* dest, const float* src, size_t len) {
    size_t idx = 0;
    while (idx < len) {
        // Verify next 8 elements are all non-zero
        if (src[idx] != 0.0f && src[idx + 1] != 0.0f && src[idx + 2] != 0.0f && src[idx + 3] != 0.0f &&
            src[idx + 4] != 0.0f && src[idx + 5] != 0.0f && src[idx + 6] != 0.0f && src[idx + 7] != 0.0f) {
            // Load 8 floats using unaligned load
            __m256 simd_vec = _mm256_loadu_ps(&src[idx]);
            // Store 8 floats to destination
            _mm256_storeu_ps(&dest[idx], simd_vec);
            idx += 8;
        } else {
            // Copy single element when condition not met
            dest[idx] = src[idx];
            idx++;
        }
    }
}

