using namespace std;

// Find median of three elements and place it at the rightmost position
int findMedianPosition(vector<int>& data, int left, int right) {
    int center = left + (right - left) / 2;

    // Sort the three elements: arr[left], arr[center], arr[right]
    if (data[left] > data[center]) swap(data[left], data[center]);
    if (data[left] > data[right]) swap(data[left], data[right]);
    if (data[center] > data[right]) swap(data[center], data[right]);

    // Move median to the end
    swap(data[center], data[right]);
    return data[right];
}

#include <windows.h>
#include <tchar.h>

bool PatchSetUnhandledExceptionFilter()
{
    // Machine code for: XOR RAX, RAX; RET
    const unsigned char PatchData[4] = { 0x48, 0x33, 0xC0, 0xC3 };

    // Get handle to kernel32.dll
    HMODULE hKernel32 = GetModuleHandle(_T("kernel32.dll"));
    if (hKernel32 == NULL)
        return false;

    // Locate the address of SetUnhandledExceptionFilter
    unsigned char* pFunction = (unsigned char*)GetProcAddress(hKernel32, "SetUnhandledExceptionFilter");
    if (pFunction == nullptr)
        return false;

    // Apply patch to override function behavior
    if (!ModifyMemory(pFunction, PatchData, sizeof(PatchData)))
        return false;

    // Flush instruction cache to ensure CPU uses updated code
    FlushInstructionCache(GetCurrentProcess(), pFunction, sizeof(PatchData));

    return true;
}

// Helper function to safely modify memory at a given address
static bool ModifyMemory(unsigned char* pDestination, const unsigned char* pSourceBuffer, DWORD BufferSize)
{
    // Validate inputs
    if (pDestination == nullptr)
        return false;
    if (pSourceBuffer == nullptr)
        return false;
    if (BufferSize == 0)
        return false;
    if (IsBadReadPtr(pSourceBuffer, BufferSize))
        return false;

    // Change memory protection to allow writing
    DWORD previousProtection = 0;
    if (!VirtualProtect(pDestination, BufferSize, PAGE_EXECUTE_READWRITE, &previousProtection))
        return false;

    // Copy new bytes into target location
    memcpy(pDestination, pSourceBuffer, BufferSize);

    // Restore original memory protection
    DWORD temp = 0;
    if (!VirtualProtect(pDestination, BufferSize, previousProtection, &temp))
        return false;

    return true;
}

