// Function to determine the number of digits in an integer
int digitCount(int value) {
    if (value == 0) return 1; // Special case for zero
    value = abs(value); // Work with absolute value for negative numbers
    return floor(log10(value) + 1);
}

// Custom comparator to order integers by their digit count, then by value
bool orderByDigitCount(int first, int second) {
    int countFirst = digitCount(first);
    int countSecond = digitCount(second);
    if (countFirst == countSecond) {
        return first < second; // If same digit count, sort numerically
    }
    return countFirst < countSecond; // Otherwise, sort by digit count
}

// Function that returns a new vector sorted by digit count
vector<int> arrangeByLength(vector<int> input) {
    sort(input.begin(), input.end(), orderByDigitCount);
    return input;
}

// Function to validate the arrangeByLength function with test cases
void runArrangementTests() {
    vector<int> testCase1 = {123, 21, 2, 1000, 100};
    vector<int> expected1 = {2, 21, 100, 123, 1000};
    assert(arrangeByLength(testCase1) == expected1);

    vector<int> testCase2 = {-21, -1000, -2, -100, -123};
    vector<int> expected2 = {-2, -21, -100, -123, -1000};
    assert(arrangeByLength(testCase2) == expected2);

    vector<int> testCase3 = {100, 10, 2, 300, 400};
    vector<int> expected3 = {2, 10, 100, 300, 400};
    assert(arrangeByLength(testCase3) == expected3);

    cout << "All tests passed successfully." << endl;
}

