#include <immintrin.h>

// Compute a simple XOR-based hash using SIMD operations
uint32_t calculateChecksum(const uint32_t* input, size_t count) {
    __m128i accumulator = _mm_set1_epi32(0);
    for (size_t index = 0; index < count / 4; ++index) {
        __m128i block = _mm_loadu_si128((__m128i*)&input[index * 4]);
        accumulator = _mm_xor_si128(accumulator, block);
    }
    uint32_t output;
    _mm_storeu_si128((__m128i*)&output, accumulator);
    return output;
}

