// Function to enclose script elements with CDATA sections
QString encloseScriptsWithCdata(const QString &htmlContent) {
    QString updatedHtml = htmlContent;
    int position = 0;
    while ((position = updatedHtml.indexOf("<script", position)) != -1) {
        int closingTagPos = updatedHtml.indexOf("</script>", position);
        if (closingTagPos == -1) break; // Malformed script tag

        QString scriptBlock = updatedHtml.mid(position, closingTagPos - position + 9);
        QString wrappedBlock = "<script type=\"text/javascript\">\n"
                               "    //<![CDATA[\n"
                               "    " + scriptBlock + "\n"
                               "    //]]>\n"
                               "</script>";
        updatedHtml.replace(position, closingTagPos - position + 9, wrappedBlock);
        position += wrappedBlock.length();
    }
    return updatedHtml;
}

int main() {
    QString mainContent;

    {
        QFile inputFile("main.html");
        if (!inputFile.open(QIODevice::ReadOnly)) {
            qDebug() << "Failed to open main.html for reading";
            return -1;
        }
        QTextStream inputStream(&inputFile);
        mainContent = inputStream.readAll();
        inputFile.close();
    }

    // Process HTML to embed script contents within CDATA
    QString processedHtml = encloseScriptsWithCdata(mainContent);

    QDomDocument xmlDocument;
    QString errorString;
    int errorLine = 0, errorColumn = 0;
    if (!xmlDocument.setContent(processedHtml, &errorString, &errorLine, &errorColumn)) {
        qDebug() << errorString << " at line:" << errorLine << "column:" << errorColumn;
        return -1;
    }

    std::function<void(const QDomElement&, int)> traverseAndPrint =
    [&traverseAndPrint](const QDomElement& node, int depth) {
        QString indentation(3 * depth, ' ');
        QDomNode child = node.firstChild();
        for (; !child.isNull(); child = child.nextSibling()) {
            QDomElement element = child.toElement();
            if (element.isNull()) continue;

            qDebug() << indentation + element.tagName();
            traverseAndPrint(element, depth + 1);
        }
    };
    traverseAndPrint(xmlDocument.documentElement(), 0);

    return 0;
}

