const std::string DataFile = "counter.dat";
const std::string MutexIdentifier = "Global\\SharedCounterMutex";

class CounterHandler
{
private:
    HANDLE synchronizationMutex;

public:
    CounterHandler()
    {
        synchronizationMutex = CreateMutex(NULL, FALSE, MutexIdentifier.c_str());
    }

    ~CounterHandler()
    {
        CloseHandle(synchronizationMutex);
    }

    int IncreaseCounter()
    {
        WaitForSingleObject(synchronizationMutex, INFINITE);
        int value = 0;
        std::ifstream inputFile(DataFile);
        if (inputFile.is_open())
        {
            inputFile >> value;
            inputFile.close();
        }
        value++;
        std::ofstream outputFile(DataFile);
        if (outputFile.is_open())
        {
            outputFile << value;
            outputFile.close();
        }
        ReleaseMutex(synchronizationMutex);
        return value;
    }

    int DecreaseCounter()
    {
        WaitForSingleObject(synchronizationMutex, INFINITE);
        int value = 0;
        std::ifstream inputFile(DataFile);
        if (inputFile.is_open())
        {
            inputFile >> value;
            inputFile.close();
        }
        value--;
        std::ofstream outputFile(DataFile);
        if (outputFile.is_open())
        {
            outputFile << value;
            outputFile.close();
        }
        ReleaseMutex(synchronizationMutex);
        return value;
    }
};

#include <iostream>
#include <string>
#include <vector>
#include <iterator>

class DataStreamProducer {
public:
    class StreamIterator {
    public:
        using value_type = std::string;
        using reference = std::string&;
        using pointer = std::string*;
        using difference_type = std::ptrdiff_t;
        using iterator_category = std::input_iterator_tag;

        StreamIterator(DataStreamProducer& producer, bool finish = false) : producer_(producer), finished_(finish) {
            if (!finished_) {
                current_value_ = producer_.produce_next();
            }
        }

        StreamIterator& operator++() {
            if (!finished_) {
                current_value_ = producer_.produce_next();
            }
            return *this;
        }

        StreamIterator operator++(int) {
            StreamIterator temp = *this;
            ++(*this);
            return temp;
        }

        bool operator==(const StreamIterator& rhs) const {
            return finished_ == rhs.finished_;
        }

        bool operator!=(const StreamIterator& rhs) const {
            return !(*this == rhs);
        }

        const std::string& operator*() const {
            return current_value_;
        }

        const std::string* operator->() const {
            return &current_value_;
        }

    private:
        DataStreamProducer& producer_;
        std::string current_value_;
        bool finished_;
    };

    DataStreamProducer(const std::string& source) : source_(source), skip_count_(source.find("extra") != std::string::npos ? 7 : 8) {
        state_ = 0;
    }

    StreamIterator begin() {
        return StreamIterator(*this);
    }

    StreamIterator end() {
        return StreamIterator(*this, true);
    }

private:
    std::string source_;
    int skip_count_;
    int state_;

    std::string produce_next() {
        switch (state_) {
            case 0:
                state_ = 1;
                return "payload";
            case 1:
                for (int j = 0; j < skip_count_; ++j) {
                    state_++;
                    return "skipped";
                }
                state_ = skip_count_ + 1;
                // Continue to next case
            case skip_count_ + 1:
                state_++;
                return "payload";
            default:
                return "payload"; // Continues indefinitely like Python's infinite loop
        }
    }
};

