// Definition for a Node.
class Node {
public:
    int val;
    Node* left;
    Node* right;
    Node* next;

    Node() : val(0), left(NULL), right(NULL), next(NULL) {}

    Node(int _val) : val(_val), left(NULL), right(NULL), next(NULL) {}

    Node(int _val, Node* _left, Node* _right, Node* _next)
        : val(_val), left(_left), right(_right), next(_next) {}
};
*/

class Solution {
public:
    Node* connect(Node* root) {
        if (!root) return root;

        Node* levelStart = root;

        while (levelStart) {
            Node* current = levelStart;
            Node* helper = new Node(0); // Helper node to simplify linking next level
            Node* tail = helper;

            while (current) {
                if (current->left) {
                    tail->next = current->left;
                    tail = tail->next;
                }
                if (current->right) {
                    tail->next = current->right;
                    tail = tail->next;
                }
                current = current->next;
            }

            levelStart = helper->next; // Proceed to the subsequent level
            delete helper; // Release memory allocated for helper node
        }

        return root;
    }
};

