/* Define the Iterator object */
typedef struct {
    PyObject_HEAD
    size_t limit;
    size_t index;
} CountObject;

static void CountObject_dealloc(CountObject* self) {
    Py_TYPE(self)->tp_free((PyObject*)self);
}

static PyObject* CountObject_iter(CountObject* self) {
    Py_INCREF(self);
    return (PyObject*)self;
}

static PyObject* CountObject_next(CountObject* self) {
    if (self->index >= self->limit) {
        PyErr_SetNone(PyExc_StopIteration);
        return NULL;
    }
    PyObject* value = PyLong_FromSize_t(self->index);
    self->index++;
    return value;
}

