using namespace std;

// Function to select tapas minimizing the number while staying under or equal to M calories
vector<int> selectTapas(vector<int>& calories, int maxCalories) {
    int numTapas = calories.size();
    vector<vector<int>> minCount(numTapas + 1, vector<int>(maxCalories + 1, INT_MAX));
    vector<vector<int>> decision(numTapas + 1, vector<int>(maxCalories + 1, 0));

    // Base case: 0 tapas needed for 0 calories
    minCount[0][0] = 0;

    // Fill DP table
    for (int item = 1; item <= numTapas; ++item) {
        for (int currentCalories = 0; currentCalories <= maxCalories; ++currentCalories) {
            if (calories[item - 1] > currentCalories) {
                minCount[item][currentCalories] = minCount[item - 1][currentCalories];
                decision[item][currentCalories] = decision[item - 1][currentCalories];
            } else {
                int takeItem = 1 + minCount[item - 1][currentCalories - calories[item - 1]];
                int skipItem = minCount[item - 1][currentCalories];
                if (takeItem <= skipItem) {
                    minCount[item][currentCalories] = takeItem;
                    decision[item][currentCalories] = item;
                } else {
                    minCount[item][currentCalories] = skipItem;
                    decision[item][currentCalories] = decision[item - 1][currentCalories];
                }
            }
        }
    }

    // Find the highest calorie count achievable within limit
    int actualCalories = maxCalories;
    while (decision[numTapas][actualCalories] == 0 && actualCalories >= 0) {
        --actualCalories;
    }

    // Backtrack to find selected tapas
    vector<int> selectedIndices;
    int idx = numTapas;
    int remaining = actualCalories;
    while (idx > 0 && remaining >= 0) {
        if (decision[idx][remaining] == idx) {
            selectedIndices.push_back(idx - 1);
            remaining -= calories[idx - 1];
        }
        --idx;
    }

    return selectedIndices;
}

int main() {
    vector<int> calories = {3, 5, 10, 13, 15, 16};
    int calorieLimit = 45;
    vector<int> chosenTapas = selectTapas(calories, calorieLimit);

    cout << "Tapas to order:\n";
    for (int pos : chosenTapas) {
        cout << "Tapa " << pos + 1 << ": " << calories[pos] << " calories\n";
    }

    return 0;
}

