class RuntimeEnvironment
{
public:
    RuntimeEnvironment()
    {
        HRESULT status = CLRCreateInstance(CLSID_CLRMetaHost, IID_ICLRMetaHost, (LPVOID*)&_metaHost);
        if (FAILED(status)) throw std::runtime_error("Failed to initialize CLR meta host");

        status = _metaHost->GetRuntime(L"v4.0.30319", IID_ICLRRuntimeInfo, (LPVOID*)&_runtimeInfo);
        if (FAILED(status)) throw std::runtime_error("Unable to retrieve runtime information");

        BOOL isCompatible = FALSE;
        status = _runtimeInfo->IsLoadable(&isCompatible);
        if (FAILED(status) || !isCompatible) throw std::runtime_error("Specified runtime version is not loadable");

        status = _runtimeInfo->GetInterface(CLSID_CLRRuntimeHost, IID_ICLRRuntimeHost, (LPVOID*)&_runtimeHost);
        if (FAILED(status)) throw std::runtime_error("Could not obtain CLRRuntimeHost interface");

        status = _runtimeHost->Start();
        if (FAILED(status)) throw std::runtime_error("CLR runtime failed to start");

        status = _runtimeHost->GetCLRControl(&_clrControl);
        if (FAILED(status)) throw std::runtime_error("Failed to acquire CLR control");

        status = _clrControl->GetHostControl(&_hostControl);
        if (FAILED(status)) throw std::runtime_error("Failed to get host control interface");

        status = _hostControl->QueryInterface(IID_IHostControl, (LPVOID*)&_hostControl);
        if (FAILED(status)) throw std::runtime_error("Host control interface query failed");

        status = _runtimeHost->ExecuteInDefaultAppDomain(L"ManagedLibrary.dll", L"ManagedLibrary.ManagedClass", L"Initialize", L"", &_managedInstance);
        if (FAILED(status)) throw std::runtime_error("Execution in default app domain failed");
    }

    ~RuntimeEnvironment()
    {
        _runtimeHost->Stop();
        _runtimeHost->Release();
        _runtimeInfo->Release();
        _metaHost->Release();
    }

    void ExecuteOperation()
    {
        HRESULT status = _runtimeHost->ExecuteInDefaultAppDomain(L"ManagedLibrary.dll", L"ManagedLibrary.ManagedClass", L"PerformOperation", L"", nullptr);
        if (FAILED(status)) throw std::runtime_error("Operation execution failed");
    }

private:
    ICLRMetaHost* _metaHost;
    ICLRRuntimeInfo* _runtimeInfo;
    ICLRRuntimeHost* _runtimeHost;
    ICLRControl* _clrControl;
    IHostControl* _hostControl;
    _variant_t _managedInstance;
};

int main()
{
    try
    {
        RuntimeEnvironment re;
        re.ExecuteOperation();
    }
    catch (const std::exception& ex)
    {
        std::cerr << "Error occurred: " << ex.what() << std::endl;
    }

    return 0;
}

#include <iostream>
#include <limits>

class ListNode {
public:
    int data;
    ListNode* previous;
    ListNode* next;

    ListNode(int val) : data(val), previous(nullptr), next(nullptr) {}
};

class DoublyList {
private:
    ListNode* start;
    ListNode* end;
    ListNode* minElement;
    ListNode* maxElement;

public:
    DoublyList() : start(nullptr), end(nullptr), minElement(nullptr), maxElement(nullptr) {}

    void add(int value) {
        ListNode* newNode = new ListNode(value);

        if (start == nullptr) {
            start = end = minElement = maxElement = newNode;
        } else {
            newNode->previous = end;
            end->next = newNode;
            end = newNode;

            if (value < minElement->data) {
                minElement = newNode;
            }
            if (value > maxElement->data) {
                maxElement = newNode;
            }
        }
    }

    void erase(int value) {
        ListNode* current = start;
        while (current != nullptr) {
            if (current->data == value) {
                if (current->previous) {
                    current->previous->next = current->next;
                } else {
                    start = current->next;
                }

                if (current->next) {
                    current->next->previous = current->previous;
                } else {
                    end = current->previous;
                }

                if (minElement == current) {
                    minElement = locateMinimum();
                }
                if (maxElement == current) {
                    maxElement = locateMaximum();
                }

                delete current;
                return;
            }
            current = current->next;
        }
    }

    int minimum() const {
        return minElement ? minElement->data : std::numeric_limits<int>::max();
    }

    int maximum() const {
        return maxElement ? maxElement->data : std::numeric_limits<int>::min();
    }

private:
    ListNode* locateMinimum() const {
        ListNode* minNode = start;
        ListNode* current = start;
        while (current != nullptr) {
            if (current->data < minNode->data) {
                minNode = current;
            }
            current = current->next;
        }
        return minNode;
    }

    ListNode* locateMaximum() const {
        ListNode* maxNode = start;
        ListNode* current = start;
        while (current != nullptr) {
            if (current->data > maxNode->data) {
                maxNode = current;
            }
            current = current->next;
        }
        return maxNode;
    }
};

int main() {
    DoublyList sequence;
    sequence.add(10);
    sequence.add(5);
    sequence.add(15);
    sequence.add(3);

    std::cout << "Smallest: " << sequence.minimum() << std::endl; // Output: Smallest: 3
    std::cout << "Largest: " << sequence.maximum() << std::endl;  // Output: Largest: 15

    sequence.erase(15);
    std::cout << "Largest after deleting 15: " << sequence.maximum() << std::endl; // Output: Largest: 10

    return 0;
}

#include <immintrin.h>
