// Function to perform atomic 128-bit compare-and-exchange
bool cas128(__int128* address, __int128 expected_val, __int128 desired_val) {
    __int128 previous = *address;
    __int128 result = expected_val;

    __asm__ __volatile__(
        "lock cmpxchg16b %0\n"
        : "=m"(*address), "+a"(result)
        : "d"((uint64_t)(expected_val >> 64)), "c"((uint64_t)(desired_val >> 64)),
          "b"((uint64_t)desired_val), "a"((uint64_t)expected_val), "m"(*address)
        : "memory", "cc"
    );

    return previous == expected_val;
}

int main() {
    __int128 storage = 0xFEDCBA9876543210FEDCBA9876543210;
    __int128 match_expected = 0xFEDCBA9876543210FEDCBA9876543210;
    __int128 replacement = 0xAABBCCDDEEFF0011AABBCCDDEEFF0011;

    bool outcome = cas128(&storage, match_expected, replacement);

    std::cout << "Atomic operation " << (outcome ? "completed successfully" : "did not match") << std::endl;
    std::cout << "Storage value: " << std::hex << storage << std::endl;

    return 0;
}

