#include <condition_variable>
#include <vector>
#include <memory>
#include <chrono>

class ThreadPoolManager {
public:
    ThreadPoolManager(size_t initialThreads = 20, size_t maxThreads = 200)
        : _initialCount(initialThreads)
        , _maximumCount(maxThreads)
        , _shutdown(false) {
        active_threads.reserve(_maximumCount);
        for (size_t idx = 0; idx < _initialCount; ++idx) {
            spawn_thread();
        }
    }

    void spawn_thread() {
        active_threads.emplace_back([this] {
            while (true) {
                std::function<void()> job;
                {
                    std::unique_lock<std::mutex> guard(this->_lock);
                    this->_condition.wait(guard, [this] {
                        return this->_shutdown || !this->_jobs.empty();
                    });
                    if (this->_shutdown && this->_jobs.empty())
                        break;
                    job = std::move(this->_jobs.front());
                    this->_jobs.pop_front();
                }
                job();
            }
        });
    }

    template <typename Func, typename... Params>
    auto enqueue(Func&& func, Params&&... params)
        -> std::future<typename std::result_of<Func(Params...)>::type> {
        using result_type = typename std::result_of<Func(Params...)>::type;

        auto wrapper = std::make_shared<
            std::packaged_task<result_type()>>(std::bind(std::forward<Func>(func), std::forward<Params>(params)...));

        std::future<result_type> outcome = wrapper->get_future();
        {
            std::unique_lock<std::mutex> guard(_lock);
            if (_shutdown) {
                throw std::runtime_error("Enqueue on stopped ThreadPoolManager");
            }
            if (_jobs.size() >= active_threads.size() && active_threads.size() < _maximumCount) {
                spawn_thread();
            }
            _jobs.emplace_back([wrapper] { (*wrapper)(); });
        }
        _condition.notify_one();
        return outcome;
    }

    void shutdown() {
        std::unique_lock<std::mutex> guard(_lock);
        if (!_shutdown) {
            _shutdown = true;
            _condition.notify_all();
        }
        for (std::thread& worker : active_threads)
            worker.join();
    }

    size_t pending_jobs() {
        std::unique_lock<std::mutex> guard(_lock);
        return _jobs.size();
    }

    ~ThreadPoolManager() {
        shutdown();
    }

private:
    std::vector<std::thread> active_threads;
    std::deque<std::function<void()>> _jobs;
    size_t _initialCount;
    size_t _maximumCount;
    std::mutex _lock;
    std::condition_variable _condition;
    bool _shutdown;
};

class WorkerTask {
public:
    WorkerTask(double identifier)
        : _device_id(identifier)
        , _active(true) {
    }

    void launch(ThreadPoolManager& pool) {
        _result = pool.enqueue(&WorkerTask::_process, this);
    }

    void terminate() {
        {
            _active = false;
            std::unique_lock<std::mutex> guard(_sync_mutex);

            if (_result.valid()) {
                _result.get();
                guard.unlock();
                _finalize();
            }
        }
    }

private:
    std::mutex _sync_mutex;
    double _device_id;
    std::deque<double> _packet_buffer;
    std::future<void> _result;
    bool _active;

    void _finalize() {
        std::unique_lock<std::mutex> guard(_sync_mutex);
        _packet_buffer.clear();
    }

    void _process() {
        std::unique_lock<std::mutex> guard(_sync_mutex);
        while (_active) {
            if (_packet_buffer.empty()) {
                std::cout << "executing task" << std::endl;
                continue;
            }
            double item = _packet_buffer.front();
            _packet_buffer.pop_front();
            guard.unlock();
            std::cout << "executing task" << std::endl;
            guard.lock();
        }
    }
};

int main() {
    ThreadPoolManager pool(20, 200);
    std::vector<std::shared_ptr<WorkerTask>> tasks;

    for (int index = 0; index < 100; ++index) {
        auto task = std::make_shared<WorkerTask>(1.0);
        task->launch(pool);
        tasks.push_back(task);
    }

    std::this_thread::sleep_for(std::chrono::seconds(3));

    for (auto& task : tasks) {
        task->terminate();
    }
    tasks.clear();

    for (int index = 0; index < 3; ++index) {
        auto task = std::make_shared<WorkerTask>(1.0);
        task->launch(pool);
        tasks.push_back(task);
    }

    std::this_thread::sleep_for(std::chrono::seconds(3));

    for (auto& task : tasks) {
        task->terminate();
    }

    return 0;
}

#include <QWebEngineView>
#include <QWebChannel>
