// Custom web engine widget with Qt property bindings and JavaScript integration
class hfbDisplayWidget : public QWebEngineView
{
    Q_OBJECT

    Q_PROPERTY(QString displayText READ displayText WRITE setDisplayText NOTIFY displayTextChanged)
    Q_PROPERTY(int counterValue READ counterValue WRITE setCounterValue NOTIFY counterValueChanged)

public:
    hfbDisplayWidget(QWidget * parent) : QWebEngineView(parent)
    {
        page()->setWebChannel(&_channel);
        _channel.registerObject(QString("qtBridge"), this);

        setDisplayText("Hello World");
        setCounterValue(777);
    }

    QWebChannel _channel;

    Q_INVOKABLE int processInteger(QVariant input)
    {
        int value = input.toInt();

        QString script = QString("PrintLog('c++ processInteger(%1) triggered!')").arg(value);
        setDisplayText(script);
        setCounterValue(value);

        page()->runJavaScript(script, [=](const QVariant &result){
            qDebug() << script << " -> " << result;
        });
        return value * 200;
    }

    Q_INVOKABLE double processDouble(QVariant input)
    {
        double value = input.toDouble();

        QString script = QString("PrintLog('c++ processDouble(%1) triggered!')").arg(value);
        page()->runJavaScript(script, [=](const QVariant &result){
            qDebug() << script << " -> " << result;
        });

        return (value + 0.98765);
    }

    Q_INVOKABLE QString processString(QVariant input)
    {
        QString value = input.toString();

        QString script = QString("PrintLog('c++ processString(%1) triggered!')").arg(value);
        page()->runJavaScript(script, [=](const QVariant &result){
            qDebug() << script << " -> " << result;
        });

        return (QString("c++ received:'") + value + QString("'"));
    }

    QString displayText() const { return _displayText; }
    void setDisplayText(const QString &value)
    {
        if (_displayText != value) {
            _displayText = value;
            emit displayTextChanged();
        }
    }

    int counterValue() const { return _counterValue; }
    void setCounterValue(int value)
    {
        if (_counterValue != value) {
            _counterValue = value;
            emit counterValueChanged();
        }
    }

signals:
    void displayTextChanged();
    void counterValueChanged();

private:
    QString _displayText;
    int _counterValue;
};

#include <cuda_runtime.h>

// Kernel to convert Bayer pattern (GRBG) to RGB
__global__ void demosaic_GRBG(uchar4 *outputBuffer, unsigned int imgWidth, unsigned int imgHeight) {
    int col = blockIdx.x * blockDim.x + threadIdx.x;
    int row = blockIdx.y * blockDim.y + threadIdx.y;

    if (col < imgWidth && row < imgHeight) {
        // Fetch the raw Bayer pixel value from texture memory
        unsigned char rawPixel = tex2D(bayerTexture, col, row);

        // Perform demosaicing interpolation
        uchar4 rgbPixel;

        // Determine position in Bayer pattern and interpolate accordingly
        if (row % 2 == 0) {
            if (col % 2 == 0) {
                // GR pattern: Red at (even, even)
                rgbPixel.x = rawPixel; // Red
                rgbPixel.y = (tex2D(bayerTexture, col, row - 1) + 
                              tex2D(bayerTexture, col, row + 1) + 
                              tex2D(bayerTexture, col - 1, row) + 
                              tex2D(bayerTexture, col + 1, row)) / 4; // Green
                rgbPixel.z = (tex2D(bayerTexture, col - 1, row - 1) + 
                              tex2D(bayerTexture, col - 1, row + 1) + 
                              tex2D(bayerTexture, col + 1, row - 1) + 
                              tex2D(bayerTexture, col + 1, row + 1)) / 4; // Blue
            } else {
                // BG pattern: Blue at (even, odd)
                rgbPixel.x = (tex2D(bayerTexture, col - 1, row) + 
                              tex2D(bayerTexture, col + 1, row)) / 2; // Red
                rgbPixel.y = (tex2D(bayerTexture, col, row - 1) + 
                              tex2D(bayerTexture, col, row + 1)) / 2; // Green
                rgbPixel.z = rawPixel; // Blue
            }
        } else {
            if (col % 2 == 0) {
                // GB pattern: Blue at (odd, even)
                rgbPixel.x = (tex2D(bayerTexture, col, row - 1) + 
                              tex2D(bayerTexture, col, row + 1)) / 2; // Red
                rgbPixel.y = (tex2D(bayerTexture, col - 1, row) + 
                              tex2D(bayerTexture, col + 1, row)) / 2; // Green
                rgbPixel.z = rawPixel; // Blue
            } else {
                // RG pattern: Red at (odd, odd)
                rgbPixel.x = rawPixel; // Red
                rgbPixel.y = (tex2D(bayerTexture, col, row - 1) + 
                              tex2D(bayerTexture, col, row + 1) + 
                              tex2D(bayerTexture, col - 1, row) + 
                              tex2D(bayerTexture, col + 1, row)) / 4; // Green
                rgbPixel.z = (tex2D(bayerTexture, col - 1, row - 1) + 
                              tex2D(bayerTexture, col - 1, row + 1) + 
                              tex2D(bayerTexture, col + 1, row - 1) + 
                              tex2D(bayerTexture, col + 1, row + 1)) / 4; // Blue
            }
        }

        // Write the reconstructed pixel to output buffer
        outputBuffer[row * imgWidth + col] = rgbPixel;
    }
}

// Host wrapper function to launch the kernel
void launch_demosaic_kernel(int width, int height, dim3 threadsPerBlock, dim3 blocksPerGrid, uchar4 *deviceOutput) {
    demosaic_GRBG<<<blocksPerGrid, threadsPerBlock>>>(deviceOutput, width, height);
    cudaDeviceSynchronize();
}

#include <iostream>
#include <vector>

// Compute the average of a list of integers
double computeMean(const std::vector<int>& values) {
    if (values.empty()) {
        return 0.0;
    }
    int accumulator = 0;
    for (int value : values) {
        accumulator += value;
    }
    return static_cast<double>(accumulator) / values.size();
}

int main() {
    std::vector<int> data = {1, 2, 3, 4, 5};
    double result = computeMean(data);
    std::cout << "Average: " << result << std::endl;
    return 0;
}

