#include <iostream>
#include <curl/curl.h>

std::string fetchData(const std::string& endpoint)
{
    CURL *handle;
    CURLcode result;
    std::string buffer;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    handle = curl_easy_init();
    if (handle) {
        curl_easy_setopt(handle, CURLOPT_URL, endpoint.c_str());
        curl_easy_setopt(handle, CURLOPT_WRITEFUNCTION, [](char *data, size_t len, size_t count, std::string *out) {
            out->append(data, len * count);
            return len * count;
        });
        curl_easy_setopt(handle, CURLOPT_WRITEDATA, &buffer);
        result = curl_easy_perform(handle);
        curl_easy_cleanup(handle);
    }
    curl_global_cleanup();
    return buffer;
}

int main()
{
    std::string targetUrl = "http://localhost:5000/api/mycontroller/myfunction";
    std::string serverResponse = fetchData(targetUrl);
    std::cout << "Server Response: " << serverResponse << std::endl;
    return 0;
}

