// Ensure pointer value does not exceed maximum limit
void process_ptr(int* value_ptr) noexcept;
void finalize_ptr(int* value_ptr) noexcept;

void apply_limit(int* value_ptr) noexcept {
    if (*value_ptr > 100) {
        *value_ptr = 100;
        process_ptr(value_ptr);
    }
    finalize_ptr(value_ptr);
}

#include <ESP8266WiFi.h>
