// WiFi network credentials
const char* wifiSSID = "your_SSID";
const char* wifiPass = "your_PASSWORD";

// GPIO pin for controlling the LED
const int ledGPIO = 4;

// Create web server instance on port 80
ESP8266WebServer httpServer(80);

void handleIndex() {
    String page = "<html><head><title>LED Switch</title>";
    page += "<script>function switchLED(){var req=new XMLHttpRequest();";
    page += "req.open('GET','/toggle',true);req.send();}</script>";
    page += "</head><body><h1>LED Toggle Interface</h1>";
    page += "<button onclick=\"switchLED()\">Switch LED</button>";
    page += "</body></html>";
    httpServer.send(200, "text/html", page);
}

void handleToggle() {
    static bool isLedOn = LOW;
    isLedOn = !isLedOn; // Invert current state
    digitalWrite(ledGPIO, isLedOn);
    httpServer.send(200, "text/plain", isLedOn ? "ACTIVE" : "INACTIVE");
}

void setup() {
    // Initialize serial communication for debugging
    Serial.begin(115200);

    pinMode(ledGPIO, OUTPUT);
    digitalWrite(ledGPIO, LOW);

    // Establish WiFi connection
    Serial.print("Joining ");
    Serial.println(wifiSSID);
    WiFi.begin(wifiSSID, wifiPass);

    while (WiFi.status() != WL_CONNECTED) {
        delay(500);
        Serial.print(".");
    }
    Serial.println("");
    Serial.println("Network connection established");
    Serial.print("Assigned IP: ");
    Serial.println(WiFi.localIP());

    httpServer.on("/", handleIndex);
    httpServer.on("/toggle", handleToggle);
    httpServer.begin();
    Serial.println("Web server operational");
}

void loop() {
    httpServer.handleClient();
}

