const int GRID_DIMENSION = 10;
const std::vector<int> VESSEL_LENGTHS = {5, 4, 3, 3, 2};

enum class TileState { Clear, Vessel, Strike, Miss };

class GameGrid {
private:
    std::vector<std::vector<TileState>> matrix;

public:
    GameGrid() : matrix(GRID_DIMENSION, std::vector<TileState>(GRID_DIMENSION, TileState::Clear)) {}

    void deployVessel(int length, int r, int c, bool isHorizontal) {
        if (isHorizontal) {
            for (int k = 0; k < length; ++k) {
                matrix[r][c + k] = TileState::Vessel;
            }
        } else {
            for (int k = 0; k < length; ++k) {
                matrix[r + k][c] = TileState::Vessel;
            }
        }
    }

    bool canDeploy(int length, int r, int c, bool isHorizontal) {
        if (isHorizontal) {
            if (c + length > GRID_DIMENSION) return false;
            for (int k = 0; k < length; ++k) {
                if (matrix[r][c + k] != TileState::Clear) return false;
            }
        } else {
            if (r + length > GRID_DIMENSION) return false;
            for (int k = 0; k < length; ++k) {
                if (matrix[r + k][c] != TileState::Clear) return false;
            }
        }
        return true;
    }

    bool engage(int r, int c) {
        if (matrix[r][c] == TileState::Vessel) {
            matrix[r][c] = TileState::Strike;
            return true;
        } else {
            matrix[r][c] = TileState::Miss;
            return false;
        }
    }

    bool allSunk() const {
        for (const auto& line : matrix) {
            for (const auto& tile : line) {
                if (tile == TileState::Vessel) return false;
            }
        }
        return true;
    }

    void reveal() const {
        for (const auto& line : matrix) {
            for (const auto& tile : line) {
                switch (tile) {
                    case TileState::Clear: std::cout << "."; break;
                    case TileState::Vessel: std::cout << "B"; break;
                    case TileState::Strike: std::cout << "#"; break;
                    case TileState::Miss: std::cout << "~"; break;
                }
            }
            std::cout << std::endl;
        }
    }
};

class Combatant {
private:
    GameGrid arena;
    std::string identity;

public:
    Combatant(const std::string& id) : identity(id) {}

    void setupFleet() {
        std::cout << identity << ", position your vessels:\n";
        for (int len : VESSEL_LENGTHS) {
            int r, c;
            bool horizontal;
            do {
                std::cout << "Deploy a vessel of length " << len << " (row col horizontal): ";
                std::cin >> r >> c >> horizontal;
            } while (!arena.canDeploy(len, r, c, horizontal));
            arena.deployVessel(len, r, c, horizontal);
        }
    }

    bool attack(Combatant& rival) {
        int r, c;
        std::cout << identity << ", target (row col): ";
        std::cin >> r >> c;
        return rival.arena.engage(r, c);
    }

    bool isMatchOver() const {
        return arena.allSunk();
    }

    void showGrid() const {
        std::cout << identity << "'s grid:\n";
        arena.reveal();
    }
};

int main() {
    std::srand(std::time(0));

    Combatant combatantA("Contender Alpha");
    Combatant combatantB("Contender Beta");

    combatantA.setupFleet();
    combatantB.setupFleet();

    bool turnA = true;
    while (!combatantA.isMatchOver() && !combatantB.isMatchOver()) {
        if (turnA) {
            combatantA.showGrid();
            combatantB.showGrid();
            if (combatantA.attack(combatantB)) {
                std::cout << "Direct hit!\n";
            } else {
                std::cout << "Shot missed!\n";
                turnA = false;
            }
        } else {
            combatantA.showGrid();
            combatantB.showGrid();
            if (combatantB.attack(combatantA)) {
                std::cout << "Direct hit!\n";
            } else {
                std::cout << "Shot missed!\n";
                turnA = true;
            }
        }
    }

    if (combatantA.isMatchOver()) {
        std::cout << "Contender Beta triumphs!\n";
    } else {
        std::cout << "Contender Alpha triumphs!\n";
    }

    return 0;
}

