        static TextReader singleton;
        return singleton;
    }

    void loadContent(const std::string& fileName) {
        if (storage.find(fileName) == storage.end()) {
            std::ifstream inputStream(fileName);
            std::string buffer;
            if (inputStream.is_open()) {
                std::string currentLine;
                while (std::getline(inputStream, currentLine)) {
                    buffer += currentLine + "\n";
                }
                inputStream.close();
                storage[fileName] = buffer;
            }
        }
    }

    const std::string& retrieveContent(const std::string& fileName) {
        return storage[fileName];
    }

private:
    TextReader() {}
    std::map<std::string, std::string> storage;
};

extern "C" {
    JNIEXPORT void JNICALL Java_com_example_TextLoader_nativeLoad(JNIEnv* env, jobject obj, jstring fileName) {
        const char* name = env->GetStringUTFChars(fileName, nullptr);
        TextReader::getReference().loadContent(name);
        env->ReleaseStringUTFChars(fileName, name);
    }

    JNIEXPORT jstring JNICALL Java_com_example_TextLoader_nativeRetrieve(JNIEnv* env, jobject obj, jstring fileName) {
        const char* name = env->GetStringUTFChars(fileName, nullptr);
        std::string content = TextReader::getReference().retrieveContent(name);
        env->ReleaseStringUTFChars(fileName, name);
        return env->NewStringUTF(content.c_str());
    }
}

