struct Vector3D {
    double x, y, z;
    Vector3D(double x = 0.0, double y = 0.0, double z = 0.0) : x(x), y(y), z(z) {}

    Vector3D operator-(const Vector3D& other) const {
        return Vector3D(x - other.x, y - other.y, z - other.z);
    }

    double dot(const Vector3D& other) const {
        return x * other.x + y * other.y + z * other.z;
    }

    Vector3D operator*(double scalar) const {
        return Vector3D(x * scalar, y * scalar, z * scalar);
    }
};

struct CubicSplineSegment {
    Vector3D start, end, startVec, endVec;
    CubicSplineSegment(Vector3D s, Vector3D e, Vector3D sv, Vector3D ev) 
        : start(s), end(e), startVec(sv), endVec(ev) {}

    Vector3D evaluate(double t) const {
        double t2 = t * t;
        double t3 = t2 * t;
        double h1 = 2 * t3 - 3 * t2 + 1;
        double h2 = -2 * t3 + 3 * t2;
        double h3 = t3 - 2 * t2 + t;
        double h4 = t3 - t2;
        Vector3D result = h1 * start + h2 * end + h3 * startVec + h4 * endVec;
        return result;
    }
};

double solveCubic(double p, double q, double r, double s) {
    double discriminant = q * q - 3 * p * r;
    double u = (-q + sqrt(discriminant)) / 2.0;
    double v = (-q - sqrt(discriminant)) / 2.0;
    double root1 = u / p;
    double root2 = v / p;
    double root3 = (-q / (3 * p));
    return fmax(root1, fmax(root2, root3));
}

Vector3D findSplineIntersection(const CubicSplineSegment& seg1, const CubicSplineSegment& seg2) {
    Vector3D A = seg1.start - seg2.start;
    Vector3D B = seg2.end - seg2.start - seg1.end + seg1.start;
    Vector3D C = seg1.end - seg1.start - seg2.startVec;
    Vector3D D = seg2.startVec;

    double coeff_a = 9 * (B.dot(B)) + 12 * (A.dot(C));
    double coeff_b = 27 * (A.dot(A)) + 18 * (A.dot(B)) + 4 * (B.dot(B)) + 6 * (A.dot(C)) - 18 * (B.dot(D));
    double coeff_c = 2 * (B.dot(B) * B.dot(B)) + 9 * (A.dot(B) * B.dot(B)) + 27 * (A.dot(A) * C.dot(C)) + 
                     36 * (A.dot(B) * C.dot(C)) - 72 * (B.dot(C) * C.dot(D));
    double coeff_d = -1 * (A.dot(A) + 3 * (B.dot(B)) + 6 * (A.dot(C)) - 3 * (B.dot(D))) * (B.dot(B)) + 
                     3 * A.dot(B) * C.dot(C) - 3 * B.dot(B) * D.dot(D) + 27 * (A.dot(A) * D.dot(D)) - 
                     72 * (A.dot(C) * C.dot(D));

    double param_t = solveCubic(coeff_a, coeff_b, coeff_c, coeff_d);

    return seg1.evaluate(param_t);
}

int main() {
    Vector3D s1(0, 0, 0), e1(1, 1, 1), sv1(1, 0, 0), ev1(0, 1, 0);
    Vector3D s2(1, 0, 0), e2(0, 1, 1), sv2(-1, 0, 0), ev2(0, -1, 0);
    CubicSplineSegment spline1(s1, e1, sv1, ev1);
    CubicSplineSegment spline2(s2, e2, sv2, ev2);

    Vector3D intersectionPoint = findSplineIntersection(spline1, spline2);
    cout << "Intersection: " << intersectionPoint.x << ", " << intersectionPoint.y << ", " << intersectionPoint.z << endl;

    return 0;
}

