const int GRID_SIZE = 4; // 2x2 grid
const int MOVES = 4; // up, down, left, right
const double LEARNING_RATE = 0.1; // Learning rate
const double DISCOUNT_FACTOR = 0.9; // Discount factor
const double EXPLORE_RATE = 0.1; // Epsilon for epsilon-greedy strategy

std::vector<std::vector<double>> QTable(GRID_SIZE, std::vector<double>(MOVES, 0.0));

// Function to simulate the environment
int getNextState(int currentState, int move) {
    // Simplified state transition
    switch (move) {
        case 0: return (currentState > 1) ? currentState - 2 : currentState; // Up
        case 1: return (currentState < 2) ? currentState + 2 : currentState; // Down
        case 2: return (currentState % 2 != 0) ? currentState - 1 : currentState; // Left
        case 3: return (currentState % 2 == 0) ? currentState + 1 : currentState; // Right
        default: return currentState;
    }
}

double getReward(int nextState) {
    return (nextState == 3) ? 100 : 0; // Reward for reaching the goal
}

// Epsilon-greedy action selection
int chooseAction(int state) {
    if (rand() / static_cast<double>(RAND_MAX) < EXPLORE_RATE) {
        return rand() % MOVES; // Explore
    } else {
        return std::distance(QTable[state].begin(), std::max_element(QTable[state].begin(), QTable[state].end())); // Exploit
    }
}

void updateQValue(int state, int action, int nextState) {
    double maxQ = *std::max_element(QTable[nextState].begin(), QTable[nextState].end());
    QTable[state][action] += LEARNING_RATE * (getReward(nextState) + DISCOUNT_FACTOR * maxQ - QTable[state][action]);
}

int main() {
    srand(time(0));
    int currentPos = 0;
    for (int episode = 0; episode < 1000; ++episode) { // Number of iterations
        int move = chooseAction(currentPos);
        int nextPos = getNextState(currentPos, move);
        updateQValue(currentPos, move, nextPos);
        currentPos = nextPos;
        if (currentPos == 3) { // Reset to start if goal is reached
            currentPos = 0;
        }
    }

    // Print the Q table
    for (const auto &row : QTable) {
        for (double value : row) {
            std::cout << value << " ";
        }
        std::cout << std::endl;
    }

    return 0;
}

