namespace capy = boost::capy;

// A time-consuming operation that monitors for cancellation requests
capy::task<std::string> lengthy_retrieve(int iterations)
{
    auto token = co_await capy::this_coro::stop_token;  // std::stop_token
    std::string output;

    for (int idx = 0; idx < iterations; ++idx)
    {
        // Verify if cancellation has been requested before proceeding
        if (token.stop_requested())
        {
            std::cout << "  Stopped at iteration " << idx << std::endl;
            throw std::system_error(
                make_error_code(std::errc::operation_canceled));
        }

        output += "step" + std::to_string(idx) + " ";

        // Emulate a slow process (in practice, this would involve I/O operations)
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
        std::cout << "  Finished iteration " << idx << std::endl;

        // Yield control to let pending stop requests be handled before the next check
        // Additional 15ms ensures previous output finishes before main thread continues
        std::this_thread::sleep_for(std::chrono::milliseconds(15));
    }

    co_return output;
}

// Execute with a timeout mechanism (simplified - actual implementation requires timer support)
capy::task<std::optional<std::string>> retrieve_with_timeout()
{
    auto token = co_await capy::this_coro::stop_token;  // std::stop_token

    try
    {
        auto value = co_await lengthy_retrieve(5);  // std::string
        co_return value;
    }
    catch (std::system_error const& ex)
    {
        if (ex.code() == std::errc::operation_canceled)
            co_return std::nullopt;
        throw;
    }
}

void demonstration_successful_execution()
{
    std::cout << "Demonstration: Successful completion\n";

    capy::thread_pool executor_pool;
    std::stop_source canceller;
    std::latch completion_event(1);  // std::latch - wait for 1 task
    capy::run_async(executor_pool.get_executor(), canceller.get_token(),
        [&completion_event](std::optional<std::string> outcome) {
            if (outcome)
                std::cout << "Outcome: " << *outcome << "\n";
            else
                std::cout << "Cancelled\n";
            completion_event.count_down();
        },
        [&completion_event](std::exception_ptr) { completion_event.count_down(); }
    )(retrieve_with_timeout());
    completion_event.wait();  // Suspend until operation finishes
}

void demonstration_operation_cancelled()
{
    std::cout << "\nDemonstration: Cancellation after 2 steps\n";
    capy::thread_pool executor_pool;
    std::stop_source canceller;
    std::latch completion_event(1);  // std::latch - wait for 1 task

    // Initiate the asynchronous task
    capy::run_async(executor_pool.get_executor(), canceller.get_token(),
        [&completion_event](std::optional<std::string> outcome) {
            if (outcome)
                std::cout << "Outcome: " << *outcome << "\n";
            else
                std::cout << "Cancelled (returned nullopt)\n";
            completion_event.count_down();
        },
        [&completion_event](std::exception_ptr) { completion_event.count_down(); }
    )(retrieve_with_timeout());

    // Simulate timeout: cancel after approximately 2 steps have completed
    // Timing: each step takes 10ms processing + 15ms yield = 25ms total
    // Step 1 logs at ~35ms, step 2 checks at ~50ms
    // Cancel at ~42ms: after step 1 log, before step 2 check
    std::this_thread::sleep_for(std::chrono::milliseconds(42));
    std::cout << "  Initiating cancellation..." << std::endl;
    canceller.request_stop();

    completion_event.wait();  // Wait until operation completes (post-cancellation)
}

// Illustration: Explicit stop token checking in coroutine
capy::task<int> aggregate_values(std::vector<int> const& values)
{
    auto token = co_await capy::this_coro::stop_token;  // std::stop_token
    int accumulated = 0;

    for (auto val : values)  // int
    {
        if (token.stop_requested())
        {
            std::cout << "Aggregation halted, partial sum: " << accumulated << "\n";
            co_return accumulated;  // Return intermediate result
        }

        accumulated += val;
    }

    co_return accumulated;
}

int main()
{
    demonstration_successful_execution();
    demonstration_operation_cancelled();

    return 0;
}

