// Usage: rundll32.exe zzz_display_commander.addon64,MonitorAndInject "target_app.exe"
extern "C" __declspec(dllexport) void CALLBACK MonitorAndInject(HWND hwnd, HINSTANCE hInst, LPSTR lpszCmdLine,
                                                                  int nCmdShow) {
    UNREFERENCED_PARAMETER(hwnd);
    UNREFERENCED_PARAMETER(hInst);
    UNREFERENCED_PARAMETER(nCmdShow);

    // Initialize logging system
    display_commander::config::DisplayCommanderConfigManager::GetInstance().Initialize();
    display_commander::config::DisplayCommanderConfigManager::GetInstance().SetAutoFlushLogs(true);

    // Parse target executable name from command line
    std::string target_name_ansi;
    if (lpszCmdLine != nullptr && strlen(lpszCmdLine) > 0) {
        target_name_ansi = lpszCmdLine;
        // Remove surrounding quotes if present
        if (target_name_ansi.length() >= 2 && target_name_ansi.front() == '"' && target_name_ansi.back() == '"') {
            target_name_ansi = target_name_ansi.substr(1, target_name_ansi.length() - 2);
        }
    }

    if (target_name_ansi.empty()) {
        OutputDebugStringA(
            "MonitorAndInject: No executable name specified. Expected format: rundll32.exe zzz_display_commander.addon64,MonitorAndInject \"target.exe\"");
        return;
    }

    // Convert to wide string
    int wide_len = MultiByteToWideChar(CP_ACP, 0, target_name_ansi.c_str(), -1, nullptr, 0);
    if (wide_len <= 0) {
        OutputDebugStringA("MonitorAndInject: Failed to convert executable name to wide string");
        return;
    }

    std::vector<wchar_t> wide_name(wide_len);
    MultiByteToWideChar(CP_ACP, 0, target_name_ansi.c_str(), -1, wide_name.data(), wide_len);
    std::wstring target_name_wide(wide_name.data());

    // Extract just the filename portion
    std::filesystem::path exe_path(target_name_wide);
    std::wstring filename_only = exe_path.filename().wstring();

    OutputDebugStringA(std::format("MonitorAndInject: Monitoring for process: {} (normalized: {})", target_name_ansi,
                                   std::string(filename_only.begin(), filename_only.end()))
                           .c_str());

    std::cout << "MonitorAndInject: Waiting for process: " << target_name_ansi
              << " (matching against: " << std::string(filename_only.begin(), filename_only.end()) << ")" << std::endl;

    // Begin monitoring and auto-injecting when process starts
    WaitForProcessAndInject(filename_only);
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int size;
    cin >> size;
    vector<int> arr(size + 1), indexMap(size + 1);

    for (int idx = 1; idx <= size; idx++) {
        cin >> arr[idx];
        indexMap[arr[idx]] = idx;
    }

    int mode = (size <= 2 ? 1 : 3); // mode=3 allows operations of length 2 and 4; mode=1 only allows length 2

    vector<pair<int, int>> operations;
    operations.reserve(200000);

    auto perform_reverse = [&](int left, int right) {
        while (left < right) {
            int valLeft = arr[left], valRight = arr[right];
            swap(arr[left], arr[right]);
            indexMap[valLeft] = right;
            indexMap[valRight] = left;
            left++;
            right--;
        }
    };

    if (mode == 1) {
        // Handle small cases (n <= 2) using adjacent swaps only
        for (int target = 1; target <= size; target++) {
            while (indexMap[target] > target) {
                int pos = indexMap[target];
                operations.push_back({pos - 1, pos});
                perform_reverse(pos - 1, pos);
            }
        }
    } else {
        // mode == 3: use both length-2 and length-4 reversals
        for (int target = 1; target <= size; target++) {
            while (indexMap[target] >= target + 3) {
                int pos = indexMap[target];
                operations.push_back({pos - 3, pos}); // reverse segment of length 4
                perform_reverse(pos - 3, pos);
            }
            while (indexMap[target] > target) {
                int pos = indexMap[target];
                operations.push_back({pos - 1, pos}); // reverse segment of length 2
                perform_reverse(pos - 1, pos);
            }
        }
    }

    cout << mode << "\n";
    cout << (int)operations.size() << "\n";
    for (auto &op : operations) {
        cout << op.first << " " << op.second << "\n";
    }

    return 0;
}

