namespace ocs2 {

PerformanceIndex& PerformanceIndex::operator+=(const PerformanceIndex& other) {
  this->merit += other.merit;
  this->cost += other.cost;
  this->dualFeasSSE += other.dualFeasSSE;
  this->dynViolationSSE += other.dynViolationSSE;
  this->eqConstrSSE += other.eqConstrSSE;
  this->ineqConstrSSE += other.ineqConstrSSE;
  this->eqLagrangian += other.eqLagrangian;
  this->ineqLagrangian += other.ineqLagrangian;
  return *this;
}

PerformanceIndex& PerformanceIndex::operator*=(const scalar_t factor) {
  this->merit *= factor;
  this->cost *= factor;
  this->dualFeasSSE *= factor;
  this->dynViolationSSE *= factor;
  this->eqConstrSSE *= factor;
  this->ineqConstrSSE *= factor;
  this->eqLagrangian *= factor;
  this->ineqLagrangian *= factor;
  return *this;
}

bool PerformanceIndex::isApprox(const PerformanceIndex& reference, const scalar_t tolerance) const {
  return numerics::almost_eq(this->merit, reference.merit, tolerance) &&
         numerics::almost_eq(this->cost, reference.cost, tolerance) &&
         numerics::almost_eq(this->dualFeasSSE, reference.dualFeasSSE, tolerance) &&
         numerics::almost_eq(this->dynViolationSSE, reference.dynViolationSSE, tolerance) &&
         numerics::almost_eq(this->eqConstrSSE, reference.eqConstrSSE, tolerance) &&
         numerics::almost_eq(this->ineqConstrSSE, reference.ineqConstrSSE, tolerance) &&
         numerics::almost_eq(this->eqLagrangian, reference.eqLagrangian, tolerance) &&
         numerics::almost_eq(this->ineqLagrangian, reference.ineqLagrangian, tolerance);
}

void swap(PerformanceIndex& first, PerformanceIndex& second) {
  using std::swap;
  swap(first.merit, second.merit);
  swap(first.cost, second.cost);
  swap(first.dualFeasSSE, second.dualFeasSSE);
  swap(first.dynViolationSSE, second.dynViolationSSE);
  swap(first.eqConstrSSE, second.eqConstrSSE);
  swap(first.ineqConstrSSE, second.ineqConstrSSE);
  swap(first.eqLagrangian, second.eqLagrangian);
  swap(first.ineqLagrangian, second.ineqLagrangian);
}

PerformanceIndex toPerformanceIndex(const Metrics& metrics) {
  PerformanceIndex result;
  result.merit = 0.0;  // solver will populate
  result.cost = metrics.cost;
  result.dualFeasSSE = 0.0;  // solver will populate
  result.dynViolationSSE = getEqConstraintsSSE(metrics.dynamicsViolation);
  result.eqConstrSSE = getEqConstraintsSSE(metrics.stateEqConstraint) + getEqConstraintsSSE(metrics.stateInputEqConstraint);
  result.ineqConstrSSE = getIneqConstraintsSSE(metrics.stateIneqConstraint) + getIneqConstraintsSSE(metrics.stateInputIneqConstraint);
  result.eqLagrangian = sumPenalties(metrics.stateEqLagrangian) + sumPenalties(metrics.stateInputEqLagrangian);
  result.ineqLagrangian = sumPenalties(metrics.stateIneqLagrangian) + sumPenalties(metrics.stateInputIneqLagrangian);
  return result;
}

PerformanceIndex toPerformanceIndex(const Metrics& metrics, const scalar_t dt) {
  auto index = toPerformanceIndex(metrics);
  // cost scaling already handled in multiple_shooting::computeIntermediateMetrics()
  index.dualFeasSSE *= dt;
  index.dynViolationSSE *= dt;
  index.eqConstrSSE *= dt;
  index.ineqConstrSSE *= dt;
  return index;
}

std::ostream& operator<<(std::ostream& out, const PerformanceIndex& perf) {
  constexpr size_t fieldWidth = 14;
  const auto indent = out.width();
  out << std::left;
  out << std::setw(indent) << "";
  out << "Rollout Merit:              " << std::setw(fieldWidth) << perf.merit;
  out << "Rollout Cost:               " << std::setw(fieldWidth) << perf.cost << '\n';
  out << std::setw(indent) << "";
  out << "Dual feasibilities SSE:     " << std::setw(fieldWidth) << perf.dualFeasSSE;
  out << "Dynamics violation SSE:     " << std::setw(fieldWidth) << perf.dynViolationSSE << '\n';
  out << std::setw(indent) << "";
  out << "Equality constraints SSE:   " << std::setw(fieldWidth) << perf.eqConstrSSE;
  out << "Inequality constraints SSE: " << std::setw(fieldWidth) << perf.ineqConstrSSE << '\n';
  out << std::setw(indent) << "";
  out << "Equality Lagrangian:        " << std::setw(fieldWidth) << perf.eqLagrangian;
  out << "Inequality Lagrangian:      " << std::setw(fieldWidth) << perf.ineqLagrangian;
  return out;
}

