// Evaluate mixed arithmetic and logical expressions
void evaluate_mixed_logic_arith(SMTParser::ParserPtr& p) {
    std::vector<std::string> tests = {
        // Arithmetic within boolean conditions
        "(and (> val_a 0) (< val_b 10))",

        // Boolean operators with comparisons
        "(or (= val_a val_b) (and (> val_a 0) (< val_b 0)))",

        // Implication involving arithmetic
        "(=> (>= val_a 0) (>= (+ val_a val_b) val_b))",

        // Conditional expression mixing types
        "(ite (> val_a 0) (+ val_a val_b) (- val_a val_b))",

        // Complex theory combination
        "(and (= (+ val_a val_b) val_c) (or (> val_a 0) (< val_b 0)))"
    };

    std::cout << "=== Evaluating Mixed Logic and Arithmetic ===" << std::endl;

    try {
        // Declare variables
        p->mkVarInt("val_a");
        p->mkVarInt("val_b");
        p->mkVarInt("val_c");

        for (const auto& expr : tests) {
            std::cout << "Input: " << expr << std::endl;
            std::shared_ptr<SMTParser::DAGNode> res = p->mkExpr(expr);
            assert(res && !res->isErr());
            std::cout << "  Output: " << p->toString(res) << std::endl;
            std::cout << std::endl;
        }
    } catch (const std::exception& ex) {
        std::cout << "Error during setup: " << ex.what() << std::endl;
    }
}

// Test interaction between arrays and integer arithmetic
void evaluate_array_arith(SMTParser::ParserPtr& p) {
    std::vector<std::string> tests = {
        // Indexing with computed offsets
        "(select arr_a (+ idx_i 2))",

        // Updating array at computed position
        "(store arr_a (* 3 idx_i) (+ idx_j 7))",

        // Equality of stores with reordered terms
        "(= (store arr_a idx_i (+ idx_j 2)) (store arr_a idx_i (+ 2 idx_j)))",

        // Comparing array elements
        "(> (select arr_a idx_i) (select arr_a idx_j))",

        // Universal constraint over array range
        "(forall ((idx_k Int)) (=> (and (>= idx_k 0) (< idx_k 15)) (>= (select arr_a idx_k) 0)))"
    };

    std::cout << "=== Evaluating Array-Arithmetic Interaction ===" << std::endl;

    try {
        // Setup sorts and variables
        std::shared_ptr<SMTParser::Sort> int_sort = SMTParser::SortManager::INT_SORT;
        p->mkArray("arr_a", int_sort, int_sort);
        p->mkVarInt("idx_i");
        p->mkVarInt("idx_j");
        p->mkVarInt("idx_k");

        for (const auto& expr : tests) {
            std::cout << "Input: " << expr << std::endl;
            std::shared_ptr<SMTParser::DAGNode> res = p->mkExpr(expr);
            assert(res && !res->isErr());
            std::cout << "  Output: " << p->toString(res) << std::endl;
            std::cout << std::endl;
        }
    } catch (const std::exception& ex) {
        std::cout << "Error during setup: " << ex.what() << std::endl;
    }
}

// Test bitvector operations combined with other theories
