        "(= #b1100 #b1100)",

        // Unsigned less-than comparison
        "(bvult #b1100 #b1010)",

        // Conversion from bitvector to natural number
        "(= (bv2nat #b1100) 12)",

        // Array indexed by bitvector
        "(select bv_arr #b1100)",

        // Combined constraints
        "(and (bvult bv_x bv_y) (= (select bv_arr bv_x) #b0011))"
