// Test quantifiers across different theories
void evaluate_quantifier_mix(SMTParser::ParserPtr& p) {
    std::vector<std::string> tests = {
        // Universal quantification over array indices
        "(forall ((qt_idx Int)) (=> (and (>= qt_idx 0) (< qt_idx 20)) (= (select qt_arr qt_idx) 0)))",

        // Existential quantification over bitvectors
        "(exists ((qt_bv (_ BitVec 4))) (= (bvadd qt_bv #b0001) qt_out))",

        // Quantification over strings
        "(forall ((qt_str String)) (=> (= (str.len qt_str) 1) (str.contains qt_text qt_str)))",

        // Nested quantifiers with array equality
        "(forall ((qt_i Int)) (exists ((qt_j Int)) (and (< qt_i qt_j) (= (select qt_arr qt_i) (select qt_arr qt_j)))))",

        // Mixed existential quantifiers
        "(exists ((qt_x Int) (qt_y Int)) (and (> qt_x 0) (< qt_y 10) (= (select qt_arr qt_x) (select qt_arr qt_y))))"
    };

    std::cout << "=== Evaluating Quantifier Interactions ===" << std::endl;

    try {
        // Setup sorts and variables
        std::shared_ptr<SMTParser::Sort> int_sort = p->mkIntSort();
        std::shared_ptr<SMTParser::Sort> bv4_sort = p->mkBVSort(4);
        std::shared_ptr<SMTParser::Sort> str_sort = p->mkStrSort();

        p->mkArray("qt_arr", int_sort, int_sort);
        p->mkVarBv("qt_out", 4);
        p->mkVarStr("qt_text");

        for (const auto& expr : tests) {
            std::cout << "Input: " << expr << std::endl;
            std::shared_ptr<SMTParser::DAGNode> res = p->mkExpr(expr);
            assert(res && !res->isErr());
            std::cout << "  Output: " << p->toString(res) << std::endl;
            std::cout << std::endl;
        }
    } catch (const std::exception& ex) {
        std::cout << "Error during setup: " << ex.what() << std::endl;
    }
}

// Real-world scenario examples combining multiple theories
void evaluate_real_world_cases(SMTParser::ParserPtr& p) {
    std::vector<std::string> tests = {
        // Symbolic execution path condition
        "(and (= var_x (+ var_y 7)) (= var_z (* 3 var_x)) (> var_z 25))",

        // Safe array access guard
        "(=> (and (>= idx 0) (< idx (select arr_len arr_size))) (>= (select arr_data idx) 0))",

        // Password policy enforcement
        "(and (>= (str.len pwd) 10) (str.contains pwd \"!\") (not (= pwd \"default!\")))",

        // Bitvector cryptographic pattern
        "(= (bvxor (bvand bv_a bv_b) (bvor bv_a bv_b)) expected_val)"
    };

    std::cout << "=== Evaluating Real-World Scenarios ===" << std::endl;

    try {
        // Setup sorts and variables
        std::shared_ptr<SMTParser::Sort> int_sort = p->mkIntSort();
        std::shared_ptr<SMTParser::Sort> bv32_sort = p->mkBVSort(32);
        std::shared_ptr<SMTParser::Sort> str_sort = p->mkStrSort();

        p->mkVarInt("var_x");
        p->mkVarInt("var_y");
        p->mkVarInt("var_z");
        p->mkVarInt("idx");
        p->mkVarInt("len");
        p->mkVarInt("max_val");
        p->mkVarInt("arr_size");
        p->mkArray("arr_data", int_sort, int_sort);
        p->mkVarStr("pwd");
        p->mkVarBv("bv_a", 32);
        p->mkVarBv("bv_b", 32);
        p->mkVarBv("expected_val", 32);

        for (const auto& expr : tests) {
            std::cout << "Input: " << expr << std::endl;
            std::shared_ptr<SMTParser::DAGNode> res = p->mkExpr(expr);
            assert(res && !res->isErr());
            std::cout << "  Output: " << p->toString(res) << std::endl;
            std::cout << std::endl;
        }
    } catch (const std::exception& ex) {
        std::cout << "Error during setup: " << ex.what() << std::endl;
    }
}

