int main(int argc, char ** argv) {
    registerInteraction(argc, argv);
    std::cout.setf(std::ios::fixed);
    std::cout.precision(20);

    int size = inf.readInt();
    println(size);

    std::vector<int> arrA(size);
    for (int idx = 0; idx < size; idx++) {
        arrA[idx] = inf.readInt();
    }

    std::vector<int> arrB(size);
    for (int idx = 0; idx < size; idx++) {
        arrB[idx] = inf.readInt();
    }

    for (int queryCount = 0; queryCount <= 10000; queryCount++) {
        std::string action = ouf.readToken();

        if (action == "?") {
            long double valX = ouf.readDouble();
            if (!std::isfinite(valX) || valX < -1e12 || valX > 1e12) {
                quitf(_wa, "Invalid query: element %.4f is out of range [-1000000000000, 1000000000000]", valX);
            }

            long double valY = ouf.readDouble();
            if (!std::isfinite(valY) || valY < -1e12 || valY > 1e12) {
                quitf(_wa, "Invalid query: element %.4f is out of range [-1000000000000, 1000000000000]", valY);
            }

            long double resultSum = 0.0;
            for (int i = 0; i < size; i++) {
                resultSum += std::abs(arrA[i] * valX - valY + arrB[i]) / std::sqrt(arrA[i] * arrA[i] + 1.0);
            }
            std::cout << resultSum << std::endl;
        } 
        else if (action == "!") {
            std::vector<int> guessA(size);
            for (int i = 0; i < size; i++) {
                guessA[i] = ouf.readInt();
            }

            std::vector<int> guessB(size);
            for (int i = 0; i < size; i++) {
                guessB[i] = ouf.readInt();
            }

            std::vector<int> order(size);
            std::iota(order.begin(), order.end(), 0);
            std::sort(order.begin(), order.end(), [&](int i, int j) -> bool {
                return std::make_pair(guessA[i], guessB[i]) < std::make_pair(guessA[j], guessB[j]);
            });

            bool isCorrect = true;
            for (int i = 0; i < size; i++) {
                if (guessA[order[i]] != arrA[i] || guessB[order[i]] != arrB[i]) {
                    quitp(0., "Wrong guess. Ratio: 0.0000");
                }
            }

            double scoreRatio = queryCount <= 402 ? 1.0 : 1.0 - 0.7 * (queryCount - 402) / (10000 - 402);
            double unboundedScore = 1.0 - 0.7 * (queryCount - 402) / (10000 - 402);
            if (scoreRatio < 0.0) scoreRatio = 0.0;

            quitp(scoreRatio, "Correct guess. Ratio: %.4f, RatioUnbounded: %.4f", scoreRatio, unboundedScore);
        } 
        else {
            quitf(_wa, "Invalid action type: expected ? or !, but got %s", action.c_str());
        }
    }

    quitp(0., "Too many queries. Ratio: 0.0000");
    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

// Function to count the number of prime numbers less than n using Sieve of Eratosthenes
class PrimeCounter {
public:
    int countPrimes(int limit) {
        vector<bool> isPrime(limit + 1, true);
        int result = 0;

        for (int num = 2; num < limit; num++) {
            if (isPrime[num]) {
                result++;
                // Mark all multiples of num as non-prime
                for (int multiple = 2 * num; multiple < limit; multiple += num) {
                    isPrime[multiple] = false;
                }
            }
        }
        return result;
    }
};

int main() {
    PrimeCounter pc;
    int n = 10;
    cout << "Count of prime numbers less than " << n << " is: " << pc.countPrimes(n) << endl;
    return 0;
}

