#include <iostream>
#include <fstream>
#include <stdexcept>
#include <optional>

// g++ disk_v2.cpp -o disk_v2 -lboost_thread -lboost_system
class DiskStoredIntVector {
public:
    DiskStoredIntVector(const std::string& path) : filepath_(path) {
        // Open file in binary mode for read/write operations
        stream_.open(filepath_, std::ios::in | std::ios::out | std::ios::binary);
        if (!stream_) {
            // If file does not exist, create it first
            stream_.clear();
            stream_.open(filepath_, std::ios::out | std::ios::binary);
            stream_.close();
            // Reopen with full permissions
            stream_.open(filepath_, std::ios::in | std::ios::out | std::ios::binary);
        }
    }

    ~DiskStoredIntVector() {
        if (stream_.is_open()) {
            stream_.close();
        }
    }

    int getElementAt(std::size_t pos) {
        // Check cache first
        if (cache_ && cache_->position == pos) {
            return cache_->storedValue;
        }

        // Read from disk
        std::size_t byteOffset = pos * sizeof(int);
        stream_.seekg(byteOffset, std::ios::beg);
        int element;
        stream_.read(reinterpret_cast<char*>(&element), sizeof(int));

        if (stream_.gcount() != static_cast<std::streamsize>(sizeof(int))) {
            throw std::out_of_range("Requested position exceeds array bounds");
        }

        // Update cache
        cache_ = CacheEntry{pos, element};
        return element;
    }

    void pushBack(int newValue) {
        stream_.seekp(0, std::ios::end);
        stream_.write(reinterpret_cast<const char*>(&newValue), sizeof(int));
        if (!stream_) {
            throw std::ios_base::failure("Write operation failed on disk");
        }
    }

    void updateElement(std::size_t pos, int newValue) {
        std::size_t byteOffset = pos * sizeof(int);
        stream_.seekp(byteOffset, std::ios::beg);
        stream_.write(reinterpret_cast<const char*>(&newValue), sizeof(int));

        if (!stream_) {
            throw std::ios_base::failure("Failed to update value at specified position");
        }

        // Update cache if necessary
        if (cache_ && cache_->position == pos) {
            cache_->storedValue = newValue;
        }
    }

    std::size_t length() {
        stream_.seekg(0, std::ios::end);
        std::size_t totalBytes = stream_.tellg();
        if (totalBytes == static_cast<std::size_t>(-1)) {
            throw std::ios_base::failure("Unable to determine file size");
        }
        return totalBytes / sizeof(int);
    }

private:
    struct CacheEntry {
        std::size_t position;
        int storedValue;
    };

    std::string filepath_;
    std::fstream stream_;
    std::optional<CacheEntry> cache_;
};

int main() {
    try {
        DiskStoredIntVector storage("numbers.dat");

        // Add some initial values
        storage.pushBack(100);
        storage.pushBack(200);
        storage.pushBack(300);

        // Access and display elements
        std::cout << "Position 0: " << storage.getElementAt(0) << std::endl;
        std::cout << "Position 1: " << storage.getElementAt(1) << std::endl;
        std::cout << "Position 2: " << storage.getElementAt(2) << std::endl;

        // Modify an element
        storage.updateElement(1, 250);
        std::cout << "Position 1 after update: " << storage.getElementAt(1) << std::endl;

        // Display vector size and last element
        std::cout << "Total elements: " << storage.length() << std::endl;
        std::cout << "Final element: " << storage.getElementAt(storage.length() - 1) << std::endl;

    } catch (const std::exception& err) {
        std::cerr << "Exception caught: " << err.what() << std::endl;
    }

    return 0;
}

