namespace nb = nanobind;
using namespace mscclpp;

void bind_sm_channel(nb::module_& module) {
  nb::class_<SmChannel> smChannelClass(module, "SmChannel");
  smChannelClass
      .def("__init__",
           [](SmChannel* ptr, std::shared_ptr<SmDevice2DeviceSemaphore> sem, RegisteredMemory dstMem, uintptr_t srcAddr) {
             new (ptr) SmChannel(sem, dstMem, reinterpret_cast<void*>(srcAddr));
           })
      .def("__init__",
           [](SmChannel* ptr, std::shared_ptr<SmDevice2DeviceSemaphore> sem, RegisteredMemory dstMem, uintptr_t srcAddr,
              uintptr_t getPacketBufferAddr) {
             new (ptr) SmChannel(sem, dstMem, reinterpret_cast<void*>(srcAddr), reinterpret_cast<void*>(getPacketBufferAddr));
           })
      .def("device_handle", &SmChannel::deviceHandle);

  nb::class_<SmChannel::DeviceHandle>(module, "SmChannelDeviceHandle")
      .def(nb::init<>())
      .def_rw("semaphore_", &SmChannel::DeviceHandle::semaphore_)
      .def_rw("src_", &SmChannel::DeviceHandle::src_)
      .def_rw("dst_", &SmChannel::DeviceHandle::dst_)
      .def_rw("getPacketBuffer_", &SmChannel::DeviceHandle::getPacketBuffer_)
      .def_prop_ro("raw", [](const SmChannel::DeviceHandle& handle) -> nb::bytes {
        return nb::bytes(reinterpret_cast<const char*>(&handle), sizeof(handle));
      });
}

