#define DEBUG_TYPE "flattener_optimizer"
#define DBGS() (llvm::dbgs() << "[" DEBUG_TYPE "]: ")
#define DBGSNL() (llvm::dbgs() << "\n")
#define LDBG(X) LLVM_DEBUG(DBGS() << X << "\n")

namespace mlir {
namespace hfusion {
namespace detail {

// Flattener constructor: initializes data structures for dimension analysis
Flattener::Flattener(Operation *op) : DimensionAnalyzer(op) {
  // Initialize internal state: each operation's inputs/outputs are linked via arguments.
  // Each tensor dimension is assigned a unique index; we use union-find to group equal dims.
  //
  // Example:
  // args:     arg0        arg1       arg2
  // shape:   [7x6xf32]  [5xf32]   [8x7x6x9xf32]
  // indices:  0 1        2          3 4 5 6 7 8
  //
  // arg0 → {0,1}, arg1 → {2}, arg2 → {3,4,5,6,7,8}
  // ops may share subranges (e.g., op1 uses dims 4–5 from arg2)
  //
  // Union-find solverShapeElem_ merges equivalent dimensions.
  // Broadcast/reduce ops introduce new segments.
  //
  // Disable strict tensor.dim binding across regions to avoid over-constraining dynamic shapes.
  bindUsingTensorDim = false;
}

LogicalResult Flattener::flatten(bool allowMultiDynamic) {
  auto initRes = initialize();
  if (failed(initRes))
    return success();

  // Mark broken connections in each argument's dimension list
  for (size_t idx = 0; idx < argumentsRef_.size(); ++idx) {
    markBroken(argumentsRef_[idx]);
  }

  propagateBroken();

  // If multi-dynamic is disallowed, break all dynamic shape segments
  if (!allowMultiDynamic) {
    breakDynamicShapes();
    propagateBroken();
  }

  adjustOperations();
  return success();
}

/// Marks dimension connections as broken based on shape inference rules
void Flattener::markBroken(const DimensionIndex &dims) {
  int len = static_cast<int64_t>(dims.size());
  for (int i = 0; i < len; ++i) {
    // Left gap?
    if (i == 0 || dims[i - 1] != dims[i] - 1) {
      LLVM_DEBUG(llvm::dbgs() << "left gap at dim " << dims[i] << "\n");
      isConnected_[dims[i]].leftConnected = false;
      if (i > 0)
        isConnected_[dims[i - 1]].rightConnected = false;
      if (dims[i] > 0)
        isConnected_[dims[i] - 1].rightConnected = false;
    }

    // Right gap?
    if (i + 1 == static_cast<int>(dims.size()) || dims[i + 1] != dims[i] + 1) {
      LLVM_DEBUG(llvm::dbgs() << "right gap at dim " << dims[i] << "\n");
      isConnected_[dims[i]].rightConnected = false;
      if (i + 1 < static_cast<int>(dims.size()))
        isConnected_[dims[i + 1]].leftConnected = false;
      if (dims[i] + 1 < static_cast<int>(isConnected_.size()))
        isConnected_[dims[i] + 1].leftConnected = false;
    }
  }
}

/// Checks whether a mutation can propagate in direction `dir` from position `pos`
bool Flattener::computeMutation(int pos, int dir) const {
  LDBG("Checking mutation propagation: pos=" << pos << ", dir=" << dir);
  bool ok = true;
  int curr = pos;

  while (curr + dir >= 0 && curr + dir < static_cast<int64_t>(isConnected_.size())) {
    curr += dir;
    // Check connectivity barrier
    bool connected = isConnected_[std::min(curr, curr - dir)].rightConnected &&
                     isConnected_[std::max(curr, curr - dir)].leftConnected;
    if (!connected)
      break;

    // Only unit elements can be traversed
    if (isConnected_[curr].elementKind != ElementKind::Unit) {
      LDBG("Blocked by non-unit node " << curr << " (kind="
                                       << static_cast<int>(isConnected_[curr].elementKind) << ")");
      ok = false;
      break;
    }
  }

  LDBG("Mutation propagation possible? " << ok);
  return ok;
}

/// Step 4: Propagate broken connections through union-find and spread logic
void Flattener::propagateBroken() {
  propagateConnection();
  spreadConnection();

  // Break connections around mutation points
  for (int i = 0; i < argumentTotalLength_; ++i) {
    int root = solverCollapserElem_->find(i);
    if (root != i)
      continue;

    if (isConnected_[i].elementKind != ElementKind::HasMutation)
      continue;

    if (!computeMutation(i, -1))
      disconnect(i - 1, i);

    if (!computeMutation(i, 1))
      disconnect(i, i + 1);
  }

  propagateConnection();
  spreadConnection();
}

/// Step 4.5: Handle dynamic dimensions — prevent flattening multiple dynamics in one segment
void Flattener::breakDynamicShapes() {
  BitVector visited(argumentTotalLength_);
  auto markVisited = [&visited, this](int idx) {
    visited[solverCollapserElem_->find(idx)] = true;
  };

  int rightBound;
  for (int leftBound = 0; leftBound < argumentTotalLength_; leftBound = rightBound + 1) {
    markVisited(leftBound);
    LDBG("Segment start at index " << leftBound);
    assert(leftBound == 0 || !isConnected(leftBound - 1, leftBound));

    SmallVector<int> dynIndices;
    auto collectIfDynamic = [&dynIndices, this](int idx) {
      auto info = solverShapeElem_->getMinParentAndShapePair(idx);
      if (ShapedType::isDynamic(info.second))
        dynIndices.push_back(idx);
    };

    rightBound = leftBound;
    collectIfDynamic(rightBound);

    while (rightBound + 1 < argumentTotalLength_ && isConnected(rightBound, rightBound + 1)) {
      rightBound++;
      markVisited(rightBound);
      collectIfDynamic(rightBound);
    }

    // If more than one dynamic dimension exists in this segment, break between them
    if (dynIndices.size() > 1) {
      LDBG("Breaking multiple dynamic dims in segment: " << dynIndices.size());
      for (size_t k = 1; k < dynIndices.size(); ++k) {
        disconnect(dynIndices[k] - 1, dynIndices[k]);
      }
    }
  }
}

