#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int blackTiles, whiteTiles, costBlack, costWhite;
    if (!(cin >> blackTiles >> whiteTiles >> costBlack >> costWhite)) return 0;

    char bgColor, islandColor; // bgColor = background, islandColor = island
    int islandCount; // Number of islands of islandColor
    int holeCount;   // Number of holes of bgColor inside islandColor islands

    // Choose the cheaper color as background to minimize total cost
    if (costBlack < costWhite) {
        bgColor = '@';
        islandColor = '.';
        islandCount = whiteTiles;
        holeCount = blackTiles - 1;
    } else {
        bgColor = '.';
        islandColor = '@';
        islandCount = blackTiles;
        holeCount = whiteTiles - 1;
    }

    vector<string> resultGrid;

    if (holeCount == 0) {
        // No holes needed: create M simple disconnected islands
        string row0 = "", row1 = "";

        // Start with a background separator
        row0 += bgColor;
        row1 += bgColor;

        for (int idx = 0; idx < islandCount; ++idx) {
            row0 += islandColor; // Place island cell
            row1 += bgColor;     // Background below

            row0 += bgColor;     // Separator after island
            row1 += bgColor;     // Continue background
        }

        resultGrid.push_back(row0);
        resultGrid.push_back(row1);
    } else {
        // Need holes: build one complex island with all holes + remaining simple islands
        string topRow = "", middleRow = "", bottomRow = "", baseRow = "";

        // Initial separator column
        topRow += bgColor;
        middleRow += bgColor;
        bottomRow += bgColor;
        baseRow += bgColor;

        // Complex island containing all holes (spans 3 rows)
        for (int h = 0; h < 2 * holeCount + 1; ++h) {
            topRow += islandColor;
            if (h % 2 == 0) {
                middleRow += islandColor;
            } else {
                middleRow += bgColor; // This is a hole
            }
            bottomRow += islandColor;
            baseRow += bgColor;
        }

        // Separator after complex island
        topRow += bgColor;
        middleRow += bgColor;
        bottomRow += bgColor;
        baseRow += bgColor;

        // Add remaining simple islands (islandCount - 1)
        for (int s = 0; s < islandCount - 1; ++s) {
            topRow += bgColor;
            middleRow += islandColor;
            bottomRow += bgColor;
            baseRow += bgColor;

            // Separator after each simple island
            topRow += bgColor;
            middleRow += bgColor;
            bottomRow += bgColor;
            baseRow += bgColor;
        }

        resultGrid.push_back(topRow);
        resultGrid.push_back(middleRow);
        resultGrid.push_back(bottomRow);
        resultGrid.push_back(baseRow);
    }

    cout << resultGrid.size() << " " << resultGrid[0].size() << "\n";
    for (const string& line : resultGrid) {
        cout << line << "\n";
    }

    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

// Global variable to store n for use in query function with bounds checking
long long global_n;

// Function to send a query and process the response; exits on response 0
int query(long long val_x, long long val_y) {
    // Clamp input values to valid range [1, global_n]
    if (val_x < 1) val_x = 1;
    if (val_x > global_n) val_x = global_n;
    if (val_y < 1) val_y = 1;
    if (val_y > global_n) val_y = global_n;

    std::cout << val_x << " " << val_y << std::endl;
    int result;
    std::cin >> result;

    if (result == 0) {
        exit(0);
    }
    return result;
}

int main() {
    // Optimize I/O performance
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::cin >> global_n;

    // Initialize search ranges for two unknown numbers
    long long range_a_min = 1, range_a_max = global_n;
    long long range_b_min = 1, range_b_max = global_n;

    while (true) {
        // If both ranges are narrowed to single values, we've found the solution
        if (range_a_min == range_a_max && range_b_min == range_b_max) {
            query(range_a_min, range_b_min);
            break; // Should not reach here due to early exit in query()
        }

        // If 'a' is known exactly, perform binary search on 'b'
        if (range_a_min == range_a_max) {
            long long mid_b = range_b_min + (range_b_max - range_b_min) / 2;
            int res = query(range_a_min, mid_b);

            if (res == 2) { // y < b → mid_b < b
                range_b_min = mid_b + 1;
            } else { // res == 3: since x=a, must be y > b → mid_b > b
                range_b_max = mid_b - 1;
            }
            continue;
        }

        // If 'b' is known exactly, perform binary search on 'a'
        if (range_b_min == range_b_max) {
            long long mid_a = range_a_min + (range_a_max - range_a_min) / 2;
            int res = query(mid_a, range_b_min);

            if (res == 1) { // x < a → mid_a < a
                range_a_min = mid_a + 1;
            } else { // res == 3: since y=b, must be x > a → mid_a > a
                range_a_max = mid_a - 1;
            }
            continue;
        }

        // Both 'a' and 'b' still have uncertainty: query midpoints of both ranges
        long long mid_a = range_a_min + (range_a_max - range_a_min) / 2;
        long long mid_b = range_b_min + (range_b_max - range_b_min) / 2;

        int res = query(mid_a, mid_b);

        if (res == 1) { // x < a
            range_a_min = mid_a + 1;
        } else if (res == 2) { // y < b
            range_b_min = mid_b + 1;
        } else { // res == 3: ambiguous case (x > a or y > b)
            // Heuristic: shrink the larger range to balance search space reduction
            if ((range_a_max - range_a_min) >= (range_b_max - range_b_min)) {
                range_a_max = mid_a - 1;
            } else {
                range_b_max = mid_b - 1;
            }
        }
    }

    return 0;
}

