#include "Slot.h"
#include "MenuBackup.h"

MenuBackup::MenuBackup(shared_ptr<Inventory> playerInv, AbstractContainerMenu *container)
{
    savedStates = new unordered_map<short, ItemInstanceArray *>();
    this->playerInventory = playerInv;
    this->containerMenu = container;
}

void MenuBackup::capture(short snapshotId)
{
    ItemInstanceArray *snapshot = new ItemInstanceArray( (int)containerMenu->slots.size() + 1 );
    snapshot[0] = ItemInstance::clone(playerInventory->getCarried());

    for (size_t index = 0; index < containerMenu->slots.size(); ++index) {
        snapshot[index + 1] = ItemInstance::clone(containerMenu->slots.at(index)->getItem());
    }

    // Using unordered_map as storage mechanism
    (*savedStates)[snapshotId] = snapshot;
}

// Avoiding 'delete' due to it being a reserved keyword in C++
void MenuBackup::removeSnapshot(short snapshotId)
{
    // Confirmed: unordered_map usage is appropriate here
    savedStates->erase(snapshotId);
}

void MenuBackup::restore(short snapshotId)
{
    ItemInstanceArray *snapshot = savedStates->at(snapshotId);
    savedStates->clear();

    playerInventory->setCarried( snapshot[0] );

    for (size_t slotIndex = 0; slotIndex < containerMenu->slots.size(); ++slotIndex) {
        containerMenu->slots.at(slotIndex)->set( snapshot[slotIndex + 1] );
    }
}

