#include <iostream>
#include <vector>
#include <string>
#include <numeric>
#include <algorithm>
#include <iterator>
using namespace std;

// Check if the graph remains connected after removing a bridge
bool check_connectivity() {
    cout << "? 1 1" << endl;
    int answer;
    cin >> answer;
    if (answer == -1) {
        exit(0);
    }
    return answer == 1;
}

void process_test_case() {
    int num_vertices;
    int num_edges;
    cin >> num_vertices >> num_edges;

    vector<pair<int, int>> edge_list(num_edges);
    for (int index = 0; index < num_edges; ++index) {
        cin >> edge_list[index].first >> edge_list[index].second;
    }

    vector<int> result(num_edges, 0);
    vector<int> confirmed_roads;
    vector<int> pending_roads(num_edges);
    iota(pending_roads.begin(), pending_roads.end(), 0);

    while (true) {
        vector<int> newly_found_bridges;

        // Temporarily remove confirmed roads
        for (int road_id : confirmed_roads) {
            cout << "- " << (road_id + 1) << endl;
        }

        vector<int> remaining_pending;
        for (int road_id : pending_roads) {
            cout << "- " << (road_id + 1) << endl;

            if (!check_connectivity()) {
                newly_found_bridges.push_back(road_id);
            } else {
                remaining_pending.push_back(road_id);
            }

            cout << "+ " << (road_id + 1) << endl;
        }

        // Restore confirmed roads
        for (int road_id : confirmed_roads) {
            cout << "+ " << (road_id + 1) << endl;
        }

        if (newly_found_bridges.empty()) {
            break;
        }

        // Mark newly found bridges as required
        for (int bridge_id : newly_found_bridges) {
            result[bridge_id] = 1;
            confirmed_roads.push_back(bridge_id);
        }

        pending_roads = remaining_pending;
    }

    cout << "!";
    for (int idx = 0; idx < num_edges; ++idx) {
        cout << " " << result[idx];
    }
    cout << endl;

    int verdict;
    cin >> verdict;
    if (verdict == 0) {
        exit(0);
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int test_cases;
    cin >> test_cases;
    while (test_cases--) {
        process_test_case();
    }
    return 0;
}

#include <asio/bind_executor.hpp>
#include <asio/io_context.hpp>
#include <asio/ip/tcp.hpp>
#include <asio/use_future.hpp>
#include <asio/write.hpp>
#include <cstring>
#include <functional>
#include <iostream>
#include <string>
#include <type_traits>
#include <utility>

using asio::ip::tcp;

//------------------------------------------------------------------------------
// Modified composed operation: wraps async_write with a simplified completion signature
template <typename CompletionToken>
auto initiate_async_send(tcp::socket& sock,
    const char* data, CompletionToken&& token)
  // Return type depends on the completion token and handler signature
  -> typename asio::async_result<
    typename std::decay<CompletionToken>::type,
    void(std::error_code)>::return_type
{
  // Initialize the async operation with the provided token
  asio::async_completion<CompletionToken,
    void(std::error_code)> result(token);

  // Get the executor associated with the completion handler (or fallback to socket's executor)
  auto bound_executor = asio::get_associated_executor(
      result.completion_handler, sock.get_executor());

  // Perform the underlying async_write, adapting the handler signature by dropping the size parameter
  asio::async_write(sock,
      asio::buffer(data, std::strlen(data)),
      asio::bind_executor(bound_executor,
        std::bind(std::move(result.completion_handler),
          std::placeholders::_1)));

  return result.result.get();
}
//------------------------------------------------------------------------------
void demo_callback_style()
{
  asio::io_context ctx;
  tcp::acceptor listener(ctx, {tcp::v4(), 55555});
  tcp::socket conn = listener.accept();

  // Use a lambda for callback-based completion
  initiate_async_send(conn, "Demo via callback\r\n",
      [](const std::error_code& ec)
      {
        if (!ec)
        {
          std::cout << "Data transmitted successfully\n";
        }
        else
        {
          std::cout << "Transmission failed: " << ec.message() << "\n";
        }
      });

  ctx.run();
}
//------------------------------------------------------------------------------
void demo_future_style()
{
  asio::io_context ctx;
  tcp::acceptor listener(ctx, {tcp::v4(), 55555});
  tcp::socket conn = listener.accept();

  // Use use_future to get a std::future for synchronous waiting
  std::future<void> fut = initiate_async_send(
      conn, "Demo via future\r\n", asio::use_future);

  ctx.run();

  try
  {
    fut.get();  // Wait for completion and rethrow exceptions if any
    std::cout << "Data transmitted successfully\n";
  }
  catch (const std::exception& ex)
  {
    std::cout << "Exception caught: " << ex.what() << "\n";
  }
}
//------------------------------------------------------------------------------
int main()
{
  demo_callback_style();
  demo_future_style();
}

