#include "valdi/android/MainThreadDispatcher.hpp"
#include <future>

namespace ValdiAndroid {

MainThreadDispatcher::MainThreadDispatcher(JavaEnv env, jobject obj)
    : GlobalRefJavaObjectBase(env, obj, "MainThreadManager") {
    auto instance = toObject();
    auto clazz = instance.getClass();
    clazz.getMethod("runOnMainThread", _runOnMainThreadMethod);
    clazz.getMethod("runOnMainThreadDelayed", _runOnMainThreadDelayedMethod);
}

MainThreadDispatcher::~MainThreadDispatcher() = default;

void MainThreadDispatcher::execute(Valdi::DispatchFunction* func, bool isSynchronous) {
    if (isSynchronous) {
        std::promise<void> completionPromise;
        auto resultFuture = completionPromise.get_future();

        // Wrap the function to ensure safe execution and cleanup
        // Original capture [&] was unsafe: could lead to use-after-free if stack frame
        // was destroyed before delete func completed.
        auto safeWrapper = new Valdi::DispatchFunction([func, &completionPromise]() {
            (*func)();
            completionPromise.set_value();
            delete func;
        });

        _runOnMainThreadMethod.call(toObject(), reinterpret_cast<int64_t>(safeWrapper));
        resultFuture.wait();
    } else {
        _runOnMainThreadMethod.call(toObject(), reinterpret_cast<int64_t>(func));
    }
}

void MainThreadDispatcher::schedule(int64_t delayMillis, Valdi::DispatchFunction* func) {
    _runOnMainThreadDelayedMethod.call(toObject(), delayMillis, reinterpret_cast<int64_t>(func));
}

} // namespace ValdiAndroid

