DiskArrayCollection::DiskArrayCollection(FileHandle& fileHandle, ShadowFile& shadowFile,
    bool skipShadowing)
    : fileHandle(fileHandle), shadowFile{shadowFile}, bypassShadowing{skipShadowing},
      numHeaders{0} {
    readTrxHeaders.emplace_back(std::make_unique<HeaderPage>());
    writeTrxHeaders.emplace_back(std::make_unique<HeaderPage>());
    diskHeaderPagesCount = 0;
}

DiskArrayCollection::DiskArrayCollection(FileHandle& fileHandle, ShadowFile& shadowFile,
    page_idx_t startHeaderPage, bool skipShadowing)
    : fileHandle(fileHandle), shadowFile{shadowFile}, bypassShadowing{skipShadowing},
      numHeaders{0} {
    // Load header pages from disk using optimistic reads (idempotent: may retry multiple times)
    page_idx_t currentPageIdx = startHeaderPage;
    do {
        std::unique_ptr<HeaderPage> loadedPage;
        page_idx_t nextIdx = INVALID_PAGE_IDX;
        fileHandle.optimisticReadPage(currentPageIdx, [&](auto* frame) {
            const auto* page = reinterpret_cast<const HeaderPage*>(frame);
            loadedPage = std::make_unique<HeaderPage>(*page);
            nextIdx = page->nextHeaderPage;
        });
        if (!loadedPage) {
            throw RuntimeException("Unable to load header page from disk.");
        }
        numHeaders += loadedPage->numHeaders;
        readTrxHeaders.emplace_back(std::make_unique<HeaderPage>(*loadedPage));
        writeTrxHeaders.push_back(std::move(loadedPage));
        currentPageIdx = nextIdx;
    } while (currentPageIdx != INVALID_PAGE_IDX);
    diskHeaderPagesCount = readTrxHeaders.size();
}

void DiskArrayCollection::checkpoint(page_idx_t firstHeaderPage, PageAllocator& allocator) {
    page_idx_t currentDiskPage = firstHeaderPage;
    for (page_idx_t memIndex = 0; memIndex < writeTrxHeaders.size(); ++memIndex) {
        if (writeTrxHeaders[memIndex]->nextHeaderPage == INVALID_PAGE_IDX &&
            memIndex < writeTrxHeaders.size() - 1) {
            // Allocate new header page for next checkpointed array version
            allocateNextHeaderPage(allocator, memIndex);
        }

        // Update only if modified or never written before
        if (memIndex >= diskHeaderPagesCount ||
            *writeTrxHeaders[memIndex] != *readTrxHeaders[memIndex]) {
            ShadowUtils::updatePage(*allocator.getDataFH(), currentDiskPage,
                true /*full-page write*/, shadowFile, [&](auto* frame) {
                    memcpy(frame, writeTrxHeaders[memIndex].get(), sizeof(HeaderPage));
                    if constexpr (sizeof(HeaderPage) < LBUG_PAGE_SIZE) {
                        // Clear unused space in page
                        std::fill(frame + sizeof(HeaderPage), frame + LBUG_PAGE_SIZE, 0);
                    }
                });
        }
        currentDiskPage = writeTrxHeaders[memIndex]->nextHeaderPage;
    }
    diskHeaderPagesCount = writeTrxHeaders.size();
}

void DiskArrayCollection::allocateNextHeaderPage(PageAllocator& allocator,
    common::page_idx_t memIndex) {
    auto newPage = allocator.allocatePage();
    writeTrxHeaders[memIndex]->nextHeaderPage = newPage;
    // Structural changes (e.g., new header page allocation) are not rollback-safe.
    // Apply same change to read version to keep versions consistent pre-checkpoint.
    readTrxHeaders[memIndex]->nextHeaderPage = newPage;
}

size_t DiskArrayCollection::appendDiskArray() {
    auto priorCount = numHeaders++;
    // May not reside on final header page — empty slots possible after rollback
    auto pageIndex = numHeaders % HeaderPage::NUM_HEADERS_PER_PAGE;
    if (pageIndex >= writeTrxHeaders.size()) {
        writeTrxHeaders.emplace_back(std::make_unique<HeaderPage>());
        // Mirror addition in read set; contents will be populated at next checkpoint
        readTrxHeaders.emplace_back(std::make_unique<HeaderPage>());
    }
    auto& targetPage = *writeTrxHeaders[pageIndex];
    DASSERT(targetPage.numHeaders < HeaderPage::NUM_HEADERS_PER_PAGE);
    auto slotIndex = targetPage.numHeaders;
    targetPage.headers[slotIndex] = DiskArrayHeader{};
    targetPage.numHeaders++;
    readTrxHeaders[pageIndex]->numHeaders++;
    return priorCount;
}

void DiskArrayCollection::releaseStorage(PageAllocator& allocator,
    common::page_idx_t firstHeaderPage) const {
    page_idx_t currentPage = firstHeaderPage;
    for (page_idx_t memIndex = 0; memIndex < readTrxHeaders.size(); ++memIndex) {
        if (currentPage == INVALID_PAGE_IDX) {
            break;
        }
        allocator.freePage(currentPage);
        currentPage = readTrxHeaders[memIndex]->nextHeaderPage;
    }
}

