#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <functional>
#if defined(__GNUC__) || defined(__clang__)
#define BUILTIN_CLZ __builtin_clz
#else
#include <intrin.h>
#define BUILTIN_CLZ __lzcnt
#endif

const int MAX_SIZE = 4100;
const int LOG_LEVELS = 13;

int array_size, query_count;
int input_array[MAX_SIZE];
int position_map[MAX_SIZE];
int node_counter;
std::vector<std::pair<int, int>> operation_list;

int rmq_min_table[LOG_LEVELS][MAX_SIZE];
int segment_tree_node_ids[4 * MAX_SIZE];

void construct_rmq() {
    for (int idx = 1; idx <= array_size; ++idx) {
        rmq_min_table[0][idx] = input_array[idx];
    }

    for (int level = 1; level < LOG_LEVELS; ++level) {
        int span = 1 << level;
        for (int start = 1; start + span - 1 <= array_size; ++start) {
            int half_span = 1 << (level - 1);
            rmq_min_table[level][start] = std::min(
                rmq_min_table[level - 1][start],
                rmq_min_table[level - 1][start + half_span]
            );
        }
    }
}

int range_minimum_query(int left, int right) {
    if (left > right) return array_size + 1;
    int length = right - left + 1;
    int exponent = 31 - BUILTIN_CLZ(length);
    return std::min(
        rmq_min_table[exponent][left],
        rmq_min_table[exponent][right - (1 << exponent) + 1]
    );
}

int build_segment_subtree(const std::vector<int>& sorted_values, int left_bound, int right_bound) {
    if (left_bound == right_bound - 1) {
        return position_map[sorted_values[left_bound]];
    }

    int middle = left_bound + (right_bound - left_bound) / 2;
    int left_child_id = build_segment_subtree(sorted_values, left_bound, middle);
    int right_child_id = build_segment_subtree(sorted_values, middle, right_bound);

    node_counter++;
    operation_list.push_back({left_child_id, right_child_id});
    return node_counter;
}

void construct_segment_tree(int tree_node, int range_left, int range_right) {
    if (range_left == range_right) {
        segment_tree_node_ids[tree_node] = range_left;
        return;
    }

    int mid_point = range_left + (range_right - range_left) / 2;
    construct_segment_tree(tree_node * 2, range_left, mid_point);
    construct_segment_tree(tree_node * 2 + 1, mid_point + 1, range_right);

    std::vector<int> temp_values;
    temp_values.reserve(range_right - range_left + 1);
    for (int i = range_left; i <= range_right; ++i) {
        temp_values.push_back(input_array[i]);
    }
    std::sort(temp_values.begin(), temp_values.end());

    segment_tree_node_ids[tree_node] = build_segment_subtree(temp_values, 0, temp_values.size());
}

struct QueryNode {
    int identifier;
    int left_range, right_range;
};

void collect_query_nodes(int tree_node, int range_left, int range_right, 
                         int query_left, int query_right, 
                         std::vector<QueryNode>& output) {
    if (query_left > query_right) {
        return;
    }

    if (query_left == range_left && query_right == range_right) {
        output.push_back({segment_tree_node_ids[tree_node], range_left, range_right});
        return;
    }

    int mid_point = range_left + (range_right - range_left) / 2;
    collect_query_nodes(tree_node * 2, range_left, mid_point,
                        query_left, std::min(query_right, mid_point), output);
    collect_query_nodes(tree_node * 2 + 1, mid_point + 1, range_right,
                        std::max(query_left, mid_point + 1), query_right, output);
}

struct SetMetadata {
    int id;
    int minimum_value;
};

bool compareSetMetadata(const SetMetadata& first, const SetMetadata& second) {
    return first.minimum_value < second.minimum_value;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::cin >> array_size >> query_count;
    for (int i = 1; i <= array_size; ++i) {
        std::cin >> input_array[i];
        position_map[input_array[i]] = i;
    }

    node_counter = array_size;

    construct_rmq();
    construct_segment_tree(1, 1, array_size);

    std::vector<int> answers(query_count);

    for (int q_idx = 0; q_idx < query_count; ++q_idx) {
        int l, r;
        std::cin >> l >> r;

        std::vector<QueryNode> node_collection;
        collect_query_nodes(1, 1, array_size, l, r, node_collection);

        std::vector<SetMetadata> set_data;
        set_data.reserve(node_collection.size());
        for (const auto& node : node_collection) {
            set_data.push_back({node.identifier, range_minimum_query(node.left_range, node.right_range)});
        }

        std::sort(set_data.begin(), set_data.end(), compareSetMetadata);

        if (set_data.size() == 1) {
            answers[q_idx] = set_data[0].id;
        } else {
            int merged_set_id = set_data[0].id;
            for (size_t j = 1; j < set_data.size(); ++j) {
                node_counter++;
                operation_list.push_back({merged_set_id, set_data[j].id});
                merged_set_id = node_counter;
            }
            answers[q_idx] = merged_set_id;
        }
    }

    std::cout << node_counter << "\n";
    for (const auto& op : operation_list) {
        std::cout << op.first << " " << op.second << "\n";
    }
    for (int i = 0; i < query_count; ++i) {
        std::cout << answers[i] << (i == query_count - 1 ? "" : " ");
    }
    std::cout << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int size;
    cin >> size;

    if (size == 1) {
        cout << 1 << " " << 1 << endl;
        cout.flush();
        return 0;
    }

    vector<int> baseArray(size + 1);
    mt19937 randomGen(chrono::steady_clock::now().time_since_epoch().count());
    bool baseFound = false;
    int attempts = 0;

    while (!baseFound && attempts < 100) {
        vector<int> candidate(size);
        iota(candidate.begin(), candidate.end(), 1);
        shuffle(candidate.begin(), candidate.end(), randomGen);

        cout << 0;
        for (int val : candidate) cout << " " << val;
        cout << endl;
        cout.flush();

        int response;
        cin >> response;

        if (response == 0) {
            baseFound = true;
            for (int idx = 1; idx <= size; idx++) {
                baseArray[idx] = candidate[idx - 1];
            }
        }
        attempts++;
    }

    // Proceed assuming base was found successfully
    vector<int> resultPermutation(size + 1, 0);
    int discoveredCount = 0;

    for (int value = 1; value <= size; value++) {
        vector<int> availablePositions;
        for (int pos = 1; pos <= size; pos++) {
            if (resultPermutation[pos] == 0) {
                availablePositions.push_back(pos);
            }
        }

        int left = 0, right = availablePositions.size() - 1;
        while (left < right) {
            int mid = (left + right) / 2;
            vector<int> subset;
            for (int k = left; k <= mid; k++) {
                subset.push_back(availablePositions[k]);
            }

            vector<int> tempPermutation(size + 1);
            for (int i = 1; i <= size; i++) {
                tempPermutation[i] = baseArray[i];
            }

            for (int position : subset) {
                tempPermutation[position] = value;
            }

            cout << 0;
            for (int i = 1; i <= size; i++) {
                cout << " " << tempPermutation[i];
            }
            cout << endl;
            cout.flush();

            int feedback;
            cin >> feedback;
            int countIncrease = feedback - discoveredCount;

            if (countIncrease == 1) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }

        int finalPosition = availablePositions[left];
        resultPermutation[finalPosition] = value;
        baseArray[finalPosition] = value;
        discoveredCount++;
    }

    cout << 1;
    for (int i = 1; i <= size; i++) {
        cout << " " << resultPermutation[i];
    }
    cout << endl;
    cout.flush();

    return 0;
}

