#include <iostream>
#include <vector>
using namespace std;

struct BinaryNode {
    int data;
    BinaryNode* leftChild;
    BinaryNode* rightChild;
    BinaryNode(int x) : data(x), leftChild(nullptr), rightChild(nullptr) {}
};

class TreeTraversal {
public:
    vector<int> getInorder(BinaryNode* node) {
        vector<int> result;
        BinaryNode* current = node;
        while (current != nullptr) {
            if (current->leftChild == nullptr) {
                // Process current node
                result.push_back(current->data);
                current = current->rightChild;
            } else {
                // Locate predecessor (rightmost node in left subtree)
                BinaryNode* pred = current->leftChild;
                while (pred->rightChild != nullptr && pred->rightChild != current) {
                    pred = pred->rightChild;
                }
                if (pred->rightChild == nullptr) {
                    // Establish thread
                    pred->rightChild = current;
                    current = current->leftChild;
                } else {
                    // Remove thread and process current node
                    pred->rightChild = nullptr;
                    result.push_back(current->data);
                    current = current->rightChild;
                }
            }
        }
        return result;
    }
};

int main() {
    // Construct a sample binary tree
    BinaryNode* root = new BinaryNode(1);
    root->rightChild = new BinaryNode(2);
    root->rightChild->leftChild = new BinaryNode(3);

    TreeTraversal solver;
    vector<int> traversalResult = solver.getInorder(root);

    cout << "Inorder sequence: ";
    for (int value : traversalResult) {
        cout << value << " ";
    }
    cout << endl;

    return 0;
}

