#include <bits/stdc++.h>
using namespace std;

int n, queries;
vector<int> values;
map<pair<int, int>, int> memo;
vector<pair<int, int>> operations;
int node_counter;

int build_tree(int left, int right) {
    pair<int, int> key = {left, right};
    if (memo.find(key) != memo.end()) return memo[key];

    vector<int> indices;
    for (int idx = left; idx <= right; ++idx) {
        indices.push_back(idx);
    }

    if (indices.empty()) return -1;

    sort(indices.begin(), indices.end(), [&](int x, int y) {
        return values[x] < values[y];
    });

    int current_node = indices[0];
    for (size_t j = 1; j < indices.size(); ++j) {
        int next_node = indices[j];
        node_counter++;
        operations.emplace_back(current_node, next_node);
        current_node = node_counter;
    }

    memo[key] = current_node;
    return current_node;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    cin >> n >> queries;
    values.resize(n + 1);
    for (int i = 1; i <= n; ++i) {
        cin >> values[i];
    }

    vector<int> results(queries);
    node_counter = n;

    for (int i = 0; i < queries; ++i) {
        int l, r;
        cin >> l >> r;
        results[i] = build_tree(l, r);
    }

    int total_nodes = node_counter;
    cout << total_nodes << '\n';

    for (auto [u, v] : operations) {
        cout << u << " " << v << '\n';
    }

    for (int i = 0; i < queries; ++i) {
        cout << results[i];
        if (i < queries - 1) cout << " ";
        else cout << "\n";
    }

    return 0;
}

