using namespace ChromaPrint3D;

// Test sRGB gamma correction round-trip conversion
TEST(Color, SrgbGammaRoundTrip) {
    for (float value : {0.0f, 0.01f, 0.04045f, 0.1f, 0.5f, 0.9f, 1.0f}) {
        float linear = SrgbToLinear(value);
        float restored = LinearToSrgb(linear);
        EXPECT_NEAR(restored, value, 1e-5f) << "Original value: " << value;
    }
}

// Test RGB to Lab and back conversion round-trip
TEST(Color, RgbLabRoundTrip) {
    Rgb input(0.2f, 0.5f, 0.8f);
    Lab lab_color = input.ToLab();
    Rgb recovered = lab_color.ToRgb();
    EXPECT_NEAR(recovered.r(), input.r(), 1e-4f);
    EXPECT_NEAR(recovered.g(), input.g(), 1e-4f);
    EXPECT_NEAR(recovered.b(), input.b(), 1e-4f);
}

// Verify consistency between ToLab() and static FromRgb()
TEST(Color, LabFromRgbConsistency) {
    Rgb rgb_input(0.3f, 0.6f, 0.1f);
    Lab lab_method1 = rgb_input.ToLab();
    Lab lab_method2 = Lab::FromRgb(rgb_input);
    EXPECT_FLOAT_EQ(lab_method1.l(), lab_method2.l());
    EXPECT_FLOAT_EQ(lab_method1.a(), lab_method2.a());
    EXPECT_FLOAT_EQ(lab_method1.b(), lab_method2.b());
}

// Verify consistency between ToRgb() and static FromLab()
TEST(Color, RgbFromLabConsistency) {
    Lab lab_input(50.0f, 20.0f, -30.0f);
    Rgb rgb_method1 = lab_input.ToRgb();
    Rgb rgb_method2 = Rgb::FromLab(lab_input);
    EXPECT_FLOAT_EQ(rgb_method1.r(), rgb_method2.r());
    EXPECT_FLOAT_EQ(rgb_method1.g(), rgb_method2.g());
    EXPECT_FLOAT_EQ(rgb_method1.b(), rgb_method2.b());
}

// DeltaE76 distance between identical colors should be zero
TEST(Color, DeltaE76SameColor) {
    Lab color(50.0f, 0.0f, 0.0f);
    EXPECT_FLOAT_EQ(Lab::DeltaE76(color, color), 0.0f);
}

// DeltaE76 distance for known test case (3-4-5 triangle)
TEST(Color, DeltaE76KnownValue) {
    Lab point_a(50.0f, 0.0f, 0.0f);
    Lab point_b(50.0f, 3.0f, 4.0f);
    float delta_e = Lab::DeltaE76(point_a, point_b);
    EXPECT_NEAR(delta_e, 5.0f, 1e-5f);
}

// Test 8-bit RGB to internal representation round-trip
TEST(Color, Rgb255RoundTrip) {
    uint8_t r_in = 128, g_in = 64, b_in = 200;
    Rgb converted = Rgb::FromRgb255(r_in, g_in, b_in);
    uint8_t r_out, g_out, b_out;
    converted.ToRgb255(r_out, g_out, b_out);
    EXPECT_EQ(r_out, r_in);
    EXPECT_EQ(g_out, g_in);
    EXPECT_EQ(b_out, b_in);
}

// Test basic arithmetic operations on RGB colors
TEST(Color, RgbArithmetic) {
    Rgb color1(0.1f, 0.2f, 0.3f);
    Rgb color2(0.4f, 0.5f, 0.6f);
    Rgb sum = color1 + color2;
    EXPECT_NEAR(sum.r(), 0.5f, 1e-6f);
    EXPECT_NEAR(sum.g(), 0.7f, 1e-6f);
    Rgb scaled = color1 * 2.0f;
    EXPECT_NEAR(scaled.r(), 0.2f, 1e-6f);
}

// Test basic arithmetic operations on Lab colors
TEST(Color, LabArithmetic) {
    Lab lab1(50.0f, 10.0f, -20.0f);
    Lab lab2(30.0f, -5.0f, 15.0f);
    Lab sum = lab1 + lab2;
    EXPECT_NEAR(sum.l(), 80.0f, 1e-6f);
    EXPECT_NEAR(sum.a(), 5.0f, 1e-6f);
}

// Test linear interpolation between two Lab colors
TEST(Color, LabLerp) {
    Lab start(0.0f, 0.0f, 0.0f);
    Lab end(100.0f, 50.0f, -50.0f);
    Lab midpoint = Lab::Lerp(start, end, 0.5f);
    EXPECT_NEAR(midpoint.l(), 50.0f, 1e-6f);
    EXPECT_NEAR(midpoint.a(), 25.0f, 1e-6f);
}

// Verify black and white points in Lab space
TEST(Color, BlackWhiteConversion) {
    Rgb black_point(0.0f, 0.0f, 0.0f);
    Lab black_lab = black_point.ToLab();
    EXPECT_NEAR(black_lab.l(), 0.0f, 0.1f);

    Rgb white_point(1.0f, 1.0f, 1.0f);
    Lab white_lab = white_point.ToLab();
    EXPECT_NEAR(white_lab.l(), 100.0f, 0.5f);
}

