#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    vector<int> arr(n+1);
    for (int idx = 1; idx <= n; ++idx) cin >> arr[idx];

    vector<pair<int,int>> operations;
    operations.reserve(2200000);

    vector<int> queries(m);
    vector<int> position(n+1);

    for (int idx = 1; idx <= n; ++idx) position[arr[idx]] = idx;

    long long totalCount = n;

    for (int idx = 0; idx < m; ++idx) {
        int left, right;
        cin >> left >> right;

        vector<int> values;
        values.reserve(right - left + 1);

        for (int j = left; j <= right; ++j) values.push_back(arr[j]);

        sort(values.begin(), values.end());

        if (values.empty()) {
            queries[idx] = 1; // fallback case
        } else {
            long long currentPos = position[values[0]];

            for (size_t t = 1; t < values.size(); ++t) {
                int valPos = position[values[t]];
                operations.emplace_back((int)currentPos, valPos);
                ++totalCount;
                currentPos = totalCount;
            }
            queries[idx] = (int)currentPos;
        }
    }

    cout << totalCount << "\n";

    for (auto &op : operations) {
        cout << op.first << " " << op.second << "\n";
    }

    for (int i = 0; i < m; ++i) {
        if (i > 0) cout << " ";
        cout << queries[i];
    }
    cout << "\n";

    return 0;
}

