#include <iostream>
#include <vector>
#include <cmath>
#include <cstdio>
#include <algorithm>
using namespace std;

const double PI = acos(-1.0);

// Compute squared distance between two 3D points
double sqDist(const array<double,3>& p1, const array<double,3>& p2) {
    double dx = p1[0] - p2[0];
    double dy = p1[1] - p2[1];
    double dz = p1[2] - p2[2];
    return dx*dx + dy*dy + dz*dz;
}

int main() {
    int pointCount;
    cin >> pointCount;
    vector<array<double,3>> points(pointCount);

    // Handle special case: two diametrically opposite points
    if (pointCount == 2) {
        points[0] = {0.0, 0.0, 1.0};
        points[1] = {0.0, 0.0, -1.0};
        double minDistance = 2.0;
        printf("%.12lf\n", minDistance);
        for (int idx = 0; idx < pointCount; ++idx)
            printf("%.12lf %.12lf %.12lf\n", points[idx][0], points[idx][1], points[idx][2]);
        return 0;
    }

    // Generate initial distribution using Fibonacci spiral on unit sphere
    double spacing = 2.0 / pointCount;
    double angleStep = PI * (3.0 - sqrt(5.0));   // golden angle in radians

    for (int idx = 0; idx < pointCount; ++idx) {
        double yCoord = idx * spacing - 1.0 + spacing / 2.0;
        double radius = sqrt(1.0 - yCoord * yCoord);
        double phi = idx * angleStep;
        double xCoord = cos(phi) * radius;
        double zCoord = sin(phi) * radius;
        points[idx] = {xCoord, yCoord, zCoord};
    }

    // Calculate initial minimum pairwise distance
    double bestMin = 1e100;
    for (int i = 0; i < pointCount; ++i) {
        for (int j = i + 1; j < pointCount; ++j) {
            double d2 = sqDist(points[i], points[j]);
            if (d2 < bestMin) bestMin = d2;
        }
    }
    bestMin = sqrt(bestMin);
    auto optimalPoints = points;

    // Iterative optimization using repulsive forces
    const int maxIterations = 100;
    const double tolerance = 1e-12;
    double learningRate = 0.1;
    double decayFactor = 0.995;

    for (int iteration = 0; iteration < maxIterations; ++iteration) {
        vector<array<double,3>> displacement(pointCount, {0.0, 0.0, 0.0});

        // Calculate repulsive forces (inverse square law)
        for (int i = 0; i < pointCount; ++i) {
            for (int j = i + 1; j < pointCount; ++j) {
                array<double,3> diff = {points[i][0] - points[j][0],
                                        points[i][1] - points[j][1],
                                        points[i][2] - points[j][2]};
                double distSq = diff[0]*diff[0] + diff[1]*diff[1] + diff[2]*diff[2];
                if (distSq < tolerance) continue;
                double invDistSq = 1.0 / distSq;
                displacement[i][0] += diff[0] * invDistSq;
                displacement[i][1] += diff[1] * invDistSq;
                displacement[i][2] += diff[2] * invDistSq;
                displacement[j][0] -= diff[0] * invDistSq;
                displacement[j][1] -= diff[1] * invDistSq;
                displacement[j][2] -= diff[2] * invDistSq;
            }
        }

        // Update positions and reproject onto sphere
        for (int i = 0; i < pointCount; ++i) {
            points[i][0] += learningRate * displacement[i][0];
            points[i][1] += learningRate * displacement[i][1];
            points[i][2] += learningRate * displacement[i][2];
            double magnitude = sqrt(points[i][0]*points[i][0] + 
                                   points[i][1]*points[i][1] + 
                                   points[i][2]*points[i][2]);
            if (magnitude > tolerance) {
                points[i][0] /= magnitude;
                points[i][1] /= magnitude;
                points[i][2] /= magnitude;
            }
        }

        // Evaluate new configuration
        double currentMin = 1e100;
        for (int i = 0; i < pointCount; ++i) {
            for (int j = i + 1; j < pointCount; ++j) {
                double d2 = sqDist(points[i], points[j]);
                if (d2 < currentMin) currentMin = d2;
            }
        }
        currentMin = sqrt(currentMin);

        // Update best solution if improved
        if (currentMin > bestMin) {
            bestMin = currentMin;
            optimalPoints = points;
        }

        learningRate *= decayFactor;
        if (learningRate < 1e-6) break;
    }

    // Output final result
    printf("%.12lf\n", bestMin);
    for (int i = 0; i < pointCount; ++i) {
        printf("%.12lf %.12lf %.12lf\n", optimalPoints[i][0], optimalPoints[i][1], optimalPoints[i][2]);
    }

    return 0;
}

