TEST_BEGIN(test_malloc_strtoumax_extended) {
    struct test_case_s {
        const char *input_value;
        const char *expected_tail;
        int base_value;
        int expected_error;
        const char *error_name;
        uintmax_t expected_value;
    };

#define ERR_CODE(e)     e, #e
#define UMAX_CONST(x)   ((uintmax_t)x##ULL)
#define SMAX_CONST(x)   ((uintmax_t)(intmax_t)x##LL)

    struct test_case_s test_cases[] = {
        {"0",     "0",    -1, ERR_CODE(EINVAL), UINTMAX_MAX},
        {"0",     "0",    1,  ERR_CODE(EINVAL), UINTMAX_MAX},
        {"0",     "0",    37, ERR_CODE(EINVAL), UINTMAX_MAX},
        {"",      "",     0,  ERR_CODE(EINVAL), UINTMAX_MAX},
        {"+",     "+",    0,  ERR_CODE(EINVAL), UINTMAX_MAX},
        {"++3",   "++3",  0,  ERR_CODE(EINVAL), UINTMAX_MAX},
        {"-",     "-",    0,  ERR_CODE(EINVAL), UINTMAX_MAX},
        {"42",    "",     0,  ERR_CODE(0),      UMAX_CONST(42)},
        {"+42",   "",     0,  ERR_CODE(0),      UMAX_CONST(42)},
        {"-42",   "",     0,  ERR_CODE(0),      SMAX_CONST(-42)},
        {"042",   "",     0,  ERR_CODE(0),      UMAX_CONST(042)},
        {"+042",  "",     0,  ERR_CODE(0),      UMAX_CONST(042)},
        {"-042",  "",     0,  ERR_CODE(0),      SMAX_CONST(-042)},
        {"0x42",  "",     0,  ERR_CODE(0),      UMAX_CONST(0x42)},
        {"+0x42", "",     0,  ERR_CODE(0),      UMAX_CONST(0x42)},
        {"-0x42", "",     0,  ERR_CODE(0),      SMAX_CONST(-0x42)},
        {"0",     "",     0,  ERR_CODE(0),      UMAX_CONST(0)},
        {"1",     "",     0,  ERR_CODE(0),      UMAX_CONST(1)},
        {"42",    "",     0,  ERR_CODE(0),      UMAX_CONST(42)},
        {" 42",   "",     0,  ERR_CODE(0),      UMAX_CONST(42)},
        {"42 ",   " ",    0,  ERR_CODE(0),      UMAX_CONST(42)},
        {"0x",    "x",    0,  ERR_CODE(0),      UMAX_CONST(0)},
        {"42x",   "x",    0,  ERR_CODE(0),      UMAX_CONST(42)},
        {"07",    "",     0,  ERR_CODE(0),      UMAX_CONST(7)},
        {"010",   "",     0,  ERR_CODE(0),      UMAX_CONST(8)},
        {"08",    "8",    0,  ERR_CODE(0),      UMAX_CONST(0)},
        {"0_",    "_",    0,  ERR_CODE(0),      UMAX_CONST(0)},
        {"0x",    "x",    0,  ERR_CODE(0),      UMAX_CONST(0)},
        {"0X",    "X",    0,  ERR_CODE(0),      UMAX_CONST(0)},
        {"0xg",   "xg",   0,  ERR_CODE(0),      UMAX_CONST(0)},
        {"0XA",   "",     0,  ERR_CODE(0),      UMAX_CONST(10)},
        {"010",   "",     10, ERR_CODE(0),      UMAX_CONST(10)},
        {"0x3",   "x3",   10, ERR_CODE(0),      UMAX_CONST(0)},
        {"12",    "2",    2,  ERR_CODE(0),      UMAX_CONST(1)},
        {"78",    "8",    8,  ERR_CODE(0),      UMAX_CONST(7)},
        {"9a",    "a",    10, ERR_CODE(0),      UMAX_CONST(9)},
        {"9A",    "A",    10, ERR_CODE(0),      UMAX_CONST(9)},
        {"fg",    "g",    16, ERR_CODE(0),      UMAX_CONST(15)},
        {"FG",    "G",    16, ERR_CODE(0),      UMAX_CONST(15)},
        {"0xfg",  "g",    16, ERR_CODE(0),      UMAX_CONST(15)},
        {"0XFG",  "G",    16, ERR_CODE(0),      UMAX_CONST(15)},
        {"z_",    "_",    36, ERR_CODE(0),      UMAX_CONST(35)},
        {"Z_",    "_",    36, ERR_CODE(0),      UMAX_CONST(35)}
    };

#undef ERR_CODE
#undef UMAX_CONST
#undef SMAX_CONST

    unsigned index;
    for (index = 0; index < sizeof(test_cases)/sizeof(struct test_case_s); index++) {
        struct test_case_s *current_test = &test_cases[index];
        int error;
        uintmax_t conversion_result;
        char *output_remainder;
        set_errno(0);
        conversion_result = malloc_strtoumax(current_test->input_value, &output_remainder, current_test->base_value);
        error = get_errno();

        expect_d_eq(error, current_test->expected_error,
            "Expected errno %s for \"%s\", base %d",
            current_test->error_name, current_test->input_value, current_test->base_value);

        expect_str_eq(output_remainder, current_test->expected_tail,
            "Unexpected remainder for \"%s\", base %d",
            current_test->input_value, current_test->base_value);

        if (error == 0) {
            expect_ju_eq(conversion_result, current_test->expected_value,
                "Unexpected result for \"%s\", base %d",
                current_test->input_value, current_test->base_value);
        }
    }
}
TEST_END

TEST_BEGIN(test_malloc_snprintf_truncated_modified) {
#define BUFFER_SIZE	15
	char buffer[BUFFER_SIZE];
	size_t written_length;
	size_t buffer_length;

#define TEST_CASE(expected_string_untruncated, ...) do {			\
	written_length = malloc_snprintf(buffer, buffer_length, __VA_ARGS__);	\
	expect_d_eq(strncmp(buffer, expected_string_untruncated, buffer_length-1), 0,	\
	    "Unexpected string inequality (\"%s\" vs \"%s\")",		\
	    buffer, expected_string_untruncated);				\
	expect_zu_eq(written_length, strlen(expected_string_untruncated),		\
	    "Unexpected result");					\
} while (0)

	for (buffer_length = 1; buffer_length < BUFFER_SIZE; buffer_length++) {
		TEST_CASE("012346789",	"012346789");
		TEST_CASE("a0123b",	"a%sb", "0123");
		TEST_CASE("a01234567",	"a%s%s", "0123", "4567");
		TEST_CASE("a0123  ",	"a%-6s", "0123");
		TEST_CASE("a  0123",	"a%6s", "0123");
		TEST_CASE("a   012",	"a%6.3s", "0123");
		TEST_CASE("a   012",	"a%*.*s", 6, 3, "0123");
		TEST_CASE("a 123b",	"a% db", 123);
		TEST_CASE("a123b",	"a%-db", 123);
		TEST_CASE("a-123b",	"a%-db", -123);
		TEST_CASE("a+123b",	"a%+db", 123);
	}
#undef BUFFER_SIZE
#undef TEST_CASE
}
TEST_END

