#include "staticsparser.h"
#include "io/BinaryReader.h"
#include <cassert>
#include <iostream>
#include <iomanip>

template<typename Element, typename SizeType>
struct StaticArray {
    Element* elements = nullptr;
    SizeType count = 0;

    ~StaticArray() {
        delete[] elements;
    }

    void AllocateFrom(BinaryReader& stream) {
        stream.ReadLE(count);
        delete[] elements;
        if (count > 0)
            elements = new Element[count];
    }

    void LoadFrom(BinaryReader& stream) {
        for (SizeType idx = 0; idx < count; idx++)
            elements[idx].LoadFrom(stream);
    }

    void AllocateAndLoad(BinaryReader& stream) {
        AllocateFrom(stream);
        LoadFrom(stream);
    }
};

struct stringReference_t {
    uint32_t size = 0;
    const char* content = nullptr;

    void LoadFrom(BinaryReader& stream) {
        assert(stream.ReadLE(size));
        assert(stream.ReadBytes(content, size));
    }
};

typedef StaticArray<stringReference_t, uint32_t> stringArray_t;

void DisplayStrings(stringArray_t& list) {
    for (uint32_t index = 0; index < list.count; index++)
        printf("\"%.*s\"\n", list.elements[index].size, list.elements[index].content);
}

struct recordEntry_t {
    uint32_t field0;
    uint32_t field1;
    uint32_t field2;
    uint32_t field3;
    uint32_t field4;
    uint32_t field5;
    uint32_t field6;
    uint32_t field7;

    void LoadFrom(BinaryReader& stream) {
        stream.ReadLE(field0);
        stream.ReadLE(field1);
        stream.ReadLE(field2);
        stream.ReadLE(field3);
        stream.ReadLE(field4);
        stream.ReadLE(field5);
        stream.ReadLE(field6);
        stream.ReadLE(field7);
    }
};

struct recordBlock_t {
    StaticArray<recordEntry_t, uint32_t> records;
    uint32_t zeroValue;
    uint32_t worldEntityId;
    uint32_t primaryTableSize;

    void LoadFrom(BinaryReader& stream) {
        records.AllocateFrom(stream);
        stream.ReadLE(zeroValue);
        assert(zeroValue == 0);
        stream.ReadLE(worldEntityId);
        stream.ReadLE(primaryTableSize);
        records.LoadFrom(stream);
    }
};

void AbortParsing(BinaryReader& stream) {
    printf("%zu\n", stream.GetPosition());
    assert(0);
    //std::cout << std::hex << std::setfill('0') << std::setw(16) << (const void*)(end - start) << std::endl;
}

struct StaticDataSection {
    recordBlock_t mainRecord;
    stringArray_t arrayA;
    stringArray_t arrayB;

    void LoadFrom(BinaryReader& stream) {
        mainRecord.LoadFrom(stream);
        arrayA.AllocateAndLoad(stream);
        assert(arrayA.count == mainRecord.primaryTableSize);

        while (true) {
            uint32_t opcode, aux0, aux1;
            assert(stream.ReadLE(opcode));
            if (opcode == 0) {
                stream.ReadLE(aux0);
                stream.ReadLE(aux1);
                assert(aux0 == 0 && aux1 == 0);
            } else {
                AbortParsing(stream);
            }
        }
        //DisplayStrings(arrayA);
        //const char* start = stream.GetNext();
        //const char* end = stream.GetNext();
        //std::cout << std::hex << std::setfill('0') << std::setw(16) << (const void*)(end - start) << std::endl;
    }
};

void StaticsParser::Parse(BinaryReader& stream) {
    StaticDataSection data;
    data.LoadFrom(stream);
}

#include <gtest/gtest.h>
