using namespace NPerforator::NLinguist::NPython;

// Forward declaration of TryScanVersion function
namespace NPerforator::NLinguist::NPython {
    TMaybe<TPythonVersion> TryScanVersion(TConstArrayRef<char> data);
}

TEST(PythonVersionParsing, TryScanVersion) {
    struct TestCaseData {
        TString InputString;
        bool IsExpectedToParse;
        TPythonVersion ExpectedParsedVersion;
    };

    TVector<TestCaseData> testCases = {
        {"Python 3.10.0", true, {3, 10, 0}},
        {"Python 3.10.1", true, {3, 10, 1}},
        {"Python 2.7", true, {2, 7, 0}},
        {"Python 2.7.10", true, {2, 7, 10}},
        {"Python 3.8.15", true, {3, 8, 15}},
        {"Python 3.12.0", true, {3, 12, 0}},
        {"Python 3.12.1", true, {3, 12, 1}},
        {"Python 2.8.3", true, {2, 8, 3}},
        {"Python version 3.10.0, 64 bit", true, {3, 10, 0}},
        {"Version: Python 2.7.15", true, {2, 7, 15}},
        {"Python 4.0.0", false, {}},  // Unsupported major version
        {"No version here", false, {}},
        {"Python v9.8.7", false, {}},
    };

    for (const auto& testCase : testCases) {
        TMaybe<TPythonVersion> actualResult = TryScanVersion(
            TConstArrayRef<char>{testCase.InputString.data(), testCase.InputString.size()}
        );

        if (testCase.IsExpectedToParse) {
            ASSERT_TRUE(actualResult.Defined()) 
                << "Failed to parse version from string: '" << testCase.InputString << "'";

            TString expectedStr = std::to_string(testCase.ExpectedParsedVersion.MajorVersion) + "." +
                                  std::to_string(testCase.ExpectedParsedVersion.MinorVersion) + "." +
                                  std::to_string(testCase.ExpectedParsedVersion.MicroVersion);

            TString actualStr = std::to_string(actualResult->MajorVersion) + "." +
                                std::to_string(actualResult->MinorVersion) + "." +
                                std::to_string(actualResult->MicroVersion);

            EXPECT_EQ(actualResult->MajorVersion, testCase.ExpectedParsedVersion.MajorVersion)
                << "Major version mismatch for input: '" << testCase.InputString
                << "', expected: " << expectedStr << ", got: " << actualStr;

            EXPECT_EQ(actualResult->MinorVersion, testCase.ExpectedParsedVersion.MinorVersion)
                << "Minor version mismatch for input: '" << testCase.InputString
                << "', expected: " << expectedStr << ", got: " << actualStr;

            EXPECT_EQ(actualResult->MicroVersion, testCase.ExpectedParsedVersion.MicroVersion)
                << "Micro version mismatch for input: '" << testCase.InputString
                << "', expected: " << expectedStr << ", got: " << actualStr;
        } else {
            EXPECT_FALSE(actualResult.Defined())
                << "Should not parse version from string: '" << testCase.InputString << "'";
        }
    }
}

