	Minecraft *mcInstance = Minecraft::GetInstance();
	mcInstance->localplayers[padIndex]->respawn();
	app.SetGameStarted(true);
	mcInstance->gameRenderer->EnableUpdateThread();

	// Wait until respawn completes (online mode) or proceed immediately (offline)
