#include "IRrecv.h"
#include "IRsend.h"
#include "IRutils.h"

/// @file
/// @brief Arris "Manchester code" based infrared protocol implementation.
/// @see https://github.com/crankyoldgit/IRremoteESP8266/issues/1595
// Supports:
//   Brand: Arris,  Model: VIP1113M Set-top box
//   Brand: Arris,  Model: 120A V1.0 A18 remote

const uint8_t kArrisOverhead = 2;
const uint16_t kArrisHalfClockPeriod = 320;  // microseconds
const uint16_t kArrisHdrMark = 8 * kArrisHalfClockPeriod;  // microseconds
const uint16_t kArrisHdrSpace = 6 * kArrisHalfClockPeriod;  // microseconds

/// @see https://github.com/crankyoldgit/IRremoteESP8266/issues/1595#issuecomment-913755841
// Total gap duration: 77184 microseconds.
const uint32_t kArrisGapSpace = 102144 - ((14 + kArrisBits * 2) *
                                          kArrisHalfClockPeriod);  // microseconds

const uint32_t kArrisReleaseToggle = 0x800008;
const uint8_t kArrisChecksumSize = 4;
const uint8_t kArrisCommandSize = 19;
const uint8_t kArrisReleaseBit = kArrisChecksumSize + kArrisCommandSize;

using irutils::sumNibbles;

#if SEND_ARRIS

/// Send an Arris Manchester-coded IR message.
/// Status: STABLE / Confirmed working.
/// @param[in] message The data payload to transmit.
/// @param[in] nbits Number of bits in the message to send.
/// @param[in] repeat How many times the transmission should be repeated.
/// @see https://github.com/crankyoldgit/IRremoteESP8266/issues/1595
void IRsend::sendArris(const uint64_t message, const uint16_t nbits,
                       const uint16_t repeat) {
  enableIROut(38);
  for (uint16_t r = 0; r <= repeat; r++) {
    // Initial header segment
    mark(kArrisHdrMark);
    space(kArrisHdrSpace);
    // Second header part + Manchester-encoded data + footer
    sendManchester(kArrisHalfClockPeriod * 2, 0, kArrisHalfClockPeriod,
                   0, kArrisGapSpace, message, nbits);
  }
}

/// Toggle the release bit in an Arris message.
/// Used to differentiate between button press and button release events.
/// @param[in] message The existing Arris message.
/// @return Modified message with the release bit inverted.
uint32_t IRsend::toggleArrisRelease(const uint32_t message) {
  return message ^ kArrisReleaseToggle;
}

/// Encode an Arris command into a 32-bit raw message.
/// @param[in] opcode The command value to encode.
/// @param[in] action Whether this is a press (false) or release (true) event.
/// @return Encoded 32-bit message suitable for sendArris().
/// @note Bit layout: header(32) + release(1) + opcode(19) + checksum(4).
uint32_t IRsend::encodeArris(const uint32_t opcode, const bool action) {
  uint32_t result = 0x10000000;
  irutils::setBits(&result, kArrisChecksumSize, kArrisCommandSize, opcode);
  irutils::setBit(&result, kArrisReleaseBit, action);
  return result + sumNibbles(result);
}
#endif  // SEND_ARRIS

#if DECODE_ARRIS

/// Decode an Arris Manchester-coded IR signal.
/// Status: STABLE / Confirmed working.
/// @param[in,out] results Pointer to decode result structure to populate.
/// @param[in] offset Starting position in raw buffer for decoding.
/// @param[in] nbits Expected number of data bits.
/// @param[in] strict Whether to enforce strict protocol compliance.
/// @return true if decoding succeeded, false otherwise.
/// @see https://github.com/crankyoldgit/IRremoteESP8266/issues/1595
bool IRrecv::decodeArris(decode_results *results, uint16_t offset,
                         const uint16_t nbits, const bool strict) {
  if (results->rawlen < nbits + kArrisOverhead - offset)
    return false;  // Message too short for valid match.

  // Protocol compliance check
  if (strict && nbits != kArrisBits)
    return false;  // Doesn't match expected protocol length.

  // First header segment verification
  if (!matchMark(results->rawbuf[offset++], kArrisHdrMark)) return false;
  if (!matchSpace(results->rawbuf[offset++], kArrisHdrSpace)) return false;

  // Decode Manchester-encoded data portion
  uint64_t message = 0;
  if (!matchManchester(results->rawbuf + offset, &message,
                       results->rawlen - offset, nbits,
                       kArrisHalfClockPeriod * 2, 0,
                       kArrisHalfClockPeriod, 0, 0,
                       false, kUseDefTol, kMarkExcess, true, false))
    return false;

  // Checksum validation if strict mode enabled
  if (strict) {
    uint8_t storedChecksum = GETBITS32(message, 0, kArrisChecksumSize);
    uint8_t computedChecksum = sumNibbles(message >> kArrisChecksumSize);
    if (storedChecksum != computedChecksum)
      return false;
  }

  // Populate decode results
  results->decode_type = decode_type_t::ARRIS;
  results->bits = nbits;
  results->value = message;
  results->address = static_cast<bool>(GETBIT32(message, kArrisReleaseBit));
  results->command = GETBITS32(message, kArrisChecksumSize, kArrisCommandSize);

  return true;
}
#endif  // DECODE_ARRIS

