struct TestSE3CostFunctor {
  EIGEN_MAKE_ALIGNED_OPERATOR_NEW
  TestSE3CostFunctor(Sophus::SE3d T_ba) : T_ba(T_ba) {}
  template <class T>
  bool operator()(T const* const sT_ab, T* sResiduals) const {
    Eigen::Map<Sophus::SE3<T> const> const T_ab(sT_ab);
    Eigen::Map<Eigen::Matrix<T, 6, 1> > residuals(sResiduals);
    residuals = (T_ba * T_ab).log();
    residuals = (T_ab * T_ba).log();
    residuals = (T_ab * T_ba.cast<T>()).log();
    return true;
  }
  Sophus::SE3d T_ba;
};

struct TestPointCostFunctor {
  EIGEN_MAKE_ALIGNED_OPERATOR_NEW
  TestPointCostFunctor(Sophus::SE3d T_ba, Eigen::Vector3d point_a)
      : T_ba(T_ba), point_a(point_a) {}
  template <class T>
  bool operator()(T const* const sT_ab, T const* const spoint_b,
                  T* sResiduals) const {
    using Vector3T = Eigen::Matrix<T, 3, 1>;
    Eigen::Map<Sophus::SE3<T> const> const T_ab(sT_ab);
    Eigen::Map<Vector3T const> point_b(spoint_b);
    Eigen::Map<Vector3T> residuals(sResiduals);
    Vector3T point_b_prime = T_ba * point_b;
    point_b_prime = T_ba.cast<T>() * point_b;
    Vector3T point_a_prime = T_ab * point_a;
    point_a_prime = T_ab * point_a.cast<T>();
    residuals = point_b_prime - point_a_prime;
    return true;
  }
  Sophus::SE3d T_ba;
  Eigen::Vector3d point_a;
};

bool test(Sophus::SE3d const& T_target, Sophus::SE3d const& T_init,
          Sophus::SE3d::Point const& point_a_init,
          Sophus::SE3d::Point const& point_b) {
  static constexpr int kNumPointParameters = 3;
  Sophus::SE3d T_wr = T_init;
  Sophus::SE3d::Point point_a = point_a_init;

  ceres::Problem problem;
  problem.AddParameterBlock(T_wr.data(), Sophus::SE3d::num_parameters,
                            new Sophus::test::LocalParameterizationSE3);

  ceres::CostFunction* cost_function1 =
      new ceres::AutoDiffCostFunction<TestSE3CostFunctor, Sophus::SE3d::DoF,
                                      Sophus::SE3d::num_parameters>(
          new TestSE3CostFunctor(T_target.inverse()));
  problem.AddResidualBlock(cost_function1, NULL, T_wr.data());

  ceres::CostFunction* cost_function2 =
      new ceres::AutoDiffCostFunction<TestPointCostFunctor, kNumPointParameters,
                                      Sophus::SE3d::num_parameters,
                                      kNumPointParameters>(
          new TestPointCostFunctor(T_target.inverse(), point_b));
  problem.AddResidualBlock(cost_function2, NULL, T_wr.data(), point_a.data());

  ceres::Solver::Options options;
  options.gradient_tolerance = 0.01 * Sophus::Constants<double>::epsilon();
  options.function_tolerance = 0.01 * Sophus::Constants<double>::epsilon();
  options.linear_solver_type = ceres::DENSE_QR;

  ceres::Solver::Summary summary;
  Solve(options, &problem, &summary);
  std::cout << summary.BriefReport() << std::endl;

  double const mse = (T_target.inverse() * T_wr).log().squaredNorm();
  bool const passed = mse < 10. * Sophus::Constants<double>::epsilon();
  return passed;
}

template <typename Scalar>
bool CreateSE3FromMatrix(const Eigen::Matrix<Scalar, 4, 4>& mat) {
  Sophus::SE3<Scalar> se3 = Sophus::SE3<Scalar>(mat);
  std::cout << se3.translation().y() << std::endl;
  return true;
}

int main(int, char**) {
  using SE3Type = Sophus::SE3<double>;
  using SO3Type = Sophus::SO3<double>;
  using Point = SE3Type::Point;
  double const kPi = Sophus::Constants<double>::pi();

  std::vector<SE3Type> se3_vec;
  se3_vec.push_back(
      SE3Type(SO3Type::exp(Point(0.1, 0.3, 0.0)), Point(0, 0, 0)));
  se3_vec.push_back(
      SE3Type(SO3Type::exp(Point(0.1, 0.3, -0.5)), Point(5, 0, 0)));
  se3_vec.push_back(SE3Type(SO3Type::exp(Point(0., 0., 0.)), Point(0, 50, 3)));
  se3_vec.push_back(
      SE3Type(SO3Type::exp(Point(0., 0., 0.00002)), Point(0, 0, 0)));
  se3_vec.push_back(SE3Type(SO3Type::exp(Point(0., 0., 0.00002)),
                            Point(0, -0.00000002, 0.0000000002)));
  se3_vec.push_back(
      SE3Type(SO3Type::exp(Point(0., 0., 0.00002)), Point(0.02, 0, 0)));
  se3_vec.push_back(SE3Type(SO3Type::exp(Point(kPi, 0, 0)), Point(2, -3, 0)));
  se3_vec.push_back(
      SE3Type(SO3Type::exp(Point(0.1, 0.3, 0.0)), Point(0, 0, 0)) *
      SE3Type(SO3Type::exp(Point(kPi, 0, 0)), Point(0, 0, 0)) *
      SE3Type(SO3Type::exp(Point(-0.1, -0.3, -0.0)), Point(0, 0, 0)));
  se3_vec.push_back(
      SE3Type(SO3Type::exp(Point(0.2, 0.3, 0.1)), Point(1, 0, -4)) *
      SE3Type(SO3Type::exp(Point(kPi, 0, 0)), Point(0, 0, 0)) *
      SE3Type(SO3Type::exp(Point(-0.2, -0.3, -0.1)), Point(0, 3, 0)));

  std::vector<Point> point_vec;
  point_vec.emplace_back(1.024, 2.76, -1.48);
  point_vec.emplace_back(9.4, -7.1, -4.2);
  point_vec.emplace_back(2.3, 0.2, 9.2);
  point_vec.emplace_back(12.1, 1.8, 3.6);
  point_vec.emplace_back(-3.12, 3.24, 2.1);
  point_vec.emplace_back(-8.2, 6.3, -1.3);
  point_vec.emplace_back(0.1, 2.6, 5.8);
  point_vec.emplace_back(7.2, 7.6, -13);
  point_vec.emplace_back(5.6, 9.4, 0.1);

  for (size_t i = 0; i < se3_vec.size(); ++i) {
    const size_t other_index = (i + 3) % se3_vec.size();
    bool const passed = test(se3_vec[i], se3_vec[other_index],
                             point_vec[i], point_vec[other_index]);
    if (!passed) {
      std::cerr << "failed!" << std::endl << std::endl;
      exit(-1);
    }
  }

  Eigen::Matrix<ceres::Jet<double, 28>, 4, 4> mat;
  mat.setIdentity();
  std::cout << CreateSE3FromMatrix(mat) << std::endl;
  return 0;
}

