/*----------------------------------------------------------------------------------------------------------------------
|	Initializes taxonBlockID to "TAXA" and totalTaxa to 0.
*/
NxsTaxaBlock::NxsTaxaBlock()
  : NxsBlock()
	{
	totalTaxa	= 0;
	taxonBlockID	= "TAXA";
	}
/*----------------------------------------------------------------------------------------------------------------------
|	Erases taxonNames vector.
*/
NxsTaxaBlock::~NxsTaxaBlock()
	{
	taxonNames.erase(taxonNames.begin(), taxonNames.end());
	}
/*----------------------------------------------------------------------------------------------------------------------
|	This function provides the ability to read everything following the block name (which is read by the NxsReader 
|	object) to the end or endblock statement. Characters are read from the input stream in. Overrides the abstract 
|	virtual function in the base class. 
*/
void NxsTaxaBlock::Read(
  NxsToken &token)	/* the token used to read from in */
	{
	totalTaxa			= 0;
	int expected_ntax	= 0;
	isEmpty				= false;
	isUserSupplied		= true;
	// This should be the semicolon after the block name
	//
	token.GetNextToken();
	if (!token.Equals(";")) 
		{
		errormsg = "Expecting ';' after TAXA block name, but found ";
		errormsg += token.GetToken();
		errormsg += " instead";
		throw NxsException(errormsg, token.GetFilePosition(), token.GetFileLine(), token.GetFileColumn());
		}
	for (;;)
		{
		token.GetNextToken();
		if (token.Equals("DIMENSIONS"))
			{
			// This should be the NTAX keyword
			//
			token.GetNextToken(); 
			if (!token.Equals("NTAX"))
				{
				errormsg = "Expecting NTAX keyword, but found ";
				errormsg += token.GetToken();
				errormsg += " instead";
				throw NxsException(errormsg, token.GetFilePosition(), token.GetFileLine(), token.GetFileColumn());
				}
			// This should be the equals sign
			//
			token.GetNextToken(); 
			if (!token.Equals("=")) 
				{
				errormsg = "Expecting '=', but found ";
				errormsg += token.GetToken();
				errormsg += " instead";
				throw NxsException(errormsg, token.GetFilePosition(), token.GetFileLine(), token.GetFileColumn());
				}
			// This should be the number of taxa
			//
			token.GetNextToken();
			expected_ntax = atoi(token.GetToken().c_str());
			if (expected_ntax <= 0)
				{
				errormsg = "NTAX should be greater than zero (";
				errormsg += token.GetToken();
				errormsg += " was specified)";
				throw NxsException(errormsg, token.GetFilePosition(), token.GetFileLine(), token.GetFileColumn());
				}
			// This should be the terminating semicolon
			//
			token.GetNextToken(); 
			if (!token.Equals(";"))
				{
				errormsg = "Expecting ';' to terminate DIMENSIONS command, but found ";
				errormsg += token.GetToken();
				errormsg += " instead";
				throw NxsException(errormsg, token.GetFilePosition(), token.GetFileLine(), token.GetFileColumn());
				}
			}	// if (token.Equals("DIMENSIONS"))
		else if (token.Equals("TAXLABELS")) 
			{
			if (expected_ntax <= 0) 
				{
				errormsg = "NTAX must be specified before TAXLABELS command";
				throw NxsException(errormsg, token.GetFilePosition(), token.GetFileLine(), token.GetFileColumn());
				}
			for (unsigned j = 0; (int)j < expected_ntax; j++)
				{
                token.SetLabileFlagBit(NxsToken::hyphenNotPunctuation + NxsToken::preserveUnderscores);
				token.GetNextToken();
				//@pol should check to make sure this is not punctuation
				AddTaxonName(token.GetToken());
				}
			// This should be terminating semicolon
			//
			token.GetNextToken(); 
			if (!token.Equals(";"))
				{
				errormsg = "Expecting ';' to terminate TAXLABELS command, but found ";
				errormsg += token.GetToken();
				errormsg += " instead";
				throw NxsException(errormsg, token.GetFilePosition(), token.GetFileLine(), token.GetFileColumn());
				}
			}	// if (token.Equals("TAXLABELS")) 
		else if (token.Equals("END") || token.Equals("ENDBLOCK"))
			{
			// Get the semicolon following END
			//
			token.GetNextToken();
			if (!token.Equals(";"))
				{
				errormsg = "Expecting ';' to terminate the ENDBLOCK command, but found ";
				errormsg += token.GetToken();
				errormsg += " instead";
				throw NxsException(errormsg, token.GetFilePosition(), token.GetFileLine(), token.GetFileColumn());
				}
			break;
			}	// if (token.Equals("END") || token.Equals("ENDBLOCK"))
		else
			{
			SkippingCommand(token.GetToken());
			do
				{
				token.GetNextToken();
				}
			while (!token.AtEOF() && !token.Equals(";"));
			if (token.AtEOF())
				{
				errormsg = "Unexpected end of file encountered";
				throw NxsException(errormsg, token.GetFilePosition(), token.GetFileLine(), token.GetFileColumn());
				}
			}	// token not END, ENDBLOCK, TAXLABELS, or DIMENSIONS
		}	// GetNextToken loop
	}
/*----------------------------------------------------------------------------------------------------------------------
|	This function outputs a brief report of the contents of this taxa block. Overrides the abstract virtual function in
|	the base class.
*/
void NxsTaxaBlock::Report(
  ostream &out)	/* the output stream to which to write the report */
	{
	out << endl;
	out << taxonBlockID << " block contains ";
	if (totalTaxa == 0)
		{
		out << "no taxa" << endl;
		}
	else if (totalTaxa == 1)
		out << "one taxon" << endl;
	else
		out << totalTaxa << " taxa" << endl;
	if (totalTaxa == 0)
		return;
	for (unsigned m = 0; m < totalTaxa; m++)
		{
		out << '\t' << (m+1) << '\t' << taxonNames[m] << endl;
		}
	}
/*----------------------------------------------------------------------------------------------------------------------
|	Flushes taxonNames and sets totalTaxa to 0 in preparation for reading a new TAXA block.
*/
void NxsTaxaBlock::Reset()
	{
	errormsg.clear();
	isEmpty			= true;
	isEnabled		= true;
	isUserSupplied	= false;
	totalTaxa		= 0;
	taxonNames.clear();
	needsQuotes.clear();
	}
/*----------------------------------------------------------------------------------------------------------------------
|	Adds taxon label 's' to end of list of taxon names and increments totalTaxa by 1. Returns index of taxon label just 
|	added.
*/
unsigned NxsTaxaBlock::AddTaxonName(
  NxsString s)	/* the taxon label to add */
	{
	isEmpty = false;
	if (s.QuotesNeeded())
		needsQuotes.push_back(true);
	else
		needsQuotes.push_back(false);

	taxonNames.push_back(s);
	totalTaxa++;
	return (totalTaxa-1);
	}
/*----------------------------------------------------------------------------------------------------------------------
|	Changes the label for taxon 'i' to 's'.
*/
void NxsTaxaBlock::ChangeTaxonLabel(
  unsigned i,	/* the taxon label number to change */
  NxsString s)	/* the string used to replace label i */
	{
	assert(i < (unsigned)taxonNames.size());
	if (s.QuotesNeeded())
		needsQuotes[i] = true;
	else
		needsQuotes[i] = false;
	taxonNames[i] = s;
	}
/*----------------------------------------------------------------------------------------------------------------------
|	Returns the length of the longest taxon label stored. Useful for formatting purposes in outputting the data matrix 
|	(i.e., you want the left edge of the matrix to line up).
*/
unsigned NxsTaxaBlock::GetMaxTaxonLabelLength()
	{
	assert(totalTaxa == (unsigned)taxonNames.size());
	unsigned maxlength = 0;
	for (unsigned j = 0; j < totalTaxa; j++)
		{
		unsigned thislen = taxonNames[j].size();
		if (thislen > maxlength)
			maxlength = thislen;
		}
	return maxlength;
	}
/*----------------------------------------------------------------------------------------------------------------------
|	Returns the label for taxon 'i'.
*/
NxsString NxsTaxaBlock::GetTaxonLabel(
  unsigned i)	/* the taxon label number to return */
	{
	assert(i >= 0);
	assert(i < (unsigned)taxonNames.size());
	return taxonNames[i];
	}
/*----------------------------------------------------------------------------------------------------------------------
|	Returns true if taxonNames[i] contains embedded spaces and thus should be surrounded by single quotes if output is
|	NEXUS format.
*/
bool NxsTaxaBlock::NeedsQuotes(
  unsigned i)	/* the taxon label number in question */
	{
	assert(i >= 0);
	assert(i < (unsigned)taxonNames.size());
	return needsQuotes[i];
	}
/*----------------------------------------------------------------------------------------------------------------------
|	Returns true if taxonNames contains an entry equal to 's', and returns false otherwise.
*/
bool NxsTaxaBlock::IsAlreadyDefined(
  NxsString s)	/* the s to attempt to find in the taxonNames list */
	{
	NxsStringVector::const_iterator iter = find(taxonNames.begin(), taxonNames.end(), s);
	bool taxonFound = (iter != taxonNames.end());
	return taxonFound;
	}
/*----------------------------------------------------------------------------------------------------------------------
|	Returns index of taxon named 's' in taxonNames list. If taxon named 's' cannot be found, or if there are no 
|	labels currently stored in the taxonNames list, throws NxsX_NoSuchTaxon exception.
*/
unsigned NxsTaxaBlock::FindTaxon(
  NxsString s)	/* the string to attempt to find in the taxonNames list */
	{
	unsigned pos = 0;
	NxsStringVector::const_iterator j;
	for (j = taxonNames.begin(); j != taxonNames.end(); ++j)
		{
		if (*j == s)
			break;
		pos++;
		}
	if (j == taxonNames.end())
		throw NxsTaxaBlock::NxsX_NoSuchTaxon();
	return pos;
	}
/*----------------------------------------------------------------------------------------------------------------------
|	Returns number of taxon labels currently stored.
*/
unsigned NxsTaxaBlock::GetNumTaxonLabels()
	{
	return (unsigned)taxonNames.size();
	}
/*----------------------------------------------------------------------------------------------------------------------
|	Sets totalTaxa to n.
*/
void NxsTaxaBlock::SetNtax(
  unsigned n)	/* the number of taxa */
	{
	totalTaxa = n;
	}

