/**Function********************************************************************

  Synopsis    [Displays statistics on symmetric variables.]

  Description []

  SideEffects [None]

******************************************************************************/
void
Cudd_VariableSymmetry(
  DdManager * manager,
  int  first,
  int  last)
{
    int j,pos,bottom;
    int TotalSymm = 0;
    int TotalGroups = 0;

    for (j = first; j <= last; j++) {
	if (manager->subtables[j].next != (unsigned) j) {
	    pos = j;
	    (void) fprintf(manager->out,"Cluster:");
	    do {
		(void) fprintf(manager->out,"  %d",manager->invperm[pos]);
		TotalSymm++;
		bottom = pos;
		pos = manager->subtables[pos].next;
	    } while (pos != j);
	    TotalGroups++;
#ifdef DD_DEBUG
	    assert(manager->subtables[bottom].next == (unsigned) j);
#endif
	    j = bottom;
	    (void) fprintf(manager->out,"\n");
	}
    }
    (void) fprintf(manager->out,"Total Symmetric = %d\n",TotalSymm);
    (void) fprintf(manager->out,"Total Groups = %d\n",TotalGroups);

} /* end of Cudd_VariableSymmetry */


