int
cuddVerifySymmetry(
  DdManager * manager,
  int  posX,
  int  posY)
{
    DdNode *f,*f0,*f1,*f01,*f00,*f11,*f10;
    int negated;		/* f0 is complemented */
    int positiveSym;	/* posX and posY may be positively symmetric */
    int negativeSym;	/* posX and posY may be negatively symmetric */
    int arcCount;	/* number of arcs from layer posX to layer posY */
    int TotalRef;	/* total reference count of layer posY minus 1 */
    int yindex;
    int k;
    DdNodePtr *bucket;
    int slots;
    DdNode *dummy = &(manager->sentinel);
#ifdef DD_DEBUG
    int xindex;
#endif

    /* Checks that posX and posY are not the projection functions.
    ** For posX it is sufficient to check whether there is only one
    ** node; indeed, if there is one node, it is the projection function
    ** and it cannot point to posY. Hence, if posY isn't just the projection
    ** function, it has one arc coming from a layer different from posX.
    */
    if (manager->subtables[posX].keys == 1) {
	return(0);
    }
    yindex = manager->invperm[posY];
    if (manager->subtables[posY].keys == 1) {
	if (manager->vars[yindex]->ref == 1)
	    return(0);
    }

    positiveSym = negativeSym = 1;
    arcCount = 0;
    slots = manager->subtables[posX].slots;
    bucket = manager->subtables[posX].nodelist;
    for (k = 0; k < slots; k++) {
	f = bucket[k];
	while (f != dummy) {
	    /* Find f1, f0, f11, f10, f01, f00. */
	    f1 = cuddT(f);
	    f0 = Cudd_Regular(cuddE(f));
	    negated = Cudd_IsComplement(cuddE(f));
	    if ((int) f1->index == yindex) {
		arcCount++;
		f11 = cuddT(f1); f10 = cuddE(f1);
	    } else {
		if ((int) f0->index != yindex) {
		    /* If f is an isolated projection function it is
		    ** allowed to bypass layer posY.
		    */
		    if (f1 != DD_ONE(manager) || f0 != DD_ONE(manager) || f->ref != 1)
			return(0); /* f bypasses layer posY */
		}
		f11 = f10 = f1;
	    }
	    if ((int) f0->index == yindex) {
		arcCount++;
		f01 = cuddT(f0); f00 = cuddE(f0);
	    } else {
		f01 = f00 = f0;
	    }
	    if (negated) {
		f01 = Cudd_Not(f01);
		f00 = Cudd_Not(f00);
	    }

	    if (f1 != DD_ONE(manager) || f0 != DD_ONE(manager) || f->ref != 1) {
		positiveSym &= f01 == f10;
		negativeSym &= f11 == f00;
		if ((positiveSym == 0) && (negativeSym == 0))
		    return(0);
	    }

	    f = f->next;
	} /* while */
    } /* for */

    /* Calculate the total reference counts of posY */
    TotalRef = -1; /* -1 for projection function */
    slots = manager->subtables[posY].slots;
    bucket = manager->subtables[posY].nodelist;
    for (k = 0; k < slots; k++) {
	f = bucket[k];
	while (f != dummy) {
	    TotalRef += f->ref;
	    f = f->next;
	}
    }

#if defined(DD_DEBUG) && defined(DD_VERBOSE)
    if (arcCount == TotalRef) {
	xindex = manager->invperm[posX];
	(void) fprintf(manager->out,
		       "Found symmetry! x =%d\ty = %d\tPos(%d,%d)\n",
		       xindex,yindex,posX,posY);
    }
#endif

    return(arcCount == TotalRef);

} /* end of cuddVerifySymmetry */



/**Function********************************************************************

  Synopsis    [Symmetric sifting procedure.]

  Description [Symmetric sifting procedure.
  Assumes that no dead nodes are present.
    <ol>
    <li> Order all the variables according to the number of entries in
    each unique subtable.
    <li> Sift the variable up and down, remembering each time the total
    size of the DD heap and grouping variables that are symmetric.
    <li> Select the best permutation.
    <li> Repeat 3 and 4 for all variables.
    </ol>
  Returns 1 plus the number of symmetric variables if successful; 0
  otherwise.]

  SideEffects [None]

  SeeAlso     [cuddSymmSiftingConvergence]

******************************************************************************/
int
cuddSymmetricSifting(
  DdManager * manager,
  int  lower,
  int  upper)
{
    int		i;
    int		*order;
    int		currentSize;
    int		pos;
    int		status;
    int		symCount;
    int		groupCount;
#ifdef DD_STATS
    int		previousSize;
#endif

    currentSize = manager->size;

    /* Find order in which to sift variables. */
    order = NULL;
    nodeCount = ALLOC(int,currentSize);
    if (nodeCount == NULL) {
	manager->errorCode = CUDD_MEMORY_OUT;
	goto cuddSymmetricSiftingMemoryError;
    }
    order = ALLOC(int,currentSize);
    if (order == NULL) {
	manager->errorCode = CUDD_MEMORY_OUT;
	goto cuddSymmetricSiftingMemoryError;
    }

    for (i = 0; i < currentSize; i++) {
	pos = manager->perm[i];
	nodeCount[i] = manager->subtables[pos].keys;
	order[i] = i;
    }

    qsort((void *)order,currentSize,sizeof(int),(DD_QSFP)ddUniqueCompare);

    /* Initialize the symmetry of each subtable to itself. */
    for (i = lower; i <= upper; i++) {
	manager->subtables[i].next = i;
    }

    for (i = 0; i < ddMin(manager->siftMaxVar,currentSize); i++) {
	if (ddTotalNumberSwapping >= manager->siftMaxSwap)
	    break;
        if (util_cpu_time() - manager->startTime > manager->timeLimit) {
            manager->autoDyn = 0; /* prevent further reordering */
            break;
        }
	pos = manager->perm[order[i]];
#ifdef DD_STATS
	previousSize = manager->keys - manager->isolated;
#endif
	if (pos < lower || pos > upper) continue;
	if (manager->subtables[pos].next == (unsigned) pos) {
	    status = ddSiftingAux(manager,pos,lower,upper);
	    if (!status) goto cuddSymmetricSiftingMemoryError;
#ifdef DD_STATS
	    if (manager->keys < (unsigned) previousSize + manager->isolated) {
		(void) fprintf(manager->out,"-");
	    } else if (manager->keys > (unsigned) previousSize +
		       manager->isolated) {
		(void) fprintf(manager->out,"+"); /* should never happen */
	    } else {
		(void) fprintf(manager->out,"=");
	    }
	    fflush(manager->out);
#endif
	}
    }

    FREE(order);
    FREE(nodeCount);

    ddGroupStats(manager, lower, upper, &symCount, &groupCount);

#ifdef DD_STATS
    (void) fprintf(manager->out, "\n#:S_SIFTING %8d: symmetric variables\n",
		   symCount);
    (void) fprintf(manager->out, "#:G_SIFTING %8d: symmetric groups",
		   groupCount);
#endif

    return(1+symCount);

cuddSymmetricSiftingMemoryError:

    if (nodeCount != NULL) FREE(nodeCount);
    if (order != NULL) FREE(order);

    return(0);

} /* end of cuddSymmetricSifting */



/**Function********************************************************************

  Synopsis    [Symmetric sifting to convergence algorithm.]

  Description [Symmetric sifting to convergence algorithm.
  Assumes that no dead nodes are present.
    <ol>
    <li> Order all the variables according to the number of entries in
    each unique subtable.
    <li> Sift the variable up and down, remembering each time the total
    size of the DD heap and grouping variables that are symmetric.
    <li> Select the best permutation.
    <li> Repeat 3 and 4 for all variables.
    <li> Repeat 1-4 until no further improvement.
    </ol>
  Returns 1 plus the number of symmetric variables if successful; 0
  otherwise.]

  SideEffects [None]

  SeeAlso     [cuddSymmetricSifting]

******************************************************************************/
int
cuddSymmSiftingConvergence(
  DdManager * manager,
  int  lower,
  int  upper)
{
    int		i;
    int		*order;
    int		currentSize;
    int		pos;
    int		status;
    int		symCount;
    int		groupCount;
    int		classes;
    int		initialSize;
#ifdef DD_STATS
    int		previousSize;
#endif

    initialSize = manager->keys - manager->isolated;

    currentSize = manager->size;

    /* Find order in which to sift variables. */
    order = NULL;
    nodeCount = ALLOC(int,currentSize);
    if (nodeCount == NULL) {
	manager->errorCode = CUDD_MEMORY_OUT;
	goto cuddSymmSiftingConvergenceMemoryError;
    }
    order = ALLOC(int,currentSize);
    if (order == NULL) {
	manager->errorCode = CUDD_MEMORY_OUT;
	goto cuddSymmSiftingConvergenceMemoryError;
    }

    for (i = 0; i < currentSize; i++) {
	pos = manager->perm[i];
	nodeCount[i] = manager->subtables[pos].keys;
	order[i] = i;
    }

    qsort((void *)order,currentSize,sizeof(int),(DD_QSFP)ddUniqueCompare);

    /* Initialize the symmetry of each subtable to itself
    ** for first pass of converging symmetric sifting.
    */
    for (i = lower; i <= upper; i++) {
	manager->subtables[i].next = i;
    }

    for (i = 0; i < ddMin(manager->siftMaxVar, manager->size); i++) {
	if (ddTotalNumberSwapping >= manager->siftMaxSwap)
	    break;
        if (util_cpu_time() - manager->startTime > manager->timeLimit) {
            manager->autoDyn = 0; /* prevent further reordering */
            break;
        }
	pos = manager->perm[order[i]];
	if (pos < lower || pos > upper) continue;
	/* Only sift if not in symmetry group already. */
	if (manager->subtables[pos].next == (unsigned) pos) {
#ifdef DD_STATS
	    previousSize = manager->keys - manager->isolated;
#endif
	    status = ddSiftingAux(manager,pos,lower,upper);
	    if (!status) goto cuddSymmSiftingConvergenceMemoryError;
#ifdef DD_STATS
	    if (manager->keys < (unsigned) previousSize + manager->isolated) {
		(void) fprintf(manager->out,"-");
	    } else if (manager->keys > (unsigned) previousSize +
		       manager->isolated) {
		(void) fprintf(manager->out,"+");
	    } else {
		(void) fprintf(manager->out,"=");
	    }
	    fflush(manager->out);
#endif
	}
    }

    /* Sifting now until convergence. */
    while ((unsigned) initialSize > manager->keys - manager->isolated) {
	initialSize = manager->keys - manager->isolated;
#ifdef DD_STATS
	(void) fprintf(manager->out,"\n");
#endif
	/* Here we consider only one representative for each symmetry class. */
	for (pos = lower, classes = 0; pos <= upper; pos++, classes++) {
	    while ((unsigned) pos < manager->subtables[pos].next) {
		pos = manager->subtables[pos].next;
	    }
	    /* Here pos is the largest index in a group.
	    ** Groups consist of adjacent variables.
	    ** Hence, the next increment of pos will move it to a new group.
	    */
	    i = manager->invperm[pos];
	    nodeCount[i] = manager->subtables[pos].keys;
	    order[classes] = i;
	}

	qsort((void *)order,classes,sizeof(int),(DD_QSFP)ddUniqueCompare);

	/* Now sift. */
	for (i = 0; i < ddMin(manager->siftMaxVar,classes); i++) {
	    if (ddTotalNumberSwapping >= manager->siftMaxSwap)
		break;
            if (util_cpu_time() - manager->startTime > manager->timeLimit) {
              manager->autoDyn = 0; /* prevent further reordering */
              break;
            }
	    pos = manager->perm[order[i]];
	    if ((unsigned) pos >= manager->subtables[pos].next) {
#ifdef DD_STATS
		previousSize = manager->keys - manager->isolated;
#endif
		status = ddConvergeSiftingAux(manager,pos,lower,upper);
		if (!status ) goto cuddSymmSiftingConvergenceMemoryError;
#ifdef DD_STATS
		if (manager->keys < (unsigned) previousSize + manager->isolated) {
		    (void) fprintf(manager->out,"-");
		} else if (manager->keys > (unsigned) previousSize +
			   manager->isolated) {
		    (void) fprintf(manager->out,"+");
		} else {
		    (void) fprintf(manager->out,"=");
		}
		fflush(manager->out);
#endif
	    }
	} /* for */
    }

    ddGroupStats(manager, lower, upper, &symCount, &groupCount);

#ifdef DD_STATS
    (void) fprintf(manager->out, "\n#:S_SIFTING %8d: symmetric variables\n",
		   symCount);
    (void) fprintf(manager->out, "#:G_SIFTING %8d: symmetric groups",
		   groupCount);
#endif

    FREE(order);
    FREE(nodeCount);

    return(1+symCount);

cuddSymmSiftingConvergenceMemoryError:

    if (nodeCount != NULL) FREE(nodeCount);
    if (order != NULL) FREE(order);

    return(0);

} /* end of cuddSymmSiftingConvergence */



/*---------------------------------------------------------------------------*/
/* Definition of static functions                                            */
/*---------------------------------------------------------------------------*/



/**Function********************************************************************

  Synopsis    [Comparison function used by qsort.]

  Description [Comparison function used by qsort to order the variables
  according to the number of keys in the subtables.
  Returns the difference in number of keys between the two
  variables being compared.]

  SideEffects [None]

******************************************************************************/
static int
ddUniqueCompare(
  int * ptrA,
  int * ptrB)
{
#if 0
    if (nodeCount[*ptrB] == nodeCount[*ptrA]) {
	return((*ptrA) - (*ptrB));
    }
#endif
    return(nodeCount[*ptrB] - nodeCount[*ptrA]);

} /* end of ddUniqueCompare */



/**Function********************************************************************

  Synopsis    [Moves a variable between boundaries while checking symmetries.]

  Description [Moves a variable between boundaries while checking symmetries.
  Finds the best position and does the required changes.
  Assumes that the variable is not part of a symmetry group. Returns 1 if
  successful; 0 otherwise.]

  SideEffects [None]

******************************************************************************/
static int
ddSiftingAux(
  DdManager * manager,
  int  pos,
  int  min,
  int  max)
{
    Move *step;
    Move *stepsUp;	/* list of upward moves */
    Move *stepsDown;	/* list of downward moves */
    int	 initialSize;
    int	 result;
    int  k;
    int  topbot;	/* index to either top or bottom of symmetry group */
    int  initGroupSize, finalGroupSize;


#ifdef DD_DEBUG
    /* check for previously detected symmetry */
    assert(manager->subtables[pos].next == (unsigned) pos);
#endif

    initialSize = manager->keys - manager->isolated;

    stepsDown = NULL;
    stepsUp = NULL;

    if ((pos - min) > (max - pos)) {
	/* Will go down first, unless pos == max:
	** Look for consecutive symmetries above pos.
	*/
	for (k = pos; k > min; k--) {
	    if (!cuddVerifySymmetry(manager,k-1,k))
		break;
	    topbot = manager->subtables[k-1].next; /* find top of k-1's group */
	    manager->subtables[k-1].next = k;
	    manager->subtables[pos].next = topbot; /* pos is bottom of group so its */
					       /* next is top of k-1's group */
	    k = topbot + 1; /* add 1 for k--; new k is top of symm group */
	}
    } else {
	/* Will go up first unless pos == min:
	** Look for consecutive symmetries below pos.
	*/
	for (k = pos; k < max; k++) {
	    if (!cuddVerifySymmetry(manager,k,k+1))
		break;
	    /* find bottom of k+1's symm group */
	    topbot = k + 1;
	    while ((unsigned) topbot < manager->subtables[topbot].next) {
		topbot = manager->subtables[topbot].next;
	    }
	    manager->subtables[topbot].next = manager->subtables[k].next;
	    manager->subtables[k].next = k + 1;
	    k = topbot - 1; /* subtract 1 for k++; new k is bottom of group */
	}
    }

    /* Now pos may be in the middle of a symmetry group.
    ** Find bottom of pos's symm group.
    */
    while ((unsigned) pos < manager->subtables[pos].next)
	pos = manager->subtables[pos].next;

    if (pos == min) { /* Sift down */

#ifdef DD_DEBUG
	/* pos must be a singleton */
	assert((unsigned) pos == manager->subtables[pos].next);
#endif
	if (pos == max) return(1);	/* just one variable */

	initGroupSize = 1;

	stepsDown = ddMoveDown(manager,pos,max);
	    /* after this point pos --> max, unless early term */
	if (stepsDown == MV_ERROR) goto ddSiftingAuxMemoryError;
	if (stepsDown == NULL) return(1);

	pos = stepsDown->y;
	/* Find bottom of pos's group */
	k = pos;
	while ((unsigned) k < manager->subtables[k].next) {
	    k = manager->subtables[k].next;
	}
#ifdef DD_DEBUG
	/* pos should be the top of the symmetry group and k the bottom */
	assert((unsigned) k >= manager->subtables[k].next);
	assert((unsigned) pos == manager->subtables[k].next);
#endif
	finalGroupSize = k - pos + 1;

	if (initGroupSize == finalGroupSize) {
	    /* No new symmetry groups detected, return to best position */
	    result = ddBackwardSteps(manager,stepsDown,initialSize);
	} else {
	    initialSize = manager->keys - manager->isolated;
	    stepsUp = ddMoveUp(manager,pos,min);
	    result = ddBackwardSteps(manager,stepsUp,initialSize);
	}
	if (!result) goto ddSiftingAuxMemoryError;

    } else if (cuddNextHigh(manager,pos) > max) { /* Sift up */
	/* Find top of pos's symm group */
	k = pos;				/* bottom */
	pos = manager->subtables[pos].next;	/* top */

	if (pos == min) return(1); /* just one big group */

	initGroupSize = k - pos + 1;

	stepsUp = ddMoveUp(manager,pos,min);
	    /* after this point pos --> min, unless early term */
	if (stepsUp == MV_ERROR) goto ddSiftingAuxMemoryError;
	if (stepsUp == NULL) return(1);

	pos = stepsUp->x;
	/* Find top of pos's group */
	k = manager->subtables[pos].next;
#ifdef DD_DEBUG
	/* pos should be the bottom of the symmetry group and k the top */
	assert((unsigned) pos >= manager->subtables[pos].next);
	assert((unsigned) k == manager->subtables[pos].next);
#endif
	finalGroupSize = pos - k + 1;

	if (initGroupSize == finalGroupSize) {
	    /* No new symmetry groups detected, return to best position */
	    result = ddBackwardSteps(manager,stepsUp,initialSize);
	} else {
	    initialSize = manager->keys - manager->isolated;
	    stepsDown = ddMoveDown(manager,pos,max);
	    result = ddBackwardSteps(manager,stepsDown,initialSize);
	}
	if (!result) goto ddSiftingAuxMemoryError;

    } else if ((pos - min) > (max - pos)) { /* must go down first: shorter */

	stepsDown = ddMoveDown(manager,pos,max);
	/* at this point pos == max, unless early term */
	if (stepsDown == MV_ERROR) goto ddSiftingAuxMemoryError;

	if (stepsDown != NULL) {
	    pos = stepsDown->y;	/* pos is top here */
	    k = pos;
	    while ((unsigned) k < manager->subtables[k].next) {
		k = manager->subtables[k].next;
	    }
	} else {
	    k = pos;
	    while ((unsigned) k < manager->subtables[k].next) {
		k = manager->subtables[k].next;
	    }
	    pos = manager->subtables[k].next;
	}
#ifdef DD_DEBUG
	/* pos should be the top of the symmetry group and k the bottom */
	assert((unsigned) k >= manager->subtables[k].next);
	assert((unsigned) pos == manager->subtables[k].next);
#endif
	initGroupSize = k - pos + 1;

	stepsUp = ddMoveUp(manager,pos,min);
	if (stepsUp == MV_ERROR) goto ddSiftingAuxMemoryError;

	if (stepsUp != NULL) {
	    pos = stepsUp->x;
	    k = manager->subtables[pos].next;
	} else {
	    k = pos;
	    while ((unsigned) pos < manager->subtables[pos].next)
		pos = manager->subtables[pos].next;
	}
#ifdef DD_DEBUG
	/* pos should be the bottom of the symmetry group and k the top */
	assert((unsigned) pos >= manager->subtables[pos].next);
	assert((unsigned) k == manager->subtables[pos].next);
#endif
	finalGroupSize = pos - k + 1;

	if (initGroupSize == finalGroupSize) {
	    /* No new symmetry groups detected, return to best position */
	    result = ddBackwardSteps(manager,stepsUp,initialSize);
	} else {
	    while (stepsDown != NULL) {
		step = stepsDown->next;
		cuddDeallocMove(manager, stepsDown);
		stepsDown = step;
	    }
	    initialSize = manager->keys - manager->isolated;
	    stepsDown = ddMoveDown(manager,pos,max);
	    result = ddBackwardSteps(manager,stepsDown,initialSize);
	}
	if (!result) goto ddSiftingAuxMemoryError;

    } else { /* moving up first: shorter */
	/* Find top of pos's symmetry group */
	pos = manager->subtables[pos].next;

	stepsUp = ddMoveUp(manager,pos,min);
	/* at this point pos == max, unless early term */
	if (stepsUp == MV_ERROR) goto ddSiftingAuxMemoryError;

	if (stepsUp != NULL) {
	    pos = stepsUp->x;
	    k = manager->subtables[pos].next;
	} else {
	    while ((unsigned) pos < manager->subtables[pos].next)
		pos = manager->subtables[pos].next;
	    k = manager->subtables[pos].next;
	}
#ifdef DD_DEBUG
	/* pos is bottom of the symmetry group and k is top */
	assert((unsigned) pos >= manager->subtables[pos].next);
	assert((unsigned) k == manager->subtables[pos].next);
#endif
	initGroupSize = pos - k + 1;

	stepsDown = ddMoveDown(manager,pos,max);
	if (stepsDown == MV_ERROR) goto ddSiftingAuxMemoryError;

	if (stepsDown != NULL) {
	    pos = stepsDown->y;
	    k = pos;
	    while ((unsigned) k < manager->subtables[k].next) {
		k = manager->subtables[k].next;
	    }
	} else {
	    k = pos;
	    pos = manager->subtables[pos].next;
	}
#ifdef DD_DEBUG
	/* pos should be the top of the symmetry group and k the bottom */
	assert((unsigned) k >= manager->subtables[k].next);
	assert((unsigned) pos == manager->subtables[k].next);
#endif
	finalGroupSize = k - pos + 1;

	if (initGroupSize == finalGroupSize) {
	    /* No new symmetries detected, go back to best position */
	    result = ddBackwardSteps(manager,stepsDown,initialSize);
	} else {
	    while (stepsUp != NULL) {
		step = stepsUp->next;
		cuddDeallocMove(manager, stepsUp);
		stepsUp = step;
	    }
	    initialSize = manager->keys - manager->isolated;
	    stepsUp = ddMoveUp(manager,pos,min);
	    result = ddBackwardSteps(manager,stepsUp,initialSize);
	}
	if (!result) goto ddSiftingAuxMemoryError;
    }

    while (stepsDown != NULL) {
	step = stepsDown->next;
	cuddDeallocMove(manager, stepsDown);
	stepsDown = step;
    }
    while (stepsUp != NULL) {
	step = stepsUp->next;
	cuddDeallocMove(manager, stepsUp);
	stepsUp = step;
    }

    return(1);

ddSiftingAuxMemoryError:
    if (stepsDown != MV_ERROR) {
	while (stepsDown != NULL) {
	    step = stepsDown->next;
	    cuddDeallocMove(manager, stepsDown);
	    stepsDown = step;
	}
    }
    if (stepsUp != MV_ERROR) {
	while (stepsUp != NULL) {
	    step = stepsUp->next;
	    cuddDeallocMove(manager, stepsUp);
	    stepsUp = step;
	}
    }

    return(0);

} /* end of ddSiftingAux */



/**Function********************************************************************

  Synopsis    [Moves a variable between boundaries while checking symmetries.]

  Description [Moves a variable between boundaries while checking symmetries.
  Finds the best position and does the required changes.
  Assumes that the variable is either an isolated variable, or it is the bottom of
  a symmetry group. All symmetries may not have been found, because of
  exceeded growth limit. Returns 1 if successful; 0 otherwise.]

  SideEffects [None]

******************************************************************************/
static int
ddConvergeSiftingAux(
  DdManager * manager,
  int  pos,
  int  min,
  int  max)
{
    Move *step;
    Move *stepsUp;	/* list of up moves */
    Move *stepsDown;	/* list of down moves */
    int	 initialSize;
    int	 result;
    int  k;
    int  initGroupSize, finalGroupSize;


    initialSize = manager->keys - manager->isolated;

    stepsDown = NULL;
    stepsUp = NULL;

    if (pos == min) { /* Sift down */
#ifdef DD_DEBUG
	/* pos is bottom of symmetry group */
	assert((unsigned) pos >= manager->subtables[pos].next);
#endif
	k = manager->subtables[pos].next;
	initGroupSize = pos - k + 1;

	stepsDown = ddMoveDown(manager,pos,max);
	/* at this point pos == max, unless early term */
	if (stepsDown == MV_ERROR) goto ddConvergeSiftingAuxMemoryError;
	if (stepsDown == NULL) return(1);

	pos = stepsDown->y;
	k = pos;
	while ((unsigned) k < manager->subtables[k].next) {
	    k = manager->subtables[k].next;
	}
#ifdef DD_DEBUG
	/* pos should be the top of the symmetric group and k the bottom */
	assert((unsigned) k >= manager->subtables[k].next);
	assert((unsigned) pos == manager->subtables[k].next);
#endif
	finalGroupSize = k - pos + 1;

	if (initGroupSize == finalGroupSize) {
	    /* No new symmetries detected, go back to best position */
	    result = ddBackwardSteps(manager,stepsDown,initialSize);
	} else {
	    initialSize = manager->keys - manager->isolated;
	    stepsUp = ddMoveUp(manager,pos,min);
	    result = ddBackwardSteps(manager,stepsUp,initialSize);
	}
	if (!result) goto ddConvergeSiftingAuxMemoryError;

    } else if (cuddNextHigh(manager,pos) > max) { /* Sift up */
	/* Find top of pos's symm group */
	while ((unsigned) pos < manager->subtables[pos].next)
	    pos = manager->subtables[pos].next;
	k = pos;				/* bottom */
	pos = manager->subtables[pos].next;	/* top */

	if (pos == min) return(1);

	initGroupSize = k - pos + 1;

	stepsUp = ddMoveUp(manager,pos,min);
	    /* at this point pos == min, unless early term */
	if (stepsUp == MV_ERROR) goto ddConvergeSiftingAuxMemoryError;
	if (stepsUp == NULL) return(1);

	pos = stepsUp->x;
	k = manager->subtables[pos].next;
#ifdef DD_DEBUG
	/* pos should be the bottom of the symmetry group and k the top */
	assert((unsigned) pos >= manager->subtables[pos].next);
	assert((unsigned) k == manager->subtables[pos].next);
#endif
	finalGroupSize = pos - k + 1;

	if (initGroupSize == finalGroupSize) {
	    /* No new symmetry groups detected, return to best position */
	    result = ddBackwardSteps(manager,stepsUp,initialSize);
	} else {
	    initialSize = manager->keys - manager->isolated;
	    stepsDown = ddMoveDown(manager,pos,max);
	    result = ddBackwardSteps(manager,stepsDown,initialSize);
	}
	if (!result)
	    goto ddConvergeSiftingAuxMemoryError;

    } else if ((pos - min) > (max - pos)) { /* must go down first: shorter */
	stepsDown = ddMoveDown(manager,pos,max);
	    /* at this point pos == max, unless early term */
	if (stepsDown == MV_ERROR) goto ddConvergeSiftingAuxMemoryError;

	if (stepsDown != NULL) {
	    pos = stepsDown->y;
	    k = pos;
	    while ((unsigned) k < manager->subtables[k].next) {
		k = manager->subtables[k].next;
	    }
	} else {
	    while ((unsigned) pos < manager->subtables[pos].next)
		pos = manager->subtables[pos].next;
	    k = pos;
	    pos = manager->subtables[pos].next;
	}
#ifdef DD_DEBUG
	/* pos should be the top of the symmetry group and k the bottom */
	assert((unsigned) k >= manager->subtables[k].next);
	assert((unsigned) pos == manager->subtables[k].next);
#endif
	initGroupSize = k - pos + 1;

	stepsUp = ddMoveUp(manager,pos,min);
	if (stepsUp == MV_ERROR) goto ddConvergeSiftingAuxMemoryError;

	if (stepsUp != NULL) {
	    pos = stepsUp->x;
	    k = manager->subtables[pos].next;
	} else {
	    k = pos;
	    while ((unsigned) pos < manager->subtables[pos].next)
		pos = manager->subtables[pos].next;
	}
#ifdef DD_DEBUG
	/* pos should be the bottom of the symmetry group and k the top */
	assert((unsigned) pos >= manager->subtables[pos].next);
	assert((unsigned) k == manager->subtables[pos].next);
#endif
	finalGroupSize = pos - k + 1;

	if (initGroupSize == finalGroupSize) {
	    /* No new symmetry groups detected, return to best position */
	    result = ddBackwardSteps(manager,stepsUp,initialSize);
	} else {
	    while (stepsDown != NULL) {
		step = stepsDown->next;
		cuddDeallocMove(manager, stepsDown);
		stepsDown = step;
	    }
	    initialSize = manager->keys - manager->isolated;
	    stepsDown = ddMoveDown(manager,pos,max);
	    result = ddBackwardSteps(manager,stepsDown,initialSize);
