static void print_address_info(const struct Curl_addrinfo *addr_list)
{
  printf("Address info dump:\n");
  for(const struct Curl_addrinfo *current = addr_list; current; current = current->ai_next) {
    char ip_string[INET6_ADDRSTRLEN];
    printf("    family %2d, canonical name %s, ",
           current->ai_family, 
           current->ai_canonname ? current->ai_canonname : "<none>");
    Curl_printable_address(current, ip_string, sizeof(ip_string));
    printf("%s\n", ip_string);
  }
}
#else
#define print_address_info(ignore) Curl_nop_stmt
#endif

/*
 * Synchronous DNS resolution function for IPv6-enabled builds.
 *
 * This function performs blocking DNS resolution and returns a linked list
 * of address information structures. On success, the caller is responsible
 * for freeing the returned data using Curl_freeaddrinfo().
 */
struct Curl_addrinfo *Curl_sync_getaddrinfo(struct Curl_easy *handle,
                                            const char *domain_name,
                                            int service_port,
                                            int address_family)
{
  struct addrinfo request;
  struct Curl_addrinfo *result;
  int status_code;
  char port_buffer[12];
  char *port_ptr = NULL;
#ifndef USE_RESOLVE_ON_IPS
  char ip_storage[128];
#endif
  int domain_family = PF_INET;

  if((address_family != CURL_IPRESOLVE_V4) && Curl_ipv6works(handle))
    domain_family = PF_UNSPEC;

  memset(&request, 0, sizeof(request));
  request.ai_family = domain_family;
  request.ai_socktype = (handle->conn->transport == TRNSPRT_TCP) ?
    SOCK_STREAM : SOCK_DGRAM;

#ifndef USE_RESOLVE_ON_IPS
  if((1 == curlx_inet_pton(AF_INET, domain_name, ip_storage)) ||
     (1 == curlx_inet_pton(AF_INET6, domain_name, ip_storage))) {
    request.ai_flags = AI_NUMERICHOST;
  }
#endif

  if(service_port) {
    msnprintf(port_buffer, sizeof(port_buffer), "%d", service_port);
    port_ptr = port_buffer;
  }

  status_code = Curl_getaddrinfo_ex(domain_name, port_ptr, &request, &result);
  if(status_code) {
    infof(handle, "DNS lookup failed for %s:%d", domain_name, service_port);
    return NULL;
  }

  if(service_port) {
    Curl_addrinfo_set_port(result, service_port);
  }

  print_address_info(result);
  return result;
}

