#include <iostream>
#include <vector>
#include <algorithm>
#include <random>
#include <cmath>
using namespace std;

// Simulates the text wrapping process: returns how many lines are needed
// to display words with lengths in 'a' given line width 'W'.
// Returns 0 if any word length exceeds W.
int count_lines(const vector<int>& lengths, int max_width) {
    int num_lines = 1;
    long long current_length = 0;

    for (int len : lengths) {
        if (len > max_width) return 0;

        if (current_length + len <= max_width) {
            current_length += len;
        } else {
            num_lines++;
            current_length = len;
        }
    }

    return num_lines;
}

void process_case() {
    const int N = 100000;

    // First query: all words of length 1
    cout << "? " << N;
    for (int i = 0; i < N; ++i) cout << " 1";
    cout << endl;

    int response1;
    cin >> response1;

    // Handle termination or invalid input
    if (response1 == 0 || response1 == -1) exit(0);

    // Calculate bounds for possible W values based on first response
    // k1 = ceil(N / W) => W is in [ceil(N/k1), floor((N-1)/(k1-1))] for k1 > 1
    int lower_bound = (N + response1 - 1) / response1;
    int upper_bound;

    if (response1 == 1) {
        upper_bound = 100000;
    } else {
        upper_bound = (N - 1) / (response1 - 1);
    }

    // Clamp to problem constraints
    if (upper_bound > 100000) upper_bound = 100000;
    if (lower_bound > upper_bound) lower_bound = upper_bound;

    // If range is narrowed down to one value, output it directly
    if (lower_bound == upper_bound) {
        cout << "! " << lower_bound << endl;
        return;
    }

    // Second query: use random word lengths to distinguish between candidates
    mt19937 rng_engine(42); 
    vector<int> word_lengths(N);
    for (int idx = 0; idx < N; ++idx) {
        word_lengths[idx] = (rng_engine() % lower_bound) + 1;
    }

    cout << "? " << N;
    for (int idx = 0; idx < N; ++idx) {
        cout << " " << word_lengths[idx];
    }
    cout << endl;

    int response2;
    cin >> response2;
    if (response2 == -1) exit(0);

    // Binary search to find exact W value
    int result = upper_bound;
    int left = lower_bound, right = upper_bound;

    while (left <= right) {
        int candidate = left + (right - left) / 2;
        int simulated = count_lines(word_lengths, candidate);

        if (simulated == response2) {
            result = candidate;
            break;
        } else if (simulated < response2) {
            right = candidate - 1;
        } else {
            left = candidate + 1;
        }
    }

    cout << "! " << result << endl;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int test_cases;
    if (cin >> test_cases) {
        while (test_cases--) {
            process_case();
        }
    }

    return 0;
}

#include "PLUGIN_NAME.h"
