static const FName PLUGIN_NAMETabIdentifier("PLUGIN_NAME");

#define LOCTEXT_NAMESPACE "FPLUGIN_NAMEModule"

void FPLUGIN_NAMEModule::StartupModule()
{
    // Initialize styling and commands for the plugin
    FPLUGIN_NAMEStyle::Initialize();
    FPLUGIN_NAMEStyle::ReloadTextures();
    FPLUGIN_NAMECommands::Register();

    PluginActionList = MakeShareable(new FUICommandList);
    PluginActionList->MapAction(
        FPLUGIN_NAMECommands::Get().OpenPluginWindow,
        FExecuteAction::CreateRaw(this, &FPLUGIN_NAMEModule::OnPluginButtonClicked),
        FCanExecuteAction()
    );

    UToolMenus::RegisterStartupCallback(FSimpleMulticastDelegate::FDelegate::CreateRaw(this, &FPLUGIN_NAMEModule::SetupMenuEntries));

    FGlobalTabmanager::Get()->RegisterNomadTabSpawner(PLUGIN_NAMETabIdentifier, FOnSpawnTab::CreateRaw(this, &FPLUGIN_NAMEModule::CreatePluginTab))
        .SetDisplayName(LOCTEXT("FPLUGIN_NAMETabTitle", "PLUGIN_NAME"))
        .SetMenuType(ETabSpawnerMenuType::Hidden);
}

void FPLUGIN_NAMEModule::ShutdownModule()
{
    // Clean up resources when module is unloaded
    UToolMenus::UnRegisterStartupCallback(this);
    UToolMenus::UnregisterOwner(this);

    FPLUGIN_NAMEStyle::Shutdown();
    FPLUGIN_NAMECommands::Unregister();
    FGlobalTabmanager::Get()->UnregisterNomadTabSpawner(PLUGIN_NAMETabIdentifier);
}

TSharedRef<SDockTab> FPLUGIN_NAMEModule::CreatePluginTab(const FSpawnTabArgs& SpawnArgs)
{
    FText DisplayText = FText::Format(
        LOCTEXT("WindowContentPlaceholder", "Implement logic in {0} within {1} to customize this tab's content"),
        FText::FromString(TEXT("FPLUGIN_NAMEModule::CreatePluginTab")),
        FText::FromString(TEXT("PLUGIN_NAME.cpp"))
    );

    return SNew(SDockTab)
        .TabRole(ETabRole::NomadTab)
        [
            SNew(SBox)
            .HAlign(HAlign_Center)
            .VAlign(VAlign_Center)
            [
                SNew(STextBlock)
                .Text(DisplayText)
            ]
        ];
}

void FPLUGIN_NAMEModule::OnPluginButtonClicked()
{
    FGlobalTabmanager::Get()->TryInvokeTab(PLUGIN_NAMETabIdentifier);
}

void FPLUGIN_NAMEModule::SetupMenuEntries()
{
    FToolMenuOwnerScoped OwnerScope(this);

    {
        UToolMenu* MainMenuBar = UToolMenus::Get()->ExtendMenu("LevelEditor.MainMenu.Window");
        if (MainMenuBar)
        {
            FToolMenuSection& LayoutSection = MainMenuBar->FindOrAddSection("WindowLayout");
            LayoutSection.AddMenuEntryWithCommandList(FPLUGIN_NAMECommands::Get().OpenPluginWindow, PluginActionList);
        }
    }

    {
        UToolMenu* ToolBarMenu = UToolMenus::Get()->ExtendMenu("LevelEditor.LevelEditorToolBar");
        if (ToolBarMenu)
        {
            FToolMenuSection& SettingsSection = ToolBarMenu->FindOrAddSection("Settings");
            FToolMenuEntry& ButtonEntry = SettingsSection.AddEntry(FToolMenuEntry::InitToolBarButton(FPLUGIN_NAMECommands::Get().OpenPluginWindow));
            ButtonEntry.SetCommandList(PluginActionList);
        }
    }
}

