// Attempts to insert a symbolic operand in place of the immediate ImmVal 
// within the MCInst. The immediate ImmVal has already been adjusted for PC 
// displacement by the caller. If IsBranch is true, the instruction is a 
// branch; otherwise false. When setupForSymbolicDisassembly() was previously 
// called, the GetOpInfo callback may provide symbolic details at Address for 
// this instruction. If GetOpInfo returns non-zero, its output is used to 
// construct an MCExpr added as an operand. If GetOpInfo returns zero and 
// IsBranch is true, SymbolLookUp is used to find a symbol for ImmVal. If no 
// symbol is found, an MCExpr with ImmVal is created. Returns true if an 
// operand was added to MCInst, false otherwise.
bool MCExternalSymbolizer::tryAddingSymbolicOperand(
    MCInst &inst, raw_ostream &commentStream, int64_t ImmVal, uint64_t Addr,
    bool BranchFlag, uint64_t Offset, uint64_t OpWidth, uint64_t InstrLen) {
  struct LLVMOpInfo1 RefInfo;
  std::memset(&RefInfo, 0, sizeof(struct LLVMOpInfo1));
  RefInfo.Value = ImmVal;

  if (!GetOpInfo ||
      !GetOpInfo(DisInfo, Addr, Offset, OpWidth, InstrLen, 1, &RefInfo)) {
    // Reset RefInfo fields when GetOpInfo fails
    std::memset(&RefInfo, 0, sizeof(struct LLVMOpInfo1));

    // Without relocation info from GetOpInfo(), attempt to infer if ImmVal 
    // represents a symbol address using SymbolLookUp(). For branches, this 
    // guess is always reasonable. For immediates, it's less certain, so we 
    // avoid guessing for 1-byte operands unless it's a branch.
    if (!SymbolLookUp || (OpWidth == 1 && !BranchFlag))
      return false;

    uint64_t RefType;
    if (BranchFlag)
      RefType = LLVMDisassembler_ReferenceType_In_Branch;
    else
      RefType = LLVMDisassembler_ReferenceType_InOut_None;

    const char *SymName;
    const char *FoundName = SymbolLookUp(DisInfo, ImmVal, &RefType, Addr,
                                        &SymName);
    if (FoundName) {
      RefInfo.AddSymbol.Name = FoundName;
      RefInfo.AddSymbol.Present = true;
      // For C++ mangled names, display demangled version in comment
      if(RefType == LLVMDisassembler_ReferenceType_DeMangled_Name)
        commentStream << SymName;
    }
    // Always create MCExpr for branches to show hex addresses
    else if (BranchFlag) {
      RefInfo.Value = ImmVal;
    }

    // Output special reference types to comment stream
    if(RefType == LLVMDisassembler_ReferenceType_Out_SymbolStub)
      commentStream << "symbol stub for: " << SymName;
    else if(RefType == LLVMDisassembler_ReferenceType_Out_Objc_Message)
      commentStream << "Objc message: " << SymName;

    if (!FoundName && !BranchFlag)
      return false;
  }

  // Build the expression components
  const MCExpr *LeftPart = nullptr;
  if (RefInfo.AddSymbol.Present) {
    if (RefInfo.AddSymbol.Name) {
      StringRef Name(RefInfo.AddSymbol.Name);
      MCSymbol *Sym = Ctx.getOrCreateSymbol(Name);
      LeftPart = MCSymbolRefExpr::create(Sym, Ctx);
    } else {
      LeftPart = MCConstantExpr::create((int)RefInfo.AddSymbol.Value, Ctx);
    }
  }

  const MCExpr *RightPart = nullptr;
  if (RefInfo.SubtractSymbol.Present) {
    if (RefInfo.SubtractSymbol.Name) {
      StringRef Name(RefInfo.SubtractSymbol.Name);
      MCSymbol *Sym = Ctx.getOrCreateSymbol(Name);
      RightPart = MCSymbolRefExpr::create(Sym, Ctx);
    } else {
      RightPart = MCConstantExpr::create((int)RefInfo.SubtractSymbol.Value, Ctx);
    }
  }

  const MCExpr *OffsetExpr = nullptr;
  if (RefInfo.Value != 0)
    OffsetExpr = MCConstantExpr::create(RefInfo.Value, Ctx);

  // Construct final expression
  const MCExpr *FinalExpr;
  if (RightPart) {
    const MCExpr *LHS;
    if (LeftPart)
      LHS = MCBinaryExpr::createSub(LeftPart, RightPart, Ctx);
    else
      LHS = MCUnaryExpr::createMinus(RightPart, Ctx);
    if (OffsetExpr)
      FinalExpr = MCBinaryExpr::createAdd(LHS, OffsetExpr, Ctx);
    else
      FinalExpr = LHS;
  } else if (LeftPart) {
    if (OffsetExpr)
      FinalExpr = MCBinaryExpr::createAdd(LeftPart, OffsetExpr, Ctx);
    else
      FinalExpr = LeftPart;
  } else {
    FinalExpr = OffsetExpr ? OffsetExpr : MCConstantExpr::create(0, Ctx);
  }

  // Apply variant kind transformation
  FinalExpr = RelInfo->createExprForCAPIVariantKind(FinalExpr, RefInfo.VariantKind);
  if (!FinalExpr)
    return false;

  inst.addOperand(MCOperand::createExpr(FinalExpr));
  return true;
}

// Adds comments for load instructions referencing base register PC. These often 
// point to entries in literal pools near the instruction's Address. Uses the 
// instruction's Address and immediate Value to look up possible literal pool 
// entries. SymbolLookUp returns symbol names, literal C string pointers, or 
// Objective-C data structure references.
void MCExternalSymbolizer::tryAddingPcLoadReferenceComment(raw_ostream &commentStream,
                                                           int64_t ImmVal,
                                                           uint64_t Addr) {
  if (SymbolLookUp) {
    uint64_t RefType = LLVMDisassembler_ReferenceType_In_PCrel_Load;
    const char *SymName;
    (void)SymbolLookUp(DisInfo, ImmVal, &RefType, Addr, &SymName);

    if(RefType == LLVMDisassembler_ReferenceType_Out_LitPool_SymAddr)
      commentStream << "literal pool symbol address: " << SymName;
    else if(RefType == LLVMDisassembler_ReferenceType_Out_LitPool_CstrAddr) {
      commentStream << "literal pool for: \"";
      commentStream.write_escaped(SymName);
      commentStream << "\"";
    }
    else if(RefType == LLVMDisassembler_ReferenceType_Out_Objc_CFString_Ref)
      commentStream << "Objc cfstring ref: @\"" << SymName << "\"";
    else if(RefType == LLVMDisassembler_ReferenceType_Out_Objc_Message)
      commentStream << "Objc message: " << SymName;
    else if(RefType == LLVMDisassembler_ReferenceType_Out_Objc_Message_Ref)
      commentStream << "Objc message ref: " << SymName;
    else if(RefType == LLVMDisassembler_ReferenceType_Out_Objc_Selector_Ref)
      commentStream << "Objc selector ref: " << SymName;
    else if(RefType == LLVMDisassembler_ReferenceType_Out_Objc_Class_Ref)
      commentStream << "Objc class ref: " << SymName;
  }
}

namespace llvm {
MCSymbolizer *createMCSymbolizer(const Triple &TargetTriple, LLVMOpInfoCallback GetOpInfo,
                                 LLVMSymbolLookupCallback SymbolLookUp,
                                 void *ClientData, MCContext *Context,
                                 std::unique_ptr<MCRelocationInfo> &&RelocInfo) {
  assert(Context && "No MCContext provided for symbolic disassembly");
  return new MCExternalSymbolizer(*Context, std::move(RelocInfo), GetOpInfo,
                                  SymbolLookUp, ClientData);
}
}

