void run_kernel(const volatile struct RuntimeParams* params)
{
#ifdef RUNTIME_FORMATS
    const volatile FormatConfig& fmts = params->formats;
#endif

    // Initialize unary data copy: srcA → dest
#ifdef ARCH_BLACKHOLE
    _llk_math_eltwise_unary_datacopy_init_<DataCopyType::A2D, is_fp32_dest_acc_en, BroadcastType::NONE, false, false>(
        FACE_R_DIM, fmts.math);
#else
    _llk_math_eltwise_unary_datacopy_init_<DataCopyType::A2D, is_fp32_dest_acc_en, BroadcastType::NONE, false>(
        FACE_R_DIM, fmts.math);
#endif

    _llk_math_pack_sync_init_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
    _llk_math_hw_configure_<is_fp32_dest_acc_en>(fmts.math, fmts.math);

    // Block until destination buffer region is ready
    _llk_math_wait_for_dest_available_<DstSync::SyncHalf>();

    // Process all input tiles
    for (std::size_t tile_id = 0; tile_id < static_cast<std::size_t>(params->TILE_CNT); ++tile_id)
    {
        LLK_ASSERT(
            tile_id < get_dest_max_tiles<DstSync::SyncHalf, is_fp32_dest_acc_en, DstTileShape::Tile32x32>(),
            "Block tile index exceeds maximum destination tiles");

        // Perform element-wise copy from srcA to dest
        _llk_math_eltwise_unary_datacopy_<DataCopyType::A2D, DstSync::SyncHalf, is_fp32_dest_acc_en, BroadcastType::NONE, unpack_to_dest>(
            static_cast<int>(tile_id), fmts.math, fmts.math);
    }

    _llk_math_dest_section_done_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
}
