#ifdef LLK_TRISC_PACK
#include "ckernel_sfpu_reduce_custom.h"
#include "llk_pack.h"
#include "llk_pack_common.h"
#include "params.h"

void run_kernel(const volatile struct RuntimeParams* params)
{
#ifdef RUNTIME_FORMATS
    const volatile FormatConfig& fmts = params->formats;
#endif

    // Configure packer hardware
#ifdef ARCH_BLACKHOLE
    _llk_pack_hw_configure_<is_fp32_dest_acc_en, false, false>(fmts.pack_src, fmts.pack_dst, 16U * 16U * 4U);
#else
    _llk_pack_hw_configure_<is_fp32_dest_acc_en, false>(fmts.pack_src, fmts.pack_dst, 16U * 16U * 4U);
#endif

    _llk_pack_init_<false, false>(fmts.pack_dst);

    // Prepare destination for packing
#ifdef ARCH_BLACKHOLE
    _llk_pack_dest_init_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
#else
    _llk_pack_dest_init_<DstSync::SyncHalf, false, false>();
#endif

    _llk_packer_wait_for_math_done_();

    // SFPU reduce operations setup
    _llk_math_eltwise_unary_sfpu_init_<SfpuType::reduce>();
    ckernel::sfpu::_init_reduce_max_col_subblock_4x2_<DataFormat::Float16_b>();
    _llk_math_eltwise_unary_sfpu_start_<DstSync::SyncHalf>(0U);
    ckernel::sfpu::_reduce_max_col_subblock_4x2_prologue_();
    ckernel::sfpu::_calculate_reduce_max_col_subblock_4x2_<PoolType::MAX, REDUCE_COL, DataFormat::Float16_b>(BLOCK_RT_DIM);
    ckernel::sfpu::_reduce_max_col_subblock_4x2_epilogue_();
    _llk_math_eltwise_unary_sfpu_done_();

    // Wait for math completion and write packed results back to L1
    for (std::size_t t_idx = 0; t_idx < static_cast<std::size_t>(params->TILE_CNT); ++t_idx)
    {
        LLK_ASSERT(
            t_idx < get_dest_max_tiles<DstSync::SyncHalf, is_fp32_dest_acc_en, DstTileShape::Tile32x32>(),
            "Block tile index exceeds maximum destination tiles");

        _llk_pack_<DstSync::SyncHalf, is_fp32_dest_acc_en, false>(
            static_cast<int>(t_idx), L1_ADDRESS(params->buffer_Res[t_idx]));
    }

    _llk_pack_dest_section_done_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
}
#endif

