PubAckPacket::PubAckPacket(ParsingInformation* info, OnPubAckInternalCallback cb)
: _parsingInformation(info)
, _callback(cb)
, _position(0)
, _highByte(0)
, _packetIdValue(0) {
}

PubAckPacket::~PubAckPacket() {
}

void PubAckPacket::parseVariableHeader(char* buffer, size_t size, size_t* byteIndex) {
  char current = buffer[(*byteIndex)++];
  if (_position++ == 0) {
    _highByte = current;
  } else {
    _packetIdValue = current | (_highByte << 8);
    _parsingInformation->bufferState = BufferState::NONE;
    _callback(_packetIdValue);
  }
}

void PubAckPacket::parsePayload(char* data, size_t len, size_t* position) {
  (void)data;
  (void)len;
  (void)position;
}

