#include <fstream>
#include <iostream>
#include <omp.h>
#include <vector>
#include "bench_utils.h"
#include "superkmeans/common.h"
#include "superkmeans/hierarchical_superkmeans.h"
#include "superkmeans/superkmeans.h"

int main(int argc, char* argv[]) {
    std::string dataset_name = (argc > 1) ? std::string(argv[1]) : std::string("yahoo");
    auto iter = bench_utils::DATASET_PARAMS.find(dataset_name);
    if (iter == bench_utils::DATASET_PARAMS.end()) {
        std::cerr << "Unknown dataset '" << dataset_name << "'\n";
        return 1;
    }

    const size_t num_samples = iter->second.first;
    const size_t num_features = iter->second.second;
    const size_t cluster_count = 40000; // bench_utils::get_default_n_clusters(num_samples);
    int max_iterations = 5;
    float sample_ratio = 1.0f;

    std::string data_file = bench_utils::get_data_path(dataset_name);
    const size_t NUM_THREADS = omp_get_max_threads();
    omp_set_num_threads(NUM_THREADS);

    std::cout << "=== Assign Benchmark ===" << std::endl;
    std::cout << "Dataset: " << dataset_name << " (n=" << num_samples << ", d=" << num_features << ")\n";
    std::cout << "cluster_count=" << cluster_count << " max_iterations=" << max_iterations
              << " sample_ratio=" << sample_ratio << "\n";

    std::vector<float> dataset;
    try {
        dataset.reserve(num_samples * num_features);
    } catch (const std::bad_alloc& e) {
        std::cerr << "Failed to allocate dataset vector for n*d = " << (num_samples * num_features) << ": " << e.what()
                  << "\n";
        return 1;
    }

    std::ifstream input_stream(data_file, std::ios::binary);
    if (!input_stream) {
        std::cerr << "Failed to open " << data_file << std::endl;
        return 1;
    }

    input_stream.read(reinterpret_cast<char*>(dataset.data()), num_samples * num_features * sizeof(float));
    input_stream.close();

    // --- Training ---
    skmeans::HierarchicalSuperKMeansConfig settings;
    settings.iters_mesoclustering = 3;
    settings.iters_fineclustering = 5;
    settings.iters_refinement = 0;
    settings.verbose = false;
    settings.n_threads = NUM_THREADS;
    settings.unrotate_centroids = true;
    settings.early_termination = false;
    settings.sampling_fraction = sample_ratio;
    settings.use_blas_only = false;

    auto is_spherical = std::find(
        bench_utils::ANGULAR_DATASETS.begin(), bench_utils::ANGULAR_DATASETS.end(), dataset_name
    );
    if (is_spherical != bench_utils::ANGULAR_DATASETS.end()) {
        std::cout << "Using spherical k-means" << std::endl;
        settings.angular = true;
    }

    auto kmeans_instance =
        skmeans::HierarchicalSuperKMeans<skmeans::Quantization::f32, skmeans::DistanceFunction::l2>(
            cluster_count, num_features, settings
        );

    bench_utils::TicToc training_timer;
    training_timer.Tic();
    auto cluster_centers = kmeans_instance.Train(dataset.data(), num_samples);
    training_timer.Toc();

    std::cout << "\nTraining completed in " << training_timer.GetMilliseconds() << " ms" << std::endl;

    // --- FastAssign (GEMM+PRUNING fast path) ---
    bench_utils::TicToc fast_assign_timer;
    fast_assign_timer.Tic();
    auto fast_cluster_assignments = kmeans_instance.FastAssign(dataset.data(), cluster_centers.data(), num_samples, cluster_count);
    fast_assign_timer.Toc();

    double fast_time_ms = fast_assign_timer.GetMilliseconds();
    std::cout << "\nFastAssign: " << fast_time_ms << " ms" << std::endl;

    // --- Assign (brute force) ---
    bench_utils::TicToc brute_force_timer;
    brute_force_timer.Tic();
    auto brute_assignments = kmeans_instance.Assign(dataset.data(), cluster_centers.data(), num_samples, cluster_count);
    brute_force_timer.Toc();

    double brute_time_ms = brute_force_timer.GetMilliseconds();
    std::cout << "Assign:     " << brute_time_ms << " ms" << std::endl;

    // --- Compare ---
    double speedup_factor = brute_time_ms / fast_time_ms;
    size_t agreement_count = 0;

    for (size_t idx = 0; idx < num_samples; ++idx) {
        if (fast_cluster_assignments[idx] == brute_assignments[idx]) {
            ++agreement_count;
        }
    }

    double agreement_percent = 100.0 * static_cast<double>(agreement_count) / static_cast<double>(num_samples);

    std::cout << "\nSpeedup: " << speedup_factor << "x" << std::endl;
    std::cout << "Agreement: " << agreement_percent << "% (" << agreement_count << "/" << num_samples << ")" << std::endl;

    return 0;
}

#include <execinfo.h>
