namespace Gorgon::Utils {

    void CrashHandler::Backtrace() {
        // Allocate space for trace points
        void **buffer = static_cast<void**>(malloc((maxDepth + offset + 2) * sizeof(void*)));
        int count = backtrace(buffer, maxDepth + offset + 2);

        char **symbolStrings = nullptr;
        symbolStrings = backtrace_symbols(buffer, count);
        auto termOut = StdConsole();

        auto printFrame = [&](int idx) {
            std::string rawLine = symbolStrings[idx];
            auto openParen = rawLine.find_first_of('(');
            auto closeParenOrPlus = rawLine.find_first_of("+)", openParen);

            std::string funcName = rawLine.substr(openParen + 1, closeParenOrPlus - openParen - 1);

            std::string demangledName = demangle(funcName);

            int pipeFds[2];
            if (pipe(pipeFds)) return;

            pid_t childPid = fork();
            if (childPid > 0) {
                if (childPid < 0) return;
                wait(nullptr);

                close(pipeFds[1]);
                char outputBuffer[2048];

                ssize_t bytesRead = read(pipeFds[0], outputBuffer, sizeof(outputBuffer) - 1);
                if (bytesRead <= 0) {
                    close(pipeFds[0]);
                    return;
                }
                outputBuffer[bytesRead] = '\0';

                close(pipeFds[0]);

                std::string lineContent = outputBuffer;

                size_t colonPos = lineContent.find_first_of(':');
                size_t spaceAfterColon = lineContent.find_first_of(' ', colonPos);
                if (spaceAfterColon == std::string::npos)
                    spaceAfterColon = lineContent.length();

                std::string filePathPart;
                try {
                    filePathPart = Filesystem::Canonical(lineContent.substr(0, colonPos));
                } catch (...) {
                    filePathPart = lineContent.substr(0, colonPos);
                }

                int lineNumber = String::To<int>(lineContent.substr(colonPos + 1, spaceAfterColon - colonPos - 1));

                std::string dirPath = Filesystem::GetDirectory(filePathPart);
                if (!dirPath.empty() && dirPath.back() == '/')
                    dirPath.pop_back();

                std::string baseDir = Filesystem::GetFilename(dirPath);
                std::string baseFile = Filesystem::GetFilename(filePathPart);

                termOut.SetColor(Console::Magenta);
                if ((idx - offset - 1) == 1) {
                    termOut.SetBold(true);
                }
                std::cout << "  [" << (idx - offset - 1) << "] ";
                termOut.SetBold(false);
                termOut.SetColor(Console::Default);

                if (!demangledName.empty()) {
                    std::cout << "In function ";
                    termOut.SetColor(Console::Yellow);
                    std::cout << demangledName << " ";
                } else if (!funcName.empty()) {
                    std::cout << "In function ";
                    termOut.SetColor(Console::Yellow);
                    std::cout << funcName << " ";
                }
                termOut.SetColor(Console::Default);
                std::cout << "at ";
                if ((idx - offset - 1) == 1) {
                    termOut.SetColor(Console::Red);
                }
                std::cout << "..." << baseDir << "/" << baseFile;
                termOut.SetBold();
                std::cout << ":" << lineNumber << std::endl;
                termOut.Reset();
            }
            else if (childPid == 0) {
                errno = 0;
                char addressStr[64];
                snprintf(addressStr, sizeof(addressStr), "%p", buffer[idx]);

                close(pipeFds[0]);
                dup2(pipeFds[1], STDOUT_FILENO);
                dup2(pipeFds[1], STDERR_FILENO);

                execlp("addr2line", "addr2line", addressStr, "-e", Filesystem::ExePath().c_str(), nullptr);

                perror("Addr2line utility not found.");
                _exit(EXIT_FAILURE);
            }
        };

#ifdef TEST
        for (int j = 2; j < offset + 2; ++j) {
            printFrame(j);
        }
#endif

        for (int k = offset + 2; k < count; ++k) {
            printFrame(k);
        }
    }

}

