#if defined(__aarch64__) || defined(_M_ARM64)
#include <secp256k1/field.hpp>
#include <secp256k1/field_asm.hpp>
#include <secp256k1/config.hpp>
#include <cstdint>
#include <cstring>

namespace secp256k1::fast {
namespace arm64 {

// ============================================================================
// ARM64 256-bit Field Multiplication with secp256k1 Reduction (Optimized)
// ============================================================================
// Full 4x4 limb multiply -> 512-bit -> reduce mod p in one pass.
// Uses MUL/UMULH pairs (2 cycles each on Cortex-A76, 3 on A55).
// Total: 16 MUL + 16 UMULH + reduction ~= 50-80 cycles on A76
//
// Strategy: Schoolbook 4x4 multiply into 8 limbs, then secp256k1-specific
// reduction using k = 2^32 + 977.
// ============================================================================
void field_mul_arm64(uint64_t dest[4], const uint64_t x[4], const uint64_t y[4]) noexcept {
    // Phase 1: Full 256x256 -> 512 bit multiplication
    // Using inline assembly to maximize register utilization and
    // exploit ARM64's ability to do MUL+UMULH in parallel pipelines.

    uint64_t prod[8]; // 512-bit intermediate product

    __asm__ __volatile__(
        // ---- Column 0: prod[0] ----
        "mul    x22,  %[in_a0], %[in_b0]       \n\t"
        "umulh  x23,  %[in_a0], %[in_b0]       \n\t"
        "str    x22,  [%[mem_prod], #0]        \n\t"

        // ---- Column 1: prod[1] ----
        "mul    x24,  %[in_a0], %[in_b1]       \n\t"
        "umulh  x25,  %[in_a0], %[in_b1]       \n\t"
        "mul    x26,  %[in_a1], %[in_b0]       \n\t"
        "umulh  x27,  %[in_a1], %[in_b0]       \n\t"
        "adds   x23,  x23,  x24               \n\t"
        "adcs   x25,  x25,  xzr               \n\t"
        "adds   x23,  x23,  x26               \n\t"
        "adcs   x25,  x25,  x27               \n\t"
        "str    x23,  [%[mem_prod], #8]       \n\t"
        "mov    x28,  xzr                     \n\t"
        "adc    x28,  x28,  xzr               \n\t"

        // ---- Column 2: prod[2] ----
        "mul    x22,  %[in_a0], %[in_b2]       \n\t"
        "umulh  x23,  %[in_a0], %[in_b2]       \n\t"
        "mul    x24,  %[in_a1], %[in_b1]       \n\t"
        "umulh  x26,  %[in_a1], %[in_b1]       \n\t"
        "mul    x27,  %[in_a2], %[in_b0]       \n\t"
        "umulh  x29,  %[in_a2], %[in_b0]       \n\t"
        "adds   x25,  x25,  x22               \n\t"
        "adcs   x23,  x23,  x28               \n\t"
        "adc    x28,  xzr,  xzr               \n\t"
        "adds   x25,  x25,  x24               \n\t"
        "adcs   x23,  x23,  x26               \n\t"
        "adc    x28,  x28,  xzr               \n\t"
        "adds   x25,  x25,  x27               \n\t"
        "adcs   x23,  x23,  x29               \n\t"
        "adc    x28,  x28,  xzr               \n\t"
        "str    x25,  [%[mem_prod], #16]      \n\t"

        // ---- Column 3: prod[3] ----
        "mul    x22,  %[in_a0], %[in_b3]       \n\t"
        "umulh  x24,  %[in_a0], %[in_b3]       \n\t"
        "mul    x25,  %[in_a1], %[in_b2]       \n\t"
        "umulh  x26,  %[in_a1], %[in_b2]       \n\t"
        "mul    x27,  %[in_a2], %[in_b1]       \n\t"
        "umulh  x29,  %[in_a2], %[in_b1]       \n\t"
        "adds   x23,  x23,  x22               \n\t"
        "adcs   x24,  x24,  x28               \n\t"
        "adc    x28,  xzr,  xzr               \n\t"
        "adds   x23,  x23,  x25               \n\t"
        "adcs   x24,  x24,  x26               \n\t"
        "adc    x28,  x28,  xzr               \n\t"
        "adds   x23,  x23,  x27               \n\t"
        "adcs   x24,  x24,  x29               \n\t"
        "adc    x28,  x28,  xzr               \n\t"
        "mul    x22,  %[in_a3], %[in_b0]       \n\t"
        "umulh  x25,  %[in_a3], %[in_b0]       \n\t"
        "adds   x23,  x23,  x22               \n\t"
        "adcs   x24,  x24,  x25               \n\t"
        "adc    x28,  x28,  xzr               \n\t"
        "str    x23,  [%[mem_prod], #24]      \n\t"

        // ---- Column 4: prod[4] ----
        "mul    x22,  %[in_a1], %[in_b3]       \n\t"
        "umulh  x23,  %[in_a1], %[in_b3]       \n\t"
        "mul    x25,  %[in_a2], %[in_b2]       \n\t"
        "umulh  x26,  %[in_a2], %[in_b2]       \n\t"
        "mul    x27,  %[in_a3], %[in_b1]       \n\t"
        "umulh  x29,  %[in_a3], %[in_b1]       \n\t"
        "adds   x24,  x24,  x22               \n\t"
        "adcs   x23,  x23,  x28               \n\t"
        "adc    x28,  xzr,  xzr               \n\t"
        "adds   x24,  x24,  x25               \n\t"
        "adcs   x23,  x23,  x26               \n\t"
        "adc    x28,  x28,  xzr               \n\t"
        "adds   x24,  x24,  x27               \n\t"
        "adcs   x23,  x23,  x29               \n\t"
        "adc    x28,  x28,  xzr               \n\t"
        "str    x24,  [%[mem_prod], #32]      \n\t"

        // ---- Column 5: prod[5] ----
        "mul    x22,  %[in_a2], %[in_b3]       \n\t"
        "umulh  x24,  %[in_a2], %[in_b3]       \n\t"
        "mul    x25,  %[in_a3], %[in_b2]       \n\t"
        "umulh  x26,  %[in_a3], %[in_b2]       \n\t"
        "adds   x23,  x23,  x22               \n\t"
        "adcs   x24,  x24,  x28               \n\t"
        "adc    x28,  xzr,  xzr               \n\t"
        "adds   x23,  x23,  x25               \n\t"
        "adcs   x24,  x24,  x26               \n\t"
        "adc    x28,  x28,  xzr               \n\t"
        "str    x23,  [%[mem_prod], #40]      \n\t"

        // ---- Column 6: prod[6] ----
        "mul    x22,  %[in_a3], %[in_b3]       \n\t"
        "umulh  x23,  %[in_a3], %[in_b3]       \n\t"
        "adds   x24,  x24,  x22               \n\t"
        "adcs   x23,  x23,  x28               \n\t"
        "str    x24,  [%[mem_prod], #48]      \n\t"
        "str    x23,  [%[mem_prod], #56]      \n\t"

        : /* no output operands -- results stored via pointers */
        : [in_a0] "r"(x[0]), [in_a1] "r"(x[1]), [in_a2] "r"(x[2]), [in_a3] "r"(x[3]),
          [in_b0] "r"(y[0]), [in_b1] "r"(y[1]), [in_b2] "r"(y[2]), [in_b3] "r"(y[3]),
          [mem_prod] "r"(prod)
        : "x22", "x23", "x24", "x25", "x26", "x27", "x28", "x29",
          "cc", "memory"
    );

    // Phase 2: secp256k1 fast reduction
    // p = 2^256 - k where k = 0x1000003D1
    // prod[0..3] + prod[4..7] * k (mod 2^256), then normalize

    constexpr uint64_t K = 0x1000003D1ULL;

    uint64_t res0 = prod[0], res1 = prod[1], res2 = prod[2], res3 = prod[3];

    __asm__ __volatile__(
        // Reduce prod[4]: res += prod[4] * K
        "mul    x22,  %[ph4], %[const_k]        \n\t"
        "umulh  x23,  %[ph4], %[const_k]        \n\t"
        "adds   res0, res0, x22                 \n\t"
        "adcs   res1, res1, x23                 \n\t"
        "adcs   res2, res2, xzr                 \n\t"
        "adcs   res3, res3, xzr                 \n\t"
        "adc    x28, xzr, xzr                   \n\t"

        // Reduce prod[5]: res += prod[5] * K << 64
        "mul    x22,  %[ph5], %[const_k]        \n\t"
        "umulh  x23,  %[ph5], %[const_k]        \n\t"
        "adds   res1, res1, x22                 \n\t"
        "adcs   res2, res2, x23                 \n\t"
        "adcs   res3, res3, xzr                 \n\t"
        "adc    x28, x28, xzr                   \n\t"

        // Reduce prod[6]: res += prod[6] * K << 128
        "mul    x22,  %[ph6], %[const_k]        \n\t"
        "umulh  x23,  %[ph6], %[const_k]        \n\t"
        "adds   res2, res2, x22                 \n\t"
        "adcs   res3, res3, x23                 \n\t"
        "adc    x28, x28, xzr                   \n\t"

        // Reduce prod[7]: res += prod[7] * K << 192
        "mul    x22,  %[ph7], %[const_k]        \n\t"
        "umulh  x23,  %[ph7], %[const_k]        \n\t"
        "adds   res3, res3, x22                 \n\t"
        "adc    x28, x28, x23                   \n\t"

        // Second-round reduction for overflow in x28 (<= ~0x1000003D1 max)
        "mul    x22,  x28, %[const_k]           \n\t"
        "umulh  x23,  x28, %[const_k]           \n\t"
        "adds   res0, res0, x22                 \n\t"
        "adcs   res1, res1, x23                 \n\t"
        "adcs   res2, res2, xzr                 \n\t"
        "adcs   res3, res3, xzr                 \n\t"
        "adc    x28, xzr, xzr                   \n\t"

        // Third-round (extremely rare, but mathematically possible)
        "mul    x22,  x28, %[const_k]           \n\t"
        "adds   res0, res0, x22                 \n\t"
        "adcs   res1, res1, xzr                 \n\t"
        "adcs   res2, res2, xzr                 \n\t"
        "adc    res3, res3, xzr                 \n\t"

        : [res0] "+r"(res0), [res1] "+r"(res1), [res2] "+r"(res2), [res3] "+r"(res3)
        : [ph4] "r"(prod[4]), [ph5] "r"(prod[5]), [ph6] "r"(prod[6]), [ph7] "r"(prod[7]),
          [const_k] "r"(K)
        : "x22", "x23", "x28", "cc"
    );

    // Final normalization: if res >= p, subtract p (branchless)
    // p = {0xFFFFFFFEFFFFFC2F, 0xFFFFFFFFFFFFFFFF, 0xFFFFFFFFFFFFFFFF, 0xFFFFFFFFFFFFFFFF}
    constexpr uint64_t MOD0 = 0xFFFFFFFEFFFFFC2FULL;
    constexpr uint64_t MOD1 = 0xFFFFFFFFFFFFFFFFULL;
    uint64_t tmp0, tmp1, tmp2, tmp3;

    __asm__ __volatile__(
        // Subtract modulus
        "subs   tmp0, res0, mod0         \n\t"
        "sbcs   tmp1, res1, mod1         \n\t"
        "sbcs   tmp2, res2, mod1         \n\t"
        "sbcs   tmp3, res3, mod1         \n\t"

        // Branchless select via CSEL: dest = borrow ? res : tmp
        "csel   tmp0, res0, tmp0, cc     \n\t"
        "csel   tmp1, res1, tmp1, cc     \n\t"
        "csel   tmp2, res2, tmp2, cc     \n\t"
        "csel   tmp3, res3, tmp3, cc     \n\t"

        : [tmp0] "=&r"(tmp0), [tmp1] "=&r"(tmp1), [tmp2] "=&r"(tmp2), [tmp3] "=&r"(tmp3)
        : [res0] "r"(res0), [res1] "r"(res1), [res2] "r"(res2), [res3] "r"(res3),
          [mod0] "r"(MOD0), [mod1] "r"(MOD1)
        : "cc"
    );

    dest[0] = tmp0;
    dest[1] = tmp1;
    dest[2] = tmp2;
    dest[3] = tmp3;
}

// ============================================================================
// ARM64 256-bit Field Squaring with secp256k1 Reduction
// ============================================================================
// Exploits symmetry: x[i]*x[j] appears twice for i!=j, so we compute it once
// and double. Only 10 multiplications instead of 16.
// ============================================================================
void field_sqr_arm64(uint64_t dest[4], const uint64_t val[4]) noexcept {
    uint64_t temp[8];

    __asm__ __volatile__(
        // Compute cross products (i<j), each appears 2x

        // x[0]*x[1]
        "mul    x22,  %[in_x0], %[in_x1]       \n\t"
        "umulh  x23,  %[in_x0], %[in_x1]       \n\t"

        // x[0]*x[2]
        "mul    x24,  %[in_x0], %[in_x2]       \n\t"
        "umulh  x25,  %[in_x0], %[in_x2]       \n\t"

        // x[0]*x[3]
        "mul    x26,  %[in_x0], %[in_x3]       \n\t"
        "umulh  x27,  %[in_x0], %[in_x3]       \n\t"

        // x[1]*x[2]
        "mul    x28,  %[in_x1], %[in_x2]       \n\t"
        "umulh  x29,  %[in_x1], %[in_x2]       \n\t"

        // x[1]*x[3]
        "mul    x30,  %[in_x1], %[in_x3]       \n\t"
        "umulh  x31,  %[in_x1], %[in_x3]       \n\t"

        // x[2]*x[3]
        "mul    x20,  %[in_x2], %[in_x3]       \n\t"
        "umulh  x21,  %[in_x2], %[in_x3]       \n\t"

        // Accumulate cross products into columns

        // col2 += x02_lo
        "adds   x23, x23,  x24               \n\t"
        "adcs   x25, x25,  x26               \n\t"
        "adcs   x27, x27,  xzr               \n\t"
        "adc    x22, xzr,  xzr               \n\t"

        // col3 += x12_lo
        "adds   x25, x25,  x28               \n\t"
        "adcs   x27, x27,  x29               \n\t"
        "adc    x22, x22,  xzr               \n\t"

        // col4 += x13_lo
        "adds   x27, x27,  x30               \n\t"
        "adcs   x31, x31,  x22               \n\t"
        "adc    x22, xzr,  xzr               \n\t"

        // col5 += x23_lo
        "adds   x31, x31,  x20               \n\t"
        "adc    x21, x21,  x22               \n\t"

        // Double everything (shift left by 1 for 2x cross products)
        "lsr    x22, x21, #63                \n\t"
        "extr   x21, x21, x31, #63           \n\t"
        "extr   x31, x31, x27, #63           \n\t"
        "extr   x27, x27, x25, #63           \n\t"
        "extr   x25, x25, x23, #63           \n\t"
        "extr   x23, x23, x22, #63           \n\t" // Note: x22 here is actually previous MSB
        "lsl    x22, x22, #1                 \n\t"

        // Now add diagonal products x[i]*x[i]
        // x[0]*x[0]
        "mul    x24, %[in_x0], %[in_x0]       \n\t"
        "umulh  x26, %[in_x0], %[in_x0]       \n\t"
        "str    x24, [%[mem_temp], #0]        \n\t"
        "adds   x22, x22,  x26               \n\t"
        "str    x22, [%[mem_temp], #8]        \n\t"

        // x[1]*x[1]  
        "mul    x24, %[in_x1], %[in_x1]       \n\t"
        "umulh  x26, %[in_x1], %[in_x1]       \n\t"
        "adcs   x23, x23,  x24               \n\t"
        "adcs   x25, x25,  x26               \n\t"
        "str    x23, [%[mem_temp], #16]       \n\t"
        "str    x25, [%[mem_temp], #24]       \n\t"

        // x[2]*x[2]
        "mul    x24, %[in_x2], %[in_x2]       \n\t"
        "umulh  x26, %[in_x2], %[in_x2]       \n\t"
        "adcs   x27, x27,  x24               \n\t"
        "adcs   x31, x31,  x26               \n\t"
        "str    x27, [%[mem_temp], #32]       \n\t"
        "str    x31, [%[mem_temp], #40]       \n\t"

        // x[3]*x[3]
        "mul    x24, %[in_x3], %[in_x3]       \n\t"
        "umulh  x26, %[in_x3], %[in_x3]       \n\t"
        "adcs   x21, x21,  x24               \n\t"
        "adc    x22, x22,  x26               \n\t"
        "str    x21, [%[mem_temp], #48]       \n\t"
        "str    x22, [%[mem_temp], #56]       \n\t"

        : /* outputs via memory */
        : [in_x0] "r"(val[0]), [in_x1] "r"(val[1]), [in_x2] "r"(val[2]), [in_x3] "r"(val[3]),
          [mem_temp] "r"(temp)
        : "x20", "x21", "x22", "x23", "x24", "x25", "x26", "x27",
          "x28", "x29", "x30", "x31",
          "cc", "memory"
    );

    // Phase 2: secp256k1 fast reduction (identical to mul)
    constexpr uint64_t K = 0x1000003D1ULL;

    uint64_t r0 = temp[0], r1 = temp[1], r2 = temp[2], r3 = temp[3];

    __asm__ __volatile__(
        "mul    x22,  %[th4], %[const_k]        \n\t"
        "umulh  x23,  %[th4], %[const_k]        \n\t"
        "adds   r0, r0, x22                     \n\t"
        "adcs   r1, r1, x23                     \n\t"
        "adcs   r2, r2, xzr                     \n\t"
        "adcs   r3, r3, xzr                     \n\t"
        "adc    x28, xzr, xzr                   \n\t"
        "mul    x22,  %[th5], %[const_k]        \n\t"
        "umulh  x23,  %[th5], %[const_k]        \n\t"
        "adds   r1, r1, x22                     \n\t"
        "adcs   r2, r2, x23                     \n\t"
        "adcs   r3, r3, xzr                     \n\t"
        "adc    x28, x28, xzr                   \n\t"
        "mul    x22,  %[th6], %[const_k]        \n\t"
        "umulh  x23,  %[th6], %[const_k]        \n\t"
        "adds   r2, r2, x22                     \n\t"
        "adcs   r3, r3, x23                     \n\t"
        "adc    x28, x28, xzr                   \n\t"
        "mul    x22,  %[th7], %[const_k]        \n\t"
        "umulh  x23,  %[th7], %[const_k]        \n\t"
        "adds   r3, r3, x22                     \n\t"
        "adc    x28, x28, x23                   \n\t"
        "mul    x22,  x28, %[const_k]           \n\t"
        "umulh  x23,  x28, %[const_k]           \n\t"
        "adds   r0, r0, x22                     \n\t"
        "adcs   r1, r1, x23                     \n\t"
        "adcs   r2, r2, xzr                     \n\t"
        "adcs   r3, r3, xzr                     \n\t"
        "adc    x28, xzr, xzr                   \n\t"
        "mul    x22,  x28, %[const_k]           \n\t"
        "adds   r0, r0, x22                     \n\t"
        "adcs   r1, r1, xzr                     \n\t"
        "adcs   r2, r2, xzr                     \n\t"
        "adc    r3, r3, xzr                     \n\t"
        : [r0] "+r"(r0), [r1] "+r"(r1), [r2] "+r"(r2), [r3] "+r"(r3)
        : [th4] "r"(temp[4]), [th5] "r"(temp[5]), [th6] "r"(temp[6]), [th7] "r"(temp[7]),
          [const_k] "r"(K)
        : "x22", "x23", "x28", "cc"
    );

    // Branchless normalization
    constexpr uint64_t MP0 = 0xFFFFFFFEFFFFFC2FULL;
    constexpr uint64_t MP1 = 0xFFFFFFFFFFFFFFFFULL;
    uint64_t s0, s1, s2, s3;
    __asm__ __volatile__(
        "subs   s0, r0, mp0         \n\t"
        "sbcs   s1, r1, mp1         \n\t"
        "sbcs   s2, r2, mp1         \n\t"
        "sbcs   s3, r3, mp1         \n\t"
        // CSEL: 4 instructions vs BIC+AND+ORR (12 instructions)
        "csel   s0, r0, s0, cc      \n\t"
        "csel   s1, r1, s1, cc      \n\t"
        "csel   s2, r2, s2, cc      \n\t"
        "csel   s3, r3, s3, cc      \n\t"
        : [s0] "=&r"(s0), [s1] "=&r"(s1), [s2] "=&r"(s2), [s3] "=&r"(s3)
        : [r0] "r"(r0), [r1] "r"(r1), [r2] "r"(r2), [r3] "r"(r3),
          [mp0] "r"(MP0), [mp1] "r"(MP1)
        : "cc"
    );

    dest[0] = s0;
    dest[1] = s1;
    dest[2] = s2;
    dest[3] = s3;
}

// ============================================================================
// ARM64 256-bit Field Add/Sub with Branchless Normalization
// ============================================================================
void field_add_arm64(uint64_t out[4], const uint64_t lhs[4], const uint64_t rhs[4]) noexcept {
    uint64_t sum0, sum1, sum2, sum3;
    uint64_t diff0, diff1, diff2, diff3;

    // Prime p limbs -- passed as register inputs (ARM64 MOV can't encode arbitrary 64-bit)
    constexpr uint64_t MOD0 = 0xFFFFFFFEFFFFFC2FULL;
    constexpr uint64_t MOD1 = 0xFFFFFFFFFFFFFFFFULL;

    __asm__ __volatile__(
        // lhs + rhs
        "adds   sum0, lhs0, rhs0     \n\t"
        "adcs   sum1, lhs1, rhs1     \n\t"
        "adcs   sum2, lhs2, rhs2     \n\t"
        "adcs   sum3, lhs3, rhs3     \n\t"
        "adc    x28, xzr, xzr        \n\t"   // carry into x28

        // Subtract modulus
        "subs   diff0, sum0, mod0        \n\t"
        "sbcs   diff1, sum1, mod1        \n\t"
        "sbcs   diff2, sum2, mod1        \n\t"
        "sbcs   diff3, sum3, mod1        \n\t"
        "sbcs   x28,  x28,  xzr          \n\t"  // carry - 0 - borrow

        // If x28 == 0 (no borrow from carry): use subtracted
        // If x28 wrapped (borrow): use original sum
        // CSEL: 4 instructions vs BIC+AND+ORR (12 instructions)
        "csel   diff0, sum0, diff0, cc     \n\t"
        "csel   diff1, sum1, diff1, cc     \n\t"
        "csel   diff2, sum2, diff2, cc     \n\t"
        "csel   diff3, sum3, diff3, cc     \n\t"

        : [sum0] "=&r"(sum0), [sum1] "=&r"(sum1), [sum2] "=&r"(sum2), [sum3] "=&r"(sum3),
          [diff0] "=&r"(diff0),
          [diff1] "=&r"(diff1),
          [diff2] "=&r"(diff2),
          [diff3] "=&r"(diff3)
        : [lhs0] "r"(lhs[0]), [lhs1] "r"(lhs[1]), [lhs2] "r"(lhs[2]), [lhs3] "r"(lhs[3]),
          [rhs0] "r"(rhs[0]), [rhs1] "r"(rhs[1]), [rhs2] "r"(rhs[2]), [rhs3] "r"(rhs[3]),
          [mod0] "r"(MOD0), [mod1] "r"(MOD1)
        : "x28", "cc"
    );

    out[0] = diff0;
    out[1] = diff1;
    out[2] = diff2;
    out[3] = diff3;
}

