    int         totalSlaves;
};

struct JoinExchangePacket {
    int         checksum;             // Validation key
    MessageType type;
    int         joinCount;            // Total number of joins across nodes
    struct {
        char        streamID [Stream::MAXHANDLE]; // Identifier for communication stream
    } joinEntry [DD::MAXJOINS];
};

