//------------------------------------------------------------------------------
void
DD::MasterProcess (
    void
) {
#if defined (WIN32)
    throw new Exception("Remote execution is not supported on Microsoft Windows");
#else
    const char * hostPID = GetHostnamePID();
    char threadLabel [strlen(hostPID) + 100];
    snprintf(threadLabel, sizeof(threadLabel), "%s master", hostPID);
    this->log->RegisterThread(threadLabel);
    delete [] hostPID;

    this->log->Write(Log::DD_STARTUP, "Distributed DD master process started");

    const char * mainArguments = this->flow->DH->mainArgs;
    const char * executablePath = this->flow->DH->exePath;
    const char * remoteShellCmd = this->multiNode->GetAttrib("remoteShellCommand");
    if (remoteShellCmd == nullptr)
        remoteShellCmd = "ssh -n";

    // Capture environment variables required for remote execution
    const char * currentDir = getenv("PWD");
    const char * libPathEnv = getenv("LD_LIBRARY_PATH");
    if (libPathEnv == nullptr) libPathEnv = "";

    // Launch slave processes on remote machines
    for (int idx = 0; idx < this->nodeSet->numNodes; ++idx) {
        Node * targetNode = this->nodeSet->node[idx];
        targetNode->stream = new Stream(Stream::TCPIP, &handleMasterStreamError, &logMasterStreamEvent);
        char * localEndpoint = targetNode->stream->LocalHandle();

        // Construct shell command for remote execution
        constexpr int MAX_CMD_LEN = 10000;
        char remoteExecution[MAX_CMD_LEN];
        int written = snprintf(remoteExecution, MAX_CMD_LEN,
                    "%s %s 'cd %s; export LD_LIBRARY_PATH=%s; ulimit -c unlimited; %s -S %s %s' < /dev/null",
                        remoteShellCmd,
                        targetNode->hostname,
                        currentDir,
                        libPathEnv,
                        executablePath,
                        localEndpoint,
                        mainArguments
                        );
        if (written >= MAX_CMD_LEN)
            throw new Exception("Internal error: Remote command line too long in MasterProcess!");

        // Fork and execute
        this->log->Write(Log::MAJOR, "Master spawning node %d slave process on \"%s\"", idx, targetNode->hostname);
        this->log->Write(Log::CONFIG_MINOR, "Master process executing shell command \"%s\"", remoteExecution);
        targetNode->remotePID = fork();
        if (targetNode->remotePID == 0) {
            if (system(remoteExecution) == 0)
                exit(0);
            else {
                this->log->Write(Log::ALWAYS, "Trouble running \"%s\"", remoteExecution);
                exit(1);
            }
        }
    }

    // Verify all slaves are alive after launch
    sleep(1);
    for (int idx = 0; idx < this->nodeSet->numNodes; ++idx) {
        Node * targetNode = this->nodeSet->node[idx];
        int status;
        int rc = waitpid(targetNode->remotePID, &status, WNOHANG);
        if (rc != 0 && WIFEXITED(status))
            throw new Exception("Slave process for node %d on \"%s\" has exited prematurely", idx, targetNode->hostname);
    }

    // Wait for greeting messages from all slaves
    for (int idx = 0; idx < this->nodeSet->numNodes; ++idx) {
        Node * targetNode = this->nodeSet->node[idx];
        this->log->Write(Log::MAJOR, "Master connecting to node %d", idx);
        targetNode->stream->Connect();
        MasterSlavePacket packet;
        targetNode->stream->Receive(reinterpret_cast<char*>(&packet), sizeof(packet));
        if (packet.checksum != CHECKSUM_VALUE)
            throw new Exception("Got malformed message from slave %d", idx);
        if (packet.type != MSG_GREETING)
            throw new Exception("Expected GREETING message from slave %d but got something else", idx);
        this->log->Write(Log::MAJOR, "Master received GREETING from node %d", idx);
    }

    // Send setup packets with node IDs
    for (int idx = 0; idx < this->nodeSet->numNodes; ++idx) {
        Node * targetNode = this->nodeSet->node[idx];
        MasterSlavePacket packet;
        packet.checksum = CHECKSUM_VALUE;
        packet.type = MSG_SETUP;
        packet.slaveIndex = idx;
        this->log->Write(Log::MINOR, "Master sending SETUP message to node %d", idx);
        targetNode->stream->Send(reinterpret_cast<char*>(&packet), sizeof(packet));
    }

    // Collect local join tables and build global union
    JoinExchangePacket globalTable;
    globalTable.joinCount = -1;
    for (int jid = 0; jid < DD::MAXJOINS; ++jid)
        globalTable.joinEntry[jid].streamID[0] = '\0';

    for (int idx = 0; idx < this->nodeSet->numNodes; ++idx) {
        Node * targetNode = this->nodeSet->node[idx];
        JoinExchangePacket localTable;
        this->log->Write(Log::MAJOR, "Master waiting for LOCAL_JOIN from node %d", idx);
        targetNode->stream->Receive(reinterpret_cast<char*>(&localTable), sizeof(localTable));
        if (localTable.checksum != CHECKSUM_VALUE)
            throw new Exception("Got malformed message from slave %d", idx);
        if (localTable.type != MSG_LOCAL_JOIN)
            throw new Exception("Expected LOCAL_JOIN from slave %d but got something else", idx);
        this->log->Write(Log::MAJOR, "Master received LOCAL_JOIN from node %d", idx);

        if (globalTable.joinCount < 0)
            globalTable.joinCount = localTable.joinCount;
        else if (globalTable.joinCount != localTable.joinCount)
            throw new Exception("Inconsistent numJoins values in LOCAL_JOIN messages (%d != %d)", globalTable.joinCount, localTable.joinCount);

        for (int jid = 0; jid < globalTable.joinCount; ++jid)
            if (localTable.joinEntry[jid].streamID[0] != '\0')
                strcpy(globalTable.joinEntry[jid].streamID, localTable.joinEntry[jid].streamID);
    }

    // Prepare and send global join table
    globalTable.checksum = CHECKSUM_VALUE;
    globalTable.type = MSG_GLOBAL_JOIN;
    for (int idx = 0; idx < this->nodeSet->numNodes; ++idx) {
        Node * targetNode = this->nodeSet->node[idx];
        this->log->Write(Log::MAJOR, "Master sending GLOBAL_JOIN to node %d", idx);
        targetNode->stream->Send(reinterpret_cast<char*>(&globalTable), sizeof(globalTable));
    }

    // Wait for all slaves to finish
    this->log->Write(Log::ALWAYS, "Master process has completed its tasks and is waiting for all slaves to terminate");
    for (int idx = 0; idx < this->nodeSet->numNodes; ++idx) {
        Node * targetNode = this->nodeSet->node[idx];
        pid_t finishedPID = waitpid(targetNode->remotePID, nullptr, 0);
        if (finishedPID != targetNode->remotePID)
            throw new Exception("Internal error: Unexpected return value from waitpid in MasterProces!");
        delete targetNode->stream;
        targetNode->stream = nullptr;
    }
    this->log->Write(Log::ALWAYS, "Master process observed termination of all slaves and is now exiting");
#endif
}

//------------------------------------------------------------------------------
static void *   lead_thread_func      (void *);
static void *   follow_thread_func    (void *);

void
DD::SlaveProcess (
    void
) {
#if defined (WIN32)
    throw new Exception("Remote execution is not supported on Microsoft Windows");
#else
    char * hostPID = GetHostnamePID();
    char threadLabel[strlen(hostPID) + 100];
    snprintf(threadLabel, sizeof(threadLabel), "%s slave", hostPID);
    this->log->RegisterThread(threadLabel);

    // Connect to master and send greeting
    this->log->Write(Log::ALWAYS, "Slave process connecting to master on \"%s\" and sending GREETING", this->flow->DH->slaveArg);
    Stream * masterLink = new Stream(Stream::TCPIP, this->flow->DH->slaveArg, &handleSlaveStreamError, &logSlaveStreamEvent);
    MasterSlavePacket packet;
    packet.checksum = CHECKSUM_VALUE;
    packet.type = MSG_GREETING;
    masterLink->Send(reinterpret_cast<char*>(&packet), sizeof(packet));

    // Receive setup info
    this->log->Write(Log::MAJOR, "Slave sent GREETING, now awaiting SETUP message");
    masterLink->Receive(reinterpret_cast<char*>(&packet), sizeof(packet));
    if (packet.checksum != CHECKSUM_VALUE)
        throw new Exception("Got malformed message from master");
    if (packet.type != MSG_SETUP)
        throw new Exception("Expected SETUP message from master but got something else");
    this->nodeID = packet.slaveIndex;
    sprintf(threadLabel, "%s slave:%d", hostPID, this->nodeID);
    this->log->RenameThread(threadLabel);
    this->log->Write(Log::MAJOR, "Slave received SETUP message");
    delete [] hostPID;

    this->role = ROLE_SLAVE;
    this->CreateFixedEntities();
    this->ReadConfig();

    // Setup minimum barrier iterator
    this->minbarCat = new Category(this, DD::minBarCategoryName);
    this->minbar = new Iterator(this, DD::minBarCategoryName, nullptr, this->minbarCat, &MinimumBarrier_Function);
    this->minbar->Place(this->nodeSet->node[0]);
    this->minbar->Detach();
    this->mapperList->Rewind();
    Iterator * mapper;
    while ((mapper = static_cast<Iterator*>(this->mapperList->Next())) != nullptr)
        this->JoinIterators(mapper, this->minbar);

    // Analyze join types and prepare local join exchange data
    JoinExchangePacket localJoinData;
    localJoinData.checksum = CHECKSUM_VALUE;
    localJoinData.type = MSG_LOCAL_JOIN;
    localJoinData.joinCount = this->numJoins;
    for (int jid = 0; jid < DD::MAXJOINS; ++jid)
        localJoinData.joinEntry[jid].streamID[0] = '\0';

    for (int jid = 0; jid < this->numJoins; ++jid) {
        Iterator * iter1 = this->iterator[this->join[jid].iter1].iterator;
        Iterator * iter2 = this->iterator[this->join[jid].iter2].iterator;
        if (iter1->node->nodeID == this->nodeID) {
            if (iter2->node->nodeID == this->nodeID)
                this->join[jid].local = true;
            else {
                if ((this->log->GetMask() & Log::DD_SENDRECV) == 0)
                    this->join[jid].stream = new Stream(Stream::TCPIP, &handleJoinStreamError);
                else
                    this->join[jid].stream = new Stream(Stream::TCPIP, &handleJoinStreamError, &logJoinStreamEvent);
                strcpy(localJoinData.joinEntry[jid].streamID, this->join[jid].stream->LocalHandle());
                this->join[jid].leader = true;
                this->log->Write(Log::CONFIG_MINOR, "Slave leading join %d; handle is \"%s\"", jid, localJoinData.joinEntry[jid].streamID);
            }
        } else if (iter2->node->nodeID == this->nodeID)
            this->join[jid].follower = true;
    }

    // Exchange local join data with master
    masterLink->Send(reinterpret_cast<char*>(&localJoinData), sizeof(localJoinData));
    this->log->Write(Log::MAJOR, "Slave sent local join exchange table; waiting for global union");
    memset(&localJoinData, 0, sizeof(localJoinData));
    masterLink->Receive(reinterpret_cast<char*>(&localJoinData), sizeof(localJoinData));
    if (localJoinData.checksum != CHECKSUM_VALUE)
        throw new Exception("Got malformed message from master");
    if (localJoinData.type != MSG_GLOBAL_JOIN)
        throw new Exception("Expected GLOBAL_JOIN message from master but got something else");
    if (localJoinData.joinCount != this->numJoins)
        throw new Exception("Inconsistent numJoins value in GLOBAL_JOIN message");
    delete masterLink;

    // Start helper threads for leader/follower roles
    this->leadFollowSync = new Semaphore("leadFollow", 0, this->log);
    for (int jid = 0; jid < this->numJoins; ++jid) {
        if (this->join[jid].leader) {
            if (pthread_create(&this->join[jid].thid, nullptr, &lead_thread_func, reinterpret_cast<void*>(jid)) != 0)
                throw new Exception("Pthreads error: Cannot create leader thread %s", strerror(errno));
            this->leadFollowSync->PSem();
        }
    }

    for (int jid = 0; jid < this->numJoins; ++jid) {
        if (this->join[jid].follower) {
            if (localJoinData.joinEntry[jid].streamID[0] == '\0')
                throw new Exception("Slot %d in GLOBAL_JOIN message is empty", jid);
            strcpy(this->join[jid].handle, localJoinData.joinEntry[jid].streamID);
            if (pthread_create(&this->join[jid].thid, nullptr, &follow_thread_func, reinterpret_cast<void*>(jid)) != 0)
                throw new Exception("Pthreads error: Cannot create follower thread %s", strerror(errno));
        }
    }

    // Cleanup and wait for threads
    delete this->leadFollowSync;
    this->leadFollowSync = nullptr;
    for (int jid = 0; jid < this->numJoins; ++jid) {
        if (this->join[jid].leader || this->join[jid].follower) {
            this->log->Write(Log::CONFIG_MINOR, "Waiting for termination of join %d %s thread", jid, this->join[jid].leader ? "leader" : "follower");
            if (pthread_join(this->join[jid].thid, nullptr) != 0)
                throw new Exception("Pthreads error: Cannot join with thread, errno=%d", errno);
        }
    }
    this->log->Write(Log::CONFIG_MINOR, "All slave join threads have terminated");

    // Build lists of categories and iterators
    this->categoryList = new List();
    for (int catid = 0; catid < this->numCategories; ++catid)
        this->categoryList->Append(static_cast<void*>(this->category[catid].category));

    this->iteratorList = new List();
    for (int iterid = 0; iterid < this->numIterators; ++iterid)
        this->iteratorList->Append(static_cast<void*>(this->iterator[iterid].iterator));

    this->PrintJoinTable();
    this->InitializeLocalMessageBuffers();
    this->StartLocalIteratorThreads();
    if (this->mappersOnThisNode > 0)
        SetupMinimumBarrier();
    this->RunSimulation();
    this->log->Write(Log::ALWAYS, "Slave is terminating");
#endif
}

//------------------------------------------------------------------------------
static void *
lead_thread_func (
    void * arg
) {
    int jid = static_cast<int>(reinterpret_cast<long>(arg));  // index in join table
    DD * dd = FLOW2D3D->dd;
    dd->log->Write(Log::CONFIG_MINOR, "Leader thread for join %d starting", jid);
    try {
        dd->leadFollowSync->VSem();
        dd->join[jid].stream->Connect();
    } catch (Exception * ex) {
        dd->log->Write(Log::ALWAYS, "Exception in leader thread for join %d: %s", jid, ex->message);
        exit(1);
    }
    dd->log->Write(Log::CONFIG_MINOR, "Leader thread for join %d terminating", jid);
    return nullptr;
}

static void *
follow_thread_func (
    void * arg
) {
    int jid = static_cast<int>(reinterpret_cast<long>(arg));  // index in join table
    DD * dd = FLOW2D3D->dd;
    dd->log->Write(Log::CONFIG_MINOR, "Follower thread for join %d starting; handle = \"%s\"", jid, dd->join[jid].handle);
    try {
        if ((dd->log->GetMask() & Log::DD_SENDRECV) == 0)
            dd->join[jid].stream = new Stream(Stream::TCPIP, dd->join[jid].handle, &handleJoinStreamError);
        else
            dd->join[jid].stream = new Stream(Stream::TCPIP, dd->join[jid].handle, &handleJoinStreamError, &logJoinStreamEvent);
    } catch (Exception * ex) {
        dd->log->Write(Log::ALWAYS, "Exception in follower thread for join %d: %s", jid, ex->message);
        exit(1);
    }
    dd->log->Write(Log::CONFIG_MINOR, "Follower thread for join %d terminating", jid);
    return nullptr;
}

#include "Enemy.h"
#include <Gorgon/Filesystem.h>
#include <Gorgon/Graphics/Bitmap.h>
#include <Gorgon/Graphics/TextureAnimation.h>

namespace Assets {

    // Load a single asteroid image.
    // File names on disk are astroid1.png, astroid2.png, astroid3.png,
    // but internal type indices start at 0, so we offset by +1 when constructing filenames.
    void Astroid::Load(int idx) {
        this->type = idx;
        std::string basepath = "Resources/astroid" + std::to_string(idx + 1);

        if(Gorgon::Filesystem::IsFile(basepath + ".png")) {
            // Load as static image
            Gorgon::Graphics::Bitmap bitmap;
            bitmap.Import(basepath + ".png");
            bitmap.Prepare();
            image.SetAnimation(std::move(bitmap));
        }
        else {
            // Load animated sequence frame-by-frame
            Gorgon::Graphics::BitmapAnimationProvider animation;
            for(int frameNum = 1; ; ++frameNum) {
                std::string filepath = basepath + "_" + std::to_string(frameNum) + ".png";
                if(!Gorgon::Filesystem::IsFile(filepath)) break;

                Gorgon::Graphics::Bitmap frameBmp;
                frameBmp.Import(filepath);
                animation.Add(std::move(frameBmp), 250);
            }
            animation.Prepare();
            image.SetAnimation(std::move(animation));
        }
    }

    // Upload the asteroid's current image to GPU
    void Astroid::Prepare() {
        auto &animRef = image.GetAnimation();

        if(auto *singleBmp = dynamic_cast<Gorgon::Graphics::Bitmap*>(&animRef)) {
            singleBmp->Prepare();
        }
        else if(auto *animPtr = dynamic_cast<Gorgon::Graphics::BitmapAnimationProvider*>(&animRef)) {
            animPtr->Prepare();
        }
    }

    // Convenience: load all asteroid variants in bulk
    void Astroid::LoadAll() {
        for(int i = 0; i < types; ++i) {
            astroids.AddNew().Load(i);
        }
    }

    // Convenience: prepare (upload) all loaded variants
    void Astroid::PrepareAll() {
        for(int i = 0; i < types; ++i) {
            astroids[i].Prepare();
        }
    }

    // Static member definition — required in exactly one .cpp file
    Gorgon::Containers::Collection<Astroid> Astroid::astroids;
}

