/// Reset internal state for a fresh SSA update session
void MachineSSAUpdater::Initialize(const TargetRegisterClass *RC) {
  if (!AV)
    AV = new BlockToRegMap();
  else
    getStoredValues(AV).clear();
  VRC = RC;
}

/// Overload: infer register class from an existing virtual register
void MachineSSAUpdater::Initialize(Register reg) {
  Initialize(MRI->getRegClass(reg));
}

/// Check whether a value is already known for a given block
bool MachineSSAUpdater::HasValueForBlock(MachineBasicBlock *BB) const {
  return getStoredValues(AV).find(BB) != getStoredValues(AV).end();
}

/// Record that a specific register value is available at end of BB
void MachineSSAUpdater::AddAvailableValue(MachineBasicBlock *BB, Register val) {
  getStoredValues(AV)[BB] = val;
}

/// Get value live at end of BB (public entry point)
Register MachineSSAUpdater::GetValueAtEndOfBlock(MachineBasicBlock *BB) {
  return GetValueAtEndOfBlockInternal(BB);
}

// Helper: look for an identical PHI node already present in BB
static Register FindMatchingPHI(
    MachineBasicBlock *BB,
    SmallVectorImpl<std::pair<MachineBasicBlock *, Register>> &predValues) {
  if (BB->empty())
    return Register();

  auto iter = BB->begin();
  if (!iter->isPHI())
    return Register();

  BlockToRegMap cached;
  for (size_t i = 0, n = predValues.size(); i != n; ++i)
    cached[predValues[i].first] = predValues[i].second;

  while (iter != BB->end() && iter->isPHI()) {
    bool match = true;
    for (unsigned idx = 1, numOps = iter->getNumOperands(); idx != numOps; idx += 2) {
      Register srcReg = iter->getOperand(idx).getReg();
      MachineBasicBlock *srcBB = iter->getOperand(idx + 1).getMBB();
      if (cached[srcBB] != srcReg) {
        match = false;
        break;
      }
    }
    if (match)
      return iter->getOperand(0).getReg();
    ++iter;
  }
  return Register();
}

// Helper: create a new instruction defining a virtual register
static MachineInstrBuilder CreateNewDef(
    unsigned opcode,
    MachineBasicBlock *BB,
    MachineBasicBlock::iterator pos,
    const TargetRegisterClass *RC,
    MachineRegisterInfo *regInfo,
    const TargetInstrInfo *tii) {
  Register newVR = regInfo->createVirtualRegister(RC);
  return BuildMI(*BB, pos, DebugLoc(), tii->get(opcode), newVR);
}

/// Get value live in middle of BB — may insert PHIs or IMPLICIT_DEF as needed
Register MachineSSAUpdater::GetValueInMiddleOfBlock(
    MachineBasicBlock *BB,
    bool onlyExisting) {
  // If no local definition, delegate to end-of-block logic
  if (!HasValueForBlock(BB))
    return GetValueAtEndOfBlockInternal(BB, onlyExisting);

  // No predecessors → undef
  if (BB->pred_empty()) {
    if (onlyExisting)
      return Register();
    MachineInstr *defInst = CreateNewDef(TargetOpcode::IMPLICIT_DEF,
                                         BB, BB->getFirstTerminator(),
                                         VRC, MRI, TII);
    return defInst->getOperand(0).getReg();
  }

  // Collect values from all predecessors
  SmallVector<std::pair<MachineBasicBlock*, Register>, 8> predList;
  Register singularVal;
  bool first = true;

  for (MachineBasicBlock *pred : BB->predecessors()) {
    Register val = GetValueAtEndOfBlockInternal(pred, onlyExisting);
    predList.emplace_back(pred, val);
    if (first) {
      singularVal = val;
      first = false;
    } else if (val != singularVal) {
      singularVal = Register();
    }
  }

  // If all preds supply same value, reuse it
  if (singularVal)
    return singularVal;

  // Try to reuse existing PHI
  Register reused = FindMatchingPHI(BB, predList);
  if (reused)
    return reused;

  // If we can't insert new instructions, give up
  if (onlyExisting)
    return Register();

  // Insert new PHI
  MachineBasicBlock::iterator loc = BB->empty() ? BB->end() : BB->begin();
  MachineInstrBuilder phiBuilder = CreateNewDef(TargetOpcode::PHI,
                                                BB, loc, VRC, MRI, TII);

  // Populate PHI operands
  for (auto &p : predList)
    phiBuilder.addReg(p.second).addMBB(p.first);

  // Try constant folding
  if (unsigned constVal = phiBuilder->isConstantValuePHI()) {
    phiBuilder->eraseFromParent();
    return constVal;
  }

  // Report newly inserted PHI if requested
  if (InsertedPHIs)
    InsertedPHIs->push_back(phiBuilder);

  LLVM_DEBUG(dbgs() << "  Inserted PHI: " << *phiBuilder << "\n");
  return phiBuilder.getReg(0);
}

// Helper: find which predecessor corresponds to a PHI operand
static MachineBasicBlock *FindPredFromPHIOperand(
    const MachineInstr *phi,
    MachineOperand *op) {
  for (unsigned i = 1, n = phi->getNumOperands(); i != n; i += 2) {
    if (&phi->getOperand(i) == op)
      return phi->getOperand(i + 1).getMBB();
  }
  llvm_unreachable("Failed to locate PHI predecessor");
}

// Rewrite a use operand to refer to the correct SSA value
void MachineSSAUpdater::RewriteUse(MachineOperand &useOp) {
  MachineInstr *user = useOp.getParent();
  Register newReg;

  if (user->isPHI()) {
    MachineBasicBlock *source = FindPredFromPHIOperand(user, &useOp);
    newReg = GetValueAtEndOfBlockInternal(source);
  } else {
    newReg = GetValueInMiddleOfBlock(user->getParent());
  }

  useOp.setReg(newReg);
}

namespace llvm {

// Traits for generic SSAUpdaterImpl template
template<>
class SSAUpdaterTraits<MachineSSAUpdater> {
public:
  using BlockType = MachineBasicBlock;
  using ValueType = Register;
  using PhiInstr = MachineInstr;
  using SuccIter = MachineBasicBlock::succ_iterator;

  static SuccIter succ_begin(BlockType *BB) { return BB->succ_begin(); }
  static SuccIter succ_end(BlockType *BB) { return BB->succ_end(); }

  // Iterator over PHI operands
  class PhiOperandIterator {
  private:
    MachineInstr *PHI;
    unsigned index;

  public:
    explicit PhiOperandIterator(MachineInstr *P) : PHI(P), index(1) {}
    PhiOperandIterator(MachineInstr *P, bool) : PHI(P), index(PHI->getNumOperands()) {}

    PhiOperandIterator &operator++() { index += 2; return *this; }
    bool operator==(const PhiOperandIterator &other) const { return index == other.index; }
    bool operator!=(const PhiOperandIterator &other) const { return !(*this == other); }

    unsigned getIncomingValue() const { return PHI->getOperand(index).getReg(); }
    MachineBasicBlock *getIncomingBlock() const {
      return PHI->getOperand(index + 1).getMBB();
    }
  };

  static PhiOperandIterator phi_begin(PhiInstr *P) { return PhiOperandIterator(P); }
  static PhiOperandIterator phi_end(PhiInstr *P) { return PhiOperandIterator(P, true); }

  static void getPredecessors(BlockType *BB,
                              SmallVectorImpl<BlockType*> *out) {
    append_range(*out, BB->predecessors());
  }

  static Register getUndefValue(BlockType *BB, MachineSSAUpdater *updater) {
    MachineInstr *def = CreateNewDef(TargetOpcode::IMPLICIT_DEF,
                                     BB, BB->getFirstNonPHI(),
                                     updater->VRC, updater->MRI,
                                     updater->TII);
    return def->getOperand(0).getReg();
  }

  static Register makeEmptyPhi(BlockType *BB, unsigned /*numPreds*/,
                               MachineSSAUpdater *updater) {
    MachineBasicBlock::iterator pos = BB->empty() ? BB->end() : BB->begin();
    MachineInstr *phi = CreateNewDef(TargetOpcode::PHI, BB, pos,
                                     updater->VRC, updater->MRI,
                                     updater->TII);
    return phi->getOperand(0).getReg();
  }

  static void addPhiOperand(PhiInstr *phi, Register val, BlockType *pred) {
    BuildMI(*pred->getParent(), phi, DebugLoc(), pred->getParent()->getInstrInfo()->get(TargetOpcode::PHI))
        .addReg(val).addMBB(pred);
  }

  static PhiInstr *isPhiInstr(MachineInstr *I) {
    return I && I->isPHI() ? I : nullptr;
  }

  static PhiInstr *valueIsPhi(Register val, MachineSSAUpdater *updater) {
    return isPhiInstr(updater->MRI->getVRegDef(val));
  }

  static PhiInstr *valueIsNewPhi(Register val, MachineSSAUpdater *updater) {
    PhiInstr *phi = valueIsPhi(val, updater);
    return (phi && phi->getNumOperands() <= 1) ? phi : nullptr;
  }

  static Register getPhiResult(PhiInstr *phi) {
    return phi->getOperand(0).getReg();
  }
};

} // end namespace llvm

// Internal implementation: retrieve or construct SSA value at end of BB
Register
MachineSSAUpdater::GetValueAtEndOfBlockInternal(MachineBasicBlock *BB,
                                                bool onlyExisting) {
  BlockToRegMap &stored = getStoredValues(AV);
  Register existing = stored.lookup(BB);
  if (existing || onlyExisting)
    return existing;

  SSAUpdaterImpl<MachineSSAUpdater> impl(this, &stored, InsertedPHIs);
  return impl.GetValue(BB);
}

#include <iostream>
#include <vector>
using namespace std;

class Solution {
public:
    void generateSubarrays(vector<int>& inputArray, vector<int>& currentSubset, int index, vector<vector<int>>& allSubsets) {
        if (index == inputArray.size()) {
            allSubsets.push_back(currentSubset);
            return;
        }

        // Include the current element in the subset
        currentSubset.push_back(inputArray[index]);
        generateSubarrays(inputArray, currentSubset, index + 1, allSubsets);

        // Exclude the current element from the subset
        currentSubset.pop_back();
        generateSubarrays(inputArray, currentSubset, index + 1, allSubsets);
    }

    vector<vector<int>> subsets(vector<int>& nums) {
        vector<vector<int>> resultSubsets;

        vector<int> tempSubset;

        generateSubarrays(nums, tempSubset, 0, resultSubsets);

        return resultSubsets;
    }
};

int main() {
    Solution solver;
    vector<int> elements = {1, 2, 3};
    vector<vector<int>> output = solver.subsets(elements);

    for (int i = 0; i < output.size(); i++) {
        cout << "{ ";
        for (int j = 0; j < output[i].size(); j++) {
            cout << output[i][j] << " ";
        }
        cout << "}" << endl;
    }

    return 0;
}

