// Function that consumes an integer value (annotated as sink)
void drain([[clang::annotate("psr.sink")]] int value) {}

// External function returning a random integer
extern int generateRandom();

// Function that processes input x with a loop
int process(int input) {
  while (generateRandom()) {
    input = 0;
    break;
  }
  return input;
}

// Main entry point with annotated source parameter
int main([[clang::annotate("psr.source")]] int count, char *arguments[]) {
  int result = process(count);
  // Directly pass to drain without additional handling => potential leak
  drain(result);
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int size, threshold;
    scanf("%d%d", &size, &threshold);

    vector<bool> processed(size + 1, false);
    int count = 0;

    for (int idx = 1; idx <= size; ++idx) {
        if (processed[idx]) continue;

        count++;

        // Reset memory state
        printf("R\n");
        fflush(stdout);

        // Query current pivot element
        printf("? %d\n", idx);
        fflush(stdout);

        char response;
        scanf(" %c", &response);  // ignore response

        // Check remaining elements against current pivot
        for (int jdx = idx + 1; jdx <= size; ++jdx) {
            if (processed[jdx]) continue;

            printf("? %d\n", jdx);
            fflush(stdout);

            scanf(" %c", &response);
            if (response == 'Y') {
                processed[jdx] = true;
            }
        }

        processed[idx] = true;
    }

    printf("! %d\n", count);
    fflush(stdout);

    return 0;
}

