bool FDisplayClusterVrpnKeyboardInputDevice::Initialize()
{
	// Create VRPN device interface
	DeviceImplementation.Reset(new vrpn_Button_Remote(TCHAR_TO_UTF8(*NetworkAddress)));

	// Attach event callback
	if (DeviceImplementation->register_change_handler(this, &FDisplayClusterVrpnKeyboardInputDevice::OnKeyboardEvent) != 0)
	{
		UE_LOG(LogDisplayClusterInputVRPN, Error, TEXT("%s - failed to register VRPN event handler"), *ToString());
		return false;
	}

	// Complete base setup
	return FDisplayClusterVrpnKeyboardInputDataHolder::Initialize();
}

////////////////////////////////////////////////////////////////////////////////////////////////
// FDisplayClusterVrpnKeyboardInputDevice
////////////////////////////////////////////////////////////////////////////////////////////////

void VRPN_CALLBACK FDisplayClusterVrpnKeyboardInputDevice::OnKeyboardEvent(void *Context, vrpn_BUTTONCB const* EventData)
{
	auto DeviceInstance = reinterpret_cast<FDisplayClusterVrpnKeyboardInputDevice*>(Context);

	auto Entry = DeviceInstance->DeviceData.Find(EventData->button);
	if (!Entry)
	{
		Entry = &DeviceInstance->DeviceData.Add(EventData->button);
		// Initialize old state explicitly
		Entry->PreviousButtonState = false;
	}

	//@note: A button may transition multiple times within a single update cycle (e.g., 0→1→0).
	//       In such cases, only the final state is recorded, potentially missing intermediate changes.
	//       This is acceptable under normal usage conditions where rapid toggling does not occur.
	//       Such behavior usually indicates contact bounce or hardware noise rather than intentional input.
	//
	// Convert integer state from VRPN to boolean representation:
	// VRPN uses int32 but only two values are meaningful: 0 (released), 1 (pressed).
	Entry->CurrentButtonState = (EventData->state != 0);

	UE_LOG(LogDisplayClusterInputVRPN, VeryVerbose, TEXT("Keyboard %s:%d - %d"), *DeviceInstance->GetId(), EventData->button, EventData->state);
}

