namespace {
    struct CueMarker {
        CueMarker(int samplePos, int markerId) : mSample(samplePos), mIdentifier(markerId) {}
        // total size: 0x8
        int mSample; // offset 0x0, size 0x4
        int mIdentifier; // offset 0x4, size 0x4
    };

    struct TextLabel {
        TextLabel(const String &text, int idVal) : mText(text), mIdentifier(idVal) {}
        // total size: 0x10
        class String mText; // offset 0x0, size 0xC
        int mIdentifier; // offset 0xC, size 0x4
    };

    bool SortByPosition(const CueMarker &a, const CueMarker &b) {
        return a.mSample < b.mSample;
    }
}

WaveFile::WaveFile(BinStream &stream) : mMarkers(), mRiffList(stream, true) {
    ParseFormat();
    ParseMarkers();
    ParseSampleCount();
}

WaveFile::~WaveFile() {}

void WaveFile::ParseFormat() {
    mRiffList.Reset();
    ChunkHeader *fmtChunk = (ChunkHeader *)mRiffList.Next(kWaveFormatChunkID);
    MILO_ASSERT(fmtChunk != null, 0x6e);

    IDataChunk fmtData(mRiffList);
    fmtData >> mFormat;
    fmtData >> mNumChannels;
    fmtData >> mSamplesPerSec;
    fmtData >> mAvgBytesPerSec;
    fmtData >> mBlockAlign;
    fmtData >> mBitsPerSample;

    MILO_ASSERT(mAvgBytesPerSec == mSamplesPerSec * mBlockAlign, 0x78);
    MILO_ASSERT(mBlockAlign == mNumChannels * mBitsPerSample / 8, 0x79);
}

void WaveFile::ParseMarkers() {
    std::vector<CueMarker> cueList;
    std::vector<TextLabel> labelList;

    mRiffList.Reset();
    if (!mRiffList.Next(kWaveCueChunkID))
        return;

    int numCues, idx;
    {
        IDataChunk cueChunk(mRiffList);
        cueChunk >> numCues;
        for (idx = 0; idx < numCues; idx++) {
            int idVal, samplePos;
            cueChunk >> idVal >> samplePos;
            cueList.push_back(CueMarker(samplePos, idVal));
            cueChunk.Seek(0x10, BinStream::kSeekCur);
        }
    }

    if (numCues == 0)
        return;

    mRiffList.Reset();
    if (mRiffList.Next(kWaveAdditionalChunkID)) {
        IListChunk listChunk(mRiffList);
        for (idx = 0; idx < numCues; idx++) {
            listChunk.Next(kWaveLabelChunkID);
            IDataChunk dataChunk(listChunk);
            int textLen = dataChunk.Header()->Length() - 4;
            int labelId;
            dataChunk >> labelId;

            String labelStr;
            labelStr.resize(textLen);
            dataChunk.Read((char *)labelStr.c_str(), textLen);

            labelList.push_back(TextLabel(labelStr, labelId));
        }
    }

    std::sort(cueList.begin(), cueList.end(), SortByPosition);

    for (idx = 0; idx < numCues; idx++) {
        String foundLabel;
        for (int k = 0; k < labelList.size(); k++) {
            if (labelList[k].mIdentifier == cueList[idx].mIdentifier) {
                foundLabel = labelList[k].mText;
                break;
            }
        }
        mMarkers.push_back(WaveFileMarker(cueList[idx].mSample, cueList[idx].mIdentifier, foundLabel));
    }
}

void WaveFile::ParseSampleCount() {
    mRiffList.Reset();
    ChunkHeader *dataChunk = (ChunkHeader *)mRiffList.Next(kWaveDataChunkID);
    MILO_ASSERT(dataChunk != null, 0xEA);

    mNumSamples = dataChunk->Length() / mBlockAlign;
}

IListChunk &WaveFile::PrepareToProvideData() {
    mRiffList.Reset();
    ChunkHeader *dataChunk = (ChunkHeader *)mRiffList.Next(kWaveDataChunkID);
    MILO_ASSERT(dataChunk != null, 0x17e);
    return mRiffList;
}

WaveFileData::WaveFileData(WaveFile &wf)
    : IDataChunk(wf.PrepareToProvideData()), mWaveFile(wf) {}

WaveFileData::~WaveFileData() {}

