#include <errno.h>
#include <sys/ipc.h>
#include <sys/shm.h>

//------------------------------------------------------------------------------
//  Region and context descriptor type definitions
//  The context descriptor resides in a dedicated shared memory page,
//  safeguarded by a semaphore, and holds lists for regions and pages.
//  Two region categories exist: active regions for user data and void regions,
//  representing unused portions of mapped pages available for future allocations.
//  Region chains are maintained in ascending order based on name (data) or size (voids).
//  The page table records the dimensions and identifiers of all shared memory
//  segments tied to the context (excluding the context descriptor itself),
//  primarily used during context teardown.
//  Additionally, a per-process mapping table stores the local virtual addresses
//  of each page. This table resides within the "Contexts" array, indexed by
//  the top-level ESM API functions.
#define NULL_IDX (-1)        // Represents an invalid index
typedef struct RD_st {
    char    label [ESM_MAX_NAME];   // region identifier
    int     offset;     // displacement from start of page to region
    int     pgindex;        // page index [0..ESM_MAX_PAGES]
    int     extent;       // actual size in bytes
    int     next_link;           // forward linked-list pointer
    int     prev_link;           // backward linked-list pointer
    }
    RD;
typedef struct PD_st {
    int     shmid;      // UNIX shared memory segment identifier
    int     total_size;       // actual size in bytes (1024 * cd->pagesize or larger)
    }
    PD;
typedef struct CD_st {
    int     signature;          // marker for utilities listing ESM contexts on host
    int     ctx_id;             // unique context identifier
    int     sema_id;            // mutual exclusion semaphore for this context
    // Region descriptor chain
    int     num_regions;        // count of allocated regions in context
    RD      region_table [ESM_MAX_REGIONS];
    int     rd_head;         // head of allocated region descriptors (sorted by name)
    int     rd_void_head;        // head of empty regions (sorted by size)
    int     rd_free_head;         // head of free region descriptors (list)
    // Page list
    int     num_pages;         // number of pages in context
    PD      page_table [ESM_MAX_PAGES];  // page descriptor table
    int     page_block_size;       // shared memory page size in 1K blocks
    }
    CD;

//------------------------------------------------------------------------------
//  Semaphore operation macros.
static struct sembuf Psem = { 0, -1, 0 };
static struct sembuf Vsem = { 0,  1, 0 };
#define P(S,E)  { \
    if (semop ((S), &Psem, 1) != 0) { \
        SetError (thid, "Semaphore P-operation on %d fails: %s", (S), strerror (errno)); \
        return (E); \
        } \
    }
#define V(S,E)  { \
    if (semop ((S), &Vsem, 1) != 0) { \
        SetError (thid, "Semaphore V-operation on %d fails: %s", (S), strerror (errno)); \
        return (E); \
        } \
    }

//------------------------------------------------------------------------------
//  Macro functions
//  Detach a mapped shared memory segment
#define DETACH(I,E)  { \
    if (shmdt ((I))) { \
        SetError (thid, "Cannot detach shared memory segment: %s", strerror (errno)); \
        return (E); \
        } \
    }
//  Destroy a shared memory segment
#define DESTROY(I,E)  { \
    struct shmid_ds buf; \
    if (shmctl ((I), IPC_RMID, &buf) != 0) { \
        SetError (thid, "Cannot destroy shared memory segment: %s", strerror (errno)); \
        return (E); \
        } \
    }
//  Convert a relative address within a page (A) to an absolute address
//  given a page base address (B) in the local address space
#define LOCALADDRESS(B,A) ( \
    (void *)((char *)(B) + (long)(A)) \
    )

