    int *   head,
    const char *  name
    );
static int
FindHoleBySize (
    RD      regions[],
    int *   head,
    int     required_size
    );
static void
AddRegionToList (
    RD      regions[],
    int *   listhead,
    int     newreg
    );
static void
AddHoleToList (
    RD      regions[],
    int *   listhead,
    int     newreg
    );
static void
RemoveFromList (
    RD      regions[],
    int *   head,
    int     index
    );

//------------------------------------------------------------------------------
int
ESM_Shared_Create (
    int thid,
    int pagesize
    ) {
    // Allocate a slot in the per-process context table
    if (NumContexts >= ESM_MAX_CONTEXTS) {
        SetError (thid, "Too many contexts (%d) for process; ESM_Create fails", ESM_MAX_CONTEXTS);
        return 0;
        }
    int ci = NumContexts++;

    // Create a new context descriptor in shared memory for all processes
    int contextid = shmget (IPC_PRIVATE, sizeof (CD), IPC_CREAT | SHM_R | SHM_W);
    if (contextid < 0) {
        SetError (thid, "Cannot create context descriptor segment in ESM_Create: %s", strerror (errno));
        return 0;
        }

    // A context ID (= shared memeory segment ID) of zero is valid in Linux, but not a valid ESM context ID.
    // If we get a zero, create an additional segment and delete the first one.
    if (contextid == 0) {
        int alt_contextid = shmget (IPC_PRIVATE, sizeof (CD), IPC_CREAT | SHM_R | SHM_W);
        if (alt_contextid < 0) {
            SetError (thid, "Cannot create second non-zero context descriptor segment in ESM_Create: %s", strerror (errno));
            return 0;
            }
        DESTROY (contextid, ESM_ERROR);
        contextid = alt_contextid;
        }

    // Attach context descriptor to local address space (temporarily)
    CD * cd = (CD *) shmat (contextid, NULL, 0);
    if ((long) cd == -1) {
        SetError (thid, "Cannot attach context descriptor segment in ESM_Create: %s", strerror (errno));
        DESTROY (contextid, 0);
        return 0;
        }

    // Create a mutual exclusion semaphore for all processes
    int semid = semget (IPC_PRIVATE, 1, IPC_CREAT | SEM_A | SEM_R);
    if (semid < 0) {
        SetError (thid, "Cannot create context descriptor mutex semaphore in ESM_Create: %s", strerror (errno));
        DESTROY (contextid, 0);
        return 0;
        }

    // Initialize context descriptor
    cd->signature       = ESM_MAGIC;
    cd->ctx_id          = contextid;
    cd->page_block_size = pagesize;
    cd->num_pages       = 0;
    cd->sema_id         = semid;
    V (cd->sema_id, 0);

    // Initialize region table in context descriptor
    for (int i = 0 ; i < ESM_MAX_REGIONS ; i++) {
        RD * rd = &cd->region_table[i];
        memset ((void *) rd, 0, sizeof (RD));
        rd->prev_link = i-1;
        rd->next_link = i+1;
        }
    cd->num_regions = 0;
    cd->region_table[0].prev_link = NULL_IDX;
    cd->region_table[ESM_MAX_REGIONS-1].next_link = NULL_IDX;
    cd->rd_free_head = 0;
    cd->rd_head = NULL_IDX;
    cd->rd_void_head = NULL_IDX;

    // Initialize page table in context descriptor
    for (int pi = 0 ; pi < ESM_MAX_PAGES ; pi++) {
        PD * pd = &cd->page_table[pi];
        memset ((void *) pd, 0, sizeof (PD));
        Contexts[ci].pageaddr[pi] = NULL;
        }
    Contexts[ci].contextid = contextid;
    Contexts[ci].cd = cd;
    Contexts[ci].nattached = 0;
    return contextid;
}

int
ESM_Shared_Delete (
    int thid,
    int ci,
    int contextid
    ) {
    // If the context is not attached to the current process, attach it
    if (ci < 0) {
        ci = AttachContext (thid, contextid);
        if (ci < 0)
            return ESM_ERROR;
        }
    CD * cd = (CD *) Contexts[ci].cd;
    P (cd->sema_id, ESM_ERROR);

    // Destroy all data pages
    for (int pi = 0 ; pi < cd->num_pages ; pi++) {
        DETACH (Contexts[ci].pageaddr[pi], ESM_ERROR);
        DESTROY (cd->page_table[pi].shmid, ESM_ERROR);
        }

    // Destroy mutual exclusion semaphore
    if (semctl (cd->sema_id, 0, IPC_RMID) != 0) {
        SetError (thid, "Cannot remove semaphore (%d) associated with context descriptor (%d): %s",
                        cd->sema_id,
                contextid,
                strerror (errno)
                );
        return ESM_ERROR;
        }

    // Destroy context descriptor
    DETACH (cd, ESM_ERROR);
    DESTROY (contextid, ESM_ERROR);

    // Clear entry in local contexts table
    Contexts[ci].contextid = 0;
    Contexts[ci].cd = NULL;
    Contexts[ci].nattached = 0;
    return ESM_OK;
}

void *
ESM_Shared_Alloc (
    int     thid,
    int     ci,
    int     contextid,
    const char *  name,
    size_t  size
    ) {
    // If the context is not attached to the current process, attach it
    if (ci < 0) {
        ci = AttachContext (thid, contextid);
        if (ci < 0)
            return NULL;
        }

    // Check if the region already exists in the context.
    CD * cd = (CD *) Contexts[ci].cd;
    P (cd->sema_id, NULL);

    int reg = FindRegionByName (cd->region_table, &cd->rd_head, name);
    if (reg == NULL_IDX) {
        if (size <= 0) {
            V (cd->sema_id, NULL);
            return NULL;    // did not find region; no allocation, lookup only
            }
    }
    else {      // found region
        if (size == 0 || size == cd->region_table[reg].extent) {
            void * paddr;       // base address of page in local address space
            paddr = Contexts[ci].pageaddr[cd->region_table[reg].pgindex];
            if (paddr == NULL) {
                V (cd->sema_id, NULL);
                return NULL;
                }
            else {
                V (cd->sema_id, NULL);
                return LOCALADDRESS (paddr, cd->region_table[reg].offset);
                }
            }
        else {
            V (cd->sema_id, NULL);
            return NULL;
            }
        }

    // The region was not found. Find smallest void large enough to accommodate the region.
    int hole = FindHoleBySize (cd->region_table, &cd->rd_void_head, size);
    if (hole == NULL_IDX) {
        // No suitable void found. Make one
        if (cd->num_pages == ESM_MAX_PAGES) {
            SetError (thid, "Page limit has been reached; try increasing page size");
            V (cd->sema_id, NULL);
            return NULL;
            }
        hole = AcquireRegionDescriptor (cd->region_table, &cd->rd_free_head);
        if (hole == NULL_IDX) {
            SetError (thid, "Region descriptors have been exhausted; cannot make void");
            V (cd->sema_id, NULL);
            return NULL;
            }
        int pi = cd->num_pages++;
        cd->page_table[pi].total_size = max (size, 1024 * cd->page_block_size);
        cd->page_table[pi].shmid = shmget (IPC_PRIVATE, cd->page_table[pi].total_size, IPC_CREAT | SHM_R | SHM_W);
        if (cd->page_table[pi].shmid <= 0) {
            SetError (thid, "Cannot create new page in ESM_Alloc: %s", strerror (errno));
            cd->num_pages--;
            V (cd->sema_id, NULL);
            return NULL;
            }
        void * pageaddr = shmat (cd->page_table[pi].shmid, NULL, 0);
        if ((long) pageaddr == -1) {
            SetError (thid, "Cannot attach new page in ESM_Alloc: %s", strerror (errno));
            DESTROY (cd->page_table[pi].shmid, NULL);
            cd->num_pages--;
            V (cd->sema_id, NULL);
            return NULL;
            }
        Contexts[ci].pageaddr[pi] = pageaddr;
        Contexts[ci].nattached++;
        cd->region_table[hole].pgindex = pi;
        cd->region_table[hole].offset = 0;
        cd->region_table[hole].extent = cd->page_table[pi].total_size;
    }
    else
        RemoveFromList (cd->region_table, &cd->rd_void_head, hole);

    // At this point we have a suitable void.
    // Split it into a piece for the new region and a smaller void left over.
    int newreg = AcquireRegionDescriptor (cd->region_table, &cd->rd_free_head);
    if (newreg == NULL_IDX) {
        SetError (thid, "Region descriptors have been exhausted");
        V (cd->sema_id, NULL);
        return NULL;
        }

    strcpy (cd->region_table[newreg].label, name);
    cd->region_table[newreg].extent = size;
    cd->region_table[newreg].pgindex = cd->region_table[hole].pgindex;
    cd->region_table[newreg].offset = cd->region_table[hole].offset;
    AddRegionToList (cd->region_table, &cd->rd_head, newreg);
    cd->num_regions++;

    if ((cd->region_table[hole].extent -= size) > 0) {
        cd->region_table[hole].offset += size;
        AddHoleToList (cd->region_table, &cd->rd_void_head, hole);
    }
    else
        ReleaseRegionDescriptor (cd->region_table, &cd->rd_free_head, hole);

    // Convert relative offset in void to absolute address in local address space
    void * addr = LOCALADDRESS (
                    Contexts[ci].pageaddr[cd->region_table[newreg].pgindex],
                    cd->region_table[newreg].offset
                    );
    memset (addr, 0, size);
    V (cd->sema_id, NULL);
    return addr;
}

int
ESM_Shared_Free (
    int thid,
    int ci,
    int contextid,
    const char * name
    ) {
    // If the context is not attached to the current process, attach it
    if (ci < 0) {
        ci = AttachContext (thid, contextid);
        if (ci < 0)
            return ESM_ERROR;
        }

    CD * cd = (CD *) Contexts[ci].cd;
    P (cd->sema_id, ESM_ERROR);

    // Look for the region's descriptor
    int reg = FindRegionByName (cd->region_table, &cd->rd_head, name);
    if (reg == NULL_IDX) {
        SetError (thid, "Cannot find region \"%s\" in ESM_Free", name);
        V (cd->sema_id, ESM_ERROR);
        return ESM_ERROR;
        }

    // Found it. Move the region descriptor to the void list
    RemoveFromList (cd->region_table, &cd->rd_head, reg);
    memset ((void *) cd->region_table[reg].label, 0, ESM_MAX_NAME);
    AddHoleToList (cd->region_table, &cd->rd_void_head, reg);
    cd->num_regions--;

    // Coalesce the new void with any directly adjoining voids.
    // There can be at most two: one just before and one just after in the same page.
    // Look for voids directly after the new void
    for (int r = cd->rd_void_head ; r != NULL_IDX ; r = cd->region_table[r].next_link) {
        if (cd->region_table[r].pgindex != cd->region_table[reg].pgindex)
            continue;
        if (cd->region_table[reg].offset + cd->region_table[reg].extent != cd->region_table[r].offset)
            continue;
        // Make the new void larger by increasing its size and remove the old void
        cd->region_table[reg].extent += cd->region_table[r].extent;
        RemoveFromList (cd->region_table, &cd->rd_void_head, r);
        RemoveFromList (cd->region_table, &cd->rd_void_head, reg);
        ReleaseRegionDescriptor (cd->region_table, &cd->rd_free_head, r);
        AddHoleToList (cd->region_table, &cd->rd_void_head, reg);
    }

    // Look for voids directly before the new void
    for (int r = cd->rd_void_head ; r != NULL_IDX ; r = cd->region_table[r].next_link) {
        if (cd->region_table[r].pgindex != cd->region_table[reg].pgindex)
            continue;
        if (cd->region_table[r].offset + cd->region_table[r].extent != cd->region_table[reg].offset)
            continue;
        // Make the old void larger by increasing its size and remove the new void
        cd->region_table[r].extent += cd->region_table[reg].extent;
        RemoveFromList (cd->region_table, &cd->rd_void_head, r);
        RemoveFromList (cd->region_table, &cd->rd_void_head, reg);
        ReleaseRegionDescriptor (cd->region_table, &cd->rd_free_head, reg);
        AddHoleToList (cd->region_table, &cd->rd_void_head, r);
    }

    V (cd->sema_id, ESM_ERROR);
    return ESM_OK;
}

