//------------------------------------------------------------------------------
//  Internal functions
static int
AttachContext (
    int     thid,
    int     ctx_id
    ) {
    // Map a context descriptor and all of its pages to the address space
    // of the local process and return an index of a slot in the local
    // context table containing the mapped addresses.
    if (NumContexts >= ESM_MAX_CONTEXTS) {
        SetError (thid, "Too many contexts (%d) for process; Cannot attach context", ESM_MAX_CONTEXTS);
        return -1;
        }
    int ci = NumContexts++;
    Contexts[ci].contextid = ctx_id;
    Contexts[ci].nattached = 0;

    // Attach context descriptor
    Contexts[ci].cd = shmat (ctx_id, NULL, 0);
    if ((long) Contexts[ci].cd == -1) {
        SetError (thid, "Cannot attach context descriptor to process: %s", strerror (errno));
        return -1;
        }

    // Attach all pages listed in the context descriptor
    CD * cd = (CD *) Contexts[ci].cd;
    for (int pi = 0 ; pi < cd->num_pages ; pi++) {
        Contexts[ci].pageaddr[pi] = shmat (cd->page_table[pi].shmid, NULL, 0);
        if ((long) Contexts[ci].pageaddr[pi] == -1) {
            SetError (thid, "Cannot attach context page to process: %s", strerror (errno));
            return -1;
            }
        Contexts[ci].nattached++;
    }
    return ci;
}

//------------------------------------------------------------------------------
//  Functions to manage region lists
static int
AcquireRegionDescriptor (
    RD      regions[],
    int *   freehead
    ) {
    // Peel off an empty region descriptor from the free list and return its index
    int reg = *freehead;
    if (reg == NULL_IDX)
        return NULL_IDX;   // no more empty descriptors
    *freehead = regions[reg].next_link;
    if (*freehead != NULL_IDX)
        regions[*freehead].prev_link = NULL_IDX;
    regions[reg].prev_link = NULL_IDX;
    regions[reg].next_link = NULL_IDX;
    return reg;
}

static void
ReleaseRegionDescriptor (
    RD      regions[],
    int *   freehead,
    int     index
    ) {
    // Put a cleared region descriptor at the head of a list (the free list)
    memset ((void *) &regions[index], 0, sizeof (RD));
    regions[index].prev_link = NULL_IDX;
    regions[index].next_link = *freehead;
    *freehead = index;
}

static int
FindRegionByName (
    RD      regions[],
    int *   head,
    const char *  name
    ) {
    // Search for a region with the given name in the ordered list of regions
    int reg = *head;
    while (reg != NULL_IDX) {
        if (strcmp (regions[reg].label, name) == 0)
            break;
        reg = regions[reg].next_link;
    }
    return reg;
}

static int
FindHoleBySize (
    RD      regions[],
    int *   head,
    int     required_size
    ) {
    // Search for the smallest void large enough to accomodate the requested size.
    // The void list is ordered by size (ascending).
    int reg = *head;
    while (reg != NULL_IDX) {
        if (regions[reg].extent >= required_size)
            break;
        reg = regions[reg].next_link;
    }
    return reg;
}

static void
AddRegionToList (
    RD      regions[],
    int *   listhead,
    int     newreg
    ) {
    // If the region list is empty, make the new descriptor the first and last element
    if (*listhead == NULL_IDX) {
        *listhead = newreg;
        regions[newreg].prev_link = NULL_IDX;
        regions[newreg].next_link = NULL_IDX;
        return;
    }

    // Insert the new descriptor in the list ordered by name (ascending)
    int prevreg = NULL_IDX;
    int reg = *listhead;
    while (reg != NULL_IDX) {
        if (strcmp (regions[reg].label, regions[newreg].label) >= 0) {    // found insertion place
            regions[newreg].next_link = reg;
            if (regions[reg].prev_link == NULL_IDX) { // insert before 1st element of list
                regions[newreg].prev_link = NULL_IDX;
                *listhead = newreg;
            }
            else {  // insert somewhere in the middle
                regions[newreg].prev_link = regions[reg].prev_link;
                regions[regions[reg].prev_link].next_link = newreg;
            }
            regions[reg].prev_link = newreg;
            break;
        }
        prevreg = reg;
        reg = regions[reg].next_link;
    }
    if (reg == NULL_IDX) {   // insert after last element
        regions[newreg].prev_link = prevreg;
        regions[newreg].next_link = NULL_IDX;
        regions[prevreg].next_link = newreg;
    }
}

static void
AddHoleToList (
    RD      regions[],
    int *   listhead,
    int     newreg
    ) {
    // If the region list is empty, make the new descriptor the first and last element
    if (*listhead == NULL_IDX) {
        *listhead = newreg;
        regions[newreg].prev_link = NULL_IDX;
        regions[newreg].next_link = NULL_IDX;
        return;
    }

    // Insert the new descriptor in the list ordered by size (ascending)
    int prevreg = NULL_IDX;
    int reg = *listhead;
    while (reg != NULL_IDX) {
        if (regions[reg].extent >= regions[newreg].extent) {    // found insertion place
            regions[newreg].next_link = reg;
            if (regions[reg].prev_link == NULL_IDX) { // insert before 1st element of list
                regions[newreg].prev_link = NULL_IDX;
                *listhead = newreg;
            }
            else {  // insert somewhere in the middle
                regions[newreg].prev_link = regions[reg].prev_link;
                regions[regions[reg].prev_link].next_link = newreg;
            }
            regions[reg].prev_link = newreg;
            break;
        }
        prevreg = reg;
        reg = regions[reg].next_link;
    }
    if (reg == NULL_IDX) {   // insert after last element
        regions[newreg].prev_link = prevreg;
        regions[newreg].next_link = NULL_IDX;
        regions[prevreg].next_link = newreg;
    }
}

static void
RemoveFromList (
    RD      regions[],
    int *   head,
    int     index
    ) {
    // Remove the element with the given index from a doubly-linked list
    if (regions[index].prev_link == NULL_IDX)     // remove first element from the list
        *head = regions[index].next_link;
    else
        regions[regions[index].prev_link].next_link = regions[index].next_link;

    if (regions[index].next_link != NULL_IDX)
        regions[regions[index].next_link].prev_link = regions[index].prev_link;

    regions[index].prev_link = NULL_IDX;
    regions[index].next_link = NULL_IDX;
}

//------------------------------------------------------------------------------
//  The following routines are used by the esm_info command to print information
//  about all contexts in the local host readable by the current user.  It is
//  not formally part of the ESM API.
int
ESM_Shared_Info (
    FILE * output
    ) {
    int thid = -1;
#if defined (HAVE_STRUCT_SHM_INFO)
    struct shm_info shm_info;
    // Get count of shared memory segments
    int maxid = shmctl (0, SHM_INFO, (struct shmid_ds *) &shm_info);
    if (maxid < 0) {
        SetError (thid, "Cannot get shared memory info: %s", strerror (errno));
        return ESM_ERROR;
        }

    // Look for readable shared memory segments and when found attach them
    for (int id = 0 ; id <= maxid ; id++) {
        struct shmid_ds segment;
        int shmid = shmctl (id, SHM_STAT, &segment);
        if (shmid < 0)
            continue;

        // Attach segment to local address space
        CD * cd = (CD *) shmat (shmid, NULL, 0);
        if ((long) cd == -1) {
            SetError (thid, "Cannot attach context descriptor segment in ESM_Shared_Info: %s", strerror (errno));
            DESTROY (shmid, 0);
            return (0);
        }

        // If the segment is an ESM context descriptor, print information about it
        if (cd->signature == ESM_MAGIC)
            PrintContextSegmentInfo (&segment, cd, output);

        // Detach segment from local address space
        if (shmdt ((shmem_t) cd) != 0)
            SetError (thid, "Cannot detach context descriptor segment in ESM_Shared_Info: %s", strerror (errno));
    }
    return ESM_OK;
#else
    SetError (thid, "ESM_Info not implemented on this platform");
    return ESM_ERROR;
#endif
}

static void
PrintContextSegmentInfo (
    struct shmid_ds * segment,
    CD *    cd,
    FILE *  output
    ) {
    fprintf (output, "ESM Context %d\n", cd->ctx_id);
    fprintf (output, "\tsemaphore=%d\n", cd->sema_id);
    fprintf (output, "\tattaches=%d\n", (int) segment->shm_nattch);

    int nholes = 0;
    for (int hole = cd->rd_void_head ; hole != NULL_IDX ; hole = cd->region_table[hole].next_link) nholes++;
    fprintf (output, "\tholes=%d", nholes);
    if (nholes == 0)
        fprintf (output, "\n");

    nholes = 0;
    for (int hole = cd->rd_void_head ; hole != NULL_IDX ; hole = cd->region_table[hole].next_link) {
        if (nholes % 10 == 0)  fprintf (output, "\n\t\t");
        fprintf (output, "%d ", cd->region_table[hole].extent);
        nholes++;
    }
    fprintf (output, "\n\tregions=%d\n", cd->num_regions);

    for (int reg = cd->rd_head ; reg != NULL_IDX ; reg = cd->region_table[reg].next_link) {
        fprintf (output, "\t\tname=\"%s\", size=%d, pagenum=%d, offset=%d\n",
                cd->region_table[reg].label,
                cd->region_table[reg].extent,
                cd->region_table[reg].pgindex,
                cd->region_table[reg].offset
            );
    }
    fprintf (output, "\n");
}
#endif

