using namespace llvm;
using namespace llvm::X86Disassembler;

/// Disassembler table generator - responsible for producing decoder tables for
/// various processor architectures.
/// X86-specific disassembler implementation
///
/// *** NEED TO FIX A "Primary decode conflict"? CHECK THE BOTTOM OF THIS COMMENT!
///
/// This module generates the data structures used by the X86 disassembler,
/// which are described in detail in lib/Target/X86/X86Disassembler.h.
///
/// The output includes several key components:
///
/// - A context mapping table (CONTEXTS_SYM) that associates attribute sets with
///   instruction contexts.  While some attributes affect decoding, most don't -
///   for instance, a 64-bit instruction with both OPSIZE and XS prefixes decodes
///   identically to one with only OPSIZE set.  This optimization reduces table size.
/// - Six opcode hierarchy tables (ONEBYTE_SYM, TWOBYTE_SYM, THREEBYTE38_SYM,
///   THREEBYTE3A_SYM, THREEBYTEA6_SYM, and THREEBYTEA7_SYM) that guide the
///   decoder through instruction parsing.  At the leaf nodes are instruction IDs,
///   16-bit values that uniquely identify instructions and match their position
///   in the target's CodeGenInstructions list.
/// - An instruction metadata table (INSTRUCTIONS_SYM) storing operand info and
///   decoding details for each instruction.
///
/// When conflicts arise during table generation (handled in setTableFields()
/// in X86DisassemblerTables.cpp):
///
/// - Instructions whose native context matches the current one take precedence.
/// - If neither matches, the more specific (higher-priority) context wins,
///   as determined by outranks() (see X86DisassemblerTables.cpp).
/// - If both match, the emitter reports an error and terminates.
///
/// *** HOW TO RESOLVE "Primary decode conflict" ERRORS
///
/// Common solutions (in order of likelihood):
///
/// (1) Exclude one instruction via filter() in X86RecognizableInstr.cpp.
///     This is most frequent - verify against Intel manuals first though.
/// (2) Correct the .td files (X86.td and related) if opcode definitions are wrong.
/// (3) Adjust context requirements in .td files or add new contexts via
///     include/llvm/Support/X86DisassemblerDecoderCommon.h (rare).
///
/// Key files involved:
/// - DisassemblerEmitter.cpp: Main entry point; extracts instructions from
///   CodeGenTarget and feeds them into the table-building logic.
/// - X86DisassemblerTables.h/.cpp: Table management and emission logic.
/// - X86ModRMFilters.h: Filters for valid ModR/M values per instruction.
/// - X86RecognizableInstr.h/.cpp: Per-instruction processing and metadata extraction.

static void GenerateDisassembler(RecordKeeper &Data, raw_ostream &Output) {
  CodeGenTarget Processor(Data);
  emitSourceFileHeader(" * " + Processor.getName().str() + " Disassembler", Output);

  // Special handling for X86 architecture
  if (Processor.getName() == "X86") {
    DisassemblerTables DecoderTables;
    ArrayRef<const CodeGenInstruction*> InstructionList =
      Processor.getInstructionsByEnumValue();

    for (unsigned Index = 0, Limit = InstructionList.size(); Index != Limit; ++Index)
      RecognizableInstr::processInstr(DecoderTables, *InstructionList[Index], Index);

    if (DecoderTables.hasConflicts()) {
      PrintError(Processor.getTargetRecord()->getLoc(), "Primary decode conflict");
      return;
    }

    DecoderTables.emit(Output);
    return;
  }

  // WebAssembly requires special handling due to variable-length opcodes
  if (Processor.getName() == "WebAssembly") {
    emitWebAssemblyDisassemblerTables(Output, Processor.getInstructionsByEnumValue());
    return;
  }

  std::string PredicatePrefix = std::string(Processor.getName());
  if (PredicatePrefix == "Thumb")
    PredicatePrefix = "ARM";

  EmitDecoder(Data, Output, PredicatePrefix);
}

static TableGen::Emitter::Opt GeneratorFlag("gen-disassembler", GenerateDisassembler,
                                            "Generate disassembler");

