// Helper macros for MD5 algorithm operations
#define ROTATE_LEFT(x, n) (((x) << (n)) | ((x) >> (32 - (n))))
#define F_FUNC(m, n, o) (((m) & (n)) | (~(m) & (o)))
#define G_FUNC(m, n, o) (((m) & (o)) | ((n) & ~(o)))
#define H_FUNC(m, n, o) ((m) ^ (n) ^ (o))
#define I_FUNC(m, n, o) ((n) ^ ((m) | ~(o)))

// MD5 round function macros
#define ROUND_F(p, q, r, s, k, shift, constant)                                                                        \
  {                                                                                                                    \
    (p) += F_FUNC((q), (r), (s)) + (k) + (constant);                                                                  \
    (p) = (q) + ROTATE_LEFT((p), (shift));                                                                             \
  }
#define ROUND_G(p, q, r, s, k, shift, constant)                                                                        \
  {                                                                                                                    \
    (p) += G_FUNC((q), (r), (s)) + (k) + (constant);                                                                  \
    (p) = (q) + ROTATE_LEFT((p), (shift));                                                                             \
  }
#define ROUND_H(p, q, r, s, k, shift, constant)                                                                        \
  {                                                                                                                    \
    (p) += H_FUNC((q), (r), (s)) + (k) + (constant);                                                                  \
    (p) = (q) + ROTATE_LEFT((p), (shift));                                                                             \
  }
#define ROUND_I(p, q, r, s, k, shift, constant)                                                                        \
  {                                                                                                                    \
    (p) += I_FUNC((q), (r), (s)) + (k) + (constant);                                                                  \
    (p) = (q) + ROTATE_LEFT((p), (shift));                                                                             \
  }

// MD5 context structure definition
struct MD5Context {
    unsigned long state[4];
    unsigned long datalen;
    unsigned long bitlen;
    unsigned char data[64];
};

// MD5 transformation function
void md5_transform(MD5Context* ctx, const unsigned char data[]) {
    unsigned long a, b, c, d, m[16], idx, i;

#ifndef BROKKR_BIG_ENDIAN
    // Convert little-endian input to big-endian word format
    for (idx = 0, i = 0; idx < 16; ++idx, i += 4)
        m[idx] = (unsigned long)data[i] | 
                 ((unsigned long)data[i + 1] << 8) | 
                 ((unsigned long)data[i + 2] << 16) | 
                 ((unsigned long)data[i + 3] << 24);
#endif

    // Initialize working variables
    a = ctx->state[0];
    b = ctx->state[1];
    c = ctx->state[2];
    d = ctx->state[3];

    // First round
    ROUND_F(a, b, c, d, m[0], 7, 0xd76aa478);
    ROUND_F(d, a, b, c, m[1], 12, 0xe8c7b756);
    ROUND_F(c, d, a, b, m[2], 17, 0x242070db);
    ROUND_F(b, c, d, a, m[3], 22, 0xc1bdceee);
    ROUND_F(a, b, c, d, m[4], 7, 0xf57c0faf);
    ROUND_F(d, a, b, c, m[5], 12, 0x4787c62a);
    ROUND_F(c, d, a, b, m[6], 17, 0xa8304613);
    ROUND_F(b, c, d, a, m[7], 22, 0xfd469501);
    ROUND_F(a, b, c, d, m[8], 7, 0x698098d8);
    ROUND_F(d, a, b, c, m[9], 12, 0x8b44f7af);
    ROUND_F(c, d, a, b, m[10], 17, 0xffff5bb1);
    ROUND_F(b, c, d, a, m[11], 22, 0x895cd7be);
    ROUND_F(a, b, c, d, m[12], 7, 0x6b901122);
    ROUND_F(d, a, b, c, m[13], 12, 0xfd987193);
    ROUND_F(c, d, a, b, m[14], 17, 0xa679438e);
    ROUND_F(b, c, d, a, m[15], 22, 0x49b40821);

    // Second round
    ROUND_G(a, b, c, d, m[1], 5, 0xf61e2562);
