}

// Initialize MD5 context
void md5_init(MD5Context* ctx) {
    ctx->datalen = 0;
    ctx->bitlen = 0;
    ctx->state[0] = 0x67452301;
    ctx->state[1] = 0xefcdab89;
    ctx->state[2] = 0x98badcfe;
    ctx->state[3] = 0x10325476;
}

// Update MD5 with data
void md5_update(MD5Context* ctx, const unsigned char data[], size_t len) {
    size_t i = 0;

    if (ctx->datalen) {
        size_t fill = 64 - ctx->datalen;
        if (len < fill) {
            memcpy(ctx->data + ctx->datalen, data, len);
            ctx->datalen += (unsigned long)len;
            return;
        }
        memcpy(ctx->data + ctx->datalen, data, fill);
        md5_transform(ctx, ctx->data);
        ctx->bitlen += 512;
        ctx->datalen = 0;
        i = fill;
    }

    for (; i + 64 <= len; i += 64) {
        md5_transform(ctx, data + i);
        ctx->bitlen += 512;
    }

    if (i < len) {
        memcpy(ctx->data, data + i, len - i);
        ctx->datalen = (unsigned long)(len - i);
    }
}

// Finalize MD5 and produce hash
void md5_final(MD5Context* ctx, unsigned char hash[]) {
    size_t i = ctx->datalen;

    // Padding
    if (ctx->datalen < 56) {
        ctx->data[i++] = 0x80;
        while (i < 56) ctx->data[i++] = 0x00;
    } else {
        ctx->data[i++] = 0x80;
        while (i < 64) ctx->data[i++] = 0x00;
        md5_transform(ctx, ctx->data);
        memset(ctx->data, 0, 56);
    }

    // Append length in bits
    ctx->bitlen += ctx->datalen * 8;
    ctx->data[56] = (unsigned char)(ctx->bitlen);
    ctx->data[57] = (unsigned char)(ctx->bitlen >> 8);
    ctx->data[58] = (unsigned char)(ctx->bitlen >> 16);
    ctx->data[59] = (unsigned char)(ctx->bitlen >> 24);
    ctx->data[60] = (unsigned char)(ctx->bitlen >> 32);
    ctx->data[61] = (unsigned char)(ctx->bitlen >> 40);
    ctx->data[62] = (unsigned char)(ctx->bitlen >> 48);
    ctx->data[63] = (unsigned char)(ctx->bitlen >> 56);

    md5_transform(ctx, ctx->data);

#ifndef BROKKR_BIG_ENDIAN
    // Convert to little-endian output
    for (i = 0; i < 4; ++i) {
        hash[i] = (ctx->state[0] >> (i * 8)) & 0xff;
        hash[i + 4] = (ctx->state[1] >> (i * 8)) & 0xff;
        hash[i + 8] = (ctx->state[2] >> (i * 8)) & 0xff;
        hash[i + 12] = (ctx->state[3] >> (i * 8)) & 0xff;
    }
#endif
}

