#include <vector>
using namespace std;

class Solution {
public:
    // Generate Pascal's Triangle up to the specified number of rows
    vector<vector<int>> generate(int numRows) {
        vector<vector<int>> triangle;

        // First row is always [1]
        if (numRows > 0) {
            triangle.push_back({1});
        }

        // Build subsequent rows
        for (int rowIndex = 1; rowIndex < numRows; rowIndex++) {
            vector<int> currentRow;

            // Each row starts with 1
            currentRow.push_back(1);

            // Calculate middle elements by summing adjacent elements from previous row
            for (int colIndex = 1; colIndex < triangle.back().size(); colIndex++) {
                currentRow.push_back(triangle.back()[colIndex] + triangle.back()[colIndex - 1]);
            }

            // Each row ends with 1
            currentRow.push_back(1);

            // Add the completed row to the triangle
            triangle.push_back(currentRow);
        }

        return triangle;
    }
};

