#include "test/jemalloc_test.h"

TEST_BEGIN(test_sz_psz2ind_renamed) {
	/*
	 * Verifying page-aligned size class indices located before the primary
	 * group where all size classes are multiples of the page size.
	 * On x86_64 Linux, these are 4096, 8192, 12288, 16384, with indices
	 * 0, 1, 2, and 3 respectively.
	 */
	for (size_t grp = 0; grp < SC_NGROUP; grp++) {
		for (size_t psize = grp * PAGE + 1; psize <= (grp + 1) * PAGE; psize++) {
			pszind_t idx = sz_psz2ind(psize);
			expect_zu_eq(idx, grp, "Expected %u for sz_psz2ind(%zu), got %u", 
			    grp, psize, idx);
		}
	}

	sc_data_t info;
	memset(&info, 0, sizeof(info));
	sc_data_init(&info);

	/*
	 * 'threshold' marks the start of the first regular group where all
	 * size classes are multiples of the page size.
	 * For x86_64 Linux, this is 16384, and its index is 36.
	 */
	size_t threshold_psz = 1 << (SC_LG_NGROUP + LG_PAGE);
	size_t threshold_idx = 0;
	while (threshold_idx < SC_NSIZES &&
	    reg_size_compute(info.sc[threshold_idx].lg_base,
		info.sc[threshold_idx].lg_delta,
		info.sc[threshold_idx].ndelta) < threshold_psz) {
		threshold_idx++;
	}
	expect_zu_eq(
	    reg_size_compute(info.sc[threshold_idx].lg_base,
		info.sc[threshold_idx].lg_delta,
		info.sc[threshold_idx].ndelta),
	    threshold_psz, "Size class equal to %zu not found", threshold_psz);

	/*
	 * Checking various sizes in groups following 'threshold'. The step
	 * size is PAGE / 3 to improve test performance.
	 */
	threshold_idx -= SC_NGROUP;
	for (size_t psize = threshold_psz; psize <= 64 * 1024 * 1024; psize += PAGE / 3) {
		pszind_t idx = sz_psz2ind(psize);
		sc_t upper_sc = info.sc[idx + threshold_idx];
		expect_zu_gt(psize,
		    reg_size_compute(upper_sc.lg_base, upper_sc.lg_delta,
			upper_sc.ndelta),
		    "Expected size > computed for sz_psz2ind(%zu) = %u", psize, idx);
		sc_t lower_sc = info.sc[idx + threshold_idx + 1];
		expect_zu_le(psize,
		    reg_size_compute(lower_sc.lg_base, lower_sc.lg_delta,
			lower_sc.ndelta),
		    "Expected size <= computed for sz_psz2ind(%zu) = %u", psize, idx);
	}

	pszind_t final_idx = sz_psz2ind(SC_LARGE_MAXCLASS + 1);
	expect_lu_eq(final_idx, SC_NPSIZES,
	    "Expected %u as sz_psz2ind(%llu), got %u", 
	    SC_NPSIZES, (unsigned long long)SC_LARGE_MAXCLASS, final_idx);
}
TEST_END

int main(void) {
	return test(test_sz_psz2ind_renamed);
}

#include <iostream>
#include <vector>
#include <numeric>
#include <algorithm>
#include <random>
#include <chrono>
using namespace std;

int main() {
    // Speed up I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int nodes, edges;
    if (!(cin >> nodes >> edges)) return 0;

    // Graph representation using adjacency list (1-indexed)
    vector<vector<int>> graph(nodes + 1);
    for (int i = 0; i < edges; ++i) {
        int a, b;
        cin >> a >> b;
        graph[a].push_back(b);
        graph[b].push_back(a);
    }

    // Track best partition and maximum cut size
    vector<int> best_partition(nodes + 1, 0);
    long long best_cut_value = -1;

    // Time constraint setup
    const double max_duration = 0.90;
    auto start_timestamp = chrono::high_resolution_clock::now();

    // Random number generator initialization
    mt19937_64 prng(chrono::steady_clock::now().time_since_epoch().count());

    // Vertex ordering for random traversal
    vector<int> order(nodes);
    iota(order.begin(), order.end(), 1);
    vector<int> temp_partition(nodes + 1);

    // Iterative optimization with time limit
    while (true) {
        // Random initial assignment
        for (int v = 1; v <= nodes; ++v) {
            temp_partition[v] = prng() & 1;
        }

        // Local search: flip vertices to improve cut
        bool changed = true;
        while (changed) {
            changed = false;
            shuffle(order.begin(), order.end(), prng);

            for (int vertex : order) {
                int same_group = 0;
                int other_group = 0;

                for (int neighbor : graph[vertex]) {
                    if (temp_partition[vertex] == temp_partition[neighbor]) {
                        same_group++;
                    } else {
                        other_group++;
                    }
                }

                if (same_group > other_group) {
                    temp_partition[vertex] ^= 1;
                    changed = true;
                }
            }
        }

        // Evaluate current partition
        long long cut_size = 0;
        for (int u = 1; u <= nodes; ++u) {
            if (temp_partition[u] == 0) {
                for (int v : graph[u]) {
                    if (temp_partition[v] == 1) {
                        cut_size++;
                    }
                }
            }
        }

        // Update best solution if improved
        if (cut_size > best_cut_value) {
            best_cut_value = cut_size;
            best_partition = temp_partition;
        }

        // Check time budget
        auto now = chrono::high_resolution_clock::now();
        chrono::duration<double> diff = now - start_timestamp;
        if (diff.count() >= max_duration) break;
    }

    // Output final partition
    for (int i = 1; i <= nodes; ++i) {
        cout << best_partition[i];
        if (i < nodes) cout << " ";
    }
    cout << "\n";

    return 0;
}

#include <iostream>
#include <magic_enum/magic_enum.hpp>
#include <magic_enum/magic_enum_iostream.hpp>

enum class Status : int { FAILED = -5, PENDING = 0, SUCCESS = 5 };

template <typename E>
auto convert_to_underlying(magic_enum::Enum<E> value) {
  return static_cast<magic_enum::underlying_type_t<E>>(value);
}

int main() {
  // Enum variable to its string representation
  Status s1 = Status::FAILED;
  auto s1_label = magic_enum::enum_name(s1);
  std::cout << s1_label << std::endl; // FAILED

  // Sequence of all enum names
  constexpr auto labels = magic_enum::enum_names<Status>();
  std::cout << "Status names:";
  for (const auto& label : labels) {
    std::cout << " " << label;
  }
  std::cout << std::endl;

  // String to enum conversion
  auto s2 = magic_enum::enum_cast<Status>("PENDING");
  if (s2.has_value()) {
    std::cout << "PENDING = " << convert_to_underlying(s2.value()) << std::endl; // PENDING = 0
  }

  // Case-insensitive conversion
  s2 = magic_enum::enum_cast<Status>("pending", magic_enum::case_insensitive);
  if (s2.has_value()) {
    std::cout << "PENDING = " << convert_to_underlying(s2.value()) << std::endl; // PENDING = 0
  }

  // Integer to enum
  auto s3 = magic_enum::enum_cast<Status>(5);
  if (s3.has_value()) {
    std::cout << "SUCCESS = " << magic_enum::enum_integer(s3.value()) << std::endl; // SUCCESS = 5
  }

  // Enum to integer
  auto s4_int = magic_enum::enum_integer(Status::FAILED);
  std::cout << "FAILED = " << s4_int << std::endl; // FAILED = -5

  using magic_enum::iostream_operators::operator<<;
  std::cout << "Status: " << s1 << " " << s2 << " " << s3 << std::endl; // Status: FAILED PENDING SUCCESS

  // Count of enum values
  std::cout << "Status enum size: " << magic_enum::enum_count<Status>() << std::endl; // Size: 3

  // Access by index
  std::cout << "Status[1] = " << magic_enum::enum_value<Status>(1) << std::endl; // Status[1] = PENDING

  // All enum values
  constexpr auto all_values = magic_enum::enum_values<Status>();
  std::cout << "Status values:";
  for (const auto val : all_values) {
    std::cout << " " << val;
  }
  std::cout << std::endl;

  enum class Permission { READ = 1, WRITE = 2, EXECUTE = 4 };
  using namespace magic_enum::bitwise_operators;
  Permission perm = Permission::READ | Permission::EXECUTE;
  std::cout << perm << std::endl; // 5

  enum mode { low, medium, high };
  static_assert(magic_enum::is_unscoped_enum_v<mode>);
  static_assert(!magic_enum::is_unscoped_enum_v<Status>);
  static_assert(!magic_enum::is_unscoped_enum_v<Permission>);

  static_assert(!magic_enum::is_scoped_enum_v<mode>);
  static_assert(magic_enum::is_scoped_enum_v<Status>);
  static_assert(magic_enum::is_scoped_enum_v<Permission>);

  // Enum entries (value-name pairs)
  constexpr auto entry_list = magic_enum::enum_entries<Status>();
  std::cout << "Status entries:";
  for (const auto& entry : entry_list) {
    std::cout << " " << entry.second << " = " << static_cast<int>(entry.first);
  }
  std::cout << std::endl;

  return 0;
}

