#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int testCases;
    if (!(cin >> testCases)) return 0;

    vector<unsigned long long> queries(testCases);
    for (int idx = 0; idx < testCases; ++idx) {
        cin >> queries[idx];
    }

    for (int qIdx = 0; qIdx < testCases; ++qIdx) {
        unsigned long long target = queries[qIdx];

        // Construct operation sequence: 'M' for max (double), 'N' for min (add one)
        vector<char> steps;
        int highestBit = 63 - __builtin_clzll(target); // position of most significant bit
        for (int bitPos = highestBit - 1; bitPos >= 0; --bitPos) {
            steps.push_back('M'); // doubling step
            if ((target >> bitPos) & 1ULL) {
                steps.push_back('N'); // increment step
            }
        }

        int length = (int)steps.size();
        cout << length << "\n";

        if (length == 0) {
            cout << "\n";
            continue;
        }

        // Compute relative values during simulation
        vector<long long> deltas(length);
        long long minVal = 0, maxVal = -1;
        for (int pos = 0; pos < length; ++pos) {
            if (steps[pos] == 'M') {
                maxVal += 1;
                deltas[pos] = maxVal;
            } else {
                minVal -= 1;
                deltas[pos] = minVal;
            }
        }

        // Rank the relative values to produce permutation
        vector<int> positions(length);
        iota(positions.begin(), positions.end(), 0);
        sort(positions.begin(), positions.end(), [&](int a, int b) {
            return deltas[a] < deltas[b];
        });

        vector<int> result(length);
        for (int rank = 0; rank < length; ++rank) {
            result[positions[rank]] = rank;
        }

        for (int i = 0; i < length; ++i) {
            if (i > 0) cout << " ";
            cout << result[i];
        }
        cout << "\n";
    }

    return 0;
}

