//////////////////////////////////////////////////////////////////////////////
// Serialize binary data as CBOR
//////////////////////////////////////////////////////////////////////////////
static void EncodeBinaryCbor(benchmark::State& state)
{
    std::vector<uint8_t> pattern(256);
    std::iota(pattern.begin(), pattern.end(), 0);
    auto iter = pattern.begin();
    std::vector<uint8_t> input_buffer;
    input_buffer.reserve(state.range(0));
    for (int index = 0; index < state.range(0); ++index)
    {
        if (iter == pattern.end())
        {
            iter = pattern.begin();
        }
        input_buffer.push_back(*iter);
        ++iter;
    }
    json::binary_t encoded{input_buffer};
    json object{{"kind", "binary"}, {"payload", encoded}};
    while (state.KeepRunning())
    {
        json::to_cbor(object);
    }
    state.SetBytesProcessed(state.iterations() * json::to_cbor(object).size());
}
BENCHMARK(EncodeBinaryCbor)->RangeMultiplier(2)->Range(8, 8 << 12);
