#include <iostream>
#include <vector>
#include <string>
#include <numeric>
#include <algorithm>
#include <random>
#include <iomanip>

// Fixed seed for reproducibility of random operations
std::mt19937 prng(42);

void process() {
    int participants;
    int rounds;
    std::cin >> participants >> rounds;

    // Initialize weights for each participant
    std::vector<long double> expert_weights(participants, 1.0L);
    // Track error counts per participant
    std::vector<int> error_counts(participants, 0);

    for (int round = 0; round < rounds; ++round) {
        std::string predictions;
        std::cin >> predictions;
        int predicted_value;

        // Determine the smallest error count among all participants
        int least_errors = *std::min_element(error_counts.begin(), error_counts.end());

        // Strategy: If any participant has zero errors, follow their prediction first
        if (least_errors == 0) {
            int best_expert_index = -1;
            for (int idx = 0; idx < participants; ++idx) {
                if (error_counts[idx] == 0) {
                    best_expert_index = idx;
                    break;
                }
            }
            predicted_value = predictions[best_expert_index] - '0';
        } else {
            // Use weighted random selection based on current expert weights
            long double weight_for_zero = 0.0L;
            long double weight_for_one = 0.0L;

            for (int idx = 0; idx < participants; ++idx) {
                if (predictions[idx] == '0') {
                    weight_for_zero += expert_weights[idx];
                } else {
                    weight_for_one += expert_weights[idx];
                }
            }

            long double combined_weight = weight_for_zero + weight_for_one;

            // Fallback if all weights become negligible
            if (combined_weight == 0.0L) {
                predicted_value = 0;
            } else {
                long double probability_of_one = weight_for_one / combined_weight;
                std::uniform_real_distribution<long double> sampler(0.0L, 1.0L);
                if (sampler(prng) < probability_of_one) {
                    predicted_value = 1;
                } else {
                    predicted_value = 0;
                }
            }
        }

        std::cout << predicted_value << std::endl;

        int actual_result;
        std::cin >> actual_result;

        // Update expert performance and weights
        for (int idx = 0; idx < participants; ++idx) {
            int expert_prediction = predictions[idx] - '0';
            if (expert_prediction != actual_result) {
                error_counts[idx]++;
                expert_weights[idx] *= 0.5L;
            }
        }
    }
}

int main() {
    // Optimize I/O performance
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    process();
    return 0;
}

