// Convert fixed-point to double for comparison
static double
fxp_to_double(fxp_t val) {
	double integer_part = (double)(val >> 16);
	double fractional_part = (double)(val & ((1U << 16) - 1)) / (1U << 16);
	return integer_part + fractional_part;
}

// Check if two doubles are approximately equal
static bool
doubles_approx_equal(double x, double y) {
	/*
	 * Tolerance-based comparison: accept values close in either relative
	 * or absolute terms due to limited precision.
	 */
	return fabs(x - y) < 0.01 || fabs(x - y) / x < 0.01;
}

// Compare two fxp_t values via conversion to double
static bool
fxp_values_close(fxp_t val1, fxp_t val2) {
	return doubles_approx_equal(fxp_to_double(val1), fxp_to_double(val2));
}

// Parse a string into an fxp_t value
static fxp_t
parse_fxp_string(const char *input_str) {
	fxp_t parsed_value;
	bool parse_error = fxp_parse(&parsed_value, input_str, NULL);
	assert_false(parse_error, "Invalid fxp string: %s", input_str);
	return parsed_value;
}

// Verify parsing accuracy against expected string representation
static void
verify_parse_accuracy(const char *expected_str, const char *input_str) {
	double expected_value = strtod(expected_str, NULL);
	fxp_t parsed_fxp;
	char *parse_end;
	bool parse_error = fxp_parse(&parsed_fxp, input_str, &parse_end);
	expect_false(parse_error, "Unexpected parse failure");
	expect_ptr_eq(input_str + strlen(expected_str), parse_end,
	    "Did not parse entire string");
	expect_true(doubles_approx_equal(fxp_to_double(parsed_fxp), expected_value),
	    "Failed to parse %s correctly", expected_str);
}

// Test valid parsing scenarios with various formats
static void
run_valid_parsing_tests(const char *test_str) {
	// Direct parsing should succeed
	verify_parse_accuracy(test_str, test_str);

	// Parsing with trailing text should still work
	char buffer[100];
	snprintf(buffer, sizeof(buffer), "%s附加文本内容", test_str);
	verify_parse_accuracy(test_str, buffer);

	// Parsing with space-separated suffix
	snprintf(buffer, sizeof(buffer), "%s 后缀空格", test_str);
	verify_parse_accuracy(test_str, buffer);

	// Parsing within malloc.conf-like format
	snprintf(buffer, sizeof(buffer), "%s:配置项:1", test_str);
	verify_parse_accuracy(test_str, buffer);
}

