	bool error_occurred = fxp_parse(&result, invalid_str, &end_marker);
	expect_true(error_occurred, "Expected parse error on: %s", invalid_str);
	expect_ptr_eq((void *)0x123, end_marker,
	    "Parse error should not alter result pointer");
	expect_u32_eq(result, FXP_INIT_INT(333),
	    "Parse error should not modify stored value");
}

