	size_t num_values = sizeof(test_values)/sizeof(test_values[0]);

	for (size_t idx_i = 0; idx_i < num_values; idx_i++) {
		fxp_t fxp_a = parse_fxp_string(test_values[idx_i]);
		double dbl_a = strtod(test_values[idx_i], NULL);
		uint32_t fxp_floor = fxp_round_down(fxp_a);
		uint32_t fxp_round = fxp_round_nearest(fxp_a);
		uint32_t dbl_floor = (uint32_t)dbl_a;
		uint32_t dbl_round = (uint32_t)round(dbl_a);

		expect_u32_eq(dbl_floor, fxp_floor,
		    "Floor mismatch for %s", test_values[idx_i]);
		expect_u32_eq(dbl_round, fxp_round,
		    "Round-to-nearest mismatch for %s", test_values[idx_i]);

		for (size_t idx_j = 0; idx_j < num_values; idx_j++) {
			fxp_t fxp_b = parse_fxp_string(test_values[idx_j]);
			double dbl_b = strtod(test_values[idx_j], NULL);
			fxp_t fxp_sum = fxp_add(fxp_a, fxp_b);
			double dbl_sum = dbl_a + dbl_b;
			expect_true(
			    doubles_approx_equal(fxp_to_double(fxp_sum), dbl_sum),
			    "Addition mismatch: %s + %s", test_values[idx_i], test_values[idx_j]);

			if (dbl_a > dbl_b) {
				fxp_t fxp_diff = fxp_sub(fxp_a, fxp_b);
				double dbl_diff = dbl_a - dbl_b;
				expect_true(
				    doubles_approx_equal(fxp_to_double(fxp_diff), dbl_diff),
				    "Subtraction mismatch: %s - %s", test_values[idx_i], test_values[idx_j]);
			}

			fxp_t fxp_prod = fxp_mul(fxp_a, fxp_b);
			double dbl_prod = dbl_a * dbl_b;
			expect_true(
			    doubles_approx_equal(fxp_to_double(fxp_prod), dbl_prod),
			    "Multiplication mismatch: %s * %s", test_values[idx_i], test_values[idx_j]);

			if (dbl_b != 0.0) {
				fxp_t fxp_quot = fxp_div(fxp_a, fxp_b);
				double dbl_quot = dbl_a / dbl_b;
				expect_true(
				    doubles_approx_equal(fxp_to_double(fxp_quot), dbl_quot),
				    "Division mismatch: %s / %s", test_values[idx_i], test_values[idx_j]);
			}
		}
	}
}
TEST_END

int
main(void) {
	return test_no_reentrancy(
	    test_valid_parsing,
	    test_invalid_parsing,
	    test_percentage_initialization,
	    test_addition_operations,
	    test_subtraction_operations,
	    test_multiplication_operations,
	    test_division_operations,
	    test_rounding_operations,
	    test_fractional_multiplication,
	    test_print_roundtrip,
	    test_stress_comparison);
}

