// Global configuration variables
std::uint32_t unpack_config_context    = 0;
std::uint32_t pack_dst_sync_addr       = 0;
std::uint32_t math_dst_sync_tile_idx   = 0;

#ifdef LLK_TRISC_UNPACK
#include "experimental/llk_unpack_AB_sub_bcast_col_custom.h"
#include "llk_unpack_common.h"
#include "params.h"

void run_kernel(const volatile struct RuntimeParams* input_params)
{
#ifdef RUNTIME_FORMATS
    const volatile FormatConfig& fmt_cfg = input_params->formats;
#endif

    // Configure unpacker hardware with face dimensions and count
    _llk_unpack_hw_configure_<is_fp32_dest_acc_en>(
        fmt_cfg.unpack_A_src, fmt_cfg.unpack_B_src,
        fmt_cfg.unpack_A_dst, fmt_cfg.unpack_B_dst,
        FACE_R_DIM, FACE_R_DIM, 4U /* num_faces */, 4U /* num_faces */);

    // Initialize custom broadcast column unpacking
    _llk_unpack_AB_sub_bcast_col_init_custom_<BROADCAST_TYPE>();

    // Execute custom unpack operation
    _llk_unpack_AB_sub_bcast_col_custom_<BROADCAST_TYPE>(
        L1_ADDRESS(input_params->buffer_A[0]),
        L1_ADDRESS(input_params->buffer_B[0]),
        CT_DIM);
}
#endif

#ifdef LLK_TRISC_MATH
#include "experimental/llk_math_eltwise_binary_custom.h"
#include "llk_math_common.h"
#include "params.h"

void run_kernel(const volatile struct RuntimeParams* input_params)
{
#ifdef RUNTIME_FORMATS
    const volatile FormatConfig& fmt_cfg = input_params->formats;
#endif

    // Initialize synchronization for destination buffer
    _llk_math_pack_sync_init_<DstSync::SyncHalf, is_fp32_dest_acc_en>();

    // Configure math unit hardware
    _llk_math_hw_configure_<is_fp32_dest_acc_en>(fmt_cfg.math, fmt_cfg.math);

    // Setup element-wise binary operation with fidelity settings
    _llk_math_eltwise_binary_init_custom_<ELTWISE_BINARY_OP, BROADCAST_TYPE, MATH_FIDELITY>(4U, 0U);

    // Wait until destination buffer is ready
    _llk_math_wait_for_dest_available_<DstSync::SyncHalf>();

    // Perform custom binary operation with reuse
    _llk_math_eltwise_binary_bcast_reuse_custom_(CT_DIM);

    // Signal completion of destination section
    _llk_math_dest_section_done_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
}
#endif

#ifdef LLK_TRISC_PACK
#include "llk_pack.h"
#include "llk_pack_common.h"
#include "params.h"

void run_kernel(const volatile struct RuntimeParams* input_params)
{
#ifdef RUNTIME_FORMATS
    const volatile FormatConfig& fmt_cfg = input_params->formats;
#endif

#ifdef ARCH_BLACKHOLE
    // Pack hardware configuration for Blackhole architecture
    _llk_pack_hw_configure_<is_fp32_dest_acc_en, false, false>(fmt_cfg.pack_src, fmt_cfg.pack_dst, 16U * 16U * 4U);
#else
    // Default pack hardware configuration
    _llk_pack_hw_configure_<is_fp32_dest_acc_en, false>(fmt_cfg.pack_src, fmt_cfg.pack_dst, 16U * 16U * 4U);
#endif

    // Initialize packer with no special flags
    _llk_pack_init_<false, false>(fmt_cfg.pack_dst);

#ifdef ARCH_BLACKHOLE
    // Destination initialization for Blackhole
    _llk_pack_dest_init_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
#else
    // Default destination initialization
    _llk_pack_dest_init_<DstSync::SyncHalf, false, false>();
#endif

    // Ensure math operations have completed before packing
    _llk_packer_wait_for_math_done_();

    // Pack all result tiles into L1 memory
    for (std::size_t tile_index = 0; tile_index < input_params->TILE_CNT; ++tile_index)
    {
        _llk_pack_<DstSync::SyncHalf, is_fp32_dest_acc_en, false>(
            static_cast<int>(tile_index),
            L1_ADDRESS(input_params->buffer_Res[tile_index]));
    }

    // Mark destination section as complete
    _llk_pack_dest_section_done_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
}
#endif

