{
	int idx;
	if( light == GL_LIGHT0 )
	{
		idx = 0;
	}
	else if( light == GL_LIGHT1 )
	{
		idx = 1;
	}
	else return;

	float *data = values->_getDataPointer();
	switch( mode )
	{
	case GL_POSITION:
		RenderManager.StateSetLightDirection(idx, data[0], data[1], data[2]);
		break;
	case GL_DIFFUSE:
		RenderManager.StateSetLightColour(idx, data[0], data[1], data[2]);
		break;
	case GL_AMBIENT:
		break;
	case GL_SPECULAR:
		break;
	}
}

