/******************************************************************************/
/* A list of all the tsds in the nominal state. */
typedef ql_head(tsd_t) tsd_active_list_t;
static tsd_active_list_t tsd_active_entries = ql_head_initializer(tsd_active_entries);
static malloc_mutex_t tsd_active_entries_lock;
/* How many slow-path-enabling features are turned on. */
static atomic_u32_t tsd_global_slow_counter = ATOMIC_INIT(0);

static bool
tsd_is_in_active_list(tsd_t *tsd) {
	tsd_t *cursor;
	bool found = false;
	malloc_mutex_lock(TSDN_NULL, &tsd_active_entries_lock);
	ql_foreach(cursor, &tsd_active_entries, TSD_MANGLE(tsd_link)) {
		if (tsd == cursor) {
			found = true;
			break;
		}
	}
	malloc_mutex_unlock(TSDN_NULL, &tsd_active_entries_lock);
	return found;
}

static void
tsd_insert_active(tsd_t *tsd) {
	assert(!tsd_is_in_active_list(tsd));
	assert(tsd_state_get(tsd) <= tsd_state_nominal_max);
	ql_elm_new(tsd, TSD_MANGLE(tsd_link));
	malloc_mutex_lock(tsd_tsdn(tsd), &tsd_active_entries_lock);
	ql_tail_insert(&tsd_active_entries, tsd, TSD_MANGLE(tsd_link));
	malloc_mutex_unlock(tsd_tsdn(tsd), &tsd_active_entries_lock);
}

static void
tsd_erase_active(tsd_t *tsd) {
	assert(tsd_is_in_active_list(tsd));
	assert(tsd_state_get(tsd) <= tsd_state_nominal_max);
	malloc_mutex_lock(tsd_tsdn(tsd), &tsd_active_entries_lock);
	ql_remove(&tsd_active_entries, tsd, TSD_MANGLE(tsd_link));
	malloc_mutex_unlock(tsd_tsdn(tsd), &tsd_active_entries_lock);
}

static void
tsd_trigger_recompute_all(tsdn_t *tsdn) {
	atomic_fence(ATOMIC_RELEASE);
	malloc_mutex_lock(tsdn, &tsd_active_entries_lock);
	tsd_t *remote_tsd;
	ql_foreach(remote_tsd, &tsd_active_entries, TSD_MANGLE(tsd_link)) {
		assert(tsd_atomic_load(&remote_tsd->state, ATOMIC_RELAXED)
		    <= tsd_state_nominal_max);
		tsd_atomic_store(&remote_tsd->state,
		    tsd_state_nominal_recompute, ATOMIC_RELAXED);
		atomic_fence(ATOMIC_SEQ_CST);
		te_next_event_fast_set_non_nominal(remote_tsd);
	}
	malloc_mutex_unlock(tsdn, &tsd_active_entries_lock);
}

void
tsd_global_slow_inc(tsdn_t *tsdn) {
	atomic_fetch_add_u32(&tsd_global_slow_counter, 1, ATOMIC_RELAXED);
	tsd_trigger_recompute_all(tsdn);
}

void tsd_global_slow_dec(tsdn_t *tsdn) {
	atomic_fetch_sub_u32(&tsd_global_slow_counter, 1, ATOMIC_RELAXED);
	tsd_trigger_recompute_all(tsdn);
}

static bool
tsd_locally_slow(tsd_t *tsd) {
	return !tsd_tcache_enabled_get(tsd)
	    || tsd_reentrancy_level_get(tsd) > 0;
}

bool
tsd_global_slow(void) {
	return atomic_load_u32(&tsd_global_slow_counter, ATOMIC_RELAXED) > 0;
}

/******************************************************************************/
static uint8_t
tsd_current_state_compute(tsd_t *tsd) {
	if (!tsd_nominal(tsd)) {
		return tsd_state_get(tsd);
	}
	if (malloc_slow || tsd_locally_slow(tsd) || tsd_global_slow()) {
		return tsd_state_nominal_slow;
	} else {
		return tsd_state_nominal;
	}
}

void
tsd_slow_refresh(tsd_t *tsd) {
	uint8_t old_state;
	do {
		uint8_t new_state = tsd_current_state_compute(tsd);
		old_state = tsd_atomic_exchange(&tsd->state, new_state,
		    ATOMIC_ACQUIRE);
	} while (old_state == tsd_state_nominal_recompute);
	te_recompute_fast_threshold(tsd);
}

void
tsd_state_update(tsd_t *tsd, uint8_t new_state) {
	assert(new_state != tsd_state_nominal_recompute);
	uint8_t old_state = tsd_atomic_load(&tsd->state, ATOMIC_RELAXED);
	if (old_state > tsd_state_nominal_max) {
		assert(!tsd_is_in_active_list(tsd));
		tsd_atomic_store(&tsd->state, new_state, ATOMIC_RELAXED);
		if (new_state <= tsd_state_nominal_max) {
			tsd_insert_active(tsd);
		}
	} else {
		assert(tsd_is_in_active_list(tsd));
		if (new_state > tsd_state_nominal_max) {
			tsd_erase_active(tsd);
			tsd_atomic_store(&tsd->state, new_state,
			    ATOMIC_RELAXED);
		} else {
			tsd_slow_refresh(tsd);
		}
	}
	te_recompute_fast_threshold(tsd);
}

static void
tsd_prng_seed_init(tsd_t *tsd) {
	*tsd_prng_statep_get(tsd) = config_debug ? 0 :
	    (uint64_t)(uintptr_t)tsd;
}

static bool
tsd_data_setup(tsd_t *tsd) {
	rtree_ctx_data_init(tsd_rtree_ctxp_get_unsafe(tsd));
	tsd_prng_seed_init(tsd);
	tsd_te_init(tsd);
	tsd_san_init(tsd);
	return tsd_tcache_enabled_data_init(tsd);
}

static void
assert_tsd_cleanup_valid(tsd_t *tsd) {
	assert(!tsd_nominal(tsd));
	assert(!tsd_is_in_active_list(tsd));
	assert(*tsd_arenap_get_unsafe(tsd) == NULL);
	assert(*tsd_iarenap_get_unsafe(tsd) == NULL);
	assert(*tsd_tcache_enabledp_get_unsafe(tsd) == false);
	assert(*tsd_prof_tdatap_get_unsafe(tsd) == NULL);
}

static bool
tsd_data_setup_no_cleanup(tsd_t *tsd) {
	assert(tsd_state_get(tsd) == tsd_state_reincarnated ||
	    tsd_state_get(tsd) == tsd_state_minimal_initialized);
	rtree_ctx_data_init(tsd_rtree_ctxp_get_unsafe(tsd));
	*tsd_tcache_enabledp_get_unsafe(tsd) = false;
	*tsd_reentrancy_levelp_get(tsd) = 1;
	tsd_prng_seed_init(tsd);
	tsd_te_init(tsd);
	tsd_san_init(tsd);
	assert_tsd_cleanup_valid(tsd);
	return false;
}

tsd_t *
tsd_fetch_slow_path(tsd_t *tsd, bool minimal) {
	assert(!tsd_fast(tsd));
	if (tsd_state_get(tsd) == tsd_state_nominal_slow) {
	} else if (tsd_state_get(tsd) == tsd_state_nominal_recompute) {
		tsd_slow_refresh(tsd);
	} else if (tsd_state_get(tsd) == tsd_state_uninitialized) {
		if (!minimal) {
			if (tsd_initialization_complete) {
				tsd_state_update(tsd, tsd_state_nominal);
				tsd_slow_refresh(tsd);
				tsd_set(tsd);
				tsd_data_setup(tsd);
			}
		} else {
			tsd_state_update(tsd, tsd_state_minimal_initialized);
			tsd_set(tsd);
			tsd_data_setup_no_cleanup(tsd);
			*tsd_min_init_state_nfetchedp_get(tsd) = 1;
		}
	} else if (tsd_state_get(tsd) == tsd_state_minimal_initialized) {
		uint8_t *nfetched = tsd_min_init_state_nfetchedp_get(tsd);
		assert(*nfetched >= 1);
		(*nfetched)++;
		if (!minimal || *nfetched == TSD_MIN_INIT_STATE_MAX_FETCHED) {
			tsd_state_update(tsd, tsd_state_nominal);
			assert(*tsd_reentrancy_levelp_get(tsd) >= 1);
			(*tsd_reentrancy_levelp_get(tsd))--;
			tsd_slow_refresh(tsd);
			tsd_data_setup(tsd);
		} else {
			assert_tsd_cleanup_valid(tsd);
		}
	} else if (tsd_state_get(tsd) == tsd_state_purgatory) {
		tsd_state_update(tsd, tsd_state_reincarnated);
		tsd_set(tsd);
		tsd_data_setup_no_cleanup(tsd);
	} else {
		assert(tsd_state_get(tsd) == tsd_state_reincarnated);
	}
	return tsd;
}

