    !defined(_WIN32))

void *
tsd_init_check_recursion(tsd_init_list_t *list, tsd_init_block_t *block) {
	pthread_t self = pthread_self();
	tsd_init_block_t *iter;
	malloc_mutex_lock(TSDN_NULL, &list->lock);
	ql_foreach(iter, &list->entries, link) {
		if (iter->thread == self) {
			malloc_mutex_unlock(TSDN_NULL, &list->lock);
			return iter->data;
		}
	}
	ql_elm_new(block, link);
	block->thread = self;
	ql_tail_insert(&list->entries, block, link);
	malloc_mutex_unlock(TSDN_NULL, &list->lock);
	return NULL;
}

void
tsd_init_finish(tsd_init_list_t *list, tsd_init_block_t *block) {
	malloc_mutex_lock(TSDN_NULL, &list->lock);
	ql_remove(&list->entries, block, link);
	malloc_mutex_unlock(TSDN_NULL, &list->lock);
}
#endif

void
tsd_prefork(tsd_t *tsd) {
	malloc_mutex_prefork(tsd_tsdn(tsd), &tsd_active_entries_lock);
}

void
tsd_postfork_parent(tsd_t *tsd) {
	malloc_mutex_postfork_parent(tsd_tsdn(tsd), &tsd_active_entries_lock);
}

void
tsd_postfork_child(tsd_t *tsd) {
	malloc_mutex_postfork_child(tsd_tsdn(tsd), &tsd_active_entries_lock);
	ql_new(&tsd_active_entries);
	if (tsd_state_get(tsd) <= tsd_state_nominal_max) {
		tsd_insert_active(tsd);
	}
}

