namespace py = pybind11;
using namespace qdk::chemistry::algorithms;
using namespace qdk::chemistry::data;

// Alias for return type: energy + wavefunction
using ResultType = std::pair<double, std::shared_ptr<Wavefunction>>;

// Trampoline class to support Python subclassing
class AbstractPMCBase
    : public ProjectedMultiConfigurationCalculator,
      public pybind11::trampoline_self_life_support {
 public:
  std::string identifier() const override {
    PYBIND11_OVERRIDE_PURE(std::string, ProjectedMultiConfigurationCalculator,
                           identifier);
  }

  std::vector<std::string> tags() const override {
    PYBIND11_OVERRIDE(std::vector<std::string>,
                      ProjectedMultiConfigurationCalculator, tags);
  }

  // Utility to update internal settings from derived classes
  void update_settings(
      std::unique_ptr<qdk::chemistry::data::Settings> updated) {
    this->_settings = std::move(updated);
  }

 protected:
  ResultType _execute_impl(
      std::shared_ptr<Hamiltonian> hamiltonian,
      const std::vector<Configuration> &determinants) const override {
    PYBIND11_OVERRIDE_PURE(ResultType, ProjectedMultiConfigurationCalculator,
                           _execute_impl, hamiltonian, determinants);
  }
};

void bind_projected_mc(py::module &m) {
  // Bind abstract base class
  py::class_<ProjectedMultiConfigurationCalculator,
             AbstractPMCBase, py::smart_holder>
      pmc_base(m, "ProjectedMultiConfigurationCalculator",
               R"(
Abstract foundation for projected multi-configurational (PMC) quantum chemistry computations.
This interface enables flexible projection of the Hamiltonian onto user-specified determinant spaces,
allowing integration with external methods for selecting relevant configurations.
The computation yields both the total energy and the corresponding wavefunction.
To implement a custom PMC solver, derive from this class.
Example:
    >>> import qdk_chemistry.algorithms as alg
    >>> import qdk_chemistry.data as data
    >>> class CustomPMC(alg.ProjectedMultiConfigurationCalculator):
    ...     def __init__(self):
    ...         super().__init__()
    ...     def _execute_impl(self, hamiltonian: data.Hamiltonian, determinants: list[data.Configuration]) -> tuple[float, data.Wavefunction]:
    ...         # Your implementation here
    ...         return energy, wavefunction
)");

  pmc_base.def(py::init<>(),
               R"(
Initialize an empty PMC calculator instance.
Typically invoked via `super().__init__()` in subclasses.
)");

  pmc_base.def("compute", &ProjectedMultiConfigurationCalculator::run,
               R"(
Execute the projected multi-configurational calculation.
Settings are locked prior to execution.
Args:
    hamiltonian (qdk_chemistry.data.Hamiltonian): System Hamiltonian operator
    determinants (list[qdk_chemistry.data.Configuration]): Determinant space for projection
Returns:
    tuple[float, qdk_chemistry.data.Wavefunction]: Energy and optimized wavefunction
Raises:
    RuntimeError: On computational failure
    ValueError: For invalid inputs
)",
               py::arg("hamiltonian"), py::arg("determinants"));

  pmc_base.def("config", &ProjectedMultiConfigurationCalculator::settings,
               R"(
Retrieve current configuration parameters.
Returns:
    qdk_chemistry.data.Settings: Reference to active settings object
)",
               py::return_value_policy::reference_internal);

  // Expose internal settings as mutable property for subclasses
  pmc_base.def_property(
      "_internal_config",
      [](AbstractPMCBase &calc) -> Settings & { return calc.config(); },
      [](AbstractPMCBase &calc,
         std::unique_ptr<qdk::chemistry::data::Settings> replacement) {
        calc.update_settings(std::move(replacement));
      },
      py::return_value_policy::reference_internal,
      R"(
Writable internal settings reference.
Allows subclasses to inject specialized Settings types during initialization.
Example:
    >>> class SpecializedPMC(alg.ProjectedMultiConfigurationCalculator):
    ...     def __init__(self):
    ...         super().__init__()
    ...         self._internal_config = ElectronicStructureSettings()
)");

  pmc_base.def("label", &ProjectedMultiConfigurationCalculator::name,
               R"(
Algorithm identifier string.
Returns:
    str: Human-readable name of the algorithm
)");

  pmc_base.def("category", &ProjectedMultiConfigurationCalculator::type_name,
               R"(
Classification label for the algorithm.
Returns:
    str: Type classification string
)");

  // Factory binding
  qdk::chemistry::python::bind_algorithm_factory<
      ProjectedMultiConfigurationCalculatorFactory,
      ProjectedMultiConfigurationCalculator,
      AbstractPMCBase>(
      m, "ProjectedMultiConfigurationCalculatorFactory");

  pmc_base.def("__repr__", [](const ProjectedMultiConfigurationCalculator &) {
    return "<qdk_chemistry.algorithms.ProjectedMultiConfigurationCalculator>";
  });

  // Concrete MACIS-based implementation
  py::class_<microsoft::MacisPmc, ProjectedMultiConfigurationCalculator,
             py::smart_holder>(m, "QdkMacisPmc", R"(
Concrete PMC solver using Microsoft's MACIS library.
Performs Hamiltonian projection over user-provided determinants for strongly correlated systems.
Inherits behavior from :class:`ProjectedMultiConfigurationCalculator`.
Usage example:
.. code-block:: python
    import qdk_chemistry.algorithms as alg
    import qdk_chemistry.data as data
    pmc = alg.QdkMacisPmc()
    pmc.config().set("davidson_res_tol", 1e-8)
    pmc.config().set("davidson_max_m", 200)
    energy, wf = pmc.compute(hamiltonian, determinants)
See Also:
    :class:`ProjectedMultiConfigurationCalculator`
    :class:`qdk_chemistry.data.Hamiltonian`
    :class:`qdk_chemistry.data.Configuration`
    :class:`qdk_chemistry.data.Wavefunction`
)")
      .def(py::init<>(), R"(
Construct with default configuration.
)");
}

