ControlsScreen::ControlsScreen(Screen* prevScreen, Options* settings) {
    // 4J - added initialisers
    title = L"Controls";
    activeKeyIndex = -1;
    previousScreen = prevScreen;
    gameSettings  = settings;
}

int ControlsScreen::getLeftOffset() { return width / 2 - 155; }

void ControlsScreen::init() {
    Language* lang = Language::getInstance();
    int startX = getLeftOffset();

    for (int idx = 0; idx < Options::keyMappings_length; ++idx) {
        buttons.emplace_back(new SmallButton(
            idx,
            startX + (idx % 2) * ROW_WIDTH,
            height / 6 + 24 * (idx >> 1),
            BUTTON_WIDTH,
            20,
            gameSettings->getKeyMessage(idx)
        ));
    }

    buttons.emplace_back(new Button(
        200,
        width / 2 - 100,
        height / 6 + 24 * 7,
        lang->getElement(L"gui.done")
    ));

    title = lang->getElement(L"controls.title");
}

void ControlsScreen::buttonClicked(Button* btn) {
    for (int i = 0; i < Options::keyMappings_length; ++i) {
        buttons[i]->msg = gameSettings->getKeyMessage(i);
    }

    if (btn->id == 200) {
        minecraft->setScreen(previousScreen);
    } else {
        activeKeyIndex = btn->id;
        btn->msg = L"> " + gameSettings->getKeyMessage(btn->id) + L" <";
    }
}

void ControlsScreen::keyPressed(wchar_t charEvent, int keyEvent) {
    if (activeKeyIndex >= 0) {
        gameSettings->setKey(activeKeyIndex, keyEvent);
        buttons[activeKeyIndex]->msg = gameSettings->getKeyMessage(activeKeyIndex);
        activeKeyIndex = -1;
    } else {
        Screen::keyPressed(charEvent, keyEvent);
    }
}

void ControlsScreen::render(int mouseX, int mouseY, float alpha) {
    renderBackground();
    drawCenteredString(font, title, width / 2, 20, 0xffffff);

    int startX = getLeftOffset();
    for (int i = 0; i < Options::keyMappings_length; ++i) {
        drawString(
            font,
            gameSettings->getKeyDescription(i),
            startX + (i % 2) * ROW_WIDTH + BUTTON_WIDTH + 6,
            height / 6 + 24 * (i >> 1) + 7,
            0xffffffff
        );
    }

    Screen::render(mouseX, mouseY, alpha);
}

