    if (auto* lnf = dynamic_cast<TemplateLookAndFeel*>(&getLookAndFeel()))
        lnf->drawCachedMainBackground(g);
    else
        g.fillAll(getLookAndFeel().findColour(juce::ResizableWindow::backgroundColourId));
}

void TemplateAudioProcessorEditor::resized() {
    panel.setBounds(getLocalBounds()); // Expand panel to fill the entire client area
    if (auto* lnf = dynamic_cast<TemplateLookAndFeel*>(&getLookAndFeel()))
        lnf->generateMainBackground(getWidth(), getHeight());
}

#include <iostream>
#include <iomanip>
#include <cmath>

// Assume necessary headers like <Teuchos_RCP.hpp>, <Teuchos_ParameterList.hpp>,
// <MeshManager_Brick.hpp>, <Intrepid2_Basis_HCURL_HEX_I1_FEM.hpp>,
// <Intrepid2_DefaultCubatureFactory.hpp>, <shards_CellTopology.hpp>,
// <ROL_Ptr.hpp>, <Kokkos_Core.hpp>, and custom FE_CURL are included elsewhere.

int main() {
  int errorFlag = 0;
  std::ostream* outStream = &std::cout;

  try {
    // Load parameters from XML file
    std::string config_file = "input_05.xml";
    Teuchos::RCP<Teuchos::ParameterList> params
      = Teuchos::rcp( new Teuchos::ParameterList() );
    Teuchos::updateParametersFromXmlFile(config_file, params.ptr());

    /*** Initialize mesh / degree-of-freedom manager. ***/
    MeshManager_Brick<double, Kokkos::DefaultExecutionSpace> mesh_manager(*params);
    auto node_coords = mesh_manager.getNodes();
    auto connectivity = mesh_manager.getCellToNodeMap();

    *outStream << "Total nodes: " << mesh_manager.getNumNodes() << "\n";
    *outStream << "Total cells: " << mesh_manager.getNumCells() << "\n";
    *outStream << "Total edges: " << mesh_manager.getNumEdges() << "\n";

    ROL::Ptr<MeshManager<double, Kokkos::DefaultExecutionSpace>> mesh_ptr
      = ROL::makePtrFromRef(mesh_manager);

    // Define basis and cubature
    using RealType = double;
    using DeviceType = Kokkos::DefaultExecutionSpace;
    using BasisPtr = ROL::Ptr<Intrepid2::Basis<DeviceType, RealType, RealType>>;

    BasisPtr hcurl_basis
      = ROL::makePtr<Intrepid2::Basis_HCURL_HEX_I1_FEM<DeviceType, RealType, RealType>>();

    shards::CellTopology cell_topology = hcurl_basis->getBaseCellTopology();
    Intrepid2::DefaultCubatureFactory factory;
    int integration_order = 4;
    auto cubature = factory.create<DeviceType, RealType, RealType>(cell_topology, integration_order);

    // Allocate and populate cell node coordinates
    auto num_cells = mesh_manager.getNumCells();
    unsigned num_nodes_per_cell = cell_topology.getNodeCount();
    unsigned space_dim = cell_topology.getDimension();

    Kokkos::View<RealType***, DeviceType> cell_node_coords("cell_node_coords",
        num_cells, num_nodes_per_cell, space_dim);

    for (int c = 0; c < num_cells; ++c) {
      for (unsigned n = 0; n < num_nodes_per_cell; ++n) {
        for (unsigned d = 0; d < space_dim; ++d) {
          cell_node_coords(c, n, d) = node_coords(connectivity(c, n), d);
        }
      }
    }

    // Construct finite element object
    FE_CURL<RealType, DeviceType> fe_obj(cell_node_coords, hcurl_basis, cubature);

    // Prepare views for evaluation
    unsigned num_quad_points = cubature->getNumPoints();
    unsigned cub_dim = cubature->getDimension();
    unsigned num_basis = hcurl_basis->getCardinality();

    Kokkos::View<RealType***, DeviceType> vals1("vals1", num_cells, num_quad_points, cub_dim);
    Kokkos::View<RealType***, DeviceType> vals2("vals2", num_cells, num_quad_points, cub_dim);
    Kokkos::View<RealType***, DeviceType> curls1("curls1", num_cells, num_quad_points, cub_dim);
    Kokkos::View<RealType***, DeviceType> curls2("curls2", num_cells, num_quad_points, cub_dim);
    Kokkos::View<RealType**, DeviceType> coeffs1("coeffs1", num_cells, num_basis);
    Kokkos::View<RealType**, DeviceType> coeffs2("coeffs2", num_cells, num_basis);
    Kokkos::View<RealType*, DeviceType> integrals("integrals", num_cells);

    // Initialize coefficients
    Kokkos::deep_copy(coeffs1, static_cast<RealType>(0));
    Kokkos::deep_copy(coeffs2, static_cast<RealType>(0));

    for (int c = 0; c < num_cells; ++c) {
      coeffs1(c, 0) = static_cast<RealType>(1);
      coeffs2(c, 0) = static_cast<RealType>(1);
    }

    // Evaluate values and compute integral
    fe_obj.evaluateValue(vals1, coeffs1);
    fe_obj.evaluateValue(vals2, coeffs2);
    fe_obj.computeIntegral(integrals, vals1, vals2);

    RealType valval_integral = 0;
    for (int c = 0; c < num_cells; ++c) {
      valval_integral += integrals(c);
    }

    if (std::abs(valval_integral - static_cast<RealType>(4)/static_cast<RealType>(9))
        > std::sqrt(ROL::ROL_EPSILON<RealType>())) {
      errorFlag = -1;
    }

    // Evaluate curls and compute integral
    fe_obj.evaluateCurl(curls1, coeffs1);
    fe_obj.evaluateCurl(curls2, coeffs2);
    fe_obj.computeIntegral(integrals, curls1, curls2);

    RealType curlcurl_integral = 0;
    for (int c = 0; c < num_cells; ++c) {
      curlcurl_integral += integrals(c);
    }

    if (std::abs(curlcurl_integral - static_cast<RealType>(8)/static_cast<RealType>(3))
        > std::sqrt(ROL::ROL_EPSILON<RealType>())) {
      errorFlag = -1;
    }

    *outStream << std::setprecision(14)
               << "\nvalue_integral=" << valval_integral
               << "  curl_curl_integral=" << curlcurl_integral << "\n";

  } catch (const std::logic_error& e) {
    *outStream << "Exception caught: " << e.what() << "\n";
    errorFlag = -1000;
  }

  if (errorFlag != 0)
    std::cout << "End Result: TEST FAILED\n";
  else
    std::cout << "End Result: TEST PASSED\n";

  return 0;
}

#include <vector>
using namespace std;

// Generate all subset sums recursively 
void calculateSubsets(vector<int>& input, int pos, int size, int currentSum, vector<int>& result) {

    // Termination condition
    if (pos == size) {
        result.push_back(currentSum);
        return;
    }

    // Include current element and proceed
    calculateSubsets(input, pos + 1, size, currentSum + input[pos], result);
    // Exclude current element and proceed
    calculateSubsets(input, pos + 1, size, currentSum, result);
}

vector<int> generateSubsetSums(vector<int>& inputArray) {
    // Initialize result container

    vector<int> output;
    calculateSubsets(inputArray, 0, inputArray.size(), 0, output);
    return output;
}

