#include <iostream>
#include <vector>
#include <string>
#include <set>
#include <algorithm>

// Process one test case scenario
void process_case() {
    int count;
    std::cin >> count;
    std::set<std::string> collected_words;

    // Try each letter from 'a' to 'z' as prefix
    for (char ch = 'a'; ch <= 'z'; ++ch) {
        if (collected_words.size() == count) {
            break;
        }

        std::string base(1, ch);
        int request_size = 1;

        // Exponential search to find all words starting with current prefix
        while (true) {
            if (collected_words.size() == count) {
                break;
            }

            std::cout << "ask " << base << " " << request_size << std::endl;
            int actual_count;
            std::cin >> actual_count;

            for (int idx = 0; idx < actual_count; ++idx) {
                std::string term;
                std::cin >> term;
                collected_words.insert(term);
            }

            // If we received fewer words than requested, no more exist for this prefix
            if (actual_count < request_size) {
                break;
            }

            // Safety check: if we asked for 'count' and got 'count', we have all words
            if (request_size == count) {
                break;
            }

            // Increase query size exponentially
            request_size *= 2;
            if (request_size > count) {
                request_size = count;
            }
        }
    }

    // Print the result
    std::cout << "result";
    for (const auto& item : collected_words) {
        std::cout << " " << item;
    }
    std::cout << std::endl;
}

int main() {
    // Optimize I/O operations
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int test_cases;
    std::cin >> test_cases;

    while (test_cases-- > 0) {
        process_case();
    }

    return 0;
}

