// Cancel the ongoing image decoding process
void StaticIODeviceImageLoader::cancelOperation() const {
  if (m_resource) { BackgroundImageDecoder::instance()->abort(m_resource->identifier()); }
}

// Decode and render the image using the provided configuration
void StaticIODeviceImageLoader::process(const RenderConfig &settings) {
  // TODO: support rendering with a different config instead of ignoring it
  m_resource = BackgroundImageDecoder::instance()->process(std::move(m_buffer), settings);
  connect(m_resource.get(), &BackgroundImageDecodeResponse::imageReady, this,
          [this](const QPixmap &image) { emit contentChanged(image); });
}

