void tst_QMcpPromptMessageContent::copyCtor()
{
    // Create original with text
    QMcpPromptMessageContent src;
    QMcpTextContent txt;
    txt.setText("Original message");
    src.setTextContent(txt);

    // Test copy constructor
    QMcpPromptMessageContent dst(src);
    QCOMPARE(dst.refType(), "textContent"_ba);
    QCOMPARE(dst.textContent().text(), "Original message"_L1);

    // Modify original and verify independence
    QMcpTextContent newTxt;
    newTxt.setText("Changed message");
    src.setTextContent(newTxt);
    QCOMPARE(dst.textContent().text(), "Original message"_L1);
    QCOMPARE(src.textContent().text(), "Changed message"_L1);
}

