#include "gtest/gtest.h"
#include "core/demangler.hpp"
#include <cstring>
#include <string>

struct mock_demangle_backend
{
    static inline int invocation_counter = 0;
    static char* perform_demangling(const char* mangled_symbol, char*, size_t*, int* status)
    {
        ++invocation_counter;
        if(std::string(mangled_symbol).find("ERROR") != std::string::npos)
        {
            *status = -1;
            return nullptr;
        }
        std::string output_value = "unmangled_" + std::string(mangled_symbol);
        char*       buffer       = static_cast<char*>(std::malloc(output_value.size() + 1));
        memcpy(buffer, output_value.c_str(), output_value.size() + 1);
        *status = 0;
        return buffer;
    }
};

class demangle_test_suite : public ::testing::Test
{
protected:
    void SetUp() override { mock_demangle_backend::invocation_counter = 0; }
};

TEST_F(demangle_test_suite, basic_success_case)
{
    rocprofsys::utility::demangler<mock_demangle_backend> demangler_obj;
    std::string result = demangler_obj.demangle("symbol");
    EXPECT_EQ(result, "unmangled_symbol");
    EXPECT_EQ(mock_demangle_backend::invocation_counter, 1);
}

TEST_F(demangle_test_suite, failure_returns_original_input)
{
    rocprofsys::utility::demangler<mock_demangle_backend> demangler_obj;
    std::string result = demangler_obj.demangle("symbol_ERROR");
    EXPECT_EQ(result, "symbol_ERROR");
    EXPECT_EQ(mock_demangle_backend::invocation_counter, 1);
}

TEST_F(demangle_test_suite, empty_input_yields_empty_output)
{
    rocprofsys::utility::demangler<mock_demangle_backend> demangler_obj;
    std::string result = demangler_obj.demangle("");
    EXPECT_TRUE(result.empty());
    EXPECT_EQ(mock_demangle_backend::invocation_counter, 0);
}

TEST_F(demangle_test_suite, caching_avoids_duplicate_calls)
{
    rocprofsys::utility::demangler<mock_demangle_backend> demangler_obj;
    std::string first  = demangler_obj.demangle("symbol");
    std::string second = demangler_obj.demangle("symbol");
    std::string third  = demangler_obj.demangle("symbol");
    EXPECT_EQ(first, "unmangled_symbol");
    EXPECT_EQ(first, second);
    EXPECT_EQ(second, third);
    EXPECT_EQ(mock_demangle_backend::invocation_counter, 1);
}

TEST_F(demangle_test_suite, distinct_inputs_use_separate_cache_entries)
{
    rocprofsys::utility::demangler<mock_demangle_backend> demangler_obj;
    std::string val1          = demangler_obj.demangle("symbolA");
    std::string val2          = demangler_obj.demangle("symbolB");
    std::string val1_repeated = demangler_obj.demangle("symbolA");
    EXPECT_EQ(val1, "unmangled_symbolA");
    EXPECT_EQ(val2, "unmangled_symbolB");
    EXPECT_EQ(val1, val1_repeated);
    EXPECT_EQ(mock_demangle_backend::invocation_counter, 2);
}

TEST_F(demangle_test_suite, string_view_support)
{
    rocprofsys::utility::demangler<mock_demangle_backend> demangler_obj;
    std::string str_val = "symbol";
    std::string_view sv{ str_val };
    std::string result = demangler_obj.demangle(sv);
    EXPECT_EQ(result, "unmangled_symbol");
    EXPECT_EQ(mock_demangle_backend::invocation_counter, 1);
}

TEST_F(demangle_test_suite, template_based_demangle)
{
    rocprofsys::utility::demangler<mock_demangle_backend> demangler_obj;
    std::string result = demangler_obj.demangle<int>();
    EXPECT_NE(result.find("unmangled_"), std::string::npos);
    EXPECT_FALSE(result.empty());
}

TEST_F(demangle_test_suite, failed_demangle_cached_correctly)
{
    rocprofsys::utility::demangler<mock_demangle_backend> demangler_obj;
    std::string first  = demangler_obj.demangle("ERROR");
    std::string second = demangler_obj.demangle("ERROR");
    EXPECT_EQ(first, "ERROR");
    EXPECT_EQ(first, second);
    EXPECT_EQ(mock_demangle_backend::invocation_counter, 1);
}

TEST_F(demangle_test_suite, separate_instances_have_independent_caches)
{
    rocprofsys::utility::demangler<mock_demangle_backend> instance_a;
    rocprofsys::utility::demangler<mock_demangle_backend> instance_b;
    instance_a.demangle("symbol");
    instance_b.demangle("symbol");
    EXPECT_EQ(mock_demangle_backend::invocation_counter, 2);
}

