/*-------------------------------------------------------------------------
 * Function:	H5G_loc_lookup_cb
 *
 * Purpose:	Callback for retrieving object location for an object in a group
 *
 * Return:	Non-negative on success/Negative on failure
 *
 * Programmer:	Quincey Koziol
 *              Monday, October 17, 2005
 *
 *-------------------------------------------------------------------------
 */
static herr_t
H5G_loc_lookup_cb(H5G_loc_t H5_ATTR_UNUSED *grp_loc/*in*/, const char *symbol,
    const H5O_link_t H5_ATTR_UNUSED *lnk, H5G_loc_t *obj_loc, void *_udata/*in,out*/,
    H5G_own_loc_t *own_loc/*out*/)
{
    H5G_loc_fnd_t *data = (H5G_loc_fnd_t *)_udata;   /* User data passed in */
    herr_t result = SUCCEED;            /* Return value */
    FUNC_ENTER_NOAPI_NOINIT
    /* Check if the name in this group resolved to a valid object */
    if(obj_loc == NULL)
        HGOTO_ERROR(H5E_SYM, H5E_NOTFOUND, FAIL, "object '%s' doesn't exist", symbol)
    /* Take ownership of the object's group location */
    /* (Group traversal callbacks are responsible for either taking ownership
     *  of the group location for the object, or freeing it. - QAK)
     */
    H5G__loc_copy(data->location, obj_loc, H5_COPY_SHALLOW);
    *own_loc = H5G_OWN_OBJ_LOC;
done:
    FUNC_LEAVE_NOAPI(result)
} /* end H5G_loc_lookup_cb() */

/*-------------------------------------------------------------------------
 * Function:	H5G_locate_find
 *
 * Purpose:	Find a symbol from a location
 *
 * Return:	Non-negative on success/Negative on failure
 *
 * Programmer:	Quincey Koziol
 *		Tuesday, September 13, 2005
 *
 *-------------------------------------------------------------------------
 */
herr_t
H5G_locate_find(const H5G_loc_t *location, const char *symbol, H5G_loc_t *obj_loc/*out*/,
    hid_t lapl_id, hid_t dxpl_id)
{
    H5G_loc_fnd_t udata;                /* User data for traversal callback */
    herr_t ret_value = SUCCEED;         /* Return value */
    FUNC_ENTER_NOAPI(FAIL)
    /* Check args. */
    HDassert(location);
    HDassert(symbol && *symbol);
    HDassert(obj_loc);
    /* Set up user data for locating object */
    udata.location = obj_loc;
    /* Traverse group hierarchy to locate object */
    if(H5G_traverse(location, symbol, H5G_TARGET_NORMAL, H5G_loc_lookup_cb, &udata, lapl_id, dxpl_id) < 0)
        HGOTO_ERROR(H5E_SYM, H5E_NOTFOUND, FAIL, "can't find object")
done:
    FUNC_LEAVE_NOAPI(ret_value)
} /* end H5G_locate_find() */

/*-------------------------------------------------------------------------
 * Function:	H5G_loc_lookup_by_idx_cb
 *
 * Purpose:	Callback for retrieving object location for an object in a group
 *              according to the order within an index
 *
 * Return:	Non-negative on success/Negative on failure
 *
 * Programmer:	Quincey Koziol
 *              Monday, November 20, 2006
 *
 *-------------------------------------------------------------------------
 */
static herr_t
H5G_loc_lookup_by_idx_cb(H5G_loc_t H5_ATTR_UNUSED *grp_loc/*in*/, const char H5_ATTR_UNUSED *symbol,
    const H5O_link_t H5_ATTR_UNUSED *lnk, H5G_loc_t *obj_loc, void *_udata/*in,out*/,
    H5G_own_loc_t *own_loc/*out*/)
{
    H5G_loc_fbi_t *data = (H5G_loc_fbi_t *)_udata;   /* User data passed in */
    H5O_link_t found_lnk;               /* Link within group */
    hbool_t lnk_copied = FALSE;         /* Whether the link was copied */
    size_t links_remaining = H5L_NUM_LINKS;  /* # of links left to traverse */
    hbool_t obj_loc_valid = FALSE;      /* Flag to indicate that the object location is valid */
    hbool_t obj_exists = FALSE;         /* Whether the object exists (unused) */
    herr_t result = SUCCEED;            /* Return value */
    FUNC_ENTER_NOAPI_NOINIT
    /* Check if the name in this group resolved to a valid link */
    if(obj_loc == NULL)
        HGOTO_ERROR(H5E_SYM, H5E_NOTFOUND, FAIL, "group doesn't exist")
    /* Query link */
    if(H5G_obj_lookup_by_idx(obj_loc->oloc, data->idx_type, data->order,
                data->offset, &found_lnk, data->dxpl_id) < 0)
        HGOTO_ERROR(H5E_SYM, H5E_NOTFOUND, FAIL, "link not found")
    lnk_copied = TRUE;
    /* Build the initial object location for the link */
    if(H5G__link_to_loc(obj_loc, &found_lnk, data->location) < 0)
        HGOTO_ERROR(H5E_SYM, H5E_CANTINIT, FAIL, "cannot initialize object location")
    obj_loc_valid = TRUE;
    /* Perform any special traversals that the link needs */
    /* (soft links, user-defined links, file mounting, etc.) */
    /* (may modify the object location) */
    if(H5G__traverse_special(obj_loc, &found_lnk, H5G_TARGET_NORMAL, &links_remaining, TRUE, data->location, &obj_exists, data->lapl_id, data->dxpl_id) < 0)
        HGOTO_ERROR(H5E_LINK, H5E_TRAVERSE, FAIL, "special link traversal failed")
done:
    /* Reset the link information, if we have a copy */
    if(lnk_copied)
        H5O_msg_reset(H5O_LINK_ID, &found_lnk);
    /* Release the object location if we failed after copying it */
    if(result < 0 && obj_loc_valid)
        if(H5G_locate_release(data->location) < 0)
            HDONE_ERROR(H5E_SYM, H5E_CANTRELEASE, FAIL, "can't free location")
    /* Indicate that this callback didn't take ownership of the group *
     * location for the object */
    *own_loc = H5G_OWN_NONE;
    FUNC_LEAVE_NOAPI(result)
} /* end H5G_loc_lookup_by_idx_cb() */

/*-------------------------------------------------------------------------
 * Function:	H5G_locate_find_by_idx
