 * Purpose:	Find a symbol from a location, according to the order in an index
 *
 * Return:	Non-negative on success/Negative on failure
 *
 * Programmer:	Quincey Koziol
 *		Monday, November 20, 2006
 *
 *-------------------------------------------------------------------------
 */
herr_t
H5G_locate_find_by_idx(H5G_loc_t *location, const char *group_name, H5_index_t idx_type,
    H5_iter_order_t order, hsize_t offset, H5G_loc_t *obj_loc/*out*/, hid_t lapl_id,
    hid_t dxpl_id)
{
    H5G_loc_fbi_t udata;                /* User data for traversal callback */
    herr_t ret_value = SUCCEED;         /* Return value */
    FUNC_ENTER_NOAPI(FAIL)
    /* Check args. */
    HDassert(location);
    HDassert(group_name && *group_name);
    HDassert(obj_loc);
    /* Set up user data for locating object */
    udata.dxpl_id = dxpl_id;
    udata.lapl_id = lapl_id;
    udata.idx_type = idx_type;
    udata.order = order;
    udata.offset = offset;
    udata.location = obj_loc;
    /* Traverse group hierarchy to locate object */
    if(H5G_traverse(location, group_name, H5G_TARGET_NORMAL, H5G_loc_lookup_by_idx_cb, &udata, lapl_id, dxpl_id) < 0)
        HGOTO_ERROR(H5E_SYM, H5E_NOTFOUND, FAIL, "can't find object")
done:
    FUNC_LEAVE_NOAPI(ret_value)
} /* end H5G_locate_find_by_idx() */

/*-------------------------------------------------------------------------
 * Function:	H5G__locate_insert
 *
 * Purpose:	Insert an object at a location
 *
 * Return:	Non-negative on success/Negative on failure
 *
 * Programmer:	Quincey Koziol
 *		Tuesday, September 13, 2005
 *
 *-------------------------------------------------------------------------
 */
herr_t
H5G__locate_insert(H5G_loc_t *grp_loc, const char *symbol, H5G_loc_t *obj_loc,
    H5O_type_t obj_type, const void *crt_info, hid_t dxpl_id)
{
    H5O_link_t  lnk;                    /* Link for object to insert */
    herr_t      result = SUCCEED;       /* Return value */
    FUNC_ENTER_PACKAGE
    /* Check args. */
    HDassert(grp_loc);
    HDassert(symbol && *symbol);
    HDassert(obj_loc);
    /* Create link object for the object location */
    lnk.type = H5L_TYPE_HARD;
    lnk.cset = H5F_DEFAULT_CSET;
    lnk.corder = 0;     /* Will be reset if the group is tracking creation order */
    lnk.corder_valid = FALSE;   /* Indicate that the creation order isn't valid (yet) */
    /* Casting away const OK -QAK */
    lnk.name = (char *)symbol;
    lnk.u.hard.addr = obj_loc->oloc->addr;
    /* Insert new group into current group's symbol table */
    if(H5G_obj_insert(grp_loc->oloc, symbol, &lnk, TRUE, obj_type, crt_info,
            dxpl_id) < 0)
        HGOTO_ERROR(H5E_SYM, H5E_CANTINSERT, FAIL, "unable to insert object")
    /* Set the name of the object location */
    if(H5G_name_set(grp_loc->path, obj_loc->path, symbol) < 0)
       HGOTO_ERROR(H5E_SYM, H5E_CANTINIT, FAIL, "cannot set name")
done:
    FUNC_LEAVE_NOAPI(result)
} /* end H5G__locate_insert() */

/*-------------------------------------------------------------------------
 * Function:	H5G_loc_exists_cb
 *
 * Purpose:	Callback for checking if an object exists
 *
 * Return:	Non-negative on success/Negative on failure
 *
 * Programmer:	Quincey Koziol
 *              Tuesday, February 2, 2010
 *
 *-------------------------------------------------------------------------
 */
static herr_t
H5G_loc_exists_cb(H5G_loc_t H5_ATTR_UNUSED *grp_loc/*in*/, const char H5_ATTR_UNUSED *symbol,
    const H5O_link_t H5_ATTR_UNUSED *lnk, H5G_loc_t *obj_loc, void *_udata/*in,out*/,
    H5G_own_loc_t *own_loc/*out*/)
{
    H5G_loc_exists_t *data = (H5G_loc_exists_t *)_udata;   /* User data passed in */
    FUNC_ENTER_NOAPI_NOINIT_NOERR
    /* Check if the name in this group resolved to a valid object */
    if(obj_loc == NULL)
        if(lnk)
            data->found = FALSE;
        else
            data->found = FAIL;
    else
        data->found = TRUE;
    /* Indicate that this callback didn't take ownership of the group *
     * location for the object */
    *own_loc = H5G_OWN_NONE;
    FUNC_LEAVE_NOAPI(SUCCEED)
} /* end H5G_loc_exists_cb() */

/*-------------------------------------------------------------------------
 * Function:	H5G_locate_exists
 *
 * Purpose:	Check if an object actually exists at a location
 *
 * Return:	Success:	TRUE/FALSE
 * 		Failure:	Negative
 *
 * Programmer:	Quincey Koziol
 *		Tuesday, February 2, 2010
 *
 *-------------------------------------------------------------------------
 */
htri_t
H5G_locate_exists(const H5G_loc_t *location, const char *symbol, hid_t lapl_id, hid_t dxpl_id)
{
    H5G_loc_exists_t udata;     /* User data for traversal callback */
    htri_t ret_value;           /* Return value */
    FUNC_ENTER_NOAPI(FAIL)
    /* Check args. */
    HDassert(location);
    HDassert(symbol && *symbol);
    /* Set up user data for locating object */
    udata.found = FALSE;
    /* Traverse group hierarchy to locate object */
    if(H5G_traverse(location, symbol, H5G_TARGET_EXISTS, H5G_loc_exists_cb, &udata, lapl_id, dxpl_id) < 0)
        HGOTO_ERROR(H5E_SYM, H5E_NOTFOUND, FAIL, "can't check if object exists")
    /* Set return value */
    ret_value = udata.found;
done:
    FUNC_LEAVE_NOAPI(ret_value)
} /* end H5G_locate_exists() */

