/*-------------------------------------------------------------------------
 * Function:	H5G_loc_retrieve_comment_cb
 *
 * Purpose:	Callback for retrieving object comment for an object in a group
 *
 * Return:	Non-negative on success/Negative on failure
 *
 * Programmer:	Quincey Koziol
 *              Thursday, August 30, 2007
 *
 *-------------------------------------------------------------------------
 */
static herr_t
H5G_loc_retrieve_comment_cb(H5G_loc_t H5_ATTR_UNUSED *grp_loc/*in*/, const char H5_ATTR_UNUSED *symbol, const H5O_link_t H5_ATTR_UNUSED *lnk,
    H5G_loc_t *obj_loc, void *_udata/*in,out*/, H5G_own_loc_t *own_loc/*out*/)
{
    H5G_loc_gc_t *data = (H5G_loc_gc_t *)_udata;   /* User data passed in */
    H5O_name_t comment;                 /* Object header "comment" message */
    herr_t result = SUCCEED;            /* Return value */
    FUNC_ENTER_NOAPI_NOINIT
    /* Check if the name in this group resolved to a valid link */
    if(obj_loc == NULL)
        HGOTO_ERROR(H5E_SYM, H5E_NOTFOUND, FAIL, "name doesn't exist")
    /* Query object comment */
    comment.s = NULL;
    if(NULL == H5O_msg_read(obj_loc->oloc, H5O_NAME_ID, &comment, data->dxpl_id)) {
	if(data->buffer_comment && data->buf_size > 0)
            data->buffer_comment[0] = '\0';
	data->actual_comment_size = 0;
    } else {
        if(data->buffer_comment && data->buf_size)
	   HDstrncpy(data->buffer_comment, comment.s, data->buf_size);
	data->actual_comment_size = (ssize_t)HDstrlen(comment.s);
	H5O_msg_reset(H5O_NAME_ID, &comment);
    } /* end else */
done:
    /* Indicate that this callback didn't take ownership of the group *
     * location for the object */
    *own_loc = H5G_OWN_NONE;
    FUNC_LEAVE_NOAPI(result)
} /* end H5G_loc_retrieve_comment_cb() */

/*-------------------------------------------------------------------------
 * Function:	H5G_locate_get_comment
 *
 * Purpose:	Retrieve the information for an object from a group location
 *              and path to that object
 *
 * Return:	Success:	Number of bytes in the comment excluding the
 *				null terminator.  Zero if the object has no
 *				comment.
 *
 *		Failure:	Negative
 *
 * Programmer:	Quincey Koziol
 *		Thursday, August 30, 2007
 *
 *-------------------------------------------------------------------------
 */
ssize_t
H5G_locate_get_comment(H5G_loc_t *location, const char *symbol, char *comment/*out*/,
    size_t bufsize, hid_t lapl_id, hid_t dxpl_id)
{
    H5G_loc_gc_t udata;         /* User data for traversal callback */
    ssize_t ret_value;          /* Return value */
    FUNC_ENTER_NOAPI(FAIL)
    /* Check args. */
    HDassert(location);
    HDassert(symbol && *symbol);
    /* Set up user data for locating object */
    udata.dxpl_id = dxpl_id;
    udata.buffer_comment = comment;
    udata.buf_size = bufsize;
    udata.actual_comment_size = (-1);
    /* Traverse group hierarchy to locate object */
    if(H5G_traverse(location, symbol, H5G_TARGET_NORMAL, H5G_loc_retrieve_comment_cb, &udata, lapl_id, dxpl_id) < 0)
        HGOTO_ERROR(H5E_SYM, H5E_NOTFOUND, FAIL, "can't find object")
    /* Set the return value */
    ret_value = udata.actual_comment_size;
done:
    FUNC_LEAVE_NOAPI(ret_value)
} /* end H5G_locate_get_comment() */

