// A custom hash function based on jenkins_one_at_a_time_hash,
// initialized with a non-zero value so that custom_hash(0) != 0.
static uint32_t custom_hash(const uint8_t *input, size_t length) {
  uint32_t state = 0x7A4B2C1D;  // Non-zero initial seed
  for (size_t idx = 0; idx < length; ++idx) {
    state += input[idx];
    state += (state << 13);
    state ^= (state >> 7);
  }
  state += (state << 5);
  state ^= (state >> 12);
  state += (state << 14);
  return state;
}

extern "C" int LLVMFuzzerTestOneInput(const uint8_t *buffer, size_t len) {
  if (len < 18)
    return 0;

  uint32_t computed = custom_hash(&buffer[0], len - 4);
  uint32_t expected = reinterpret_cast<const uint32_t *>(&buffer[len - 4])[0];

  if (computed != expected)
    return 0;

  fprintf(stderr, "SUCCESS: custom_hash matched! %x == %x\n", 
          static_cast<unsigned int>(computed),
          static_cast<unsigned int>(expected));
  abort();
  return 0;
}

#include "group_sum_matrix.h"
template <typename T>
IGL_INLINE void igl::group_sum_matrix(
  const Eigen::Matrix<int,Eigen::Dynamic,1> & group_ids,
  const int num_groups,
  Eigen::SparseMatrix<T>& A)
{
  // number of vertices
  int vertex_count = group_ids.rows();
  assert(num_groups > group_ids.maxCoeff());
  A.resize(num_groups, vertex_count);

  // builds A such that A(i,j) = 1 where i corresponds to group i and j
  // corresponds to vertex j
  // Loop over vertices
  for(int v = 0; v < vertex_count; v++)
  {
    A.insert(group_ids(v), v) = 1;
  }

  A.makeCompressed();
}

template <typename T>
IGL_INLINE void igl::group_sum_matrix(
  const Eigen::Matrix<int,Eigen::Dynamic,1> & group_ids,
  Eigen::SparseMatrix<T>& A)
{
  return group_sum_matrix(group_ids, group_ids.maxCoeff() + 1, A);
}

