#include <vector>
#include <queue>
using namespace std;

class Solution {
public:
    vector<int> maxSlidingWindow(vector<int>& data, int windowSize) {
        vector<int> output;
        priority_queue<pair<int, int>> pq;

        // Initialize with the first 'windowSize' elements
        for(int idx = 0; idx < windowSize; idx++) {
            pq.push({data[idx], idx});
        }

        // Store maximum of first window
        output.push_back(pq.top().first);

        // Slide the window through the rest of the array
        for(int pos = windowSize; pos < data.size(); pos++) {
            // Add current element to heap
            pq.push({data[pos], pos});

            // Remove elements outside current window
            while(!pq.empty() && pq.top().second <= pos - windowSize) {
                pq.pop();
            }

            // Record maximum value of current window
            output.push_back(pq.top().first);
        }

        return output;
    }
};

