class P2pTests : public ::testing::Test {
protected:
  int deviceCount;
  std::vector<hipDeviceProp_t> props;
  ncclProxyConnection connection;
  ncclProxyState proxyState;
  ncclProxyArgs args;
  p2pShmProxyInfo *proxyInfo;

