struct Reference_WDF
{
    // Resistor combinations
    chowdsp::wdft::ResistorT<float> R_1 { 2.0e3f };
    chowdsp::wdft::ResistorT<float> R_2 { 6.0e3f };
    chowdsp::wdft::WDFSeriesT<float, decltype(R_1), decltype(R_2)> S_1 { R_1, R_2 };
    chowdsp::wdft::ResistorT<float> R_3 { 5.0e3f };
    chowdsp::wdft::WDFSeriesT<float, decltype(S_1), decltype(R_3)> S_2 { S_1, R_3 };
    chowdsp::wdft::ResistorT<float> R_4 { 12.0e3f };
    chowdsp::wdft::ResistorT<float> R_5 { 4.0e3f };
    chowdsp::wdft::WDFParallelT<float, decltype(R_4), decltype(R_5)> P_1 { R_4, R_5 };
    chowdsp::wdft::WDFParallelT<float, decltype(S_2), decltype(P_1)> P_2 { S_2, P_1 };

    // Capacitor combinations
    chowdsp::wdft::CapacitorT<float> C_1 { 2.0e-6f };
    chowdsp::wdft::CapacitorT<float> C_2 { 6.0e-6f };
    chowdsp::wdft::WDFSeriesT<float, decltype(C_1), decltype(C_2)> S_4 { C_1, C_2 };
    chowdsp::wdft::CapacitorT<float> C_3 { 5.0e-9f };
    chowdsp::wdft::WDFSeriesT<float, decltype(S_4), decltype(C_3)> S_5 { S_4, C_3 };
    chowdsp::wdft::CapacitorT<float> C_4 { 12.0e-9f };
    chowdsp::wdft::CapacitorT<float> C_5 { 4.0e-6f };
    chowdsp::wdft::WDFParallelT<float, decltype(C_4), decltype(C_5)> P_3 { C_4, C_5 };
    chowdsp::wdft::WDFParallelT<float, decltype(S_5), decltype(P_3)> P_4 { S_5, P_3 };

    // Join resistor and capacitor combos
    chowdsp::wdft::WDFSeriesT<float, decltype(P_2), decltype(P_4)> S_3 { P_2, P_4 };

    // RCSeries + R
    chowdsp::wdft::ResistorT<float> R_6 { 12.0e3f };
    chowdsp::wdft::WDFSeriesT<float, decltype(S_3), decltype(R_6)> S_6 { S_3, R_6 };

    // RCSeries + C
    chowdsp::wdft::CapacitorT<float> C_6 { 5.0e-6f };
    chowdsp::wdft::WDFSeriesT<float, decltype(S_6), decltype(C_6)> S_7 { S_6, C_6 };

    // RCParallel
    chowdsp::wdft::ResistorT<float> R_7 { 12.0e3f };
    chowdsp::wdft::CapacitorT<float> C_7 { 12.0e-6f };
    chowdsp::wdft::WDFParallelT<float, decltype(R_7), decltype(C_7)> P_5 { R_7, C_7 };

    // RCParallel + R
    chowdsp::wdft::ResistorT<float> R_8 { 120.0e3f };
    chowdsp::wdft::WDFParallelT<float, decltype(P_5), decltype(R_8)> P_6 { P_5, R_8 };

    // RCParallel + C
    chowdsp::wdft::CapacitorT<float> C_8 { 120.0e-9f };
    chowdsp::wdft::WDFParallelT<float, decltype(P_6), decltype(C_8)> P_7 { P_6, C_8 };

    // RCSeries + RCParallel
    chowdsp::wdft::WDFSeriesT<float, decltype(S_7), decltype(P_7)> S_8 { S_7, P_7 };

    // Load
    chowdsp::wdft::ResistorT<float> R_load { 120.0e3f };
    chowdsp::wdft::WDFSeriesT<float, decltype(R_load), decltype(S_8)> S_load { R_load, S_8 };

    chowdsp::wdft::ResistorT<float> R_volt2 { 6.0e3f };
    chowdsp::wdft::WDFSeriesT<float, decltype(R_volt2), decltype(S_load)> S_volt2 { R_volt2, S_load };

    chowdsp::wdft::ResistorT<float> R_volt1 { 12.0e3f };
    chowdsp::wdft::WDFSeriesT<float, decltype(R_volt1), decltype(S_volt2)> S_volt1 { R_volt1, S_volt2 };

    chowdsp::wdft::IdealVoltageSourceT<float, decltype(S_volt1)> Vin_source { S_volt1 };

    void prepare(float sample_rate)
    {
        // No-op in reference implementation
    }

    float process(float input_voltage)
    {
        Vin_source.setVoltage(input_voltage);
        Vin_source.incident(S_volt1.reflected());
        S_volt1.incident(Vin_source.reflected());
        return chowdsp::wdft::voltage<float>(R_load);
    }
};

int main()
{
    std::cout << "Reductions Circuit Validation\n";
    static constexpr float sampling_freq = 48000.0f;
    Reference_WDF ref_impl {};
    ref_impl.prepare(sampling_freq);

    Impedances imp_data {};
    calc_impedances(
        imp_data,
        sampling_freq,
        {
            .R2_val = ref_impl.R_2.wdf.R,
            .R4_val = ref_impl.R_4.wdf.R,
            .C2_val = ref_impl.C_2.C_value,
            .C4_val = ref_impl.C_4.C_value,
        });

    State sim_state {};
    static constexpr int num_samples = 100;
    std::array<float, num_samples> reference_results {};
    float worst_error = 0.0f;

    for (int idx = 0; idx < num_samples; ++idx)
    {
        const auto test_result = process(sim_state, imp_data, 1.0f);
        reference_results[idx] = ref_impl.process(1.0f);
        const auto diff = std::abs(test_result - reference_results[idx]);
        worst_error = std::max(diff, worst_error);
    }

    std::cout << "Maximum Error: " << worst_error << '\n';
    if (worst_error > 1.0e-3f)
    {
