#include "int_lib.h"
#ifdef CRT_HAS_128BIT
// Computes the number of set bits (population count) in a 128-bit integer
COMPILER_RT_ABI int __popcountti2(ti_int input) {
  tu_int value = (tu_int)input;
  // Step 1: Subtract shifted version to compute pairwise bit counts
  value = value - ((value >> 1) &
                   (((tu_int)0x5555555555555555uLL << 64) | 0x5555555555555555uLL));

  // Step 2: Combine adjacent 2-bit sums into 4-bit groups
  value = ((value >> 2) &
           (((tu_int)0x3333333333333333uLL << 64) | 0x3333333333333333uLL)) +
          (value & (((tu_int)0x3333333333333333uLL << 64) | 0x3333333333333333uLL));

  // Step 3: Combine adjacent 4-bit sums into 8-bit groups
  value = (value + (value >> 4)) &
          (((tu_int)0x0F0F0F0F0F0F0F0FuLL << 64) | 0x0F0F0F0F0F0F0F0FuLL);

  // Step 4: Combine upper and lower 64-bit halves
  du_int half_sum = (du_int)(value + (value >> 64));

  // Step 5: Combine 32-bit halves
  su_int quarter_sum = (su_int)(half_sum + (half_sum >> 32));

  // Step 6: Combine 16-bit halves
  quarter_sum = quarter_sum + (quarter_sum >> 16);

  // Step 7: Final combination and mask to get 8-bit result
  return (quarter_sum + (quarter_sum >> 8)) & 0xFF;
}
#endif // CRT_HAS_128BIT

