// Modified Sieve of Eratosthenes for prime generation up to a custom limit
const int MAX_LIMIT = 1500000;
std::vector<int> prime_list;
bool prime_flags[MAX_LIMIT + 1];

void generate_primes() {
    std::fill(prime_flags, prime_flags + MAX_LIMIT + 1, true);
    prime_flags[0] = prime_flags[1] = false;

    for (int p = 2; p * p <= MAX_LIMIT; ++p) {
        if (prime_flags[p]) {
            for (int j = p * p; j <= MAX_LIMIT; j += p) {
                prime_flags[j] = false;
            }
        }
    }

    for (int p = 2; p <= MAX_LIMIT; ++p) {
        if (prime_flags[p]) {
            prime_list.push_back(p);
        }
    }
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    long long upper_bound;
    std::cin >> upper_bound;

    generate_primes();

    // Determine maximum sequence length using prime-based construction
    // Based on condition: (p_i + 1) * p_{i+1} <= upper_bound
    int best_index = -1;
    for (size_t idx = 0; idx + 1 < prime_list.size(); ++idx) {
        if ((__int128)(prime_list[idx] + 1) * prime_list[idx + 1] <= upper_bound) {
            best_index = static_cast<int>(idx);
        } else {
            break;
        }
    }

    if (best_index == -1) {
        // Fallback: use powers of two for small values
        std::vector<long long> result_sequence;
        long long value = 1;
        while (value <= upper_bound) {
            result_sequence.push_back(value);
            if (upper_bound / 2 < value) break;
            value *= 2;
        }

        if (result_sequence.empty()) {
            result_sequence.push_back(1);
        }

        std::cout << result_sequence.size() << "\n";
        for (size_t pos = 0; pos < result_sequence.size(); ++pos) {
            std::cout << result_sequence[pos] 
                      << (pos == result_sequence.size() - 1 ? "" : " ");
        }
        std::cout << "\n";
        return 0;
    }

    int sequence_length = best_index + 3;
    std::vector<long long> sequence(sequence_length);

    // First element: (p_1 - 1) * p_0
    sequence[0] = static_cast<long long>(prime_list[1] - 1) * prime_list[0];

    // Middle elements: p_{i-1} * p_i for i=1..sequence_length-2
    for (int pos = 1; pos < sequence_length - 1; ++pos) {
        sequence[pos] = static_cast<long long>(prime_list[pos - 1]) * prime_list[pos];
    }

    // Last element: c * p_{sequence_length-2}
    long long last_prime = prime_list[sequence_length - 2];
    long long second_last_prime = prime_list[sequence_length - 3];
    long long max_multiplier = upper_bound / last_prime;
    long long multiplier = max_multiplier;

    // Ensure gcd(c, p_{sequence_length-3}) = 1
    if (multiplier % second_last_prime == 0) {
        multiplier--;
    }
    sequence[sequence_length - 1] = multiplier * last_prime;

    std::cout << sequence_length << "\n";
    for (int pos = 0; pos < sequence_length; ++pos) {
        std::cout << sequence[pos] 
                  << (pos == sequence_length - 1 ? "" : " ");
    }
    std::cout << "\n";

    return 0;
}

