DockLayout::DockLayout()
    : m_maximizedDock(nullptr), m_decoAllocator(new DockDecoAllocator()) {}

//-------------------------------------
DockLayout::~DockLayout() {
  // Clean up Regions (separators are Widgets with parent, so they get deleted recursively)
  unsigned int i;
  for (i = 0; i < m_regions.size(); ++i) delete m_regions[i];
  // Clean up dockWidgets
  for (i = 0; i < m_items.size(); ++i) {
    // delete m_items[i]->widget();
    delete m_items[i];
  }
  // Delete decorator allocator
  delete m_decoAllocator;
}
//-------------------------------------
int DockLayout::widgetCount() const { return m_items.size(); }
//-------------------------------------
void DockLayout::addWidget(QLayoutItem *item) {
  DockWidget *newWidget = dynamic_cast<DockWidget *>(item->widget());
  // Verify added item is indeed a DockWidget type;
  assert(newWidget);
  // Check if item is already managed by layout. If so, exit.
  if (find(newWidget)) return;
  // Enforce reparenting. Required to ensure all items share same geometry() reference.
  // Also store parentLayout for convenience.
  newWidget->m_parentLayout = this;
  newWidget->setParent(parentWidget());
  // Remember reparenting resets window flags if new parent differs from current (see Qt docs).
  // First restore standard floating flags, then apply custom appearance (which may reassign flags).
  newWidget->setWindowFlags(Qt::Tool | Qt::FramelessWindowHint);
  newWidget->setFloatingAppearance();
  m_items.push_back(item);
}
//-------------------------------------
QLayoutItem *DockLayout::removeAt(int idx) {
  if (idx < 0 || idx >= (int)m_items.size()) return nullptr;
  QLayoutItem *item = m_items[idx];
  DockWidget *dw    = static_cast<DockWidget *>(item->widget());
  // If docked, undock item
  if (!dw->isFloating()) undockItem(dw);
  // Reset item's parentLayout
  dw->m_parentLayout = nullptr;
  m_items.erase(m_items.begin() + idx);
  return item;
}
//-------------------------------------
QLayoutItem *DockLayout::getLayoutItem(int idx) const {
  if (idx >= (int)m_items.size()) return nullptr;
  return m_items[idx];
}
//-------------------------------------
QWidget *DockLayout::getWidget(int idx) const { return getLayoutItem(idx)->widget(); }
//-------------------------------------
QSize DockLayout::minSize() const {
  if (!m_regions.empty()) {
    Region *r = m_regions.front();
    r->calculateExtremalSizes();
    return QSize(r->m_minimumSize[0], r->m_minimumSize[1]);
  }
  return QSize(0, 0);
}
//-------------------------------------
QSize DockLayout::maxSize() const {
  if (!m_regions.empty()) {
    Region *r = m_regions.front();
    r->calculateExtremalSizes();
    return QSize(r->m_maximumSize[0], r->m_maximumSize[1]);
  }
  return QSize(QWIDGETSIZE_MAX, QWIDGETSIZE_MAX);
}
//-------------------------------------
QSize DockLayout::preferredSize() const {
  QSize s(0, 0);
  int n = m_items.size();
  if (n > 0) s = QSize(100, 70);  // start with a nice default size
  int i = 0;
  while (i < n) {
    QLayoutItem *o = m_items[i];
    s              = s.expandedTo(o->sizeHint());
    ++i;
  }
  return s + n * QSize(spacing(), spacing());
  // return QSize(0,0);
}
//-------------------------------------
// ----------------------
//    Custom Methods
// ----------------------
QWidget *DockLayout::containerAt(QPoint point) const {
  // Search among regions, from leaf regions to root.
  int i;
  unsigned int j;
  for (i = m_regions.size() - 1; i >= 0; --i) {
    Region *currRegion = m_regions[i];
    DockWidget *item   = currRegion->getItem();
    // First check if item contains the point
    if (item && item->geometry().contains(point)) return currRegion->getItem();
    // Then search among separators
    for (j = 0; j < currRegion->separators().size(); ++j)
      if (currRegion->separator(j)->geometry().contains(point))
        return currRegion->separator(j);
  }
  return nullptr;
}
//-------------------------------------
void DockLayout::setMaximized(DockWidget *item, bool state) {
  if (item && state != item->m_maximized) {
    if (state) {
      // Maximize
      if (m_maximizedDock) {
        // If maximized already exists, normalize it
        Region *r = find(m_maximizedDock);
        m_maximizedDock->setGeometry(convertToIntegerRect(r->getGeometry()));
        m_maximizedDock->m_maximized = false;
      }
      // Now attempt requested item maximization
      QSize minimumSize = item->minimumSize();
      QSize maximumSize = item->maximumSize();
      if (contentsRect().width() > minimumSize.width() &&
          contentsRect().height() > minimumSize.height() &&
          contentsRect().width() < maximumSize.width() &&
          contentsRect().height() < maximumSize.height()) {
        // Maximization succeeds
        item->setGeometry(contentsRect());
        item->raise();
        item->m_maximized = true;
        m_maximizedDock   = item;
        // Hide all other docked widgets (no need to update them. Moreover,
        // doing so could eventually result in painting over the newly maximized widget)
        DockWidget *currWidget;
        for (int i = 0; i < widgetCount(); ++i) {
          currWidget = (DockWidget *)getLayoutItem(i)->widget();
          if (currWidget != item && !currWidget->isFloating())
            currWidget->hide();
        }
      }
    } else {
      // Normalize
      Region *r = find(m_maximizedDock);
      if (r) m_maximizedDock->setGeometry(convertToIntegerRect(r->getGeometry()));
      m_maximizedDock->m_maximized = false;
      m_maximizedDock              = nullptr;
      // Show all other docked widgets
      DockWidget *currWidget;
      for (int i = 0; i < widgetCount(); ++i) {
        currWidget = (DockWidget *)getLayoutItem(i)->widget();
        if (currWidget != item && !currWidget->isFloating()) currWidget->show();
      }
    }
  }
}
