unsigned int Opaque::safe_pred(const unsigned int value) {
  if (value <= 0) {
    throw std::logic_error("absurd case");
  } else {
    unsigned int prev = value - 1;
    return prev;
  }
}

unsigned int Opaque::pred_of_succ(const unsigned int value) {
  return safe_pred((std::move(value) + 1));
}

bool Opaque::nat_eq_dec(const unsigned int n, const unsigned int m) {
  if (n <= 0) {
    if (m <= 0) {
      return true;
    } else {
      unsigned int _m = m - 1;
      return false;
    }
  } else {
    unsigned int n_prev = n - 1;
    if (m <= 0) {
      return false;
    } else {
      unsigned int m_prev = m - 1;
      if (nat_eq_dec(n_prev, m_prev)) {
        return true;
      } else {
        return false;
      }
    }
  }
}

bool Opaque::are_equal(const unsigned int first, const unsigned int second) {
  if (nat_eq_dec(first, second)) {
    return true;
  } else {
    return false;
  }
}

