static __attribute__((naked)) void hook_entry_point() {
    asm volatile (
        "mov r5, sp\n"
        "str r0, [r4, #0x0c]\n"
        "str r1, [r4, #0x10]\n"
        "str r2, [r4, #0x14]\n"
        "str r3, [r4, #0x18]\n"
        "str lr, [r4, #0x1c]\n"
        "str sp, [r4, #0x20]\n"
        "ldr r6, [r4, #0x4]\n"
        "bl set_hook_state\n"
        "mov r0, r4\n"
        "blx r6\n"
        "mov sp, r5\n"
        "add r6, r4, #0x24\n"
        "bx r6"
    );
}

u32 get_sp_from_context(CoreHookContext *context) {
    return context->sp + 4 * 14;
}

__attribute__((naked)) void restore_and_return(CoreHookContext *ctx, u32 ret_addr) {
    asm volatile (
        "ldr sp, [r0, #0x20]\n"
        "add sp, sp, #0x10\n"
        "ldmia sp!, {r4-r12, lr}\n"
        "mov r2, r1\n"
        "ldr r1, [r0, #0x10]\n"
        "ldr r0, [r0, #0x0c]\n"
        "bx r2\n"
    );
}

void install_arm_hook(u32 target, u32 callback) {
    const u32 stub[] = {
        0xE92D5FFF,
        0xE59F4004,
        0xE5945000,
        0xE12FFF15,
    };

    auto ctx = std::make_unique<CoreHookContext>();
    ctx->wrapCallbackAddress = (u32)hook_entry_point;
    ctx->targetAddress = target;
    ctx->callbackAddress = callback;
    ctx->restoreIns = 0xE8BD5FFF;
    ctx->jmpIns = 0xE51FF004;
    ctx->returnAddress = target + 4 * 5;
    ctx->overwrittenIns[0] = *(u32*)target;
    ctx->overwrittenIns[1] = *((u32*)target + 1);
    ctx->overwrittenIns[2] = *((u32*)target + 2);
    ctx->overwrittenIns[3] = *((u32*)target + 3);
    ctx->overwrittenIns[4] = *((u32*)target + 4);

    CoreHookContext *ctx_ptr = ctx.get();
    active_hooks.push_back(std::move(ctx));

    *(u32*)target = stub[0];
    *((u32*)target + 1) = stub[1];
    *((u32*)target + 2) = stub[2];
    *((u32*)target + 3) = stub[3];
    *((u32*)target + 4) = (u32)ctx_ptr;
}

