#define MAX_LOG_CALLS 10
#define LOG_WINDOW_MS 1000
#define LOG_BAN_MS 10000

static u64 log_window_start = 0;
static u64 log_ban_until = 0;
static int log_call_count = 0;

static bool is_log_allowed(void) {
    u64 current_time = osGetTime();
    if (current_time < log_ban_until)
        return false;
    if (current_time - log_window_start > LOG_WINDOW_MS) {
        log_window_start = current_time;
        log_call_count = 0;
    }
    log_call_count++;
    if (log_call_count >= MAX_LOG_CALLS) {
        log_ban_until = current_time + LOG_BAN_MS;
        return false;
    }
    return true;
}

extern "C" void custom_debug_handler(u32 arg1, u32 arg2, const char* author, u32 arg3, const char* fmt, ...) {
    va_list args;
    va_start(args, fmt);
    if (is_log_allowed() && strcmp(author, "BuildGeometry") != 0 && strcmp(author, "loadChunk") != 0) {
        char buffer[0x200] = {0};
        int written = vsnprintf(buffer, sizeof(buffer), fmt, args);
        if (buffer[written-1] == '\n')
            buffer[written-1] = '\0';

        if (arg2 == 2)
            Core::Debug::LogInfo("[Game.Info] " + std::string(author) + ": " + buffer);
        else if (arg2 == 8)
            Core::Debug::LogInfo("[Game.Warn] " + std::string(author) + ": " + buffer);
        else
            Core::Debug::LogInfo(' ' + std::string(author) + ": " + buffer);
    }
    va_end(args);
    return;
}

static __attribute__((naked)) void debug_log_hook_stub(CoreHookContext* ctx) {
    asm volatile (
        "ldmia sp!, {r0-r12, lr}\n"
        "b custom_debug_handler\n"
    );
}

