using RealType = double;
using index_type = std::vector<RealType>::size_type;

void execute_test(MPI_Comm comm, const ROL::Ptr<std::ostream> & outputStream);
int main( int argc, char* argv[] ) 
{
  using ROL::Ptr;
  using ROL::makePtr;
  using ROL::makePtrFromRef;

  ROL::GlobalMPISession mpiSession(&argc, &argv);  
  int myRank = ROL::GlobalMPISession::getRank();

  auto outputStream = ROL::makeStreamPtr( std::cout, argc > 1 && myRank==0 );
  int statusFlag  = 0;

  try {
    execute_test(MPI_COMM_WORLD, outputStream);
  }
  catch (std::exception& err) {
    *outputStream << err.what() << "\n";
    statusFlag = -1000;
  }

  if(myRank==0) {
    if (statusFlag != 0)
      std::cout << "Final Result: TEST FAILED\n";
    else
      std::cout << "Final Result: TEST PASSED\n";
  }

  return 0;
}

void execute_test(MPI_Comm comm, const ROL::Ptr<std::ostream> & outputStream)
{
  using ROL::Ptr;
  using ROL::makePtr;
  using ROL::makePtrFromRef;

  int numRanks = -1;
  int myRank = -1;
  MPI_Comm_size(comm, &numRanks);
  MPI_Comm_rank(comm, &myRank);

  *outputStream << "Processor " << myRank << "/" << numRanks << std::endl;

  ROL::Ptr<const ROL::PinTCommunicators> communicators = ROL::makePtr<ROL::PinTCommunicators>(comm,1);
  ROL::Ptr<const ROL::PinTVectorCommunication<RealType>> vectorComm = ROL::makePtr<ROL::PinTVectorCommunication_StdVector<RealType>>();

  ROL::Ptr<ROL::ParameterList> pl = ROL::getParametersFromXmlFile("input_ex01.xml");

  uint spatialPoints     = pl->get("Spatial Discretization",     64);
  uint temporalPoints    = pl->get("Temporal Discretization",   128);
  RealType finalTime     = pl->get("End Time",                  1.0);
  RealType timeStepSize  = finalTime/(static_cast<RealType>(temporalPoints));

  ROL::Ptr<ROL::DynamicConstraint<RealType>> dyn_con
    = ROL::makePtr<Constraint_ParabolicControl<RealType>>(*pl);

  ROL::Ptr<ROL::StdVector<RealType>>         zk = ROL::makePtr<ROL::StdVector<RealType>>(ROL::makePtr<std::vector<RealType>>(spatialPoints+2));
  ROL::Ptr<ROL::StdVector<RealType>> u0 = ROL::makePtr<ROL::StdVector<RealType>>(ROL::makePtr<std::vector<RealType>>(spatialPoints,0.0));

  ROL::Ptr< ROL::PinTVector<RealType>> state;
  ROL::Ptr< ROL::PinTVector<RealType>> control;

  state        = ROL::buildStatePinTVector<RealType>(   communicators, vectorComm, temporalPoints,     u0);
  control      = ROL::buildControlPinTVector<RealType>( communicators, vectorComm, temporalPoints,     zk);

  int localSteps = control->numOwnedSteps();
  auto timestamps = ROL::makePtr<std::vector<ROL::TimeStamp<RealType>>>(localSteps);

  for( index_type k=0; k<timestamps->size(); ++k ) {
    timestamps->at(k).t.resize(2);
    timestamps->at(k).t.at(0) = k*timeStepSize;
    timestamps->at(k).t.at(1) = (k+1)*timeStepSize;
  }

  ROL::PinTConstraint<RealType> pint_constraint(dyn_con,u0,timestamps);
  pint_constraint.applyMultigrid(2,communicators,vectorComm);

  double tolerance = 1e-10;
  auto constraintResidual = state->clone();
  auto jacobianAction = constraintResidual->clone();
  auto statePerturbation = state->clone();
  auto stateWeight = state->clone();
  auto controlPerturbation = control->clone();

  ROL::RandomizeVector<RealType>(*state);
  ROL::RandomizeVector<RealType>(*control);
  ROL::RandomizeVector<RealType>(*statePerturbation);
  ROL::RandomizeVector<RealType>(*stateWeight);
  ROL::RandomizeVector<RealType>(*controlPerturbation);

  pint_constraint.setGlobalScale(1.0);

  // Check solve
  //////////////////////////////////////////////////////////////////////
  {
    if(myRank==0)
      *outputStream << "Verifying solve" << std::endl;

    double solveResidual = pint_constraint.checkSolve(*state,*control,*constraintResidual,true,*outputStream);
    VERIFY_CONDITION(solveResidual < tolerance);
  }

  // Check Jacobian_1
  /////////////////////////////////////////////////////////////////////////////
  {
    if(myRank==0)
      *outputStream << "Verifying apply Jacobian 1" << std::endl;

    auto errors = pint_constraint.checkApplyJacobian_1(*state,*control,*statePerturbation,*jacobianAction,true,*outputStream);
    VERIFY_CONDITION(errors[6][3]/errors[6][1] < 1e-6);
  }

  // Check Jacobian_2
  /////////////////////////////////////////////////////////////////////////////
  {
    if(myRank==0)
      *outputStream << "Verifying apply Jacobian 2" << std::endl;

    auto errors = pint_constraint.checkApplyJacobian_2(*state,*control,*controlPerturbation,*jacobianAction,true,*outputStream);
    VERIFY_CONDITION(errors[6][3]/errors[6][1] < 1e-6);
  }

  // Check Adjoint Jacobian_1
  /////////////////////////////////////////////////////////////////////////////
  {
    if(myRank==0)
      *outputStream << "Verifying apply Adjoint Jacobian 1" << std::endl;

    auto error = pint_constraint.checkAdjointConsistencyJacobian_1(*stateWeight,*statePerturbation,*state,*control,true,*outputStream);
    VERIFY_CONDITION(error<1e-8);
  }

  // Check Adjoint Jacobian_2
  /////////////////////////////////////////////////////////////////////////////
  {
    if(myRank==0)
      *outputStream << "Verifying apply Adjoint Jacobian 2" << std::endl;

    auto error = pint_constraint.checkAdjointConsistencyJacobian_2(*stateWeight,*controlPerturbation,*state,*control,true,*outputStream);
    VERIFY_CONDITION(error<1e-8);
  }

  // Check inverse Jacobian_1
  /////////////////////////////////////////////////////////////////////////////
  {
    RealType inv_1     = pint_constraint.checkInverseJacobian_1(*jacobianAction,*statePerturbation,*state,*control,true,*outputStream);
    VERIFY_CONDITION(inv_1 < tolerance);
  }

  // Check inverse adjoint Jacobian_1
  /////////////////////////////////////////////////////////////////////////////
  {
    RealType adj_inv_1 = pint_constraint.checkInverseAdjointJacobian_1(*jacobianAction,*statePerturbation,*state,*control,true,*outputStream);
    VERIFY_CONDITION(adj_inv_1 < tolerance);
  }

  auto combinedVector = makePtr<ROL::Vector_SimOpt<RealType>>(state,control);
  auto v_1 = combinedVector->clone();
  auto v_2 = state->clone();
  auto r_1 = v_1->clone();
  auto r_2 = v_2->clone();

  ROL::RandomizeVector<RealType>(*r_1);
  ROL::RandomizeVector<RealType>(*r_2);

  // Check local forward and adjoint operators
  {
    using ROL::PinTVector;
    auto tempVec = state->clone();
    auto forwardResult = state->clone();
    auto localForwardResult = state->clone();
    auto adjointResult = state->clone();
    auto localJacobianResult = state->clone();
    auto adjointJacobianResult = state->clone();

    PinTVector<RealType> & pint_tempVec = dynamic_cast<PinTVector<RealType>&>(*tempVec);
    PinTVector<RealType> & pint_jac_res = dynamic_cast<PinTVector<RealType>&>(*localJacobianResult);
    PinTVector<RealType> & pint_adj_res = dynamic_cast<PinTVector<RealType>&>(*adjointJacobianResult);

    ROL::RandomizeVector<RealType>(*tempVec);

    tolerance = 1e-12;

    // Compute Jacobian action
    pint_constraint.applyJacobian_1(*localJacobianResult,
                                    *tempVec,
                                    *state,
                                    *control,tolerance);

    // Compute adjoint Jacobian action
    pint_constraint.applyAdjointJacobian_1(*adjointJacobianResult,
                                           *tempVec,
                                           *state,
                                           *control,tolerance);

    // Adjust right-hand side for subdomain solvers
    int steps = pint_jac_res.numOwnedSteps();

    pint_tempVec.boundaryExchangeRightToLeft();

    if(myRank+1<numRanks) {
      pint_jac_res.getVectorPtr(2*(steps-1)+1)->axpy(1.0,*pint_tempVec.getVectorPtr(2*(steps-1))); 
      pint_adj_res.getVectorPtr(2*(steps-1))->axpy(1.0,*pint_tempVec.getVectorPtr(2*(steps-1)+1));
    }

    int level = 0;

    pint_constraint.invertTimeStepJacobian(dynamic_cast<PinTVector<RealType>&>(*forwardResult),
                                           dynamic_cast<const PinTVector<RealType>&>(*localJacobianResult),
                                           dynamic_cast<const PinTVector<RealType>&>(*state),
                                           dynamic_cast<const PinTVector<RealType>&>(*control),
                                           tolerance,
                                           level);

    pint_constraint.applyJacobian_1_leveled_approx(*localForwardResult,
                                                   *forwardResult,
                                                   *state,
                                                   *control,
                                                   tolerance,
                                                   level);

    RealType tempNorm   = tempVec->norm();
    RealType jacNorm  = localJacobianResult->norm();

    // Check forward time step Jacobian
    {
      forwardResult->axpy(-1.0,*tempVec);
      RealType forwardNorm  = forwardResult->norm();

      if(myRank==0)
        *outputStream << "Testing vector norm = " << tempNorm  << " (error = " << forwardNorm/tempNorm << ")" << std::endl;

      VERIFY_CONDITION(forwardNorm/tempNorm <= 1e-12);

      if(myRank==0)
        *outputStream << "Forward block Jacobi subdomain inversion VERIFIED with proc " 
                   << " (relative error = " << forwardNorm / tempNorm  << ")" << std::endl;

      localForwardResult->axpy(-1.0,*localJacobianResult);
      RealType localForwardNorm  = localForwardResult->norm();
      VERIFY_CONDITION(localForwardNorm/jacNorm <= 1e-13);
    }

    pint_constraint.invertAdjointTimeStepJacobian(dynamic_cast<PinTVector<RealType>&>(*adjointResult),
                                                  dynamic_cast<const PinTVector<RealType>&>(*adjointJacobianResult),
                                                  dynamic_cast<const PinTVector<RealType>&>(*state),
                                                  dynamic_cast<const PinTVector<RealType>&>(*control),
                                                  tolerance,
                                                  level);

    pint_constraint.applyAdjointJacobian_1_leveled_approx(*localForwardResult,
                                                          *adjointResult,
                                                          *state,
                                                          *control,
                                                          tolerance,
                                                          level);

    RealType adjNorm  = adjointJacobianResult->norm();

    // Check backward time step Jacobian
    {
      adjointResult->axpy(-1.0,*tempVec);
      RealType adjointNorm = adjointResult->norm();

      if(myRank==0)
        *outputStream << "Testing vector norm = " << tempNorm  << " (error = " << adjointNorm/tempNorm << ")" << std::endl;

      VERIFY_CONDITION(adjointNorm/tempNorm <= 1e-12);

      if(myRank==0)
        *outputStream << "Adjoint block Jacobi subdomain inversion VERIFIED with proc " 
                   << " (relative error = " << adjointNorm / tempNorm  << ")\n" << std::endl;

      localForwardResult->axpy(-1.0,*adjointJacobianResult);
      RealType localAdjointNorm  = localForwardResult->norm();
      VERIFY_CONDITION(localAdjointNorm/adjNorm <= 1e-13);

      if(myRank==0)
        *outputStream << "Adjoint block Jacobi subdomain apply VERIFIED with proc " 
                   << " (relative error = " << localAdjointNorm / adjNorm  << ")\n" << std::endl;
    }
  }
}

