#include "llvm/Passes/PassPlugin.h"
#include "llvm/Support/raw_ostream.h"
#include <cstdint>

using namespace llvm;

Expected<PassPlugin> PassPlugin::Load(const std::string &Path) {
  std::string ErrMsg;
  auto LibHandle =
      sys::DynamicLibrary::getPermanentLibrary(Path.c_str(), &ErrMsg);
  if (!LibHandle.isValid())
    return make_error<StringError>(Twine("Failed to load module '") +
                                       Path + "': " + ErrMsg,
                                   inconvertibleErrorCode());

  PassPlugin PluginObj{Path, LibHandle};

  // Resolve the plugin entry point symbol
  intptr_t entryPoint =
      (intptr_t)LibHandle.getAddressOfSymbol("llvmGetPassPluginInfo");
  if (!entryPoint)
    // Symbol missing indicates an outdated plugin format
    return make_error<StringError>(Twine("Missing plugin entry in '") +
                                       Path + "'. Could be an old-style plugin?",
                                   inconvertibleErrorCode());

  PluginObj.Info = reinterpret_cast<decltype(llvmGetPassPluginInfo) *>(entryPoint)();

  // Verify API compatibility
  if (PluginObj.Info.APIVersion != LLVM_PLUGIN_API_VERSION)
    return make_error<StringError>(
        Twine("Incompatible API version for plugin '") + Path + "'. Received " +
            Twine(PluginObj.Info.APIVersion) + ", expected " +
            Twine(LLVM_PLUGIN_API_VERSION) + ".",
        inconvertibleErrorCode());

  // Ensure required callback is present
  if (!PluginObj.Info.RegisterPassBuilderCallbacks)
    return make_error<StringError>(Twine("No registration callback in plugin '") +
                                       Path + "'.",
                                   inconvertibleErrorCode());

  return PluginObj;
}

