  A_matrix_.resize(0, 0);
  B_matrix_.resize(0, 0);
  C_matrix_.resize(0, 0);
  D_matrix_.resize(0, 0);
}

Filter::Filter(matrix_t A_matrix, matrix_t B_matrix, matrix_t C_matrix, matrix_t D_matrix)
    : A_matrix_(std::move(A_matrix)),
      B_matrix_(std::move(B_matrix)),
      C_matrix_(std::move(C_matrix)),
      D_matrix_(std::move(D_matrix)),
      a_diag_(A_matrix_.diagonal()),
      b_diag_(B_matrix_.diagonal()),
      c_diag_(C_matrix_.diagonal()),
      d_diag_(D_matrix_.diagonal()),
      state_dim_(A_matrix_.rows()),
      input_dim_(B_matrix_.cols()),
      output_dim_(C_matrix_.rows()) {
  verifyDimensions();
  // precompute row + column scaling
  CC_scaled_ = c_diag_ * matrix_t::Ones(c_diag_.cols(), c_diag_.rows()) * c_diag_;
  DC_scaled_ = d_diag_ * matrix_t::Ones(d_diag_.cols(), c_diag_.rows()) * c_diag_;
  DD_scaled_ = d_diag_ * matrix_t::Ones(d_diag_.cols(), d_diag_.rows()) * d_diag_;
  // Prepare inv(A)
  if (A_matrix_.size() > 0) {
    A_factor_.compute(A_matrix_);
  }
  // Prepare inv(D)
  D_factor_.compute(D_matrix_);
  // Prepare inv([A, B; C, D])
  matrix_t ABCD_block(state_dim_ + input_dim_, state_dim_ + input_dim_);
  ABCD_block << A_matrix_, B_matrix_, C_matrix_, D_matrix_;
  ABCD_factor_.compute(ABCD_block);
}

void Filter::print() const {
  std::cerr << "Number of states: " << state_dim_ << std::endl;
  std::cerr << "Number of inputs: " << input_dim_ << std::endl;
  std::cerr << "Number of outputs: " << output_dim_ << std::endl;
  auto printMatrix = [](const std::string& label, const matrix_t& mat) {
    if (mat.isDiagonal()) {
      std::cerr << label << ": (diagonal) \n" << mat.diagonal().transpose() << "\n";
    } else {
      std::cerr << label << ": \n" << mat << "\n";
    }
  };
  printMatrix("A", A_matrix_);
  printMatrix("B", B_matrix_);
  printMatrix("C", C_matrix_);
  printMatrix("D", D_matrix_);
}

void Filter::findEquilibriumForOutput(const vector_t& y_target, vector_t& x_state, vector_t& u_input) const {
  // Solve (given y)
  // [0  =  [  A    B    [x
  //  y]       C    D  ]  u]
  vector_t combined_zero(state_dim_ + output_dim_);
  combined_zero << vector_t::Zero(state_dim_), y_target;
  const vector_t state_input_solution = ABCD_factor_.solve(combined_zero);
  x_state = state_input_solution.head(state_dim_);
  u_input = state_input_solution.tail(input_dim_);
}

void Filter::findEquilibriumForOutputGivenState(const vector_t& y_target, const vector_t& x_state, vector_t& u_input) const {
  // Solve (given y, x)
  //  y =  [  C    D  ] [x; u]
  vector_t residual = y_target;
  residual.noalias() -= C_matrix_ * x_state;
  u_input = D_factor_.solve(residual);
}

void Filter::findEquilibriumForInput(const vector_t& u_input, vector_t& x_state, vector_t& y_output) const {
  // Solve (given u)
  // [0  =  [  A    B    [x
  //  y]       C    D  ]  u]
  y_output.noalias() = D_matrix_ * u_input;
  if (state_dim_ > 0) {
    x_state = -A_factor_.solve(B_matrix_ * u_input);
    y_output.noalias() += C_matrix_ * x_state;
  }
}

void Filter::verifyDimensions() const {
  bool consistent = true;
  // check number of states
  consistent &= state_dim_ == A_matrix_.rows();
  consistent &= state_dim_ == B_matrix_.rows();
  consistent &= state_dim_ == C_matrix_.cols();
  // Check number of inputs
  consistent &= input_dim_ == B_matrix_.cols();
  consistent &= input_dim_ == D_matrix_.cols();
  // Check number of outputs
  consistent &= output_dim_ == C_matrix_.rows();
  consistent &= output_dim_ == D_matrix_.rows();
  if (!consistent) {
    print();
    throw std::runtime_error("Loopshaping: Filter: Matrix dimensions not consistent.");
  }
}

