#include "rows_to_matrix.h"
#include <cassert>
#include <cstdio>
#include "max_size.h"
#include "min_size.h"

template <class Row, class Mat>
IGL_INLINE bool igl::rows_to_matrix(const std::vector<Row> & inputList, Mat & outputMatrix)
{
  // number of rows (vectors in the list)
  int rowCount = inputList.size();
  if(rowCount == 0)
  {
    fprintf(stderr,"Error: rows_to_matrix() input list is empty()\n");
    return false;
  }

  // number of columns (size of each row vector)
  int colCount = igl::min_size(inputList);
  if(colCount != igl::max_size(inputList))
  {
    fprintf(stderr,"Error: rows_to_matrix()"
      " input vectors have inconsistent sizes\n");
    return false;
  }

  assert(colCount != -1);

  // Resize output matrix to match dimensions
  outputMatrix.resize(rowCount, colCount);

  // Populate matrix with row vectors
  int rowIndex = 0;
  typename std::vector<Row>::const_iterator iter = inputList.begin();
  while(iter != inputList.end())
  {
    outputMatrix.row(rowIndex) = inputList[rowIndex];
    // advance to next row
    rowIndex++;
    iter++;
  }

  return true;
}

