using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int size;
    if (!(cin >> size)) return 0;

    vector<int> parent(size + 1, 0);
    for (int idx = 2; idx <= size; ++idx) {
        int val; 
        cin >> val; 
        parent[idx] = val;
    }

    // Construct a path decomposition for the tree
    // Node bags: {j} for j=1..size
    // Edge bags: {u, parent[u]} for u=2..size
    // Total bags = size + (size-1) = 2*size - 1

    int totalBags = 2 * size - 1;
    cout << totalBags << "\n";

    // Print node bags (1 to size)
    for (int j = 1; j <= size; ++j) {
        cout << 1 << " " << j << "\n";
    }

    // Print edge bags (size+1 to 2*size-1)
    for (int u = 2; u <= size; ++u) {
        cout << 2 << " " << u << " " << parent[u] << "\n";
    }

    // Build path connections between bags:
    // C1 -- E2 -- C2 -- E3 -- ... -- C_{size}
    vector<pair<int, int>> bagConnections;

    if (size >= 2) {
        // Connect C1 (bag 1) to E2 (bag size+1)
        bagConnections.push_back({1, size + 1});

        for (int u = 2; u <= size; ++u) {
            int edgeBag = size + (u - 1);   // E_u
            int nodeBag = u;                // C_u

            // Connect E_u to C_u
            bagConnections.push_back({edgeBag, nodeBag});

            // Connect C_u to E_{u+1} if exists
            if (u + 1 <= size) {
                int nextEdgeBag = size + u; // E_{u+1}
                bagConnections.push_back({nodeBag, nextEdgeBag});
            }
        }
    }

    // Output all connections
    for (const auto& conn : bagConnections) {
        cout << conn.first << " " << conn.second << "\n";
    }

    return 0;
}

