bool opt_prof_stats = true;
malloc_mutex_t prof_stats_lock;
static prof_stats_t live_stats[PROF_SC_NSIZES];
static prof_stats_t accum_stats[PROF_SC_NSIZES];

static void
prof_stats_enter(tsd_t *tsd, szind_t index) {
    assert(opt_prof && opt_prof_stats);
    assert(index < SC_NSIZES);
    malloc_mutex_lock(tsd_tsdn(tsd), &prof_stats_lock);
}

static void
prof_stats_exit(tsd_t *tsd) {
    malloc_mutex_unlock(tsd_tsdn(tsd), &prof_stats_lock);
}

void
prof_stats_add(tsd_t *tsd, szind_t index, size_t bytes) {
    cassert(config_prof);
    prof_stats_enter(tsd, index);
    live_stats[index].req_sum += bytes;
    live_stats[index].count++;
    accum_stats[index].req_sum += bytes;
    accum_stats[index].count++;
    prof_stats_exit(tsd);
}

void
prof_stats_remove(tsd_t *tsd, szind_t index, size_t bytes) {
    cassert(config_prof);
    prof_stats_enter(tsd, index);
    live_stats[index].req_sum -= bytes;
    live_stats[index].count--;
    prof_stats_exit(tsd);
}

void
prof_stats_copy_live(tsd_t *tsd, szind_t index, prof_stats_t *result) {
    cassert(config_prof);
    prof_stats_enter(tsd, index);
    memcpy(result, &live_stats[index], sizeof(prof_stats_t));
    prof_stats_exit(tsd);
}

void
prof_stats_copy_accum(tsd_t *tsd, szind_t index, prof_stats_t *result) {
    cassert(config_prof);
    prof_stats_enter(tsd, index);
    memcpy(result, &accum_stats[index], sizeof(prof_stats_t));
    prof_stats_exit(tsd);
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <iterator>
using namespace std;

// Global data storage
int size_n;
vector<int> values;

// Function to compute longest (increasing/decreasing) subsequence on unused elements
// Returns indices of the selected subsequence
vector<int> find_subseq(const vector<bool>& used, bool is_desc) {
    vector<int> min_tails;      // stores tail values of active subsequences
    vector<int> tail_indices;   // stores corresponding indices in 'values'
    vector<int> prev_idx(size_n, -1);  // parent pointers for reconstruction

    for (int i = 0; i < size_n; ++i) {
        if (used[i]) continue;

        int current_val = values[i];
        if (is_desc) current_val = -current_val;  // convert to LIS problem

        auto pos = lower_bound(min_tails.begin(), min_tails.end(), current_val);
        int seq_len = distance(min_tails.begin(), pos);

        if (pos == min_tails.end()) {
            min_tails.push_back(current_val);
            tail_indices.push_back(i);
        } else {
            *pos = current_val;
            tail_indices[seq_len] = i;
        }

        if (seq_len > 0) {
            prev_idx[i] = tail_indices[seq_len - 1];
        }
    }

    // Reconstruct the subsequence
    vector<int> result;
    if (tail_indices.empty()) return result;

    int curr = tail_indices.back();
    while (curr != -1) {
        result.push_back(curr);
        curr = prev_idx[curr];
    }
    reverse(result.begin(), result.end());
    return result;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> size_n)) return 0;
    values.resize(size_n);
    for (int idx = 0; idx < size_n; ++idx) {
        cin >> values[idx];
    }

    // We need two increasing and two decreasing subsequences
    // Try all permutations of the pattern [inc, inc, dec, dec]
    vector<int> order = {0, 0, 1, 1};
    sort(order.begin(), order.end());

    long long max_total = -1;
    vector<int> final_assignment(size_n, 3);  // default assignment: group d (index 3)

    do {
        vector<bool> taken(size_n, false);
        vector<int> temp_owner(size_n, -1);
        long long current_sum = 0;

        int inc_used = 0;
        int dec_used = 0;

        for (int t : order) {
            int group_id = -1;

            if (t == 0) {
                group_id = (inc_used == 0) ? 0 : 2;
                inc_used++;
            } else {
                group_id = (dec_used == 0) ? 1 : 3;
                dec_used++;
            }

            vector<int> indices = find_subseq(taken, (t == 1));
            current_sum += indices.size();

            for (int idx : indices) {
                taken[idx] = true;
                temp_owner[idx] = group_id;
            }
        }

        if (current_sum > max_total) {
            max_total = current_sum;
            for (int i = 0; i < size_n; ++i) {
                final_assignment[i] = (temp_owner[i] == -1) ? 3 : temp_owner[i];
            }
        }

    } while (next_permutation(order.begin(), order.end()));

    // Build output groups based on final assignment
    vector<int> group_a, group_b, group_c, group_d;
    group_a.reserve(size_n);
    group_b.reserve(size_n);
    group_c.reserve(size_n);
    group_d.reserve(size_n);

    for (int i = 0; i < size_n; ++i) {
        switch (final_assignment[i]) {
            case 0: group_a.push_back(values[i]); break;
            case 1: group_b.push_back(values[i]); break;
            case 2: group_c.push_back(values[i]); break;
            default: group_d.push_back(values[i]); break;
        }
    }

    // Output sizes
    cout << group_a.size() << " " << group_b.size() << " " 
         << group_c.size() << " " << group_d.size() << "\n";

    // Helper lambda to print a vector with space separation
    auto display = [](const vector<int>& vec) {
        for (size_t k = 0; k < vec.size(); ++k) {
            cout << vec[k];
            if (k + 1 < vec.size()) cout << " ";
        }
        cout << "\n";
    };

    display(group_a);
    display(group_b);
    display(group_c);
    display(group_d);

    return 0;
}

