// Insertion sort implementation
int main() {
    int arr[] = {5, 2, 8, 1, 9};
    int n = 5;

    for (int index = 0; index < n; index++) {
        int temp = arr[index];
        int position = index - 1;

        for (; position >= 0 && arr[position] > temp; position--) {
            // shift elements to the right
            arr[position + 1] = arr[position];
        }

        arr[position + 1] = temp;
    }

    // Print sorted array
    for (int i = 0; i < n; i++) {
        std::cout << arr[i] << " ";
    }
    std::cout << std::endl;

    return 0;
}

#include <bits/stdc++.h>
using namespace std;
using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int testCases;
    if (!(cin >> testCases)) return 0;

    while (testCases--) {
        int days, tasks;
        ll penalty;
        cin >> days >> tasks >> penalty;

        vector<ll> arrA(days + 1), arrB(tasks + 1);
        for (int idx = 1; idx <= days; ++idx) cin >> arrA[idx];
        for (int idx = 1; idx <= tasks; ++idx) cin >> arrB[idx];

        // Prefix sums of arrA
        vector<ll> prefixA(days + 1, 0);
        for (int idx = 1; idx <= days; ++idx) prefixA[idx] = prefixA[idx - 1] + arrA[idx];

        // Thresholds cumulative sum of arrB
        vector<ll> cumThreshold(tasks + 1, 0);
        for (int idx = 1; idx <= tasks; ++idx) cumThreshold[idx] = cumThreshold[idx - 1] + arrB[idx];

        // Helper function: K(x) returns max k such that cumThreshold[k] <= x
        auto countSegments = [&](ll value) -> int {
            if (value < 0) return 0;
            int k = upper_bound(cumThreshold.begin(), cumThreshold.end(), value) - cumThreshold.begin() - 1;
            if (k < 0) k = 0;
            if (k > tasks) k = tasks;
            return k;
        };

        // DP array initialization
        vector<ll> dpCurrent(days + 1, LLONG_MIN / 4);
        dpCurrent[0] = 0;  // Base case: zero days processed

        // Divide and conquer DP optimization
        vector<ll> dpNext(days + 1, LLONG_MIN / 4);
        dpNext[0] = 0;

        function<void(int, int, int, int)> divideAndConquer = [&](int left, int right, int optLeft, int optRight) {
            if (left > right) return;

            int mid = (left + right) >> 1;
            ll bestValue = LLONG_MIN / 4;
            int bestPosition = optLeft;

            int jLimit = min(mid - 1, optRight);
            for (int j = optLeft; j <= jLimit; ++j) {
                ll currentValue = dpCurrent[j] + (ll)countSegments(prefixA[mid] - prefixA[j]) - penalty;
                if (currentValue > bestValue) {
                    bestValue = currentValue;
                    bestPosition = j;
                }
            }

            dpNext[mid] = bestValue;

            divideAndConquer(left, mid - 1, optLeft, bestPosition);
            divideAndConquer(mid + 1, right, bestPosition, optRight);
        };

        // Compute DP values for positions 1 through days
        divideAndConquer(1, days, 0, days - 1);

        cout << dpNext[days] << "\n";
    }

    return 0;
}

