// Singleton instance initialization
Frustum *Frustum::frustum = new Frustum();

// Constructor: allocate buffers for matrix operations
Frustum::Frustum()
{	
	_projectionMatrix = MemoryTracker::createFloatBuffer(16);
	_modelViewMatrix = MemoryTracker::createFloatBuffer(16);
	_combinedMatrix = MemoryTracker::createFloatBuffer(16);
}

// Destructor: release allocated memory
Frustum::~Frustum()
{
	delete _projectionMatrix;
	delete _modelViewMatrix;
	delete _combinedMatrix;
}

// Public method to retrieve the calculated frustum data
FrustumData *Frustum::getFrustum()
{
	frustum->computeClippingPlanes();
    return frustum;
}

    ///////////////////////////////// PLANE NORMALIZATION \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\*
    /////
    /////	This normalizes a plane (A side) from a given frustum.
    /////
    ///////////////////////////////// PLANE NORMALIZATION \\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\\*
void Frustum::normalizePlane(float **planes, int index)
{
    float length = (float) sqrt(planes[index][X] * planes[index][X] + 
                                planes[index][Y] * planes[index][Y] + 
                                planes[index][Z] * planes[index][Z]);

    // Normalize each component by dividing by the magnitude
    planes[index][X] /= length;
    planes[index][Y] /= length;
    planes[index][Z] /= length;
    planes[index][W] /= length;
}

void Frustum::computeClippingPlanes()
{
    _projectionMatrix->clear();
    _modelViewMatrix->clear();
    _combinedMatrix->clear();

    // Retrieve current OpenGL matrices
    glGetFloat(GL_PROJECTION_MATRIX, _projectionMatrix);
    glGetFloat(GL_MODELVIEW_MATRIX, _modelViewMatrix);

    // Prepare matrices for reading
    _projectionMatrix->flip()->limit(16);
    _projectionMatrix->get(&proj);
    _modelViewMatrix->flip()->limit(16);
    _modelViewMatrix->get(&modl);

    // Combine projection and modelview matrices to get clipping planes
    clip[0]  = modl[0] * proj[0]  + modl[1] * proj[4]  + modl[2] * proj[8]  + modl[3] * proj[12];
    clip[1]  = modl[0] * proj[1]  + modl[1] * proj[5]  + modl[2] * proj[9]  + modl[3] * proj[13];
    clip[2]  = modl[0] * proj[2]  + modl[1] * proj[6]  + modl[2] * proj[10] + modl[3] * proj[14];
    clip[3]  = modl[0] * proj[3]  + modl[1] * proj[7]  + modl[2] * proj[11] + modl[3] * proj[15];
    clip[4]  = modl[4] * proj[0]  + modl[5] * proj[4]  + modl[6] * proj[8]  + modl[7] * proj[12];
    clip[5]  = modl[4] * proj[1]  + modl[5] * proj[5]  + modl[6] * proj[9]  + modl[7] * proj[13];
    clip[6]  = modl[4] * proj[2]  + modl[5] * proj[6]  + modl[6] * proj[10] + modl[7] * proj[14];
    clip[7]  = modl[4] * proj[3]  + modl[5] * proj[7]  + modl[6] * proj[11] + modl[7] * proj[15];
    clip[8]  = modl[8] * proj[0]  + modl[9] * proj[4]  + modl[10] * proj[8] + modl[11] * proj[12];
    clip[9]  = modl[8] * proj[1]  + modl[9] * proj[5]  + modl[10] * proj[9] + modl[11] * proj[13];
    clip[10] = modl[8] * proj[2]  + modl[9] * proj[6]  + modl[10] * proj[10] + modl[11] * proj[14];
    clip[11] = modl[8] * proj[3]  + modl[9] * proj[7]  + modl[10] * proj[11] + modl[11] * proj[15];
    clip[12] = modl[12] * proj[0] + modl[13] * proj[4] + modl[14] * proj[8] + modl[15] * proj[12];
    clip[13] = modl[12] * proj[1] + modl[13] * proj[5] + modl[14] * proj[9] + modl[15] * proj[13];
    clip[14] = modl[12] * proj[2] + modl[13] * proj[6] + modl[14] * proj[10] + modl[15] * proj[14];
    clip[15] = modl[12] * proj[3] + modl[13] * proj[7] + modl[14] * proj[11] + modl[15] * proj[15];

    // Extract frustum planes from combined matrix
    // Right plane
    m_Frustum[RIGHT][X] = clip[3] - clip[0];
    m_Frustum[RIGHT][Y] = clip[7] - clip[4];
    m_Frustum[RIGHT][Z] = clip[11] - clip[8];
    m_Frustum[RIGHT][W] = clip[15] - clip[12];
    normalizePlane(m_Frustum, RIGHT);

    // Left plane
    m_Frustum[LEFT][X] = clip[3] + clip[0];
    m_Frustum[LEFT][Y] = clip[7] + clip[4];
    m_Frustum[LEFT][Z] = clip[11] + clip[8];
    m_Frustum[LEFT][W] = clip[15] + clip[12];
    normalizePlane(m_Frustum, LEFT);

    // Bottom plane
    m_Frustum[BOTTOM][X] = clip[3] + clip[1];
    m_Frustum[BOTTOM][Y] = clip[7] + clip[5];
    m_Frustum[BOTTOM][Z] = clip[11] + clip[9];
    m_Frustum[BOTTOM][W] = clip[15] + clip[13];
    normalizePlane(m_Frustum, BOTTOM);

    // Top plane
    m_Frustum[TOP][X] = clip[3] - clip[1];
    m_Frustum[TOP][Y] = clip[7] - clip[5];
    m_Frustum[TOP][Z] = clip[11] - clip[9];
    m_Frustum[TOP][W] = clip[15] - clip[13];
    normalizePlane(m_Frustum, TOP);

    // Back plane
    m_Frustum[BACK][X] = clip[3] - clip[2];
    m_Frustum[BACK][Y] = clip[7] - clip[6];
    m_Frustum[BACK][Z] = clip[11] - clip[10];
    m_Frustum[BACK][W] = clip[15] - clip[14];
    normalizePlane(m_Frustum, BACK);

    // Front plane
    m_Frustum[FRONT][X] = clip[3] + clip[2];
    m_Frustum[FRONT][Y] = clip[7] + clip[6];
    m_Frustum[FRONT][Z] = clip[11] + clip[10];
    m_Frustum[FRONT][W] = clip[15] + clip[14];
    normalizePlane(m_Frustum, FRONT);
}

