using namespace db;

// Ensure the iterator has read a complete page
void LoadUtils::ensureIteratorReadPage(fs::AlignedBufferIterator& iter) {
    // Verify that we have received a full page
    if (iter.remainingBytes() != DumpConfig::PAGE_SIZE) {
        const std::string details = fmt::format("Received {} bytes but expected {} bytes",
                                       iter.remainingBytes(), DumpConfig::PAGE_SIZE);
        throw TuringException("Failed to read from file: iterator did not get full page "
                              "prior to loading nodes. "
                              + details);
    }
}

// Verify sufficient space is available for loading and prepare buffer if needed
void LoadUtils::ensureLoadSpace(size_t neededSpace,
                                fs::FilePageReader& reader,
                                fs::AlignedBufferIterator& iter) {
    if (neededSpace > DumpConfig::PAGE_SIZE) {
        const std::string details =
            fmt::format("Attempting to write {} bytes which exceeds page size of {}",
                        neededSpace, DumpConfig::PAGE_SIZE);
        throw TuringException("Illegal read: " + details);
    }
    if (iter.remainingBytes() < neededSpace) {
        reader.nextPage();
        iter = reader.begin();
        LoadUtils::ensureIteratorReadPage(iter);
    }
}

// Advance to a new page and ensure it's properly loaded
void LoadUtils::newPage(fs::AlignedBufferIterator& iter, fs::FilePageReader& reader) {
    reader.nextPage();
    iter = reader.begin();
    ensureIteratorReadPage(iter);
}

