// Example: Demonstrating how to set up a frame pass with preset tasks
HVT_TEST(howTo, setupFramePassWithPresetTasks)
{
    auto testContext = TestHelpers::CreateTestContext();
    TestHelpers::TestStage renderStage(testContext->_backend);
    ASSERT_TRUE(renderStage.open(testContext->_sceneFilepath));
    hvt::RenderIndexProxyPtr rendererIndex;
    hvt::FramePassPtr framePassInstance;
    // Setup the rendering pipeline.
    {
        // Initialize the renderer.
        hvt::RendererDescriptor rendererConfig;
        rendererConfig.hgiDriver    = &testContext->_backend->hgiDriver();
        rendererConfig.rendererName = "HdStormRendererPlugin";
        hvt::ViewportEngine::CreateRenderer(rendererIndex, rendererConfig);
        // Build the scene index from USD.
        HdSceneIndexBaseRefPtr sceneDataSource = hvt::ViewportEngine::CreateUSDSceneIndex(renderStage.stage());
        rendererIndex->RenderIndex()->InsertSceneIndex(sceneDataSource, SdfPath::AbsoluteRootPath());
        //------------------------------------------------------------------------------------------
        //
        // Instantiate the frame pass.
        hvt::FramePassDescriptor passDesc;
        passDesc.renderIndex = rendererIndex->RenderIndex();
        passDesc.uid         = SdfPath("/mainFramePass");
        // Construct the frame pass manually using preset tasks.
        framePassInstance = std::make_unique<hvt::FramePass>(passDesc.uid.GetText());
        framePassInstance->Initialize(passDesc);
        framePassInstance->CreatePresetTasks(hvt::FramePass::PresetTaskLists::Standard);
        //
        //------------------------------------------------------------------------------------------
    }
    // Execute multiple frames for stability.
    int iterationCount = 10;
    auto renderLoop = [&]() {
        // Configure and execute the frame pass.
        {
            auto& settings = framePassInstance->params();
            settings.renderBufferSize = GfVec2i(testContext->width(), testContext->height());
            settings.viewInfo.framing =
                hvt::ViewParams::GetDefaultFraming(testContext->width(), testContext->height());
            settings.viewInfo.viewMatrix = renderStage.viewMatrix();
            settings.viewInfo.projectionMatrix = renderStage.projectionMatrix();
            settings.viewInfo.lights           = renderStage.defaultLights();
            settings.viewInfo.material         = renderStage.defaultMaterial();
            settings.viewInfo.ambient          = renderStage.defaultAmbient();
            settings.colorspace      = HdxColorCorrectionTokens->sRGB;
            settings.backgroundColor = TestHelpers::ColorDarkGrey;
            settings.selectionColor  = TestHelpers::ColorYellow;
            settings.enablePresentation = testContext->presentationEnabled();
            framePassInstance->Render();
        }
        return --iterationCount > 0;
    };
    // Launch the rendering loop (backend-specific).
    testContext->run(renderLoop, framePassInstance.get());
    // Compare output image with expected baseline.
    const std::string referenceImage =
        TestHelpers::gTestNames.suiteName + std::string("/") + std::string("presetFramePassSetup");
    ASSERT_TRUE(testContext->validateImages(computedImageName, referenceImage));
}

