  auto CheckCondition = [&] {
    if (inputSize >= 2 && inputData[0] == 'H') {
        std::cout << "SUCCESS: Matched expected pattern, terminating\n";
        abort();
    }
  };

  std::thread workerThreads[] = {
      std::thread(CheckCondition),
      std::thread(CheckCondition),
      std::thread(CheckCondition),
      std::thread(CheckCondition),
      std::thread(CheckCondition),
      std::thread(CheckCondition)
  };

  for (auto &threadRef : workerThreads) {
