TEST(hsa, tables)
{
    namespace hsa = ::rocprofiler::hsa;

    // Retrieve HSA API table version information
    auto ver_info = hsa::get_table_version();

    // Access individual HSA API table components
    auto* core_api     = hsa::get_core_table();
    auto* amd_ext_api  = hsa::get_amd_ext_table();
    auto* fini_ext_api = hsa::get_fini_ext_table();
    auto* img_ext_api  = hsa::get_img_ext_table();
    auto* tool_api     = hsa::get_amd_tool_table();
#if ROCPROFILER_SDK_HSA_PC_SAMPLING > 0
    auto* pcs_api      = hsa::get_pc_sampling_ext_table();
#endif

    // Get full HsaApiTable instance
    auto full_table = hsa::get_table();

    //------------------------------------------------------------------------//
    //  Validate against HSA header constants
    //------------------------------------------------------------------------//
    // Verify main table version fields
    EXPECT_EQ(ver_info.major_id, HSA_API_TABLE_MAJOR_VERSION);
    EXPECT_EQ(ver_info.minor_id, sizeof(hsa::hsa_api_table_t));
    EXPECT_EQ(ver_info.step_id, HSA_API_TABLE_STEP_VERSION);

    // Verify core API table version fields
    EXPECT_EQ(core_api->version.major_id, HSA_CORE_API_TABLE_MAJOR_VERSION);
    EXPECT_EQ(core_api->version.minor_id, sizeof(hsa::hsa_core_table_t));
    EXPECT_EQ(core_api->version.step_id, HSA_CORE_API_TABLE_STEP_VERSION);

    // Verify AMD extension API table version fields
    EXPECT_EQ(amd_ext_api->version.major_id, HSA_AMD_EXT_API_TABLE_MAJOR_VERSION);
    EXPECT_EQ(amd_ext_api->version.minor_id, sizeof(hsa::hsa_amd_ext_table_t));
    EXPECT_EQ(amd_ext_api->version.step_id, HSA_AMD_EXT_API_TABLE_STEP_VERSION);

    // Verify finalizer extension API table version fields
    EXPECT_EQ(fini_ext_api->version.major_id, HSA_FINALIZER_API_TABLE_MAJOR_VERSION);
    EXPECT_EQ(fini_ext_api->version.minor_id, sizeof(hsa::hsa_fini_ext_table_t));
    EXPECT_EQ(fini_ext_api->version.step_id, HSA_FINALIZER_API_TABLE_STEP_VERSION);

    // Verify image extension API table version fields
    EXPECT_EQ(img_ext_api->version.major_id, HSA_IMAGE_API_TABLE_MAJOR_VERSION);
    EXPECT_EQ(img_ext_api->version.minor_id, sizeof(hsa::hsa_img_ext_table_t));
    EXPECT_EQ(img_ext_api->version.step_id, HSA_IMAGE_API_TABLE_STEP_VERSION);

    // Verify tools API table version fields
    EXPECT_EQ(tool_api->version.major_id, HSA_TOOLS_API_TABLE_MAJOR_VERSION);
    EXPECT_EQ(tool_api->version.minor_id, sizeof(hsa::hsa_amd_tool_table_t));
    EXPECT_EQ(tool_api->version.step_id, HSA_TOOLS_API_TABLE_STEP_VERSION);

#if ROCPROFILER_SDK_HSA_PC_SAMPLING > 0
    // Verify PC sampling extension API table version fields
    EXPECT_EQ(pcs_api->version.major_id, HSA_PC_SAMPLING_API_TABLE_MAJOR_VERSION);
    EXPECT_EQ(pcs_api->version.minor_id, sizeof(hsa::hsa_pc_sampling_ext_table_t));
    EXPECT_EQ(pcs_api->version.step_id, HSA_PC_SAMPLING_API_TABLE_STEP_VERSION);
#endif

    //------------------------------------------------------------------------//
    //  Cross-check between different retrieval methods
    //------------------------------------------------------------------------//
    // Ensure consistency of version info across retrieval approaches
    EXPECT_EQ(full_table.version.major_id, ver_info.major_id);
    EXPECT_EQ(full_table.version.minor_id, ver_info.minor_id);
    EXPECT_EQ(full_table.version.step_id, ver_info.step_id);

    // Ensure pointer identity for all table components
    EXPECT_EQ(full_table.core_, core_api);
    EXPECT_EQ(full_table.amd_ext_, amd_ext_api);
    EXPECT_EQ(full_table.finalizer_ext_, fini_ext_api);
    EXPECT_EQ(full_table.image_ext_, img_ext_api);
}

#include <iostream>

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int start_depth;
    std::cin >> start_depth;

    if (start_depth == 0) {
        return 0;
    }

    int current_depth = start_depth;
    int previous_up_color = -1;
    int exit_reached;

    while (current_depth > 0) {
        int up_color = -1;

        if (previous_up_color == -1) {
            // Initial step: determine upward direction by testing colors
            // Try color 0 first
            std::cout << "move 0" << std::endl;
            std::cin >> exit_reached;
            if (exit_reached) return 0;

            std::cout << "query" << std::endl;
            int new_depth;
            std::cin >> new_depth;

            std::cout << "move 0" << std::endl; // Return to original position
            std::cin >> exit_reached;

            if (new_depth < current_depth) {
                up_color = 0;
            } else {
                // Try color 1
                std::cout << "move 1" << std::endl;
                std::cin >> exit_reached;
                if (exit_reached) return 0;

                std::cout << "query" << std::endl;
                std::cin >> new_depth;

                std::cout << "move 1" << std::endl; // Return to original position
                std::cin >> exit_reached;

                if (new_depth < current_depth) {
                    up_color = 1;
                } else {
                    up_color = 2;
                }
            }
        } else {
            // Subsequent steps: use known downward color to infer remaining options
            int option1 = (previous_up_color + 1) % 3;
            int option2 = (previous_up_color + 2) % 3;

            // Test option1
            std::cout << "move " << option1 << std::endl;
            std::cin >> exit_reached;
            if (exit_reached) return 0;

            std::cout << "query" << std::endl;
            int new_depth;
            std::cin >> new_depth;

            std::cout << "move " << option1 << std::endl; // Return to original position
            std::cin >> exit_reached;

            if (new_depth < current_depth) {
                up_color = option1;
            } else {
                up_color = option2;
            }
        }

        // Final move for this level
        std::cout << "move " << up_color << std::endl;
        std::cin >> exit_reached;
        if (exit_reached) {
            return 0;
        }

        current_depth--;
        previous_up_color = up_color;
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <random>
#include <ctime>
using namespace std;

// Structure representing an edge between two nodes
struct Connection {
    int from, to;
};

// Global configuration variables
int NODE_COUNT, EDGE_COUNT;
vector<Connection> connections;
vector<vector<int>> adjacency; // adjacency[u] holds indices of edges incident to u
vector<int> optimal_config;    // Best valid vertex cover found so far
int optimal_size;              // Size (number of vertices) in the best solution

void optimize() {
    // Set time limit slightly below 2 seconds
    double max_time = 1.9;
    clock_t begin = clock();

    // Initialize random number generator with fixed seed for reproducibility
    mt19937 prng(1337);

    // Start with trivial solution: all vertices included
    optimal_config.assign(NODE_COUNT + 1, 1);
    optimal_size = NODE_COUNT;

    // Precompute initial degrees for efficiency
    vector<int> initial_deg(NODE_COUNT + 1, 0);
    for (const auto& conn : connections) {
        initial_deg[conn.from]++;
        initial_deg[conn.to]++;
    }

    // Reusable data structures for repeated iterations
    vector<int> current_config(NODE_COUNT + 1);
    vector<int> dynamic_deg(NODE_COUNT + 1);
    vector<int> edge_state(EDGE_COUNT);         // 0 = uncovered, 1 = covered
    vector<int> active_edges(EDGE_COUNT);       // List of currently uncovered edge indices
    vector<int> edge_position(EDGE_COUNT);      // Maps edge index -> position in active_edges
    vector<int> coverage_count(EDGE_COUNT);     // How many selected vertices cover each edge
    vector<int> selected_vertices;              // Vertices currently in the solution
    selected_vertices.reserve(NODE_COUNT);

    // Main loop: generate candidate solutions until time runs out
    while (true) {
        // Check if we've exceeded the time budget
        double elapsed = (double)(clock() - begin) / CLOCKS_PER_SEC;
        if (elapsed > max_time) break;

        // --- Reset state for new iteration ---
        fill(current_config.begin(), current_config.end(), 0);
        dynamic_deg = initial_deg;

        // Initialize edge tracking arrays
        for (int i = 0; i < EDGE_COUNT; ++i) {
            active_edges[i] = i;
            edge_position[i] = i;
            edge_state[i] = 0;
        }
        int remaining_edges = EDGE_COUNT;
        int current_solution_size = 0;

        // --- Greedy construction phase ---
        while (remaining_edges > 0) {
            // Select a random uncovered edge
            int rand_index = prng() % remaining_edges;
            int edge_idx = active_edges[rand_index];

            int node_u = connections[edge_idx].from;
            int node_v = connections[edge_idx].to;

            // Choose endpoint with higher dynamic degree (tie-break randomly)
            int chosen_node = -1;
            if (dynamic_deg[node_u] > dynamic_deg[node_v]) {
                chosen_node = node_u;
            } else if (dynamic_deg[node_v] > dynamic_deg[node_u]) {
                chosen_node = node_v;
            } else {
                chosen_node = (prng() & 1) ? node_u : node_v;
            }

            // Add chosen node to solution
            current_config[chosen_node] = 1;
            current_solution_size++;

            // Update coverage and degrees for incident edges
            for (int inc_edge : adjacency[chosen_node]) {
                if (edge_state[inc_edge] == 1) continue;

                edge_state[inc_edge] = 1;

                // Remove this edge from active list in O(1)
                int pos = edge_position[inc_edge];
                int last_edge = active_edges[remaining_edges - 1];

                active_edges[pos] = last_edge;
                edge_position[last_edge] = pos;

                remaining_edges--;

                // Decrease degree of neighbor node
                int neighbor = (connections[inc_edge].from == chosen_node) 
                             ? connections[inc_edge].to 
                             : connections[inc_edge].from;
                dynamic_deg[neighbor]--;
            }
        }

        // --- Optimization phase: remove redundant vertices ---
        fill(coverage_count.begin(), coverage_count.end(), 0);
        selected_vertices.clear();

        // Compute coverage counts
        for (int v = 1; v <= NODE_COUNT; ++v) {
            if (current_config[v]) {
                selected_vertices.push_back(v);
                for (int e_idx : adjacency[v]) {
                    coverage_count[e_idx]++;
                }
            }
        }

        // Randomize processing order to explore different local minima
        shuffle(selected_vertices.begin(), selected_vertices.end(), prng);

        for (int node : selected_vertices) {
            bool can_remove = true;

            // Check if all edges incident to 'node' are covered by other vertices
            for (int e_idx : adjacency[node]) {
                if (coverage_count[e_idx] < 2) {
                    can_remove = false;
                    break;
                }
            }

            if (can_remove) {
                current_config[node] = 0;
                current_solution_size--;

                // Update coverage counts
                for (int e_idx : adjacency[node]) {
                    coverage_count[e_idx]--;
                }
            }
        }

        // --- Update global best solution ---
        if (current_solution_size < optimal_size) {
            optimal_size = current_solution_size;
            optimal_config = current_config;
        }
    }
}

int main() {
    // Speed up I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    if (cin >> NODE_COUNT >> EDGE_COUNT) {
        adjacency.resize(NODE_COUNT + 1);
        connections.reserve(EDGE_COUNT);

        for (int i = 0; i < EDGE_COUNT; ++i) {
            int u, v;
            cin >> u >> v;
            connections.push_back({u, v});
            adjacency[u].push_back(i);
            adjacency[v].push_back(i);
        }

        optimize();

        // Output final solution
        for (int i = 1; i <= NODE_COUNT; ++i) {
            cout << optimal_config[i] << "\n";
        }
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

// Interactive solution using randomized signature matching
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    if (!(cin >> T)) return 0;

    while (T--) {
        int n;
        if (!(cin >> n)) return 0;

        // Fixed excluded position (1-indexed)
        int fixed_pos = 2;  
        cout << fixed_pos << '\n';
        cout.flush();

        auto query = [&](const vector<int>& perm) -> int {
            cout << "?";
            for (int val : perm) {
                cout << ' ' << val;
            }
            cout << '\n';
            cout.flush();

            int result;
            if (!(cin >> result)) exit(0);
            if (result == -1) exit(0);
            return result;
        };

        // Number of queries: capped at 200 or 10*n, whichever is smaller
        int num_queries = min(10 * n, 200);

        // Generate random permutations
        vector<vector<int>> permutations;
        permutations.reserve(num_queries);
        vector<int> base(n);
        iota(base.begin(), base.end(), 1);

        mt19937_64 rng(584729 + n * 123456);

        for (int t = 0; t < num_queries; ++t) {
            shuffle(base.begin(), base.end(), rng);
            permutations.push_back(base);
        }

        // Precompute positions: pos[t][value] = index in permutation t
        vector<vector<int>> positions(num_queries, vector<int>(n + 1));
        for (int t = 0; t < num_queries; ++t) {
            for (int idx = 0; idx < n; ++idx) {
                positions[t][permutations[t][idx]] = idx;
            }
        }

        // Ask all queries and store responses
        vector<int> answers(num_queries);
        for (int t = 0; t < num_queries; ++t) {
            answers[t] = query(permutations[t]);
        }

        // Build cost matrix for assignment problem
        const int INF_COST = 1e9;
        vector<vector<int>> cost_matrix(n, vector<int>(n, INF_COST));

        int fixed_idx = fixed_pos - 1; // convert to 0-based

        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j <= n; ++j) {
                if (i == j) continue;

                int penalty = 0;
                for (int t = 0; t < num_queries; ++t) {
                    int pos_i = positions[t][i];
                    int pos_j = positions[t][j];

                    int contribution = (pos_i != fixed_idx && pos_i < pos_j) ? 1 : 0;

                    if (contribution) {
                        penalty += (num_queries - answers[t]);
                    } else {
                        penalty += answers[t];
                    }

                    if (penalty > INF_COST / 2) break;
                }
                cost_matrix[i - 1][j - 1] = penalty;
            }
        }

        // Hungarian algorithm for minimum cost assignment
        int N = n;
        vector<int> u(N + 1), v(N + 1), p_match(N + 1), path(N + 1);

        for (int i = 1; i <= N; ++i) {
            p_match[0] = i;
            int j0 = 0;
            vector<int> min_vals(N + 1, INF_COST);
            vector<bool> visited(N + 1, false);

            do {
                visited[j0] = true;
                int i0 = p_match[j0];
                int delta = INF_COST;
                int j1 = 0;

                for (int j = 1; j <= N; ++j) {
                    if (!visited[j]) {
                        int current = cost_matrix[i0 - 1][j - 1] - u[i0] - v[j];
                        if (current < min_vals[j]) {
                            min_vals[j] = current;
                            path[j] = j0;
                        }
                        if (min_vals[j] < delta) {
                            delta = min_vals[j];
                            j1 = j;
                        }
                    }
                }

                for (int j = 0; j <= N; ++j) {
                    if (visited[j]) {
                        u[p_match[j]] += delta;
                        v[j] -= delta;
                    } else {
                        min_vals[j] -= delta;
                    }
                }
                j0 = j1;
            } while (p_match[j0] != 0);

            do {
                int j1 = path[j0];
                p_match[j0] = p_match[j1];
                j0 = j1;
            } while (j0);
        }

        // Reconstruct the permutation
        vector<int> permutation_result(n + 1);
        for (int j = 1; j <= N; ++j) {
            int i = p_match[j];
            permutation_result[i] = j;
        }

        // Fix any fixed points (derangement constraint)
        vector<int> fixed_points;
        for (int i = 1; i <= n; ++i) {
            if (permutation_result[i] == i) {
                fixed_points.push_back(i);
            }
        }

        if (!fixed_points.empty()) {
            int sz = fixed_points.size();
            for (int idx = 0; idx < sz; ++idx) {
                int a = fixed_points[idx];
                int b = fixed_points[(idx + 1) % sz];
                swap(permutation_result[a], permutation_result[b]);
            }
        }

        // Output final answer
        cout << "!";
        for (int i = 1; i <= n; ++i) {
            cout << ' ' << permutation_result[i];
        }
        cout << '\n';
        cout.flush();
    }

    return 0;
}

#include <vector>
#include <algorithm>
#include <queue>
#include <cmath>

class Solution {
public:
    double mincostToHireWorkers(std::vector<int>& quality, std::vector<int>& wage, int groupSize) {
        int totalWorkers = quality.size();
        double bestCost = 1e18;

        for (int idx = 0; idx < totalWorkers; ++idx) {
            double unitRatio = static_cast<double>(wage[idx]) / quality[idx];
            std::vector<double> eligibleWages;

            for (int jdx = 0; jdx < totalWorkers; ++jdx) {
                int currQuality = quality[jdx];
                int currWage = wage[jdx];

                if (unitRatio * currQuality >= currWage) {
                    eligibleWages.push_back(unitRatio * currQuality);
                }
            }

            std::sort(eligibleWages.begin(), eligibleWages.end());

            if (eligibleWages.size() < static_cast<size_t>(groupSize)) {
                continue;
            }

            double groupTotal = 0.0;
            for (int kdx = 0; kdx < groupSize; ++kdx) {
                groupTotal += eligibleWages[kdx];
            }

            bestCost = std::min(bestCost, groupTotal);
        }

        return bestCost;
    }
};

