// Helper macros for generating unique names
#define CAT_IMPL(s1, s2) s1##s2
#define CAT(s1, s2) CAT_IMPL(s1, s2)
#define UNIQUE_VAR(x) CAT(x, __COUNTER__)

// Interface for exception translators
struct ITranslator {
    virtual bool translate(string&) = 0;
};

// Template class implementing a translator for a specific exception type
template<typename T>
struct ExceptionTranslator : ITranslator {
    ExceptionTranslator(string(*handler)(T)) : m_handler(handler) {}

    bool translate(string& result) override {
        try {
            throw;
        } catch(T ex) {
            result = m_handler(ex);
            return true;
        } catch(...) {
            return false;
        }
    }

    string(*m_handler)(T);
};

// Forward declaration of registration function
void registerTranslatorImpl(ITranslator* t);

// Registration function template
template<typename T>
int registerTranslator(string(*handler)(T)) {
    static ExceptionTranslator<T> translator(handler);
    registerTranslatorImpl(&translator);
    return 0;
}

// Macro to define and register a translator
#define DEFINE_TRANSLATOR_2(name, type)                  \
    static string name(type);                            \
    static int UNIQUE_VAR(REG_) = registerTranslator(&name); \
    static string name(type)

#define DEFINE_TRANSLATOR(type) DEFINE_TRANSLATOR_2(UNIQUE_VAR(EXC_TRANS_), type)

// Storage for translators
vector<ITranslator*> translatorList;

// Implementation of translator registration
void registerTranslatorImpl(ITranslator* t) {   
    translatorList.push_back(t);
}

// Main translation function
string handleException() {
    // Try registered translators
    string result;
    for(size_t idx = 0; idx < translatorList.size(); ++idx) {
        if(translatorList[idx]->translate(result)) {
            return result;
        }
    }

    // Fallback to default exception handling
    try {
        throw;
    } catch(exception& ex) {
        return ex.what();
    } catch(string& msg) {
        return msg;
    } catch(const char* msg) {
        return msg;
    } catch(...) {
        return "Unknown exception!";
    }
}

// Define and register a translator for double exceptions
DEFINE_TRANSLATOR(double& e) {
    return string("double value: ") + to_string(e);
}

int main() {
    try {
        //throw 42;
        throw 5.0;
        //throw runtime_error("error occurred!");
    } catch(...) {
        cout << handleException() << endl;
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int N;
    cin >> N;

    double baseMM = 10000.0;
    double baseXX = 20001.0;

    // Initial phase: estimate slope and intercept
    double y_start = -300000000.0;
    double step_size = 10000000.0;
    double y_end = y_start + step_size;

    cout << "? " << baseXX << " " << y_start << endl;
    cout.flush();
    double val_start;
    cin >> val_start;

    cout << "? " << baseXX << " " << y_end << endl;
    cout.flush();
    double val_end;
    cin >> val_end;

    double initial_slope = (val_end - val_start) / step_size;
    double weight = -initial_slope;
    double intercept = val_start + y_start * weight;

    double current_slope = -weight;
    double current_intercept = intercept;
    int last_a_index = -10001;

    vector<int> a_values, b_values;

    const double slope_tolerance = 1e-4;
    const double epsilon = 0.4;
    const double diff_threshold = 3e-5;

    for(int idx = 0; idx < N; idx++) {
        // Binary search to find next 'a'
        int left = last_a_index + 1;
        int right = 10000;

        while (left < right) {
            int mid = (left + right) / 2;
            double test_y = mid * baseXX + baseMM;

            cout << "? " << baseXX << " " << test_y << endl;
            cout.flush();
            double f_test;
            cin >> f_test;

            double test_y_plus = test_y + epsilon;
            cout << "? " << baseXX << " " << test_y_plus << endl;
            cout.flush();
            double f_test_plus;
            cin >> f_test_plus;

            double estimated_slope = (f_test_plus - f_test) / epsilon;

            if (estimated_slope > current_slope + slope_tolerance) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }

        // Verify candidate 'a'
        int candidate_a = left;
        double test_y = candidate_a * baseXX + baseMM;

        cout << "? " << baseXX << " " << test_y << endl;
        cout.flush();
        double f_candidate;
        cin >> f_candidate;

        double test_y_plus = test_y + epsilon;
        cout << "? " << baseXX << " " << test_y_plus << endl;
        cout.flush();
        double f_candidate_plus;
        cin >> f_candidate_plus;

        double final_slope = (f_candidate_plus - f_candidate) / epsilon;

        if (final_slope <= current_slope + slope_tolerance) {
            // Skip invalid candidate
            continue;
        }

        int a_found = candidate_a;

        // Local binary search for precise p value
        double lower_p = a_found * baseXX - baseMM;
        double upper_p = a_found * baseXX + baseMM;

        int local_iterations = 0;
        const int max_local_iterations = 60;

        while ((upper_p - lower_p) > 1e-10 && local_iterations < max_local_iterations) {
            local_iterations++;
            double mid_p = (lower_p + upper_p) / 2.0;

            cout << "? " << baseXX << " " << mid_p << endl;
            cout.flush();
            double f_mid;
            cin >> f_mid;

            double expected = current_slope * mid_p + current_intercept;
            double deviation = f_mid - expected;

            if (deviation > diff_threshold) {
                upper_p = mid_p;
            } else {
                lower_p = mid_p;
            }
        }

        double approx_p = (lower_p + upper_p) / 2.0;
        long long a_component = llround(approx_p / baseXX);
        double remainder = approx_p - a_component * baseXX;
        double exact_p = a_component * baseXX + round(remainder);

        long long b_component = llround(exact_p - a_component * baseXX);

        a_values.push_back((int)a_component);
        b_values.push_back((int)b_component);

        // Update slope and intercept
        double aa_val = (double)a_component;
        double ww_val = 1.0 / sqrt(aa_val * aa_val + 1.0);
        double old_exp = current_slope * exact_p + current_intercept;

        current_slope += 2.0 * ww_val;
        current_intercept = old_exp - current_slope * exact_p;

        last_a_index = (int)a_component;
    }

    // Output final result
    cout << "!";
    for (int a : a_values) cout << " " << a;
    for (int b : b_values) cout << " " << b;
    cout << endl;
    cout.flush();

    return 0;
}

