namespace {
// Helper struct to hold a vector with its ID
struct VectorData {
    uint64_t _identifier {0};
    std::vector<float> dataPoints;
};

// Compute squared Euclidean distance between two vectors
float computeSquaredDistance(const std::vector<float>& firstVec, const std::vector<float>& secondVec) {
    float result = 0.0f;
    for (size_t idx = 0; idx < firstVec.size(); ++idx) {
        const float diff = firstVec[idx] - secondVec[idx];
        result += diff * diff;
    }
    return result;
}

// Find k nearest neighbors using Euclidean distance
void getNearestNeighbors(std::vector<uint64_t>& output,
                         const std::vector<VectorData>& dataset,
                         const std::vector<float>& target,
                         size_t count) {
    // Compute distances for all vectors
    std::vector<std::pair<float, uint64_t>> distanceList;
    for (const auto& item : dataset) {
        const float dist = computeSquaredDistance(item.dataPoints, target);
        distanceList.emplace_back(dist, item._identifier);
    }

    // Sort by distance (ascending)
    std::sort(distanceList.begin(), distanceList.end(),
              [](const auto& a, const auto& b) { return a.first < b.first; });

    // Extract top k IDs
    output.clear();
    for (size_t i = 0; i < count && i < distanceList.size(); ++i) {
        output.push_back(distanceList[i].second);
    }
}
}  // namespace

