#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int blackCount, whiteCount, rows, cols;
    if (!(cin >> blackCount >> whiteCount >> rows >> cols)) return 0;

    // Special case: 1D optimal arrangement when counts differ by at most 1
    if (abs(blackCount - whiteCount) <= 1) {
        int r = 1, c = blackCount + whiteCount;
        cout << r << " " << c << "\n";

        bool firstColor = (blackCount >= whiteCount);
        int placedBlack = 0, placedWhite = 0;

        for (int idx = 0; idx < c; ++idx) {
            bool placeBlack = ((idx % 2 == 0) ? firstColor : !firstColor);

            if (placeBlack) {
                if (placedBlack < blackCount) {
                    cout << '@';
                    placedBlack++;
                } else {
                    cout << '.';
                    placedWhite++;
                }
            } else {
                if (placedWhite < whiteCount) {
                    cout << '.';
                    placedWhite++;
                } else {
                    cout << '@';
                    placedBlack++;
                }
            }
        }
        cout << "\n";
        return 0;
    }

    // General construction with 5 rows:
    // Top 2 rows: white background with black islands on row 0 at even positions.
    // Middle row: black separator with one white cell to link a white island.
    // Bottom 2 rows: black background with white islands on row 3 at even positions.

    int width = max(2*blackCount - 1, 2*whiteCount - 1);
    int height = 5;
    vector<string> grid(height, string(width, '@'));

    // Initialize grid:
    // Rows 0-1 as white
    for (int col = 0; col < width; ++col) {
        grid[0][col] = '.';
        grid[1][col] = '.';
    }
    // Row 2 remains black by default (already '@')
    // Rows 3-4 remain black by default (already '@')

    // Place black islands in upper section (row 0 at even columns)
    for (int i = 0; i < blackCount; ++i) {
        int column = 2*i;
        grid[0][column] = '@';
        // Ensure separator columns (odd) in upper section stay white
        if (column + 1 < width) {
            grid[0][column+1] = '.';
            grid[1][column+1] = '.';
        }
    }

    // Place white islands in lower section (row 3 at even columns)
    for (int i = 0; i < whiteCount; ++i) {
        int column = 2*i;
        grid[3][column] = '.';
        // Separator columns (odd) remain black (already '@')
    }

    // Connect one black island to black base: set row 1 at a black island column to '@'
    int conn1;
    if (blackCount == 1) {
        // Use column 0 (only island) for black connection
        conn1 = 0;
    } else {
        // rightmost black island column
        conn1 = 2*(blackCount-1);
    }
    grid[1][conn1] = '@';

    // Connect one white island to upper white base through row 2 white cell at a different island column
    int conn2;
    if (blackCount == 1) {
        // Ensure different column from conn1=0; need whiteCount>=2 (since |b-w|>1 implies w>=3 when b=1)
        conn2 = (whiteCount >= 2 ? 2 : 0);
    } else {
        // choose the leftmost white island at column 0
        conn2 = 0;
        if (conn2 == conn1) {
            // if by chance equal (when conn1==0), shift to next available white island column if exists
            if (whiteCount >= 2) conn2 = 2;
            else {
                // fallback: expand grid by 2 columns to the right
                int oldWidth = width;
                width += 2;
                for (int r = 0; r < height; ++r) grid[r].resize(width, '@');
                grid[0].replace(oldWidth, 2, "..");
                grid[1].replace(oldWidth, 2, "..");
                // row2 '@@' already
                // rows3-4 '@@' already
                conn2 = oldWidth; // new even column
                grid[3][conn2] = '.';
            }
        }
    }

    // Ensure conn2 within bounds and corresponds to a white island column
    if (conn2 >= width) {
        // Shouldn't happen due to above handling, but guard
        conn2 = (whiteCount >= 1 ? 2*(whiteCount-1) : 0);
        if (conn2 >= width) conn2 = 0;
    }

    // Make separator at conn2 white to connect that white island to upper white base
    grid[2][conn2] = '.';

    // Output result
    cout << height << " " << width << "\n";
    for (int r = 0; r < height; ++r) {
        cout << grid[r] << "\n";
    }

    return 0;
}

#include "benchmark/benchmark.h"
#include "spdlog/spdlog.h"
#include "spdlog/pattern_formatter.h"

// Benchmark function for pattern formatting performance
void formatter_performance_test(benchmark::State &state, std::string format_string) {
    auto formatter = spdlog::details::make_unique<spdlog::pattern_formatter>(format_string);
    spdlog::memory_buf_t output_buffer;
    std::string log_channel = "channel-name";
    const char *message_content =
        "Sample log entry with 80 characters long text content here          ";
    spdlog::source_loc location_info{"src/module/submodule/file.cpp", 456, "test_function()"};
    spdlog::details::log_msg log_entry(location_info, log_channel, spdlog::level::warn, message_content);

    for (auto _ : state) {
        output_buffer.clear();
        formatter->format(log_entry, output_buffer);
        benchmark::DoNotOptimize(output_buffer);
    }
}

// Run multiple formatting benchmarks
void run_all_format_benchmarks() {
    // Test individual format flags
    std::string all_format_flags = "+vtPnlLaAbBcCYDmdHIMSefFprRTXzEisg@luioO%";
    std::vector<std::string> single_flag_patterns;
    for (auto &flag_char : all_format_flags) {
        auto pattern_str = std::string("%") + flag_char;
        benchmark::RegisterBenchmark(pattern_str.c_str(), &formatter_performance_test, pattern_str);

        // Additional padding tests commented out
        // pattern_str = std::string("%16") + flag_char;
        // benchmark::RegisterBenchmark(pattern_str.c_str(), &formatter_performance_test, pattern_str);
        // pattern_str = std::string("%=16") + flag_char;
        // benchmark::RegisterBenchmark(pattern_str.c_str(), &formatter_performance_test, pattern_str);
    }

    // Complex real-world patterns
    std::vector<std::string> complex_patterns = {
        "[%Y-%m-%d %H:%M:%S] [%l] [%n] %v",
        "[%D %T] [%l] [%n] %v",
        "[%Y/%m/%d %H:%M:%S.%f] [%l] [%n] [%t] %v",
    };

    for (auto &pattern : complex_patterns) {
        benchmark::RegisterBenchmark(pattern.c_str(), &formatter_performance_test, pattern)
            ->Iterations(2000000);
    }
}

int main(int argument_count, char *arguments[]) {
    spdlog::set_pattern("[%^%t%$] %v");

    if (argument_count != 2) {
        spdlog::error("Usage: {} <pattern> (or \"all\" to test all)", arguments[0]);
        return 1;
    }

    std::string selected_pattern = arguments[1];
    if (selected_pattern == "all") {
        run_all_format_benchmarks();
    } else {
        benchmark::RegisterBenchmark(selected_pattern.c_str(), &formatter_performance_test, selected_pattern);
    }

    benchmark::Initialize(&argument_count, arguments);
    benchmark::RunSpecifiedBenchmarks();
    return 0;
}

