namespace {

/// This pass computes liveness data for each basic block in a function and
/// attaches register live-out information to patchpoint intrinsics when present.
///
/// The pass can be disabled using the -enable-patchpoint-liveness=false flag.
/// Functions lacking any patchpoint intrinsics are bypassed. The data this pass
/// generates is optional and not required by the patchpoint intrinsic itself.
class StackMapLiveness : public MachineFunctionPass {
  const TargetRegisterInfo *TRI = nullptr;
  LivePhysRegs LiveRegs;

public:
  static char ID;

  /// Constructor: initializes the pass.
  StackMapLiveness();

  /// Declare analysis dependencies and preserved info.
  void getAnalysisUsage(AnalysisUsage &AU) const override;

  MachineFunctionProperties getRequiredProperties() const override {
    return MachineFunctionProperties().set(
        MachineFunctionProperties::Property::NoVRegs);
  }

  /// Main entry point: process the given machine function.
  bool runOnMachineFunction(MachineFunction &MF) override;

private:
  /// Core logic: perform liveness analysis on MF.
  bool performLivenessAnalysis(MachineFunction &MF);

  /// Attach current live register set to the given instruction.
  void attachLiveOutToInstr(MachineFunction &MF, MachineInstr &MI);

  /// Build and return a register mask based on current live registers.
  uint32_t *buildRegisterMask(MachineFunction &MF) const;
};

} // anonymous namespace

char StackMapLiveness::ID = 0;
char &llvm::StackMapLivenessID = StackMapLiveness::ID;

INITIALIZE_PASS(StackMapLiveness, "stackmap-liveness",
                "StackMap Liveness Analysis", false, false)

StackMapLiveness::StackMapLiveness() : MachineFunctionPass(ID) {
  initializeStackMapLivenessPass(*PassRegistry::getPassRegistry());
}

void StackMapLiveness::getAnalysisUsage(AnalysisUsage &AU) const {
  AU.setPreservesAll();
  AU.setPreservesCFG();
  MachineFunctionPass::getAnalysisUsage(AU);
}

bool StackMapLiveness::runOnMachineFunction(MachineFunction &MF) {
  if (!EnablePatchPointLiveness)
    return false;

  LLVM_DEBUG(dbgs() << "********** COMPUTING STACKMAP LIVENESS: "
                    << MF.getName() << " **********\n");

  TRI = MF.getSubtarget().getRegisterInfo();
  ++NumStackMapFuncVisited;

  if (!MF.getFrameInfo().hasPatchPoint()) {
    ++NumStackMapFuncSkipped;
    return false;
  }

  return performLivenessAnalysis(MF);
}

bool StackMapLiveness::performLivenessAnalysis(MachineFunction &MF) {
  bool Modified = false;

  for (auto &MBB : MF) {
    LLVM_DEBUG(dbgs() << "****** BB " << MBB.getName() << " ******\n");

    LiveRegs.init(*TRI);
    LiveRegs.addLiveOutsNoPristines(MBB);

    bool ContainsStackmap = false;

    for (MachineInstr &Instr : llvm::reverse(MBB)) {
      if (Instr.getOpcode() == TargetOpcode::PATCHPOINT) {
        attachLiveOutToInstr(MF, Instr);
        Modified = true;
        ContainsStackmap = true;
        ++NumStackMaps;
      }

      LLVM_DEBUG(dbgs() << "   " << LiveRegs << "   " << Instr);
      LiveRegs.stepBackward(Instr);
    }

    ++NumBBsVisited;
    if (!ContainsStackmap)
      ++NumBBsHaveNoStackmap;
  }

  return Modified;
}

void StackMapLiveness::attachLiveOutToInstr(MachineFunction &MF,
                                            MachineInstr &MI) {
  uint32_t *Mask = buildRegisterMask(MF);
  MachineOperand Operand = MachineOperand::CreateRegLiveOut(Mask);
  MI.addOperand(MF, Operand);
}

uint32_t *StackMapLiveness::buildRegisterMask(MachineFunction &MF) const {
  uint32_t *Mask = MF.allocateRegMask();

  for (auto Reg : LiveRegs)
    Mask[Reg / 32] |= 1U << (Reg % 32);

  TRI->adjustStackMapLiveOutMask(Mask);
  return Mask;
}

