void XmlBtPolarWriter::writeXMLBtPolar(BoatPolar *polarData)
{
    if (!polarData) return;

    setAutoFormatting(true);
    writeStartDocument();

    {
        writeDTD("<!DOCTYPE flow5>");
        writeStartElement("XflBoatPolar");
        {
            writeAttribute("version", "1.0");
            writeUnits();
            writeBtPolarInformation(polarData);
        }
        writeEndElement();
    }

    writeEndDocument();
}

void XmlBtPolarWriter::writeBtPolarInformation(BoatPolar const *polarInfo)
{
    QString buffer;
    writeStartElement("Polar");
    {
        writeTextElement("Polar_Name", QString::fromStdString(polarInfo->name()));
        writeComment("For automation: leaving boat name blank associates analysis with all available vessels");
        writeTextElement("Boat_Name", QString::fromStdString(polarInfo->boatName()));
        writeComment("All vessel performance curves are defined as control-type data");
        writeTheStyle(polarInfo->theStyle());
        writeTextElement("Method", xml::analysisMethod(polarInfo->analysisMethod()));

        writeStartElement("Reference_Dimensions");
        {
            writeComment("Valid options: AUTO or CUSTOM");
            writeTextElement("Reference_Dimensions",   xml::referenceDimension(polarInfo->referenceDim()));
            writeComment("These parameters apply only when Reference_Dimensions is CUSTOM");
            writeTextElement("Reference_Area",         QString::asprintf("%11.5f", polarInfo->referenceArea() * Units::m2toUnit()));
            writeTextElement("Reference_Chord_Length", QString::asprintf("%11.5f", polarInfo->referenceChordLength() * Units::mtoUnit()));
        }
        writeEndElement();

        writeWakeData(*polarInfo);

        buffer = QString::asprintf("%g, %g, %g",
                                   polarInfo->CoG().x * Units::mtoUnit(),
                                   polarInfo->CoG().y * Units::mtoUnit(),
                                   polarInfo->CoG().z * Units::mtoUnit());
        writeTextElement("CoG", buffer);

        writeStartElement("Wind_gradient");
        {
            writeWindSpline(polarInfo->windSpline());
        }
        writeEndElement();

        writeFluidProperties(polarInfo->viscosity(), polarInfo->density());

        if (polarInfo->hasExtraDrag())
            writeExtraDrag(polarInfo->extraDragList());

        writeComment("Lower and upper bounds separated by comma");
        writeTextElement("Boat_Speed", QString::asprintf(" %g, %g", polarInfo->VBtMin(),  polarInfo->VBtMax()));
        writeTextElement("TWS",        QString::asprintf(" %g, %g", polarInfo->qInfMin(), polarInfo->qInfMax()));
        writeTextElement("TWA",        QString::asprintf(" %g, %g", polarInfo->twaMin(),  polarInfo->twaMax()));
        writeTextElement("Phi",        QString::asprintf(" %g, %g", polarInfo->phiMin(),  polarInfo->phiMax()));
        writeTextElement("Ry",         QString::asprintf(" %g, %g", polarInfo->RyMin(),   polarInfo->RyMax()));

        writeStartElement("SailAngles");
        {
            for (int idx = 0; idx < polarInfo->sailAngleSize(); ++idx)
            {
                QString label, values;
                label = QString::asprintf("Sail_%d", idx + 1);
                values = QString::asprintf("%.3f,  %.3f", polarInfo->sailAngleMin(idx), polarInfo->sailAngleMax(idx));
                writeTextElement(label, values);
            }
        }
        writeEndElement();
    }
    writeEndElement();
}

void XmlBtPolarWriter::writeWindSpline(BSpline const &splineData)
{
    writeTextElement("Degree", QString::asprintf("%d", splineData.degree()));
    for (int i = 0; i < splineData.ctrlPointCount(); ++i)
    {
        writeTextElement("Point", QString::asprintf("%g, %g",
                                                    splineData.controlPoint(i).x,
                                                    splineData.controlPoint(i).y)); // units in meters
    }
}

