#include "Buffer.h"
#include <cassert>

// Constructor: initializes buffer with specified capacity
Buffer::Buffer(unsigned int size)
: m_capacity(size),
  m_current(0),
  m_upperBound(size),
  hasStorage(false) {}

// Resets the buffer state. The current position becomes zero, the upper bound
// is set to the total capacity, and any existing mark is invalidated. This
// operation doesn't overwrite existing content but conceptually prepares the
// buffer for fresh data.
//
// Returns:
// Reference to the current buffer instance
Buffer* Buffer::reset() {
    m_current = 0;
    m_upperBound = m_capacity;
    return this;
}

// Adjusts the buffer's upper limit. If the current position exceeds the new
// limit, it gets adjusted down to match. Any existing mark beyond the new
// limit is removed.
// Parameters: newBound - Desired upper limit; must be >= 0 and <= buffer capacity
// Returns: Current buffer reference
Buffer* Buffer::setLimit(unsigned int newBound) {
    assert(newBound <= m_capacity);
    m_upperBound = newBound;
    if (m_current > newBound) m_current = newBound;
    return this;
}

// Accessor for the current limit value
unsigned int Buffer::getLimit() { return m_upperBound; }

// Updates the buffer's position pointer. If a mark exists beyond the new
// position, it gets cleared.
// Parameters: newIndex - New position index; must be >= 0 and <= current limit
// Returns: Current buffer reference
Buffer* Buffer::setPosition(unsigned int newIndex) {
    assert(newIndex <= m_upperBound);
    m_current = newIndex;
    return this;
}

// Retrieves the current position in the buffer
// Returns: Current position value
unsigned int Buffer::getPosition() { return m_current; }

// Calculates how many elements remain between current position and limit
// Returns: Count of available elements for reading/writing
unsigned int Buffer::getRemaining() { return m_upperBound - m_current; }

