// Class VectorRn
VectorRn VectorRn::WorkVector;
double VectorRn::MaxAbs() const {
  double maximum = 0.0;
  double *cursor = x;
  for (long count = length; count > 0; count--) {
    if ((*cursor) > maximum) {
      maximum = *cursor;
    } else if (-(*cursor) > maximum) {
      maximum = -(*cursor);
    }
    cursor++;
  }
  return maximum;
}

// MatrixRmn
MatrixRmn MatrixRmn::WorkMatrix;
void MatrixRmn::SetDiagonalEntries(double value) {
  long diagonalLength = std::min(NumRows, NumCols);
  double *diagonalPtr = x;
  for (; diagonalLength > 0; diagonalLength--) {
    *diagonalPtr = value;
    diagonalPtr += NumRows + 1;
  }
}

void MatrixRmn::SetDiagonalEntries(const VectorRn &values) {
  long diagonalLength = std::min(NumRows, NumCols);
  assert(values.length == diagonalLength);
  double *diagonalPtr = x;
  double *source = values.x;
  for (; diagonalLength > 0; diagonalLength--) {
    *diagonalPtr = *(source++);
    diagonalPtr += NumRows + 1;
  }
}

void MatrixRmn::SetSuperDiagonalEntries(double value) {
  long superDiagLength = std::min(NumRows, (long)(NumCols - 1));
  double *target = x + NumRows;
  for (; superDiagLength > 0; superDiagLength--) {
    *target = value;
    target += NumRows + 1;
  }
}

void MatrixRmn::SetSuperDiagonalEntries(const VectorRn &values) {
  long superDiagLength = std::min((long)(NumRows - 1), NumCols);
  assert(superDiagLength == values.length);
  double *target = x + NumRows;
  double *source = values.x;
  for (; superDiagLength > 0; superDiagLength--) {
    *target = *(source++);
    target += NumRows + 1;
  }
}

void MatrixRmn::SetSubDiagonalEntries(double value) {
  long subDiagLength = std::min(NumRows, NumCols) - 1;
  double *target = x + 1;
  for (; subDiagLength > 0; subDiagLength--) {
    *target = value;
    target += NumRows + 1;
  }
}

void MatrixRmn::SetSubDiagonalEntries(const VectorRn &values) {
  long subDiagLength = std::min(NumRows, NumCols) - 1;
  assert(subDiagLength == values.length);
  double *target = x + 1;
  double *source = values.x;
  for (; subDiagLength > 0; subDiagLength--) {
    *target = *(source++);
    target += NumRows + 1;
  }
}

void MatrixRmn::SetColumn(long colIndex, const VectorRn &values) {
  assert(NumRows == values.GetLength());
  double *target = x + colIndex * NumRows;
  const double *source = values.x;
  for (long i = NumRows; i > 0; i--) {
    *(target++) = *(source++);
  }
}

void MatrixRmn::SetRow(long rowIndex, const VectorRn &values) {
  assert(NumCols == values.GetLength());
  double *target = x + rowIndex;
  const double *source = values.x;
  for (long i = NumRows; i > 0; i--) {
    *target = *(source++);
    target += NumRows;
  }
}

void MatrixRmn::SetSequence(const VectorRn &values, long startRow, long startCol,
                            long rowStep, long colStep) {
  long length = values.length;
  assert(startRow >= 0 && startRow < NumRows && startCol >= 0 &&
         startCol < NumCols);
  assert(startRow + (length - 1) * rowStep >= 0 &&
         startRow + (length - 1) * rowStep < NumRows);
  assert(startCol + (length - 1) * colStep >= 0 &&
         startCol + (length - 1) * colStep < NumCols);
  double *target = x + startRow + NumRows * startCol;
  double *source = values.x;
  long stride = rowStep + NumRows * colStep;
  for (; length > 0; length--) {
    *target = *(source++);
    target += stride;
  }
}

void MatrixRmn::LoadAsSubmatrix(const MatrixRmn &source) {
  assert(source.NumRows <= NumRows && source.NumCols <= NumCols);
  int extraColStep = NumRows - source.NumRows;
  double *dest = x;
  double *src = source.x;
  for (long i = source.NumCols; i > 0; i--) {
    for (long j = source.NumRows; j > 0; j--) {
      *(dest++) = *(src++);
    }
    dest += extraColStep;
  }
}

void MatrixRmn::LoadAsSubmatrixTranspose(const MatrixRmn &source) {
  assert(source.NumRows <= NumCols && source.NumCols <= NumRows);
  double *rowPtr = x;
  double *src = source.x;
  for (long i = source.NumCols; i > 0; i--) {
    double *dest = rowPtr;
    for (long j = source.NumRows; j > 0; j--) {
      *dest = *(src++);
      dest += NumRows;
    }
    rowPtr++;
  }
}

double MatrixRmn::FrobeniusNorm() const { return sqrt(FrobeniusNormSq()); }

void MatrixRmn::Multiply(const VectorRn &vector, VectorRn &result) const {
  assert(vector.GetLength() == NumCols && result.GetLength() == NumRows);
  double *out = result.GetPtr();
  const double *rowPtr = x;
  for (long j = NumRows; j > 0; j--) {
    const double *in = vector.GetPtr();
    const double *matrixPtr = rowPtr++;
    *out = 0.0f;
    for (long i = NumCols; i > 0; i--) {
      *out += (*(in++)) * (*matrixPtr);
      matrixPtr += NumRows;
    }
    out++;
  }
}

void MatrixRmn::MultiplyTranspose(const VectorRn &vector, VectorRn &result) const {
  assert(vector.GetLength() == NumRows && result.GetLength() == NumCols);
  double *out = result.GetPtr();
  const double *colPtr = x;
  for (long i = NumCols; i > 0; i--) {
    const double *in = vector.GetPtr();
    *out = 0.0f;
    for (long j = NumRows; j > 0; j--) {
      *out += (*(in++)) * (*(colPtr++));
    }
    out++;
  }
}

double MatrixRmn::DotProductColumn(const VectorRn &vector, long colNum) const {
  assert(vector.GetLength() == NumRows);
  double *ptrC = x + colNum * NumRows;
  double *ptrV = vector.x;
  double result = 0.0;
  for (long i = NumRows; i > 0; i--) {
    result += (*(ptrC++)) * (*(ptrV++));
  }
  return result;
}

MatrixRmn &MatrixRmn::AddToDiagonal(double value) {
  long diagLength = std::min(NumRows, NumCols);
  double *diagPtr = x;
  for (; diagLength > 0; diagLength--) {
    *diagPtr += value;
    diagPtr += NumRows + 1;
  }
  return *this;
}

MatrixRmn &MatrixRmn::AddToDiagonal(const VectorRn &values) {
  long diagLength = std::min(NumRows, NumCols);
  double *diagPtr = x;
  const double *valPtr = values.x;
  for (; diagLength > 0; diagLength--) {
    *diagPtr += *(valPtr++);
    diagPtr += NumRows + 1;
  }
  return *this;
}

MatrixRmn &MatrixRmn::MultiplyScalar(const MatrixRmn &source, double factor,
                                     MatrixRmn &destination) {
  long numCols = source.NumCols;
  double *destPtr = destination.x;
  for (long i = destination.NumCols; i > 0; i--) {
    double *srcPtr = source.x;
    for (long j = destination.NumRows; j > 0; j--) {
      *destPtr = *srcPtr * factor;
      destPtr++;
      srcPtr++;
    }
    srcPtr += source.NumRows;
  }
  return destination;
}

MatrixRmn &MatrixRmn::Multiply(const MatrixRmn &first, const MatrixRmn &second,
                               MatrixRmn &destination) {
  assert(first.NumCols == second.NumRows && first.NumRows == destination.NumRows &&
         second.NumCols == destination.NumCols);
  long length = first.NumCols;
  double *bPtr = second.x;
  double *destPtr = destination.x;
  for (long i = destination.NumCols; i > 0; i--) {
    double *aPtr = first.x;
    for (long j = destination.NumRows; j > 0; j--) {
      *destPtr = DotArray(length, aPtr, first.NumRows, bPtr, 1);
      destPtr++;
      aPtr++;
    }
    bPtr += second.NumRows;
  }
  return destination;
}

MatrixRmn &MatrixRmn::TransposeMultiply(const MatrixRmn &first, const MatrixRmn &second,
                                        MatrixRmn &destination) {
  assert(first.NumRows == second.NumRows && first.NumCols == destination.NumRows &&
         second.NumCols == destination.NumCols);
  long length = first.NumRows;
  double *bPtr = second.x;
  double *destPtr = destination.x;
  for (long i = destination.NumCols; i > 0; i--) {
    double *aPtr = first.x;
    for (long j = destination.NumRows; j > 0; j--) {
      *destPtr = DotArray(length, aPtr, 1, bPtr, 1);
      destPtr++;
      aPtr += first.NumRows;
    }
    bPtr += second.NumRows;
  }
  return destination;
}

MatrixRmn &MatrixRmn::MultiplyTranspose(const MatrixRmn &first, const MatrixRmn &second,
                                        MatrixRmn &destination) {
  assert(first.NumCols == second.NumCols && first.NumRows == destination.NumRows &&
         second.NumRows == destination.NumCols);
  long length = first.NumCols;
  double *bPtr = second.x;
  double *destPtr = destination.x;
  for (long i = destination.NumCols; i > 0; i--) {
    double *aPtr = first.x;
    for (long j = destination.NumRows; j > 0; j--) {
      *destPtr = DotArray(length, aPtr, first.NumRows, bPtr, second.NumRows);
      destPtr++;
      aPtr++;
    }
    bPtr++;
  }
  return destination;
}

void MatrixRmn::Solve(const VectorRn &rightSide, VectorRn *solution) const {
  assert(NumRows == NumCols && NumCols == solution->GetLength() &&
         NumRows == rightSide.GetLength());
  MatrixRmn &augmented = GetWorkMatrix(NumRows, NumCols + 1);
  augmented.LoadAsSubmatrix(*this);
  augmented.SetColumn(NumRows, rightSide);
  augmented.ConvertToRefNoFree();

  double *lastSol = solution->x + NumRows - 1;
  double *endRow = augmented.x + NumRows * NumCols - 1;
  double *rhsPtr = endRow + NumRows;
  for (long i = NumRows; i > 0; i--) {
    double accum = *(rhsPtr--);
    double *rowPtr = endRow;
    double *solPtr = lastSol;
    for (long j = NumRows - i; j > 0; j--) {
      accum -= (*rowPtr) * (*(solPtr--));
      rowPtr -= NumCols;
    }
    assert(*rowPtr != 0.0);
    *solPtr = accum / (*rowPtr);
    endRow--;
  }
}

void MatrixRmn::ConvertToRefNoFree() {
  long iterations = std::min(NumRows, NumCols);
  double *rowPtr1 = x;
  const long diagStep = NumRows + 1;
  long remainingCols = NumCols;
  for (; iterations > 1; iterations--) {
    double *rowPtr2 = rowPtr1;
    double maxVal = fabs(*rowPtr1);
    double *pivotRow = rowPtr1;
    long i;
    for (i = iterations - 1; i > 0; i--) {
      const double &candidate = *(++pivotRow);
      if (candidate > maxVal) {
        maxVal = *pivotRow;
        rowPtr2 = pivotRow;
      } else if (-candidate > maxVal) {
        maxVal = -candidate;
        rowPtr2 = pivotRow;
      }
    }

    if (rowPtr1 != rowPtr2) {
      double *to = rowPtr1;
      for (long i = remainingCols; i > 0; i--) {
        double temp = *to;
        *to = *rowPtr2;
        *rowPtr2 = temp;
        to += NumRows;
        rowPtr2 += NumRows;
      }
    }

    rowPtr2 = rowPtr1;
    for (i = iterations - 1; i > 0; i--) {
      rowPtr2++;
      double *dest = rowPtr2;
      double *src = rowPtr1;
      assert(*src != 0.0);
      double alpha = (*dest) / (*src);
      *dest = 0.0;
      for (long j = remainingCols - 1; j > 0; j--) {
        dest += NumRows;
        src += NumRows;
        *dest -= (*src) * alpha;
      }
    }

    rowPtr1 += diagStep;
    remainingCols--;
  }
}

void MatrixRmn::CalcGivensValues(double a, double b, double *cosine, double *sine) {
  double denominator = sqrt(a * a + b * b);
  if (denominator == 0.0) {
    *cosine = 1.0;
    *sine = 0.0;
  } else {
    denominator = 1.0 / denominator;
    *cosine = a * denominator;
    *sine = -b * denominator;
  }
}

void MatrixRmn::PostApplyGivens(double c, double s, long index) {
  assert(0 <= index && index < NumCols);
  double *colA = x + index * NumRows;
  double *colB = colA + NumRows;
  for (long i = NumRows; i > 0; i--) {
    double temp = *colA;
    *colA = (*colA) * c + (*colB) * s;
    *colB = (*colB) * c - temp * s;
    colA++;
    colB++;
  }
}

void MatrixRmn::PostApplyGivens(double c, double s, long idx1, long idx2) {
  assert(idx1 != idx2 && 0 <= idx1 && idx1 < NumCols && 0 <= idx2 &&
         idx2 < NumCols);
  double *colA = x + idx1 * NumRows;
  double *colB = x + idx2 * NumRows;
  for (long i = NumRows; i > 0; i--) {
    double temp = *colA;
    *colA = (*colA) * c + (*colB) * s;
    *colB = (*colB) * c - temp * s;
    colA++;
    colB++;
  }
}

void MatrixRmn::ComputeSVD(MatrixRmn &U, VectorRn &w, MatrixRmn &V) const {
  assert(U.NumRows == NumRows && V.NumCols == NumCols &&
         U.NumRows == U.NumCols && V.NumRows == V.NumCols &&
         w.GetLength() == std::min(NumRows, NumCols));
  VectorRn &superDiag = VectorRn::GetWorkVector(w.GetLength() - 1);

  MatrixRmn *leftMatrix;
  MatrixRmn *rightMatrix;
  if (NumRows >= NumCols) {
    U.LoadAsSubmatrix(*this);
    leftMatrix = &U;
    rightMatrix = &V;
  } else {
    V.LoadAsSubmatrixTranspose(*this);
    leftMatrix = &V;
    rightMatrix = &U;
  }

  CalcBidiagonal(*leftMatrix, *rightMatrix, w, superDiag);
  ConvertBidiagToDiagonal(*leftMatrix, *rightMatrix, w, superDiag);
}

void MatrixRmn::CalcBidiagonal(MatrixRmn &U, MatrixRmn &V, VectorRn &w,
                               VectorRn &superDiag) {
  assert(U.NumRows >= V.NumRows);
  const long rowStep = U.NumCols;
  const long diagStep = U.NumCols + 1;
  double *diagPtr = U.x;
  double *wPtr = w.x;
  double *superDiagPtr = superDiag.x;
  long colLengthLeft = U.NumRows;
  long rowLengthLeft = V.NumCols;

  while (true) {
    SvdHouseholder(diagPtr, colLengthLeft, rowLengthLeft, 1, rowStep, wPtr);
    if (rowLengthLeft == 2) {
      *superDiagPtr = *(diagPtr + rowStep);
      break;
    }

    SvdHouseholder(diagPtr + rowStep, rowLengthLeft - 1, colLengthLeft, rowStep,
                   1, superDiagPtr);
    rowLengthLeft--;
    colLengthLeft--;
    diagPtr += diagStep;
    wPtr++;
    superDiagPtr++;
  }

  int extra = 0;
  diagPtr += diagStep;
  wPtr++;
  if (colLengthLeft > 2) {
    extra = 1;
    colLengthLeft--;
    SvdHouseholder(diagPtr, colLengthLeft, 1, 1, 0, wPtr);
  } else {
    *wPtr = *diagPtr;
  }

  V.ExpandHouseholders(V.NumCols - 2, 1, U.x + U.NumRows, U.NumRows, 1);
  U.ExpandHouseholders(V.NumCols - 1 + extra, 0, U.x, 1, U.NumRows);
}

void MatrixRmn::SvdHouseholder(double *basePt, long colLength, long numCols,
                               long colStride, long rowStride,
                               double *retFirstEntry) {
  double *cPtr = basePt;
  double norm = 0.0;
  long i;
  for (i = colLength; i > 0; i--) {
    norm += Square(*cPtr);
    cPtr += colStride;
  }
  norm = sqrt(norm);

  double imageVal;
  if ((*basePt) < 0.0) {
    imageVal = norm;
    norm = 2.0 * norm * (norm - (*basePt));
  } else {
    imageVal = -norm;
    norm = 2.0 * norm * (norm + (*basePt));
  }
  norm = sqrt(norm);

  if (norm == 0.0) {
    cPtr = basePt;
    for (i = colLength; i > 0; i--) {
      *cPtr = 0.0;
      cPtr += colStride;
    }
    *retFirstEntry = 0.0;
    return;
  }

  *retFirstEntry = imageVal;
  *basePt -= imageVal;
  norm = 1.0 / norm;
  cPtr = basePt;
  for (i = colLength; i > 0; i--) {
    *cPtr *= norm;
    cPtr += colStride;
  }

  double *rPtr = basePt;
  for (long j = numCols - 1; j > 0; j--) {
    rPtr += rowStride;
    double dotP = DotArray(colLength, basePt, colStride, rPtr, colStride);
    AddArrayScale(colLength, basePt, colStride, rPtr, colStride, -2.0 * dotP);
  }
}

void MatrixRmn::ExpandHouseholders(long numXforms, int numZerosSkipped,
                                   const double *basePt, long colStride,
                                   long rowStride) {
  long numToTransform = NumCols - numXforms + 1 - numZerosSkipped;
  assert(numToTransform > 0);

  if (numXforms == 0) {
    SetIdentity();
    return;
  }

  long hDiagStride = rowStride + colStride;
  const double *hBase = basePt + hDiagStride * (numXforms - 1);
  const double *hDiagPtr = hBase + colStride * (numToTransform - 1);
  long i;
  double *diagPtr = x + NumCols * NumRows - 1;
  double *colPtr = diagPtr - (numToTransform - 1);

  for (i = numToTransform; i > 0; i--) {
    CopyArrayScale(numToTransform, hBase, colStride, colPtr, 1,
                   -2.0 * (*hDiagPtr));
    *diagPtr += 1.0;
    diagPtr -= (NumRows + 1);
    colPtr -= NumRows;
    hDiagPtr -= colStride;
  }

  double *colLastPtr = x + NumRows * NumCols - numToTransform - 1;
  for (i = numXforms - 1; i > 0; i--) {
    numToTransform++;
    hBase -= hDiagStride;
    colPtr = colLastPtr;
    for (long j = numToTransform - 1; j > 0; j--) {
      double dotProd2N = -2.0 * DotArray(numToTransform - 1, hBase + colStride,
                                         colStride, colPtr + 1, 1);
      *colPtr = dotProd2N * (*hBase);
      AddArrayScale(numToTransform - 1, hBase + colStride, colStride,
                    colPtr + 1, 1, dotProd2N);
      colPtr -= NumRows;
    }
    CopyArrayScale(numToTransform, hBase, colStride, colPtr, 1,
                   -2.0 * (*hBase));
    *colPtr += 1.0;
    colLastPtr--;
  }

  if (numZerosSkipped != 0) {
    assert(numZerosSkipped == 1);
    double *d = x;
    *d = 1;
    double *d2 = d;
    for (i = NumRows - 1; i > 0; i--) {
      *(++d) = 0;
      *(d2 += NumRows) = 0;
    }
  }
}

void MatrixRmn::ConvertBidiagToDiagonal(MatrixRmn &U, MatrixRmn &V, VectorRn &w,
                                        VectorRn &superDiag) const {
  long lastBidiagIdx = V.NumRows - 1;
  long firstBidiagIdx = 0;

  double aa = w.MaxAbs();
  double bb = superDiag.MaxAbs();
  double eps = 1.0e-15 * std::max(w.MaxAbs(), superDiag.MaxAbs());

  while (true) {
    bool workLeft = UpdateBidiagIndices(&firstBidiagIdx, &lastBidiagIdx, w, superDiag, eps);
    if (!workLeft) {
      break;
    }

    double *wPtr = w.x + firstBidiagIdx;
    double *sdPtr = superDiag.x + firstBidiagIdx;
    double extraOffDiag = 0.0;
    if ((*wPtr) == 0.0) {
      ClearRowWithDiagonalZero(firstBidiagIdx, lastBidiagIdx, U, wPtr, sdPtr, eps);
      if (firstBidiagIdx > 0) {
        if (IsSmall(*sdPtr, eps)) {
          *sdPtr = 0.0;
        }
      }
    }

    // Continue with Givens rotations...
  }
}

