#include <hip/hip_runtime.h>
#include <rocprofiler-sdk-roctx/roctx.h>
#include <chrono>
#include <cstdio>
#include <cstdlib>
#include <iostream>
#include <mutex>
#include <random>
#include <stdexcept>
#include <thread>

#if defined(USE_MPI)
#    include <mpi.h>
#endif

#define HIP_CHECK(CALL)                                                                            \
    {                                                                                              \
        hipError_t err = (CALL);                                                                   \
        if(hipSuccess != err)                                                                      \
        {                                                                                          \
            std::unique_lock<std::mutex> guard{io_mutex};                                          \
            fprintf(stderr,                                                                        \
                    "%s:%d :: HIP error: %s\n",                                                    \
                    __FILE__,                                                                      \
                    __LINE__,                                                                      \
                    hipGetErrorString(err));                                                       \
            throw std::runtime_error("HIP_API_CALL_FAILED");                                       \
        }                                                                                          \
    }

namespace
{
using lock_guard = std::unique_lock<std::mutex>;
std::mutex io_mutex{};
constexpr size_t TILE_SIZE = 32;

void check_last_hip_error();
void validate_results(int const*, int const*, int, int);
__global__ void matrix_transpose_kernel(int const* __restrict__, int* __restrict__, int, int);
void execute_transpose_task(int, int, int, size_t, size_t);

__global__ void matrix_transpose_kernel(int const* __restrict__ input,
                                        int* __restrict__ output,
                                        int rows,
                                        int cols)
{
    __shared__ int tile[TILE_SIZE][TILE_SIZE];

    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;
    int idx = row * rows + col;

    tile[threadIdx.y][threadIdx.x] = input[idx];
    __syncthreads();

    // Transposed index
    row = blockIdx.x * blockDim.x + threadIdx.y;
    col = blockIdx.y * blockDim.y + threadIdx.x;
    idx = row * cols + col;

    output[idx] = tile[threadIdx.x][threadIdx.y];
}

void execute_transpose_task(int rank, int thread_id, int device_id, size_t iterations, size_t sync_interval)
{
    roctxRangePush("execute_transpose_task");

    constexpr int M = 9920;  // 4960 * 2
    constexpr int N = 9920;  // 4960 * 2

    hipStream_t stream{};
    printf("[transpose] Rank %i, thread %i assigned to device %i\n", rank, thread_id, device_id);

    HIP_CHECK(hipSetDevice(device_id));
    HIP_CHECK(hipStreamCreate(&stream));

    {
        lock_guard lk{io_mutex};
        std::cout << "[transpose][" << rank << "][" << thread_id << "] Matrix dims: "
                  << M << " x " << N << std::endl;
    }

    std::mt19937_64 rng{std::random_device{}() * (rank + 1) * (thread_id + 1)};
    std::uniform_int_distribution<int> dist{0, 1000};

    size_t bytes = sizeof(int) * M * N;
    int* host_input  = new int[bytes];
    int* host_output = new int[bytes];

    for(size_t i = 0; i < M * N; ++i)
    {
        host_input[i]  = dist(rng);
        host_output[i] = 0;
    }

    int* dev_input  = nullptr;
    int* dev_output = nullptr;

    HIP_CHECK(hipMalloc(&dev_input, bytes));
    HIP_CHECK(hipMalloc(&dev_output, bytes));
    HIP_CHECK(hipMemsetAsync(dev_input, 0, bytes, stream));
    HIP_CHECK(hipMemsetAsync(dev_output, 0, bytes, stream));
    HIP_CHECK(hipMemcpyAsync(dev_input, host_input, bytes, hipMemcpyHostToDevice, stream));
    HIP_CHECK(hipStreamSynchronize(stream));

    dim3 grid(M / TILE_SIZE, N / TILE_SIZE, 1);
    dim3 block(TILE_SIZE, TILE_SIZE, 1);

    auto start_time = std::chrono::high_resolution_clock::now();

    for(size_t iter = 0; iter < iterations; ++iter)
    {
        matrix_transpose_kernel<<<grid, block, 0, stream>>>(dev_input, dev_output, M, N);
        check_last_hip_error();
        if(iter % sync_interval == sync_interval - 1)
            HIP_CHECK(hipStreamSynchronize(stream));
    }

    auto end_time = std::chrono::high_resolution_clock::now();

    HIP_CHECK(hipStreamSynchronize(stream));
    HIP_CHECK(hipMemcpyAsync(host_output, dev_output, bytes, hipMemcpyDeviceToHost, stream));

    double elapsed_seconds =
        std::chrono::duration_cast<std::chrono::duration<double>>(end_time - start_time).count();
    double gigabytes = static_cast<double>(bytes) * iterations * 2.0 / (1ull << 30);

    {
        lock_guard lk{io_mutex};
        std::cout << "[transpose][" << rank << "][" << thread_id << "] Execution time: "
                  << elapsed_seconds << " seconds\n";
        std::cout << "[transpose][" << rank << "][" << thread_id << "] Throughput: "
                  << (gigabytes / elapsed_seconds) << " GB/s\n";
    }

    HIP_CHECK(hipStreamSynchronize(stream));
    HIP_CHECK(hipStreamDestroy(stream));

    validate_results(host_input, host_output, M, N);

    HIP_CHECK(hipFree(dev_input));
    HIP_CHECK(hipFree(dev_output));
    delete[] host_input;
    delete[] host_output;

    roctxRangePop();
}

void check_last_hip_error()
{
    hipError_t err = hipGetLastError();
    if(hipSuccess != err)
    {
        lock_guard lk{io_mutex};
        std::cerr << "HIP runtime error: " << hipGetErrorString(err) << std::endl;
        throw std::runtime_error("HIP_ERROR");
    }
}

void validate_results(int const* ref, int const* res, int height, int width)
{
    for(int trial = 0; trial < 10; ++trial)
    {
        int r = rand() % height;
        int c = rand() % width;
        if(ref[r * width + c] != res[c * height + r])
        {
            lock_guard lk{io_mutex};
            std::cout << "Mismatch at (" << r << "," << c << "): "
                      << ref[r * width + c] << " vs " << res[c * height + r] << "\n";
        }
    }
}
}  // namespace

void run_transpose(size_t num_threads, size_t num_iterations, size_t sync_frequency)
{
    auto range_id = roctxRangeStart("run_transpose");

    int world_rank = 0;
    int world_size = 1;

    printf("[transpose] Threads: %zu\n", num_threads);
    printf("[transpose] Iterations: %zu\n", num_iterations);
    printf("[transpose] Sync every %zu iterations\n", sync_frequency);

#if defined(USE_MPI)
    MPI_Comm_rank(MPI_COMM_WORLD, &world_rank);
    MPI_Comm_size(MPI_COMM_WORLD, &world_size);
#else
    (void) world_size;
#endif

    int num_devices = 0;
    HIP_CHECK(hipGetDeviceCount(&num_devices));
    printf("[transpose] Devices available: %i\n", num_devices);

    std::vector<int> device_map(world_size * num_threads, 0);
    for(size_t t = 0; t < num_threads; ++t)
    {
        for(int r = 0; r < world_size; ++r)
        {
            size_t idx = r * num_threads + t;
            device_map[idx] = (t + r) % num_devices;
        }
    }

    int base_device_idx = world_rank * num_threads;
    std::vector<std::thread> worker_threads;

    for(size_t t = 1; t < num_threads; ++t)
    {
        worker_threads.emplace_back(
            execute_transpose_task,
            world_rank,
            static_cast<int>(t),
            device_map[base_device_idx + t],
            num_iterations,
            sync_frequency);
    }

    execute_transpose_task(world_rank, 0, device_map[base_device_idx], num_iterations, sync_frequency);

    for(auto& th : worker_threads)
        th.join();

#if defined(USE_MPI)
    MPI_Barrier(MPI_COMM_WORLD);
#endif

    roctxRangeStop(range_id);
}

