void reconstructPermutation() {
    int size;
    cin >> size;

    // Output k value
    cout << "1" << endl;

    vector<int> perm(size + 1, 0);
    vector<int> positionMap(size + 1, 0); // positionMap[value] = index where value is located

    // First handle elements from 2 to size
    for (int currentIndex = 2; currentIndex <= size; ++currentIndex) {
        int helperValue = 1; // Use 1 as helper/dummy

        // Create candidate list excluding current index
        vector<int> candidates;
        for (int i = 1; i <= size; ++i) {
            if (i != currentIndex) {
                candidates.push_back(i);
            }
        }

        // Remove helper from candidates for partitioning
        vector<int> workingCandidates;
        for (int val : candidates) {
            if (val != helperValue) {
                workingCandidates.push_back(val);
            }
        }

        // Get known predecessor if available
        int knownPred = positionMap[currentIndex];

        while (!workingCandidates.empty()) {
            if (workingCandidates.size() == 1) {
                perm[currentIndex] = workingCandidates[0];
                break;
            }

            // Split candidates into two parts
            int midPoint = workingCandidates.size() / 2;
            vector<int> leftPart, rightPart;

            for (int i = 0; i < midPoint; ++i) {
                leftPart.push_back(workingCandidates[i]);
            }
            for (int i = midPoint; i < workingCandidates.size(); ++i) {
                rightPart.push_back(workingCandidates[i]);
            }

            // Build base query: [currentIndex, helper, left, right]
            vector<int> baseQuery(size);
            int idx = 0;
            baseQuery[idx++] = currentIndex;
            baseQuery[idx++] = helperValue;
            for (int val : leftPart) baseQuery[idx++] = val;
            for (int val : rightPart) baseQuery[idx++] = val;

            // Build test query: [helper, left, currentIndex, right]
            vector<int> testQuery(size);
            idx = 0;
            testQuery[idx++] = helperValue;
            for (int val : leftPart) testQuery[idx++] = val;
            testQuery[idx++] = currentIndex;
            for (int val : rightPart) testQuery[idx++] = val;

            int baseResult = executeQuery(baseQuery);
            int testResult = executeQuery(testQuery);
            int difference = testResult - baseResult;

            // Calculate value with default offset
            int calculatedValue = difference + 1;

            // Check if known predecessor is in left part
            bool predInLeft = false;
            if (knownPred != 0 && knownPred != helperValue) {
                for (int val : leftPart) {
                    if (val == knownPred) {
                        predInLeft = true;
                        break;
                    }
                }
            }

            if (knownPred != 0) {
                // Deterministic case with known predecessor
                int predecessorTerm = 0;
                if (knownPred == helperValue) {
                    predecessorTerm = 0;
                } else if (predInLeft) {
                    predecessorTerm = 1;
                }

                int targetInRight = calculatedValue - predecessorTerm;
                if (targetInRight == 1) {
                    workingCandidates = rightPart;
                } else {
                    workingCandidates = leftPart;
                }
            } else {
                // Ambiguous case
                if (calculatedValue == 0) {
                    workingCandidates = leftPart;
                } else if (calculatedValue == 2) {
                    workingCandidates = rightPart;
                } else { // calculatedValue == 1
                    if (difference == 2) {
                        workingCandidates = rightPart;
                    } else if (difference == -1) {
                        workingCandidates = leftPart;
                    } else {
                        // Handle ambiguity
                        if (workingCandidates.size() <= 2) {
                            perm[currentIndex] = -1;
                            break;
                        }
                        workingCandidates = leftPart;
                    }
                }
            }
        }

        if (workingCandidates.size() == 1) {
            perm[currentIndex] = workingCandidates[0];
        } else if (perm[currentIndex] == 0) {
            perm[currentIndex] = (leftPart.size() > 0) ? leftPart[0] : 
                                (rightPart.size() > 0) ? rightPart[0] : 0;
        }

        if (perm[currentIndex] != -1 && perm[currentIndex] != 0) {
            positionMap[perm[currentIndex]] = currentIndex;
        }
    }

    // Determine p[1] as the missing value
    set<int> usedValues;
    for (int i = 2; i <= size; ++i) {
        if (perm[i] != -1 && perm[i] != 0) {
            usedValues.insert(perm[i]);
        }
    }

    for (int i = 1; i <= size; ++i) {
        if (usedValues.find(i) == usedValues.end()) {
            perm[1] = i;
            break;
        }
    }
    positionMap[perm[1]] = 1;

    // Resolve any remaining ambiguous cases
    vector<int> remainingValues;
    for (int i = 1; i <= size; ++i) {
        if (usedValues.find(i) == usedValues.end() && i != perm[1]) {
            remainingValues.push_back(i);
        }
    }

    int remainingIdx = 0;
    for (int i = 2; i <= size; ++i) {
        if (perm[i] == -1 || perm[i] == 0) {
            if (remainingIdx < remainingValues.size()) {
                perm[i] = remainingValues[remainingIdx++];
            }
        }
    }

    // Output final permutation
    cout << "!";
    for (int i = 1; i <= size; ++i) {
        cout << " " << perm[i];
    }
    cout << endl;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int testCases;
    if (cin >> testCases) {
        while (testCases--) {
            reconstructPermutation();
        }
    }

    return 0;
}

