static void parse_hex(const char* hex_str, uint8_t* buffer, size_t size) {
    for (size_t idx = 0; idx < size; ++idx) {
        unsigned int val = 0;
#ifdef __clang__
#pragma clang diagnostic push
#pragma clang diagnostic ignored "-Wdeprecated-declarations"
#endif
        // NOLINTNEXTLINE(cert-err34-c) -- parsing 2-digit hex, overflow impossible
        if (sscanf(hex_str + idx * 2, "%02x", &val) != 1) val = 0;
#ifdef __clang__
#pragma clang diagnostic pop
#endif
        buffer[idx] = static_cast<uint8_t>(val);
    }
}

// -- HMAC-SHA512 Test ---------------------------------------------------------
static void run_hmac_sha512_test() {
    printf("\n--- HMAC-SHA512 ---\n");
    // RFC 4231 Test Case 2
    const char* key_text = "Jefe";
    const char* message_text = "what do ya want for nothing?";

    auto output = hmac_sha512(
        reinterpret_cast<const uint8_t*>(key_text), 4,
        reinterpret_cast<const uint8_t*>(message_text), 28);

    // Expected: 164b7a7bfcf819e2e395fbe73b56e0a387bd64222e831fd610270cd7ea250554
    //           9758bf75c05a994a6d034f65f8f0e6fdcaeab1a34d4a6b4b636e070a38bce737
    uint8_t expected_hash[64];
    parse_hex("164b7a7bfcf819e2e395fbe73b56e0a387bd64222e831fd610270cd7ea250554"
              "9758bf75c05a994a6d034f65f8f0e6fdcaeab1a34d4a6b4b636e070a38bce737",
              expected_hash, 64);

    VERIFY(std::memcmp(output.data(), expected_hash, 64) == 0,
           "HMAC-SHA512 RFC 4231 TC2 verification");
}

// -- BIP-32 Master Key --------------------------------------------------------
static void run_master_key_test() {
    printf("\n--- BIP-32 Master Key ---\n");
    // BIP-32 Test Vector 1: Seed = 000102030405060708090a0b0c0d0e0f
    uint8_t seed_bytes[16];
    parse_hex("000102030405060708090a0b0c0d0e0f", seed_bytes, 16);

    auto [master_node, success] = bip32_master_key(seed_bytes, 16);
    VERIFY(success, "Master key creation successful");
    VERIFY(master_node.is_private, "Master key is private");
    VERIFY(master_node.depth == 0, "Master depth equals zero");

    // Expected chain code from BIP-32 TV1:
    // 873dff81c02f525623fd1fe5167eac3a55a049de3d314bb42ee227ffed37d508
    uint8_t expected_chain_code[32];
    parse_hex("873dff81c02f525623fd1fe5167eac3a55a049de3d314bb42ee227ffed37d508",
              expected_chain_code, 32);
    VERIFY(std::memcmp(master_node.chain_code.data(), expected_chain_code, 32) == 0,
           "Master chain code matches BIP-32 TV1");

    // Expected master private key:
    // e8f32e723decf4051aefac8e2c93c9c5b214313817cdb01a1494b917c8436b35
    uint8_t expected_private_key[32];
    parse_hex("e8f32e723decf4051aefac8e2c93c9c5b214313817cdb01a1494b917c8436b35",
              expected_private_key, 32);
    VERIFY(std::memcmp(master_node.key.data(), expected_private_key, 32) == 0,
           "Master private key matches BIP-32 TV1");
}

// -- BIP-32 Child Derivation --------------------------------------------------
static void run_child_derivation_test() {
    printf("\n--- BIP-32 Child Derivation ---\n");
    uint8_t seed_data[16];
    parse_hex("000102030405060708090a0b0c0d0e0f", seed_data, 16);

    auto [root_key, root_ok] = bip32_master_key(seed_data, 16);
    VERIFY(root_ok, "Root key valid for derivation tests");

    // Derive m/0' (hardened)
    auto [child_hardened, hardened_ok] = root_key.derive_hardened(0);
    VERIFY(hardened_ok, "m/0' derivation succeeded");
    VERIFY(child_hardened.depth == 1, "m/0' depth is 1");
    VERIFY(child_hardened.is_private, "m/0' is private");

    // Verify child chain code matches BIP-32 TV1 m/0':
    // 47fdacbd0f1097043b78c63c20c34ef4ed9a111d980047ad16282c7ae6236141
    uint8_t expected_cc[32];
    parse_hex("47fdacbd0f1097043b78c63c20c34ef4ed9a111d980047ad16282c7ae6236141",
              expected_cc, 32);
    VERIFY(std::memcmp(child_hardened.chain_code.data(), expected_cc, 32) == 0,
           "m/0' chain code matches BIP-32 TV1");

    // Public key derivation: convert to public, then do normal derivation
    auto derived_public = child_hardened.to_public();
    VERIFY(!derived_public.is_private, "to_public() returns public key");

    // Derive m/0'/1 (normal child from m/0')
    auto [child_normal, normal_ok] = child_hardened.derive_normal(1);
    VERIFY(normal_ok, "m/0'/1 derivation succeeded");
    VERIFY(child_normal.depth == 2, "m/0'/1 depth is 2");
}

// -- BIP-32 Path Derivation ---------------------------------------------------
static void run_path_derivation_test() {
    printf("\n--- BIP-32 Path Derivation ---\n");
    uint8_t seed_input[16];
    parse_hex("000102030405060708090a0b0c0d0e0f", seed_input, 16);

    auto [root, root_success] = bip32_master_key(seed_input, 16);
    VERIFY(root_success, "Root key ready for path test");

    // Derive m/0'/1
    auto [intermediate_key, path_ok] = bip32_derive_path(root, "m/0'/1");
    VERIFY(path_ok, "Path m/0'/1 derivation succeeded");
    VERIFY(intermediate_key.depth == 2, "Path m/0'/1 depth is 2");

    // Derive m/0'/1/2' -- deeper path
    auto [deep_key, deep_ok] = bip32_derive_path(root, "m/0'/1/2'");
    VERIFY(deep_ok, "Path m/0'/1/2' derivation succeeded");
    VERIFY(deep_key.depth == 3, "Path m/0'/1/2' depth is 3");

    // Invalid paths
    auto [_, bad_path1_result] = bip32_derive_path(root, "");
    (void)_;
    VERIFY(!bad_path1_result, "Empty path correctly rejected");

    auto [_2, bad_path2_result] = bip32_derive_path(root, "x/0");
    (void)_2;
    VERIFY(!bad_path2_result, "Path not starting with 'm' correctly rejected");
}

// -- Serialization ------------------------------------------------------------
static void run_serialization_test() {
    printf("\n--- BIP-32 Serialization ---\n");
    uint8_t seed_value[16];
    parse_hex("000102030405060708090a0b0c0d0e0f", seed_value, 16);

    auto [root_node, root_valid] = bip32_master_key(seed_value, 16);
    (void)root_valid;

    auto serialized = root_node.serialize();
    VERIFY(serialized.size() == 78, "Serialized key length is 78 bytes");

    // Check version bytes (xprv = 0x0488ADE4)
    VERIFY(serialized[0] == 0x04 && serialized[1] == 0x88 &&
           serialized[2] == 0xAD && serialized[3] == 0xE4,
           "Serialized version matches xprv");

    // Check depth
    VERIFY(serialized[4] == 0, "Serialized depth is 0");

    // Fingerprint
    auto fp = root_node.fingerprint();
    (void)fp;
    VERIFY(fp.size() == 4, "Fingerprint size is 4 bytes");
}

// -- Seed Length Validation ---------------------------------------------------
static void run_seed_validation_test() {
    printf("\n--- BIP-32 Seed Validation ---\n");

    uint8_t short_seed[8] = {1,2,3,4,5,6,7,8};
    auto [_, short_result] = bip32_master_key(short_seed, 8);
    (void)_;
    VERIFY(!short_result, "Seed shorter than 16 bytes rejected");

    uint8_t seed_16[16];
    for (int i = 0; i < 16; ++i) seed_16[i] = static_cast<uint8_t>(i + 1);
    auto [key_16, ok_16] = bip32_master_key(seed_16, 16);
    (void)key_16;
    VERIFY(ok_16, "16-byte seed accepted");

    uint8_t seed_64[64];
    for (int i = 0; i < 64; ++i) seed_64[i] = static_cast<uint8_t>(i + 1);
    auto [key_64, ok_64] = bip32_master_key(seed_64, 64);
    (void)key_64;
    VERIFY(ok_64, "64-byte seed accepted");
}

// -- Main ---------------------------------------------------------------------
int test_bip32_run() {
    printf("=== BIP-32 HD Key Derivation Tests ===\n");
    run_hmac_sha512_test();
    run_master_key_test();
    run_child_derivation_test();
    run_path_derivation_test();
    run_serialization_test();
    run_seed_validation_test();

    printf("\n=== Summary: %d/%d tests passed ===\n", passed_count, test_count);
    return (passed_count == test_count) ? 0 : 1;
}

