// Unit test for AdvanceSearchTableView: selection, copy/cut, and deletion behavior
class AdvanceSearchTableViewTest : public PlainTestSuite {
  Q_OBJECT
 public:
 private slots:
  void testCase_FileSelectionAndOperations() {
    // Prepare test data: two text files and one folder
    QList<FsNodeEntry> sampleEntries{
        {"document1.txt", false, "clark kent daily planet"},
        {"document2.txt", true, "Clark KENT Daily Planet"},
        {"subfolder", true, ""},
    };

    TDir tempDir;
    QCOMPARE(tempDir.createEntries(sampleEntries), static_cast<int>(sampleEntries.size()));
    QString basePath = tempDir.path();
    QVERIFY(QFileInfo(basePath).isDir());

    // Setup models
    AdvanceSearchModel fileModel;
    fileModel.initFilter(QDir::Filter::Dirs | QDir::Filter::Files | QDir::Filter::NoDotAndDotDot);
    fileModel.initIteratorFlag(QDirIterator::IteratorFlag::Subdirectories);
    fileModel.setRootPath(basePath);

    SearchProxyModel proxyModel;
    proxyModel.initSearchMode(SearchTools::SearchModeE::NORMAL);
    proxyModel.initNameFilterDisables(false);  // Hide non-matching items
    proxyModel.initFileNameFiltersCaseSensitive(Qt::CaseSensitivity::CaseInsensitive);
    proxyModel.initFileContentsCaseSensitive(Qt::CaseSensitivity::CaseInsensitive);

    AdvanceSearchTableView view{&fileModel, &proxyModel};
    fileModel.setRootPath(basePath);

    // Test 1: Filter by text — expect 2 matches
    proxyModel.startFilterWhenTextChanged("document", "CLARK");
    QCOMPARE(proxyModel.rowCount(), 2);

    // Test 2: Copy/cut operations on selected rows
    {
      view.selectAll();
      QModelIndexList nameColumns = view.selectionModel()->selectedRows(0);
      QCOMPARE(nameColumns.size(), 2);

      auto clipboardData = MimeDataHelper::GetMimeDataMemberFromSearchModel(fileModel, proxyModel, nameColumns);
      QCOMPARE(clipboardData.texts.size(), 2);
      QCOMPARE(clipboardData.urls.size(), 2);
      QCOMPARE(clipboardData.srcIndexes.size(), 2);

      const QString expectedPaths = clipboardData.texts.join('\n');
      QCOMPARE(expectedPaths.count("document1.txt"), 1);
      QCOMPARE(expectedPaths.count("document2.txt"), 1);
      QCOMPARE(expectedPaths.count("\n"), 1);

      // Perform cut operation
      QVERIFY(MimeDataHelper::FillCutCopySomething<AdvanceSearchModel>(fileModel, clipboardData.srcIndexes, Qt::DropAction::MoveAction));
      QCOMPARE(fileModel.mCutIndexes.isEmpty(), false);
      QCOMPARE(fileModel.mCopyIndexes.isEmpty(), true);

      // Perform copy operation
      QVERIFY(MimeDataHelper::FillCutCopySomething<AdvanceSearchModel>(fileModel, clipboardData.srcIndexes, Qt::DropAction::CopyAction));
      QCOMPARE(fileModel.mCutIndexes.isEmpty(), true);
      QCOMPARE(fileModel.mCopyIndexes.isEmpty(), false);

      // Attempt unsupported action (Link) — should fail
      QVERIFY(!MimeDataHelper::FillCutCopySomething<AdvanceSearchModel>(fileModel, clipboardData.srcIndexes, Qt::DropAction::LinkAction));
      QCOMPARE(fileModel.mCutIndexes.isEmpty(), true);
      QCOMPARE(fileModel.mCopyIndexes.isEmpty(), false);
    }

    // Test 3: Delete key handling
    view.clearSelection();

    QSignalSpy trashSignalSpy(FileOpActs::GetInst().MOVE_TO_TRASHBIN,
                              &QAction::triggered);

    // No selection → no signal
    QKeyEvent deletePress{QEvent::KeyPress, Qt::Key_Delete, Qt::NoModifier, QString(), false, 1};
    view.keyPressEvent(&deletePress);
    QCOMPARE(trashSignalSpy.count(), 0);

    // Select all and press delete → trigger once
    view.selectAll();
    view.keyPressEvent(&deletePress);
    QCOMPARE(trashSignalSpy.count(), 1);
  }
};

