struct NullMutex
{
  void acquire() {}
  void release() {}
};

struct CounterMutex
{
  void acquire() { lockCount_++; }
  void release() { unlockCount_++; }
  [[nodiscard]] int getLockCount() const { return lockCount_; }
  [[nodiscard]] int getUnlockCount() const { return unlockCount_; }

private:
  mutable int lockCount_ {0};
  mutable int unlockCount_ {0};
};

TEST(LockedRangeAdapter, createAndIterateNonConstContainerVector)
{
  std::vector<int> storage {2, 4, 6, 8, 10, 12};
  NullMutex mtx;
  int result {0};
  for (auto x : makeLockedRange<std::lock_guard>(storage, mtx))
  {
    result += x;
  }
  EXPECT_EQ(result, std::accumulate(storage.begin(), storage.end(), 0));
}

