  }
  EXPECT_EQ(mtx.getLockCount(), 1);
  EXPECT_EQ(mtx.getLockCount(), mtx.getUnlockCount());
}

TEST(LockedRangeAdapter, stdMutexNonConstContainerVector)
{
  std::vector<int> sharedVec {7, 14, 21, 28, 35, 42};
  const size_t expectedSum = std::accumulate(sharedVec.begin(), sharedVec.end(), 0) + 2 * sharedVec.size();
  std::mutex mtx;

  std::thread thr1(
    [&sharedVec, &mtx]()
    {
      for (auto& elem : makeLockedRange<std::lock_guard>(sharedVec, mtx))
      {
        elem += 1;
      }
    });

  std::thread thr2(
    [&sharedVec, &mtx]()
    {
      for (auto& elem : makeLockedRange<std::lock_guard>(sharedVec, mtx))
      {
        elem += 1;
      }
    });

  thr1.join();
  thr2.join();

  std::lock_guard guard(mtx);
  EXPECT_EQ(expectedSum, std::accumulate(sharedVec.begin(), sharedVec.end(), 0));
}

TEST(LockedRangeAdapter, stdSharedMutexNonConstContainerVector)
{
  std::vector<int> buffer {11, 22, 33, 44, 55, 66};
  std::shared_mutex rwMutex;
  int readResult {0};
  int initialSum = std::accumulate(buffer.begin(), buffer.end(), 0);

  std::thread writerThread(
    [&buffer, &rwMutex]()
    {
      for (auto& val : makeLockedRange<std::lock_guard>(buffer, rwMutex))
      {
        val += 1;
      }
    });

  std::thread readerThread(
    [&buffer, &rwMutex, &readResult]()
    {
      for (auto val : makeLockedRange<std::lock_guard>(buffer, rwMutex))
      {
        readResult += val;
      }
    });

  writerThread.join();
  readerThread.join();

  std::lock_guard guard(rwMutex);
  int finalSum = std::accumulate(buffer.begin(), buffer.end(), 0);

  EXPECT_TRUE(readResult == initialSum || readResult == finalSum);
}

