TEST(SmartPtrIteratorAdapter, checkAdaptedIteratorInterface)
{
  using ValueType = double;
  using ContainerType = std::unique_ptr<ValueType>;
  using VectorType = std::vector<ContainerType>;

  VectorType ptrVec;
  auto adaptedStart = SmartPtrIteratorAdapter(ptrVec.begin());
  auto adaptedFinish = SmartPtrIteratorAdapter(ptrVec.end());

  static_assert(std::is_same_v<decltype(*adaptedStart), ValueType*>,
                "Dereferencing the adapted iterator should yield a pointer to the underlying type.");
  static_assert(std::is_same_v<decltype(adaptedStart.operator->()), ValueType&>,
                "Member access operator of the adapted iterator should yield a reference to the underlying type.");

  EXPECT_TRUE(adaptedStart == adaptedFinish);
  EXPECT_FALSE(adaptedStart != adaptedFinish);
}

TEST(SmartPtrIteratorAdapter, runtimeUniquePtr)
{
  // Setup
  std::array<int, 7> source {1, 3, 15, 30, 9, 100, 27};
  std::vector<std::unique_ptr<int>> ptrs;
  ptrs.reserve(source.size());
  for (int val : source)
  {
    ptrs.push_back(std::make_unique<int>(val));
  }

  int computedSum {0};
  for (int* rawPtr : makeRange(SmartPtrIteratorAdapter(ptrs.begin()), SmartPtrIteratorAdapter(ptrs.end())))
  {
    computedSum += *rawPtr;
  }

  EXPECT_EQ(computedSum, std::accumulate(source.begin(), source.end(), 0));
}

TEST(SmartPtrIteratorAdapter, runtimeSharedPtr)
{
  // Setup
  std::array<int, 7> initValues {2, 4, 18, 36, 12, 99, 24};
  std::vector<std::shared_ptr<int>> smartPtrs;
  smartPtrs.reserve(initValues.size());
  for (int v : initValues)
  {
    smartPtrs.push_back(std::make_shared<int>(v));
  }

  int total {0};
  for (int* raw : makeRange(SmartPtrIteratorAdapter(smartPtrs.begin()), SmartPtrIteratorAdapter(smartPtrs.end())))
  {
    total += *raw;
  }

  EXPECT_EQ(total, std::accumulate(initValues.begin(), initValues.end(), 0));
}

