namespace debug {
void log_message(const char *format, ...) {
  char buffer[2048];
  va_list arguments;
  va_start(arguments, format);
  vsnprintf(buffer, 2048, format, arguments);
  OutputDebugStringA(buffer);
  va_end(arguments);
}
std::string extract_filename(const std::string &path) {
  unsigned int pos = path.find_last_of("\\/");
  if (pos == std::string::npos) {
    return path;
  } else {
    return path.substr(pos + 1);
  }
}
struct CallFrame {
  DWORD64 addr;
  std::string func_name;
  std::string lib_name;
  unsigned int lineno;
  std::string src_file;
};
inline std::vector<CallFrame> capture_stack() {
#if _WIN64
  DWORD arch = IMAGE_FILE_MACHINE_AMD64;
#else
  DWORD arch = IMAGE_FILE_MACHINE_I386;
#endif
  HANDLE proc = GetCurrentProcess();
  HANDLE thr = GetCurrentThread();
  if (SymInitialize(proc, NULL, TRUE) == FALSE) {
    log_message("Failed to call SymInitialize.");
    return std::vector<CallFrame>();
  }
  SymSetOptions(SYMOPT_LOAD_LINES);
  CONTEXT ctx = {};
  ctx.ContextFlags = CONTEXT_FULL;
  RtlCaptureContext(&ctx);
#if _WIN64
  STACKFRAME frame = {};
  frame.AddrPC.Offset = context.Rip;
  frame.AddrPC.Mode = AddrModeFlat;
  frame.AddrFrame.Offset = context.Rbp;
  frame.AddrFrame.Mode = AddrModeFlat;
  frame.AddrStack.Offset = context.Rsp;
  frame.AddrStack.Mode = AddrModeFlat;
#else
  STACKFRAME frame = {};
  frame.AddrPC.Offset = context.Eip;
  frame.AddrPC.Mode = AddrModeFlat;
  frame.AddrFrame.Offset = context.Ebp;
  frame.AddrFrame.Mode = AddrModeFlat;
  frame.AddrStack.Offset = context.Esp;
  frame.AddrStack.Mode = AddrModeFlat;
#endif
  bool initial = true;
  std::vector<CallFrame> frames;
  while (StackWalk(arch, proc, thr, &frame, &ctx, NULL,
                   SymFunctionTableAccess, SymGetModuleBase, NULL)) {
    CallFrame f = {};
    f.addr = frame.AddrPC.Offset;
#if _WIN64
    DWORD64 base = 0;
#else
    DWORD base = 0;
#endif
    base = SymGetModuleBase(proc, frame.AddrPC.Offset);
    char module_path[MAX_PATH];
    if (base &&
        GetModuleFileNameA((HINSTANCE)base, module_path, MAX_PATH)) {
      f.lib_name = extract_filename(module_path);
    } else {
      f.lib_name = "Unknown Module";
    }
#if _WIN64
    DWORD64 disp = 0;
#else
    DWORD disp = 0;
#endif
    char symbol_buffer[sizeof(IMAGEHLP_SYMBOL) + 511];
    PIMAGEHLP_SYMBOL sym = (PIMAGEHLP_SYMBOL)symbol_buffer;
    sym->SizeOfStruct = sizeof(IMAGEHLP_SYMBOL) + 511;
    sym->MaxNameLength = 510;
    if (SymGetSymFromAddr(proc, frame.AddrPC.Offset, &disp, sym)) {
      f.func_name = sym->Name;
    } else {
      DWORD err = GetLastError();
      log_message("Failed to resolve address 0x%X: %u\n", frame.AddrPC.Offset, err);
      f.func_name = "Unknown Function";
    }
    IMAGEHLP_LINE line_info;
    line_info.SizeOfStruct = sizeof(IMAGEHLP_LINE);
    DWORD line_disp = 0;
    if (SymGetLineFromAddr(proc, frame.AddrPC.Offset, &line_disp, &line_info)) {
      f.src_file = line_info.FileName;
      f.lineno = line_info.LineNumber;
    } else {
      DWORD err = GetLastError();
      log_message("Failed to resolve line for 0x%X: %u\n", frame.AddrPC.Offset,
            err);
      f.lineno = 0;
    }
    if (!initial) {
      frames.push_back(f);
    }
    initial = false;
  }
  SymCleanup(proc);
  return frames;
}
}  // namespace debug
#endif
