namespace quadrants {
void print_traceback() {
#ifdef __APPLE__
  static std::mutex trace_printer_mutex;
  void *stack_frames_ptr[128] = {};
  int count = backtrace((void **)stack_frames_ptr, 128);
  char **symbols = backtrace_symbols((void **)stack_frames_ptr, count);
  std::vector<std::string> traces;
  for (int idx = 0; idx < count; idx++) {
    char func_symbol[2048] = {};
    char module_name[2048] = {};
    int offset_val = 0;
    char addr_str[64] = {};
    sscanf(symbols[idx], "%*s %s %s %s %*s %d", module_name, addr_str, func_symbol,
           &offset_val);
    int demangle_status = 0;
    char *demangled_func =
        abi::__cxa_demangle(func_symbol, NULL, 0, &demangle_status);
    char frame_buffer[8192] = {};
    sprintf(frame_buffer, "* %28s | %7d | %s", module_name, offset_val,
            demangled_func);
    if (demangled_func != nullptr)
      free(demangled_func);
    std::string frameStr(frame_buffer);
    traces.push_back(frameStr);
  }
  free(symbols);
  traces.erase(traces.begin());
  std::reverse(traces.begin(), traces.end());
  std::lock_guard<std::mutex> lock(trace_printer_mutex);
  printf("\n");
  printf(
      "                            * Quadrants Core - Stack Traceback *        "
      " "
      "  "
      "                  \n");
  printf(
      "========================================================================"
      "==================\n");
  printf(
      "|                       Module |  Offset | Function                     "
      "                 |\n");
  printf(
      "|-----------------------------------------------------------------------"
      "-----------------|\n");
  std::reverse(traces.begin(), traces.end());
  for (auto trace_line : traces) {
    const int func_column = 39;
    const int total_width = 86;
    const int func_len = total_width - func_column - 2;
    int k;
    for (k = 0; k < (int)trace_line.size(); k++) {
      std::cout << trace_line[k];
      if (k > func_column + 3 &&
          (k - 3 - func_column) % func_len == 0) {
        std::cout << " |" << std::endl << " ";
        for (int m = 0; m < func_column; m++) {
          std::cout << " ";
        }
        std::cout << " | ";
      }
    }
    for (int m = 0;
         m < func_len + 2 - (k - 3 - func_column) % func_len;
         m++) {
      std::cout << " ";
    }
    std::cout << "|" << std::endl;
  }
  printf(
      "========================================================================"
      "==================\n");
  printf("\n");
#elif defined(_WIN64)
  fmt::print(fg(fmt::color::magenta), "***********************************\n");
  fmt::print(fg(fmt::color::magenta),
             "* Quadrants Compiler Stack Traceback *\n");
  fmt::print(fg(fmt::color::magenta), "***********************************\n");
  std::vector<debug::CallFrame> stack = debug::capture_stack();
  for (unsigned int i = 0; i < stack.size(); i++) {
    fmt::print(fg(fmt::color::magenta),
               fmt::format("0x{:x}: ", stack[i].addr));
    fmt::print(fg(fmt::color::red), stack[i].func_name);
    if (stack[i].src_file != std::string(""))
      fmt::print(fg(fmt::color::magenta),
                 fmt::format("(line {} in {})", stack[i].lineno, stack[i].src_file));
    fmt::print(fg(fmt::color::magenta),
               fmt::format(" in {}\n", stack[i].lib_name));
  }
#else
  constexpr int BT_BUFFER_SIZE = 2048;
  int nptrs;
  void *buffer[BT_BUFFER_SIZE];
  char **strings;
  nptrs = backtrace(buffer, BT_BUFFER_SIZE);
  strings = backtrace_symbols(buffer, nptrs);
  if (strings == nullptr) {
    perror("backtrace_symbols");
    exit(EXIT_FAILURE);
  }
  fmt::print(fg(fmt::color::magenta), "***********************************\n");
  fmt::print(fg(fmt::color::magenta),
             "* Quadrants Compiler Stack Traceback *\n");
  fmt::print(fg(fmt::color::magenta), "***********************************\n");
  for (int j = 1; j < nptrs; j++) {
    std::string s(strings[j]);
    std::size_t slash_pos = s.find("/");
    std::size_t open_paren = s.find("(");
    std::size_t plus_pos = s.rfind("+");
    std::string formatted_line;
    if (slash_pos == 0 && open_paren < plus_pos && s[open_paren + 1] != '+') {
      std::string name = s.substr(open_paren + 1, plus_pos - open_paren - 1);
      char *demangled_name_;
      int status = -1;
      demangled_name_ =
          abi::__cxa_demangle(name.c_str(), nullptr, nullptr, &status);
      if (demangled_name_) {
        name = std::string(demangled_name_);
      }
      std::string prefix = s.substr(0, open_paren);
      formatted_line = fmt::format("{}: {}", prefix, name);
      free(demangled_name_);
    } else {
      formatted_line = s;
    }
    fmt::print(fg(fmt::color::magenta), "{}\n", formatted_line);
  }
  std::free(strings);
#endif
  fmt::print(
      fg(fmt::color::orange),
      "\nInternal error occurred. Check out this page for possible solutions:\n"
      "https://docs.taichi-lang.org/docs/install\n");
}
