/*
  Determine the number of slices based on circle radius and pixel size.
  \param radius of circle
  \param size of pixel
  \return number of divisions to approximate a circle
  */
int calculateSlices(double r, double pxSize = 1.0) {
  if (r <= 0) return 2;
  double angleStep;
  double val = pxSize * 0.5 / r;
  if (fabs(1.0 - val) <= 1)
    angleStep = acos(1.0 - val);
  else
    angleStep = M_PI_4;
  assert(angleStep != 0.0);
  int numSlices = (int)(M_2PI / angleStep);
  return numSlices != 0 ? numSlices : 2;
}
