//-----------------------------------------------------------------------------
double tglGetPixelSize2() {
  double matrix[16];
  glMatrixMode(GL_MODELVIEW);
  glGetDoublev(GL_MODELVIEW_MATRIX, matrix);
  double determinant = fabs(matrix[0] * matrix[5] - matrix[1] * matrix[4]);
  if (determinant < TConsts::epsilon) determinant = TConsts::epsilon;
  return 1.0 / determinant;
}
//-----------------------------------------------------------------------------
TRectD tglGetBounds() {
  TAffine4 viewMatrix;
  TAffine4 projMatrix;
  glGetDoublev(GL_MODELVIEW_MATRIX, viewMatrix.a);
  glGetDoublev(GL_PROJECTION_MATRIX, projMatrix.a);
  return (projMatrix * viewMatrix).get2d().inv() * TRectD(-1.0, -1.0, 1.0, 1.0);
}
