  tglVertex(pt2);
  glEnd();
}
//-----------------------------------------------------------------------------
void tglDrawCircle(const TPointD &center, double radius) {
  if (radius <= 0) return;
  double pxSize = sqrt(tglGetPixelSize2());
  int slices = std::max(3, calculateSlices(radius, pxSize));
  double step = M_2PI / static_cast<double>(slices);
  double cosVal = cos(step), sinVal = sin(step);
  glPushMatrix();
  glTranslated(center.x, center.y, 0.0);
  glBegin(GL_LINE_STRIP);
  double x = radius, y = 0.0;
  glVertex2d(x, y);
  for(int i = slices - 1; i > 0; --i) {
    double tempX = x;
    x = cosVal * tempX - sinVal * y;
    y = sinVal * tempX + cosVal * y;
    glVertex2d(x, y);
  }
  glVertex2d(radius, 0.0);
  glEnd();
  glPopMatrix();
}
//-----------------------------------------------------------------------------
void tglDrawDisk(const TPointD &c, double r) {
  if (r <= 0) return;
  double pxSize = 1;
  int slices    = 60;
  if (slices <= 0) slices = calculateSlices(r, pxSize) >> 1;
  glPushMatrix();
  glTranslated(c.x, c.y, 0.0);
  GLUquadric *quadric = gluNewQuadric();
  gluDisk(quadric, 0, r, slices, 1);
  gluDeleteQuadric(quadric);
  glPopMatrix();
}
