void tglDraw(const TCubic &cubic, int precision, GLenum mode) {
  CHECK_ERRORS_BY_GL;
  assert(mode == GL_POINT || mode == GL_LINE);
  float ctrlPts[4][3];
  ctrlPts[0][0] = cubic.getP0().x;
  ctrlPts[0][1] = cubic.getP0().y;
  ctrlPts[0][2] = 0.0;
  ctrlPts[1][0] = cubic.getP1().x;
  ctrlPts[1][1] = cubic.getP1().y;
  ctrlPts[1][2] = 0.0;
  ctrlPts[2][0] = cubic.getP2().x;
  ctrlPts[2][1] = cubic.getP2().y;
  ctrlPts[2][2] = 0.0;
  ctrlPts[3][0] = cubic.getP3().x;
  ctrlPts[3][1] = cubic.getP3().y;
  ctrlPts[3][2] = 0.0;
  CHECK_ERRORS_BY_GL;
  glMap1f(GL_MAP1_VERTEX_3, 0.0, 1.0, 3, 4, &ctrlPts[0][0]);
  CHECK_ERRORS_BY_GL;
  glEnable(GL_MAP1_VERTEX_3);
  CHECK_ERRORS_BY_GL;
  glMapGrid1f(precision, 0.0, 1.0);
  CHECK_ERRORS_BY_GL;
  glEvalMesh1(mode, 0, precision);
  CHECK_ERRORS_BY_GL;
}
//-----------------------------------------------------------------------------
void tglDraw(const TRectD &rect, const std::vector<TRaster32P> &textures,
             bool blending) {
  double pixelSize2 = tglGetPixelSize2();
  // level is the smallest power of 2 greater than sqrt(pixelSize2)
  unsigned int level = 1;
  while (pixelSize2 * level * level <= 1.0) level <<= 1;
  unsigned int texCount = static_cast<unsigned int>(textures.size());
  if (level > texCount) level = texCount;
  level = texCount - level;
  tglDraw(rect, textures[level], blending);
}
//-------------------------------------------------------------------
void tglDraw(const TRectD &rect, const TRaster32P &tex, bool blending) {
  CHECK_ERRORS_BY_GL;
  glPushAttrib(GL_ALL_ATTRIB_BITS);
  if (blending) {
    glEnable(GL_BLEND);
    glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA);
  }
  unsigned int texWidth  = 1;
  unsigned int texHeight = 1;
  while (texWidth < static_cast<unsigned int>(tex->getLx())) texWidth <<= 1;
  while (texHeight < static_cast<unsigned int>(tex->getLy())) texHeight <<= 1;
  double lwTex = 1.0;
  double lhTex = 1.0;
  TRaster32P texture;
  unsigned int texLx = static_cast<unsigned int>(tex->getLx());
  unsigned int texLy = static_cast<unsigned int>(tex->getLy());
  if (texWidth != texLx || texHeight != texLy) {
    texture = TRaster32P(texWidth, texHeight);
    texture->fill(TPixel32(0, 0, 0, 0));
    texture->copy(tex);
    lwTex = static_cast<double>(texLx) / static_cast<double>(texWidth);
    lhTex = static_cast<double>(texLy) / static_cast<double>(texHeight);
    if (lwTex > 1.0) lwTex = 1.0;
    if (lhTex > 1.0) lhTex = 1.0;
  } else
    texture = tex;
  GLenum fmt =
#if defined(TNZ_MACHINE_CHANNEL_ORDER_BGRM)
      GL_BGRA_EXT;
#elif defined(TNZ_MACHINE_CHANNEL_ORDER_MBGR)
      GL_ABGR_EXT;
#elif defined(TNZ_MACHINE_CHANNEL_ORDER_RGBM)
      GL_RGBA;
#elif defined(TNZ_MACHINE_CHANNEL_ORDER_MRGB)
      GL_BGRA;
#else
//   Error  PLATFORM NOT SUPPORTED
#error "unknown channel order!"
#endif
  // Generate a texture id and bind it.
  GLuint texId;
  glGenTextures(1, &texId);
  glBindTexture(GL_TEXTURE_2D, texId);
  glPixelStorei(GL_UNPACK_ROW_LENGTH, texture->getWrap());
  texture->lock();
  glTexImage2D(GL_TEXTURE_2D, 0, 4, texWidth, texHeight, 0, fmt,
#ifdef TNZ_MACHINE_CHANNEL_ORDER_MRGB
               GL_UNSIGNED_INT_8_8_8_8_REV,
#else
               GL_UNSIGNED_BYTE,
#endif
               texture->getRawData());
  glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_CLAMP);
  glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_CLAMP);
  glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_LINEAR);
  glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_LINEAR);
  glTexEnvf(GL_TEXTURE_ENV, GL_TEXTURE_ENV_MODE, GL_REPLACE);
  glEnable(GL_TEXTURE_2D);
  glHint(GL_PERSPECTIVE_CORRECTION_HINT, GL_NICEST);
  double rectLx = rect.getLx();
  double rectLy = rect.getLy();
  tglColor(TPixel32(0, 0, 0, 0));
  glPushMatrix();
  glTranslated(rect.x0, rect.y0, 0.0);
  glBegin(GL_POLYGON);
  glTexCoord2d(0, 0);
  tglVertex(TPointD(0.0, 0.0));
  glTexCoord2d(lwTex, 0);
  tglVertex(TPointD(rectLx, 0.0));
  glTexCoord2d(lwTex, lhTex);
  tglVertex(TPointD(rectLx, rectLy));
  glTexCoord2d(0, lhTex);
  tglVertex(TPointD(0.0, rectLy));
  glEnd();
  glDisable(GL_TEXTURE_2D);
  glPopMatrix();
  glPopAttrib();
  // Delete texture
  glDeleteTextures(1, &texId);
  texture->unlock();
}
//-----------------------------------------------------------------------------
void tglBuildMipmaps(std::vector<TRaster32P> &rasters,
                     const TFilePath &filepath) {
  assert(rasters.size() > 0);
  TRop::ResampleFilterType resampleFilter = TRop::ClosestPixel;
  TRasterP ras;
  TImageReader::load(filepath, ras);
  int rasLx = ras->getLx();
  int rasLy = ras->getLy();
  int lx = 1;
  while (lx < rasLx) lx <<= 1;
  int ly = 1;
  while (ly < rasLy) ly <<= 1;
  TRaster32P ras2(lx, ly);
  double sx = static_cast<double>(lx) / static_cast<double>(ras->getLx());
  double sy = static_cast<double>(ly) / static_cast<double>(ras->getLy());
#ifndef SCALE_BY_GLU
  TRop::resample(ras2, ras, TScale(sx, sy), resampleFilter);
#else
  ras->lock();
  gluScaleImage(GL_RGBA, ras->getLx(), ras->getLy(), GL_UNSIGNED_BYTE,
                ras->getRawData(), lx, ly, GL_UNSIGNED_BYTE,
                ras2->getRawData());
  ras->unlock();
#endif
  rasters[0] = ras2;
  int ras2Lx = ras2->getLx();
  int ras2Ly = ras2->getLy();
  for (int i = 1; i < static_cast<int>(rasters.size()); ++i) {
    lx >>= 1;
    ly >>= 1;
    if (lx < 1) lx = 1;
    if (ly < 1) ly = 1;
    rasters[i] = TRaster32P(lx, ly);
    sx         = static_cast<double>(lx) / static_cast<double>(ras2Lx);
    sy         = static_cast<double>(ly) / static_cast<double>(ras2Ly);
    rasters[i] = TRaster32P(lx, ly);
#ifndef SCALE_BY_GLU
    TRop::resample(rasters[i], ras2, TScale(sx, sy), resampleFilter);
#else
    ras2->lock();
    gluScaleImage(GL_RGBA, ras->getLx(), ras->getLy(), GL_UNSIGNED_BYTE,
                  ras2->getRawData(), lx, ly, GL_UNSIGNED_BYTE,
                  rasters[i]->getRawData());
    ras2->unlock();
#endif
  }
}
