    for (int case_num = 0; case_num < num_test_cases; ++case_num) {
        int nodes, edges, initial_node, initial_step_count;
        cin >> nodes >> edges >> initial_node >> initial_step_count;

        // Skip edge input
        for (int idx = 0; idx < edges; ++idx) {
            int node1, node2;
            cin >> node1 >> node2;
        }

        // Clear newline buffer
        cin.ignore();

        bool finished = false;
        while (!finished) {
            string input_line;
            getline(cin, input_line);

            if (input_line.empty()) continue;

            if (input_line[0] == 'A' || input_line[0] == 'F') {
                finished = true;
                continue;
            }

            stringstream parser(input_line);
            int neighbor_count;
            parser >> neighbor_count;

            vector<int> neighbors(neighbor_count), visited_status(neighbor_count);
            for (int j = 0; j < neighbor_count; ++j) {
                parser >> neighbors[j] >> visited_status[j];
            }

            // Determine next move: prefer unvisited neighbor first
            int selected_move = 1;
            for (int k = 0; k < neighbor_count; ++k) {
                if (visited_status[k] == 0) {
                    selected_move = k + 1;
                    break;
                }
            }

            cout << selected_move << endl;
            cout.flush();
        }
    }

    return 0;
}

