#include <SDL3/SDL.h>
#include "SerialDevice.hpp"

// Thread entry point for serial device communication
int SDLCALL SerialDeviceThreadRunner(void *param) {
    SerialDevice *dev = static_cast<SerialDevice*>(param);
    dev->run_communication_loop();
    return 0;
}

SerialDevice::SerialDevice(const char *device_name, const char *port_identifier) {
    this->device_name = device_name ? device_name : "SerialDevice";
    this->port_identifier = port_identifier ? port_identifier : "UNK";

    // Launch the processing thread
    this->worker_thread = SDL_CreateThread(SerialDeviceThreadRunner, device_name, (void*)this);
}

SerialDevice::~SerialDevice() {
    // Terminate only if not already handled by subclass
    if (worker_thread) {
        SDL_Log("SerialDevice: %s terminating", device_name);
        SerialMessage shutdown_msg = {MESSAGE_SHUTDOWN, 0};
        host_queue.send(shutdown_msg);
        SDL_WaitThread(worker_thread, nullptr);
        worker_thread = nullptr;
    }
}

