void RecordPlayerTile::setRecord(
    Level* world,
    int    cx,
    int    cy,
    int    cz,
    int    recordId
) {
    if (world->isClientSide) return;

    auto tileEntity = world->getTileEntity(cx, cy, cz);
    auto jukeboxEntity = std::dynamic_pointer_cast<RecordPlayerTile::Entity>(tileEntity);

    if (jukeboxEntity) {
        jukeboxEntity->record = recordId;
        jukeboxEntity->setChanged();
        world->setData(cx, cy, cz, 1);
    }
}

void RecordPlayerTile::dropRecording(Level* world, int cx, int cy, int cz) {
    if (world->isClientSide) return;

    auto tileEntity = world->getTileEntity(cx, cy, cz);
    auto jukeboxEntity = std::dynamic_pointer_cast<RecordPlayerTile::Entity>(tileEntity);

    if (!jukeboxEntity) return;

    int prevRecord = jukeboxEntity->record;
    if (prevRecord == 0) return;

    world->levelEvent(LevelEvent::SOUND_PLAY_RECORDING, cx, cy, cz, 0);
    // 4J-PB- the level event will play the music
    // world->playStreamingMusic(L"", cx, cy, cz);

    jukeboxEntity->record = 0;
    jukeboxEntity->setChanged();
    world->setData(cx, cy, cz, 0);

    float spread = 0.7f;
    double offsetX = world->random->nextFloat() * spread + (1.0f - spread) * 0.5;
    double offsetY = world->random->nextFloat() * spread + (1.0f - spread) * 0.2 + 0.6;
    double offsetZ = world->random->nextFloat() * spread + (1.0f - spread) * 0.5;

    auto itemEntity = std::make_shared<ItemEntity>(
        world,
        cx + offsetX,
        cy + offsetY,
        cz + offsetZ,
        std::make_shared<ItemInstance>(prevRecord, 1, 0)
    );
    itemEntity->throwTime = 10;
    world->addEntity(itemEntity);
}

void RecordPlayerTile::onRemove(
    Level* world,
    int    cx,
    int    cy,
    int    cz,
    int    typeId,
