#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int size;
    if (!(cin >> size)) return 0;

    long long edgeCount = 1LL * size * (size - 1) / 2;
    vector<int> edgeValues(edgeCount);

    for (long long i = 0; i < edgeCount; ++i) {
        cin >> edgeValues[i];
    }

    vector<vector<int>> adjacencyMatrix(size, vector<int>(size, 0));
    long long position = 0;

    for (int row = 0; row < size; ++row) {
        for (int col = row + 1; col < size; ++col) {
            int value = edgeValues[position++];
            adjacencyMatrix[row][col] = value;
            adjacencyMatrix[col][row] = value;
        }
    }

    vector<int> result(size, 0);
    for (int node = 0; node < size; ++node) {
        int combined = ~0;
        for (int neighbor = 0; neighbor < size; ++neighbor) {
            if (neighbor != node) {
                combined &= adjacencyMatrix[node][neighbor];
            }
        }
        result[node] = combined;
    }

    for (int i = 0; i < size; ++i) {
        if (i > 0) cout << ' ';
        cout << result[i];
    }
    cout << '\n';

    return 0;
}

