    const int ROWS = 100, COLS = 100;
    vector<string> grid(ROWS, string(COLS, '#'));

    // Top half black, bottom half white
    for (int row = 0; row < 48; ++row) {
        for (int col = 0; col < COLS; ++col) grid[row][col] = '#';
    }
    for (int row = 48; row < ROWS; ++row) {
        for (int col = 0; col < COLS; ++col) grid[row][col] = '.';
    }

    // Add white cells in black region (avoiding boundary at row 48)
    int remainingWhite = whiteNeeded - 1;
    for (int r = 0; r < 47 && remainingWhite > 0; r += 2) {
        for (int c = 0; c < COLS && remainingWhite > 0; c += 2) {
            grid[r][c] = '.';
            --remainingWhite;
        }
    }

    // Add black cells in white region (avoiding boundary at row 48)
    int remainingBlack = blackNeeded - 1;
    for (int r = 50; r < ROWS && remainingBlack > 0; r += 2) {
        for (int c = 0; c < COLS && remainingBlack > 0; c += 2) {
            grid[r][c] = '#';
