#include <assert.h>
#include <math.h>
#include <mpi.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Generates an array filled with random values between 0 and 1
float*
generate_random_values(int count)
{
    float* values = (float*) malloc(sizeof(float) * count);
    assert(values != NULL);
    int idx;
    for(idx = 0; idx < count; idx++)
    {
        values[idx] = (rand() / (float) RAND_MAX);
    }
    return values;
}

int
main(int argc, char** argv)
{
    if(argc != 2)
    {
        fprintf(stderr, "Usage: std_dev num_elements_per_process\n");
        exit(1);
    }

    int elements_per_rank = atoi(argv[1]);
    MPI_Init(NULL, NULL);

    int my_rank;
    MPI_Comm_rank(MPI_COMM_WORLD, &my_rank);
    int num_ranks;
    MPI_Comm_size(MPI_COMM_WORLD, &num_ranks);

    // Initialize random seed based on rank to ensure different sequences per process
    srand(time(NULL) * my_rank);

    float* random_data = NULL;
    random_data = generate_random_values(elements_per_rank);

    // Compute local sum of elements
    float partial_sum = 0.0f;
    int   j;
    for(j = 0; j < elements_per_rank; j++)
    {
        partial_sum += random_data[j];
    }

    // Aggregate all local sums to compute global mean
    float total_sum;
    MPI_Allreduce(&partial_sum, &total_sum, 1, MPI_FLOAT, MPI_SUM, MPI_COMM_WORLD);
    float average = total_sum / (elements_per_rank * num_ranks);

    // Compute local sum of squared deviations from the mean
    float local_sq_error = 0.0f;
    for(j = 0; j < elements_per_rank; j++)
    {
        float diff = random_data[j] - average;
        local_sq_error += diff * diff;
    }

    // Reduce squared errors to root process
    float global_sq_error;
    MPI_Reduce(&local_sq_error, &global_sq_error, 1, MPI_FLOAT, MPI_SUM, 0, MPI_COMM_WORLD);

    // Calculate and output standard deviation on root process
    if(my_rank == 0)
    {
        float variance = global_sq_error / (elements_per_rank * num_ranks);
        float stddev = sqrt(variance);
        printf("Mean - %f, Standard deviation = %f\n", average, stddev);
    }

    // Cleanup resources
    free(random_data);
    MPI_Barrier(MPI_COMM_WORLD);
    MPI_Finalize();
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

// Represents an interval [leftBound, rightBound] containing 'count' candidates
// 'prevCount' tracks how many candidates exist before leftBound (i.e., in [0, leftBound-1])
struct Interval {
    int leftBound;
    int rightBound;
    int count;
    int prevCount;
};

// Outputs the answer and terminates the program
void reportAnswer(int pos) {
    cout << "! " << pos << endl;
    exit(0);
}

// Performs a query at position 'pos' and returns counts of candidates on left and right
pair<int, int> ask(int pos) {
    cout << "? " << pos << endl;
    int leftCount, rightCount;
    if (!(cin >> leftCount >> rightCount)) exit(0);
    if (leftCount == -1) exit(0); // Should not occur under problem constraints
    return {leftCount, rightCount};
}

int main() {
    // Speed up I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    int minTotal = 2e9; 
    vector<Interval> intervals;

    // First query at the middle position
    int mid = (n - 1) / 2;
    pair<int, int> result = ask(mid);
    int currentSum = result.first + result.second;

    if (currentSum == 0) reportAnswer(mid);
    minTotal = currentSum;

    // Initialize intervals based on first query results
    if (result.first > 0) {
        intervals.push_back({0, mid - 1, result.first, 0});
    }
    if (result.second > 0) {
        intervals.push_back({mid + 1, n - 1, result.second, result.first});
    }

    while (!intervals.empty()) {
        Interval current = intervals.back();
        intervals.pop_back();

        if (current.leftBound > current.rightBound) continue;

        int center = (current.leftBound + current.rightBound) / 2;
        pair<int, int> q = ask(center);
        int sumAtCenter = q.first + q.second;

        if (sumAtCenter == 0) reportAnswer(center);

        if (sumAtCenter < minTotal) {
            // Found a better candidate — update best known total and reset search space
            minTotal = sumAtCenter;
            intervals.clear();

            // New search space: only positions better than 'center'
            if (q.first > 0) {
                intervals.push_back({0, center - 1, q.first, 0});
            }
            if (q.second > 0) {
                intervals.push_back({center + 1, n - 1, q.second, q.first});
            }
        } else {
            // Current position is not better than best known

            // Count candidates strictly between leftBound and center-1
            int leftCandidates = q.first - current.prevCount;

            // Remaining candidates are in [center+1, rightBound]
            int rightCandidates = current.count - leftCandidates;

            // Add sub-intervals for further exploration
            if (leftCandidates > 0) {
                intervals.push_back({current.leftBound, center - 1, leftCandidates, current.prevCount});
            }
            if (rightCandidates > 0) {
                intervals.push_back({center + 1, current.rightBound, rightCandidates, q.first});
            }
        }
    }

    // Safety fallback — though logic ensures a solution is found earlier
    return 0;
}

