namespace glk {

TextureRenderer::TextureRenderer() {
  // Initialize the plain rendering effect
  plain_effect = std::make_shared<PlainRendering>();

  // Define vertex positions for a full-screen quad
  std::vector<Eigen::Vector3f> quad_vertices = {
    Eigen::Vector3f(-1.0f, -1.0f, 0.0f),
    Eigen::Vector3f(1.0f, -1.0f, 0.0f),
    Eigen::Vector3f(-1.0f, 1.0f, 0.0f),
    Eigen::Vector3f(1.0f, 1.0f, 0.0f)};

  // Setup VAO and VBO for vertex data
  glGenVertexArrays(1, &vao);
  glBindVertexArray(vao);

  glGenBuffers(1, &vbo);
  glBindBuffer(GL_ARRAY_BUFFER, vbo);
  glBufferData(GL_ARRAY_BUFFER, sizeof(GL_FLOAT) * 3 * quad_vertices.size(), quad_vertices.data(), GL_STATIC_DRAW);

  // Configure vertex attribute pointer
  glBindVertexArray(vao);
  glBindBuffer(GL_ARRAY_BUFFER, vbo);
  glVertexAttribPointer(0, 3, GL_FLOAT, GL_FALSE, 0, 0);
  glBindBuffer(GL_ARRAY_BUFFER, 0);
}

TextureRenderer::~TextureRenderer() {
  // Clean up OpenGL resources
  glDeleteVertexArrays(1, &vao);
  glDeleteBuffers(1, &vbo);
}

void TextureRenderer::draw(const glk::Texture& color_texture) {
  // Delegate drawing to the plain effect
  plain_effect->draw(*this, color_texture);
}

void TextureRenderer::draw_plain(glk::GLSLShader& shader) const {
  // Get the vertex position attribute location from the shader
  GLint position_loc = shader.attrib("vert_position");

  // Bind VAO and enable vertex attribute
  glBindVertexArray(vao);
  glEnableVertexAttribArray(position_loc);

  // Draw the quad using triangle strip
  glDrawArrays(GL_TRIANGLE_STRIP, 0, 4);

  // Unbind buffer
  glBindBuffer(GL_ARRAY_BUFFER, 0);
}

}  // namespace glk

