void ConsoleUIController::initialize(
    ID3D11Device*           device,
    ID3D11DeviceContext*    context,
    ID3D11RenderTargetView* renderTarget,
    ID3D11DepthStencilView* depthStencil,
    S32                     width,
    S32                     height
) {
#ifdef _USE_IGGY_RENDERER
    m_renderTargetView = renderTarget;
    m_depthStencilView = depthStencil;

    // Common initialization steps
    preInitialize(width, height);

    gdraw_functions = gdraw_D3D11_CreateContext(device, context, width, height);
    if (!gdraw_functions) {
        app.DebugPrintf("GDraw initialization failed!\n");
#ifndef _CONTENT_PACKAGE
        __debugbreak();
#endif
        app.FatalLoadError();
    }

    /* Configure GDraw resource caches: number of handles and memory budget.
       For D3D11, these are hints — actual memory is managed by the driver. */
    gdraw_D3D11_SetResourceLimits(
        GDRAW_D3D11_RESOURCE_vertexbuffer,
        8000,
        24 * 1024 * 1024
    );
    gdraw_D3D11_SetResourceLimits(
        GDRAW_D3D11_RESOURCE_texture,
        7500,
        256 * 1024 * 1024
    );
    gdraw_D3D11_SetResourceLimits(
        GDRAW_D3D11_RESOURCE_rendertarget,
        20,
        64 * 1024 * 1024
    );

    // Connect Iggy to GDraw
    IggySetGDraw(gdraw_functions);

    // Use DirectSound for audio output (no custom processing)
    IggyAudioUseDirectSound();

    // Finalize shared setup
    postInitialize();
#endif
}

void ConsoleUIController::renderFrame() {
#ifdef _USE_IGGY_RENDERER
    // Set up render target and depth buffer for GDraw
    gdraw_D3D11_SetTileOrigin(
        m_renderTargetView,
        m_depthStencilView,
        nullptr,
        0,
        0
    );

    renderScenes();

    // Signal end of frame rendering
    gdraw_D3D11_NoMoreGDrawThisFrame();
#endif
}

