GDrawTexture* ConsoleUIController::acquireSubstitutionTexture(int texId) {
    /* Wrap an existing D3D texture for use by Iggy/GDraw.
       The application retains ownership of the underlying resource. */
    ID3D11ShaderResourceView* srv = RenderManager.TextureGetTexture(texId);
    ID3D11Resource*           res;
    srv->GetResource(&res);
    ID3D11Texture2D* tex2d = static_cast<ID3D11Texture2D*>(res);
    D3D11_TEXTURE2D_DESC desc;
    tex2d->GetDesc(&desc);
    GDrawTexture* gTex = gdraw_D3D11_WrappedTextureCreate(srv);
    return gTex;
}

void ConsoleUIController::releaseSubstitutionTexture(
    void*         userData,
    GDrawTexture* handle
) {
    /* Release only the GDraw wrapper; the D3D texture remains untouched. */
    gdraw_D3D11_WrappedTextureDestroy(handle);
}

void ConsoleUIController::cleanup() {
#ifdef _USE_IGGY_RENDERER
    // Terminate GDraw context — safe only after all players destroyed
    gdraw_D3D11_DestroyContext();
#endif
}

