#include <gz/transport/Node.hh>
#include <gz/msgs/image.pb.h>
#include <gst/gst.h>
#include <gst/app/gstappsrc.h>

// Global elements for GStreamer pipeline
GstElement *video_pipeline = nullptr;
GMainLoop *main_loop = nullptr;
GstElement *source_element = nullptr;
bool pipeline_ready = false;

// Configuration parameters
std::string DESTINATION_IP = "127.0.0.1";
int DESTINATION_PORT = 5600;
int FPS_VALUE = 10;

// Callback function for incoming image messages
void handle_image_message(const gz::msgs::Image &image_msg) {
    if (!source_element) return;

    // Set caps only once on the first frame
    if (!pipeline_ready) {
        GstCaps *caps = gst_caps_new_simple("video/x-raw",
            "format", G_TYPE_STRING, "RGB",
            "width", G_TYPE_INT, image_msg.width(),
            "height", G_TYPE_INT, image_msg.height(),
            "framerate", GST_TYPE_FRACTION, FPS_VALUE, 1,
            NULL);

        gst_app_src_set_caps(GST_APP_SRC(source_element), caps);
        gst_caps_unref(caps);

        std::cout << "Initialized GStreamer with resolution: " 
                  << image_msg.width() << "x" << image_msg.height() << std::endl;
        pipeline_ready = true;
    }

    // Transfer image data to GStreamer buffer
    gsize buffer_size = image_msg.data().size();
    GstBuffer *frame_buffer = gst_buffer_new_allocate(NULL, buffer_size, NULL);

    if (frame_buffer) {
        gst_buffer_fill(frame_buffer, 0, image_msg.data().c_str(), buffer_size);

        GstFlowReturn result = gst_app_src_push_buffer(GST_APP_SRC(source_element), frame_buffer);
        if (result != GST_FLOW_OK) {
            g_warning("Failed to push buffer into appsrc");
        }
    } else {
        g_warning("Could not allocate buffer for GStreamer");
    }
}

// Check if NVIDIA encoder is available
bool has_nvidia_encoder() {
    GstElementFactory *factory = gst_element_factory_find("nvh264enc");
    bool found = (factory != nullptr);
    if (found) {
        gst_object_unref(factory);
    }
    return found;
}

// Signal handler for graceful shutdown
void interrupt_handler(int signal_code) {
    (void)signal_code; // Avoid unused parameter warning
    if (main_loop) {
        g_main_loop_quit(main_loop);
    }
}

int main(int argc, char **argv) {
    if (argc < 3) {
        std::cerr << "Usage: ./gz_gst_bridge <gz_topic> <ip_address> [port] [fps]\n";
        return 1;
    }

    std::string topic_name = argv[1];
    DESTINATION_IP = argv[2];

    if (argc > 3) DESTINATION_PORT = std::stoi(argv[3]);
    if (argc > 4) FPS_VALUE = std::stoi(argv[4]);

    // Initialize GStreamer and Gazebo transport
    gst_init(&argc, &argv);    
    gz::transport::Node node_handle;

    // Construct pipeline string based on available encoder
    std::string pipeline_description;
    std::string network_config = "host=" + DESTINATION_IP + " port=" + std::to_string(DESTINATION_PORT);

    if (has_nvidia_encoder()) {
        std::cout << "Detected NVIDIA GPU encoder (nvh264enc)\n";
        pipeline_description = "appsrc name=source ! queue max-size-buffers=1 leaky=downstream ! "
                               "videoconvert ! "
                               "nvh264enc preset=low-latency-hq zerolatency=true rc-mode=cbr bitrate=2048 qp-min=15 qp-max=35 gop-size=30 ! "
                               "rtph264pay config-interval=1 mtu=1400 ! udpsink sync=false " + network_config;
    } else {
        std::cout << "Falling back to CPU encoder (x264enc)\n";
        pipeline_description = "appsrc name=source ! queue max-size-buffers=1 leaky=downstream ! "
                               "videoconvert ! "
                               "x264enc speed-preset=ultrafast tune=zerolatency bitrate=2048 key-int-max=30 ! "
                               "rtph264pay config-interval=1 mtu=1400 ! udpsink sync=false " + network_config;
    }

    // Launch pipeline
    GError *error = nullptr;
    video_pipeline = gst_parse_launch(pipeline_description.c_str(), &error);

    if (!video_pipeline) {
        std::cerr << "Pipeline creation failed: " << error->message << std::endl;
        return -1;
    }

    // Configure appsrc element
    source_element = gst_bin_get_by_name(GST_BIN(video_pipeline), "source");
    g_object_set(source_element, "format", GST_FORMAT_TIME, NULL);
    g_object_set(source_element, "is-live", TRUE, NULL);
    g_object_set(source_element, "do-timestamp", TRUE, NULL);
    g_object_set(source_element, "leaky-type", 2, NULL); // Drop old buffers
    g_object_set(source_element, "max-bytes", 0, NULL);
    g_object_set(source_element, "max-buffers", 2, NULL);

    // Start pipeline
    gst_element_set_state(video_pipeline, GST_STATE_PLAYING);

    // Subscribe to Gazebo topic
    if (!node_handle.Subscribe(topic_name, handle_image_message)) {
        std::cerr << "Failed to subscribe to topic: " << topic_name << std::endl;
        return -1;
    }

    std::cout << "Streaming " << topic_name << " to " << DESTINATION_IP 
              << ":" << DESTINATION_PORT << " at " << FPS_VALUE << " FPS." << std::endl;

    // Run main loop
    main_loop = g_main_loop_new(NULL, FALSE);
    signal(SIGINT, interrupt_handler);
    g_main_loop_run(main_loop);

    // Cleanup resources
    gst_element_set_state(video_pipeline, GST_STATE_NULL);
    gst_object_unref(source_element);
    gst_object_unref(video_pipeline);
    g_main_loop_unref(main_loop);

    return 0;
}

