TEST_F(TorchCommBackendFactoryTest, GenericBackendOperations) {
  at::Device dev(at::kCPU);
  CommOptions cfg;
  auto backend = TorchCommFactory::get().create_backend(
      kBackendIdentifier, dev, "test_comm", cfg);
  ASSERT_NE(backend, nullptr);

  // Exercise point-to-point communication primitives
  auto tensor = at::ones({2, 2}, at::kFloat);
  auto tx_work = backend->send(tensor, 1, true, SendOptions{});
  ASSERT_NE(tx_work, nullptr);
  EXPECT_TRUE(tx_work->isCompleted());

  auto rx_work = backend->recv(tensor, 0, true, RecvOptions{});
  ASSERT_NE(rx_work, nullptr);
  EXPECT_TRUE(rx_work->isCompleted());

  // Exercise collective communication primitives
  auto bcast_op = backend->broadcast(tensor, 0, true, BroadcastOptions{});
  ASSERT_NE(bcast_op, nullptr);
  EXPECT_TRUE(bcast_op->isCompleted());

  auto reduce_op =
      backend->all_reduce(tensor, ReduceOp::SUM, true, AllReduceOptions{});
  ASSERT_NE(reduce_op, nullptr);
  EXPECT_TRUE(reduce_op->isCompleted());

  // Exercise barrier operation
  auto barrier_op = backend->barrier(true, BarrierOptions{});
  ASSERT_NE(barrier_op, nullptr);
  EXPECT_TRUE(barrier_op->isCompleted());
}

