// Computes the adjustment in the sum of squared differences when transferring 1 unit from position i to j
long long compute_s2_adjustment(long long val_i, long long target_i, long long val_j, long long target_j) {
    long long diff_i = val_i - target_i;
    long long diff_j = val_j - target_j;
    long long new_val_i = val_j - 1;
    long long new_val_j = val_i + 1;
    long long new_diff_i = new_val_i - target_i;
    long long new_diff_j = new_val_j - target_j;
    return new_diff_i * new_diff_i + new_diff_j * new_diff_j - diff_i * diff_i - diff_j * diff_j;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int size;
    std::cin >> size;

    std::vector<long long> first(size), second(size);
    long long total_first = 0, total_second = 0;

    for (int idx = 0; idx < size; ++idx) {
        std::cin >> first[idx];
        total_first += first[idx];
    }

    for (int idx = 0; idx < size; ++idx) {
        std::cin >> second[idx];
        total_second += second[idx];
    }

    if (total_first != total_second) {
        std::cout << "No" << std::endl;
        return 0;
    }

    std::vector<std::pair<int, int>> operations;

    // Limit iterations to avoid infinite loops
    for (int step = 0; step < 40000; ++step) {
        bool uniform = true;
        for (int pos = 0; pos < size; ++pos) {
            if (first[pos] != second[pos]) {
                uniform = false;
                break;
            }
        }
        if (uniform) {
            break;
        }

        long long min_delta = 0;
        int best_pos_i = -1, best_pos_j = -1;

        for (int i = 0; i < size; ++i) {
            for (int j = i + 1; j < size; ++j) {
                long long adjustment = compute_s2_adjustment(first[i], second[i], first[j], second[j]);
                if (adjustment < min_delta) {
                    min_delta = adjustment;
                    best_pos_i = i;
                    best_pos_j = j;
                }
            }
        }

        if (best_pos_i != -1) {
            operations.emplace_back(best_pos_i + 1, best_pos_j + 1);
            long long temp_i = first[best_pos_i];
            long long temp_j = first[best_pos_j];
            first[best_pos_i] = temp_j - 1;
            first[best_pos_j] = temp_i + 1;
        } else {
            // No beneficial move found; terminate
            break;
        }
    }

    bool achievable = true;
    for (int index = 0; index < size; ++index) {
        if (first[index] != second[index]) {
            achievable = false;
            break;
        }
    }

    if (achievable) {
        std::cout << "Yes" << std::endl;
        std::cout << operations.size() << std::endl;
        for (const auto& op : operations) {
            std::cout << op.first << " " << op.second << std::endl;
        }
    } else {
        std::cout << "No" << std::endl;
    }

    return 0;
}

#define UCLN_TYPE_IS_COMMON
#include "ucln_imp.h"
static cleanupFunc *gCommonCleanupRoutines[UCLN_COMMON_COUNT];
static cleanupFunc *gLibraryCleanupRoutines[UCLN_COMMON];
/************************************************
 The cleanup sequence is critical in this function.
 Ensure you have reviewed ucln.h before modifying.
 ************************************************/
U_CAPI void U_EXPORT2
u_cleanup()
{
    UTRACE_ENTRY_OC(UTRACE_U_CLEANUP);
    icu::umtx_lock(nullptr);     /* Enforce a memory barrier to guarantee visibility of   */
    icu::umtx_unlock(nullptr);   /*   all data written by other threads.                 */
    ucln_library_cleanup();
    cmemory_cleanup();       /* Revert any heap functions previously set via u_setMemoryFunctions(). */
    UTRACE_EXIT();           /* Must precede utrace_cleanup(), which disables tracing. */
/*#if U_ENABLE_TRACING*/
    utrace_cleanup();
/*#endif*/
}

U_CAPI void U_EXPORT2 ucln_cleanupOne(ECleanupLibraryType libType) 
{
    if (gLibraryCleanupRoutines[libType])
    {
        gLibraryCleanupRoutines[libType]();
        gLibraryCleanupRoutines[libType] = nullptr;
    }
}

U_CFUNC void
ucln_common_registerCleanup(ECleanupCommonType type,
                            cleanupFunc *func)
{
    // Thread safety considerations: As per ticket 10295, registerCleanup() calls may happen concurrently.
    // Although they should store identical values, thread sanity checkers flag such cases.
    // Guarding the assignment with a mutex resolves these warnings.
    // However, this can cause recursive entry into std::call_once() in umutex.cpp when this code,
    // executed from the call_once handler, attempts to acquire the ICU global mutex—re-entering
    // the mutex initialization path. Therefore, we specially handle UCLN_COMMON_MUTEX by avoiding
    // the ICU global mutex for it.
    //
    // No other part of ICU utilizes std::call_once().
    U_ASSERT(UCLN_COMMON_START < type && type < UCLN_COMMON_COUNT);
    if (type == UCLN_COMMON_MUTEX) {
        gCommonCleanupRoutines[type] = func;
    } else if (UCLN_COMMON_START < type && type < UCLN_COMMON_COUNT)  {
        icu::Mutex m;     // Refer to ticket 10295 for further details.
        gCommonCleanupRoutines[type] = func;
    }
#if !UCLN_NO_AUTO_CLEANUP && (defined(UCLN_AUTO_ATEXIT) || defined(UCLN_AUTO_LOCAL))
    ucln_registerAutomaticCleanup();
#endif
}

// Note: ucln_registerCleanup() executes while holding the ICU global mutex.
//       Exercise caution if extending this function.
//       See ticket 10295 for context.
U_CAPI void U_EXPORT2
ucln_registerCleanup(ECleanupLibraryType type,
                     cleanupFunc *func)
{
    U_ASSERT(UCLN_START < type && type < UCLN_COMMON);
    if (UCLN_START < type && type < UCLN_COMMON)
    {
        gLibraryCleanupRoutines[type] = func;
    }
}

U_CFUNC UBool ucln_library_cleanup() {
    int32_t libType = UCLN_START;
    int32_t commonFunc = UCLN_COMMON_START;
    for (libType++; libType<UCLN_COMMON; libType++) {
        ucln_cleanupOne(static_cast<ECleanupLibraryType>(libType));
    }
    for (commonFunc++; commonFunc<UCLN_COMMON_COUNT; commonFunc++) {
        if (gCommonCleanupRoutines[commonFunc])
        {
            gCommonCleanupRoutines[commonFunc]();
            gCommonCleanupRoutines[commonFunc] = nullptr;
        }
    }
#if !UCLN_NO_AUTO_CLEANUP && (defined(UCLN_AUTO_ATEXIT) || defined(UCLN_AUTO_LOCAL))
    ucln_unRegisterAutomaticCleanup();
#endif
    return true;
}

