// Handle key presses to prevent accidental dialog closure
void Polar3dDlg::keyPressEvent(QKeyEvent *pEvent)
{
    switch (pEvent->key())
    {
        case Qt::Key_Return:
        case Qt::Key_Enter:
        {
            m_DialogButtons->button(QDialogButtonBox::Save)->setFocus();
            break;
        }
        case Qt::Key_Escape:
        {
            reject();
            break;
        }
        default:
            pEvent->ignore();
    }
}

// Restore saved geometry when dialog opens
void Polar3dDlg::showEvent(QShowEvent *pEvent)
{
    QDialog::showEvent(pEvent);
    restoreGeometry(s_WindowGeometry);
}

// Save geometry when dialog closes
void Polar3dDlg::hideEvent(QHideEvent *pEvent)
