// Read wake configuration into Polar3d object
void Polar3dDlg::readWakeData(Polar3d &polar3d) const
{
    polar3d.setVortonWake(      m_RadioVortonWake->isChecked());
    polar3d.setNXWakePanel4(         m_EditNXWakePanels->value());
    polar3d.setTotalWakeLengthFactor(m_EditWakeLength->value());
    polar3d.setWakePanelFactor(      m_EditWakeFactor->value());
    polar3d.setBufferWakeFactor(m_EditVPWBuffer->value());
    polar3d.setVortonL0(        m_EditVortonL0->value());
    polar3d.setVPWMaxLength(    m_EditVPWMaxDist->value());
    polar3d.setVortonCoreSize(  m_EditVortonCore->value());
    polar3d.setVPWIterations(   m_EditVPWIters->value());
}

// Update unit labels based on current reference chord
void Polar3dDlg::setVPWUnits(Polar3d &polar3d)
{
    m_LabelVPWBufferUnit->setText(QString::asprintf("x reference chord = %9.3g", 
        polar3d.bufferWakeFactor() * polar3d.referenceChordLength() * Units::mtoUnit()) + Units::lengthUnitQLabel());
    m_LabelVPWStepUnit->setText(QString::asprintf("x reference chord = %9.3g", 
        polar3d.vortonL0() * polar3d.referenceChordLength() * Units::mtoUnit()) + Units::lengthUnitQLabel());
    m_LabelVtnCoreUnit->setText(QString::asprintf("x reference chord = %9.3g", 
        polar3d.vortonCoreSize() * polar3d.referenceChordLength() * Units::mtoUnit()) + Units::lengthUnitQLabel());
    m_LabelVPWDiscard->setText(QString::asprintf("x reference chord = %9.3g", 
        polar3d.VPWMaxLength() * polar3d.referenceChordLength() * Units::mtoUnit()) + Units::lengthUnitQLabel());

    double totalDist = polar3d.vortonL0() * polar3d.referenceChordLength() * double(polar3d.VPWIterations());
    totalDist += polar3d.bufferWakeLength() * polar3d.referenceChordLength();
    m_LabelVPWMaxLen->setText(QString(QChar(0x21D2)) + QString::asprintf(" max. distance = %9.3g ", 
        totalDist * Units::mtoUnit()) + Units::lengthUnitQLabel());
}

// Handle method selection changes
void Polar3dDlg::onMethod()
{
    readMethodData();
    enableControls();
    setPolar3dName();
}

// Disable vortex-based wake options when not applicable
void Polar3dDlg::disableVortonWake(Polar3d &polar3d)
{
    m_GroupVortonWake->setEnabled(false);
    m_RadioPanelWake->setEnabled(false);
    m_RadioVortonWake->setEnabled(false);
    m_RadioPanelWake->setChecked(true);
    polar3d.setVortonWake(false);
}

