#include <flutter/dart_project.h>
#include <flutter/flutter_view_controller.h>
#include <windows.h>
#include "flutter_window.h"
#include "utils.h"

int APIENTRY wWinMain(_In_ HINSTANCE hInstance, _In_opt_ HINSTANCE hPrevInstance,
                      _In_ wchar_t *cmdLine, _In_ int nCmdShow) {
  // Attach to existing console or create a new one for debugging
  if (!::AttachConsole(ATTACH_PARENT_PROCESS) && ::IsDebuggerPresent()) {
    CreateAndAttachConsole();
  }

  // Initialize COM for plugin and library compatibility
  ::CoInitializeEx(nullptr, COINIT_APARTMENTTHREADED);

  flutter::DartProject dartProject(L"assets");
  std::vector<std::string> args = GetCommandLineArguments();
  dartProject.set_dart_entrypoint_arguments(std::move(args));

  FlutterWindow flutterWindow(dartProject);
  Win32Window::Point windowOrigin(20, 20);
  Win32Window::Size windowSize(1920, 1080);

  if (!flutterWindow.Create(L"custom_flutter_app", windowOrigin, windowSize)) {
    return EXIT_FAILURE;
  }

  flutterWindow.SetQuitOnClose(true);

  ::MSG message;
  while (::GetMessage(&message, nullptr, 0, 0)) {
    ::TranslateMessage(&message);
    ::DispatchMessage(&message);
  }

  ::CoUninitialize();
  return EXIT_SUCCESS;
}

