class ARMELFStreamer;

class ARMTargetAsmStreamer : public ARMTargetStreamer {
  formatted_raw_ostream &Output;
  MCInstPrinter &Disassembler;
  bool IsVerboseMode;

  void emitFnStart() override;
  void emitFnEnd() override;
  void emitCantUnwind() override;
  void emitPersonality(const MCSymbol *Symbol) override;
  void emitPersonalityIndex(unsigned Index) override;
  void emitHandlerData() override;
  void emitSetFP(unsigned FpReg, unsigned SpReg, int64_t Offset = 0) override;
  void emitMovSP(unsigned Reg, int64_t Offset = 0) override;
  void emitPad(int64_t Amount) override;
  void emitRegSave(const SmallVectorImpl<unsigned> &List,
                   bool isVector) override;
  void emitUnwindRaw(int64_t Offset,
                     const SmallVectorImpl<uint8_t> &Opcodes) override;
  void switchVendor(StringRef Vendor) override;
  void emitAttribute(unsigned Attribute, unsigned Value) override;
  void emitTextAttribute(unsigned Attribute, StringRef String) override;
  void emitIntTextAttribute(unsigned Attribute, unsigned IntValue,
                            StringRef StringValue) override;
  void emitArch(ARM::ArchKind Kind) override;
  void emitArchExtension(uint64_t Extension) override;
  void emitObjectArch(ARM::ArchKind Kind) override;
  void emitFPU(ARM::FPUKind Kind) override;
  void emitInst(uint32_t Instruction, char Suffix = '\0') override;
  void finishAttributeSection() override;
  void annotateTLSDescriptorSequence(const MCSymbolRefExpr *SRE) override;
  void emitThumbSet(MCSymbol *Symbol, const MCExpr *Value) override;
  void emitARMWinCFIAllocStack(unsigned Size, bool Wide) override;
  void emitARMWinCFISaveRegMask(unsigned Mask, bool Wide) override;
  void emitARMWinCFISaveSP(unsigned Reg) override;
  void emitARMWinCFISaveFRegs(unsigned First, unsigned Last) override;
  void emitARMWinCFISaveLR(unsigned Offset) override;
  void emitARMWinCFIPrologEnd(bool Fragment) override;
  void emitARMWinCFINop(bool Wide) override;
  void emitARMWinCFIEpilogStart(unsigned Condition) override;
  void emitARMWinCFIEpilogEnd() override;
  void emitARMWinCFICustom(unsigned Opcode) override;

public:
  ARMTargetAsmStreamer(MCStreamer &S, formatted_raw_ostream &OS,
                       MCInstPrinter &IP, bool Verbose);
};

ARMTargetAsmStreamer::ARMTargetAsmStreamer(MCStreamer &S,
                                           formatted_raw_ostream &OS,
                                           MCInstPrinter &IP,
                                           bool Verbose)
    : ARMTargetStreamer(S), Output(OS), Disassembler(IP),
      IsVerboseMode(Verbose) {}

void ARMTargetAsmStreamer::emitFnStart() { Output << "\t.fnstart\n"; }
void ARMTargetAsmStreamer::emitFnEnd() { Output << "\t.fnend\n"; }
void ARMTargetAsmStreamer::emitCantUnwind() { Output << "\t.cantunwind\n"; }

void ARMTargetAsmStreamer::emitPersonality(const MCSymbol *Symbol) {
  Output << "\t.personality " << Symbol->getName() << '\n';
}

void ARMTargetAsmStreamer::emitPersonalityIndex(unsigned Index) {
  Output << "\t.personalityindex " << Index << '\n';
}

void ARMTargetAsmStreamer::emitHandlerData() { Output << "\t.handlerdata\n"; }

void ARMTargetAsmStreamer::emitSetFP(unsigned FpReg, unsigned SpReg,
                                     int64_t Offset) {
  Output << "\t.setfp\t";
  Disassembler.printRegName(Output, FpReg);
  Output << ", ";
  Disassembler.printRegName(Output, SpReg);
  if (Offset)
    Output << ", #" << Offset;
  Output << '\n';
}

void ARMTargetAsmStreamer::emitMovSP(unsigned Reg, int64_t Offset) {
  assert((Reg != ARM::SP && Reg != ARM::PC) &&
         "the operand of .movsp cannot be either sp or pc");
  Output << "\t.movsp\t";
  Disassembler.printRegName(Output, Reg);
  if (Offset)
    Output << ", #" << Offset;
  Output << '\n';
}

void ARMTargetAsmStreamer::emitPad(int64_t Amount) {
  Output << "\t.pad\t#" << Amount << '\n';
}

void ARMTargetAsmStreamer::emitRegSave(const SmallVectorImpl<unsigned> &List,
                                       bool isVector) {
  assert(List.size() && "Register list should not be empty");
  if (isVector)
    Output << "\t.vsave\t{";
  else
    Output << "\t.save\t{";
  Disassembler.printRegName(Output, List[0]);
  for (unsigned idx = 1, end = List.size(); idx != end; ++idx) {
    Output << ", ";
    Disassembler.printRegName(Output, List[idx]);
  }
  Output << "}\n";
}

void ARMTargetAsmStreamer::switchVendor(StringRef Vendor) {}

void ARMTargetAsmStreamer::emitAttribute(unsigned Attribute, unsigned Value) {
  Output << "\t.eabi_attribute\t" << Attribute << ", " << Twine(Value);
  if (IsVerboseMode) {
    StringRef Name = ELFAttrs::attrTypeAsString(
        Attribute, ARMBuildAttrs::getARMAttributeTags());
    if (!Name.empty())
      Output << "\t@ " << Name;
  }
  Output << "\n";
}

void ARMTargetAsmStreamer::emitTextAttribute(unsigned Attribute,
                                             StringRef String) {
  switch (Attribute) {
  case ARMBuildAttrs::CPU_name:
    Output << "\t.cpu\t" << String.lower();
    break;
  default:
    Output << "\t.eabi_attribute\t" << Attribute << ", \"";
    if (Attribute == ARMBuildAttrs::also_compatible_with)
      Output.write_escaped(String);
    else
      Output << String;
    Output << "\"";
    if (IsVerboseMode) {
      StringRef Name = ELFAttrs::attrTypeAsString(
          Attribute, ARMBuildAttrs::getARMAttributeTags());
      if (!Name.empty())
        Output << "\t@ " << Name;
    }
    break;
  }
  Output << "\n";
}

void ARMTargetAsmStreamer::emitIntTextAttribute(unsigned Attribute,
                                                unsigned IntValue,
                                                StringRef StringValue) {
  switch (Attribute) {
  default: llvm_unreachable("unsupported multi-value attribute in asm mode");
  case ARMBuildAttrs::compatibility:
    Output << "\t.eabi_attribute\t" << Attribute << ", " << IntValue;
    if (!StringValue.empty())
      Output << ", \"" << StringValue << "\"";
    if (IsVerboseMode)
      Output << "\t@ "
             << ELFAttrs::attrTypeAsString(Attribute,
                                           ARMBuildAttrs::getARMAttributeTags());
    break;
  }
  Output << "\n";
}

void ARMTargetAsmStreamer::emitArch(ARM::ArchKind Kind) {
  Output << "\t.arch\t" << ARM::getArchName(Kind) << "\n";
}

void ARMTargetAsmStreamer::emitArchExtension(uint64_t Extension) {
  Output << "\t.arch_extension\t" << ARM::getArchExtName(Extension) << "\n";
}

void ARMTargetAsmStreamer::emitObjectArch(ARM::ArchKind Kind) {
  Output << "\t.object_arch\t" << ARM::getArchName(Kind) << '\n';
}

void ARMTargetAsmStreamer::emitFPU(ARM::FPUKind Kind) {
  Output << "\t.fpu\t" << ARM::getFPUName(Kind) << "\n";
}

void ARMTargetAsmStreamer::finishAttributeSection() {}

void ARMTargetAsmStreamer::annotateTLSDescriptorSequence(
    const MCSymbolRefExpr *S) {
  Output << "\t.tlsdescseq\t" << S->getSymbol().getName() << "\n";
}

void ARMTargetAsmStreamer::emitThumbSet(MCSymbol *Symbol, const MCExpr *Value) {
  const MCAsmInfo *MAI = Streamer.getContext().getAsmInfo();
  Output << "\t.thumb_set\t";
  Symbol->print(Output, MAI);
  Output << ", ";
  Value->print(Output, MAI);
  Output << '\n';
}

void ARMTargetAsmStreamer::emitInst(uint32_t Instruction, char Suffix) {
  Output << "\t.inst";
  if (Suffix)
    Output << "." << Suffix;
  Output << "\t0x" << Twine::utohexstr(Instruction) << "\n";
}

void ARMTargetAsmStreamer::emitUnwindRaw(int64_t Offset,
                                      const SmallVectorImpl<uint8_t> &Opcodes) {
  Output << "\t.unwind_raw " << Offset;
  for (uint8_t Opcode : Opcodes)
    Output << ", 0x" << Twine::utohexstr(Opcode);
  Output << '\n';
}

void ARMTargetAsmStreamer::emitARMWinCFIAllocStack(unsigned Size, bool Wide) {
  if (Wide)
    Output << "\t.seh_stackalloc_w\t" << Size << "\n";
  else
    Output << "\t.seh_stackalloc\t" << Size << "\n";
}

static void printRegisters(formatted_raw_ostream &OS, ListSeparator &LS, int Begin,
                           int Finish) {
  if (Begin != Finish)
    OS << LS << "r" << Begin << "-r" << Finish;
  else
    OS << LS << "r" << Begin;
}

void ARMTargetAsmStreamer::emitARMWinCFISaveRegMask(unsigned Mask, bool Wide) {
  if (Wide)
    Output << "\t.seh_save_regs_w\t";
  else
    Output << "\t.seh_save_regs\t";
  ListSeparator LS;
  int First = -1;
  Output << "{";
  for (int I = 0; I <= 12; I++) {
    if (Mask & (1 << I)) {
      if (First < 0)
        First = I;
    } else {
      if (First >= 0) {
        printRegisters(Output, LS, First, I - 1);
        First = -1;
      }
    }
  }
  if (First >= 0)
    printRegisters(Output, LS, First, 12);
  if (Mask & (1 << 14))
    Output << LS << "lr";
  Output << "}\n";
}

void ARMTargetAsmStreamer::emitARMWinCFISaveSP(unsigned Reg) {
  Output << "\t.seh_save_sp\tr" << Reg << "\n";
}

void ARMTargetAsmStreamer::emitARMWinCFISaveFRegs(unsigned First,
                                                  unsigned Last) {
  if (First != Last)
    Output << "\t.seh_save_fregs\t{d" << First << "-d" << Last << "}\n";
  else
    Output << "\t.seh_save_fregs\t{d" << First << "}\n";
}

void ARMTargetAsmStreamer::emitARMWinCFISaveLR(unsigned Offset) {
  Output << "\t.seh_save_lr\t" << Offset << "\n";
}

void ARMTargetAsmStreamer::emitARMWinCFIPrologEnd(bool Fragment) {
  if (Fragment)
    Output << "\t.seh_endprologue_fragment\n";
  else
    Output << "\t.seh_endprologue\n";
}

void ARMTargetAsmStreamer::emitARMWinCFINop(bool Wide) {
  if (Wide)
    Output << "\t.seh_nop_w\n";
  else
    Output << "\t.seh_nop\n";
}

void ARMTargetAsmStreamer::emitARMWinCFIEpilogStart(unsigned Condition) {
  if (Condition == ARMCC::AL)
    Output << "\t.seh_startepilogue\n";
  else
    Output << "\t.seh_startepilogue_cond\t"
           << ARMCondCodeToString(static_cast<ARMCC::CondCodes>(Condition)) << "\n";
}

void ARMTargetAsmStreamer::emitARMWinCFIEpilogEnd() {
  Output << "\t.seh_endepilogue\n";
}

void ARMTargetAsmStreamer::emitARMWinCFICustom(unsigned Opcode) {
  int I;
  for (I = 3; I > 0; I--)
    if (Opcode & (0xffu << (8 * I)))
      break;
  ListSeparator LS;
  Output << "\t.seh_custom\t";
  for (; I >= 0; I--)
    Output << LS << ((Opcode >> (8 * I)) & 0xff);
  Output << "\n";
}

