#include <bits/stdc++.h>
using namespace std;

// Convert character to index: 0-9 for digits, 10-35 for uppercase letters
inline int charToIndex(unsigned char c) {
    if (c >= '0' && c <= '9') return c - '0';
    return 10 + (c - 'A');
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string firstStr, secondStr;
    if (!getline(cin, firstStr)) firstStr.clear();
    if (!getline(cin, secondStr)) secondStr.clear();

    // Determine which string is longer to use as the search string
    bool firstIsLonger = firstStr.size() >= secondStr.size();
    string &searchStr = firstIsLonger ? firstStr : secondStr;   // longer string
    string &patternRef = firstIsLonger ? secondStr : firstStr;  // shorter string
    string pattern = std::move(patternRef);                      // move to own variable

    const size_t patternLen = pattern.size();

    // Count character frequencies in the pattern
    array<size_t, 36> freqCount{};
    for (unsigned char ch : pattern) freqCount[charToIndex(ch)]++;

    // Build position lists for each character in the pattern
    array<vector<int>, 36> charPositions;
    for (int i = 0; i < 36; ++i) charPositions[i].reserve(freqCount[i]);
    for (int idx = 0; idx < (int)patternLen; ++idx) {
        unsigned char ch = (unsigned char)pattern[idx];
        charPositions[charToIndex(ch)].push_back(idx);
    }

    // Release memory used by pattern
    pattern.clear();
    pattern.shrink_to_fit();

    // Prepare pointers for each character's position list
    array<int, 36> posPtr{};
    int lastMatchPos = 0;
    string result;
    result.reserve(patternLen);

    for (unsigned char ch : searchStr) {
        int charIdx = charToIndex(ch);
        auto &positions = charPositions[charIdx];
        int &currentPtr = posPtr[charIdx];

        // Advance pointer past positions that are before current position
        while (currentPtr < (int)positions.size() && positions[currentPtr] < lastMatchPos) {
            ++currentPtr;
        }

        // If we found a valid position, include this character in result
        if (currentPtr < (int)positions.size()) {
            result.push_back((char)ch);
            lastMatchPos = positions[currentPtr] + 1;
            ++currentPtr;

            // Early exit if we've matched all characters
            if (lastMatchPos >= (int)patternLen) break;
        }
    }

    // Output the resulting subsequence
    cout.write(result.data(), (streamsize)result.size());
    cout.put('\n');
    return 0;
}

