// Fixed problem size as per constraints
const int GRID_SIZE = 20;

struct Ghost {
    int identifier;
    int row, col;
};

struct Action {
    char direction;
    int position;
    int depth;
    int expense;
    std::vector<int> ghosts_affected; // IDs of Ghosts removed by this action
};

struct Step {
    char dir;
    int idx;
};

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int placeholder;
    std::cin >> placeholder; // Read N from input, though it's fixed at 20.

    std::vector<std::string> board(GRID_SIZE);
    std::vector<Ghost> ghosts;
    std::map<std::pair<int, int>, int> ghost_lookup;

    for (int i = 0; i < GRID_SIZE; ++i) {
        std::cin >> board[i];
        for (int j = 0; j < GRID_SIZE; ++j) {
            if (board[i][j] == 'x') {
                int id = ghosts.size();
                ghosts.push_back({id, i, j});
                ghost_lookup[{i, j}] = id;
            }
        }
    }

    int total_ghosts = ghosts.size();
    std::vector<Action> actions;

    // Generate all valid 'Up' actions
    for (int col = 0; col < GRID_SIZE; ++col) {
        std::vector<int> path_ghosts;
        for (int row = 0; row < GRID_SIZE; ++row) {
            if (board[row][col] == 'o') break;
            if (board[row][col] == 'x') path_ghosts.push_back(ghost_lookup.at({row, col}));
            if (!path_ghosts.empty()) 
                actions.push_back({'U', col, row, 2 * (row + 1), path_ghosts});
        }
    }

    // Generate all valid 'Down' actions
    for (int col = 0; col < GRID_SIZE; ++col) {
        std::vector<int> path_ghosts;
        for (int row = GRID_SIZE - 1; row >= 0; --row) {
            if (board[row][col] == 'o') break;
            if (board[row][col] == 'x') path_ghosts.push_back(ghost_lookup.at({row, col}));
            if (!path_ghosts.empty()) 
                actions.push_back({'D', col, row, 2 * (GRID_SIZE - row), path_ghosts});
        }
    }

    // Generate all valid 'Left' actions
    for (int row = 0; row < GRID_SIZE; ++row) {
        std::vector<int> path_ghosts;
        for (int col = 0; col < GRID_SIZE; ++col) {
            if (board[row][col] == 'o') break;
            if (board[row][col] == 'x') path_ghosts.push_back(ghost_lookup.at({row, col}));
            if (!path_ghosts.empty()) 
                actions.push_back({'L', row, col, 2 * (col + 1), path_ghosts});
        }
    }

    // Generate all valid 'Right' actions
    for (int row = 0; row < GRID_SIZE; ++row) {
        std::vector<int> path_ghosts;
        for (int col = GRID_SIZE - 1; col >= 0; --col) {
            if (board[row][col] == 'o') break;
            if (board[row][col] == 'x') path_ghosts.push_back(ghost_lookup.at({row, col}));
            if (!path_ghosts.empty()) 
                actions.push_back({'R', row, col, 2 * (GRID_SIZE - col), path_ghosts});
        }
    }

    std::vector<bool> status(total_ghosts, false);
    int cleared_count = 0;
    std::vector<Step> solution_sequence;

    while (cleared_count < total_ghosts) {
        double best_score = -1.0;
        int selected_action_index = -1;

        for (int idx = 0; idx < actions.size(); ++idx) {
            int gain = 0;
            for (int gid : actions[idx].ghosts_affected) {
                if (!status[gid]) {
                    gain++;
                }
            }
            if (gain == 0) continue;

            double evaluation = static_cast<double>(gain) / std::sqrt(actions[idx].expense);
            if (evaluation > best_score || 
               (evaluation == best_score && selected_action_index != -1 && 
                actions[idx].expense < actions[selected_action_index].expense)) {
                best_score = evaluation;
                selected_action_index = idx;
            }
        }

        if (selected_action_index == -1) break; // Safety check

        Action& chosen = actions[selected_action_index];

        if (chosen.direction == 'U') {
            for (int step = 0; step < chosen.depth + 1; ++step) 
                solution_sequence.push_back({'U', chosen.position});
            for (int step = 0; step < chosen.depth + 1; ++step) 
                solution_sequence.push_back({'D', chosen.position});
        } else if (chosen.direction == 'D') {
            for (int step = 0; step < GRID_SIZE - chosen.depth; ++step) 
                solution_sequence.push_back({'D', chosen.position});
            for (int step = 0; step < GRID_SIZE - chosen.depth; ++step) 
                solution_sequence.push_back({'U', chosen.position});
        } else if (chosen.direction == 'L') {
            for (int step = 0; step < chosen.depth + 1; ++step) 
                solution_sequence.push_back({'L', chosen.position});
            for (int step = 0; step < chosen.depth + 1; ++step) 
                solution_sequence.push_back({'R', chosen.position});
        } else if (chosen.direction == 'R') {
            for (int step = 0; step < GRID_SIZE - chosen.depth; ++step) 
                solution_sequence.push_back({'R', chosen.position});
            for (int step = 0; step < GRID_SIZE - chosen.depth; ++step) 
                solution_sequence.push_back({'L', chosen.position});
        }

        for (int gid : chosen.ghosts_affected) {
            if (!status[gid]) {
                status[gid] = true;
                cleared_count++;
            }
        }
    }

    for (const auto& step : solution_sequence) {
        std::cout << step.dir << " " << step.idx << "\n";
    }

    return 0;
}

