// Load a compressed NBT tag from an input stream
CompoundTag *NbtIo::readCompressed(InputStream *inputStream)
{
	MemSect(26);
	// 4J - this was using a try/finally block
	DataInputStream dataIn = DataInputStream(inputStream); // 4J - was new GZIPInputStream as well
	CompoundTag *result = NbtIo::read((DataInput *)&dataIn);
	dataIn.close();
	MemSect(0);
	return result;
}

// Save a compressed NBT tag to an output stream
void NbtIo::writeCompressed(CompoundTag *tag, OutputStream *outputStream)
{
	// 4J - this was using a try/finally block
	// 4J Stu - Buffer output in 1024 byte chunks so that we can allocate properly in the save file
	BufferedOutputStream bufferedOut = BufferedOutputStream(outputStream, 1024);
	DataOutputStream dataOut = DataOutputStream(&bufferedOut); // 4J - was new GZIPOutputStream as well
	NbtIo::write(tag, &dataOut);
	dataOut.close();
}

// Decompress tags from a byte array. Doesn't free the original buffer data.
CompoundTag *NbtIo::decompress(byteArray sourceBuffer)
{
	ByteArrayInputStream bais = ByteArrayInputStream(sourceBuffer);
	// 4J - this was using a try/finally block
	DataInputStream inputStream = DataInputStream(&bais); // 4J - was new GZIPInputStream as well
	CompoundTag *result = NbtIo::read((DataInput *)&inputStream);
	bais.reset();		// This prevents the buffer referenced by the input stream from being freed when it goes out of scope
	inputStream.close();
	return result;
}

// Compress an NBT tag into a byte array
byteArray NbtIo::compress(CompoundTag *tag)
{
	// 4J - this was using a try/finally block
    ByteArrayOutputStream baos = ByteArrayOutputStream();
    DataOutputStream dos = DataOutputStream(&baos); // 4J - was new GZIPOutputStream as well
	NbtIo::write(tag, &dos);
	byteArray output(baos.buf.length);
	System::arraycopy(baos.buf, 0, &output, 0, baos.buf.length);
	dos.close();
	return output;
}

// Parse a single named tag from the input stream
CompoundTag *NbtIo::read(DataInput *dis)
{
	Tag *tag = Tag::readNamedTag(dis);
	if (tag->getId() == Tag::TAG_Compound) 
		return (CompoundTag *)tag;
	if (tag != NULL) 
		delete tag;
	// Root tag must be a named compound tag
	return NULL;
}

// Write a compound tag to the output stream
void NbtIo::write(CompoundTag *tag, DataOutput *dos)
{
	Tag::writeNamedTag(tag, dos);
}

