Y_UNIT_TEST_SUITE(TestSourceRoot) {
    Y_UNIT_TEST(TestStrip) {
        // Reconstruct() converts "\" -> "/" on Windows
        const TString filePath = TPathSplit(__SOURCE_FILE_IMPL__.As<TStringBuf>()).Reconstruct();
        UNIT_ASSERT_EQUAL(filePath, "util" LOCSLASH_S "system" LOCSLASH_S "src_root_ut.cpp");
    }

    Y_UNIT_TEST(TestPrivateChopPrefixRoutine) {
        static constexpr const char testStr[] = ":\0:\0: It's unlikely that this string has an ARCADIA_ROOT as its prefix :\0:\0:";
        static constexpr const auto testStaticBuf = STATIC_BUF(testStr);
        UNIT_ASSERT_VALUES_EQUAL(TStringBuf(testStr, sizeof(testStr) - 1), ::NPrivate::StripRoot(testStaticBuf).As<TStringBuf>());
        UNIT_ASSERT_VALUES_EQUAL(0, ::NPrivate::RootPrefixLength(testStaticBuf));

        static_assert(::NPrivate::IsProperPrefix(STATIC_BUF("alpha"), STATIC_BUF("alphabet")), R"(IsProperPrefix("alpha", "alphabet") failed)");
        static_assert(!::NPrivate::IsProperPrefix(STATIC_BUF("alphabet"), STATIC_BUF("alpha")), R"(IsProperPrefix("alphabet", "alpha") failed)");
        static_assert(!::NPrivate::IsProperPrefix(STATIC_BUF("identifier"), STATIC_BUF("identifier")), R"(IsProperPrefix("identifier", "identifier") failed)");
        static_assert(::NPrivate::IsProperPrefix(STATIC_BUF("identifier"), STATIC_BUF("identifier/")), R"(IsProperPrefix("identifier", "identifier/") failed)");
        static_assert(::NPrivate::IsProperPrefix(STATIC_BUF(""), STATIC_BUF("teststring")), R"(IsProperPrefix("", "teststring") failed)");
        static_assert(!::NPrivate::IsProperPrefix(STATIC_BUF(""), STATIC_BUF("")), R"(IsProperPrefix("", "") failed)");
        static_assert(::NPrivate::IsProperPrefix(STATIC_BUF("folder"), STATIC_BUF("folder/file.txt")), R"(IsProperPrefix("folder", "folder/file.txt") failed)");
    }
} // Y_UNIT_TEST_SUITE(TestSourceRoot)

