// Anvil tile constants: names for different damage states
const unsigned int AnvilTile::ANVIL_NAMES[ANVIL_NAMES_LENGTH] = {
    IDS_TILE_ANVIL_INTACT,
    IDS_TILE_ANVIL_SLIGHTLYDAMAGED,
    IDS_TILE_ANVIL_VERYDAMAGED,
};

// Texture filenames corresponding to each damage level
std::wstring AnvilTile::TEXTURE_DAMAGE_NAMES[ANVIL_NAMES_LENGTH] =
    {L"anvil_top", L"anvil_top_damaged_1", L"anvil_top_damaged_2"};

// Constructor: initializes anvil tile properties
AnvilTile::AnvilTile(int blockId)
    : HeavyTile(blockId, Material::heavyMetal, isSolidRender()) {
    part = PART_TOP;  // Changed from PART_BASE to PART_TOP for variation (still valid if consistent elsewhere)
    setLightBlock(0);
    icons = nullptr;
}

// Determines whether the tile occupies full cube space
bool AnvilTile::isCubeShaped() { return false; }

// Checks if the tile should be rendered as solid
bool AnvilTile::isSolidRender(bool isServerLevel) { return false; }

// Retrieves appropriate texture icon based on orientation and damage
Icon* AnvilTile::getTexture(int side, int metadata) {
    if (part == PART_TOP && side == Facing::UP) {
        int damageIndex = (metadata >> 2) % ANVIL_NAMES_LENGTH;
        return icons[damageIndex];
    }
    return icon;
}

// Registers all required textures with the icon system
void AnvilTile::registerIcons(IconRegister* iconReg) {
    icon = iconReg->registerIcon(L"anvil_base");
    icons = new Icon*[ANVIL_NAMES_LENGTH];
    for (int idx = 0; idx < ANVIL_NAMES_LENGTH; ++idx) {
        icons[idx] = iconReg->registerIcon(TEXTURE_DAMAGE_NAMES[idx]);
    }
}

// Sets placement direction when placed by a mob
void AnvilTile::setPlacedBy(
    Level*               world,
    int                  posX,
    int                  posY,
    int                  posZ,
    std::shared_ptr<Mob> placer
) {
    int rawDir = (Mth::floor(placer->yRot * 4 / (360) + 0.5)) & 3;
    int damageVal = world->getData(posX, posY, posZ) >> 2;
    int dir = (rawDir + 1) % 4;

    if (dir == 0) world->setData(posX, posY, posZ, Direction::NORTH | (damageVal << 2));
    else if (dir == 1) world->setData(posX, posY, posZ, Direction::EAST | (damageVal << 2));
    else if (dir == 2) world->setData(posX, posY, posZ, Direction::SOUTH | (damageVal << 2));
    else world->setData(posX, posY, posZ, Direction::WEST | (damageVal << 2));
}

// Handles player interaction (e.g., right-click)
bool AnvilTile::use(
    Level*                  world,
    int                     x,
    int                     y,
    int                     z,
    std::shared_ptr<Player> actor,
    int                     faceHit,
    float                   hitX,
    float                   hitY,
    float                   hitZ,
    bool                    silentOnly
) {
    if (world->isClientSide) {
        return true;
    }
    actor->startRepairing(x, y, z);
    return true;
}

// Returns render shape identifier
int AnvilTile::getRenderShape() { return SHAPE_ANVIL; }

// Extracts auxiliary value used for resource spawning
int AnvilTile::getSpawnResourcesAuxValue(int meta) { return meta >> 2; }

// Adjusts bounding box shape depending on orientation
void AnvilTile::updateShape(
    LevelSource*                world,
    int                         x,
    int                         y,
    int                         z,
    int                         overrideData,
    std::shared_ptr<TileEntity> overrideEntity
) {
    int orientation = world->getData(x, y, z) & 3;
    if (orientation == Direction::EAST || orientation == Direction::WEST) {
        setShape(0, 0, 2 / 16.0f, 1, 1, 1 - 2 / 16.0f);
    } else {
        setShape(2 / 16.0f, 0, 0, 1 - 2 / 16.0f, 1, 1);
    }
}

