#define DEBUG_TYPE "livestacks"

void CgLiveStacks::releaseMemory() {
  // Free memory used by value numberings; actual VNInfo instances do not require destruction.
  ValueNumberAllocator.Reset();
  SlotToIntervalMap.clear();
  SlotToRegClassMap.clear();
}

bool CgLiveStacks::runOnCgFunction(CgFunction &func) {
  TRI = func.getSubtarget().getRegisterInfo();
  // TODO: Currently no analysis is performed; register allocators are expected to supply data.
  func.LSS = this;
  return false;
}

CgLiveInterval &
CgLiveStacks::getOrCreateInterval(int slot, const TargetRegisterClass *regClass) {
  assert(slot >= 0 && "Spill slot index must be non-negative");

  SS2IntervalMap::iterator iter = SlotToIntervalMap.find(slot);
  if (iter == SlotToIntervalMap.end()) {
    iter = SlotToIntervalMap
               .emplace(
                   std::piecewise_construct,
                   std::forward_as_tuple(slot),
                   std::forward_as_tuple(Register::index2StackSlot(slot), 0.0f))
               .first;
    SlotToRegClassMap.insert(std::make_pair(slot, regClass));
  } else {
    // Refine to the most specific common register class.
    const TargetRegisterClass *prevRC = SlotToRegClassMap[slot];
    SlotToRegClassMap[slot] = TRI->getCommonSubClass(prevRC, regClass);
  }
  return iter->second;
}

/// dump - Provide textual output of the live intervals.
void CgLiveStacks::print(raw_ostream &out) const {
  out << "********** LIVE INTERVALS **********\n";
  for (const_iterator it = begin(), endIt = end(); it != endIt; ++it) {
    it->second.print(out);
    int slotIdx = it->first;
    const TargetRegisterClass *rc = getIntervalRegClass(slotIdx);
    if (rc)
      out << " [" << TRI->getRegClassName(rc) << "]\n";
    else
      out << " [Unknown]\n";
  }
}

#include <algorithm>
#include "IRrecv.h"
#include "IRsend.h"
#include "IRutils.h"

// Constants for LEGO Power Functions protocol
const uint16_t kLegoPfBitMark = 158;
const uint16_t kLegoPfHdrSpace = 1026;
const uint16_t kLegoPfZeroSpace = 263;
const uint16_t kLegoPfOneSpace = 553;
const uint32_t kLegoPfMinCommandLength = 16000;  // 16ms

#if SEND_LEGOPF
/// Send a LEGO Power Functions command.
/// Status: Beta / Should work.
/// @param[in] payload The data to be transmitted.
/// @param[in] bitCount Number of bits in the message.
/// @param[in] repetitions How many times to repeat the transmission.
/// @note When repetitions > 0, at least 5 messages are sent per specification.
void IRsend::sendLegoPf(const uint64_t payload, const uint16_t bitCount,
                        const uint16_t repetitions) {
  uint8_t channelId = ((payload >> (bitCount - 4)) & 0b11) + 1;
  if (repetitions) {
    // In repeat mode: add initial pause before transmission
    if (channelId < 4) space((4 - channelId) * kLegoPfMinCommandLength);

    // Ensure minimum of 5 repeats as per spec
    for (uint16_t rep = 0; rep < std::max(repetitions, static_cast<uint16_t>(5)); rep++) {
      // Vary start-to-start timing for repeated messages
      sendGeneric(kLegoPfBitMark, kLegoPfHdrSpace,
                  kLegoPfBitMark, kLegoPfOneSpace,
                  kLegoPfBitMark, kLegoPfZeroSpace,
                  kLegoPfBitMark, kLegoPfHdrSpace,
                  ((rep < 2) ? 5 : (6 + 2 * channelId)) * kLegoPfMinCommandLength,
                  payload, bitCount, 38000, true, 0, kDutyDefault);
    }
  } else {
    // Single transmission without repetition
    sendGeneric(kLegoPfBitMark, kLegoPfHdrSpace,
                kLegoPfBitMark, kLegoPfOneSpace,
                kLegoPfBitMark, kLegoPfZeroSpace,
                kLegoPfBitMark, kLegoPfHdrSpace,
                kLegoPfMinCommandLength * 5,
                payload, bitCount, 38000, true, 0, kDutyDefault);
  }
}
