#if DECODE_LEGOPF
/// Decode a received LEGO Power Functions signal.
/// Status: Stable / Appears to work correctly.
/// @param[in,out] decodeData Pointer to storage for decoded results.
/// @param[in] startIndex Starting position in raw buffer for decoding.
/// @param[in] expectedBits Expected number of data bits.
/// @param[in] enforceStrict Whether to enforce strict protocol compliance.
/// @return True if decoding succeeded, false otherwise.
bool IRrecv::decodeLegoPf(decode_results* decodeData, uint16_t startIndex,
                          const uint16_t expectedBits, const bool enforceStrict) {
  // Basic validation if strict mode is enabled
  if (enforceStrict && expectedBits != kLegoPfBits) return false;

  uint64_t decodedValue = 0;

  // Attempt to match header, data, and footer
  if (!matchGeneric(decodeData->rawbuf + startIndex, &decodedValue,
                    decodeData->rawlen - startIndex, expectedBits,
                    kLegoPfBitMark, kLegoPfHdrSpace,
                    kLegoPfBitMark, kLegoPfOneSpace,
                    kLegoPfBitMark, kLegoPfZeroSpace,
                    kLegoPfBitMark, kLegoPfMinCommandLength,
                    true)) return false;

  // LRC verification when strict mode is active
  if (enforceStrict) {
    uint16_t lrcCheckValue = decodedValue;
    uint8_t lrc = 0xF;
    for (uint8_t i = 0; i < 4; i++) {
      lrc ^= (lrcCheckValue & 0xF);
      lrcCheckValue >>= 4;
    }
    if (lrc) return false;
  }

  // Store decoded information
  decodeData->decode_type = LEGOPF;
  decodeData->bits = expectedBits;
  decodeData->value = decodedValue;
  decodeData->address = ((decodedValue >> (expectedBits - 4)) & 0b11) + 1;  // Channel ID
  decodeData->command = (decodedValue >> 4) & 0xFF;  // Payload between channel ID and LRC

  return true;
}
#endif  // DECODE_LEGOPF

