// Inline assembly for retrieving and configuring the x87 FPU control register 
// when using GCC on x86 architecture.
#if defined(_Py_MEMORY_SANITIZER)
__attribute__((no_sanitize_memory))
#endif
unsigned short _Py_fetch_fpu_control_word(void) {
    unsigned short control;
    __asm__ __volatile__ ("fnstcw %0" : "=m" (control));
    return control;
}
void _Py_update_fpu_control_word(unsigned short control) {
    __asm__ __volatile__ ("fldcw %0" : : "m" (control));
}
