#include <iostream>

// Helper function to handle division warnings
static int __Pyx_cdivision_warning(const char *, int); /* proto */
/////////////// CDivisionWarning ///////////////
static int __Pyx_cdivision_warning(const char *source_file, int line_number) {
#if CYTHON_COMPILING_IN_PYPY
    // suppress compiler warnings
    source_file++; line_number++;
    return PyErr_Warn(PyExc_RuntimeWarning,
                     "division with oppositely signed operands, C and Python semantics differ");
#else
    return PyErr_WarnExplicit(PyExc_RuntimeWarning,
                              "division with oppositely signed operands, C and Python semantics differ",
                              source_file,
                              line_number,
                              __Pyx_MODULE_NAME,
                              NULL);
#endif
}
/////////////// DivInt.proto ///////////////
static CYTHON_INLINE %(type)s __Pyx_div_%(type_name)s(%(type)s, %(type)s, int is_const); /* proto */
/////////////// DivInt ///////////////
static CYTHON_INLINE %(type)s __Pyx_div_%(type_name)s(%(type)s dividend, %(type)s divisor, int is_const) {
    %(type)s quotient = dividend / divisor;
    %(type)s remainder = dividend - quotient*divisor;
    %(type)s adjust_for_python = (is_const ?
        // leverage compile-time constant folding for 'divisor'.
        ((remainder != 0) & ((remainder < 0) ^ (divisor < 0))) :
        ((remainder ^ divisor) < 0)
    );
    return quotient - adjust_for_python;
}
/////////////// ModInt.proto ///////////////
static CYTHON_INLINE %(type)s __Pyx_mod_%(type_name)s(%(type)s, %(type)s, int is_const); /* proto */
/////////////// ModInt ///////////////
static CYTHON_INLINE %(type)s __Pyx_mod_%(type_name)s(%(type)s dividend, %(type)s divisor, int is_const) {
    %(type)s remainder = dividend % divisor;
    %(type)s adjust_for_python = (is_const ?
        // leverage compile-time constant folding for 'divisor'.
        ((remainder != 0) & ((remainder < 0) ^ (divisor < 0))) :
        ((remainder ^ divisor) < 0)
    );
    return remainder + adjust_for_python * divisor;
}
/////////////// ModFloat.proto ///////////////
static CYTHON_INLINE %(type)s __Pyx_mod_%(type_name)s(%(type)s, %(type)s, int is_const); /* proto */
/////////////// ModFloat ///////////////
static CYTHON_INLINE %(type)s __Pyx_mod_%(type_name)s(%(type)s dividend, %(type)s divisor, int is_const) {
    CYTHON_UNUSED_VAR(is_const);
    %(type)s remainder = fmod%(math_h_modifier)s(dividend, divisor);
    remainder += ((remainder != 0) & ((remainder < 0) ^ (divisor < 0))) * divisor;
    return remainder;
}
/////////////// IntPow.proto ///////////////
static CYTHON_INLINE %(type)s %(func_name)s(%(type)s, %(type)s); /* proto */
/////////////// IntPow ///////////////
static CYTHON_INLINE %(type)s %(func_name)s(%(type)s base, %(type)s exponent) {
    %(type)s temp = base;
    switch (exponent) {
        case 3:
            temp *= base;
        CYTHON_FALLTHROUGH;
        case 2:
            temp *= base;
        CYTHON_FALLTHROUGH;
        case 1:
            return temp;
        case 0:
            return 1;
    }
    #if %(signed)s
    if (unlikely(exponent<0)) return 0;
    #endif
    temp = 1;
    while (likely(exponent)) {
        temp *= (base * (exponent&1)) | ((~exponent)&1);    /* 1 or base */
        base *= base;
        exponent >>= 1;
    }
    return temp;
}

