InMemGraph::InMemGraph(const common::offset_t nodeCount, storage::MemoryManager* mm)
    : csrOffsets(mm), csrEdges(mm) {
    reset(nodeCount);
}
void InMemGraph::reset(const common::offset_t nodeCount) {
    this->numNodes = nodeCount;
    csrOffsets.reserve(nodeCount);
    csrOffsets.clear();
    csrEdges.clear();
    numEdges = 0;
}
void InMemGraph::prepareNextNode() {
    csrOffsets.push_back(csrEdges.size());
}
void InMemGraph::addNeighbor(const common::offset_t destination, const weight_t edgeWeight) {
    csrEdges.emplace_back(destination, edgeWeight);
    numEdges++;
}
