#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <assert.h>
#include "dds/dds.h"

// Compile-time constants for built-in topics used in monitoring discovery
static const dds_entity_t monitored_entities[] = {
  DDS_BUILTIN_TOPIC_DCPSPUBLICATION,
  DDS_BUILTIN_TOPIC_DCPSSUBSCRIPTION
};

struct key_buffer {
    char buffer[36]; // Format: 8 hex + ':' + 8 hex + ':' + 8 hex + ':' + 8 hex + '\0'
};

static char *format_key(struct key_buffer *kb, const dds_builtintopic_topic_key_t *key)
{
    (void) snprintf(kb->buffer, sizeof(kb->buffer),
                    "%02x%02x%02x%02x:%02x%02x%02x%02x:%02x%02x%02x%02x:%02x%02x%02x%02x",
                    key->d[0], key->d[1], key->d[2], key->d[3],
                    key->d[4], key->d[5], key->d[6], key->d[7],
                    key->d[8], key->d[9], key->d[10], key->d[11],
                    key->d[12], key->d[13], key->d[14], key->d[15]);
    return kb->buffer;
}

static const char *state_to_string(dds_instance_state_t state)
{
    switch (state)
    {
        case DDS_ALIVE_INSTANCE_STATE: return "alive";
        case DDS_NOT_ALIVE_NO_WRITERS_INSTANCE_STATE: return "no_writers";
        case DDS_NOT_ALIVE_DISPOSED_INSTANCE_STATE: return "disposed";
    }
    assert(0);
    return "";
}

static bool handle_topic_event(dds_entity_t cond)
{
#define MAX_SAMPLES 10
    void *sample_list[MAX_SAMPLES] = { NULL };
    dds_sample_info_t info_list[MAX_SAMPLES];
    sample_list[0] = NULL;

    int32_t count = dds_take(cond, sample_list, info_list, MAX_SAMPLES, MAX_SAMPLES);
    bool found_app_topic = false;

    for (int32_t idx = 0; idx < count; idx++)
    {
        dds_builtintopic_topic_t const *topic_data = (dds_builtintopic_topic_t const *)sample_list[idx];
        struct key_buffer kb;
        printf("%s: %s", state_to_string(info_list[idx].instance_state), format_key(&kb, &topic_data->key));

        if (info_list[idx].valid_data)
        {
            printf(" %s %s", topic_data->topic_name, topic_data->type_name);
            if (strncmp(topic_data->topic_name, "DCPS", 4) != 0)
            {
                found_app_topic = true;
            }
        }
        printf("\n");
    }

    (void) dds_return_loan(cond, sample_list, count);
#undef MAX_SAMPLES
    return found_app_topic;
}

static bool check_endpoints(dds_entity_t ep_conditions[])
{
    bool endpoints_found = false;
    for (size_t i = 0; i < sizeof(monitored_entities) / sizeof(monitored_entities[0]) && !endpoints_found; i++)
    {
        void *single_sample = NULL;
        dds_sample_info_t single_info;
        int32_t result_count = dds_take(ep_conditions[i], &single_sample, &single_info, 1, 1);

        if (result_count > 0 && single_info.valid_data)
        {
            dds_builtintopic_endpoint_t const *endpoint = (dds_builtintopic_endpoint_t const *)single_sample;
            if (strncmp(endpoint->topic_name, "DCPS", 4) != 0)
                endpoints_found = true;
        }

        (void) dds_return_loan(ep_conditions[i], &single_sample, result_count);
    }
    return endpoints_found;
}

int main(int argc, char **argv)
{
    (void)argc;
    (void)argv;

    const dds_entity_t domain_participant = dds_create_participant(DDS_DOMAIN_DEFAULT, NULL, NULL);
    if (domain_participant < 0)
    {
        fprintf(stderr, "dds_create_participant failed: %s\n", dds_strretcode(domain_participant));
        return 1;
    }

    const dds_entity_t waitset_handle = dds_create_waitset(domain_participant);

    const dds_entity_t topic_reader = dds_create_reader(domain_participant, DDS_BUILTIN_TOPIC_DCPSTOPIC, NULL, NULL);
    if (topic_reader < 0)
    {
        if (topic_reader == DDS_RETCODE_UNSUPPORTED)
            fprintf(stderr, "Topic discovery support not compiled in — rebuild with ENABLE_TOPIC_DISCOVERY=ON\n");
        else
            fprintf(stderr, "dds_create_reader(DCPSTopic) failed: %s\n", dds_strretcode(topic_reader));
        dds_delete(domain_participant);
        return 1;
    }

    const dds_entity_t topic_condition = dds_create_readcondition(topic_reader, DDS_ANY_STATE);
    (void) dds_waitset_attach(waitset_handle, topic_condition, 0);

    dds_entity_t endpoint_readers[sizeof(monitored_entities) / sizeof(monitored_entities[0])];
    dds_entity_t endpoint_conditions[sizeof(monitored_entities) / sizeof(monitored_entities[0])];

    for (size_t i = 0; i < sizeof(monitored_entities) / sizeof(monitored_entities[0]); i++)
    {
        endpoint_readers[i] = dds_create_reader(domain_participant, monitored_entities[i], NULL, NULL);
        endpoint_conditions[i] = dds_create_readcondition(endpoint_readers[i], DDS_ANY_STATE);
        (void) dds_waitset_attach(waitset_handle, endpoint_conditions[i], 0);
    }

    bool app_topics_discovered = false;
    bool remote_endpoints_exist = false;

    const dds_time_t deadline = dds_time() + DDS_SECS(10);

    while (dds_waitset_wait_until(waitset_handle, NULL, 0, deadline) > 0)
    {
        if (handle_topic_event(topic_condition))
            app_topics_discovered = true;

        if (!remote_endpoints_exist && check_endpoints(endpoint_conditions))
        {
            remote_endpoints_exist = true;
            for (size_t i = 0; i < sizeof(endpoint_readers) / sizeof(endpoint_readers[0]); i++)
                (void) dds_delete(endpoint_readers[i]);
        }
    }

    if (!app_topics_discovered && remote_endpoints_exist)
    {
        fprintf(stderr, "No application topics discovered, but remote readers/writers detected. Is topic discovery enabled?\n");
    }

    dds_delete(domain_participant);
    return 0;
}

