#include <TranslatorRoster.h>
#include <TranslatorFormats.h>
#include <DataIO.h>
#include <File.h>
#include <Entry.h>
#include <Message.h>
#include <iostream>

int main() {
    // Open the Markdown document for reading
    BFile markdownDoc("./document.md", B_READ_ONLY);
    if (markdownDoc.InitCheck() != B_OK) {
        std::cerr << "Unable to open document.md\n";
        return 1;
    }

    // Create the output text file (overwrite if it already exists)
    BFile outputFile("./output.txt", B_CREATE_FILE | B_ERASE_FILE | B_WRITE_ONLY);
    if (outputFile.InitCheck() != B_OK) {
        std::cerr << "Unable to create output.txt\n";
        return 1;
    }

    // Retrieve the default translator roster
    BTranslatorRoster* manager = BTranslatorRoster::Default();
    if (!manager) {
        std::cerr << "Could not access translator roster\n";
        return 1;
    }

    // Set up identification parameters
    BMessage params;
    params.AddString("name", "./document.md");
    params.AddString("BEOS:TYPE", "text/markdown");

    translator_info info;
    status_t err = manager->Identify(&markdownDoc, &params, &info);
    if (err == B_OK) {
        const char* translatorName = nullptr;
        const char* description = nullptr;
        int32 releaseVersion = 0;

        // Fetch translator metadata
        if (manager->GetTranslatorInfo(info.translator, &translatorName, &description, &releaseVersion) == B_OK) {
            std::cout << "Using translator: " << translatorName << " (v" << releaseVersion << ")\n";
            std::cout << "Description: " << description << "\n";
        } else {
            std::cerr << "Error: Failed to retrieve translator details\n";
        }
    } else {
        std::cerr << "Identification failed: " << err << "\n";
        return 1;
    }

    // Rewind input file to start position for translation
    markdownDoc.Seek(0, SEEK_SET);

    // Perform the actual translation from Markdown to plain text
    status_t translationStatus = manager->Translate(&markdownDoc, nullptr, &params, &outputFile, B_TRANSLATOR_TEXT);
    if (translationStatus != B_OK) {
        std::cerr << "Translation process failed: " << translationStatus << "\n";
        return 1;
    } else {
        std::cout << "Successfully generated output file: output.txt\n";
    }

    return 0;
}

