static void
memoryErrorCallback (
    enum mcheck_status status
    ) {
    printf ("ABORT: Memory integrity check failed: %s\n",
                (status == MCHECK_DISABLED) ? "Integrity checks are inactive" :
                (status == MCHECK_OK)       ? "Memory block intact" :
                (status == MCHECK_FREE)     ? "Double-free detected" :
                (status == MCHECK_HEAD)     ? "Buffer overflow before allocated block" :
                (status == MCHECK_TAIL)     ? "Buffer underflow after allocated block" :
                "<unknown error>");
