//------------------------------------------------------------------------------
// Constructor: Initialize object, parse config, load & invoke start component
DeltaresHydro::DeltaresHydro (
    int     argc,
    char *  argv [],
    char *  envp []
    ) {
    this->programPath = strdup (argv[0]);

#if defined(HAVE_CONFIG_H)
    this->programName = strdup (basename (argv[0]));
#else
    char * ext = new char[5];
    this->programName = new char[MAXSTRING];
    _splitpath (argv[0], NULL, NULL, this->programName, ext);
    StringCbCatA (this->programName, MAXSTRING, ext);
    delete [] ext;
#endif

    this->slaveOption = NULL;
    this->shutdownRequested = false;

    Log::Mask debugLevel = Log::ALWAYS; // Controls verbosity: silent → trace
    FILE *      logStream = stdout;     // Output destination for logs

    // Reconstruct full command line for spawning slaves
    int totalLen = 0;
    for (int idx = 1 ; idx < argc ; idx++)
        totalLen += strlen (argv[idx]) + 1;

    this->fullCommandLine = new char [totalLen+1];
    memset (this->fullCommandLine, '\0', totalLen+1);
    char * cursor = this->fullCommandLine;
    for (int idx = 1 ; idx < argc ; idx++) {
        int len = strlen (argv[idx]);
        memcpy (cursor, argv[idx], len);
        cursor += len;
        *cursor++ = ' ';
    }

    // Parse command-line options
    int optChar;
    while ((optChar = getopt (argc, argv, (char *) "d:l:S:v?")) != -1) {
        switch (optChar) {
            case 'd': {
                if (sscanf (optarg, "%i", &debugLevel) != 1)
                    throw new Exception("Invalid debug level (-d option)");
                break;
            }
            case 'l': {
                logStream = fopen (optarg, "w");
                if (logStream == NULL)
                    throw new Exception("Unable to open log file \"%s\"", optarg);
                break;
            }
            case 'S': {
                this->slaveOption = optarg;
                break;
            }
            case 'v': {
                displayInfo (this->programName);
                this->shutdownRequested = true;
                return;
            }
            case '?': {
                showHelp (this->programName);
                this->shutdownRequested = true;
                return;
            }
            default: {
                throw new Exception("Unrecognized argument. Run \"%s -?\" for usage", this->programName);
            }
        }
    }

    if (argc - optind != 1)
        throw new Exception("Incorrect invocation. Run \"%s -?\" for syntax", this->programName);

    this->timer = new Clock ();
    this->logger = new Log (logStream, this->timer, debugLevel);

    // Load XML configuration
    this->configFile = argv[optind];
    FILE * fp;
    if (strcmp (this->configFile, "-") == 0)
        fp = stdin;
    else {
        fp = fopen (this->configFile, "r");
        if (fp == NULL)
            throw new Exception("Cannot access configuration file \"%s\"", this->configFile);
    }

    this->xmlConfig = new XmlTree (fp);
    fclose (fp);

    // Validate root element
    XmlTree * root = this->xmlConfig->Lookup ("/deltaresHydro");
    if (root == NULL)
        throw new Exception("Configuration file \"%s\" lacks deltaresHydro root node", this->configFile);

    // Determine initial component name
    const char * mainComponentName = "flow2D3D";
    this->startNode = root->Lookup (mainComponentName);
    if (this->startNode == NULL)
        throw new Exception("Missing configuration for primary component \"%s\"", mainComponentName);

#if defined (MONOLITHIC_FLOW2D3D)
    this->isInitialized = FLOW2D3D_MonolithicInit (this);
#else
    // Load dynamic library for main component
    XmlTree * libElement = this->startNode->Lookup ("library");
    if (libElement == NULL)
        throw new Exception("Primary component \"%s\" missing library specification", mainComponentName);

    const char * libName = libElement->charData;

#if defined (HAVE_CONFIG_H)
#if defined (OSX)
    throw new Exception("ABORT: %s not yet supported on Apple macOS", this->programName);
#else
    char buffer [strlen (libName) + 3+3+1];
    if (strchr (libName, '/') == NULL && strchr (libName, '.') == NULL) {
        sprintf (buffer, "lib%s%s", libName, D3D_PLUGIN_EXT);
        libName = buffer;
    }
    this->logger->Write (Log::DETAIL, "Loading plugin \"%s\"", libName);
    void * handle = dlopen (libName, RTLD_LAZY);
    if (handle == NULL)
        throw new Exception("Failed to load plugin \"%s\": %s", libName, dlerror ());
    StartComponentEntry entry = (StartComponentEntry) dlsym (handle, this->entryPointName);
    if (entry == NULL)
        throw new Exception("Symbol \"%s\" not found in \"%s\"", this->entryPointName, libName);
    this->logger->Write (Log::DETAIL, "Invoking plugin entry point");
    this->isInitialized = entry (this);
#endif
#elif defined (WIN32)
    char * dllPath = new char[strlen (libName) + 4+1];
    if (strchr (libName, '/') == NULL && strchr (libName, '\\') == NULL && strchr (libName, '.') == NULL) {
        sprintf (dllPath, "%s.dll", libName);
        libName = dllPath;
    }
    this->logger->Write (Log::DETAIL, "Loading DLL \"%s\"", libName);
    HINSTANCE dllHandle = LoadLibrary (LPCSTR(libName));
    if (dllHandle == NULL)
        throw new Exception("Failed to load DLL \"%s\". Error code: %d", libName, GetLastError());
    typedef int (__cdecl *FuncPtr)(LPWSTR);
    FuncPtr entryPoint = (FuncPtr) GetProcAddress (dllHandle, this->entryPointName);
    if (entryPoint == NULL)
        throw new Exception("Function \"%s\" missing in \"%s\". Error code: %d", this->entryPointName, libName, GetLastError());
    this->logger->Write (Log::DETAIL, "Calling DLL entry function");
    this->isInitialized = ((entryPoint) ((LPWSTR) this));
    delete [] dllPath;
#endif
#endif // MONOLITHIC_FLOW2D3D
}

//------------------------------------------------------------------------------
// Destructor
DeltaresHydro::~DeltaresHydro (
    void
    ) {
    if (this->shutdownRequested)
        return;

    delete this->mainComponent;

#if defined(HAVE_CONFIG_H)
    free (this->programName);
#else
    delete [] this->programName;
#endif

    this->logger->Write (Log::ALWAYS, "d_hydro shutting down normally");

    delete this->timer;
    delete this->xmlConfig;
    free (this->programPath);
    delete this->logger;
    delete [] this->fullCommandLine;
}

//------------------------------------------------------------------------------
void
DeltaresHydro::Execute (
    void
    ) {
    try {
        if (this->shutdownRequested) return;
        this->mainComponent->Run();
    }
    catch (Exception *ex) {
        printf ("#### d_hydro ABORT: %s\n", ex->message);
    }
}

