//-*****************************************************************************
namespace AbcA = Alembic::AbcCoreAbstract;
using namespace Alembic::Util;

//-*****************************************************************************
void CreateTestFile(const std::string &archivePath)
{
    AbcA::MetaData md;
    md.setUnique("name", "arkive");
    Alembic::AbcCoreOgawa::WriteArchive aw;
    AbcA::ArchiveWriterPtr archive = aw(archivePath, md);

    AbcA::ObjectWriterPtr rootObj = archive->getTop();
    AbcA::ObjectWriterPtr deepestChild;

    {
        md.set("name", "objLevel1");
        AbcA::ObjectWriterPtr level1 = rootObj->createChild(
            AbcA::ObjectHeader("level1", md));

        md.set("name", "objLevel2");
        AbcA::ObjectWriterPtr level2 = level1->createChild(
            AbcA::ObjectHeader("level2", md));

        md.set("name", "objLevel3");
        deepestChild = level2->createChild(
            AbcA::ObjectHeader("level3", md));
    }

    AbcA::CompoundPropertyWriterPtr props = deepestChild->getProperties();
    const AbcA::TimeSamplingType cyclicType(3, 3.0);

    const size_t sampleCount = 40;
    const Dimensions dims(sampleCount);
