//-*****************************************************************************
void LoadTestFile(const std::string &archivePath)
{
    Alembic::AbcCoreOgawa::ReadArchive ar;
    AbcA::ArchiveReaderPtr arkive = ar(archivePath);

    AbcA::CompoundPropertyReaderPtr targetProps;
    AbcA::ObjectReaderPtr currentObj = arkive->getTop();

    while (true)
    {
        if (currentObj->getNumChildren() == 0)
        {
            std::cout << "Reached terminal node: " 
                      << currentObj->getFullName() << std::endl;
            targetProps = currentObj->getProperties();
            std::cout << "Properties count: " 
                      << targetProps->getNumProperties() << std::endl;
            break;
        }
        currentObj = currentObj->getChild(0);
    }

    AbcA::ScalarPropertyReaderPtr scalarReader;
    AbcA::ArrayPropertyReaderPtr arrayReader1;
    AbcA::ArrayPropertyReaderPtr arrayReader2;

    for (size_t i = 0; i < targetProps->getNumProperties(); ++i)
    {
        AbcA::BasePropertyReaderPtr prop = targetProps->getProperty(i);
        std::cout << "Property found: " << prop->getName() << std::endl;

        if (prop->isScalar())
        {
            scalarReader = prop->asScalarPtr();
            std::cout << "Scalar has " << scalarReader->getNumSamples() 
                      << " samples" << std::endl;
        }
        else if (prop->isArray())
        {
            if (prop->getName() == "intArrayProp1")
                arrayReader1 = prop->asArrayPtr();
            else if (prop->getName() == "intArrayProp2")
                arrayReader2 = prop->asArrayPtr();

            std::cout << "Array property has " 
                      << prop->asArrayPtr()->getNumSamples() 
                      << " samples" << std::endl;
        }
    }

    // Read scalar samples
    for (size_t s = 0; s < scalarReader->getNumSamples(); ++s)
    {
        float64_t val = 0.0;
        scalarReader->getSample(s, (void*)&val);
        TESTING_ASSERT(val == 99.99);
        std::cout << scalarReader->getName() << " sample " << s 
                  << ": " << val << std::endl << std::endl;
    }

    // Read first array property
    std::cout << "FIRST ARRAY PROPERTY (Cyclic)" << std::endl;
    AbcA::ArraySamplePtr samplePtr;
    for (size_t s = 0; s < arrayReader1->getNumSamples(); ++s)
    {
        arrayReader1->getSample(s, samplePtr);
        const AbcA::TimeSampling ts = arrayReader1->getTimeSampling();
        size_t pointCount = samplePtr->getDimensions().numPoints();

        TESTING_ASSERT((AbcA::chrono_t)s == ts.getSampleTime(s));

        std::cout << "Sample " << s << ", time " << ts.getSampleTime(s) 
                  << ", points: " << pointCount << std::endl;

        int32_t* data = (int32_t*)samplePtr->getData();
        for (size_t j = 0; j < pointCount; ++j)
        {
            TESTING_ASSERT(data[j] == static_cast<int32_t>(s + j));
            std::cout << j << ": " << data[j] << ", ";
        }
        std::cout << std::endl << std::endl;
        samplePtr->reset();
    }

    // Read second array property
    std::cout << "SECOND ARRAY PROPERTY (Acyclic)" << std::endl;
    for (size_t s = 0; s < arrayReader2->getNumSamples(); ++s)
    {
        arrayReader2->getSample(s, samplePtr);
        const AbcA::TimeSampling ts = arrayReader2->getTimeSampling();
        size_t pointCount = samplePtr->getDimensions().numPoints();

        std::cout << "Sample " << s << ", time " << ts.getSampleTime(s) 
                  << ", points: " << pointCount << std::endl;

        int32_t* data = (int32_t*)samplePtr->getData();
        for (size_t j = 0; j < pointCount; ++j)
        {
            TESTING_ASSERT(data[j] == static_cast<int32_t>(s + j));
            std::cout << j << ": " << data[j] << ", ";
        }
        std::cout << std::endl << std::endl;
        samplePtr->reset();
    }
}

