// Global variables
int total_pairs;
vector<int> connections[1005]; // Adjacency list for the graph structure
int partner_target[1005];      // Stores L(u) if identified (for degree 3 nodes)
bool matched[1005];            // Tracks if a chameleon has been paired in the result

// Perform a query with a list of chameleons
int perform_query(const vector<int>& participants) {
    if (participants.empty()) return 0;

    cout << "Query " << participants.size();
    for (int member : participants) cout << " " << member;
    cout << endl;

    int answer;
    cin >> answer;
    return answer;
}

// Check if chameleon u is connected to any member in set s
bool has_connection(int u, const vector<int>& s) {
    if (s.empty()) return false;

    vector<int> test_group = s;
    test_group.push_back(u);
    int result = perform_query(test_group);

    // If result is not |S| + 1, there's at least one connection reducing color count
    return result != (int)s.size() + 1;
}

// Recursively find neighbors of u within set s using divide-and-conquer
void discover_neighbors(int u, const vector<int>& candidates) {
    if (candidates.empty()) return;

    // Optimization: A node can have at most 3 connections
    if (connections[u].size() >= 3) return;

    // Skip if no connection exists between u and candidates
    if (!has_connection(u, candidates)) return;

    // Base case: single candidate must be a neighbor
    if (candidates.size() == 1) {
        connections[u].push_back(candidates[0]);
        connections[candidates[0]].push_back(u);
        return;
    }

    // Divide and conquer approach
    int split_point = candidates.size() / 2;
    vector<int> left_half(candidates.begin(), candidates.begin() + split_point);
    vector<int> right_half(candidates.begin() + split_point, candidates.end());

    discover_neighbors(u, left_half);
    discover_neighbors(u, right_half);
}

int main() {
    // Optimize I/O operations
    ios_base::sync_with_stdio(false);

    if (!(cin >> total_pairs)) return 0;

    // Maintain independent sets to minimize queries
    // Graph has max degree 3, so greedy coloring with 4 colors suffices
    vector<vector<int>> independent_groups;

    // Phase 1: Build the graph structure
    for (int i = 1; i <= 2 * total_pairs; ++i) {
        // Search for existing connections among previously processed vertices
        for (const auto& group : independent_groups) {
            discover_neighbors(i, group);
        }

        // Place i into first compatible independent set
        bool assigned = false;
        for (auto& group : independent_groups) {
            bool conflict_found = false;

            // Check if i conflicts with any member in this group
            for (int neighbor : connections[i]) {
                for (int member : group) {
                    if (member == neighbor) {
                        conflict_found = true;
                        break;
                    }
                }
                if (conflict_found) break;
            }

            if (!conflict_found) {
                group.push_back(i);
                assigned = true;
                break;
            }
        }

        // Create new group if no placement found
        if (!assigned) {
            independent_groups.push_back({i});
        }
    }

    // Phase 2: Identify special love relationships
    // Nodes with degree 3 have neighbors {c_u, L(u), L^-1(u)}
    // Nodes with degree 1 have only neighbor {c_u}
    for (int i = 1; i <= 2 * total_pairs; ++i) {
        if (connections[i].size() == 3) {
            int a = connections[i][0];
            int b = connections[i][1];
            int c = connections[i][2];

            // Property: Query({i, L^-1(i), c_i}) returns 1
            // The pair that yields 1 with i contains L^-1(i) and c_i
            // Remaining neighbor is L(i)

            if (perform_query({i, a, b}) == 1) {
                partner_target[i] = c;
            } else if (perform_query({i, a, c}) == 1) {
                partner_target[i] = b;
            } else {
                partner_target[i] = a;
            }
        }
    }

    // Phase 3: Output final pairings
    for (int i = 1; i <= 2 * total_pairs; ++i) {
        if (matched[i]) continue;

        // Color partner is the neighbor NOT involved in a love relationship
        // Edge {i, v} is love edge if L(i) == v or L(v) == i
        // Otherwise it's a color-matching edge

        for (int neighbor : connections[i]) {
            if (partner_target[i] != neighbor && partner_target[neighbor] != i) {
                cout << "Answer " << i << " " << neighbor << endl;
                matched[i] = true;
                matched[neighbor] = true;
                break;
            }
        }
    }

    return 0;
}

