#include <vector>
using namespace std;

class Solution {
public:
    void reverseString(vector<char>& str) {
        int start = 0;
        int end = str.size() - 1;
        while (start < end) {
            swap(str[start], str[end]);
            start++;
            end--;
        }
    }
};

