#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    vector<int> sortByBits(vector<int>& inputArray) {
        sort(inputArray.begin(), inputArray.end(), [](int x, int y) {
            int countX = __builtin_popcount(x);
            int countY = __builtin_popcount(y);
            if (countX == countY) 
                return x < y;      // If same number of 1-bits, sort by numeric value
            return countX < countY; // Otherwise, sort by number of 1-bits
        });
        return inputArray;
    }
};

