#include <iostream>
#include <vector>
#include <cmath>
#include <numeric>
#include <random>

// Use unsigned 64-bit integers for modular multiplication to avoid overflow
using u64 = uint64_t;
using u128 = unsigned __int128;

u64 modulus_value;

// Function to compute bit_length(x) = floor(log2(x)) + 1 for x > 0
// Returns the number of bits needed to represent x in binary
int bit_length(u64 value) {
    if (value == 0) return 0;
    return 64 - __builtin_clzll(value);
}

// Modular multiplication using 128-bit intermediate to prevent overflow
u64 mod_multiply(u64 first, u64 second) {
    return (u128)first * second % modulus_value;
}

int main() {
    // Optimize I/O operations
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::cin >> modulus_value;

    // Number of experiments to perform
    const int experiment_count = 24000;
    std::vector<u64> base_values(experiment_count);
    std::vector<long long> observed_results(experiment_count);

    // Initialize random number generator with fixed seed for reproducibility
    std::mt19937_64 prng(std::random_device{}());
    std::uniform_int_distribution<u64> uniform_dist(2, modulus_value - 1);

    // Conduct all experiments first
    for (int idx = 0; idx < experiment_count; ++idx) {
        base_values[idx] = uniform_dist(prng);
        std::cout << "? " << base_values[idx] << std::endl;
        std::cin >> observed_results[idx];
    }

    // Precompute powers and their bit-lengths for efficiency
    std::vector<std::vector<u64>> power_table(experiment_count, std::vector<u64>(60));
    std::vector<std::vector<int>> bit_counts(experiment_count, std::vector<int>(60));
    std::vector<long long> initial_sum(experiment_count, 0);

    for (int exp_idx = 0; exp_idx < experiment_count; ++exp_idx) {
        u64 current_base = base_values[exp_idx];
        for (int power_idx = 0; power_idx < 60; ++power_idx) {
            power_table[exp_idx][power_idx] = current_base;
            bit_counts[exp_idx][power_idx] = bit_length(current_base) + 1;
            initial_sum[exp_idx] += (long long)bit_counts[exp_idx][power_idx] * bit_counts[exp_idx][power_idx];
            current_base = mod_multiply(current_base, current_base);
        }
    }

    u64 secret_d = 0;
    std::vector<u64> remainder_state(experiment_count, 1);
    std::vector<long long> accumulated_correction(experiment_count, 0);

    // Determine each bit of d sequentially from least significant to most significant
    for (int bit_position = 0; bit_position < 60; ++bit_position) {
        long double numerator = 0.0L;
        long double denominator = 0.0L;

        for (int exp_idx = 0; exp_idx < experiment_count; ++exp_idx) {
            long long residual = observed_results[exp_idx] - initial_sum[exp_idx] - accumulated_correction[exp_idx];
            long long coefficient = (long long)bit_counts[exp_idx][bit_position] * (bit_length(remainder_state[exp_idx]) + 1);

            numerator += (long double)residual * coefficient;
            denominator += (long double)coefficient * coefficient;
        }

        long double estimated_beta = 0.0L;
        if (denominator > 1e-12L) {
            estimated_beta = numerator / denominator;
        }

        int current_bit = (estimated_beta > 0.5L) ? 1 : 0;

        if (current_bit) {
            secret_d |= (1ULL << bit_position);
        }

        if (bit_position < 59) {
            // Update correction terms and remainder state for next iteration
            if (current_bit) {
                for (int exp_idx = 0; exp_idx < experiment_count; ++exp_idx) {
                    accumulated_correction[exp_idx] += (long long)bit_counts[exp_idx][bit_position] * (bit_length(remainder_state[exp_idx]) + 1);
                    remainder_state[exp_idx] = mod_multiply(remainder_state[exp_idx], power_table[exp_idx][bit_position]);
                }
            }
        }
    }

    std::cout << "! " << secret_d << std::endl;
    return 0;
}

