// Helper function to expose NonblockingFuture for different types
template <typename T>
void expose_nonblocking_future(nb::handle& parent_module, const std::string& type_suffix) {
    std::string class_name = std::string("NonblockingFuture") + type_suffix;
    nb::class_<NonblockingFuture<T>>(parent_module, class_name.c_str())
        .def("is_ready", &NonblockingFuture<T>::ready)
        .def("fetch_result", &NonblockingFuture<T>::get);
}

// Register core components of the MSCCL++ library
void register_core_components(nb::module_& m) {
    // Version info
    m.def("library_version", &version);

    // Bootstrap interface
    nb::class_<Bootstrap>(m, "Bootstrap")
        .def("rank", &Bootstrap::getRank)
        .def("world_size", &Bootstrap::getNranks)
        .def("ranks_per_node", &Bootstrap::getNranksPerNode)
        .def(
            "transmit",
            [](Bootstrap* self, uintptr_t buffer_addr, size_t byte_count, int target_rank, int message_tag) {
                void* buffer = reinterpret_cast<void*>(buffer_addr);
                self->send(buffer, byte_count, target_rank, message_tag);
            },
            nb::arg("buffer"), nb::arg("size_bytes"), nb::arg("target_rank"), nb::arg("tag"))
        .def(
            "receive",
            [](Bootstrap* self, uintptr_t buffer_addr, size_t byte_count, int source_rank, int message_tag) {
                void* buffer = reinterpret_cast<void*>(buffer_addr);
                self->recv(buffer, byte_count, source_rank, message_tag);
            },
            nb::arg("buffer"), nb::arg("size_bytes"), nb::arg("source_rank"), nb::arg("tag"))
        .def("gather_all", &Bootstrap::allGather, nb::arg("output_buffer"), nb::arg("element_count"))
        .def("synchronize", &Bootstrap::barrier)
        .def("transmit", static_cast<void (Bootstrap::*)(const std::vector<char>&, int, int)>(&Bootstrap::send),
             nb::arg("data"), nb::arg("peer_rank"), nb::arg("tag"))
        .def("receive", static_cast<void (Bootstrap::*)(std::vector<char>&, int, int)>(&Bootstrap::recv),
             nb::arg("data"), nb::arg("peer_rank"), nb::arg("tag"));

    // Unique ID handling
    nb::class_<UniqueId>(m, "UniqueId");

    // TCP-based bootstrap implementation
    nb::class_<TcpBootstrap, Bootstrap>(m, "TcpBootstrap")
        .def(nb::init<int, int>(), "Avoid direct construction; use factory methods instead.")
        .def_static(
            "factory_create", [](int rank, int world_size) { 
                return std::make_shared<TcpBootstrap>(rank, world_size); 
            }, nb::arg("rank"), nb::arg("world_size"))
        .def_static("generate_unique_identifier", &TcpBootstrap::createUniqueId)
        .def("extract_unique_identifier", &TcpBootstrap::getUniqueId)
        .def("establish_connection", 
             static_cast<void (TcpBootstrap::*)(UniqueId, int64_t)>(&TcpBootstrap::initialize),
             nb::call_guard<nb::gil_scoped_release>(), nb::arg("uid"), nb::arg("timeout_seconds") = 30)
        .def("establish_connection", 
             static_cast<void (TcpBootstrap::*)(const std::string&, int64_t)>(&TcpBootstrap::initialize),
             nb::call_guard<nb::gil_scoped_release>(), nb::arg("interface_ip_port"), nb::arg("timeout_seconds") = 30);

    // Transport enumeration
    nb::enum_<Transport>(m, "Transport")
        .value("Undefined", Transport::Unknown)
        .value("CudaIpcLink", Transport::CudaIpc)
        .value("NvLink", Transport::Nvls)
        .value("InfiniBand0", Transport::IB0)
        .value("InfiniBand1", Transport::IB1)
        .value("InfiniBand2", Transport::IB2)
        .value("InfiniBand3", Transport::IB3)
        .value("InfiniBand4", Transport::IB4)
        .value("InfiniBand5", Transport::IB5)
        .value("InfiniBand6", Transport::IB6)
        .value("InfiniBand7", Transport::IB7)
        .value("TotalTransports", Transport::NumTransports);

    // Transport flags
    nb::class_<TransportFlags>(m, "TransportFlags")
        .def(nb::init<>())
        .def(nb::init_implicit<Transport>(), nb::arg("transport_type"))
        .def("contains", &TransportFlags::has, nb::arg("transport_type"))
        .def("is_empty", &TransportFlags::none)
        .def("any_set", &TransportFlags::any)
        .def("all_set", &TransportFlags::all)
        .def("count_active", &TransportFlags::count)
        .def(nb::self | nb::self)
        .def(nb::self | Transport())
        .def(nb::self & nb::self)
        .def(nb::self & Transport())
        .def(nb::self ^ nb::self)
        .def(nb::self ^ Transport())
        .def("__ior__", [](TransportFlags& lhs, const TransportFlags& rhs) { return lhs |= rhs; }, nb::is_operator())
        .def("__iand__", [](TransportFlags& lhs, const TransportFlags& rhs) { return lhs &= rhs; }, nb::is_operator())
        .def("__ixor__", [](TransportFlags& lhs, const TransportFlags& rhs) { return lhs ^= rhs; }, nb::is_operator())
        .def(~nb::self)
        .def(nb::self == nb::self)
        .def(nb::self != nb::self);

    // Registered memory wrapper
    nb::class_<RegisteredMemory>(m, "RegisteredMemory")
        .def(nb::init<>())
        .def("address", &RegisteredMemory::data)
        .def("length", &RegisteredMemory::size)
        .def("available_transports", &RegisteredMemory::transports)
        .def("to_bytes", &RegisteredMemory::serialize)
        .def_static("from_bytes", &RegisteredMemory::deserialize, nb::arg("serialized_data"));

    // Connection interface
    nb::class_<Connection>(m, "Connection")
        .def("write_data", &Connection::write, nb::arg("destination"), nb::arg("dst_offset"),
             nb::arg("source"), nb::arg("src_offset"), nb::arg("size_in_bytes"))
        .def(
            "update_and_push",
            [](Connection* self, RegisteredMemory dst_mem, uint64_t dst_off, uintptr_t src_addr, uint64_t new_val) {
                self->updateAndSync(dst_mem, dst_off, (uint64_t*)src_addr, new_val);
            },
            nb::arg("dst_memory"), nb::arg("dst_offset"), nb::arg("src_address"), nb::arg("new_value"))
        .def("flush_operations", &Connection::flush, nb::call_guard<nb::gil_scoped_release>(),
             nb::arg("max_wait_microseconds") = (int64_t)3e7)
        .def("local_transport", &Connection::transport)
        .def("remote_transport", &Connection::remoteTransport);

    // Endpoint and configuration
    nb::class_<Endpoint>(m, "Endpoint")
        .def("transport_type", &Endpoint::transport)
        .def("to_bytes", &Endpoint::serialize)
        .def_static("from_bytes", &Endpoint::deserialize, nb::arg("serialized_data"));

    nb::class_<EndpointConfig>(m, "EndpointConfig")
        .def(nb::init<>())
        .def(nb::init_implicit<Transport>(), nb::arg("preferred_transport"))
        .def_rw("preferred_transport", &EndpointConfig::transport)
        .def_rw("ib_max_completion_queue_size", &EndpointConfig::ibMaxCqSize)
        .def_rw("ib_max_completion_queue_polls", &EndpointConfig::ibMaxCqPollNum)
        .def_rw("ib_max_send_work_requests", &EndpointConfig::ibMaxSendWr)
        .def_rw("ib_max_work_requests_per_send", &EndpointConfig::ibMaxWrPerSend);

    // Context management
    nb::class_<Context>(m, "Context")
        .def(nb::init<>())
        .def(
            "register_host_memory",
            [](Communicator* comm, uintptr_t ptr, size_t size, TransportFlags transports) {
                return comm->registerMemory((void*)ptr, size, transports);
            },
            nb::arg("host_pointer"), nb::arg("size_bytes"), nb::arg("transports"))
        .def("instantiate_endpoint", &Context::createEndpoint, nb::arg("config"))
        .def("establish_link", &Context::connect, nb::arg("local_endpoint"), nb::arg("remote_endpoint"));

    // Expose futures for key types
    expose_nonblocking_future<RegisteredMemory>(m, "RegisteredMemory");
    expose_nonblocking_future<std::shared_ptr<Connection>>(m, "shared_ptr_Connection");

    // Communicator class
    nb::class_<Communicator>(m, "Communicator")
        .def(nb::init<std::shared_ptr<Bootstrap>, std::shared_ptr<Context>>(), nb::arg("bootstrap_instance"),
             nb::arg("context") = nullptr)
        .def("bootstrap", &Communicator::bootstrap)
        .def("context", &Communicator::context)
        .def(
            "register_device_memory",
            [](Communicator* self, uintptr_t ptr, size_t size, TransportFlags transports) {
                return self->registerMemory((void*)ptr, size, transports);
            },
            nb::arg("device_pointer"), nb::arg("size_bytes"), nb::arg("transports"))
        .def("announce_memory", &Communicator::sendMemoryOnSetup, nb::arg("memory"), nb::arg("remote_rank"),
             nb::arg("tag"))
        .def("await_memory", &Communicator::recvMemoryOnSetup, nb::arg("remote_rank"), nb::arg("tag"))
        .def("setup_link", &Communicator::connectOnSetup, nb::arg("remote_rank"), nb::arg("tag"),
             nb::arg("local_config"))
        .def("find_peer_rank", &Communicator::remoteRankOf)
        .def("extract_tag", &Communicator::tagOf)
        .def("finalize_setup", &Communicator::setup);
}

