// Test structures for serialization (renamed and slightly modified)
struct SamplePayload {
  std::string text;
  bool operator==(const SamplePayload& rhs) const { return text == rhs.text; }
};

struct SampleRecord {
  int identifier;
  int value;
  bool operator==(const SampleRecord& rhs) const { 
    return identifier == rhs.identifier && value == rhs.value; 
  }
};

// Glaze metadata for test structures (with reordered fields and renamed members)
template <>
struct glz::meta<SamplePayload> {
  using T = SamplePayload;
  static constexpr auto value = glz::object("text", &T::text);
};

template <>
struct glz::meta<SampleRecord> {
  using T = SampleRecord;
  static constexpr auto value = glz::object("identifier", &T::identifier, "value", &T::value);
};

namespace aeronet::test {

class JsonSerializerTest : public ::testing::Test {
 protected:
  void SetUp() override {}
  void TearDown() override {}
};

TEST_F(JsonSerializerTest, SerializeSimpleMessage) {
  SamplePayload payload{"Greetings, Universe!"};
  auto json = SerializeToJson(payload);
  // The JSON should contain the serialized message
  ASSERT_FALSE(json.empty());
  ASSERT_TRUE(json.contains("Greetings, Universe!"));
}

TEST_F(JsonSerializerTest, SerializeWorldObject) {
  SampleRecord record{100, 5678};
  auto json = SerializeToJson(record);
  ASSERT_FALSE(json.empty());
  ASSERT_TRUE(json.contains("100"));
  ASSERT_TRUE(json.contains("5678"));
}

