// Safe subtraction implementation to prevent underflow in unsigned integers
unsigned int NatSubUnderflowSafe::sub_checked(const unsigned int operand1,
                                              const unsigned int operand2) {
  // Check if subtraction would cause underflow by comparing result with first operand
  unsigned int difference = operand1 - operand2;
  return ((difference > operand1) ? 0 : difference);
}

// Alternative subtraction method with operands swapped in comparison logic
unsigned int NatSubUnderflowSafe::sub_alt(const unsigned int value_a,
                                          const unsigned int value_b) {
  // Compute difference and check for underflow condition
  unsigned int diff = value_b - value_a;
  return ((diff > value_b) ? 0 : diff);
}

