// Perform full decoding of an Ogg Vorbis packet
int vorbis_synthesis(vorbis_block *block, ogg_packet *packet) {
    vorbis_dsp_state     *dsp = block->vd;
    private_state        *backend = dsp->backend_state;
    vorbis_info          *info = dsp->vi;
    codec_setup_info     *setup = info->codec_setup;
    oggpack_buffer       *buffer = &block->opb;
    int                   mapping_type, current_mode, channel_index;

    /* Prepare internal state for decoding */
    _vorbis_block_ripcord(block);
    oggpack_readinit(buffer, packet->packet, packet->bytes);

    /* Validate packet type */
    if (oggpack_read(buffer, 1) != 0) {
        /* Not an audio data packet */
        return(OV_ENOTAUDIO);
    }

    /* Extract mode index and block configuration */
    current_mode = oggpack_read(buffer, backend->modebits);
    if (current_mode == -1) return(OV_EBADPACKET);

    block->mode = current_mode;
    block->W = setup->mode_param[current_mode]->blockflag;

    if (block->W) {
        block->lW = oggpack_read(buffer, 1);
        block->nW = oggpack_read(buffer, 1);
        if (block->nW == -1) return(OV_EBADPACKET);
    } else {
        block->lW = 0;
        block->nW = 0;
    }

    /* Set metadata fields */
    block->granulepos = packet->granulepos;
    block->sequence   = packet->packetno;
    block->eofflag    = packet->e_o_s;

    /* Allocate PCM output buffers */
    block->pcmend = setup->blocksizes[block->W];
    block->pcm = _vorbis_block_alloc(block, sizeof(*block->pcm) * info->channels);
    for (channel_index = 0; channel_index < info->channels; ++channel_index) {
        block->pcm[channel_index] = _vorbis_block_alloc(block, block->pcmend * sizeof(*block->pcm[channel_index]));
    }

    /* Determine mapping and invoke inverse transform */
    mapping_type = setup->map_type[setup->mode_param[current_mode]->mapping];
    return(_mapping_P[mapping_type]->inverse(block, setup->map_param[setup->mode_param[current_mode]->mapping]));
}

/* Track PCM position without decoding samples — useful for fast-forwarding */
int vorbis_synthesis_trackonly(vorbis_block *block, ogg_packet *packet) {
    vorbis_dsp_state     *dsp = block->vd;
    private_state        *backend = dsp->backend_state;
    vorbis_info          *info = dsp->vi;
    codec_setup_info     *setup = info->codec_setup;
    oggpack_buffer       *buffer = &block->opb;
    int                   current_mode;

    _vorbis_block_ripcord(block);
    oggpack_readinit(buffer, packet->packet, packet->bytes);

    if (oggpack_read(buffer, 1) != 0) {
        return(OV_ENOTAUDIO);  // Non-audio packet
    }

    current_mode = oggpack_read(buffer, backend->modebits);
    if (current_mode == -1) return(OV_EBADPACKET);

    block->mode = current_mode;
    block->W = setup->mode_param[current_mode]->blockflag;

    if (block->W) {
        block->lW = oggpack_read(buffer, 1);
        block->nW = oggpack_read(buffer, 1);
        if (block->nW == -1) return(OV_EBADPACKET);
    } else {
        block->lW = 0;
        block->nW = 0;
    }

    block->granulepos = packet->granulepos;
    block->sequence   = packet->packetno;
    block->eofflag    = packet->e_o_s;

    /* Skip PCM allocation */
    block->pcmend = 0;
    block->pcm    = NULL;
    return(0);
}

/* Return block size for a given packet without decoding */
long vorbis_packet_blocksize(vorbis_info *info, ogg_packet *packet) {
    codec_setup_info     *setup = info->codec_setup;
    oggpack_buffer       buffer;
    int                  current_mode;

    oggpack_readinit(&buffer, packet->packet, packet->bytes);

    if (oggpack_read(&buffer, 1) != 0) {
        return(OV_ENOTAUDIO);
    }

    {
        int modebits = 0;
        int num_modes = setup->modes;
        while (num_modes > 1) {
            modebits++;
            num_modes >>= 1;
        }

        current_mode = oggpack_read(&buffer, modebits);
    }

    if (current_mode == -1) return(OV_EBADPACKET);
    return(setup->blocksizes[setup->mode_param[current_mode]->blockflag]);
}

/* Enable or disable half-rate mode */
int vorbis_synthesis_halfrate(vorbis_info *info, int enable) {
    codec_setup_info *setup = info->codec_setup;

    /* MDCT constraint: minimum window size is 64 samples */
    if (setup->blocksizes[0] <= 64 && enable) return -1;

    setup->halfrate_flag = (enable ? 1 : 0);
    return 0;
}

/* Query whether half-rate mode is active */
int vorbis_synthesis_halfrate_p(vorbis_info *info) {
    codec_setup_info *setup = info->codec_setup;
    return setup->halfrate_flag;
}

