// Perform type casting for a literal expression
void LiteralExpression::cast(const LogicalType& newType) {
    // Ensure the literal value allows type conversion before proceeding
    if (!value.allowTypeChange()) {
        // LCOV_EXCL_START
        throw BinderException(
            std::format("Literal expression cannot be cast from {} to {}.",
                dataType.toString(), newType.toString()));
        // LCOV_EXCL_STOP
    }

    // Update the data type and propagate the change to the value
    dataType = newType.copy();
    value.setDataType(newType);
}

