// Type alias for symbol-stub pair
using SymbolStubPair = std::pair<MCSymbol *, MachineModuleInfoImpl::StubValueTy>;

// Comparison function to sort stub pairs by symbol name
static int CompareSymbolStubs(const SymbolStubPair *A, const SymbolStubPair *B) {
  return A->first->getName().compare(B->first->getName());
}

// Return sorted list of stubs and clear the original map
MachineModuleInfoImpl::SymbolListTy MachineModuleInfoImpl::getSortedStubs(
    DenseMap<MCSymbol *, MachineModuleInfoImpl::StubValueTy> &Stubs) {
  SymbolListTy SortedStubs(Stubs.begin(), Stubs.end());
  array_pod_sort(SortedStubs.begin(), SortedStubs.end(), CompareSymbolStubs);
  Stubs.clear();
  return SortedStubs;
}

