int main(int argc, char** argv) {
    int* deviceMemory;
    int counter_index = 0;
    if (argc > 1) counter_index = atoi(argv[1]);

    prepare();

    // Initialize the profiler
    CHECK_ROCPROFILER(rocprofiler_initialize());

    // Create a profiling session in no-replay mode
    rocprofiler_session_id_t session_handle;
    CHECK_ROCPROFILER(rocprofiler_create_session(ROCPROFILER_NONE_REPLAY_MODE, &session_handle));

    // Set up output buffer for collected data
    rocprofiler_buffer_id_t buffer_handle;
    CHECK_ROCPROFILER(rocprofiler_create_buffer(
        session_handle,
        [](const rocprofiler_record_header_t* record, const rocprofiler_record_header_t* end_record,
           rocprofiler_session_id_t session_id, rocprofiler_buffer_id_t buffer_id) {
            WriteBufferRecords(record, end_record, session_id, buffer_id);
        },
        0x777777, &buffer_handle));

    // Configure XGMI counter sampling
    rocprofiler_filter_id_t filter_handle;
    [[maybe_unused]] rocprofiler_filter_property_t filter_props = {};

    std::vector<std::string> xgmi_metrics = {
        "xgmi_link0_data_outbound", "xgmi_link1_data_outbound",
        "xgmi_link2_data_outbound", "xgmi_link3_data_outbound",
        "xgmi_link4_data_outbound", "xgmi_link5_data_outbound",
        "xgmi_link6_data_outbound", "xgmi_link7_data_outbound"
    };

    rocprofiler_counters_sampler_counter_input_t metric_inputs[2] = {
        {.name = const_cast<char*>(xgmi_metrics[counter_index].c_str()),
         .type = ROCPROFILER_COUNTERS_SAMPLER_XGMI_COUNTERS}
    };

    uint32_t interval_ms = 1000;
    uint32_t run_time_ms = 5000;

    rocprofiler_counters_sampler_parameters_t sampler_config = {
        .counters = metric_inputs,
        .counters_num = 1,
        .sampling_rate = interval_ms,
        .sampling_duration = run_time_ms,
        .gpu_agent_index = 0
    };

    CHECK_ROCPROFILER(rocprofiler_create_filter(
        session_handle, 
        ROCPROFILER_COUNTERS_SAMPLER,
        rocprofiler_filter_data_t{.counters_sampler_parameters = sampler_config}, 
        0, 
        &filter_handle,
        filter_props));

    CHECK_ROCPROFILER(rocprofiler_set_filter_buffer(session_handle, filter_handle, buffer_handle));

    // Standard HIP operations
    hipDeviceProp_t device_properties;
    HIP_CALL(hipGetDeviceProperties(&device_properties, 0));
    HIP_CALL(hipMalloc((void**)&deviceMemory, 1 * sizeof(int)));

    // Launch kernels not to be profiled
    kernelCalls('A');
    kernelCalls('B');

    std::cout << "Monitoring: " << xgmi_metrics[counter_index]
              << " ; sample interval: " << interval_ms << " ms; total duration: " << run_time_ms << " ms" << std::endl;

    // Start profiling session
    CHECK_ROCPROFILER(rocprofiler_start_session(session_handle));

    // Launch kernels to be profiled
    kernelCalls('C');
    kernelCalls('D');
    kernelCalls('E');
    kernelCalls('F');

    // Cleanup non-profiled resources
    HIP_CALL(hipFree(deviceMemory));

    // Let sampling run for extended period
    sleep(6);

    // Stop and finalize profiling
    CHECK_ROCPROFILER(rocprofiler_terminate_session(session_handle));
    CHECK_ROCPROFILER(rocprofiler_flush_data(session_handle, buffer_handle));
    CHECK_ROCPROFILER(rocprofiler_destroy_session(session_handle));
    CHECK_ROCPROFILER(rocprofiler_finalize());

    return 0;
}

