namespace {
// Track seen exception addresses to avoid duplicate logging
std::unordered_set<uintptr_t> g_exception_address_cache;
// Check if exception address was seen before, and record it if not
// Returns true if address was already seen (should skip detailed logging)
bool IsExceptionAddressDuplicate(uintptr_t address) {
    utils::SRWLockExclusive lock(utils::g_seen_exception_addresses_lock);
    auto result = g_exception_address_cache.insert(address);
    return !result.second;  // true if already existed (insert failed)
}

// Helper function to print process information
void DisplayProcessDetails() {
    try {
        LogInfo("=== PROCESS DETAILS ===");
        // Process ID
        DWORD pid = GetCurrentProcessId();
        std::ostringstream pid_stream;
        pid_stream << "Process ID: " << pid;
        LogInfo("%s", pid_stream.str().c_str());

        // Thread ID
        DWORD tid = GetCurrentThreadId();
        std::ostringstream tid_stream;
        tid_stream << "Thread ID: " << tid;
        LogInfo("%s", tid_stream.str().c_str());

        // Process executable path
        wchar_t exe_path[MAX_PATH];
        if (GetModuleFileNameW(nullptr, exe_path, MAX_PATH) != 0) {
            int required_size = WideCharToMultiByte(CP_UTF8, 0, exe_path, -1, nullptr, 0, nullptr, nullptr);
            if (required_size > 0) {
                std::vector<char> temp_buffer(required_size);
                WideCharToMultiByte(CP_UTF8, 0, exe_path, -1, temp_buffer.data(), required_size, nullptr, nullptr);
                std::ostringstream path_stream;
                path_stream << "Executable Path: " << temp_buffer.data();
                LogInfo("%s", path_stream.str().c_str());
            }
        }

        // Command line
        LPSTR cmdline = GetCommandLineA();
        if (cmdline != nullptr) {
            std::ostringstream cmd_stream;
            cmd_stream << "Command Line: " << cmdline;
            LogInfo("%s", cmd_stream.str().c_str());
        }

        // Process memory information
        HANDLE proc_handle = GetCurrentProcess();
        PROCESS_MEMORY_COUNTERS_EX mem_info = {};
        if (GetProcessMemoryInfo(proc_handle, reinterpret_cast<PROCESS_MEMORY_COUNTERS*>(&mem_info),
                                 sizeof(mem_info)) != 0) {
            std::ostringstream mem_stream;
            mem_stream << "Memory Usage - Working Set: " << (mem_info.WorkingSetSize / 1024 / 1024) << " MB, "
                       << "Peak Working Set: " << (mem_info.PeakWorkingSetSize / 1024 / 1024) << " MB, "
                       << "Page Faults: " << mem_info.PageFaultCount;
            LogInfo("%s", mem_stream.str().c_str());
        }
        LogInfo("=== END PROCESS DETAILS ===");
    } catch (...) {
        LogInfo("=== PROCESS DETAILS ERROR ===");
        LogInfo("Exception occurred while gathering process details");
        LogInfo("=== END PROCESS DETAILS ===");
    }
}

// Helper function to print system information
void DisplaySystemDetails() {
    try {
        LogInfo("=== SYSTEM DETAILS ===");
        // OS Version (using RtlGetVersion which is safer than GetVersionEx)
        typedef NTSTATUS(WINAPI * RtlGetVersionFunc)(OSVERSIONINFOEXW*);
        HMODULE ntdll_module = GetModuleHandleW(L"ntdll.dll");
        if (ntdll_module != nullptr) {
            RtlGetVersionFunc rtl_get_version_func =
                reinterpret_cast<RtlGetVersionFunc>(GetProcAddress(ntdll_module, "RtlGetVersion"));
            if (rtl_get_version_func != nullptr) {
                OSVERSIONINFOEXW os_details = {};
                os_details.dwOSVersionInfoSize = sizeof(OSVERSIONINFOEXW);
                if (rtl_get_version_func(&os_details) == 0) {
                    std::ostringstream os_stream;
                    os_stream << "OS Version: Windows " << os_details.dwMajorVersion << "." << os_details.dwMinorVersion
                              << " Build " << os_details.dwBuildNumber;
                    if (os_details.wServicePackMajor > 0) {
                        os_stream << " SP" << os_details.wServicePackMajor;
                    }
                    LogInfo("%s", os_stream.str().c_str());
                }
            }
        }

        // CPU Information
        SYSTEM_INFO sys_info = {};
        GetSystemInfo(&sys_info);
        std::ostringstream cpu_stream;
        cpu_stream << "CPU - Cores: " << sys_info.dwNumberOfProcessors << ", Architecture: ";
        switch (sys_info.wProcessorArchitecture) {
            case PROCESSOR_ARCHITECTURE_AMD64: cpu_stream << "x64"; break;
            case PROCESSOR_ARCHITECTURE_INTEL: cpu_stream << "x86"; break;
            case PROCESSOR_ARCHITECTURE_ARM:   cpu_stream << "ARM"; break;
            case PROCESSOR_ARCHITECTURE_ARM64: cpu_stream << "ARM64"; break;
            default:                           cpu_stream << "Unknown (0x" << std::hex << sys_info.wProcessorArchitecture << ")"; break;
        }
        LogInfo("%s", cpu_stream.str().c_str());

        // System memory (more detailed)
        MEMORYSTATUSEX mem_status = {};
        mem_status.dwLength = sizeof(mem_status);
        if (GlobalMemoryStatusEx(&mem_status) != 0) {
            std::ostringstream mem_stream;
            mem_stream << "System Memory - Total: " << (mem_status.ullTotalPhys / 1024 / 1024 / 1024) << " GB, "
                       << "Available: " << (mem_status.ullAvailPhys / 1024 / 1024 / 1024) << " GB, "
                       << "Load: " << mem_status.dwMemoryLoad << "%";
            LogInfo("%s", mem_stream.str().c_str());
        }

        // Current time
        time_t current_time;
        time(&current_time);
        struct tm local_time_info;
        if (localtime_s(&local_time_info, &current_time) == 0) {
            char time_buffer[64];
            strftime(time_buffer, sizeof(time_buffer), "%Y-%m-%d %H:%M:%S", &local_time_info);
            std::ostringstream time_stream;
            time_stream << "Crash Timestamp: " << time_buffer;
            LogInfo("%s", time_stream.str().c_str());
        }
        LogInfo("=== END SYSTEM DETAILS ===");
    } catch (...) {
        LogInfo("=== SYSTEM DETAILS ERROR ===");
        LogInfo("Exception occurred while gathering system details");
        LogInfo("=== END SYSTEM DETAILS ===");
    }
}

