#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    unsigned long long value;
    if (!(cin >> value)) return 0;

    // Construct a 64x64 matrix using snake-like pattern
    // This approach enables encoding numbers up to 2^64 through bridge connections
    int size = 64;
    vector<vector<int>> grid(size, vector<int>(size, 0));

    // Create the serpentine pattern: alternate row directions
    for (int row = 0; row < size; ++row) {
        if (row % 2 == 0) {
            for (int col = 0; col <= row; ++col) grid[row][col] = 1;
        } else {
            for (int col = 0; col <= row; ++col) grid[row][size - 1 - col] = 1;
        }
    }

    // Establish the terminal column as a path collector
    for (int row = 0; row < size; ++row) grid[row][size - 1] = 1;

    // Activate horizontal bridges based on binary representation of input
    for (int bit = 0; bit < size; ++bit) {
        if (((value >> bit) & 1ULL) == 0) continue;

        if (bit % 2 == 0) {
            // Even rows: fill from diagonal position to right edge
            for (int col = bit; col < size; ++col) grid[bit][col] = 1;
        } else {
            // Odd rows: fill from mirrored diagonal to right edge
            for (int col = size - 1 - bit; col < size; ++col) grid[bit][col] = 1;
        }
    }

    cout << size << "\n";
    for (int r = 0; r < size; ++r) {
        for (int c = 0; c < size; ++c) {
            if (c) cout << ' ';
            cout << grid[r][c];
        }
        cout << "\n";
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <limits>
#include <climits>
using namespace std;

class Solution {
public:
    // Helper to compute smallest and largest bloom days
    vector<int> getMinAndMax(const vector<int>& days) {
        int smallest = INT_MAX;
        int largest = INT_MIN;
        for (int d : days) {
            if (d > largest) largest = d;
            if (d < smallest) smallest = d;
        }
        return {smallest, largest};
    }

    // Check if we can form at least 'targetBouquets' bouquets by 'day'
    bool canProduce(vector<int>& bloomDays, int targetBouquets, int flowersPerBouquet, int dayLimit) {
        int bouquetsMade = 0;
        int currentStreak = 0;
        for (int bloomDay : bloomDays) {
            if (bloomDay <= dayLimit) {
                currentStreak++;
                if (currentStreak == flowersPerBouquet) {
                    bouquetsMade++;
                    currentStreak = 0;
                }
            } else {
                currentStreak = 0;
            }
        }
        return bouquetsMade >= targetBouquets;
    }

    // Brute-force approach: linear scan over possible days
    int minDaysBruteForce(vector<int>& bloomDays, int targetBouquets, int flowersPerBouquet) {
        long long needed = (long long)targetBouquets * flowersPerBouquet;
        if (needed > bloomDays.size()) return -1;

        vector<int> range = getMinAndMax(bloomDays);
        int startDay = range[0];
        int endDay = range[1];

        for (int d = startDay; d <= endDay; ++d) {
            if (canProduce(bloomDays, targetBouquets, flowersPerBouquet, d)) {
                return d;
            }
        }
        return -1;
    }

    // Optimized approach: binary search on answer space
    int minDaysBinarySearch(vector<int>& bloomDays, int targetBouquets, int flowersPerBouquet) {
        long long needed = (long long)targetBouquets * flowersPerBouquet;
        if (needed > bloomDays.size()) return -1;

        vector<int> range = getMinAndMax(bloomDays);
        int left = range[0];
        int right = range[1];

        while (left < right) {
            int mid = left + (right - left) / 2;
            if (canProduce(bloomDays, targetBouquets, flowersPerBouquet, mid)) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }
        return left;
    }
};

int main() {
    vector<int> bloomPeriod = {7,7,7,7,12,7,7};
    int bouquetsNeeded = 2;
    int adjacentFlowers = 3;

    Solution solver;
    int result = solver.minDaysBinarySearch(bloomPeriod, bouquetsNeeded, adjacentFlowers); // expected: 12
    cout << result << endl;

    return 0;
}

