TEST_F(ShmTests, ShmSendProxyProgress) {
  opArgs.state = ncclProxyOpReady;
  opArgs.protocol = NCCL_PROTO_SIMPLE;
  opArgs.nsubs = 1;
  opArgs.chunkSteps = 1;
  opArgs.sliceSteps = 1;
  opArgs.subs[0].nsteps = 4;
  opArgs.subs[0].connection = &conn;

  ncclResult_t result = shmSendProxyProgress(&state, &opArgs);
  EXPECT_EQ(result, ncclSuccess);
  EXPECT_EQ(opArgs.state, ncclProxyOpProgress);
  EXPECT_EQ(opArgs.subs[0].base, 0);
  EXPECT_EQ(opArgs.subs[0].posted, 0);
  EXPECT_EQ(opArgs.subs[0].transmitted, 0);
  EXPECT_EQ(opArgs.subs[0].done, 0);

  for (int i = 0; i < opArgs.subs[0].nsteps; i++) {
    proxyInfo->ceRecvMem->tail = i + 1;
    proxyInfo->ceRecvMem->connFifo[i % NCCL_STEPS].size =
        state.buffSizes[NCCL_PROTO_SIMPLE] / NCCL_STEPS;

    result = shmSendProxyProgress(&state, &opArgs);
    EXPECT_EQ(result, ncclSuccess);

    hipStreamSynchronize(proxyInfo->stream);

    result = shmSendProxyProgress(&state, &opArgs);
    EXPECT_EQ(result, ncclSuccess);
    EXPECT_GE(opArgs.subs[0].transmitted, i + 1);
    EXPECT_GE(opArgs.subs[0].done, i + 1);
  }

  EXPECT_EQ(opArgs.state, ncclProxyOpNone);
  EXPECT_EQ(opArgs.subs[0].transmitted, opArgs.subs[0].nsteps);
  EXPECT_EQ(opArgs.subs[0].done, opArgs.subs[0].nsteps);
  EXPECT_EQ(opArgs.done, opArgs.nsubs);
  EXPECT_EQ(proxyInfo->recvMem->tail, opArgs.subs[0].base + opArgs.subs[0].done);
}

