  memset(&resp->desc, 0, sizeof(ncclShmIpcDesc_t));
  EXPECT_EQ(memcmp(&proxyInfo->desc, &resp->desc, sizeof(ncclShmIpcDesc_t)), 0);

  if (proxyInfo) {
