#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

const int MAX_ROWS = 30;
int heap_arr[MAX_ROWS][MAX_ROWS]; // stores the ball values

struct Operation {
    int r1, c1, r2, c2;
};

vector<Operation> operations_list;

void execute_swap(int r1, int c1, int r2, int c2) {
    operations_list.push_back({r1, c1, r2, c2});
    swap(heap_arr[r1][c1], heap_arr[r2][c2]);
}

int main() {
    // Read input: fill the triangular structure
    for (int row = 0; row < MAX_ROWS; ++row) {
        for (int col = 0; col <= row; ++col) {
            cin >> heap_arr[row][col];
        }
    }

    int operation_count = 0;
    const int LIMIT_OPERATIONS = 10000;
    bool has_moved = true;

    while (has_moved && operation_count < LIMIT_OPERATIONS) {
        has_moved = false;

        // Process from second-last row upward
        for (int row = MAX_ROWS - 2; row >= 0; --row) {
            for (int col = 0; col <= row; ++col) {
                int curr_row = row;
                int curr_col = col;

                // Sift down the element at (curr_row, curr_col)
                while (curr_row < MAX_ROWS - 1) {
                    int current_val = heap_arr[curr_row][curr_col];
                    int left_child = heap_arr[curr_row + 1][curr_col];
                    int right_child = heap_arr[curr_row + 1][curr_col + 1];

                    // Check if heap property is satisfied
                    if (current_val <= left_child && current_val <= right_child) {
                        break;
                    }

                    // Determine which child to swap with (smaller one)
                    int target_row, target_col;
                    if (left_child <= right_child) {
                        target_row = curr_row + 1;
                        target_col = curr_col;
                    } else {
                        target_row = curr_row + 1;
                        target_col = curr_col + 1;
                    }

                    execute_swap(curr_row, curr_col, target_row, target_col);
                    operation_count++;
                    has_moved = true;

                    if (operation_count >= LIMIT_OPERATIONS) break;

                    // Move down to the child position
                    curr_row = target_row;
                    curr_col = target_col;
                }

                if (operation_count >= LIMIT_OPERATIONS) break;
            }

            if (operation_count >= LIMIT_OPERATIONS) break;
        }
    }

    // Output results
    cout << operations_list.size() << endl;
    for (const Operation& op : operations_list) {
        cout << op.r1 << " " << op.c1 << " " << op.r2 << " " << op.c2 << endl;
    }

    return 0;
}

