static void runLongRunningOperation(Connection* conn) {
    auto result = conn->query(
        "UNWIND RANGE(1,100000) AS x UNWIND RANGE(1, 100000) AS y RETURN COUNT(x + y);");
    ASSERT_FALSE(result->isSuccess());
    ASSERT_EQ(result->getErrorMessage(), "Interrupted.");
}

TEST_F(ApiTest, Interrupt) {
    std::thread longRunningThread(runLongRunningOperation, conn.get());
    std::atomic<bool> executionCompleted{false};
    std::thread interrupterThread([&]() {
        while (!executionCompleted) {
#ifdef _WIN32
            Sleep(1000);
#else
            sleep(1 /* wait 1 second before interrupting the operation */);
#endif
            conn->interrupt();
        }
    });
    longRunningThread.join();
    executionCompleted = true;
    interrupterThread.join();
}
