TEST_F(ApiTest, CloseDatabaseBeforeQueryResultAndConnection) {
    auto config = SystemConfig();
    config.bufferPoolSize = 10 * 1024 * 1024; // 10MB
    config.maxNumThreads = 2;
    config.maxDBSize = 1 << 30; // 1GB
    auto localDatabase = std::make_unique<Database>(":memory:", config);
    auto connection = std::make_unique<Connection>(localDatabase.get());
    auto queryResult = connection->query("RETURN 1+1 AS col;");
    ASSERT_TRUE(queryResult->isSuccess());
    ASSERT_EQ(queryResult->getNext()->getValue(0)->getValue<int64_t>(), 2);
    queryResult->resetIterator();
    // Close the database before the result and connection. It should not cause SEGFAULT.
    localDatabase.reset();
    // All public Connection methods that check for closed DB
    try {
        connection->setMaxNumThreadForExec(1);
    } catch (Exception& e) {
        ASSERT_STREQ(e.what(), "Runtime exception: The current operation is not allowed because "
                               "the parent database is closed.");
    }
    try {
        connection->getMaxNumThreadForExec();
    } catch (Exception& e) {
        ASSERT_STREQ(e.what(), "Runtime exception: The current operation is not allowed because "
                               "the parent database is closed.");
    }
    try {
        connection->prepare("RETURN 1");
    } catch (Exception& e) {
        ASSERT_STREQ(e.what(), "Runtime exception: The current operation is not allowed because "
                               "the parent database is closed.");
    }
    try {
        std::unordered_map<std::string, std::unique_ptr<Value>> params;
        connection->prepareWithParams("RETURN 1", std::move(params));
    } catch (Exception& e) {
        ASSERT_STREQ(e.what(), "Runtime exception: The current operation is not allowed because "
                               "the parent database is closed.");
    }
    try {
        connection->query("RETURN 2+2;");
    } catch (Exception& e) {
        ASSERT_STREQ(e.what(), "Runtime exception: The current operation is not allowed because "
                               "the parent database is closed.");
    }
    try {
        std::unordered_map<std::string, std::unique_ptr<Value>> params;
        connection->executeWithParams(nullptr, std::move(params));
    } catch (Exception& e) {
        ASSERT_STREQ(e.what(), "Runtime exception: The current operation is not allowed because "
                               "the parent database is closed.");
    }
    try {
        connection->interrupt();
    } catch (Exception& e) {
        ASSERT_STREQ(e.what(), "Runtime exception: The current operation is not allowed because "
                               "the parent database is closed.");
    }
    try {
        connection->setQueryTimeOut(1000);
    } catch (Exception& e) {
        ASSERT_STREQ(e.what(), "Runtime exception: The current operation is not allowed because "
                               "the parent database is closed.");
    }
    // All public QueryResult methods that check for closed DB
    ASSERT_TRUE(queryResult->isSuccess());
    ASSERT_NO_THROW(queryResult->getErrorMessage());
    ASSERT_NO_THROW(queryResult->getNumColumns());
    ASSERT_NO_THROW(queryResult->getColumnNames());
    ASSERT_NO_THROW(queryResult->getColumnDataTypes());
    ASSERT_NO_THROW(queryResult->getQuerySummary());
    try {
        (void)queryResult->getNumTuples();
        FAIL();
    } catch (Exception& e) {
        ASSERT_STREQ(e.what(), "Runtime exception: The current operation is not allowed because "
                               "the parent database is closed.");
    }
    try {
        queryResult->resetIterator();
        FAIL();
    } catch (Exception& e) {
        ASSERT_STREQ(e.what(), "Runtime exception: The current operation is not allowed because "
                               "the parent database is closed.");
    }
    try {
        (void)queryResult->hasNext();
        FAIL();
    } catch (Exception& e) {
        ASSERT_STREQ(e.what(), "Runtime exception: The current operation is not allowed because "
                               "the parent database is closed.");
    }
    try {
        (void)queryResult->hasNextQueryResult();
        FAIL();
    } catch (Exception& e) {
        ASSERT_STREQ(e.what(), "Runtime exception: The current operation is not allowed because "
                               "the parent database is closed.");
    }
    try {
        queryResult->getNextQueryResult();
        FAIL();
    } catch (Exception& e) {
        ASSERT_STREQ(e.what(), "Runtime exception: The current operation is not allowed because "
                               "the parent database is closed.");
    }
    try {
        queryResult->getNext();
        FAIL();
    } catch (Exception& e) {
        ASSERT_STREQ(e.what(), "Runtime exception: The current operation is not allowed because "
                               "the parent database is closed.");
    }
    try {
        (void)queryResult->toString();
        FAIL();
    } catch (Exception& e) {
        ASSERT_STREQ(e.what(), "Runtime exception: The current operation is not allowed because "
                               "the parent database is closed.");
    }
    try {
        (void)queryResult->getArrowSchema();
        FAIL();
    } catch (Exception& e) {
        ASSERT_STREQ(e.what(), "Runtime exception: The current operation is not allowed because "
                               "the parent database is closed.");
    }
    try {
        queryResult->getNextArrowChunk(1);
        FAIL();
    } catch (Exception& e) {
        ASSERT_STREQ(e.what(), "Runtime exception: The current operation is not allowed because "
                               "the parent database is closed.");
    }
}

TEST_F(ApiTest, CloseDatabaseBeforeQueryResultWithMultipleStatements) {
    auto config = SystemConfig();
    config.bufferPoolSize = 10 * 1024 * 1024; // 10MB
    config.maxNumThreads = 2;
    config.maxDBSize = 1 << 30; // 1GB
    auto localDatabase = std::make_unique<Database>(":memory:", config);
    auto connection = std::make_unique<Connection>(localDatabase.get());
    auto queryResult = connection->query("RETURN 1+1; RETURN 2+2; RETURN 3+3;");
    ASSERT_TRUE(queryResult->isSuccess());
    ASSERT_EQ(queryResult->getNext()->getValue(0)->getValue<int64_t>(), 2);
    auto nextResult = queryResult->getNextQueryResult();
    ASSERT_EQ(nextResult->getNext()->getValue(0)->getValue<int64_t>(), 4);
    nextResult = queryResult->getNextQueryResult();
    ASSERT_EQ(nextResult->getNext()->getValue(0)->getValue<int64_t>(), 6);
    queryResult->resetIterator();
    localDatabase.reset();
}

TEST_F(ApiTest, ToStringDoesNotModifyIterator) {
    auto queryResult = conn->query("MATCH (p:person) RETURN p.ID ORDER BY p.ID");
    ASSERT_TRUE(queryResult->isSuccess());
