/// Send an Argo A/C formatted message.
/// Status: [WREM-2] BETA / Likely functional.
///         [WREM-3] Verified working with Argo 13 ECO (WREM-3)
/// @note The "no footer" component requires re-validation but kept for compatibility.
///       Prefer using @c sendFooter=true version for WREM-2 as well.
/// @param[in] data The message to transmit.
/// @param[in] nbytes The byte count of message to be sent.
/// @param[in] repeat How many times the command should repeat.
/// @param[in] sendFooter Whether to include footer and final gap.
///                       *REQUIRED* for WREM-3, UNKNOWN for WREM-2 (retained from legacy)
/// @note Consider removing this param (default to true) if WREM-2 works w/ it
void IRsend::sendArgo(const unsigned char data[], const uint16_t nbytes,
                      const uint16_t repeat, bool sendFooter /*= false*/) {
  if (nbytes < std::min({kArgo3AcControlStateLength,
                         kArgo3ConfigStateLength,
                         kArgo3iFeelReportStateLength,
                         kArgo3TimerStateLength,
                         kArgoStateLength,
                         kArgoShortStateLength})) {
    return;  // Insufficient bytes for valid transmission.
  }
  const uint16_t _footermark = (sendFooter)? kArgoBitMark : 0;
  const uint32_t _gap = (sendFooter)? kArgoGap : 0;
  sendGeneric(kArgoHdrMark, kArgoHdrSpace, kArgoBitMark, kArgoOneSpace,
              kArgoBitMark, kArgoZeroSpace,
              _footermark, _gap,
              data, nbytes, kArgoFrequency, false, repeat, kDutyDefault);
}

/// Send an Argo A/C formatted message (WREM-3 variant).
/// Status: Confirmed operational with Argo 13 ECO (WREM-3)
/// @param[in] data The message to transmit.
/// @param[in] nbytes The byte count of message to be sent.
/// @param[in] repeat How many times the command should repeat.
void IRsend::sendArgoWREM3(const unsigned char data[], const uint16_t nbytes,
                           const uint16_t repeat) {
  sendArgo(data, nbytes, repeat, true);
}
#endif  // SEND_ARGO

