/**
 * @brief Enumerated identifiers for tensor mapping in variant_pack.
 */
enum TensorUIDs {
    QUERY_ID,         // Q
    KEY_ID,           // K
    VALUE_ID,         // V
    SCALE_ID,         // 1/sqrt(head_dim)
    OUTPUT_ID,        // O
    STATS_ID,         // Forward stats for backward
    GRAD_OUTPUT_ID,   // dO
    GRAD_Q_ID,        // dQ
    GRAD_K_ID,        // dK
    GRAD_V_ID         // dV
};

// Cache types for forward/backward graphs
using fwd_cache_map = std::map<std::tuple<int,int,int,int,int,int>, std::shared_ptr<fe::graph::Graph>>;
using bwd_cache_map = std::map<std::tuple<int,int,int,int,int>, std::shared_ptr<fe::graph::Graph>>;

/**
 * @brief Fetches or constructs a cached forward SDPA graph.
 *
 * Builds a causal-masked scaled dot-product attention graph for the forward pass.
 * Input layout: QKV interleaved as (B, S, Nq + 2*Nkv, Dh).
 * Output layout: O as (B, S, Nq, Dh), stats as (B, Nq, S, 1) if needed.
 */
auto get_or_build_fwd_graph(int batch, int n_query, int n_keyval, int sequence_length, int head_size, bool inference_only, cudnnHandle_t context) {
    thread_local fwd_cache_map local_fwd_cache;
    auto key = std::make_tuple(batch, n_query, n_keyval, sequence_length, head_size, inference_only);
    auto found = local_fwd_cache.find(key);
    if (found != local_fwd_cache.end()) {
        return found->second;
    }

    auto graph_ptr = std::make_shared<fe::graph::Graph>();
    graph_ptr->set_io_data_type(fe::DataType_t::BFLOAT16)
              .set_intermediate_data_type(fe::DataType_t::FLOAT)
              .set_compute_data_type(fe::DataType_t::FLOAT);

    int total_heads = n_query + 2 * n_keyval;
    auto Q_tensor = graph_ptr->tensor(fe::graph::Tensor_attributes().set_name("Q_tensor")
                                         .set_dim({batch, n_query, sequence_length, head_size})
                                         .set_uid(QUERY_ID)
                                         .set_stride({total_heads * head_size * sequence_length, head_size, total_heads * head_size, 1}));
    auto K_tensor = graph_ptr->tensor(fe::graph::Tensor_attributes().set_name("K_tensor")
                                         .set_dim({batch, n_keyval, sequence_length, head_size})
                                         .set_uid(KEY_ID)
                                         .set_stride({total_heads * head_size * sequence_length, head_size, total_heads * head_size, 1}));
    auto V_tensor = graph_ptr->tensor(fe::graph::Tensor_attributes().set_name("V_tensor")
                                         .set_dim({batch, n_keyval, sequence_length, head_size})
                                         .set_uid(VALUE_ID)
                                         .set_stride({total_heads * head_size * sequence_length, head_size, total_heads * head_size, 1}));
    auto scale_tensor = graph_ptr->tensor(fe::graph::Tensor_attributes().set_name("scale_factor")
                                             .set_dim({1,1,1,1})
                                             .set_stride({1,1,1,1})
                                             .set_uid(SCALE_ID)
                                             .set_is_pass_by_value(true)
                                             .set_data_type(fe::DataType_t::FLOAT));

    auto sdpa_attr = fe::graph::SDPA_attributes().set_name("flash_sdpa_fwd");
    sdpa_attr.set_is_inference(inference_only);
    sdpa_attr.set_attn_scale(scale_tensor);
    sdpa_attr.set_causal_mask(true);

    auto [output_tensor, stats_tensor] = graph_ptr->sdpa(Q_tensor, K_tensor, V_tensor, sdpa_attr);

    output_tensor->set_output(true)
                  .set_dim({batch, n_query, sequence_length, head_size})
                  .set_stride({n_query * head_size * sequence_length, head_size, n_query * head_size, 1})
                  .set_uid(OUTPUT_ID);

    if (!inference_only) {
        stats_tensor->set_output(true)
                     .set_data_type(fe::DataType_t::FLOAT)
                     .set_dim({batch, n_query, sequence_length, 1})
                     .set_stride({n_query * sequence_length, sequence_length, 1, 1})
                     .set_uid(STATS_ID);
    }

    FE_ASSERT_OK(graph_ptr->validate());
    FE_ASSERT_OK(graph_ptr->build_operation_graph(context));
    auto plan_list = graph_ptr->create_execution_plans({fe::HeurMode_t::A});
    FE_ASSERT_OK(graph_ptr->check_support(context));
    FE_ASSERT_OK(graph_ptr->build_plans(context));

    local_fwd_cache.emplace(key, graph_ptr);
    return graph_ptr;
}

/**
 * @brief Retrieves or builds a cached backward SDPA graph.
 *
 * Computes gradients w.r.t. Q, K, V using causal masking and optional deterministic mode.
 */
auto get_or_build_bwd_graph(int batch, int n_query, int n_keyval, int sequence_length, int head_size, cudnnHandle_t context) {
    thread_local bwd_cache_map local_bwd_cache;
    auto key = std::make_tuple(batch, n_query, n_keyval, sequence_length, head_size);
    auto it = local_bwd_cache.find(key);
    if (it != local_bwd_cache.end()) {
        return it->second;
    }

    auto graph = std::make_shared<fe::graph::Graph>();
    graph->set_io_data_type(fe::DataType_t::BFLOAT16)
          .set_intermediate_data_type(fe::DataType_t::FLOAT)
          .set_compute_data_type(fe::DataType_t::FLOAT);

    int total_heads = n_query + 2 * n_keyval;

    auto Q = graph->tensor(fe::graph::Tensor_attributes().set_name("Q_grad")
                              .set_dim({batch, n_query, sequence_length, head_size})
                              .set_uid(QUERY_ID)
                              .set_stride({total_heads * head_size * sequence_length, head_size, total_heads * head_size, 1}));
    auto K = graph->tensor(fe::graph::Tensor_attributes().set_name("K_grad")
                              .set_dim({batch, n_keyval, sequence_length, head_size})
                              .set_uid(KEY_ID)
                              .set_stride({total_heads * head_size * sequence_length, head_size, total_heads * head_size, 1}));
    auto V = graph->tensor(fe::graph::Tensor_attributes().set_name("V_grad")
                              .set_dim({batch, n_keyval, sequence_length, head_size})
                              .set_uid(VALUE_ID)
                              .set_stride({total_heads * head_size * sequence_length, head_size, total_heads * head_size, 1}));
    auto O = graph->tensor(fe::graph::Tensor_attributes().set_name("O_grad")
                              .set_dim({batch, n_query, sequence_length, head_size})
                              .set_uid(OUTPUT_ID)
                              .set_stride({n_query * head_size * sequence_length, head_size, n_query * head_size, 1}));
    auto dO = graph->tensor(fe::graph::Tensor_attributes().set_name("dO_grad")
                              .set_dim({batch, n_query, sequence_length, head_size})
                              .set_uid(GRAD_OUTPUT_ID)
                              .set_stride({n_query * head_size * sequence_length, head_size, n_query * head_size, 1}));
    auto stats = graph->tensor(fe::graph::Tensor_attributes().set_name("stats_grad")
                                  .set_dim({batch, n_query, sequence_length, 1})
                                  .set_uid(STATS_ID)
                                  .set_stride({n_query * sequence_length, sequence_length, 1, 1})
                                  .set_data_type(fe::DataType_t::FLOAT));
    auto scale = graph->tensor(fe::graph::Tensor_attributes().set_name("scale_grad")
                                  .set_dim({1,1,1,1})
                                  .set_stride({1,1,1,1})
                                  .set_uid(SCALE_ID)
                                  .set_is_pass_by_value(true)
                                  .set_data_type(fe::DataType_t::FLOAT));

    bool use_deterministic = false;
#if CUDNN_FRONTEND_MAJOR_VERSION > 1 || CUDNN_FRONTEND_MINOR_VERSION >= 5
    {
        int dev_id;
        cudaGetDevice(&dev_id);
        cudaDeviceProp props;
        cudaGetDeviceProperties(&props, dev_id);
        int sm_ver = props.major * 10 + props.minor;
        size_t cudnn_v = cudnnGetVersion();
        if (sm_ver < 100 || cudnn_v >= 91800) {
            use_deterministic = true;
        }
    }
#endif

    auto bwd_attrs = fe::graph::SDPA_backward_attributes().set_name("flash_sdpa_bwd")
#if CUDNN_FRONTEND_MAJOR_VERSION > 1 || CUDNN_FRONTEND_MINOR_VERSION >= 5
                        .set_deterministic_algorithm(use_deterministic)
#endif
                        .set_causal_mask(true)
                        .set_attn_scale(scale);

    auto [dQ, dK, dV] = graph->sdpa_backward(Q, K, V, O, dO, stats, bwd_attrs);

    dQ->set_output(true).set_dim({batch, n_query, sequence_length, head_size}).set_stride({total_heads * head_size * sequence_length, head_size, total_heads * head_size, 1}).set_uid(GRAD_Q_ID);
    dK->set_output(true).set_dim({batch, n_keyval, sequence_length, head_size}).set_stride({total_heads * head_size * sequence_length, head_size, total_heads * head_size, 1}).set_uid(GRAD_K_ID);
    dV->set_output(true).set_dim({batch, n_keyval, sequence_length, head_size}).set_stride({total_heads * head_size * sequence_length, head_size, total_heads * head_size, 1}).set_uid(GRAD_V_ID);

    FE_ASSERT_OK(graph->validate());
    FE_ASSERT_OK(graph->build_operation_graph(context));
    auto plans = graph->create_execution_plans({fe::HeurMode_t::A});
    FE_ASSERT_OK(graph->check_support(context));
    FE_ASSERT_OK(graph->build_plans(context));

    local_bwd_cache.emplace(key, graph);
    return graph;
}

/**
 * @brief Executes the forward attention kernel via cuDNN.
 */
void forward_attention_kernel(nv_bfloat16* out,
                              float* stats_buffer,
                              const nv_bfloat16* qkv_input,
                              std::byte* scratchpad,
                              cudnnHandle_t handle,
                              int batch, int seq_len, int n_query, int n_keyval, int head_dim,
                              cudaStream_t stream) {
    bool inference_mode = (stats_buffer == nullptr);
    CUDNN_ERR_CHECK(cudnnSetStream(handle, stream));

    auto graph = get_or_build_fwd_graph(batch, n_query, n_keyval, seq_len, head_dim, inference_mode, handle);

    const void* ptrQ = static_cast<const void*>(qkv_input);
    const void* ptrK = static_cast<const void*>(qkv_input + n_query * head_dim);
    const void* ptrV = static_cast<const void*>(qkv_input + (n_query + n_keyval) * head_dim);

    float scale_val = 1.0f / static_cast<float>(std::sqrt(static_cast<double>(head_dim)));
    void* ptrO = static_cast<void*>(out);

    std::unordered_map<int64_t, void*> variant_map = {
        {QUERY_ID, const_cast<void*>(ptrQ)},
        {KEY_ID, const_cast<void*>(ptrK)},
        {VALUE_ID, const_cast<void*>(ptrV)},
        {SCALE_ID, &scale_val},
        {OUTPUT_ID, ptrO}
    };

    if (!inference_mode) {
        variant_map[STATS_ID] = stats_buffer;
    }

    FE_ASSERT_OK(graph->execute(handle, variant_map, scratchpad));
    CUDA_CHECK(cudaGetLastError());
}

/**
 * @brief Executes the backward attention kernel via cuDNN.
 */
void backward_attention_kernel(nv_bfloat16* grad_qkv,
                               const float* stats,
                               const nv_bfloat16* out,
                               const nv_bfloat16* grad_out,
                               const nv_bfloat16* qkv,
                               std::byte* scratchpad,
                               cudnnHandle_t handle,
                               int batch, int seq_len, int n_query, int n_keyval, int head_dim,
                               cudaStream_t stream) {
    auto graph = get_or_build_bwd_graph(batch, n_query, n_keyval, seq_len, head_dim, handle);

    void* ptrQ = const_cast<void*>(static_cast<const void*>(qkv));
    void* ptrK = const_cast<void*>(static_cast<const void*>(qkv + n_query * head_dim));
    void* ptrV = const_cast<void*>(static_cast<const void*>(qkv + (n_query + n_keyval) * head_dim));
    void* ptrO = const_cast<void*>(static_cast<const void*>(out));
    void* ptrdO = const_cast<void*>(static_cast<const void*>(grad_out));
    void* ptrStats = const_cast<void*>(static_cast<const void*>(stats));
    float scale_val = 1.0f / static_cast<float>(std::sqrt(static_cast<double>(head_dim)));

    void* ptrdQ = grad_qkv;
    void* ptrdK = grad_qkv + n_query * head_dim;
    void* ptrdV = grad_qkv + (n_query + n_keyval) * head_dim;

    std::unordered_map<int64_t, void*> variant_map = {
        {QUERY_ID, ptrQ}, {KEY_ID, ptrK}, {VALUE_ID, ptrV},
        {OUTPUT_ID, ptrO}, {GRAD_OUTPUT_ID, ptrdO}, {STATS_ID, ptrStats},
        {GRAD_Q_ID, ptrdQ}, {GRAD_K_ID, ptrdK}, {GRAD_V_ID, ptrdV},
        {SCALE_ID, &scale_val}
    };

    CUDNN_ERR_CHECK(cudnnSetStream(handle, stream));
    FE_ASSERT_OK(graph->execute(handle, variant_map, scratchpad));
    CUDA_CHECK(cudaGetLastError());
}

/**
 * @brief Returns the workspace size needed for attention ops.
 */
std::size_t get_workspace_bytes(int batch, int seq_len, int n_query, int n_keyval, int head_dim, cudnnHandle_t handle) {
    auto graph = get_or_build_bwd_graph(batch, n_query, n_keyval, seq_len, head_dim, handle);
    return graph->get_workspace_size();
}

/**
 * @brief Initializes and returns a new cuDNN handle.
 */
cudnnHandle_t initialize_cudnn_handle() {
    cudnnHandle_t handle;
    CUDNN_ERR_CHECK(cudnnCreate(&handle));
    return handle;
}

/**
 * @brief Safely destroys a cuDNN handle.
 */
void release_cudnn_handle(cudnnHandle_t handle) noexcept {
    if (handle) {
        (void)cudnnDestroy(handle);
    }
}

