upb_CType to_fieldtype(upb_FieldType type) {
  switch (type) {
#define CASE(descriptor_type, ctype)           \
  case kUpb_FieldType_##descriptor_type: \
    return kUpb_CType_##ctype;
  CASE(Float,    Float);
  CASE(Double,   Double);
  CASE(Bool,     Bool);
  CASE(String,   String);
  CASE(Bytes,    Bytes);
