using namespace llvm;

namespace {
  struct CrashRecoveryContextImpl;
  static LLVM_THREAD_LOCAL const CrashRecoveryContextImpl *ActiveContext;

  struct CrashRecoveryContextImpl {
    // When threading is off, this links all active instances.
    // With threads enabled, each thread has its own instance,
    // so this pointer remains null.
    const CrashRecoveryContextImpl *Link;
    CrashRecoveryContext *Handler;
    ::jmp_buf RecoveryBuffer;
    volatile unsigned Errored : 1;
    unsigned ThreadSwitched : 1;
    unsigned BufferValid : 1;

  public:
    CrashRecoveryContextImpl(CrashRecoveryContext *CRC) noexcept
        : Handler(CRC), Errored(false), ThreadSwitched(false), BufferValid(false) {
      Link = ActiveContext;
      ActiveContext = this;
    }

    ~CrashRecoveryContextImpl() {
      if (!ThreadSwitched)
        ActiveContext = Link;
    }

    void markThreadSwitched() {
#if defined(LLVM_ENABLE_THREADS) && LLVM_ENABLE_THREADS != 0
      ThreadSwitched = true;
#endif
    }

    void processCrash(int ExitCode, uintptr_t Info) {
      ActiveContext = Link;
      assert(!Errored && "Recovery context already triggered!");
      Errored = true;

      if (Handler->DumpStackOnCrash)
        sys::CleanupOnSignal(Info);

      Handler->ErrorCode = ExitCode;

      if (BufferValid)
        longjmp(RecoveryBuffer, 1);
    }
  };

  std::mutex &getRecoveryMutex() {
    static std::mutex MutexInstance;
    return MutexInstance;
  }

  static bool gRecoveryEnabled = false;
  static LLVM_THREAD_LOCAL const CrashRecoveryContext *IsInRecoveryMode;
}

static void setupSignalHandlers();
static void removeSignalHandlers();

CrashRecoveryContextCleanup::~CrashRecoveryContextCleanup() = default;

CrashRecoveryContext::CrashRecoveryContext() {
  sys::DisableSystemDialogsOnCrash();
}

CrashRecoveryContext::~CrashRecoveryContext() {
  CrashRecoveryContextCleanup *node = head;
  const CrashRecoveryContext *PrevRecovery = IsInRecoveryMode;
  IsInRecoveryMode = this;

  while (node) {
    CrashRecoveryContextCleanup *current = node;
    node = current->nextNode;
    current->cleanupExecuted = true;
    current->recoverResources();
    delete current;
  }

  IsInRecoveryMode = PrevRecovery;

  CrashRecoveryContextImpl *impl = (CrashRecoveryContextImpl *)Implementation;
  delete impl;
}

bool CrashRecoveryContext::isRecovering() {
  return IsInRecoveryMode != nullptr;
}

CrashRecoveryContext *CrashRecoveryContext::getCurrent() {
  if (!gRecoveryEnabled)
    return nullptr;

  const CrashRecoveryContextImpl *ctx = ActiveContext;
  if (!ctx)
    return nullptr;

  return ctx->Handler;
}

void CrashRecoveryContext::activate() {
  std::lock_guard<std::mutex> guard(getRecoveryMutex());
  if (gRecoveryEnabled)
    return;

  gRecoveryEnabled = true;
  setupSignalHandlers();
}

void CrashRecoveryContext::deactivate() {
  std::lock_guard<std::mutex> guard(getRecoveryMutex());
  if (!gRecoveryEnabled)
    return;

  gRecoveryEnabled = false;
  removeSignalHandlers();
}

void CrashRecoveryContext::registerCleanup(CrashRecoveryContextCleanup *cleanup) {
  if (!cleanup)
    return;

  if (head)
    head->prevNode = cleanup;

  cleanup->nextNode = head;
  head = cleanup;
}

void CrashRecoveryContext::unregisterCleanup(CrashRecoveryContextCleanup *cleanup) {
  if (!cleanup)
    return;

  if (cleanup == head) {
    head = cleanup->nextNode;
    if (head)
      head->prevNode = nullptr;
  } else {
    cleanup->prevNode->nextNode = cleanup->nextNode;
    if (cleanup->nextNode)
      cleanup->nextNode->prevNode = cleanup->prevNode;
  }

  delete cleanup;
}

