static int exceptionFilter(_EXCEPTION_POINTERS *info) {
  const CrashRecoveryContextImpl *ctx = ActiveContext;
  if (!ctx) {
    CrashRecoveryContext::deactivate();
    return EXCEPTION_CONTINUE_SEARCH;
  }

  int code = (int)info->ExceptionRecord->ExceptionCode;
  if ((code & 0xF0000000) == 0xE0000000)
    code &= ~0xF0000000;

  const_cast<CrashRecoveryContextImpl *>(ctx)->processCrash(
      code, reinterpret_cast<uintptr_t>(info));

  return EXCEPTION_EXECUTE_HANDLER;
}

