bool CrashRecoveryContext::runSafely(function_ref<void()> func) {
  if (!gRecoveryEnabled) {
    func();
    return true;
  }

  assert(!Implementation && "Context already initialized!");
  Implementation = new CrashRecoveryContextImpl(this);

  __try {
    func();
  } __except (exceptionFilter(GetExceptionInformation())) {
    return false;
  }

  return true;
}
