static LONG CALLBACK exceptionHandler(PEXCEPTION_POINTERS info) {
  constexpr ULONG DbgPrintExceptionWideC = 0x4001000AL;

  switch (info->ExceptionRecord->ExceptionCode) {
  case DBG_PRINTEXCEPTION_C:
  case DbgPrintExceptionWideC:
  case 0x406D1388:
    return EXCEPTION_CONTINUE_EXECUTION;
  }

  const CrashRecoveryContextImpl *ctx = ActiveContext;
  if (!ctx) {
    CrashRecoveryContext::deactivate();
    return EXCEPTION_CONTINUE_SEARCH;
  }

  int code = (int)info->ExceptionRecord->ExceptionCode;
  if ((code & 0xF0000000) == 0xE0000000)
    code &= ~0xF0000000;

  const_cast<CrashRecoveryContextImpl *>(ctx)->processCrash(
      code, reinterpret_cast<uintptr_t>(info));

  llvm_unreachable("Should have jumped out via longjmp");
}

