#include <signal.h>

static const int SignalList[] =
    { SIGABRT, SIGBUS, SIGFPE, SIGILL, SIGSEGV, SIGTRAP };
static const unsigned SignalCount = std::size(SignalList);
static struct sigaction OldActions[SignalCount];

static void signalHandler(int sig) {
  const CrashRecoveryContextImpl *ctx = ActiveContext;
  if (!ctx) {
    CrashRecoveryContext::deactivate();
    raise(sig);
    return;
  }

  sigset_t mask;
  sigemptyset(&mask);
  sigaddset(&mask, sig);
  sigprocmask(SIG_UNBLOCK, &mask, nullptr);

  int code = 128 + sig;
  if (sig == SIGPIPE)
    code = EX_IOERR;

  const_cast<CrashRecoveryContextImpl *>(ctx)->processCrash(code, sig);
}

static void setupSignalHandlers() {
  struct sigaction action;
  action.sa_handler = signalHandler;
  action.sa_flags = 0;
  sigemptyset(&action.sa_mask);

  for (unsigned i = 0; i < SignalCount; ++i)
    sigaction(SignalList[i], &action, &OldActions[i]);
}

static void removeSignalHandlers() {
  for (unsigned i = 0; i < SignalCount; ++i)
    sigaction(SignalList[i], &OldActions[i], nullptr);
}

