bool CrashRecoveryContext::runSafely(function_ref<void()> func) {
  if (gRecoveryEnabled) {
    assert(!Implementation && "Context already initialized!");
    CrashRecoveryContextImpl *ctx = new CrashRecoveryContextImpl(this);
    Implementation = ctx;
    ctx->BufferValid = true;

    if (setjmp(ctx->RecoveryBuffer) != 0)
      return false;
  }

  func();
  return true;
}

