[[noreturn]] void CrashRecoveryContext::handleExit(int code) {
#if defined(_WIN32)
  ::RaiseException(0xE0000000 | code, 0, 0, NULL);
#else
  CrashRecoveryContextImpl *ctx = (CrashRecoveryContextImpl *)Implementation;
  assert(ctx && "Context not initialized!");
  ctx->processCrash(code, 0);
#endif
  llvm_unreachable("Expected setjmp to be called!");
}

bool CrashRecoveryContext::isCrashError(int code) {
#if defined(_WIN32)
  unsigned severity = ((unsigned)code & 0xF0000000) >> 28;
  if (severity != 0xC && severity != 8)
    return false;
#else
  if (code <= 128)
    return false;
#endif
  return true;
}

bool CrashRecoveryContext::throwIfCrashError(int code) {
  if (!isCrashError(code))
    return false;

#if defined(_WIN32)
  ::RaiseException(code, 0, 0, NULL);
#else
  llvm::sys::unregisterHandlers();
  raise(code - 128);
#endif
  return true;
}

static void setThreadBackgroundPriority() {
#ifdef __APPLE__
  setpriority(PRIO_DARWIN_THREAD, 0, PRIO_DARWIN_BG);
#endif
}

static bool hasBackgroundPriority() {
#ifdef __APPLE__
  return getpriority(PRIO_DARWIN_THREAD, 0) == 1;
#else
  return false;
#endif
}

namespace {
struct ThreadTaskData {
  function_ref<void()> Task;
  CrashRecoveryContext *Context;
  bool UseBackgroundPriority;
  bool ExecutionResult;
};
}

static void executeTask(void *userData) {
  ThreadTaskData *data = reinterpret_cast<ThreadTaskData*>(userData);
  if (data->UseBackgroundPriority)
    setThreadBackgroundPriority();

  data->ExecutionResult = data->Context->runSafely(data->Task);
}

bool CrashRecoveryContext::runSafelyOnThread(function_ref<void()> task,
                                             unsigned stackSize) {
  bool useBg = hasBackgroundPriority();
  ThreadTaskData info = { task, this, useBg, false };

  llvm::thread worker(stackSize == 0
                          ? std::nullopt
                          : std::optional<unsigned>(stackSize),
                      executeTask, &info);

  worker.join();

  if (CrashRecoveryContextImpl *ctx = (CrashRecoveryContextImpl *)Implementation)
    ctx->markThreadSwitched();

  return info.ExecutionResult;
}

