int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int count;
    if (!(cin >> count)) return 0;

    const long double PI = acosl(-1.0L);
    const long double angle_step = PI * (3.0L - sqrtl(5.0L)); // Golden angle in radians

    vector<array<long double, 3>> points;
    points.reserve(count);

    for (int idx = 0; idx < count; ++idx) {
        long double z_coord = 1.0L - 2.0L * ((idx + 0.5L) / (long double)count);
        long double radius = sqrtl(max(0.0L, 1.0L - z_coord * z_coord));
        long double azimuth = angle_step * idx;
        long double x_coord = radius * cosl(azimuth);
        long double y_coord = radius * sinl(azimuth);

        long double magnitude = sqrtl(x_coord * x_coord + y_coord * y_coord + z_coord * z_coord);
        if (magnitude > 0) {
            x_coord /= magnitude;
            y_coord /= magnitude;
            z_coord /= magnitude;
        }

        points.push_back({x_coord, y_coord, z_coord});
    }

    long double min_squared_dist = numeric_limits<long double>::infinity();
    for (int i = 0; i < count; ++i) {
        for (int j = i + 1; j < count; ++j) {
            long double diff_x = points[i][0] - points[j][0];
            long double diff_y = points[i][1] - points[j][1];
            long double diff_z = points[i][2] - points[j][2];
            long double squared_dist = diff_x * diff_x + diff_y * diff_y + diff_z * diff_z;

            if (squared_dist < min_squared_dist) {
                min_squared_dist = squared_dist;
            }
        }
    }

    long double min_distance = sqrtl(min_squared_dist);

    cout.setf(std::ios::fixed);
    cout << setprecision(12) << (double)min_distance << "\n";

    for (int i = 0; i < count; ++i) {
        cout << setprecision(12)
             << (double)points[i][0] << " "
             << (double)points[i][1] << " "
             << (double)points[i][2] << "\n";
    }

    return 0;
}

