// Structure to represent an operation
struct Operation {
    int left, right, direction;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int size;
    if(!(cin >> size)) return 0;
    vector<int> array(size+1), indexMap(size+1);
    for (int idx = 1; idx <= size; ++idx) {
        cin >> array[idx];
        indexMap[array[idx]] = idx;
    }
    int constantVal = 2;
    vector<Operation> operations;
    operations.reserve(size * size / 2);
    for (int target = 1; target <= size; ++target) {
        int currentPos = indexMap[target];
        while (currentPos > target) {
            // Perform swap by shifting left on [currentPos-1, currentPos]
            operations.push_back({currentPos-1, currentPos, 0});
            int val1 = array[currentPos-1], val2 = array[currentPos];
            swap(array[currentPos-1], array[currentPos]);
            indexMap[val1] = currentPos;
            indexMap[val2] = currentPos-1;
            --currentPos;
        }
    }
    cout << constantVal << " " << operations.size() << "\n";
    for (auto &op : operations) {
        cout << op.left << " " << op.right << " " << op.direction << "\n";
    }
    return 0;
}

