  /**
   * \brief Ensure correct rank assignment per device using ncclCommSplit.
   * ******************************************************************************************/
  TEST(Standalone, SplitComms_RankCheck_Variant)
  {
    int totalDevices;
    HIPCALL(hipGetDeviceCount(&totalDevices));
    if (totalDevices < 2) {
      GTEST_SKIP() << "This test requires at least two GPU units.";
    }

    std::vector<ncclComm_t> originalComms(totalDevices);
    NCCLCHECK(ncclCommInitAll(originalComms.data(), totalDevices, nullptr));

    std::vector<ncclComm_t> partitionedComms(totalDevices);
    int numPartitions = 2;
    std::map<int, int> partitionCounts;

    NCCLCHECK(ncclGroupStart());
    for (int localIdx = 0; localIdx < totalDevices; ++localIdx) {
      int color = localIdx % numPartitions;
      NCCLCHECK(ncclCommSplit(originalComms[localIdx], color, localIdx, &partitionedComms[localIdx], NULL));
      partitionCounts[color]++;
    }
    NCCLCHECK(ncclGroupEnd());

    for (int idx = 0; idx < totalDevices; ++idx) {
      int subRank, subSize;
      NCCLCHECK(ncclCommUserRank(partitionedComms[idx], &subRank));
      NCCLCHECK(ncclCommCount(partitionedComms[idx], &subSize));
      ASSERT_EQ(subRank, idx / numPartitions);
      ASSERT_EQ(subSize, partitionCounts[idx % numPartitions]);
    }

    for (auto& comm : partitionedComms)
      NCCLCHECK(ncclCommDestroy(comm));
    for (auto& comm : originalComms)
      NCCLCHECK(ncclCommDestroy(comm));
  }

