  /**
   * \brief Reduce number of ranks to half via ncclCommSplit.
   * ******************************************************************************************/
  TEST(Standalone, SplitComms_HalfReduction)
  {
    int devCount;
    HIPCALL(hipGetDeviceCount(&devCount));
    if (devCount < 2) {
      GTEST_SKIP() << "This test needs at least two devices.";
    }

    std::vector<ncclComm_t> initComms(devCount);
    NCCLCHECK(ncclCommInitAll(initComms.data(), devCount, nullptr));

    int targetRanks = devCount / 2;
    std::vector<ncclComm_t> reducedComms(devCount);

    NCCLCHECK(ncclGroupStart());
    for (int r = 0; r < devCount; ++r) {
      int color = (r < targetRanks) ? 0 : NCCL_SPLIT_NOCOLOR;
      NCCLCHECK(ncclCommSplit(initComms[r], color, r, &reducedComms[r], NULL));
    }
    NCCLCHECK(ncclGroupEnd());

    for (int i = 0; i < devCount; ++i) {
      int origRank, origSize;
      NCCLCHECK(ncclCommUserRank(initComms[i], &origRank));
      NCCLCHECK(ncclCommCount(initComms[i], &origSize));
      if (i < targetRanks) {
        int newRank, newSize;
        NCCLCHECK(ncclCommUserRank(reducedComms[i], &newRank));
        NCCLCHECK(ncclCommCount(reducedComms[i], &newSize));
        ASSERT_EQ(origRank, newRank);
        ASSERT_EQ(newSize, targetRanks);
      } else {
        ASSERT_EQ(reducedComms[i], nullptr);
      }
    }

    for (auto& c : reducedComms)
      NCCLCHECK(ncclCommDestroy(c));
    for (auto& c : initComms)
      NCCLCHECK(ncclCommDestroy(c));
  }

  /**
   * \brief Measure timing consistency across protocols: LL, LL128, Simple.
   * ******************************************************************************************/
  TEST(Standalone, ProtocolTiming_Check)
  {
    using namespace std::chrono;
    using ClockType = high_resolution_clock;
    long long totalMicros = 0;
    const int repeatCount = 25, warmupCount = 7;

    int gpuCount;
    HIPCALL(hipGetDeviceCount(&gpuCount));
    if (gpuCount < 2) {
      GTEST_SKIP() << "Two or more GPUs needed.";
    }

    hipDeviceProp_t props;
    HIPCALL(hipGetDeviceProperties(&props, 0));

    constexpr int numNodes = 2;
    std::vector<ncclComm_t> communicators(numNodes);
    std::vector<int*> dInput(numNodes);
    std::vector<int*> dOutput(numNodes);
    std::vector<hipStream_t> streams(numNodes);

    char* savedProto = getenv("NCCL_PROTO");
    const char* protoList[3] = {"LL", "LL128", "Simple"};

    for (const auto& protoName : protoList) {
      totalMicros = 0;
      if (strncmp("gfx12", props.gcnArchName, 5) == 0) {
        setenv("NCCL_PROTO", "Simple", 1);
      } else {
        setenv("NCCL_PROTO", protoName, 1);
      }

      NCCLCHECK(ncclCommInitAll(communicators.data(), numNodes, nullptr));

      int elemCount = 1250;
      std::vector<int> hInput(elemCount);
      std::vector<int> hExpected(elemCount);
      for (int i = 0; i < elemCount; ++i) {
        hInput[i] = i;
        hExpected[i] = 2 * i;
      }

      for (int node = 0; node < numNodes; ++node) {
        HIPCALL(hipSetDevice(node));
        HIPCALL(hipStreamCreate(&streams[node]));
        HIPCALL(hipMalloc((void**)&dInput[node], elemCount * sizeof(int)));
        HIPCALL(hipMalloc((void**)&dOutput[node], elemCount * sizeof(int)));
        HIPCALL(hipMemcpy(dInput[node], hInput.data(), elemCount * sizeof(int), hipMemcpyHostToDevice));
        HIPCALL(hipMemset(dOutput[node], 0, elemCount * sizeof(int)));
        HIPCALL(hipDeviceSynchronize());
      }

      for (int rep = -warmupCount; rep < repeatCount; ++rep) {
        for (int node = 0; node < numNodes; ++node) {
          HIPCALL(hipSetDevice(node));
          HIPCALL(hipMemset(dOutput[node], 0, elemCount * sizeof(int)));
          HIPCALL(hipDeviceSynchronize());
        }

        NCCLCHECK(ncclGroupStart());
        for (int node = 0; node < numNodes; ++node)
          NCCLCHECK(ncclAllReduce(dInput[node], dOutput[node], elemCount, ncclInt, ncclSum, communicators[node], streams[node]));
        ncclResult_t res = ncclGroupEnd();
        if (res != ncclSuccess) continue;

        const auto startTime = ClockType::now();
        for (int node = 0; node < numNodes; ++node) {
          HIPCALL(hipStreamSynchronize(streams[node]));
        }

        if (rep >= 0)
          totalMicros += duration_cast<microseconds>(ClockType::now() - startTime).count();

        std::vector<int> hOutput(elemCount);
        for (int node = 0; node < numNodes; ++node) {
          HIPCALL(hipMemcpy(hOutput.data(), dOutput[node], elemCount * sizeof(int), hipMemcpyDeviceToHost));
          HIPCALL(hipDeviceSynchronize());
          for (int i = 0; i < elemCount; ++i)
            ASSERT_EQ(hOutput[i], hExpected[i]);
        }
      }

      double avgTime = static_cast<double>(totalMicros) / repeatCount;
      EXPECT_LT(avgTime, 5000.0);
      printf("[ INFO     ] protocol: %s, avg runtime: %f microseconds\n", protoName, avgTime);

      for (int node = 0; node < numNodes; ++node) {
        HIPCALL(hipFree(dInput[node]));
        HIPCALL(hipFree(dOutput[node]));
        HIPCALL(hipStreamDestroy(streams[node]));
        NCCLCHECK(ncclCommDestroy(communicators[node]));
      }
    }

    if (savedProto)
      setenv("NCCL_PROTO", savedProto, 1);
    else
      unsetenv("NCCL_PROTO");
  }

  /**
   * \brief Validate kernel stack usage against architecture-specific limits.
   * ******************************************************************************************/
  TEST(Standalone, KernelStackSize_Validation)
  {
    const char* kernelName = "ncclDevKernel";
    std::vector<std::string> coFiles = splitString(executeCommand("find ../ -type f -name \"librccl*.co\""), '\n');

    if (coFiles.empty())
      GTEST_SKIP() << "No .co files found in build directory.";

    for (const auto& filePath : coFiles) {
      std::string readCmd = std::string(ROCM_PATH) + "/llvm/bin/llvm-readelf --notes " + filePath;
      std::vector<std::string> notes = splitString(executeCommand(readCmd.c_str()), '\n');
      if (notes.empty())
        GTEST_SKIP() << "llvm-readelf not available.";

      ArchInfo archData = parseMetadata(notes);
      for (const auto& k : archData.kernels) {
        if (k.name.find(kernelName) != std::string::npos) {
          int stackSize = k.privateSegmentFixedSize;
          int maxAllowed = (archData.archName == "gfx90a") ? MAX_STACK_SIZE_gfx90a : MAX_STACK_SIZE;
          printf("[ INFO     ] Arch: %s Kernel: %s StackSize: %d\n", archData.archName.c_str(), k.name.c_str(), stackSize);
          EXPECT_LE(stackSize, maxAllowed);
        }
      }
    }
  }

  /**
   * \brief Confirm device binding correctness for communicators.
   * ******************************************************************************************/
  TEST(Standalone, DeviceBinding_Assertion)
  {
    int deviceCount;
    HIPCALL(hipGetDeviceCount(&deviceCount));
    if (deviceCount < 1) {
      GTEST_SKIP() << "No CUDA-capable devices detected.";
    }

    ncclComm_t singleComm;
    ncclUniqueId uniqueId;
    NCCLCHECK(ncclGetUniqueId(&uniqueId));
    HIPCALL(hipSetDevice(0));
    NCCLCHECK(ncclCommInitRank(&singleComm, 1, uniqueId, 0));

    int boundDevice;
    NCCLCHECK(ncclCommCuDevice(singleComm, &boundDevice));
    ASSERT_EQ(boundDevice, 0);
    NCCLCHECK(ncclCommDestroy(singleComm));

    if (deviceCount > 1) {
      std::vector<ncclComm_t> multiComms(deviceCount);
      NCCLCHECK(ncclCommInitAll(multiComms.data(), deviceCount, nullptr));

      for (int i = 0; i < deviceCount; ++i) {
        int assignedDev;
        NCCLCHECK(ncclCommCuDevice(multiComms[i], &assignedDev));
        ASSERT_EQ(assignedDev, i);
      }

      for (int i = 0; i < deviceCount; ++i)
        NCCLCHECK(ncclCommDestroy(multiComms[i]));
    }
  }

  /**
   * \brief Test error handling when querying rank from null communicator.
   * ******************************************************************************************/
  TEST(Standalone, NullComm_RankQuery_Failure)
  {
    int devCount;
    HIPCALL(hipGetDeviceCount(&devCount));
    if (devCount < 2) {
      GTEST_SKIP() << "Need at least two devices.";
    }

    std::vector<ncclComm_t> validComms(devCount);
    NCCLCHECK(ncclCommInitAll(validComms.data(), devCount, nullptr));

    ncclComm_t nullHandle = nullptr;
    int dummyRank;
    NCCLCHECK(ncclCommUserRank(nullHandle, &dummyRank));

    for (auto& c : validComms)
      NCCLCHECK(ncclCommDestroy(c));
  }
}

