#include <iostream>
#include <vector>
#include <algorithm>
#include <random>
#include <bitset>

using namespace std;

struct Connection {
    int from;
    int to;
    int idx;
};

int nodes, edgesCount;
vector<Connection> connections;
vector<vector<pair<int, int>>> adjacency; // node -> {neighbor, edge_index}

// Bitsets for constraint checking
bitset<10000> current_mask;
bitset<10000> candidate_nodes;
bitset<10000> full_set;

struct ExperimentResult {
    vector<int> entry_time;
    vector<int> exit_time;
    vector<int> dfs_order; // maps DFS index -> original node
    int answer;
};

vector<ExperimentResult> experiments;

void perform_random_dfs(int start_node, vector<int>& parent, vector<int>& order, vector<int>& entry, vector<int>& exit_time, mt19937& generator) {
    vector<int> stack;
    stack.push_back(start_node);

    vector<bool> visited(nodes, false);
    visited[start_node] = true;

    int timer = 0;

    struct StackFrame {
        int node;
        int next_edge;
    };
    vector<StackFrame> call_stack;

    // Pre-shuffle adjacency lists
    vector<vector<int>> shuffled_adj(nodes);
    for (int u = 0; u < nodes; ++u) {
        for (auto& p : adjacency[u]) {
            shuffled_adj[u].push_back(p.first);
        }
        shuffle(shuffled_adj[u].begin(), shuffled_adj[u].end(), generator);
    }

    call_stack.push_back({start_node, 0});
    entry[start_node] = timer++;
    order[entry[start_node]] = start_node;

    while (!call_stack.empty()) {
        StackFrame& frame = call_stack.back();
        int u = frame.node;

        if (frame.next_edge < shuffled_adj[u].size()) {
            int v = shuffled_adj[u][frame.next_edge];
            frame.next_edge++;
            if (!visited[v]) {
                visited[v] = true;
                entry[v] = timer++;
                order[entry[v]] = v;
                call_stack.push_back({v, 0});
            }
        } else {
            exit_time[u] = timer - 1;
            call_stack.pop_back();
        }
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> nodes >> edgesCount)) return 0;

    adjacency.resize(nodes);
    for (int i = 0; i < edgesCount; ++i) {
        int u, v;
        cin >> u >> v;
        connections.push_back({u, v, i});
        adjacency[u].push_back({v, i});
        adjacency[v].push_back({u, i});
    }

    mt19937 rng(2025);

    // Initialize bitset
    for (int i = 0; i < nodes; ++i) {
        full_set[i] = 1;
    }

    const int num_experiments = 250;

    vector<int> edge_direction(edgesCount); // 0: from->to, 1: to->from
    vector<int> entry_time(nodes), exit_time(nodes), dfs_order(nodes);

    for (int exp = 0; exp < num_experiments; ++exp) {
        int root = uniform_int_distribution<int>(0, nodes - 1)(rng);

        fill(entry_time.begin(), entry_time.end(), 0);
        fill(exit_time.begin(), exit_time.end(), 0);
        fill(dfs_order.begin(), dfs_order.end(), 0);

        perform_random_dfs(root, vector<int>(), dfs_order, entry_time, exit_time, rng);

        // Determine edge directions based on DFS order
        for (const auto& conn : connections) {
            if (entry_time[conn.from] < entry_time[conn.to]) {
                edge_direction[conn.idx] = 0;
            } else {
                edge_direction[conn.idx] = 1;
            }
        }

        cout << "0 ";
        for (int i = 0; i < edgesCount; ++i) {
            cout << edge_direction[i] << (i == edgesCount - 1 ? "" : " ");
        }
        cout << '\n';

        int response;
        cin >> response;
        if (response == -1) exit(0);

        ExperimentResult exp_data;
        exp_data.entry_time = entry_time;
        exp_data.exit_time = exit_time;
        exp_data.dfs_order = dfs_order;
        exp_data.answer = response;
        experiments.push_back(exp_data);
    }

    // Final solver
    int final_A = -1, final_B = -1;

    for (int candidate_A = 0; candidate_A < nodes; ++candidate_A) {
        candidate_nodes = full_set;
        candidate_nodes[candidate_A] = 0;

        bool feasible = true;

        for (const auto& exp : experiments) {
            int A_entry = exp.entry_time[candidate_A];
            int A_exit = exp.exit_time[candidate_A];
            bool must_be_in_subtree = (exp.answer == 1);

            for (int candidate_B = candidate_nodes._Find_first(); 
                 candidate_B < nodes; 
                 candidate_B = candidate_nodes._Find_next(candidate_B)) {

                int B_entry = exp.entry_time[candidate_B];
                bool in_subtree = (B_entry >= A_entry && B_entry <= A_exit);

                if (must_be_in_subtree != in_subtree) {
                    candidate_nodes[candidate_B] = 0;
                }
            }

            if (candidate_nodes.none()) {
                feasible = false;
                break;
            }
        }

        if (feasible) {
            final_A = candidate_A;
            final_B = candidate_nodes._Find_first();
            break;
        }
    }

    cout << "1 " << final_A << " " << final_B << endl;

    return 0;
}

#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
using namespace std;

// Definition of Interval: represents a meeting time slot
class Interval {
public:
    int start, end;
    Interval(int s, int e) : start(s), end(e) {}
};

class Solution {
public:
    int minMeetingRooms(vector<Interval>& meetings) {
        // Sort meetings by their start times
        sort(meetings.begin(), meetings.end(), [](const Interval& x, const Interval& y) {
            return x.start < y.start;
        });

        // Min heap to track end times of ongoing meetings
        priority_queue<int, vector<int>, greater<int>> endTimeHeap;

        for (const auto& meeting : meetings) {
            // If the earliest ending meeting has ended before this one starts, reuse that room
            if (!endTimeHeap.empty() && endTimeHeap.top() <= meeting.start) {
                endTimeHeap.pop();
            }

            // Add current meeting's end time to the heap
            endTimeHeap.push(meeting.end);
        }

        // The size of the heap is the minimum number of rooms needed
        return endTimeHeap.size();
    }
};

int main() {
    Solution solver;
    vector<Interval> schedule = {Interval(0, 30), Interval(5, 10), Interval(15, 20)};
    cout << "Minimum number of meeting rooms required: " << solver.minMeetingRooms(schedule) << endl;

    // Expected output: 2
    // Explanation: Intervals (0,30) and (5,10) overlap, requiring two rooms.
    // Interval (15,20) can use either room after one becomes free.
    return 0;
}

