#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

// Function to execute a comparison query.
// Outputs the current candidates and reads back the fastest one.
int performRace(const vector<int>& candidates) {
    cout << "?";
    for (int val : candidates) cout << " " << val;
    cout << endl;

    int winner;
    cin >> winner;
    return winner;
}

void process() {
    int size;
    // Read input size; exit if reading fails
    if (!(cin >> size)) return;

    // Build a forest where each node points to its slower peers
    // Using adjacency list representation; nodes are 1-indexed
    vector<vector<int>> slowerPeers(size * size + 1);

    // Track current top contenders (roots of trees)
    vector<int> currentTop;

    // Phase 1: Initial grouping
    // Divide all size^2 elements into 'size' groups of 'size' each
    // Race each group, promote winners as roots, attach losers under them
    int elementCounter = 1;
    for (int groupIdx = 0; groupIdx < size; ++groupIdx) {
        vector<int> groupMembers;
        for (int memberIdx = 0; memberIdx < size; ++memberIdx) {
            groupMembers.push_back(elementCounter++);
        }

        int groupWinner = performRace(groupMembers);
        currentTop.push_back(groupWinner);

        for (int member : groupMembers) {
            if (member != groupWinner) {
                slowerPeers[groupWinner].push_back(member);
            }
        }
    }

    // Target number of top elements to identify
    int neededCount = size * size - size + 1;
    vector<int> finalOrder;

    for (int step = 0; step < neededCount; ++step) {
        // Reduce candidate set to single root via repeated races
        while (currentTop.size() > 1) {
            vector<int> raceEntries;
            vector<int> activeRootsInRace;

            int pickCount = min((int)currentTop.size(), size);
            for (int i = 0; i < pickCount; ++i) {
                raceEntries.push_back(currentTop[i]);
                activeRootsInRace.push_back(currentTop[i]);
            }

            // Fill remaining slots with known slower elements (descendants)
            if (raceEntries.size() < size) {
                int fillNeeded = size - raceEntries.size();
                for (int root : activeRootsInRace) {
                    if (fillNeeded <= 0) break;

                    vector<int> bfsQueue;
                    bfsQueue.push_back(root);
                    size_t queuePos = 0;

                    while (queuePos < bfsQueue.size() && fillNeeded > 0) {
                        int node = bfsQueue[queuePos++];
                        for (int child : slowerPeers[node]) {
                            raceEntries.push_back(child);
                            fillNeeded--;
                            if (fillNeeded == 0) break;
                            bfsQueue.push_back(child);
                        }
                    }
                }
            }

            // Run the actual race
            int newWinner = performRace(raceEntries);

            // Rebuild candidate list:
            // - Keep non-participating roots
            // - Add the new winner
            // - Attach defeated roots as children of winner
            vector<int> updatedTop;

            for (size_t idx = pickCount; idx < currentTop.size(); ++idx) {
                updatedTop.push_back(currentTop[idx]);
            }

            updatedTop.push_back(newWinner);

            for (int loser : activeRootsInRace) {
                if (loser != newWinner) {
                    slowerPeers[newWinner].push_back(loser);
                }
            }

            currentTop = updatedTop;
        }

        // Current top is the next fastest overall
        int fastest = currentTop[0];
        finalOrder.push_back(fastest);

        // Promote its slower peers as new candidates
        currentTop.clear();
        for (int peer : slowerPeers[fastest]) {
            currentTop.push_back(peer);
        }
    }

    // Output final ordering
    cout << "!";
    for (int val : finalOrder) cout << " " << val;
    cout << endl;
}

int main() {
    int testCases;
    if (cin >> testCases) {
        while (testCases--) {
            process();
        }
    }
    return 0;
}

