using namespace std;

// Function to send a query and receive response from interactor
long long ask(int node, int dist) {
    if (dist <= 0) return 0;
    cout << "? " << node << " " << dist << endl;
    long long answer;
    cin >> answer;
    return answer;
}

int main() {
    int height;
    if (!(cin >> height)) return 0;

    // Total number of nodes in perfect binary tree: n = 2^height - 1
    // Goal: compute total sum of all node weights S = sum(f_v)
    // Querying distance d from node u gives sum of weights at distance d from u.
    // Summing over all d >= 1 gives Scan(u) = S - f_{parent(u)}.
    // We aim to estimate S by finding max_u Scan(u), assuming some node has small or zero weight.

    int node_count = (1 << height) - 1;
    long long best_estimate = 0;

    // Limit number of queries to stay within Q <= 3N/4 budget
    int sample_size = 400;
    if (sample_size > node_count) sample_size = node_count;

    // Perform scanning on first 'sample_size' nodes
    for (int idx = 1; idx <= sample_size; ++idx) {
        long long scan_sum = 0;
        // Maximum possible distance in tree is 2*height
        for (int distance = 1; distance <= 2 * height; ++distance) {
            scan_sum += ask(idx, distance);
        }
        if (scan_sum > best_estimate) {
            best_estimate = scan_sum;
        }
    }

    cout << "! " << best_estimate << endl;
    return 0;
}

#include "arcball.h"

double ArcBall::s_sphereRadius = 0.85;

ArcBall::ArcBall()
{
    m_Quat.a  = 0.0;
    m_Quat.qx = m_Quat.qy = m_Quat.qz = 0.0;

    // initialize the arcball with a pseudo iso viewpoint
    Quaternion qti;
    qti.fromEulerAngles(ROLL, PITCH, YAW);
    Quaternion qtyaw(-45.0, Vector3d(0.0,0.0,1.0));
    setQuat(qti * qtyaw);

    m_Start.set(0.0, 0.0, 1.0);
    m_Current.set(0.0, 0.0, 1.0);
}

void ArcBall::applyRotation(Quaternion const &rotQ, bool bInverted)
{
    if(bInverted)
        m_Quat = m_Quat * rotQ;
    else
        m_Quat = rotQ * m_Quat;
}

/** update current arcball rotation */
void ArcBall::move(double vx, double vy)
{
    getSpherePoint(vx, vy, m_Current);
    if((m_Current - m_Start).norm() < 1.e-6) return;

    // build the incremental quaternion which rotates the former vector position to the new one
    Quaternion qt;
    qt.from2UnitVectors(m_Start.normalized(), m_Current.normalized());

    // update the quat representing the view matrix
    m_Quat = qt * m_QuatStart;
}

void ArcBall::rotateCrossPoint(float &angleOut, float &xf, float &yf, float &zf)
{
    Vector3d axisRef(1.0, 0.0, 0.0);
    double cosAngle   = axisRef.dot(m_Current);
    double halfCos    = sqrt((1.0 + cosAngle) * 0.5);
    angleOut = 2.0f * acosf(float(halfCos)) * 180.0f / PIf;

    Vector3d crossVec = axisRef.cross(m_Current);
    crossVec.normalize();
    xf = crossVec.xf();
    yf = crossVec.yf();
    zf = crossVec.zf();
}

void ArcBall::setQuat(double realPart, double qx, double qy, double qz)
{
    m_Quat.a  = realPart;
    m_Quat.qx = qx;
    m_Quat.qy = qy;
    m_Quat.qz = qz;
}

void ArcBall::start(double vx, double vy)
{
    getSpherePoint(vx, vy, m_Start);
    m_Current = m_Start;
    m_QuatStart = m_Quat;
}

/** returns a unit vector to the point on the sphere's surface from the input viewport coordinates */
void ArcBall::getSpherePoint(double xv, double yv, Vector3d &Pt)
{
    double r2 = s_sphereRadius * s_sphereRadius;
    if(r2 > xv*xv + yv*yv) 
        Pt.set(xv, yv, sqrt(r2 - xv*xv - yv*yv));
    else               
        Pt.set(xv, yv, 0.0);
    Pt.normalize();
}

