HVT_TEST(TestViewportToolbox, TestFramePasses_MainOnly)
{
    // This unit test uses a frame pass to render a USD 3D model using Storm.
    auto context = TestHelpers::CreateTestContext();
    // Defines the initial frame pass.
    TestHelpers::TestStage sceneModel(context->_backend);
    ASSERT_TRUE(sceneModel.open(context->_sceneFilepath));
    // Main scene Frame Pass.
    TestHelpers::FramePassInstance renderingData =
        TestHelpers::FramePassInstance::CreateInstance(sceneModel.stage(), context->_backend);
    hvt::FramePass& framePass = *renderingData.sceneFramePass.get();
    // Render 15 times (i.e., arbitrary number to guarantee best result).
    int iterationCount = 15;
    auto executeRender = [&]()
    {
        hvt::FramePassParams& parameters = framePass.params();
        parameters.renderBufferSize = pxr::GfVec2i(context->width(), context->height());
        parameters.viewInfo.framing =
            hvt::ViewParams::GetDefaultFraming(context->width(), context->height());
        parameters.viewInfo.viewMatrix       = sceneModel.viewMatrix();
        parameters.viewInfo.projectionMatrix = sceneModel.projectionMatrix();
        parameters.viewInfo.lights           = sceneModel.defaultLights();
        parameters.viewInfo.material         = sceneModel.defaultMaterial();
        parameters.viewInfo.ambient          = sceneModel.defaultAmbient();
        parameters.colorspace      = HdxColorCorrectionTokens->sRGB;
        parameters.backgroundColor = TestHelpers::ColorDarkGrey;
        parameters.selectionColor  = TestHelpers::ColorYellow;
        parameters.enablePresentation = context->presentationEnabled();
        framePass.Render();
        // Force GPU sync. Wait for all GPU commands to complete before proceeding.
        // This ensures render operations are fully finished before the next frame
        // or validation step, preventing race conditions and ensuring consistent results.
        context->_backend->waitForGPUIdle();
        return --iterationCount > 0;
    };
    try
    {
        // Run the render loop.
        context->run(executeRender, &framePass);
        // Validate the rendering result.
        const std::string generatedImagePath = TestHelpers::getComputedImagePath();
        ASSERT_TRUE(
            context->validateImages(generatedImagePath, TestHelpers::gTestNames.fixtureName));
    }
    catch (const std::exception& ex)
    {
        FAIL() << __FILE__ << ":" << __LINE__ << ": " << ex.what() << "\n";
    }
}

