DoubleIntegratorInterface::DoubleIntegratorInterface(const std::string& configPath, const std::string& libDir, bool printInfo) {
  // Verify that the configuration file exists
  boost::filesystem::path configFile(configPath);
  if (boost::filesystem::exists(configFile)) {
    std::cerr << "[DoubleIntegratorInterface] Reading configuration from: " << configFile << std::endl;
  } else {
    throw std::invalid_argument("[DoubleIntegratorInterface] Configuration file not found: " + configFile.string());
  }

  // Ensure the library directory exists
  boost::filesystem::path libPath(libDir);
  boost::filesystem::create_directories(libPath);
  std::cerr << "[DoubleIntegratorInterface] Using library directory: " << libPath << std::endl;

  // Load default initial state and target goal
  loadData::loadEigenMatrix(configPath, "initialState", currentState_);
  loadData::loadEigenMatrix(configPath, "targetGoal", desiredGoal_);

  // Load DDP-MPC parameters
  ddpSettings_ = ddp::loadSettings(configPath, "ddp", printInfo);
  mpcSettings_ = mpc::loadSettings(configPath, "mpc", printInfo);

  /*
   * ReferenceManager & SolverSynchronizedModule
   */
  referenceManagerPtr_.reset(new ReferenceManager);

  /*
   * Optimal control problem formulation
   */
  // Define cost matrices
  matrix_t Q_matrix(STATE_DIM, STATE_DIM);
  matrix_t R_matrix(INPUT_DIM, INPUT_DIM);
  matrix_t Q_final_matrix(STATE_DIM, STATE_DIM);

  loadData::loadEigenMatrix(configPath, "Q", Q_matrix);
  loadData::loadEigenMatrix(configPath, "R", R_matrix);
  loadData::loadEigenMatrix(configPath, "Q_final", Q_final_matrix);

  std::cerr << "Q:\n" << Q_matrix << "\n";
  std::cerr << "R:\n" << R_matrix << "\n";
  std::cerr << "Q_final:\n" << Q_final_matrix << "\n";

  problem_.costPtr->add("stage_cost", std::make_unique<QuadraticStateInputCost>(Q_matrix, R_matrix));
  problem_.finalCostPtr->add("terminal_cost", std::make_unique<QuadraticStateCost>(Q_final_matrix));

  // System dynamics definition
  const matrix_t A_matrix = (matrix_t(STATE_DIM, STATE_DIM) << 0.0, 1.0, 0.0, 0.0).finished();
  const matrix_t B_matrix = (matrix_t(STATE_DIM, INPUT_DIM) << 0.0, 1.0).finished();
  problem_.dynamicsPtr.reset(new LinearSystemDynamics(A_matrix, B_matrix));

  // Set up trajectory rollout
  auto rolloutConfig = rollout::loadSettings(configPath, "rollout", printInfo);
  rolloutPtr_.reset(new TimeTriggeredRollout(*problem_.dynamicsPtr, rolloutConfig));

  // Initialize solver components
  linearSystemInitializerPtr_.reset(new DefaultInitializer(INPUT_DIM));
}

