// Count regular bracket substrings in string s
int count_valid_brackets(const string& str) {
    int len = str.size();
    int result = 0;
    for (int start = 0; start < len; ++start) {
        int balance = 0;
        for (int end = start; end < len; ++end) {
            if (str[end] == '(') balance++;
            else balance--;
            if (balance < 0) break;
            if (balance == 0) result++;
        }
    }
    return result;
}

// Generate a distinguishing pattern for m variables
// Returns a vector where -1 represents filler, 0..m-1 represent variables
vector<int> generate_pattern(int var_count) {
    while (true) {
        int pattern_length = 14 + rand() % 8; // Length between 14 and 21
        vector<int> pattern(pattern_length);
        for (int idx = 0; idx < pattern_length; ++idx) {
            if (rand() % 3 == 0) 
                pattern[idx] = -1; // filler
            else 
                pattern[idx] = rand() % var_count; // variable index
        }

        map<int, int> seen_results;
        bool valid = true;
        int total_states = 1 << var_count;

        // Test all possible assignments to variables
        for (int assignment = 0; assignment < total_states; ++assignment) {
            string constructed = "";
            for (int pos : pattern) {
                if (pos == -1) {
                    constructed += ')';
                } else {
                    if ((assignment >> pos) & 1) 
                        constructed += '(';
                    else 
                        constructed += ')';
                }
            }
            int evaluation = count_valid_brackets(constructed);
            if (seen_results.find(evaluation) != seen_results.end()) {
                valid = false;
                break;
            }
            seen_results[evaluation] = assignment;
        }

        if (valid) return pattern;
    }
}

// Send query and receive response
int send_query(const vector<int>& positions) {
    cout << "0 " << positions.size();
    for (int pos : positions) cout << " " << pos;
    cout << endl;
    int answer;
    cin >> answer;
    if (answer == -1) exit(0); // Error condition
    return answer;
}

void process_test_case(int sequence_length) {
    // Step 1: Determine first character
    bool first_is_close = false;
    vector<int> batch;

    // Batch queries for efficiency
    for (int idx = 2; idx <= sequence_length; ++idx) {
        batch.push_back(idx);
        batch.push_back(1);
        if (batch.size() >= 900 || idx == sequence_length) {
            int result = send_query(batch);
            if (result > 0) first_is_close = true;
            batch.clear();
        }
    }
    char first_char = first_is_close ? ')' : '(';

    // Step 2: Prepare pattern for 6 variables
    int num_vars = 6;
    vector<int> base_pattern = generate_pattern(num_vars);

    // Build lookup table from results to bitmasks
    map<int, int> result_to_mask;
    int total_states = 1 << num_vars;
    for (int mask = 0; mask < total_states; ++mask) {
        string test_str = "";
        for (int pos : base_pattern) {
            if (pos == -1) test_str += ')';
            else {
                if ((mask >> pos) & 1) test_str += '(';
                else test_str += ')';
            }
        }
        result_to_mask[count_valid_brackets(test_str)] = mask;
    }

    string solution(sequence_length, ' ');
    solution[0] = first_char;

    // Step 3: Process remaining characters in chunks
    for (int start = 2; start <= sequence_length; start += num_vars) {
        int chunk_size = min(num_vars, sequence_length - start + 1);
        vector<int> current_indices;
        for (int j = 0; j < chunk_size; ++j) 
            current_indices.push_back(start + j);

        // Pad with first position if needed
        while (current_indices.size() < num_vars) 
            current_indices.push_back(1);

        vector<int> query_positions;
        if (first_char == ')') {
            // Filler is ')', use pattern directly
            for (int pos : base_pattern) {
                if (pos == -1) query_positions.push_back(1);
                else query_positions.push_back(current_indices[pos]);
            }
        } else {
            // Filler is '(', use reversed pattern
            vector<int> reversed_pattern = base_pattern;
            reverse(reversed_pattern.begin(), reversed_pattern.end());
            for (int pos : reversed_pattern) {
                if (pos == -1) query_positions.push_back(1);
                else query_positions.push_back(current_indices[pos]);
            }
        }

        int query_result = send_query(query_positions);
        int bitmask = result_to_mask[query_result];

        for (int j = 0; j < chunk_size; ++j) {
            int bit_value = (bitmask >> j) & 1;
            char character;
            if (first_char == ')') {
                // Bit 1 means '('
                character = (bit_value ? '(' : ')');
            } else {
                // Bit 1 means ')'
                character = (bit_value ? ')' : '(');
            }
            solution[start + j - 1] = character;
        }
    }

    cout << "1 " << solution << endl;
}

int main() {
    srand(1337); 
    int n;
    while (cin >> n) {
        process_test_case(n);
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int size;
vector<vector<int>> graph;
vector<int> indegree;

bool compare(int x, int y) {
    cout << "? " << x << " " << y << endl;
    char response;
    cin >> response;
    return response == '<';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    cin >> size;
    graph.resize(size + 1);
    indegree.assign(size + 1, 0);

    // Build edges between consecutive elements
    for (int i = 1; i < size; ++i) {
        if (compare(i, i + 1)) {
            graph[i].push_back(i + 1);
            ++indegree[i + 1];
        } else {
            graph[i + 1].push_back(i);
            ++indegree[i];
        }
    }

    // Build edges between elements with gap of 2 (for odd indices)
    for (int i = 1; i <= size - 2; i += 2) {
        if (compare(i, i + 2)) {
            graph[i].push_back(i + 2);
            ++indegree[i + 2];
        } else {
            graph[i + 2].push_back(i);
            ++indegree[i];
        }
    }

    // Topological sort using min-heap for lexicographically smallest order
    vector<int> topo_order;
    priority_queue<int, vector<int>, greater<int>> min_heap;

    for (int node = 1; node <= size; ++node) {
        if (indegree[node] == 0) {
            min_heap.push(node);
        }
    }

    while (!min_heap.empty()) {
        int current = min_heap.top();
        min_heap.pop();
        topo_order.push_back(current);

        for (int neighbor : graph[current]) {
            if (--indegree[neighbor] == 0) {
                min_heap.push(neighbor);
            }
        }
    }

    // Assign values according to topological order
    vector<int> result(size + 1);
    int current_value = 1;
    for (int position : topo_order) {
        result[position] = current_value++;
    }

    cout << "!";
    for (int i = 1; i <= size; ++i) {
        cout << " " << result[i];
    }
    cout << endl;

    return 0;
}

