void freeaddrinfo(struct addrinfo *node)
{
    size_t count;
    for (count = 0; node != NULL; count++, node = node->ai_next);

    struct aibuf *buf = (struct aibuf *)((char *)node - offsetof(struct aibuf, ai));
    buf -= buf->slot;

    LOCK(buf->lock);
    if (!(buf->ref -= count)) {
        free(buf);
    } else {
        UNLOCK(buf->lock);
    }
}

