#include <bits/stdc++.h>
using namespace std;
typedef vector<int> Perm;

struct SearchState {
    Perm arrangement;
    int op1, op2; // operation parameters used to reach this state
    int parent;   // index of predecessor state in BFS queue
};

// Apply transformation (a,b) to permutation arr
Perm transform(const Perm& arr, int a, int b) {
    int len = arr.size();
    Perm result(len);

    // Take last b elements and put them at the beginning
    for (int i = 0; i < b; i++) {
        result[i] = arr[len - b + i];
    }

    // Middle section: from index a to len-b-1
    for (int i = 0; i < len - a - b; i++) {
        result[b + i] = arr[a + i];
    }

    // Remaining first a elements go to the end
    for (int i = 0; i < a; i++) {
        result[len - a + i] = arr[i];
    }

    return result;
}

// BFS solver for small n (n <= 9)
pair<Perm, vector<pair<int,int>>> solve_bfs(const Perm& initial, int limit) {
    int size = initial.size();
    map<Perm, SearchState> seen;
    queue<int> bfs_queue;
    vector<SearchState> all_states;

    // Initialize starting state
    all_states.push_back({initial, -1, -1, -1});
    seen[initial] = all_states[0];
    bfs_queue.push(0);

    Perm optimal_perm = initial;
    int best_index = 0;

    while (!bfs_queue.empty()) {
        int current_idx = bfs_queue.front();
        bfs_queue.pop();

        Perm current = all_states[current_idx].arrangement;

        // Update best found so far
        if (current < optimal_perm) {
            optimal_perm = current;
            best_index = current_idx;
        }

        // Generate all possible operations (a,b) where a >= 1, b >= 1, a+b < size
        for (int a = 1; a < size; a++) {
            for (int b = 1; a + b < size; b++) {
                Perm next_state = transform(current, a, b);

                if (seen.find(next_state) == seen.end()) {
                    SearchState new_state = {next_state, a, b, current_idx};
                    all_states.push_back(new_state);
                    seen[next_state] = new_state;
                    bfs_queue.push(all_states.size() - 1);

                    // Early termination if we've reached the operation limit
                    if (all_states.size() > 100000) break;
                }
            }
            if (all_states.size() > 100000) break;
        }
    }

    // Reconstruct operation sequence
    vector<pair<int,int>> ops;
    int idx = best_index;
    while (all_states[idx].parent != -1) {
        ops.push_back({all_states[idx].op1, all_states[idx].op2});
        idx = all_states[idx].parent;
    }
    reverse(ops.begin(), ops.end());

    return {optimal_perm, ops};
}

// Greedy approach for larger n (> 9)
vector<pair<int,int>> solve_heuristic(Perm p, int max_ops) {
    int n = p.size();
    vector<pair<int,int>> operations;

    // Try to bring smallest missing numbers to front one by one
    for (int target = 1; target <= n && operations.size() < max_ops; target++) {
        // Find position of target value
        int pos = -1;
        for (int i = 0; i < n; i++) {
            if (p[i] == target) {
                pos = i;
                break;
            }
        }

        if (pos == 0) continue; // Already in correct position

        bool applied = false;

        // Case 1: Element is somewhere in the middle or near the end (pos >= 2)
        if (pos >= 2) {
            int b_val = n - pos;
            if (1 + b_val < n) {
                operations.push_back({1, b_val});
                p = transform(p, 1, b_val);
                applied = true;
            }
        }
        // Case 2: Element is at the very end (pos == n-1)
        else if (pos == n - 1) {
            if (1 + 1 < n) {
                operations.push_back({1, 1});
                p = transform(p, 1, 1);
                applied = true;
            }
        }
        // Case 3: Element is second (pos == 1)
        else if (pos == 1) {
            if (2 + 1 < n) {
                operations.push_back({2, 1});
                p = transform(p, 2, 1);

                if (1 + 1 < n) {
                    operations.push_back({1, 1});
                    p = transform(p, 1, 1);
                    applied = true;
                } else {
                    // Undo previous operation if second step not possible
                    operations.pop_back();
                    break;
                }
            }
        }

        if (!applied) break;
    }

    // Ensure we don't exceed maximum allowed operations
    if (operations.size() > max_ops) {
        operations.resize(max_ops);
    }

    return operations;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    Perm perm(N);
    for (int i = 0; i < N; i++) {
        cin >> perm[i];
    }

    vector<pair<int,int>> result_ops;

    if (N <= 9) {
        auto solution = solve_bfs(perm, 4 * N);
        result_ops = solution.second;

        // Enforce operation limit
        if (result_ops.size() > 4 * N) {
            result_ops.resize(4 * N);
        }
    } else {
        result_ops = solve_heuristic(perm, 4 * N);
    }

    cout << result_ops.size() << '\n';
    for (const auto& op : result_ops) {
        cout << op.first << ' ' << op.second << '\n';
    }

    return 0;
}

