    for (int j = 0; j < NCCL_NUM_PROTOCOLS; j++) {
      cost_matrix[i][j] = 1.0;
    }
  }
  int channels;

  pluginGetCollInfo(context, ncclFuncAllReduce, 32768, 1,
                    cost_matrix_ptr, NCCL_NUM_ALGORITHMS, NCCL_NUM_PROTOCOLS,
                    0, &channels);
  custom_logger(NCCL_LOG_INFO, NCCL_ALL, __FILE__, __LINE__,
                "DEBUG: Fallback test - checking cost_matrix[RING][SIMPLE] (%p) = %.1f",
                &cost_matrix[NCCL_ALGO_RING][NCCL_PROTO_SIMPLE], cost_matrix[NCCL_ALGO_RING][NCCL_PROTO_SIMPLE]);
  VERIFY_TEST(cost_matrix[NCCL_ALGO_RING][NCCL_PROTO_SIMPLE] == 1.0, "Should use pass through unmodified");
  VERIFY_TEST(channels == 1, "Should use default channels");

  pluginFinalize(context);
  unlink("fallback_test.conf");
  unsetenv("NCCL_TUNER_CONFIG_FILE");
  TEST_SUCCESS();
}

// Test 11: Large configuration file handling
int test_large_configuration() {
  const char* large_file = "large_test.conf";
  FILE* f = fopen(large_file, "w");
  VERIFY_TEST(f != NULL, "Should be able to create large config file");
  fprintf(f, "# Large configuration file for testing dynamic allocation\n");
  const int num_entries = 500;
  const char* coll_types[] = {"allreduce", "broadcast", "reduce", "allgather", "reducescatter"};
  const char* algo_types[] = {"tree", "ring", "collnet_direct", "nvls"};
  const char* proto_types[] = {"simple", "ll", "ll128"};
  for (int i = 0; i < num_entries; i++) {
    const char* coll = coll_types[i % 5];
    const char* algo = algo_types[i % 4];
    const char* proto = proto_types[i % 3];
    size_t min_bytes = (i * 1024) % 1048576;
    size_t max_bytes = min_bytes + 65536;
    int channels = (i % 8) + 1;
    int nodes = (i % 4) == 0 ? -1 : (i % 4);
    int ranks = (i % 8) == 0 ? -1 : (i % 32) + 1;
    int pipeOps = (i % 3) == 0 ? -1 : (i % 4) + 1;
    int regBuff = (i % 3) == 0 ? -1 : (i % 2);
    fprintf(f, "%s,%zu,%zu,%s,%s,%d,%d,%d,%d,%d\n",
            coll, min_bytes, max_bytes, algo, proto, channels, nodes, ranks, pipeOps, regBuff);
  }
  fclose(f);
  setenv("NCCL_TUNER_CONFIG_FILE", large_file, 1);
  void* context = NULL;
  ncclResult_t result = pluginInit(&context, 0, 16, 4, custom_logger, NULL, NULL);
  VERIFY_TEST(result == ncclSuccess, "Plugin init with large config should succeed");
  TunerContext* ctx = (TunerContext*)context;
  VERIFY_TEST(ctx->numConfigs == num_entries, "Should load all configurations from large file");
  VERIFY_TEST(ctx->maxConfigs == num_entries, "maxConfigs should match allocated size");
  VERIFY_TEST(ctx->configs != NULL, "Configs array should be dynamically allocated");

  // Verify configuration access throughout the array
  for (int i = 0; i < ctx->numConfigs; i++) {
    TuningConfig* cfg = &ctx->configs[i];
    VERIFY_TEST(cfg->collType >= ncclFuncBroadcast && cfg->collType <= ncclFuncAllReduce,
                "Collective type should be valid");
    VERIFY_TEST(cfg->maxBytes >= cfg->minBytes, "maxBytes should be >= minBytes");
    VERIFY_TEST(cfg->nChannels > 0, "nChannels should be positive");
  }

  // Test specific configuration access
  TuningConfig* first_cfg = &ctx->configs[0];
  VERIFY_TEST(first_cfg != NULL, "First config should be accessible");
  TuningConfig* mid_cfg = &ctx->configs[num_entries / 2];
  VERIFY_TEST(mid_cfg != NULL, "Middle config should be accessible");
  TuningConfig* last_cfg = &ctx->configs[num_entries - 1];
  VERIFY_TEST(last_cfg != NULL, "Last config should be accessible");

  mock_logger(NCCL_LOG_INFO, NCCL_ALL, __FILE__, __LINE__,
              "Successfully loaded %d configurations (dynamic allocation)", ctx->numConfigs);
  mock_logger(NCCL_LOG_INFO, NCCL_ALL, __FILE__, __LINE__,
              "Memory allocated for %d configurations (%zu bytes total)",
              ctx->maxConfigs, ctx->maxConfigs * sizeof(TuningConfig));

  // Test finding configurations in large set
  float cost_matrix[NCCL_NUM_ALGORITHMS][NCCL_NUM_PROTOCOLS];
  float* cost_matrix_ptr[NCCL_NUM_ALGORITHMS];
  for (int i = 0; i < NCCL_NUM_ALGORITHMS; i++) {
    cost_matrix_ptr[i] = cost_matrix[i];
    for (int j = 0; j < NCCL_NUM_PROTOCOLS; j++) {
      cost_matrix[i][j] = 1.0;
    }
  }
  int channels;
  result = pluginGetCollInfo(context, ncclFuncAllReduce, 32768, 1,
                            cost_matrix_ptr, NCCL_NUM_ALGORITHMS, NCCL_NUM_PROTOCOLS,
                            0, &channels);
  VERIFY_TEST(result == ncclSuccess, "GetCollInfo should work with large config set");

  pluginFinalize(context);
  unlink(large_file);
  unsetenv("NCCL_TUNER_CONFIG_FILE");
  TEST_SUCCESS();
}

// Test 12: Very large configuration stress test
int test_very_large_stress() {
  const char* stress_file = "stress_test.conf";
  FILE* f = fopen(stress_file, "w");
  VERIFY_TEST(f != NULL, "Should be able to create stress test config file");
  fprintf(f, "# Stress test configuration with very large number of entries\n");
  const int stress_count = 2000;
  for (int i = 0; i < stress_count; i++) {
    fprintf(f, "allreduce,%d,%d,ring,simple,4,-1,-1,-1,-1\n",
            i * 512, (i * 512) + 1024);
  }
  fclose(f);
  setenv("NCCL_TUNER_CONFIG_FILE", stress_file, 1);
  void* context = NULL;
  ncclResult_t result = pluginInit(&context, 0, 8, 2, custom_logger, NULL, NULL);
  VERIFY_TEST(result == ncclSuccess, "Plugin should handle very large config files");
  TunerContext* ctx = (TunerContext*)context;
  VERIFY_TEST(ctx->numConfigs == stress_count, "Should load all stress test configurations");
  VERIFY_TEST(ctx->configs != NULL, "Stress test configs should be allocated");

  mock_logger(NCCL_LOG_INFO, NCCL_ALL, __FILE__, __LINE__,
              "Stress test - loaded %d configurations successfully", stress_count);
  mock_logger(NCCL_LOG_INFO, NCCL_ALL, __FILE__, __LINE__,
              "Memory usage: %zu bytes for configuration array",
              stress_count * sizeof(TuningConfig));

  // Verify configuration access throughout entire range
  for (int i = 0; i < stress_count; i += 100) {
    TuningConfig* cfg = &ctx->configs[i];
    VERIFY_TEST(cfg->collType == ncclFuncAllReduce, "Config should have correct collective type");
    VERIFY_TEST(cfg->minBytes == (size_t)(i * 512), "Config should have correct minBytes");
  }

  unlink(stress_file);
  unsetenv("NCCL_TUNER_CONFIG_FILE");
  TEST_SUCCESS();
}

