void CritParticle::tick()
{
    for (int index = 0; index < 16; index++)
    {
        double offsetX = random->nextFloat() * 2 - 1;
        double offsetY = random->nextFloat() * 2 - 1;
        double offsetZ = random->nextFloat() * 2 - 1;
        if (offsetX * offsetX + offsetY * offsetY + offsetZ * offsetZ > 1) continue;

        double posX = entity->x + offsetX * entity->bbWidth / 4;
        double posY = entity->bb->y0 + entity->bbHeight / 2 + offsetY * entity->bbHeight / 4;
        double posZ = entity->z + offsetZ * entity->bbWidth / 4;

        level->addParticle(particleName, posX, posY, posZ, offsetX, offsetY + 0.2, offsetZ);
    }

    life++;
    if (life >= lifeTime) 
    {
        remove();
    }
}

