    FollowParent();
}

void TransConstraint::SetScaleVectorOnTransform(RndTransformable *trans, Vector3 &scaleVec) {
    MILO_ASSERT(trans, 0x80);
    Vector3 eulerOut;
    Hmx::Matrix3 rotMat;
    Transform worldXfm = trans->WorldXfm();
    MakeEuler(worldXfm.m, eulerOut);
    MakeRotMatrix(eulerOut, rotMat, true);
    Scale(rotMat, scaleVec, rotMat);
    worldXfm.m = rotMat;
    trans->SetWorldXfm(worldXfm);
}

void TransConstraint::FollowParent() {
    if (mParent && mChild) {
        Vector3 parentPos = mParent->WorldXfm().v;
        Vector3 childPos = mChild->WorldXfm().v;

        for (int axis = 0; axis < 3; ++axis) {
            if (mTrackAxis[axis]) {
                childPos[axis] = parentPos[axis];
            }
        }
        mChild->SetWorldPos(childPos);

        if (mModifyScale) {
            Vector3 parentScale;
            MakeScale(mParent->WorldXfm().m, parentScale);

            Vector3 childScale;
            MakeScale(mChild->WorldXfm().m, childScale);

            for (int dim = 0; dim < 3; ++dim) {
                if (mTrackAxis[dim]) {
                    childScale[dim] = parentScale[dim];
                }
            }
            SetScaleVectorOnTransform(mChild, childScale);
        }
    }
}

