void bind_executor_module(nb::module_& module) {
  // Register data types enumeration
  nb::enum_<DataType>(module, "DataType")
      .value("int32", DataType::INT32)
      .value("uint32", DataType::UINT32)
      .value("float16", DataType::FLOAT16)
      .value("float32", DataType::FLOAT32)
      .value("bfloat16", DataType::BFLOAT16);

  // Register packet types enumeration
  nb::enum_<PacketType>(module, "PacketType")
      .value("LL8", PacketType::LL8)
      .value("LL16", PacketType::LL16);

  // Bind ExecutionPlan class
  nb::class_<ExecutionPlan>(module, "ExecutionPlan")
      .def(nb::init<const std::string>(), nb::arg("plan_path"))
      .def("name", &ExecutionPlan::name)
      .def("collective", &ExecutionPlan::collective)
      .def("min_message_size", &ExecutionPlan::minMessageSize)
      .def("max_message_size", &ExecutionPlan::maxMessageSize);

  // Bind Executor class with custom lambda for execute method
  nb::class_<Executor>(module, "Executor")
      .def(nb::init<std::shared_ptr<Communicator>>(), nb::arg("communicator"))
      .def(
          "run",
          [](Executor* instance, int local_rank, uintptr_t input_buffer, uintptr_t output_buffer,
             size_t input_size, size_t output_size, DataType type, const ExecutionPlan& plan,
             uintptr_t cuda_stream, PacketType pkt_type) {
            instance->execute(local_rank, reinterpret_cast<void*>(input_buffer), reinterpret_cast<void*>(output_buffer),
                              input_size, output_size, type, plan, (cudaStream_t)cuda_stream, pkt_type);
          },
          nb::arg("rank"), nb::arg("input"), nb::arg("output"), nb::arg("input_size"), nb::arg("output_size"),
          nb::arg("data_type"), nb::arg("plan"), nb::arg("stream"), nb::arg("packet_type") = PacketType::LL16);
}

#include "../backend/src/QuantumRegister.hpp"
#include <benchmark/benchmark.h>
#include <iostream>

// Benchmark for Hadamard Gate operation to evaluate memory bandwidth limitations
static void BM_HadamardOperation(benchmark::State &state) {
  int qubit_count = state.range(0);

  // Initialize quantum register outside the timing loop to exclude allocation overhead
  // Note: 28 qubits require 2^28 * 16 bytes ≈ 4 GB of RAM
  try {
    QuantumRegister qr(qubit_count);

    for (auto _ : state) {
      // Execute the memory-bound Hadamard gate application
      qr.applyHadamard(0);

      // Prevent compiler optimizations and ensure memory operations are preserved
      benchmark::DoNotOptimize(qr.getStateVector().data());
      benchmark::ClobberMemory();
    }

    // Compute memory throughput metrics
    // Each iteration processes: read all amplitudes once + write all amplitudes once
    // Total data volume = 2 × (2^N × 16 bytes), where N is number of qubits
    double processed_bytes = static_cast<double>(1ULL << qubit_count) * 16.0 * 2.0;
    state.SetBytesProcessed(static_cast<int64_t>(state.iterations()) * 
                            static_cast<int64_t>(processed_bytes));

  } catch (const std::exception &err) {
    state.SkipWithError("Insufficient memory or allocation failure");
  }
}

// Register benchmarks for different system sizes:
// 20 qubits → 16 MB, 25 qubits → 512 MB, 28 qubits → 4 GB
BENCHMARK(BM_HadamardOperation)
    ->Arg(20)
    ->Arg(25)
    ->Arg(28)
    ->Unit(benchmark::kMillisecond);

BENCHMARK_MAIN();

