using namespace llvm;

// Determine if this specialization context should be finalized (true) or only
// serve as a hint for other components (false)?
bool InlineAttempt::isActive() {
  if (!Callers.empty()) { // Not root function
    if (isPathCondition) // Path condition functions are symbolic and produce no runtime code
      return false;
    else
      return isShared() || active;
  }
  return true; // Root function: always active
}

// Loop unroll iterations are always finalized if their enclosing loop is.
bool PeelIteration::isActive() { return true; }
bool PeelAttempt::isActive() { return active; }

// Attempt to set the active (finalized) status to 'val'
void InlineAttempt::setActive(bool val, bool skipStats) {
  // Root function cannot be deactivated
  if (Callers.empty())
    return;
  // Shared functions cannot currently be deactivated
  if (isShared())
    return;
  // Path conditions never get finalized anyway
  if (isPathCondition)
    return;
  active = val;
  if (!skipStats)
    pass->getRoot()->gatherStats();
}

void PeelIteration::setActive(bool val, bool skipStats) {
  assert(0 && "Individual iteration deactivation not supported yet");
}

void PeelAttempt::setActive(bool val, bool skipStats) { active = val; }

// Will this specialization context be placed in a different residual function
// than its parent?
bool InlineAttempt::commitsSeparately() {
  // No parent exists in this case
  if (isRootMainCall())
    return true;
  for (SmallVector<ShadowInstruction *, 1>::iterator iter = Callers.begin(),
                                                     iterEnd = Callers.end();
       iter != iterEnd; ++iter) {
    // If this function has non-null CommitF while its parent has a different one,
    // it implies this context was committed before the parent obtained its commit
    // function, and since we didn't claim our own, we inherited it implicitly.
    if (CommitF && (*iter)->parent->IA->getFunctionRoot()->CommitF != CommitF)
      return true;
  }
  return false;
}

// Loop unroll iterations always commit within the same function as their direct parent.
bool PeelIteration::commitsSeparately() { return false; }

// Return true if this function must be compiled as a standalone residual function
// instead of being inlined everywhere as usual.
// Note that even if it *could* inline, SaveSplit.cpp may still decide to split
// it for optimization reasons.
bool InlineAttempt::mustCommitSeparately() {
  // Root function naturally requires its own residual function.
  if (isRootMainCall())
    return true;
  // Vararg functions: we currently don't rewrite vararg intrinsics, and Dragonegg's
  // vararg handling exposes the real implementation which we can't modify, so
  // va_list must exist at runtime.
  if (F.isVarArg())
    return true;
  // Shared functions need separate functions to support multiple callers.
  // Note: this feature may be outdated.
  if (isShared())
    return true;
  // Has the user explicitly marked this as a split point?
  if (pass->splitFunctions.count(&F))
    return true;
  // Unclear why this check is needed — possibly missing logic to insert
  // fallback-to-unspecialized-code flags and post-invoke tests?
  if (hasFailedReturnPath()) {
    for (uint32_t idx = 0, limit = Callers.size(); idx != limit; ++idx) {
      if (inst_is<InvokeInst>(Callers[idx]))
        return true;
    }
  }
  return false;
}

bool PeelIteration::mustCommitSeparately() { return false; }

bool IntegrationAttempt::allAncestorsActive() {
  // Not active?
  if (!isActive())
    return false;
  // Not getting inlined/unrolled at all?
  // Note on use of getUniqueParent: this function determines whether a user
  // can reference a heap object allocated in this context. Contexts where
  // allocations might escape are unsharable, so if getUniqueParent fails,
  // we're either both committed (safe) or both uncommitted (no impact).
  IntegrationAttempt *ancestor = getUniqueParent();
  if (ancestor && !ancestor->allAncestorsActive())
    return false;
  return true;
}

