}

std::string Test::toString() const {
    std::ostringstream stream;
    stream << op_name() << std::endl;
    stream << "- input1: " << _attributes->input1->info() << std::endl;
    stream << "- input2: " << _attributes->input2->info() << std::endl;
    stream << "- output: " << _attributes->output->info() << std::endl;
    stream << std::scientific << std::setprecision(2);
    stream << "- rtol=" << _rtol << ", atol=" << _atol << std::endl;
    return stream.str();
}

