// ClimaButler IR protocol constants
const uint16_t kClimaButlerBitMark = 511;    // microseconds
const uint16_t kClimaButlerHdrMark = kClimaButlerBitMark;
const uint16_t kClimaButlerHdrSpace = 3492;  // microseconds
const uint16_t kClimaButlerOneSpace = 1540;  // microseconds
const uint16_t kClimaButlerZeroSpace = 548;  // microseconds
const uint32_t kClimaButlerGap = kDefaultMessageGap;  // microseconds (Estimated)
const uint16_t kClimaButlerCarrierFreq = 38000;     // Hz (Estimated)

#if SEND_CLIMABUTLER
/// Transmit a ClimaButler-encoded infrared signal.
/// Status: STABLE / Verified working.
/// @param[in] payload The 64-bit IR command data.
/// @param[in] bitCount Number of bits to transmit (typically kClimaButlerBits).
/// @param[in] repeatCount How many times the transmission should be repeated.
void IRsend::sendClimaButler(const uint64_t payload, const uint16_t bitCount,
                             const uint16_t repeatCount) {
  enableIROut(kClimaButlerCarrierFreq);
  for (uint16_t repetition = 0; repetition <= repeatCount; repetition++) {
    // Send header and data portion
    sendGeneric(kClimaButlerHdrMark, kClimaButlerHdrSpace,
                kClimaButlerBitMark, kClimaButlerOneSpace,
                kClimaButlerBitMark, kClimaButlerZeroSpace,
                kClimaButlerBitMark, kClimaButlerHdrSpace,
                payload, bitCount, kClimaButlerCarrierFreq, true, 0, kDutyDefault);
    // End with footer mark and gap
    mark(kClimaButlerBitMark);
    space(kClimaButlerGap);
  }
}
#endif  // SEND_CLIMABUTLER

#if DECODE_CLIMABUTLER
/// Decode an incoming ClimaButler IR message.
/// Status: STABLE / Verified working.
/// @param[in,out] decodeData Pointer to storage for decoded results.
/// @param[in] startIndex Starting position in raw buffer for decoding.
/// @param[in] expectedBits Expected number of data bits.
/// @param[in] enforceStrict Whether to enforce strict bit-count validation.
/// @return true if decoding succeeded, false otherwise.
bool IRrecv::decodeClimaButler(decode_results *decodeData, uint16_t startIndex,
                               const uint16_t expectedBits, const bool enforceStrict) {
  // Check minimum buffer length requirement
  if (decodeData->rawlen < 2 * expectedBits + kHeader + 2 * kFooter - startIndex)
    return false;  // Signal too short for valid match

  // Enforce bit count if strict mode is enabled
  if (enforceStrict && expectedBits != kClimaButlerBits)
    return false;

  // Attempt to match header and data portion
  uint16_t consumed = matchGeneric(decodeData->rawbuf + startIndex,
                                   &(decodeData->value),
                                   decodeData->rawlen - startIndex,
                                   expectedBits,
                                   kClimaButlerHdrMark, kClimaButlerHdrSpace,
                                   kClimaButlerBitMark, kClimaButlerOneSpace,
                                   kClimaButlerBitMark, kClimaButlerZeroSpace,
                                   kClimaButlerBitMark, kClimaButlerHdrSpace);
  if (!consumed) return false;  // Header/data mismatch

  startIndex += consumed;

  // Validate footer mark
  if (!matchMark(decodeData->rawbuf[startIndex++], kClimaButlerBitMark))
    return false;

  // Validate final gap
  if (decodeData->rawlen <= startIndex &&
      !matchAtLeast(decodeData->rawbuf[startIndex], kClimaButlerGap))
    return false;

  // Record successful decode
  decodeData->decode_type = decode_type_t::CLIMABUTLER;
  decodeData->bits = expectedBits;
  decodeData->command = 0;
  decodeData->address = 0;
  return true;
}
#endif  // DECODE_CLIMABUTLER

