// Convert string to integer, handling optional sign and whitespace
int atoi(const char *str) {
    int result = 0, negativeFlag = 0;

    // Skip leading whitespace characters
    while (isspace(*str)) str++;

    // Check for sign character
    switch (*str) {
        case '-': negativeFlag = 1;
        case '+': str++;
    }

    // Process digits, building result as negative to handle INT_MIN safely
    while (isdigit(*str)) {
        result = 10 * result - (*str++ - '0');
    }

    return negativeFlag ? result : -result;
}

