using namespace std;

// Upper bound on number of nodes based on problem constraints
const int MAX_NODES = 1005;
int numVertices, numEdges;

// Adjacency representation using bitsets for fast operations
bitset<MAX_NODES> connections[MAX_NODES];

// Current set of vertices forming the clique under exploration
vector<int> current_set;
// Best clique discovered so far
vector<int> optimal_set;
// Size of the largest clique found
int max_clique_size = 0;

// Timing control variables
clock_t begin_clock;
const double MAX_DURATION = 1.95; // Keep slightly under 2 seconds

// Reusable arrays for greedy coloring to minimize memory allocation overhead
static int color_usage[MAX_NODES];
static int color_marker = 0;

/**
 * Recursive backtracking function to find maximum clique.
 * candidates: bitset representing feasible vertices at this recursion level
 */
void search(bitset<MAX_NODES> candidates) {
    // Time budget check
    if ((double)(clock() - begin_clock) / CLOCKS_PER_SEC > MAX_DURATION) return;

    int remaining = candidates.count();

    // Base case: no more candidates left
    if (remaining == 0) {
        if (current_set.size() > max_clique_size) {
            max_clique_size = current_set.size();
            optimal_set = current_set;
        }
        return;
    }

    // Pruning: upper bound check using remaining candidates
    if (current_set.size() + remaining <= max_clique_size) return;

    // Extract candidate vertices into a list for processing
    vector<int> vertex_list;
    vertex_list.reserve(remaining);
    for (int idx = 1; idx <= numVertices; ++idx) {
        if (candidates[idx]) vertex_list.push_back(idx);
    }

    // Apply greedy coloring heuristic on induced subgraph
    vector<int> assigned_colors(numVertices + 1, 0);
    int highest_color = 0;

    for (int node : vertex_list) {
        color_marker++;

        // Mark colors used by adjacent already-colored nodes
        for (int neighbor : vertex_list) {
            if (neighbor == node) continue;
            if (assigned_colors[neighbor] != 0 && connections[node][neighbor]) {
                color_usage[assigned_colors[neighbor]] = color_marker;
            }
        }

        // Find first available color
        int chosen_color = 1;
        while (color_usage[chosen_color] == color_marker) chosen_color++;
        assigned_colors[node] = chosen_color;
        if (chosen_color > highest_color) highest_color = chosen_color;
    }

    // Coloring-based pruning: chromatic number bounds clique number
    if (current_set.size() + highest_color <= max_clique_size) return;

    // Sort vertices by ascending color class
    sort(vertex_list.begin(), vertex_list.end(), [&](int a, int b) {
        return assigned_colors[a] < assigned_colors[b];
    });

    // Process vertices in reverse order (higher color classes first)
    for (int i = vertex_list.size() - 1; i >= 0; --i) {
        // Periodic time limit check
        if ((double)(clock() - begin_clock) / CLOCKS_PER_SEC > MAX_DURATION) return;

        int vertex = vertex_list[i];
        int color_class = assigned_colors[vertex];

        // Further pruning: remaining potential based on color class
        if (current_set.size() + color_class <= max_clique_size) break;

        // Include current vertex in the clique
        current_set.push_back(vertex);

        // Exclude this vertex from future consideration in sibling branches
        candidates[vertex] = 0;

        // Recurse with only common neighbors
        search(candidates & connections[vertex]);

        // Backtrack
        current_set.pop_back();
    }
}

int main() {
    // Input reading
    if (scanf("%d %d", &numVertices, &numEdges) != 2) return 0;

    // Build adjacency structure
    for (int i = 0; i < numEdges; ++i) {
        int u, v;
        scanf("%d %d", &u, &v);
        if (u >= 1 && u <= numVertices && v >= 1 && v <= numVertices) {
            connections[u][v] = 1;
            connections[v][u] = 1;
        }
    }

    // Initialize timing and search
    begin_clock = clock();
    bitset<MAX_NODES> initial_candidates;
    for (int i = 1; i <= numVertices; ++i) initial_candidates.set(i);

    search(initial_candidates);

    // Output result: mark which vertices belong to the best clique
    vector<int> output_flag(numVertices + 1, 0);
    for (int v : optimal_set) {
        output_flag[v] = 1;
    }

    for (int i = 1; i <= numVertices; ++i) {
        printf("%d\n", output_flag[i]);
    }

    return 0;
}

