// Count the number of odd integers in the inclusive range [minVal, maxVal]
class OddCounter {
public:
    int calculateOddCount(int minVal, int maxVal) {
        int result = (maxVal - minVal) / 2;
        if (minVal % 2 != 0 || maxVal % 2 != 0)
            result += 1;
        return result;
    }
};

