using namespace llvm;

#define DEBUG_TYPE "lowerinvoke"

STATISTIC(NumReplacedInvokes, "Number of invoke instructions replaced");

namespace {
  class LowerInvokeAdapter : public FunctionPass {
  public:
    static char ID; // Pass identification, replacement for typeid
    explicit LowerInvokeAdapter() : FunctionPass(ID) {
      initializeLowerInvokeAdapterPass(*PassRegistry::getPassRegistry());
    }
    bool runOnFunction(Function &func) override;
  };
}

char LowerInvokeAdapter::ID = 0;

INITIALIZE_PASS(LowerInvokeAdapter, "lowerinvoke",
                "Lower invoke and unwind, for unwindless code generators",
                false, false)

static bool processFunction(Function &func) {
  bool Modified = false;

  for (BasicBlock &block : func) {
    if (InvokeInst *invoke = dyn_cast<InvokeInst>(block.getTerminator())) {
      SmallVector<Value *, 16> arguments(invoke->args());
      SmallVector<OperandBundleDef, 1> bundles;
      invoke->getOperandBundlesAsDefs(bundles);

      // Insert a regular call instruction...
      CallInst *replacementCall =
          CallInst::Create(invoke->getFunctionType(), invoke->getCalledOperand(),
                           arguments, bundles, "", invoke);
      replacementCall->takeName(invoke);
      replacementCall->setCallingConv(invoke->getCallingConv());
      replacementCall->setAttributes(invoke->getAttributes());
      replacementCall->setDebugLoc(invoke->getDebugLoc());

      invoke->replaceAllUsesWith(replacementCall);

      // Insert an unconditional branch to the normal destination.
      BranchInst::Create(invoke->getNormalDest(), invoke);

      // Remove any PHI node entries from the exception destination.
      invoke->getUnwindDest()->removePredecessor(&block);

      // Remove the original invoke instruction now.
      invoke->eraseFromParent();

      ++NumReplacedInvokes;
      Modified = true;
    }
  }

  return Modified;
}

bool LowerInvokeAdapter::runOnFunction(Function &func) {
  return processFunction(func);
}

namespace llvm {
char &LowerInvokePassIdentifier = LowerInvokeAdapter::ID;

// Public Interface To the LowerInvoke pass.
FunctionPass *createLowerInvokePass() { return new LowerInvokeAdapter(); }

PreservedAnalyses LowerInvokePass::run(Function &func,
                                       FunctionAnalysisManager &AM) {
  bool Modified = processFunction(func);

  if (!Modified)
    return PreservedAnalyses::all();

  return PreservedAnalyses::none();
}
}

