#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <chrono>
#include <random>
using namespace std;

// City representation
struct Location {
    int identifier;
    int coordX, coordY;
};

int numLocations;
vector<Location> locations;
vector<int> route; // size N+1
vector<bool> isPrime;

// Euclidean distance helper
inline double calc_distance(int id1, int id2) {
    long long diffX = locations[id1].coordX - locations[id2].coordX;
    long long diffY = locations[id1].coordY - locations[id2].coordY;
    return std::sqrt((double)diffX * diffX + (double)diffY * diffY);
}

// Penalty multiplier helper
// step_number is 1-based index of the step
// origin_id is the ID of the city at step_number-1
inline double get_penalty_factor(int step_number, int origin_id) {
    if (step_number % 10 == 0 && !isPrime[origin_id]) return 1.1;
    return 1.0;
}

int main() {
    // Fast I/O setup
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> numLocations)) return 0;

    locations.resize(numLocations);
    for (int idx = 0; idx < numLocations; ++idx) {
        locations[idx].identifier = idx;
        cin >> locations[idx].coordX >> locations[idx].coordY;
    }

    // Precompute primes using Sieve of Eratosthenes
    isPrime.assign(numLocations + 1, true);
    isPrime[0] = isPrime[1] = false;
    for (int prime_candidate = 2; prime_candidate * prime_candidate <= numLocations; prime_candidate++) {
        if (isPrime[prime_candidate]) {
            for (int multiple = prime_candidate * prime_candidate; multiple <= numLocations; multiple += prime_candidate)
                isPrime[multiple] = false;
        }
    }

    // Initial Tour: Bitonic Tour based on X-coordinates (input is sorted by X)
    route.reserve(numLocations + 1);
    route.push_back(0);

    // Add even indices in increasing order
    for (int i = 2; i < numLocations; i += 2) 
        route.push_back(i);

    // Add odd indices in decreasing order
    for (int i = (numLocations % 2 == 0 ? numLocations - 1 : numLocations - 2); i >= 1; i -= 2) 
        route.push_back(i);

    route.push_back(0);

    auto start_timestamp = chrono::steady_clock::now();

    // Optimization Parameters
    int search_window = 25; 
    int prime_swap_range = 40;
    bool found_improvement = true;

    // Main optimization loop
    while (true) {
        // Time check: stop if close to 2s limit (leave 150ms buffer)
        if (chrono::duration_cast<chrono::milliseconds>(chrono::steady_clock::now() - start_timestamp).count() > 1850) break;

        found_improvement = false;

        // 1. Windowed 2-opt improvement
        for (int pos1 = 1; pos1 < numLocations - 1; ++pos1) {
            // Periodic time check
            if ((pos1 & 4095) == 0) {
                if (chrono::duration_cast<chrono::milliseconds>(chrono::steady_clock::now() - start_timestamp).count() > 1850) goto finish_loop;
            }

            int end_limit = min(numLocations - 1, pos1 + search_window);
            for (int pos2 = pos1 + 1; pos2 <= end_limit; ++pos2) {
                // Consider reversing segment route[pos1...pos2]
                // This affects edges (route[pos1-1], route[pos1]) and (route[pos2], route[pos2+1])

                double current_cost = 0;
                double proposed_cost = 0;

                // Calculate costs for all steps k in [pos1, pos2+1]
                for (int step = pos1; step <= pos2 + 1; ++step) {
                    // Old configuration cost
                    current_cost += calc_distance(route[step-1], route[step]) * get_penalty_factor(step, route[step-1]);

                    // New configuration after reversal
                    int src_idx = step - 1;
                    int dst_idx = step;

                    int src_node = (src_idx < pos1) ? route[src_idx] : (src_idx > pos2 ? route[src_idx] : route[pos1 + pos2 - src_idx]);
                    int dst_node = (dst_idx < pos1) ? route[dst_idx] : (dst_idx > pos2 ? route[dst_idx] : route[pos1 + pos2 - dst_idx]);

                    double factor_new = 1.0;
                    if (step % 10 == 0 && !isPrime[src_node]) factor_new = 1.1;
                    proposed_cost += calc_distance(src_node, dst_node) * factor_new;
                }

                if (proposed_cost < current_cost - 1e-9) {
                    reverse(route.begin() + pos1, route.begin() + pos2 + 1);
                    found_improvement = true;
                }
            }
        }

        // 2. Prime fix pass: target steps that incur penalty
        for (int step_target = 10; step_target <= numLocations; step_target += 10) {
            if ((step_target & 511) == 0) {
                 if (chrono::duration_cast<chrono::milliseconds>(chrono::steady_clock::now() - start_timestamp).count() > 1850) goto finish_loop;
            }

            // If this step has a penalty (source is not prime), try to fix it
            if (isPrime[route[step_target-1]]) continue;

            // Search for a prime city nearby in the tour to swap with
            int lower_bound = max(1, step_target - 1 - prime_swap_range);
            int upper_bound = min(numLocations - 1, step_target - 1 + prime_swap_range);

            int idx_origin = step_target - 1; // Index of non-prime city causing penalty

            for (int k = lower_bound; k <= upper_bound; ++k) {
                if (k == idx_origin) continue;
                if (!isPrime[route[k]]) continue; // Only swap with a prime

                int idx_swap = k;
                int p1 = idx_origin;
                int p2 = idx_swap;
                if (p1 > p2) swap(p1, p2);

                // Identify steps affected by swapping route[p1] and route[p2]
                vector<int> affected_steps;
                affected_steps.push_back(p1);
                affected_steps.push_back(p1+1);
                if (p2 != p1 + 1) affected_steps.push_back(p2); // Avoid duplicate if adjacent
                affected_steps.push_back(p2+1);

                double old_local_cost = 0;
                double new_local_cost = 0;

                // Calculate old local cost
                for (int s : affected_steps) {
                    if (s > numLocations) continue; // Boundary check
                    old_local_cost += calc_distance(route[s-1], route[s]) * get_penalty_factor(s, route[s-1]);
                }

                // Perform swap
                swap(route[p1], route[p2]);

                // Calculate new local cost
                for (int s : affected_steps) {
                    if (s > numLocations) continue;
                    new_local_cost += calc_distance(route[s-1], route[s]) * get_penalty_factor(s, route[s-1]);
                }

                if (new_local_cost < old_local_cost - 1e-9) {
                    found_improvement = true;
                    // Keep the swap and break from inner search (Greedy)
                    break;
                } else {
                    // Revert swap
                    swap(route[p1], route[p2]);
                }
            }
        }
        if (!found_improvement) break; // Local optimum reached
    }

    finish_loop:;
    cout << route.size() << "\n";
    for (int i = 0; i < route.size(); ++i) {
        cout << route[i] << "\n";
    }
    return 0;
}

