#include <iostream>
#include <vector>
#include <cstdlib>
using namespace std;

// Global state tracking variables
int startDepth;
int currentDepth;
int stepCount = 0;

// Constants for move limits and safety margin
const int MAX_STEPS = 100000;
const int SAFETY_MARGIN = 95000;

// Function to query the current depth (distance to exit)
int get_depth() {
    cout << "query" << endl;
    int d;
    if (!(cin >> d)) exit(0);
    return d;
}

// Function to move along an edge of color c
void traverse_edge(int c) {
    cout << "move " << c << endl;
    int result;
    if (!(cin >> result)) exit(0);
    stepCount++;
    if (result == 1) {
        // Reached the exit
        exit(0);
    }
}

// History of successful upward moves
vector<int> path_history;

// The color of the edge that leads back down to the previous node
int last_downward_edge = -1;

// Perform one safe upward move
// Cost: 1 query, up to 3 moves
void perform_safe_move() {
    // Determine candidate colors excluding the downward edge
    vector<int> options;
    for (int col = 0; col < 3; ++col) {
        if (col != last_downward_edge) {
            options.push_back(col);
        }
    }

    // Try first option
    int attempt_col = options[0];
    traverse_edge(attempt_col);

    // Check if move was upward or downward
    int new_depth = get_depth();
    if (new_depth < currentDepth) {
        // Successful upward move
        currentDepth = new_depth;
        last_downward_edge = attempt_col;
        path_history.push_back(attempt_col);
    } else {
        // Moved downward instead — revert and try other option
        traverse_edge(attempt_col); // Return to original node

        int alt_col = options[1];
        traverse_edge(alt_col);

        // This must be the correct upward move
        currentDepth--;
        last_downward_edge = alt_col;
        path_history.push_back(alt_col);
    }
}

// Initial move to determine starting direction
void initialize_direction() {
    // Try color 0
    traverse_edge(0);
    int d = get_depth();
    if (d < currentDepth) {
        currentDepth = d;
        last_downward_edge = 0;
        path_history.push_back(0);
        return;
    }
    traverse_edge(0); // Backtrack

    // Try color 1
    traverse_edge(1);
    d = get_depth();
    if (d < currentDepth) {
        currentDepth = d;
        last_downward_edge = 1;
        path_history.push_back(1);
        return;
    }
    traverse_edge(1); // Backtrack

    // Must be color 2
    traverse_edge(2);
    currentDepth--;
    last_downward_edge = 2;
    path_history.push_back(2);
}

int main() {
    // Read initial depth
    if (!(cin >> startDepth)) return 0;
    currentDepth = startDepth;

    // If already at the exit
    if (currentDepth == 0) return 0;

    // First move initialization
    initialize_direction();

    // Continue until reaching the root (exit)
    while (currentDepth > 0) {
        // Safety check: avoid exceeding move limit
        if (stepCount > SAFETY_MARGIN) {
            perform_safe_move();
            continue;
        }

        // Attempt pattern detection in move history
        int best_cycle = -1;
        int H = path_history.size();

        // Look for repeating patterns of length 1 to 20
        for (int cycle_len = 1; cycle_len <= 20 && cycle_len * 2 <= H; ++cycle_len) {
            bool is_match = true;
            // Compare last cycle_len elements with preceding cycle_len elements
            for (int offset = 0; offset < cycle_len; ++offset) {
                if (path_history[H - cycle_len + offset] != path_history[H - 2 * cycle_len + offset]) {
                    is_match = false;
                    break;
                }
            }
            if (is_match) {
                best_cycle = cycle_len;
                break; // Use smallest valid period
            }
        }

        if (best_cycle != -1) {
            // Pattern detected — attempt batched moves
            int batch_size = best_cycle;
            if (batch_size > currentDepth) batch_size = currentDepth;

            // Build predicted sequence from pattern
            vector<int> predicted_sequence;
            for (int i = 0; i < batch_size; ++i) {
                predicted_sequence.push_back(path_history[H - best_cycle + i]);
            }

            // Execute batch
            for (int col : predicted_sequence) {
                traverse_edge(col);
            }

            // Verify with single query
            int final_depth = get_depth();

            if (final_depth == currentDepth - batch_size) {
                // Prediction confirmed
                currentDepth = final_depth;
                last_downward_edge = predicted_sequence.back();
                path_history.insert(path_history.end(), 
                                   predicted_sequence.begin(), 
                                   predicted_sequence.end());
            } else {
                // Prediction failed — backtrack and fall back to safe move
                for (int i = batch_size - 1; i >= 0; --i) {
                    traverse_edge(predicted_sequence[i]);
                }
                perform_safe_move();
            }
        } else {
            // No pattern found — use safe move
            perform_safe_move();
        }
    }

    return 0;
}

