public:
	virtual void StartupModule() override
	{
		// Load the required level sequence module to ensure availability
		FModuleManager::Get().LoadModuleChecked("LevelSequence");

		// Initialize take metadata for the ULevelSequence CDO to support editor tooltips
		UTakeMetaData* SequenceMetaData = GetMutableDefault<ULevelSequence>()->FindOrAddMetaData<UTakeMetaData>();
		SequenceMetaData->SetFlags(RF_Transient);

		// Store a reference to the LevelSequence CDO for later cleanup
		LevelSequenceCDO = GetMutableDefault<ULevelSequence>();

