			CachedCDO->RemoveMetaData<UTakeMetaData>();
		}

		// Unregister take data from Movie Scene Tools
		FMovieSceneToolsModule::Get().UnregisterTakeData(TakeDataHandle.Get());
	}

private:
	// Weak pointer to preserve safety during destruction order
	TWeakObjectPtr<ULevelSequence> LevelSequenceCDO;
	TSharedPtr<IMovieSceneToolsTakeData> TakeDataHandle;
};

