namespace engine::monitor {
//-------------------------------------------------------------------------
/// @details
///		Called to update the monitor
///	@param[in]	force
///		Force an update even if the timer has not expired
//-------------------------------------------------------------------------
void Monitor::updateProcess() noexcept {
    while (!async::cancelled()) {
        // Check if it's time to refresh
        async::sleep(100ms);
        // Skip if the interval hasn't elapsed yet
        if (time::now() - m_lastRefresh > 2.5s) {
            // Proceed only if the monitor is active
            if (m_active) updateMonitor();
            // Record the latest update timestamp
            m_lastRefresh = time::now();
        }
    }
    // Termination point
    return;
}
//-------------------------------------------------------------------------
/// @details
///		Start the monitor
//-------------------------------------------------------------------------
void Monitor::startMonitor() noexcept {
    // Prevent redundant initialization
    ASSERT(!m_active);
    // Launch monitoring thread
    m_workerThread = async::Thread{_location, "Status",
                                   _bind(&Monitor::updateProcess, this)};
    // Activate the thread
    m_workerThread->start();
    // Mark as initialized
    m_active = true;
}
//-------------------------------------------------------------------------
/// @details
///		Start the counters
//-------------------------------------------------------------------------
void Monitor::startCounters() noexcept { Parent::startCounters(); }
//-----------------------------------------------------------------
///	@details
///		Output a warning message to the console
