///		Error code to output
//-----------------------------------------------------------------
Error Monitor::warning(Error &&ccode) noexcept {
    // Synchronize access
    auto guard = lock();
    if (m_warnings.size() < 25) m_warnings.emplace_back(_mv(ccode));
    return ccode;
}
//-----------------------------------------------------------------
///	@details
