}
//-------------------------------------------------------------------------
/// @details
///		Stops the counters and does a final count flush if they have
/// 	changed
//-------------------------------------------------------------------------
void Monitor::stopCounters() noexcept {
    // Delegate to base class
    Parent::stopCounters();
    // Finalize pending updates
    updateMonitor();
}
//-------------------------------------------------------------------------
/// @details
///		Stop the monitor
//-------------------------------------------------------------------------
void Monitor::stopMonitor() noexcept {
    // Early exit if already stopped
    if (!m_active) return;
    // Signal shutdown
    m_active = false;
    // Handle cleanup of worker thread
    if (m_workerThread) {
        // Request cancellation
        m_workerThread->cancel();
        // Wait for completion
        m_workerThread->join();
        // Release resources
        m_workerThread.reset();
    }
    // Confirm inactive state
    m_active = false;
    // Output completion info
    // LOGT("Completed {} in {}", this, m_status.elapsed());
    // LOGT("Total count: {}, size: {}",
    //      MONITOR(completed).count,
