#include <iostream>
#include <vector>
#include <string>
#include <numeric>
#include <algorithm>

struct Person {
    int identifier;
    std::string full_name;
    int years_old;
    std::vector<int> transaction_amounts;
    int join_year;
    std::string account_status;
};

struct CleanedPerson {
    std::string full_name;
    int expenditure;
    int tenure_years;
    std::string category;
};

struct OutputData {
    std::vector<CleanedPerson> cleaned_persons;
    int overall_income;
    int person_count;
    double mean_expenditure;
};

OutputData transform_data_flow(const std::vector<Person>& people) {
    std::vector<Person> selected;
    std::copy_if(people.begin(), people.end(), std::back_inserter(selected), [](const Person& person) {
        return person.account_status == "active" && person.years_old >= 25;
    });

    std::vector<CleanedPerson> cleaned_persons;
    std::transform(selected.begin(), selected.end(), std::back_inserter(cleaned_persons), [](const Person& person) {
        CleanedPerson cp;
        cp.full_name = person.full_name;
        cp.expenditure = std::accumulate(person.transaction_amounts.begin(), person.transaction_amounts.end(), 0);
        cp.tenure_years = 2026 - person.join_year;

        if (cp.expenditure < 500) {
            cp.category = "Bronze";
        } else if (cp.expenditure < 1000) {
            cp.category = "Silver";
        } else {
            cp.category = "Gold";
        }
        return cp;
    });

    int overall_income = std::accumulate(cleaned_persons.begin(), cleaned_persons.end(), 0, [](int sum_val, const CleanedPerson& person) {
        return sum_val + person.expenditure;
    });

    OutputData output;
    output.cleaned_persons = cleaned_persons;
    output.overall_income = overall_income;
    output.person_count = cleaned_persons.size();
    output.mean_expenditure = output.person_count > 0 ? static_cast<double>(overall_income) / output.person_count : 0.0;
    return output;
}

int main() {
    std::vector<Person> people = {
        {1, "Alice", 30, {200, 400, 150}, 2019, "active"},
        {2, "Bob", 22, {100, 50}, 2021, "active"},
        {3, "Charlie", 28, {500, 600}, 2020, "inactive"},
        {4, "Diana", 35, {300, 200, 100}, 2018, "active"}
    };

    auto output = transform_data_flow(people);

    std::cout << "Cleaned Persons:\n";
    for (const auto& person : output.cleaned_persons) {
        std::cout << person.full_name << ", expenditure: " << person.expenditure
                  << ", tenure_years: " << person.tenure_years
                  << ", category: " << person.category << "\n";
    }

    std::cout << "Overall Income: " << output.overall_income << "\n";
    std::cout << "Person Count: " << output.person_count << "\n";
    std::cout << "Mean Expenditure: " << output.mean_expenditure << "\n";

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <random>
#include <numeric>
#include <chrono>
using namespace std;

// Main function to process each test scenario
void runTest() {
    int size;
    if (!(cin >> size)) return;

    // Create initial list of pen IDs from 0 to size-1
    vector<int> pens(size);
    iota(pens.begin(), pens.end(), 0);

    // Randomize pen order using time-based seed for fair comparisons
    unsigned rngSeed = chrono::system_clock::now().time_since_epoch().count();
    shuffle(pens.begin(), pens.end(), default_random_engine(rngSeed));

    // Container for pens confirmed to have ink (survivors)
    vector<int> survivors;

    // Lambda function to interact with the judge system
    auto ask = [&](int id) -> int {
        cout << "0 " << id << endl;
        int answer;
        cin >> answer;
        return answer;
    };

    // Continue until only two pens remain in total
    while (pens.size() + survivors.size() > 2) {
        if (pens.empty()) {
            // Only known survivors left; make them compete directly
            int first = survivors.back(); survivors.pop_back();
            int second = survivors.back(); survivors.pop_back();

            if (ask(first) == 0) {
                // First pen exhausted, keep second
                survivors.push_back(second);
            } else {
                // First has ink; test second
                if (ask(second) == 0) {
                    // Second exhausted, keep first
                    survivors.push_back(first);
                } else {
                    // Both have ink; both survive
                    survivors.push_back(first);
                    survivors.push_back(second);
                }
            }
        } else {
            // Take a candidate pen from the untested pool
            int candidate = pens.back(); pens.pop_back();

            if (survivors.empty()) {
                // No known survivors yet; pair two unknown pens
                int opponent = pens.back(); pens.pop_back();

                if (ask(candidate) == 0) {
                    // Candidate failed; opponent remains unverified
                    pens.push_back(opponent);
                } else {
                    // Candidate succeeded; test opponent
                    if (ask(opponent) == 0) {
                        // Opponent failed; promote candidate
                        survivors.push_back(candidate);
                    } else {
                        // Both succeeded; promote both
                        survivors.push_back(candidate);
                        survivors.push_back(opponent);
                    }
                }
            } else {
                // Use a known survivor as opponent
                int champion = survivors.back(); survivors.pop_back();

                // Test candidate first (more likely to fail)
                if (ask(candidate) == 0) {
                    // Candidate failed; champion remains untouched
                    survivors.push_back(champion);
                } else {
                    // Candidate succeeded; test champion
                    if (ask(champion) == 0) {
                        // Champion failed; replace with candidate
                        survivors.push_back(candidate);
                    } else {
                        // Both survived; keep both
                        survivors.push_back(candidate);
                        survivors.push_back(champion);
                    }
                }
            }
        }
    }

    // Collect final two pens
    vector<int> finalPens;
    finalPens.insert(finalPens.end(), pens.begin(), pens.end());
    finalPens.insert(finalPens.end(), survivors.begin(), survivors.end());

    // Report result
    cout << "1 " << finalPens[0] << " " << finalPens[1] << endl;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int testCount;
    if (cin >> testCount) {
        while (testCount--) {
            runTest();
        }
    }
    return 0;
}

