#define SOL_ALL_SAFETIES_ON 1
#include <sol/sol.hpp>
#include <string>
#include <tuple>

int main(int argc, char* argv[]) {
    sol::state lua_vm;
    lua_vm.open_libraries(sol::lib::base);

    lua_vm["process_values"] = [](int x, int y, sol::object z) {
        // Pass the object through without modification
        return std::make_tuple(x, y, z);
    };

    std::tuple<int, int, int> output1 = lua_vm["process_values"](100, 200, 300);
    const std::tuple<int, int, int> target1(100, 200, 300);
    SOL_ASSERT(output1 == target1);

    std::tuple<int, int, std::string> output2;
    output2 = lua_vm["process_values"](100, 200, std::string("MEOW MEOW MEOW!"));
    const std::tuple<int, int, std::string> target2(
        100, 200, "MEOW MEOW MEOW!");
    SOL_ASSERT(output2 == target2);

    int first, second;
    std::string third;
    sol::tie(first, second, third) = lua_vm["process_values"](100, 200, "meow");
    SOL_ASSERT(first == 100);
    SOL_ASSERT(second == 200);
    SOL_ASSERT(third == "meow");

    lua_vm.script(R"(
        p, q, r = process_values(175, 275, "hiss")
        assert(p == 175)
        assert(q == 275)
        assert(r == "hiss")
    )");

    return 0;
}

