#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    int R, H;
    cin >> R >> H; // R=75, H=1 in the official test, but we read anyway.

    // Moduli for the tests. Their sum is 30.
    vector<int> moduli = {13, 7, 5, 3, 2};

    // Send all robots at once.
    for (int m : moduli) {
        for (int remainder = 0; remainder < m; ++remainder) {
            // Collect all positions p such that p % m == remainder.
            vector<int> positions;
            for (int pos = 1; pos <= 1000; ++pos) {
                if (pos % m == remainder) {
                    positions.push_back(pos);
                }
            }
            // Output the query for this robot.
            cout << "? " << positions.size();
            for (int position : positions) {
                cout << " " << position;
            }
            cout << endl;
            cout.flush();
        }
    }

    // Wait for the results.
    cout << "@" << endl;
    cout.flush();

    int L;
    cin >> L;
    vector<int> answers(L);
    for (int i = 0; i < L; ++i) {
        cin >> answers[i];
    }

    // Decode: split answers according to the moduli.
    vector<vector<int>> positive_residues(moduli.size()); // residues with answer 1 for each modulus
    int counter = 0;
    for (int i = 0; i < moduli.size(); ++i) {
        int m = moduli[i];
        for (int r = 0; r < m; ++r) {
            if (answers[counter + r] == 1) {
                positive_residues[i].push_back(r);
            }
        }
        counter += m;
    }

    // Precompute residues for all numbers 1..1000 for each modulus.
    vector<vector<int>> num_mod(1001, vector<int>(moduli.size()));
    for (int val = 1; val <= 1000; ++val) {
        for (int i = 0; i < moduli.size(); ++i) {
            num_mod[val][i] = val % moduli[i];
        }
    }

    // Brute-force search over all unordered pairs (x,y), x <= y.
    int first_num = -1, second_num = -1;
    for (int x = 1; x <= 1000; ++x) {
        for (int y = x; y <= 1000; ++y) {
            bool valid = true;
            for (int mi = 0; mi < moduli.size(); ++mi) {
                int m = moduli[mi];
                int rx = num_mod[x][mi];
                int ry = num_mod[y][mi];

                // Check that for every residue r, (rx==r or ry==r) equals whether r is in positive_residues[mi].
                for (int r = 0; r < m; ++r) {
                    bool covered = (rx == r) || (ry == r);
                    bool expected = false;
                    for (int rr : positive_residues[mi]) {
                        if (rr == r) {
                            expected = true;
                            break;
                        }
                    }
                    if (covered != expected) {
                        valid = false;
                        break;
                    }
                }
                if (!valid) break;
            }
            if (valid) {
                first_num = x;
                second_num = y;
                break;
            }
        }
        if (first_num != -1) break;
    }

    // Output the answer.
    cout << "! " << first_num << " " << second_num << endl;
    cout.flush();
    return 0;
}

#include "llvm/Transforms/IPO/EmbedBitcodePass.h"
#include "llvm/Bitcode/BitcodeWriter.h"
#include "llvm/Bitcode/BitcodeWriterPass.h"
#include "llvm/IR/PassManager.h"
#include "llvm/Pass.h"
#include "llvm/Support/ErrorHandling.h"
#include "llvm/Support/MemoryBufferRef.h"
#include "llvm/Support/raw_ostream.h"
#include "llvm/TargetParser/Triple.h"
#include "llvm/Transforms/IPO/ThinLTOBitcodeWriter.h"
#include "llvm/Transforms/Utils/ModuleUtils.h"
#include <memory>
#include <string>

using namespace llvm;

PreservedAnalyses EmbedBitcodePass::run(Module &module, ModuleAnalysisManager &analysisMgr) {
  if (module.getGlobalVariable("llvm.embedded.module", /*AllowInternal=*/true))
    report_fatal_error("Can only embed the module once",
                       /*gen_crash_diag=*/false);

  Triple targetTriple(module.getTargetTriple());
  if (targetTriple.getObjectFormat() != Triple::ELF)
    report_fatal_error(
        "EmbedBitcode pass currently only supports ELF object format",
        /*gen_crash_diag=*/false);

  std::string bufferData;
  raw_string_ostream stream(bufferData);

  if (isThinLTO)
    ThinLTOBitcodeWriterPass(stream, /*ThinLinkOS=*/nullptr).run(module, analysisMgr);
  else
    BitcodeWriterPass(stream, /*ShouldPreserveUseListOrder=*/false, emitLTOSummary)
        .run(module, analysisMgr);

  embedBufferInModule(module, MemoryBufferRef(bufferData, "ModuleData"), ".llvm.lto");
  return PreservedAnalyses::all();
}

