#include <math.h>
#include <assert.h>
#include "PeakFinder.h"
using namespace soundtouch;
#define MAX_VAL(x, y) (((x) > (y)) ? (x) : (y))

PeakFinder::PeakFinder()
{
    lowerBound = upperBound = 0;
}

// Locates the baseline of a peak by starting from 'peakIndex' and moving in the 
// specified 'stepDirection' until the next upward trend after the lowest point starts
int PeakFinder::findBaseline(const float *signal, int peakIndex, int stepDirection) const
{
    float referenceValue;
    int minIndex;
    int currentIndex;
    int ascentCounter;
    float slope;

    ascentCounter = 0;
    referenceValue = signal[peakIndex];
    minIndex = peakIndex;
    currentIndex = peakIndex;

    while ((currentIndex > lowerBound) && (currentIndex < upperBound))
    {
        int previousIndex;
        previousIndex = currentIndex;
        currentIndex += stepDirection;

        // compute local derivative
        slope = signal[currentIndex] - signal[previousIndex];

        if (slope <= 0)
        {
            // descending segment, continue
            if (ascentCounter > 0)
            {
                ascentCounter--;  // reduce ascent counter
            }

            // check for new minimum
            if (signal[currentIndex] < referenceValue)
            {
                // update minimum
                minIndex = currentIndex;
                referenceValue = signal[currentIndex];
            }
        }
        else
        {
            // ascending segment, increment ascent counter
            ascentCounter++;
            if (ascentCounter > 5) break;    // prolonged ascent indicates next peak => exit
        }
    }
    return minIndex;
}

// Determines the index where the signal crosses a specified threshold, beginning at 
// 'peakIndex' and advancing in the given 'stepDirection'
int PeakFinder::findThresholdCrossing(const float *signal, float threshold, int peakIndex, int stepDirection) const
{
    float peakMagnitude;
    int currentIndex;

    peakMagnitude = signal[peakIndex];
    assert(peakMagnitude >= threshold);

    currentIndex = peakIndex;
    while ((currentIndex >= lowerBound) && (currentIndex < upperBound))
    {
        if (signal[currentIndex + stepDirection] < threshold) 
            return currentIndex;   // threshold crossing detected

        currentIndex += stepDirection;
    }
    return -1;  // no crossing found
}

// Computes the weighted average position (center of mass) of 'signal' values 
// between indices 'startIdx' and 'endIdx'
double PeakFinder::computeCenterOfMass(const float *signal, int startIdx, int endIdx) const
{
    int idx;
    float valueSum;
    float weightSum;

    valueSum = 0.0f;
    weightSum = 0.0f;

    for (idx = startIdx; idx <= endIdx; idx++)
    {
        valueSum += static_cast<float>(idx) * signal[idx];
        weightSum += signal[idx];
    }

    if (weightSum < 1e-6) return 0.0;
    return static_cast<double>(valueSum) / static_cast<double>(weightSum);
}

/// Estimates precise center of a peak using local center-of-mass calculation
double PeakFinder::estimatePeakCenter(const float *signal, int peakIndex) const
{
    float peakMagnitude;            // magnitude of the peak
    int crossStart, crossEnd;       // indices where the peak's hump intersects the cutoff level
    float cutoffLevel;              // threshold value for intersection
    float baselineLevel;            // baseline magnitude of the peak
    int base1, base2;               // bottom positions of the peak hump

    // locate baseline positions on both sides
    base1 = findBaseline(signal, peakIndex, -1);
    base2 = findBaseline(signal, peakIndex, 1);

    baselineLevel = MAX_VAL(signal[base1], signal[base2]);
    peakMagnitude = signal[peakIndex];

    if (baselineLevel < 1e-6) return 0.0;                // insufficient baseline => detection failure
    if ((peakMagnitude / baselineLevel) < 1.3) return 0.0;   // peak less than 30% above baseline => invalid peak

    // compute 70%-level cutoff
    cutoffLevel = 0.70f * peakMagnitude + 0.30f * baselineLevel;

    // find threshold crossings on both sides
    crossStart = findThresholdCrossing(signal, cutoffLevel, peakIndex, -1);
    crossEnd = findThresholdCrossing(signal, cutoffLevel, peakIndex, 1);

    if ((crossStart < 0) || (crossEnd < 0)) return 0.0;   // missing crossing => not a valid peak

    // compute center of mass within the identified region
    return computeCenterOfMass(signal, crossStart, crossEnd);
}

double PeakFinder::locatePeak(const float *signal, int lowLimit, int highLimit) 
{
    int i;
    int peakIndex;              // index of maximum amplitude
    double refinedPeakPos, currentPeak;

    this->lowerBound = lowLimit;
    this->upperBound = highLimit;

    // locate global maximum
    peakIndex = lowLimit;
    currentPeak = signal[lowLimit];

    for (i = lowLimit + 1; i < highLimit; i++)
    {
        if (signal[i] > currentPeak) 
        {
            currentPeak = signal[i];
            peakIndex = i;
        }
    }

    // refine position using center-of-mass method
    refinedPeakPos = estimatePeakCenter(signal, peakIndex);
    currentPeak = refinedPeakPos;

    // verify whether the strongest peak might be a harmonic of a stronger fundamental
    for (i = 2; i < 10; i++)
    {
        double candidatePeak, tempScore;
        int idx1, idx2;

        peakIndex = static_cast<int>(refinedPeakPos / static_cast<double>(i) + 0.5f);
        if (peakIndex < lowLimit) break;

        // compute center-of-mass for potential fundamental peak
        candidatePeak = estimatePeakCenter(signal, peakIndex);

        // compare with currently best peak
        idx1 = static_cast<int>(refinedPeakPos + 0.5);
        idx2 = static_cast<int>(candidatePeak + 0.5);
        tempScore = 2.0 * (signal[idx2] - signal[idx1]) / (signal[idx2] + signal[idx1]);

        if (fabs(tempScore) < 0.1)
        {
            // The dominant peak appears to be a harmonic of a nearly equal fundamental,
            // so prefer the fundamental instead
            currentPeak = candidatePeak;
        }
    }
    return currentPeak;
}

