/// Default limit on the number of uses to explore during capture analysis.
/// Chosen to keep analysis cost reasonable for clients like BasicAliasAnalysis,
/// where results may not be cached.
static cl::opt<unsigned>
    MaxUsesLimit("capture-tracking-max-uses", cl::Hidden,
                 cl::desc("Maximum number of uses to explore."),
                 cl::init(100));

unsigned llvm::getDefaultMaxUsesToExploreForCaptureTracking() {
  return MaxUsesLimit;
}

CaptureTracker::~CaptureTracker() = default;

bool CaptureTracker::shouldExplore(const Use *U) { return true; }

bool CaptureTracker::isDereferenceableOrNull(Value *O, const DataLayout &DL) {
  bool CanBeNull, CanBeFreed;
  return O->getPointerDereferenceableBytes(DL, CanBeNull, CanBeFreed);
}

namespace {

struct SimpleCaptureTracker : public CaptureTracker {
  explicit SimpleCaptureTracker(bool TrackReturns)
      : TrackReturns(TrackReturns) {}

  void tooManyUses() override {
    LLVM_DEBUG(dbgs() << "Captured due to too many uses\n");
    IsCaptured = true;
  }

  bool captured(const Use *U) override {
    if (isa<ReturnInst>(U->getUser()) && !TrackReturns)
      return false;
    LLVM_DEBUG(dbgs() << "Captured by: " << *U->getUser() << "\n");
    IsCaptured = true;
    return true;
  }

  bool TrackReturns;
  bool IsCaptured = false;
};

struct CapturesBefore : public CaptureTracker {
  CapturesBefore(bool TrackReturns, const Instruction *AtInstr,
                 const DominatorTree *DomTree, bool IncludeAtInstr,
                 const LoopInfo *LoopInfo)
      : AtInstr(AtInstr), DomTree(DomTree), TrackReturns(TrackReturns),
        IncludeAtInstr(IncludeAtInstr), LoopInfo(LoopInfo) {}

  void tooManyUses() override { IsCaptured = true; }

  bool isSafeToPrune(Instruction *Instr) {
    if (AtInstr == Instr)
      return !IncludeAtInstr;
    if (!DomTree->isReachableFromEntry(Instr->getParent()))
      return true;
    return !isPotentiallyReachable(Instr, AtInstr, nullptr, DomTree, LoopInfo);
  }

  bool captured(const Use *U) override {
    Instruction *Instr = cast<Instruction>(U->getUser());
    if (isa<ReturnInst>(Instr) && !TrackReturns)
      return false;
    if (isSafeToPrune(Instr))
      return false;
    IsCaptured = true;
    return true;
  }

  const Instruction *AtInstr;
  const DominatorTree *DomTree;
  bool TrackReturns;
  bool IncludeAtInstr;
  bool IsCaptured = false;
  const LoopInfo *LoopInfo;
};

struct EarliestCaptures : public CaptureTracker {
  EarliestCaptures(bool TrackReturns, Function &Func, const DominatorTree &DT)
      : DT(DT), TrackReturns(TrackReturns), Func(Func) {}

  void tooManyUses() override {
    IsCaptured = true;
    FirstCapture = &*Func.getEntryBlock().begin();
  }

  bool captured(const Use *U) override {
    Instruction *Instr = cast<Instruction>(U->getUser());
    if (isa<ReturnInst>(Instr) && !TrackReturns)
      return false;
    if (!FirstCapture)
      FirstCapture = Instr;
    else
      FirstCapture = DT.findNearestCommonDominator(FirstCapture, Instr);
    IsCaptured = true;
    return false;
  }

  Instruction *FirstCapture = nullptr;
  const DominatorTree &DT;
  bool TrackReturns;
  bool IsCaptured = false;
  Function &Func;
};

} // anonymous namespace

bool llvm::PointerMayBeCaptured(const Value *V, bool TrackReturns,
                                bool TrackStores, unsigned MaxUses) {
  assert(!isa<GlobalValue>(V) &&
         "It doesn't make sense to ask whether a global is captured.");
  (void)TrackStores;
  LLVM_DEBUG(dbgs() << "Captured?: " << *V << " = ");

  SimpleCaptureTracker SCT(TrackReturns);
  PointerMayBeCaptured(V, &SCT, MaxUses);

  if (SCT.IsCaptured)
    ++NumCaptured;
  else {
    ++NumNotCaptured;
    LLVM_DEBUG(dbgs() << "not captured\n");
  }

  return SCT.IsCaptured;
}

bool llvm::PointerMayBeCapturedBefore(const Value *V, bool TrackReturns,
                                      bool TrackStores, const Instruction *I,
                                      const DominatorTree *DT, bool IncludeI,
                                      unsigned MaxUses, const LoopInfo *LI) {
  assert(!isa<GlobalValue>(V) &&
         "It doesn't make sense to ask whether a global is captured.");

  if (!DT)
    return PointerMayBeCaptured(V, TrackReturns, TrackStores, MaxUses);

  CapturesBefore CB(TrackReturns, I, DT, IncludeI, LI);
  PointerMayBeCaptured(V, &CB, MaxUses);

  if (CB.IsCaptured)
    ++NumCapturedBefore;
  else
    ++NumNotCapturedBefore;

  return CB.IsCaptured;
}

Instruction *llvm::FindEarliestCapture(const Value *V, Function &F,
                                       bool TrackReturns, bool TrackStores,
                                       const DominatorTree &DT,
                                       unsigned MaxUses) {
  assert(!isa<GlobalValue>(V) &&
         "It doesn't make sense to ask whether a global is captured.");

  EarliestCaptures EC(TrackReturns, F, DT);
  PointerMayBeCaptured(V, &EC, MaxUses);

  if (EC.IsCaptured)
    ++NumCapturedBefore;
  else
    ++NumNotCapturedBefore;

  return EC.FirstCapture;
}

UseCaptureKind llvm::DetermineUseCaptureKind(
    const Use &U,
    function_ref<bool(Value *, const DataLayout &)> IsDerefOrNull) {
  Instruction *Instr = dyn_cast<Instruction>(U.getUser());

  if (!Instr)
    return UseCaptureKind::MAY_CAPTURE;

  switch (Instr->getOpcode()) {
  case Instruction::Call:
  case Instruction::Invoke: {
    auto *Call = cast<CallBase>(Instr);

    if (Call->onlyReadsMemory() && Call->doesNotThrow() &&
        Call->getType()->isVoidTy())
      return UseCaptureKind::NO_CAPTURE;

    if (isIntrinsicReturningPointerAliasingArgumentWithoutCapturing(Call, true))
      return UseCaptureKind::PASSTHROUGH;

    if (auto *MI = dyn_cast<MemIntrinsic>(Call))
      if (MI->isVolatile())
        return UseCaptureKind::MAY_CAPTURE;

    if (Call->isCallee(&U))
      return UseCaptureKind::NO_CAPTURE;

    if (Call->isDataOperand(&U) &&
        !Call->doesNotCapture(Call->getDataOperandNo(&U)))
      return UseCaptureKind::MAY_CAPTURE;

    return UseCaptureKind::NO_CAPTURE;
  }
  case Instruction::Load: {
    auto *LI = cast<LoadInst>(Instr);
    if (LI->isVolatile())
      return UseCaptureKind::MAY_CAPTURE;
    return UseCaptureKind::NO_CAPTURE;
  }
  case Instruction::VAArg:
    return UseCaptureKind::NO_CAPTURE;

  case Instruction::Store: {
    auto *SI = cast<StoreInst>(Instr);
    if (U.getOperandNo() == 0 || SI->isVolatile())
      return UseCaptureKind::MAY_CAPTURE;
    return UseCaptureKind::NO_CAPTURE;
  }
  case Instruction::AtomicRMW: {
    auto *ARMWI = cast<AtomicRMWInst>(Instr);
    if (U.getOperandNo() == 1 || ARMWI->isVolatile())
      return UseCaptureKind::MAY_CAPTURE;
    return UseCaptureKind::NO_CAPTURE;
  }
  case Instruction::AtomicCmpXchg: {
    auto *ACXI = cast<AtomicCmpXchgInst>(Instr);
    if (U.getOperandNo() == 1 || U.getOperandNo() == 2 || ACXI->isVolatile())
      return UseCaptureKind::MAY_CAPTURE;
    return UseCaptureKind::NO_CAPTURE;
  }
  case Instruction::GetElementPtr:
    if (Instr->getType()->isVectorTy())
      return UseCaptureKind::MAY_CAPTURE;
    return UseCaptureKind::PASSTHROUGH;

  case Instruction::BitCast:
  case Instruction::PHI:
  case Instruction::Select:
  case Instruction::AddrSpaceCast:
    return UseCaptureKind::PASSTHROUGH;

  case Instruction::ICmp: {
    unsigned Idx = U.getOperandNo();
    unsigned OtherIdx = 1 - Idx;
    if (auto *CPN = dyn_cast<ConstantPointerNull>(Instr->getOperand(OtherIdx))) {
      if (CPN->getType()->getAddressSpace() == 0 &&
          isNoAliasCall(U.get()->stripPointerCasts()))
        return UseCaptureKind::NO_CAPTURE;

      if (!Instr->getFunction()->nullPointerIsDefined()) {
        auto *Obj = Instr->getOperand(Idx)->stripPointerCastsSameRepresentation();
        const DataLayout &DL = Instr->getModule()->getDataLayout();
        if (IsDerefOrNull && IsDerefOrNull(Obj, DL))
          return UseCaptureKind::NO_CAPTURE;
      }
    }
    return UseCaptureKind::MAY_CAPTURE;
  }

  default:
    return UseCaptureKind::MAY_CAPTURE;
  }
}

void llvm::PointerMayBeCaptured(const Value *V, CaptureTracker *Tracker,
                                unsigned MaxUses) {
  assert(V->getType()->isPointerTy() && "Capture is for pointers only!");

  if (MaxUses == 0)
    MaxUses = getDefaultMaxUsesToExploreForCaptureTracking();

  SmallVector<const Use *, 20> Worklist;
  SmallSet<const Use *, 20> Visited;

  auto AddUses = [&](const Value *Val) {
    for (const Use &U : Val->uses()) {
      if (Visited.size() >= MaxUses) {
        Tracker->tooManyUses();
        return false;
      }
      if (!Visited.insert(&U).second)
        continue;
      if (!Tracker->shouldExplore(&U))
        continue;
      Worklist.push_back(&U);
    }
    return true;
  };

  if (!AddUses(V))
    return;

  auto IsDerefOrNull = [Tracker](Value *V, const DataLayout &DL) {
    return Tracker->isDereferenceableOrNull(V, DL);
  };

  while (!Worklist.empty()) {
    const Use *U = Worklist.pop_back_val();
    switch (DetermineUseCaptureKind(*U, IsDerefOrNull)) {
    case UseCaptureKind::NO_CAPTURE:
      continue;
    case UseCaptureKind::MAY_CAPTURE:
      if (Tracker->captured(U))
        return;
      continue;
    case UseCaptureKind::PASSTHROUGH:
      if (!AddUses(U->getUser()))
        return;
      continue;
    }
  }
}

bool llvm::isNonEscapingLocalObject(
    const Value *V, SmallDenseMap<const Value *, bool, 8> *Cache) {
  SmallDenseMap<const Value *, bool, 8>::iterator CacheIt;
  if (Cache) {
    bool Inserted;
    std::tie(CacheIt, Inserted) = Cache->insert({V, false});
    if (!Inserted)
      return CacheIt->second;
  }

  if (isIdentifiedFunctionLocal(V)) {
    bool Result = !PointerMayBeCaptured(V, false, /*StoreCaptures=*/true);
    if (Cache)
      CacheIt->second = Result;
    return Result;
  }

  return false;
}

#include "test_ffb_common.h"
#include "src/Config.h"
#include <fstream>

namespace FFBEngineTests {
TEST_CASE(test_slope_config_migration, "Regression") {
    std::cout << "Test: Slope Config Migration (Issue #104)" << std::endl;
    // 1. Create a legacy config file
    std::ofstream dataFile("legacy_slope_backup.ini");
    dataFile << "[Presets]" << std::endl;
    dataFile << "[Preset:LegacyTest]" << std::endl;
    dataFile << "slope_negative_threshold=-0.88" << std::endl; // Legacy key
    dataFile << "slope_detection_enabled=1" << std::endl;
    dataFile.close();

    // 2. Load it
    FFBEngine engine;
    // Reset to defaults first to ensure we don't have lingering state
    engine.m_slope_min_threshold = -0.3f; 

    Config::m_config_path = "legacy_slope_backup.ini";
    Config::LoadPresets(); // Should parse and migrate
    Config::ApplyPreset((int)Config::presets.size() - 1, engine); // Apply the last loaded preset (LegacyTest)

    // 3. Verify Migration
    // The legacy key should have populated the new variable
    ASSERT_NEAR(engine.m_slope_min_threshold, -0.88f, 0.001f);

    // Verify Struct
    ASSERT_NEAR(Config::presets.back().slope_min_threshold, -0.88f, 0.001f);
    std::remove("legacy_slope_backup.ini");
}

TEST_CASE(test_slope_persistence_new_key, "Regression") {
    std::cout << "Test: Slope Persistence New Key (Issue #104)" << std::endl;
    FFBEngine engine;
    engine.m_slope_min_threshold = -0.55f;
    engine.m_slope_detection_enabled = true;

    // Save to a new file
    Config::Save(engine, "slope_new_format.ini");

    // Read back manually to check keys
    std::ifstream reader("slope_new_format.ini");
    std::string record;
    bool hasNewKey = false;
    bool hasOldKey = false;

    while (std::getline(reader, record)) {
        if (record.find("slope_min_threshold=-0.55") != std::string::npos) {
            hasNewKey = true;
        }
        if (record.find("slope_negative_threshold=") != std::string::npos) {
            hasOldKey = true;
        }
    }
    reader.close();

    ASSERT_TRUE(hasNewKey);
    ASSERT_TRUE(!hasOldKey); // Should NOT write deprecated key
    std::remove("slope_new_format.ini");
}
} // namespace FFBEngineTests

