/* Autocorrelation-based LPC coefficient computation algorithm 
   originally proposed by N. Levinson (1947), later refined by J. Durbin (1959). */
/* Input : n samples of time-domain signal data
   Output: m linear prediction coefficients, residual energy */
float vorbis_lpc_from_data(float *signal,float *coefficients,int sample_count,int order){
  double *autocorr=alloca(sizeof(*autocorr)*(order+1));
  double *lpc_coeffs=alloca(sizeof(*lpc_coeffs)*(order));
  double residual_error;
  int i,j;

  /* Compute autocorrelation sequence with (order+1) lags */
  j=order+1;
  while(j--){
    double acc=0.0; /* Use double precision for accumulator to maintain accuracy */
    for(i=j;i<sample_count;i++)acc+=(double)signal[i]*signal[i-j];
    autocorr[j]=acc;
  }

  /* Derive LPC coefficients from autocorrelation values using Durbin's recursion */
  residual_error=autocorr[0];

  for(i=0;i<order;i++){
    double reflection=-autocorr[i+1];
    if(residual_error==0){
      memset(coefficients,0,order*sizeof(*coefficients));
      return 0.0f;
    }

    /* Compute reflection coefficient using partial correlation sum */
    for(j=0;j<i;j++)reflection-=lpc_coeffs[j]*autocorr[i-j];
    reflection/=residual_error; 

    /* Update LPC coefficients and error term */
    lpc_coeffs[i]=reflection;
    for(j=0;j<i/2;j++){
      double temp=lpc_coeffs[j];
      lpc_coeffs[j]+=reflection*lpc_coeffs[i-1-j];
      lpc_coeffs[i-1-j]+=reflection*temp;
    }
    if(i%2)lpc_coeffs[j]+=lpc_coeffs[j]*reflection;
    residual_error*=1.0f-reflection*reflection;
  }

  for(j=0;j<order;j++)coefficients[j]=(float)lpc_coeffs[j];

  /* Return residual energy for subsequent filter excitation */
  return residual_error;
}

void vorbis_lpc_predict(float *prediction_coeffs,float *initial_conditions,int m,
                     float *output_samples,long num_samples){
  /* in: prediction_coeffs[0...m-1] LPC analysis coefficients 
         initial_conditions[0...m-1] boundary values (buffer size n+m-1)
    out: output_samples[0...n-1] synthesized signal samples */
  long i,j,data_index,pred_index;
  float predicted_value;
  float *intermediate_buffer=alloca(sizeof(*intermediate_buffer)*(m+num_samples));

  if(!initial_conditions)
    for(i=0;i<m;i++)
      intermediate_buffer[i]=0.0f;
  else
    for(i=0;i<m;i++)
      intermediate_buffer[i]=initial_conditions[i];

  for(i=0;i<num_samples;i++){
    predicted_value=0.0f;
    data_index=i;
    pred_index=m;
    for(j=0;j<m;j++)
      predicted_value-=intermediate_buffer[data_index++]*prediction_coeffs[--pred_index];

    output_samples[i]=intermediate_buffer[data_index]=predicted_value;
  }
}

