namespace {

// System/390 convention: bit numbering starts at the left (most significant) bit as 0.
// This class helps set specific bit ranges within a byte.
class BitField {
  uint8_t Data;

  constexpr static uint8_t encodeBits(uint8_t StartBit, uint8_t Width, uint8_t Val,
                                      uint8_t PrevVal) {
    assert(StartBit < 8 && "Start bit out of range!");
    assert(StartBit + Width <= 8 && "Bit field exceeds byte boundary!");

    uint8_t Mask = ((1u << Width) - 1u) << (7u - StartBit - Width + 1u);
    uint8_t ShiftedVal = (Val << (7u - StartBit - Width + 1u)) & Mask;
    assert((ShiftedVal & Mask) == ShiftedVal && "Value too large for field!");

    return (PrevVal & ~Mask) | ShiftedVal;
  }

public:
  constexpr BitField() : Data(0) {}
  constexpr BitField(uint8_t Start, uint8_t Len, uint8_t Value)
      : Data(encodeBits(Start, Len, Value, 0)) {}

  void update(uint8_t Start, uint8_t Len, uint8_t Value) {
    Data = encodeBits(Start, Len, Value, Data);
  }

  constexpr operator uint8_t() const { return Data; }
};

// Standard record flags
constexpr uint8_t IsContinued = BitField(7, 1, 1);   // Record continues in next physical record
constexpr uint8_t IsContinuation = BitField(6, 1, 1); // This is a continuation record

// GOFFOstream handles writing logical records to fixed-size physical records.
// It manages buffering and automatic padding with zeros.
class GOFFOutputHandler : public raw_ostream {
  raw_pwrite_stream &Stream;
  size_t BytesRemaining;
#ifndef NDEBUG
  size_t PaddingSize = 0;
#endif
  uint32_t LogicalRecordCount;
  GOFF::RecordType ActiveRecordType;
  bool NewRecordStarted;
  char Buffer[GOFF::RecordContentLength];

  size_t bytesLeftInPhysical() {
    size_t remainder = BytesRemaining % GOFF::RecordContentLength;
    return remainder ? remainder : GOFF::RecordContentLength;
  }

  static void emitRecordHeader(raw_ostream &OS, GOFF::RecordType Type,
                               size_t RemainingBytes, uint8_t Flags);

  void padCurrentRecord();
  void write_data(const char *Ptr, size_t Size) override;
  uint64_t get_position() const override { return Stream.tell(); }

public:
  explicit GOFFOutputHandler(raw_pwrite_stream &OutStream)
      : Stream(OutStream), BytesRemaining(0), LogicalRecordCount(0),
        NewRecordStarted(false) {
    SetBuffer(Buffer, sizeof(Buffer));
  }

  ~GOFFOutputHandler() { finish(); }

  raw_pwrite_stream &getStream() { return Stream; }

  void beginRecord(GOFF::RecordType Type, size_t ContentSize);
  void finish() { padCurrentRecord(); }
  uint32_t getLogicalRecordCount() const { return LogicalRecordCount; }

  template<typename T>
  void writeBigEndian(T value) {
    value = support::endian::byte_swap<T>(value, endianness::big);
    write(reinterpret_cast<const char*>(&value), sizeof(T));
  }
};

void GOFFOutputHandler::emitRecordHeader(raw_ostream &OS, GOFF::RecordType Type,
                                         size_t RemainingBytes, uint8_t Flags) {
  uint8_t TypeAndFlags = Flags | (static_cast<uint8_t>(Type) << 4);
  if (RemainingBytes > GOFF::RecordLength)
    TypeAndFlags |= IsContinued;

  OS << static_cast<unsigned char>(GOFF::PTVPrefix)
     << static_cast<unsigned char>(TypeAndFlags)
     << static_cast<unsigned char>(0);
}

void GOFFOutputHandler::beginRecord(GOFF::RecordType Type, size_t Size) {
  padCurrentRecord();
  ActiveRecordType = Type;
  BytesRemaining = Size;

#ifdef NDEBUG
  size_t tempPadding;
#else
  size_t &tempPadding = PaddingSize;
#endif

  tempPadding = Size % GOFF::RecordContentLength;
  if (tempPadding != 0) {
    tempPadding = GOFF::RecordContentLength - tempPadding;
    BytesRemaining += tempPadding;
  }

  NewRecordStarted = true;
  ++LogicalRecordCount;
}

void GOFFOutputHandler::padCurrentRecord() {
  assert(GetNumBytesInBuffer() <= BytesRemaining &&
         "Buffer overflow detected");

  size_t neededPadding = BytesRemaining - GetNumBytesInBuffer();
  if (neededPadding > 0) {
    assert(neededPadding == PaddingSize && "Incorrect padding calculation");
    assert(neededPadding < GOFF::RecordLength &&
           "Attempting to pad more than one physical record");
    raw_ostream::write_zeros(neededPadding);
  }

  flush();
  assert(BytesRemaining == 0 && "Incomplete flush");
  assert(GetNumBytesInBuffer() == 0 && "Buffer not cleared");
}

void GOFFOutputHandler::write_data(const char *Ptr, size_t Size) {
  assert(Size <= BytesRemaining && "Too much data written");
  assert(BytesRemaining > 0 && "No space left in current record");

  if (BytesRemaining % GOFF::RecordContentLength == 0) {
    emitRecordHeader(Stream, ActiveRecordType, BytesRemaining,
                     NewRecordStarted ? 0 : IsContinuation);
    NewRecordStarted = false;
  }

  assert(!NewRecordStarted && "Misaligned new record start");

  size_t index = 0;
  while (Size > 0) {
    size_t chunkSize = bytesLeftInPhysical();
    if (chunkSize > Size)
      chunkSize = Size;

    Stream.write(Ptr + index, chunkSize);
    index += chunkSize;
    Size -= chunkSize;
    BytesRemaining -= chunkSize;

    if (Size > 0)
      emitRecordHeader(Stream, ActiveRecordType, BytesRemaining);
  }
}

class GOFFWriter : public MCObjectWriter {
  std::unique_ptr<MCGOFFObjectTargetWriter> TargetWriter;
  GOFFOutputHandler Output;

public:
  GOFFWriter(std::unique_ptr<MCGOFFObjectTargetWriter> TW, raw_pwrite_stream &OS)
      : TargetWriter(std::move(TW)), Output(OS) {}

  ~GOFFWriter() override {}

  void writeFileHeader();
  void writeFooter();

  void recordRelocation(MCAssembler &Asm, const MCAsmLayout &Layout,
                        const MCFragment *Fragment, const MCFixup &Fixup,
                        MCValue Target, uint64_t &FixedValue) override {}

  void executePostLayoutBinding(MCAssembler &Asm,
                                const MCAsmLayout &Layout) override {}

  uint64_t writeObject(MCAssembler &Asm, const MCAsmLayout &Layout) override;
};

} // end anonymous namespace

void GOFFWriter::writeFileHeader() {
  Output.beginRecord(GOFF::RT_HDR, /*Size=*/57);
  Output.write_zeros(1);       // Reserved
  Output.writeBigEndian<uint32_t>(0); // Target Hardware Environment
  Output.writeBigEndian<uint32_t>(0); // Target Operating System Environment
  Output.write_zeros(2);       // Reserved
  Output.writeBigEndian<uint16_t>(0); // CCSID
  Output.write_zeros(16);      // Character Set name
  Output.write_zeros(16);      // Language Product Identifier
  Output.writeBigEndian<uint32_t>(1); // Architecture Level
  Output.writeBigEndian<uint16_t>(0); // Module Properties Length
  Output.write_zeros(6);       // Reserved
}

void GOFFWriter::writeFooter() {
  uint8_t Flags = GOFF::END_EPR_None;
  uint8_t AddressingMode = 0;
  uint32_t ESDIdentifier = 0;
  // TODO: Populate entry point info.

  Output.beginRecord(GOFF::RT_END, /*Size=*/13);
  Output.writeBigEndian<uint8_t>(BitField(6, 2, Flags)); // Indicator flags
  Output.writeBigEndian<uint8_t>(AddressingMode);        // AMODE
  Output.write_zeros(3);                                 // Reserved
  Output.writeBigEndian<uint32_t>(0);                    // Record Count (zeroed per spec)
  Output.writeBigEndian<uint32_t>(ESDIdentifier);        // ESDID of entry point
  Output.finish();
}

uint64_t GOFFWriter::writeObject(MCAssembler &Asm, const MCAsmLayout &Layout) {
  uint64_t InitialOffset = Output.getStream().tell();
  writeFileHeader();
  writeFooter();
  LLVM_DEBUG(dbgs() << "Wrote " << Output.getLogicalRecordCount()
                    << " logical records.\n");
  return Output.getStream().tell() - InitialOffset;
}

std::unique_ptr<MCObjectWriter>
llvm::createGOFFObjectWriter(std::unique_ptr<MCGOFFObjectTargetWriter> MOTW,
                             raw_pwrite_stream &OS) {
  return std::make_unique<GOFFWriter>(std::move(MOTW), OS);
}

