#include "xdelta3_wrapper.h"
#include <stdlib.h>
#include <string.h>
extern "C"
{
    /**
    * Modified command line handler for xdelta operations.
    * First argument should represent the program name (e.g., "xdelta").
    **/
    int xd3_main_cmdline(int arg_count, char** arg_values);
    extern void (*message_output_func)(const char* text);
}
static std::string _output_buffer;
static void custom_print(const char* text) {
    _output_buffer.append(text);
}
std::string get_xd3_messages()
{
    return _output_buffer;
}
int run_xd3_command(const std::vector<std::string>& arguments)
{
    char** argv = new char* [arguments.size() + 2];
    argv[0] = new char[8] {'x', 'd', 'e', 'l', 't', 'a', '3', '\0'};
    int index = 1;
    for (const auto& item : arguments)
    {
        size_t length = item.length() + 1;
        argv[index] = new char[length];
        std::copy(item.begin(), item.end(), argv[index]);
        argv[index][length - 1] = '\0';
        index++;
    }
    argv[index] = nullptr;
    message_output_func = &custom_print;
    _output_buffer.clear();
    int result = xd3_main_cmdline(index, argv);
    message_output_func = nullptr;
    for (int i = 0; i < index; i++)
    {
        delete[] argv[i];
    }
    delete[] argv;
    return result;
}

#include <iostream>
#include <vector>
#include <bitset>
using namespace std;

// Fixed string length
const int LEN = 1000;

// Gaussian elimination basis: each row corresponds to a pivot position
bitset<LEN> gauss_basis[LEN];
int rhs_values[LEN];
bool pivot_exists[LEN];
int solution_bits[LEN];

void process() {
    int input_n;
    // Read N (though fixed at 1000)
    if (!(cin >> input_n)) return;

    // Reset pivot tracking
    for (int idx = 0; idx < LEN; ++idx) {
        pivot_exists[idx] = false;
    }

    // Seeded random number generator (deterministic seed)
    mt19937 prng(5489);
    int equations_collected = 0;

    // Collect enough independent equations to solve for all bits
    while (equations_collected < LEN) {
        // Random modulus in range [40, 51]
        int mod_val = 40 + (prng() % 12);

        // Generate random mask of length mod_val
        vector<int> mask(mod_val);
        for (int k = 0; k < mod_val; ++k) {
            mask[k] = prng() % 2;
        }

        // Build equation vector based on mask
        bitset<LEN> eq_vec;
        for (int pos = 0; pos < LEN; ++pos) {
            if (mask[pos % mod_val]) {
                eq_vec.set(pos);
            }
        }

        // Check linear independence and find pivot
        bitset<LEN> temp_vec = eq_vec;
        int pivot_pos = -1;

        for (int row = 0; row < LEN; ++row) {
            if (temp_vec.test(row)) {
                if (pivot_exists[row]) {
                    temp_vec ^= gauss_basis[row];
                } else {
                    pivot_pos = row;
                    break;
                }
            }
        }

        // If pivot found, proceed with query
        if (pivot_pos != -1) {
            int num_states = 2 * mod_val;

            // Send query indicator
            cout << "1" << endl;

            // Build transition tables
            vector<int> trans_0(num_states), trans_1(num_states);
            for (int state = 0; state < num_states; ++state) {
                int pos_mod = state % mod_val;
                int parity_bit = state / mod_val;
                int next_pos = (pos_mod + 1) % mod_val;

                // Input '0' does not change parity
                trans_0[state] = next_pos + parity_bit * mod_val;

                // Input '1' flips parity if mask[pos_mod] == 1
                int new_parity = parity_bit ^ mask[pos_mod];
                trans_1[state] = next_pos + new_parity * mod_val;
            }

            // Output transition data
            cout << num_states;
            for (int t : trans_0) cout << " " << t;
            for (int t : trans_1) cout << " " << t;
            cout << endl;

            // Read final state from judge
            int end_state;
            cin >> end_state;

            // Determine observed parity
            int observed_parity = (end_state >= mod_val) ? 1 : 0;

            // Update system with new equation
            int current_rhs = observed_parity;
            temp_vec = eq_vec;
            for (int r = 0; r < LEN; ++r) {
                if (temp_vec.test(r)) {
                    if (pivot_exists[r]) {
                        temp_vec ^= gauss_basis[r];
                        current_rhs ^= rhs_values[r];
                    } else {
                        // Store new basis vector and RHS
                        gauss_basis[r] = temp_vec;
                        rhs_values[r] = current_rhs;
                        pivot_exists[r] = true;
                        equations_collected++;
                        break;
                    }
                }
            }
        }
    }

    // Back-substitution to determine solution bits
    for (int i = LEN - 1; i >= 0; --i) {
        int val = rhs_values[i];
        for (int j = i + 1; j < LEN; ++j) {
            if (gauss_basis[i].test(j)) {
                val ^= solution_bits[j];
            }
        }
        solution_bits[i] = val;
    }

    // Output final guess
    cout << "0" << endl;
    for (int i = 0; i < LEN; ++i) {
        cout << solution_bits[i];
    }
    cout << endl;
}

int main() {
    process();
    return 0;
}

