#include "binder/bound_statement_visitor.h"
#include "binder/bound_explain.h"
#include "binder/copy/bound_copy_from.h"
#include "binder/copy/bound_copy_to.h"
#include "binder/query/bound_regular_query.h"
#include "common/cast.h"

using namespace lbug::common;

namespace lbug {
namespace binder {

void BoundStatementVisitor::process(const BoundStatement& stmt) {
    switch (stmt.getStatementType()) {
    case StatementType::QUERY: {
        processRegularQuery(stmt);
    } break;
    case StatementType::CREATE_SEQUENCE: {
        processCreateSequence(stmt);
    } break;
    case StatementType::DROP: {
        processDrop(stmt);
    } break;
    case StatementType::CREATE_TABLE: {
        processCreateTable(stmt);
    } break;
    case StatementType::CREATE_TYPE: {
        processCreateType(stmt);
    } break;
    case StatementType::ALTER: {
        processAlter(stmt);
    } break;
    case StatementType::COPY_FROM: {
        processCopyFrom(stmt);
    } break;
    case StatementType::COPY_TO: {
        processCopyTo(stmt);
    } break;
    case StatementType::STANDALONE_CALL: {
        processStandaloneCall(stmt);
    } break;
    case StatementType::EXPLAIN: {
        processExplain(stmt);
    } break;
    case StatementType::CREATE_MACRO: {
        processCreateMacro(stmt);
    } break;
    case StatementType::TRANSACTION: {
        processTransaction(stmt);
    } break;
    case StatementType::EXTENSION: {
        processExtension(stmt);
    } break;
    case StatementType::EXPORT_DATABASE: {
        processExportDatabase(stmt);
    } break;
    case StatementType::IMPORT_DATABASE: {
        processImportDatabase(stmt);
    } break;
    case StatementType::ATTACH_DATABASE: {
        processAttachDatabase(stmt);
    } break;
    case StatementType::DETACH_DATABASE: {
        processDetachDatabase(stmt);
    } break;
    case StatementType::USE_DATABASE: {
        processUseDatabase(stmt);
    } break;
    case StatementType::CREATE_GRAPH: {
        processCreateGraph(stmt);
    } break;
    case StatementType::USE_GRAPH: {
        processUseGraph(stmt);
    } break;
    case StatementType::STANDALONE_CALL_FUNCTION: {
        processStandaloneCallFunction(stmt);
    } break;
    case StatementType::EXTENSION_CLAUSE: {
        processExtensionClause(stmt);
    } break;
    default:
        UNREACHABLE_CODE;
    }
}

void BoundStatementVisitor::processUnsafe(BoundStatement& stmt) {
    switch (stmt.getStatementType()) {
    case StatementType::QUERY: {
        processRegularQueryUnsafe(stmt);
    } break;
    default:
        break;
    }
}

void BoundStatementVisitor::processCopyFrom(const BoundStatement& stmt) {
    auto& copyFrom = dynamic_cast_checked<const BoundCopyFrom&>(stmt);
    if (copyFrom.getInfo()->source->type == ScanSourceType::QUERY) {
        auto querySource =
            dynamic_cast_checked<BoundQueryScanSource*>(copyFrom.getInfo()->source.get());
        process(*querySource->statement);
    }
}

void BoundStatementVisitor::processCopyTo(const BoundStatement& stmt) {
    auto& copyTo = dynamic_cast_checked<const BoundCopyTo&>(stmt);
    processRegularQuery(*copyTo.getRegularQuery());
}

void BoundStatementVisitor::processRegularQuery(const BoundStatement& stmt) {
    auto& regularQuery = dynamic_cast_checked<const BoundRegularQuery&>(stmt);
    for (auto idx = 0u; idx < regularQuery.getNumSingleQueries(); ++idx) {
        processSingleQuery(*regularQuery.getSingleQuery(idx));
    }
}

void BoundStatementVisitor::processRegularQueryUnsafe(BoundStatement& stmt) {
    auto& regularQuery = stmt.cast<BoundRegularQuery>();
    for (auto idx = 0u; idx < regularQuery.getNumSingleQueries(); ++idx) {
        processSingleQueryUnsafe(*regularQuery.getSingleQueryUnsafe(idx));
    }
}

void BoundStatementVisitor::processSingleQuery(const NormalizedSingleQuery& singleQuery) {
    for (auto idx = 0u; idx < singleQuery.getNumQueryParts(); ++idx) {
        processQueryPart(*singleQuery.getQueryPart(idx));
    }
}

void BoundStatementVisitor::processSingleQueryUnsafe(NormalizedSingleQuery& singleQuery) {
    for (auto idx = 0u; idx < singleQuery.getNumQueryParts(); ++idx) {
        processQueryPartUnsafe(*singleQuery.getQueryPartUnsafe(idx));
    }
}

void BoundStatementVisitor::processQueryPart(const NormalizedQueryPart& queryPart) {
    for (auto idx = 0u; idx < queryPart.getNumReadingClause(); ++idx) {
        processReadingClause(*queryPart.getReadingClause(idx));
    }
    for (auto idx = 0u; idx < queryPart.getNumUpdatingClause(); ++idx) {
        processUpdatingClause(*queryPart.getUpdatingClause(idx));
    }
    if (queryPart.hasProjectionBody()) {
        processProjectionBody(*queryPart.getProjectionBody());
        if (queryPart.hasProjectionBodyPredicate()) {
            processProjectionBodyPredicate(queryPart.getProjectionBodyPredicate());
        }
    }
}

void BoundStatementVisitor::processQueryPartUnsafe(NormalizedQueryPart& queryPart) {
    for (auto idx = 0u; idx < queryPart.getNumReadingClause(); ++idx) {
        processReadingClauseUnsafe(*queryPart.getReadingClause(idx));
    }
    for (auto idx = 0u; idx < queryPart.getNumUpdatingClause(); ++idx) {
        processUpdatingClause(*queryPart.getUpdatingClause(idx));
    }
    if (queryPart.hasProjectionBody()) {
        processProjectionBody(*queryPart.getProjectionBody());
        if (queryPart.hasProjectionBodyPredicate()) {
            processProjectionBodyPredicate(queryPart.getProjectionBodyPredicate());
        }
    }
}

void BoundStatementVisitor::processExplain(const BoundStatement& stmt) {
    process(*(stmt.constCast<BoundExplain>()).getStatementToExplain());
}

void BoundStatementVisitor::processReadingClause(const BoundReadingClause& readingClause) {
    switch (readingClause.getClauseType()) {
    case ClauseType::MATCH: {
        processMatch(readingClause);
    } break;
    case ClauseType::UNWIND: {
        processUnwind(readingClause);
    } break;
    case ClauseType::TABLE_FUNCTION_CALL: {
        processTableFunctionCall(readingClause);
    } break;
    case ClauseType::LOAD_FROM: {
        processLoadFrom(readingClause);
    } break;
    default:
        UNREACHABLE_CODE;
    }
}

void BoundStatementVisitor::processReadingClauseUnsafe(BoundReadingClause& readingClause) {
    switch (readingClause.getClauseType()) {
    case ClauseType::MATCH: {
        processMatchUnsafe(readingClause);
    } break;
    case ClauseType::UNWIND: {
        processUnwind(readingClause);
    } break;
    case ClauseType::TABLE_FUNCTION_CALL: {
        processTableFunctionCall(readingClause);
    } break;
    case ClauseType::LOAD_FROM: {
        processLoadFrom(readingClause);
    } break;
    default:
        UNREACHABLE_CODE;
    }
}

void BoundStatementVisitor::processUpdatingClause(const BoundUpdatingClause& updatingClause) {
    switch (updatingClause.getClauseType()) {
    case ClauseType::SET: {
        processSet(updatingClause);
    } break;
    case ClauseType::DELETE_: {
        processDelete(updatingClause);
    } break;
    case ClauseType::INSERT: {
        processInsert(updatingClause);
    } break;
    case ClauseType::MERGE: {
        processMerge(updatingClause);
    } break;
    default:
        UNREACHABLE_CODE;
    }
}

} // namespace binder
} // namespace lbug

#include "llvm/Demangle/Demangle.h"
#include "llvm/Demangle/StringViewExtras.h"
#include "llvm/Demangle/Utility.h"
#include <cctype>
#include <cstring>
#include <limits>
#include <string_view>

using namespace llvm;
using llvm::itanium_demangle::OutputBuffer;
using llvm::itanium_demangle::starts_with;

namespace {
/// Demangler structure for D language symbol demangling.
struct DDemangler {
  /// Initialize the demangler with the mangled string.
  ///
  /// \param Mangled String to demangle.
  DDemangler(std::string_view Mangled);

  /// Extract and demangle the mangled symbol and append it to the output buffer.
  ///
  /// \param Demangled Output buffer to write the demangled name.
  /// \return The remaining string on success or nullptr on failure.
  const char *demangleSymbol(OutputBuffer *Demangled);

private:
  /// Internal helper to parse mangled symbol.
  void demangleSymbol(OutputBuffer *Demangled, std::string_view &Mangled);

  /// Decode a numeric value from the mangled string.
  ///
  /// \param Mangled Input string view (modified on success/failure).
  /// \param Ret Output numeric value.
  void decodeNumber(std::string_view &Mangled, unsigned long &Ret);

  /// Decode a back-reference position.
  ///
  /// \param Mangled Input string view (modified on success/failure).
  /// \param Ret Computed position offset.
  /// \return true if decoding succeeded.
  bool decodeBackrefPos(std::string_view &Mangled, long &Ret);

  /// Decode a full back-reference.
  ///
  /// \param Mangled Input string view (modified on success/failure).
  /// \param Ret Reference to the resolved string view.
  /// \return true if decoding succeeded.
  bool decodeBackref(std::string_view &Mangled, std::string_view &Ret);

  /// Parse an identifier back-reference.
  void parseIdentifierBackref(OutputBuffer *Demangled, std::string_view &Mangled);

  /// Parse a type back-reference.
  void parseTypeBackref(std::string_view &Mangled);

  /// Check if current position starts a valid symbol name.
  bool isSymbolName(std::string_view Mangled);

  /// Parse and demangle an identifier.
  void parseIdentifier(OutputBuffer *Demangled, std::string_view &Mangled);

  /// Parse a length-prefixed literal name.
  void parseLName(OutputBuffer *Demangled, std::string_view &Mangled, unsigned long Len);

  /// Parse qualified names (e.g., module.Class.function).
  void parseQualified(OutputBuffer *Demangled, std::string_view &Mangled);

  /// Parse a type encoding.
  bool parseType(std::string_view &Mangled);

  /// Immutable view of the original mangled string.
  const std::string_view SourceStr;

  /// Track last back-reference position to prevent infinite recursion.
  int LastBackrefIndex;
};
} // namespace

void DDemangler::decodeNumber(std::string_view &Mangled, unsigned long &Ret) {
  if (Mangled.empty() || !std::isdigit(Mangled.front())) {
    Mangled = {};
    return;
  }

  unsigned long Val = 0;
  do {
    unsigned long Digit = Mangled[0] - '0';
    if (Val > (std::numeric_limits<unsigned int>::max() - Digit) / 10) {
      Mangled = {};
      return;
    }
    Val = Val * 10 + Digit;
    Mangled.remove_prefix(1);
  } while (!Mangled.empty() && std::isdigit(Mangled.front()));

  if (Mangled.empty()) {
    Mangled = {};
    return;
  }
  Ret = Val;
}

bool DDemangler::decodeBackrefPos(std::string_view &Mangled, long &Ret) {
  if (Mangled.empty() || !std::isalpha(Mangled.front())) {
    Mangled = {};
    return false;
  }

  unsigned long Val = 0;
  while (!Mangled.empty() && std::isalpha(Mangled.front())) {
    if (Val > (std::numeric_limits<unsigned long>::max() - 25) / 26)
      break;
    Val *= 26;
    if (Mangled[0] >= 'a' && Mangled[0] <= 'z') {
      Val += Mangled[0] - 'a';
      if ((long)Val <= 0)
        break;
      Ret = Val;
      Mangled.remove_prefix(1);
      return true;
    }
    Val += Mangled[0] - 'A';
    Mangled.remove_prefix(1);
  }

  Mangled = {};
  return false;
}

bool DDemangler::decodeBackref(std::string_view &Mangled, std::string_view &Ret) {
  assert(!Mangled.empty() && Mangled.front() == 'Q' && "Invalid back reference!");
  Ret = {};

  const char *Qpos = Mangled.data();
  long RefPos;
  Mangled.remove_prefix(1);

  if (!decodeBackrefPos(Mangled, RefPos)) {
    Mangled = {};
    return false;
  }

  if (RefPos > Qpos - SourceStr.data()) {
    Mangled = {};
    return false;
  }

  Ret = Qpos - RefPos;
  return true;
}

void DDemangler::parseIdentifierBackref(OutputBuffer *Demangled, std::string_view &Mangled) {
  unsigned long Len;
  std::string_view Backref;

  if (!decodeBackref(Mangled, Backref)) {
    Mangled = {};
    return;
  }

  decodeNumber(Backref, Len);
  if (Backref.empty() || Backref.length() < Len) {
    Mangled = {};
    return;
  }

  parseLName(Demangled, Backref, Len);
  if (Backref.empty())
    Mangled = {};
}

void DDemangler::parseTypeBackref(std::string_view &Mangled) {
  if (Mangled.data() - SourceStr.data() >= LastBackrefIndex) {
    Mangled = {};
    return;
  }

  int SaveRefPos = LastBackrefIndex;
  LastBackrefIndex = Mangled.data() - SourceStr.data();

  std::string_view Backref;
  if (!decodeBackref(Mangled, Backref)) {
    Mangled = {};
    return;
  }

  if (Backref.empty() || !parseType(Backref))
    Mangled = {};

  LastBackrefIndex = SaveRefPos;
  if (Backref.empty())
    Mangled = {};
}

bool DDemangler::isSymbolName(std::string_view Mangled) {
  long Ret;
  const char *Qref = Mangled.data();

  if (std::isdigit(Mangled.front()))
    return true;

  if (Mangled.front() != 'Q')
    return false;

  Mangled.remove_prefix(1);
  bool Valid = decodeBackrefPos(Mangled, Ret);
  if (!Valid || Ret > Qref - SourceStr.data())
    return false;

  return std::isdigit(Qref[-Ret]);
}

void DDemangler::demangleSymbol(OutputBuffer *Demangled, std::string_view &Mangled) {
  Mangled.remove_prefix(2); // Skip "_D"
  parseQualified(Demangled, Mangled);

  if (Mangled.empty()) {
    Mangled = {};
    return;
  }

  if (Mangled.front() == 'Z') {
    Mangled.remove_prefix(1);
  } else if (!parseType(Mangled)) {
    Mangled = {};
  }
}

void DDemangler::parseQualified(OutputBuffer *Demangled, std::string_view &Mangled) {
  size_t NotFirst = false;
  do {
    if (!Mangled.empty() && Mangled.front() == '0') {
      do
        Mangled.remove_prefix(1);
      while (!Mangled.empty() && Mangled.front() == '0');
      continue;
    }

    if (NotFirst)
      *Demangled << '.';
    NotFirst = true;

    parseIdentifier(Demangled, Mangled);
  } while (!Mangled.empty() && isSymbolName(Mangled));
}

void DDemangler::parseIdentifier(OutputBuffer *Demangled, std::string_view &Mangled) {
  if (Mangled.empty()) {
    Mangled = {};
    return;
  }

  if (Mangled.front() == 'Q')
    return parseIdentifierBackref(Demangled, Mangled);

  unsigned long Len;
  decodeNumber(Mangled, Len);

  if (Mangled.empty() || !Len || Mangled.length() < Len) {
    Mangled = {};
    return;
  }

  if (Len >= 4 && starts_with(Mangled, "__S")) {
    const size_t SuffixLen = Mangled.length() - Len;
    std::string_view P = Mangled.substr(3);
    while (P.length() > SuffixLen && std::isdigit(P.front()))
      P.remove_prefix(1);
    if (P.length() == SuffixLen) {
      Mangled.remove_prefix(Len);
      return parseIdentifier(Demangled, Mangled);
    }
  }

  parseLName(Demangled, Mangled, Len);
}

bool DDemangler::parseType(std::string_view &Mangled) {
  if (Mangled.empty()) {
    Mangled = {};
    return false;
  }

  switch (Mangled.front()) {
  case 'i':
    Mangled.remove_prefix(1);
    return true;
  case 'Q': {
    parseTypeBackref(Mangled);
    return true;
  }
  default:
    Mangled = {};
    return false;
  }
}

void DDemangler::parseLName(OutputBuffer *Demangled, std::string_view &Mangled,
                            unsigned long Len) {
  switch (Len) {
  case 6:
    if (starts_with(Mangled, "__initZ")) {
      Demangled->prepend("initializer for ");
      Demangled->setCurrentPosition(Demangled->getCurrentPosition() - 1);
      Mangled.remove_prefix(Len);
      return;
    }
    if (starts_with(Mangled, "__vtblZ")) {
      Demangled->prepend("vtable for ");
      Demangled->setCurrentPosition(Demangled->getCurrentPosition() - 1);
      Mangled.remove_prefix(Len);
      return;
    }
    break;
  case 7:
    if (starts_with(Mangled, "__ClassZ")) {
      Demangled->prepend("ClassInfo for ");
      Demangled->setCurrentPosition(Demangled->getCurrentPosition() - 1);
      Mangled.remove_prefix(Len);
      return;
    }
    break;
  case 11:
    if (starts_with(Mangled, "__InterfaceZ")) {
      Demangled->prepend("Interface for ");
      Demangled->setCurrentPosition(Demangled->getCurrentPosition() - 1);
      Mangled.remove_prefix(Len);
      return;
    }
    break;
  case 12:
    if (starts_with(Mangled, "__ModuleInfoZ")) {
      Demangled->prepend("ModuleInfo for ");
      Demangled->setCurrentPosition(Demangled->getCurrentPosition() - 1);
      Mangled.remove_prefix(Len);
      return;
    }
    break;
  }

  *Demangled << Mangled.substr(0, Len);
  Mangled.remove_prefix(Len);
}

DDemangler::DDemangler(std::string_view Mangled)
    : SourceStr(Mangled), LastBackrefIndex(Mangled.length()) {}

const char *DDemangler::demangleSymbol(OutputBuffer *Demangled) {
  std::string_view M(this->SourceStr);
  demangleSymbol(Demangled, M);
  return M.data();
}

char *llvm::dlangDemangle(std::string_view MangledName) {
  if (MangledName.empty() || !starts_with(MangledName, "_D"))
    return nullptr;

  OutputBuffer Demangled;
  if (MangledName == "_Dmain") {
    Demangled << "D main";
  } else {
    DDemangler D(MangledName);
    const char *M = D.demangleSymbol(&Demangled);
    if (M == nullptr || *M != '\0') {
      std::free(Demangled.getBuffer());
      return nullptr;
    }
  }

  if (Demangled.getCurrentPosition() > 0) {
    Demangled << '\0';
    Demangled.setCurrentPosition(Demangled.getCurrentPosition() - 1);
    return Demangled.getBuffer();
  }

  std::free(Demangled.getBuffer());
  return nullptr;
}

