struct FuncRenamerPass : public impl::HACCRenameFunctionBase<FuncRenamerPass> {
public:
  void runOnOperation() override;
};

void FuncRenamerPass::runOnOperation() {
  auto module = getOperation();
  module->walk([&](func::FuncOp funcOp) {
    auto renameAttr =
        funcOp->getAttrOfType<hacc::RenameFuncAttr>(hacc::RenameFuncAttr::name);
    if (!renameAttr)
      return;

    auto targetName = renameAttr.getTargetName();
    if (targetName.name.empty()) {
      funcOp.emitOpError() << "invalid target function name: " << targetName;
      signalPassFailure();
      return;
    }

    // Ensure no other function already uses the target name
    auto existingFunc = SymbolTable::lookupNearestSymbolFrom(funcOp, targetName);
    if (existingFunc) {
      funcOp.emitOpError()
          << "cannot rename function to @" << targetName.getValue()
          << " since another function with that name already exists!";
      signalPassFailure();
      return;
    }

    // Replace all symbol references to the old name
    if (failed(SymbolTable::replaceAllSymbolUses(funcOp.getSymNameAttr(),
                                                 targetName.getAttr(), module))) {
      funcOp.emitOpError() << "failed to update symbol references during renaming!";
      signalPassFailure();
      return;
    }

    // Apply the new name and remove the renaming attribute
    funcOp->removeAttr(hacc::RenameFuncAttr::name);
    funcOp.setSymName(targetName.getAttr());
  });
}

std::unique_ptr<Pass> mlir::hacc::createRenameFuncPass() {
  return std::make_unique<FuncRenamerPass>();
}

