#include <gtest/gtest.h>
using namespace Valdi;
namespace ValdiTest {
TEST(AutoMalloc, doesNotAllocateIfCapacityIsSufficient) {
    AutoMalloc<int, 8> buffer(4);
    ASSERT_FALSE(buffer.allocated());
    ASSERT_TRUE(buffer.get() != nullptr);
    for (size_t idx = 0; idx < 4; idx++) {
        buffer.get()[idx] = 100;
    }
    for (size_t idx = 0; idx < 4; idx++) {
        ASSERT_EQ(static_cast<int>(100), buffer.get()[idx]);
    }
}
TEST(AutoMalloc, allocatesMemoryWhenCapacityIsInsufficient) {
    AutoMalloc<int, 8> buffer(16);
    ASSERT_TRUE(buffer.allocated());
    ASSERT_TRUE(buffer.get() != nullptr);
    for (size_t idx = 0; idx < 16; idx++) {
        buffer.get()[idx] = 100;
    }
    for (size_t idx = 0; idx < 16; idx++) {
        ASSERT_EQ(static_cast<int>(100), buffer.get()[idx]);
    }
}
TEST(AutoMalloc, supportsResizing) {
    AutoMalloc<int, 8> buffer;
    ASSERT_FALSE(buffer.allocated());
    ASSERT_TRUE(buffer.get() == nullptr);
    buffer.resize(4);
    ASSERT_FALSE(buffer.allocated());
    ASSERT_TRUE(buffer.get() != nullptr);
    auto* originalPtr = buffer.get();
    buffer.resize(16);
    ASSERT_TRUE(buffer.allocated());
    ASSERT_TRUE(buffer.get() != nullptr);
    ASSERT_NE(originalPtr, buffer.get());
    originalPtr = buffer.get();
    buffer.resize(15);
    ASSERT_TRUE(buffer.allocated());
    ASSERT_EQ(originalPtr, buffer.get());
    buffer.resize(14);
    ASSERT_TRUE(buffer.allocated());
    ASSERT_EQ(originalPtr, buffer.get());
}
