void helper_func() {
    std::cout << "helper function!" << std::endl;
}

void another_helper() {
    std::cout << "another helper function!" << std::endl;
}

struct helper_class {
    int value = 42;
    double compute_value() {
        return 15.75;
    }
};

int main(int, char*[]) {
    std::cout << "=== functions (all) ===" << std::endl;
    sol::state lua_vm;
    lua_vm.open_libraries(sol::lib::base);

    // put an instance of "helper_class" into lua
    // (we'll go into more detail about this later
    // just know here that it works and is
    // put into lua as a userdata
    lua_vm.set("hc", helper_class());

    // binds a plain function
    lua_vm["h1"] = helper_func;
    lua_vm.set_function("h2", &another_helper);

    // binds just the member function
    lua_vm["c1"] = &helper_class::compute_value;

    // binds the class to the type
    lua_vm.set_function(
         "c2", &helper_class::compute_value, helper_class {});

    // binds just the member variable as a function
    lua_vm["p1"] = &helper_class::value;

    // binds class with member variable as function
    lua_vm.set_function(
         "p2", &helper_class::value, helper_class {});

    lua_vm.script(R"(
    h1() -- helper function!
    h2() -- another helper function!

    -- need class instance if you don't bind it with the function
    print(c1(hc)) -- 15.75
    -- does not need class instance: was bound to lua with one 
    print(c2()) -- 15.75

    -- need class instance if you 
    -- don't bind it with the function
    print(p1(hc)) -- 42
    -- does not need class instance: 
    -- it was bound with one 
    print(p2()) -- 42
    -- can set, still 
    -- requires instance
    p1(hc, 100)
    -- can set, does not need 
    -- class instance: was bound with one 
    p2(200)
    print(p1(hc)) -- 100
    print(p2()) -- 200
    )");

    std::cout << std::endl;
    return 0;
}

