// Convert ASCII digit to hex value
unsigned char charToHex(char ch) {
    if (0x61 <= ch && ch <= 0x66) {
        return ch - 0x61 + 0xa;
    } else if (0x41 <= ch && ch <= 0x46) {
        return ch - 0x41 + 0xa;
    } else {
        return ch - 0x30;
    }
}

// Parse 16-byte hex string into binary output
void parseHex16(const char *input, unsigned char *output) {
    const char *src = input;
    unsigned int val;
    for (int idx = 0; idx < 0x10; idx++, src += 2) {
        val = charToHex(src[1]) + (charToHex(src[0]) << 4);
        *output++ = val;
    }
}

// Simple LCG-based PRNG
long pseudoRandom(long seed) {
    static long state = 0xEB;
    if (seed != 0)
        state = seed;
    state = state * 0x19660E + 0x3C6EF35F;
    return state;
}

// Check endianness and perform byte swap on 32-bit value
#define ENDIAN_CHECK(ptr, val) (*(((unsigned char *)(ptr)) + 3) == (val))
#define SWAP_BYTES_32(v)                                                                 \
    do {                                                                                 \
        unsigned char t0, t1;                                                            \
        t0 = *((unsigned char *)(v) + 0);                                                \
        t1 = *((unsigned char *)(v) + 3);                                                \
        *((unsigned char *)(v) + 0) = t1;                                                \
        *((unsigned char *)(v) + 3) = t0;                                                \
        t0 = *((unsigned char *)(v) + 1);                                                \
        t1 = *((unsigned char *)(v) + 2);                                                \
        *((unsigned char *)(v) + 1) = t1;                                                \
        *((unsigned char *)(v) + 2) = t0;                                                \
    } while (0)

// Generate masher key using PRNG
void KeyChain::generateMasher(unsigned char *buffer) {
    unsigned int *masher_ptr = reinterpret_cast<unsigned int *>(buffer);
    unsigned int test_val = 1;
    bool is_big_endian = ENDIAN_CHECK(&test_val, 1);

    for (int i = 0; i < 8; i++) {
        *masher_ptr = pseudoRandom((i == 0) ? 0xEB : 0);
        if (is_big_endian) {
            SWAP_BYTES_32(masher_ptr);
        }
        masher_ptr++;
    }
}

// XOR two buffers of 8 uint32 values
void xorBuffers(unsigned char *buf1, unsigned char *buf2) {
    unsigned int *ui1 = reinterpret_cast<unsigned int *>(buf1);
    unsigned int *ui2 = reinterpret_cast<unsigned int *>(buf2);
    for (int i = 0; i < 8; i++) {
        ui1[i] ^= ui2[i];
    }
}

// Circular left shift by 19 bits modulo 32
int rotateLeft(int value) {
    value += 19;
    value %= 32;
    return value;
}

// Swap two characters
void exchangeChars(char &first, char &second) {
    char temp = first;
    first = second;
    second = temp;
}

// Shuffle operations on character buffer
void shuffleA(char *buffer) {
    for (int i = 0; i < 8; i++) {
        exchangeChars(buffer[rotateLeft(i * 4)], buffer[i * 4 + 2]);
        exchangeChars(buffer[rotateLeft(i * 4 + 3)], buffer[i * 4 + 1]);
    }
}

void shuffleB(char *buffer) {
    for (int i = 0; i < 8; i++) {
        exchangeChars(buffer[(7 - i) * 4 + 1], buffer[i * 4 + 2]);
        exchangeChars(buffer[(7 - i) * 4], buffer[i * 4 + 3]);
    }
}

void shuffleC(char *buffer) {
    for (int i = 0; i < 8; i++) {
        exchangeChars(buffer[rotateLeft((7 - i) * 4 + 1)], buffer[i * 4 + 2]);
        exchangeChars(buffer[(7 - i) * 4], buffer[i * 4 + 3]);
    }
}

void shuffleD(char *buffer) {
    for (int i = 0; i < 8; i++) {
        exchangeChars(buffer[(7 - i) * 4 + 1], buffer[i * 4 + 2]);
        exchangeChars(buffer[rotateLeft((7 - i) * 4)], buffer[i * 4 + 3]);
    }
}

void shuffleE(char *buffer) {
    for (int i = 0; i < 8; i++) {
        exchangeChars(buffer[(7 - i) * 4 + 1], buffer[rotateLeft(i * 4 + 2)]);
        exchangeChars(buffer[(7 - i) * 4], buffer[i * 4 + 3]);
    }
}

void shuffleF(char *buffer) {
    for (int i = 0; i < 8; i++) {
        exchangeChars(buffer[(7 - i) * 4 + 1], buffer[i * 4 + 2]);
        exchangeChars(buffer[(7 - i) * 4], buffer[rotateLeft(i * 4 + 3)]);
    }
}

// Apply all shuffles in sequence
void applyFullShuffle(char *buffer) {
    shuffleA(buffer);
    shuffleB(buffer);
    shuffleC(buffer);
    shuffleD(buffer);
    shuffleE(buffer);
    shuffleF(buffer);
}

// Dummy function to increase analysis difficulty
void dummyCounter() {
    static int callCount = 0;
    callCount++;
}

// Safe memory copy with dummy calls inserted
void secureCopy(unsigned char *dest, const unsigned char *src, unsigned int size) {
    for (unsigned int i = 0; i < size; i++) {
        dummyCounter();
        dest[i] = src[i];
    }
}

// Reveal key by shuffling and XORing
void deriveKey(long *keyBuffer, unsigned char *mask) {
    for (int i = 0; i < 0xE; i++) {
        applyFullShuffle(reinterpret_cast<char *>(keyBuffer));
    }
    xorBuffers(reinterpret_cast<unsigned char *>(keyBuffer), mask);
}

// Extract key from hidden storage
void extractKey(unsigned char *source, char *temp, unsigned char *mask) {
    deriveKey(reinterpret_cast<long *>(source), mask);
    secureCopy(reinterpret_cast<unsigned char *>(temp), source, 0x20);
}

// Public interface to get a specific key
void KeyChain::extractKeyAt(unsigned int index, unsigned char *output1, unsigned char *output2) {
    unsigned char intermediate[32];
    char tempBuffer[32];
    secureCopy(intermediate, &secretData[index * 0x20], 0x20);
    extractKey(intermediate, tempBuffer, output2);
    parseHex16(tempBuffer, output1);
}

// Return number of available keys
unsigned int KeyChain::countKeys() { return 0xC; }

