// Disjoint Set Union with union-by-size and path compression
struct DSU {
    std::vector<int> parent;
    std::vector<int> size;
    int num_components;

    DSU(int n) {
        parent.resize(n);
        std::iota(parent.begin(), parent.end(), 0);
        size.assign(n, 1);
        num_components = n;
    }

    DSU(const DSU& other) = default;

    int find(int x) {
        if (parent[x] == x)
            return x;
        return parent[x] = find(parent[x]);
    }

    void merge(int x, int y) {
        int root_x = find(x);
        int root_y = find(y);
        if (root_x != root_y) {
            if (size[root_x] < size[root_y]) 
                std::swap(root_x, root_y);
            parent[root_y] = root_x;
            size[root_x] += size[root_y];
            num_components--;
        }
    }
};

struct Coordinate {
    int x_coord, y_coord;
};

struct Connection {
    int node_a, node_b;
    int weight; // Rounded Euclidean distance
};

// Edge in the component graph
struct GraphEdge {
    int comp_u, comp_v; // component roots
    double cost;         // estimated weight
    bool operator<(const GraphEdge& other) const {
        return cost < other.cost;
    }
};

double compute_distance(const Coordinate& a, const Coordinate& b) {
    long long diff_x = a.x_coord - b.x_coord;
    long long diff_y = a.y_coord - b.y_coord;
    return std::sqrt(static_cast<double>(diff_x * diff_x + diff_y * diff_y));
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    const int TOTAL_POINTS = 400;
    const int TOTAL_CONNECTIONS = 1995;

    std::vector<Coordinate> points(TOTAL_POINTS);
    for (int idx = 0; idx < TOTAL_POINTS; ++idx) {
        std::cin >> points[idx].x_coord >> points[idx].y_coord;
    }

    std::vector<Connection> connections(TOTAL_CONNECTIONS);
    for (int idx = 0; idx < TOTAL_CONNECTIONS; ++idx) {
        std::cin >> connections[idx].node_a >> connections[idx].node_b;
        connections[idx].weight = static_cast<int>(std::round(compute_distance(points[connections[idx].node_a], points[connections[idx].node_b])));
    }

    DSU dsu(TOTAL_POINTS);

    for (int step = 0; step < TOTAL_CONNECTIONS; ++step) {
        int threshold;
        std::cin >> threshold;

        int a = connections[step].node_a;
        int b = connections[step].node_b;
        int root_a = dsu.find(a);
        int root_b = dsu.find(b);

        if (root_a == root_b) {
            std::cout << 0 << '\n';
            continue;
        }

        // Dynamically adjust beta based on progress
        double progress = static_cast<double>(step) / (TOTAL_CONNECTIONS - 1);
        double beta = 1.4 + 1.6 * progress * progress;

        std::vector<GraphEdge> candidate_edges;
        if (step < TOTAL_CONNECTIONS - 1) {
            candidate_edges.reserve(TOTAL_CONNECTIONS - 1 - step);
        }

        for (int next_idx = step + 1; next_idx < TOTAL_CONNECTIONS; ++next_idx) {
            int ra = dsu.find(connections[next_idx].node_a);
            int rb = dsu.find(connections[next_idx].node_b);
            if (ra != rb) {
                candidate_edges.push_back({ra, rb, beta * connections[next_idx].weight});
            }
        }

        std::sort(candidate_edges.begin(), candidate_edges.end());

        double min_path_weight = 1e18; // Effectively infinity

        if (!candidate_edges.empty()) {
            DSU temp_dsu = dsu;
            for (const auto& edge : candidate_edges) {
                if (temp_dsu.find(edge.comp_u) != temp_dsu.find(edge.comp_v)) {
                    temp_dsu.merge(edge.comp_u, edge.comp_v);
                    if (temp_dsu.find(root_a) == temp_dsu.find(root_b)) {
                        min_path_weight = edge.cost;
                        break;
                    }
                }
            }
        }

        if (static_cast<double>(threshold) < min_path_weight) {
            std::cout << 1 << '\n';
            dsu.merge(a, b);
        } else {
            std::cout << 0 << '\n';
        }
    }

    return 0;
}

