namespace {
constexpr int server_port = 19021;

bool send_message(const std::shared_ptr<dap::Writer>& writer, const std::string& message) {
  return writer->write(message.data(), message.size()) && writer->write("\0", 1);
}

std::string receive_message(const std::shared_ptr<dap::Reader>& reader) {
  char buffer_char;
  std::string received_string;
  while (reader->read(&buffer_char, sizeof(buffer_char)) > 0) {
    if (buffer_char == '\0') {
      return received_string;
    }
    received_string += buffer_char;
  }
  return reader->isOpen() ? "<read failed>" : "<stream closed>";
}
}  // anonymous namespace

TEST(Network, ClientServerCommunication) {
  dap::Chan<bool> completion_flag;
  auto server_instance = dap::net::Server::create();

  if (!server_instance->start(
          server_port,
          [&](const std::shared_ptr<dap::ReaderWriter>& rw) {
            ASSERT_EQ(receive_message(rw), "client to server");
            ASSERT_TRUE(send_message(rw, "server to client"));
            completion_flag.put(true);
          },
          [&](const char* error_msg) { FAIL() << "Server error: " << error_msg; })) {
    FAIL() << "Couldn't start server";
    return;
  }

  for (int iteration = 0; iteration < 5; iteration++) {
    auto client_connection = dap::net::connect("localhost", server_port);
    ASSERT_NE(client_connection, nullptr) << "Failed to connect client " << iteration;
    ASSERT_TRUE(send_message(client_connection, "client to server"));
    ASSERT_EQ(receive_message(client_connection), "server to client");
    completion_flag.take();
    std::this_thread::sleep_for(std::chrono::seconds(1));
  }

  server_instance.reset();
}

TEST(Network, ServerRestartFunctionality) {
  dap::Chan<bool> completion_flag;
  auto on_client_connect = [&](const std::shared_ptr<dap::ReaderWriter>& rw) {
    ASSERT_EQ(receive_message(rw), "client to server");
    ASSERT_TRUE(send_message(rw, "server to client"));
    completion_flag.put(true);
  };

  auto on_server_error = [&](const char* error_msg) { FAIL() << "Server error: " << error_msg; };

  auto server = dap::net::Server::create();

  if (!server->start(server_port, on_client_connect, on_server_error)) {
    FAIL() << "Couldn't start server";
    return;
  }

  server->stop();
  server->stop();
  server->stop();

  if (!server->start(server_port, on_client_connect, on_server_error)) {
    FAIL() << "Couldn't restart server";
    return;
  }

  auto client = dap::net::connect("localhost", server_port);
  ASSERT_NE(client, nullptr) << "Failed to connect";
  ASSERT_TRUE(send_message(client, "client to server"));
  ASSERT_EQ(receive_message(client), "server to client");
  completion_flag.take();

  server->stop();
  server->stop();
  server->stop();
  server.reset();
}

