// Vertex Shader Source Code - Modified wave function and variable names
const char* vertexShaderSource = R"(
#version 330 core
layout(location = 0) in vec3 position;
layout(location = 1) in vec2 texCoords;

out vec2 surfaceTexCoord;

uniform mat4 modelMatrix;
uniform mat4 viewMatrix;
uniform mat4 projMatrix;
uniform float elapsedTime;

void main()
{
    // Calculate wave displacement using different frequency combinations
    float verticalDisplacement = 0.15 * sin(6.0 * position.x + 1.5 * elapsedTime) + 
                                 0.03 * sin(9.0 * position.x + 2.5 * elapsedTime);
    vec3 adjustedPosition = position + vec3(0.0, verticalDisplacement, 0.0);

    gl_Position = projMatrix * viewMatrix * modelMatrix * vec4(adjustedPosition, 1.0);
    surfaceTexCoord = texCoords;
}
)";

// Fragment Shader Source Code - Slightly modified lighting calculations
const char* fragmentShaderSource = R"(
#version 330 core
in vec2 surfaceTexCoord;

out vec4 outputColor;

uniform sampler2D waterSurfaceTexture;
uniform vec3 lightDirection;
uniform vec3 cameraPosition;

void main()
{
    vec4 baseColor = texture(waterSurfaceTexture, surfaceTexCoord);

    // Simplified normal vector for the water surface
    vec3 surfaceNormal = normalize(vec3(0.0, 1.0, 0.0));

    // Compute lighting components
    vec3 directionToLight = normalize(lightDirection - vec3(0.0, 0.0, 0.0));
    vec3 directionToCamera = normalize(cameraPosition - vec3(0.0, 0.0, 0.0));

    float diffuseIntensity = max(dot(surfaceNormal, directionToLight), 0.0);
    vec3 reflectedLight = reflect(-directionToLight, surfaceNormal);
    float specularIntensity = pow(max(dot(directionToCamera, reflectedLight), 0.0), 24.0);

    vec3 finalColor = (diffuseIntensity + 0.25 * specularIntensity) * baseColor.rgb;

    outputColor = vec4(finalColor, 1.0);
}
)";

int main()
{
    // Initialize GLFW library
    if (!glfwInit())
    {
        std::cerr << "Error: Failed to initialize GLFW" << std::endl;
