#include <cmath>
#include <cassert>

class PrimeHandler {
public:
    // Check if a number is prime using an alternative approach
    bool isPrime(int n) {
        if (n <= 1) return false;
        if (n == 2) return true;
        if (n % 2 == 0) return false;

        // Check odd divisors up to sqrt(n)
        int limit = static_cast<int>(std::sqrt(n));
        for (int i = 3; i <= limit; i += 2) {
            if (n % i == 0) return false;
        }
        return true;
    }

    // Generate a list of prime numbers up to a certain number
    std::vector<int> generatePrimes(int maxVal) {
        std::vector<int> primes;
        for (int candidate = 2; candidate <= maxVal; ++candidate) {
            if (isPrime(candidate)) {
                primes.push_back(candidate);
            }
        }
        return primes;
    }

    // Find the nth prime number using a different counting strategy
    int nthPrime(int position) {
        if (position <= 0) return -1; // Invalid input

        int foundCount = 0;
        int currentNum = 2;

        while (foundCount < position) {
            if (isPrime(currentNum)) {
                foundCount++;
                if (foundCount == position) {
                    return currentNum;
                }
            }
            currentNum++;
        }
        return -1; // Should never reach here for valid inputs
    }
};

// Function to test the PrimeHandler class with modified assertions
void testPrimeHandler() {
    PrimeHandler handler;

    // Test isPrime functionality
    assert(handler.isPrime(2) == true);
    assert(handler.isPrime(3) == true);
    assert(handler.isPrime(4) == false);
    assert(handler.isPrime(5) == true);
    assert(handler.isPrime(17) == true);
    assert(handler.isPrime(18) == false);

    // Test generatePrimes functionality
    std::vector<int> primesUpTo10 = handler.generatePrimes(10);
    std::vector<int> expectedPrimes = {2, 3, 5, 7};
    assert(primesUpTo10.size() == expectedPrimes.size());
