void encrypt_chars(int length, char EKey)
{
    int index = 0;
    char current_char;

    while (index < length)
    {
        current_char = OChars[index];
        __asm
        {
            push ebx
            push edx

            movzx edx, current_char
            push edx
            lea ebx, EKey
            push ebx
            call encrypt4
            add esp, 8
            mov current_char, al

            pop edx
            pop ebx
        }
        EChars[index] = current_char;
        index++;
    }
}

