// 128-bit unsigned integer structure with 16-byte alignment
typedef struct __attribute__((aligned(16))) {
    uint64_t low_part;
    uint64_t high_part;
} uint128_value;

// Compare-and-swap implementation for 128-bit values using inline assembly
template<>
inline bool compare_and_swap(volatile uint128_value *target, 
                             uint128_value expected, 
                             uint128_value desired) {
    uint64_t exp_low = expected.low_part;
    uint64_t exp_high = expected.high_part;
    uint64_t new_low = desired.low_part;
    uint64_t new_high = desired.high_part;
    unsigned char success_flag = 0;

    __asm__ __volatile__ (
        "lock cmpxchg16b %2\n\t"
        "setz %0\n\t"
        : "=q" (success_flag), "+m" (*target)
        : "a" (exp_low), "d" (exp_high), "b" (new_low), "c" (new_high)
        : "cc", "memory"
    );

    return static_cast<bool>(success_flag);
}

