// Custom stream buffer implementation for managed streams
public ref class ManagedBuffer : public std::streambuf
{
public:
    ManagedBuffer(System::IO::Stream^ ioStream)
    {
        managedStream = ioStream;
        setp(internalBuffer, internalBuffer + sizeof(internalBuffer) - 1);
    }

    ~ManagedBuffer()
    {
        flush();
    }

protected:
    int overflow(int ch) override
    {
        if (ch != traits_type::eof())
        {
            internalBuffer[pptr() - pbase()] = static_cast<char>(ch);
            if (flush() == -1)
            {
                return traits_type::eof();
            }
        }
        return ch;
    }

    int flush() override
    {
        if (pptr() > pbase())
        {
            pin_ptr<unsigned char> pinnedPtr = &internalBuffer[0];
            array<unsigned char>^ managedArray = gcnew array<unsigned char>(pptr() - pbase());
            System::Runtime::InteropServices::Marshal::Copy(IntPtr(pinnedPtr), managedArray, 0, managedArray->Length);
            managedStream->Write(managedArray, 0, managedArray->Length);
            pbump(-static_cast<int>(managedArray->Length));
        }
        return 0;
    }

private:
    System::IO::Stream^ managedStream;
    unsigned char internalBuffer[1024];
};

