// Perform bubble sort on the vector in ascending order
void bubbleSort(std::vector<int> &arr) {
    int n = arr.size();
    bool changed;
    for (int pass = 0; pass < n - 1; ++pass) {
        changed = false;
        for (int index = 0; index < n - pass - 1; ++index) {
            if (arr[index] > arr[index + 1]) {
                int temp = arr[index];
                arr[index] = arr[index + 1];
                arr[index + 1] = temp;
                changed = true;
            }
        }
        if (!changed) break;
    }
}

