#define MATRIX_SIZE 1024
#define THREADS_PER_BLOCK 32

// Parallel merge operation for two sorted subarrays
__device__ void mergeSegments(int* data, int left, int mid, int right) {
    int i = left;
    int j = mid + 1;
    int k = 0;

    // Temporary storage for merged result
    __shared__ int temp[THREADS_PER_BLOCK * 2];

    // Merge the two halves into temporary array
    while (i <= mid && j <= right) {
        if (data[i] <= data[j]) {
            temp[k++] = data[i++];
        } else {
            temp[k++] = data[j++];
        }
    }

    // Copy remaining elements from left half
    while (i <= mid) {
        temp[k++] = data[i++];
    }

    // Copy remaining elements from right half
    while (j <= right) {
        temp[k++] = data[j++];
    }

    // Copy merged elements back to original array
    for (int idx = 0; idx < k; idx++) {
        data[left + idx] = temp[idx];
    }
}

// Kernel to perform parallel segment merging
__global__ void mergeKernel(int* data, int width, int segmentSize) {
    int row = blockIdx.x * blockDim.x + threadIdx.x;
    if (row < width / segmentSize) {
        int left = row * segmentSize;
        int mid = left + segmentSize / 2 - 1;
        int right = left + segmentSize - 1;

        if (mid < width && right < width) {
            mergeSegments(data, left, mid, right);
        }
    }
}

// Kernel to initialize segments as single elements (trivially sorted)
__global__ void initKernel(int* data, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        // No operation needed - data is already loaded
    }
}

// Helper function to check if array is sorted
bool verifySorted(int* data, int size) {
    for (int i = 0; i < size - 1; i++) {
        if (data[i] > data[i + 1])
            return false;
    }
    return true;
}

int main() {
    const int totalElements = MATRIX_SIZE * MATRIX_SIZE;

    /* Initialize device */
    int deviceID = 0;
    cudaDeviceProp deviceProperties;
    cudaGetDeviceProperties(&deviceProperties, deviceID);
    printf("Using Device %d: %s\n", deviceID, deviceProperties.name);
    cudaSetDevice(deviceID);

    // Read input data from binary file
    FILE* input = fopen("/content/datSeq1M.bin", "rb");
    int* hostArray = (int*)malloc(totalElements * sizeof(int));
    fseek(input, sizeof(int), SEEK_SET); // Skip first integer
    fread(hostArray, sizeof(int), totalElements, input);
    fclose(input);

    // Print first few elements before sorting
    for (int i = 0; i < 11; i++) {
        printf("%d ", hostArray[i]);
    }
    printf("\n");

    // Allocate GPU memory
    int* deviceArray;
    cudaMalloc((void**)&deviceArray, totalElements * sizeof(int));

    // Transfer data to GPU
    cudaMemcpy(deviceArray, hostArray, totalElements * sizeof(int), cudaMemcpyHostToDevice);

    // Launch sorting kernels using iterative merge sort
    int currentSegmentSize = 1;
    int numElements = totalElements;

    while (currentSegmentSize < numElements) {
        int nextSegmentSize = currentSegmentSize * 2;
        int threadsPerBlock = THREADS_PER_BLOCK;
        int blocksPerGrid = (numElements / nextSegmentSize) + ((numElements % nextSegmentSize) ? 1 : 0);

        // Launch merge kernel for current segment size
        mergeKernel<<<blocksPerGrid, threadsPerBlock>>>(deviceArray, numElements, nextSegmentSize);
        cudaDeviceSynchronize();
        cudaGetLastError();

        currentSegmentSize = nextSegmentSize;
    }

    // Copy sorted data back to host
    cudaMemcpy(hostArray, deviceArray, totalElements * sizeof(int), cudaMemcpyDeviceToHost);

    // Verify sorting result
    bool isSorted = verifySorted(hostArray, totalElements);

    // Print first few elements after sorting
    for (int i = 0; i < 11; i++) {
        printf("%d ", hostArray[i]);
    }
    printf("\n");

    // Output verification result
    if (isSorted) {
        printf("The array is ordered.\n");
    } else {
        printf("The array is not ordered.\n");
    }

    // Cleanup resources
    cudaFree(deviceArray);
    free(hostArray);

    return 0;
}

