    // Allocate and initialize input data (simulating indata)
    std::complex<float>* indata = new std::complex<float>[W];
    for (int i = 0; i < W; ++i) {
        indata[i] = std::complex<float>(static_cast<float>(i % 10), static_cast<float>((i * 3) % 7));
    }

    // Output buffer for our custom IFFT implementation
    std::complex<float>* outdata = new std::complex<float>[W];

    // Custom inverse DFT implementation (simplified, not optimized)
    for (int k = 0; k < W; ++k) {
        std::complex<float> sum(0.0f, 0.0f);
        for (int n = 0; n < W; ++n) {
            float angle = 2.0f * 3.14159265359f * static_cast<float>(n * k) / static_cast<float>(W);
