// MyDomTraversal.cpp
#include "MyDomTraversal.h"
#include <mshtml.h>

void ExploreDocumentStructure(IHTMLDocument2* pDoc) {
    if (!pDoc) return;

    IHTMLElementCollection* pBodyElements = nullptr;
    HRESULT hr = pDoc->get_body(&pBodyElements);
    if (FAILED(hr) || !pBodyElements) return;

    long elementCount = 0;
    pBodyElements->get_length(&elementCount);

    std::vector<IHTMLDOMNode*> nodeStack;
    for (long idx = 0; idx < elementCount; ++idx) {
        IHTMLDOMNode* currentNode = nullptr;
        pBodyElements->item(idx, &currentNode);
        if (!currentNode) continue;

        nodeStack.push_back(currentNode);

        while (!nodeStack.empty()) {
            IHTMLDOMNode* current = nodeStack.back();
            nodeStack.pop_back();

            // Extract and print text content if available
            BSTR rawText = nullptr;
            if (SUCCEEDED(current->get_nodeValue(&rawText)) && rawText) {
                wprintf(L"Text Node: %s\n", rawText);
                SysFreeString(rawText);
            }

            // Push children onto stack in reverse order so leftmost child is processed first
            IHTMLDOMNode* child = nullptr;
            if (SUCCEEDED(current->get_firstChild(&child)) && child) {
                std::vector<IHTMLDOMNode*> tempChildren;
                while (child) {
                    tempChildren.push_back(child);
                    IHTMLDOMNode* sibling = nullptr;
                    child->get_nextSibling(&sibling);
                    child->Release();
                    child = sibling;
                }
                // Reverse to maintain original order when pushing to stack
                for (auto it = tempChildren.rbegin(); it != tempChildren.rend(); ++it) {
                    nodeStack.push_back(*it);
                }
            }

            current->Release();
        }
    }

    pBodyElements->Release();
}

