// Compute a * b + c using fused multiply-add and convert to float
float test_1(const double &a, const double &b, const double &c) {
    // Use std::fma for accurate fused multiply-add operation
    double temp = std::fma(a, b, c);
    // Convert the result to a 64-bit floating point value in an SSE register,
    // then extract it as a 32-bit float
    return _mm_cvtsd_f32(_mm_set_sd(temp));
}

// Alternative implementation using explicit multiplication and addition
float test_2(const double &a, const double &b, const double &c) {
    // Perform the computation with potential rounding at each step
    double intermediate = a * b;
    double result = intermediate + c;
    // Convert final result to single precision float
    return _mm_cvtsd_f32(_mm_set_sd(result));
}

#include <immintrin.h>

// Transpose a 4x4 matrix of 32-bit integers using AVX-512 instructions
void transpose_4x4_zmm(__m512i& row0, __m512i& row1, __m512i& row2, __m512i& row3) {
    // First stage: shuffle within pairs of rows to interleave elements
    __m512i temp0 = _mm512_shuffle_i32x4(row0, row1, 0x44);
    __m512i temp1 = _mm512_shuffle_i32x4(row0, row1, 0xEE);
    __m512i temp2 = _mm512_shuffle_i32x4(row2, row3, 0x44);
    __m512i temp3 = _mm512_shuffle_i32x4(row2, row3, 0xEE);

    // Second stage: use variable permutation to combine shuffled results
    // The index vector selects elements from the two source vectors to form transposed rows
    __m512i indices = _mm512_setr_epi32(0, 4, 1, 5, 2, 6, 3, 7, 8, 12, 9, 13, 10, 14, 11, 15);

    row0 = _mm512_permutex2var_epi32(temp0, indices, temp2);
    row1 = _mm512_permutex2var_epi32(temp0, indices, temp3);
    row2 = _mm512_permutex2var_epi32(temp1, indices, temp2);
    row3 = _mm512_permutex2var_epi32(temp1, indices, temp3);
}

