// Determine if a number is prime using an alternative approach
bool checkPrime(int value) {
    // Handle edge cases: numbers less than 2 are not prime
    if (value < 2) {
        return false;
    }

    // Special case for 2 and 3
    if (value == 2 || value == 3) {
        return true;
    }

    // Eliminate even numbers and multiples of 3
    if (value % 2 == 0 || value % 3 == 0) {
        return false;
    }

    // Check odd divisors from 5 up to sqrt(value)
    // Using a different loop structure with decrementing counter
    int limit = static_cast<int>(std::sqrt(value));
    int divisor = 5;

    while (divisor <= limit) {
        // Test both divisor and divisor + 2 (which covers the pattern 5,7,11,13,...)
        if (value % divisor == 0 || value % (divisor + 2) == 0) {
            return false;
        }
        divisor += 6;
    }

    return true;
}

int main() {
    int testValue;
    std::cout << "Enter a number to check if it's prime: ";
    std::cin >> testValue;

    if (checkPrime(testValue)) {
        std::cout << testValue << " is a prime number.\n";
    } else {
        std::cout << testValue << " is not a prime number.\n";
    }

    return 0;
}

#include <atomic>
#include <cassert>

// Shared atomic variables for inter-thread communication
std::atomic<int> flag_a{0};
std::atomic<int> flag_b{0};

// First execution context - sets first flag
void thread_one() {
    flag_a.store(1, std::memory_order_release);
}

// Second execution context - sets second flag  
void thread_two() {
    flag_b.store(1, std::memory_order_release);
}

// Third execution context - checks specific ordering
void thread_three() {
    // Verify first flag is set while second remains unset
    assert(flag_a.load(std::memory_order_acquire) == 1 && 
           flag_b.load(std::memory_order_acquire) == 0);
}

// Fourth execution context - checks opposite ordering
void thread_four() {
    // Verify second flag is set while first remains unset
    assert(flag_b.load(std::memory_order_acquire) == 1 && 
           flag_a.load(std::memory_order_acquire) == 0);
}

