struct InsertInlineAsmPass : public FunctionPass {
  static char ID; // Pass identification, replacement for typeid
  InsertInlineAsmPass() : FunctionPass(ID) {}

  bool runOnFunction(Function &F) override {
    // Position the builder at the start of the entry block
    BasicBlock *entryBlock = &F.getEntryBlock();
    IRBuilder<> Builder(entryBlock, entryBlock->begin());

    // Define inline assembly string and constraints
    StringRef asmCode = "bswap $0";
    StringRef constraintStr = "=r,r";

    // Set up function type for inline assembly
    LLVMContext &ctx = F.getContext();
    Type *int32Ty = Type::getInt32Ty(ctx);
    std::vector<Type*> paramTypes;
    paramTypes.push_back(int32Ty);
    FunctionType *asmFuncType = FunctionType::get(int32Ty, paramTypes, false);

    // Construct the InlineAsm object
    InlineAsm *inlineAsm = InlineAsm::get(asmFuncType, asmCode, constraintStr, 
                                          /*hasSideEffects=*/false, 
                                          /*isAlignStack=*/false);

    // Prepare argument: constant integer value 1234
    ConstantInt *inputVal = ConstantInt::get(int32Ty, 1234);

    // Insert call instruction with result name
    CallInst *resultCall = Builder.CreateCall(inlineAsm, inputVal, "bswap_result");

    return true; // Indicate that the function was modified
  }
};

