// Find the maximum element in a vector using manual iteration
int findMax(const std::vector<int>& arr) {
    if (arr.empty()) {
        return -1;  // Return -1 for empty vector as sentinel value
    }

    int currentMax = arr[0];
    for (size_t i = 1; i < arr.size(); ++i) {
        if (arr[i] > currentMax) {
            currentMax = arr[i];
        }
    }
    return currentMax;
}

