    int tid = blockIdx.x * blockDim.x + threadIdx.x;

    // Validate thread is within bounds (adjusted for 0-based indexing)
    if (tid >= total) return;

    // Process only valid indices with proper boundary handling
    if (tid < total - 1) {
        float base_val = values[tid];

        // Iterate through remaining elements using post-increment
        int j = tid + 1;
        while (j < total) {
            float diff = values[j] - base_val;
            float squared = diff * diff;

            // Check threshold condition
            if (squared < 10.0f) {
                // Atomically store the computed value
                atomicExch(&newvalues[j], squared);
            }

            j++;
        }
    }
}

