// Forward declaration of the original function
Eigen::MatrixXd computeMatrix(const LineArray& lines);

// Alternative wrapper that converts Eigen matrix to nested vector
vector<vector<double>> matrix_converter(const LineArray& input_lines) {
    Eigen::MatrixXd computed = computeMatrix(input_lines);
    size_t row_count = computed.rows();
    size_t col_count = computed.cols();

    vector<vector<double>> output(row_count, vector<double>(col_count));

    for (size_t r = 0; r < row_count; ++r) {
        for (size_t c = 0; c < col_count; ++c) {
            output[r][c] = computed(r, c);
        }
    }

    return output;
}

