// Optimized pixel blending function using SIMD and OpenMP
void blendImages(const uint8_t* inputFrame, const uint8_t* overlayFrame, uint8_t* outputFrame, int width, int height) {
    int totalPixels = width * height;
    int alignedChunk = totalPixels - (totalPixels % 16); // Process in blocks of 16 pixels

    __m128i zeroVec = _mm_setzero_si128(); // All-zero vector for alpha comparison

    #pragma omp parallel for
    for (int idx = 0; idx < alignedChunk; idx += 16) {
        // Load four consecutive RGBA vectors (each 16 bytes)
        __m128i rgbaBlock0 = _mm_loadu_si128(reinterpret_cast<const __m128i*>(overlayFrame + idx * 4));
        __m128i rgbaBlock1 = _mm_loadu_si128(reinterpret_cast<const __m128i*>(overlayFrame + idx * 4 + 16));
        __m128i rgbaBlock2 = _mm_loadu_si128(reinterpret_cast<const __m128i*>(overlayFrame + idx * 4 + 32));
        __m128i rgbaBlock3 = _mm_loadu_si128(reinterpret_cast<const __m128i*>(overlayFrame + idx * 4 + 48));

        // Extract alpha channels: replicate the 4th byte of each pixel across the whole lane
        __m128i alpha0 = _mm_shuffle_epi32(rgbaBlock0, _MM_SHUFFLE(3,3,3,3));
        __m128i alpha1 = _mm_shuffle_epi32(rgbaBlock1, _MM_SHUFFLE(3,3,3,3));
        __m128i alpha2 = _mm_shuffle_epi32(rgbaBlock2, _MM_SHUFFLE(3,3,3,3));
        __m128i alpha3 = _mm_shuffle_epi32(rgbaBlock3, _MM_SHUFFLE(3,3,3,3));

        // Create masks: 0xFF where alpha == 0, 0x00 otherwise
        __m128i mask0 = _mm_cmpeq_epi8(alpha0, zeroVec);
        __m128i mask1 = _mm_cmpeq_epi8(alpha1, zeroVec);
        __m128i mask2 = _mm_cmpeq_epi8(alpha2, zeroVec);
        __m128i mask3 = _mm_cmpeq_epi8(alpha3, zeroVec);

        // Load corresponding RGB source data (3 bytes per pixel, unaligned)
        __m128i srcBlock0 = _mm_loadu_si128(reinterpret_cast<const __m128i*>(inputFrame + idx * 3));
        __m128i srcBlock1 = _mm_loadu_si128(reinterpret_cast<const __m128i*>(inputFrame + idx * 3 + 16));
        __m128i srcBlock2 = _mm_loadu_si128(reinterpret_cast<const __m128i*>(inputFrame + idx * 3 + 32));
        __m128i srcBlock3 = _mm_loadu_si128(reinterpret_cast<const __m128i*>(inputFrame + idx * 3 + 48));

        // Blend logic: if mask is set (alpha==0), keep source; else use overlay
        __m128i outBlock0 = _mm_or_si128(
            _mm_andnot_si128(mask0, rgbaBlock0),
            _mm_and_si128(mask0, srcBlock0)
        );
        __m128i outBlock1 = _mm_or_si128(
            _mm_andnot_si128(mask1, rgbaBlock1),
            _mm_and_si128(mask1, srcBlock1)
        );
        __m128i outBlock2 = _mm_or_si128(
            _mm_andnot_si128(mask2, rgbaBlock2),
            _mm_and_si128(mask2, srcBlock2)
        );
        __m128i outBlock3 = _mm_or_si128(
            _mm_andnot_si128(mask3, rgbaBlock3),
            _mm_and_si128(mask3, srcBlock3)
        );

        // Store results to destination buffer
        _mm_storeu_si128(reinterpret_cast<__m128i*>(outputFrame + idx * 3), outBlock0);
        _mm_storeu_si128(reinterpret_cast<__m128i*>(outputFrame + idx * 3 + 16), outBlock1);
        _mm_storeu_si128(reinterpret_cast<__m128i*>(outputFrame + idx * 3 + 32), outBlock2);
        _mm_storeu_si128(reinterpret_cast<__m128i*>(outputFrame + idx * 3 + 48), outBlock3);
    }

    // Handle remaining pixels that don't fit into 16-pixel chunks
    for (int p = alignedChunk; p < totalPixels; ++p) {
        if (overlayFrame[p * 4 + 3] == 0) {
            outputFrame[p * 3]     = inputFrame[p * 3];
            outputFrame[p * 3 + 1] = inputFrame[p * 3 + 1];
            outputFrame[p * 3 + 2] = inputFrame[p * 3 + 2];
        } else {
            outputFrame[p * 3]     = overlayFrame[p * 4];
            outputFrame[p * 3 + 1] = overlayFrame[p * 4 + 1];
            outputFrame[p * 3 + 2] = overlayFrame[p * 4 + 2];
        }
    }
}

// High-resolution timer helper
uint64_t getCurrentTimeMicros() {
    timeval currentTime;
    gettimeofday(&currentTime, nullptr);
    return static_cast<uint64_t>(currentTime.tv_sec) * 1000000ULL + 
           static_cast<uint64_t>(currentTime.tv_usec);
}

int main(int argc, char** argv) {
    const int FRAME_WIDTH = 1920;
    const int FRAME_HEIGHT = 1080;
    const int RGB_SIZE = FRAME_WIDTH * FRAME_HEIGHT * 3;

    // Allocate aligned memory for performance
    uint8_t* overlayData = new uint8_t[FRAME_WIDTH * FRAME_HEIGHT * 4];
    uint8_t* sourceData = new uint8_t[RGB_SIZE];
    uint8_t* resultData = new uint8_t[RGB_SIZE];

    uint64_t startTime = getCurrentTimeMicros();

    // Run benchmark loop
    for (int iter = 0; iter < 1000; ++iter) {
        blendImages(sourceData, overlayData, resultData, FRAME_WIDTH, FRAME_HEIGHT);
    }

    uint64_t elapsedMicros = getCurrentTimeMicros() - startTime;
    std::cout << "Execution time: " << (elapsedMicros / 1000) << " ms" << std::endl;

    delete[] overlayData;
    delete[] sourceData;
    delete[] resultData;

    return 0;
}

