// Encode data to Base64 format without line breaks
std::string encode_to_base64(const unsigned char* data, size_t size) {
    BIO *b64_bio, *mem_bio;
    BUF_MEM *buffer_memory;

    b64_bio = BIO_new(BIO_f_base64());
    mem_bio = BIO_new(BIO_s_mem());
    b64_bio = BIO_push(b64_bio, mem_bio);

    BIO_set_flags(b64_bio, BIO_FLAGS_BASE64_NO_NL);
    BIO_write(b64_bio, data, size);
    BIO_flush(b64_bio);
    BIO_get_mem_ptr(b64_bio, &buffer_memory);
    BIO_set_close(b64_bio, BIO_NOCLOSE);
    BIO_free_all(b64_bio);

    std::string result(buffer_memory->data, buffer_memory->length);
    BUF_MEM_free(buffer_memory);

    return result;
}

// Encrypt plaintext using AES-256-CBC and return Base64-encoded ciphertext
std::string perform_aes_encryption(const std::string& plain_text, const std::string& encryption_key, const std::string& initialization_vector) {
    size_t text_length = plain_text.size();
    unsigned char* encrypted_data = new unsigned char[text_length + AES_BLOCK_SIZE];

    EVP_CIPHER_CTX* cipher_context = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(cipher_context, EVP_aes_256_cbc(), nullptr, 
                       reinterpret_cast<const unsigned char*>(encryption_key.c_str()), 
                       reinterpret_cast<const unsigned char*>(initialization_vector.c_str()));

    int bytes_written;
    EVP_EncryptUpdate(cipher_context, encrypted_data, &bytes_written, 
                      reinterpret_cast<const unsigned char*>(plain_text.c_str()), text_length);

    int final_bytes;
    EVP_EncryptFinal_ex(cipher_context, encrypted_data + bytes_written, &final_bytes);

    size_t total_encrypted_length = bytes_written + final_bytes;
    EVP_CIPHER_CTX_free(cipher_context);

    std::string encoded_result = encode_to_base64(encrypted_data, total_encrypted_length);
    delete[] encrypted_data;

    return encoded_result;
}

