using u64 = unsigned long long;

struct Bucket {
    u64 mLeaves[16] = {};
};

struct BucketMap {
    u64 tryAcquire() noexcept {
        while (true) {
            u64 currentMap = mData.load(std::memory_order_relaxed);

            // Determine which bit to check: if LSB is 1, use bit 1; otherwise use bit 0
            u64 selectedBit = (currentMap & 1) ? 2ULL : 1ULL;

            // Attempt to set the selected bit using atomic OR
            u64 oldMap = mData.fetch_or(selectedBit, std::memory_order_relaxed);

            // Check if the bit was previously clear (i.e., acquisition succeeded)
            if ((oldMap & selectedBit) == 0) {
                return (selectedBit == 2ULL) ? 1ULL : 0ULL;
            }
        }
    }

    __attribute__((noinline)) Bucket getBucket() noexcept {
        tryAcquire();
        return Bucket();
    }

    std::atomic<u64> mData{ 1 };
};

