struct DataStruct
{
    unsigned char* buffer;
    int size;
};

extern "C" DLLAPI int API_ReadFile(const wchar_t* filepath, DataStruct** result)
{
    // Open file in binary mode for reading
    FILE* handle = nullptr;
    errno_t status = _wfopen_s(&handle, filepath, L"rb");
    if (status != 0 || handle == nullptr)
    {
        return -1; // Failed to open file
    }

    // Determine file size
    fseek(handle, 0, SEEK_END);
    long totalBytes = ftell(handle);
    fseek(handle, 0, SEEK_SET);

    // Allocate output structure and data buffer
    *result = new DataStruct();
    (*result)->buffer = new unsigned char[static_cast<size_t>(totalBytes)];
    (*result)->size = totalBytes;

    // Read entire file content
    size_t actuallyRead = fread((*result)->buffer, sizeof(unsigned char), 
                                static_cast<size_t>(totalBytes), handle);
    fclose(handle);

    // Validate read operation
    if (actuallyRead != static_cast<size_t>(totalBytes))
    {
        delete[] (*result)->buffer;
        delete *result;
        return -2; // Incomplete read
    }

    return 0; // Operation completed successfully
}

extern "C" DLLAPI void API_FreeData(DataStruct* info)
{
    if (info != nullptr)
    {
        delete[] info->buffer;
        delete info;
    }
}

