// Optimized version of Conway's Game of Life kernel using shared memory with border handling
__global__ void gameOfLife(float* returnBuffer, int width, int height) {
    __shared__ float tile[34][34]; // 32x32 block + 2-pixel border (1 on each side)

    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int x = blockIdx.x * blockDim.x + tx;
    int y = blockIdx.y * blockDim.y + ty;

    // Load interior cell data into shared memory
    if (x < width && y < height) {
        tile[ty + 1][tx + 1] = tex2D(inputTex, x, y);
    }

    // Load left and right borders
    if (tx == 0) {
        if (x > 0) {
            tile[ty + 1][0] = tex2D(inputTex, x - 1, y);
        } else {
            tile[ty + 1][0] = 0.0f; // Boundary condition for left edge
        }
        if (x < width - 1) {
            tile[ty + 1][33] = tex2D(inputTex, x + 1, y);
        } else {
            tile[ty + 1][33] = 0.0f; // Boundary condition for right edge
        }
    }

    // Load top and bottom borders
    if (ty == 0) {
        if (y > 0) {
            tile[0][tx + 1] = tex2D(inputTex, x, y - 1);
        } else {
            tile[0][tx + 1] = 0.0f; // Boundary condition for top edge
        }
        if (y < height - 1) {
            tile[33][tx + 1] = tex2D(inputTex, x, y + 1);
        } else {
            tile[33][tx + 1] = 0.0f; // Boundary condition for bottom edge
        }
    }

    __syncthreads();

    // Only compute for valid interior cells
    if (x > 0 && x < width - 1 && y > 0 && y < height - 1) {
        // Count live neighbors using the 8 surrounding cells in shared memory
        float current = tile[ty + 1][tx + 1];
        float neighborCount = 
            tile[ty][tx]     + tile[ty][tx + 1]   + tile[ty][tx + 2] +
            tile[ty + 1][tx] +                 tile[ty + 1][tx + 2] +
            tile[ty + 2][tx] + tile[ty + 2][tx + 1] + tile[ty + 2][tx + 2];

        // Apply Conway's rules: underpopulation (<2), survival (2-3), overpopulation (>3), reproduction (=3)
        float result = 0.0f;
        if (neighborCount == 3 || (current != 0.0f && neighborCount == 2)) {
            result = 1.0f;
        }

        returnBuffer[x + y * width] = result;
    }
}

#include <iostream>
#include <cstdlib>
#include <ctime>

class JammingWeapon {
private:
    float jamChance;
    int jamTimer;
    bool isJammed;
    int state;

public:
    JammingWeapon() : jamChance(0.05f), jamTimer(70), isJammed(false), state(0) {
        // Initialize random seed
        std::srand(static_cast<unsigned>(std::time(nullptr)));
    }

    // States: 0=Ready, 1=Deselect, 2=Select, 3=Fire, 4=Flash, 5=Jam
    void setReadyState() { state = 0; }
    void setDeselectState() { state = 1; }
    void setSelectState() { state = 2; }
    void setFireState() { state = 3; }
    void setFlashState() { state = 4; }
    void setJamState() { state = 5; }

    bool checkJamCondition() {
        if (isJammed) {
            return true;
        }
        // Generate random number between 0 and 1
        float randomValue = static_cast<float>(std::rand()) / static_cast<float>(RAND_MAX);
        if (randomValue < jamChance) {
            isJammed = true;
            return true;
        }
        return false;
    }

    void processJamCooldown() {
        if (isJammed) {
            jamTimer--;
            if (jamTimer <= 0) {
                isJammed = false;
                jamTimer = 70;
            }
        }
    }

    void executeAction(const char* actionName) {
        if (state == 0) { // Ready
            std::cout << "WEAP B 1 A_WeaponReady" << std::endl;
        } else if (state == 1 || state == 2) { // Deselect/Select
            if (checkJamCondition()) {
                setJamState();
                return;
            }
            std::cout << "WEAP C 1 A_" << (state == 1 ? "Lower" : "Raise") << std::endl;
        } else if (state == 3) { // Fire
            if (checkJamCondition()) {
                setJamState();
                return;
            }
            std::cout << "WEAP A 0 Bright A_PlaySound(\"weapons/pistol\", CHAN_WEAPON)" << std::endl;
            std::cout << "WEAP A 0 A_GunFlash" << std::endl;
            std::cout << "WEAP A 1 Bright" << std::endl;
            std::cout << "WEAP A 0 A_FireBullets(1, 1, 1, 5, \"BulletPuff\")" << std::endl;
        } else if (state == 4) { // Flash
            if (checkJamCondition()) {
                setJamState();
                return;
            }
            std::cout << "TNT1 A 0 A_Light0" << std::endl;
        } else if (state == 5) { // Jam
            std::cout << "WEAP A 3 A_PlaySound(\"weapons/jam\", CHAN_WEAPON)" << std::endl;
            std::cout << "WEAP A 3" << std::endl;
            std::cout << "WEAP A 3" << std::endl;
            processJamCooldown();
            setReadyState();
        }
    }

    bool isWeaponJammed() const { return isJammed; }
};

int main() {
    JammingWeapon weapon;

    // Test the weapon functionality
    std::cout << "Testing jamming weapon..." << std::endl;

    // Simulate selecting the weapon
    weapon.setSelectState();
    weapon.executeAction("Select");

    // Simulate firing the weapon
    weapon.setFireState();
    for (int i = 0; i < 5; i++) {
        std::cout << "Firing attempt " << (i+1) << ":" << std::endl;
        weapon.executeAction("Fire");
        if (weapon.isWeaponJammed()) {
            std::cout << "Weapon is jammed!" << std::endl;
            break;
        }
    }

    return 0;
}

