using namespace Microsoft::WRL;
using namespace D2D1;

class Direct2DControl : public HwndHost
{
public:
    Direct2DControl() : m_hostWindow(nullptr), m_factory(nullptr), m_renderTarget(nullptr) {}

    ~Direct2DControl()
    {
        if (m_renderTarget) m_renderTarget->Release();
        if (m_factory) m_factory->Release();
    }

    // Create the underlying Win32 window
    HWND CreateNativeWindow(HWND parent, HINSTANCE hInstance)
    {
        static const wchar_t CLASS_NAME[] = L"Direct2DDrawingHost";

        WNDCLASS wc = {};
        wc.lpfnWndProc = DefWindowProc;
        wc.hInstance = hInstance;
        wc.lpszClassName = CLASS_NAME;
        RegisterClass(&wc);

        return CreateWindow(
            CLASS_NAME,
            L"RenderingSurface",
            WS_CHILD | WS_VISIBLE,
            0, 0, 0, 0,
            parent,
            nullptr,
            hInstance,
            nullptr
        );
    }

    // Initialize and construct the hosting infrastructure
    HRESULT BuildWindowCore(HWND hwndParent)
    {
        m_hostWindow = CreateNativeWindow(hwndParent, GetModuleHandle(nullptr));

        // Setup Direct2D factory with optional debug info
        D2D1_FACTORY_OPTIONS factoryOptions = {};
#if defined(_DEBUG)
        factoryOptions.debugLevel = D2D1_DEBUG_LEVEL_INFORMATION;
#endif

        D2D1CreateFactory(
            D2D1_FACTORY_TYPE_SINGLE_THREADED,
            factoryOptions,
            &m_factory
        );

        return S_OK;
    }

    // Clean up resources and destroy the window
    void DestroyWindowCore()
    {
        if (m_hostWindow)
        {
            DestroyWindow(m_hostWindow);
            m_hostWindow = nullptr;
        }
    }

    // Expose the hosted window handle
    HWND GetHandle() const
    {
        return m_hostWindow;
    }

    // Prepare the render target based on current client area
    void InitializeRenderTarget()
    {
        if (!m_hostWindow || !m_factory) return;

        RECT clientRect;
        GetClientRect(m_hostWindow, &clientRect);

        D2D1_SIZE_U dimensions = D2D1::SizeU(
            clientRect.right - clientRect.left,
            clientRect.bottom - clientRect.top
        );

        m_factory->CreateHwndRenderTarget(
            D2D1::RenderTargetProperties(),
            D2D1::HwndRenderTargetProperties(m_hostWindow, dimensions),
            &m_renderTarget
        );
    }

    // Perform rendering operations
    void DrawContent()
    {
        if (!m_renderTarget) return;

        m_renderTarget->BeginDraw();

        // Clear background to sky blue
        m_renderTarget->Clear(D2D1::ColorF(D2D1::ColorF::SkyBlue));

        // Draw a red rectangle
        D2D1_RECT_F drawingRect = D2D1::RectF(0.0f, 0.0f, 100.0f, 100.0f);
        ComPtr<ID2D1SolidColorBrush> brush;
        m_renderTarget->CreateSolidColorBrush(D2D1::ColorF(D2D1::ColorF::Red), &brush);
        m_renderTarget->FillRectangle(drawingRect, brush.Get());

        m_renderTarget->EndDraw();
    }

    // Process window messages
    LRESULT HandleMessage(HWND hwnd, UINT message, WPARAM wParam, LPARAM lParam)
    {
        switch (message)
        {
        case WM_PAINT:
            DrawContent();
            ValidateRect(m_hostWindow, nullptr);
            return 0;

        case WM_SIZE:
            if (m_renderTarget)
            {
                RECT rc;
                GetClientRect(m_hostWindow, &rc);
                D2D1_SIZE_U newSize = D2D1::SizeU(rc.right - rc.left, rc.bottom - rc.top);
                m_renderTarget->Resize(newSize);
            }
            return 0;

        case WM_DESTROY:
            PostQuitMessage(0);
            return 0;
        }

        return DefWindowProc(hwnd, message, wParam, lParam);
    }

private:
    HWND m_hostWindow;
    ComPtr<ID2D1Factory> m_factory;
    ComPtr<ID2D1HwndRenderTarget> m_renderTarget;
};

