// Helper function to populate a Java HashMap with roster data
jobject createRosterMap(JNIEnv* env) {
    // Locate required Java classes and methods
    jclass mapClass = env->FindClass("java/util/HashMap");
    jclass boolClass = env->FindClass("java/lang/Boolean");

    jmethodID mapConstructor = env->GetMethodID(mapClass, "<init>", "()V");
    jmethodID boolConstructor = env->GetMethodID(boolClass, "<init>", "(Z)V");
    jmethodID putMethod = env->GetMethodID(mapClass, "put", "(Ljava/lang/Object;Ljava/lang/Object;)Ljava/lang/Object;");

    // Instantiate the HashMap
    jobject resultMap = env->NewObject(mapClass, mapConstructor);

    // Retrieve the internal roster map
    std::map<std::string, RosterItem>* rosterData = GetRosterMap();
    if (!rosterData || rosterData->empty()) {
        return resultMap;
    }

    // Iterate through the roster entries
    auto iterator = rosterData->begin();
    while (iterator != rosterData->end()) {
        // Convert C++ string to Java string for key
        jstring entryKey = env->NewStringUTF(iterator->second.name.c_str());

        // Create Java Boolean object from C++ boolean
        jboolean friendStatus = iterator->second.isfriend;
        jobject booleanValue = env->NewObject(boolClass, boolConstructor, friendStatus);

        // Insert into the HashMap
        env->CallObjectMethod(resultMap, putMethod, entryKey, booleanValue);

        ++iterator;
    }

    return resultMap;
}

