// Find the largest value in a vector of integers
int findMaximum(const std::vector<int>& values) {
    if (values.empty()) {
        throw std::invalid_argument("Vector is empty");
    }
    int currentMax = values[0];
    size_t index = 1;
    while (index < values.size()) {
        if (values[index] > currentMax) {
            currentMax = values[index];
        }
        ++index;
    }
    return currentMax;
}

int main() {
    std::vector<int> numbers = {3, 5, 7, 2, 8, -1, 4};
    try {
        std::cout << "The maximum element is: " << findMaximum(numbers) << std::endl;
    } catch (const std::invalid_argument& error) {
        std::cerr << error.what() << std::endl;
    }
    return 0;
}

