sampler2D inputTexture : register(s0);

// Constants related to CRT effect
float2 screenResolution = float2(1280, 720); // Target display resolution
float curvatureFactor = 1.5; // Controls the strength of the curved screen effect

// Function to simulate barrel distortion for screen curvature
float2 applyCurvature(float2 uvCoords, float curvatureStrength)
{
    float2 centerPoint = float2(0.5, 0.5);
    float2 offsetFromCenter = uvCoords - centerPoint;
    float radialDistance = distance(uvCoords, centerPoint);

    // Apply nonlinear scaling based on distance from center
    float scale = 1.0 + curvatureStrength * radialDistance;
    uvCoords = centerPoint + offsetFromCenter * scale;

    return uvCoords;
}

float4 main(float2 texCoord : TEXCOORD0) : COLOR
{
    // Apply curvature distortion to texture coordinates
    float2 adjustedUV = applyCurvature(texCoord, curvatureFactor);

    // Clip pixels that fall outside normalized coordinate bounds
    if (adjustedUV.x < 0.0 || adjustedUV.x > 1.0 || 
        adjustedUV.y < 0.0 || adjustedUV.y > 1.0)
        return float4(0.0, 0.0, 0.0, 1.0);

    // Sample the texture using distorted coordinates
    float4 baseColor = tex2D(inputTexture, adjustedUV);

    // Generate scanline pattern
    float scanlineContrast = 0.1;
    float scanlineThickness = 2.0;
    float scanlineSpacing = 4.0;

    // Calculate vertical line index based on original Y coordinate
    float rowNumber = floor(texCoord.y * screenResolution.y);
    bool isScanline = fmod(rowNumber, scanlineSpacing) < scanlineThickness;
    float scanlineFactor = isScanline ? scanlineContrast : 1.0;

    // Apply scanline modulation to RGB channels
    baseColor.rgb *= scanlineFactor;

    return baseColor;
}

