#include <glm/glm.hpp>

// Helper structure for vertex data
struct VertexData {
    glm::vec3 position;
    glm::vec3 color;
};

void Terrain::ConvertHeightMapToMeshData()
{
    // Clear existing mesh data
    vertices.clear();
    indices.clear();

    // Reserve space to avoid reallocations (optimization)
    vertices.reserve(worldSize * worldSize);
    indices.reserve((worldSize - 1) * (worldSize - 1) * 6);

    // Generate vertices with height-based coloring
    int index = 0;
    for (int x = 0; x < worldSize; ++x)
    {
        for (int z = 0; z < worldSize; ++z, ++index)
        {
            VertexData vertex;
            vertex.position = glm::vec3(static_cast<float>(x), 
                                       heightMap[x][z], 
                                       static_cast<float>(z));

            // Normalize height and apply grayscale coloring
            float normalizedHeight = heightMap[x][z];
            float colorValue = normalizedHeight * 0.5f + 0.5f;
            vertex.color = glm::vec3(colorValue, colorValue, colorValue);

            vertices.push_back(vertex);
        }
    }

    // Create triangle indices using a different traversal pattern
    for (int x = 0; x < worldSize - 1; ++x)
    {
        for (int z = 0; z < worldSize - 1; ++z)
        {
            // Calculate corner indices for the current quad
            int baseIndex = x * worldSize + z;
            int rightNeighbor = baseIndex + 1;
            int bottomNeighbor = baseIndex + worldSize;
            int diagonalNeighbor = bottomNeighbor + 1;

            // First triangle: (base, diagonal, bottom)
            indices.push_back(baseIndex);
            indices.push_back(diagonalNeighbor);
            indices.push_back(bottomNeighbor);

            // Second triangle: (base, right, diagonal)
            indices.push_back(baseIndex);
            indices.push_back(rightNeighbor);
            indices.push_back(diagonalNeighbor);
        }
    }
}

#include "greenwald_khanna.h"

// Compute quantile estimates for given percentiles using Greenwald-Khanna algorithm
std::vector<double> ComputeQuantileEstimates(const std::vector<double>& input_data, 
                                             const std::vector<double>& target_percentiles, 
                                             double accuracy_param)
{
    greenwald_khanna<double> gk_structure(accuracy_param);

    // Insert all data points into the summary structure
    for (double element : input_data)
    {
        gk_structure.insert(element);
    }

    // Extract quantile estimates for each requested percentile
    std::vector<double> quantile_estimates;
    for (double p : target_percentiles)
    {
        quantile_estimates.push_back(gk_structure.quantile(p));
    }

    return quantile_estimates;
}

