// Function to normalize whitespace in a string
std::string normalizeWhitespace(const std::string& text) {
    if (text.empty()) return text;

    std::string output;
    bool previousWasSpace = false;

    for (size_t index = 0; index < text.size(); ++index) {
        char currentChar = text[index];

        if (std::isspace(static_cast<unsigned char>(currentChar))) {
            // Only add a space if we haven't just added one and the result isn't empty
            if (!previousWasSpace && !output.empty()) {
                output += ' ';
            }
            previousWasSpace = true;
        } else {
            output += currentChar;
            previousWasSpace = false;
        }
    }

    // Trim trailing space if present
    if (!output.empty() && output.back() == ' ') {
        output.pop_back();
    }

    return output;
}

// Function to verify the normalization works correctly
void validateWhitespaceNormalization() {
    std::string input1 = "  Hello   World!  ";
    std::string expected1 = "Hello World!";
    if (normalizeWhitespace(input1) != expected1) {
        std::cerr << "Test 1 failed!" << std::endl;
        return;
    }

    std::string input2 = "  This is    a test  ";
    std::string expected2 = "This is a test";
    if (normalizeWhitespace(input2) != expected2) {
        std::cerr << "Test 2 failed!" << std::endl;
        return;
    }

    std::string input3 = "NoExtraSpaces";
    std::string expected3 = "NoExtraSpaces";
    if (normalizeWhitespace(input3) != expected3) {
        std::cerr << "Test 3 failed!" << std::endl;
        return;
    }

    std::string input4 = " ";
    std::string expected4 = "";
    if (normalizeWhitespace(input4) != expected4) {
        std::cerr << "Test 4 failed!" << std::endl;
        return;
    }

    std::string input5 = "   ";
    std::string expected5 = "";
    if (normalizeWhitespace(input5) != expected5) {
        std::cerr << "Test 5 failed!" << std::endl;
        return;
    }

    std::cout << "All tests passed!" << std::endl;
}

int main() {
