// Helper function to extract binary content from a file into a string buffer
std::string loadBinaryFile(const std::string& path) {
    std::ifstream inputStream(path, std::ios::binary | std::ios::ate);
    if (!inputStream) {
        throw std::runtime_error("Unable to open file for reading.");
    }

    std::streamsize fileSize = inputStream.tellg();
    inputStream.seekg(0, std::ios::beg);

    std::string content;
    content.resize(static_cast<size_t>(fileSize));
    if (!inputStream.read(&content[0], fileSize)) {
        throw std::runtime_error("Failed to read file contents.");
    }
    return content;
}

// Derive encryption key and initialization vector using MD5-based KDF
void generateCryptoParameters(const std::string& passphrase,
                              const std::string& rawSalt,
                              std::string& outKey,
                              std::string& outIv) {
    Poco::Crypto::CipherFactory& engine = Poco::Crypto::CipherFactory::defaultFactory();
    Poco::Crypto::CipherKey params("md5", passphrase, rawSalt, 1);

    outKey = params.key();
    outIv  = params.iv();
}

int main() {
    const std::string targetFile = "encrypted_file";
    const std::string secretPass = "your_password";

    try {
        // Load entire file content
        std::string rawData = loadBinaryFile(targetFile);

        // Validate header
        if (rawData.size() < 16 || rawData.substr(0, 8) != "Salted__") {
            std::cerr << "Error: File does not appear to be in expected OpenSSL format." << std::endl;
            return 1;
        }

        // Extract salt and ciphertext
        std::string extractedSalt = rawData.substr(8, 8);
        std::string cipherText    = rawData.substr(16);

        // Generate key and IV
        std::string derivedKey, derivedIv;
        generateCryptoParameters(secretPass, extractedSalt, derivedKey, derivedIv);

        // Setup decryption cipher
        Poco::Crypto::CipherFactory& factory = Poco::Crypto::CipherFactory::defaultFactory();
        Poco::Crypto::CipherKey aesKey("aes-128-cbc", derivedKey, derivedIv);
        Poco::AutoPtr<Poco::Crypto::Cipher> decryptor = factory.createCipher(aesKey);

        // Perform decryption with Base64 decoding
        std::string plaintext = decryptor->decryptString(cipherText, Poco::Crypto::Cipher::ENC_BASE64);

        std::cout << "Decrypted data: " << plaintext << std::endl;

    } catch (const std::exception& ex) {
        std::cerr << "Exception occurred: " << ex.what() << std::endl;
        return 1;
    }

    return 0;
}

