#include <iostream>
#include <vector>
#include <string>

// Convert string into matrix using spiral placement and read in spiral order
std::string transformString(std::string input, int rows, int cols, char placeholder = 'X') {
    // Create 2D grid filled with placeholder character
    std::vector<std::vector<char>> grid(rows, std::vector<char>(cols, placeholder));

    // Movement vectors: right, down, left, up (clockwise rotation)
    const int moveX[] = {0, 1, 0, -1};
    const int moveY[] = {1, 0, -1, 0};

    int curRow = 0, curCol = 0;  // Current position
    int dirIdx = 0;              // Current direction index
    int pos = 0;                 // Position in input string

    // Fill the grid in spiral pattern
    while (pos < input.length()) {
        grid[curRow][curCol] = input[pos++];

        // Compute next cell coordinates
        int nextRow = curRow + moveX[dirIdx];
        int nextCol = curCol + moveY[dirIdx];

        // Check if next cell is invalid or already occupied
        if (nextRow < 0 || nextRow >= rows || 
            nextCol < 0 || nextCol >= cols || 
            grid[nextRow][nextCol] != placeholder) {
            // Turn clockwise to next direction
            dirIdx = (dirIdx + 1) % 4;
            nextRow = curRow + moveX[dirIdx];
            nextCol = curCol + moveY[dirIdx];
        }

        // Update current position
        curRow = nextRow;
        curCol = nextCol;
    }

    // Read values in spiral order
    std::string output;
    std::vector<std::vector<bool>> marked(rows, std::vector<bool>(cols, false));

    curRow = 0;
    curCol = 0;
    dirIdx = 0;

    while (true) {
        output += grid[curRow][curCol];
        marked[curRow][curCol] = true;

        // Calculate next position
        int nextRow = curRow + moveX[dirIdx];
        int nextCol = curCol + moveY[dirIdx];

        // If next position is invalid or already visited, change direction
        if (nextRow < 0 || nextRow >= rows || 
            nextCol < 0 || nextCol >= cols || 
            marked[nextRow][nextCol]) {
            dirIdx = (dirIdx + 1) % 4;
            nextRow = curRow + moveX[dirIdx];
            nextCol = curCol + moveY[dirIdx];

            // If still invalid after direction change, we're done
            if (nextRow < 0 || nextRow >= rows || 
                nextCol < 0 || nextCol >= cols || 
                marked[nextRow][nextCol]) {
                break;
            }
        }

        // Move to next position
        curRow = nextRow;
        curCol = nextCol;
    }

    return output;
}

int main() {
    std::string s1 = "HELLOPROGRAMMING";
    int r1 = 5, c1 = 4;
    std::cout << transformString(s1, r1, c1) << std::endl;

    std::string s2 = "HELLOPROGRAMMING";
    int r2 = 4, c2 = 4;
    std::cout << transformString(s2, r2, c2) << std::endl;

    std::string s3 = "A";
    int r3 = 1, c3 = 1;
    std::cout << transformString(s3, r3, c3) << std::endl;

    std::string s4 = "HELLO";
    int r4 = 3, c4 = 3;
    std::cout << transformString(s4, r4, c4, 'X') << std::endl;

    return 0;
}

