__global__
void convert_rgba_to_luminance(const uchar4* __restrict__ input,
                               unsigned char* __restrict__ output,
                               int height, int width)
{
    // Compute global coordinates in the image
    int col = blockIdx.x * blockDim.x + threadIdx.x;
    int row = blockIdx.y * blockDim.y + threadIdx.y;

    // Bounds check: skip threads outside image boundaries
    if (col >= width || row >= height) {
        return;
    }

    // Linear index into the image array
    int pos = row * width + col;

    // Load pixel data
    uchar4 pixel = input[pos];

    // Compute weighted luminance using standard coefficients
    float intensity = 0.2126f * pixel.x + 0.7152f * pixel.y + 0.0722f * pixel.z;

    // Store result as unsigned char
    output[pos] = static_cast<unsigned char>(intensity);
}

void host_rgba_to_greyscale(const uchar4 * const h_input,
                            uchar4 * const d_input,
                            unsigned char* const d_output,
                            size_t rows,
                            size_t cols)
{
    // Define block dimensions (16x16 threads per block)
    const dim3 threadsPerBlock(16, 16, 1);

    // Calculate grid dimensions with ceiling division
    const dim3 blocksPerGrid((static_cast<int>(cols) + threadsPerBlock.x - 1) / threadsPerBlock.x,
                             (static_cast<int>(rows) + threadsPerBlock.y - 1) / threadsPerBlock.y,
                             1);

    // Launch kernel
    convert_rgba_to_luminance<<<blocksPerGrid, threadsPerBlock>>>(
        d_input, d_output, static_cast<int>(rows), static_cast<int>(cols));

    // Ensure kernel completion and check for errors
    cudaDeviceSynchronize();
    checkCudaErrors(cudaGetLastError());
}

