class CustomGraphicsView : public QGraphicsView {
public:
    CustomGraphicsView(QGraphicsScene *scene, QWidget *parent = nullptr)
        : QGraphicsView(scene, parent) {
        grabGesture(Qt::PinchGesture);
    }

protected:
    bool event(QEvent *event) override {
        if (event->type() == QEvent::Gesture)
            return handleGestureEvent(static_cast<QGestureEvent*>(event));
        return QGraphicsView::event(event);
    }

    bool handleGestureEvent(QGestureEvent *gestureEvent) {
        if (QPinchGesture *pinch = gestureEvent->gesture(Qt::PinchGesture)) {
            handlePinch(pinch);
        }
        return true;
    }

    void handlePinch(QPinchGesture *pinch) {
        if (pinch->changeFlags() & QPinchGesture::ScaleFactorChanged) {
            qDebug() << "Zoom level updated to" << pinch->scaleFactor();
        }
    }
};

