// Function to print Fibonacci sequence up to n terms
int main() {
    int terms;
    std::cout << "Enter the number of terms: ";
    std::cin >> terms;

    if (terms <= 0) {
        std::cout << "Please enter a positive integer." << std::endl;
        return 0;
    }

    long long prev = 0, curr = 1;

    for (int count = 1; count <= terms; ++count) {
        if (count == 1) {
            std::cout << prev << " ";
        } else if (count == 2) {
            std::cout << curr << " ";
        } else {
            long long temp = prev + curr;
            prev = curr;
            curr = temp;
            std::cout << curr << " ";
        }
    }
    std::cout << std::endl;

    return 0;
}

