// Continuously observe a memory location for modifications
void monitor_changes(int* target_var) {
    int previous_value = *target_var;

    do {
        int current_value = *target_var;

        // Detect any change in the observed value
        if (current_value != previous_value) {
            printf("Value has changed!");
            previous_value = current_value;
        }

        // Brief pause to reduce CPU usage
        std::this_thread::sleep_for(std::chrono::milliseconds(1));

    } while (true);
}

