// Find the k smallest elements from the input array
std::vector<int> k_smallest_elements(std::vector<int>& arr, int k) {
    std::multiset<int> s;
    for (int value : arr) {
        s.insert(value);
        // Maintain only k elements by removing the largest when size exceeds k
        if (static_cast<int>(s.size()) > k) {
            s.erase(--s.end());
        }
    }
    // Convert multiset to vector and return
    return std::vector<int>(s.begin(), s.end());
}

