float Polynomial(int degree, int coefficients[], float value) 
{   
    float result = 0.0f;

    if (degree == 0)
    {
        result = coefficients[0];
    }
    else
    {
        result = coefficients[0];
        int index = 1;
        float current_power = value;

        while (index <= degree)
        {
            result += coefficients[index] * current_power;
            current_power *= current_power;
            index++;
        }
    }

    return result;
}

