std::vector<char> base64_decode(const std::string& encoded_string) {
    std::vector<char> result;
    int length = encoded_string.length();
    int pos = 0;
    int count = 0;
    int index = 0;
    unsigned char buffer[4];
    unsigned char decoded_triplet[3];

    while (pos < length && encoded_string[index] != '=' && std::isalnum(encoded_string[index])) {
        unsigned char current_char = static_cast<unsigned char>(encoded_string[index]);
        int value;

        if (current_char >= 'A' && current_char <= 'Z') {
            value = current_char - 'A';
        } else if (current_char >= 'a' && current_char <= 'z') {
            value = current_char - 'a' + 26;
        } else if (current_char >= '0' && current_char <= '9') {
            value = current_char - '0' + 52;
        } else if (current_char == '+') {
            value = 62;
        } else {
            value = 63;
        }

        buffer[count++] = static_cast<unsigned char>(value);

        if (count == 4) {
            decoded_triplet[0] = (buffer[0] << 2) | ((buffer[1] & 0x30) >> 4);
            decoded_triplet[1] = ((buffer[1] & 0x0F) << 4) | ((buffer[2] & 0x3C) >> 2);
            decoded_triplet[2] = ((buffer[2] & 0x03) << 6) | buffer[3];

            for (int k = 0; k < 3; ++k) {
                result.push_back(static_cast<char>(decoded_triplet[k]));
            }
            count = 0;
        }

        index++;
    }

    if (count > 0) {
        for (int fill = count; fill < 4; ++fill) {
            buffer[fill] = 0;
        }

        decoded_triplet[0] = (buffer[0] << 2) | ((buffer[1] & 0x30) >> 4);
        decoded_triplet[1] = ((buffer[1] & 0x0F) << 4) | ((buffer[2] & 0x3C) >> 2);
        decoded_triplet[2] = ((buffer[2] & 0x03) << 6) | buffer[3];

        for (int out_idx = 0; out_idx < count - 1; ++out_idx) {
            result.push_back(static_cast<char>(decoded_triplet[out_idx]));
        }
    }

    return result;
}

