// Convert UTF-8 string to UTF-16 (std::u16string)
std::u16string convertUtf8ToUtf16(const std::string& input) {
    if (input.empty()) return std::u16string();

    // Use unique_ptr to manage conversion object lifetime (optional but safe)
    auto converter = std::make_unique<std::wstring_convert<
        std::codecvt_utf8_utf16<char16_t>, char16_t>>();

    try {
        return converter->from_bytes(input);
    } catch (...) {
        return std::u16string(); // Return empty on failure
    }
}

