// Custom thread class to execute Python code in a separate thread
class PythonExecutor : public QThread {
    Q_OBJECT

public:
    explicit PythonExecutor(QObject *parent = nullptr) : QThread(parent) {}

signals:
    void executionFinished(const QString &output);

protected:
    void run() override final {
        Py_Initialize();

        // Set up Python path to include current directory
        PyRun_SimpleString("import sys");
        PyRun_SimpleString("sys.path.append('./')");

        // Attempt to import the specified module
        PyObject* pModule = PyImport_ImportModule("your_module");
        if (pModule != nullptr) {
            // Get the function from the module
            PyObject* pFunc = PyObject_GetAttrString(pModule, "your_function");

            if (pFunc && PyCallable_Check(pFunc)) {
                // Prepare arguments for the Python function
                PyObject* pArgs = PyTuple_New(1);
                PyObject* pArgValue = PyUnicode_FromString("your_argument");
                PyTuple_SetItem(pArgs, 0, pArgValue);

                // Call the Python function
                PyObject* pResult = PyObject_CallObject(pFunc, pArgs);

                if (pResult != nullptr) {
                    // Convert result to C++ string
                    const char* resultStr = PyUnicode_AsUTF8(pResult);

                    // Emit result via signal using lambda and queued connection
                    QMetaObject::invokeMethod(this, [this, resultStr]() {
                        emit executionFinished(QString(resultStr));
                    }, Qt::QueuedConnection);

                    Py_DECREF(pResult);
                }

                Py_DECREF(pArgs);
                Py_XDECREF(pFunc);
            }

            Py_DECREF(pModule);
        }

        Py_Finalize();
    }
};

// Main window class with UI elements for Python execution
class PythonIDE : public QWidget {
    Q_OBJECT

public:
    explicit PythonIDE(QWidget *parent = nullptr) : QWidget(parent) {
        QVBoxLayout *mainLayout = new QVBoxLayout(this);

        // Initialize UI components
        outputDisplay = new QTextEdit(this);
        inputField = new QLineEdit(this);
        executeBtn = new QPushButton("Execute Python", this);

        // Add widgets to layout
        mainLayout->addWidget(outputDisplay);
        mainLayout->addWidget(inputField);
        mainLayout->addWidget(executeBtn);

        // Connect signals and slots
        connect(executeBtn, &QPushButton::clicked, this, &PythonIDE::startExecution);
    }

private slots:
    void startExecution() {
        // Create and configure thread for Python execution
        pythonWorker = new PythonExecutor(this);
        connect(pythonWorker, &PythonExecutor::executionFinished, this, &PythonIDE::handleOutput);

        // Disable controls during execution
        inputField->setEnabled(false);
        executeBtn->setEnabled(false);

        // Start the background thread
        pythonWorker->start();
    }

    void handleOutput(const QString &message) {
        // Display result in output area
        outputDisplay->append(message);

        // Re-enable controls after completion
        inputField->setEnabled(true);
        executeBtn->setEnabled(true);

        // Clean up thread object
        pythonWorker->deleteLater();
    }

private:
    QTextEdit *outputDisplay;
    QLineEdit *inputField;
    QPushButton *executeBtn;
    PythonExecutor *pythonWorker;
};

