#include <cuda_runtime.h>
#include <iostream>

#define MATRIX_SIZE 1000

__global__ void performMatrixMultiplication(float *inputMatrixA, float *inputMatrixB, float *outputMatrixC, int dimension) {
    int rowIndex = blockIdx.y * blockDim.y + threadIdx.y;
    int colIndex = blockIdx.x * blockDim.x + threadIdx.x;

    if (rowIndex < dimension && colIndex < dimension) {
        float accumulator = 0.0f;
        for (int k = 0; k < dimension; k++) {
            accumulator += inputMatrixA[rowIndex * dimension + k] * inputMatrixB[k * dimension + colIndex];
        }
        outputMatrixC[rowIndex * dimension + colIndex] = accumulator;
    }
}

int main() {
    float *host_A, *host_B, *host_C;
    float *device_A, *device_B, *device_C;

    // Allocate host memory
    host_A = (float*)malloc(MATRIX_SIZE * MATRIX_SIZE * sizeof(float));
    host_B = (float*)malloc(MATRIX_SIZE * MATRIX_SIZE * sizeof(float));
    host_C = (float*)malloc(MATRIX_SIZE * MATRIX_SIZE * sizeof(float));

    // Initialize matrices with constant values
    for (int idx = 0; idx < MATRIX_SIZE * MATRIX_SIZE; idx++) {
        host_A[idx] = 1.0f;
        host_B[idx] = 2.0f;
    }

    // Allocate device memory
    cudaMalloc(&device_A, MATRIX_SIZE * MATRIX_SIZE * sizeof(float));
    cudaMalloc(&device_B, MATRIX_SIZE * MATRIX_SIZE * sizeof(float));
    cudaMalloc(&device_C, MATRIX_SIZE * MATRIX_SIZE * sizeof(float));

    // Transfer data from host to device
    cudaMemcpy(device_A, host_A, MATRIX_SIZE * MATRIX_SIZE * sizeof(float), cudaMemcpyHostToDevice);
    cudaMemcpy(device_B, host_B, MATRIX_SIZE * MATRIX_SIZE * sizeof(float), cudaMemcpyHostToDevice);

    // Configure execution configuration
    dim3 blockSize(16, 16);
    dim3 gridSize((MATRIX_SIZE + blockSize.x - 1) / blockSize.x, (MATRIX_SIZE + blockSize.y - 1) / blockSize.y);

    // Execute kernel
    performMatrixMultiplication<<<gridSize, blockSize>>>(device_A, device_B, device_C, MATRIX_SIZE);

    // Copy results back to host
    cudaMemcpy(host_C, device_C, MATRIX_SIZE * MATRIX_SIZE * sizeof(float), cudaMemcpyDeviceToHost);

    // Release device resources
    cudaFree(device_A);
    cudaFree(device_B);
    cudaFree(device_C);

    // Release host resources
    free(host_A);
    free(host_B);
    free(host_C);

    return 0;
}

#include <coroutine>
#include <iostream>

class AsyncOperation {
public:
    struct callback_handler {
        AsyncOperation get_return_object() {
            return AsyncOperation{std::coroutine_handle<callback_handler>::from_promise(*this)};
        }

        std::suspend_never suspend_initial() { return {}; }
        std::suspend_never suspend_final() noexcept { return {}; }

        void complete_value() {}
        void handle_error() { std::terminate(); }

        bool m_paused = false;
    };

    bool finished() const { return m_coroutine.done(); }
    void execute() { m_coroutine.resume(); }
    void halt() { m_coroutine.promise().m_paused = true; }

private:
    std::coroutine_handle<callback_handler> m_coroutine;

    AsyncOperation(std::coroutine_handle<callback_handler> coro) : m_coroutine(coro) {}
    ~AsyncOperation() { if (m_coroutine) m_coroutine.destroy(); }

    friend struct callback_handler;
};

AsyncOperation process_task() {
    for (;;) {
        std::cout << "Coroutine running\n";
        co_await std::suspend_always{};
        std::cout << "Coroutine resumed\n";
    }
}

int main() {
    AsyncOperation operation = process_task();
    operation.execute();
    operation.halt();
    operation.execute();
    return 0;
}

