// Determine if a number is prime using optimized checks
bool checkPrime(int value) {
    if (value <= 1) return false;
    if (value <= 3) return true;
    if (value % 2 == 0 || value % 3 == 0) return false;

    int limit = static_cast<int>(std::sqrt(value));
    for (int j = 5; j <= limit; j += 6) {
        if (value % j == 0 || value % (j + 2) == 0) return false;
    }
    return true;
}

// Find the smallest prime strictly larger than the input
int findNextPrime(int number) {
    if (number < 2) return 2;
    int candidate = number + 1;
    bool isFound = false;

    while (!isFound) {
        if (checkPrime(candidate)) {
            isFound = true;
        } else {
            candidate++;
        }
    }
    return candidate;
}

int main() {
    int userInput;
    std::cout << "Enter a number: ";
    std::cin >> userInput;

    int nextP = findNextPrime(userInput);
    std::cout << "The first prime number greater than " << userInput << " is " << nextP << std::endl;

    return 0;
}

