// Function to print Fibonacci sequence up to n terms
void displayFibonacci(int count) {
    long long prev = 0, curr = 1, temp;

    for (int j = 0; j < count; j++) {
        if (j == 0) {
            cout << prev << " ";
        } else if (j == 1) {
            cout << curr << " ";
        } else {
            temp = prev + curr;
            cout << temp << " ";
            prev = curr;
            curr = temp;
        }
    }
    cout << endl;
}

