// Custom AST node processor for virtual functions
class VirtualFunctionInspector {
public:
    explicit VirtualFunctionInspector(ASTContext *Ctx) : Context(Ctx) {}

    void inspect(Decl *D) {
        if (!D) return;

        // Process current node
        if (auto *Method = dyn_cast<CXXMethodDecl>(D)) {
            if (Method->isVirtual()) {
                llvm::outs() << "Virtual function: " << Method->getNameAsString() << "\n";
            }
        }

        // Recursively process children
        for (auto *Child : D->children()) {
            inspect(Child);
        }
    }

private:
    ASTContext *Context;
};

// Custom consumer that uses manual traversal instead of RecursiveASTVisitor
class VirtualFunctionConsumer : public ASTConsumer {
public:
    explicit VirtualFunctionConsumer(ASTContext *Ctx) : Inspector(Ctx) {}

    void HandleTranslationUnit(ASTContext &Ctx) override {
        Decl *TU = Ctx.getTranslationUnitDecl();
        Inspector.inspect(TU);
    }

private:
    VirtualFunctionInspector Inspector;
};

// Frontend action factory
class VirtualFunctionAction : public ASTFrontendAction {
public:
    std::unique_ptr<ASTConsumer> CreateASTConsumer(CompilerInstance &CI, StringRef File) override {
        return std::make_unique<VirtualFunctionConsumer>(&CI.getASTContext());
    }
};

int main(int argc, const char **argv) {
    CommonOptionsParser OptionsParser(argc, argv, "virtual-function-extractor");
    ClangTool Tool(OptionsParser.getCompilations(), OptionsParser.getSourcePathList());
    return Tool.run(newFrontendActionFactory<VirtualFunctionAction>().get());
}

#include <immintrin.h>
