#include <cstdint>

void count_frequencies(const __m128i &vec, uint32_t frequencies[256]) {
    // Process each byte position individually using extraction
    for (int pos = 0; pos < 16; ++pos) {
        // Extract the byte at position 'pos' directly
        uint8_t byte_val = static_cast<uint8_t>(_mm_extract_epi8(vec, pos));

        // Increment the corresponding frequency counter
        frequencies[byte_val]++;
    }
}

