// Alternative grid table implementation with modified structure and logic
class CustomGridDataSource : public wxGridStringTable
{
public:
    CustomGridDataSource(const std::vector<std::vector<std::string>>& initialData)
        : m_gridData(initialData)
    {
    }

    // Override methods to provide grid data access
    int GetRowsCount() override { return static_cast<int>(m_gridData.size()); }
    int GetColsCount() override { return m_gridData.empty() ? 0 : static_cast<int>(m_gridData[0].size()); }

    std::string GetCellValue(int row, int col) override 
    { 
        return (row >= 0 && row < static_cast<int>(m_gridData.size()) && 
                col >= 0 && col < static_cast<int>(m_gridData[row].size())) 
               ? m_gridData[row][col] 
               : ""; 
    }

    void SetCellValue(int row, int col, const std::string& value) override 
    { 
        if (row >= 0 && row < static_cast<int>(m_gridData.size()) && 
            col >= 0 && col < static_cast<int>(m_gridData[row].size()))
        {
            m_gridData[row][col] = value;
        }
    }

    std::string GetColumnLabel(int colIndex) override 
    { 
        return "Col " + std::to_string(colIndex + 1); 
    }

    std::string GetColumnType(int colIndex) override 
    { 
        return "text"; 
    }

    // Modified sorting implementation using stable_sort for consistent ordering
    void PerformSorting(int columnIndex) override
    {
        if (columnIndex < 0 || columnIndex >= GetColsCount() || m_gridData.size() <= 1)
            return;

        std::stable_sort(m_gridData.begin(), m_gridData.end(), 
            [columnIndex](const std::vector<std::string>& firstRow, const std::vector<std::string>& secondRow) {
                return firstRow[columnIndex] < secondRow[columnIndex];
            });
    }

private:
    std::vector<std::vector<std::string>> m_gridData;
};

// Enhanced event handler with additional functionality
class GridInteractionHandler : public wxEvtHandler
{
public:
    void ProcessGridInteraction(wxGridEvent& event)
    {
        if (event.GetEventType() == wxEVT_GRID_LABEL_LEFT_CLICK)
        {
            wxGrid* associatedGrid = dynamic_cast<wxGrid*>(event.GetEventObject());
            if (associatedGrid)
            {
                int clickedColumn = event.GetCol();
                if (clickedColumn >= 0)
                {
                    associatedGrid->SortByColumn(clickedColumn);
                }
            }
        }

        event.Skip();
    }
};

// Initialize and setup the grid component
wxGrid* CreateConfiguredGrid(wxWindow* parent)
{
    wxGrid* gridComponent = new wxGrid(parent, wxID_ANY);

    // Prepare sample data in different order than original
    std::vector<std::vector<std::string>> sampleData = {
        {"C", "B", "A"}, 
        {"X", "Z", "Y"}
    };

    gridComponent->SetTable(new CustomGridDataSource(sampleData));

    // Attach custom event handling mechanism
    GridInteractionHandler* interactionHandler = new GridInteractionHandler();
    gridComponent->PushEventHandler(interactionHandler);

    return gridComponent;
}

#include <immintrin.h>

// Performs complex conjugate multiplication using AVX intrinsics
// out[i] = in1[i] * conj(in2[i])
void avx_vcmulcc(cfloat* out, const cfloat* in1, const cfloat* in2, int n) {
    for (int idx = 0; idx < n; idx += 8) {
        // Load 8 complex numbers (16 floats) from each input array
        __m256 vec_in1 = _mm256_loadu_ps((const float*)(in1 + idx));
        __m256 vec_in2 = _mm256_loadu_ps((const float*)(in2 + idx));

        // Extract real and imaginary parts for first vector
        __m256 in1_real = _mm256_permute_ps(vec_in1, _MM_SHUFFLE(2, 3, 0, 1));
        __m256 in1_imag = _mm256_permute_ps(vec_in1, _MM_SHUFFLE(3, 2, 1, 0));

        // Extract real and imaginary parts for second vector (conjugated)
        __m256 in2_real = _mm256_permute_ps(vec_in2, _MM_SHUFFLE(2, 3, 0, 1));
        __m256 in2_imag = _mm256_permute_ps(vec_in2, _MM_SHUFFLE(3, 2, 1, 0));

        // Compute real part: real1*real2 - imag1*(-imag2) = real1*real2 + imag1*imag2
        // But since we want conjugate multiply (in1 * conj(in2)), 
        // conj(in2) = real2 - i*imag2, so:
        // (a+bi)(c-di) = ac + bd + i(bc - ad)
        __m256 real_result = _mm256_add_ps(_mm256_mul_ps(in1_real, in2_real), 
                                          _mm256_mul_ps(in1_imag, in2_imag));

        // Compute imaginary part: real1*(-imag2) + imag1*real2 = -real1*imag2 + imag1*real2
        __m256 imag_result = _mm256_sub_ps(_mm256_mul_ps(in1_imag, in2_real), 
                                          _mm256_mul_ps(in1_real, in2_imag));

        // Store results interleaved: [real0, imag0, real1, imag1, ...]
        __m256 combined = _mm256_permute2f128_ps(real_result, imag_result, 0x20);
        _mm256_storeu_ps((float*)(out + idx), combined);
    }
}

