#include <cstdint>

// Acquire an available index using atomic bit manipulation
std::uint64_t acquire() noexcept {
    while (true) {
        std::uint64_t currentMap = mData;

        // Determine which bit to check first based on the least significant bit
        std::uint64_t candidateIndex = (currentMap & 1) ? 1ULL : 0ULL;
        std::uint64_t bitMask = 1ULL << candidateIndex;

        // Attempt to set the bit atomically
        std::uint64_t priorValue = __atomic_fetch_or(&mData, bitMask, __ATOMIC_SEQ_CST);

        // Check if the bit was previously unset (i.e., slot was free)
        if ((priorValue & bitMask) == 0) {
            return candidateIndex;
        }
    }
}

