// Chess board representation
char chessboard[8][8] = {
    {'R', 'N', 'B', 'Q', 'K', 'B', 'N', 'R'},
    {'P', 'P', 'P', 'P', 'P', 'P', 'P', 'P'},
    {' ', '.', ' ', '.', ' ', '.', ' ', '.'},
    {'.', ' ', '.', ' ', '.', ' ', '.', ' '},
    {' ', '.', ' ', '.', ' ', '.', ' ', '.'},
    {'.', ' ', '.', ' ', '.', ' ', '.', ' '},
    {'p', 'p', 'p', 'p', 'p', 'p', 'p', 'p'},
    {'r', 'n', 'b', 'q', 'k', 'b', 'n', 'r'}
};

void display_board();
bool move_allowed(int start_row, int start_col, int end_row, int end_col);
void execute_move(int start_row, int start_col, int end_row, int end_col);
bool king_under_attack(bool is_white_turn);
bool checkmate_condition(bool is_white_turn);
bool stalemate_condition(bool is_white_turn);
bool match_ended(bool is_white_turn);

// Function to print the current state of the board
void display_board() {
    cout << endl << "   a  b  c  d  e  f  g  h" << endl;
    for (int row = 0; row < 8; ++row) {
        cout << row + 1 << "  ";
        for (int col = 0; col < 8; ++col) {
            cout << chessboard[row][col] << "  ";
        }
        cout << row + 1 << endl;
    }
    cout << "   a  b  c  d  e  f  g  h" << endl << endl;
}

// Execute a move if it's valid
void execute_move(int start_row, int start_col, int end_row, int end_col) {
    if (move_allowed(start_row, start_col, end_row, end_col)) {
        swap(chessboard[start_row][start_col], chessboard[end_row][end_col]);
    }
}

int main() {
    bool white_plays = true;
    while (!match_ended(white_plays)) {
        display_board();
        cout << "Current player: " << ((white_plays) ? "White" : "Black") << endl;
        bool move_confirmed = false;
        while (!move_confirmed) {
            string input;
            cout << "Enter your move (e.g., e2e4): ";
            getline(cin, input);
            if (input.length() == 4) {
                int start_row = input[1] - '1';
                int start_col = input[0] - 'a';
                int end_row = input[3] - '1';
                int end_col = input[2] - 'a';

                // Validate piece ownership and move legality
                if (isupper(input[0]) || islower(input[0])) {
                    char piece = chessboard[start_row][start_col];
                    bool is_white_piece = isupper(piece);
                    if (move_allowed(start_row, start_col, end_row, end_col) && 
                        (is_white_piece == white_plays)) {
                        execute_move(start_row, start_col, end_row, end_col);
                        move_confirmed = true;
                    }
                }
            }
            if (!move_confirmed) {
                cout << "Invalid move. Please try again." << endl;
            }
        }
        white_plays = !white_plays;
    }

    display_board();
    if (checkmate_condition(white_plays)) {
        cout << ((white_plays) ? "Black" : "White") << " wins by checkmate!" << endl;
    } else if (stalemate_condition(white_plays)) {
        cout << "Game ends in a draw due to stalemate." << endl;
    }

    return 0;
}

