// Split a string by a given delimiter character
std::vector<std::string> splitString(const std::string& input, char sep) {
    std::vector<std::string> parts;
    std::string currentPart;
    std::istringstream stream(input);

    while (std::getline(stream, currentPart, sep)) {
        parts.push_back(currentPart);
    }

    return parts;
}

int main() {
    std::string data = "apple,banana,cherry";
    char separator = ',';

    std::vector<std::string> result = splitString(data, separator);

    for (const auto& item : result) {
        std::cout << item << std::endl;
    }

    return 0;
}

