#include <iostream>
#include <vector>

int main() 
{ 
    const int total_terms = 100;
    std::vector<unsigned long long> fibonacci(total_terms);

    // Initialize first two Fibonacci numbers
    fibonacci[0] = 0; 
    fibonacci[1] = 1; 

    // Generate Fibonacci sequence using iterative approach
    for (int index = 2; index < total_terms; ++index) 
    { 
        fibonacci[index] = fibonacci[index - 1] + fibonacci[index - 2]; 
    } 

    // Output with formatting: 10 numbers per line
    const int items_per_row = 10;
    for (int position = 0; position < total_terms; ++position) 
    {
        std::cout << fibonacci[position] << " "; 

        // Check if we've printed enough numbers for current line
        if ((position + 1) % items_per_row == 0) {
            std::cout << "\n";
        }
    }

    return 0; 
}

