#include <sys/resource.h>
#include <iostream>

int main() {
    double total_time = 0.0;
    const int iterations = 10;
    const long count = 1000000L;

    struct rusage process_stats;
    struct timeval user_start, user_end, sys_start, sys_end;

    for (int rep = 0; rep < iterations; ++rep) {
        getrusage(RUSAGE_SELF, &process_stats);
        user_start = process_stats.ru_utime;
        sys_start = process_stats.ru_stime;

        // Empty loop to measure overhead
        for (long j = 0; j < count; ++j) {
            // Do nothing
        }

        getrusage(RUSAGE_SELF, &process_stats);
        user_end = process_stats.ru_utime;
        sys_end = process_stats.ru_stime;

        double user_time = static_cast<double>(user_end.tv_sec) + 
                          static_cast<double>(user_end.tv_usec) / 1000000.0;
        double system_time = static_cast<double>(sys_end.tv_sec) + 
                            static_cast<double>(sys_end.tv_usec) / 1000000.0;
        double start_user_time = static_cast<double>(user_start.tv_sec) + 
                                static_cast<double>(user_start.tv_usec) / 1000000.0;
        double start_sys_time = static_cast<double>(sys_start.tv_sec) + 
                               static_cast<double>(sys_start.tv_usec) / 1000000.0;

        total_time += ((user_time + system_time) - (start_user_time + start_sys_time)) / 
                     static_cast<double>(iterations);
    }

    std::cout << total_time << '\n';

    return 0;
}

