// Retrieve shader source code from an asset file
std::string retrieveShaderCode(AAssetManager* manager, const std::string& path) {
    AAsset* file = AAssetManager_open(manager, path.c_str(), AASSET_MODE_STREAMING);
    if (!file) {
        return "";
    }

    off_t size = AAsset_getLength(file);
    std::vector<char> data(size + 1);
    AAsset_read(file, data.data(), size);
    data[size] = '\0'; // Ensure null-termination
    AAsset_close(file);

    return std::string(data.data());
}

#include <cstddef>

struct TVersionizedPointer {
    std::intptr_t Ver;
    void* Ptr;
};

extern "C" {
    TVersionizedPointer* GetVersionizedPointer(void* PointerStorage, size_t size) {
        // Align the pointer to accommodate TVersionizedPointer structure
        std::uintptr_t base = reinterpret_cast<std::uintptr_t>(PointerStorage);
        std::uintptr_t alignment = alignof(TVersionizedPointer);
        std::uintptr_t alignedAddress = (base + alignment - 1) & ~(alignment - 1);

        return reinterpret_cast<TVersionizedPointer*>(alignedAddress);
    }
}

