int main() {
    cv::VideoCapture camera(0);
    vector<rectangle> detectedFaces;
    frontal_face_detector faceDetector = get_frontal_face_detector();
    cv::namedWindow("Face Detection Demo");
    cv::Mat currentFrame, resizedFrame;

    if (!camera.isOpened()) {
