    cv::destroyAllWindows();
    return 0;
}

#include <iostream>
#include <vector>
#include <mutex>
#include <cuda_runtime.h>

// Custom memory allocator for GPU device memory using a free list approach
class DeviceMemoryPool {
public:
    DeviceMemoryPool(size_t chunk_size, size_t chunk_count) 
        : chunk_size_(chunk_size), chunk_count_(chunk_count) {
        // Allocate contiguous GPU memory block
        cudaMalloc(&device_pool_, chunk_size * chunk_count);

        // Prepare tracking structures
        block_info_.resize(chunk_count);
        for (size_t i = 0; i < chunk_count; ++i) {
            block_info_[i].available = true;
            block_info_[i].id = static_cast<int>(i);
            block_info_[i].next_available = static_cast<int>(i + 1);
        }
        block_info_[chunk_count - 1].next_available = -1;
        first_free_block_ = 0;
    }

    ~DeviceMemoryPool() {
        cudaFree(device_pool_);
    }

    void* request_memory() {
        std::lock_guard<std::mutex> guard(access_mutex_);

        if (first_free_block_ == -1) {
            throw std::runtime_error("No available memory blocks");
        }

        int current_id = first_free_block_;
        first_free_block_ = block_info_[current_id].next_available;

        block_info_[current_id].available = false;
        return static_cast<char*>(device_pool_) + current_id * chunk_size_;
    }

    void release_memory(void* address) {
        std::lock_guard<std::mutex> guard(access_mutex_);

        size_t offset = static_cast<char*>(address) - static_cast<char*>(device_pool_);
        int block_index = static_cast<int>(offset / chunk_size_);

        block_info_[block_index].available = true;
        block_info_[block_index].next_available = first_free_block_;
        first_free_block_ = block_index;
    }

private:
    size_t const chunk_size_;
    size_t const chunk_count_;
    void* device_pool_;
    std::vector<struct MemoryBlock> block_info_;
    int first_free_block_;
    std::mutex access_mutex_;

    struct MemoryBlock {
        bool available;
        int id;
        int next_available;
    };
};

int main() {
    DeviceMemoryPool pool(256, 1024);

    void* block_a = pool.request_memory();
    void* block_b = pool.request_memory();

    pool.release_memory(block_a);
    pool.release_memory(block_b);

    return 0;
}

#include <pybind11/pybind11.h>
#include <pybind11/stl.h>
#include <vector>
#include <memory>
#include <unordered_map>

namespace py = pybind11;

class Foo {
public:
    Foo() : a(5) {}

    int a;
};

class Bar {
public:
    Bar() {
        auto foo1 = std::make_shared<Foo>();
        auto foo2 = std::make_shared<Foo>();
        foos.emplace_back(foo1);
        foos.emplace_back(foo2);
    }

    std::vector<std::shared_ptr<Foo>> foos;
};

PYBIND11_MODULE(pybug, m) {
    py::class_<Foo, std::shared_ptr<Foo>> foo_class(m, "Foo", py::dynamic_attr());
    foo_class
        .def(py::init<>())
        .def_readwrite("a", &Foo::a);

    py::class_<Bar> bar_class(m, "Bar");
    bar_class
        .def(py::init<>())
        .def_property_readonly("foos", [](Bar &b) {
            static std::unordered_map<std::shared_ptr<Foo>, py::handle> obj_cache;
            py::list result_list;

            for (const auto &item : b.foos) {
                auto iter = obj_cache.find(item);
                if (iter == obj_cache.end()) {
                    py::object temp_obj = py::cast(item, py::return_value_policy::reference);
                    obj_cache[item] = temp_obj;
                    result_list.append(temp_obj);
                } else {
                    result_list.append(iter->second);
                }
            }
            return result_list;
        });
}

#include <altivec.h>
#undef vector

typedef __vector unsigned char uint8x16_p;

// Load 8 bytes from memory into a vector register using alternative addressing
uint8x16_p VectorFastLoad8(const void* p)
{
    long offset = 0;
    uint8x16_p res;

    // Use pointer arithmetic instead of division for offset calculation
    const char* addr = static_cast<const char*>(p);
    __asm__ volatile (
        "lxvd2x %x0, %1, %2"
        : "=wa" (res)
        : "r" (addr), "r" (offset >> 2)
        : "memory"
    );

    return res;
}

#include <cuda_runtime.h>
#include <thrust/device_vector.h>
#include <thrust/sort.h>
#include <thrust/execution_policy.h>

struct Point {
    float x, y;
};

struct TreeNode {
    int leftIdx, rightIdx;  // Child node indices
    int begin, finish;      // Range of points in the array
    int splitDim;           // Splitting dimension (0 for x, 1 for y)
    float threshold;        // Splitting value
};

__global__ void constructTreeKernel(Point* points, TreeNode* nodes, int* workList, int* listSize, int* nextNodeCounter) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= *listSize) return;

    int current = workList[idx];
    TreeNode& node = nodes[current];
    int lo = node.begin;
    int hi = node.finish;
    int dim = node.splitDim;

    // Sort points in the current range by the specified dimension
    thrust::sort(thrust::device, points + lo, points + hi, [dim] __device__ (const Point& a, const Point& b) {
        return (dim == 0) ? a.x < b.x : a.y < b.y;
    });

    // Determine median index and splitting value
    int mid = (lo + hi) / 2;
    float splitVal = (dim == 0) ? points[mid].x : points[mid].y;

    // Allocate new child nodes atomically
    int leftChild = atomicAdd(nextNodeCounter, 1);
    int rightChild = atomicAdd(nextNodeCounter, 1);

    // Initialize children with updated parameters
    nodes[leftChild] = { -1, -1, lo, mid, 1 - dim, 0.0f };
    nodes[rightChild] = { -1, -1, mid + 1, hi, 1 - dim, 0.0f };

    // Update current node with split info and child references
    node.threshold = splitVal;
    node.leftIdx = leftChild;
    node.rightIdx = rightChild;

    // Push children onto the work stack
    workList[*listSize] = leftChild;
    workList[(*listSize)++] = rightChild;
}

void constructKdTree(Point* d_points, int pointCount, TreeNode* d_nodes, int maxNodes) {
    // Setup initial root node
    TreeNode initialNode = { -1, -1, 0, pointCount, 0, 0.0f };
    cudaMemcpy(d_nodes, &initialNode, sizeof(TreeNode), cudaMemcpyHostToDevice);

    // Allocate device memory for stack management
    int* d_workList;
    cudaMalloc(&d_workList, maxNodes * sizeof(int));
    int* d_listSize;
    cudaMalloc(&d_listSize, sizeof(int));
    int* d_nextNodeCounter;
    cudaMalloc(&d_nextNodeCounter, sizeof(int));

    // Initialize stack state
    int h_listSize = 1;
    int h_nextNodeCounter = 1;
    cudaMemcpy(d_workList, &initialNode, sizeof(TreeNode), cudaMemcpyHostToDevice);
    cudaMemcpy(d_listSize, &h_listSize, sizeof(int), cudaMemcpyHostToDevice);
    cudaMemcpy(d_nextNodeCounter, &h_nextNodeCounter, sizeof(int), cudaMemcpyHostToDevice);

    // Launch configuration
    int threadsPerBlock = 256;
    int blocksPerGrid = (maxNodes + threadsPerBlock - 1) / threadsPerBlock;

    // Iteratively process tree levels until stack is empty
    while (h_listSize > 0) {
        constructTreeKernel<<<blocksPerGrid, threadsPerBlock>>>(
            d_points, d_nodes, d_workList, d_listSize, d_nextNodeCounter);
        cudaDeviceSynchronize();

        // Retrieve updated stack size and counter from device
        cudaMemcpy(&h_listSize, d_listSize, sizeof(int), cudaMemcpyDeviceToHost);
        cudaMemcpy(&h_nextNodeCounter, d_nextNodeCounter, sizeof(int), cudaMemcpyDeviceToHost);
    }

    // Cleanup allocated resources
    cudaFree(d_workList);
    cudaFree(d_listSize);
    cudaFree(d_nextNodeCounter);
}

