using namespace std;

// Function to substitute variables in a formula and compute the result
string evaluateExpression(string expression, vector<pair<string, string>> varMap) {
    // Replace known variables with their values
    for (const auto& var : varMap) {
        size_t pos = 0;
        while ((pos = expression.find(var.first, pos)) != string::npos) {
            // Ensure we replace whole words only (simple check: space or boundary)
            if ((pos == 0 || !isalnum(expression[pos - 1])) &&
                (pos + var.first.length() >= expression.length() || 
                 !isalnum(expression[pos + var.first.length()]))) {
                expression.replace(pos, var.first.length(), var.second);
                pos += var.second.length();
            } else {
                pos += var.first.length();
            }
        }
    }

    // Parse and compute the arithmetic expression
    try {
        double value = parseArithmetic(expression);
        ostringstream oss;
        oss << value;
        return oss.str();
    } catch (...) {
        return "Error";
    }
}

// Helper function to compute simple arithmetic expressions (e.g., "5 * 2 + 3")
double parseArithmetic(const string& expr) {
    istringstream iss(expr);
    double total = 0.0;
    char op = '+';
    double num;

    if (!(iss >> total)) {
        throw runtime_error("Invalid numeric format");
    }

    while (iss >> op >> num) {
        switch (op) {
            case '+': total += num; break;
            case '-': total -= num; break;
            case '*': total *= num; break;
            case '/': 
                if (num == 0) throw runtime_error("Division by zero");
                total /= num; 
                break;
            default:
                throw runtime_error("Unsupported operator");
        }
    }

    return total;
}

int main() {
    string filename = "formulas.txt";
    ifstream input(filename);
    vector<pair<string, string>> formulaList;

    // Load formulas from file
    string line;
    while (getline(input, line)) {
        size_t eqPos = line.find('=');
        if (eqPos != string::npos && eqPos > 0) {
            string name = line.substr(0, eqPos);
            string expr = line.substr(eqPos + 1);
            formulaList.emplace_back(name, expr);
        }
    }
    input.close();

    // Ask user for context (variables and keywords)
    cout << "Enter your calculation context (e.g., voltage=5V, I=1A, t=10s): ";
    string userInput;
    getline(cin, userInput);

    // Parse variable assignments
    vector<pair<string, string>> assignments;
    istringstream context(userInput);
    string part;
    while (getline(context, part, ',')) {
        size_t eqIdx = part.find('=');
        if (eqIdx != string::npos) {
            string key = part.substr(0, eqIdx);
            string val = part.substr(eqIdx + 1);
            // Trim spaces
            while (!key.empty() && isspace(key.back())) key.pop_back();
            while (!val.empty() && isspace(val.front())) val.erase(0, 1);
            assignments.emplace_back(key, val);
        }
    }

    // Search for matching formula and compute
    string targetKeywords;
    for (const auto& ch : userInput) {
        if (isalpha(ch)) targetKeywords += ch;
    }

    for (const auto& [name, expr] : formulaList) {
        bool match = true;
        for (size_t i = 0; i < name.length(); ++i) {
            if (targetKeywords.find(name[i]) == string::npos) {
                match = false;
                break;
            }
        }
        if (match) {
            string computed = evaluateExpression(expr, assignments);
            cout << name << ": " << computed << endl;
        }
    }

    return 0;
}

#include <cstdio>
#include <cstring>
#include <sys/mman.h>

// Allocate memory with read/write/execute permissions for JIT compilation
void* create_runtime_buffer(size_t bytes) {
    void *region = mmap(
        nullptr,
        bytes,
        PROT_READ | PROT_WRITE | PROT_EXEC,
        MAP_PRIVATE | MAP_ANONYMOUS,
        -1,
        0
    );

    if (region == MAP_FAILED) {
        std::perror("Memory allocation failed");
        return nullptr;
    }
    return region;
}

// Copy bytecode into the allocated executable region
void inject_bytecode(size_t len, const unsigned char *source, void *target) {
    std::memcpy(static_cast<unsigned char*>(target), source, len);
}

// Function pointer type for our generated code
using ExecutableRoutine = void (*)();

int main() {
    // Machine code for: write(1, "X", 1); exit(0);
    unsigned char program[] = {
        0x48, 0xc7, 0xc0, 0x01, 0x00, 0x00, 0x00,  // rax = 1 (sys_write)
        0x48, 0xc7, 0xc7, 0x01, 0x00, 0x00, 0x00,  // rdi = 1 (stdout)
        0x48, 0xc7, 0xc6, 0x01, 0x00, 0x00, 0x00,  // rsi = message address
        0x48, 0xc7, 0xc2, 0x01, 0x00, 0x00, 0x00,  // rdx = 1 (length)
        0x0f, 0x05,                                // syscall
        0x48, 0xc7, 0xc0, 0x3c, 0x00, 0x00, 0x00,  // rax = 60 (sys_exit)
        0x48, 0x31, 0xff,                          // rdi = 0 (exit status)
        0x0f, 0x05                                 // syscall
    };

    size_t code_size = sizeof(program);
    void *runtime_area = create_runtime_buffer(code_size);

    if (runtime_area == nullptr) {
        return 1;
    }

    inject_bytecode(code_size, program, runtime_area);

    ExecutableRoutine runner = reinterpret_cast<ExecutableRoutine>(runtime_area);
    runner();

    return 0;
}

