#include <stdexcept>

class MinPriorityQueue {
public:
    MinPriorityQueue() = default;

    // Add a new element to the priority queue
    void enqueue(int val) {
        data.push_back(val);
        heapifyUp(data.size() - 1);
    }

    // Remove and return the smallest element
    int dequeue() {
        if (data.empty()) {
            throw std::runtime_error("Priority queue is empty");
        }

        int minVal = data[0];
        data[0] = data.back();
        data.pop_back();

        if (!data.empty()) {
            heapifyDown(0);
        }

        return minVal;
    }

    // Peek at the smallest element without removing it
    int peek() const {
        if (data.empty()) {
            throw std::runtime_error("Priority queue is empty");
        }
        return data.front();
    }

    // Check if the priority queue is empty
    bool isEmpty() const {
        return data.empty();
    }

    // Return the number of elements in the priority queue
    size_t count() const {
        return data.size();
    }

private:
    std::vector<int> data;

    // Move element up to maintain heap property
    void heapifyUp(int idx) {
        while (idx > 0) {
            int parentIdx = (idx - 1) / 2;
            if (data[idx] < data[parentIdx]) {
                std::swap(data[idx], data[parentIdx]);
                idx = parentIdx;
            } else {
                break;
            }
        }
    }

    // Move element down to maintain heap property
    void heapifyDown(int idx) {
        int n = static_cast<int>(data.size());
        while (true) {
            int leftChild = 2 * idx + 1;
            int rightChild = 2 * idx + 2;
            int minIdx = idx;

            if (leftChild < n && data[leftChild] < data[minIdx]) {
                minIdx = leftChild;
            }

            if (rightChild < n && data[rightChild] < data[minIdx]) {
                minIdx = rightChild;
            }

            if (minIdx != idx) {
                std::swap(data[idx], data[minIdx]);
                idx = minIdx;
            } else {
                break;
            }
        }
    }
};

// Demonstration of the priority queue functionality
int main() {
    MinPriorityQueue pq;
    pq.enqueue(3);
    pq.enqueue(2);
    pq.enqueue(15);
    pq.enqueue(5);
    pq.enqueue(4);
    pq.enqueue(45);

    while (!pq.isEmpty()) {
        std::cout << pq.dequeue() << " ";
    }

    return 0;
}

