#include <algorithm>
#include <random>
#include <cmath>
#include <limits>

using namespace std;

struct City {
    int id;
    double x, y;
};

double calculateDistance(const City& pointA, const City& pointB) {
    double dx = pointA.x - pointB.x;
    double dy = pointA.y - pointB.y;
    return sqrt(dx * dx + dy * dy);
}

double evaluateTour(const vector<City>& locations, const vector<int>& route) {
    double totalDistance = 0.0;
    int n = route.size();
    for (int i = 0; i < n; ++i) {
        int nextIndex = (i + 1) % n;
        totalDistance += calculateDistance(locations[route[i]], locations[route[nextIndex]]);
    }
    return totalDistance;
}

vector<vector<double>> buildDistanceTable(const vector<City>& cities) {
    int size = cities.size();
    vector<vector<double>> distanceMatrix(size, vector<double>(size));
    for (int i = 0; i < size; ++i) {
        for (int j = 0; j < size; ++j) {
            distanceMatrix[i][j] = calculateDistance(cities[i], cities[j]);
        }
    }
    return distanceMatrix;
}

// Order Crossover (OX) implementation
vector<int> performCrossover(const vector<int>& parentA, const vector<int>& parentB) {
    int length = parentA.size();
    vector<int> child(length, -1);

    // Select two random cut points
    int cut1 = rand() % length;
    int cut2 = rand() % length;
    if (cut1 > cut2) swap(cut1, cut2);

    // Copy segment from parentA to child
    for (int i = cut1; i <= cut2; ++i) {
        child[i] = parentA[i];
    }

    // Fill remaining positions with genes from parentB
    int pos = (cut2 + 1) % length;
    int idx = (cut2 + 1) % length;

    while (pos != cut1) {
        if (find(child.begin(), child.end(), parentB[idx]) == child.end()) {
            child[pos] = parentB[idx];
            pos = (pos + 1) % length;
        }
        idx = (idx + 1) % length;
    }

    return child;
}

// Inversion mutation: reverse a random subsequence
void applyMutation(vector<int>& individual, double rate) {
    for (int i = 0; i < individual.size(); ++i) {
        if (rand() / static_cast<double>(RAND_MAX) < rate) {
            int start = rand() % individual.size();
            int end = rand() % individual.size();
            if (start > end) swap(start, end);
            reverse(individual.begin() + start, individual.begin() + end + 1);
        }
    }
}

// Tournament selection
int tournamentSelection(const vector<pair<double, vector<int>>>& populationWithFitness, int tournamentSize) {
    int bestIdx = rand() % populationWithFitness.size();
    for (int i = 1; i < tournamentSize; ++i) {
        int candidate = rand() % populationWithFitness.size();
        if (populationWithFitness[candidate].first < populationWithFitness[bestIdx].first) {
            bestIdx = candidate;
        }
    }
    return bestIdx;
}

vector<int> solveTSP_GA(const vector<City>& locations, int populationCount, double mutationProbability, int maxGenerations) {
    int cityCount = locations.size();
    vector<vector<int>> currentPopulation(populationCount, vector<int>(cityCount));

    // Initialize population with random permutations
    for (int i = 0; i < populationCount; ++i) {
        for (int j = 0; j < cityCount; ++j) {
            currentPopulation[i][j] = j;
        }
        random_shuffle(currentPopulation[i].begin(), currentPopulation[i].end());
    }

    for (int generation = 0; generation < maxGenerations; ++generation) {
        // Evaluate fitness for each individual
        vector<pair<double, vector<int>>> evaluatedPopulation;
        for (const auto& route : currentPopulation) {
            evaluatedPopulation.push_back({evaluateTour(locations, route), route});
        }

        // Sort by fitness (shortest distance first)
        sort(evaluatedPopulation.begin(), evaluatedPopulation.end(),
             [](const pair<double, vector<int>>& a, const pair<double, vector<int>>& b) {
                 return a.first < b.first;
             });

        // Create new population using tournament selection and crossover
        vector<vector<int>> nextGeneration;

        // Elitism: keep the best solution
        nextGeneration.push_back(evaluatedPopulation[0].second);

        // Fill rest of population through selection and crossover
        while (nextGeneration.size() < populationCount) {
            int parentIdx1 = tournamentSelection(evaluatedPopulation, 5);
            int parentIdx2 = tournamentSelection(evaluatedPopulation, 5);

            vector<int> offspring = performCrossover(evaluatedPopulation[parentIdx1].second,
                                                    evaluatedPopulation[parentIdx2].second);

            applyMutation(offspring, mutationProbability);
            nextGeneration.push_back(offspring);
        }

        currentPopulation = nextGeneration;
    }

    // Find and return the best solution found
    vector<pair<double, vector<int>>> finalEvaluation;
    for (const auto& route : currentPopulation) {
        finalEvaluation.push_back({evaluateTour(locations, route), route});
    }
    sort(finalEvaluation.begin(), finalEvaluation.end(),
         [](const pair<double, vector<int>>& a, const pair<double, vector<int>>& b) {
             return a.first < b.first;
         });

    return finalEvaluation[0].second;
}

int main() {
    vector<City> cityList = {{0, 0, 0}, {1, 1, 2}, {2, 3, 1}, {3, 5, 5}, {4, 6, 2}};
    int populationSize = 100;
    double mutationChance = 0.01;
    int numberOfGenerations = 1000;

    vector<int> optimalRoute = solveTSP_GA(cityList, populationSize, mutationChance, numberOfGenerations);

    cout << "Optimal Route: ";
    for (int cityIndex : optimalRoute) {
        cout << cityList[cityIndex].id << " ";
    }
    cout << "\nTotal Distance: " << evaluateTour(cityList, optimalRoute) << endl;

    return 0;
}

