using namespace Eigen;

// Ray representation with origin and direction
struct LightPath {
    Vector3f start;
    Vector3f dir;
    LightPath(Vector3f o, Vector3f d) : start(o), dir(d) {}
};

// Spherical object with position, size, and color properties
struct Ball {
    Vector3f pos;
    float size;
    Vector3f shade;
    Ball(Vector3f c, float r, Vector3f col) : pos(c), size(r), shade(col) {}

    // Check intersection between ray and sphere
    bool hit(const LightPath& path, float& dist) const {
        Vector3f center_to_origin = pos - path.start;
        float projection = center_to_origin.dot(path.dir);

        if (projection < 0) return false; // Behind the ray

        float distance_squared = center_to_origin.squaredNorm() - projection * projection;
        float radius_squared = size * size;

        if (distance_squared > radius_squared) return false; // Missed the sphere

        float depth = std::sqrt(radius_squared - distance_squared);
        dist = projection - depth;
        return true;
    }
};

Vector3f compute_lighting(const LightPath& path, const std::vector<Ball>& objects) {
    float min_distance = std::numeric_limits<float>::max();
    const Ball* nearest_object = nullptr;

    for (const auto& obj : objects) {
        float distance;
        if (obj.hit(path, distance) && distance < min_distance) {
            min_distance = distance;
            nearest_object = &obj;
        }
    }

    if (nearest_object) {
        Vector3f impact_point = path.start + path.dir * min_distance;
        Vector3f surface_normal = (impact_point - nearest_object->pos).normalized();
        Vector3f illumination_direction = Vector3f(1, -1, -1).normalized();
        float intensity = std::max(0.0f, surface_normal.dot(illumination_direction));
        return nearest_object->shade * intensity;
    }

    return Vector3f(0, 0, 0); // Default background color
}

int main() {
    int image_width = 800, image_height = 600;
    std::vector<Vector3f> pixels(image_width * image_height, Vector3f(0, 0, 0));

    Vector3f eye_position(0, 0, -5);
    Vector3f screen_center(0, 0, 0);
    float view_width = 2.0f, view_height = 2.0f * image_height / image_width;

    std::vector<Ball> scene_objects = {
        Ball(Vector3f(0, 0, 0), 1, Vector3f(1, 0, 0)),
        Ball(Vector3f(1, 0, 0), 1, Vector3f(0, 1, 0)),
        Ball(Vector3f(-1, 0, 0), 1, Vector3f(0, 0, 1))
    };

    // Generate rays for each pixel
    for (int row = 0; row < image_height; ++row) {
        for (int col = 0; col < image_width; ++col) {
            float u_param = (2 * (col + 0.5) / image_width - 1) * view_width;
            float v_param = (1 - 2 * (row + 0.5) / image_height) * view_height;
            Vector3f pixel_position(screen_center + Vector3f(u_param, v_param, 0));
            LightPath ray(eye_position, (pixel_position - eye_position).normalized());
            pixels[row * image_width + col] = compute_lighting(ray, scene_objects);
        }
    }

    // Output pixel data in RGB format
    for (int row = 0; row < image_height; ++row) {
        for (int col = 0; col < image_width; ++col) {
            Vector3f pixel_color = pixels[row * image_width + col];
            std::cout << (int)(255 * std::min(1.0f, pixel_color[0])) << " "
                      << (int)(255 * std::min(1.0f, pixel_color[1])) << " "
                      << (int)(255 * std::min(1.0f, pixel_color[2])) << "\n";
        }
    }

    return 0;
}

#include <iostream>
#include <list>
#include <algorithm>

class OptimizedRangeTracker {
private:
    std::list<int> data;
    std::list<int>::iterator minPos;
    std::list<int>::iterator maxPos;

public:
    OptimizedRangeTracker() : minPos(data.end()), maxPos(data.end()) {}

    void addElement(int val) {
        data.push_back(val);
        auto current = std::prev(data.end());

        if (minPos == data.end() || val < *minPos) {
            minPos = current;
        }
        if (maxPos == data.end() || val > *maxPos) {
            maxPos = current;
        }
    }

    void deleteElement(int val) {
        auto iter = std::find(data.begin(), data.end(), val);
        if (iter != data.end()) {
            bool wasMin = (iter == minPos);
            bool wasMax = (iter == maxPos);

            if (wasMin) {
                if (iter == data.begin()) {
                    minPos = data.end();
                } else {
                    minPos = std::prev(iter);
                }
            }

            if (wasMax) {
                if (std::next(iter) == data.end()) {
                    maxPos = data.end();
                } else {
                    maxPos = std::next(iter);
                }
            }

            data.erase(iter);

            // Revalidate iterators after removal
            if (data.empty()) {
                minPos = data.end();
                maxPos = data.end();
            } else {
                if (wasMin) {
                    minPos = std::min_element(data.begin(), data.end());
                }
                if (wasMax) {
                    maxPos = std::max_element(data.begin(), data.end());
                }
            }
        }
    }

    int findMinimum() const {
        return (minPos != data.end()) ? *minPos : -1;
    }

    int findMaximum() const {
        return (maxPos != data.end()) ? *maxPos : -1;
    }
};

int main() {
    OptimizedRangeTracker tracker;
    tracker.addElement(5);
    tracker.addElement(3);
    tracker.addElement(7);

    std::cout << "Minimum: " << tracker.findMinimum() << std::endl; // 3
    std::cout << "Maximum: " << tracker.findMaximum() << std::endl; // 7

    tracker.deleteElement(3);
    std::cout << "Minimum after deletion: " << tracker.findMinimum() << std::endl; // 5

    return 0;
}

#include <boost/python.hpp>
