// Helper function to convert OpenCV matrix to Python numpy array (double precision)
boost::python::object cvmat_to_ndarray(const cv::Mat& image) {
    npy_intp shape[2] = {image.rows, image.cols};
    PyObject* ndarray_obj = PyArray_SimpleNew(2, shape, NPY_FLOAT64);
    std::memcpy(PyArray_DATA(reinterpret_cast<PyArrayObject*>(ndarray_obj)), 
                image.ptr<double>(), 
                image.total() * sizeof(double));
    return boost::python::object(boost::python::handle<>(boost::python::borrowed(ndarray_obj)));
}

// Helper function to convert Python numpy array back to OpenCV matrix
cv::Mat ndarray_to_cvmat(boost::python::object& py_array) {
    PyArrayObject* arr = reinterpret_cast<PyArrayObject*>(py_array.ptr());
    npy_intp* dimensions = PyArray_DIMS(arr);
    cv::Mat result(dimensions[0], dimensions[1], CV_64F, PyArray_DATA(arr));
    return result;
}

// Function demonstrating interaction with scikit-learn via Boost.Python
void execute_sklearn_workflow() {
    // Set up Python environment access
    boost::python::object main_module = boost::python::import("__main__");
    boost::python::object global_namespace = main_module.attr("__dict__");

    // Import required modules from scikit-learn
    boost::python::object sklearn_pkg = boost::python::import("sklearn");
    boost::python::object data_utils = sklearn_pkg.attr("datasets");
    boost::python::object estimators = sklearn_pkg.attr("linear_model");

    // Load and prepare dataset
    boost::python::object iris_data = data_utils.attr("load_iris")();
    boost::python::object features = iris_data.attr("data");
    boost::python::object labels = iris_data.attr("target");

    // Initialize and train logistic regression model
    boost::python::object classifier = estimators.attr("LogisticRegression")();
    classifier.attr("fit")(features, labels);

    // Perform prediction on training data
    boost::python::object raw_predictions = classifier.attr("predict")(features);
    boost::python::list python_list = boost::python::extract<boost::python::list>(raw_predictions);

    // Transfer predictions to C++ container
    std::vector<int> host_predictions;
    int count = boost::python::len(python_list);
    for (int idx = 0; idx < count; ++idx) {
        host_predictions.push_back(boost::python::extract<int>(python_list[idx]));
    }

    // Output results to console
    for (auto val : host_predictions) {
        std::cout << val << " ";
    }
    std::cout << std::endl;
}

// Module definition for Python extension
BOOST_PYTHON_MODULE(sklearn_bridge) {
    using namespace boost::python;
    def("execute_sklearn_workflow", execute_sklearn_workflow);
}

// Standalone entry point for testing purposes
int standalone_main() {
    Py_Initialize();
    import_array(); // Required for NumPy C-API initialization

    // Execute the workflow directly
    execute_sklearn_workflow();

    Py_Finalize();
    return 0;
}

#include <boost/python.hpp>
#include <vector>

// Base abstract class with pure virtual function
class InterfaceA {
public:
    std::vector<int> data;

    virtual ~InterfaceA() = default;
    virtual void process() = 0;
};

// Another interface with dependency on InterfaceA
class InterfaceB {
public:
    virtual ~InterfaceB() = default;
    virtual void execute(const InterfaceA& input) = 0;
};

namespace py = boost::python;

// Wrapper for InterfaceA to support Python overrides
class PyInterfaceA : public InterfaceA, py::wrapper<InterfaceA> {
public:
    void process() override {
        if (py::override func = this->get_override("process")) {
            func();
        }
    }
};

// Wrapper for InterfaceB to support Python overrides
class PyInterfaceB : public InterfaceB, py::wrapper<InterfaceB> {
public:
    void execute(const InterfaceA& input) override {
        if (py::override func = this->get_override("execute")) {
            func(input);
        }
    }
};

// Custom converter from C++ InterfaceA to Python object
struct InterfaceA_to_python {
    static PyObject* convert(const InterfaceA& obj) {
        py::object pyObj = py::object(py::ptr(new PyInterfaceA(obj)));
        return pyObj.ptr();
    }
};

BOOST_PYTHON_MODULE(example_module) {
    using int_vector = std::vector<int>;

    // Expose std::vector<int> as a Python list-like type
    py::class_<int_vector>("IntSequence")
        .def(py::vector_indexing_suite<int_vector>());

    // Register InterfaceA and its wrapper
    py::class_<InterfaceA, PyInterfaceA, boost::noncopyable>("InterfaceA")
        .def_readwrite("data", &InterfaceA::data)
        .def("process", py::pure_virtual(&InterfaceA::process));

    // Register InterfaceB and its wrapper
    py::class_<InterfaceB, PyInterfaceB, boost::noncopyable>("InterfaceB")
        .def("execute", py::pure_virtual(&InterfaceB::execute));

    // Set up automatic conversion from InterfaceA to Python object
    py::to_python_converter<InterfaceA, InterfaceA_to_python>();
}

