// Compute the cost function for linear regression using mean squared error
double calculate_error(const std::vector<double>& inputs, const std::vector<double>& outputs, double intercept, double slope) {
    int sample_count = inputs.size();
    double total_error = 0.0;

    // Use index-based iteration to compute squared differences
    for (int idx = 0; idx < sample_count; ++idx) {
        double predicted = intercept + slope * inputs[idx];
        double difference = predicted - outputs[idx];
        total_error += difference * difference;
    }

    return total_error / (2.0 * sample_count);
}

// Perform gradient descent optimization to minimize the cost function
void optimize_parameters(const std::vector<double>& inputs, const std::vector<double>& outputs, 
                        double& intercept, double& slope, double learning_rate, int max_steps) {
    int sample_count = inputs.size();

    // Iterate for the specified number of steps
    for (int step = 0; step < max_steps; ++step) {
        double temp_intercept = 0.0;
        double temp_slope = 0.0;

        // Accumulate gradients over all samples
        for (int idx = 0; idx < sample_count; ++idx) {
            double prediction = intercept + slope * inputs[idx];
            double error = prediction - outputs[idx];

            temp_intercept += error;
            temp_slope += error * inputs[idx];
        }

        // Update parameters using the computed gradients
        intercept -= learning_rate * temp_intercept / sample_count;
        slope -= learning_rate * temp_slope / sample_count;

        // Monitor progress by calculating current cost
        double current_error = calculate_error(inputs, outputs, intercept, slope);
        std::cout << "Step " << step << " - Error: " << current_error << std::endl;
    }
}

int main() {
    // Training data points
    std::vector<double> x_values = {1, 2, 3, 4, 5};
    std::vector<double> y_values = {2, 4, 5, 4, 5};

    // Initialize parameters
    double intercept = 0.0;
    double slope = 0.0;
    double learning_rate = 0.01;
    int training_steps = 1000;

    // Run the optimization process
    optimize_parameters(x_values, y_values, intercept, slope, learning_rate, training_steps);

    // Output final learned parameters
    std::cout << "Final intercept: " << intercept << ", slope: " << slope << std::endl;

    return 0;
}

