#include <iostream>
#include "xtensor/xreducer.hpp"
#include "xtensor/xrandom.hpp"
#include <ctime>

using namespace std;

// Function to measure execution time and sum of random array
pair<double, double> benchmark_reduction(int array_size, int iterations = 30) {
    double total_time = 0.0;
    double accumulated_sum = 0.0;

    for (int iter = 0; iter < iterations; ++iter) {
        // Generate random tensor with values in [0, 1)
        xt::xtensor<double, 1> data = xt::random::rand({array_size}, 0.0, 1.0);

        // Start timing
        clock_t begin = clock();

        // Compute sum using immediate evaluation with parallel execution
        double result = xt::sum(data, xt::evaluation_strategy::immediate, xt::parallelExecution())();

        // End timing
        clock_t end = clock();

        // Accumulate results
        accumulated_sum += result;
        total_time += static_cast<double>(end - begin);
    }

    // Return average time per iteration and total sum
    return make_pair(total_time / CLOCKS_PER_SEC / iterations, accumulated_sum);
}

int main(int argc, char *argv[]) {
    // Test different array sizes: 10^5, 10^6, 10^7
    for (int exp = 5; exp <= 7; ++exp) {
        int n = static_cast<int>(pow(10, exp));
        pair<double, double> stats = benchmark_reduction(n);

        cout << "size: " << n 
             << " \t " << stats.first << " sec\t" 
             << stats.second << endl;
    }

    return 0;
}

#include <curl/curl.h>
#include <cstdio>
#include <iostream>

// Custom callback function to read data from file for upload
size_t file_reader(void *buffer, size_t block_size, size_t blocks, void *data) {
    FILE *fp = static_cast<FILE*>(data);
    if (fp != nullptr) {
        return fread(buffer, block_size, blocks, fp);
    }
    return 0;
}

int main() {
    CURL *handle = nullptr;
    FILE *input_file = nullptr;
    CURLcode result_code;

    // Initialize global curl environment
    curl_global_init(CURL_GLOBAL_ALL);
    handle = curl_easy_init();

    if (handle) {
        // Open the local file in binary read mode
        input_file = fopen("path_to_your_file", "rb");
        if (input_file) {
            // Configure the curl session
            curl_easy_setopt(handle, CURLOPT_URL, "http://yourserver.com/upload");
            curl_easy_setopt(handle, CURLOPT_READFUNCTION, file_reader);
            curl_easy_setopt(handle, CURLOPT_READDATA, input_file);
            curl_easy_setopt(handle, CURLOPT_UPLOAD, 1L);

            // Prepare HTTP headers for range-based upload resumption
            struct curl_slist *headers = nullptr;
            headers = curl_slist_append(headers, "Content-Range: bytes 0-4999/100000");
            curl_easy_setopt(handle, CURLOPT_HTTPHEADER, headers);

            // Execute the upload request
            result_code = curl_easy_perform(handle);

            // Handle potential errors
            if (result_code != CURLE_OK) {
                std::cerr << "Upload failed: " << curl_easy_strerror(result_code) << std::endl;
            }

            // Clean up header list and close file
            curl_slist_free_all(headers);
            fclose(input_file);
        }

        // Clean up curl resources
        curl_easy_cleanup(handle);
    }

    // Finalize global curl state
    curl_global_cleanup();
    return 0;
}

