// Template function with compile-time enable flag
template<bool Enable>
void compute_vector_sum()
{
    double arr_dst[4] = {1.0, 1.0, 1.0, 1.0};
    double arr_src[4] = {1.0, 2.0, 3.0, 4.0};
    double* dst_ptr = arr_dst;
    double* src_ptr = arr_src;

    asm volatile (
        "vld1.64    {d0}, [%[src]]      \n" // Load first two elements
        "vld1.64    {d1}, [%[src], #16] \n" // Load next two elements
        "vld1.64    {d2}, [%[dst]]      \n" // Load destination

        "vadd.f64   d0, d0, d2          \n"
        "vadd.f64   d0, d0, d2          \n"

        // Conditional add based on Enable flag
        "cmp %[flag], #1                \n"
        "it eq                          \n"
        "vadd.f64   d0, d0, d2          \n"

        "vst1.64    {d0}, [%[dst]]      \n"
        "vst1.64    {d1}, [%[dst], #16] \n"
        : [src]"+r"(src_ptr),
          [dst]"+r"(dst_ptr)
        : [flag]"r"(Enable)
        : "d0", "d1", "d2", "memory"
    );

    for (int idx = 0; idx < 4; ++idx)
    {
        std::printf("%.1f, ", arr_dst[idx]);
    }
    std::printf("\n");
}

