#include <limits>
#include <cstdint>
#include <immintrin.h>

using T = uint32_t;

// Perform a right shift operation combining two values using _shrd intrinsic
T combineShift(T highPart, T lowPart, T shiftAmount)
{
    // Use the _shrd instruction to shift the combined 64-bit value (highPart:lowPart) right by shiftAmount bits
    return _shrd(highPart, lowPart, shiftAmount);
}

__inline__ __device__ uint32_t per_byte_bit_left_rotate(uint32_t input, uint8_t amount) {
    uint32_t output = 0;
    uint8_t shift_amount = amount % 8;  // Ensure amount is within byte range

    int byte_index = 0;
    uint32_t temp_input = input;

    while (byte_index < 4) {
        // Extract current byte
        uint8_t current_byte = temp_input & 0xFF;

        // Perform left rotation within the byte
        uint8_t rotated_byte = (current_byte << shift_amount) | (current_byte >> (8 - shift_amount));

        // Place rotated byte back into result
        output |= (rotated_byte << (byte_index * 8));

        // Move to next byte
        temp_input >>= 8;
        byte_index++;
    }

    return output;
}

#include <vector>
#include <iostream>
using namespace std;

// Merge two sorted arrays into nums1 in-place, removing duplicates
void merge(vector<int>& nums1, int m, vector<int>& nums2, int n) {
    // Start from the end of both valid parts
    int idx1 = m - 1;
    int idx2 = n - 1;
    int writePos = m + n - 1;

    // Process elements from the back
    while (idx1 >= 0 && idx2 >= 0) {
        if (nums1[idx1] > nums2[idx2]) {
            nums1[writePos] = nums1[idx1];
            // Skip duplicate values in nums1
            while (idx1 > 0 && nums1[idx1] == nums1[idx1 - 1]) {
                idx1--;
            }
            idx1--;
        } else if (nums1[idx1] < nums2[idx2]) {
            nums1[writePos] = nums2[idx2];
            // Skip duplicate values in nums2
            while (idx2 > 0 && nums2[idx2] == nums2[idx2 - 1]) {
                idx2--;
            }
            idx2--;
        } else {
            // Equal elements: place once and skip duplicates in both
            nums1[writePos] = nums1[idx1];
            writePos--;

            // Skip duplicates in nums1
            while (idx1 > 0 && nums1[idx1] == nums1[idx1 - 1]) {
                idx1--;
            }
            idx1--;

            // Skip duplicates in nums2
            while (idx2 > 0 && nums2[idx2] == nums2[idx2 - 1]) {
                idx2--;
            }
            idx2--;
        }
        writePos--;
    }

    // Copy any remaining elements from nums2
    while (idx2 >= 0) {
        nums1[writePos] = nums2[idx2];
        // Skip duplicates in nums2
        while (idx2 > 0 && nums2[idx2] == nums2[idx2 - 1]) {
            idx2--;
        }
        idx2--;
        writePos--;
    }

    // Ensure final size is correct
    nums1.resize(m + n);
}

