// Recursive function to compute factorial with input validation
long long computeFactorial(int value) {
    if (value < 0) {
        throw std::invalid_argument("Factorial is undefined for negative integers");
    }

    // Base cases: 0! = 1 and 1! = 1
    if (value == 0 || value == 1) {
        return 1;
    }

    // Recursive case: n! = n * (n-1)!
    return value * computeFactorial(value - 1);
}

// Unit tests for the factorial implementation
void runFactorialTests() {
    assert(computeFactorial(0) == 1);
    assert(computeFactorial(1) == 1);
    assert(computeFactorial(5) == 120);
    assert(computeFactorial(10) == 3628800);
    std::cout << "All unit tests completed successfully." << std::endl;
}

