#include <vector>

// Perform matrix multiplication: C = A * B
void performMatrixMultiplication(float* matrixA, float* matrixB, float* resultMatrix, int dimension) {
    // Iterate through each element position in the result matrix
    for (int colIndex = 0; colIndex < dimension; ++colIndex) {
        for (int rowIndex = 0; rowIndex < dimension; ++rowIndex) {
            float accumulatedValue = 0.0f;

            // Compute dot product of row from A and column from B
            for (int innerIndex = 0; innerIndex < dimension; ++innerIndex) {
                accumulatedValue += matrixA[rowIndex * dimension + innerIndex] * 
                                   matrixB[innerIndex * dimension + colIndex];
            }

            resultMatrix[rowIndex * dimension + colIndex] = accumulatedValue;
        }
    }
}

int main() {
    const int MATRIX_SIZE = 1024;

    // Initialize matrices with appropriate values
    std::vector<float> inputMatrixA(MATRIX_SIZE * MATRIX_SIZE, 1.0f);
    std::vector<float> inputMatrixB(MATRIX_SIZE * MATRIX_SIZE, 1.0f);
    std::vector<float> outputMatrix(MATRIX_SIZE * MATRIX_SIZE, 0.0f);

    // Measure execution time
    auto startTime = std::chrono::high_resolution_clock::now();
    performMatrixMultiplication(inputMatrixA.data(), inputMatrixB.data(), outputMatrix.data(), MATRIX_SIZE);
    auto endTime = std::chrono::high_resolution_clock::now();

    // Calculate and display elapsed time
    std::chrono::duration<double> elapsedTime = endTime - startTime;
    std::cout << "CPU Time: " << elapsedTime.count() << " seconds" << std::endl;

    return 0;
}

