// Game constants
const unsigned int SCREEN_X = 800;
const unsigned int SCREEN_Y = 600;
const float PADDLE_VELOCITY = 5.0f;
const float BALL_SIZE = 10.0f;
const float MOVEMENT_SPEED = 3.0f;

// Player paddle class
class Racket {
public:
    sf::RectangleShape body;
    float moveSpeed;

    Racket(float startX, float startY, float width, float height, float velocity) {
        body.setPosition(startX, startY);
        body.setSize({width, height});
        body.setFillColor(sf::Color::White);
        moveSpeed = velocity;
    }

    void goUp() {
        sf::Vector2<float> currentPos = body.getPosition();
        if (currentPos.y > 0.0f) {
            body.move(0.0f, -moveSpeed);
        }
    }

    void goDown() {
        sf::Vector2<float> currentPos = body.getPosition();
        if (currentPos.y + body.getSize().y < SCREEN_Y) {
            body.move(0.0f, moveSpeed);
        }
    }
};

// Moving ball class
class Sphere {
public:
    sf::CircleShape visual;
    sf::Vector2<float> motion;
    float rate;

    Sphere(float x, float y, float radius) {
        visual.setPosition(x, y);
        visual.setRadius(radius);
        visual.setFillColor(sf::Color::White);
        motion = {1.0f, 1.0f};
        rate = MOVEMENT_SPEED;
    }

    void refresh() {
        sf::Vector2<float> pos = visual.getPosition();
        pos += motion * rate;

        // Horizontal collision with walls
        if (pos.x <= 0 || pos.x + 2 * BALL_SIZE >= SCREEN_X) {
            motion.x = -motion.x;
        }

        // Vertical collision with top/bottom
        if (pos.y <= 0 || pos.y + 2 * BALL_SIZE >= SCREEN_Y) {
            motion.y = -motion.y;
        }

        visual.setPosition(pos);
    }
};

int main() {
    sf::RenderWindow display(sf::VideoMode(SCREEN_X, SCREEN_Y), "Pong");

    // Initialize game objects
    Racket leftRacket(50, SCREEN_Y / 2 - 50, 20, 100, PADDLE_VELOCITY);
    Racket rightRacket(SCREEN_X - 70, SCREEN_Y / 2 - 50, 20, 100, PADDLE_VELOCITY);
    Sphere centerBall(SCREEN_X / 2 - BALL_SIZE, SCREEN_Y / 2 - BALL_SIZE, BALL_SIZE);

    while (display.isOpen()) {
        sf::Event action;
        while (display.pollEvent(action)) {
            if (action.type == sf::Event::Closed)
                display.close();
        }

        // Handle player input for left racket
        if (sf::Keyboard::isKeyPressed(sf::Keyboard::W)) leftRacket.goUp();
        if (sf::Keyboard::isKeyPressed(sf::Keyboard::S)) leftRacket.goDown();

        // Simple AI for right racket
        if (centerBall.visual.getPosition().y > rightRacket.body.getPosition().y + 50) 
            rightRacket.goDown();
        if (centerBall.visual.getPosition().y < rightRacket.body.getPosition().y + 50) 
            rightRacket.goUp();

        // Update ball position and handle collisions
        centerBall.refresh();

        // Render frame
        display.clear(sf::Color::Black);
        display.draw(leftRacket.body);
        display.draw(rightRacket.body);
        display.draw(centerBall.visual);
        display.display();
    }

    return 0;
}

