// Helper function to convert string to lowercase for case-insensitive matching
std::string toLower(const std::string& str) {
    std::string result = str;
    for (char& c : result) {
        c = std::tolower(static_cast<unsigned char>(c));
    }
    return result;
}

// Check if any keyword appears in the sentence (case-insensitive)
bool hasKeyword(const std::string& text, const std::vector<std::string>& keywords) {
    std::string lowerText = toLower(text);
    for (const auto& keyword : keywords) {
        std::string lowerKeyword = toLower(keyword);
        if (lowerText.find(lowerKeyword) != std::string::npos) {
            return true;
        }
    }
    return false;
}

// Determine the intent of a sentence based on keywords
std::string determineIntent(const std::string& sentence) {
    // Map intents to their associated keywords
    std::unordered_map<std::string, std::vector<std::string>> intentMap = {
        {"greeting", {"hello", "hi", "hey", "good morning", "good afternoon", "good evening"}},
        {"farewell", {"bye", "goodbye", "see you", "take care"}},
        {"gratitude", {"thank you", "thanks", "appreciate it"}},
        {"inquiry", {"what", "why", "how", "when", "where", "who", "which", "can you", "could you", "would you"}}
    };

    // Iterate through each intent and check for keyword presence
    for (const auto& pair : intentMap) {
        if (hasKeyword(sentence, pair.second)) {
            return pair.first;
        }
    }

    return "unknown";
}

int main() {
    // Test sentences to analyze
    std::vector<std::string> testSentences = {
        "Hello, how are you?",
        "Goodbye, see you tomorrow.",
        "Thank you for your help.",
        "Can you tell me the time?",
        "This is a random sentence."
    };

    // Process and display results for each sentence
    for (const auto& sentence : testSentences) {
        std::string detectedIntent = determineIntent(sentence);
        std::cout << "Sentence: " << sentence << "\nIntent: " << detectedIntent << "\n\n";
    }

    return 0;
}

