#include <iostream>

// Priority Queue implementation using a linked list with descending priority order
class PriorityQueue {
public:
    PriorityQueue();
    ~PriorityQueue();
    void insert(int itemValue, int itemPriority);
    int removeHighest();
    bool empty() const;
    void print() const;
private:
    struct Element {
        int data;
        int priorityLevel;
        Element* link;
    };
    Element* head;
};

PriorityQueue::PriorityQueue() {
    head = nullptr;
}

PriorityQueue::~PriorityQueue() {
    while (!empty()) {
        removeHighest();
    }
}

void PriorityQueue::insert(int itemValue, int itemPriority) {
    Element* newElement = new Element;
    newElement->data = itemValue;
    newElement->priorityLevel = itemPriority;
    newElement->link = nullptr;

    if (empty() || itemPriority > head->priorityLevel) {
        newElement->link = head;
        head = newElement;
    } else {
        Element* current = head;
        while (current->link != nullptr && current->link->priorityLevel >= itemPriority) {
            current = current->link;
        }
        newElement->link = current->link;
        current->link = newElement;
    }
}

int PriorityQueue::removeHighest() {
    if (empty()) {
        throw std::runtime_error("Priority queue is empty, cannot remove element.");
    }

    Element* temp = head;
    int result = head->data;
    head = head->link;
    delete temp;
    return result;
}

bool PriorityQueue::empty() const {
    return head == nullptr;
}

void PriorityQueue::print() const {
    Element* current = head;
    while (current != nullptr) {
        std::cout << current->data << " [priority: " << current->priorityLevel << "] -> ";
        current = current->link;
    }
    std::cout << "null" << std::endl;
}

int main() {
    PriorityQueue pq;

    pq.insert(10, 3);
    pq.insert(5, 1);
    pq.insert(3, 4);
    pq.insert(20, 2);

    pq.print();

    std::cout << "Removed highest priority: " << pq.removeHighest() << std::endl;
    std::cout << "Removed highest priority: " << pq.removeHighest() << std::endl;

    pq.print();

    return 0;
}

#include <iostream>
