// Helper function to reconstruct and print the LCS using the direction table
void displayCommonSubsequence(const std::string& sequence1, const std::string& sequence2, 
                              int len1, int len2, const std::vector<std::vector<int>>& directions) {
    if (len1 == 0 || len2 == 0) return;

    if (directions[len1][len2] == 1) {  // Characters match
        displayCommonSubsequence(sequence1, sequence2, len1 - 1, len2 - 1, directions);
        std::cout << sequence1[len1 - 1];
    } else if (directions[len1][len2] == 2) {  // Move up (from sequence1)
        displayCommonSubsequence(sequence1, sequence2, len1 - 1, len2, directions);
    } else {  // Move left (from sequence2)
        displayCommonSubsequence(sequence1, sequence2, len1, len2 - 1, directions);
    }
}

std::string computeLCS(const std::string& firstStr, const std::string& secondStr) {
    int length1 = firstStr.size();
    int length2 = secondStr.size();

    // DP table for lengths of LCS
    std::vector<std::vector<int>> lcsLengths(length1 + 1, std::vector<int>(length2 + 1, 0));
    // Direction table: 1=diagonal (match), 2=up, 3=left
    std::vector<std::vector<int>> dirTable(length1 + 1, std::vector<int>(length2 + 1, 0));

    // Fill the DP tables
    for (int i = 1; i <= length1; ++i) {
        for (int j = 1; j <= length2; ++j) {
            if (firstStr[i - 1] == secondStr[j - 1]) {
                lcsLengths[i][j] = lcsLengths[i - 1][j - 1] + 1;
                dirTable[i][j] = 1;  // Match case
            } else if (lcsLengths[i - 1][j] >= lcsLengths[i][j - 1]) {
                lcsLengths[i][j] = lcsLengths[i - 1][j];
                dirTable[i][j] = 2;  // Prefer moving up
            } else {
                lcsLengths[i][j] = lcsLengths[i][j - 1];
                dirTable[i][j] = 3;  // Move left
            }
        }
    }

    std::cout << "The longest common subsequence is: ";
    displayCommonSubsequence(firstStr, secondStr, length1, length2, dirTable);
    std::cout << std::endl;

    return firstStr;  // Return first string as placeholder (function primarily prints result)
}

int main() {
    std::string strA = "ABCBDAB";
    std::string strB = "BDCAB";
    computeLCS(strA, strB);
    return 0;
}

