// Function to remove vowels from a string
std::string filterConsonants(const std::string& text) {
    std::string consonantsOnly;
    for (size_t i = 0; i < text.length(); ++i) {
        char currentChar = text[i];
        bool isVowel = false;

        // Check if character is a vowel (case-insensitive)
        switch (currentChar) {
            case 'a': case 'e': case 'i': case 'o': case 'u':
            case 'A': case 'E': case 'I': case 'O': case 'U':
                isVowel = true;
                break;
            default:
                isVowel = false;
        }

        if (!isVowel) {
            consonantsOnly += currentChar;
        }
    }
    return consonantsOnly;
}

