#include <iostream>
#include <vector>
#include <algorithm>
#include <random>
#include <cmath>
#include <limits>

// Define a city as a pair of coordinates
struct City {
    int x, y;
};

// Calculate the Euclidean distance between two cities
double calculate_distance(const City& point1, const City& point2) {
    int dx = point1.x - point2.x;
    int dy = point1.y - point2.y;
    return std::sqrt(static_cast<double>(dx * dx + dy * dy));
}

// Calculate the total distance of a route (circular path)
double compute_total_distance(const std::vector<City>& locations, const std::vector<int>& path) {
    double total = 0.0;
    size_t n = path.size();
    for (size_t i = 0; i < n; ++i) {
        total += calculate_distance(locations[path[i]], locations[path[(i + 1) % n]]);
    }
    return total;
}

// Generate a random permutation of city indices
std::vector<int> create_random_path(size_t count) {
    std::vector<int> path(count);
    for (size_t i = 0; i < count; ++i) {
        path[i] = static_cast<int>(i);
    }

    // Use modern random shuffle (std::shuffle instead of deprecated std::random_shuffle)
    std::random_device rd;
    std::mt19937 gen(rd());
    std::shuffle(path.begin(), path.end(), gen);
    return path;
}

// Partially matched crossover (PMX) implementation
std::vector<int> perform_crossover(const std::vector<int>& parentA, const std::vector<int>& parentB) {
    size_t length = parentA.size();
    std::vector<int> child(length, -1);

    // Select two random cut points
    size_t cut1 = std::rand() % length;
    size_t cut2 = std::rand() % length;
    if (cut1 > cut2) std::swap(cut1, cut2);

    // Copy segment from parentA to child
    for (size_t i = cut1; i <= cut2; ++i) {
        child[i] = parentA[i];
    }

    // Fill remaining positions from parentB
    size_t pos = (cut2 + 1) % length;
    for (size_t i = 0; i < length; ++i) {
        size_t idx = (cut2 + 1 + i) % length;
        if (std::find(child.begin(), child.end(), parentB[idx]) == child.end()) {
            child[pos] = parentB[idx];
            pos = (pos + 1) % length;
        }
    }

    return child;
}

// Apply mutation by swapping two cities with given probability
void apply_mutation(std::vector<int>& path, double rate) {
    for (size_t i = 0; i < path.size(); ++i) {
        if (static_cast<double>(std::rand()) / RAND_MAX < rate) {
            size_t j = std::rand() % path.size();
            std::swap(path[i], path[j]);
        }
    }
}

// Tournament selection: pick k random individuals and return the best one
std::vector<int> tournament_select(const std::vector<std::vector<int>>& group, 
                                   const std::vector<City>& places, int tournament_size = 5) {
    std::vector<int> selected = group[0];
    double min_dist = compute_total_distance(places, selected);

    for (int i = 0; i < tournament_size; ++i) {
        size_t idx = std::rand() % group.size();
        double dist = compute_total_distance(places, group[idx]);
        if (dist < min_dist) {
            min_dist = dist;
            selected = group[idx];
        }
    }
    return selected;
}

// Main genetic algorithm function
std::vector<int> run_genetic_algorithm(const std::vector<City>& locations, 
                                      size_t pop_size, size_t max_generations, 
                                      double mutation_prob) {
    // Initialize population with random paths
    std::vector<std::vector<int>> population(pop_size);
    for (size_t i = 0; i < pop_size; ++i) {
        population[i] = create_random_path(locations.size());
    }

    // Evolve over generations
    for (size_t gen = 0; gen < max_generations; ++gen) {
        std::vector<std::vector<int>> next_gen(pop_size);

        for (size_t i = 0; i < pop_size; ++i) {
            std::vector<int> p1 = tournament_select(population, locations);
            std::vector<int> p2 = tournament_select(population, locations);
            std::vector<int> offspring = perform_crossover(p1, p2);
            apply_mutation(offspring, mutation_prob);
            next_gen[i] = offspring;
        }

        population = next_gen;
    }

    // Find best solution in final population
    std::vector<int> best_path = population[0];
    double best_distance = compute_total_distance(locations, best_path);

    for (const auto& path : population) {
        double current_distance = compute_total_distance(locations, path);
        if (current_distance < best_distance) {
            best_distance = current_distance;
            best_path = path;
        }
    }

    return best_path;
}

int main() {
    // Define test cities
    std::vector<City> city_locations = {
        {0, 0}, {1, 2}, {3, 1}, {5, 2}, {2, 4}, 
        {4, 5}, {6, 3}, {7, 1}, {8, 2}, {9, 4}
    };

    // Algorithm parameters
    size_t population_size = 100;
    size_t num_generations = 1000;
    double mutation_probability = 0.01;

    // Run genetic algorithm
    std::vector<int> optimal_route = run_genetic_algorithm(city_locations, 
                                                          population_size, 
                                                          num_generations, 
                                                          mutation_probability);

    // Output results
    std::cout << "Optimal Route: ";
    for (int city_index : optimal_route) {
        std::cout << city_index << " ";
    }
    std::cout << std::endl;

    double shortest_distance = compute_total_distance(city_locations, optimal_route);
    std::cout << "Shortest Path Length: " << shortest_distance << std::endl;

    return 0;
}

