// Container to associate native pointers with unique identifiers
std::map<long, RFEthernetDetector*> objectRegistry;

// Produces a fresh identifier for each new instance
long createIdentifier() {
    static long currentId = 1000;
    return currentId++;
}

// Initializes the detector and registers it in the registry
JNIEXPORT jlong JNICALL Java_RFEthernetDetector_init(JNIEnv *env, jobject thisObj, jint portNumber) {
    RFEthernetDetector *detectorInstance = new RFEthernetDetector(static_cast<WORD>(portNumber));
    long identifier = createIdentifier();
    objectRegistry[identifier] = detectorInstance;
    return identifier;
}

// Invokes an operation on the associated native object
JNIEXPORT void JNICALL Java_RFEthernetDetector_doSomething(JNIEnv *env, jobject thisObj) {
    jclass objClass = env->GetObjectClass(thisObj);
    jfieldID fieldId = env->GetFieldID(objClass, "nativeHandle", "J");
    jlong storedId = env->GetLongField(thisObj, fieldId);

    RFEthernetDetector *detector = objectRegistry[storedId];
    if (detector != nullptr) {
        detector->doSomething();
    }
}

// Releases resources tied to the given identifier
JNIEXPORT void JNICALL Java_RFEthernetDetector_dispose(JNIEnv *env, jobject thisObj, jlong handle) {
    auto it = objectRegistry.find(handle);
    if (it != objectRegistry.end()) {
        delete it->second;
        objectRegistry.erase(it);
    }
}

