class PythonOutputStreamBuffer : public std::streambuf {
public:
    PythonOutputStreamBuffer(PyFileObject* pyFile) : file(pyFile) {
        setp(internalBuffer, internalBuffer + sizeof(internalBuffer) - 1);
    }

protected:
    int overflow(int character) override {
        if (character != EOF) {
            char ch = static_cast<char>(character);
            PyFile_WriteString(&ch, 1, (PyObject*)file);
        }
        return 0;
    }

    int sync() override {
        size_t length = pptr() - pbase();
        if (length > 0) {
            PyFile_WriteString(pbase(), static_cast<int>(length), (PyObject*)file);
            pbump(-static_cast<int>(length));
        }
        return 0;
    }

private:
    PyFileObject* file;
    char internalBuffer[1024];
};

class PythonOutputStream : public std::ostream {
public:
    PythonOutputStream(PyFileObject* pyFile) 
        : std::ostream(new PythonOutputStreamBuffer(pyFile)) {}

    ~PythonOutputStream() {
        delete rdbuf();
    }
};

