struct TVersionizedPointer {
  std::intptr_t Ver;
  void* Ptr;
};

struct TVersionizedPointerStorage {
  char data[2 * sizeof(TVersionizedPointer)];
};

TVersionizedPointer* GetAlignedVersionizedPointer(TVersionizedPointerStorage& PointerStorage) {
  const size_t alignment = alignof(TVersionizedPointer);
  const size_t storage_size = sizeof(TVersionizedPointer);

  // Calculate address with offset to ensure alignment
  std::uintptr_t base_addr = reinterpret_cast<std::uintptr_t>(&PointerStorage);
  std::uintptr_t aligned_offset = (base_addr + storage_size - 1) & ~(storage_size - 1);

  return reinterpret_cast<TVersionizedPointer*>(aligned_offset);
}

