// Compute the difference between the maximum and minimum values in the vector
int computeSpread(const std::vector<int>& data) {
    if (data.empty()) {
        return 0;  // Handle empty input by returning 0
    }

    int currentMin = data[0];
    int currentMax = data[0];

    for (size_t i = 1; i < data.size(); ++i) {
        if (data[i] < currentMin) {
            currentMin = data[i];
        }
        if (data[i] > currentMax) {
            currentMax = data[i];
        }
    }

    return currentMax - currentMin;
}

