// Represents a time interval in seconds
class Duration {
public:
    Duration(int days, int hours, int minutes, int seconds)
        : total_seconds_(days * 24 * 3600 + hours * 3600 + minutes * 60 + seconds) {}

    int GetTotalSeconds() const {
        return total_seconds_;
    }

private:
    int total_seconds_;
};

// Represents a specific point in time
class Timestamp {
public:
    Timestamp(int year, int month, int day, int hour, int minute, int second)
        : time_point_(std::chrono::system_clock::from_time_t(std::mktime(&tm_struct_))) {
        tm_struct_.tm_year = year - 1900;
        tm_struct_.tm_mon = month - 1;
        tm_struct_.tm_mday = day;
        tm_struct_.tm_hour = hour;
        tm_struct_.tm_min = minute;
        tm_struct_.tm_sec = second;
    }

    std::string Format() const {
        std::time_t raw_time = std::chrono::system_clock::to_time_t(time_point_);
        std::tm* local_time = std::localtime(&raw_time);
        char buffer[80];
        std::strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", local_time);
        return std::string(buffer);
    }

    Duration operator-(const Timestamp& other) const {
        auto diff_duration = time_point_ - other.time_point_;
        auto seconds_count = std::chrono::duration_cast<std::chrono::seconds>(diff_duration).count();
        return Duration(0, 0, 0, static_cast<int>(seconds_count));
    }

private:
    std::chrono::system_clock::time_point time_point_;
    std::tm tm_struct_;
};

int main() {
    Timestamp current(2023, 10, 1, 12, 0, 0);
    Timestamp future(2023, 10, 2, 14, 30, 0);

    std::cout << "Current: " << current.Format() << std::endl;
    std::cout << "Future: " << future.Format() << std::endl;

    Duration elapsed = future - current;
    std::cout << "Elapsed seconds: " << elapsed.GetTotalSeconds() << std::endl;

    return 0;
}

