    int* smallArray3 = new int[1 << 16];   // 2^16 = 65536 elements

    // Initialize small arrays to zero
    for (int idx = 0; idx < (1 << 14); ++idx) smallArray1[idx] = 0;
    for (int idx = 0; idx < (1 << 15); ++idx) smallArray2[idx] = 0;
    for (int idx = 0; idx < (1 << 16); ++idx) smallArray3[idx] = 0;

