    int* largeArray2 = new int[1 << 25];   // 2^25 = 33,554,432 elements
    int* largeArray3 = new int[1 << 26];   // 2^26 = 67,108,864 elements

    // Initialize large arrays to zero
    for (int idx = 0; idx < (1 << 24); ++idx) largeArray1[idx] = 0;
    for (int idx = 0; idx < (1 << 25); ++idx) largeArray2[idx] = 0;
    for (int idx = 0; idx < (1 << 26); ++idx) largeArray3[idx] = 0;

