// Helper: Read entire binary file into a string
static Status LoadBinaryFile(Env* pEnv, const string& sPath, string* pData) {
    uint64 nSize = 0;
    TF_RETURN_IF_ERROR(pEnv->GetFileSize(sPath, &nSize));

    pData->resize(static_cast<size_t>(nSize));
    std::unique_ptr<RandomAccessFile> pFile;
    TF_RETURN_IF_ERROR(pEnv->NewRandomAccessFile(sPath, &pFile));

    StringPiece piece;
    size_t readBytes = static_cast<size_t>(nSize);
    TF_RETURN_IF_ERROR(pFile->Read(0, nSize, &piece, &(*pData)[0]));

    return Status::OK();
}

// Preprocess PNG image: decode → cast → expand dims → resize → normalize
Status PrepareImageTensor(const string& sImagePath,
                          int nTargetWidth, int nTargetHeight,
                          float fMean, float fScale,
                          Tensor* pOutputTensor) {
    string sImageData;
    TF_RETURN_IF_ERROR(LoadBinaryFile(Env::Default(), sImagePath, &sImageData));

    // Build subgraph dynamically
    Scope root = Scope::NewRootScope();
    auto inputPlaceholder = ops::Placeholder(root.WithOpName("img_input"), DT_STRING);

    // Decode PNG (3 channels)
    auto decodedImg = ops::DecodePng(root.WithOpName("decode_png"),
                                     inputPlaceholder,
                                     ops::DecodePng::Channels(3));

    // Cast to float
    auto floatImg = ops::Cast(root.WithOpName("cast_to_float"), decodedImg, DT_FLOAT);

    // Add batch dimension
    auto batchedImg = ops::ExpandDims(root, floatImg, 0);

    // Resize to target dimensions
    auto resizedImg = ops::ResizeBilinear(root,
                                          batchedImg,
                                          ops::Const(root.WithOpName("size"), {nTargetHeight, nTargetWidth}));

    // Normalize: (x - mean) / scale
    auto normalizedImg = ops::Div(
        root.WithOpName("normalize"),
        ops::Sub(root, resizedImg, ops::Const(root, fMean)),
        ops::Const(root, fScale));

    // Build graph
    GraphDef graph;
    TF_RETURN_IF_ERROR(root.ToGraphDef(&graph));

    // Run inference on this small graph
    std::unique_ptr<Session> pSession;
    TF_RETURN_IF_ERROR(NewSession(SessionOptions(), &pSession));
    TF_RETURN_IF_ERROR(pSession->Create(graph));

    std::vector<std::pair<string, Tensor>> feedDict = {{"img_input", Tensor(DT_STRING, TensorShape(), {{sImageData}})}};
    std::vector<Tensor> outputs;
    TF_RETURN_IF_ERROR(pSession->Run(feedDict, {"normalize"}, {}, &outputs));

    if (!outputs.empty()) {
        *pOutputTensor = outputs[0];
    } else {
        return errors::Internal("No output produced from image preprocessing");
    }

    return Status::OK();
}

int main(int argc, char* argv[]) {
    tensorflow::port::InitMain(argv[0], &argc, &argv);

    // Load model graph
    GraphDef modelGraph;
    Status status = ReadBinaryProto(Env::Default(), "models/graph.pb", &modelGraph);
    if (!status.ok()) {
        std::cerr << "Failed to load graph: " << status.ToString() << std::endl;
        return -1;
    }
    std::cout << "Model graph loaded successfully.\n";

    // Prepare input tensor
    Tensor inputTensor;
    status = PrepareImageTensor("temp.png", 224, 224, 127.5f, 255.0f, &inputTensor);
    if (!status.ok()) {
        std::cerr << "Image preprocessing failed: " << status.ToString() << std::endl;
        return -1;
    }
    std::cout << "Input tensor prepared.\n";

    // Create session and run inference
    std::unique_ptr<Session> pInferSession;
    status = NewSession(SessionOptions(), &pInferSession);
    if (!status.ok()) {
        std::cerr << "Session creation failed: " << status.ToString() << std::endl;
        return -1;
    }

    status = pInferSession->Create(modelGraph);
    if (!status.ok()) {
        std::cerr << "Graph instantiation failed: " << status.ToString() << std::endl;
        return -1;
    }

    std::vector<Tensor> resultTensors;
    std::vector<std::pair<string, Tensor>> inputs = {{"input_input", inputTensor}};
    status = pInferSession->Run(inputs, {"activation_output/Relu"}, {}, &resultTensors);
    if (!status.ok()) {
        std::cerr << "Inference failed: " << status.ToString() << std::endl;
        return -1;
    }

    // Output analysis
    for (const auto& outTensor : resultTensors) {
        std::cout << "Output shape: " << outTensor.shape().DebugString() << "\n";
