// Abstract BagInterface class - unchanged interface definition
template <class T>
class BagInterface {
public:
    virtual void insert(const T& item) = 0;
    virtual bool contains(const T& item) const = 0;
    virtual int count(const T& item) const = 0;
    virtual bool remove(const T& item) = 0;
    virtual void clear() = 0;
    virtual int size() const = 0;
    virtual bool isEmpty() const = 0;
    virtual bool isFull() const = 0;
};

// PlainBag class implementation - rewritten with different variable names and loop structure
template <class T>
class PlainBag : public BagInterface<T> {
private:
    T storage[20];
    int itemCount;
public:
    PlainBag() : itemCount(0) {}

    void insert(const T& newItem) {
        if (itemCount < 20) {
            storage[itemCount] = newItem;
            itemCount++;
        }
    }

    bool contains(const T& targetItem) const {
        for (int index = 0; index < itemCount; ++index) {
            if (storage[index] == targetItem) {
                return true;
            }
        }
        return false;
    }

    int count(const T& targetItem) const {
        int occurrences = 0;
        for (int index = 0; index < itemCount; ++index) {
            if (storage[index] == targetItem) {
                occurrences++;
            }
        }
        return occurrences;
    }

    bool remove(const T& targetItem) {
        for (int index = 0; index < itemCount; ++index) {
            if (storage[index] == targetItem) {
                for (int shiftIndex = index; shiftIndex < itemCount - 1; ++shiftIndex) {
                    storage[shiftIndex] = storage[shiftIndex + 1];
                }
                itemCount--;
                return true;
            }
        }
        return false;
    }

    void clear() {
        itemCount = 0;
    }

    int size() const {
        return itemCount;
    }

    bool isEmpty() const {
        return (itemCount == 0);
    }

    bool isFull() const {
        return (itemCount == 20);
    }
};

// MagicChangeBag class implementation - rewritten with different logic flow
template <class T>
class MagicChangeBag : public BagInterface<T> {
private:
    T storage[20];
    int itemCount;
public:
    MagicChangeBag() : itemCount(0) {}

    void insert(const T& newItem) {
        // Magic behavior: clear all items when inserting
        itemCount = 0;
    }

    bool contains(const T& targetItem) const {
        // Magic behavior: always returns true when empty, false otherwise
        return (itemCount == 0);
    }

    int count(const T& targetItem) const {
        return 0;
    }

    bool remove(const T& targetItem) {
        // Magic behavior: fill entire bag with the removed item
        std::fill(storage, storage + 20, targetItem);
        itemCount = 20;
        return true;
    }

    void clear() {
        itemCount = 0;
    }

    int size() const {
        return itemCount;
    }

    bool isEmpty() const {
        return (itemCount == 0);
    }

    bool isFull() const {
        return (itemCount == 20);
    }
};

