// Perform binary search on sorted vector for target value
int binarySearch(const std::vector<int>& data, int value) {
    int start = 0;
    int end = static_cast<int>(data.size()) - 1;

    while (start <= end) {
        int middle = start + ((end - start) >> 1);

        if (data[middle] == value) {
            return middle;
        } else if (data[middle] > value) {
            end = middle - 1;
        } else {
            start = middle + 1;
        }
    }

    return -1; // Value not found in data
}

