template <typename T>
class ExclusiveHolder {
private:
    std::unique_ptr<T> owner;

public:
    explicit ExclusiveHolder(T* raw) : owner(raw) {}

    // Transfer ownership only
    ExclusiveHolder(ExclusiveHolder&& other) noexcept : owner(std::move(other.owner)) {}
    ExclusiveHolder& operator=(ExclusiveHolder&& other) noexcept {
        owner = std::move(other.owner);
        return *this;
    }

    // Prevent copying to maintain exclusivity
    ExclusiveHolder(const ExclusiveHolder&) = delete;
    ExclusiveHolder& operator=(const ExclusiveHolder&) = delete;

    // Interface for accessing the managed object
    T* access() const { return owner.get(); }
    T& dereference() const { return *owner; }
    T* arrow() const { return owner.get(); }

    // Create a non-owning shared reference
    std::shared_ptr<T> share_access() {
        assert(owner);
        return std::shared_ptr<T>(owner.get(), [](T*) {}); // Custom no-op deleter
    }
};

