int OnCalculate(const int rates_total, const int prev_calculated, const datetime &time[], const double &open[], const double &high[], const double &low[], const double &close[], const long &tick_volume[], const long &volume[], const int &spread[])
  {
   if(rates_total < Lookback)
      return(0);

   ArraySetAsSeries(SupportBuffer,true);
   ArraySetAsSeries(ResistanceBuffer,true);

   int index = Lookback;
   while(index < rates_total && !IsStopped())
     {
      // Find minimum low in the lookback period for support
      double minLow = low[index];
      for(int k = 1; k < Lookback; k++)
        {
         if(low[index - k] < minLow)
            minLow = low[index - k];
        }
      SupportBuffer[index] = minLow;

      // Find maximum high in the lookback period for resistance
      double maxHigh = high[index];
      for(int k = 1; k < Lookback; k++)
        {
         if(high[index - k] > maxHigh)
            maxHigh = high[index - k];
        }
      ResistanceBuffer[index] = maxHigh;

      index++;
     }

   return rates_total;
  }

#include <arm_neon.h>

void my_function(uint32_t *src, uint32_t *dst) {
    // Load 4 32-bit values as 16 bytes
    uint8x16_t bytes = vld1q_u8(reinterpret_cast<uint8_t*>(src));

    // Extract individual bytes and rearrange them in reversed order per 32-bit word
    uint8x16_t swapped;
    for (int i = 0; i < 4; ++i) {
        uint8_t b0 = vgetq_lane_u8(bytes, i * 4 + 0);
        uint8_t b1 = vgetq_lane_u8(bytes, i * 4 + 1);
        uint8_t b2 = vgetq_lane_u8(bytes, i * 4 + 2);
        uint8_t b3 = vgetq_lane_u8(bytes, i * 4 + 3);

        vsetq_lane_u8(b3, swapped, i * 4 + 0);
        vsetq_lane_u8(b2, swapped, i * 4 + 1);
        vsetq_lane_u8(b1, swapped, i * 4 + 2);
        vsetq_lane_u8(b0, swapped, i * 4 + 3);
    }

    // Store the result back
    vst1q_u8(reinterpret_cast<uint8_t*>(dst), swapped);
}

