// Deterministic Finite Automaton implementation
struct DFA {
    int start_state;
    set<int> final_states;
    unordered_map<int, unordered_map<char, int>> delta;

    // Check if the input string is accepted by the automaton
    bool recognize(const string& word) {
        int state = start_state;
        for (char c : word) {
            auto it = delta[state].find(c);
            if (it == delta[state].end()) {
                return false; // Transition undefined for current state and symbol
            }
            state = it->second;
        }
        return final_states.count(state) > 0;
    }
};

