using json = nlohmann::json;

struct WeatherReading {
    std::string place;
    double tempC;
    double elevation;
    int timeOfDay;
    std::string period;
};

struct ConvertedResult {
    std::string place;
    double tempF;
};

double applyElevationCorrection(double celsius, double elevation) {
    return celsius - 0.0065 * elevation;
}

double applyTimeCorrection(double celsius, int hour) {
    if (hour >= 6 && hour < 12) {
        return celsius - 1;
    } else if (hour >= 18 && hour < 24) {
        return celsius - 2;
    }
    return celsius;
}

double applySeasonalCorrection(double celsius, const std::string& season) {
    if (season == "summer") {
        return celsius + 2;
    } else if (season == "winter") {
        return celsius - 2;
    }
    return celsius;
}

double convertTo Fahrenheit(double celsius) {
    return celsius * 9.0 / 5.0 + 32.0;
}

std::vector<ConvertedResult> processTemperatureData(const std::vector<WeatherReading>& readings) {
    std::vector<ConvertedResult> processed;
    for (const auto& reading : readings) {
        double currentTemp = reading.tempC;
        double height = reading.elevation;
        int moment = reading.timeOfDay;
        std::string term = reading.period;

        double correctedByHeight = applyElevationCorrection(currentTemp, height);
        double correctedByTime = applyTimeCorrection(correctedByHeight, moment);
        double finalTempC = applySeasonalCorrection(correctedByTime, term);

        double tempF = convertTo Fahrenheit(finalTempC);
        processed.push_back({reading.place, tempF});
    }
    return processed;
}

void writeJsonOutput(const std::vector<ConvertedResult>& output) {
    json j = output;
    std::ofstream outFile("results.json");
    outFile << std::setw(4) << j << std::endl;
}

void writeCsvOutput(const std::vector<ConvertedResult>& output) {
    std::ofstream outFile("results.csv");
    outFile << "location,fahrenheit\n";
    for (const auto& item : output) {
        outFile << item.place << "," << item.tempF << "\n";
    }
}

int main() {
    std::vector<WeatherReading> input = {
        {"New York", 20, 10, 10, "summer"},
        {"Los Angeles", 25, 50, 18, "winter"}
    };

    std::vector<ConvertedResult> processedData = processTemperatureData(input);
    writeJsonOutput(processedData);
    writeCsvOutput(processedData);

    return 0;
}

