// Function to find two indices whose values sum up to the target
std::vector<int> findPairIndices(std::vector<int>& values, int goal) {
    std::unordered_map<int, int> valueToPosition;

    for (int index = 0; index < values.size(); ++index) {
        int needed = goal - values[index];

        // Check if the needed value has already been seen
        if (valueToPosition.count(needed)) {
            return {valueToPosition[needed], index};
        }

        // Store current value and its index
        valueToPosition[values[index]] = index;
    }

    // Return empty vector if no pair found
    return {};
}

int main() {
    std::vector<int> numbers = {2, 7, 11, 15};
    int desiredSum = 9;

    std::vector<int> solution = findPairIndices(numbers, desiredSum);

    if (solution.size() == 2) {
        std::cout << "[" << solution[0] << ", " << solution[1] << "]" << std::endl;
    } else {
        std::cout << "No valid result found." << std::endl;
    }

    return 0;
}

