// Determine if a number is prime using optimized logic
bool checkPrime(int value) {
    if (value <= 1) return false;
    if (value <= 3) return true;
    if (value % 2 == 0 || value % 3 == 0) return false;

    int limit = static_cast<int>(std::sqrt(value));
    for (int j = 5; j <= limit; j += 6) {
        if (value % j == 0 || value % (j + 2) == 0) return false;
    }
    return true;
}

// Compute the sum of all digits in a positive integer
int digitSum(int number) {
    int total = 0;
    while (number > 0) {
        total += number % 10;
        number /= 10;
    }
    return total;
}

// Find the maximum prime in the collection and return its digit sum
int maxPrimeDigitSum(const std::vector<int>& data) {
    int maxPrime = -1;
    for (size_t idx = 0; idx < data.size(); ++idx) {
        int current = data[idx];
        if (checkPrime(current) && current > maxPrime) {
            maxPrime = current;
        }
    }
    return (maxPrime != -1) ? digitSum(maxPrime) : 0;
}

