// Employee class for managing employee data
class StaffMember {
public:
    // Constructor with default values
    StaffMember(int identifier = 0, const std::string& fullName = "", 
                const std::string& role = "", double compensation = 0.0)
        : identifier(identifier), fullName(fullName), role(role), compensation(compensation) {}

    // Destructor
    ~StaffMember() {}

    // Accessor methods
    int getIdentifier() const { return identifier; }
    std::string getFullName() const { return fullName; }
    std::string getRole() const { return role; }
    double getCompensation() const { return compensation; }

    // Mutator methods
    void setIdentifier(int id) { identifier = id; }
    void setFullName(const std::string& name) { fullName = name; }
    void setRole(const std::string& position) { role = position; }
    void setCompensation(double salary) { compensation = salary; }

    // Static method to retrieve all staff members from the database
    static std::vector<std::shared_ptr<StaffMember>> fetchStaffFromDatabase(const std::string& databasePath) {
        sqlite3* connection;
        int result = sqlite3_open(databasePath.c_str(), &connection);
        if (result) {
            std::cerr << "Unable to open database: " << sqlite3_errmsg(connection) << std::endl;
            return {};
        }

        std::vector<std::shared_ptr<StaffMember>> staffList;
        std::string query = "SELECT id, name, position, salary FROM employees;";

        sqlite3_stmt* statement;
        result = sqlite3_prepare_v2(connection, query.c_str(), -1, &statement, nullptr);
        if (result != SQLITE_OK) {
            std::cerr << "Statement preparation failed: " << sqlite3_errmsg(connection) << std::endl;
            sqlite3_close(connection);
            return {};
        }

        while (sqlite3_step(statement) == SQLITE_ROW) {
            int empId = sqlite3_column_int(statement, 0);
            std::string empName = reinterpret_cast<const char*>(sqlite3_column_text(statement, 1));
            std::string empRole = reinterpret_cast<const char*>(sqlite3_column_text(statement, 2));
            double empSalary = sqlite3_column_double(statement, 3);

            staffList.push_back(std::make_shared<StaffMember>(empId, empName, empRole, empSalary));
        }

        sqlite3_finalize(statement);
        sqlite3_close(connection);

        return staffList;
    }

private:
    int identifier;
    std::string fullName;
    std::string role;
    double compensation;
};

int main() {
    // Demonstration of usage
    std::vector<std::shared_ptr<StaffMember>> staff = StaffMember::fetchStaffFromDatabase("example.db");

    for (const auto& member : staff) {
        std::cout << "ID: " << member->getIdentifier() 
                  << ", Name: " << member->getFullName()
                  << ", Role: " << member->getRole() 
                  << ", Compensation: " << member->getCompensation() << std::endl;
    }

    return 0;
}

