// Function to capture and return keyboard scan code
int getkeys() {
    union REGS input_regs, output_regs;

    // Wait indefinitely until a key is pressed
    do {
        // Continue looping while no key is detected
    } while (!kbhit());

    // Prepare interrupt call: function 0 (read keystroke)
    input_regs.h.ah = 0;

    // Execute DOS interrupt 22h
    int86(22, &input_regs, &output_regs);

    // Return the scan code stored in AH register
    return output_regs.h.ah;
}

