FARPROC WINAPI HookedGetProcAddress(HMODULE hModule, LPCSTR procName)
{
    FARPROC result = orig_GetProcAddress(hModule, procName);

    if (result != nullptr)
    {
        char debugMsg[512] = {0};
        strcpy_s(debugMsg, "Resolved function: ");
        strcat_s(debugMsg, procName);
        strcat_s(debugMsg, "\n");
        OutputDebugStringA(debugMsg);
    }

    return result;
}

// DLL entry point
BOOL WINAPI DllMain(HINSTANCE hInst, DWORD reason, LPVOID reserved)
{
    switch (reason)
    {
    case DLL_PROCESS_ATTACH:
        // Ensure original functions are initialized
        InitOriginalFunctions();

        // Apply detours
        DetourTransactionBegin();
        DetourUpdateThread(GetCurrentThread());
        DetourAttach(&(PVOID&)orig_LoadLibrary, HookedLoadLibraryA);
        DetourAttach(&(PVOID&)orig_GetProcAddress, HookedGetProcAddress);
        DetourTransactionCommit();
        break;

    case DLL_PROCESS_DETACH:
        // Remove detours
        DetourTransactionBegin();
        DetourUpdateThread(GetCurrentThread());
        DetourDetach(&(PVOID&)orig_LoadLibrary, HookedLoadLibraryA);
        DetourDetach(&(PVOID&)orig_GetProcAddress, HookedGetProcAddress);
        DetourTransactionCommit();
        break;
    }

    return TRUE;
}

