// Find the maximum element in a vector of integers
int findMaximum(const std::vector<int>& data) {
    if (data.empty()) {  // Handle empty vector case
        return INT_MIN;  // Return the smallest possible integer value
    }
    int current_max = data[0];  // Start with the first element as the maximum
    for (size_t index = 1; index < data.size(); ++index) {
        if (data[index] > current_max) {
            current_max = data[index];
        }
    }
    return current_max;
}

