namespace py = pybind11;

class Matrix3D {
public:
    std::vector<std::vector<std::vector<double>>> elements;
    int dim_x, dim_y, dim_z;

    // Constructor
    Matrix3D(int x, int y, int z) : dim_x(x), dim_y(y), dim_z(z) {
        elements.resize(dim_x, std::vector<std::vector<double>>(dim_y, std::vector<double>(dim_z, 0.0)));
    }

    // Overloaded operator() for element access (with bounds checking comment)
    double& at(int i, int j, int k) {
        return elements[i][j][k];
    }

    // Function to convert Matrix3D to a NumPy array
    py::array_t<double> to_numpy_array() const {
        py::array_t<double> np_array({dim_x, dim_y, dim_z});
        auto buffer = np_array.mutable_unchecked<3>();
        for (int i = 0; i < dim_x; ++i) {
            for (int j = 0; j < dim_y; ++j) {
                for (int k = 0; k < dim_z; ++k) {
                    buffer(i, j, k) = elements[i][j][k];
                }
            }
        }
        return np_array;
    }

    // Function to convert a NumPy array to Matrix3D
    static Matrix3D from_numpy_array(const py::array_t<double>& np_array) {
        auto buffer = np_array.unchecked<3>();
        Matrix3D result(buffer.shape(0), buffer.shape(1), buffer.shape(2));
        for (int i = 0; i < buffer.shape(0); ++i) {
            for (int j = 0; j < buffer.shape(1); ++j) {
                for (int k = 0; k < buffer.shape(2); ++k) {
                    result.elements[i][j][k] = buffer(i, j, k);
                }
            }
        }
        return result;
    }
};

