// Helper function to determine if a number is prime
bool checkPrime(int value) {
    if (value <= 1)
        return false;

    if (value == 2)
        return true;

    if (value % 2 == 0)
        return false;

    int limit = static_cast<int>(std::sqrt(value));
    for (int j = 3; j <= limit; j += 2) {
        if (value % j == 0)
            return false;
    }

    return true;
}

// Function to count the digits in a positive integer
int countDigits(int n) {
    if (n == 0)
        return 1;

    int cnt = 0;
    while (n > 0) {
        cnt++;
        n /= 10;
    }
    return cnt;
}

// Find the longest prime (by digit count) in the list
int locateLongestPrime(const std::vector<int>& numbers) {
    int bestLength = -1;
    int candidate = -1;

    for (size_t idx = 0; idx < numbers.size(); ++idx) {
        int current = numbers[idx];

        if (checkPrime(current)) {
            int digitCount = countDigits(current);

            if (digitCount > bestLength) {
                bestLength = digitCount;
                candidate = current;
            }
        }
    }

    return candidate;
}

int main() {
    std::vector<int> data = {1, 3, 131, 323, 5107, 34, 8278, 109, 163, 2323, 321, 3039, 31};
    int answer = locateLongestPrime(data);

    if (answer != -1) {
        std::cout << "The prime number with the maximum number of digits is: " << answer << std::endl;
    } else {
        std::cout << "No prime numbers found in the list." << std::endl;
    }

    return 0;
}

