#include <iostream>
#include <complex>
#include <cmath>
#include <vector>

// Solves cubic equation ax^3 + bx^2 + cx + d = 0 using Cardano's formula
std::vector<std::complex<double>> findCubicRoots(double a, double b, double c, double d) {
    if (a == 0.0) {
        throw std::invalid_argument("Leading coefficient 'a' cannot be zero in a cubic equation.");
    }

    // Transform to monic cubic: x^3 + px + q = 0 after substitution x = t - b/(3a)
    double norm_b = b / a;
    double norm_c = c / a;
    double norm_d = d / a;

    double p_val = norm_c - (norm_b * norm_b) / 3.0;
    double q_val = norm_d + (2.0 * norm_b * norm_b * norm_b) / 27.0 - (norm_b * norm_c) / 3.0;

    // Discriminant for depressed cubic
    double delta = (q_val * q_val) / 4.0 + (p_val * p_val * p_val) / 27.0;

    std::vector<std::complex<double>> solution_set;

    if (delta > 0) {
        // One real root and two complex conjugate roots
        double sqrt_delta = std::sqrt(delta);
        double u_val = std::cbrt(-q_val / 2.0 + sqrt_delta);
        double v_val = std::cbrt(-q_val / 2.0 - sqrt_delta);

        double real_solution = u_val + v_val - norm_b / 3.0;
        solution_set.push_back(std::complex<double>(real_solution, 0.0));

        std::complex<double> conj1(-0.5 * (u_val + v_val) - norm_b / 3.0, 
                                   std::sqrt(3.0) * 0.5 * (u_val - v_val));
        std::complex<double> conj2(-0.5 * (u_val + v_val) - norm_b / 3.0, 
                                   -std::sqrt(3.0) * 0.5 * (u_val - v_val));
        solution_set.push_back(conj1);
        solution_set.push_back(conj2);
    } else if (delta == 0) {
        // All roots real, at least two equal
        double u_val = std::cbrt(-q_val / 2.0);
        double sol1 = 2.0 * u_val - norm_b / 3.0;
        double sol2 = -u_val - norm_b / 3.0;

        solution_set.push_back(sol1);
        solution_set.push_back(sol2);
        solution_set.push_back(sol2);
    } else {
        // Three distinct real roots (casus irreducibilis)
        double r_val = std::sqrt(-p_val / 3.0);
        double angle = std::acos(-q_val / (2.0 * r_val * r_val * r_val));
        double amplitude = 2.0 * r_val;

        double root_a = amplitude * std::cos(angle / 3.0) - norm_b / 3.0;
        double root_b = amplitude * std::cos((angle + 2.0 * M_PI) / 3.0) - norm_b / 3.0;
        double root_c = amplitude * std::cos((angle + 4.0 * M_PI) / 3.0) - norm_b / 3.0;

        solution_set.push_back(root_a);
        solution_set.push_back(root_b);
        solution_set.push_back(root_c);
    }

    return solution_set;
}

int main() {
    // Coefficients for equation x^3 - 6x^2 + 11x - 6 = 0 with roots 1, 2, 3
    double coeff_a = 1.0;
    double coeff_b = -6.0;
    double coeff_c = 11.0;
    double coeff_d = -6.0;

    std::vector<std::complex<double>> computed_roots = findCubicRoots(coeff_a, coeff_b, coeff_c, coeff_d);

    std::cout << "Computed roots of the cubic polynomial:" << std::endl;
    for (const auto& root : computed_roots) {
        std::cout << root << std::endl;
    }

    return 0;
}

