template<std::size_t BitCount>
struct BigInt;

// Helper for performing addition across multiple words
template <std::size_t BitCount, std::size_t WordIdx, bool IsFinal = (WordIdx == BigInt<BitCount>::word_count)>
struct AddHelper;

// Specialization for when we've processed all words
template <std::size_t BitCount, std::size_t WordIdx>
struct AddHelper<BitCount, WordIdx, true> {
    static void perform(BigInt<BitCount>& lhs, const BigInt<BitCount>& rhs) {
        uint64_t carry = 0;
        for (std::size_t idx = 0; idx < WordIdx; ++idx) {
            uint64_t temp = lhs.data_[idx] + rhs.data_[idx] + carry;
            lhs.data_[idx] = temp;
            carry = (temp < lhs.data_[idx]) ? 1 : 0;
        }
    }
};

// General case for partial word processing
template <std::size_t BitCount, std::size_t WordIdx>
struct AddHelper<BitCount, WordIdx, false> {
    static void perform(BigInt<BitCount>& lhs, const BigInt<BitCount>& rhs) {
        uint64_t carry = 0;
        for (std::size_t idx = 0; idx < WordIdx; ++idx) {
            uint64_t temp = lhs.data_[idx] + rhs.data_[idx] + carry;
            lhs.data_[idx] = temp;
            carry = (temp < lhs.data_[idx]) ? 1 : 0;
        }
    }
};

// Main big integer class template
template<std::size_t BitCount>
struct BigInt {
    using limb_type = uint64_t;
    static constexpr std::size_t bit_width = BitCount;
    static constexpr std::size_t word_count = (BitCount + 63) / 64;
    using storage = std::array<uint64_t, word_count>;

    explicit BigInt(limb_type initial_value = 0) {
        // Verify two's complement behavior
        assert(-1L >> 1 == -1L);

        // Initialize all limbs to zero
        data_.fill(0);
        data_[0] = initial_value;
    }

    // Access individual words
    limb_type& operator[](std::size_t index) { return data_[index]; }
    const limb_type& operator[](std::size_t index) const { return data_[index]; }

    // Addition assignment operator
    BigInt& operator+=(const BigInt& other) {
        AddHelper<bit_width, word_count>::perform(*this, other);
        return *this;
    }

    // Bitwise NOT operator
    BigInt& operator~() {
        std::transform(data_.begin(), data_.end(), data_.begin(),
                      [](limb_type x) { return ~x; });
        return *this;
    }

    // Print raw representation in hex
    void print_raw(std::ostream& stream) const {
        stream << "(";
        for (std::size_t i = word_count - 1; i > 0; --i) {
            stream << "0x" << std::hex << data_[i] << " ";
        }
        stream << "0x" << data_[0] << ")";
    }

private:
    storage data_;
};

// Stream output operator
template <std::size_t BitCount>
std::ostream& operator<<(std::ostream& stream, const BigInt<BitCount>& value) {
    if (stream.flags() & std::ios_base::hex) {
        value.print_raw(stream);
    } else {
        // Placeholder for decimal printing
        stream << "[big integer]";
    }
    return stream;
}

int main(int argc, const char* argv[]) {
    BigInt<256> num_a;      // initialized to zero
    BigInt<256> num_b(1);   // initialized to one

    // Apply bitwise NOT to num_a (should become all ones)
    ~num_a;

    std::cout << " num_a: " << std::hex << num_a << std::endl;
    std::cout << " expected: (0xffffffffffffffff 0xffffffffffffffff 0xffffffffffffffff 0xffffffffffffffff) " << std::endl;

    // Add one to get overflow (should wrap to zero)
    num_a += num_b;

    std::cout << " after increment: " << num_a << std::endl;
    std::cout << " expected: (0 0 0 0) " << std::endl;

    return 0;
}

