using v8::Persistent;
using v8::PropertyCallbackInfo;
using v8::String;
using v8::Symbol;
using v8::Undefined;
using v8::Value;

// Generator class with slightly different naming and internal logic
class RangeIterator {
public:
  RangeIterator(int beginVal, int limitVal) : pos(beginVal), limit(limitVal) {}

  bool hasMore() const {
    return pos < limit;
  }

  int advance() {
    return pos++;
  }

private:
  int pos;
  int limit;
};

// Factory function for creating the generator instance
void CreateGenerator(const FunctionCallbackInfo<Value>& info) {
  Isolate* isolate = info.GetIsolate();
  Local<Context> context = isolate->GetCurrentContext();

  if (info.IsConstructCall()) {
    int start = info[0]->IntegerValue(context).ToChecked();
    int finish = info[1]->IntegerValue(context).ToChecked();

    RangeIterator* iter = new RangeIterator(start, finish);
    info.This()->SetInternalField(0, External::New(isolate, iter));

    info.GetReturnValue().Set(info.This());
  } else {
    Local<Function> cons = Local<Function>::New(isolate, constructorRef);
    Local<Value> argv[2] = { info[0], info[1] };
    info.GetReturnValue().Set(cons->NewInstance(context, 2, argv).ToLocalChecked());
  }
}

// Implementation of the iterator's next() method
void GetNextValue(const FunctionCallbackInfo<Value>& info) {
  Isolate* isolate = info.GetIsolate();
  Local<Context> context = isolate->GetCurrentContext();
  RangeIterator* iter = static_cast<RangeIterator*>(info.This()->GetInternalField(0).As<External>()->Value());

  if (iter->hasMore()) {
    int current = iter->advance();
    Local<Object> result = Object::New(isolate);
    result->Set(context, String::NewFromUtf8Literal(isolate, "value").ToLocalChecked(), Number::New(isolate, current));
    result->Set(context, String::NewFromUtf8Literal(isolate, "done").ToLocalChecked(), Boolean::New(isolate, false));
    info.GetReturnValue().Set(result);
  } else {
    Local<Object> result = Object::New(isolate);
    result->Set(context, String::NewFromUtf8Literal(isolate, "value").ToLocalChecked(), Undefined(isolate));
    result->Set(context, String::NewFromUtf8Literal(isolate, "done").ToLocalChecked(), Boolean::New(isolate, true));
    info.GetReturnValue().Set(result);
  }
}

// Implementation of @@iterator method (returns self)
void ReturnSelfForIteration(const PropertyCallbackInfo<Value>& info) {
  info.GetReturnValue().Set(info.Holder());
}

// Persistent reference to the constructor function
Persistent<Function> RangeIterator::constructorRef;

// Module initialization function
void SetupModule(Local<Object> exports) {
  Isolate* isolate = exports->GetIsolate();
  Local<Context> context = isolate->GetCurrentContext();

  // Create function template for the generator class
  Local<FunctionTemplate> tpl = FunctionTemplate::New(isolate, CreateGenerator);
  tpl->SetClassName(String::NewFromUtf8Literal(isolate, "RangeIterator").ToLocalChecked());
  tpl->InstanceTemplate()->SetInternalFieldCount(1);

  // Add methods to prototype
  NODE_SET_PROTOTYPE_METHOD(tpl, "next", GetNextValue);

  // Set up @@iterator symbol property
  Local<Function> iteratorFunc = FunctionTemplate::New(isolate, ReturnSelfForIteration)
                                     ->GetFunction(context)
                                     .ToLocalChecked();
  tpl->InstanceTemplate()->Set(Symbol::GetIterator(isolate), iteratorFunc);

  // Store constructor in persistent handle
  constructorRef.Reset(isolate, tpl->GetFunction(context).ToLocalChecked());

  // Export the class to module exports
  exports->Set(context,
               String::NewFromUtf8Literal(isolate, "RangeIterator").ToLocalChecked(),
               tpl->GetFunction(context).ToLocalChecked()).Check();
}

