// Type ID generator using template metaprogramming
template <typename TBase>
class ComponentTypeManager
{
public:
    template <typename TDerived>
    static std::size_t AssignNewType()
    {
        static const std::size_t typeId = s_nextAvailableId++;
        return typeId;
    }

private:
    static std::size_t s_nextAvailableId;
};

template <typename TBase>
std::size_t ComponentTypeManager<TBase>::s_nextAvailableId = 0;

// Helper function to get type ID for a component type
template <typename T>
std::size_t GetComponentTypeId()
{
    return ComponentTypeManager<void>::AssignNewType<T>();
}

// Base class for all components
class ComponentBase
{
public:
    virtual ~ComponentBase() = default;
    virtual std::unique_ptr<ComponentBase> Clone(const rapidjson::Value&) = 0;
};

// Template component class
template <typename T>
class Component : public ComponentBase
{
public:
    std::unique_ptr<ComponentBase> Clone(const rapidjson::Value& json) override
    {
        auto instance = std::make_unique<T>();
        instance->Deserialize(json);
        return instance;
    }

    virtual void Deserialize(const rapidjson::Value&) = 0;
};

// Example component classes (minimal implementations)
class Position : public Component<Position>
{
public:
    float x = 0.0f, y = 0.0f;
    void Deserialize(const rapidjson::Value& json) override
    {
        if (json.IsObject()) {
            if (json.HasMember("x") && json["x"].IsNumber()) x = json["x"].GetFloat();
            if (json.HasMember("y") && json["y"].IsNumber()) y = json["y"].GetFloat();
        }
    }
};

class Name : public Component<Name>
{
public:
    std::string value;
    void Deserialize(const rapidjson::Value& json) override
    {
        if (json.IsString()) value = json.GetString();
    }
};

class Size : public Component<Size>
{
public:
    float width = 0.0f, height = 0.0f;
    void Deserialize(const rapidjson::Value& json) override
    {
        if (json.IsObject()) {
            if (json.HasMember("width") && json["width"].IsNumber()) width = json["width"].GetFloat();
            if (json.HasMember("height") && json["height"].IsNumber()) height = json["height"].GetFloat();
        }
    }
};

class Velocity : public Component<Velocity>
{
public:
    float dx = 0.0f, dy = 0.0f;
    void Deserialize(const rapidjson::Value& json) override
    {
        if (json.IsObject()) {
            if (json.HasMember("dx") && json["dx"].IsNumber()) dx = json["dx"].GetFloat();
            if (json.HasMember("dy") && json["dy"].IsNumber()) dy = json["dy"].GetFloat();
        }
    }
};

// Factory implementation for creating components from JSON
class ComponentFactory
{
public:
    template <typename C>
    void RegisterComponentType()
    {
        std::size_t id = GetComponentTypeId<C>();
        m_factoryMap[id] = std::make_shared<Component<C>>();
    }

    template <typename C>
    std::shared_ptr<ComponentBase> GetFactoryForType()
    {
        std::size_t id = GetComponentTypeId<C>();
        return m_factoryMap[id];
    }

    std::unique_ptr<ComponentBase> InstantiateFromJson(const std::string& typeName, const rapidjson::Value& jsonData)
    {
        std::size_t typeId = m_nameToId.at(typeName);
        auto factory = m_factoryMap[typeId];
        return factory->Clone(jsonData);
    }

    template <typename C>
    void RegisterTypeName(const std::string& name)
    {
        std::size_t id = GetComponentTypeId<C>();
        m_nameToId[name] = id;
    }

private:
    std::unordered_map<std::size_t, std::shared_ptr<ComponentBase>> m_factoryMap;
    std::unordered_map<std::string, std::size_t> m_nameToId;
};

int main()
{
    std::ifstream inputFile("components.json");
    rapidjson::IStreamWrapper streamWrapper(inputFile);
    rapidjson::Document doc;
    doc.ParseStream(streamWrapper);

    ComponentFactory factory;

    // Register all component types
    factory.RegisterComponentType<Position>();
    factory.RegisterComponentType<Name>();
    factory.RegisterComponentType<Size>();
    factory.RegisterComponentType<Velocity>();

    // Map names to their type IDs
    factory.RegisterTypeName<Position>("Position");
    factory.RegisterTypeName<Name>("Name");
    factory.RegisterTypeName<Size>("Size");
    factory.RegisterTypeName<Velocity>("Velocity");

    // Process each entity in the JSON document
    for (auto& entity : doc.GetArray())
    {
        for (auto& componentEntry : entity.GetObject())
        {
            std::string componentName = componentEntry.name.GetString();
            factory.InstantiateFromJson(componentName, componentEntry.value);
        }
    }

    return 0;
}

