#include <unordered_map>
#include <cstdint>

// Precompute scaled reciprocals for efficient division by common scale factors
std::unordered_map<uint32_t, uint32_t> inverse_factors;

void setupInverseFactors() {
    for (uint32_t factor = 1; factor <= 256; ++factor) {
        inverse_factors[factor] = static_cast<uint32_t>((1u << 16) / factor);
    }
}

void aricoder::encode(symbol* s)
{   
    // Compute interval width and update coder state
    uint32_t range = chigh - clow + 1;
    cstep = (range * inverse_factors[s->scale]) >> 16;

    // Update the current code interval
    chigh = clow + cstep * s->high_count - 1;
    clow  = clow + cstep * s->low_count;

    // Handle e3 normalization: expand interval when it falls outside middle half
    while ((clow >= CODER_LIMIT050) || (chigh < CODER_LIMIT050)) {
        if (chigh < CODER_LIMIT050) { 
            // Both bounds are in lower half: output '0' and propagate carries
            write_zero();
            flush_pending_ones();
        } else { 
            // Both bounds are in upper half: output '1' and adjust
            write_one();
            clow  &= CODER_LIMIT050 - 1;
            chigh &= CODER_LIMIT050 - 1;
            flush_pending_zeros();
        }
        clow  <<= 1;
        chigh = (chigh << 1) | 1;
    }

    // Handle e3 expansion: maintain sufficient precision when interval straddles middle region
    while ((clow >= CODER_LIMIT025) && (chigh < CODER_LIMIT075)) {
        ++nrbits;
        clow  &= CODER_LIMIT025 - 1;
        chigh ^= (CODER_LIMIT025 | CODER_LIMIT050);
        clow  <<= 1;
        chigh = (chigh << 1) | 1;
    }
}

#include <iostream>
