#include <cassert>
#include <random>

// Function to perform modular exponentiation using iterative squaring
long long modPow(long long base, long long exponent, long long mod) {
    long long res = 1;
    base %= mod;
    while (exponent > 0) {
        if (exponent & 1) {
            res = (__int128)res * base % mod;
        }
        exponent >>= 1;
        base = (__int128)base * base % mod;
    }
    return res;
}

// Optimized Miller-Rabin primality test with deterministic bases for small numbers
bool isProbablePrime(long long num, int iterations = 5) {
    if (num <= 1) return false;
    if (num <= 3) return true;
    if (num % 2 == 0) return false;

    // Decompose num-1 into d * 2^s
    long long d = num - 1;
    int s = 0;
    while ((d & 1) == 0) {
        d >>= 1;
        s++;
    }

    // Use random witnesses
    std::random_device rd;
    std::mt19937_64 gen(rd());
    std::uniform_int_distribution<long long> dis(2, num - 2);

    for (int i = 0; i < iterations; ++i) {
        long long witness = dis(gen);
        long long x = modPow(witness, d, num);

        if (x == 1 || x == num - 1) continue;

        bool composite = true;
        for (int r = 1; r < s; ++r) {
            x = modPow(x, 2, num);
            if (x == num - 1) {
                composite = false;
                break;
            }
        }
        if (composite) return false;
    }
    return true;
}

// Check if number is prime and within specified bounds
bool checkPrimeWithBounds(long long value) {
    const long long upperLimit = 1000000000000000000LL; // 10^18
    if (value < 2 || value > upperLimit) return false;
    return isProbablePrime(value);
}

int main() {
    long long inputNumber;
    std::cout << "Enter a number: ";
    std::cin >> inputNumber;

    if (checkPrimeWithBounds(inputNumber)) {
        std::cout << inputNumber << " is a prime number within the range 1 to 10^18." << std::endl;
    } else {
        std::cout << inputNumber << " is not a prime number or is out of the range 1 to 10^18." << std::endl;
    }

    return 0;
}

#include <cstring>

// Simulate RC input change handling with timeout fallback
void onRCInputChange() {
  static unsigned long lastValidSignalTime = 0;
  static int previousMode = -1;

  // Measure the high pulse width from the RC receiver
  unsigned long pulseWidth = pulseInLong(RC_INPUT_PIN, HIGH, 20000);

  if (pulseWidth != 0) {
    int currentMode = 0; // Default to position 1

    // Determine mode based on pulse duration ranges
    if (pulseWidth > 1100 && pulseWidth < 1400) {
      currentMode = 0; // Lower range: switch position 1
    } else if (pulseWidth > 1500 && pulseWidth < 1800) {
      currentMode = 1; // Middle-low range: switch position 2
    } else if (pulseWidth > 1900 && pulseWidth < 2100) {
      currentMode = 2; // Upper range: switch position 3
    }

    // Check if the mode has actually changed
    if (previousMode != currentMode) {
      previousMode = currentMode;

      // Clear the heat simulation array
      std::memset(heat, 0, sizeof(heat));
    }

    lastValidSignalTime = millis();
  }

  // Handle signal loss: if no valid pulse received for over a second
  if (millis() - lastValidSignalTime > 1000) {
    int fallbackMode = 0; // Default to safe position 1
    previousMode = fallbackMode;

    // Reset fire simulation state
    std::memset(heat, 0, sizeof(heat));
  }
}

#include <jni.h>

// Helper function to retrieve the native handle from Java object
static SimpleClass* getNativeHandle(JNIEnv* env, jobject obj) {
    jclass cls = env->GetObjectClass(obj);
    jfieldID fid = env->GetFieldID(cls, "nativeHandle", "J");
    jlong handle = env->GetLongField(obj, fid);
    return reinterpret_cast<SimpleClass*>(handle);
}

extern "C" {
    JNIEXPORT jlong JNICALL Java_SimpleClass_createNative(JNIEnv* env, jobject obj);
    JNIEXPORT void JNICALL Java_SimpleClass_destroyNative(JNIEnv* env, jobject obj, jlong handle);
    JNIEXPORT void JNICALL Java_SimpleClass_setIntVar(JNIEnv* env, jobject obj, jint someNum);
    JNIEXPORT jint JNICALL Java_SimpleClass_getIntVar(JNIEnv* env, jobject obj);
}

class SimpleClass {
private:
    int storedValue;
public:
    SimpleClass() : storedValue(0) {}
    ~SimpleClass() {}
    void assignValue(int val) { storedValue = val; }
    int retrieveValue() const { return storedValue; }
};

JNIEXPORT jlong JNICALL Java_SimpleClass_createNative(JNIEnv* env, jobject obj) {
    SimpleClass* instance = new SimpleClass();
    return reinterpret_cast<jlong>(instance);
}

JNIEXPORT void JNICALL Java_SimpleClass_destroyNative(JNIEnv* env, jobject obj, jlong handle) {
    SimpleClass* instance = reinterpret_cast<SimpleClass*>(handle);
    delete instance;
}

JNIEXPORT void JNICALL Java_SimpleClass_setIntVar(JNIEnv* env, jobject obj, jint someNum) {
    SimpleClass* instance = getNativeHandle(env, obj);
    instance->assignValue(someNum);
}

JNIEXPORT jint JNICALL Java_SimpleClass_getIntVar(JNIEnv* env, jobject obj) {
    SimpleClass* instance = getNativeHandle(env, obj);
    return instance->retrieveValue();
}

void aricoder::setup() {
    // Compute scaled reciprocals for each symbol
    for (int idx = 0; idx < total_symbols; ++idx) {
        symbols[idx].inv_scale = ((1U << 30) / symbols[idx].range);
    }
}

void aricoder::compress(symbol* sym) {
    unsigned int range_span = (chigh - clow) + 1;
    cstep = (range_span * sym->inv_scale) >> 30;

    unsigned int new_high = clow + (cstep * sym->max_idx) - 1;
    unsigned int new_low = clow + (cstep * sym->min_idx);

    clow = new_low;
    chigh = new_high;

    // Handle overflow conditions
    bool underflow = false;
    while ((clow >= HALF_RANGE) || (chigh < HALF_RANGE)) {
        if (chigh < HALF_RANGE) {
            output_bit(false);
            flush_remaining_bits(true);
        } else {
            output_bit(true);
            clow &= (HALF_RANGE - 1);
            chigh &= (HALF_RANGE - 1);
            flush_remaining_bits(false);
        }

        clow <<= 1;
        chigh = (chigh << 1) | 1;
    }

    // Handle mid-range normalization
    while ((clow >= QUARTER_RANGE) && (chigh < THREE_QUARTERS_RANGE)) {
        bit_counter++;
        clow &= (QUARTER_RANGE - 1);
        chigh ^= (QUARTER_RANGE + HALF_RANGE);
        clow <<= 1;
        chigh = (chigh << 1) | 1;
    }
}

