using namespace std;

// Function to reconstruct and print the longest common subsequence
void displayLCS(const string& firstStr, const string& secondStr, const vector<vector<int>>& table) {
    int len1 = firstStr.length();
    int len2 = secondStr.length();
    string result;

    int idx1 = len1, idx2 = len2;
    while (idx1 > 0 && idx2 > 0) {
        if (firstStr[idx1 - 1] == secondStr[idx2 - 1]) {
            result += firstStr[idx1 - 1];
            idx1--;
            idx2--;
        } else if (table[idx1 - 1][idx2] > table[idx1][idx2 - 1]) {
            idx1--;
        } else {
            idx2--;
        }
    }

    reverse(result.begin(), result.end());
    cout << "Longest Common Subsequence: " << result << endl;
}

// Function to compute and return the length of the longest common subsequence
int computeLCSLength(const string& firstStr, const string& secondStr) {
    int len1 = firstStr.length();
    int len2 = secondStr.length();

    // Initialize DP table with zeros
    vector<vector<int>> dp(len1 + 1, vector<int>(len2 + 1, 0));

    // Fill the DP table using bottom-up approach
    for (int i = 1; i <= len1; ++i) {
        for (int j = 1; j <= len2; ++j) {
            if (firstStr[i - 1] == secondStr[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1] + 1;
            } else {
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]);
            }
        }
    }

    // Display the actual LCS sequence
    displayLCS(firstStr, secondStr, dp);

    return dp[len1][len2];
}

int main() {
    string input1, input2;
    cout << "Enter the first string: ";
    cin >> input1;
    cout << "Enter the second string: ";
    cin >> input2;

    int lcsLen = computeLCSLength(input1, input2);
    cout << "Length of the Longest Common Subsequence: " << lcsLen << endl;

    return 0;
}

#include <iostream>
