using namespace std;

int main() {
    int n, m;
    cin >> n >> m;

    // Handle negative numbers by converting to positive
    if (n < 0) {
        n = -n;  // equivalent to abs(n)
    }

    // Find the nearest multiple of m that is >= original n for positive case
    // or nearest multiple of m that is >= |n| for negative case
    int remainder = n % m;
    if (remainder == 0) {
        cout << n << endl;
    } else {
        // For positive n: round up to next multiple
        // For negative n: after making n positive, we also round up
        cout << n + (m - remainder) << endl;
    }

    return 0;
}

