#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <unistd.h>
#include <opencv2/opencv.hpp>
#include <iostream>

int main() {
    // Create shared memory for image data transfer
    const char* shared_mem_name = "/image_buffer";
    int shm_file_desc = shm_open(shared_mem_name, O_CREAT | O_RDWR, 0666);
    if (shm_file_desc == -1) {
        perror("Failed to create shared memory");
        return 1;
    }

    // Define image dimensions and allocate space
    const int frame_width = 640;
    const int frame_height = 480;
    const int channels = 3;
    const size_t buffer_size = static_cast<size_t>(frame_width) * frame_height * channels;

    if (ftruncate(shm_file_desc, buffer_size) == -1) {
        perror("Failed to set shared memory size");
        return 1;
    }

    // Map shared memory into process address space
    void* mapped_ptr = mmap(nullptr, buffer_size, PROT_WRITE, MAP_SHARED, shm_file_desc, 0);
    if (mapped_ptr == MAP_FAILED) {
        perror("Memory mapping failed");
        return 1;
    }

    // Initialize OpenCV matrix with shared memory as data buffer
    cv::Mat shared_frame(frame_height, frame_width, CV_8UC3, mapped_ptr);

    // Initialize camera capture
    cv::VideoCapture camera(0);
    if (!camera.isOpened()) {
        std::cerr << "Unable to access camera" << std::endl;
        munmap(mapped_ptr, buffer_size);
        close(shm_file_desc);
        return 1;
    }

