using namespace std;

// Structure representing a connection in the graph
struct Connection {
    int destination;  // Target node
    int cost;         // Edge weight
};

// Function to insert an edge into the adjacency list
void insertEdge(vector<vector<Connection>>& adjList, int source, int target, int weight) {
    adjList[source].emplace_back(target, weight);
}

// Modified Dijkstra's algorithm to compute shortest path
vector<int> findShortestPath(const vector<vector<Connection>>& adjList, int origin, int destination) {
    int vertexCount = adjList.size();
    vector<int> distances(vertexCount, numeric_limits<int>::max());
    vector<int> predecessors(vertexCount, -1);
    distances[origin] = 0;

    // Min-heap priority queue: (distance, node)
    using HeapElement = pair<int, int>;
    priority_queue<HeapElement, vector<HeapElement>, greater<HeapElement>> minHeap;
    minHeap.emplace(0, origin);

    while (!minHeap.empty()) {
        int currentNode = minHeap.top().second;
        int currentDist = minHeap.top().first;
        minHeap.pop();

        // Early exit if destination reached
        if (currentNode == destination) break;

        // Skip outdated entries
        if (currentDist > distances[currentNode]) continue;

        // Explore neighbors
        for (const Connection& conn : adjList[currentNode]) {
            int neighbor = conn.destination;
            int edgeWeight = conn.cost;
            int newDistance = distances[currentNode] + edgeWeight;

            if (newDistance < distances[neighbor]) {
                distances[neighbor] = newDistance;
                predecessors[neighbor] = currentNode;
                minHeap.emplace(newDistance, neighbor);
            }
        }
    }

    // Reconstruct path from destination to origin
    vector<int> reconstructedPath;
    int current = destination;
    while (current != -1) {
        reconstructedPath.push_back(current);
        current = predecessors[current];
    }
    reverse(reconstructedPath.begin(), reconstructedPath.end());

    return reconstructedPath;
}

int main() {
    // Graph setup: 5 nodes (0-4)
    int totalNodes = 5;
    vector<vector<Connection>> adjacencyList(totalNodes);

    // Populate edges with weights
    insertEdge(adjacencyList, 0, 1, 10);
    insertEdge(adjacencyList, 0, 2, 5);
    insertEdge(adjacencyList, 1, 2, 2);
    insertEdge(adjacencyList, 1, 3, 1);
    insertEdge(adjacencyList, 2, 1, 3);
    insertEdge(adjacencyList, 2, 3, 9);
    insertEdge(adjacencyList, 2, 4, 2);
    insertEdge(adjacencyList, 3, 4, 4);

    // Compute shortest path from node 0 to node 4
    vector<int> optimalPath = findShortestPath(adjacencyList, 0, 4);

    // Output result
    cout << "Optimal route: ";
    for (int vertex : optimalPath) {
        cout << vertex << " ";
    }
    cout << endl;

    return 0;
}

