class MyEnumerator {
public:
    using pair_type = std::pair<pos, Obj*>;

    MyEnumerator() : index(0) {
        // Initialize with some sample data
        data.emplace_back(pos(1, 2), new Obj(1));
        data.emplace_back(pos(3, 4), new Obj(2));
        data.emplace_back(pos(5, 6), new Obj(3));
