        for (auto& p : data) {
            delete p.second;
        }
    }

    const pair_type* next() {
        if (index < static_cast<int>(data.size())) {
            current_pair = &data[index++];
            return current_pair;
        }
        current_pair = nullptr;
        return nullptr;
    }

private:
    std::vector<pair_type> data;
    int index;
    const pair_type* current_pair = nullptr;
};

