#include <immintrin.h>

// Prefetch data into cache hierarchy based on requested level
void prefetch_line(void* addr, int cache_level) {
    if (cache_level == 0) {
        _mm_prefetch((char*)addr, _MM_HINT_T0);
    } else if (cache_level == 1) {
        _mm_prefetch((char*)addr, _MM_HINT_T1);
    } else if (cache_level == 2) {
        _mm_prefetch((char*)addr, _MM_HINT_T2);
    } else if (cache_level == 3) {
        _mm_prefetch((char*)addr, _MM_HINT_NTA);
    }
}

