#include <cmath>

// Compute reciprocal square root using iterative refinement
float ReciprocalSqrt(float value) {
    // Initial approximation using bit manipulation trick
    float halfValue = 0.5f * value;
    int* intPtr = reinterpret_cast<int*>(&value);
    int biasedInteger = 0x5f3759df - (*intPtr >> 1);

    // Convert back to float for refinement
    value = *reinterpret_cast<float*>(&biasedInteger);

    // Apply Newton-Raphson iteration for improved accuracy
    // Formula: x_{n+1} = x_n * (1.5 - 0.5 * x_n^2 * value)
    value *= (1.5f - halfValue * value * value);

    return value;
}

