// Kernel: reads from device memory (no texture), writes processed pixel to output
__global__ void processPixelKernel(unsigned char* input, unsigned char* output, int width, int height) {
    int X = blockIdx.x * blockDim.x + threadIdx.x;
    int Y = blockIdx.y * blockDim.y + threadIdx.y;

    if (X < width && Y < height) {
        int idx = (Y * width + X) * 3;
        unsigned char red   = input[idx + 0];
        unsigned char green = input[idx + 1];
        unsigned char blue  = input[idx + 2];

        // Store in output (same as input here — could be modified for actual processing)
        output[idx + 0] = red;
        output[idx + 1] = green;
        output[idx + 2] = blue;
    }
}

int main() {
    // Assume width and height are defined elsewhere (e.g., from image metadata)
    const int width = 640;
    const int height = 480;

    // Allocate host image buffer (simulating IPL image data)
    size_t imgSize = width * height * 3 * sizeof(unsigned char);
    unsigned char* h_image = new unsigned char[imgSize];
    // Initialize with dummy data (e.g., gradient)
    for (int i = 0; i < width * height * 3; ++i) {
        h_image[i] = static_cast<unsigned char>(i % 256);
    }

    // Allocate device memory
    unsigned char* d_input;
    unsigned char* d_output;
    CUDA_CHECK(cudaMalloc(&d_input, imgSize));
    CUDA_CHECK(cudaMalloc(&d_output, imgSize));

    // Copy input image to device
    CUDA_CHECK(cudaMemcpy(d_input, h_image, imgSize, cudaMemcpyHostToDevice));

    // Configure kernel launch parameters
    dim3 block(16, 16);
    dim3 grid((width + block.x - 1) / block.x, (height + block.y - 1) / block.y);

    // Launch kernel
    processPixelKernel<<<grid, block>>>(d_input, d_output, width, height);
    CUDA_CHECK(cudaDeviceSynchronize());

    // Copy result back to host
    unsigned char* h_result = new unsigned char[imgSize];
    CUDA_CHECK(cudaMemcpy(h_result, d_output, imgSize, cudaMemcpyDeviceToHost));

    // Cleanup
    delete[] h_image;
    delete[] h_result;
    cudaFree(d_input);
    cudaFree(d_output);

    // Optional: verify correctness (e.g., compare first few bytes)
    bool match = true;
    for (int i = 0; i < 10; ++i) {
        if (h_image[i] != h_result[i]) {
            match = false;
            break;
        }
    }
    std::cout << "Data integrity check: " << (match ? "PASSED" : "FAILED") << std::endl;

    return 0;
}

