int timeGap[] = {500, 1000, 500, 1000}; // duration in ms
int lightLevel[] = {128, 0, 128, 0}; // PWM intensity (0-255)
int stepCount = sizeof(blinkState) / sizeof(blinkState[0]);

// Storage for incoming serial data
String receivedData = "";
String tempDelays = "";
String tempBrightness = "";

void setup() {
  // Set up the LED pin for output
  pinMode(ledOutput, OUTPUT);

  // Initialize serial communication
  Serial.begin(9600);
  Serial.println("LED Pattern Sequencer");
  Serial.println("Send new settings as comma-separated values:");
  Serial.println("Format: state,state,...,delay,delay,...,brightness,brightness,...");
  Serial.println("Example: 1,0,1,0,500,1000,500,1000,128,0,128,0");
}

void loop() {
  // Read and process serial input if available
  if (Serial.available() > 0) {
    String rawData = Serial.readStringUntil('\n');
    updateSettings(rawData);
  }

  // Execute the current blinking sequence
  for (int pos = 0; pos < stepCount; pos++) {
    analogWrite(ledOutput, lightLevel[pos]);
    delay(timeGap[pos]);
  }
}

void updateSettings(String data) {
  // Parse incoming string into segments
  String segments[12];
  int segmentIndex = 0;
  int startIdx = 0;

  while (startIdx < data.length()) {
    int nextComma = data.indexOf(',', startIdx);
    if (nextComma == -1) {
      segments[segmentIndex] = data.substring(startIdx);
      segmentIndex++;
      break;
    }
    segments[segmentIndex] = data.substring(startIdx, nextComma);
    segmentIndex++;
    startIdx = nextComma + 1;
  }

  // Validate and apply new settings
  if (segmentIndex >= 3 && segmentIndex % 3 == 0) {
    stepCount = segmentIndex / 3;
    for (int i = 0; i < stepCount; i++) {
      blinkState[i] = segments[i * 3].toInt();
      timeGap[i] = segments[i * 3 + 1].toInt();
      lightLevel[i] = segments[i * 3 + 2].toInt();
    }
    Serial.println("Pattern configuration updated!");
  } else {
    Serial.println("Error: Input must contain three equal-length groups (states, delays, brightness).");
  }
}

#include <iostream>
#include <string>
#include <vector>
#include <cctype>
#include <unordered_map>

enum class TokenType {
    INT, FLOAT, IDENTIFIER, ASSIGN, PLUS, MINUS, MUL, DIV, LPAREN, RPAREN, SEMICOLON, EOF_TOKEN,
    IF, WHILE, FUNCTION, COMMA, LBRACE, RBRACE, ERROR
};

struct Token {
    TokenType type;
    std::string value;
    int line;
    int column;
};

class Lexer {
public:
    Lexer(const std::string& source) : sourceCode(source), currentIndex(0), currentLine(1), currentColumn(1) {}

    Token getNextToken();

private:
    std::string sourceCode;
    size_t currentIndex;
    int currentLine;
    int currentColumn;

    char peekCurrentChar();
    void moveNext();
    void ignoreWhitespace();
    Token parseNumber();
    Token parseName();
    Token checkReservedWord(const std::string& text);
};

char Lexer::peekCurrentChar() {
    return currentIndex < sourceCode.length() ? sourceCode[currentIndex] : '\0';
}

void Lexer::moveNext() {
    if (peekCurrentChar() == '\n') {
        currentLine++;
        currentColumn = 1;
    } else {
        currentColumn++;
    }
    currentIndex++;
}

void Lexer::ignoreWhitespace() {
    while (std::isspace(peekCurrentChar())) {
        moveNext();
    }
}

Token Lexer::parseNumber() {
    std::string numericValue;
    while (std::isdigit(peekCurrentChar()) || peekCurrentChar() == '.') {
        numericValue += peekCurrentChar();
        moveNext();
    }
    if (numericValue.find('.') != std::string::npos) {
        return {TokenType::FLOAT, numericValue, currentLine, currentColumn};
    } else {
        return {TokenType::INT, numericValue, currentLine, currentColumn};
    }
}

Token Lexer::parseName() {
    std::string nameBuffer;
    while (std::isalnum(peekCurrentChar()) || peekCurrentChar() == '_') {
        nameBuffer += peekCurrentChar();
        moveNext();
    }
    return checkReservedWord(nameBuffer);
}

Token Lexer::checkReservedWord(const std::string& text) {
    static const std::unordered_map<std::string, TokenType> reservedWords = {
        {"if", TokenType::IF},
        {"while", TokenType::WHILE},
        {"function", TokenType::FUNCTION}
    };

    auto found = reservedWords.find(text);
    if (found != reservedWords.end()) {
        return {found->second, text, currentLine, currentColumn};
    }
    return {TokenType::IDENTIFIER, text, currentLine, currentColumn};
}

Token Lexer::getNextToken() {
    ignoreWhitespace();

    if (currentIndex >= sourceCode.length()) {
        return {TokenType::EOF_TOKEN, "", currentLine, currentColumn};
    }

    char ch = peekCurrentChar();
    if (std::isdigit(ch)) {
        return parseNumber();
    }

    if (std::isalpha(ch) || ch == '_') {
        return parseName();
    }

    moveNext();
    switch (ch) {
        case '+': return {TokenType::PLUS, "+", currentLine, currentColumn};
        case '-': return {TokenType::MINUS, "-", currentLine, currentColumn};
        case '*': return {TokenType::MUL, "*", currentLine, currentColumn};
        case '/': return {TokenType::DIV, "/", currentLine, currentColumn};
        case '(': return {TokenType::LPAREN, "(", currentLine, currentColumn};
        case ')': return {TokenType::RPAREN, ")", currentLine, currentColumn};
        case ';': return {TokenType::SEMICOLON, ";", currentLine, currentColumn};
        case ',': return {TokenType::COMMA, ",", currentLine, currentColumn};
        case '{': return {TokenType::LBRACE, "{", currentLine, currentColumn};
        case '}': return {TokenType::RBRACE, "}", currentLine, currentColumn};
        default: return {TokenType::ERROR, std::string(1, ch), currentLine, currentColumn};
    }
}

