class ArithmeticNode {
public:
    virtual ~ArithmeticNode() {}
    virtual double compute() const = 0;
};

class NumericValue : public ArithmeticNode {
private:
    double data;
public:
    NumericValue(double val) : data(val) {}
    double compute() const override { return data; }
};

class OperationNode : public ArithmeticNode {
private:
    ArithmeticNode* operand1;
    ArithmeticNode* operand2;
    char operation;
public:
    OperationNode(ArithmeticNode* op1, char op, ArithmeticNode* op2) 
        : operand1(op1), operation(op), operand2(op2) {}

    ~OperationNode() {
        delete operand1;
        delete operand2;
    }

    double compute() const override {
        double first = operand1->compute();
        double second = operand2->compute();

        switch (operation) {
            case '+': return first + second;
            case '-': return first - second;
            case '*': return first * second;
            case '/': return first / second;
            default: throw std::runtime_error("Unsupported operator encountered");
        }
    }
};

