// Helper function to determine if a character is an arithmetic operator
bool isArithmeticOperator(char c) {
    return c == '+' || c == '-' || c == '*' || c == '/';
}

// Helper function to determine if a character starts a number (including decimals)
bool isNumberStart(char c) {
    return std::isdigit(c) || c == '.';
}

// Function to get precedence level of an operator
int getPrecedenceLevel(char op) {
    if (op == '+' || op == '-') return 1;
    if (op == '*' || op == '/') return 2;
    return 0;
}

// Convert infix expression to postfix notation
std::string convertToPostfix(const std::string &infixExpr) {
    std::stack<char> opStack;
    std::string result;
    std::istringstream stream(infixExpr);
    std::string token;

    while (stream >> token) {
        // If token starts with a digit or decimal point, it's a number
        if (isNumberStart(token[0])) {
            result += token + " ";
        }
        // Handle operators
        else if (isArithmeticOperator(token[0])) {
            while (!opStack.empty() && 
                   getPrecedenceLevel(opStack.top()) >= getPrecedenceLevel(token[0])) {
                result += opStack.top();
                opStack.pop();
                result += " ";
            }
            opStack.push(token[0]);
        }
        // Handle left parenthesis
        else if (token[0] == '(') {
            opStack.push(token[0]);
        }
        // Handle right parenthesis
        else if (token[0] == ')') {
            while (!opStack.empty() && opStack.top() != '(') {
                result += opStack.top();
                opStack.pop();
                result += " ";
            }
            if (!opStack.empty() && opStack.top() == '(') {
                opStack.pop(); // Remove the matching '('
            }
        }
    }

    // Pop remaining operators from stack
    while (!opStack.empty()) {
        result += opStack.top();
        opStack.pop();
        result += " ";
    }

    return result;
}

// Evaluate a postfix expression
double evaluateExpression(const std::string &postfixExpr) {
    std::stack<double> valueStack;
    std::istringstream iss(postfixExpr);
    std::string token;

    while (iss >> token) {
        if (isNumberStart(token[0])) {
            valueStack.push(std::stod(token));
        } else if (isArithmeticOperator(token[0])) {
            double second = valueStack.top(); valueStack.pop();
            double first = valueStack.top(); valueStack.pop();

            switch (token[0]) {
                case '+': valueStack.push(first + second); break;
                case '-': valueStack.push(first - second); break;
                case '*': valueStack.push(first * second); break;
                case '/': valueStack.push(first / second); break;
            }
        }
    }

    return valueStack.top();
}

int main() {
    std::string expression = "3 + 4 * 2 / ( 1 - 5 )";
    std::string postfixForm = convertToPostfix(expression);
    double computedResult = evaluateExpression(postfixForm);

    std::cout << "Infix Expression: " << expression << std::endl;
    std::cout << "Postfix Expression: " << postfixForm << std::endl;
    std::cout << "Computed Result: " << computedResult << std::endl;

    return 0;
}

