#include <RTClib.h>

RTC_DS3231 rtc;

// Alarm settings: 7:00 AM
const int setHour = 7;
const int setMinute = 0;
const int buzzerOutput = 8;

void initializeSystem() {
  Serial.begin(9600);

  if (!rtc.begin()) {
    Serial.println("Failed to detect RTC module");
    while (true) {
      // Halt execution if RTC not found
    }
  }

  // Check if RTC lost power and re-synchronize time if needed
  if (rtc.lostPower()) {
    Serial.println("RTC time was lost. Setting current date/time...");
    rtc.adjust(DateTime(F(__DATE__), F(__TIME__)));
  }

  pinMode(buzzerOutput, OUTPUT);
}

void runClockAndAlarm() {
  DateTime currentTime = rtc.now();

  // Display current time in HH:MM:SS format
  Serial.print("Current time: ");
  Serial.print(currentTime.hour(), DEC);
  Serial.print(':');
  Serial.print(currentTime.minute(), DEC);
  Serial.print(':');
  Serial.print(currentTime.second(), DEC);
  Serial.println();

  // Trigger alarm when current time matches set time
  if (currentTime.hour() == setHour && currentTime.minute() == setMinute) {
    Serial.println("Alarm triggered!");
    digitalWrite(buzzerOutput, HIGH);
    delay(10000); // Activate buzzer for 10 seconds
    digitalWrite(buzzerOutput, LOW);
  }

  delay(1000); // Pause before next time check
}

int main() {
  initializeSystem();

  while (true) {
    runClockAndAlarm();
  }

  return 0;
}

