class MathClampAssembler : public CodeStubAssembler {
 public:
  MathClampAssembler(Zone* zone, Isolate* isolate)
      : CodeStubAssembler(zone, isolate, Code::STUB, kNoCallSiteDetails) {}

  Node* Clamp(Node* value, Node* lower_bound, Node* upper_bound) {
    // First ensure the value is not below the lower bound
    Node* meets_lower_threshold = this->Int32GreaterThanOrEqual(value, lower_bound);
    Node* adjusted_value = this->ChangeInt32ToInt32(
        this->SelectInt32(meets_lower_threshold, value, lower_bound));

    // Then ensure it does not exceed the upper bound
    Node* within_upper_limit = this->Int32LessThanOrEqual(adjusted_value, upper_bound);
    Node* result = this->ChangeInt32ToInt32(
        this->SelectInt32(within_upper_limit, adjusted_value, upper_bound));

    return result;
  }
};

