const int trackWidth = 20;
const int trackLength = 40;

void renderTrack(const char grid[][trackLength], int playerY) {
    for (int row = 0; row < trackWidth; ++row) {
        for (int col = 0; col < trackLength; ++col) {
            if (row == playerY && col == trackLength / 2) {
                std::cout << 'R';
            } else {
                std::cout << grid[row][col];
            }
        }
        std::cout << "\n";
    }
}

void updatePlayerPosition(int &yPos, char cmd) {
    if (cmd == 'l' && yPos > 0) {
        --yPos;
    } else if (cmd == 'r' && yPos < trackWidth - 1) {
        ++yPos;
    }
}

int main() {
    srand(time(0));

    char field[trackWidth][trackLength] = {};

    for (int i = 0; i < trackWidth; ++i) {
        for (int j = 0; j < trackLength; ++j) {
            if (j == 0 || j == trackLength - 1) {
                field[i][j] = '|';
            } else {
                field[i][j] = ' ';
            }
        }
    }

    int playerY = trackWidth / 2;
    int remainingLaps = 3;
    int distanceTraveled = 0;

    while (remainingLaps > 0) {
        system("clear");

        renderTrack(field, playerY);

        char key;
        std::cin >> key;
        updatePlayerPosition(playerY, key);

        int randomOffset = rand() % 3 - 1;
        if (playerY + randomOffset >= 0 && playerY + randomOffset < trackWidth) {
            playerY += randomOffset;
        }

        if (++distanceTraveled >= trackLength) {
            --remainingLaps;
            distanceTraveled = 0;
        }

        usleep(50000);
    }

    std::cout << "Well done! You completed the course!\n";

    return 0;
}

