class GameObject {
public:
    Vector2D position;
    Vector2D velocity;
    int uniqueID = -1;
    std::shared_ptr<bitmap_image> imagePtr;

    GameObject(std::shared_ptr<bitmap_image> img, const Vector2D& pos, const Vector2D& vel)
        : imagePtr(img), position(pos), velocity(vel) {}

    GameObject(std::shared_ptr<bitmap_image> img, float px, float py, float vx, float vy)
        : imagePtr(img), position(px, py), velocity(vx, vy) {}

    int getIdentifier() const { return uniqueID; }
};

std::vector<std::shared_ptr<GameObject>> objectList;
int globalCounter = 0;
bool isGameActive = true;
HWND consoleWindowHandle;
HDC deviceContext;
COLORREF pixelColor;

void registerObject(std::shared_ptr<GameObject> obj) {
    if (objectList.size() >= MAX_OBJECTS) {
        objectList.erase(objectList.begin());
        obj->uniqueID = MAX_OBJECTS - 1;
    }
    obj->uniqueID = globalCounter++;
    objectList.push_back(obj);
}

void handleInput() {}

void updateLogic() {}

Vector2D calculateInterpolatedPosition(float alpha, const Vector2D& currentPos, const Vector2D& currentVel) {
    return Vector2D(currentPos.x + (currentVel.x * alpha), currentPos.y + (currentVel.y * alpha));
}

void drawBitmapToScreen(std::shared_ptr<bitmap_image> img, const Vector2D& screenPos) {
    unsigned int height = img->height();
    unsigned int width = img->width();
    rgb_t pixelRGB;

    for (unsigned int py = 0; py < height; ++py) {
        for (unsigned int px = 0; px < width; ++px) {
            pixelRGB = img->get_pixel(px, py);
            pixelColor = RGB(pixelRGB.red, pixelRGB.green, pixelRGB.blue);
            SetPixelV(deviceContext, static_cast<int>(px + screenPos.x), 
                      static_cast<int>(py + screenPos.y), pixelColor);
        }
    }
}

void renderSingleObject(float alpha, std::shared_ptr<GameObject> obj) {
    Vector2D interpolatedPos = calculateInterpolatedPosition(alpha, obj->position, obj->velocity);
    drawBitmapToScreen(obj->imagePtr, interpolatedPos);
}

void presentFrame(float alpha) {
    for (const auto& obj : objectList) {
        renderSingleObject(alpha, obj);
    }
}

void adjustWindowSize() {
    RECT windowRect;
    GetWindowRect(consoleWindowHandle, &windowRect);
    MoveWindow(consoleWindowHandle, windowRect.left, windowRect.top, 800, 600, TRUE);
}

