    return 0;
}

int gameLoop() {
    const int TARGET_TICKS_PER_SECOND = 60;
    const int TIME_PER_TICK = 1000 / TARGET_TICKS_PER_SECOND;
    const int MAX_UPDATES_PER_FRAME = 1;

    DWORD nextUpdateTick = GetTickCount();
    float interpolationFactor;
    int updateCount;

    while (isGameActive) {
        updateCount = 0;
        while (GetTickCount() > nextUpdateTick && updateCount < MAX_UPDATES_PER_FRAME) {
            handleInput();
            updateLogic();

            nextUpdateTick += TIME_PER_TICK;
            updateCount++;
        }

        interpolationFactor = static_cast<float>(GetTickCount() + TIME_PER_TICK - nextUpdateTick) / 
                              static_cast<float>(TIME_PER_TICK);
        presentFrame(interpolationFactor);
    }
    return 0;
}

int cleanupResources() {
    ReleaseDC(consoleWindowHandle, deviceContext);
    return 0;
}

