    setupTestScenario();
    gameLoop();
    cleanupResources();
    return 0;
}

#include <iostream>
using namespace std;

// Define the Node structure
struct Node {
    int value;
    Node* link;
};

// Function to allocate and initialize a new node
Node* newNode(int val) {
    Node* created = new Node();
    if (created == nullptr) {
        cout << "Memory allocation failed\n";
        return nullptr;
    }
    created->value = val;
    created->link = nullptr;
    return created;
}

// Add a new node at the start of the list
void prepend(Node** start, int val) {
    Node* fresh = newNode(val);
    fresh->link = *start;
    *start = fresh;
}

// Append a new node at the end of the list
void append(Node** start, int val) {
    Node* fresh = newNode(val);
    if (*start == nullptr) {
        *start = fresh;
        return;
    }
    Node* cursor = *start;
    while (cursor->link != nullptr) {
        cursor = cursor->link;
    }
    cursor->link = fresh;
}

// Insert a new node at a specified index in the list
void insertAt(Node** start, int val, int idx) {
    if (idx == 1) {
        prepend(start, val);
        return;
    }
    Node* fresh = newNode(val);
    Node* cursor = *start;
    for (int count = 1; cursor != nullptr && count < idx - 1; ++count) {
        cursor = cursor->link;
    }
    if (cursor == nullptr) {
        cout << "Invalid index\n";
        return;
    }
    fresh->link = cursor->link;
    cursor->link = fresh;
}

// Display all nodes in the list
void showList(Node* start) {
    Node* cursor = start;
    while (cursor != nullptr) {
        cout << cursor->value << " ";
        cursor = cursor->link;
    }
    cout << endl;
}

// Remove a node with a specific value from the list
void removeNode(Node** start, int target) {
    Node* cursor = *start;
    Node* prior = nullptr;

    if (cursor != nullptr && cursor->value == target) {
        *start = cursor->link;
        delete cursor;
        return;
    }

    while (cursor != nullptr && cursor->value != target) {
        prior = cursor;
        cursor = cursor->link;
    }

    if (cursor == nullptr) {
        cout << "Value not found\n";
        return;
    }

    prior->link = cursor->link;
    delete cursor;
}

// Entry point of the program
int main() {
    Node* head = nullptr;

    append(&head, 10);
    append(&head, 20);
    prepend(&head, 5);
    insertAt(&head, 15, 2);

    cout << "Linked list: ";
    showList(head);

    removeNode(&head, 15);
    cout << "After removing 15: ";
    showList(head);

    return 0;
}

#include <vector>
#include <cmath>
#include <random>
#include <complex>

struct RadioSignal {
  double transmitPower; // in dBm
  double carrierFreq;
  double channelBandwidth;
};

class FullBandSpectrumSynthesizer {
public:
  FullBandSpectrumSynthesizer(double lowFreq, double highFreq, double samplingRate, double ambientNoise, double signalToNoise, std::vector<RadioSignal> txList) :
    m_lowFreq(lowFreq), m_highFreq(highFreq), m_samplingRate(samplingRate), m_ambientNoise(ambientNoise), 
    m_signalToNoise(signalToNoise), m_txSignals(txList) {}

  std::vector<double> synthesize() {
    const size_t binCount = 1024;
    std::vector<double> frequencies(binCount);
    double deltaF = m_samplingRate / binCount;

    for (size_t idx = 0; idx < binCount; ++idx) {
      frequencies[idx] = m_lowFreq + idx * deltaF;
    }

    std::vector<double> spectrum(binCount, m_ambientNoise);

    for (const auto& tx : m_txSignals) {
      std::vector<double> txSpectrum = buildTxSpectrum(tx, frequencies, binCount);
      for (size_t idx = 0; idx < binCount; ++idx) {
        spectrum[idx] += txSpectrum[idx];
      }
    }

    return spectrum;
  }

private:
  double m_lowFreq;
  double m_highFreq;
  double m_samplingRate;
  double m_ambientNoise;
  double m_signalToNoise;
  std::vector<RadioSignal> m_txSignals;

  std::mt19937 m_randomEngine;
  std::uniform_real_distribution<double> m_phaseDist{0.0, 1.0};

  std::vector<double> buildTxSpectrum(const RadioSignal& tx, const std::vector<double>& freqs, size_t bins) {
    std::vector<double> result(bins, 0.0);
    double halfBW = tx.channelBandwidth / 2.0;

    for (size_t i = 0; i < bins; ++i) {
      double f = freqs[i];
      if (f >= tx.carrierFreq - halfBW && f <= tx.carrierFreq + halfBW) {
        double p_watts = dBm_to_W(tx.transmitPower);
        double n_watts = p_watts / dB_to_ratio(m_signalToNoise);

        std::complex<double> sig = create_tx_complex(p_watts, f);
        std::complex<double> noise = create_noise_complex(n_watts);
        std::complex<double> combined = sig + noise;

        double magnitude = std::abs(combined);
        double psd = W_to_dBm(magnitude / m_samplingRate) - 30.0;
        result[i] = psd;
      }
    }
    return result;
  }

  std::vector<double> create_noise_floor(const std::vector<double>& freqs, size_t bins) {
    std::vector<double> floor(bins);
    double basePower = dBm_to_W(m_ambientNoise);

    for (size_t i = 0; i < bins; ++i) {
      double noiseVal = compute_noise(basePower);
      floor[i] = W_to_dBm(noiseVal / m_samplingRate) - 30.0;
    }
    return floor;
  }

  double compute_noise(double powerLevel) {
    std::normal_distribution<double> dist(0.0, std::sqrt(powerLevel));
    double re = dist(m_randomEngine);
    double im = dist(m_randomEngine);
    return re * re + im * im;
  }

  std::complex<double> create_tx_complex(double power, double frequency) {
    double phase = m_phaseDist(m_randomEngine) * 2.0 * M_PI;
    double amp = std::sqrt(dBm_to_W(power));
    double angle = 2.0 * M_PI * frequency / m_samplingRate + phase;
    return std::complex<double>(amp * std::cos(angle), amp * std::sin(angle));
  }

  std::complex<double> create_noise_complex(double power) {
    std::normal_distribution<double> dist(0.0, std::sqrt(dBm_to_W(power)));
    double re = dist(m_randomEngine);
    double im = dist(m_randomEngine);
    return std::complex<double>(re, im);
  }

  double dBm_to_W(double dBm) {
    return std::pow(10.0, dBm / 10.0 - 3.0);
  }

  double W_to_dBm(double watts) {
    return 10.0 * std::log10(watts * 1000.0);
  }

  double dB_to_ratio(double dB) {
    return std::pow(10.0, dB / 10.0);
  }
};

#include <iostream>
