// Check if two strings are anagrams by comparing character frequencies
bool areAnagrams(std::string s1, std::string s2) {
    if (s1.length() != s2.length()) {
        return false;
    }

    // Use frequency counting instead of sorting
    std::vector<int> charCount(26, 0);

    for (char c : s1) {
        if (c >= 'a' && c <= 'z') {
            charCount[c - 'a']++;
        }
    }

    for (char c : s2) {
        if (c >= 'a' && c <= 'z') {
            charCount[c - 'a']--;
        }
    }

    // If all counts are zero, strings are anagrams
    for (int count : charCount) {
        if (count != 0) {
            return false;
        }
    }

    return true;
}

int main() {
    std::string s1 = "listen";
    std::string s2 = "silent";
    std::cout << std::boolalpha << areAnagrams(s1, s2) << std::endl;  // Output: true
    return 0;
}

#include <cstdio>
#include <cstdlib>

typedef unsigned long U32;

extern "C" __declspec(dllexport) int ReadFile(LPSTR Path, U32** DataPtr, U32* Count)
{
    FILE *fileHandle;
    U32 *buffer;
    long fileSize;

    // Open file in binary read mode
    fileHandle = fopen(Path, "rb");
    if (fileHandle == nullptr) {
        return 0;
    }

    // Determine file size
    fseek(fileHandle, 0L, SEEK_END);
    fileSize = ftell(fileHandle);
    rewind(fileHandle);

    // Validate file size alignment
    if (fileSize % sizeof(U32) != 0) {
        fclose(fileHandle);
        return -3; // File size is not a multiple of sizeof(U32)
    }

    // Allocate memory for the entire file content
    buffer = static_cast<U32*>(malloc(fileSize));
    if (buffer == nullptr) {
        fclose(fileHandle);
        return -1;
    }

    // Read file contents into buffer
    size_t elementsRead = fread(buffer, sizeof(U32), fileSize / sizeof(U32), fileHandle);
    if (elementsRead == 0) {
        fclose(fileHandle);
        free(buffer);
        return -2;
    }

    *Count = static_cast<U32>(elementsRead);
    *DataPtr = buffer;
    fclose(fileHandle);
    return 1;
}

#include <iostream>
#include <vector>
#include <string>

// Function to compute the longest common subsequence of two strings
std::string findLCS(const std::string& str1, const std::string& str2) {
    int len1 = str1.size();
    int len2 = str2.size();

    // Initialize DP table with zeros
    std::vector<std::vector<int>> table(len1 + 1, std::vector<int>(len2 + 1, 0));

    // Build the DP table bottom-up
    for (int idx1 = 1; idx1 <= len1; ++idx1) {
        for (int idx2 = 1; idx2 <= len2; ++idx2) {
            if (str1[idx1 - 1] == str2[idx2 - 1]) {
                table[idx1][idx2] = table[idx1 - 1][idx2 - 1] + 1;
            } else {
                table[idx1][idx2] = (table[idx1 - 1][idx2] > table[idx1][idx2 - 1]) 
                                  ? table[idx1 - 1][idx2] 
                                  : table[idx1][idx2 - 1];
            }
        }
    }

    // Backtrack to construct the LCS string
    std::string result;
    int pos1 = len1, pos2 = len2;
    while (pos1 > 0 && pos2 > 0) {
        if (str1[pos1 - 1] == str2[pos2 - 1]) {
            result = str1[pos1 - 1] + result;
            --pos1;
            --pos2;
        } else if (table[pos1 - 1][pos2] > table[pos1][pos2 - 1]) {
            --pos1;
        } else {
            --pos2;
        }
    }

    return result;
}

// Entry point for testing the LCS implementation
int main() {
    std::string firstString = "ABCBDAB";
    std::string secondString = "BDCAB";

    std::string lcsResult = findLCS(firstString, secondString);
    std::cout << "The longest common subsequence of \"" << firstString << "\" and \"" 
              << secondString << "\" is: " << lcsResult << std::endl;

    return 0;
}

