#ifndef ATOMIC_UTILS_H
#define ATOMIC_UTILS_H

#include <cstddef>

class AtomicUtils
{
public:
    /**
     * Atomically compare and swap: if the value at addr equals expected,
     * store desired into addr; return the original value at addr
     */
    static size_t compareAndSwap(volatile size_t* location, size_t expected, size_t desired)
    {
        size_t previous;
        __asm__ volatile(
            "lock cmpxchgq %2, %1\n\t"
            : "=a"(previous), "+m"(*location)
            : "r"(desired), "0"(expected)
            : "memory"
        );
        return previous;
    }
};

#endif

