#include <cuda_runtime.h>

// CUDA Kernel: computes a value for each 3D array element based on its coordinates
__global__ void compute3DValues(float *deviceArray, int width, int height, int depth) {
    int col = blockIdx.x * blockDim.x + threadIdx.x;
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int slice = blockIdx.z * blockDim.z + threadIdx.z;

    if (col < width && row < height && slice < depth) {
        // Compute linear index for 3D array storage (row-major order)
        int idx = slice * width * height + row * width + col;

        // Assign sum of coordinates as the value
        deviceArray[idx] = static_cast<float>(col + row + slice);
    }
}

int main() {
    // Define dimensions of the 3D array
    int dimX = 2, dimY = 2, dimZ = 2;
    int totalElements = dimX * dimY * dimZ;
    int memorySize = totalElements * sizeof(float);

    // Allocate host memory
    float *hostData = (float *)malloc(memorySize);

    // Allocate device memory
    float *deviceData;
    cudaMalloc((void **)&deviceData, memorySize);

    // Initialize host data (not strictly necessary since we overwrite it after kernel execution)
    for (int i = 0; i < totalElements; ++i) {
        hostData[i] = 0.0f;
    }

    // Transfer initial data to device
    cudaMemcpy(deviceData, hostData, memorySize, cudaMemcpyHostToDevice);

    // Configure execution configuration
    dim3 blockSize(8, 8, 8);  // Reduced block size for better occupancy on smaller grids
    dim3 gridSize(
        (dimX + blockSize.x - 1) / blockSize.x,
        (dimY + blockSize.y - 1) / blockSize.y,
        (dimZ + blockSize.z - 1) / blockSize.z
    );

    // Launch the CUDA kernel
    compute3DValues<<<gridSize, blockSize>>>(deviceData, dimX, dimY, dimZ);

    // Synchronize to ensure kernel completion before copying back
    cudaDeviceSynchronize();

    // Copy results back to host
    cudaMemcpy(hostData, deviceData, memorySize, cudaMemcpyDeviceToHost);

    // Output results in structured format
    for (int z = 0; z < dimZ; ++z) {
        for (int y = 0; y < dimY; ++y) {
            for (int x = 0; x < dimX; ++x) {
                std::cout << "hostData[" << z << "][" << y << "][" << x << "] = " 
                          << hostData[z * dimX * dimY + y * dimX + x] << std::endl;
            }
        }
    }

    // Clean up resources
    free(hostData);
    cudaFree(deviceData);

    return 0;
}

