// Determine if a number is prime using an alternative approach
bool checkPrime(int value) {
    // Handle edge cases: numbers less than 2 are not prime
    if (value < 2) {
        return false;
    }

    // Special case for 2 and 3
    if (value == 2 || value == 3) {
        return true;
    }

    // Eliminate even numbers and multiples of 3
    if (value % 2 == 0 || value % 3 == 0) {
        return false;
    }

    // Check divisibility using 6k ± 1 optimization
    int divisor = 5;
    while (divisor * divisor <= value) {
        if (value % divisor == 0 || value % (divisor + 2) == 0) {
            return false;
        }
        divisor += 6;
    }

    return true;
}

int main() {
    int inputNumber;
    std::cout << "Enter a number to check if it is prime: ";
    std::cin >> inputNumber;

    if (checkPrime(inputNumber)) {
        std::cout << inputNumber << " is a prime number." << std::endl;
    } else {
        std::cout << inputNumber << " is not a prime number." << std::endl;
    }

    return 0;
}

