#include <cstdint>
#include <atomic>

// Define a constant representing an invalid index (all bits set)
static constexpr std::uint64_t INVALID_INDEX = ~std::uint64_t(0);

class BitAllocator {
public:
    // Returns a bitmask with all bits set (indicating full occupancy)
    static constexpr std::uint64_t all_occupied() noexcept {
        return ~std::uint64_t(0);
    }

    // Attempts to find and reserve the first available bit (index)
    std::uint64_t allocate() noexcept {
        while (true) {
            // Load current state without synchronization for performance
            auto current_map = mBitMap.load(std::memory_order_relaxed);

            // If no free bits remain, return invalid index
            if (current_map == all_occupied()) {
                return INVALID_INDEX;
            }

            // Find the least significant unset bit using count trailing zeros
            std::uint64_t candidate_index = __builtin_ctzl(~current_map);

            // Attempt to set this bit atomically
            auto mask = make_bit(candidate_index);
            auto prior_state = mBitMap.fetch_or(mask, std::memory_order_acq_rel);

            // Verify that the bit was indeed unset before our attempt
            if ((prior_state & mask) == 0) {
                return candidate_index;  // Successfully allocated
            }
            // Otherwise, loop again in case of race condition
        }
    }

private:
    // Helper to create a bitmask for a specific index
    static constexpr std::uint64_t make_bit(std::uint64_t idx) noexcept {
        return std::uint64_t(1) << idx;
    }

    // Atomic storage for the bitmap
    std::atomic<std::uint64_t> mBitMap{ 0 };
};

int main() {
    BitAllocator allocator;
    return allocator.allocate();
}

