#define checkCudaErrors(val) verifyCudaResult((val), #val, __FILE__, __LINE__)

template <typename T>
void verifyCudaResult(T error_code, char const *const function_name, 
                      char const *const source_file, int const line_number) {
    if (error_code != 0) {
        fprintf(stderr, "CUDA error encountered at %s:%d — error code=%d(%s) in function \"%s\"\n", 
                source_file, line_number, static_cast<unsigned int>(error_code), 
                cudaGetErrorName(error_code), function_name);
        cudaDeviceReset();
        exit(EXIT_FAILURE);
    }
}

