// Check if a number is prime using optimized logic
bool checkPrime(int value) {
    if (value <= 1) return false;
    if (value == 2) return true;
    if (value % 2 == 0) return false;

    int limit = static_cast<int>(std::sqrt(value));
    for (int j = 3; j <= limit; j += 2) {
        if (value % j == 0) return false;
    }
    return true;
}

// Compute sum of first 'count' prime numbers
int accumulatePrimes(int count) {
    int total = 0;
    int current = 2;
    int found = 0;

    while (found < count) {
        if (checkPrime(current)) {
            total += current;
            found++;
        }
        current++;
    }
    return total;
}

int main() {
    std::cout << accumulatePrimes(10) << std::endl;
    return 0;
}

