int main() {
    // Initialize random seed based on current time
    srand(static_cast<unsigned int>(time(nullptr)));

    const int matrixSize = 1000;
    const int iterations = 10;

    // Generate random matrices
    MatrixXd A = MatrixXd::Random(matrixSize, matrixSize);
    MatrixXd B = MatrixXd::Random(matrixSize, matrixSize);
    MatrixXd C = MatrixXd::Random(matrixSize, matrixSize);

    // Set up parallel execution with 8 threads
    Eigen::ThreadPool threadPool(8);
    Eigen::ThreadPoolDevice device(&threadPool, 8);

    cout << "Running matrix multiplication benchmark with " << matrixSize << "x" << matrixSize 
         << " matrices over " << iterations << " iterations" << endl;

    clock_t beginTime = clock();
    for (int k = 0; k < iterations; ++k) {
        C.device(device) = A * B;
    }
    clock_t endTime = clock() - beginTime;

    double totalTime = static_cast<double>(endTime) / CLOCKS_PER_SEC;
    cout << "Average time per multiplication: " << totalTime / iterations << " seconds" << endl;

    return 0;
}

