// Reordered and refactored task scheduler implementation
class JobDispatcher {
public:
    JobDispatcher() : shutdown_flag(false) {}

    // Add a recurring job with specified delay
    void enqueue_job(std::function<void()> job_func, std::chrono::milliseconds delay_ms) {
        {
            std::lock_guard<std::mutex> guard(queue_mutex);
            auto current_time = std::chrono::steady_clock::now();
            jobs.push({job_func, delay_ms, current_time + delay_ms});
        }
        condition.notify_one();
    }

    // Launch worker threads
    void activate() {
        for (int i = 0; i < thread_count; ++i) {
            executor_threads.emplace_back(&JobDispatcher::process, this);
        }
    }

    // Terminate all workers gracefully
    void deactivate() {
        {
            std::lock_guard<std::mutex> guard(queue_mutex);
            shutdown_flag = true;
        }
        condition.notify_all();
        for (auto& thread : executor_threads) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

private:
    struct JobDescriptor {
        std::function<void()> execute;
        std::chrono::milliseconds period;
        std::chrono::steady_clock::time_point scheduled_time;
    };

    // Comparator for priority queue (min-heap based on next execution time)
    struct JobComparator {
        bool operator()(const JobDescriptor& first, const JobDescriptor& second) const {
            return first.scheduled_time > second.scheduled_time;
        }
    };

    void process() {
        while (true) {
            std::unique_lock<std::mutex> lock(queue_mutex);

            // Wait until there's work or shutdown is requested
            condition.wait(lock, [this] { 
                return shutdown_flag || !jobs.empty(); 
            });

            // Exit if shutdown and no pending jobs
            if (shutdown_flag && jobs.empty()) {
                break;
            }

            auto current_time = std::chrono::steady_clock::now();

            // Execute all due jobs
            while (!jobs.empty() && jobs.top().scheduled_time <= current_time) {
                JobDescriptor current_job = jobs.top();
                jobs.pop();

                lock.unlock();
                current_job.execute();
                lock.lock();

                // Reschedule if not shutting down
                if (!shutdown_flag) {
                    current_job.scheduled_time += current_job.period;
                    jobs.push(current_job);
                }
            }

            // Calculate wait time for next job if any remain
            if (!jobs.empty()) {
                auto next_execution = jobs.top().scheduled_time;
                auto remaining_time = std::chrono::duration_cast<std::chrono::milliseconds>(
                    next_execution - current_time
                );
                condition.wait_for(lock, remaining_time);
            }
        }
    }

    std::vector<std::thread> executor_threads;
    std::mutex queue_mutex;
    std::condition_variable condition;

    // Priority queue using custom comparator
    std::priority_queue<JobDescriptor, std::vector<JobDescriptor>, JobComparator> jobs;

    bool shutdown_flag;
    static constexpr int thread_count = 4;
};

// Sample function to demonstrate usage
void display_notification(const std::string& text) {
    std::cout << text << std::endl;
}

int main() {
    JobDispatcher dispatcher;

    // Schedule periodic tasks
    dispatcher.enqueue_job(
        []() { display_notification("Task A"); }, 
        std::chrono::milliseconds(1000)
    );

    dispatcher.enqueue_job(
        []() { display_notification("Task B"); }, 
        std::chrono::milliseconds(500)
    );

    dispatcher.activate();

    // Let tasks run for 10 seconds
    std::this_thread::sleep_for(std::chrono::seconds(10));

    dispatcher.deactivate();

    return 0;
}

#include <iostream>

// Definition for singly-linked list.
struct ListNode {
    int val;
    ListNode *next;
    ListNode(int x) : val(x), next(nullptr) {}
};

bool hasCycle(ListNode *head) {
    // Handle edge cases: empty list or single node without cycle
    if (!head || !head->next) {
        return false;
    }

    // Use two pointers moving at different speeds
    ListNode *slow = head;
    ListNode *fast = head;

    while (fast && fast->next) {
        slow = slow->next;          // Advance by one node
        fast = fast->next->next;    // Advance by two nodes

        // If they meet, there's a cycle
        if (slow == fast) {
            return true;
        }
    }

    // Fast pointer reached the end, so no cycle exists
    return false;
}

int main() {
    // Create test linked list with a cycle
    ListNode *node1 = new ListNode(1);
    ListNode *node2 = new ListNode(2);
    ListNode *node3 = new ListNode(3);
    ListNode *node4 = new ListNode(4);

    node1->next = node2;
    node2->next = node3;
    node3->next = node4;
    node4->next = node2;  // Cycle back to second node

    // Check for cycle and output result
    if (hasCycle(node1)) {
        std::cout << "Cycle detected." << std::endl;
    } else {
        std::cout << "No cycle detected." << std::endl;
    }

    // Free allocated memory
    delete node1;
    delete node2;
    delete node3;
    delete node4;

    return 0;
}

#include <iostream>
