class IRGenerator {
public:
    std::string generateAssembly(Node* n) {
        std::string result = "";
        std::string intermediate = translateToIR(n);
        result = convertToAsm(intermediate);
        return result;
    }

private:
    std::string translateToIR(Node* n) {
        if (n->type == Node::IF) {
            std::string irCode = "";
            // Process condition first
            irCode += translateToIR(n->getChild(0));

            // Generate conditional jump logic
            std::string condVal = n->getChild(0)->value;
            int labelId = nextLabel++;

            irCode += "if " + condVal + " goto .true" + std::to_string(labelId) + "\n";
            irCode += "goto .false" + std::to_string(labelId) + "\n";
            irCode += ".true" + std::to_string(labelId) + ":\n";

            // Process true branch
            irCode += translateToIR(n->getChild(1));

            // Continue with false branch marker
            irCode += ".false" + std::to_string(labelId) + ":\n";
            return irCode;
        }
        // Placeholder for other node types
        return "";
    }

    std::string convertToAsm(const std::string& irText) {
        std::string asmOutput = "";
        std::vector<std::string> lines = tokenize(irText, '\n');

        for (const auto& line : lines) {
            if (line.find("if") != std::string::npos) {
                asmOutput += "cmp ...\n";
                asmOutput += "jnz .true" + getLabel(line) + "\n";
                asmOutput += "jmp .false" + getLabel(line) + "\n";
            } else if (line.find("goto") != std::string::npos) {
                asmOutput += "jmp " + getLabel(line) + "\n";
            } else if (line.find(".true") != std::string::npos || 
                       line.find(".false") != std::string::npos) {
                asmOutput += line + ":\n";
            } else {
                asmOutput += line + "\n";
            }
        }
        return asmOutput;
    }

    std::vector<std::string> tokenize(const std::string& input, char sep) {
        std::vector<std::string> parts;
        std::string currentPart;
        std::istringstream stream(input);

        while (std::getline(stream, currentPart, sep)) {
            parts.push_back(currentPart);
        }
        return parts;
    }

    std::string getLabel(const std::string& instruction) {
        size_t pos = instruction.rfind(' ');
        if (pos != std::string::npos && pos + 1 < instruction.length()) {
            return instruction.substr(pos + 1);
        }
        return "";
    }

    int nextLabel = 0;
};

#include <map>
#include <vector>

template<typename Key, typename T, typename Compare, typename Allocator, typename Predicate>
inline void generic_remove(std::map<Key, T, Compare, Allocator> &container, const Predicate &pred)
{
    std::vector<Key> keys_to_remove;

    // First pass: identify keys whose values satisfy the predicate
    for (auto const &pair : container)
    {
        if (pred(pair.second))
        {
            keys_to_remove.push_back(pair.first);
        }
    }

    // Second pass: erase the identified keys
    for (const auto &key : keys_to_remove)
    {
        container.erase(key);
    }
}

