// Structure to manage backtrace capture state
struct StackTraceContext {
    void** position;
    void** limit;
};

// Unwind callback function to collect stack frames
static _Unwind_Reason_Code unwind_frame_handler(struct _Unwind_Context* context, void* param) {
    StackTraceContext* ctx = static_cast<StackTraceContext*>(param);
    uintptr_t instruction_ptr = _Unwind_GetIP(context);

    if (instruction_ptr != 0) {
        if (ctx->position >= ctx->limit) {
            return _URC_END_OF_STACK;
        } else {
            *(ctx->position++) = reinterpret_cast<void*>(instruction_ptr);
        }
    }
    return _URC_NO_REASON;
}

// Capture current call stack into provided buffer
void get_stack_trace(void** storage, size_t max_depth) {
    StackTraceContext context = {storage, storage + max_depth};
    _Unwind_Backtrace(unwind_frame_handler, &context);
}

// Display captured stack trace in human-readable form
void show_stack_trace() {
    const size_t max_entries = 64;
    void* stack_buffer[max_entries];
    char** demangled_symbols;

    get_stack_trace(stack_buffer, max_entries);
    demangled_symbols = backtrace_symbols(stack_buffer, max_entries);

    if (demangled_symbols != nullptr) {
        for (size_t idx = 0; idx < max_entries && demangled_symbols[idx] != nullptr; ++idx) {
            std::cout << demangled_symbols[idx] << std::endl;
        }
        free(demangled_symbols);
    }
}

// Signal handler to print backtrace on crash
void crash_handler(int sig_number) {
    std::cout << "Crash detected with signal: " << sig_number << std::endl;
    show_stack_trace();
}

int main() {
    // Install custom signal handler for segmentation fault
    signal(SIGSEGV, crash_handler);

