typedef struct {
    float re;
    float im;
} dcmplx;

dcmplx ComplexConv(int len, dcmplx *hat, dcmplx *buf)
{
    dcmplx result = {0.0f, 0.0f};

    // Process complex multiplication and accumulation using inline assembly
    asm volatile (
        "vdup.32 q0, #0\n\t"          // Initialize accumulator registers with zero
        "mov r4, #0\n\t"              // Initialize loop counter
        ".complex_loop:\n\t"
        "vldr s10, [%[h_ptr], #4]\n\t"   // Load hat[i].im
        "vldr s9, [%[h_ptr]]\n\t"        // Load hat[i].re
        "vneg.f32 s10, s10\n\t"          // Conjugate: negate imaginary part
        "vldr s12, [%[b_ptr], #4]\n\t"   // Load buf[i].im
        "vldr s11, [%[b_ptr]]\n\t"       // Load buf[i].re
        "vmul.f32 s8, s12, s9\n\t"       // temp_re = hat.re * buf.im
        "vmul.f32 s12, s10, s12\n\t"     // temp_im = hat.im * buf.im
        "adds %[h_ptr], #8\n\t"          // Advance hat pointer by sizeof(dcmplx)
        "vmla.f32 s8, s10, s11\n\t"      // temp_re += hat.im * buf.re
        "vnmls.f32 s12, s11, s9\n\t"     // temp_im -= buf.re * hat.re
        "adds %[b_ptr], #8\n\t"          // Advance buf pointer by sizeof(dcmplx)
        "vadd.f32 s1, s1, s8\n\t"        // Accumulate real parts
        "vadd.f32 s0, s0, s12\n\t"       // Accumulate imaginary parts
        "adds r4, r4, #1\n\t"            // Increment loop counter
        "cmp r4, %[count]\n\t"           // Compare with length
        "bne .complex_loop\n\t"
        : [result]"=w"(result), [h_ptr]"+r"(hat), [b_ptr]"+r"(buf)
        : [count]"r"(len)
        : "r4", "s8", "s9", "s10", "s11", "s12", "cc"
    );

    return result;
}

