#include <iostream>

typedef struct {
    float re;
    float im;
} dcmplx;

dcmplx ComplexConv(int length, dcmplx *input, dcmplx *buffer)
{
    dcmplx result = {0.0f, 0.0f};

    for (int idx = 0; idx < length; ++idx) {
        // Load current complex values
        float hat_re = input[idx].re;
        float hat_im = -input[idx].im;  // Note: negated in original asm
        float buf_re = buffer[idx].re;
        float buf_im = buffer[idx].im;

        // Complex multiplication: (hat_re + i*hat_im) * (buf_re + i*buf_im)
        // Real part: hat_re * buf_re - hat_im * buf_im
        // Imaginary part: hat_re * buf_im + hat_im * buf_re

        // Using the specific operations from the assembly:
        // First vmul: s14 = s15 * s13 = buf_re * hat_re
        // Second vmul: s15 = s11 * s15 = (-hat_im) * buf_re
        // vmla: s14 += s11 * s12 = (-hat_im) * buf_im
        // vnmls: s15 -= s12 * s13 = buf_im * hat_re

        float real_part = buf_re * hat_re + (-hat_im) * buf_im;
        float imag_part = (-hat_im) * buf_re - buf_im * hat_re;

        // Accumulate results
        result.re += real_part;
        result.im += imag_part;
    }

    return result;
}

