// Read CPU statistics from /proc/stat and return the numeric values (excluding the 'cpu' label)
std::vector<long> fetchCPUStats() {
    std::ifstream procStat("/proc/stat");
    std::string firstLine;
    std::getline(procStat, firstLine);

    std::istringstream stream(firstLine);
    std::string token;
    stream >> token; // Discard "cpu"

    std::vector<long> stats;
    while (stream >> token) {
        stats.push_back(std::stol(token));
    }
    return stats;
}

// Compute CPU usage percentage based on two snapshots
double computeCPUUtilization(const std::vector<long>& earlier, const std::vector<long>& later) {
    long sumEarlier = 0;
    long sumLater = 0;

    for (size_t idx = 0; idx < earlier.size(); ++idx) {
        sumEarlier += earlier[idx];
        sumLater += later[idx];
    }

    long totalChange = sumLater - sumEarlier;
    long idleChange = later[3] - earlier[3];

    double utilization = 0.0;
    if (totalChange != 0) {
        utilization = (1.0 - (static_cast<double>(idleChange) / static_cast<double>(totalChange))) * 100.0;
    }
    return utilization;
}

// Display current CPU usage by sampling twice with a one-second interval
void showCPUUsage() {
    auto snapshot1 = fetchCPUStats();
    std::this_thread::sleep_for(std::chrono::seconds(1));
    auto snapshot2 = fetchCPUStats();

    double cpuPercent = computeCPUUtilization(snapshot1, snapshot2);
    std::cout << "CPU Usage: " << cpuPercent << "%" << std::endl;
}

