// Helper function to simulate the blackhole behavior (assumed to be defined elsewhere)
int blackhole(const std::vector<int>& v);

// Create a copy of the input vector using manual iteration and push_back
int copy_vec1(const std::vector<int>& v1) {
    std::vector<int> v2;
    for (size_t i = 0; i < v1.size(); ++i) {
        v2.push_back(v1[i]);
    }
    return blackhole(v2);
}

// Create a copy using iterator-based construction with explicit begin/end
int copy_vec2(const std::vector<int>& v1) {
    std::vector<int> v2;
    v2.reserve(v1.size());
    for (auto it = v1.begin(); it != v1.end(); ++it) {
        v2.push_back(*it);
    }
    return blackhole(v2);
}

