// Check if a number is prime using an alternative approach
bool checkPrime(int number) {
    if (number <= 1) return false;
    if (number == 2) return true;
    if (number % 2 == 0) return false;

    int limit = static_cast<int>(std::sqrt(number));
    for (int divisor = 3; divisor <= limit; divisor += 2) {
        if (number % divisor == 0) return false;
    }
    return true;
}

int main() {
    std::vector<int> primeNumbers;

    // Collect all prime numbers from 0 to 100
    for (int value = 0; value <= 100; ++value) {
        if (checkPrime(value)) {
            primeNumbers.push_back(value);
        }
    }

    // Output the primes separated by spaces
    for (size_t i = 0; i < primeNumbers.size(); ++i) {
        std::cout << primeNumbers[i];
        if (i < primeNumbers.size() - 1) {
            std::cout << " ";
        }
    }
    std::cout << std::endl;

    return 0;
}

