// Check if a character is a vowel (case-insensitive)
bool isVowel(char ch) {
    // Convert to lowercase for uniform comparison
    char lowerCh = std::tolower(static_cast<unsigned char>(ch));
    return lowerCh == 'a' || lowerCh == 'e' || lowerCh == 'i' || 
           lowerCh == 'o' || lowerCh == 'u';
}

// Remove all vowels from the input string
std::string filterConsonants(const std::string& text) {
    std::string filtered;
    for (size_t i = 0; i < text.length(); ++i) {
        if (!isVowel(text[i])) {
            filtered += text[i];
        }
    }
    return filtered;
}

