// Global flag to track password dialog visibility
static bool bPasswordDialogActive = false;

LRESULT CALLBACK MainWndProc(HWND hwnd, UINT uMsg, WPARAM wParam, LPARAM lParam)
{
    switch (uMsg)
    {
    case WM_HOTKEY:
        if (wParam == 100) // Custom hotkey ID
        {
            DisplayAuthenticationPrompt(hwnd);
        }
        break;

    case WM_KEYDOWN:
    case WM_SYSKEYDOWN:
    case WM_LBUTTONDOWN:
    case WM_RBUTTONDOWN:
        if (!bPasswordDialogActive)
        {
            DisplayAuthenticationPrompt(hwnd);
        }
        break;

    case WM_CLOSE:
        if (bPasswordDialogActive)
        {
            return 0; // Prevent closing while dialog is active
        }
        // Continue with default handling when dialog not visible
    default:
        return DefWindowProcW(hwnd, uMsg, wParam, lParam);
    }

    return 0;
}

void DisplayAuthenticationPrompt(HWND hwndParent)
{
    bPasswordDialogActive = true;

    // Show the authentication dialog
    if (DialogBoxW(GetModuleHandleW(NULL), 
                   MAKEINTRESOURCEW(IDD_AUTH_DIALOG), 
                   hwndParent, 
                   AuthDialogProc) == IDOK)
    {
        // Exit application on successful authentication
        PostQuitMessage(0);
    }

    bPasswordDialogActive = false;
}

INT_PTR CALLBACK AuthDialogProc(HWND hDlg, UINT message, WPARAM wParam, LPARAM lParam)
{
    switch (message)
    {
    case WM_INITDIALOG:
        return (INT_PTR)TRUE;

    case WM_COMMAND:
        if (LOWORD(wParam) == IDOK || LOWORD(wParam) == IDCANCEL)
        {
            if (LOWORD(wParam) == IDOK)
            {
                wchar_t inputBuffer[256];
                GetDlgItemTextW(hDlg, IDC_PASSWORD_FIELD, inputBuffer, 256);

                std::wstring enteredPassword(inputBuffer);
                if (enteredPassword == L"your_password")
                {
                    EndDialog(hDlg, IDOK);
                }
                else
                {
                    MessageBoxW(hDlg, L"Incorrect password.", L"Access Denied", MB_OK | MB_ICONERROR);
                }
            }
            else
            {
                EndDialog(hDlg, IDCANCEL);
            }
            return (INT_PTR)TRUE;
        }
        break;
    }

    return (INT_PTR)FALSE;
}

