// Read entire file into vector using streambuf iterator approach
std::vector<char> readFileIntoBuffer(const char* path) {
    std::ifstream file(path, std::ios::binary);
    if (!file) return {};

    // Get file size by seeking to end and getting position
    file.seekg(0, std::ios::end);
    auto fileSize = static_cast<size_t>(file.tellg());
    file.seekg(0, std::ios::beg);

    // Create buffer and read data
    std::vector<char> buffer(fileSize);
    file.read(buffer.data(), fileSize);
    return buffer;
}

// Convert 64-bit value from network byte order (big-endian) to host order
uint64_t convertBigEndianToHost(uint64_t networkValue) {
    // Check system endianness at compile time for optimization
    constexpr bool isLittleEndian = __BYTE_ORDER__ == __ORDER_LITTLE_ENDIAN__;

    if constexpr (isLittleEndian) {
        // On little-endian systems, swap bytes
        uint64_t swapped = 0;
        for (int i = 0; i < 8; ++i) {
            swapped |= ((networkValue >> (i * 8)) & 0xFF) << ((7 - i) * 8);
        }
        return swapped;
    } else {
        // On big-endian systems, no conversion needed
        return networkValue;
    }
}

int main(int argc, char* argv[]) {
    const char* filename = "myFile";

    // Read file contents
    std::vector<char> fileData = readFileIntoBuffer(filename);

    // Ensure we have enough bytes to read
    if (fileData.size() < 8) {
        std::cerr << "File too small: expected at least 8 bytes" << std::endl;
        return 1;
    }

    // Extract first 8 bytes using array indexing instead of iterators
    uint64_t rawValue = 0;
    for (int i = 0; i < 8; ++i) {
        rawValue = (rawValue << 8) | (static_cast<uint8_t>(fileData[i]) & 0xFF);
    }

    // Convert endianness
    uint64_t finalValue = convertBigEndianToHost(rawValue);

    std::cout << "Size: " << finalValue << std::endl;
    return 0;
}

