#include <cstdint>

// Computes the floor of log base 2 of a positive integer
static inline int log2_floor(int val) {
#if defined(__x86_64__) || defined(__i386__)
    // Use bit scan reverse instruction for x86/x86_64
    if (val <= 0) return -1;
    int result;
    __asm__ volatile (
        "bsr %1, %0"
        : "=r"(result)
        : "r"(val)
        : "cc"
    );
    return result;
#elif defined(__arm__) || defined(__aarch64__)
    // Use count leading zeros for ARM architectures
    if (val <= 0) return -1;
    unsigned int clz_result;
    __asm__ volatile (
        "clz %0, %1"
        : "=r"(clz_result)
        : "r"(val)
    );
    return 31 - static_cast<int>(clz_result);
#else
    // Generic implementation without inline assembly
    if (val <= 0) return -1;
    int exponent = 0;
    while ((val >> (exponent + 1)) > 0) {
        ++exponent;
    }
    return exponent;
#endif
}

