// Structure to hold 2D coordinates
struct Coordinates  
{  
    double x_coord, y_coord;  
};

// CUDA kernel to update point coordinates
__global__ void UpdateCoordinates(Coordinates* device_coords)  
{  
    // Only the first thread in the grid performs the update
    if (threadIdx.x == 0 && threadIdx.y == 0 && blockIdx.x == 0 && blockIdx.y == 0)
    {  
        device_coords->x_coord = 100.0;  
        device_coords->y_coord = 100.0;    
    }
}  

int main()  
{  
    // Allocate and initialize host memory
    Coordinates* host_coords = (Coordinates*)malloc(sizeof(Coordinates));  
    host_coords->x_coord = 10.0;   
    host_coords->y_coord = 10.0;    

    // Allocate device memory
    Coordinates* device_coords;  
    cudaMalloc((void**)&device_coords, sizeof(Coordinates));  

    // Copy data from host to device
    cudaMemcpy(device_coords, host_coords, sizeof(Coordinates), cudaMemcpyHostToDevice);  

    // Define execution configuration
    dim3 block_dimensions(16, 16);  
    dim3 grid_dimensions(1, 1);  

    // Launch kernel
    UpdateCoordinates<<<grid_dimensions, block_dimensions>>>(device_coords);  

    // Wait for kernel completion before copying results back
    cudaDeviceSynchronize();  

    // Copy updated data back to host
    cudaMemcpy(host_coords, device_coords, sizeof(Coordinates), cudaMemcpyDeviceToHost);    
    std::cout << host_coords->x_coord << " " << host_coords->y_coord << std::endl;

    // Clean up allocated memory
    cudaFree(device_coords);
    free(host_coords);

    return 0;
}

