// Kernel to read from texture and write to global memory
__global__ void textureReadKernel(cudaTextureObject_t texObj, float *output, int cols, int rows) {
    int col = blockIdx.x * blockDim.x + threadIdx.x;
    int row = blockIdx.y * blockDim.y + threadIdx.y;

    if (col < cols && row < rows) {
        // Sample texture at integer coordinates using normalized or unnormalized access
        float sample = tex2D<float>(texObj, col + 0.5f, row + 0.5f);
        output[row * cols + col] = sample;
    }
}

int main() {
    // Device pointers and texture object
    float *d_inputData;
    cudaTextureObject_t texResource;
    float *d_result;

    // Define image dimensions
    int imageWidth = 256;
    int imageHeight = 256;

    // Compute total byte size
    size_t bytes = imageWidth * imageHeight * sizeof(float);

    // Allocate device memory for input and output
    cudaMalloc(&d_inputData, bytes);
    cudaMalloc(&d_result, bytes);

    // Initialize input data to zero (can be replaced with actual data)
    cudaMemset(d_inputData, 0, bytes);

    // Setup resource descriptor for linear memory
    cudaResourceDesc resDesc = {};
    resDesc.resType = cudaResourceTypeLinear;
    resDesc.res.linear.devPtr = d_inputData;
    resDesc.res.linear.desc = cudaCreateChannelDesc<float>();
    resDesc.res.linear.sizeInBytes = bytes;

    // Configure texture descriptor
    cudaTextureDesc texDesc = {};
    texDesc.readMode = cudaReadModeElementType;
    texDesc.addressMode[0] = cudaAddressModeClamp;
    texDesc.addressMode[1] = cudaAddressModeClamp;
    texDesc.filterMode = cudaFilterModePoint;  // Changed to point sampling for exact integer mapping
    texDesc.normalizedCoords = 0;             // Use unnormalized coordinates

    // Create texture object
    cudaCreateTextureObject(&texResource, &resDesc, &texDesc, nullptr);

    // Define execution configuration
    dim3 threadsPerBlock(16, 16);
    dim3 blocksPerGrid(
        (imageWidth + threadsPerBlock.x - 1) / threadsPerBlock.x,
        (imageHeight + threadsPerBlock.y - 1) / threadsPerBlock.y
    );

    // Launch kernel
    textureReadKernel<<<blocksPerGrid, threadsPerBlock>>>(texResource, d_result, imageWidth, imageHeight);
    cudaDeviceSynchronize();

    // Transfer results back to host
    float *h_result = new float[imageWidth * imageHeight];
    cudaMemcpy(h_result, d_result, bytes, cudaMemcpyDeviceToHost);

    // Cleanup resources
    cudaDestroyTextureObject(texResource);
    cudaFree(d_inputData);
    cudaFree(d_result);
    delete[] h_result;

    return 0;
}

