// Custom class to expose data via WebChannel
class DataProvider : public QObject {
    Q_OBJECT
public:
    explicit DataProvider(QObject *parent = nullptr) : QObject(parent) {}

    // Exposed method to retrieve structured data as JSON string
    Q_INVOKABLE QString fetchJsonData() const {
        QList<QVariantMap> records;

        // First record
        QVariantMap entry1;
        entry1["name"] = "value1";
        entry1["id"] = 123;
        records << entry1;

        // Second record
        QVariantMap entry2;
        entry2["name"] = "value2";
        entry2["id"] = 456;
        records << entry2;

        // Convert list of maps to JSON array
        QJsonArray jsonArr;
        for (const QVariantMap &record : records) {
            jsonArr.append(QJsonObject::fromVariantMap(record));
        }

        // Serialize to compact JSON string
        QJsonDocument doc(jsonArr);
        return doc.toJson(QJsonDocument::Compact);
    }
};

