// Rearrange bytes by separating even and odd positions 
uint8x16_t oddeven(uint8x16_t input_vector) {
    // Split the 16-byte vector into two 8-byte chunks
    uint8x8_t chunk_low  = vget_low_u8(input_vector);
    uint8x16_t chunk_high = vget_high_u8(input_vector);

    // Perform unzip operation to separate even/odd bytes
    auto unpacked = vuzp_u8(chunk_low, chunk_high);

    // Reassemble the result by combining the separated byte sequences
    return vcombine_u8(unpacked.val[0], unpacked.val[1]);
}

