struct Point3D {
    double x, y, z;

    Point3D(double x_val, double y_val, double z_val) : x(x_val), y(y_val), z(z_val) {}

    double distFrom(const Point3D &other) const {
        double dx = x - other.x;
        double dy = y - other.y;
        double dz = z - other.z;
        return std::sqrt(dx * dx + dy * dy + dz * dz);
    }
};

bool sortByX(const Point3D &a, const Point3D &b) {
    return a.x < b.x;
}

bool sortByY(const Point3D &a, const Point3D &b) {
    return a.y < b.y;
}

bool sortByZ(const Point3D &a, const Point3D &b) {
    return a.z < b.z;
}

double smallerValue(double val1, double val2) {
    return (val1 < val2) ? val1 : val2;
}

double exhaustiveSearch(std::vector<Point3D> &pts, int count) {
    double minDistance = std::numeric_limits<double>::max();
    for (int idx1 = 0; idx1 < count; ++idx1) {
        for (int idx2 = idx1 + 1; idx2 < count; ++idx2) {
            double currentDist = pts[idx1].distFrom(pts[idx2]);
            if (currentDist < minDistance) {
                minDistance = currentDist;
            }
        }
    }
    return minDistance;
}

double nearStrip(std::vector<Point3D> &stripPoints, int count, double threshold) {
    double bestDistance = threshold;

    for (int i = 0; i < count; ++i) {
        for (int j = i + 1; j < count && (stripPoints[j].y - stripPoints[i].y) < bestDistance; ++j) {
            double distance = stripPoints[i].distFrom(stripPoints[j]);
            if (distance < bestDistance) {
                bestDistance = distance;
            }
        }
    }
    return bestDistance;
}

double recursiveClosest(std::vector<Point3D> &sortedByX, std::vector<Point3D> &sortedByY, int size) {
    // Base case: use brute force for small number of points
    if (size <= 3) {
        return exhaustiveSearch(sortedByX, size);
    }

    // Divide the set into two halves
    int middleIndex = size / 2;
    Point3D medianPoint = sortedByX[middleIndex];

    // Split the Y-sorted array into left and right parts
    std::vector<Point3D> leftY, rightY;
    for (int i = 0; i < size; ++i) {
        if (sortedByY[i].x <= medianPoint.x) {
            leftY.push_back(sortedByY[i]);
        } else {
            rightY.push_back(sortedByY[i]);
        }
    }

    // Recursively find minimum distances in both halves
    double leftMin = recursiveClosest(sortedByX, leftY, middleIndex);
    double rightMin = recursiveClosest(sortedByX, rightY, size - middleIndex);

    // Determine the smaller of the two distances
    double currentMin = smallerValue(leftMin, rightMin);

    // Build the strip containing points within currentMin distance from the dividing line
    std::vector<Point3D> strip;
    for (int i = 0; i < size; ++i) {
        if (std::abs(sortedByY[i].x - medianPoint.x) < currentMin) {
            strip.push_back(sortedByY[i]);
        }
    }

    // Find the closest pair in the strip and compare with current minimum
    return smallerValue(currentMin, nearStrip(strip, static_cast<int>(strip.size()), currentMin));
}

double findClosestPair(std::vector<Point3D> &pointSet, int totalPoints) {
    std::vector<Point3D> byX = pointSet;
    std::vector<Point3D> byY = pointSet;

    std::sort(byX.begin(), byX.end(), sortByX);
    std::sort(byY.begin(), byY.end(), sortByY);

    return recursiveClosest(byX, byY, totalPoints);
}

int main() {
    std::vector<Point3D> coordinates = {{2, 3, 4}, {12, 30, 40}, {40, 50, 60}, {5, 1, 2}, {12, 10, 3}};
    int count = coordinates.size();
    std::cout << "The smallest distance is " << findClosestPair(coordinates, count) << std::endl;
    return 0;
}

