// Function to safely add two 64-bit integers with overflow/underflow detection
int64_t safeAdd(int64_t x, int64_t y) {
    // Check for positive overflow: if both operands are positive and their sum would exceed INT64_MAX
    if (x > 0 && y > 0 && x > INT64_MAX - y) {
        throw std::overflow_error("Integer overflow occurred during addition");
    }

    // Check for negative underflow: if both operands are negative and their sum would go below INT64_MIN
    if (x < 0 && y < 0 && x < INT64_MIN - y) {
        throw std::underflow_error("Integer underflow occurred during addition");
    }

    return x + y;
}

