// 3D vector structure with basic operations
struct Vec3 {
    float x, y, z;

    // Default constructor initializes to zero
    Vec3() : x(0.0f), y(0.0f), z(0.0f) {}

    // Parameterized constructor
    Vec3(float vx, float vy, float vz) : x(vx), y(vy), z(vz) {}

    // Vector addition
    Vec3 operator+(const Vec3& other) const { 
        return Vec3(x + other.x, y + other.y, z + other.z); 
    }

    // Vector subtraction
    Vec3 operator-(const Vec3& other) const { 
        return Vec3(x - other.x, y - other.y, z - other.z); 
    }

    // Scalar multiplication
    Vec3 operator*(float scalar) const { 
        return Vec3(x * scalar, y * scalar, z * scalar); 
    }

    // Scalar division
    Vec3 operator/(float scalar) const { 
        return Vec3(x / scalar, y / scalar, z / scalar); 
    }

    // Dot product calculation
    float dotProduct(const Vec3& other) const { 
        return x * other.x + y * other.y + z * other.z; 
    }

    // Cross product calculation
    Vec3 crossProduct(const Vec3& other) const { 
        return Vec3(y * other.z - z * other.y,
                    z * other.x - x * other.z,
                    x * other.y - y * other.x); 
    }

    // Magnitude (length) of the vector
    float magnitude() const { 
        return std::sqrt(x * x + y * y + z * z); 
    }

    // Normalize the vector to unit length
    Vec3 normalized() const { 
        return (*this) / magnitude(); 
    }
};

// Ray structure representing a ray in 3D space
struct Ray {
    Vec3 originPoint;
    Vec3 directionVector;

    // Constructor initializing origin and direction
    Ray(const Vec3& origin, const Vec3& direction) 
        : originPoint(origin), directionVector(direction) {}
};

// RGB color representation
struct Color {
    float red, green, blue;

    // Default constructor initializes to black
    Color() : red(0.0f), green(0.0f), blue(0.0f) {}

    // Parameterized constructor
    Color(float r, float g, float b) : red(r), green(g), blue(b) {}

    // Color addition
    Color operator+(const Color& other) const { 
        return Color(red + other.red, green + other.green, blue + other.blue); 
    }

    // Scalar multiplication
    Color operator*(float scalar) const { 
        return Color(red * scalar, green * scalar, blue * scalar); 
    }

    // Component-wise color multiplication
    Color operator*(const Color& other) const { 
        return Color(red * other.red, green * other.green, blue * other.blue); 
    }
};

