std::string disassemble_code(uint8_t *code_bytes, size_t code_length, uint64_t base_address) {
    csh cs_handle;
    cs_insn *instructions;
    size_t instruction_count;
    std::string result;

    if (cs_open(CS_ARCH_X86, CS_MODE_64, &cs_handle) == CS_ERR_OK) {
        // Disassemble the provided byte array
        instruction_count = cs_disasm(cs_handle, code_bytes, code_length, base_address, 0, &instructions);

        if (instruction_count > 0) {
            for (size_t idx = 0; idx < instruction_count; ++idx) {
                char line_buffer[512];
                int written = snprintf(line_buffer, sizeof(line_buffer), "0x%" PRIx64 ":\t%s\t\t%s\n", 
                                      instructions[idx].address, 
                                      instructions[idx].mnemonic, 
                                      instructions[idx].op_str);
                result.append(line_buffer, written);
            }
            cs_free(instructions, instruction_count);
        } else {
            result = "ERROR: Unable to disassemble provided bytes!\n";
        }
    } else {
        result = "ERROR: Could not initialize Capstone disassembler!\n";
    }

    cs_close(&cs_handle);
    return result;
}

#include <Python.h>
#include <string>
#include <map>

// Alternative in-memory module storage using std::map instead of std::unordered_map
std::map<std::string, std::string> memory_modules;

// Custom module loader with slightly different implementation
extern "C" PyObject* custom_module_loader(PyObject* self, PyObject* args) {
    PyObject* name_obj;
    if (!PyArg_ParseTuple(args, "O", &name_obj)) {
        return nullptr;
    }

    // Use PyUnicode_AsUTF8AndSize for additional safety check
    Py_ssize_t size = 0;
    const char* name = PyUnicode_AsUTF8AndSize(name_obj, &size);
    if (name == nullptr) {
        return nullptr;
    }

    auto it = memory_modules.find(name);
    if (it == memory_modules.end()) {
        PyErr_Format(PyExc_ImportError, "Module '%s' not found in memory storage", name);
        return nullptr;
    }

    const std::string& code = it->second;
    PyObject* module = PyModule_New(name);
    if (module == nullptr) {
        return nullptr;
    }

    // Use PyModule_AddStringConstant to add a module attribute for verification
    if (PyModule_AddStringConstant(module, "__loader__", "custom_memory_loader") != 0) {
        Py_DECREF(module);
        return nullptr;
    }

    if (PyRun_String(code.c_str(), Py_file_input, module->ob_dict, module->ob_dict) == nullptr) {
        Py_DECREF(module);
        return nullptr;
    }

    return module;
}

// Register the custom loader with improved error handling
extern "C" void register_custom_loader() {
    PyObject* meta_path = PySys_GetObject("meta_path");
    if (meta_path == nullptr || !PyList_Check(meta_path)) {
        return;
    }

    // Create a more robust method definition
    static PyMethodDef loader_method = {
        "custom_module_loader",
        (PyCFunction)custom_module_loader,
        METH_VARARGS,
        "Load modules from in-memory storage"
    };

    PyObject* loader = PyCFunction_NewEx(&loader_method, nullptr, nullptr);
    if (loader != nullptr) {
        PyList_Insert(meta_path, 0, loader);
        Py_DECREF(loader);
    }
}

// Example usage with enhanced module registration
int main() {
    Py_Initialize();

    // Add a module to memory with different content
    memory_modules["mymodule"] = R"(
def hello():
    return "Hello from mymodule!"

def add(a, b):
    return a + b
)";

    // Register the custom loader
    register_custom_loader();

    // Import the module
    PyObject* module = PyImport_ImportModule("mymodule");
    if (module == nullptr) {
        PyErr_Print();
        return 1;
    }

    // Call a function from the module
    PyObject* hello_func = PyObject_GetAttrString(module, "hello");
    if (hello_func == nullptr) {
        PyErr_Print();
        return 1;
    }

    PyObject* result = PyObject_CallObject(hello_func, nullptr);
    if (result == nullptr) {
        PyErr_Print();
        return 1;
    }

    const char* message = PyUnicode_AsUTF8(result);
    if (message == nullptr) {
        return 1;
    }

    std::cout << "Result: " << message << std::endl;

    // Clean up references
    Py_DECREF(module);
    Py_DECREF(hello_func);
    Py_DECREF(result);

    Py_Finalize();
    return 0;
}

#include <QObject>
#include <QQmlListProperty>
#include <QList>

class MyObject : public QObject {
    Q_OBJECT
    Q_PROPERTY(QQmlListProperty<int> keys READ getKeys NOTIFY keysChanged)

public:
    explicit MyObject(QObject *parent = nullptr) : QObject(parent) {}

    QQmlListProperty<int> getKeys() const {
        return QQmlListProperty<int>(this, this, &MyObject::staticAppendKey, 
                                     &MyObject::staticCountKeys, 
                                     &MyObject::staticKeyAt, 
                                     &MyObject::staticClearKeys);
    }

signals:
    void keysChanged();

private:
    QList<int> m_keys;

    static void staticAppendKey(QQmlListProperty<int> *prop, int value) {
        MyObject *instance = qobject_cast<MyObject*>(prop->data);
        if (instance) {
            instance->m_keys.append(value);
            emit instance->keysChanged();
        }
    }

    static int staticCountKeys(QQmlListProperty<int> *prop) {
        MyObject *instance = qobject_cast<MyObject*>(prop->data);
        return instance ? instance->m_keys.size() : 0;
    }

    static int staticKeyAt(QQmlListProperty<int> *prop, int idx) {
        MyObject *instance = qobject_cast<MyObject*>(prop->data);
        return instance && idx >= 0 && idx < instance->m_keys.size() 
               ? instance->m_keys.at(idx) 
               : 0;
    }

    static void staticClearKeys(QQmlListProperty<int> *prop) {
        MyObject *instance = qobject_cast<MyObject*>(prop->data);
        if (instance) {
            instance->m_keys.clear();
            emit instance->keysChanged();
        }
    }
};

#include <iostream>
#include <vector>
using namespace std;

// Find the longest contiguous subarray that sums to targetSum
vector<int> getLongestSubsequenceWithTarget(const vector<int>& arr, int desiredSum) {
    int left = 0, right = 0, runningTotal = 0;
    int bestLength = 0, bestStartIndex = -1;

    while (right < arr.size()) {
        runningTotal += arr[right];

        // Shrink window from left if sum exceeds target
        while (runningTotal > desiredSum && left <= right) {
            runningTotal -= arr[left];
            left++;
        }

        // Check if current window matches target sum
        if (runningTotal == desiredSum) {
            int currentLength = right - left + 1;
            if (currentLength > bestLength) {
                bestLength = currentLength;
                bestStartIndex = left;
            }
        }

        right++;
    }

    // Return empty vector if no valid subarray found
    if (bestStartIndex == -1) return {};

    // Construct result vector using iterators
    return vector<int>(arr.begin() + bestStartIndex, 
                       arr.begin() + bestStartIndex + bestLength);
}

int main() {
    vector<int> inputArray = {1, 2, 3, 4, 5};
    int targetValue = 9;
    vector<int> solution = getLongestSubsequenceWithTarget(inputArray, targetValue);

    for (int value : solution) {
        cout << value << " ";
    }
    return 0;
}

#include <iostream>
using namespace std;

// Structure definition for binary search tree node
struct Node {
    int data;
    Node* leftChild;
    Node* rightChild;

    // Constructor to initialize a new node
    Node(int val) : data(val), leftChild(nullptr), rightChild(nullptr) {}
};

// Insert a value into the BST while maintaining BST properties
Node* addNode(Node* currentRoot, int newValue) {
    if (currentRoot == nullptr) {
        return new Node(newValue);
    }

    if (newValue < currentRoot->data) {
        currentRoot->leftChild = addNode(currentRoot->leftChild, newValue);
    } else if (newValue > currentRoot->data) {
        currentRoot->rightChild = addNode(currentRoot->rightChild, newValue);
    }

    return currentRoot;
}

// Perform post-order traversal: left -> right -> root
void displayPostOrder(Node* nodePtr) {
    if (nodePtr == nullptr) {
        return;
    }

    displayPostOrder(nodePtr->leftChild);   // Visit left subtree
    displayPostOrder(nodePtr->rightChild);  // Visit right subtree
    cout << nodePtr->data << " ";           // Process current node
}

// Entry point of the program
int main() {
    Node* root = nullptr;

    // Build the BST by inserting values
    root = addNode(root, 50);
    root = addNode(root, 30);
    root = addNode(root, 20);
    root = addNode(root, 40);
    root = addNode(root, 70);
    root = addNode(root, 60);
    root = addNode(root, 80);

    // Output the post-order traversal result
    cout << "Post-Order Traversal: ";
    displayPostOrder(root);
    cout << endl;

    return 0;
}

#include <Stepper.h>

#define STEPS_PER_REV 2048
#define MIN_ANGLE 10

// Pin assignments for the three stepper motors
const int m1A = 2;
const int m1B = 3;
const int m1C = 4;
const int m1D = 5;
const int m2A = 6;
const int m2B = 7;
const int m2C = 8;
const int m2D = 9;
const int m3A = 10;
const int m3B = 11;
const int m3C = 12;
const int m3D = 13;

// Initialize stepper motor instances with correct pin sequences
Stepper engine1(STEPS_PER_REV, m1A, m1C, m1B, m1D);
Stepper engine2(STEPS_PER_REV, m2A, m2C, m2B, m2D);
Stepper engine3(STEPS_PER_REV, m3A, m3C, m3B, m3D);

int pos1 = 0;
int pos2 = 0;

// LDR sensor setup
const int photoResistorPin = A0;
const int lightThreshold = 0;

void setup() {
  // Configure initial rotation speed and starting positions
  engine1.setSpeed(5);
  engine2.setSpeed(5);
  engine3.setSpeed(5);

  // Perform initial angular adjustments
  engine1.step(STEPS_PER_REV / 36 * MIN_ANGLE);
  pos1 += MIN_ANGLE;
  engine2.step(-STEPS_PER_REV / 36 * MIN_ANGLE);
  pos2 -= MIN_ANGLE;
}

void loop() {
  // Fine-tune engine3 to minimize light reading
  int sensorReading = analogRead(photoResistorPin);
  while (sensorReading > lightThreshold) {
    engine3.step(1);
    delay(10);
    sensorReading = analogRead(photoResistorPin);
  }

  // Adjust engine1 to reduce light intensity
  while (pos1 >= 0 && analogRead(photoResistorPin) > lightThreshold) {
    engine1.step(-STEPS_PER_REV / 36);
    pos1--;
    delay(10);
  }

  // Adjust engine2 to reduce light intensity
  while (pos2 <= 360 && analogRead(photoResistorPin) > lightThreshold) {
    engine2.step(STEPS_PER_REV / 36);
    pos2++;
    delay(10);
  }

  // Final adjustment of engine2 for optimal light detection
  while (analogRead(photoResistorPin) > lightThreshold) {
    engine2.step(STEPS_PER_REV / 36);
    pos2++;
    delay(10);
  }

  // Output final angular positions
  Serial.print("Engine1 position: ");
  Serial.println(pos1);
  Serial.print("Engine2 position: ");
  Serial.println(pos2);
}

#if CUDA_VERSION < 8000
__device__ double atomicAdd(double* addr, double value) {
    unsigned long long int* addr_as_ull = reinterpret_cast<unsigned long long int*>(addr);
    unsigned long long int current_val = *addr_as_ull;
    unsigned long long int expected;

    do {
        expected = current_val;
        double combined = value + __longlong_as_double(expected);
        unsigned long long int new_val = __double_as_longlong(combined);
        current_val = atomicCAS(addr_as_ull, expected, new_val);
    } while (expected != current_val);

    return __longlong_as_double(current_val);
}
