#include <vector>
#include <thread>
#include <algorithm>
#include <mutex>
#include <future>

std::mutex print_mutex; // Mutex for thread-safe output operations

// Partition and sort function using Hoare-like partitioning scheme
void efficient_sort(std::vector<int>& data, int start, int end) {
    if (start >= end) return;

    int mid = start + (end - start) / 2;
    int pivot_value = data[mid];
    int low = start;
    int high = end;

    while (low <= high) {
        while (data[low] < pivot_value) ++low;
        while (data[high] > pivot_value) --high;

        if (low <= high) {
            std::swap(data[low], data[high]);
            ++low;
            --high;
        }
    }

    // Recursively sort partitions
    if (start < high) efficient_sort(data, start, high);
    if (low < end) efficient_sort(data, low, end);
}

// Parallel version with threshold-based switching to sequential sorting
void concurrent_sort(std::vector<int>& dataset, int begin, int finish, int cutoff) {
    if (finish - begin <= cutoff) {
        efficient_sort(dataset, begin, finish);
    } else {
        int middle_point = begin + (finish - begin) / 2;
        int pivot_val = dataset[middle_point];
        int left_idx = begin;
        int right_idx = finish;

        while (left_idx <= right_idx) {
            while (dataset[left_idx] < pivot_val) ++left_idx;
            while (dataset[right_idx] > pivot_val) --right_idx;

            if (left_idx <= right_idx) {
                std::swap(dataset[left_idx], dataset[right_idx]);
                ++left_idx;
                --right_idx;
            }
        }

        std::future<void> left_task;
        std::future<void> right_task;

        if (begin < right_idx) {
            left_task = std::async(std::launch::async, 
                                   concurrent_sort, 
                                   std::ref(dataset), 
                                   begin, 
                                   right_idx, 
                                   cutoff);
        }

        if (left_idx < finish) {
            right_task = std::async(std::launch::async, 
                                    concurrent_sort, 
                                    std::ref(dataset), 
                                    left_idx, 
                                    finish, 
                                    cutoff);
        }

        if (left_task.valid()) left_task.get();
        if (right_task.valid()) right_task.get();
    }
}

int main() {
    std::vector<int> numbers = {3, 6, 8, 10, 1, 2, 1};
    int cutoff_threshold = 10;

    {
        std::lock_guard<std::mutex> lock(print_mutex);
        std::cout << "Original array: ";
        for (int value : numbers) {
            std::cout << value << " ";
        }
        std::cout << std::endl;
    }

    concurrent_sort(numbers, 0, static_cast<int>(numbers.size()) - 1, cutoff_threshold);

    {
        std::lock_guard<std::mutex> lock(print_mutex);
        std::cout << "Sorted array: ";
        for (int value : numbers) {
            std::cout << value << " ";
        }
        std::cout << std::endl;
    }

    return 0;
}

