// Helper function to invoke a static Java method returning a String
jstring invokeStaticStringMethod(JNIEnv* env, const QAndroidJniObject& javaClass, const char* methodName, const char* methodSig, va_list args) {
    jclass clazz = javaClass.object<jclass>();
    jmethodID methodId = env->GetStaticMethodID(clazz, methodName, methodSig);
    jstring result = static_cast<jstring>(env->CallStaticObjectMethodV(clazz, methodId, args));
    return result;
}

// Wrapper that handles argument packing and converts JNI result to QString
QString callStaticJavaString(const QAndroidJniObject& javaClass, const char* methodName, const char* signature, ...) {
    JNIEnv* jniEnv = QAndroidJniEnvironment::javaEnv();

    va_list arguments;
    va_start(arguments, signature);
    jstring jniResult = invokeStaticStringMethod(jniEnv, javaClass, methodName, signature, arguments);
    va_end(arguments);

    return QAndroidJniObject(jniResult).toString();
}

