#include <iostream>
#include <map>
#include <sstream>
#include <string>

// Parse a Python-style dictionary string into a C++ map
std::map<std::string, std::string> extractDictEntries(const std::string &inputStr) {
    std::map<std::string, std::string> result;

    // Locate the braces that enclose the dictionary
    size_t leftBrace = inputStr.find('{');
    size_t rightBrace = inputStr.rfind('}');

    // Extract content between braces
    std::string innerContent = inputStr.substr(leftBrace + 1, rightBrace - leftBrace - 1);

    // Split by commas to get individual key-value pairs
    std::istringstream stream(innerContent);
    std::string pair;

    while (std::getline(stream, pair, ',')) {
        // Find the colon separator
        size_t colonIndex = pair.find(':');

        // Extract and clean up the key
        std::string rawKey = pair.substr(0, colonIndex);
        size_t keyStart = rawKey.find_first_not_of(" '\"");
        size_t keyEnd = rawKey.find_last_not_of(" '\"");
        std::string cleanedKey = (keyStart != std::string::npos) ? 
                                 rawKey.substr(keyStart, keyEnd - keyStart + 1) : "";

        // Extract and clean up the value
        std::string rawValue = pair.substr(colonIndex + 1);
        size_t valStart = rawValue.find_first_not_of(" '\"");
        size_t valEnd = rawValue.find_last_not_of(" '\"");
        std::string cleanedValue = (valStart != std::string::npos) ? 
                                   rawValue.substr(valStart, valEnd - valStart + 1) : "";

        // Insert into map if both key and value are non-empty
        if (!cleanedKey.empty() && !cleanedValue.empty()) {
            result[cleanedKey] = cleanedValue;
        }
    }

    return result;
}

int main() {
    std::string pythonStyleDict = "{'item1': 1, 'item2': 2.0, 'item3': 'a string', 'item4': 'another string'}";

    std::map<std::string, std::string> dictMap = extractDictEntries(pythonStyleDict);

    // Output each key-value pair
    for (const auto &entry : dictMap) {
        std::cout << entry.first << ": " << entry.second << std::endl;
    }

    return 0;
}

#include <iostream>
#include <unordered_set>

// Node structure for XOR linked list
struct Node {
    int data;
    Node* diff; // Stores XOR of previous and next node addresses

    Node(int val) : data(val), diff(nullptr) {}
};

class XorList {
private:
    Node* start;
    Node* end;

public:
    XorList() : start(nullptr), end(nullptr) {}

    // Helper function to compute XOR of two node pointers
    Node* computeXor(Node* a, Node* b) {
        return reinterpret_cast<Node*>(reinterpret_cast<uintptr_t>(a) ^ reinterpret_cast<uintptr_t>(b));
    }

    // Insert element at the end of the list
    void pushBack(int value) {
        Node* newNode = new Node(value);
        if (!start) {
            start = end = newNode;
            return;
        }

        Node* last = end;
        Node* prevNode = computeXor(end->diff, nullptr); // Since end->next is nullptr
        end->diff = computeXor(newNode, prevNode);
        newNode->diff = computeXor(last, nullptr);
        end = newNode;
    }

    // Reverse the XOR linked list in-place
    void invert() {
        Node* current = start;
        Node* previous = nullptr;
        Node* future = nullptr;

        while (current) {
            future = computeXor(previous, current->diff);
            current->diff = computeXor(future, previous);
            previous = current;
            current = future;
        }

        // Swap start and end pointers
        Node* temp = start;
        start = end;
        end = temp;
    }

    // Print all elements in forward order
    void display() {
        Node* current = start;
        Node* previous = nullptr;
        Node* nextNode;

        while (current) {
            std::cout << current->data << " ";
            nextNode = computeXor(previous, current->diff);
            previous = current;
            current = nextNode;
        }
        std::cout << std::endl;
    }
};

int main() {
    XorList list;
    list.pushBack(1);
    list.pushBack(2);
    list.pushBack(3);

    list.display(); // Output: 1 2 3

    list.invert();
    list.display(); // Output: 3 2 1

    return 0;
}

#include <opencv2/opencv.hpp>
#include <iostream>

int main() {
    // Load the input image in grayscale mode
    cv::Mat sourceImage = cv::imread("input.png", cv::IMREAD_GRAYSCALE);

    if (sourceImage.empty()) {
        std::cerr << "Error: Could not load image 'input.png'" << std::endl;
        return -1;
    }

    // Define corresponding points for affine transformation
    cv::Point2f sourcePoints[3];
    cv::Point2f targetPoints[3];

    // Set up source triangle vertices
    sourcePoints[0] = cv::Point2f(0.0f, 0.0f);
    sourcePoints[1] = cv::Point2f(static_cast<float>(sourceImage.cols - 1), 0.0f);
    sourcePoints[2] = cv::Point2f(0.0f, static_cast<float>(sourceImage.rows - 1));

    // Set up destination triangle vertices (scaled by factor of 2)
    targetPoints[0] = cv::Point2f(0.0f, 0.0f);
    targetPoints[1] = cv::Point2f(static_cast<float>((sourceImage.cols * 2) - 1), 0.0f);
    targetPoints[2] = cv::Point2f(0.0f, static_cast<float>((sourceImage.rows * 2) - 1));

    // Compute the affine transformation matrix
    cv::Mat transformMatrix = cv::getAffineTransform(sourcePoints, targetPoints);

    // Prepare output image with doubled dimensions
    cv::Mat transformedImage;
    cv::Size newSize(sourceImage.cols * 2, sourceImage.rows * 2);

    // Apply the affine warp using cubic interpolation
    cv::warpAffine(sourceImage, transformedImage, transformMatrix, newSize, cv::INTER_CUBIC);

    // Write the result to file
    cv::imwrite("output.png", transformedImage);

    return 0;
}

