// Function to determine if a number is prime using an alternative approach
bool checkPrime(int value) {
    // Handle edge cases for numbers less than or equal to 1
    if (value <= 1) {
        return false;
    }

    // Special case for 2 and 3
    if (value <= 3) {
        return true;
    }

    // Eliminate multiples of 2 and 3
    if (value % 2 == 0 || value % 3 == 0) {
        return false;
    }

    // Check for factors using the 6k ± 1 optimization
    int limit = static_cast<int>(std::sqrt(value));
    int divisor = 5;
    while (divisor <= limit) {
        if (value % divisor == 0 || value % (divisor + 2) == 0) {
            return false;
        }
        divisor += 6;
    }

    return true;
}

// Function to display all prime numbers in a given range
void showPrimesInRange(int lowerBound, int upperBound) {
    for (int current = lowerBound; current <= upperBound; ++current) {
        if (checkPrime(current)) {
            std::cout << current << " ";
        }
    }
    std::cout << std::endl;
}

