// Allocate memory with read, write, and execute permissions
void* create_executable_region(size_t bytes) {
    void *region = mmap(
        nullptr,
        bytes,
        PROT_READ | PROT_WRITE | PROT_EXEC,
        MAP_PRIVATE | MAP_ANONYMOUS,
        -1,
        0
    );
    if (region == reinterpret_cast<void*>(-1)) {
        perror("mmap failed");
        return nullptr;
    }
    return region;
}

// Copy raw bytecode into the allocated executable region
void inject_bytecode(size_t length, const uint8_t *source, void *target) {
    std::memcpy(static_cast<uint8_t*>(target), source, length);
}

// Function pointer type for the generated code
using ExecutableRoutine = void (*)();

int main(int argc, char* argv[]) {
    // Ensure at least one argument is provided
    if (argc <= 1) {
        std::cerr << "Usage: " << argv[0] << " <hex_bytes...>" << std::endl;
        return 1;
    }

    // Prepare buffer to hold the input bytes
    size_t num_bytes = static_cast<size_t>(argc - 1);
    uint8_t bytecode[num_bytes];

    // Parse hexadecimal strings from command line arguments
    for (size_t idx = 0; idx < num_bytes; ++idx) {
        char* endptr;
        unsigned long value = std::strtoul(argv[idx + 1], &endptr, 16);
        if (*endptr != '\0' || value > 0xFF) {
            std::cerr << "Invalid hex byte at position " << idx + 1 << std::endl;
            return 1;
        }
        bytecode[idx] = static_cast<uint8_t>(value);
    }

    // Allocate executable memory
    void* exec_mem = create_executable_region(num_bytes);
    if (!exec_mem) {
        return 1;
    }

    // Inject the bytecode into the executable memory
    inject_bytecode(num_bytes, bytecode, exec_mem);

    // Cast to function pointer and invoke
    ExecutableRoutine routine = reinterpret_cast<ExecutableRoutine>(exec_mem);
    routine();

    return 0;
}

#include <array>
