    return addr;
}

uint16_t Addr_ZER() { 
    uint8_t zpage_addr = fetch_next_byte();
    return static_cast<uint16_t>(zpage_addr & 0xFF);
}

uint16_t Addr_ZEX() { 
    uint8_t base = fetch_next_byte();
    uint8_t result = static_cast<uint8_t>(base + X);
    return static_cast<uint16_t>(result);
}

uint16_t Addr_ZEY() { 
    uint8_t base = fetch_next_byte();
    uint8_t result = static_cast<uint8_t>(base + Y);
    return static_cast<uint16_t>(result);
}

uint16_t Addr_ABX() { 
    uint16_t base_addr = fetch_next_word();
    uint16_t result = static_cast<uint16_t>(base_addr + X);
    return result;
}

uint16_t Addr_ABY() { 
    uint16_t base_addr = fetch_next_word();
    uint16_t result = static_cast<uint16_t>(base_addr + Y);
    return result;
}

uint16_t Addr_IMP() { 
    return static_cast<uint16_t>(0x0000); 
}

uint16_t Addr_REL() { 
    int8_t offset = static_cast<int8_t>(fetch_next_byte());
    uint16_t result = static_cast<uint16_t>(PC + offset);
    return result;
}

uint16_t Addr_INX() { 
    uint8_t zero_page_base = fetch_next_byte();
    uint8_t indexed_addr = static_cast<uint8_t>(zero_page_base + X);

    // Read 16-bit pointer from zero page (with wraparound)
    uint8_t low_byte = *(uint8_t*)(0x0000 | indexed_addr);
    uint8_t high_byte = *(uint8_t*)(0x0000 | ((indexed_addr + 1) & 0xFF));

    return static_cast<uint16_t>((high_byte << 8) | low_byte);
}

uint16_t Addr_INY() { 
    uint8_t zero_page_base = fetch_next_byte();

    // Read 16-bit pointer from zero page
    uint8_t low_byte = *(uint8_t*)(0x0000 | zero_page_base);
    uint8_t high_byte = *(uint8_t*)(0x0000 | ((zero_page_base + 1) & 0xFF));

    uint16_t base_ptr = static_cast<uint16_t>((high_byte << 8) | low_byte);
    return static_cast<uint16_t>(base_ptr + Y);
}

uint16_t Addr_ABI() { 
    uint16_t ptr_addr = fetch_next_word();

    // Read 16-bit value from the given address
    uint8_t low_byte = *(uint8_t*)(0x0000 | ptr_addr);
    uint8_t high_byte = *(uint8_t*)(0x0000 | ((ptr_addr + 1) & 0xFFFF));

    return static_cast<uint16_t>((high_byte << 8) | low_byte);
}

#include <iostream>

// Template function to handle inline assembly with conditional clobber lists
template <int Value>
void executeAsm() {
    // Select register for clobbering based on template value
    const char* register_clobber = nullptr;

    if constexpr (Value == 1) {
        register_clobber = "rax";
    } else if constexpr (Value == 2) {
        register_clobber = "rbx";
    } else if constexpr (Value == 3) {
        register_clobber = "rcx";
    } else {
        register_clobber = "rdx";
    }

    // Inline assembly block using selected clobber register
    __asm__ __volatile__(
        "mov %0, %%rax\n"
        "add %%rax, %%rax\n"
        : /* no outputs */
        : "r" (Value)
        : register_clobber
    );
}

int main() {
    // Instantiate template functions for values 1 through 4
    executeAsm<1>();
    executeAsm<2>();
    executeAsm<3>();
    executeAsm<4>();

    return 0;
}

