// Helper class for automatic JNI local reference cleanup
class JniLocalRefGuard {
    JNIEnv* env_;
    jobject ref_;
public:
    JniLocalRefGuard(JNIEnv* env, jobject ref) : env_(env), ref_(ref) {}
    ~JniLocalRefGuard() {
        if (ref_ != nullptr && env_ != nullptr) {
            env_->DeleteLocalRef(ref_);
