    m_pSocket = zsock_new_sub(endpoint.c_str(), "");

    zmq_pollitem_t pollItem = { zsock_handle(m_pSocket), 0, ZMQ_POLLIN, 0 };
    int result = zmq_poll(&pollItem, 1, 1000); // Timeout after 1 second

    if (result < 0)
    {
        int errCode = zmq_errno();
        fprintf(stderr, "zmq_poll error: %s\n", zmq_strerror(errCode));
        return false;
    }

    if (result == 0)
    {
        fprintf(stderr, "Connection attempt timed out for endpoint: %s\n", endpoint.c_str());
        return false;
    }

    return true;
}

