#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64
#define OLED_RESET -1
#define SCREEN_ADDR 0x3C
#define WIFI_CHANNEL 1
#define MAX_BUFFER 1024

Adafruit_SSD1306 oled(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, OLED_RESET);

void handleIncomingData(const uint8_t *senderMac, const uint8_t *payload, size_t length);

uint8_t ringBuffer[MAX_BUFFER];
size_t writeIndex = 0;
size_t readIndex = 0;
size_t pendingBytes = 0;

void initializeESPNow() {
  WiFi.disconnect();
  if (esp_now_init() == ESP_OK) {
    Serial.println("ESP-NOW initialized successfully");
  } else {
    Serial.println("ESP-NOW initialization failed");
    ESP.restart();
  }
}

void setupAccessPoint() {
  const char apSSID[] = "Slave_1";
  if (!WiFi.softAP(apSSID, "Slave_1_Password", WIFI_CHANNEL, 0)) {
    Serial.println("Failed to configure Access Point");
    ESP.restart();
  } else {
    Serial.print("Access Point configured: ");
    Serial.println(apSSID);
    Serial.print("Channel: ");
    Serial.println(WiFi.channel());
  }
}

void setup() {
  Serial.begin(115200);
  WiFi.mode(WIFI_AP);
  setupAccessPoint();
  initializeESPNow();
  esp_now_register_recv_cb(handleIncomingData);

  if (!oled.begin(SSD1306_SWITCHCAPVCC, SCREEN_ADDR)) {
    Serial.println(F("OLED display initialization failed"));
    for (;;); // Halt execution
  }
  oled.clearDisplay();
}

void handleIncomingData(const uint8_t *senderMac, const uint8_t *payload, size_t length) {
  char macAddress[18];
  sprintf(macAddress, "%02x:%02x:%02x:%02x:%02x:%02x",
          senderMac[0], senderMac[1], senderMac[2], senderMac[3], senderMac[4], senderMac[5]);

  Serial.print("Received from device: ");
  Serial.println(macAddress);
  Serial.println();

  for (size_t idx = 0; idx < length; ++idx) {
    writeIndex = (writeIndex + 1) % MAX_BUFFER;
    ringBuffer[writeIndex] = payload[idx];

    if (writeIndex == readIndex) {
      readIndex = (readIndex + 1) % MAX_BUFFER;
    }

    pendingBytes++;
  }

  Serial.println("Contents of receive buffer:");
  for (size_t i = 0; i < pendingBytes; ++i) {
    Serial.print(ringBuffer[i], HEX);
    Serial.print(" ");
    if ((i + 1) % 16 == 0) {
      Serial.println();
    }
  }

  Wire.beginTransmission(SCREEN_ADDR);
  for (size_t j = 0; j < pendingBytes; ++j) {
    Wire.write(ringBuffer[j]);
  }
  Wire.endTransmission();

  pendingBytes = 0;
}

