namespace py = pybind11;

// Base class for inheritance hierarchy
struct BaseClass { };

// Derived class inheriting from BaseClass
struct DerivedClass : public BaseClass { };

// Container that accepts shared pointers to BaseClass
struct Storage {
    void add(const std::shared_ptr<BaseClass>& obj) { }
};

PYBIND11_MODULE(PybindTestModule, mod) {
    // Bind BaseClass with shared_ptr support
    py::class_<BaseClass, std::shared_ptr<BaseClass>>(mod, "BaseClass")
        .def(py::init<>());

    // Bind DerivedClass, inheriting from BaseClass
    py::class_<DerivedClass, std::shared_ptr<DerivedClass>, BaseClass>(mod, "DerivedClass")
        .def(py::init<>());

    // Bind Storage class with shared_ptr support
    py::class_<Storage, std::shared_ptr<Storage>>(mod, "Storage")
        .def(py::init<>())
        // Original method: accepts shared_ptr<BaseClass>
        .def("add", &Storage::add)
        // Overloaded method: accepts shared_ptr<DerivedClass> and casts it internally
        .def("add", [](Storage& container, const std::shared_ptr<DerivedClass>& obj) {
            container.add(obj);  // Implicit upcast to shared_ptr<BaseClass>
        });
}

void Menu::item::winAppendMenu(HMENU menuHandle) {
    // Local buffer for wide string conversion
    wchar_t* tempBuffer = nullptr;

    // Handle different menu item types
    switch (type) {
        case separator_type_id:
            AppendMenu(menuHandle, MF_SEPARATOR, 0, nullptr);
            break;

        case vseparator_type_id:
            AppendMenu(menuHandle, MF_MENUBREAK, 0, nullptr);
            break;

        case submenu_type_id:
            if (nullptr != winMenu) {
                // Convert menu text to wide string
                LPWSTR textStr = getWString(winConstructMenuText(), L"", (const wchar_t*&)tempBuffer);

                if (L'\0' != textStr[0]) {
                    AppendMenuW(menuHandle, MF_POPUP | MF_STRING, (uintptr_t)winMenu, textStr);
                } else {
                    AppendMenu(menuHandle, MF_POPUP | MF_STRING, (uintptr_t)winMenu, winConstructMenuText().c_str());
                }
            }
            break;

        case item_type_id:
            // Build menu attributes based on status
            unsigned int flags = MF_STRING;

            if (status.checked) {
                flags |= MF_CHECKED;
            } else {
                flags |= MF_UNCHECKED;
            }

            if (status.enabled) {
                flags |= MF_ENABLED;
            } else {
                flags |= (MF_DISABLED | MF_GRAYED);
            }

            // Process menu text and append item
            LPWSTR itemText = getWString(winConstructMenuText(), L"", (const wchar_t*&)tempBuffer);

            if (L'\0' != itemText[0]) {
                AppendMenuW(menuHandle, flags, (uintptr_t)(master_id + winMenuMinimumID), itemText);
            } else {
                AppendMenu(menuHandle, flags, (uintptr_t)(master_id + winMenuMinimumID), winConstructMenuText().c_str());
            }
            break;

        default:
            // Unknown type - do nothing
            break;
    }

    // Clean up allocated buffer
    if (nullptr != tempBuffer) {
        delete[] tempBuffer;
        tempBuffer = nullptr;
    }
}

