using namespace std;

// Function to locate the longest repeated substring pattern
string locateMaxDuplicate(const string &text) {
    int length = text.length();
    string bestMatch = "";

    // Try all possible substring lengths from largest to smallest
    for (int subLen = length / 2; subLen > 0; --subLen) {
        for (int startIdx = 0; startIdx <= length - subLen; ++startIdx) {
            string candidate = text.substr(startIdx, subLen);

            // Check if this substring appears again later in the text
            size_t nextOccurrence = text.find(candidate, startIdx + subLen);
            if (nextOccurrence != string::npos) {
                if (candidate.length() > bestMatch.length()) {
                    bestMatch = candidate;
                }
            }
        }
    }
    return bestMatch;
}

// Function to apply compression using repeated patterns
string applyCompression(const string &input) {
    string current = input;

    while (true) {
        string pattern = locateMaxDuplicate(current);
        if (pattern.empty()) break;

        // Count how many times the pattern appears
        int occurrences = 0;
        size_t searchPos = 0;
        while ((searchPos = current.find(pattern, searchPos)) != string::npos) {
            occurrences++;
            searchPos += pattern.length();
        }

        // Only compress if it appears more than once
        if (occurrences > 1) {
            string marker = "[" + pattern + "]" + to_string(occurrences);
            size_t firstPos = current.find(pattern);
            current = current.substr(0, firstPos) + marker + current.substr(firstPos + pattern.length());
        } else {
            break;
        }
    }
    return current;
}

// Function to handle file processing with pattern detection
void handleFileProcessing(const string &sourcePath, const string &targetPath) {
    ifstream source(sourcePath);
    ofstream target(targetPath);

    if (!source.is_open() || !target.is_open()) {
        cerr << "Failed to open required files." << endl;
        return;
    }

    string currentLine;
    while (getline(source, currentLine)) {
        // Check for specific pattern in line
        if (currentLine.find("d+c+d+f+d+c+d+f+d+c+d+f+d+c+d+f+") != string::npos) {
            string processed = applyCompression(currentLine);
            target << processed << "\n";
        } else {
            target << currentLine << "\n";
        }
    }

    source.close();
    target.close();
}

int main() {
    string sourceFile = "input.txt";
    string destinationFile = "output.txt";
    handleFileProcessing(sourceFile, destinationFile);
    return 0;
}

