#include <iostream>
using namespace std;

// Binary Search Tree Node definition
struct TreeNode {
    int value;
    TreeNode* leftChild;
    TreeNode* rightChild;

    TreeNode(int v) : value(v), leftChild(nullptr), rightChild(nullptr) {}
};

// BST implementation with different traversal and deletion logic
class BinarySearchTree {
public:
    TreeNode* head; // root node reference

    BinarySearchTree() : head(nullptr) {}

    // Insert a new key into the tree
    void addValue(int val) {
        head = insertIntoTree(head, val);
    }

    // Remove a key from the tree
    void removeValue(int val) {
        head = removeFromTree(head, val);
    }

    // Display in-order traversal (left-root-right)
    void showInOrder() {
        traverseInOrder(head);
        cout << endl;
    }

    // Display pre-order traversal (root-left-right)
    void showPreOrder() {
        traversePreOrder(head);
        cout << endl;
    }

    // Display post-order traversal (left-right-root)
    void showPostOrder() {
        traversePostOrder(head);
        cout << endl;
    }

private:
    // Recursive helper to insert a value
    TreeNode* insertIntoTree(TreeNode* node, int val) {
        if (node == nullptr) {
            return new TreeNode(val);
        }

        if (val < node->value) {
            node->leftChild = insertIntoTree(node->leftChild, val);
        } else if (val > node->value) {
            node->rightChild = insertIntoTree(node->rightChild, val);
        }
        return node;
    }

    // Find the minimum value node in a subtree
    TreeNode* findMinNode(TreeNode* node) {
        TreeNode* curr = node;
        while (curr && curr->leftChild != nullptr) {
            curr = curr->leftChild;
        }
        return curr;
    }

    // Recursive helper to delete a value
    TreeNode* removeFromTree(TreeNode* node, int val) {
        if (node == nullptr) {
            return nullptr;
        }

        if (val < node->value) {
            node->leftChild = removeFromTree(node->leftChild, val);
        } else if (val > node->value) {
            node->rightChild = removeFromTree(node->rightChild, val);
        } else {
            // Node found - handle deletion cases

            // Case 1: No left child
            if (node->leftChild == nullptr) {
                TreeNode* temp = node->rightChild;
                delete node;
                return temp;
            }

            // Case 2: No right child
            if (node->rightChild == nullptr) {
                TreeNode* temp = node->leftChild;
                delete node;
                return temp;
            }

            // Case 3: Two children - replace with inorder successor
            TreeNode* successor = findMinNode(node->rightChild);
            node->value = successor->value;
            node->rightChild = removeFromTree(node->rightChild, successor->value);
        }
        return node;
    }

    // In-order traversal helper (left -> root -> right)
    void traverseInOrder(TreeNode* node) {
        if (node != nullptr) {
            traverseInOrder(node->leftChild);
            cout << node->value << " ";
            traverseInOrder(node->rightChild);
        }
    }

    // Pre-order traversal helper (root -> left -> right)
    void traversePreOrder(TreeNode* node) {
        if (node != nullptr) {
            cout << node->value << " ";
            traversePreOrder(node->leftChild);
            traversePreOrder(node->rightChild);
        }
    }

    // Post-order traversal helper (left -> right -> root)
    void traversePostOrder(TreeNode* node) {
        if (node != nullptr) {
            traversePostOrder(node->leftChild);
            traversePostOrder(node->rightChild);
            cout << node->value << " ";
        }
    }
};

int main() {
    BinarySearchTree bst;

    // Build the tree with sample values
    bst.addValue(50);
    bst.addValue(30);
    bst.addValue(20);
    bst.addValue(40);
    bst.addValue(70);
    bst.addValue(60);
    bst.addValue(80);

    // Show traversals before deletion
    cout << "Inorder traversal: ";
    bst.showInOrder();

    cout << "Preorder traversal: ";
    bst.showPreOrder();

    cout << "Postorder traversal: ";
    bst.showPostOrder();

    // Delete nodes and show resulting traversals
    cout << "Delete 20: ";
    bst.removeValue(20);
    bst.showInOrder();

    cout << "Delete 30: ";
    bst.removeValue(30);
    bst.showInOrder();

    cout << "Delete 50: ";
    bst.removeValue(50);
    bst.showInOrder();

    return 0;
}

#include <iostream>
