using namespace std;

// Structure to hold price information for a card
struct PriceRecord {
    float unitPrice;
    string recordDate;
    int setNumber;
    int conditionLevel;
};

// Structure representing a single card entry
struct CardRecord {
    string cardTitle;
    size_t priceCount;
    size_t groupSize;
    vector<PriceRecord> priceHistory;
    float alertThreshold;
    int isFavorite;
};

// Global container for all cards
vector<CardRecord> cardCollection;

// Populate the card collection with sample data
void InitializeCards() {
    int index = 0;
    int subIndex = 0;
    char buffer[64] = {0};

    for (index = 0; index < 3; ++index) {
        CardRecord newCard;

        // Set card name using sprintf
        snprintf(buffer, sizeof(buffer), "Card Name: %d", index);
        newCard.cardTitle = buffer;

        // Initialize default values
        newCard.alertThreshold = 1.00f;
        newCard.groupSize = 0;
        newCard.isFavorite = 1;

        // Add price history entries
        for (subIndex = 0; subIndex < 3; ++subIndex) {
            PriceRecord priceInfo;
            priceInfo.unitPrice = static_cast<float>(subIndex + 1);
            priceInfo.setNumber = subIndex;
            priceInfo.conditionLevel = subIndex - 1;

            snprintf(buffer, sizeof(buffer), "Entry %d", subIndex);
            priceInfo.recordDate = buffer;

            newCard.priceHistory.push_back(priceInfo);
        }

        // Store the count of price records
        newCard.priceCount = newCard.priceHistory.size();
        cardCollection.push_back(newCard);
    }
}

// Convert price records into a binary format for storage
void PackPriceRecords(const vector<PriceRecord>& records, vector<unsigned char>& outputBuffer) {
    for (const auto& record : records) {
        // Serialize floating point price
        memcpy(&outputBuffer[outputBuffer.size()], &record.unitPrice, sizeof(record.unitPrice));
        outputBuffer.resize(outputBuffer.size() + sizeof(record.unitPrice));

        // Serialize date string length and content
        size_t dateStringLength = record.recordDate.length();
        memcpy(&outputBuffer[outputBuffer.size()], &dateStringLength, sizeof(dateStringLength));
        outputBuffer.resize(outputBuffer.size() + sizeof(dateStringLength));

        memcpy(&outputBuffer[outputBuffer.size()], record.recordDate.c_str(), dateStringLength);
        outputBuffer.resize(outputBuffer.size() + dateStringLength);

        // Serialize integer fields
        memcpy(&outputBuffer[outputBuffer.size()], &record.setNumber, sizeof(record.setNumber));
        outputBuffer.resize(outputBuffer.size() + sizeof(record.setNumber));

        memcpy(&outputBuffer[outputBuffer.size()], &record.conditionLevel, sizeof(record.conditionLevel));
        outputBuffer.resize(outputBuffer.size() + sizeof(record.conditionLevel));
    }
}

// Reconstruct price records from binary data
void UnpackPriceRecords(const unsigned char* data, size_t dataSize, vector<PriceRecord>& records) {
    size_t position = 0;
    while (position < dataSize) {
        PriceRecord item;

        // Read price
        memcpy(&item.unitPrice, &data[position], sizeof(item.unitPrice));
        position += sizeof(item.unitPrice);

        // Read date length
        size_t dateLen;
        memcpy(&dateLen, &data[position], sizeof(dateLen));
        position += sizeof(dateLen);

        // Read date string
        item.recordDate = string(reinterpret_cast<const char*>(&data[position]), dateLen);
        position += dateLen;

        // Read integers
        memcpy(&item.setNumber, &data[position], sizeof(item.setNumber));
        position += sizeof(item.setNumber);

        memcpy(&item.conditionLevel, &data[position], sizeof(item.conditionLevel));
        position += sizeof(item.conditionLevel);

        records.push_back(item);
    }
}

// Save card data to SQLite database
int PersistCards() {
    int status;
    int cardIndex = 0;
    int priceCount = 0;
    char queryBuffer[256] = {0};

    sqlite3_stmt *statement;
    sqlite3 *database;

    status = sqlite3_open("sampledb.sqlite3", &database);

    if (status != SQLITE_OK) {
        cerr << "Failed to connect to database" << endl;
        return -1;
    }

    cout << "Database connection established" << endl;

    const char* createTableSQL = 
        "CREATE TABLE IF NOT EXISTS Cards ("
        "CardName TEXT, "
        "PriceData BLOB, "
        "PriceNum INTEGER, "
        "Threshold REAL, "
        "Fav INTEGER);";

    status = sqlite3_exec(database, createTableSQL, nullptr, nullptr, nullptr);
    if (status != SQLITE_OK) {
        cerr << "Table creation failed: " << sqlite3_errmsg(database) << endl;
        return -1;
    }

    // Iterate through all cards and insert them
    for (cardIndex = 0; cardIndex < cardCollection.size(); ++cardIndex) {
        vector<unsigned char> blobData;
        PackPriceRecords(cardCollection[cardIndex].priceHistory, blobData);

        // Prepare INSERT statement
        char sqlStatement[512] = {0};
        snprintf(sqlStatement, sizeof(sqlStatement),
            "INSERT INTO Cards (CardName, PriceData, PriceNum, Threshold, Fav) VALUES('%s', ?, %d, %f, %d)",
            cardCollection[cardIndex].cardTitle.c_str(),
            static_cast<int>(cardCollection[cardIndex].priceCount),
            cardCollection[cardIndex].alertThreshold,
            cardCollection[cardIndex].isFavorite);

        if (sqlite3_prepare_v2(database, sqlStatement, -1, &statement, NULL) != SQLITE_OK) {
            cerr << "Preparation failed: " << sqlite3_errmsg(database) << endl;
            continue;
        }

        // Bind BLOB data
        sqlite3_bind_blob(statement, 1, blobData.data(), static_cast<int>(blobData.size()), SQLITE_STATIC);

        // Execute statement
        status = sqlite3_step(statement);
        if (status != SQLITE_DONE) {
            cerr << "Execution error: " << sqlite3_errmsg(database) << endl;
        }

        sqlite3_finalize(statement);
    }

    sqlite3_close(database);
    return 0;
}

int main() {
    InitializeCards();
    PersistCards();
    return 0;
}

