// Generate pairs of unsorted and sorted integer lists
std::vector<std::vector<int>> generate_data(int sample_count, int list_length) {
    std::vector<std::vector<int>> result;
    std::random_device device;
    std::mt19937 engine(device());
    std::uniform_int_distribution<> distribution(1, 100);

    for (int index = 0; index < sample_count; ++index) {
        std::vector<int> raw_list(list_length);
        for (int position = 0; position < list_length; ++position) {
            raw_list[position] = distribution(engine);
        }

        std::vector<int> ordered_list = raw_list;
        std::sort(ordered_list.begin(), ordered_list.end());

        result.push_back(raw_list);
        result.push_back(ordered_list);
    }
    return result;
}

