#include <algorithm>

// Determine the outcome of a Rock-Paper-Scissors match
std::string decideResult(const std::string& firstChoice, const std::string& secondChoice) {
    // Convert both inputs to lowercase for case-insensitive comparison
    std::string choice1 = firstChoice;
    std::string choice2 = secondChoice;

    std::transform(choice1.begin(), choice1.end(), choice1.begin(),
                   [](unsigned char c){ return std::tolower(c); });
    std::transform(choice2.begin(), choice2.end(), choice2.begin(),
                   [](unsigned char c){ return std::tolower(c); });

    // Check for tie condition first
    if (choice1 == choice2) {
        return "Draw!";
    }

    // Apply game rules using alternative logic structure
    bool p1Wins = false;

    if (choice1 == "rock" && choice2 == "scissors") {
        p1Wins = true;
    } else if (choice1 == "paper" && choice2 == "rock") {
        p1Wins = true;
