// Generate the first n Fibonacci numbers using an iterative approach
vector<int> generateFibonacci(int count) {
    vector<int> result;
    if (count <= 0) return result;

    result.push_back(0);
    if (count == 1) return result;

    result.push_back(1);

    // Start from index 2 and continue until we have 'count' elements
    for (int idx = 2; idx < count; ++idx) {
        int prev = result[idx - 1];
        int prevPrev = result[idx - 2];
        result.push_back(prev + prevPrev);
    }

    return result;
}

int main() {
    vector<int> fibNumbers = generateFibonacci(10);

    // Print each Fibonacci number followed by a space
    for (int value : fibNumbers) {
        cout << value << " ";
    }

    return 0;
}

