// Compute the sum of integers from 0 to n-1 using a while loop
unsigned long long computeSum(unsigned long long limit)
{
    unsigned long long total = 0;
    unsigned long long counter = 0;

    while (counter < limit) {
        total += counter;
        counter++;
    }

    return total;
}

