// Type III clone: Refactored SAT solver with different implementation approach
// Using explicit backtracking instead of recursion, and renamed variables

using Variable = int;
using ClauseList = std::vector<Variable>;
using CNFFormula = std::vector<ClauseList>;

class BooleanSatisfiability {
public:
    BooleanSatisfiability(const CNFFormula& input_formula) 
        : clauses(input_formula), variable_count(0) {

        // Determine number of variables by finding max absolute value
        for (const auto& clause : input_formula) {
            for (Variable literal : clause) {
                variable_count = std::max(variable_count, std::abs(literal));
            }
        }

        // Initialize assignment array: 0=unassigned, 1=true, -1=false
        current_assignment.assign(variable_count + 1, 0);
    }

    bool find_solution() {
        // Use iterative backtracking with explicit stack
        int current_var = 1;

        while (current_var > 0 && current_var <= variable_count) {
            // Try unassigned value first
            if (current_assignment[current_var] == 0) {
                current_assignment[current_var] = 1; // Try true first
            } else if (current_assignment[current_var] == 1) {
                current_assignment[current_var] = -1; // Then try false
            } else {
                // Both values tried, backtrack
                current_assignment[current_var] = 0;
                current_var--;
                continue;
            }

            // Check if current partial assignment is still possible
            if (is_consistent(current_var)) {
                current_var++;
            }
        }

        // If we've assigned all variables, check full satisfaction
        return current_var == variable_count + 1 && is_fully_satisfied();
    }

    void display_result() const {
        for (int i = 1; i <= variable_count; ++i) {
            if (current_assignment[i] == 1) {
                std::cout << "v" << i << "=T ";
            } else if (current_assignment[i] == -1) {
                std::cout << "v" << i << "=F ";
            }
        }
        std::cout << std::endl;
    }

private:
    CNFFormula clauses;
    int variable_count;
    std::vector<int> current_assignment;

    // Check consistency up to the given variable (pruning)
    bool is_consistent(int last_assigned) const {
        for (const auto& clause : clauses) {
            bool clause_true = false;
            bool clause_unknowable = false;

            for (Variable lit : clause) {
                int var = std::abs(lit);
                if (var > last_assigned) {
                    clause_unknowable = true;
                    continue;
                }

                bool literal_value = (lit > 0) ? (current_assignment[var] == 1) : (current_assignment[-lit] == -1);
                if (literal_value) {
                    clause_true = true;
                    break;
                }
            }

            // If any clause is falsified under current assignment, inconsistent
            if (!clause_true && !clause_unknowable) {
                return false;
            }
        }
        return true;
    }

    // Verify all clauses are satisfied
    bool is_fully_satisfied() const {
        for (const auto& clause : clauses) {
            bool clause_ok = false;
            for (Variable lit : clause) {
                if (lit > 0) {
                    if (current_assignment[lit] == 1) {
                        clause_ok = true;
                        break;
                    }
                } else {
                    if (current_assignment[-lit] == -1) {
                        clause_ok = true;
                        break;
                    }
                }
            }
            if (!clause_ok) return false;
        }
        return true;
    }
};

int main() {
    // Example formula: (x1 OR x2) AND (NOT x1 OR x3)
    CNFFormula problem = {
        {1, 2},
        {-1, 3}
    };

    BooleanSatisfiability checker(problem);

    if (checker.find_solution()) {
        std::cout << "Formula is satisfiable. Assignment: ";
        checker.display_result();
    } else {
        std::cout << "Formula is unsatisfiable." << std::endl;
    }

    return 0;
}

