// Kernel to copy data using shared memory tiling
__global__ void optimized_copy_kernel(float* output, const float* input) {
    __shared__ float cache_block[BLOCK_SIZE][BLOCK_SIZE];

    int col = blockIdx.x * BLOCK_SIZE + threadIdx.x;
    int row = blockIdx.y * BLOCK_SIZE + threadIdx.y;
    int image_width = gridDim.x * BLOCK_SIZE;

    // Read from global memory into shared memory
    cache_block[threadIdx.y][threadIdx.x] = input[row * image_width + col];
    __syncthreads();

    // Write from shared memory back to global memory
    output[row * image_width + col] = cache_block[threadIdx.y][threadIdx.x];
}

