Eigen::Matrix4f create_base_matrix() {
    Eigen::Matrix4f result;
    result << 1, 2, 3, 4,
              5, 6, 7, 8,
              9, 8, 7, 6,
              5, 4, 3, 2;
    return result;
}

std::pair<pybind11::array_t<float>, pybind11::array_t<float>> generate_tensor_data(const std::vector<float>& input_values) {
    const size_t batch_size = input_values.size();
    const size_t rows_a = 5;
    const size_t cols_b = 3;
    const size_t inner_dim = 2;
    const size_t matrix_order = 4; // Dimension of square matrices

    // Pre-allocate contiguous storage for tensor data
    std::vector<float> storage_A(batch_size * rows_a * matrix_order * matrix_order);
    std::vector<float> storage_B(batch_size * cols_b * inner_dim * matrix_order * matrix_order);

    // Populate the data structures using nested loops
    for (size_t idx_batch = 0; idx_batch < batch_size; ++idx_batch) {
        // Fill A-tensor: shape [batch_size, rows_a, matrix_order, matrix_order]
        for (size_t idx_i = 0; idx_i < rows_a; ++idx_i) {
            Eigen::Matrix4f temp_mat = create_base_matrix(); // Placeholder computation

            for (size_t row = 0; row < matrix_order; ++row) {
                for (size_t col = 0; col < matrix_order; ++col) {
                    storage_A[idx_batch * rows_a * matrix_order * matrix_order +
                              idx_i * matrix_order * matrix_order +
                              row * matrix_order + col] = temp_mat(row, col);
                }
            }
        }

        // Fill B-tensor: shape [batch_size, cols_b, inner_dim, matrix_order, matrix_order]
        for (size_t idx_j = 0; idx_j < cols_b; ++idx_j) {
            for (size_t idx_k = 0; idx_k < inner_dim; ++idx_k) {
                Eigen::Matrix4f temp_mat = create_base_matrix(); // Placeholder computation

                for (size_t row = 0; row < matrix_order; ++row) {
                    for (size_t col = 0; col < matrix_order; ++col) {
                        storage_B[idx_batch * cols_b * inner_dim * matrix_order * matrix_order +
                                  idx_j * inner_dim * matrix_order * matrix_order +
                                  idx_k * matrix_order * matrix_order +
                                  row * matrix_order + col] = temp_mat(row, col);
                    }
                }
            }
        }
    }

    // Construct NumPy-compatible array views
    pybind11::array_t<float> array_A = pybind11::array_t<float>(
        {batch_size, rows_a, matrix_order, matrix_order},
        {rows_a * matrix_order * matrix_order * sizeof(float),
         matrix_order * matrix_order * sizeof(float),
         matrix_order * sizeof(float),
         sizeof(float)},
        storage_A.data()
    );

    pybind11::array_t<float> array_B = pybind11::array_t<float>(
        {batch_size, cols_b, inner_dim, matrix_order, matrix_order},
        {cols_b * inner_dim * matrix_order * matrix_order * sizeof(float),
         inner_dim * matrix_order * matrix_order * sizeof(float),
         matrix_order * matrix_order * sizeof(float),
         matrix_order * sizeof(float),
         sizeof(float)},
        storage_B.data()
    );

    return std::make_pair(array_A, array_B);
}

PYBIND11_MODULE(example_module, m) {
    m.def("generate_tensor_data", &generate_tensor_data, 
          pybind11::return_value_policy::reference);
}

