    ObjectId generateObject() {
        return nextId_++;
    }

private:
    ObjectId nextId_;
};

// Template class to manage specific component types
template <typename ComponentType>
class ComponentStorage {
public:
    void storeComponent(ObjectId objId, const ComponentType& comp) {
        storage_[objId] = comp;
    }

    ComponentType* fetchComponent(ObjectId objId) {
        auto iter = storage_.find(objId);
        return (iter != storage_.end()) ? &(iter->second) : nullptr;
    }

private:
    std::unordered_map<ObjectId, ComponentType> storage_;
};

