using namespace std;

// Interchange the values of two integer references
void exchange(int &x, int &y) {
    int buffer = x;
    x = y;
    y = buffer;
}

// Rearrange elements around a chosen pivot and return final pivot position
int rearrange(vector<int> &data, int start, int end, int pivotPos) {
    int pivotVal = data[pivotPos];
    exchange(data[pivotPos], data[end]); // Place pivot at the end
    int boundary = start;

    for (int idx = start; idx < end; ++idx) {
        if (data[idx] < pivotVal) {
            exchange(data[idx], data[boundary]);
            ++boundary;
        }
    }

    exchange(data[end], data[boundary]); // Put pivot in correct location
    return boundary;
}

// Select the k-th smallest element using randomized selection
int selectKth(vector<int> &data, int left, int right, int k) {
    if (left == right)
        return data[left];

    srand(static_cast<unsigned>(time(nullptr)));
    int pivotLoc = left + rand() % (right - left + 1);

    pivotLoc = rearrange(data, left, right, pivotLoc);

    if (k == pivotLoc)
        return data[k];
    else if (k < pivotLoc)
        return selectKth(data, left, pivotLoc - 1, k);
    else
        return selectKth(data, pivotLoc + 1, right, k);
}

// Compute the median of an odd-sized vector
int computeMedian(vector<int> &values) {
    int size = values.size();
    if (size == 0)
        throw invalid_argument("Input collection must not be empty.");
    if (size % 2 == 0)
        throw invalid_argument("Collection size needs to be odd for median calculation.");

    int middleIndex = (size - 1) / 2;
    return selectKth(values, 0, size - 1, middleIndex);
}

int main() {
    vector<int> dataset = {12, 3, 5, 7, 4, 19, 26};
    try {
        int result = computeMedian(dataset);
        cout << "The median value is: " << result << endl;
    } catch (const invalid_argument &err) {
        cout << err.what() << endl;
    }
    return 0;
}

#include <asm/unistd.h>

// System call configuration for different architectures
#if defined(__i386__)
    // 32-bit x86 system call setup
    #define _SC_OPER "int $0x80"
    #define _SC_NUM_REG "%eax"
    #define _SC_RET_REG "%eax"
    #define _SC_ARG1_REG "%ebx"
    #define _SC_ARG2_REG "%ecx"
    #define _SC_ARG3_REG "%edx"
    #define _SC_CLOBBER_LIST
#else
    // 64-bit x86 system call setup  
    #define _SC_OPER "syscall"
    #define _SC_NUM_REG "%rax"
    #define _SC_RET_REG "%rax"
    #define _SC_ARG1_REG "%rdi"
    #define _SC_ARG2_REG "%rsi"
    #define _SC_ARG3_REG "%rdx"
    #define _SC_CLOBBER_LIST "rcx", "r11"
#endif

// Alternative syscall wrapper using different implementation approach
template<typename ResultType = long, typename ArgType>
ResultType invoke_syscall(long sys_number, ArgType first_arg)
{
    long syscall_num = sys_number;
    ArgType arg_value = first_arg;
    ResultType result;

    __asm__ volatile (
        _SC_OPER
        : "=a" (result)
        : "0" (syscall_num), "D" (arg_value)
        : _SC_CLOBBER_LIST
    );

    return result;
}

// Entry point for the program - no standard library main
extern "C" void _start()
{
    // Exit the process with status code 0
    invoke_syscall(__NR_exit, 0);
}

extern "C" {
    #include <cuda_runtime.h>

    // CUDA kernel to perform element-wise addition of two arrays
    __global__ void vectorAddKernel(float *result, const float *inputA, const float *inputB, int size) {
        int index = threadIdx.x;
        if (index < size) {
            result[index] = inputA[index] + inputB[index];
        }
    }

    // Host function to manage memory and launch the CUDA kernel for array addition
    void vectorAdd(float *hostResult, const float *hostInputA, const float *hostInputB, int count) {
        float *deviceA, *deviceB, *deviceResult;

        // Allocate device memory for input and output arrays
        cudaMalloc(&deviceA, count * sizeof(float));
        cudaMalloc(&deviceB, count * sizeof(float));
        cudaMalloc(&deviceResult, count * sizeof(float));

        // Copy input data from host to device
        cudaMemcpy(deviceA, hostInputA, count * sizeof(float), cudaMemcpyHostToDevice);
        cudaMemcpy(deviceB, hostInputB, count * sizeof(float), cudaMemcpyHostToDevice);

        // Launch kernel with one thread per array element
        vectorAddKernel<<<1, count>>>(deviceResult, deviceA, deviceB, count);

        // Copy result back from device to host
        cudaMemcpy(hostResult, deviceResult, count * sizeof(float), cudaMemcpyDeviceToHost);

        // Release device memory
        cudaFree(deviceA);
        cudaFree(deviceB);
        cudaFree(deviceResult);
    }
}

