#include <iostream>
#include <vector>
#include <string>
#include <algorithm>

// Helper function to compare suffixes at offset p
bool compareSuffixAtOffset(const std::string& input, int pos1, int pos2, int offset) {
    if (pos1 + offset == static_cast<int>(input.length())) return false;
    if (pos2 + offset == static_cast<int>(input.length())) return true;
    return input[pos1 + offset] < input[pos2 + offset];
}

// Construct suffix array using doubling algorithm
std::vector<int> createSuffixArray(const std::string& text) {
    int len = text.size();
    std::vector<int> suffixes(len);
    for (int i = 0; i < len; ++i) suffixes[i] = i;

    std::vector<int> ranks(len);
    for (int i = 0; i < len; ++i) ranks[i] = static_cast<int>(text[i]);

    for (int step = 1; step < len; step *= 2) {
        std::sort(suffixes.begin(), suffixes.end(), [&](int a, int b) {
            if (ranks[a] != ranks[b]) return ranks[a] < ranks[b];
            return compareSuffixAtOffset(text, a, b, step);
        });

        std::vector<int> updatedRanks(len);
        updatedRanks[suffixes[0]] = 0;
        for (int i = 1; i < len; ++i) {
            bool different = compareSuffixAtOffset(text, suffixes[i - 1], suffixes[i], step) ||
                             (ranks[suffixes[i - 1]] != ranks[suffixes[i]]);
            updatedRanks[suffixes[i]] = updatedRanks[suffixes[i - 1]] + (different ? 1 : 0);
        }
        ranks = updatedRanks;
    }

    return suffixes;
}

// Build LCP array using Kasai's algorithm
std::vector<int> constructLCP(const std::string& text, const std::vector<int>& suffixArr) {
    int n = text.size();
    std::vector<int> rank(n);
    for (int i = 0; i < n; ++i) rank[suffixArr[i]] = i;

    std::vector<int> lcp(n, 0);
    for (int i = 0, height = 0; i < n; ++i) {
        if (rank[i] == n - 1) {
            height = 0;
            continue;
        }
        int nextPos = suffixArr[rank[i] + 1];
        while (i + height < n && nextPos + height < n && text[i + height] == text[nextPos + height]) {
            ++height;
        }
        lcp[rank[i]] = height;
        height = std::max(height - 1, 0);
    }

    return lcp;
}

// Find longest common substring among multiple strings
std::string findLongestSharedSubstring(const std::vector<std::string>& words) {
    std::string merged = "";
    for (const auto& word : words) {
        merged += word + "#";
    }

    std::vector<int> suffixOrder = createSuffixArray(merged);
    std::vector<int> longestCommonPrefix = constructLCP(merged, suffixOrder);

    int bestLength = 0;
    int bestStartIndex = 0;
    for (int i = 1; i < longestCommonPrefix.size(); ++i) {
        if (longestCommonPrefix[i] > bestLength) {
            bestLength = longestCommonPrefix[i];
            bestStartIndex = suffixOrder[i];
        }
    }

    if (bestLength == 0) return "";

    return merged.substr(bestStartIndex, bestLength);
}

int main() {
    std::vector<std::string> testStrings = {"flower", "flow", "flight"};
    std::string commonPart = findLongestSharedSubstring(testStrings);

    if (commonPart.empty()) {
        std::cout << "No shared substring detected." << std::endl;
    } else {
        std::cout << "Longest shared substring: " << commonPart << std::endl;
    }

    return 0;
}

