extern "C" __declspec(dllexport) const char* RetrieveStringFromCSharp()
{
    if (StringStorage::StoredValue == nullptr)
        return "";

    // Convert managed String to std::wstring first
    pin_ptr<const wchar_t> widePtr = PtrToStringChars(StringStorage::StoredValue);
    std::wstring wideStr(widePtr, StringStorage::StoredValue->Length);

    // Convert wstring to multibyte char string using vector for safe memory management
    size_t requiredSize = wcstombs(nullptr, wideStr.c_str(), 0);
    if (requiredSize == static_cast<size_t>(-1))
        return "";

    std::vector<char> buffer(requiredSize + 1, '\0');
    wcstombs(buffer.data(), wideStr.c_str(), buffer.size());

    // Allocate heap memory for return value (caller must manage or use appropriately)
    char* result = new char[buffer.size()];
    std::copy(buffer.begin(), buffer.end(), result);

    return result;
}

