// Function to print all prime numbers up to n using Sieve of Eratosthenes
void showPrimeNumbers(int limit) {
    vector<bool> primeFlags(limit + 1, true);
    primeFlags[0] = primeFlags[1] = false; // Mark 0 and 1 as non-prime

    for (int factor = 2; factor * factor <= limit; ++factor) {
        if (primeFlags[factor]) {
            for (int multiple = factor * factor; multiple <= limit; multiple += factor) {
                primeFlags[multiple] = false;
            }
        }
    }

    cout << "Prime numbers up to " << limit << ": ";
    for (int number = 2; number <= limit; ++number) {
        if (primeFlags[number]) {
            cout << number << " ";
        }
    }
    cout << endl;
}

int main() {
    int inputNumber;
    cout << "Enter a positive integer: ";
    cin >> inputNumber;

    showPrimeNumbers(inputNumber);

    return 0;
}

