// Enumerate network computers using Shell API
void DisplayNetworkResources()
{
    HRESULT hr = CoInitializeEx(nullptr, COINIT_APARTMENTTHREADED);
    if (SUCCEEDED(hr))
    {
        IShellItem* pItemContainer = nullptr;
        hr = SHGetKnownFolderItem(FOLDERID_NetworkFolder, KF_FLAG_DEFAULT, nullptr, IID_IShellItem, reinterpret_cast<void**>(&pItemContainer));

        if (SUCCEEDED(hr) && pItemContainer)
        {
            IEnumShellItems* pEnumerator = nullptr;
            hr = pItemContainer->BindToHandler(nullptr, BHID_EnumItems, IID_IEnumShellItems, reinterpret_cast<void**>(&pEnumerator));

            if (SUCCEEDED(hr) && pEnumerator)
            {
                IShellItem* pItem = nullptr;
                while (pEnumerator->Next(1, &pItem, nullptr) == S_OK)
                {
                    PWSTR pszDisplayName = nullptr;
                    if (SUCCEEDED(pItem->GetDisplayName(SIGDN_NORMALDISPLAY, &pszDisplayName)) && pszDisplayName)
                    {
                        std::wcout << L"Host: " << pszDisplayName << std::endl;
                        CoTaskMemFree(pszDisplayName);
                    }
                    if (pItem)
                    {
                        pItem->Release();
                        pItem = nullptr;
                    }
                }
                pEnumerator->Release();
            }
            if (pItemContainer)
            {
                pItemContainer->Release();
                pItemContainer = nullptr;
            }
        }
        CoUninitialize();
    }
}

int main()
{
    DisplayNetworkResources();
    return 0;
}

