class PhoneticEncoder {
public:
    std::pair<std::string, std::string> transform(const std::string& input) {
        std::string primaryForm, alternateForm;

        for (char ch : input) {
            char lowerChar = std::tolower(ch);

            switch (lowerChar) {
                case 'b': 
                    primaryForm += 'b'; 
                    alternateForm += 'b'; 
                    break;
                case 'c': 
                    primaryForm += 'k'; 
                    alternateForm += 's'; 
                    break;
                case 'd': 
                    primaryForm += 't'; 
                    alternateForm += 't'; 
                    break;
                case 'f': 
                    primaryForm += 'f'; 
                    alternateForm += 'f'; 
                    break;
                case 'g': 
                    primaryForm += 'k'; 
                    alternateForm += 'j'; 
                    break;
                case 'h': 
                    primaryForm += 'h'; 
                    alternateForm += 'h'; 
                    break;
                case 'j': 
                    primaryForm += 'j'; 
                    alternateForm += 'j'; 
                    break;
                case 'k': 
                    primaryForm += 'k'; 
                    alternateForm += 'k'; 
                    break;
                case 'l': 
                    primaryForm += 'l'; 
                    alternateForm += 'l'; 
                    break;
                case 'm': 
                    primaryForm += 'm'; 
                    alternateForm += 'm'; 
                    break;
                case 'n': 
                    primaryForm += 'n'; 
                    alternateForm += 'n'; 
                    break;
                case 'p': 
                    primaryForm += 'p'; 
                    alternateForm += 'p'; 
                    break;
                case 'q': 
                    primaryForm += 'k'; 
                    alternateForm += 'k'; 
                    break;
                case 'r': 
                    primaryForm += 'r'; 
                    alternateForm += 'r'; 
                    break;
                case 's': 
                    primaryForm += 's'; 
                    alternateForm += 's'; 
                    break;
                case 't': 
                    primaryForm += 't'; 
                    alternateForm += 't'; 
                    break;
                case 'v': 
                    primaryForm += 'f'; 
                    alternateForm += 'f'; 
                    break;
                case 'w': 
                    primaryForm += 'w'; 
                    alternateForm += 'w'; 
                    break;
                case 'x': 
                    primaryForm += "ks"; 
                    alternateForm += "ks"; 
                    break;
                case 'y': 
                    primaryForm += 'y'; 
                    alternateForm += 'y'; 
                    break;
                case 'z': 
                    primaryForm += 's'; 
                    alternateForm += 's'; 
                    break;
                default: 
                    primaryForm += 'a'; 
                    alternateForm += 'a'; 
                    break;
            }
        }

        return {primaryForm, alternateForm};
    }
};

int main() {
    PhoneticEncoder encoder;
    std::string term1 = "Smith";
    std::string term2 = "Smythe";

    auto result1 = encoder.transform(term1);
    auto result2 = encoder.transform(term2);

    std::cout << "Term 1: " << term1 << " -> " << result1.first << " / " << result1.second << std::endl;
    std::cout << "Term 2: " << term2 << " -> " << result2.first << " / " << result2.second << std::endl;

    if (result1.first == result2.first || result1.second == result2.second) {
        std::cout << "The terms sound similar phonetically." << std::endl;
    } else {
        std::cout << "The terms do not sound similar phonetically." << std::endl;
    }

    return 0;
}

