#include <cuda_runtime.h>
#include <iostream>
#include <cmath>

#define TILE_DIM 16

__global__ void euclideanDistanceKernel(float *inputA, float *inputB, float *outputDist, int numSamplesA, int numSamplesB) {
    __shared__ float tileB[TILE_DIM * 128];

    int sampleIdxA = blockIdx.x;
    int colStartB = blockIdx.y * TILE_DIM + threadIdx.x;
    int colEndB = colStartB + TILE_DIM;

    // Load segment of matrix B into shared memory
    for (int idx = colStartB; idx < colEndB && idx < numSamplesB; ++idx) {
        for (int feat = 0; feat < 128; ++feat) {
            tileB[(idx - colStartB) * 128 + feat] = inputB[idx * 128 + feat];
        }
    }
    __syncthreads();

    // Compute Euclidean distances for the assigned columns
    for (int colB = colStartB; colB < colEndB && colB < numSamplesB; ++colB) {
        float squaredSum = 0.0f;
        for (int dim = 0; dim < 128; ++dim) {
            float diff = inputA[sampleIdxA * 128 + dim] - tileB[(colB - colStartB) * 128 + dim];
            squaredSum += diff * diff;
        }
        outputDist[sampleIdxA * numSamplesB + colB] = sqrtf(squaredSum);
    }
}

int main() {
    const int rowsA = 1000;
    const int rowsB = 1000;
    size_t bytesA = rowsA * 128 * sizeof(float);
    size_t bytesB = rowsB * 128 * sizeof(float);
    size_t bytesC = rowsA * rowsB * sizeof(float);

    float *hostA = new float[rowsA * 128];
    float *hostB = new float[rowsB * 128];
    float *hostC = new float[rowsA * rowsB];

    // Seed and populate host arrays with pseudo-random data
    for (int i = 0; i < rowsA * 128; ++i) {
        hostA[i] = static_cast<float>(rand()) / static_cast<float>(RAND_MAX);
    }
    for (int i = 0; i < rowsB * 128; ++i) {
        hostB[i] = static_cast<float>(rand()) / static_cast<float>(RAND_MAX);
    }

    float *deviceA, *deviceB, *deviceC;
    cudaMalloc(&deviceA, bytesA);
    cudaMalloc(&deviceB, bytesB);
    cudaMalloc(&deviceC, bytesC);

    cudaMemcpy(deviceA, hostA, bytesA, cudaMemcpyHostToDevice);
    cudaMemcpy(deviceB, hostB, bytesB, cudaMemcpyHostToDevice);

    dim3 blockSize(TILE_DIM, 1);
    dim3 gridSize((rowsB + TILE_DIM - 1) / TILE_DIM, rowsA);

    euclideanDistanceKernel<<<gridSize, blockSize>>>(deviceA, deviceB, deviceC, rowsA, rowsB);

    cudaMemcpy(hostC, deviceC, bytesC, cudaMemcpyDeviceToHost);

    // Release allocated resources
    cudaFree(deviceA);
    cudaFree(deviceB);
    cudaFree(deviceC);
    delete[] hostA;
    delete[] hostB;
    delete[] hostC;

    return 0;
}

