// Function to print Fibonacci sequence up to n terms
void printFibonacciSequence(int count) {
    if (count <= 0) {
        std::cout << "Please enter a positive integer." << std::endl;
        return;
    }

    int first = 0, second = 1, next = 0;
    int position = 1;

    while (position <= count) {
        if (position == 1) {
            std::cout << first;
            if (count > 1) std::cout << ", ";
            position++;
            continue;
        }
        if (position == 2) {
            std::cout << second;
            if (count > 2) std::cout << ", ";
            position++;
            continue;
        }

        next = first + second;
        first = second;
        second = next;

        std::cout << next;
        if (position < count) {
            std::cout << ", ";
        }
        position++;
    }
}

int main() {
    int terms;
    std::cout << "Enter the number of terms: ";
    std::cin >> terms;

    printFibonacciSequence(terms);

    return 0;
}

