#include <immintrin.h>

void Transpose(double* in, double* out) {
  // Load 8x8 matrix as 8 rows of 8 doubles each
  __m512d r0 = _mm512_load_pd(in + 0);
  __m512d r1 = _mm512_load_pd(in + 8);
  __m512d r2 = _mm512_load_pd(in + 16);
  __m512d r3 = _mm512_load_pd(in + 24);
  __m512d r4 = _mm512_load_pd(in + 32);
  __m512d r5 = _mm512_load_pd(in + 40);
  __m512d r6 = _mm512_load_pd(in + 48);
  __m512d r7 = _mm512_load_pd(in + 56);

  // Interleave low and high pairs to begin transposition
  __m512d t0 = _mm512_unpacklo_pd(r0, r1);  // [0,8,2,10,4,12,6,14]
  __m512d t1 = _mm512_unpackhi_pd(r0, r1);  // [1,9,3,11,5,13,7,15]
  __m512d t2 = _mm512_unpacklo_pd(r2, r3);  // [16,24,18,26,20,28,22,30]
  __m512d t3 = _mm512_unpackhi_pd(r2, r3);  // [17,25,19,27,21,29,23,31]
  __m512d t4 = _mm512_unpacklo_pd(r4, r5);  // [32,40,34,42,36,44,38,46]
  __m512d t5 = _mm512_unpackhi_pd(r4, r5);  // [33,41,35,43,37,45,39,47]
  __m512d t6 = _mm512_unpacklo_pd(r6, r7);  // [48,56,50,58,52,60,54,62]
  __m512d t7 = _mm512_unpackhi_pd(r6, r7);  // [49,57,51,59,53,61,55,63]

  // Permute using index vectors to combine interleaved data
  __m512d idx0 = _mm512_setr_epi64(0,1,8,9,4,5,12,13);
  __m512d idx1 = _mm512_setr_epi64(2,3,10,11,6,7,14,15);

  __m512d u0 = _mm512_permutex2var_pd(t0, idx0, t2);
  __m512d u1 = _mm512_permutex2var_pd(t0, idx1, t2);
  __m512d u2 = _mm512_permutex2var_pd(t1, idx0, t3);
  __m512d u3 = _mm512_permutex2var_pd(t1, idx1, t3);
  __m512d u4 = _mm512_permutex2var_pd(t4, idx0, t6);
  __m512d u5 = _mm512_permutex2var_pd(t4, idx1, t6);
  __m512d u6 = _mm512_permutex2var_pd(t5, idx0, t7);
  __m512d u7 = _mm512_permutex2var_pd(t5, idx1, t7);

  // Combine upper/lower halves across blocks using mask moves
  {
    __m512d blend = _mm512_shuffle_f64x2(u0, u4, 0x4e);
    __m512d m0 = _mm512_setr_epi64(0,0,-1,-1,0,0,-1,-1);
    __m512d m4 = _mm512_setr_epi64(-1,-1,0,0,-1,-1,0,0);
    __m512d v0 = _mm512_mask_mov_pd(u0, m0, blend);
    __m512d v4 = _mm512_mask_mov_pd(u4, m4, blend);

    _mm512_store_pd(out + 0, v0);
    _mm512_store_pd(out + 32, v4);
  }

  {
    __m512d blend = _mm512_shuffle_f64x2(u1, u5, 0x4e);
    __m512d m1 = _mm512_setr_epi64(0,0,-1,-1,0,0,-1,-1);
    __m512d m5 = _mm512_setr_epi64(-1,-1,0,0,-1,-1,0,0);
    __m512d v1 = _mm512_mask_mov_pd(u1, m1, blend);
    __m512d v5 = _mm512_mask_mov_pd(u5, m5, blend);

    _mm512_store_pd(out + 8, v1);
    _mm512_store_pd(out + 40, v5);
  }

  {
    __m512d blend = _mm512_shuffle_f64x2(u2, u6, 0x4e);
    __m512d m2 = _mm512_setr_epi64(0,0,-1,-1,0,0,-1,-1);
    __m512d m6 = _mm512_setr_epi64(-1,-1,0,0,-1,-1,0,0);
    __m512d v2 = _mm512_mask_mov_pd(u2, m2, blend);
    __m512d v6 = _mm512_mask_mov_pd(u6, m6, blend);

    _mm512_store_pd(out + 16, v2);
    _mm512_store_pd(out + 48, v6);
  }

  {
    __m512d blend = _mm512_shuffle_f64x2(u3, u7, 0x4e);
    __m512d m3 = _mm512_setr_epi64(0,0,-1,-1,0,0,-1,-1);
    __m512d m7 = _mm512_setr_epi64(-1,-1,0,0,-1,-1,0,0);
    __m512d v3 = _mm512_mask_mov_pd(u3, m3, blend);
    __m512d v7 = _mm512_mask_mov_pd(u7, m7, blend);

    _mm512_store_pd(out + 24, v3);
    _mm512_store_pd(out + 56, v7);
  }
}

