__global__ void myKernel(const char* text, int* m, int num_chars) {
    __shared__ int D[PADDED_SIZE]; // PADDED_SIZE = (NUM_THREADS + 1) * sizeof(int)
    int thread_id = threadIdx.x;
    int block_id = blockIdx.x;
    int idx = thread_id + block_id * blockDim.x;

    if (idx < num_chars) {
        // Initialize shared memory element for this thread
        int offset = thread_id * (PADDED_SIZE / NUM_THREADS);
        D[offset] = 0;

        // Process characters using while loop
        int counter = 0;
        while (counter < num_chars) {
            // Accumulate character value in shared memory
            D[offset] += text[idx];

            // Condition check and global memory update
            if (D[offset] > SOME_THRESHOLD) {
                m[idx] = 1;
            }

            counter++;
        }
    }
}

