REGISTER_OP("PrivacyPreservingProcess")
    .Input("data_tensor: float")
    .Attr("party_type: string")
    .Attr("epsilon_param: float = 1.0")
    .Output("result_tensor: float")
    .SetShapeFn([](tensorflow::shape_inference::InferenceContext* c) {
      c->set_output(0, c->input(0));
      return tensorflow::Status::OK();
    });

namespace tensorflow {

class PrivacyPreservingProcessOp : public OpKernel {
 public:
  explicit PrivacyPreservingProcessOp(OpKernelConstruction* context)
      : OpKernel(context) {
    OP_REQUIRES_OK(context, context->GetAttr("party_type", &party_type_));
    OP_REQUIRES_OK(context, context->GetAttr("epsilon_param", &epsilon_param_));
  }

  void Compute(OpKernelContext* ctx) override {
    // Get input tensor
    const Tensor& input_tensor = ctx->input(0);

    // Prepare output tensor with same shape as input
    TensorShape result_shape(input_tensor.shape());
    Tensor* result_tensor = nullptr;
    OP_REQUIRES_OK(ctx, ctx->allocate_output(0, result_shape, &result_tensor));

    if (party_type_ == "client") {
      // Client party simply forwards the data unchanged
      *result_tensor = input_tensor;
    } else if (party_type_ == "server") {
      // Server party adds Laplacian noise for differential privacy
      float scale = 1.0f / epsilon_param_;
      ApplyNoise(ctx, input_tensor, result_tensor, scale);
    } else {
      OP_REQUIRES(ctx, false, errors::InvalidArgument("Unknown party type: ", party_type_));
    }
  }

 private:
  void ApplyNoise(OpKernelContext* ctx, const Tensor& input,
                  Tensor* output, float scale_factor) {
    auto in_flat = input.flat<float>();
    auto out_flat = output->flat<float>();

    // Use standard library random facilities for noise generation
    std::random_device rng;
    std::mt19937 gen(rng());
    std::laplace_distribution<float> dist(0.0f, scale_factor);

    for (size_t idx = 0; idx < in_flat.size(); ++idx) {
      float perturbation = dist(gen);
      out_flat(idx) = in_flat(idx) + perturbation;
    }
  }

  std::string party_type_;
  float epsilon_param_;
};

REGISTER_KERNEL_BUILDER(Name("PrivacyPreservingProcess").Device(DEVICE_CPU), PrivacyPreservingProcessOp);

