struct TreeNode {
    int value;
    int depth;
    TreeNode* leftChild;
    TreeNode* rightChild;
};

// Retrieve the depth of a subtree
int getDepth(TreeNode* node) {
    if (node == nullptr)
        return 0;
    return node->depth;
}

// Construct a new tree node with given value
TreeNode* createNode(int val) {
    TreeNode* newNode = new TreeNode();
    newNode->value = val;
    newNode->leftChild = nullptr;
    newNode->rightChild = nullptr;
    newNode->depth = 1; // Newly inserted nodes start at leaf level
    return newNode;
}

// Perform right rotation on subtree rooted at 'y'
TreeNode* rotateRight(TreeNode* y) {
    TreeNode* x = y->leftChild;
    TreeNode* subtree = x->rightChild;

    // Execute rotation
    x->rightChild = y;
    y->leftChild = subtree;

    // Recalculate depths
    y->depth = std::max(getDepth(y->leftChild), getDepth(y->rightChild)) + 1;
    x->depth = std::max(getDepth(x->leftChild), getDepth(x->rightChild)) + 1;

    // Return new root after rotation
    return x;
}

// Perform left rotation on subtree rooted at 'x'
TreeNode* rotateLeft(TreeNode* x) {
    TreeNode* y = x->rightChild;
    TreeNode* subtree = y->leftChild;

    // Execute rotation
    y->leftChild = x;
    x->rightChild = subtree;

    // Recalculate depths
    x->depth = std::max(getDepth(x->leftChild), getDepth(x->rightChild)) + 1;
    y->depth = std::max(getDepth(y->leftChild), getDepth(y->rightChild)) + 1;

    // Return new root after rotation
    return y;
}

// Compute balance factor for node N
int calculateBalance(TreeNode* node) {
    if (node == nullptr)
        return 0;
    return getDepth(node->leftChild) - getDepth(node->rightChild);
}

// Insert a value into AVL tree and maintain balance
TreeNode* addValue(TreeNode* root, int val) {
    // Standard BST insertion logic
    if (root == nullptr)
        return createNode(val);

    if (val < root->value)
        root->leftChild = addValue(root->leftChild, val);
    else if (val > root->value)
        root->rightChild = addValue(root->rightChild, val);
    else // Duplicate values not permitted
        return root;

    // Update depth of current ancestor node
    root->depth = 1 + std::max(getDepth(root->leftChild), getDepth(root->rightChild));

    // Determine balance status
    int balanceFactor = calculateBalance(root);

    // Handle four possible imbalance scenarios

    // Left-Left imbalance
    if (balanceFactor > 1 && val < root->leftChild->value)
        return rotateRight(root);

    // Right-Right imbalance
    if (balanceFactor < -1 && val > root->rightChild->value)
        return rotateLeft(root);

    // Left-Right imbalance
    if (balanceFactor > 1 && val > root->leftChild->value) {
        root->leftChild = rotateLeft(root->leftChild);
        return rotateRight(root);
    }

    // Right-Left imbalance
    if (balanceFactor < -1 && val < root->rightChild->value) {
        root->rightChild = rotateRight(root->rightChild);
        return rotateLeft(root);
    }

    // Return unchanged node if balanced
    return root;
}

