// Find and return the longest string in a vector of strings
std::string findMaxLengthString(const std::vector<std::string>& inputStrings) {
    if (inputStrings.empty()) {
        return "";
    }

    const std::string* currentLongest = &inputStrings[0];
    size_t index = 1;

    while (index < inputStrings.size()) {
        if (inputStrings[index].length() > currentLongest->length()) {
            currentLongest = &inputStrings[index];
        }
        ++index;
    }

    return *currentLongest;
}

int main() {
    std::vector<std::string> words = {"apple", "banana", "cherry", "date"};
    std::string result = findMaxLengthString(words);
    std::cout << "The longest string is: " << result << std::endl;
    return 0;
}

