void retrieveEnvironmentData(
    sqlite3* envdbhandle,
    const std::vector<IteratorStruct>& iterators, // assuming iter is part of a container
    int year,
    std::vector<EnvironmentDatum>& envCollection
) {
    for (auto iter = iterators.begin(); iter != iterators.end(); ++iter) {
        sqlite3_stmt* stmtEnv = nullptr;
        prepareSqlStatement(queryEnvData, &stmtEnv, envdbhandle, 
                            "Error preparing SQL statement to retrieve environmental data. SQLite return code: ");

        sqlite3_bind_double(stmtEnv, 1, static_cast<double>(iter->latitude));
        sqlite3_bind_double(stmtEnv, 2, static_cast<double>(iter->longitude));
        sqlite3_bind_double(stmtEnv, 3, static_cast<double>(iter->startTime));
        sqlite3_bind_double(stmtEnv, 4, static_cast<double>(iter->endTime));

        __android_log_print(ANDROID_LOG_DEBUG, "SPP/getEnvironment", 
                            "Bound parameters: lat=%.6f, lon=%.6f, start=%ld, end=%ld",
                            iter->latitude, iter->longitude, iter->startTime, iter->endTime);

        int status = sqlite3_step(stmtEnv);
        __android_log_print(ANDROID_LOG_DEBUG, "SPP/getEnvironment", 
                            "Initial step() result = %d", status);

        if (status == SQLITE_ROW) {
            do {
                EnvironmentDatum record;
                int rawTime = static_cast<int>(sqlite3_column_int(stmtEnv, 0));
                record.UnixTime = timeconvert::secondsOfYearToUNIXTime(rawTime, year);
                __android_log_print(ANDROID_LOG_DEBUG, "SPP/getEnvironment", 
                                    "Raw DB time=%d → UnixTime=%.2f", rawTime, record.UnixTime);

                record.GHI = sqlite3_column_double(stmtEnv, 1);
                record.Temperature = sqlite3_column_double(stmtEnv, 2);
                record.Humidity = sqlite3_column_double(stmtEnv, 3);

                envCollection.push_back(record);
                status = sqlite3_step(stmtEnv);
            } while (status == SQLITE_ROW);
        } else {
            __android_log_print(ANDROID_LOG_DEBUG, "SPP/getEnvironment", 
                                "No matching rows found or error encountered.");
        }

        int lastErrCode = sqlite3_extended_errcode(envdbhandle);
        __android_log_print(ANDROID_LOG_DEBUG, "SPP/getEnvironment", 
                            "SQLite error code: %s (%d). Message: %s",
                            sqlite3_errstr(lastErrCode), lastErrCode, sqlite3_errmsg(envdbhandle));

        sqlite3_finalize(stmtEnv);
    }
}

