#include <iostream>
#include <stdexcept>

template <typename T>
class DynamicArray {
private:
    T* elements;
    size_t currentSize;
    size_t allocatedCapacity;

    // Internal method to expand storage when needed
    void expandStorage(size_t newCapacity) {
        T* freshBuffer = new T[newCapacity];
        for (size_t idx = 0; idx < currentSize; ++idx) {
            freshBuffer[idx] = elements[idx];
        }
        delete[] elements;
        elements = freshBuffer;
        allocatedCapacity = newCapacity;
    }

public:
    // Default constructor
    DynamicArray() : elements(nullptr), currentSize(0), allocatedCapacity(0) {}

    // Destructor
    ~DynamicArray() {
        delete[] elements;
    }

    // Copy constructor
    DynamicArray(const DynamicArray& source) 
        : currentSize(source.currentSize), allocatedCapacity(source.allocatedCapacity) {
        elements = new T[allocatedCapacity];
        for (size_t idx = 0; idx < currentSize; ++idx) {
            elements[idx] = source.elements[idx];
        }
    }

    // Copy assignment operator
    DynamicArray& operator=(const DynamicArray& source) {
        if (this != &source) {
            delete[] elements;
            currentSize = source.currentSize;
            allocatedCapacity = source.allocatedCapacity;
            elements = new T[allocatedCapacity];
            for (size_t idx = 0; idx < currentSize; ++idx) {
                elements[idx] = source.elements[idx];
            }
        }
        return *this;
    }

    // Move constructor
    DynamicArray(DynamicArray&& source) noexcept 
        : elements(source.elements), currentSize(source.currentSize), allocatedCapacity(source.allocatedCapacity) {
        source.elements = nullptr;
        source.currentSize = 0;
        source.allocatedCapacity = 0;
    }

    // Move assignment operator
    DynamicArray& operator=(DynamicArray&& source) noexcept {
        if (this != &source) {
            delete[] elements;
            elements = source.elements;
            currentSize = source.currentSize;
            allocatedCapacity = source.allocatedCapacity;
            source.elements = nullptr;
            source.currentSize = 0;
            source.allocatedCapacity = 0;
        }
        return *this;
    }

    // Access operators
    T& operator[](size_t position) {
        return elements[position];
    }

    const T& operator[](size_t position) const {
        return elements[position];
    }

    T& getAt(size_t position) {
        if (position >= currentSize) {
            throw std::out_of_range("Position out of bounds");
        }
        return elements[position];
    }

    const T& getAt(size_t position) const {
        if (position >= currentSize) {
            throw std::out_of_range("Position out of bounds");
        }
        return elements[position];
    }

    T& firstElement() {
        return elements[0];
    }

    const T& firstElement() const {
        return elements[0];
    }

    T& lastElement() {
        return elements[currentSize - 1];
    }

    const T& lastElement() const {
        return elements[currentSize - 1];
    }

    // Capacity information
    size_t length() const {
        return currentSize;
    }

    size_t storageSize() const {
        return allocatedCapacity;
    }

    bool isEmpty() const {
        return currentSize == 0;
    }

    // Modify array size
    void adjustSize(size_t newSize) {
        if (newSize > allocatedCapacity) {
            expandStorage(newSize);
        }
        currentSize = newSize;
    }

    // Add element at the end
    void append(const T& value) {
        if (currentSize == allocatedCapacity) {
            if (allocatedCapacity == 0) {
                expandStorage(1);
            } else {
                expandStorage(allocatedCapacity * 2);
            }
        }
        elements[currentSize++] = value;
    }

    // Iterator support
    T* start() {
        return elements;
    }

    const T* start() const {
        return elements;
    }

    T* finish() {
        return elements + currentSize;
    }

    const T* finish() const {
        return elements + currentSize;
    }
};

