  // Setup ESP-NOW protocol
  if (esp_now_init() != ESP_OK) {
    Serial.println("ESP-NOW init error");
    return;
  }

  // Attach receive handler
  esp_now_register_recv_cb(onEspNowDataReceived);

  // Create message queue for inter-task communication
  frameQueue = xQueueCreate(1, sizeof(FramePacket));

  // Add remote peer device
  esp_now_peer_info_t peerInfo = {};
  uint8_t peerMac[6] = {0xCA, 0xFE, 0xBA, 0xBE, 0xFA, 0xCE};
  memcpy(peerInfo.peer_addr, peerMac, 6);
  peerInfo.channel = ESP_NOW_CHAN;
  peerInfo.encrypt = false;

  if (esp_now_add_peer(&peerInfo) != ESP_OK) {
    Serial.println("Peer registration failed");
    return;
  }

  Serial.println("System initialized");
}

void loop() {
  FramePacket frame;

  // Acquire screen content via I2C from RP2040
  Wire.beginTransmission(I2C_ADDR_LCD);
  Wire.write(0x00); // Starting register address
  Wire.endTransmission(false);

  size_t bytesRead = Wire.requestFrom(I2C_ADDR_LCD, MAX_BUFFER_LEN);
  frame.length = bytesRead;
  Wire.readBytes(frame.payload, std::min(bytesRead, (size_t)MAX_BUFFER_LEN));

  // Queue the frame for transmission
  if (xQueueSend(frameQueue, &frame, portMAX_DELAY) != pdPASS) {
    Serial.println("Queueing failed");
  }

  vTaskDelay(pdMS_TO_TICKS(1000)); // Wait one second before next update
}

#include <iostream>
using namespace std;

// Definition for singly-linked list node
struct Node {
    int data;
    Node *link;
    Node(int x) : data(x), link(NULL) {}
};

// Detect if there's a loop in the linked list using Floyd's algorithm
bool detectLoop(Node *start) {
    // Handle empty list or single node without cycle
    if (start == NULL || start->link == NULL) {
        return false;
    }

    Node *runner = start;      // Fast pointer (moves 2 steps)
    Node *walker = start->link; // Slow pointer (moves 1 step)

    while (runner != NULL && runner->link != NULL) {
        if (runner == walker) {
            return true;  // Loop found
        }
        runner = runner->link->link;  // Advance fast pointer by two nodes
        walker = walker->link;        // Advance slow pointer by one node
    }

    return false;  // No loop detected
}

// Build a sample linked list containing a loop for verification
Node* buildSampleWithLoop() {
    Node *head = new Node(10);
    head->link = new Node(20);
    head->link->link = new Node(30);
    head->link->link->link = new Node(40);
    head->link->link->link->link = head->link;  // Introduce a cycle at second node
    return head;
}

// Run test to verify cycle detection functionality
void runCycleCheck() {
    Node *listHead = buildSampleWithLoop();
    if (detectLoop(listHead)) {
        cout << "Loop identified in the linked structure." << endl;
    } else {
        cout << "No loop found in the linked structure." << endl;
    }
}

int main() {
    runCycleCheck();
    return 0;
}

