#include <immintrin.h>

// Compute vector operations using AVX instructions
void calculate_attributes(float* array, float* c, float* d, int n) {
    __m256 vec_x, vec_y, vec_z, vec_sum, vec_diff;

    for (int idx = 0; idx < n; idx += 8) {
        // Load three consecutive elements from the input array
        vec_x = _mm256_loadu_ps(&array[idx * 3 + 0]);
        vec_y = _mm256_loadu_ps(&array[idx * 3 + 1]);
        vec_z = _mm256_loadu_ps(&array[idx * 3 + 2]);

        // Compute sum and difference using SIMD operations
        vec_sum = _mm256_add_ps(vec_x, vec_y);
        vec_diff = _mm256_sub_ps(vec_x, vec_z);

        // Store results to output arrays
        _mm256_storeu_ps(&c[idx], vec_sum);
        _mm256_storeu_ps(&d[idx], vec_diff);
    }
}

