// Transpose a 2D matrix by swapping rows and columns
vector<vector<int>> transpose(const vector<vector<int>>& matrix) {
    if (matrix.empty()) return {};

    int originalRows = matrix.size();
    int originalCols = matrix[0].size();

    // Create new matrix with swapped dimensions
    vector<vector<int>> result(originalCols, vector<int>(originalRows));

    // Fill the transposed matrix by iterating through original elements
    for (int row = 0; row < originalRows; ++row) {
        for (int col = 0; col < originalCols; ++col) {
            result[col][row] = matrix[row][col];
        }
    }

    return result;
}

