// Find the longest common substring between two strings
std::string findMaxCommonSubstr(const std::string& str1, const std::string& str2) {
    int len1 = str1.size();
    int len2 = str2.size();

    // Initialize DP table with zeros
    std::vector<std::vector<int>> table(len1 + 1, std::vector<int>(len2 + 1, 0));
    int maxLen = 0;
    int endPos = -1;

    // Build the DP table
    for (int i = 1; i <= len1; ++i) {
        for (int j = 1; j <= len2; ++j) {
            if (str1[i - 1] == str2[j - 1]) {
                table[i][j] = table[i - 1][j - 1] + 1;
                if (table[i][j] > maxLen) {
                    maxLen = table[i][j];
                    endPos = i - 1;
                }
            } else {
                table[i][j] = 0;
            }
        }
    }

    // Return the longest common substring if found
    if (maxLen > 0) {
        return str1.substr(endPos - maxLen + 1, maxLen);
    }

    return ""; // No common substring exists
}

int main() {
    std::string input1 = "ABABC";
    std::string input2 = "BABC";
    std::string commonPart = findMaxCommonSubstr(input1, input2);
    std::cout << "Longest Common Substring: " << commonPart << std::endl;
    return 0;
}

void ICategoryNode::iterate(ICategoryHandler& handler) const {
    // Early exit if no children exist
    if (m_children == nullptr) {
        return;
    }

    // Iterate through all children using while loop
    Uint32 index = 0;
    Uint32 childCount = m_children.size();
    while (index < childCount) {
        bool shouldContinue = CategoryImp::recursiveIterator(handler, *m_children[index]);
        if (!shouldContinue) {
            break;
        }
        ++index;
    }
}

