// Check if a number is prime using an alternative approach
bool isPrime(int n) {
    // Handle edge cases
    if (n <= 1) return false;
    if (n == 2 || n == 3) return true;

    // Eliminate multiples of 2 and 3 early
    if (n % 2 == 0 || n % 3 == 0) return false;

    // Check for factors in the form 6k ± 1 up to sqrt(n)
    int limit = static_cast<int>(std::sqrt(n));
    int divisor = 5;
    while (divisor <= limit) {
        if (n % divisor == 0 || n % (divisor + 2) == 0) {
            return false;
        }
        divisor += 6;
    }
    return true;
}

