LRESULT CALLBACK WindowProcedure(HWND hwnd, UINT message, WPARAM wParam, LPARAM lParam);

int WINAPI WinMain(HINSTANCE hInstance, HINSTANCE hPrevInstance, LPSTR lpCmdLine, int nShowCmd) {
    WNDCLASSEX wc = {0};
    wc.cbSize = sizeof(WNDCLASSEX);
    wc.lpfnWndProc = WindowProcedure;
    wc.hInstance = hInstance;
    wc.lpszClassName = L"CustomTitleBarWindow";
    wc.hCursor = LoadCursor(NULL, IDC_ARROW);
    RegisterClassEx(&wc);

    HWND hwnd = CreateWindowEx(0, L"CustomTitleBarWindow", L"Custom Title Bar", WS_OVERLAPPEDWINDOW,
                               CW_USEDEFAULT, CW_USEDEFAULT, 800, 600, NULL, NULL, hInstance, NULL);
    ShowWindow(hwnd, nShowCmd);
    UpdateWindow(hwnd);

    MSG message;
    while (GetMessage(&message, NULL, 0, 0)) {
        TranslateMessage(&message);
        DispatchMessage(&message);
    }

    return static_cast<int>(message.wParam);
}

LRESULT CALLBACK WindowProcedure(HWND hwnd, UINT message, WPARAM wParam, LPARAM lParam) {
    static MARGINS extendedMargins = {-1};
    static HBRUSH windowBrush = CreateSolidBrush(RGB(255, 255, 255));

    switch (message) {
    case WM_NCCALCSIZE:
        if (wParam == TRUE) {
            NCCALCSIZE_PARAMS* ncParams = reinterpret_cast<NCCALCSIZE_PARAMS*>(lParam);
            ncParams->rgrc[0].top += 35; // Extend title bar area slightly more
            return WVR_REDRAW;
        }
        break;

    case WM_NCPAINT:
        {
            HRGN region = (HRGN)wParam;
            HDC dc = GetWindowDC(hwnd);
            RECT windowRect;
            GetWindowRect(hwnd, &windowRect);
            windowRect.bottom = windowRect.top + 35; // Custom title bar height

            // Draw custom close button area
            RECT closeBtnRect = {windowRect.right - 55, windowRect.top, windowRect.right, windowRect.top + 35};
            HBRUSH btnBrush = CreateSolidBrush(RGB(180, 180, 240));
            FillRect(dc, &closeBtnRect, btnBrush);
            DeleteObject(btnBrush);

            // Add a soft glow effect around the button
            for (int step = 1; step <= 8; ++step) {
                RECT glowRect = {
                    closeBtnRect.left - step,
                    closeBtnRect.top - step,
                    closeBtnRect.right + step,
                    closeBtnRect.bottom + step
                };
                COLORREF glowColor = RGB(255, 255, 255 - step * 20);
                HBRUSH glowBrush = CreateSolidBrush(glowColor);
                FrameRect(dc, &glowRect, glowBrush);
                DeleteObject(glowBrush);
            }

            ReleaseDC(hwnd, dc);
        }
        return 0;

    case WM_NCLBUTTONDOWN:
        if (LOWORD(lParam) >= 745 && LOWORD(lParam) <= 800 &&
            HIWORD(lParam) >= 0 && HIWORD(lParam) <= 35) {
            MessageBox(hwnd, L"Custom Button Activated!", L"Notification", MB_OK | MB_ICONINFORMATION);
            return 0;
        }
        break;

    case WM_CREATE:
        DwmExtendFrameIntoClientArea(hwnd, &extendedMargins);
        break;

    case WM_DESTROY:
        PostQuitMessage(0);
        break;

    default:
        return DefWindowProc(hwnd, message, wParam, lParam);
    }

    return 0;
}

#include <openssl/aes.h>
#include <openssl/evp.h>
#include <string>
#include <vector>

std::string decrypt(const std::vector<uint8_t>& encryptedData, const std::vector<uint8_t>& secretKey, const std::vector<uint8_t>& initializationVector)
{
    EVP_CIPHER_CTX* context = EVP_CIPHER_CTX_new();
    if (!context) {
        // Error handling for context allocation failure
        return "";
    }

    if (EVP_DecryptInit_ex(context, EVP_aes_256_cbc(), nullptr, secretKey.data(), initializationVector.data()) != 1) {
        EVP_CIPHER_CTX_free(context);
        // Error handling for initialization failure
        return "";
    }

    std::vector<uint8_t> decryptedBuffer(encryptedData.size() + AES_BLOCK_SIZE);
    int processedBytes;
    if (EVP_DecryptUpdate(context, decryptedBuffer.data(), &processedBytes, encryptedData.data(), encryptedData.size()) != 1) {
        EVP_CIPHER_CTX_free(context);
        // Error handling for decryption update failure
        return "";
    }

    int finalProcessedBytes;
    if (EVP_DecryptFinal_ex(context, decryptedBuffer.data() + processedBytes, &finalProcessedBytes) != 1) {
        EVP_CIPHER_CTX_free(context);
        // Error handling for final decryption step failure
        return "";
    }

    EVP_CIPHER_CTX_free(context);

    decryptedBuffer.resize(processedBytes + finalProcessedBytes);
    return std::string(decryptedBuffer.begin(), decryptedBuffer.end());
}

