#include <cuda_runtime.h>
#include <iostream>

extern "C" {
    void cudaMultiply(int* a, int* b, int* c, int size) {
        int* dev_a = nullptr;
        int* dev_b = nullptr;
        int* dev_c = nullptr;

        // Allocate device memory for input and output arrays
        cudaMalloc((void**)&dev_a, size * sizeof(int));
        cudaMalloc((void**)&dev_b, size * sizeof(int));
        cudaMalloc((void**)&dev_c, size * sizeof(int));

        // Copy input data from host to device
        cudaMemcpy(dev_a, a, size * sizeof(int), cudaMemcpyHostToDevice);
        cudaMemcpy(dev_b, b, size * sizeof(int), cudaMemcpyHostToDevice);

        // Configure kernel launch parameters
        const int blockSize = 256;
        const int gridSize = (size + blockSize - 1) / blockSize;
        dim3 blockDim(blockSize);
        dim3 gridDim(gridSize);

        // Launch the multiplication kernel
        multiplyKernel<<<gridDim, blockDim>>>(dev_a, dev_b, dev_c, size);

        // Copy result back to host
        cudaMemcpy(c, dev_c, size * sizeof(int), cudaMemcpyDeviceToHost);

        // Free device memory
        cudaFree(dev_a);
        cudaFree(dev_b);
        cudaFree(dev_c);
    }

    __global__ void multiplyKernel(int* a, int* b, int* c, int size) {
        int idx = blockIdx.x * blockDim.x + threadIdx.x;
        if (idx < size) {
            c[idx] = a[idx] * b[idx];
        }
    }
}

