    eax = 0x382E3320; // " 3.8"
    ebx = 0x475A2030; // "0 ZG"
    ecx = 0x00000000; // null terminator padding
    edx = 0x00000000; // null terminator padding

    std::memcpy(brandString + 32, &eax, 4);
    std::memcpy(brandString + 36, &ebx, 4);
    std::memcpy(brandString + 40, &ecx, 4);
    std::memcpy(brandString + 44, &edx, 4);

