// Convert 64-bit integer from network byte order to host byte order
int64_t ntohll(int64_t value) {
    uint32_t high_part = static_cast<uint32_t>(value >> 32);
    uint32_t low_part = static_cast<uint32_t>(value & 0xFFFFFFFF);

    uint32_t converted_high = ntohl(low_part);
    uint32_t converted_low = ntohl(high_part);

    return (static_cast<int64_t>(converted_high) << 32) | converted_low;
}

// Convert 64-bit integer from host byte order to network byte order
int64_t htonll(int64_t value) {
    uint32_t high_part = static_cast<uint32_t>(value >> 32);
    uint32_t low_part = static_cast<uint32_t>(value & 0xFFFFFFFF);

    uint32_t converted_high = htonl(low_part);
    uint32_t converted_low = htonl(high_part);

    return (static_cast<int64_t>(converted_high) << 32) | converted_low;
}

