#include <cstring>

// Function to create and populate a SAFEARRAY of bytes
HRESULT __stdcall TestSafeArray(SAFEARRAY** ppData)
{
    // Validate input pointer
    if (ppData == nullptr)
    {
        return E_POINTER;
    }

    *ppData = nullptr;

    // Create a SAFEARRAY of unsigned 1-byte integers (VT_UI1)
    SAFEARRAY* psa = SafeArrayCreateVector(VT_UI1, 0, 5);
    if (psa == nullptr)
    {
        return E_OUTOFMEMORY;
    }

    // Prepare data to copy into the array
    BYTE buffer[] = { 1, 2, 3, 4, 5 };

    // Lock the array for direct memory access
    HRESULT hr = SafeArrayLock(psa);
    if (FAILED(hr))
    {
        SafeArrayDestroy(psa);
        return hr;
    }

    // Copy the data into the locked array
    memcpy(psa->pvData, buffer, sizeof(buffer));

    // Unlock the array after modification
    SafeArrayUnlock(psa);

    // Return the created array to the caller
    *ppData = psa;
    return S_OK;
}

