// Function to enumerate available serial ports from the Windows registry
std::vector<std::string> getSerialPorts() {
    HKEY hKey;
    LONG status = RegOpenKeyExA(HKEY_LOCAL_MACHINE, 
                                "HARDWARE\\DEVICEMAP\\SERIALCOMM", 
                                0, 
                                KEY_READ, 
                                &hKey);

    if (status != ERROR_SUCCESS) {
        return {};
    }

    std::vector<std::string> portsList;
    char nameBuffer[1024];
    char dataBuffer[1024];
    DWORD nameLength = sizeof(nameBuffer);
    DWORD dataLength = sizeof(dataBuffer);
    DWORD type;

    for (DWORD index = 0; ; ++index) {
        nameLength = sizeof(nameBuffer);
        dataLength = sizeof(dataBuffer);

        status = RegEnumValueA(hKey, 
                               index, 
                               nameBuffer, 
                               &nameLength, 
                               nullptr, 
                               &type, 
                               reinterpret_cast<BYTE*>(dataBuffer), 
                               &dataLength);

        if (status != ERROR_SUCCESS) {
            break;
        }

        if (type == REG_SZ) {
            portsList.emplace_back(dataBuffer);
        }
    }

    RegCloseKey(hKey);
    return portsList;
}

int main() {
    auto serialPorts = getSerialPorts();
    for (const auto& port : serialPorts) {
        std::cout << port << '\n';
    }
    return 0;
}

