using namespace std;

// Determine if a graph is bipartite using BFS coloring
bool checkBipartite(int vertexCount, vector<vector<int>>& adjacencyList) {
    vector<int> nodeColor(vertexCount, -1); // -1: uncolored, 0: first group, 1: second group

    for (int startNode = 0; startNode < vertexCount; ++startNode) {
        if (nodeColor[startNode] == -1) {
            nodeColor[startNode] = 0;
            queue<int> bfsQueue;
            bfsQueue.push(startNode);

            while (!bfsQueue.empty()) {
                int currentNode = bfsQueue.front();
                bfsQueue.pop();

                for (int neighbor : adjacencyList[currentNode]) {
                    if (nodeColor[neighbor] == -1) {
                        nodeColor[neighbor] = 1 - nodeColor[currentNode];
                        bfsQueue.push(neighbor);
                    } else if (nodeColor[neighbor] == nodeColor[currentNode]) {
                        return false;
                    }
                }
            }
        }
    }
    return true;
}

int main() {
    int n, edges;
    while (cin >> n && n != 0) {
        cin >> edges;
        vector<vector<int>> graph(n);

        for (int i = 0; i < edges; ++i) {
            int u, v;
            cin >> u >> v;
            u--; v--;
            graph[u].push_back(v);
            graph[v].push_back(u);
        }

        if (checkBipartite(n, graph)) {
            cout << "Possible" << endl;
        } else {
            cout << "Not possible" << endl;
        }
    }

    return 0;
}

