// Derive key and IV using a custom key derivation function based on MD5
std::vector<unsigned char> deriveKeyAndIV(const std::string& pass, const std::string& saltBytes, int keyLen, int ivLen)
{
    Poco::Crypto::MD5Engine hasher;
    std::vector<unsigned char> inputBuffer(pass.begin(), pass.end());
    inputBuffer.insert(inputBuffer.end(), saltBytes.begin(), saltBytes.end());

    std::vector<unsigned char> result;
    int iteration = 1;

    while (static_cast<int>(result.size()) < keyLen + ivLen)
    {
        hasher.update(inputBuffer);
        std::vector<unsigned char> digest = hasher.digest();
        result.insert(result.end(), digest.begin(), digest.end());

        // XOR password portion of input with current iteration counter
        for (size_t j = 0; j < pass.size(); ++j)
        {
            inputBuffer[j] ^= static_cast<unsigned char>(iteration);
        }
        ++iteration;
    }

    return result;
}

int main()
{
    // Open encrypted file in binary mode
    std::ifstream inputFile(FILE_TO_DECRYPT, std::ios::binary);
    if (!inputFile) {
        std::cerr << "Failed to open file" << std::endl;
        return 1;
    }

    // Determine file size and read contents
    inputFile.seekg(0, std::ios::end);
    std::streampos fileSize = inputFile.tellg();
    inputFile.seekg(0, std::ios::beg);

    std::vector<char> fileData(fileSize);
    inputFile.read(fileData.data(), fileSize);

    // Extract salt from bytes 8-15 (8 bytes)
    std::string fileContent(fileData.begin(), fileData.end());
    std::string extractedSalt = fileContent.substr(8, 8);

    // Derive key (128 bits = 16 bytes) and IV (128 bits = 16 bytes)
    std::vector<unsigned char> derived = deriveKeyAndIV(PASSWORD, extractedSalt, 16, 16);

    // Split derived data into key and IV parts
    std::vector<unsigned char> aesKey(derived.begin(), derived.begin() + 16);
    std::vector<unsigned char> initVector(derived.begin() + 16, derived.begin() + 32);

    // Set up cipher using AES-128-CBC
    Poco::Crypto::CipherFactory& factoryRef = Poco::Crypto::CipherFactory::defaultFactory();
    Poco::Crypto::CipherKey keyObj("aes-128-cbc", aesKey, initVector);
    std::unique_ptr<Poco::Crypto::Cipher> pCipher = factoryRef.createCipher(keyObj);

    // Decrypt data starting after header (skip first 16 bytes: magic + salt)
    std::string ciphertext = fileContent.substr(16);
    std::string plaintext = pCipher->decryptString(ciphertext);

    std::cout << "Decrypted content: " << plaintext << std::endl;

    return 0;
}

