std::vector<Point3D> loadPoints(const std::string& filepath) {
    std::vector<Point3D> points;
    std::ifstream input(filepath);
    if (!input.is_open()) {
        std::cerr << "Error: Unable to open file " << filepath << std::endl;
        return points;
    }

    std::string line;
    while (std::getline(input, line)) {
        // Check for vertex lines starting with "v "
        if (line.length() >= 2 && line[0] == 'v' && line[1] == ' ') {
            Point3D point;
            std::sscanf(line.c_str(), "v %f %f %f", &point.x, &point.y, &point.z);
            points.push_back(point);
        }
    }
    return points;
}

std::vector<Triangle> loadTriangles(const std::string& filepath) {
    std::vector<Triangle> triangles;
    std::ifstream input(filepath);
    if (!input.is_open()) {
        std::cerr << "Error: Unable to open file " << filepath << std::endl;
        return triangles;
    }

    std::string line;
    while (std::getline(input, line)) {
        // Check for face lines starting with "f "
        if (line.length() >= 2 && line[0] == 'f' && line[1] == ' ') {
            Triangle triangle;
            std::sscanf(line.c_str(), "f %d %d %d", &triangle.p1, &triangle.p2, &triangle.p3);
