// Check if character is an arithmetic operator
bool isArithmeticOperator(char ch) {
    return ch == '+' || ch == '-' || ch == '*' || ch == '/' || ch == '^';
}

// Determine operator precedence level
int getPrecedenceLevel(char op) {
    switch (op) {
        case '+':
        case '-':
            return 1;
        case '*':
        case '/':
            return 2;
        case '^':
            return 3;
        default:
            return 0;
    }
}

// Transform infix notation to postfix notation
std::string convertToPostfix(const std::string& inputExpression) {
    std::stack<char> operatorStack;
    std::string outputString;

    for (char currentChar : inputExpression) {
        if (std::isdigit(currentChar)) {
            outputString += currentChar;
        } else if (isArithmeticOperator(currentChar)) {
            while (!operatorStack.empty() && 
                   getPrecedenceLevel(operatorStack.top()) >= getPrecedenceLevel(currentChar)) {
                outputString += operatorStack.top();
                operatorStack.pop();
            }
            operatorStack.push(currentChar);
        } else if (currentChar == '(') {
            operatorStack.push(currentChar);
        } else if (currentChar == ')') {
            while (!operatorStack.empty() && operatorStack.top() != '(') {
                outputString += operatorStack.top();
                operatorStack.pop();
            }
            if (operatorStack.empty() || operatorStack.top() != '(') {
                throw std::runtime_error("Parentheses mismatch detected");
            }
            operatorStack.pop(); // Remove the opening parenthesis
        }
    }

    // Pop remaining operators from stack
    while (!operatorStack.empty()) {
        if (operatorStack.top() == '(') {
            throw std::runtime_error("Parentheses mismatch detected");
        }
        outputString += operatorStack.top();
        operatorStack.pop();
    }

    return outputString;
}

// Compute result of postfix expression
double computePostfixResult(const std::string& postfixExpr) {
    std::stack<double> evaluationStack;

    for (char token : postfixExpr) {
        if (std::isdigit(token)) {
            evaluationStack.push(token - '0');
        } else if (isArithmeticOperator(token)) {
            if (evaluationStack.size() < 2) {
                throw std::runtime_error("Malformed expression");
            }

            double operand2 = evaluationStack.top(); evaluationStack.pop();
            double operand1 = evaluationStack.top(); evaluationStack.pop();

            switch (token) {
                case '+': evaluationStack.push(operand1 + operand2); break;
                case '-': evaluationStack.push(operand1 - operand2); break;
                case '*': evaluationStack.push(operand1 * operand2); break;
                case '/': 
                    if (operand2 == 0.0) throw std::runtime_error("Division by zero");
                    evaluationStack.push(operand1 / operand2); 
                    break;
                case '^': evaluationStack.push(std::pow(operand1, operand2)); break;
            }
        }
    }

    if (evaluationStack.size() != 1) {
        throw std::runtime_error("Malformed expression");
    }

    return evaluationStack.top();
}

// Main evaluation function that orchestrates conversion and computation
double calculateExpression(const std::string& expr) {
    std::string postfixForm = convertToPostfix(expr);
    return computePostfixResult(postfixForm);
}

int main() {
    std::string mathExpr = "3 + 5 * (2 - 4)";
    try {
        double computedValue = calculateExpression(mathExpr);
        std::cout << "Computed value: " << computedValue << std::endl;
    } catch (const std::exception& err) {
        std::cerr << "Exception occurred: " << err.what() << std::endl;
    }
    return 0;
}

