// Function to find the minimum and maximum values in a vector
std::pair<int, int> locateExtremes(const std::vector<int>& data) {
    if (data.empty()) {
        throw std::invalid_argument("Input vector is empty");
    }

    int smallest = std::numeric_limits<int>::max();
    int largest = std::numeric_limits<int>::min();

    for (size_t index = 0; index < data.size(); ++index) {
        int current = data[index];
        if (current < smallest) {
            smallest = current;
        }
        if (current > largest) {
            largest = current;
        }
    }

    return std::make_pair(smallest, largest);
}

int main() {
    std::vector<int> numbers = {3, 1, 4, 1, 5, 9, 2, 6, 5, 3, 5};
    auto extremes = locateExtremes(numbers);

    std::cout << "Minimum: " << extremes.first << std::endl;
    std::cout << "Maximum: " << extremes.second << std::endl;

    return 0;
}

