// Compute the average of a non-empty vector of doubles
double computeAverage(const std::vector<double>& values) {
    if (values.empty()) {
        throw std::invalid_argument("Input collection cannot be empty.");
    }
    double total = std::accumulate(values.begin(), values.end(), 0.0);
    return total / static_cast<double>(values.size());
}

// Calculate the population variance given the data and its mean
double computePopulationVariance(const std::vector<double>& values, double avg) {
    double squaredDiffSum = 0.0;
    for (size_t idx = 0; idx < values.size(); ++idx) {
        double diff = values[idx] - avg;
        squaredDiffSum += diff * diff;
    }
    return squaredDiffSum / static_cast<double>(values.size());
}

// Determine the population standard deviation for at least two data points
double computeStdDeviation(const std::vector<double>& dataset) {
    if (dataset.size() < 2) {
        throw std::invalid_argument("At least two data points are required.");
    }
    double avg = computeAverage(dataset);
    double popVar = computePopulationVariance(dataset, avg);
    return std::sqrt(popVar);
}

int main() {
    try {
        std::vector<double> dataset = {2.5, 3.5, 4.0, 5.5, -1.0, 0.25};
        double result = computeStdDeviation(dataset);
        std::cout << "The standard deviation is: " << result << std::endl;
    } catch (const std::exception& err) {
        std::cerr << "Exception occurred: " << err.what() << std::endl;
    }
    return 0;
}

