    }

    int bestIndex = 0;
    int currentIndex = 1;

    while (currentIndex < static_cast<int>(data.size())) {
        if (data[currentIndex] > data[bestIndex]) {
            bestIndex = currentIndex;
        }
        currentIndex++;
    }

    return bestIndex;
}

