#include <iostream>
#include <cmath>

class ThreeDVector {
public:
    // Constructor with default values
    ThreeDVector(double a = 0.0, double b = 0.0, double c = 0.0) : x_val(a), y_val(b), z_val(c) {}

    // Destructor
    ~ThreeDVector() {}

    // Getters for coordinates
    double getX() const { return x_val; }
    double getY() const { return y_val; }
    double getZ() const { return z_val; }

    // Setters for coordinates
    void setX(double a) { x_val = a; }
    void setY(double b) { y_val = b; }
    void setZ(double c) { z_val = c; }

    // Scale the vector by a factor
    ThreeDVector multiplyByScalar(double factor) const {
        return ThreeDVector(x_val * factor, y_val * factor, z_val * factor);
    }

    // Normalize the vector (make unit length)
    ThreeDVector getUnitVector() const {
        double magnitude = std::sqrt(x_val * x_val + y_val * y_val + z_val * z_val);
        if (magnitude > 1e-12) { // Avoid division by near-zero
            return ThreeDVector(x_val / magnitude, y_val / magnitude, z_val / magnitude);
        }
        return *this;
    }

    // Add another vector to this one
    ThreeDVector combineWith(const ThreeDVector& other) const {
        return ThreeDVector(x_val + other.x_val, y_val + other.y_val, z_val + other.z_val);
    }

    // Display the vector components
    void show() const {
        std::cout << "ThreeDVector(" << x_val << ", " << y_val << ", " << z_val << ")" << std::endl;
    }

private:
    double x_val, y_val, z_val;
};

// Demonstration of the class functionality
int main() {
    ThreeDVector vecA(1.0, 2.0, 3.0);
    ThreeDVector vecB(4.0, 5.0, 6.0);

    std::cout << "vecA: ";
    vecA.show();

    std::cout << "vecB: ";
    vecB.show();

    ThreeDVector scaledVec = vecA.multiplyByScalar(2.0);
    std::cout << "vecA multiplied by 2.0: ";
    scaledVec.show();

    ThreeDVector unitVec = vecA.getUnitVector();
    std::cout << "Unit vector of vecA: ";
    unitVec.show();

    ThreeDVector combinedVec = vecA.combineWith(vecB);
    std::cout << "vecA + vecB: ";
    combinedVec.show();

    return 0;
}

