// Structure definition for binary tree node
struct BinaryNode {
    int data;
    BinaryNode* leftChild;
    BinaryNode* rightChild;

    BinaryNode(int value) : data(value), leftChild(nullptr), rightChild(nullptr) {}
};

// Helper function to determine if two subtrees are symmetric (mirror images)
bool checkSymmetry(BinaryNode* nodeA, BinaryNode* nodeB) {
    // Both nodes are null: symmetric
    if (nodeA == nullptr && nodeB == nullptr) 
        return true;

    // One is null, the other isn't: not symmetric
    if (nodeA == nullptr || nodeB == nullptr) 
        return false;

    // Values must match and children must be mirror images
    return (nodeA->data == nodeB->data) &&
           checkSymmetry(nodeA->leftChild, nodeB->rightChild) &&
           checkSymmetry(nodeA->rightChild, nodeB->leftChild);
}

// Main function to verify if the entire tree is symmetric
bool isTreeSymmetric(BinaryNode* root) {
    return checkSymmetry(root, root);
}

// Utility function to allocate a new tree node
BinaryNode* newNode(int value) {
    return new BinaryNode(value);
}

// Test function to validate symmetry detection
void runSymmetryTest() {
    // Construct test tree:
    //       1
    //      / \
    //     2   2
    //    / \ / \
    //   3  4 4  3
    BinaryNode* root = newNode(1);
    root->leftChild = newNode(2);
    root->rightChild = newNode(2);
    root->leftChild->leftChild = newNode(3);
    root->leftChild->rightChild = newNode(4);
    root->rightChild->leftChild = newNode(4);
