// Determine if a number is a power of two using bit manipulation
bool is_power_of_two(int n) {
    // Negative numbers and zero cannot be powers of two
    if (n <= 0) {
        return false;
    }

    // A power of two has exactly one bit set in binary representation
    // Using the property: n & (n - 1) clears the lowest set bit
    // If n is a power of two, it has only one bit set, so n & (n - 1) should be 0
    return (n & (n - 1)) == 0;
}

int main() {
    // Test cases for powers of two
    assert(is_power_of_two(1) == true);   // 2^0 = 1
    assert(is_power_of_two(2) == true);   // 2^1 = 2
    assert(is_power_of_two(3) == false);  // Not a power of two
    assert(is_power_of_two(4) == true);   // 2^2 = 4
    assert(is_power_of_two(16) == true);  // 2^4 = 16
    assert(is_power_of_two(17) == false); // Not a power of two

    std::cout << "All tests passed!" << std::endl;
    return 0;
}

#include <vector>

// Perform binary search on a sorted vector to find the index of target
int binary_search(const std::vector<int>& data, int value) {
    int start = 0;
    int end = static_cast<int>(data.size()) - 1;

    while (start <= end) {
        int middle = start + (end - start) / 2;
        if (data[middle] == value) {
            return middle;
        } else if (data[middle] < value) {
            start = middle + 1;
        } else {
            end = middle - 1;
        }
    }

    return -1; // Value not present in the vector
}

