// Function to extract query parameters from a URL
std::unordered_map<std::string, std::string> extractQueryParams(const std::string& urlString)
{
    std::unordered_map<std::string, std::string> resultMap;

    // Locate the start of query string
    size_t questionMarkPos = urlString.find('?');
    if (questionMarkPos != std::string::npos) {
        std::string queryString = urlString.substr(questionMarkPos + 1);

        // Process each parameter
        size_t currentIndex = 0;
        while (currentIndex < queryString.length()) {
            size_t ampersandPos = queryString.find('&', currentIndex);
            if (ampersandPos == std::string::npos)
                ampersandPos = queryString.length();

            std::string currentPair = queryString.substr(currentIndex, ampersandPos - currentIndex);

            // Split key-value pair
            size_t equalsPos = currentPair.find('=');
            if (equalsPos != std::string::npos) {
                std::string paramKey = currentPair.substr(0, equalsPos);
                std::string paramValue = currentPair.substr(equalsPos + 1);

                // Decode %20 sequences in the value
                size_t decodePos = paramValue.find("%20");
                while (decodePos != std::string::npos) {
                    paramValue.replace(decodePos, 3, " ");
                    decodePos = paramValue.find("%20", decodePos + 1);
                }

                resultMap[paramKey] = paramValue;
            }

            currentIndex = ampersandPos + 1;
        }
    }

    return resultMap;
}

int main()
{
    std::string testUrl = "http://www.example.com?name=John%20Doe&age=25&city=New%20York";

    std::unordered_map<std::string, std::string> parsedData = extractQueryParams(testUrl);

    // Output the results
    for (const auto& entry : parsedData) {
        std::cout << entry.first << ": " << entry.second << std::endl;
    }

    return 0;
}

