// Macro for CUDA error checking
#define CUDA_CHECK(call) \
    do { \
        cudaError_t status = call; \
        if (status != cudaSuccess) { \
            std::cerr << "CUDA Error: " << cudaGetErrorString(status) \
                      << " in " << __FILE__ << " at line " << __LINE__ << std::endl; \
