// Matrix dimensions and block size configuration
const int MATRIX_DIM = 1024;
const int THREAD_BLOCK = 16;

// Kernel function to compute matrix multiplication with progress tracking
__global__ void matrixMultiplyKernel(const float* __restrict__ inputA,
                                     const float* __restrict__ inputB,
                                     float* __restrict__ outputC,
                                     int dimension,
                                     int* __restrict__ counter) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < dimension && col < dimension) {
        float accumulator = 0.0f;
        for (int k = 0; k < dimension; ++k) {
            accumulator += inputA[row * dimension + k] * inputB[k * dimension + col];
        }
        outputC[row * dimension + col] = accumulator;

        // Atomically increment the global progress counter
        atomicAdd(counter, 1);
    }
}

// Display progress percentage on console
void showProgress(int completed, int total) {
    int percent = (completed * 100) / total;
    fprintf(stdout, "\rProgress: %d.%02d%%", percent / 1, percent % 1);
    fflush(stdout);
}

int main() {
    float *hostA, *hostB, *hostC;
    float *deviceA, *deviceB, *deviceC;
    int *hostCounter, *deviceCounter;

    size_t matrixBytes = MATRIX_DIM * MATRIX_DIM * sizeof(float);
    size_t counterBytes = sizeof(int);

    // Allocate host memory
    hostA = static_cast<float*>(malloc(matrixBytes));
    hostB = static_cast<float*>(malloc(matrixBytes));
    hostC = static_cast<float*>(malloc(matrixBytes));
    hostCounter = static_cast<int*>(malloc(counterBytes));

    // Initialize matrices with constant values for deterministic testing
    for (int i = 0; i < MATRIX_DIM * MATRIX_DIM; ++i) {
        hostA[i] = 1.0f;
        hostB[i] = 1.0f;
        hostC[i] = 0.0f;
    }

    // Allocate device memory
    CUDA_CHECK(cudaMalloc(&deviceA, matrixBytes));
    CUDA_CHECK(cudaMalloc(&deviceB, matrixBytes));
    CUDA_CHECK(cudaMalloc(&deviceC, matrixBytes));
    CUDA_CHECK(cudaMalloc(&deviceCounter, counterBytes));

    // Transfer initial data to GPU
    CUDA_CHECK(cudaMemcpy(deviceA, hostA, matrixBytes, cudaMemcpyHostToDevice));
    CUDA_CHECK(cudaMemcpy(deviceB, hostB, matrixBytes, cudaMemcpyHostToDevice));
    CUDA_CHECK(cudaMemset(deviceCounter, 0, counterBytes));

    // Configure execution parameters
    dim3 threadsPerBlock(THREAD_BLOCK, THREAD_BLOCK);
    dim3 blocksPerGrid((MATRIX_DIM + THREAD_BLOCK - 1) / THREAD_BLOCK,
                       (MATRIX_DIM + THREAD_BLOCK - 1) / THREAD_BLOCK);

    // Create stream for asynchronous operations
    cudaStream_t workStream;
    CUDA_CHECK(cudaStreamCreate(&workStream));

    // Compute progress update interval (every 1%)
    int totalTasks = MATRIX_DIM * MATRIX_DIM;
    int stepSize = totalTasks / 100;

    // Launch kernel multiple times to simulate incremental progress updates
    for (int processed = 0; processed < totalTasks; processed += stepSize) {
        matrixMultiplyKernel<<<blocksPerGrid, threadsPerBlock, 0, workStream>>>(
            deviceA, deviceB, deviceC, MATRIX_DIM, deviceCounter
        );
        CUDA_CHECK(cudaStreamSynchronize(workStream));

        // Retrieve current progress from device
        CUDA_CHECK(cudaMemcpy(hostCounter, deviceCounter, counterBytes, cudaMemcpyDeviceToHost));
        showProgress(*hostCounter, totalTasks);
    }

    // Ensure final completion and copy results back
    CUDA_CHECK(cudaStreamSynchronize(workStream));
    CUDA_CHECK(cudaMemcpy(hostC, deviceC, matrixBytes, cudaMemcpyDeviceToHost));

    // Cleanup resources
    free(hostA);
    free(hostB);
    free(hostC);
    free(hostCounter);
    CUDA_CHECK(cudaFree(deviceA));
    CUDA_CHECK(cudaFree(deviceB));
    CUDA_CHECK(cudaFree(deviceC));
    CUDA_CHECK(cudaFree(deviceCounter));
    CUDA_CHECK(cudaStreamDestroy(workStream));

    return 0;
}

#include <cstddef>

void add_arrays(char* digits, const char* rhs_digits, size_t length) {
    char remainder = 0;

    for (size_t idx = 0; idx < length; ++idx) {
        char temp = digits[idx];
        temp += rhs_digits[idx];

        if (temp >= 16) {
            temp -= 16;
            remainder = 1;
        } else if (remainder) {
            temp += 1;
            if (temp >= 16) {
                temp -= 16;
                remainder = 1;
            } else {
                remainder = 0;
            }
        }

        digits[idx] = temp;
    }
}

