    std::string toString() const {
        return rankToString(rank) + " of " + suitToString(suit);
    }
};

// Function to create a standard deck of 52 cards using iterators instead of indices
std::vector<Card> createDeck() {
    std::vector<Card> deck;
    deck.reserve(52); // Pre-allocate memory for efficiency

    for (int s = static_cast<int>(Suit::Clubs); s <= static_cast<int>(Suit::Spades); ++s) {
        for (int r = static_cast<int>(Rank::Two); r <= static_cast<int>(Rank::Ace); ++r) {
            deck.emplace_back(static_cast<Suit>(s), static_cast<Rank>(r));
        }
    }
    return deck;
