#include <vector>
#include <string>

class Solution {
public:
    std::vector<std::string> removeComments(std::vector<std::string>& source) {
        std::vector<std::string> filtered_lines;
        bool inside_block_comment = false;
        std::string processed_line;

        for (const auto& input_line : source) {
            // Start a new line only if not inside a block comment
            if (!inside_block_comment) {
                processed_line.clear();
            }

            size_t index = 0;
            while (index < input_line.length()) {
                if (inside_block_comment) {
                    // Check for end of block comment
                    if (index + 1 < input_line.length() && 
                        input_line[index] == '*' && 
                        input_line[index + 1] == '/') {
                        inside_block_comment = false;
                        index += 2; // Skip both '*' and '/'
                        continue;
                    }
                    index++;
                } else {
                    // Check for start of block comment
                    if (index + 1 < input_line.length() && 
                        input_line[index] == '/' && 
                        input_line[index + 1] == '*') {
                        inside_block_comment = true;
                        index += 2; // Skip both '/' and '*'
                        continue;
                    }
                    // Check for line comment
                    if (index + 1 < input_line.length() && 
                        input_line[index] == '/' && 
                        input_line[index + 1] == '/') {
                        break; // Ignore the rest of the line
                    }
                    // Add current character to processed line
                    processed_line += input_line[index];
                    index++;
                }
            }

            // Add non-empty lines that are not inside a block comment
            if (!inside_block_comment && !processed_line.empty()) {
                filtered_lines.push_back(processed_line);
            }
        }

        return filtered_lines;
    }
};

#include <cuda_runtime.h>

// Kernel to read texture with boundary check and write to global memory
__global__ void processTexture(cudaTextureObject_t texObj, float* output, int width, int height, float borderValue) {
    int x = blockIdx.x * blockDim.x + threadIdx.x;
    int y = blockIdx.y * blockDim.y + threadIdx.y;

    if (x >= 0 && x < width && y >= 0 && y < height) {
        // Compute texture coordinates
        float u = static_cast<float>(x);
        float v = static_cast<float>(y);

        // Sample the texture
        float pixelValue = tex2D<float>(texObj, u, v);

        // Validate coordinate bounds for texture access
        bool inBounds = (u >= 0.0f && u < static_cast<float>(width) &&
                         v >= 0.0f && v < static_cast<float>(height));

        // Apply border value if out of bounds
        if (!inBounds) {
            pixelValue = borderValue;
        }

        // Write result to output array
        output[y * width + x] = pixelValue;
    }
}

