// Compute Euclidean distance between two 3D points
double compute_distance(const std::vector<double>& a, const std::vector<double>& b) {
    double dx = a[0] - b[0];
    double dy = a[1] - b[1];
    double dz = a[2] - b[2];
    return std::sqrt(dx * dx + dy * dy + dz * dz);
}

// Evaluate system energy as negative of smallest pairwise distance
double evaluate_energy(const std::vector<std::vector<double>>& positions) {
    double min_separation = std::numeric_limits<double>::max();
    for (size_t i = 0; i < positions.size(); ++i) {
        for (size_t j = i + 1; j < positions.size(); ++j) {
            double separation = compute_distance(positions[i], positions[j]);
            if (separation < min_separation) {
                min_separation = separation;
            }
        }
    }
    return -min_separation; // Minimize negative => maximize minimum distance
}

// Generate uniformly random point on unit sphere surface
std::vector<double> generate_spherical_point() {
    static std::mt19937 rng{std::random_device{}()};
    static std::normal_distribution<> normal(0.0, 1.0);

    double x = normal(rng);
    double y = normal(rng);
    double z = normal(rng);
    double magnitude = std::sqrt(x*x + y*y + z*z);

    return {x/magnitude, y/magnitude, z/magnitude};
}

// Apply small random displacement and re-normalize to unit sphere
std::vector<double> displace_point(const std::vector<double>& original, double step_size) {
    static std::mt19937 rng{std::random_device{}()};
    static std::uniform_real_distribution<> uniform(-step_size, step_size);

    std::vector<double> displaced = original;
    for (auto& coord : displaced) {
        coord += uniform(rng);
    }

    double magnitude = std::sqrt(displaced[0]*displaced[0] +
                                 displaced[1]*displaced[1] +
                                 displaced[2]*displaced[2]);

    for (auto& coord : displaced) {
        coord /= magnitude;
    }
    return displaced;
}

// Simulated annealing optimizer for point distribution
std::vector<std::vector<double>> optimize_positions(int count,
                                                    double start_temp,
                                                    double decay_factor,
                                                    int max_steps) {
    std::vector<std::vector<double>> current_positions;
    for (int i = 0; i < count; ++i) {
        current_positions.push_back(generate_spherical_point());
    }

    double current_temperature = start_temp;
    for (int step = 0; step < max_steps; ++step) {
        std::vector<std::vector<double>> candidate_positions = current_positions;
        for (auto& pos : candidate_positions) {
            pos = displace_point(pos, 0.1);
        }

        double current_score = evaluate_energy(current_positions);
        double candidate_score = evaluate_energy(candidate_positions);

        double delta_energy = current_score - candidate_score;
        double acceptance_chance = std::exp(delta_energy / current_temperature);

        bool accept_move = false;
        if (candidate_score > current_score) {
            accept_move = true;
        } else if (static_cast<double>(std::rand()) / RAND_MAX < acceptance_chance) {
            accept_move = true;
        }

        if (accept_move) {
            current_positions = candidate_positions;
        }

        current_temperature *= decay_factor;
    }

    return current_positions;
}

int main() {
    int particle_count = 5;
    double starting_temperature = 1.0;
    double cooling_coefficient = 0.99;
    int iteration_limit = 10000;

    std::vector<std::vector<double>> optimized_points = 
        optimize_positions(particle_count, starting_temperature, 
                          cooling_coefficient, iteration_limit);

    for (const auto& location : optimized_points) {
        std::cout << "Position: (" << location[0] << ", " 
                  << location[1] << ", " << location[2] << ")\n";
    }

    return 0;
}

#include <cmath>
#include <memory>

// Base class for covariance kernels
class CovarianceKernel {
public:
    virtual ~CovarianceKernel() = default;
    virtual double computeCovariance(double input1, double input2) const = 0;
    virtual std::unique_ptr<CovarianceKernel> duplicate() const = 0;
};

// Gaussian (RBF) kernel implementation
class RbfKernel : public CovarianceKernel {
public:
    RbfKernel(double bandwidth, double amplitude) 
        : m_bandwidth(bandwidth), m_amplitude(amplitude) {}

    RbfKernel(double bandwidth) 
        : m_bandwidth(bandwidth), m_amplitude(1.0) {}

    double computeCovariance(double input1, double input2) const override {
        double diff = input1 - input2;
        return m_amplitude * std::exp(-(diff * diff) / (m_bandwidth * m_bandwidth));
    }

    std::unique_ptr<CovarianceKernel> duplicate() const override {
        return std::make_unique<RbfKernel>(*this);
    }

private:
    double m_bandwidth;
    double m_amplitude;
};

// Composite kernel that combines two kernels additively
class SumKernel : public CovarianceKernel {
public:
    SumKernel(std::unique_ptr<CovarianceKernel> first, 
              std::unique_ptr<CovarianceKernel> second)
        : firstKernel_(std::move(first)), secondKernel_(std::move(second)) {}

    double computeCovariance(double input1, double input2) const override {
        return firstKernel_->computeCovariance(input1, input2) + 
               secondKernel_->computeCovariance(input1, input2);
    }

    std::unique_ptr<CovarianceKernel> duplicate() const override {
        return std::make_unique<SumKernel>(
            firstKernel_->duplicate(), 
            secondKernel_->duplicate()
        );
    }

private:
    std::unique_ptr<CovarianceKernel> firstKernel_;
    std::unique_ptr<CovarianceKernel> secondKernel_;
};

// Demonstration of kernel usage
int main() {
    auto kernelA = std::make_unique<RbfKernel>(1.0, 1.0);
    auto kernelB = std::make_unique<RbfKernel>(2.0, 1.0);
    auto combinedKernel = std::make_unique<SumKernel>(
        std::move(kernelA), 
        std::move(kernelB)
    );

    double pointX = 0.5;
    double pointY = 0.7;
    double covValue = combinedKernel->computeCovariance(pointX, pointY);

    // The computed covariance value can now be used in further calculations
    return 0;
}

#include <iostream>
#include <cmath>

// Two-dimensional vector class with basic operations
class Vector2D {
public:
    // Initialize vector components
    Vector2D(double xVal = 0.0, double yVal = 0.0) : xPos(xVal), yPos(yVal) {}

    // Retrieve coordinates
    double getXPos() const { return xPos; }
    double getYPos() const { return yPos; }

    // Update coordinates
    void setXPos(double newX) { xPos = newX; }
    void setYPos(double newY) { yPos = newY; }

    // Add two vectors
    Vector2D operator+(const Vector2D& rhs) const {
        return Vector2D(xPos + rhs.xPos, yPos + rhs.yPos);
    }

    // Subtract two vectors
    Vector2D operator-(const Vector2D& rhs) const {
        return Vector2D(xPos - rhs.xPos, yPos - rhs.yPos);
    }

    // Multiply vector by scalar
    Vector2D operator*(double factor) const {
        return Vector2D(xPos * factor, yPos * factor);
    }

    // Compute dot product with another vector
    double computeDot(const Vector2D& other) const {
        return xPos * other.xPos + yPos * other.yPos;
    }

    // Calculate Euclidean length of the vector
    double getLength() const {
        return std::sqrt(xPos * xPos + yPos * yPos);
    }

    // Return unit vector in same direction
    Vector2D getUnitVector() const {
        double len = getLength();
        if (len > 0.0) {
            return Vector2D(xPos / len, yPos / len);
        }
        return *this; // Preserve zero vector
    }

private:
    double xPos, yPos;
};

// Display vector contents
void showVector(const Vector2D& vec) {
    std::cout << "Vector: (" << vec.getXPos() << ", " << vec.getYPos() << ")" << std::endl;
}

int main() {
    Vector2D a(3.0, 4.0);
    Vector2D b(1.0, 2.0);

    Vector2D sumVec = a + b;
    Vector2D diffVec = a - b;
    Vector2D scaledVec = a * 2.0;
    double innerProduct = a.computeDot(b);
    double lengthA = a.getLength();
    Vector2D unitA = a.getUnitVector();

    showVector(a);
    showVector(b);
    showVector(sumVec);   // a + b
    showVector(diffVec);  // a - b
    showVector(scaledVec); // a * 2.0
    std::cout << "Dot Product: " << innerProduct << std::endl;
    std::cout << "Magnitude: " << lengthA << std::endl;
    showVector(unitA);

    return 0;
}

