__global__ void gameOfLife(float* returnBuffer, int width, int height) {
    __shared__ float tile[32][32];

    int col = blockIdx.x * blockDim.x + threadIdx.x;
    int row = blockIdx.y * blockDim.y + threadIdx.y;

    // Load data into shared memory with boundary check
    if (col < width && row < height) {
        tile[threadIdx.y + 1][threadIdx.x + 1] = tex2D(inputTex, col, row);
    }

    __syncthreads();

    // Process only interior threads (avoiding border threads)
    if (threadIdx.x > 0 && threadIdx.x < 31 && threadIdx.y > 0 && threadIdx.y < 31) {
        float currentCell = tile[threadIdx.y][threadIdx.x];
        float neighborCount = 0.0f;

        // Sum all 8 neighbors
        neighborCount += tile[threadIdx.y - 1][threadIdx.x - 1];
        neighborCount += tile[threadIdx.y - 1][threadIdx.x];
        neighborCount += tile[threadIdx.y - 1][threadIdx.x + 1];
        neighborCount += tile[threadIdx.y][threadIdx.x - 1];
        neighborCount += tile[threadIdx.y][threadIdx.x + 1];
        neighborCount += tile[threadIdx.y + 1][threadIdx.x - 1];
        neighborCount += tile[threadIdx.y + 1][threadIdx.x];
        neighborCount += tile[threadIdx.y + 1][threadIdx.x + 1];

        float nextState = 0.0f;

        // Apply Conway's Game of Life rules
        if (neighborCount == 3 || (currentCell != 0.0f && neighborCount == 2)) {
            nextState = 1.0f;
        }

        // Write result back to global memory if within bounds
        if (col < width && row < height) {
            returnBuffer[col + row * width] = nextState;
        }
    }
}

