extern "C" {

JNIEXPORT jbyteArray JNICALL
Java_com_android_camera3_camera_hardware_session_output_photo_yuv_YuvJniInterface_scale420YuvByteArray(
        JNIEnv *env, jclass /*clazz*/, jbyteArray yuvByteArray_, jint src_width, jint src_height,
        jint dst_width, jint dst_height) {

    jbyte *raw_data = env->GetByteArrayElements(yuvByteArray_, NULL);

    // Compute buffer sizes
    int input_length = env->GetArrayLength(yuvByteArray_);
    int output_length = dst_height * dst_width * 3 / 2;

    // Setup input frame structure
    input_frame.width = src_width;
    input_frame.height = src_height;
    input_frame.data = reinterpret_cast<uint8_t*>(raw_data);
    input_frame.y_plane = input_frame.data;
    input_frame.y_row_bytes = src_width;
    input_frame.u_plane = input_frame.y_plane + src_width * src_height;
    input_frame.v_plane = input_frame.u_plane + (src_width * src_height) / 4;
    input_frame.u_row_bytes = src_width / 2;
    input_frame.v_row_bytes = src_width / 2;

    // Prepare output frame
    delete[] scaled_frame.data;
    scaled_frame.width = dst_width;
    scaled_frame.height = dst_height;
    scaled_frame.data = new uint8_t[output_length];
    scaled_frame.y_plane = scaled_frame.data;
    scaled_frame.y_row_bytes = dst_width;
    scaled_frame.u_plane = scaled_frame.y_plane + dst_width * dst_height;
    scaled_frame.v_plane = scaled_frame.u_plane + (dst_width * dst_height) / 4;
    scaled_frame.u_row_bytes = dst_width / 2;
    scaled_frame.v_row_bytes = dst_width / 2;

    libyuv::FilterMode scaling_filter = libyuv::FilterModeEnum::kFilterBilinear;

    int status = I420Scale(
            input_frame.y_plane, input_frame.y_row_bytes,
            input_frame.u_plane, input_frame.u_row_bytes,
            input_frame.v_plane, input_frame.v_row_bytes,
            input_frame.width, input_frame.height,
            scaled_frame.y_plane, scaled_frame.y_row_bytes,
            scaled_frame.u_plane, scaled_frame.u_row_bytes,
            scaled_frame.v_plane, scaled_frame.v_row_bytes,
            scaled_frame.width, scaled_frame.height,
            scaling_filter);

    LOGD("Scaling completed with status: %d", status);

    // Return result as Java byte array
    jbyteArray result_array = env->NewByteArray(output_length);
    env->SetByteArrayRegion(result_array, 0, output_length, reinterpret_cast<jbyte*>(scaled_frame.data));

    env->ReleaseByteArrayElements(yuvByteArray_, raw_data, 0);

    return result_array;
}

