void StringAppendF(std::string* result, const char* fmt, ...) {
    va_list parameters;
    va_start(parameters, fmt);

    // Use dynamic buffer approach instead of fixed buffer
    std::ostringstream oss;
    char* temp_buffer = nullptr;
    size_t buffer_size = 128;

    // Try with increasing buffer sizes until successful
    while (true) {
        temp_buffer = new char[buffer_size];
        int required = vsnprintf(temp_buffer, buffer_size, fmt, parameters);

        if (required >= 0 && static_cast<size_t>(required) < buffer_size) {
            break;
        }

        delete[] temp_buffer;
        buffer_size = (required >= 0) ? (required + 1) : (buffer_size * 2);
    }

    oss << temp_buffer;
    delete[] temp_buffer;
    *result += oss.str();

    va_end(parameters);
}

