#include <android/native_window.h>

// Initialize EGL and create main + auxiliary contexts for OpenGL ES 2.0 rendering
void InitializeEGLContexts(ANativeWindow* nativeWindow) {
    EGLDisplay display = eglGetDisplay(EGL_DEFAULT_DISPLAY);

    if (display == EGL_NO_DISPLAY) {
        // Handle error: could not get EGL display
        return;
    }

    if (!eglInitialize(display, nullptr, nullptr)) {
        // Error handling for EGL initialization failure
        return;
    }

    // Context attributes specifying OpenGL ES version 2
    EGLint contextAttrs[] = {
        EGL_CONTEXT_CLIENT_VERSION, 2,
        EGL_NONE
    };

    // Configuration attributes for window surface with full-color depth buffer
    const EGLint winConfigAttrs[] = {
        EGL_SURFACE_TYPE,       EGL_WINDOW_BIT,
        EGL_RENDERABLE_TYPE,    EGL_OPENGL_ES2_BIT,
        EGL_BLUE_SIZE,          8,
        EGL_GREEN_SIZE,         8,
        EGL_RED_SIZE,           8,
        EGL_ALPHA_SIZE,         8,
        EGL_BUFFER_SIZE,        32,
        EGL_DEPTH_SIZE,         24,
        EGL_NONE
    };

    EGLConfig mainConfig;
    EGLint configCount;

    if (!eglChooseConfig(display, winConfigAttrs, &mainConfig, 1, &configCount) || configCount == 0) {
        // Failed to select appropriate EGL configuration
        return;
    }

    // Query native visual ID for buffer geometry setup
    EGLint visualFormat;
    if (!eglGetConfigAttrib(display, mainConfig, EGL_NATIVE_VISUAL_ID, &visualFormat)) {
        // Could not retrieve native visual ID
        return;
    }

    ANativeWindow_setBuffersGeometry(nativeWindow, 0, 0, visualFormat);

    // Create window surface using selected config
    EGLSurface windowSurface = eglCreateWindowSurface(display, mainConfig, nativeWindow, nullptr);
    if (windowSurface == EGL_NO_SURFACE) {
        // Surface creation failed
        return;
    }

    // Create main rendering context
    EGLContext mainContext = eglCreateContext(display, mainConfig, EGL_NO_CONTEXT, contextAttrs);
    if (mainContext == EGL_NO_CONTEXT) {
        // Context creation failed
        return;
    }

    // Setup for auxiliary offscreen context (pbuffer-based)
    const EGLint pbufferConfigAttrs[] = {
        EGL_SURFACE_TYPE,       EGL_PBUFFER_BIT,
        EGL_RENDERABLE_TYPE,    EGL_OPENGL_ES2_BIT,
        EGL_BLUE_SIZE,          8,
        EGL_GREEN_SIZE,         8,
        EGL_RED_SIZE,           8,
        EGL_ALPHA_SIZE,         8,
        EGL_DEPTH_SIZE,         0,
        EGL_STENCIL_SIZE,       0,
        EGL_NONE
    };

    const EGLint pbufferAttrs[] = {
        EGL_WIDTH,              1,
        EGL_HEIGHT,             1,
        EGL_TEXTURE_TARGET,     EGL_NO_TEXTURE,
        EGL_TEXTURE_FORMAT,     EGL_NO_TEXTURE,
        EGL_NONE
    };

    EGLConfig auxConfig;
    EGLint auxConfigCount;

    if (!eglChooseConfig(display, pbufferConfigAttrs, &auxConfig, 1, &auxConfigCount) || auxConfigCount == 0) {
        // Auxiliary config selection failed
        return;
    }

    // Create pbuffer surface for auxiliary context
    EGLSurface pbufferSurface = eglCreatePbufferSurface(display, auxConfig, pbufferAttrs);
    if (pbufferSurface == EGL_NO_SURFACE) {
        // Pbuffer surface creation failed
        return;
    }

    // Create auxiliary context sharing resources with main context
    EGLContext auxContext = eglCreateContext(display, auxConfig, mainContext, contextAttrs);
    if (auxContext == EGL_NO_CONTEXT) {
        // Auxiliary context creation failed
        return;
    }

    // Activate the main context and surface for rendering
    if (!eglMakeCurrent(display, windowSurface, windowSurface, mainContext)) {
        // Failed to bind context/surface
        return;
    }
}

