#include <iostream>
#include <stack>

// Helper function to swap two elements
void exchange(int& a, int& b) {
    int temp = a;
    a = b;
    b = temp;
}

// Modified quicksort using iterative approach with explicit stack
void quickSort(int arr[], int size) {
    if (size <= 1) return;

    std::stack<std::pair<int, int>> rangeStack;
    rangeStack.push({0, size - 1});

    while (!rangeStack.empty()) {
        auto currentRange = rangeStack.top();
        rangeStack.pop();

        int left = currentRange.first;
        int right = currentRange.second;

        if (left >= right) continue;

        // Choose first element as pivot (different from original)
        int pivot = arr[left];
        int start = left;
        int end = right;

        // Partition using two-pointer approach
        while (start < end) {
            // Move end pointer left while element > pivot
            while (start < end && arr[end] >= pivot) {
                end--;
            }

            // Move start pointer right while element <= pivot
            while (start < end && arr[start] <= pivot) {
                start++;
            }

            // Swap if pointers haven't met
            if (start < end) {
                exchange(arr[start], arr[end]);
            }
        }

        // Place pivot in correct position
        exchange(arr[left], arr[start]);
        int pivotIndex = start;

        // Push subarrays to stack for processing
        if (pivotIndex - 1 > left) {
            rangeStack.push({left, pivotIndex - 1});
        }
        if (pivotIndex + 1 < right) {
            rangeStack.push({pivotIndex + 1, right});
        }
    }
}

