// Determine operator precedence level
int getPrecedence(char op) {
    if (op == '+' || op == '-') return 1;
    if (op == '*' || op == '/') return 2;
    return 0;
}

// Check if character is an arithmetic operator
bool isArithmeticOperator(char c) {
    return c == '+' || c == '-' || c == '*' || c == '/';
}

// Check if character is a valid operand (letter or digit)
bool isVariableOrDigit(char c) {
    return std::isalpha(c) || std::isdigit(c);
}

// Convert infix expression to postfix notation
std::string convertInfixToPostfix(const std::string& infixExpr) {
    std::stack<char> operatorStack;
    std::string resultPostfix;

    for (char currentChar : infixExpr) {
        if (isVariableOrDigit(currentChar)) {
            resultPostfix += currentChar;
        } else if (currentChar == '(') {
            operatorStack.push(currentChar);
        } else if (currentChar == ')') {
            while (!operatorStack.empty() && operatorStack.top() != '(') {
                resultPostfix += operatorStack.top();
                operatorStack.pop();
            }
            if (!operatorStack.empty()) {
                operatorStack.pop();  // Remove the '('
            }
        } else if (isArithmeticOperator(currentChar)) {
            while (!operatorStack.empty() && 
                   getPrecedence(currentChar) <= getPrecedence(operatorStack.top())) {
                resultPostfix += operatorStack.top();
                operatorStack.pop();
            }
            operatorStack.push(currentChar);
        }
    }

    // Append remaining operators from stack to output
    while (!operatorStack.empty()) {
        resultPostfix += operatorStack.top();
        operatorStack.pop();
    }

    return resultPostfix;
}

