// Check if a number is prime using an alternative approach
bool checkPrime(int value) {
    if (value <= 1) return false; // Numbers <= 1 are not prime

    int divisor = 2;
    while (divisor * divisor <= value) {
        if (value % divisor == 0) return false; // Found a factor, so not prime
        divisor++;
    }
    return true; // No factors found, the number is prime
}

int main() {
    cout << "Prime numbers between 1 and 10 are: ";

    int current = 1;
    while (current <= 10) {
        if (checkPrime(current)) {
            cout << current << " ";
        }
        current++;
    }

    cout << endl;
    return 0;
}

