// Compute the sum of integers from 0 to n-1 using a while loop
unsigned long long computeSum(unsigned long long limit)
{
    unsigned long long total = 0;
    unsigned long long current = 0;

    while (current < limit)
    {
        total += current;
        current++;
    }

    return total;
}

int main()
{
    LARGE_INTEGER frequency, startTime, endTime;
    QueryPerformanceFrequency(&frequency);
    QueryPerformanceCounter(&startTime);

    // Calculate sum for 1 billion numbers (0 to 999,999,999)
    unsigned long long answer = computeSum(1000000000ULL);

    QueryPerformanceCounter(&endTime);
    double durationMs = (double)(endTime.QuadPart - startTime.QuadPart) / frequency.QuadPart * 1000.0;

    printf("Result: %llu\n", answer);
    printf("Delta: %f ms\n", durationMs);

    return 0;
}

