int _tmain(int argc, _TCHAR* argv[])
{
    HCRYPTPROV hProvider = NULL;
    HCRYPTKEY hKeyPair = NULL;
    HCRYPTHASH hHash = NULL;
    HCRYPTKEY hSessionKey = NULL;
    BOOL bSuccess = FALSE;

    // Buffer for session key export
    BYTE pbExportedKey[1024];
    DWORD dwExportedKeyLen = sizeof(pbExportedKey);

    // Acquire cryptographic context
    if (!CryptAcquireContext(&hProvider, NULL, MS_ENHANCED_PROV, PROV_RSA_FULL, 0))
    {
        if (GetLastError() == NTE_BAD_KEYSET)
        {
            bSuccess = CryptAcquireContext(&hProvider, NULL, MS_ENHANCED_PROV, 
                                          PROV_RSA_FULL, CRYPT_NEWKEYSET);
        }
        else
        {
            goto Cleanup;
        }

        if (!bSuccess)
            goto Cleanup;
    }

    // Generate Diffie-Hellman key pair
    bSuccess = CryptGenKey(hProvider, CALG_DH_EPHEM, DHKEYSIZE << 16, &hKeyPair);
    if (!bSuccess)
        goto Cleanup;

    // Create SHA-1 hash object
    bSuccess = CryptCreateHash(hProvider, CALG_SHA1, 0, 0, &hHash);
    if (!bSuccess)
        goto Cleanup;

    // Derive session key from hash (using RC4 algorithm)
    bSuccess = CryptDeriveKey(hProvider, CALG_RC4, hHash, 0, &hSessionKey);
    if (!bSuccess)
        goto Cleanup;

    // Export the session key in plaintext format
    bSuccess = CryptExportKey(hSessionKey, 0, PLAINTEXTKEYBLOB, 0, 
                             pbExportedKey, &dwExportedKeyLen);
    if (!bSuccess)
        goto Cleanup;

    // Output exported session key as hexadecimal
    for (DWORD idx = 0; idx < dwExportedKeyLen; ++idx)
    {
        printf("%02x", pbExportedKey[idx]);
    }
    printf("\n");

    // Prepare data for encryption
    BYTE encryptedData[sizeof(g_rgbTestData)];
    memcpy(encryptedData, g_rgbTestData, sizeof(g_rgbTestData));
    DWORD dataLength = sizeof(g_rgbTestData);

    // Encrypt the test data
    bSuccess = CryptEncrypt(hSessionKey, 0, TRUE, 0, encryptedData, 
                           &dataLength, sizeof(encryptedData));
    if (!bSuccess)
        goto Cleanup;

    // Output encrypted data as hexadecimal
    for (DWORD idx = 0; idx < dataLength; ++idx)
    {
        printf("%02x", encryptedData[idx]);
    }
    printf("\n");

    bSuccess = TRUE;

Cleanup:
    // Clean up resources in reverse order of creation
    if (hSessionKey) CryptDestroyKey(hSessionKey);
    if (hHash) CryptDestroyHash(hHash);
    if (hKeyPair) CryptDestroyKey(hKeyPair);
    if (hProvider) CryptReleaseContext(hProvider, 0);

    return bSuccess ? 0 : 1;
}

