// Find the maximum value in a vector of integers
int findMaximum(const std::vector<int>& data) {
    if (data.empty()) {
        throw std::invalid_argument("Vector is empty");
    }
    int maxVal = data[0];
    size_t index = 1;
    while (index < data.size()) {
        if (data[index] > maxVal) {
            maxVal = data[index];
        }
        ++index;
    }
    return maxVal;
}

int main() {
    std::vector<int> numbers = {3, 5, 7, 2, 8, -1, 4};
    try {
        std::cout << "The largest element is: " << findMaximum(numbers) << std::endl;
    } catch (const std::exception& e) {
        std::cerr << e.what() << std::endl;
    }
    return 0;
}

#include <condition_variable>
#include <mutex>

class CountdownEvent {
public:
    explicit CountdownEvent(size_t initial_count) : _remaining(initial_count) {}

    void await() {
        std::unique_lock<std::mutex> guard(_lock);
        _cv.wait(guard, [this] { return _remaining == 0; });
    }

    void signal() {
        std::unique_lock<std::mutex> guard(_lock);
        if (_remaining > 0) {
            --_remaining;
            if (_remaining == 0) {
                _cv.notify_all();
            }
        }
    }

private:
    size_t _remaining;
    std::mutex _lock;
    std::condition_variable _cv;
};

