// Function to find the longest common substring between two strings
pair<int, pair<int, int>> longestCommonSubstr(const string& str1, const string& str2) {
    int len1 = str1.size();
    int len2 = str2.size();

    // Initialize DP table with zeros
    vector<vector<int>> table(len1 + 1, vector<int>(len2 + 1, 0));

    int maxLen = 0;
    int pos1 = -1;
    int pos2 = -1;

    // Build the DP table
    for (int i = 1; i <= len1; ++i) {
        for (int j = 1; j <= len2; ++j) {
            if (str1[i-1] == str2[j-1]) {
                table[i][j] = table[i-1][j-1] + 1;
                if (table[i][j] > maxLen) {
                    maxLen = table[i][j];
                    pos1 = i - 1;
                    pos2 = j - 1;
                }
            } else {
                table[i][j] = 0;
            }
        }
    }

    // Compute starting positions
    int start1 = pos1 - maxLen + 1;
    int start2 = pos2 - maxLen + 1;

    return make_pair(maxLen, make_pair(start1, start2));
}

int main() {
    string input1, input2;

    cout << "Enter first string: ";
    cin >> input1;
    cout << "Enter second string: ";
    cin >> input2;

    auto result = longestCommonSubstr(input1, input2);
    int length = result.first;
    int idx1 = result.second.first;
    int idx2 = result.second.second;

    if (length > 0) {
        cout << "Longest common substring: " << input1.substr(idx1, length) << endl;
        cout << "Start position in first string: " << idx1 << endl;
        cout << "Start position in second string: " << idx2 << endl;
    } else {
        cout << "No common substring exists." << endl;
    }

    return 0;
}

#include <immintrin.h> // For AVX intrinsics

// Reorder function with vectorized load/store for non-zero blocks
void reorder(float* output, const float* input, size_t length) {
    size_t idx = 0;
    while (idx < length) {
        // Determine if a full vector of 8 elements can be safely processed
        bool allNonZero = true;
        for (int j = 0; j < 8 && (idx + j) < length; ++j) {
            if (input[idx + j] == 0.0f) {
                allNonZero = false;
                break;
            }
        }

        if (allNonZero && (idx + 8) <= length) {
            // Process 8 elements using AVX
            __m256 dataVec = _mm256_loadu_ps(&input[idx]);
            _mm256_storeu_ps(&output[idx], dataVec);
            idx += 8;
        } else {
            // Fall back to scalar copy for remaining or zero-containing elements
            if (idx < length) {
                output[idx] = input[idx];
                idx++;
            }
        }
    }
}

int medianOfThree(vector<int> &arr, int left, int right) {
    int middle = left + (right - left) / 2;

    // Get the values at the three positions
    int valLeft = arr[left];
    int valMid = arr[middle];
    int valRight = arr[right];

    // Determine which value is the median
    int medianValue;

    if ((valLeft > valMid && valLeft < valRight) || (valLeft < valMid && valLeft > valRight)) {
        medianValue = valLeft;
    } else if ((valMid > valLeft && valMid < valRight) || (valMid < valLeft && valMid > valRight)) {
        medianValue = valMid;
    } else {
        medianValue = valRight;
    }

    // Find the index of the median value and swap it to position 'right'
    if (medianValue == valLeft) {
        swap(arr[left], arr[right]);
    } else if (medianValue == valMid) {
        swap(arr[middle], arr[right]);
    }
    // If medianValue == valRight, no swap needed

    return medianValue;
}

