// Function to neutralize SetUnhandledExceptionFilter by replacing its implementation
bool BypassUnhandledExceptionFilter()
{
    // Machine code for: XOR RAX, RAX; RET (returns NULL immediately)
    const unsigned char PatchCode[5] = { 0x48, 0x33, 0xC0, 0xC3 };

    // Load kernel32.dll to locate the target function
    HMODULE hKernel32 = GetModuleHandle(_T("kernel32.dll"));
    if (!hKernel32)
        return false;

    // Get address of SetUnhandledExceptionFilter
    FARPROC pFunc = GetProcAddress(hKernel32, "SetUnhandledExceptionFilter");
    if (!pFunc)
        return false;

    BYTE* pFunctionAddress = reinterpret_cast<BYTE*>(pFunc);

    // Apply patch to overwrite function body
    if (!PatchFunctionBody(pFunctionAddress, PatchCode, sizeof(PatchCode)))
        return false;

    // Flush instruction cache to ensure CPU sees updated code
    FlushInstructionCache(GetCurrentProcess(), pFunctionAddress, sizeof(PatchCode));

    return true;
}

// Helper function to safely write executable memory
static bool PatchFunctionBody(BYTE* pDest, const BYTE* pSourceData, DWORD dwLength)
{
    // Validate inputs
    if (pDest == nullptr || pSourceData == nullptr || dwLength == 0)
        return false;

    // Verify source buffer is readable
    if (IsBadReadPtr(pSourceData, dwLength))
        return false;

    // Change memory protection to allow writing
    DWORD previousProtection;
    if (!VirtualProtect(pDest, dwLength, PAGE_EXECUTE_READWRITE, &previousProtection))
        return false;

    // Perform the actual copy
    memcpy(pDest, pSourceData, dwLength);

    // Restore original memory protection
    DWORD dummy;
    VirtualProtect(pDest, dwLength, previousProtection, &dummy);

    return true;
}

