// Calculate the number of digits in an integer (handles negatives and zero)
int digitCount(int value) {
    if (value == 0) return 1;
    int absValue = (value < 0) ? -value : value;
    return static_cast<int>(floor(log10(absValue)) + 1);
}

// Custom comparison for sorting by digit count, then by numeric value
bool sortByDigitCount(int first, int second) {
    int countFirst = digitCount(first);
    int countSecond = digitCount(second);

    if (countFirst == countSecond) {
        return first < second; // Same digit count: sort numerically
    }
    return countFirst < countSecond; // Different digit count: sort by length
}

// Sort a vector based on the number of digits in each element
vector<int> orderByDigitLength(vector<int> input) {
    sort(input.begin(), input.end(), sortByDigitCount);
    return input;
}

// Run test cases to verify the ordering function works correctly
void runDigitLengthTests() {
    vector<int> case1 = {123, 21, 2, 1000, 100};
    vector<int> result1 = orderByDigitLength(case1);
    vector<int> expect1 = {2, 21, 100, 123, 1000};
    assert(result1 == expect1);

    vector<int> case2 = {-21, -1000, -2, -100, -123};
    vector<int> result2 = orderByDigitLength(case2);
    vector<int> expect2 = {-2, -21, -100, -123, -1000};
    assert(result2 == expect2);

    vector<int> case3 = {100, 10, 2, 300, 400};
    vector<int> result3 = orderByDigitLength(case3);
    vector<int> expect3 = {2, 10, 100, 300, 400};
