// A 2D vector class supporting basic arithmetic operations
class Vector {
public:
    int x_coord, y_coord;

    // Constructor with default values (0, 0)
    Vector(int x = 0, int y = 0) : x_coord(x), y_coord(y) {}

    // Addition operator: adds corresponding components
    Vector operator+(const Vector& rhs) const {
        return Vector(x_coord + rhs.x_coord, y_coord + rhs.y_coord);
    }

    // Subtraction operator: subtracts corresponding components
    Vector operator-(const Vector& rhs) const {
        return Vector(x_coord - rhs.x_coord, y_coord - rhs.y_coord);
    }

    // Scalar multiplication: multiplies both components by a scalar
    Vector operator*(int factor) const {
        return Vector(x_coord * factor, y_coord * factor);
    }

    // Stream insertion operator for easy output formatting
    friend std::ostream& operator<<(std::ostream& stream, const Vector& vec) {
        stream << "(" << vec.x_coord << ", " << vec.y_coord << ")";
        return stream;
    }
};

#include <immintrin.h>

// Compute hash using SSE by XOR-ing 128-bit chunks
uint32_t computeHash(const uint32_t* data, size_t length) {
    // Initialize hash vector with zeros
    __m128i accumulator = _mm_setzero_si128();

    // Process full 128-bit (4x32-bit) chunks
    for (size_t i = 0; i < length / 4; ++i) {
        // Load unaligned 128-bit chunk from input data
        __m128i current_chunk = _mm_loadu_si128(reinterpret_cast<const __m128i*>(&data[i * 4]));

        // XOR current chunk with accumulated hash
        accumulator = _mm_xor_si128(accumulator, current_chunk);
    }

    // Extract the result: store the 128-bit value into a 32-bit variable
    // Note: only the first 32 bits will be stored due to type conversion
    uint32_t output;
    _mm_storeu_si128(reinterpret_cast<__m128i*>(&output), accumulator);
    return output;
}

