// Custom variant type supporting multiple C/C++ data types
class Variant {
public:
    // Type identifiers
    enum TypeId { T_NONE = 0, T_INT, T_FLOAT, T_DOUBLE, T_STRING };

    // Constructors for supported types
    Variant(int val) : m_type(T_INT), m_int_val(val) {}
    Variant(float val) : m_type(T_FLOAT), m_float_val(val) {}
    Variant(double val) : m_type(T_DOUBLE), m_double_val(val) {}
    Variant(const char* val) : m_type(T_STRING), m_str_val(val ? val : "") {}

    // Accessors
    TypeId GetTypeId() const { return m_type; }

    int ToInt() const { return m_int_val; }
    float ToFloat() const { return m_float_val; }
    double ToDouble() const { return m_double_val; }
    const char* ToString() const { return m_str_val.c_str(); }

private:
    TypeId m_type;
    union {
        int m_int_val;
        float m_float_val;
        double m_double_val;
    };
    std::string m_str_val; // Used only when type is T_STRING
};

// Convert a Python object to our custom Variant type
Variant ConvertPyObject(PyObject* obj) {
    if (PyLong_Check(obj)) {
        long val = PyLong_AsLong(obj);
        return Variant(static_cast<int>(val));
    } else if (PyFloat_Check(obj)) {
        double val = PyFloat_AsDouble(obj);
        return Variant(static_cast<float>(val));
    } else if (PyUnicode_Check(obj)) {
        PyObject* utf8 = PyUnicode_AsUTF8String(obj);
        const char* str = PyBytes_AsString(utf8);
        Variant result(str);
        Py_DECREF(utf8);
        return result;
    } else if (PyList_Check(obj)) {
        // Placeholder: could be extended to convert list elements recursively
        PyErr_SetString(PyExc_TypeError, "List conversion not implemented");
        return Variant(0);
    } else {
        PyErr_SetString(PyExc_TypeError, "Unsupported Python type");
        return Variant(0);
    }
}

int main() {
    // Initialize Python runtime
    Py_Initialize();

    // Create and test an example integer argument
    PyObject* pyObj = PyLong_FromLong(123);
    Variant var = ConvertPyObject(pyObj);

    if (var.GetTypeId() == Variant::T_INT) {
        std::printf("Converted integer: %d\n", var.ToInt());
    }

    // Cleanup
    Py_DECREF(pyObj);
    Py_Finalize();

    return 0;
}

