// Function to properly escape and wrap script content with CDATA
QString embedScriptsWithCdata(const QString &htmlContent) {
    QString result = htmlContent;
    int pos = 0;

    while (true) {
        int scriptStart = result.indexOf(QLatin1String("<script"), pos);
        if (scriptStart == -1) break;

        int scriptEnd = result.indexOf(QLatin1String("</script>"), scriptStart);
        if (scriptEnd == -1) break;

        // Extract the full script tag including attributes
        QString originalTag = result.mid(scriptStart, scriptEnd + 9 - scriptStart);

        // Create new wrapped version
        QString newTag = QLatin1String("<script type=\"text/javascript\">\n")
                       + QLatin1String("    //<![CDATA[\n")
                       + QLatin1String("    ") + originalTag + QLatin1String("\n")
                       + QLatin1String("    //]]>\n")
                       + QLatin1String("</script>");

        result.replace(scriptStart, scriptEnd + 9 - scriptStart, newTag);
        pos = scriptStart + newTag.length();
    }

    return result;
}

int main() {
    QString documentContent;

    {
        QFile inputFile("main.html");
        if (!inputFile.open(QIODevice::ReadOnly)) {
            qWarning() << "Failed to open main.html for reading";
            return -1;
        }

        QTextStream reader(&inputFile);
        documentContent = reader.readAll();
        inputFile.close();
    }

    // Apply preprocessing to handle script tags safely
    QString processedHtml = embedScriptsWithCdata(documentContent);

    QDomDocument xmlDocument;
    QString errorMessage;
    int errorLine = 0;
    int errorColumn = 0;

    if (!xmlDocument.setContent(processedHtml, &errorMessage, &errorLine, &errorColumn)) {
        qCritical() << "XML parsing failed:" << errorMessage 
                    << "at line" << errorLine << "column" << errorColumn;
        return -1;
    }

    // Recursive function to traverse and print DOM elements with indentation
    std::function<void(const QDomElement&, int)> traverseAndPrint =
        [&traverseAndPrint](const QDomElement& node, int depth) {
            QString indent(4 * depth, ' ');
            QDomNode child = node.firstChild();

            while (!child.isNull()) {
                QDomElement element = child.toElement();
                if (!element.isNull()) {
                    qDebug() << indent + element.tagName();
                    traverseAndPrint(element, depth + 1);
                }
                child = child.nextSibling();
            }
        };

    traverseAndPrint(xmlDocument.documentElement(), 0);

