// File and mutex names for shared counter management
const std::string CounterFilePath = "counter.dat";
const std::string SharedMutexIdentifier = "Global\\SharedCounterMutex";

class SharedCounterController
{
private:
    HANDLE synchronizationMutex;

public:
    SharedCounterController()
    {
        synchronizationMutex = CreateMutex(NULL, FALSE, SharedMutexIdentifier.c_str());
    }

    ~SharedCounterController()
    {
        if (synchronizationMutex != NULL)
        {
            CloseHandle(synchronizationMutex);
        }
    }

    int IncreaseCounterValue()
    {
        WaitForSingleObject(synchronizationMutex, INFINITE);

        int currentValue = 0;
        std::ifstream inputFile(CounterFilePath);
        if (inputFile.is_open())
        {
            inputFile >> currentValue;
            inputFile.close();
        }

        currentValue += 1;

        std::ofstream outputFile(CounterFilePath);
        if (outputFile.is_open())
        {
            outputFile << currentValue;
            outputFile.close();
        }

        ReleaseMutex(synchronizationMutex);
        return currentValue;
    }

    int DecreaseCounterValue()
    {
        WaitForSingleObject(synchronizationMutex, INFINITE);

        int currentValue = 0;
        std::ifstream inputFile(CounterFilePath);
        if (inputFile.is_open())
        {
            inputFile >> currentValue;
            inputFile.close();
        }

        currentValue -= 1;

        std::ofstream outputFile(CounterFilePath);
        if (outputFile.is_open())
        {
            outputFile << currentValue;
            outputFile.close();
        }

        ReleaseMutex(synchronizationMutex);
        return currentValue;
    }
};

#include <iostream>
#include <string>
#include <vector>
#include <iterator>

class FileStructGenerator {
public:
    class Iterator {
    public:
        using value_type = std::string;
        using reference = std::string&;
        using pointer = std::string*;
        using difference_type = std::ptrdiff_t;
        using iterator_category = std::input_iterator_tag;

        Iterator(FileStructGenerator& gen, bool isEnd = false) : generator_(gen), isEnd_(isEnd) {
            if (!isEnd_) {
                currentValue_ = generator_.generateNext();
            }
        }

        Iterator& operator++() {
            if (!isEnd_) {
                currentValue_ = generator_.generateNext();
            }
            return *this;
        }

        Iterator operator++(int) {
            Iterator temp = *this;
            ++(*this);
            return temp;
        }

        bool operator==(const Iterator& rhs) const {
            return isEnd_ == rhs.isEnd_;
        }

        bool operator!=(const Iterator& rhs) const {
            return !(*this == rhs);
        }

        const std::string& operator*() const {
            return currentValue_;
        }

        const std::string* operator->() const {
            return &currentValue_;
        }

    private:
        FileStructGenerator& generator_;
        std::string currentValue_;
        bool isEnd_;
    };

    FileStructGenerator(const std::string& path) : filePath_(path), skipCount_(path.find("more") != std::string::npos ? 5 : 6), state_(0) {}

    Iterator begin() {
        return Iterator(*this);
    }

    Iterator end() {
        return Iterator(*this, true);
    }

private:
    std::string filePath_;
    int skipCount_;
    int state_;

    std::string generateNext() {
        switch (state_) {
            case 0:
                state_ = 1;
                return "data";
            case 1:
                for (int idx = 0; idx < skipCount_; ++idx) {
                    state_++;
                    return "unused";
                }
                state_ = skipCount_ + 1;
                // Intentionally fall through
            case skipCount_ + 1:
                state_++;
                return "data";
            default:
                return "data"; // Continues indefinitely like the original behavior
        }
    }
};

// Demonstration of usage
int main() {
    FileStructGenerator generator("sample_more.txt");

    for (const auto& item : generator) {
        std::cout << item << std::endl;
    }

    return 0;
}

