// Definition for a Node.
class Node {
public:
    int val;
    Node* left;
    Node* right;
    Node* next;

    Node() : val(0), left(NULL), right(NULL), next(NULL) {}

    Node(int _val) : val(_val), left(NULL), right(NULL), next(NULL) {}

    Node(int _val, Node* _left, Node* _right, Node* _next)
        : val(_val), left(_left), right(_right), next(_next) {}
};
*/

class Solution {
public:
    Node* connect(Node* root) {
        if (!root) return root;

        Node* levelStart = root;

        while (levelStart) {
            Node* node = levelStart;
            Node* helper = new Node(0); // Temporary sentinel node for building next level
            Node* tail = helper;

            while (node) {
                if (node->left) {
                    tail->next = node->left;
                    tail = tail->next;
                }
                if (node->right) {
                    tail->next = node->right;
                    tail = tail->next;
                }
                node = node->next;
            }

            levelStart = helper->next; // Advance to the next level
            delete helper; // Release temporary sentinel
        }

        return root;
    }
};

