/* Define the CustomIterator object */
typedef struct {
    PyObject_HEAD
    size_t limit;
    size_t index;
} CustomIterator;

static void CustomIterator_dealloc(CustomIterator* self) {
    Py_TYPE(self)->tp_free((PyObject*)self);
}

static PyObject* CustomIterator_self(CustomIterator* self) {
    Py_INCREF(self);
    return (PyObject*)self;
}

static PyObject* CustomIterator_advance(CustomIterator* self) {
    if (self->index >= self->limit) {
        PyErr_SetNone(PyExc_StopIteration);
        return NULL;
    }
    PyObject* value = PyLong_FromSize_t(self->index);
    self->index++;
    return value;
}

