#include <windows.h>

// Window procedure declaration
LRESULT CALLBACK MainWndProc(HWND hwnd, UINT message, WPARAM wParam, LPARAM lParam);

// Entry point for Windows GUI application
int WINAPI WinMain(HINSTANCE hInstance, HINSTANCE hPrevInstance, LPSTR lpCmdLine, int nShowCmd) {
    // Define and initialize window class structure
    WNDCLASS wc = {};
    wc.lpfnWndProc = MainWndProc;
    wc.hInstance = hInstance;
    wc.hbrBackground = CreateSolidBrush(RGB(255, 255, 255));
    wc.lpszClassName = L"TransparentDraggableWindow";
    RegisterClass(&wc);

    // Create the main window with layered style for transparency
    HWND hWnd = CreateWindow(
        L"TransparentDraggableWindow",
        L"Transparent Draggable Window",
        WS_OVERLAPPEDWINDOW,
        CW_USEDEFAULT, CW_USEDEFAULT, 400, 300,
        NULL, NULL, hInstance, NULL
    );

    // Enable layered window style for alpha blending
    SetWindowLong(hWnd, GWL_EXSTYLE, GetWindowLong(hWnd, GWL_EXSTYLE) | WS_EX_LAYERED);

    ShowWindow(hWnd, nShowCmd);
    UpdateWindow(hWnd);

    // Message loop
    MSG msg;
    while (GetMessage(&msg, NULL, 0, 0)) {
        TranslateMessage(&msg);
        DispatchMessage(&msg);
    }
    return static_cast<int>(msg.wParam);
}

// Window procedure implementation
LRESULT CALLBACK MainWndProc(HWND hwnd, UINT msg, WPARAM wParam, LPARAM lParam) {
    static POINT dragOffset;
    static bool isDragging = false;

    switch (msg) {
        case WM_DESTROY:
            PostQuitMessage(0);
            break;

        case WM_LBUTTONDOWN:
            // Capture mouse input and prepare for dragging
            dragOffset.x = GET_X_LPARAM(lParam);
            dragOffset.y = GET_Y_LPARAM(lParam);
            isDragging = true;

            // Make window semi-transparent during drag
            SetLayeredWindowAttributes(hwnd, 0, 200, LWA_ALPHA);
            SetCursor(LoadCursor(NULL, IDC_SIZEALL));
            SetCapture(hwnd);
            break;

        case WM_MOUSEMOVE:
            if (isDragging) {
                // Calculate new position based on mouse movement
                int xPos = GET_X_LPARAM(lParam) - dragOffset.x;
                int yPos = GET_Y_LPARAM(lParam) - dragOffset.y;

                // Move window without resizing or changing z-order
                SetWindowPos(hwnd, NULL, xPos, yPos, 0, 0, 
                            SWP_NOSIZE | SWP_NOZORDER | SWP_NOACTIVATE);
            }
            break;

        case WM_LBUTTONUP:
            // Release capture and restore opacity
            isDragging = false;
            SetLayeredWindowAttributes(hwnd, 0, 255, LWA_ALPHA);
            SetCursor(LoadCursor(NULL, IDC_ARROW));
            if (GetCapture() == hwnd)
                ReleaseCapture();
            break;

        default:
            return DefWindowProc(hwnd, msg, wParam, lParam);
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <climits>

using namespace std;

// Function to select tapas minimizing the number while reaching at least M calories
vector<int> selectTapas(vector<int>& calories, int minCalories) {
    int itemCount = calories.size();

    // dp[i][j] represents the minimum number of tapas needed using first i items to achieve exactly j calories
    vector<vector<int>> dp(itemCount + 1, vector<int>(minCalories + 1, INT_MAX));
    // choice[i][j] stores which item was last selected to reach state (i, j)
    vector<vector<int>> lastChoice(itemCount + 1, vector<int>(minCalories + 1, -1));

    // Base case: 0 calories requires 0 tapas
    for (int i = 0; i <= itemCount; ++i) {
        dp[i][0] = 0;
    }

    // Fill DP table
    for (int i = 1; i <= itemCount; ++i) {
        int currentCalorie = calories[i - 1];
        for (int target = 0; target <= minCalories; ++target) {
            // Option 1: Skip current tapa
            dp[i][target] = dp[i - 1][target];
            lastChoice[i][target] = lastChoice[i - 1][target];

            // Option 2: Include current tapa if possible
            if (currentCalorie <= target && dp[i - 1][target - currentCalorie] != INT_MAX) {
                int withItem = 1 + dp[i - 1][target - currentCalorie];
                if (withItem < dp[i][target]) {
                    dp[i][target] = withItem;
                    lastChoice[i][target] = i - 1;
                }
            }
        }
    }

    // Find the smallest calorie count >= minCalories that can be achieved
    int bestTarget = minCalories;
    while (bestTarget <= minCalories && dp[itemCount][bestTarget] == INT_MAX) {
        ++bestTarget;
    }

    // If no combination found within limit, return empty result
    if (bestTarget > minCalories || dp[itemCount][bestTarget] == INT_MAX) {
        return {};
    }

    // Backtrack to find selected tapas
    vector<int> selectedIndices;
    int row = itemCount;
    int col = bestTarget;

    while (row > 0 && col >= 0) {
        if (lastChoice[row][col] != -1 && lastChoice[row][col] == row - 1) {
            selectedIndices.push_back(row - 1);
            col -= calories[row - 1];
        }
        --row;
    }

    return selectedIndices;
}

int main() {
    vector<int> calories = {3, 5, 10, 13, 15, 16};
    int requiredCalories = 45;

    vector<int> chosenTapas = selectTapas(calories, requiredCalories);

    cout << "Tapas para pedir:\n";
    for (int idx : chosenTapas) {
        cout << "Tapa " << idx + 1 << ": " << calories[idx] << " calorias\n";
    }

    return 0;
}

