// Wrapper for managing .NET runtime interaction
class DotNetHost
{
public:
    DotNetHost()
    {
        // Initialize COM and create CLR hosting infrastructure
        HRESULT hr = CoInitializeEx(nullptr, COINIT_APARTMENTTHREADED);
        if (FAILED(hr) && hr != RPC_E_CHANGED_MODE) throw std::runtime_error("COM initialization failed");

        hr = CLRCreateInstance(CLSID_CLRMetaHost, IID_ICLRMetaHost, (LPVOID*)&_metaHost);
        if (FAILED(hr)) throw std::runtime_error("Failed to initialize CLR meta host");

        hr = _metaHost->GetRuntime(L"v4.0.30319", IID_ICLRRuntimeInfo, (LPVOID*)&_runtimeInfo);
        if (FAILED(hr)) throw std::runtime_error("Failed to retrieve .NET runtime version");

        BOOL loadable = FALSE;
        hr = _runtimeInfo->IsLoadable(&loadable);
        if (FAILED(hr) || !loadable) throw std::runtime_error(".NET runtime is not loadable");

        hr = _runtimeInfo->GetInterface(CLSID_CLRRuntimeHost, IID_ICLRRuntimeHost, (LPVOID*)&_runtimeHost);
        if (FAILED(hr)) throw std::runtime_error("Failed to obtain runtime host interface");

        hr = _runtimeHost->Start();
        if (FAILED(hr)) throw std::runtime_error("Failed to start the .NET runtime");

        // Setup hosting control interfaces
        hr = _runtimeHost->GetCLRControl(&_clrControl);
        if (FAILED(hr)) throw std::runtime_error("Unable to get CLR control");

        hr = _clrControl->GetHostControl(&_hostControl);
        if (FAILED(hr)) throw std::runtime_error("Unable to get host control");

        // Execute initial method in default app domain
        hr = _runtimeHost->ExecuteInDefaultAppDomain(
            L"ManagedLibrary.dll",
            L"ManagedLibrary.ManagedClass",
            L"Start",
            L"",
            &_managedInstance
        );
        if (FAILED(hr)) throw std::runtime_error("Initial execution in app domain failed");
    }

    ~DotNetHost()
    {
        // Cleanup resources in reverse order of acquisition
        if (_hostControl) _hostControl->Release();
        if (_clrControl) _clrControl->Release();
        _runtimeHost->Stop();
        _runtimeHost->Release();
        _runtimeInfo->Release();
        _metaHost->Release();
        CoUninitialize();
    }

    void PerformOperation()
    {
        HRESULT hr = _runtimeHost->ExecuteInDefaultAppDomain(
            L"ManagedLibrary.dll",
            L"ManagedLibrary.ManagedClass",
            L"DoWork",
            L"",
            nullptr
        );
        if (FAILED(hr)) throw std::runtime_error("Execution of DoWork operation failed");
    }

private:
    ICLRMetaHost*     _metaHost   = nullptr;
    ICLRRuntimeInfo*  _runtimeInfo = nullptr;
    ICLRRuntimeHost*  _runtimeHost = nullptr;
    ICLRControl*      _clrControl = nullptr;
    IHostControl*     _hostControl = nullptr;
    _variant_t         _managedInstance;
};

int main()
{
    try
    {
        DotNetHost host;
        host.PerformOperation();
    }
    catch (const std::exception& ex)
    {
        std::cerr << "Error: " << ex.what() << std::endl;
        return 1;
    }

    return 0;
}

#include <iostream>
#include <limits>

// Node structure for doubly linked list
struct ListNode {
    int data;
    ListNode* previous;
    ListNode* next;

    ListNode(int val) : data(val), previous(nullptr), next(nullptr) {}
};

class EnhancedList {
private:
    ListNode* start;
    ListNode* end;
    ListNode* lowestNode;
    ListNode* highestNode;

public:
    EnhancedList() : start(nullptr), end(nullptr), lowestNode(nullptr), highestNode(nullptr) {}

    void addElement(int value) {
        ListNode* newNode = new ListNode(value);

        if (start == nullptr) {
            start = end = lowestNode = highestNode = newNode;
        } else {
            newNode->previous = end;
            end->next = newNode;
            end = newNode;

            if (value < lowestNode->data) {
                lowestNode = newNode;
            }
            if (value > highestNode->data) {
                highestNode = newNode;
            }
        }
    }

    void deleteElement(int value) {
        ListNode* current = start;
        while (current != nullptr) {
            if (current->data == value) {
                if (current->previous) {
                    current->previous->next = current->next;
                } else {
                    start = current->next;
                }

                if (current->next) {
                    current->next->previous = current->previous;
                } else {
                    end = current->previous;
                }

                if (lowestNode == current) {
                    lowestNode = locateLowest();
                }
                if (highestNode == current) {
                    highestNode = locateHighest();
                }

                delete current;
                return;
            }
            current = current->next;
        }
    }

    int findMinimum() const {
        return lowestNode ? lowestNode->data : std::numeric_limits<int>::max();
    }

    int findMaximum() const {
        return highestNode ? highestNode->data : std::numeric_limits<int>::min();
    }

private:
    ListNode* locateLowest() const {
        ListNode* minNode = start;
        ListNode* current = start;
        while (current != nullptr) {
            if (current->data < minNode->data) {
                minNode = current;
            }
            current = current->next;
        }
        return minNode;
    }

    ListNode* locateHighest() const {
        ListNode* maxNode = start;
        ListNode* current = start;
        while (current != nullptr) {
            if (current->data > maxNode->data) {
                maxNode = current;
            }
            current = current->next;
        }
        return maxNode;
    }
};

int main() {
    EnhancedList list;
    list.addElement(10);
    list.addElement(5);
    list.addElement(15);
    list.addElement(3);

    std::cout << "Smallest: " << list.findMinimum() << std::endl; // Output: Smallest: 3
    std::cout << "Largest: " << list.findMaximum() << std::endl; // Output: Largest: 15

    list.deleteElement(15);
    std::cout << "Largest after deleting 15: " << list.findMaximum() << std::endl; // Output: Largest: 10

    return 0;
}

#include <immintrin.h>
#include <iostream>

// Perform atomic 128-bit compare-and-swap using inline assembly
bool cas128(__int128* target, __int128 expected_val, __int128 replacement_val) {
    // Save original value for comparison later
    __int128 initial = *target;

    // Prepare registers for cmpxchg16b instruction
    uint64_t low_exp = static_cast<uint64_t>(expected_val);
    uint64_t high_exp = static_cast<uint64_t>(expected_val >> 64);
    uint64_t low_new = static_cast<uint64_t>(replacement_val);
    uint64_t high_new = static_cast<uint64_t>(replacement_val >> 64);

    // Use RAX:RDX as expected (old) value and RBX:RCX as new value
    bool result = false;
    __asm__ __volatile__(
        "lock cmpxchg16b %1\n\t"
        "setz %0\n\t"
        : "=r"(result), "+m"(*target), "+a"(low_exp), "+d"(high_exp)
        : "b"(low_new), "c"(high_new)
        : "memory", "cc"
    );

    return result && (initial == expected_val);
}

int main() {
    // Initialize 128-bit value with specific pattern
    __int128 storage = 0x0123456789abcdef123456789abcdef123456789abcdef123456789abcdef;
    __int128 match_val = 0x0123456789abcdef123456789abcdef123456789abcdef123456789abcdef;
    __int128 update_val = 0x1122334455667788112233445566778811223344556677881122334455667788;

    bool outcome = cas128(&storage, match_val, update_val);

    std::cout << "Atomic operation " << (outcome ? "completed successfully" : "did not succeed") << std::endl;
    std::cout << "Final value: " << std::hex << storage << std::endl;

    return 0;
}

