#include <vector>
#include <memory>
#include <chrono>

class ZYLThreadPool {
public:
    ZYLThreadPool(size_t initialThreads = 20, size_t maxCapacity = 200)
        : _initial(initialThreads)
        , _maxCapacity(maxCapacity)
        , _shutdown(false) {
        threads.reserve(_maxCapacity);
        for (size_t t = 0; t < _initial; ++t) {
            spawn_worker();
        }
    }

    void spawn_worker() {
        threads.emplace_back([this] {
            while (true) {
                std::function<void()> job;
                {
                    std::unique_lock<std::mutex> guard(_mtx);
                    _cv.wait(guard, [this] {
                        return _shutdown || !_jobs.empty();
                    });
                    if (_shutdown && _jobs.empty())
                        break;
                    job = std::move(_jobs.front());
                    _jobs.pop_front();
                }
                job();
            }
        });
    }

    template <typename F, typename... Args>
    auto execute(F&& func, Args&&... params)
        -> std::future<typename std::result_of<F(Args...)>::type> {
        using result_type = typename std::result_of<F(Args...)>::type;

        auto packaged = std::make_shared<std::packaged_task<result_type()>>(
            std::bind(std::forward<F>(func), std::forward<Args>(params)...));

        std::future<result_type> outcome = packaged->get_future();

        {
            std::unique_lock<std::mutex> guard(_mtx);
            if (_shutdown) {
                throw std::runtime_error("Execution attempted on terminated pool");
            }
            if (_jobs.size() >= threads.size() && threads.size() < _maxCapacity) {
                spawn_worker();
            }
            _jobs.emplace_back([packaged] { (*packaged)(); });
        }
        _cv.notify_one();
        return outcome;
    }

    void shutdown() {
        std::unique_lock<std::mutex> guard(_mtx);
        if (!_shutdown) {
            _shutdown = true;
            _cv.notify_all();
        }
        for (auto& worker : threads) {
            if (worker.joinable()) {
                worker.join();
            }
        }
    }

    size_t pending_jobs() {
        std::unique_lock<std::mutex> guard(_mtx);
        return _jobs.size();
    }

    ~ZYLThreadPool() {
        shutdown();
    }

private:
    std::vector<std::thread> threads;
    std::deque<std::function<void()>> _jobs;
    size_t _initial;
    size_t _maxCapacity;
    std::mutex _mtx;
    std::condition_variable _cv;
    bool _shutdown;
};

class WorkerTask {
public:
    WorkerTask(double identifier)
        : _id(identifier)
        , _active(true) {
    }

    void launch(ZYLThreadPool& pool) {
        _result = pool.execute(&WorkerTask::_run, this);
    }

    void terminate() {
        {
            std::unique_lock<std::mutex> guard(_lock);
            _active = false;

            if (_result.valid()) {
                _result.get();
                guard.unlock();
                _finalize();
            }
        }
    }

private:
    std::mutex _lock;
    double _id;
    std::deque<double> _buffer;
    std::future<void> _result;
    bool _active;

    void _finalize() {
        std::unique_lock<std::mutex> guard(_lock);
        _buffer.clear();
    }

    void _run() {
        std::unique_lock<std::mutex> guard(_lock);
        while (_active) {
            if (_buffer.empty()) {
                std::cout << "processing task" << std::endl;
                continue;
            }
            double item = _buffer.front();
            _buffer.pop_front();
            guard.unlock();
            std::cout << "processing task" << std::endl;
            guard.lock();
        }
    }
};

int main() {
    ZYLThreadPool pool(20, 200);
    std::vector<std::shared_ptr<WorkerTask>> tasks;

    for (int idx = 0; idx < 100; ++idx) {
        auto task = std::make_shared<WorkerTask>(1.0);
        task->launch(pool);
        tasks.push_back(task);
    }

    std::this_thread::sleep_for(std::chrono::seconds(3));

    for (auto& task : tasks) {
        task->terminate();
    }
    tasks.clear();

    for (int idx = 0; idx < 3; ++idx) {
        auto task = std::make_shared<WorkerTask>(1.0);
        task->launch(pool);
        tasks.push_back(task);
    }

    std::this_thread::sleep_for(std::chrono::seconds(3));

    for (auto& task : tasks) {
        task->terminate();
    }

    return 0;
}

