#include <cuda_runtime.h>

// Texture reference declaration (assumed to be defined elsewhere)
texture<uchar, 2, cudaReadModeElementType> tex;

__global__ void convertGRBG(uchar4 *d_output, uint width, uint height) {
    // Compute pixel coordinates using block and thread indices
    int col = blockIdx.x * blockDim.x + threadIdx.x;
    int row = blockIdx.y * blockDim.y + threadIdx.y;

    // Ensure we are within image bounds
    if (col < width && row < height) {
        // Fetch the raw Bayer pixel value
        uchar raw_val = tex2D(tex, col, row);

        // Initialize output pixel components
        uchar4 result;

        // Determine pattern type based on position parity
        bool isEvenRow = (row % 2 == 0);
        bool isEvenCol = (col % 2 == 0);

        if (isEvenRow) {
            if (isEvenCol) {
                // GR pattern: center is Green, Red at center
                result.x = raw_val; // R
                // Average vertical and horizontal neighbors for G
                uchar g1 = tex2D(tex, col, row - 1);
                uchar g2 = tex2D(tex, col, row + 1);
                uchar g3 = tex2D(tex, col - 1, row);
                uchar g4 = tex2D(tex, col + 1, row);
                result.y = (g1 + g2 + g3 + g4) / 4; // G

                // Diagonal neighbors for B estimation
                uchar b1 = tex2D(tex, col - 1, row - 1);
                uchar b2 = tex2D(tex, col - 1, row + 1);
                uchar b3 = tex2D(tex, col + 1, row - 1);
                uchar b4 = tex2D(tex, col + 1, row + 1);
                result.z = (b1 + b2 + b3 + b4) / 4; // B
            } else {
                // BG pattern: center is Blue, Green at center
                // Horizontal neighbors for R
                uchar r1 = tex2D(tex, col - 1, row);
                uchar r2 = tex2D(tex, col + 1, row);
                result.x = (r1 + r2) / 2; // R

                // Vertical neighbors for G
                uchar g1 = tex2D(tex, col, row - 1);
                uchar g2 = tex2D(tex, col, row + 1);
                result.y = (g1 + g2) / 2; // G

                result.z = raw_val; // B
            }
        } else {
            if (isEvenCol) {
                // GB pattern: center is Green, Blue at center
                // Vertical neighbors for R
                uchar r1 = tex2D(tex, col, row - 1);
                uchar r2 = tex2D(tex, col, row + 1);
                result.x = (r1 + r2) / 2; // R

                // Horizontal neighbors for G
                uchar g1 = tex2D(tex, col - 1, row);
                uchar g2 = tex2D(tex, col + 1, row);
                result.y = (g1 + g2) / 2; // G

                result.z = raw_val; // B
            } else {
                // RG pattern: center is Red, Green at center
                result.x = raw_val; // R

                // Same as first case: average cross neighbors for G
                uchar g1 = tex2D(tex, col, row - 1);
                uchar g2 = tex2D(tex, col, row + 1);
                uchar g3 = tex2D(tex, col - 1, row);
                uchar g4 = tex2D(tex, col + 1, row);
                result.y = (g1 + g2 + g3 + g4) / 4; // G

                // Diagonal neighbors for B
                uchar b1 = tex2D(tex, col - 1, row - 1);
                uchar b2 = tex2D(tex, col - 1, row + 1);
                uchar b3 = tex2D(tex, col + 1, row - 1);
                uchar b4 = tex2D(tex, col + 1, row + 1);
                result.z = (b1 + b2 + b3 + b4) / 4; // B
            }
        }

        // Write result to output buffer
        d_output[row * width + col] = result;
    }
}

void launch_convertGRBG(int imgWidth, int imgHeight, dim3 threadsPerBlock, dim3 blocksPerGrid, uchar4 *deviceOutput) {
    // Launch kernel with specified configuration
    convertGRBG<<<blocksPerGrid, threadsPerBlock>>>(deviceOutput, imgWidth, imgHeight);

    // Wait for completion
    cudaDeviceSynchronize();
}

