#include <curl/curl.h>

// Function to perform HTTP GET request and return response body
std::string fetchUrlContent(const std::string& endpoint)
{
    CURL* curlHandle = nullptr;
    CURLcode operationResult;
    std::string responseBody;

    // Initialize global curl environment
    curl_global_init(CURL_GLOBAL_DEFAULT);

    // Create a new curl session
    curlHandle = curl_easy_init();
    if (curlHandle) {
        // Configure the URL for the request
        curl_easy_setopt(curlHandle, CURLOPT_URL, endpoint.c_str());

        // Set up callback to capture response data
        curl_easy_setopt(curlHandle, CURLOPT_WRITEFUNCTION, 
            [](char* buffer, size_t unitSize, size_t unitCount, std::string* output) -> size_t {
                size_t totalBytes = unitSize * unitCount;
                output->append(buffer, totalBytes);
                return totalBytes;
            });

        // Provide the storage for captured data
        curl_easy_setopt(curlHandle, CURLOPT_WRITEDATA, &responseBody);

        // Execute the HTTP request
        operationResult = curl_easy_perform(curlHandle);

        // Clean up the curl session
        curl_easy_cleanup(curlHandle);
    }

    // Clean up global curl resources
    curl_global_cleanup();

    return responseBody;
}

int main()
{
    std::string targetUrl = "http://localhost:5000/api/mycontroller/myfunction";
    std::string serverResponse = fetchUrlContent(targetUrl);
    std::cout << "Server Response: " << serverResponse << std::endl;
    return 0;
}

