string create_acronym(const string& input) {
    string result = "";

    // Process each character in the input string
    for (size_t i = 0; i < input.length(); ++i) {
        // If current character is the start of a word (first char or after whitespace)
        if (i == 0 || isspace(input[i-1])) {
            // Add the uppercase version of this character to result
            result += toupper(input[i]);
        }
    }

    return result;
}

