// WiFi network credentials
const char* wifiSSID = "your_SSID";
const char* wifiPass = "your_PASSWORD";

// LED control pin (D2 on ESP-12E)
const int ledControlPin = 4;

// Web server instance listening on port 80
ESP8266WebServer httpServer(80);

void serveMainPage() {
    String pageContent = "<!DOCTYPE html><html><head><meta charset=\"UTF-8\"><title>LED Switch</title>";
    pageContent += "<script>function switchLed(){var req=new XMLHttpRequest();";
    pageContent += "req.open('GET','/toggle',true);req.send();}</script></head><body>";
    pageContent += "<h2 style='text-align:center;'>LED Toggle Interface</h2>";
    pageContent += "<div style='text-align:center;margin-top:50px;'>";
    pageContent += "<button onclick=\"switchLed()\" style='padding:15px 30px;font-size:18px;'>Switch LED</button>";
    pageContent += "</div></body></html>";
    httpServer.send(200, "text/html", pageContent);
}

void handleLedToggle() {
    static bool isLedOn = false;
    isLedOn = !isLedOn;
    digitalWrite(ledControlPin, isLedOn ? HIGH : LOW);
    httpServer.send(200, "text/plain", isLedOn ? "ACTIVE" : "INACTIVE");
}

void setup() {
    // Initialize serial communication for debugging
    Serial.begin(115200);

    // Configure LED pin as output and ensure it's off initially
    pinMode(ledControlPin, OUTPUT);
    digitalWrite(ledControlPin, LOW);

    // Connect to WiFi network
    Serial.print("Initiating connection to ");
    Serial.println(wifiSSID);
    WiFi.begin(wifiSSID, wifiPass);

    while (WiFi.status() != WL_CONNECTED) {
        delay(500);
        Serial.print(".");
    }

    Serial.println("\nConnection established");
    Serial.print("Assigned IP address: ");
    Serial.println(WiFi.localIP());

    // Register URL handlers
    httpServer.on("/", serveMainPage);
    httpServer.on("/toggle", handleLedToggle);

    // Start HTTP server
    httpServer.begin();
    Serial.println("Web server operational");
}

void loop() {
    httpServer.handleClient();
}

