const int GRID_DIM = 10;
const std::vector<int> FLEET_LENGTHS = {5, 4, 3, 3, 2};

enum class TileState { Blank, Vessel, Strike, Miss };

class GameGrid {
private:
    std::vector<std::vector<TileState>> matrix;

public:
    GameGrid() : matrix(GRID_DIM, std::vector<TileState>(GRID_DIM, TileState::Blank)) {}

    void deployShip(int length, int r, int c, bool isRowOriented) {
        if (isRowOriented) {
            for (int k = 0; k < length; ++k) {
                matrix[r][c + k] = TileState::Vessel;
            }
        } else {
            for (int k = 0; k < length; ++k) {
                matrix[r + k][c] = TileState::Vessel;
            }
        }
    }

    bool canPlace(int length, int r, int c, bool isRowOriented) const {
        if (isRowOriented) {
            if (c + length > GRID_DIM) return false;
            for (int k = 0; k < length; ++k) {
                if (matrix[r][c + k] != TileState::Blank) return false;
            }
        } else {
            if (r + length > GRID_DIM) return false;
            for (int k = 0; k < length; ++k) {
                if (matrix[r + k][c] != TileState::Blank) return false;
            }
        }
        return true;
    }

    bool engage(int r, int c) {
        if (matrix[r][c] == TileState::Vessel) {
            matrix[r][c] = TileState::Strike;
            return true;
        } else {
            matrix[r][c] = TileState::Miss;
            return false;
        }
    }

    bool allSunk() const {
        for (const auto& line : matrix) {
            for (const auto& tile : line) {
                if (tile == TileState::Vessel) return false;
            }
        }
        return true;
    }

    void reveal() const {
        for (const auto& line : matrix) {
            for (const auto& tile : line) {
                switch (tile) {
                    case TileState::Blank: std::cout << "."; break;
                    case TileState::Vessel: std::cout << "S"; break;
                    case TileState::Strike: std::cout << "X"; break;
                    case TileState::Miss: std::cout << "O"; break;
                }
            }
            std::cout << "\n";
        }
    }
};

class Combatant {
private:
    GameGrid arena;
    std::string identity;

public:
    Combatant(const std::string& id) : identity(id) {}

    void organizeFleet() {
        std::cout << identity << ", position your vessels:\n";
        for (int len : FLEET_LENGTHS) {
            int r, c;
            bool isRowOriented;
            do {
                std::cout << "Deploy a vessel of length " << len << " (row col orientation): ";
                std::cin >> r >> c >> isRowOriented;
            } while (!arena.canPlace(len, r, c, isRowOriented));
            arena.deployShip(len, r, c, isRowOriented);
        }
    }

    bool strikeAt(Combatant& rival) {
        int r, c;
        std::cout << identity << ", target coordinates (row col): ";
        std::cin >> r >> c;
        return rival.arena.engage(r, c);
    }

    bool checkStatus() const {
        return arena.allSunk();
    }

    void showArena() const {
        std::cout << identity << "'s grid:\n";
        arena.reveal();
    }
};

int main() {
    std::srand(static_cast<unsigned>(std::time(nullptr)));

    Combatant contenderA("Contender A");
    Combatant contenderB("Contender B");

    contenderA.organizeFleet();
    contenderB.organizeFleet();

    bool turnA = true;
    while (!contenderA.checkStatus() && !contenderB.checkStatus()) {
        if (turnA) {
            contenderA.showArena();
            contenderB.showArena();
            if (contenderA.strikeAt(contenderB)) {
                std::cout << "Direct hit!\n";
            } else {
                std::cout << "Shot missed!\n";
                turnA = false;
            }
        } else {
            contenderA.showArena();
            contenderB.showArena();
            if (contenderB.strikeAt(contenderA)) {
                std::cout << "Direct hit!\n";
            } else {
                std::cout << "Shot missed!\n";
                turnA = true;
            }
        }
    }

    if (contenderA.checkStatus()) {
        std::cout << "Contender B triumphs!\n";
    } else {
        std::cout << "Contender A triumphs!\n";
    }

    return 0;
}

