class TextLoader {
public:
    static TextLoader& get() {
        static TextLoader loader;
        return loader;
    }

    void loadText(const std::string& path) {
        if (cache.find(path) == cache.end()) {
            std::ifstream inputStream(path);
            std::string content;
            if (inputStream.is_open()) {
                std::string currentLine;
                while (std::getline(inputStream, currentLine)) {
                    content.append(currentLine).append("\n");
                }
                inputStream.close();
                cache[path] = content;
            }
        }
    }

    const std::string& retrieve(const std::string& path) {
        return cache[path];
    }

private:
    TextLoader() {}
    std::map<std::string, std::string> cache;
};

extern "C" {
    JNIEXPORT void JNICALL Java_com_example_FileParser_nativeParseFile(JNIEnv* env, jobject obj, jstring filePath) {
        const char* cPath = env->GetStringUTFChars(filePath, 0);
        TextLoader::get().loadText(cPath);
        env->ReleaseStringUTFChars(filePath, cPath);
