    JNIEXPORT jstring JNICALL Java_com_example_FileParser_nativeGetData(JNIEnv* env, jobject obj, jstring filePath) {
        const char* cPath = env->GetStringUTFChars(filePath, 0);
        std::string result = TextLoader::get().retrieve(cPath);
        env->ReleaseStringUTFChars(filePath, cPath);
        return env->NewStringUTF(result.c_str());
    }
}

