// 3D point representation
struct Vector3 {
    double x, y, z;
    Vector3(double x = 0.0, double y = 0.0, double z = 0.0) : x(x), y(y), z(z) {}

    // Vector operations
    Vector3 operator-(const Vector3& other) const {
        return Vector3(x - other.x, y - other.y, z - other.z);
    }

    double dot(const Vector3& other) const {
        return x * other.x + y * other.y + z * other.z;
    }
};

// Hermite curve definition using control points and tangents
struct SplineHermite {
    Vector3 start, end, tangentStart, tangentEnd;

    SplineHermite(Vector3 s, Vector3 e, Vector3 ts, Vector3 te) 
        : start(s), end(e), tangentStart(ts), tangentEnd(te) {}

    // Evaluate point on curve at parameter t (0 <= t <= 1)
    Vector3 evaluate(double t) const {
        double t2 = t * t;
        double t3 = t2 * t;

        // Hermite basis functions
        double h00 = 2 * t3 - 3 * t2 + 1;
        double h10 = t3 - 2 * t2 + t;
        double h01 = -2 * t3 + 3 * t2;
        double h11 = t3 - t2;

        // Interpolate using control points and tangents
        double px = h00 * start.x + h10 * tangentStart.x + h01 * end.x + h11 * tangentEnd.x;
        double py = h00 * start.y + h10 * tangentStart.y + h01 * end.y + h11 * tangentEnd.y;
        double pz = h00 * start.z + h10 * tangentStart.z + h01 * end.z + h11 * tangentEnd.z;

        return Vector3(px, py, pz);
    }
};

// Solve cubic equation ax^3 + bx^2 + cx + d = 0 for real roots
double solveCubic(double a, double b, double c, double d) {
    if (abs(a) < 1e-10) {  // Handle degenerate case (quadratic or linear)
        if (abs(b) < 1e-10) {
            return -d / c;  // Linear case
        }
        // Quadratic formula: bx^2 + cx + d = 0
        double discriminant = c * c - 4 * b * d;
        if (discriminant >= 0) {
            double root1 = (-c + sqrt(discriminant)) / (2 * b);
            double root2 = (-c - sqrt(discriminant)) / (2 * b);
            return max(root1, root2);
        }
        return -c / (2 * b);  // Complex roots, return vertex
    }

    // For cubic: ax^3 + bx^2 + cx + d = 0
    // Convert to depressed cubic: t^3 + pt + q = 0
    double p = (3 * a * c - b * b) / (3 * a * a);
    double q = (2 * b * b * b - 9 * a * b * c + 27 * a * a * d) / (27 * a * a * a);

    // Cardano's formula
    double discriminant = q * q / 4 + p * p * p / 27;

    if (discriminant > 0) {
        // One real root
        double u = cbrt(-q/2 + sqrt(discriminant));
        double v = cbrt(-q/2 - sqrt(discriminant));
        return u + v - b / (3 * a);
    } else if (abs(discriminant) < 1e-10) {
        // Multiple roots
        double root = -b / (3 * a);
        if (abs(p) < 1e-10) return root;
        double otherRoot = -3 * q / (2 * p);
        return max(root, otherRoot);
    } else {
        // Three real roots - use trigonometric solution
        double phi = acos(-q / 2 * sqrt(-27 / (p * p * p))) / 3;
        double r = 2 * sqrt(-p / 3);
        double root1 = r * cos(phi) - b / (3 * a);
        double root2 = r * cos(phi + 2.094395102) - b / (3 * a);
        double root3 = r * cos(phi + 4.188790205) - b / (3 * a);
        return max(root1, max(root2, root3));
    }
}

// Find approximate intersection point of two Hermite curves
Vector3 findCurveIntersection(const SplineHermite& spline1, const SplineHermite& spline2) {
    // Define relative vectors for distance minimization
    Vector3 relStart = spline1.start - spline2.start;
    Vector3 relEnd = spline1.end - spline2.end;
    Vector3 relTanStart = spline1.tangentStart - spline2.tangentStart;
    Vector3 relTanEnd = spline1.tangentEnd - spline2.tangentEnd;

    // Coefficients for the derivative of squared distance function
    // D(t) = |P1(t) - P2(t)|^2
    // We find critical points by solving D'(t) = 0

    // Compute dot products needed for coefficients
    double A = relStart.dot(relStart);
    double B = 2 * relStart.dot(relEnd - relStart - relTanStart);
    double C = 2 * relStart.dot(relTanStart) + (relEnd - relStart - relTanStart).dot(relEnd - relStart - relTanStart);
    double D = 2 * (relEnd - relStart - relTanStart).dot(relTanStart);
    double E = relTanStart.dot(relTanStart);

    // Derivative is cubic: at^3 + bt^2 + ct + d = 0
    double a = 9 * B + 6 * C;
    double b = 18 * A + 12 * B + 3 * C - 9 * D;
    double c = 12 * A + 6 * B - 6 * D + 3 * E;
    double d = 3 * A - 3 * D;

    // Find parameter value that minimizes distance
    double tParam = solveCubic(a, b, c, d);

    // Clamp to valid range [0,1]
    if (tParam < 0) tParam = 0;
    if (tParam > 1) tParam = 1;

    return spline1.evaluate(tParam);
}

int main() {
    // Define first Hermite curve
    Vector3 start1(0, 0, 0), end1(1, 1, 1);
    Vector3 tan1_start(1, 0, 0), tan1_end(0, 1, 0);
    SplineHermite path1(start1, end1, tan1_start, tan1_end);

    // Define second Hermite curve
    Vector3 start2(1, 0, 0), end2(0, 1, 1);
    Vector3 tan2_start(-1, 0, 0), tan2_end(0, -1, 0);
    SplineHermite path2(start2, end2, tan2_start, tan2_end);

    // Calculate intersection
    Vector3 intersectPoint = findCurveIntersection(path1, path2);
    cout << "Intersection: " << intersectPoint.x << ", " << intersectPoint.y << ", " << intersectPoint.z << endl;

    return 0;
}

