// Constants for the 2x2 grid environment
const int NUM_STATES = 4;
const int NUM_ACTIONS = 4;
const double LEARNING_RATE = 0.1;
const double DISCOUNT_FACTOR = 0.9;
const double EXPLORATION_RATE = 0.1;

// Q-value table initialized to zero
std::vector<std::vector<double>> qTable(NUM_STATES, std::vector<double>(NUM_ACTIONS, 0.0));

// Simulate transition based on current state and action
int simulateTransition(int currentState, int move) {
    switch (move) {
        case 0: // Move up
            return (currentState >= 2) ? currentState - 2 : currentState;
        case 1: // Move down
            return (currentState <= 1) ? currentState + 2 : currentState;
        case 2: // Move left
            return (currentState == 1 || currentState == 3) ? currentState - 1 : currentState;
        case 3: // Move right
            return (currentState == 0 || currentState == 2) ? currentState + 1 : currentState;
        default:
            return currentState;
    }
}

// Compute reward for reaching the terminal state
double computeReward(int finalState) {
    return (finalState == 3) ? 100.0 : 0.0;
}

// Choose action using epsilon-greedy policy
int chooseAction(int state) {
    if (static_cast<double>(rand()) / RAND_MAX < EXPLORATION_RATE) {
        return rand() % NUM_ACTIONS; // Random exploration
    } else {
        auto maxIt = std::max_element(qTable[state].begin(), qTable[state].end());
        return static_cast<int>(std::distance(qTable[state].begin(), maxIt)); // Best known action
    }
}

// Perform one Q-learning update step
void performQUpdate(int state, int action, int nextS) {
    double bestNextQ = *std::max_element(qTable[nextS].begin(), qTable[nextS].end());
    double currentQ = qTable[state][action];
    double newQ = currentQ + LEARNING_RATE * (computeReward(nextS) + DISCOUNT_FACTOR * bestNextQ - currentQ);
    qTable[state][action] = newQ;
}

int main() {
    srand(static_cast<unsigned>(time(nullptr)));

    int current = 0;
    for (int episode = 0; episode < 1000; ++episode) {
        int action = chooseAction(current);
        int next = simulateTransition(current, action);
        performQUpdate(current, action, next);
        current = next;

        if (current == 3) {
            current = 0; // Reset to initial state after goal reached
        }
    }

    // Output learned Q-values
    for (const auto &row : qTable) {
        for (double val : row) {
            std::cout << val << " ";
        }
        std::cout << "\n";
    }

    return 0;
}

