namespace capy = boost::capy;

// Renamed and restructured slow_fetch: now returns std::string via co_return
capy::task<std::string> fetch_with_steps(int count)
{
    auto token = co_await capy::this_coro::stop_token;
    std::string buffer;

    int idx = 0;
    do {
        if (token.stop_requested()) {
            std::cout << "  Stopped at iteration " << idx << std::endl;
            throw std::system_error{
                make_error_code(std::errc::operation_canceled)
            };
        }

        buffer.append("step").append(std::to_string(idx)).append(" ");

        // Simulate work
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
        std::cout << "  Finished step " << idx << std::endl;

        // Yield opportunity for cancellation before next check
        std::this_thread::sleep_for(std::chrono::milliseconds(15));
        ++idx;
    } while (idx < count);

    co_return buffer;
}

// Wrapper with timeout-like behavior: catches cancellation and returns std::nullopt
capy::task<std::optional<std::string>> attempt_fetch()
{
    auto token = co_await capy::this_coro::stop_token;

    try {
        auto fetched = co_await fetch_with_steps(5);
        co_return fetched;
    }
    catch (std::system_error const& ex) {
        if (ex.code() == std::errc::operation_canceled) {
            co_return std::nullopt;
        }
        std::rethrow_exception(std::current_exception());
    }
}

// Helper to run async with promise-based completion
void launch_task(
    capy::thread_pool& pool,
    std::stop_source& src,
    std::function<void(std::optional<std::string>)> on_success,
    std::function<void(std::exception_ptr)> on_error)
{
    auto fut = std::promise<std::optional<std::string>>{};
    auto future_obj = fut.get_future();

    capy::run_async(pool.get_executor(), src.get_token(),
        [p = std::move(fut), cb = std::move(on_success)](auto&& res) mutable {
            p.set_value(std::forward<decltype(res)>(res));
            cb(res);
        },
        [p = std::move(fut), cb = std::move(on_error)](auto&& eptr) mutable {
            p.set_exception(std::forward<decltype(eptr)>(eptr));
            cb(eptr);
        }
    )(attempt_fetch());

    // Wait synchronously for completion
    future_obj.wait();
}

void demo_successful_run()
{
    std::cout << "Scenario: Successful fetch\n";
    capy::thread_pool pool;
    std::stop_source cancel_src;

    launch_task(pool, cancel_src,
        [](auto&& result) {
            if (result.has_value())
                std::cout << "Fetched: " << *result << "\n";
            else
                std::cout << "Operation was cancelled\n";
        },
        [](auto&& eptr) {
            std::cout << "Exception occurred\n";
        }
    );
}

void demo_cancelled_run()
{
    std::cout << "\nScenario: Cancel after ~42ms\n";
    capy::thread_pool pool;
    std::stop_source cancel_src;

    launch_task(pool, cancel_src,
        [](auto&& result) {
            if (result.has_value())
                std::cout << "Fetched: " << *result << "\n";
            else
                std::cout << "Cancelled (returned nullopt)\n";
        },
        [](auto&&) {
            std::cout << "Exception during execution\n";
        }
    );

    // Delay to let first few steps complete before requesting stop
    std::this_thread::sleep_for(std::chrono::milliseconds(42));
    std::cout << "  Triggering cancellation...\n";
    cancel_src.request_stop();
}

// Alternative processor: sums items until cancellation
capy::task<int> accumulate_until_stop(std::vector<int> const& data)
{
    auto token = co_await capy::this_coro::stop_token;
    int total = 0;

    for (size_t i = 0; i < data.size(); ++i) {
        if (token.stop_requested()) {
            std::cout << "Accumulation halted early. Partial sum: " << total << "\n";
            co_return total;
        }

        total += data[i];
    }

    co_return total;
}

int main()
{
    demo_successful_run();
    demo_cancelled_run();

    return 0;
}

