inline i64 gcd(i64 a, i64 b) { return std::gcd(a, b); }
inline i64 lcm(i64 a, i64 b) { return (a / std::gcd(a, b)) * b; }

// Optimized modular exponentiation
inline i64 modpow(i64 base, i64 exp, i64 mod = MOD) {
    i64 res = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return res;
}

void solve() {
    i64 n; cin >> n;

    v1(d, n); take(d);

    // Sort divisors to access min and max efficiently
    sort(all(d));

    // Candidate secret number: product of smallest and largest divisor
    i64 candidateX = d[0] * d[n - 1];

    // Collect actual divisors of candidateX (excluding 1 and the number itself)
    vec<i64> computedDivs;

    // Iterate up to sqrt(candidateX), collecting divisor pairs
    for (i64 i = 2; i * i <= candidateX; ++i) {
        if (candidateX % i == 0) {
            computedDivs.pb(i);
            if (i != candidateX / i) {
                computedDivs.pb(candidateX / i);
            }
        }
    }

    // Sort computed divisors for comparison
    sort(all(computedDivs));

    // Check if computed list matches input list exactly
    if (computedDivs == d) {
        cout << candidateX << nl;
    } else {
        cout << -1 << nl;
    }
}

