// Helper to trim quotes from command-line argument
std::string TrimQuotes(const std::string& input) {
    if (input.size() >= 2 && input.front() == '"' && input.back() == '"') {
        return input.substr(1, input.size() - 2);
    }
    return input;
}

// RunDLL entry point to start a game and inject into it
extern "C" __declspec(dllexport) void CALLBACK StartAndInject(HWND hwnd, HINSTANCE hInst, LPSTR lpszCmdLine, int nCmdShow) {
    UNREFERENCED_PARAMETER(hwnd);
    UNREFERENCED_PARAMETER(hInst);
    UNREFERENCED_PARAMETER(nCmdShow);

    // Initialize logging configuration
    auto& config_mgr = display_commander::config::DisplayCommanderConfigManager::GetInstance();
    config_mgr.Initialize();
    config_mgr.SetAutoFlushLogs(true);

    // Extract executable path from command line
    std::string raw_cmd = lpszCmdLine ? std::string(lpszCmdLine) : "";
    std::string exe_path_ansi = TrimQuotes(raw_cmd);

    if (exe_path_ansi.empty()) {
        OutputDebugStringA(
            "StartAndInject: No exe path provided. Usage: rundll32.exe zzz_display_commander.addon64,StartAndInject "
            "\"C:\\Path\\To\\game.exe\"");
        return;
    }

    // Convert ANSI string to wide string
    int required_chars = MultiByteToWideChar(CP_ACP, 0, exe_path_ansi.c_str(), -1, nullptr, 0);
    if (required_chars <= 0) {
        OutputDebugStringA("StartAndInject: Failed to convert exe path to wide string");
        return;
    }

    std::vector<wchar_t> wide_buffer(required_chars);
    MultiByteToWideChar(CP_ACP, 0, exe_path_ansi.c_str(), -1, wide_buffer.data(), required_chars);
    std::wstring exe_path_wide(wide_buffer.begin(), wide_buffer.end() - 1); // exclude null terminator

    // Validate existence of executable
    if (!std::filesystem::exists(exe_path_wide)) {
        OutputDebugStringA(std::format("StartAndInject: Exe file not found: {}", exe_path_ansi).c_str());
        return;
    }

    OutputDebugStringA(std::format("StartAndInject: Starting process: {}", exe_path_ansi).c_str());

    // Launch process
    STARTUPINFOW startup_info = {};
    PROCESS_INFORMATION proc_info = {};
    startup_info.cb = sizeof(startup_info);

    std::wstring cmd_line = L"\"" + exe_path_wide + L"\"";
    if (!CreateProcessW(nullptr, cmd_line.data(), nullptr, nullptr, FALSE, 0, nullptr, nullptr, &startup_info, &proc_info)) {
        DWORD err_code = GetLastError();
        OutputDebugStringA(std::format("StartAndInject: Failed to start process: Error {} (0x{:X})", err_code, err_code).c_str());
        return;
    }

    CloseHandle(proc_info.hThread); // Keep only process handle

    OutputDebugStringA(std::format("StartAndInject: Process started (PID {})", proc_info.dwProcessId).c_str());

    // Allow time for initialization
    Sleep(500);

    // Detect WoW64 status
    BOOL is_wow64 = FALSE;
    IsWow64Process(proc_info.hProcess, &is_wow64);

    // Locate appropriate ReShade DLL
    std::wstring reshade_dll = GetReShadeDllPath(is_wow64 != FALSE);
    if (reshade_dll.empty()) {
        OutputDebugStringA("StartAndInject: Failed to find ReShade DLL path");
        CloseHandle(proc_info.hProcess);
        return;
    }

    // Perform injection
    bool injected = InjectIntoProcess(proc_info.dwProcessId, reshade_dll);
    CloseHandle(proc_info.hProcess);

    if (injected) {
        OutputDebugStringA(
            std::format("StartAndInject: Successfully started and injected into process (PID {})", proc_info.dwProcessId).c_str());
    } else {
        OutputDebugStringA(
            std::format("StartAndInject: Failed to inject into process (PID {})", proc_info.dwProcessId).c_str());
    }
}

// RunDLL entry point to wait for process and inject
extern "C" __declspec(dllexport) void CALLBACK WaitAndInject(HWND hwnd, HINSTANCE hInst, LPSTR lpszCmdLine, int nCmdShow) {
    UNREFERENCED_PARAMETER(hwnd);
    UNREFERENCED_PARAMETER(hInst);
    UNREFERENCED_PARAMETER(nCmdShow);

    // Initialize logging configuration
    auto& config_mgr = display_commander::config::DisplayCommanderConfigManager::GetInstance();
    config_mgr.Initialize();
    config_mgr.SetAutoFlushLogs(true);

    // Parse target executable name
    std::string raw_input = lpszCmdLine ? std::string(lpszCmdLine) : "";
    std::string exe_name_ansi = TrimQuotes(raw_input);

    if (exe_name_ansi.empty()) {
        OutputDebugStringA(
            "WaitAndInject: No exe name provided. Usage: rundll32.exe zzz_display_commander.addon64,WaitAndInject "
            "\"game.exe\"");
        return;
    }

    // Convert to wide string
    int needed = MultiByteToWideChar(CP_ACP, 0, exe_name_ansi.c_str(), -1, nullptr, 0);
    if (needed <= 0) {
        OutputDebugStringA("WaitAndInject: Failed to convert exe name to wide string");
        return;
    }

    std::vector<wchar_t> wide_buf(needed);
    MultiByteToWideChar(CP_ACP, 0, exe_name_ansi.c_str(), -1, wide_buf.data(), needed);
    std::wstring exe_name_wide(wide_buf.begin(), wide_buf.end() - 1);

    // Normalize to filename only
    std::filesystem::path full_path(exe_name_wide);
    std::wstring base_name = full_path.filename().wstring();

    // Log and print waiting info
    std::string base_name_ansi(base_name.begin(), base_name.end());
    OutputDebugStringA(std::format("WaitAndInject: Waiting for process: {} (comparing against: {})", exe_name_ansi, base_name_ansi).c_str());
    std::cout << "WaitAndInject: Waiting for process: " << exe_name_ansi
              << " (comparing against: " << base_name_ansi << ")" << std::endl;

    // Begin monitoring for new processes
    WaitForProcessAndInject(base_name);
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> arr(n + 1), indexPos(n + 1);
    for (int idx = 1; idx <= n; ++idx) {
        cin >> arr[idx];
        indexPos[arr[idx]] = idx;
    }

    // Determine operation pattern: x=1 for small n, x=3 otherwise
    int mode = (n <= 2) ? 1 : 3;
    vector<pair<int, int>> operations;
    operations.reserve(200000);

    // Function to reverse segment [l, r] and update positions accordingly
    auto applyReverse = [&](int left, int right) {
        while (left < right) {
            int valLeft = arr[left];
            int valRight = arr[right];

            swap(arr[left], arr[right]);
            indexPos[valLeft] = right;
            indexPos[valRight] = left;

            ++left;
            --right;
        }
    };

    if (mode == 1) {
        // For n <= 2: only adjacent swaps needed
        for (int target = 1; target <= n; ++target) {
            while (indexPos[target] > target) {
                int pos = indexPos[target];
                operations.emplace_back(pos - 1, pos);
                applyReverse(pos - 1, pos);
            }
        }
    } else {
        // For n > 2: use both length-2 and length-4 reversals
        for (int target = 1; target <= n; ++target) {
            // First try to move element to position using length-4 moves when possible
            while (indexPos[target] >= target + 3) {
                int pos = indexPos[target];
                operations.emplace_back(pos - 3, pos);
                applyReverse(pos - 3, pos);
            }
            // Then use length-2 moves for remaining distance
            while (indexPos[target] > target) {
                int pos = indexPos[target];
                operations.emplace_back(pos - 1, pos);
                applyReverse(pos - 1, pos);
            }
        }
    }

    cout << mode << "\n";
    cout << operations.size() << "\n";
    for (const auto& op : operations) {
        cout << op.first << " " << op.second << "\n";
    }

    return 0;
}

