// Helper: apply binary op to corresponding fields of two PerformanceIndex objects
template <typename Op>
void applyFieldwise(PerformanceIndex& lhs, const PerformanceIndex& rhs, Op&& op) {
  op(lhs.merit, rhs.merit);
  op(lhs.cost, rhs.cost);
  op(lhs.dualFeasibilitiesSSE, rhs.dualFeasibilitiesSSE);
  op(lhs.dynamicsViolationSSE, rhs.dynamicsViolationSSE);
  op(lhs.equalityConstraintsSSE, rhs.equalityConstraintsSSE);
  op(lhs.inequalityConstraintsSSE, rhs.inequalityConstraintsSSE);
  op(lhs.equalityLagrangian, rhs.equalityLagrangian);
  op(lhs.inequalityLagrangian, rhs.inequalityLagrangian);
}

PerformanceIndex& PerformanceIndex::operator+=(const PerformanceIndex& rhs) {
  applyFieldwise(*this, rhs, [](auto& a, const auto& b) { a += b; });
  return *this;
}

PerformanceIndex& PerformanceIndex::operator*=(const scalar_t c) {
  // Use temporary to avoid aliasing issues in case of self-multiplication
  PerformanceIndex tmp = *this;
  applyFieldwise(tmp, PerformanceIndex{}, [c](auto& val, const auto&) { val *= c; });
  *this = std::move(tmp);
  return *this;
}

bool PerformanceIndex::isApprox(const PerformanceIndex& other, const scalar_t prec) const {
  auto check_field = [&](const char*, const scalar_t& a, const scalar_t& b) {
    return numerics::almost_eq(a, b, prec);
  };

  return check_field("merit", merit, other.merit) &&
         check_field("cost", cost, other.cost) &&
         check_field("dualFeasibilitiesSSE", dualFeasibilitiesSSE, other.dualFeasibilitiesSSE) &&
         check_field("dynamicsViolationSSE", dynamicsViolationSSE, other.dynamicsViolationSSE) &&
         check_field("equalityConstraintsSSE", equalityConstraintsSSE, other.equalityConstraintsSSE) &&
         check_field("inequalityConstraintsSSE", inequalityConstraintsSSE, other.inequalityConstraintsSSE) &&
         check_field("equalityLagrangian", equalityLagrangian, other.equalityLagrangian) &&
         check_field("inequalityLagrangian", inequalityLagrangian, other.inequalityLagrangian);
}

void swap(PerformanceIndex& lhs, PerformanceIndex& rhs) noexcept {
  using std::swap;
  swap(lhs.merit, rhs.merit);
  swap(lhs.cost, rhs.cost);
  swap(lhs.dualFeasibilitiesSSE, rhs.dualFeasibilitiesSSE);
  swap(lhs.dynamicsViolationSSE, rhs.dynamicsViolationSSE);
  swap(lhs.equalityConstraintsSSE, rhs.equalityConstraintsSSE);
  swap(lhs.inequalityConstraintsSSE, rhs.inequalityConstraintsSSE);
  swap(lhs.equalityLagrangian, rhs.equalityLagrangian);
  swap(lhs.inequalityLagrangian, rhs.inequalityLagrangian);
}

// Internal helper to initialize from Metrics once
static PerformanceIndex makeFromMetrics(const Metrics& m) {
  PerformanceIndex pi;
  pi.merit = 0.0;
  pi.cost = m.cost;
  pi.dualFeasibilitiesSSE = 0.0;
  pi.dynamicsViolationSSE = getEqConstraintsSSE(m.dynamicsViolation);
  pi.equalityConstraintsSSE =
      getEqConstraintsSSE(m.stateEqConstraint) + getEqConstraintsSSE(m.stateInputEqConstraint);
  pi.inequalityConstraintsSSE =
      getIneqConstraintsSSE(m.stateIneqConstraint) + getIneqConstraintsSSE(m.stateInputIneqConstraint);
  pi.equalityLagrangian =
      sumPenalties(m.stateEqLagrangian) + sumPenalties(m.stateInputEqLagrangian);
  pi.inequalityLagrangian =
      sumPenalties(m.stateIneqLagrangian) + sumPenalties(m.stateInputIneqLagrangian);
  return pi;
}

PerformanceIndex toPerformanceIndex(const Metrics& m) {
  return makeFromMetrics(m);
}

PerformanceIndex toPerformanceIndex(const Metrics& m, const scalar_t dt) {
  auto pi = makeFromMetrics(m);
  // Skip scaling cost — already accounted for elsewhere
  pi.dualFeasibilitiesSSE *= dt;
  pi.dynamicsViolationSSE *= dt;
  pi.equalityConstraintsSSE *= dt;
  pi.inequalityConstraintsSSE *= dt;
  return pi;
}

std::ostream& operator<<(std::ostream& stream, const PerformanceIndex& pi) {
  const size_t tabSpace = 12;
  const auto indent = stream.width();

  // Define field labels and accessors as pairs
  struct FieldEntry {
    const char* label;
    std::function<scalar_t(const PerformanceIndex&)> getter;
  };
  const std::vector<FieldEntry> fields = {
      {"Rollout Merit:",              [](const auto& p) -> scalar_t { return p.merit; }},
      {"Rollout Cost:",               [](const auto& p) -> scalar_t { return p.cost; }},
      {"Dual feasibilities SSE:",     [](const auto& p) -> scalar_t { return p.dualFeasibilitiesSSE; }},
      {"Dynamics violation SSE:",     [](const auto& p) -> scalar_t { return p.dynamicsViolationSSE; }},
      {"Equality constraints SSE:",   [](const auto& p) -> scalar_t { return p.equalityConstraintsSSE; }},
      {"Inequality constraints SSE:", [](const auto& p) -> scalar_t { return p.inequalityConstraintsSSE; }},
      {"Equality Lagrangian:",        [](const auto& p) -> scalar_t { return p.equalityLagrangian; }},
      {"Inequality Lagrangian:",      [](const auto& p) -> scalar_t { return p.inequalityLagrangian; }}
  };

  stream << std::left;
  for (size_t i = 0; i < fields.size(); ++i) {
    if (i % 2 == 0) {
      stream << std::setw(indent) << "";
    }
    stream << fields[i].label << std::setw(tabSpace) << fields[i].getter(pi);
    if (i % 2 == 1 || i == fields.size() - 1) {
      stream << '\n';
    } else {
      stream << ' ';
    }
  }

  return stream;
}

