#include <bits/stdc++.h>

int main(int argc, char ** argv) {
    registerInteraction(argc, argv);
    std::cout.setf(std::ios::fixed);
    std::cout.precision(20);

    int n = inf.readInt();
    println(n);

    std::vector<int> original_a(n);
    for (int idx = 0; idx < n; ++idx) {
        original_a[idx] = inf.readInt();
    }

    std::vector<int> original_b(n);
    for (int idx = 0; idx < n; ++idx) {
        original_b[idx] = inf.readInt();
    }

    int query_count = 0;
    const int MAX_QUERIES = 10000;

    while (query_count <= MAX_QUERIES) {
        std::string action = ouf.readToken();

        if (action == "?") {
            long double x_val = ouf.readDouble();
            if (!std::isfinite(x_val) || x_val < -1e12 || x_val > 1e12) {
                quitf(_wa, "Invalid query: element %.4f is out of range [-1000000000000, 1000000000000]", x_val);
            }

            long double y_val = ouf.readDouble();
            if (!std::isfinite(y_val) || y_val < -1e12 || y_val > 1e12) {
                quitf(_wa, "Invalid query: element %.4f is out of range [-1000000000000, 1000000000000]", y_val);
            }

            long double total_sum = 0.0L;
            for (int i = 0; i < n; ++i) {
                long double numerator = std::abs(static_cast<long double>(original_a[i]) * x_val - y_val + static_cast<long double>(original_b[i]));
                long double denominator = std::sqrt(static_cast<long double>(original_a[i]) * original_a[i] + 1.0L);
                total_sum += numerator / denominator;
            }
            std::cout << total_sum << std::endl;

        } else if (action == "!") {
            std::vector<int> guessed_a(n);
            for (int i = 0; i < n; ++i) {
                guessed_a[i] = ouf.readInt();
            }

            std::vector<int> guessed_b(n);
            for (int i = 0; i < n; ++i) {
                guessed_b[i] = ouf.readInt();
            }

            std::vector<int> indices(n);
            for (int i = 0; i < n; ++i) {
                indices[i] = i;
            }

            std::sort(indices.begin(), indices.end(), [&](int i, int j) {
                return std::make_pair(guessed_a[i], guessed_b[i]) < std::make_pair(guessed_a[j], guessed_b[j]);
            });

            bool correct = true;
            for (int pos = 0; pos < n; ++pos) {
                int orig_idx = indices[pos];
                if (guessed_a[orig_idx] != original_a[pos] || guessed_b[orig_idx] != original_b[pos]) {
                    correct = false;
                    break;
                }
            }

            if (!correct) {
                quitp(0.0, "Wrong guess. Ratio: 0.0000");
            }

            double score = 1.0;
            if (query_count > 402) {
                score = 1.0 - 0.7 * (query_count - 402) / (MAX_QUERIES - 402);
                if (score < 0.0) score = 0.0;
            }

            double unbounded_score = 1.0 - 0.7 * (query_count - 402) / (MAX_QUERIES - 402);
            if (unbounded_score < 0.0) unbounded_score = 0.0;

            quitp(score, "Correct guess. Ratio: %.4f, RatioUnbounded: %.4f", score, unbounded_score);

        } else {
            quitf(_wa, "Invalid action type: expected ? or !, but got %s", action.c_str());
        }

        ++query_count;
    }

    quitp(0.0, "Too many queries. Ratio: 0.0000");
    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

// Function to count prime numbers less than n using optimized Sieve of Eratosthenes
int countPrimes(int limit) {
    if (limit <= 2) return 0;

    vector<bool> isComposite(limit, false);
    int primeCount = 0;

    for (int current = 2; current < limit; current++) {
        if (!isComposite[current]) {
            primeCount++;
            // Mark multiples starting from current*current for efficiency
            for (int multiple = current * current; multiple < limit; multiple += current) {
                isComposite[multiple] = true;
            }
        }
    }

    return primeCount;
}

int main() {
    int n = 10;
    cout << "Count of prime numbers less than " << n << " is: " << countPrimes(n) << endl;
    return 0;
}

