#include <iostream>
#include <fstream>
#include <stdexcept>
#include <optional>

// g++ disk.cpp -o disk  -lboost_thread -lboost_system
class OnDiskIntArray {
public:
    OnDiskIntArray(const std::string& filename) : filename_(filename) {
        // Attempt to open file for read/write in binary mode
        file_.open(filename_, std::ios::in | std::ios::out | std::ios::binary);

        // If file doesn't exist or couldn't be opened, create it
        if (!file_) {
            file_.clear();
            // Create the file by opening in output-only mode
            file_.open(filename_, std::ios::out | std::ios::binary);
            file_.close(); // Close immediately after creation

            // Reopen with full read/write access
            file_.open(filename_, std::ios::in | std::ios::out | std::ios::binary);
        }
    }

    ~OnDiskIntArray() {
        if (file_.is_open()) {
            file_.close();
        }
    }

    int getByIndex(std::size_t index) {
        // Check if requested value is cached in buffer
        if (cache_ && cache_->position == index) {
            return cache_->storedValue;
        }

        // Compute byte offset and read from disk
        std::size_t byteOffset = index * sizeof(int);
        file_.seekg(byteOffset, std::ios::beg);

        int retrievedValue;
        file_.read(reinterpret_cast<char*>(&retrievedValue), sizeof(int));

        // Verify full read occurred
        if (file_.gcount() != static_cast<std::streamsize>(sizeof(int))) {
            throw std::out_of_range("Accessed index beyond array bounds");
        }

        // Update cache with new data
        cache_ = CacheEntry{index, retrievedValue};
        return retrievedValue;
    }

    void add(int newValue) {
        // Move to end of file before appending
        file_.seekp(0, std::ios::end);
        file_.write(reinterpret_cast<const char*>(&newValue), sizeof(int));

        if (!file_) {
            throw std::ios_base::failure("Write operation failed on disk storage");
        }
    }

    void set(std::size_t index, int newValue) {
        // Calculate position in file
        std::size_t byteOffset = index * sizeof(int);
        file_.seekp(byteOffset, std::ios::beg);

        // Write new value at specified location
        file_.write(reinterpret_cast<const char*>(&newValue), sizeof(int));

        if (!file_) {
            throw std::ios_base::failure("Failed to update value at specified index");
        }

        // Update cache if current entry matches updated index
        if (cache_ && cache_->position == index) {
            cache_->storedValue = newValue;
        }
    }

    std::size_t count() {
        // Determine total file size
        file_.seekg(0, std::ios::end);
        std::streampos pos = file_.tellg();

        if (pos == static_cast<std::streampos>(-1)) {
            throw std::ios_base::failure("Unable to retrieve file size information");
        }

        // Return number of integers stored
        return static_cast<std::size_t>(pos) / sizeof(int);
    }

private:
    struct CacheEntry {
        std::size_t position;
        int storedValue;
    };

    std::string filename_;
    std::fstream file_;
    std::optional<CacheEntry> cache_;
};

int main() {
    try {
        OnDiskIntArray storage("data.bin");

        // Add some initial values
        storage.add(10);
        storage.add(20);
        storage.add(30);

        // Display stored values
        std::cout << "Position 0: " << storage.getByIndex(0) << std::endl;
        std::cout << "Position 1: " << storage.getByIndex(1) << std::endl;
        std::cout << "Position 2: " << storage.getByIndex(2) << std::endl;

        // Modify existing value
        storage.set(1, 25);
        std::cout << "Position 1 after modification: " << storage.getByIndex(1) << std::endl;

        // Show final array statistics
        std::cout << "Total elements: " << storage.count() << std::endl;
        std::cout << "Last element at index " << (storage.count()-1) << ": " 
                  << storage.getByIndex(storage.count()-1) << std::endl;

    } catch (const std::exception& error) {
        std::cerr << "Exception caught: " << error.what() << std::endl;
        return 1;
    }

    return 0;
}

#include <nanobind/nanobind.h>
#include <nanobind/stl/shared_ptr.h>
#include <nanobind/stl/string.h>
#include <mscclpp/sm_channel.hpp>

namespace nb = nanobind;
using namespace mscclpp;

void bind_sm_channel(nb::module_& module) {
  // Bind SmChannel class
  nb::class_<SmChannel> smChannelClass(module, "SmChannel");
  smChannelClass
      .def("__init__",
           [](SmChannel* instance, std::shared_ptr<SmDevice2DeviceSemaphore> sem, RegisteredMemory dstMem, uintptr_t srcAddr) {
             new (instance) SmChannel(sem, dstMem, reinterpret_cast<void*>(srcAddr));
           })
      .def("__init__",
           [](SmChannel* instance, std::shared_ptr<SmDevice2DeviceSemaphore> sem, RegisteredMemory dstMem, uintptr_t srcAddr, uintptr_t pktBufAddr) {
             new (instance) SmChannel(sem, dstMem, reinterpret_cast<void*>(srcAddr), reinterpret_cast<void*>(pktBufAddr));
           })
      .def("device_handle", &SmChannel::deviceHandle);

  // Bind nested DeviceHandle class
  nb::class_<SmChannel::DeviceHandle> deviceHandleClass(module, "SmChannelDeviceHandle");
  deviceHandleClass
      .def(nb::init<>())
      .def_rw("semaphore_", &SmChannel::DeviceHandle::semaphore_)
      .def_rw("src_", &SmChannel::DeviceHandle::src_)
      .def_rw("dst_", &SmChannel::DeviceHandle::dst_)
      .def_rw("getPacketBuffer_", &SmChannel::DeviceHandle::getPacketBuffer_)
      .def_prop_ro("raw", [](const SmChannel::DeviceHandle& handle) -> nb::bytes {
        return nb::bytes(reinterpret_cast<const char*>(&handle), sizeof(handle));
      });
}

