#define LDBG(X) LLVM_DEBUG(DBGS() << X << "\n")

namespace mlir {
namespace hfusion {
namespace detail {

// Constructor: initializes flattening infrastructure
Flattener::Flattener(Operation *op) : DimensionAnalyzer(op) {
  // Phase 1: Setup phase — associate each dimension index with connectivity info.
  //
  // Inputs, outputs, and results are modeled as flattened index sequences.
  // For instance:
  //   arg0: [7x6xf32] → indices [0,1]
  //   arg1: [5xf32]   → indices [2]
  //   arg2: [8x7x6x9xf32] → indices [3..8]
  //
  // Operations like reduce/broadcast may share or split index ranges.
  // Union-find solverShapeElem_ tracks equivalences between indices.
  //
  // Example: op1 reduces arg2 over dims [6,7]; op2 adds arg0 and op1,
  // implying index sets {0,1} == {6,7}, so we union(0,6), union(1,7).
  //
  // To avoid over-constraining inter-region flattening (e.g., <?> vs <20x?x32>),
  // tensor.dim-based binding is disabled.
  bindUsingTensorDim = false;
}

LogicalResult Flattener::flatten(bool multiDynamicShape) {
  auto initRes = initialize();
  if (failed(initRes))
    return success();

  // Mark broken connections for each argument reference
  for (size_t idx = 0; idx < argumentsRef_.size(); ++idx) {
    markBroken(argumentsRef_[idx]);
  }

  propagateBroken();

  if (!multiDynamicShape) {
    breakDynamicShapes();
    propagateBroken();
  }

  adjustOperations();
  return success();
}

// Mark disconnections in a given argument's index list
void Flattener::markBroken(const DimensionIndex &argIndices) {
  int len = static_cast<int64_t>(argIndices.size());
  for (int i = 0; i < len; ++i) {
    // Left boundary check
    if (i == 0 || argIndices[i - 1] != argIndices[i] - 1) {
      LLVM_DEBUG(llvm::dbgs() << "left gap at index " << argIndices[i] << "\n");
      isConnected_[argIndices[i]].leftConnected = false;
      if (i > 0)
        isConnected_[argIndices[i - 1]].rightConnected = false;
      if (argIndices[i] > 0)
        isConnected_[argIndices[i] - 1].rightConnected = false;
    }

    // Right boundary check
    if (i + 1 == len || argIndices[i + 1] != argIndices[i] + 1) {
      LLVM_DEBUG(llvm::dbgs() << "right gap at index " << argIndices[i] << "\n");
      isConnected_[argIndices[i]].rightConnected = false;
      if (i + 1 < len)
        isConnected_[argIndices[i + 1]].leftConnected = false;
      if (argIndices[i] + 1 < static_cast<int64_t>(isConnected_.size()))
        isConnected_[argIndices[i] + 1].leftConnected = false;
    }
  }
}

// Determine whether a mutation can propagate in direction 'dir' from position 'pos'
bool Flattener::computeMutation(int pos, int dir) const {
  LDBG("Checking mutation propagation: pos=" << pos << ", dir=" << dir);
  bool allowed = true;
  int curr = pos;

  while (curr + dir >= 0 && curr + dir < static_cast<int64_t>(isConnected_.size())) {
    // Check continuity and unit status
    int nextPos = curr + dir;
    bool leftOk = isConnected_[std::min(curr, nextPos)].rightConnected;
    bool rightOk = isConnected_[std::max(curr, nextPos)].leftConnected;
    bool canStep = leftOk && rightOk;

    if (!canStep)
      break;

    if (isConnected_[nextPos].elementKind != ElementKind::Unit) {
      LDBG("Blocked by non-unit node at " << nextPos << " (kind="
                                          << static_cast<int64_t>(
                                                 isConnected_[nextPos].elementKind)
                                          << ")");
      allowed = false;
      break;
    }

    curr = nextPos;
  }

  LDBG("Mutation allowed? " << allowed);
  return allowed;
}

// Propagate disconnection effects across connected components
void Flattener::propagateBroken() {
  propagateConnection();
  spreadConnection();

  // Scan root nodes only (union-find representatives)
  for (int i = 0; i < argumentTotalLength_; ++i) {
    int root = solverCollapserElem_->find(i);
    if (root != i)
      continue;

    if (isConnected_[i].elementKind != ElementKind::HasMutation)
      continue;

    if (!computeMutation(i, -1)) {
      disconnect(i - 1, i);
    }
    if (!computeMutation(i, 1)) {
      disconnect(i, i + 1);
    }
  }

  propagateConnection();
  spreadConnection();
}

// Handle dynamic dimensions specially: prevent flattening across multiple dyn dims
void Flattener::breakDynamicShapes() {
  BitVector visited(argumentTotalLength_);
  auto markVisited = [&visited, this](int idx) {
    visited[solverCollapserElem_->find(idx)] = true;
  };

  int rightBound;
  for (int leftBound = 0; leftBound < argumentTotalLength_; leftBound = rightBound + 1) {
    markVisited(leftBound);
    LDBG("Segment starts at index " << leftBound);
    assert(leftBound == 0 || !isConnected(leftBound - 1, leftBound));

    SmallVector<int> dynIndices;
    auto collectIfDynamic = [&dynIndices, this](int idx) {
      auto pair = solverShapeElem_->getMinParentAndShapePair(idx);
      if (ShapedType::isDynamic(pair.second)) {
        dynIndices.push_back(idx);
      }
    };

    rightBound = leftBound;
    collectIfDynamic(rightBound);

    while (rightBound + 1 < argumentTotalLength_ &&
           isConnected(rightBound, rightBound + 1)) {
      rightBound++;
      markVisited(rightBound);
      collectIfDynamic(rightBound);
    }

    // If more than one dynamic dim in segment, break internal connections
    if (dynIndices.size() > 1) {
      LDBG("Multiple dynamic dims detected in segment; breaking internal links.");
      for (size_t k = 1; k < dynIndices.size(); ++k) {
        disconnect(dynIndices[k] - 1, dynIndices[k]);
      }
    }
  }
}

