int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int b, w, x, y;
    if (!(cin >> b >> w >> x >> y)) return 0;

    char bgColor, islandColor; // background and island colors
    int totalIslands;          // number of islands (M)
    int holesNeeded;           // number of holes (K)

    // Determine which color should be background based on cost
    if (x < y) {
        bgColor = '@';
        islandColor = '.';
        totalIslands = w;
        holesNeeded = b - 1;
    } else {
        bgColor = '.';
        islandColor = '@';
        totalIslands = b;
        holesNeeded = w - 1;
    }

    vector<string> resultGrid;

    if (holesNeeded == 0) {
        // Simple case: no holes needed, just M separate islands
        string row0 = "", row1 = "";

        // Start with a background cell
        row0 += bgColor;
        row1 += bgColor;

        // Build M islands separated by background cells
        for (int i = 0; i < totalIslands; ++i) {
            row0 += islandColor;
            row1 += bgColor;

            row0 += bgColor;
            row1 += bgColor;
        }

        resultGrid.push_back(row0);
        resultGrid.push_back(row1);
    } else {
        // Complex case: need holes inside islands
        string r0 = "", r1 = "", r2 = "", r3 = "";

        // Initial background column
        r0 += bgColor; r1 += bgColor; r2 += bgColor; r3 += bgColor;

        // Create one complex island containing all holes
        // Pattern: top row all islandColor, middle row alternates island/hole, bottom row all islandColor
        for (int h = 0; h < holesNeeded; ++h) {
            r0 += islandColor;
            r1 += islandColor;
            r2 += islandColor;
            r3 += bgColor;

            r0 += islandColor;
            r1 += bgColor;  // This is a hole
            r2 += islandColor;
            r3 += bgColor;
        }

        // Add final column for the complex island
        r0 += islandColor;
        r1 += islandColor;
        r2 += islandColor;
        r3 += bgColor;

        // Separator after complex island
        r0 += bgColor; r1 += bgColor; r2 += bgColor; r3 += bgColor;

        // Add remaining simple islands (totalIslands - 1)
        for (int i = 1; i < totalIslands; ++i) {
            r0 += bgColor;
            r1 += islandColor;
            r2 += bgColor;
            r3 += bgColor;

            r0 += bgColor; r1 += bgColor; r2 += bgColor; r3 += bgColor;
        }

        resultGrid.push_back(r0);
        resultGrid.push_back(r1);
        resultGrid.push_back(r2);
        resultGrid.push_back(r3);
    }

    cout << resultGrid.size() << " " << resultGrid[0].size() << "\n";
    for (const string& line : resultGrid) {
        cout << line << "\n";
    }

    return 0;
}

