// Global variable to store n for use in query validation
long long global_n;

// Function to send a query and process the response
int send_query(long long x, long long y) {
    // Clamp values to valid range [1, global_n]
    if (x < 1) x = 1;
    if (x > global_n) x = global_n;
    if (y < 1) y = 1;
    if (y > global_n) y = global_n;

    std::cout << x << " " << y << std::endl;

    int result;
    std::cin >> result;

    if (result == 0) {
        std::exit(0);
    }

    return result;
}

int main() {
    // Optimize I/O operations
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::cin >> global_n;

    // Define search ranges for two unknown numbers: [a_low, a_high] and [b_low, b_high]
    long long left_a = 1, right_a = global_n;
    long long left_b = 1, right_b = global_n;

    while (true) {
        // If both ranges have converged to single values, we've found the solution
        if (left_a == right_a && left_b == right_b) {
            send_query(left_a, left_b);
            break; // Should not reach here due to early exit on response 0
        }

        // If 'a' is known (range narrowed to one value), perform binary search on 'b'
        if (left_a == right_a) {
            long long mid_b = left_b + (right_b - left_b) / 2;
            int res = send_query(left_a, mid_b);

            if (res == 2) { // indicates mid_b < b
                left_b = mid_b + 1;
            } else { // res == 3 implies mid_b > b (since left_a == a)
                right_b = mid_b - 1;
            }
            continue;
        }

        // If 'b' is known (range narrowed to one value), perform binary search on 'a'
        if (left_b == right_b) {
            long long mid_a = left_a + (right_a - left_a) / 2;
            int res = send_query(mid_a, left_b);

            if (res == 1) { // indicates mid_a < a
                left_a = mid_a + 1;
            } else { // res == 3 implies mid_a > a (since left_b == b)
                right_a = mid_a - 1;
            }
            continue;
        }

        // General case: query midpoints of both ranges
        long long mid_a = left_a + (right_a - left_a) / 2;
        long long mid_b = left_b + (right_b - left_b) / 2;

        int response = send_query(mid_a, mid_b);

        if (response == 1) { // x < a => mid_a < a
            left_a = mid_a + 1;
        } else if (response == 2) { // y < b => mid_b < b
            left_b = mid_b + 1;
        } else { // response == 3: ambiguous case (x > a or y > b)
            // Heuristic: shrink the larger range to balance the search space
            long long range_a = right_a - left_a;
            long long range_b = right_b - left_b;

            if (range_a >= range_b) {
                right_a = mid_a - 1;
            } else {
                right_b = mid_b - 1;
            }
        }
    }

    return 0;
}

