MenuBackup::MenuBackup(shared_ptr<Inventory> inventory, AbstractContainerMenu* menu)
    : inventory(inventory), menu(menu) {
    backups = new std::unordered_map<short, ItemInstanceArray*>();
}

void MenuBackup::save(short changeUid) {
    // Create backup storage: size = carried item + all slots
    const size_t totalSlots = 1 + menu->slots.size();
    ItemInstanceArray* snapshot = new ItemInstanceArray(static_cast<int>(totalSlots));

    // Save carried item at index 0
    snapshot[0] = ItemInstance::clone(inventory->getCarried());

    // Save each slot's item starting from index 1
    for (size_t idx = 0; idx < menu->slots.size(); ++idx) {
        Slot* slot = menu->slots[idx];
        snapshot[idx + 1] = ItemInstance::clone(slot->getItem());
    }

    // Store the snapshot under the given UID
    (*backups)[changeUid] = snapshot;
}

void MenuBackup::deleteBackup(short changeUid) {
    auto it = backups->find(changeUid);
    if (it != backups->end()) {
        delete it->second;  // Free allocated memory before erasing
        backups->erase(it);
    }
}

void MenuBackup::rollback(short changeUid) {
    auto it = backups->find(changeUid);
    if (it == backups->end()) return;

    ItemInstanceArray* snapshot = it->second;

    // Restore carried item
    inventory->setCarried(snapshot[0]);

    // Restore each slot's content
    for (size_t i = 0; i < menu->slots.size(); ++i) {
        menu->slots[i]->set(snapshot[i + 1]);
    }

    // Clean up the restored snapshot after rollback
    delete snapshot;
    backups->erase(it);
}

