using namespace std;

bool check_connectivity() {
    cout << "? 1 1" << endl;
    int result;
    cin >> result;
    if (result == -1) {
        exit(0);
    }
    return result == 1;
}

void process_case() {
    int nodes, roads_count;
    cin >> nodes >> roads_count;

    vector<pair<int, int>> road_connections(roads_count);
    for (int idx = 0; idx < roads_count; ++idx) {
        cin >> road_connections[idx].first >> road_connections[idx].second;
    }

    vector<int> result_flags(roads_count, 0);
    vector<int> confirmed_roads;
    vector<int> pending_roads(roads_count);
    iota(pending_roads.begin(), pending_roads.end(), 0);

    while (!pending_roads.empty()) {
        vector<int> critical_roads;

        // Temporarily remove all confirmed roads
        for (int road_id : confirmed_roads) {
            cout << "- " << (road_id + 1) << endl;
        }

        vector<int> remaining_roads;
        for (int road_id : pending_roads) {
            cout << "- " << (road_id + 1) << endl;

            if (!check_connectivity()) {
                critical_roads.push_back(road_id);
            } else {
                remaining_roads.push_back(road_id);
            }

            cout << "+ " << (road_id + 1) << endl;
        }

        // Restore confirmed roads
        for (int road_id : confirmed_roads) {
            cout << "+ " << (road_id + 1) << endl;
        }

        if (critical_roads.empty()) {
            break;
        }

        for (int critical_id : critical_roads) {
            result_flags[critical_id] = 1;
            confirmed_roads.push_back(critical_id);
        }

        pending_roads.swap(remaining_roads);
    }

    cout << "!";
    for (int flag : result_flags) {
        cout << " " << flag;
    }
    cout << endl;

    int verification;
    cin >> verification;
    if (verification == 0) {
        exit(0);
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int test_cases;
    cin >> test_cases;
    while (test_cases-- > 0) {
        process_case();
    }

    return 0;
}

