using asio::ip::tcp;

// Helper function to compute string length manually (equivalent to std::strlen)
inline std::size_t custom_strlen(const char* str) {
    const char* s = str;
    while (*s) ++s;
    return s - str;
}

//------------------------------------------------------------------------------
// Composed async operation: writes a null-terminated message over TCP socket
// Completion signature: void(asio::error_code)
template <typename CompletionToken>
auto initiate_async_send(tcp::socket& sock,
                         const char* msg,
                         CompletionToken&& token)
  -> typename asio::async_result<
      typename std::decay_t<CompletionToken>,
      void(asio::error_code)>::return_type
{
    asio::async_completion<CompletionToken,
        void(asio::error_code)> completer(token);

    // Capture the original executor from the completion handler
    auto bound_executor = asio::get_associated_executor(
        completer.completion_handler, sock.get_executor());

    // Use a lambda to adapt the async_write completion handler signature
    auto adapted_handler = [handler = std::move(completer.completion_handler)](
        asio::error_code ec, std::size_t /*bytes_transferred*/) mutable {
        handler(ec);
    };

    asio::async_write(sock,
        asio::buffer(msg, custom_strlen(msg)),
        asio::bind_executor(bound_executor, std::move(adapted_handler)));

    return completer.result.get();
}

//------------------------------------------------------------------------------
void run_callback_test()
{
    asio::io_context io_ctx;
    tcp::acceptor acc(io_ctx, {tcp::v4(), 55555});
    tcp::socket cli_sock = acc.accept();

    // Launch client-side write in background thread to avoid blocking accept()
    std::thread t([&]() {
        initiate_async_send(cli_sock, "Callback test message\n",
            [](const asio::error_code& err) {
                if (!err) {
                    std::cout << "[Callback] Message delivered successfully.\n";
                } else {
                    std::cerr << "[Callback] Failure: " << err.message() << '\n';
                }
            });
    });

    io_ctx.run();
    t.join();
}

//------------------------------------------------------------------------------
void run_future_test()
{
    asio::io_context io_ctx;
    tcp::acceptor acc(io_ctx, {tcp::v4(), 55556});
    tcp::socket cli_sock = acc.accept();

    std::future<void> fut = initiate_async_send(
        cli_sock, "Future-based test\n", asio::use_future);

    std::thread t([&io_ctx]() { io_ctx.run(); });

    try {
        fut.get();
        std::cout << "[Future] Transmission completed without error.\n";
    } catch (const std::exception& ex) {
        std::cerr << "[Future] Exception caught: " << ex.what() << '\n';
    }

    t.join();
}

//------------------------------------------------------------------------------
int main()
{
    std::cout << "Starting composed async send tests...\n";

    run_callback_test();
    run_future_test();

    std::cout << "All tests completed.\n";
    return 0;
}

