#include <engLib/eng.h>

namespace engine::store {
namespace {

//---------------------------------------------------------------------
/// @details
///		Decrypts the secrets within the service parameters and
///     populates the parameters with the hidden token values
///	@param[inout] service
///		Service to decrypt
//---------------------------------------------------------------------
Error decryptParameters(json::Value &service) noexcept {
    // Retrieve service metadata
    auto svcDef = IServices::getServiceDefinitionFromService(service);
    if (!svcDef) return svcDef.ccode();

    // Check for presence of 'parameters' section
    if (!service.hasMember("parameters")) return {};

    auto& params = service["parameters"];

    // Skip if no secure parameters exist
    if (!params.hasMember("secureParameters")) return {};

    auto& securePart = params["secureParameters"];

    // Extract token
    Text secretToken;
    if (auto err = securePart.lookupAssign("token", secretToken)) return err;
    if (secretToken.empty()) return {};

    // Decode base64-encoded token
    auto decodedBlob = crypto::base64Decode(secretToken);
    if (!decodedBlob) return decodedBlob.ccode();

    // Decrypt payload
    auto plainText = crypto::engineDecrypt(*decodedBlob);
    if (!plainText) return plainText.ccode();

    // Parse resulting JSON
    auto parsedJson = json::parse(plainText->toTextView());
    if (!parsedJson) return parsedJson.ccode();

    auto decryptedValues = *parsedJson;

    // Apply decrypted values to parameters
    const auto& spec = (*svcDef)->secureParameters;
    for (const auto& entry : spec) {
        const std::string& paramName = entry.first;
        const PARAM_TYPE paramKind = entry.second;

        if (paramKind != PARAM_TYPE::SECURE) continue;

        // Skip if already present in top-level params
        if (params.hasMember(paramName)) continue;

        // Skip if not found in decrypted data
        if (!decryptedValues.hasMember(paramName)) continue;

        // Copy value into main parameters
        params[paramName] = decryptedValues[paramName];
    }

    // Clean up secure section after use
    params.removeMember("secureParameters");
    return {};
}

//---------------------------------------------------------------------
/// @details
///		Encrypts the secrets within the service parameters. For secure
///		parameters, it places the values int the secure section with the
///		name and removes it from the parameters list. For readonly parameters
///		it leaves the value in the parameters, but copies it into secure
///		so we can ensure it is not overwritten
///	@param[in]	configParam
///		Parameter configuration info
///	@param[inout] target
///		Parameters set to encrypt
//---------------------------------------------------------------------
Error encryptParameters(IServiceConfig &config, json::Value &output) noexcept {
    json::Value secureList(json::arrayValue);
    json::Value readOnlyList(json::arrayValue);
    json::Value encryptedData(json::objectValue);

    // Fetch service definition
    auto svcDef = IServices::getServiceDefinitionFromService(config.serviceConfig);
    if (!svcDef) return svcDef.ccode();

    // Ensure parameters exist
    if (!config.serviceConfig.hasMember("parameters")) return {};

    // Initialize output structure
    output["parameters"] = config.serviceConfig["parameters"];
    auto& outParams = output["parameters"];

    // Iterate over secure parameter definitions
    for (const auto& item : (*svcDef)->secureParameters) {
        const std::string& key = item.first;
        const PARAM_TYPE kind = item.second;

        // Skip if parameter not present in input
        if (!outParams.hasMember(key)) continue;

        auto val = outParams[key];

        switch (kind) {
            case PARAM_TYPE::SECURE: {
                outParams.removeMember(key);
                secureList.append(key);
                break;
            }
            default:
                continue;
        }

        encryptedData[key] = val;
    }

    // Encrypt collected sensitive data
    auto cipherText = crypto::engineEncrypt(encryptedData.stringify());
    if (!cipherText) return cipherText.ccode();

    // Encode as base64
    auto encodedToken = crypto::base64Encode(*cipherText);

    // Assemble secure section
    json::Value secureSection;
    secureSection["readonly"] = readOnlyList;
    secureSection["secure"] = secureList;
    secureSection["token"] = encodedToken;

    // Attach to parameters
    outParams["secureParameters"] = secureSection;
    return {};
}

}  // namespace

//------------------------------------------------------------------
/// @details
///		Sets up the configuration of the endpoint
///	@param[in]	jobConfig
///		The overall job information - the complete parsed json file
///	@param[in]	taskConfig
///		The task configuration - the config section of the job
///	@param[in]	serviceConfig
///		The service configuration for the endpoint
//------------------------------------------------------------------
Error IServiceEndpoint::setConfig(const json::Value &_jobConfig,
                                  const json::Value &_taskConfig,
                                  const json::Value &_serviceConfig) noexcept {
    Error status;

    // Store raw configs
    config.jobConfig = _jobConfig;
    config.taskConfig = _taskConfig;
    config.serviceConfig = _serviceConfig;
    config.originalServiceConfig = _serviceConfig;

    // Reset internal state
    config.level = 0;

    // Load common path settings
    config.taskConfig.lookupAssign("commonTargetPath", config.commonTargetPath);
    config.taskConfig.lookupAssign("flatten", config.flatten);

    // Extract basic service identifiers
    if ((status = config.serviceConfig.lookupAssign("name", config.name) ||
                 config.serviceConfig.lookupAssign("key", config.key)))
        return status;

    // Determine logical and physical types
    auto ltype = IServiceEndpoint::getLogicalType(config.serviceConfig);
    if (!ltype) return ltype.ccode();
    config.logicalType = *ltype;

    auto ptype = IServiceEndpoint::getPhysicalType(config.serviceConfig);
    if (!ptype) return ptype.ccode();
    config.physicalType = *ptype;

    // Construct protocol prefix
    config.protocol = config.logicalType + "://";

    // Parse service mode
    Text modeStr = config.serviceConfig.lookup<Text>("mode").lowerCase();
    if (modeStr == "source")
        config.serviceMode = SERVICE_MODE::SOURCE;
    else if (modeStr == "target")
        config.serviceMode = SERVICE_MODE::TARGET;
    else
        return APERR(Ec::InvalidParam, "Invalid service mode", modeStr,
                     "specified");

    // Decrypt parameters before further processing
    if ((status = decryptParameters(config.serviceConfig))) return status;

    // Save decrypted parameters
    if ((status = config.serviceConfig.lookupAssign("parameters", config.parameters)))
        return status;

    // Validate pipeline if defined
    if (config.serviceConfig.hasMember("pipeline")) {
        config.pipeline.setRoot(config.serviceConfig);
        if ((status = config.pipeline.validate())) return status;
    }

    // Read additional common parameters
    config.parameters.lookupAssign<Dword>("segmentSize", config.segmentSize);

    // Support legacy 'basePath' field
    config.parameters.lookupAssign("storePath", config.storePath);
    if (config.storePath.empty())
        config.parameters.lookupAssign("basePath", config.storePath);

    // Handle export update behavior
    config.taskConfig.lookupAssign("update", config.exportUpdateBehaviorName);
    config.exportUpdateBehaviorName.lowerCase();

    if (config.exportUpdateBehaviorName == "skip"_tv)
        config.exportUpdateBehavior = EXPORT_UPDATE_BEHAVIOR::SKIP;
    else if (config.exportUpdateBehaviorName == "update"_tv)
        config.exportUpdateBehavior = EXPORT_UPDATE_BEHAVIOR::UPDATE;
    else
        config.exportUpdateBehavior = EXPORT_UPDATE_BEHAVIOR::UNKNOWN;

    // Pipeline trace level
    Text traceLevelStr;
    config.taskConfig.lookupAssign("pipelineTraceLevel", traceLevelStr);
    if (traceLevelStr == "metadata"_tv)
        config.pipelineTraceLevel = PIPELINE_TRACE_LEVEL::METADATA;
    else if (traceLevelStr == "summary"_tv)
        config.pipelineTraceLevel = PIPELINE_TRACE_LEVEL::SUMMARY;
    else if (traceLevelStr == "full"_tv)
        config.pipelineTraceLevel = PIPELINE_TRACE_LEVEL::FULL;

    return status;
}

//-------------------------------------------------------------------------
/// @details
///		Given a service configuration, encoded or not, this function will
///		encode it and return a json structure that can be returned to
///		the UI
///	@param[out]	serviceConfig
///		Recieves the encoded values to be returned to UI
///	@returns
///		Error
//-------------------------------------------------------------------------
Error IServiceEndpoint::getConfig(json::Value &_serviceConfig) noexcept {
    using namespace ap::url;
    Error status;

    // Derive unique subkey
    Text subKey;
    if ((status = getConfigSubKey(subKey))) return status;
    if (subKey.empty()) subKey = "*";

    // Build URL representation
    Url fullKey = builder() << protocol(config.protocol) << component(subKey);

    // Start from original config
    _serviceConfig = config.originalServiceConfig;

    // Update dynamic fields
    _serviceConfig["name"] = config.name;
    _serviceConfig["type"] = config.logicalType;
    _serviceConfig["key"] = static_cast<TextView>(fullKey);

    // Prepare parameter copy
    json::Value paramsCopy = config.parameters;

    // Encrypt sensitive parts
    if ((status = encryptParameters(config, _serviceConfig))) return status;

    return {};
}

