#include "valdi/android/MainThreadDispatcher.hpp"
#include <future>

namespace ValdiAndroid {

MainThreadDispatcher::MainThreadDispatcher(JavaEnv env, jobject object)
    : GlobalRefJavaObjectBase(env, object, "MainThreadManager") {
    auto obj = toObject();
    auto cls = obj.getClass();
    cls.getMethod("runOnMainThread", _runOnMainThreadMethod);
    cls.getMethod("runOnMainThreadDelayed", _runOnMainThreadDelayedMethod);
}

MainThreadDispatcher::~MainThreadDispatcher() = default;

void MainThreadDispatcher::dispatch(Valdi::DispatchFunction* func, bool synchronous) {
    if (synchronous) {
        std::promise<void> completion;
        auto future_result = completion.get_future();

        // Wrap the user function to ensure safe execution and cleanup
        auto wrapper = new Valdi::DispatchFunction([func, &completion]() {
            (*func)();
            completion.set_value();
            delete func;
        });

        _runOnMainThreadMethod.call(toObject(), reinterpret_cast<int64_t>(wrapper));
        future_result.wait();  // Block until the main thread completes
    } else {
        _runOnMainThreadMethod.call(toObject(), reinterpret_cast<int64_t>(func));
    }
}

void MainThreadDispatcher::scheduleWithDelay(int64_t delayMillis, Valdi::DispatchFunction* func) {
    _runOnMainThreadDelayedMethod.call(toObject(), delayMillis, reinterpret_cast<int64_t>(func));
}

