int main(int argc, char* argv[]) {
    using namespace Alembic::Util;

    // Test cases that should be valid standard names
    std::vector<std::string> validNames;
    validNames.push_back("abc");
    validNames.push_back("abc8675309");
    validNames.push_back("a");
    validNames.push_back("under_score");
    validNames.push_back("_underscore");
    validNames.push_back("_underscore12345");
    validNames.push_back("_");

    // Test cases that should be invalid standard names initially
    std::vector<std::string> invalidNames;
    invalidNames.push_back("");
    invalidNames.push_back("1");
    invalidNames.push_back("42abc");
    invalidNames.push_back("Name With Spaces");
    invalidNames.push_back("@#(#@$)(*");
    invalidNames.push_back("Xform No. 0x1c # not 0xc1");
    invalidNames.push_back("#");

    // Verify all valid names pass the isStandardName check
    for (std::vector<std::string>::const_iterator iter = validNames.begin();
         iter != validNames.end(); ++iter) {
        assert(isStandardName(*iter));
    }

    // Verify invalid names fail initially, then get corrected by makeStandardName
    for (std::vector<std::string>::iterator iter = invalidNames.begin();
         iter != invalidNames.end(); ++iter) {
        std::string currentName = *iter;

        // Confirm it's not a standard name initially
        assert(!isStandardName(currentName));

        // Convert to standard name
        makeStandardName(currentName);

        // Now it should be valid
        assert(isStandardName(currentName));
    }

    std::cout << "Success!" << std::endl;
    return 0;
}

#include <iostream>

// Renamed main entry point to simulate a different module or wrapper
int dimr_main_entry(int argc, char* argv[], char* envp[]) {
#if defined(MEMCHECK)
    // Memory checking setup — same logic, renamed function
    auto memAbortHandler = [](enum mcheck_status status) -> void {
        const char* msg = nullptr;
        switch (status) {
            case MCHECK_DISABLED: msg = "Consistency checking is not turned on"; break;
            case MCHECK_OK:       msg = "Block is fine"; break;
            case MCHECK_FREE:     msg = "Block freed twice"; break;
            case MCHECK_HEAD:     msg = "Memory before the block was clobbered"; break;
            case MCHECK_TAIL:     msg = "Memory after the block was clobbered"; break;
            default:              msg = "<undefined reason>";
        }
        fprintf(stderr, "ABORT: Malloc check error: %s\n", msg);
        exit(EXIT_FAILURE);
    };
    int rc = mcheck_pedantic(memAbortHandler);
    printf("DEBUG: mcheck_pedantic returns %d\n", rc);
#endif

    // Ensure version string is embedded in binary
    const char* versionStr = getversionidstring_dimr_exe();

    int exitCode = -1;
    DimrExe* dimrInstance = nullptr;
    bool shouldFinalize = false;

    initialize_parallel(argc, argv);

    try {
        dimrInstance = new DimrExe();
        dimrInstance->initialize(argc, argv, envp);
        if (!dimrInstance->isReady()) {
            delete dimrInstance;
            return 1;
        }

        dimrInstance->log->Write(INFO, my_rank, getfullversionstring_dimr_exe());
        dimrInstance->loadComponentLibrary();
        dimrInstance->componentInitialize();

        shouldFinalize = true;

        int updateResult = dimrInstance->componentUpdate();
        if (updateResult != 0) {
            throw Exception(static_cast<Exception::ErrorCode>(updateResult),
                            "dimr_exe componentUpdate failed");
        }

        shouldFinalize = false;
        dimrInstance->componentFinalize();
        dimrInstance->stopTimerAndLog();
        delete dimrInstance;
        exitCode = 0;
    }
    catch (const std::exception& ex) {
        fprintf(stderr, "#### ERROR: dimr ABORT: C++ Exception: %s\n", ex.what());
        handleCleanupAndAbort(dimrInstance, shouldFinalize);
        exitCode = 1;
    }
    catch (const Exception& ex) {
        fprintf(stderr, "#### ERROR: dimr ABORT: %s\n", ex.message);
        handleCleanupAndAbort(dimrInstance, shouldFinalize);
        exitCode = 1;
    }
    catch (const char* errStr) {
        fprintf(stderr, "#### ERROR: dimr ABORT: %s\n", errStr);
        handleCleanupAndAbort(dimrInstance, shouldFinalize);
        exitCode = 1;
    }

    finalize_parallel();
    return exitCode;
}

// Helper to centralize cleanup logic during exception handling
void handleCleanupAndAbort(DimrExe* instance, bool doFinalize) {
    if (doFinalize && instance != nullptr) {
        fprintf(stderr, "#### ERROR: dimr ABORT: Trying to finalize...\n");
        try {
            instance->componentFinalize();
        } catch (...) {
            fprintf(stderr, "#### ERROR: dimr ABORT: Finalize aborted\n");
        }
    }
    fprintf(stderr, "#### ERROR: dimr ABORT: See messages above\n");
    fflush(stderr);
    abort_parallel();
}

