//------------------------------------------------------------------------------
// Refactored timer logging method
void DimrExe::stopTimerAndLog() {
    Clock::Timestamp now = clock->Epoch();
    accumulatedTime += (now - startTimeStamp);
    startTimeStamp = 0;

    log->Write(INFO, my_rank, "%s\t: %d.%d sec", "DIMR_EXE",
               static_cast<int>(accumulatedTime / 1000000),
               static_cast<int>(accumulatedTime % 1000000));

    accumulatedTime = 0;
}

//------------------------------------------------------------------------------
// Modified initialization logic — reordered some steps, renamed variables
void DimrExe::initialize(int argc, char* argv[], char* envp[]) {
    exePath = strdup(argv[0]);

#ifndef _WIN32
    exeBaseName = strdup(basename(argv[0]));
#else
    char ext[5];
    exeBaseName = new char[MAXSTRING];
    _splitpath(argv[0], nullptr, nullptr, exeBaseName, ext);
    StringCbCatA(exeBaseName, MAXSTRING, ext);
#endif

    slaveArgs = nullptr;
    completed = false;
    debugLevel = INFO;

    FILE* logStream = stdout;

    // Reconstruct command line args
    size_t totalLen = 0;
    for (int i = 1; i < argc; ++i)
        totalLen += strlen(argv[i]) + 1;

    fullCmdLine = new char[totalLen + 1];
    memset(fullCmdLine, '\0', totalLen + 1);
    char* cursor = fullCmdLine;
    for (int i = 1; i < argc; ++i) {
        size_t argLen = strlen(argv[i]);
        memcpy(cursor, argv[i], argLen);
        cursor += argLen;
        *cursor++ = ' ';
    }

    // Parse options
    int opt;
    while ((opt = getopt(argc, argv, (char*)"d:l:S:v:i:?")) != -1) {
        switch (opt) {
            case 'd': {
                int lvl;
                if (sscanf(optarg, "%i", &lvl) != 1)
                    throw Exception(Exception::ERR_INVALID_INPUT, "Invalid log level (-d option)");
                debugLevel = std::min(std::max(lvl, ALL), FATAL);
                break;
            }
            case 'v':
                debugLevel = ALL;
                break;
            case 'l': {
                logStream = fopen(optarg, "w");
                if (!logStream)
                    throw Exception(Exception::ERR_OS, "Cannot create log file \"%s\"", optarg);
                break;
            }
            case 'S':
                slaveArgs = optarg;
                break;
            case 'i':
                printAbout(exeBaseName);
                completed = true;
                return;
            case '?':
                printUsage(exeBaseName);
                completed = true;
                return;
            default:
                throw Exception(Exception::ERR_INVALID_INPUT,
                                "Invalid command-line argument. Run \"%s -?\" for usage.", exeBaseName);
        }
    }

    if (argc - optind != 1)
        throw Exception(Exception::ERR_INVALID_INPUT,
                        "Improper usage. Run \"%s -?\" for usage.", exeBaseName);

    clock = new Clock();
    log = new Log(logStream, clock, debugLevel);
    configPath = argv[optind];
    readyFlag = true;

    startTimeStamp = clock->Epoch();
    accumulatedTime = 0;
}

//------------------------------------------------------------------------------
// Updated destructor logic — renamed internal cleanup calls
DimrExe::~DimrExe() {
    if (completed) return;

    unloadComponentLibrary();
    log->Write(DEBUG, my_rank, "dimr shutting down normally");

#ifndef _WIN32
    free(exeBaseName);
#else
    delete[] exeBaseName;
#endif

    delete clock;
    free(exePath);
    delete log;
    delete[] fullCmdLine;
    delete[] componentName;
    completed = true;
}

//------------------------------------------------------------------------------
// Refactored library loading — changed conditionals and variable names
void DimrExe::loadComponentLibrary() {
#if defined(OSX)
    throw Exception(Exception::ERR_OS, "ABORT: %s has not been ported to Apple Mac OS/X yet", exeBaseName);
#endif

#ifndef _WIN32
    char* dlErr = nullptr;
#endif

#ifdef _WIN32
    componentName = new char[16];
    sprintf(componentName, "dimr.dll\0");
#else
    componentName = new char[14];
    sprintf(componentName, "libdimr.so\0");
#endif

    log->Write(DEBUG, my_rank, "Loading dimr library \"%s\"", componentName);

#ifdef _WIN32
    SetLastError(0);
    HINSTANCE dllHandle = LoadLibraryA(componentName);
    libHandle = dllHandle;
    #define GETSYM GetProcAddress
#else
    dlerror();
    void* dllHandle = dlopen(componentName, RTLD_LAZY);
    libHandle = dllHandle;
    #define GETSYM dlsym
#endif

    if (!dllHandle) {
#ifdef _WIN32
        DWORD errCode = GetLastError();
        if (errCode == 193)
            throw Exception(Exception::ERR_OS,
                            "Cannot load component library \"%s\". Return code: %d\n"
                            "Most probably a 32bit - 64bit conflict.", componentName, errCode);
        else
            throw Exception(Exception::ERR_OS,
                            "Cannot load component library \"%s\". Return code: %d", componentName, errCode);
#else
        if ((dlErr = dlerror()) != nullptr)
            throw Exception(Exception::ERR_OS,
                            "Cannot load component library \"%s\". Error: %s", componentName, dlErr);
#endif
    }

    // Resolve required symbols
    BMI_DIMR_SET_LOGGER loggerSetter = (BMI_DIMR_SET_LOGGER)GETSYM(dllHandle, BmiDimrSetLogger);
    if (!loggerSetter)
        throw Exception(Exception::ERR_METHOD_NOT_IMPLEMENTED,
                        "Function \"%s\" not found in \"%s\".", BmiDimrSetLogger, componentName);
    loggerSetter(log);

    dllInit = (BMI_INITIALIZE)GETSYM(dllHandle, BmiInitializeEntryPoint);
    dllUpdate = (BMI_UPDATE)GETSYM(dllHandle, BmiUpdateEntryPoint);
    dllFini = (BMI_FINALIZE)GETSYM(dllHandle, BmiFinalizeEntryPoint);
    dllGetStart = (BMI_GETSTARTTIME)GETSYM(dllHandle, BmiGetStartTimeEntryPoint);
    dllGetEnd = (BMI_GETENDTIME)GETSYM(dllHandle, BmiGetEndTimeEntryPoint);
    dllGetStep = (BMI_GETTIMESTEP)GETSYM(dllHandle, BmiGetTimeStepEntryPoint);
    dllGetCur = (BMI_GETCURRENTTIME)GETSYM(dllHandle, BmiGetCurrentTimeEntryPoint);
    dllSetVal = (BMI_SETVAR)GETSYM(dllHandle, BmiSetVarEntryPoint);
    dllGetVal = (BMI_GETVAR)GETSYM(dllHandle, BmiGetVarEntryPoint);

    // Validate all loaded pointers
    if (!dllInit || !dllUpdate || !dllFini || !dllGetStart ||
        !dllGetEnd || !dllGetStep || !dllGetCur || !dllSetVal || !dllGetVal) {
        throw Exception(Exception::ERR_METHOD_NOT_IMPLEMENTED,
                        "One or more required BMI functions missing in \"%s\".", componentName);
    }
}

//------------------------------------------------------------------------------
// Simplified finalization logic
void DimrExe::componentFinalize() {
    log->Write(DEBUG, my_rank, "%s.Finalize()", componentName);
    dllFini();
}

//------------------------------------------------------------------------------
// Updated update loop — now uses while instead of do-while
int DimrExe::componentUpdate() {
    double startT, endT, stepT;
    dllGetStart(&startT);
    dllGetEnd(&endT);
    stepT = endT - startT;

    int result = dllUpdate(stepT);
    return result;
}

//------------------------------------------------------------------------------
// Library unloading — renamed and adjusted error reporting
void DimrExe::unloadComponentLibrary() {
#if defined(OSX)
    throw Exception(Exception::ERR_OS, "ABORT: %s has not been ported to Apple Mac OS/X yet", exeBaseName);
#endif

#ifndef _WIN32
    char* dlErr = nullptr;
#endif

    log->Write(ALL, my_rank, "Freeing library \"%s\"", componentName);

#ifdef _WIN32
    SetLastError(0);
    BOOL ok = FreeLibrary(libHandle);
    if (!ok || GetLastError() != 0) {
        throw Exception(Exception::ERR_OS,
                        "Cannot free component library \"%s\". Return code: %d.",
                        componentName, GetLastError());
    }
#else
    dlerror();
    int rc = dlclose(libHandle);
    if ((dlErr = dlerror()) != nullptr) {
        throw Exception(Exception::ERR_OS,
                        "Cannot free component library \"%s\". Error: %s", componentName, dlErr);
    }
#endif
}

//------------------------------------------------------------------------------
// Utility functions — renamed and slightly adjusted
static void printAbout(char* name) {
    printf("\n%s \n"
           "Copyright (C) [redacted]
           "GNU General Public License, see <http://www.gnu.org/licenses/>.\n\n"
           "redacted@example.invalid\n",
           getfullversionstring_dimr_exe());
    printf("%s\n\n", geturlstring_dimr_exe());
}

static void printUsage(char* name) {
    printf("\n"
           "Usage:\n"
           "    %s [<options>] <configurationFile>\n"
           "Options:\n"
           "    -d <int>\n"
           "        Specify debug/log level (0 = max output)\n"
           "    -v\n"
           "        Verbose mode (same as -d 0)\n"
           "    -l <filename>\n"
           "        Write logs to specified file instead of stdout\n"
           "    -i\n"
           "        Print version and contact info\n"
           "    -?\n"
           "        Show this help message\n"
           "Configuration file:\n"
           "    XML format (DTD/schema not yet available)\n"
           "    Use '-' to read from stdin.\n\n",
           name);
}

