DiskArrayCollection::DiskArrayCollection(FileHandle& fileHandle, ShadowFile& shadowFile,
    bool bypassShadowing)
    : fileHandle(fileHandle), shadowFile{shadowFile}, bypassShadowing{bypassShadowing},
      numHeaders{0} {
    // Initialize both read/write header stacks with one empty header page each
    headersForReadTrx.emplace_back(std::make_unique<HeaderPage>());
    headersForWriteTrx.emplace_back(std::make_unique<HeaderPage>());
    headerPagesOnDisk = 0;
}

DiskArrayCollection::DiskArrayCollection(FileHandle& fileHandle, ShadowFile& shadowFile,
    page_idx_t firstHeaderPage, bool bypassShadowing)
    : fileHandle(fileHandle), shadowFile{shadowFile}, bypassShadowing{bypassShadowing},
      numHeaders{0} {
    page_idx_t currentPageIdx = firstHeaderPage;
    while (currentPageIdx != INVALID_PAGE_IDX) {
        std::unique_ptr<HeaderPage> loadedHeader = nullptr;
        page_idx_t nextHeaderPageIdx = INVALID_PAGE_IDX;

        fileHandle.optimisticReadPage(currentPageIdx, [&](auto* frame) {
            auto* diskPage = reinterpret_cast<HeaderPage*>(frame);
            loadedHeader = std::make_unique<HeaderPage>(*diskPage);
            nextHeaderPageIdx = diskPage->nextHeaderPage;
        });

        if (!loadedHeader) {
            throw RuntimeException("Failed to load header page from disk.");
        }

        numHeaders += loadedHeader->numHeaders;
        headersForReadTrx.push_back(std::make_unique<HeaderPage>(*loadedHeader));
        headersForWriteTrx.push_back(std::move(loadedHeader));

        currentPageIdx = nextHeaderPageIdx;
    }
    headerPagesOnDisk = headersForReadTrx.size();
}

void DiskArrayCollection::checkpoint(page_idx_t firstHeaderPage, PageAllocator& pageAllocator) {
    page_idx_t currentDiskPage = firstHeaderPage;

    for (size_t memIndex = 0; memIndex < headersForWriteTrx.size(); ++memIndex) {
        auto& writeHeader = *headersForWriteTrx[memIndex];

        // Allocate next header page if needed (only once per header page chain)
        if (writeHeader.nextHeaderPage == INVALID_PAGE_IDX &&
            memIndex + 1 < headersForWriteTrx.size()) {
            allocateNextHeaderPage(pageAllocator, memIndex);
        }

        // Only persist if changed or not yet written
        bool needsUpdate = (memIndex >= headerPagesOnDisk) ||
                           (*headersForWriteTrx[memIndex] != *headersForReadTrx[memIndex]);

        if (needsUpdate) {
            ShadowUtils::updatePage(*pageAllocator.getDataFH(), currentDiskPage,
                true /*full page write*/, shadowFile, [&](auto* frame) {
                    memcpy(frame, headersForWriteTrx[memIndex].get(), sizeof(HeaderPage));
                    if constexpr (sizeof(HeaderPage) < LBUG_PAGE_SIZE) {
                        std::fill(frame + sizeof(HeaderPage), frame + LBUG_PAGE_SIZE, 0);
                    }
                });
        }

        currentDiskPage = writeHeader.nextHeaderPage;
    }

    headerPagesOnDisk = headersForWriteTrx.size();
}

void DiskArrayCollection::allocateNextHeaderPage(PageAllocator& pageAllocator,
    common::page_idx_t headerPageIndex) {
    auto newPageIdx = pageAllocator.allocatePage();
    headersForWriteTrx[headerPageIndex]->nextHeaderPage = newPageIdx;
    headersForReadTrx[headerPageIndex]->nextHeaderPage = newPageIdx;
}

size_t DiskArrayCollection::addDiskArray() {
    size_t arrayId = numHeaders++;
    size_t pageIndex = numHeaders / HeaderPage::NUM_HEADERS_PER_PAGE;
    size_t slotInPage = numHeaders % HeaderPage::NUM_HEADERS_PER_PAGE;

    if (slotInPage == 0 && pageIndex >= headersForWriteTrx.size()) {
        headersForWriteTrx.emplace_back(std::make_unique<HeaderPage>());
        headersForReadTrx.emplace_back(std::make_unique<HeaderPage>());
    }

    auto& targetHeaderPage = *headersForWriteTrx[slotInPage == 0 ? pageIndex - 1 : pageIndex];
    DASSERT(targetHeaderPage.numHeaders < HeaderPage::NUM_HEADERS_PER_PAGE);

    size_t slotOffset = targetHeaderPage.numHeaders;
    targetHeaderPage.headers[slotOffset] = DiskArrayHeader{};
    targetHeaderPage.numHeaders++;

    // Sync read-side counter (will be overwritten on next checkpoint)
    headersForReadTrx[slotInPage == 0 ? pageIndex - 1 : pageIndex]->numHeaders++;

    return arrayId;
}

void DiskArrayCollection::reclaimStorage(PageAllocator& pageAllocator,
    common::page_idx_t firstHeaderPage) const {
    page_idx_t currentPage = firstHeaderPage;
    for (const auto& headerPtr : headersForReadTrx) {
        if (currentPage == INVALID_PAGE_IDX) break;
        pageAllocator.freePage(currentPage);
        currentPage = headerPtr->nextHeaderPage;
    }
}

