// Reattach sub-loops that may now be fully enclosed in the newly formed loop.
static void reattachNestedLoops(LoopInfo &LI, Loop *Outer,
                                Loop *NewLoop,
                                std::set<BasicBlock *> const &LoopBlocks,
                                std::set<BasicBlock *> const &LoopHeaders) {
  auto &SubLoops = Outer ? Outer->getSubLoopsVector()
                         : LI.getTopLevelLoopsVector();

  auto splitIt = std::partition(SubLoops.begin(), SubLoops.end(),
    [&](Loop *L) -> bool {
      return L == NewLoop || !LoopBlocks.count(L->getHeader());
    });

  SmallVector<Loop *, 8> NestedLoops(splitIt, SubLoops.end());
  SubLoops.erase(splitIt, SubLoops.end());

  for (Loop *subLoop : NestedLoops) {
    LLVM_DEBUG(dbgs() << "nested loop: " << subLoop->getHeader()->getName() << "\n");

    BasicBlock *header = subLoop->getHeader();
    if (LoopHeaders.count(header)) {
      // Subsume this child loop since its header is shared with the new loop
      for (BasicBlock *BB : subLoop->blocks()) {
        if (LI.getLoopFor(BB) != subLoop) continue;
        LI.changeLoopFor(BB, NewLoop);
        LLVM_DEBUG(dbgs() << "moved block from nested: " << BB->getName() << "\n");
      }

      SmallVector<Loop *, 8> grandchildren;
      grandchildren.swap(subLoop->getSubLoopsVector());
      for (Loop *gc : grandchildren) {
        gc->setParentLoop(nullptr);
        NewLoop->addChildLoop(gc);
      }
      LI.destroy(subLoop);
      LLVM_DEBUG(dbgs() << "destroyed nested loop due to common header\n");
      continue;
    }

    subLoop->setParentLoop(nullptr);
    NewLoop->addChildLoop(subLoop);
    LLVM_DEBUG(dbgs() << "attached nested loop to new loop\n");
  }
}

// Internal routine to convert an SCC into a natural loop and integrate it into the loop hierarchy.
static void buildNaturalLoop(LoopInfo &LI, DominatorTree &DT, Loop *outer,
                             std::set<BasicBlock *> const &loopBlocks,
                             std::set<BasicBlock *> const &loopHeaders) {
#ifndef NDEBUG
  for (BasicBlock *H : loopHeaders)
    assert(loopBlocks.count(H) && "All headers must belong to the SCC.");
#endif

  std::set<BasicBlock *> preds;
  for (BasicBlock *H : loopHeaders) {
    for (BasicBlock *P : predecessors(H))
      preds.insert(P);
  }

  LLVM_DEBUG({
    dbgs() << "Predecessors found:";
    for (BasicBlock *P : preds)
      dbgs() << " " << P->getName();
    dbgs() << "\n";
  });

  SmallVector<BasicBlock *, 8> hubBlocks;
  DomTreeUpdater updater(DT, DomTreeUpdater::UpdateStrategy::Eager);
  CreateControlFlowHub(&updater, hubBlocks, preds, loopHeaders, "irr_alt");

#if defined(EXPENSIVE_CHECKS)
  assert(DT.verify(DominatorTree::VerificationLevel::Full));
#else
  assert(DT.verify(DominatorTree::VerificationLevel::Fast));
#endif

  Loop *newLoop = LI.AllocateLoop();
  if (outer)
    outer->addChildLoop(newLoop);
  else
    LI.addTopLevelLoop(newLoop);

  // Insert guard blocks first so they become the header
  for (BasicBlock *hub : hubBlocks) {
    LLVM_DEBUG(dbgs() << "inserted guard block: " << hub->getName() << "\n");
    newLoop->addBasicBlockToLoop(hub, LI);
  }

  // Add original SCC blocks
  for (BasicBlock *BB : loopBlocks) {
    newLoop->addBlockEntry(BB);
    if (LI.getLoopFor(BB) == outer) {
      LLVM_DEBUG(dbgs() << "promoted block from outer: " << BB->getName() << "\n");
      LI.changeLoopFor(BB, newLoop);
    } else {
      LLVM_DEBUG(dbgs() << "retained block from inner: " << BB->getName() << "\n");
    }
  }

  LLVM_DEBUG(dbgs() << "new loop header: " << newLoop->getHeader()->getName() << "\n");

  reattachNestedLoops(LI, outer, newLoop, loopBlocks, loopHeaders);
  newLoop->verifyLoop();
  if (outer)
    outer->verifyLoop();

#if defined(EXPENSIVE_CHECKS)
  LI.verify(DT);
#endif
}

