// Helper overloads for generic dispatch
static BasicBlock *extractBlock(BasicBlock *B) { return B; }
static BasicBlock *extractBlock(LoopBodyTraits::NodeRef N) { return N.second; }

// Top-level wrapper — top-level function case
static void wrapNaturalLoop(LoopInfo &LI, DominatorTree &DT, Function *F,
                            std::set<BasicBlock *> const &blocks,
                            std::set<BasicBlock *> const &headers) {
  buildNaturalLoop(LI, DT, nullptr, blocks, headers);
}

// Top-level wrapper — loop-contained case
static void wrapNaturalLoop(LoopInfo &LI, DominatorTree &DT, Loop &L,
                            std::set<BasicBlock *> const &blocks,
                            std::set<BasicBlock *> const &headers) {
  buildNaturalLoop(LI, DT, &L, blocks, headers);
}

// Generic SCC-processing engine — works on any graph-like object (Function or Loop).
template <typename G>
static bool reduceIrreducible(LoopInfo &LI, DominatorTree &DT, G &&graph) {
  bool modified = false;

  for (auto sccIt = scc_begin(graph); !sccIt.isAtEnd(); ++sccIt) {
    auto const &scc = *sccIt;
    if (scc.size() < 2) continue;

    std::set<BasicBlock *> sccBlocks;
    LLVM_DEBUG(dbgs() << "Detected SCC:");
    for (auto node : scc) {
      BasicBlock *bb = extractBlock(node);
      LLVM_DEBUG(dbgs() << " " << bb->getName());
      sccBlocks.insert(bb);
    }
    LLVM_DEBUG(dbgs() << "\n");

    // Identify headers by scanning predecessors in reverse order
    std::set<BasicBlock *> sccHeaders;
    LLVM_DEBUG(dbgs() << "Identified headers:");
    for (auto *bb : reverse(sccBlocks)) {
      for (BasicBlock *pred : predecessors(bb)) {
        if (!DT.isReachableFromEntry(pred)) continue;
        if (!sccBlocks.count(pred)) {
          LLVM_DEBUG(dbgs() << " " << bb->getName());
          sccHeaders.insert(bb);
          break;
        }
      }
    }
    LLVM_DEBUG(dbgs() << "\n");

    if (sccHeaders.size() == 1) {
      if (LI.isLoopHeader(*sccHeaders.begin())) {
        LLVM_DEBUG(dbgs() << "Already a natural loop — skipped\n");
        continue;
      }
    }

    wrapNaturalLoop(LI, DT, graph, sccBlocks, sccHeaders);
    modified = true;
  }

  return modified;
}

static bool fixIrreducibleInFunction(Function &F, LoopInfo &LI, DominatorTree &DT) {
  LLVM_DEBUG(dbgs() << "Processing function: " << F.getName() << "\n");
  assert(hasOnlySimpleTerminator(F) && "Unsupported terminator kind.");

  bool changed = false;
  SmallVector<Loop *, 8> worklist;

  changed |= reduceIrreducible(LI, DT, &F);
  append_range(worklist, LI);

  while (!worklist.empty()) {
    Loop *current = worklist.pop_back_val();
    LLVM_DEBUG(dbgs() << "Analyzing loop with header: "
                      << current->getHeader()->getName() << "\n");

    changed |= reduceIrreducible(LI, DT, *current);
    worklist.append(current->begin(), current->end());
  }

  return changed;
}

bool IrreducibleFixer::runOnFunction(Function &F) {
  auto &LI = getAnalysis<LoopInfoWrapperPass>().getLoopInfo();
  auto &DT = getAnalysis<DominatorTreeWrapperPass>().getDomTree();
  return fixIrreducibleInFunction(F, LI, DT);
}

// New PM entry point
PreservedAnalyses IrreducibleFixerPass::run(Function &F,
                                            FunctionAnalysisManager &AM) {
  auto &LI = AM.getResult<LoopAnalysis>(F);
  auto &DT = AM.getResult<DominatorTreeAnalysis>(F);

  if (!fixIrreducibleInFunction(F, LI, DT))
    return PreservedAnalyses::all();

  PreservedAnalyses PA;
  PA.preserve<LoopAnalysis>();
  PA.preserve<DominatorTreeAnalysis>();
  return PA;
}

