// Helper to print diagnostic info about loaded XML document
void display_xml_info(const std::string& label,
                      const pugi::xml_document& doc,
                      const pugi::xml_parse_result& res)
{
    // Extract root element name's first Unicode code point
    const wchar_t* root_name_w = pugi::as_wide(doc.first_child().name());
    unsigned int first_codepoint = root_name_w[0];

    // Get year value: assuming structure like <root><child><year>1997</year></child></root>
    const char* year_val = doc.first_child()
                              .first_child()
                              .first_child()
                              .child_value();

    std::cout << label
              << "\t: parse result '" << res.description() << "'"
              << ", root name starts at U+" << std::hex << std::uppercase
              << std::setw(4) << std::setfill('0') << first_codepoint
              << ", year: " << year_val
              << std::endl;
}

// Attempt to apply a locale to a wide input stream; returns true on success
bool configure_locale(std::wistream& in_stream, const std::string& loc_name)
{
    try {
        in_stream.imbue(std::locale(loc_name.c_str()));
        return true;
    } catch (const std::exception&) {
        return false;
    }
}

int main()
{
    pugi::xml_document xml_doc;

    // Load UTF-8 encoded file via narrow stream
    {
        std::ifstream utf8_narrow("weekly-utf-8.xml");
        auto parse_result = xml_doc.load(utf8_narrow);
        display_xml_info("UTF8 from narrow stream", xml_doc, parse_result);
    }

    // Load UTF-16 encoded file via narrow stream
    {
        std::ifstream utf16_narrow("weekly-utf-16.xml");
        auto parse_result = xml_doc.load(utf16_narrow);
        display_xml_info("UTF16 from narrow stream", xml_doc, parse_result);
    }

    // Load UTF-8 via wide stream (requires proper UTF-8 locale support)
    {
        std::wifstream utf8_wide("weekly-utf-8.xml");
        if (configure_locale(utf8_wide, "en_US.UTF-8")) {
            auto parse_result = xml_doc.load(utf8_wide);
            display_xml_info("UTF8 from wide stream", xml_doc, parse_result);
        } else {
            std::cerr << "UTF-8 locale not found\n";
        }
    }

    // Wide stream loading of UTF-16 is unsupported without custom codecvt
    {
        std::wifstream utf16_wide("weekly-utf-16.xml");
        // Note: pugixml treats wide streams as UTF-16/32 natively, so no special locale needed.
        // However, due to potential BOM or endianness issues, this may still fail depending on platform.
        auto parse_result = xml_doc.load(utf16_wide);
        display_xml_info("UTF16 from wide stream", xml_doc, parse_result);
    }

    // Load Shift-JIS via wide stream (non-portable; requires specific locales)
    {
        std::wifstream sjis_wide("weekly-shift_jis.xml");
        bool success = configure_locale(sjis_wide, ".932") ||
                       configure_locale(sjis_wide, "ja_JP.SJIS");

        if (success) {
            auto parse_result = xml_doc.load(sjis_wide);
            display_xml_info("Shift-JIS from wide stream", xml_doc, parse_result);
        } else {
            std::cerr << "Shift-JIS locale unavailable\n";
        }
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <functional>
#if defined(__GNUC__) || defined(__clang__)
#define BUILTIN_CLZ __builtin_clz
#else
#include <intrin.h>
#define BUILTIN_CLZ __lzcnt
#endif

const int MAX_SIZE = 4096 + 5;
const int LOG_LEVELS = 13;
int array_size, query_count;
int input_array[MAX_SIZE];
int position_map[MAX_SIZE];
int node_counter;
std::vector<std::pair<int, int>> operation_list;

// Sparse table for range minimum queries
int rmq_table[LOG_LEVELS][MAX_SIZE];

// Segment tree node identifiers
int segment_tree_node_ids[4 * MAX_SIZE];

// Build RMQ sparse table
void construct_rmq_table() {
    // Initialize base level (level 0)
    for (int idx = 1; idx <= array_size; ++idx) {
        rmq_table[0][idx] = input_array[idx];
    }

    // Fill higher levels using dynamic programming
    for (int level = 1; level < LOG_LEVELS; ++level) {
        int span = 1 << level;
        for (int start = 1; start + span - 1 <= array_size; ++start) {
            int half_span = 1 << (level - 1);
            rmq_table[level][start] = std::min(rmq_table[level - 1][start],
                                              rmq_table[level - 1][start + half_span]);
        }
    }
}

// Query minimum in range [l, r]
int range_minimum_query(int left, int right) {
    if (left > right) return array_size + 1;
    int length = right - left + 1;
    int exponent = 31 - BUILTIN_CLZ(length);
    int half_span = 1 << exponent;
    return std::min(rmq_table[exponent][left],
                   rmq_table[exponent][right - half_span + 1]);
}

// Recursively build segment tree nodes from sorted values
int construct_segment_nodes(const std::vector<int>& sorted_values, int begin_idx, int end_idx) {
    if (begin_idx == end_idx - 1) {
        return position_map[sorted_values[begin_idx]];
    }

    int mid_point = begin_idx + (end_idx - begin_idx) / 2;

    int left_child_id = construct_segment_nodes(sorted_values, begin_idx, mid_point);
    int right_child_id = construct_segment_nodes(sorted_values, mid_point, end_idx);

    node_counter++;
    operation_list.push_back({left_child_id, right_child_id});
    return node_counter;
}

// Build segment tree structure
void build_segment_tree(int tree_node, int range_left, int range_right) {
    if (range_left == range_right) {
        segment_tree_node_ids[tree_node] = range_left;
        return;
    }

    int mid_point = range_left + (range_right - range_left) / 2;
    build_segment_tree(tree_node * 2, range_left, mid_point);
    build_segment_tree(tree_node * 2 + 1, mid_point + 1, range_right);

    // Collect values in current segment
    std::vector<int> segment_values;
    segment_values.reserve(range_right - range_left + 1);
    for (int i = range_left; i <= range_right; ++i) {
        segment_values.push_back(input_array[i]);
    }

    // Sort and build subtree
    std::sort(segment_values.begin(), segment_values.end());
    segment_tree_node_ids[tree_node] = construct_segment_nodes(segment_values, 0, segment_values.size());
}

// Structure to hold query node information
struct QueryNode {
    int node_id;
    int left_bound, right_bound;
};

// Collect relevant segment tree nodes for a query range
void collect_query_nodes(int tree_node, int range_left, int range_right,
                        int query_left, int query_right, std::vector<QueryNode>& result) {
    if (query_left > query_right) {
        return;
    }

    if (query_left == range_left && query_right == range_right) {
        result.push_back({segment_tree_node_ids[tree_node], range_left, range_right});
        return;
    }

    int mid_point = range_left + (range_right - range_left) / 2;
    collect_query_nodes(tree_node * 2, range_left, mid_point,
                       query_left, std::min(query_right, mid_point), result);
    collect_query_nodes(tree_node * 2 + 1, mid_point + 1, range_right,
                       std::max(query_left, mid_point + 1), query_right, result);
}

// Structure to hold set information for merging
struct SetData {
    int id;
    int minimum_value;
};

// Comparison function for sorting sets by minimum value
bool compare_set_data(const SetData& first, const SetData& second) {
    return first.minimum_value < second.minimum_value;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::cin >> array_size >> query_count;
    for (int i = 1; i <= array_size; ++i) {
        std::cin >> input_array[i];
        position_map[input_array[i]] = i;
    }

    node_counter = array_size;

    construct_rmq_table();
    build_segment_tree(1, 1, array_size);

    std::vector<int> answers(query_count);

    for (int q_idx = 0; q_idx < query_count; ++q_idx) {
        int l, r;
        std::cin >> l >> r;

        std::vector<QueryNode> query_nodes;
        collect_query_nodes(1, 1, array_size, l, r, query_nodes);

        std::vector<SetData> set_info;
        set_info.reserve(query_nodes.size());
        for (const auto& node : query_nodes) {
            set_info.push_back({node.node_id, range_minimum_query(node.left_bound, node.right_bound)});
        }

        std::sort(set_info.begin(), set_info.end(), compare_set_data);

        if (set_info.empty()) {
            answers[q_idx] = 0;
        } else if (set_info.size() == 1) {
            answers[q_idx] = set_info[0].id;
        } else {
            int merged_id = set_info[0].id;
            for (size_t j = 1; j < set_info.size(); ++j) {
                node_counter++;
                operation_list.push_back({merged_id, set_info[j].id});
                merged_id = node_counter;
            }
            answers[q_idx] = merged_id;
        }
    }

    std::cout << node_counter << "\n";
    for (const auto& op : operation_list) {
        std::cout << op.first << " " << op.second << "\n";
    }
    for (int i = 0; i < query_count; ++i) {
        std::cout << answers[i];
        if (i < query_count - 1) std::cout << " ";
    }
    std::cout << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    cin >> n;

    // Special case for n = 1
    if (n == 1) {
        cout << 1 << " " << 1 << endl;
        cout.flush();
        return 0;
    }

    // Initialize base permutation candidate
    vector<int> base(n + 1);
    random_device rd;
    mt19937 gen(rd());

    bool found_base = false;
    int attempts = 0;

    // Try up to 100 random permutations to find one with 0 inversions
    while (!found_base && attempts < 100) {
        vector<int> trial(n);
        iota(trial.begin(), trial.end(), 1);
        shuffle(trial.begin(), trial.end(), gen);

        cout << 0;
        for (int val : trial) cout << " " << val;
        cout << endl;
        cout.flush();

        int response;
        cin >> response;

        if (response == 0) {
            found_base = true;
            for (int i = 1; i <= n; ++i) {
                base[i] = trial[i - 1];
            }
        }
        attempts++;
    }

    // Prepare to reconstruct the hidden permutation
    vector<int> result(n + 1, 0);
    int discovered = 0;

    // For each value from 1 to n, determine its position
    for (int target = 1; target <= n; ++target) {
        vector<int> candidates;
        for (int idx = 1; idx <= n; ++idx) {
            if (result[idx] == 0) {
                candidates.push_back(idx);
            }
        }

        int left = 0, right = (int)candidates.size() - 1;

        // Binary search to find the exact position of 'target'
        while (left < right) {
            int mid = (left + right) / 2;

            vector<int> query_perm(n + 1);
            for (int i = 1; i <= n; ++i) {
                query_perm[i] = base[i];
            }

            // Replace positions [left, mid] in candidates with 'target'
            for (int k = left; k <= mid; ++k) {
                query_perm[candidates[k]] = target;
            }

            cout << 0;
            for (int i = 1; i <= n; ++i) {
                cout << " " << query_perm[i];
            }
            cout << endl;
            cout.flush();

            int inv_diff;
            cin >> inv_diff;

            int count_new = inv_diff - discovered;
            if (count_new > 0) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }

        // Assign the value to the determined position
        int pos = candidates[left];
        result[pos] = target;
        base[pos] = target;
        discovered++;
    }

    // Output the final answer
    cout << 1;
    for (int i = 1; i <= n; ++i) {
        cout << " " << result[i];
    }
    cout << endl;
    cout.flush();

    return 0;
}

