#include <iostream>
#include <vector>
using namespace std;

// Definition for a binary tree node
struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

class TreeTraversal {
public:
    // Perform inorder traversal using Morris Traversal algorithm
    vector<int> getInorder(TreeNode* node) {
        vector<int> result;
        TreeNode* current = node;

        while (current != nullptr) {
            if (current->left == nullptr) {
                // No left child: visit node and move right
                result.push_back(current->val);
                current = current->right;
            } else {
                // Find the inorder predecessor (rightmost in left subtree)
                TreeNode* pred = current->left;
                while (pred->right != nullptr && pred->right != current) {
                    pred = pred->right;
                }

                if (pred->right == nullptr) {
                    // Create temporary thread back to current node
                    pred->right = current;
                    current = current->left;
                } else {
                    // Thread already exists: break it, visit node, then go right
                    pred->right = nullptr;
                    result.push_back(current->val);
                    current = current->right;
                }
            }
        }
        return result;
    }
};

int main() {
    // Construct example tree:
    //     1
    //      \
    //       2
    //      /
    //     3
    TreeNode* root = new TreeNode(1);
    root->right = new TreeNode(2);
    root->right->left = new TreeNode(3);

    TreeTraversal solver;
    vector<int> traversal = solver.getInorder(root);

    cout << "Inorder traversal: ";
    for (int value : traversal) {
        cout << value << " ";
    }
    cout << endl;

    return 0;
}

