MenuBackup::MenuBackup(shared_ptr<Inventory> inv, AbstractContainerMenu *container)
{
    snapshotMap = new std::unordered_map<short, ItemInstanceArray*>();
    playerInv = inv;
    uiMenu = container;
}

void MenuBackup::record(short snapshotId)
{
    ItemInstanceArray* snapshot = new ItemInstanceArray(static_cast<int>(uiMenu->slots->size()) + 1);
    snapshot[0] = ItemInstance::copy(playerInv->getCarried());

    for (size_t idx = 0; idx < uiMenu->slots->size(); ++idx)
    {
        snapshot[idx + 1] = ItemInstance::copy(uiMenu->slots->at(idx)->getItem());
    }

    // Store snapshot under given identifier
    (*snapshotMap)[snapshotId] = snapshot;
}

void MenuBackup::removeSnapshot(short snapshotId)
{
    // Safely remove specific entry from map
    auto it = snapshotMap->find(snapshotId);
    if (it != snapshotMap->end())
    {
        delete it->second;
        snapshotMap->erase(it);
    }
}

void MenuBackup::restore(short snapshotId)
{
    ItemInstanceArray* snapshot = snapshotMap->at(snapshotId);

    // Clear all existing backups after restoration (as original did)
    for (auto& pair : *snapshotMap)
    {
        delete pair.second;
    }
    snapshotMap->clear();

    // Restore carried item
    playerInv->setCarried(snapshot[0]);

    // Restore slot contents
    for (size_t i = 0; i < uiMenu->slots->size(); ++i)
    {
        uiMenu->slots->at(i)->set(snapshot[i + 1]);
    }
}

