#include <bits/stdc++.h>
using namespace std;

int n, q;
vector<int> arr;
map<pair<int, int>, int> memo;
vector<pair<int, int>> edges;
int next_node_id;

int build_tree(int left, int right) {
    pair<int, int> range = {left, right};
    if (memo.find(range) != memo.end()) return memo[range];

    vector<int> indices;
    for (int idx = left; idx <= right; idx++) {
        indices.push_back(idx);
    }

    if (indices.empty()) return -1;

    sort(indices.begin(), indices.end(), [&](int i, int j) {
        return arr[i] < arr[j];
    });

    int current = indices[0];
    for (size_t k = 1; k < indices.size(); ++k) {
        int next_val = indices[k];
        next_node_id++;
        edges.emplace_back(current, next_val);
        current = next_node_id;
    }

    memo[range] = current;
    return current;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    cin >> n >> q;
    arr.resize(n + 1);
    for (int i = 1; i <= n; i++) {
        cin >> arr[i];
    }

    vector<int> results(q);
    next_node_id = n;

    for (int i = 0; i < q; i++) {
        int l, r;
        cin >> l >> r;
        results[i] = build_tree(l, r);
    }

    cout << next_node_id << '\n';
    for (auto edge : edges) {
        cout << edge.first << " " << edge.second << '\n';
    }

    for (int i = 0; i < q; i++) {
        cout << results[i];
        if (i != q - 1) cout << " ";
        else cout << "\n";
    }

    return 0;
}

