TEST(Color, SrgbGammaRoundTrip) {
    float testValues[] = {0.0f, 0.01f, 0.04045f, 0.1f, 0.5f, 0.9f, 1.0f};
    for (float input : testValues) {
        float linearSpace = SrgbToLinear(input);
        float srgbBack    = LinearToSrgb(linearSpace);
        EXPECT_NEAR(srgbBack, input, 1e-5f) << "Original value: " << input;
    }
