// Test RGB ↔ Lab conversion round-trip accuracy
TEST(Color, RgbLabRoundTrip) {
    Rgb originalColor(0.2f, 0.5f, 0.8f);
    Lab labForm = originalColor.ToLab();
    Rgb recovered = labForm.ToRgb();

    EXPECT_NEAR(recovered.r(), originalColor.r(), 1e-4f);
    EXPECT_NEAR(recovered.g(), originalColor.g(), 1e-4f);
    EXPECT_NEAR(recovered.b(), originalColor.b(), 1e-4f);
}

// Verify consistency between ToLab() and static FromRgb()
TEST(Color, LabFromRgbConsistency) {
    Rgb rgbInput(0.3f, 0.6f, 0.1f);
    Lab labMethod1 = rgbInput.ToLab();
    Lab labMethod2 = Lab::FromRgb(rgbInput);

    EXPECT_FLOAT_EQ(labMethod1.l(), labMethod2.l());
    EXPECT_FLOAT_EQ(labMethod1.a(), labMethod2.a());
    EXPECT_FLOAT_EQ(labMethod1.b(), labMethod2.b());
}

// Verify consistency between ToRgb() and static FromLab()
TEST(Color, RgbFromLabConsistency) {
    Lab labInput(50.0f, 20.0f, -30.0f);
    Rgb rgbMethod1 = labInput.ToRgb();
    Rgb rgbMethod2 = Rgb::FromLab(labInput);

    EXPECT_FLOAT_EQ(rgbMethod1.r(), rgbMethod2.r());
    EXPECT_FLOAT_EQ(rgbMethod1.g(), rgbMethod2.g());
    EXPECT_FLOAT_EQ(rgbMethod1.b(), rgbMethod2.b());
}

// DeltaE76 should be zero for identical colors
TEST(Color, DeltaE76SameColor) {
    Lab color(50.0f, 0.0f, 0.0f);
    EXPECT_FLOAT_EQ(Lab::DeltaE76(color, color), 0.0f);
}

// DeltaE76 against known Euclidean distance case
TEST(Color, DeltaE76KnownValue) {
    Lab pointA(50.0f, 0.0f, 0.0f);
    Lab pointB(50.0f, 3.0f, 4.0f);
    float diff = Lab::DeltaE76(pointA, pointB);
    EXPECT_NEAR(diff, 5.0f, 1e-5f);
}

// Test 8-bit RGB ↔ internal Rgb conversion round-trip
TEST(Color, Rgb255RoundTrip) {
    uint8_t rIn = 128, gIn = 64, bIn = 200;
    Rgb converted = Rgb::FromRgb255(rIn, gIn, bIn);
    uint8_t rOut, gOut, bOut;
    converted.ToRgb255(rOut, gOut, bOut);

