#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, queries;
    if (!(cin >> n >> queries)) return 0;

    vector<int> arr(n + 1);
    for (int idx = 1; idx <= n; ++idx) {
        cin >> arr[idx];
    }

    // Map value to its position
    vector<int> val_to_pos(n + 1);
    for (int idx = 1; idx <= n; ++idx) {
        val_to_pos[arr[idx]] = idx;
    }

    // Store all operations and results
    vector<pair<int, int>> operations;
    operations.reserve(2200000);

    vector<int> result_values;
    result_values.reserve(queries);

    long long total_ops = n;

    for (int q_idx = 0; q_idx < queries; ++q_idx) {
        int left, right;
        cin >> left >> right;

        // Collect elements in range [left, right]
        vector<int> segment_vals;
        segment_vals.reserve(right - left + 1);
        for (int pos = left; pos <= right; ++pos) {
            segment_vals.push_back(arr[pos]);
        }

        // Sort the segment values
        sort(segment_vals.begin(), segment_vals.end());

        if (segment_vals.empty()) {
            result_values.push_back(1);
        } else {
            long long current_pos = val_to_pos[segment_vals[0]];

            // Link consecutive elements in sorted order
            for (size_t seg_idx = 1; seg_idx < segment_vals.size(); ++seg_idx) {
                int next_val = segment_vals[seg_idx];
                int next_pos = val_to_pos[next_val];

                operations.emplace_back(current_pos, next_pos);
                ++total_ops;
                current_pos = total_ops;
            }

            result_values.push_back(static_cast<int>(current_pos));
        }
    }

    cout << total_ops << "\n";
    for (const auto& op : operations) {
        cout << op.first << " " << op.second << "\n";
    }

    for (int i = 0; i < static_cast<int>(result_values.size()); ++i) {
        if (i > 0) cout << " ";
        cout << result_values[i];
    }
    cout << "\n";

    return 0;
}

