UDisplayClusterXformComponent::UDisplayClusterXformComponent(const FObjectInitializer& ObjectInitializer)
	: Super(ObjectInitializer)
{
	// Ensure the component can tick for VRPN tracking updates
	PrimaryComponentTick.bCanEverTick = true;

#if WITH_EDITOR
	if (GIsEditor)
	{
		// Initialize a visual representation mesh as a child component
		VisXformComponent = CreateDefaultSubobject<UStaticMeshComponent>(FName(*FString::Printf(TEXT("%s_impl"), *GetName())));

		if (VisXformComponent)
		{
			// Load the default screen mesh from engine resources
			static ConstructorHelpers::FObjectFinder<UStaticMesh> ScreenMesh(TEXT("/Engine/VREditor/TransformGizmo/SM_Sequencer_Node"));

			// Apply flags to prevent serialization and duplication issues
			VisXformComponent->SetFlags(EObjectFlags::RF_DuplicateTransient | RF_Transient | RF_TextExportTransient);

			// Attach to parent without preserving world transform
			VisXformComponent->AttachToComponent(this, FAttachmentTransformRules::KeepRelativeTransform);

			// Configure relative transform properties
			VisXformComponent->SetRelativeLocation(FVector::ZeroVector);
			VisXformComponent->SetRelativeRotation(FRotator::ZeroRotator);
			VisXformComponent->SetRelativeScale3D(FVector::OneVector);

			// Assign the loaded static mesh
			VisXformComponent->SetStaticMesh(ScreenMesh.Object);

			// Set mobility and collision settings
			VisXformComponent->SetMobility(EComponentMobility::Movable);
			VisXformComponent->SetCollisionEnabled(ECollisionEnabled::NoCollision);

			// Make the component visible
			VisXformComponent->SetVisibility(true);
		}
	}
#endif
}

