#include "llvm/MC/MCDXContainerWriter.h"
#include "llvm/BinaryFormat/DXContainer.h"
#include "llvm/MC/MCAsmLayout.h"
#include "llvm/MC/MCAssembler.h"
#include "llvm/MC/MCContext.h"
#include "llvm/MC/MCSection.h"
#include "llvm/Support/Alignment.h"
#include "llvm/Support/EndianStream.h"
#include <cstring>

using namespace llvm;

namespace {

class DXContainerEmitter : public MCObjectWriter {
  ::support::endian::Writer StreamWriter;
  std::unique_ptr<MCDXContainerTargetWriter> TargetWriter;

public:
  DXContainerEmitter(std::unique_ptr<MCDXContainerTargetWriter> Writer,
                     raw_pwrite_stream &OutStream)
      : StreamWriter(OutStream, llvm::endianness::little),
        TargetWriter(std::move(Writer)) {}

  ~DXContainerEmitter() override = default;

private:
  void recordRelocation(MCAssembler &, const MCAsmLayout &, const MCFragment *,
                        const MCFixup &, MCValue, uint64_t &) override {}
  void executePostLayoutBinding(MCAssembler &, const MCAsmLayout &) override {}

  uint64_t emitBinary(MCAssembler &Asm, const MCAsmLayout &Layout) override;
};

} // anonymous namespace

uint64_t DXContainerEmitter::emitBinary(MCAssembler &Asm,
                                        const MCAsmLayout &Layout) {
  SmallVector<uint64_t, 16> PartBoundaries;
  uint64_t CurrentOffset = 0;

  for (const auto &Sec : Asm) {
    uint64_t SecSize = Layout.getSectionAddressSize(&Sec);
    if (SecSize == 0)
      continue;

    assert(SecSize < UINT32_MAX && "Section too large for DXContainer");

    PartBoundaries.push_back(CurrentOffset);
    uint64_t PartSize = sizeof(dxbc::PartHeader) + SecSize;
    PartSize = alignTo(PartSize, Align(4));
    CurrentOffset = PartSize;

    if (Sec.getName() == "DXIL")
      CurrentOffset += sizeof(dxbc::ProgramHeader);
  }

  assert(CurrentOffset < UINT32_MAX && "Total part size exceeds limit");
  uint64_t HeaderEnd =
      sizeof(dxbc::Header) + (PartBoundaries.size() * sizeof(uint32_t));
  uint64_t TotalSize = HeaderEnd + CurrentOffset;
  assert(TotalSize < UINT32_MAX && "File size exceeds DXContainer limits");

  // Write DXBC magic
  StreamWriter.write<char>({'D', 'X', 'B', 'C'});
  // Zero out hash field (16 bytes)
  StreamWriter.OS.write_zeros(16);
  // Version: 1.0
  StreamWriter.write<uint16_t>(1u);
  StreamWriter.write<uint16_t>(0u);
  // File size
  StreamWriter.write<uint32_t>(static_cast<uint32_t>(TotalSize));
  // Number of parts
  StreamWriter.write<uint32_t>(static_cast<uint32_t>(PartBoundaries.size()));

  // Emit part offsets relative to start of part table
  for (uint64_t Offset : PartBoundaries)
    StreamWriter.write<uint32_t>(static_cast<uint32_t>(HeaderEnd + Offset));

  // Now write each non-empty section
  for (const auto &Sec : Asm) {
    uint64_t SecSize = Layout.getSectionAddressSize(&Sec);
    if (SecSize == 0)
      continue;

    unsigned StartPos = StreamWriter.OS.tell();

    // Four-character tag from section name
    StringRef Name = Sec.getName();
    assert(Name.size() >= 4 && "Invalid section name length");
    StreamWriter.write<char>(Name.substr(0, 4));

    uint64_t PartSize = SecSize;
    if (Sec.getName() == "DXIL")
      PartSize += sizeof(dxbc::ProgramHeader);

    PartSize = alignTo(PartSize, Align(4));
    StreamWriter.write<uint32_t>(static_cast<uint32_t>(PartSize));

    if (Sec.getName() == "DXIL") {
      dxbc::ProgramHeader progHdr{};
      memset(&progHdr, 0, sizeof(progHdr));

      const Triple &Triple = Asm.getContext().getTargetTriple();
      VersionTuple Ver = Triple.getOSVersion();

      progHdr.MajorVersion = static_cast<uint8_t>(Ver.getMajor());
      if (Ver.hasMinor())
        progHdr.MinorVersion = static_cast<uint8_t>(*Ver.getMinor());

      if (Triple.hasEnvironment())
        progHdr.ShaderKind =
            static_cast<uint16_t>(Triple.getEnvironment() - Triple::Pixel);

      // Size in 32-bit words
      progHdr.Size =
          static_cast<uint32_t>((SecSize + sizeof(dxbc::ProgramHeader) + 3) / 4);

      memcpy(progHdr.Bitcode.Magic, "DXIL", 4);
      progHdr.Bitcode.Offset = sizeof(dxbc::BitcodeHeader);
      progHdr.Bitcode.Size = static_cast<uint32_t>(SecSize);

      if (sys::IsBigEndianHost)
        progHdr.swapBytes();

      StreamWriter.write<char>(
          ArrayRef<char>(reinterpret_cast<char *>(&progHdr),
                         sizeof(dxbc::ProgramHeader)));
    }

    Asm.writeSectionData(StreamWriter.OS, &Sec, Layout);

    unsigned Written = StreamWriter.OS.tell() - StartPos;
    StreamWriter.OS.write_zeros(offsetToAlignment(Written, Align(4)));
  }

  return 0;
}

std::unique_ptr<MCObjectWriter> llvm::createDXContainerObjectWriter(
    std::unique_ptr<MCDXContainerTargetWriter> TargetWriter,
    raw_pwrite_stream &OS) {
  return std::make_unique<DXContainerEmitter>(std::move(TargetWriter), OS);
}

