        expect_str_eq(rem_ptr, current->remainder_expected,
            "Unexpected remainder for input '%s' with base %d",
            current->input_str, current->base_specified);

        if (err == 0) {
            expect_ju_eq(val, current->expected_value,
                "Unexpected result for input '%s' with base %d",
                current->input_str, current->base_specified);
        }
    }
}
TEST_END

