// Generic static array wrapper for deserialization
template<typename ElemType, typename SizeType>
struct FixedArray {
    ElemType* buffer = nullptr;
    SizeType count = 0;

    ~FixedArray() {
        delete[] buffer;
    }

    void AllocateFrom(BinaryReader& stream) {
        stream.ReadLE(count);
        delete[] buffer;
        if (count > 0)
            buffer = new ElemType[count];
    }

    void LoadFrom(BinaryReader& stream) {
        for (SizeType idx = 0; idx < count; ++idx)
            buffer[idx].Deserialize(stream);
    }

    void AllocateAndLoad(BinaryReader& stream) {
        AllocateFrom(stream);
        LoadFrom(stream);
    }
};

// Lightweight string descriptor
struct StringRef {
    uint32_t size = 0;
    const char* chars = nullptr;

    void Deserialize(BinaryReader& stream) {
        assert(stream.ReadLE(size));
        assert(stream.ReadBytes(chars, size));
    }
};

using StringTable = FixedArray<StringRef, uint32_t>;

void DisplayStrings(StringTable& table) {
    for (uint32_t i = 0; i < table.count; ++i)
        printf("\"%.*s\"\n", table.buffer[i].size, table.buffer[i].chars);
}

// Header entry record
struct RecordHeader {
    uint32_t field0;
    uint32_t field1;
    uint32_t field2;
    uint32_t field3;
    uint32_t field4;
    uint32_t field5;
    uint32_t field6;
    uint32_t field7;

    void Deserialize(BinaryReader& stream) {
        stream.ReadLE(field0);
        stream.ReadLE(field1);
        stream.ReadLE(field2);
        stream.ReadLE(field3);
        stream.ReadLE(field4);
        stream.ReadLE(field5);
        stream.ReadLE(field6);
        stream.ReadLE(field7);
    }
};

// Top-level header block
struct SectionHeader {
    FixedArray<RecordHeader, uint32_t> records;
    uint32_t zeroCheck;
    uint32_t worldEntityId;
    uint32_t primaryTableSize;

    void Deserialize(BinaryReader& stream) {
        records.AllocateFrom(stream);
        stream.ReadLE(zeroCheck);
        assert(zeroCheck == 0);
        stream.ReadLE(worldEntityId);
        stream.ReadLE(primaryTableSize);
        records.LoadFrom(stream);
    }
};

// Error handler: prints current file position and aborts
void AbortOnFailure(BinaryReader& stream) {
    printf("%zu\n", stream.GetPosition());
    assert(false);
}

// Main section containing all parsed data
struct StaticDataSection {
    SectionHeader mainHeader;
    StringTable stringTableA;
    StringTable stringTableB;

    void Deserialize(BinaryReader& stream) {
        mainHeader.Deserialize(stream);
        stringTableA.AllocateAndLoad(stream);
        assert(stringTableA.count == mainHeader.primaryTableSize);

        // Process trailing bytecode until terminator found
        for (;;) {
            uint32_t opcode, pad0, pad1;
            if (!stream.ReadLE(opcode)) break;

            if (opcode == 0) {
                stream.ReadLE(pad0);
                stream.ReadLE(pad1);
                assert(pad0 == 0 && pad1 == 0);
            } else {
                AbortOnFailure(stream);
            }
        }

        // Optional debug output:
        // DisplayStrings(stringTableA);
    }
};

// Public API implementation
void StaticsParser::Parse(BinaryReader& reader) {
    StaticDataSection data;
    data.Deserialize(reader);
}

