using namespace NPerforator::NLinguist::NPython;

namespace NPerforator::NLinguist::NPython {
    TMaybe<TPythonVersion> TryScanVersion(TConstArrayRef<char> data);
}

TEST(PythonVersionParsing, TryScanVersionAlternative) {
    struct TestCase {
        TString Input;
        bool ExpectSuccess;
        TPythonVersion Expected;
    };

    TVector<TestCase> cases = {
        {"Python 3.10.0", true, {3, 10, 0}},
        {"Python 3.10.1", true, {3, 10, 1}},
        {"Python 2.7", true, {2, 7, 0}},
        {"Python 2.7.10", true, {2, 7, 10}},
        {"Python 3.8.15", true, {3, 8, 15}},
        {"Python 3.12.0", true, {3, 12, 0}},
        {"Python 3.12.1", true, {3, 12, 1}},
        {"Python 2.8.3", true, {2, 8, 3}},
        {"Python version 3.10.0, 64 bit", true, {3, 10, 0}},
        {"Version: Python 2.7.15", true, {2, 7, 15}},
        {"Python 4.0.0", false, {}},
        {"No version here", false, {}},
        {"Python v9.8.7", false, {}},
    };

    for (const auto& test : cases) {
        TMaybe<TPythonVersion> actual = TryScanVersion(
            TConstArrayRef<char>{test.Input.data(), test.Input.size()}
        );

        if (test.ExpectSuccess) {
            ASSERT_TRUE(actual.Defined()) 
                << "Expected to parse: '" << test.Input << "'";

            EXPECT_EQ(actual->MajorVersion, test.Expected.MajorVersion)
                << "Major version mismatch on input: '" << test.Input << "'";
            EXPECT_EQ(actual->MinorVersion, test.Expected.MinorVersion)
                << "Minor version mismatch on input: '" << test.Input << "'";
            EXPECT_EQ(actual->MicroVersion, test.Expected.MicroVersion)
                << "Micro version mismatch on input: '" << test.Input << "'";
        } else {
            EXPECT_FALSE(actual.Defined())
                << "Should not have parsed: '" << test.Input << "'";
        }
    }
}

