//----------------------------------------------------------------------------------
// Processes button press events with input throttling and telemetry logging.
//----------------------------------------------------------------------------------
HRESULT CScene_Death::OnNotifyPressEx(HXUIOBJ hObjPressed, XUINotifyPress* pNotifyPressData, BOOL& rfHandled)
{
	if (m_bIgnoreInput)
		return S_OK;

	// Simulate controller input feedback
	ui.AnimateKeyPress(pNotifyPressData->UserIndex, VK_PAD_A);

	// Identify which button triggered this event
	size_t btnIdx = 0;
	for (; btnIdx < BUTTONS_DEATH_MAX && m_Buttons[btnIdx] != hObjPressed; ++btnIdx)
		;

	Minecraft* pMinecraft = Minecraft::GetInstance();
	const unsigned int userIndex = pNotifyPressData->UserIndex;

	switch (btnIdx)
	{
	case BUTTON_DEATH_EXITGAME:
	{
		// Prevent further input during exit confirmation flow
		// m_bIgnoreInput = true; // commented out per original fix for #8333

		if (!ProfileManager.IsFullVersion())
		{
			// Trial version handling
			if (userIndex == ProfileManager.GetPrimaryPad())
			{
				TelemetryManager->RecordLevelExit(userIndex, eSen_LevelExitStatus_Failed);
				CXuiSceneBase::ReduceTrialTimerValue();

				UINT confirmIds[2] = { IDS_CONFIRM_CANCEL, IDS_CONFIRM_OK };
				StorageManager.RequestMessageBox(
					IDS_EXIT_GAME,
					IDS_CONFIRM_EXIT_GAME_PROGRESS_LOST,
					confirmIds,
					2,
					userIndex,
					&UIScene_PauseMenu::ExitGameDialogReturned,
					this,
					app.GetStringTable()
				);
			}
			else
			{
				TelemetryManager->RecordLevelExit(userIndex, eSen_LevelExitStatus_Failed);
				app.SetAction(userIndex, eAppAction_ExitPlayer);
			}
		}
		else
		{
			// Full version handling
			if (userIndex == ProfileManager.GetPrimaryPad())
			{
				int playTime = -1;
				if (pMinecraft->localplayers[userIndex])
					playTime = static_cast<int>(pMinecraft->localplayers[userIndex]->getSessionTimer());

				TelemetryManager->RecordLevelExit(userIndex, eSen_LevelExitStatus_Failed);

				UINT confirmIds[3];
				int numConfirmIds = 0;

				if (StorageManager.GetSaveDisabled())
				{
					confirmIds[0] = IDS_CONFIRM_CANCEL;
					confirmIds[1] = IDS_CONFIRM_OK;
					numConfirmIds = 2;
					StorageManager.RequestMessageBox(
						IDS_EXIT_GAME,
						IDS_CONFIRM_EXIT_GAME_PROGRESS_LOST,
						confirmIds,
						numConfirmIds,
						userIndex,
						&UIScene_PauseMenu::ExitGameDialogReturned,
						this,
						app.GetStringTable()
					);
				}
				else
				{
					if (g_NetworkManager.IsHost())
					{
						confirmIds[0] = IDS_CONFIRM_CANCEL;
						confirmIds[1] = IDS_EXIT_GAME_SAVE;
						confirmIds[2] = IDS_EXIT_GAME_NO_SAVE;
						numConfirmIds = 3;
						StorageManager.RequestMessageBox(
							IDS_EXIT_GAME,
							IDS_CONFIRM_EXIT_GAME,
							confirmIds,
							numConfirmIds,
							userIndex,
							&UIScene_PauseMenu::ExitGameSaveDialogReturned,
							this,
							app.GetStringTable()
						);
					}
					else
					{
						confirmIds[0] = IDS_CONFIRM_CANCEL;
						confirmIds[1] = IDS_CONFIRM_OK;
						numConfirmIds = 2;
						StorageManager.RequestMessageBox(
							IDS_EXIT_GAME,
							IDS_CONFIRM_EXIT_GAME,
							confirmIds,
							numConfirmIds,
							userIndex,
							&UIScene_PauseMenu::ExitGameDialogReturned,
							this,
							app.GetStringTable()
						);
					}
				}
			}
			else
			{
				TelemetryManager->RecordLevelExit(userIndex, eSen_LevelExitStatus_Failed);
				app.SetAction(userIndex, eAppAction_ExitPlayer);
			}
		}
		break;
	}

	case BUTTON_DEATH_RESPAWN:
	{
		m_bIgnoreInput = true;
		app.SetAction(userIndex, eAppAction_Respawn);
		break;
	}

	default:
		break;
	}

	return S_OK;
}

//----------------------------------------------------------------------------------
// Handles keyboard/controller key presses (e.g., B, Start, Escape).
//----------------------------------------------------------------------------------
HRESULT CScene_Death::OnKeyDown(XUIMessageInput* pInputData, BOOL& rfHandled)
{
	ui.AnimateKeyPress(pInputData->UserIndex, pInputData->dwKeyCode);

	switch (pInputData->dwKeyCode)
	{
	case VK_PAD_B:
	case VK_PAD_START:
	case VK_ESCAPE:
		rfHandled = TRUE; // Block default behavior (no back-out allowed)
		break;
	}

	return S_OK;
}

//----------------------------------------------------------------------------------
// Worker thread function to perform respawn asynchronously.
//----------------------------------------------------------------------------------
int CScene_Death::RespawnThreadProc(void* lpParameter)
{
	AABB::UseDefaultThreadStorage();
	Vec3::UseDefaultThreadStorage();
	Compression::UseDefaultThreadStorage();

	const size_t iPad = reinterpret_cast<size_t>(lpParameter);
	Minecraft* pMinecraft = Minecraft::GetInstance();

	pMinecraft->localplayers[iPad]->respawn();
	app.SetGameStarted(true);
	pMinecraft->gameRenderer->EnableUpdateThread();

	// Poll until respawn completes (synchronous wait in offline mode)
	while (!pMinecraft->localplayers[iPad]->GetPlayerRespawned())
	{
		Sleep(50);
	}

	return S_OK;
}

