#include "IRrecv.h"
#include "IRsend.h"
#include "IRutils.h"

/// @file
/// @brief Arris "Manchester code" based infrared protocol implementation.
/// @see https://github.com/crankyoldgit/IRremoteESP8266/issues/1595
// Compatible with:
//   Brand: Arris,  Model: VIP1113M cable box
//   Brand: Arris,  Model: 120A V1.0 A18 remote controller

// Timing constants for the Arris protocol
const uint8_t kArrisOverhead = 2;
const uint16_t kArrisHalfClockPeriod = 320;  // microseconds per half-clock cycle
const uint16_t kArrisHdrMark = 8 * kArrisHalfClockPeriod;  // header mark duration
const uint16_t kArrisHdrSpace = 6 * kArrisHalfClockPeriod;  // header space duration

// Gap between repeated transmissions (calculated from total period minus data bits)
// Reference: https://github.com/crankyoldgit/IRremoteESP8266/issues/1595#issuecomment-913755841
// Total period: 102144 microseconds
const uint32_t kArrisGapSpace = 102144 - ((8 + 6 + kArrisBits * 2) *
                                          kArrisHalfClockPeriod);  // microseconds

// Bit mask used to toggle the release state in Arris messages
const uint32_t kArrisReleaseToggle = 0x800008;

// Protocol field sizes
const uint8_t kArrisChecksumSize = 4;      // checksum occupies 4 bits
const uint8_t kArrisCommandSize = 19;      // command occupies 19 bits
const uint8_t kArrisReleaseBit = kArrisChecksumSize + kArrisCommandSize;  // position of release bit

using irutils::sumNibbles;

#if SEND_ARRIS
/// Transmit an Arris Manchester-encoded IR signal.
/// Status: STABLE / Verified operation.
/// @param[in] messageData The encoded data packet to transmit.
/// @param[in] bitCount Number of significant bits in the message.
/// @param[in] repeatCount How many times to repeat the transmission.
/// @see https://github.com/crankyoldgit/IRremoteESP8266/issues/1595
void IRsend::sendArris(const uint64_t messageData, const uint16_t bitCount,
                       const uint16_t repeatCount) {
  enableIROut(38);

  uint16_t repetition = 0;
  while (repetition <= repeatCount) {
    // Send header portion 1
    mark(kArrisHdrMark);
    space(kArrisHdrSpace);

    // Send header portion 2, data payload, and footer using Manchester encoding
    sendManchester(kArrisHalfClockPeriod * 2, 0, kArrisHalfClockPeriod,
                   0, kArrisGapSpace, messageData, bitCount);

    repetition++;
  }
}

/// Toggle the release indicator bit in an Arris message.
/// Used to differentiate between button press and button release events.
/// @param[in] originalData The existing Arris message.
/// @return Modified message with the release bit inverted.
uint32_t IRsend::toggleArrisRelease(const uint32_t originalData) {
  return originalData ^ kArrisReleaseToggle;
}

/// Build a complete 32-bit Arris command word from components.
/// @param[in] commandCode The numeric command identifier.
/// @param[in] isReleased True if this represents button release, false for press.
/// @return Complete 32-bit Arris message ready for transmission.
/// @note Bit layout: [header:8][release:1][command:19][checksum:4]
uint32_t IRsend::encodeArris(const uint32_t commandCode, const bool isReleased) {
  uint32_t result = 0x10000000;

  // Insert command into designated bit range
  irutils::setBits(&result, kArrisChecksumSize, kArrisCommandSize, commandCode);

  // Set release status bit
  irutils::setBit(&result, kArrisReleaseBit, isReleased);

  // Append checksum (sum of nibbles) to complete the message
  return result + sumNibbles(result);
}
#endif  // SEND_ARRIS

#if DECODE_ARRIS
/// Parse an incoming Arris Manchester-coded IR signal.
/// Status: STABLE / Verified operation.
/// @param[in,out] results Pointer to storage for decoded information.
/// @param[in] startIndex Position in raw buffer where decoding should begin.
/// @param[in] expectedBits Expected number of data bits.
/// @param[in] enforceStrict Whether to require strict protocol compliance.
/// @return true if successful decode, false otherwise.
/// @see https://github.com/crankyoldgit/IRremoteESP8266/issues/1595
bool IRrecv::decodeArris(decode_results *results, uint16_t startIndex,
                         const uint16_t expectedBits, const bool enforceStrict) {
  // Check minimum buffer length requirement
  if (results->rawlen < expectedBits + kArrisOverhead - startIndex)
    return false;  // Signal too short for valid Arris frame

  // Validate protocol specification when strict mode enabled
  if (enforceStrict && expectedBits != kArrisBits)
    return false;  // Bit count doesn't match expected Arris format

  // Verify header mark timing
  if (!matchMark(results->rawbuf[startIndex++], kArrisHdrMark)) return false;

  // Verify header space timing
  if (!matchSpace(results->rawbuf[startIndex++], kArrisHdrSpace)) return false;

  // Decode Manchester-encoded data payload
  uint64_t decodedData = 0;
  if (!matchManchester(results->rawbuf + startIndex, &decodedData,
                       results->rawlen - startIndex, expectedBits,
                       kArrisHalfClockPeriod * 2, 0,
                       kArrisHalfClockPeriod, 0, 0,
                       false, kUseDefTol, kMarkExcess, true, false))
    return false;

  // Perform checksum validation in strict mode
  if (enforceStrict) {
    uint8_t calculatedChecksum = sumNibbles(decodedData >> kArrisChecksumSize);
    uint8_t transmittedChecksum = GETBITS32(decodedData, 0, kArrisChecksumSize);

    if (transmittedChecksum != calculatedChecksum)
      return false;  // Checksum mismatch indicates corrupted data
  }

  // Populate decode results structure
  results->decode_type = decode_type_t::ARRIS;
  results->bits = expectedBits;
  results->value = decodedData;

  // Extract and store release flag as address
  results->address = static_cast<bool>(GETBIT32(decodedData, kArrisReleaseBit));

  // Extract command field (skip checksum bits, include release bit position)
  results->command = GETBITS32(decodedData, kArrisChecksumSize, kArrisCommandSize);

  return true;  // Successful decode
}
#endif  // DECODE_ARRIS

