// Modified cost functor for SE3 alignment with reordered operations
struct TestSE3CostFunctorModified {
  EIGEN_MAKE_ALIGNED_OPERATOR_NEW
  TestSE3CostFunctorModified(Sophus::SE3d T_wa) : T_wa(T_wa) {}

  template <class T>
  bool operator()(T const* const sT_wr, T* sResiduals) const {
    using SE3T = Sophus::SE3<T>;
    using Vec6T = Eigen::Matrix<T, 6, 1>;

    Eigen::Map<SE3T const> const T_wr(sT_wr);
    Eigen::Map<Vec6T> residuals(sResiduals);

    // Compute residual in different ways to test multiplication compatibility
    Vec6T res1 = (T_wr * T_wa.cast<T>()).log();
    Vec6T res2 = (T_wa * T_wr.cast<T>()).log();
    Vec6T res3 = (T_wr * T_wa).log();

    // Combine residuals as average to maintain same optimization behavior
    residuals = (res1 + res2 + res3) / static_cast<T>(3.0);
    return true;
  }

  Sophus::SE3d T_wa;
};

// Modified point cost functor with alternative computation path
struct TestPointCostFunctorModified {
  EIGEN_MAKE_ALIGNED_OPERATOR_NEW
  TestPointCostFunctorModified(Sophus::SE3d T_bw, Eigen::Vector3d point_c)
      : T_bw(T_bw), point_c(point_c) {}

  template <class T>
  bool operator()(T const* const sT_wr, T const* const spoint_d,
                  T* sResiduals) const {
    using Vec3T = Eigen::Matrix<T, 3, 1>;

    Eigen::Map<Sophus::SE3<T> const> const T_wr(sT_wr);
    Eigen::Map<Vec3T const> point_d(spoint_d);
    Eigen::Map<Vec3T> residuals(sResiduals);

    // Transform points through different paths to verify Jet compatibility
    Vec3T transformed_b = T_bw.cast<T>() * point_d;
    Vec3T transformed_a = T_wr * point_c.cast<T>();
    Vec3T transformed_c = T_bw * point_d.cast<T>();

    // Use symmetric formulation of the error
    residuals = (transformed_b + transformed_c) / static_cast<T>(2.0) - transformed_a;
    return true;
  }

  Sophus::SE3d T_bw;
  Eigen::Vector3d point_c;
};

bool testOptimization(Sophus::SE3d const& target_transform,
                      Sophus::SE3d const& initial_guess,
                      Sophus::SE3d::Point const& source_point,
                      Sophus::SE3d::Point const& target_point) {
  static constexpr int kPointDim = 3;

  // Initialize parameters
  Sophus::SE3d optimized_T_wr = initial_guess;
  Sophus::SE3d::Point optimized_point = source_point;

  // Setup Ceres problem
  ceres::Problem problem;

  // Add parameter block with custom local parameterization
  problem.AddParameterBlock(optimized_T_wr.data(), Sophus::SE3d::num_parameters,
                            new Sophus::test::LocalParameterizationSE3);

  // Add first cost function (modified version)
  ceres::CostFunction* se3_cost_func =
      new ceres::AutoDiffCostFunction<TestSE3CostFunctorModified, 
                                      Sophus::SE3d::DoF,
                                      Sophus::SE3d::num_parameters>(
          new TestSE3CostFunctorModified(target_transform));
  problem.AddResidualBlock(se3_cost_func, nullptr, optimized_T_wr.data());

  // Add second cost function (modified version)
  ceres::CostFunction* point_cost_func =
      new ceres::AutoDiffCostFunction<TestPointCostFunctorModified, 
                                      kPointDim,
                                      Sophus::SE3d::num_parameters,
                                      kPointDim>(
          new TestPointCostFunctorModified(target_transform, target_point));
  problem.AddResidualBlock(point_cost_func, nullptr, 
                          optimized_T_wr.data(), optimized_point.data());

  // Configure solver options
  ceres::Solver::Options solver_options;
  solver_options.gradient_tolerance = 0.01 * Sophus::Constants<double>::epsilon();
  solver_options.function_tolerance = 0.01 * Sophus::Constants<double>::epsilon();
  solver_options.linear_solver_type = ceres::DENSE_QR;

  // Solve the problem
  ceres::Solver::Summary summary;
  Solve(solver_options, &problem, &summary);
  std::cout << summary.BriefReport() << std::endl;

  // Evaluate final error
  double const error_norm = (target_transform.inverse() * optimized_T_wr).log().squaredNorm();
  bool const success = error_norm < 10.0 * Sophus::Constants<double>::epsilon();
  return success;
}

// Template function to create SE3 from matrix with different output format
template <typename Scalar>
bool ConstructSE3FromMatrix(const Eigen::Matrix<Scalar, 4, 4>& transformation) {
  Sophus::SE3<Scalar> se3_group(transformation);
  std::cout << "Translation: [" 
            << se3_group.translation().transpose() << "]" << std::endl;
  return true;
}

int main(int, char**) {
  using SE3 = Sophus::SE3<double>;
  using SO3 = Sophus::SO3<double>;
  using Point = SE3::Point;
  constexpr double PI = Sophus::Constants<double>::pi();

  // Define test transformations
  std::vector<SE3> transform_list;
  transform_list.emplace_back(SO3::exp(Point(0.2, 0.5, 0.0)), Point(0, 0, 0));
  transform_list.emplace_back(SO3::exp(Point(0.2, 0.5, -1.0)), Point(10, 0, 0));
  transform_list.emplace_back(SO3::exp(Point(0., 0., 0.)), Point(0, 100, 5));
  transform_list.emplace_back(SO3::exp(Point(0., 0., 0.00001)), Point(0, 0, 0));
  transform_list.emplace_back(SO3::exp(Point(0., 0., 0.00001)), 
                              Point(0, -0.00000001, 0.0000000001));
  transform_list.emplace_back(SO3::exp(Point(0., 0., 0.00001)), Point(0.01, 0, 0));
  transform_list.emplace_back(SO3::exp(Point(PI, 0, 0)), Point(4, -5, 0));
  transform_list.emplace_back(
      SE3(SO3::exp(Point(0.2, 0.5, 0.0)), Point(0, 0, 0)) *
      SE3(SO3::exp(Point(PI, 0, 0)), Point(0, 0, 0)) *
      SE3(SO3::exp(Point(-0.2, -0.5, -0.0)), Point(0, 0, 0)));
  transform_list.emplace_back(
      SE3(SO3::exp(Point(0.3, 0.5, 0.1)), Point(2, 0, -7)) *
      SE3(SO3::exp(Point(PI, 0, 0)), Point(0, 0, 0)) *
      SE3(SO3::exp(Point(-0.3, -0.5, -0.1)), Point(0, 6, 0)));

  // Define test points
  std::vector<Point> point_list;
  point_list.emplace_back(1.012, 2.73, -1.4);
  point_list.emplace_back(9.2, -7.3, -4.4);
  point_list.emplace_back(2.5, 0.1, 9.1);
  point_list.emplace_back(12.3, 1.9, 3.8);
  point_list.emplace_back(-3.21, 3.42, 2.3);
  point_list.emplace_back(-8.0, 6.1, -1.1);
  point_list.emplace_back(0.0, 2.5, 5.9);
  point_list.emplace_back(7.1, 7.8, -14);
  point_list.emplace_back(5.8, 9.2, 0.0);

  // Run all tests
  for (size_t idx = 0; idx < transform_list.size(); ++idx) {
    size_t other_idx = (idx + 3) % transform_list.size();
    bool result = testOptimization(transform_list[idx], 
                                  transform_list[other_idx],
                                  point_list[idx],
                                  point_list[other_idx]);
    if (!result) {
      std::cerr << "Test failed at index " << idx << std::endl;
      return -1;
    }
  }

  // Test Jet matrix conversion
  Eigen::Matrix<ceres::Jet<double, 28>, 4, 4> jet_matrix;
  jet_matrix.setIdentity();
  std::cout << "SE3 construction from Jet matrix: " 
            << ConstructSE3FromMatrix(jet_matrix) << std::endl;

  return 0;
}

