/*----------------------------------------------------------------------------------------------------------------------
|	Constructor: initializes member variables to default values for a TAXA block.
*/
NxsTaxaBlock::NxsTaxaBlock()
  : NxsBlock()
	{
	ntax = 0;
	id = "TAXA";
	}

/*----------------------------------------------------------------------------------------------------------------------
|	Destructor: clears the taxonLabels vector.
*/
NxsTaxaBlock::~NxsTaxaBlock()
	{
	taxonLabels.clear();
	}

/*----------------------------------------------------------------------------------------------------------------------
|	Reads and processes the TAXA block content from input stream using token-based parsing.
*/
void NxsTaxaBlock::Read(
  NxsToken &token)
	{
	ntax = 0;
	int expected_ntax = 0;
	isEmpty = false;
	isUserSupplied = true;

	// Consume semicolon after block name
	token.GetNextToken();
	if (!token.Equals(";")) 
		{
		errormsg = "Expected ';' after TAXA block name, but got ";
		errormsg += token.GetToken();
		throw NxsException(errormsg, token.GetFilePosition(), token.GetFileLine(), token.GetFileColumn());
		}

	for (;;)
		{
		token.GetNextToken();

		if (token.Equals("DIMENSIONS"))
			{
			token.GetNextToken(); // skip 'NTAX'
			if (!token.Equals("NTAX"))
				{
				errormsg = "Expected NTAX keyword, but found ";
				errormsg += token.GetToken();
				throw NxsException(errormsg, token.GetFilePosition(), token.GetFileLine(), token.GetFileColumn());
				}

			token.GetNextToken(); // skip '='
			if (!token.Equals("=")) 
				{
				errormsg = "Expected '=', but found ";
				errormsg += token.GetToken();
				throw NxsException(errormsg, token.GetFilePosition(), token.GetFileLine(), token.GetFileColumn());
				}

			token.GetNextToken(); // read number
			expected_ntax = std::stoi(token.GetToken());
			if (expected_ntax <= 0)
				{
				errormsg = "NTAX must be positive (got ";
				errormsg += token.GetToken();
				errormsg += ")";
				throw NxsException(errormsg, token.GetFilePosition(), token.GetFileLine(), token.GetFileColumn());
				}

			token.GetNextToken(); // consume ';'
			if (!token.Equals(";"))
				{
				errormsg = "Expected ';' after DIMENSIONS command, but found ";
				errormsg += token.GetToken();
				throw NxsException(errormsg, token.GetFilePosition(), token.GetFileLine(), token.GetFileColumn());
				}
			}
		else if (token.Equals("TAXLABELS")) 
			{
			if (expected_ntax <= 0) 
				{
				errormsg = "NTAX must be defined before TAXLABELS";
				throw NxsException(errormsg, token.GetFilePosition(), token.GetFileLine(), token.GetFileColumn());
				}

			for (int idx = 0; idx < expected_ntax; ++idx)
				{
                token.SetLabileFlagBit(NxsToken::hyphenNotPunctuation + NxsToken::preserveUnderscores);
				token.GetNextToken();
				AddTaxonLabel(token.GetToken());
				}

			token.GetNextToken(); // consume ';'
			if (!token.Equals(";"))
				{
				errormsg = "Expected ';' after TAXLABELS command, but found ";
				errormsg += token.GetToken();
				throw NxsException(errormsg, token.GetFilePosition(), token.GetFileLine(), token.GetFileColumn());
				}
			}	
		else if (token.Equals("END") || token.Equals("ENDBLOCK"))
			{
			token.GetNextToken();
			if (!token.Equals(";"))
				{
				errormsg = "Expected ';' after ENDBLOCK, but found ";
				errormsg += token.GetToken();
				throw NxsException(errormsg, token.GetFilePosition(), token.GetFileLine(), token.GetFileColumn());
				}
			break;
			}
		else
			{
			SkippingCommand(token.GetToken());
			do
				{
				token.GetNextToken();
				}
			while (!token.AtEOF() && !token.Equals(";"));

			if (token.AtEOF())
				{
				errormsg = "Unexpected end of file";
				throw NxsException(errormsg, token.GetFilePosition(), token.GetFileLine(), token.GetFileColumn());
				}
			}
		}
	}

/*----------------------------------------------------------------------------------------------------------------------
|	Writes a summary of the taxa block contents to the output stream.
*/
void NxsTaxaBlock::Report(
  std::ostream &out)
	{
	out << std::endl;
	out << id << " contains ";
	if (ntax == 0)
		out << "no taxa" << std::endl;
	else if (ntax == 1)
		out << "one taxon" << std::endl;
	else
		out << ntax << " taxa" << std::endl;

	if (ntax == 0)
		return;

	for (unsigned k = 0; k < ntax; ++k)
		out << '\t' << (k+1) << '\t' << taxonLabels[k] << std::endl;
	}

/*----------------------------------------------------------------------------------------------------------------------
|	Resets the taxa block state for reuse or re-reading.
*/
void NxsTaxaBlock::Reset()
	{
	errormsg.clear();
	isEmpty = true;
	isEnabled = true;
	isUserSupplied = false;
	ntax = 0;
	taxonLabels.clear();
	needsQuotes.clear();
	}

/*----------------------------------------------------------------------------------------------------------------------
|	Appends a new taxon label and returns its index.
*/
unsigned NxsTaxaBlock::AddTaxonLabel(
  NxsString s)
	{
	isEmpty = false;
	needsQuotes.push_back(s.QuotesNeeded());
	taxonLabels.push_back(s);
	++ntax;
	return (ntax - 1);
	}

/*----------------------------------------------------------------------------------------------------------------------
|	Replaces the i-th taxon label with a new string.
*/
void NxsTaxaBlock::ChangeTaxonLabel(
  unsigned i,
  NxsString s)
	{
	assert(i < taxonLabels.size());
	needsQuotes[i] = s.QuotesNeeded();
	taxonLabels[i] = s;
	}

/*----------------------------------------------------------------------------------------------------------------------
|	Finds and returns the maximum length among all stored taxon labels.
*/
unsigned NxsTaxaBlock::GetMaxTaxonLabelLength()
	{
	assert(ntax == taxonLabels.size());
	unsigned maxLen = 0;
	for (unsigned i = 0; i < ntax; ++i)
		{
		unsigned len = taxonLabels[i].length();
		if (len > maxLen)
			maxLen = len;
		}
	return maxLen;
	}

/*----------------------------------------------------------------------------------------------------------------------
|	Retrieves the taxon label at position i.
*/
NxsString NxsTaxaBlock::GetTaxonLabel(
  unsigned i)
	{
	assert(i < taxonLabels.size());
	return taxonLabels[i];
	}

/*----------------------------------------------------------------------------------------------------------------------
|	Returns whether the i-th label requires quoting in NEXUS format.
*/
bool NxsTaxaBlock::NeedsQuotes(
  unsigned i)
	{
	assert(i < needsQuotes.size());
	return needsQuotes[i];
	}

/*----------------------------------------------------------------------------------------------------------------------
|	Checks if a given label already exists in the list.
*/
bool NxsTaxaBlock::IsAlreadyDefined(
  NxsString s)
	{
	return std::find(taxonLabels.begin(), taxonLabels.end(), s) != taxonLabels.end();
	}

/*----------------------------------------------------------------------------------------------------------------------
|	Searches for a taxon by name and returns its index; throws exception if not found.
*/
unsigned NxsTaxaBlock::FindTaxon(
  NxsString s)
	{
	unsigned idx = 0;
	for (auto it = taxonLabels.begin(); it != taxonLabels.end(); ++it, ++idx)
		{
		if (*it == s)
			return idx;
		}
	throw NxsTaxaBlock::NxsX_NoSuchTaxon();
	}

/*----------------------------------------------------------------------------------------------------------------------
|	Returns current number of stored taxon labels.
*/
unsigned NxsTaxaBlock::GetNumTaxonLabels()
	{
	return static_cast<unsigned>(taxonLabels.size());
	}

/*----------------------------------------------------------------------------------------------------------------------
|	Sets the ntax counter directly (does not affect actual vector size).
*/
void NxsTaxaBlock::SetNtax(
  unsigned n)
	{
	ntax = n;
	}

