/**Function********************************************************************

  Synopsis    [Prints statistics on symmetric variables.]

  Description []

  SideEffects [None]

******************************************************************************/
void
Cudd_SymmProfile(
  DdManager * manager,
  int  bottom,
  int  top)
{
    int idx, current, groupBottom;
    int totalSymmetric = 0;
    int totalGroups = 0;

    for (idx = bottom; idx <= top; idx++) {
	if (manager->subtables[idx].next != (unsigned) idx) {
	    current = idx;
	    (void) fprintf(manager->out,"Cluster:");
	    do {
		(void) fprintf(manager->out,"  %d",manager->invperm[current]);
		totalSymmetric++;
		groupBottom = current;
		current = manager->subtables[current].next;
	    } while (current != idx);
	    totalGroups++;
#ifdef DD_DEBUG
	    assert(manager->subtables[groupBottom].next == (unsigned) idx);
#endif
	    idx = groupBottom;
	    (void) fprintf(manager->out,"\n");
	}
    }
    (void) fprintf(manager->out,"Total Symmetric = %d\n",totalSymmetric);
    (void) fprintf(manager->out,"Total Groups = %d\n",totalGroups);

} /* end of Cudd_SymmProfile */


