/* Definition of internal functions                                          */
/*---------------------------------------------------------------------------*/



/**Function********************************************************************

  Synopsis    [Checks for symmetry of x and y.]

  Description [Checks for symmetry of x and y. Ignores projection
  functions, unless they are isolated. Returns 1 in case of symmetry; 0
  otherwise.]

  SideEffects [None]

******************************************************************************/
int
cuddSymmCheck(
  DdManager * manager,
  int  posX,
  int  posY)
{
    DdNode *node,*node0,*node1,*n11,*n10,*n01,*n00;
    int negated;		/* node0 is complemented */
    int posSymPos;		/* posX and posY may be positively symmetric */
    int posSymNeg;		/* posX and posY may be negatively symmetric */
    int arcCount;		/* number of arcs from layer posX to layer posY */
    int TotalRef;		/* total reference count of layer posY minus 1 */
    int yVarIndex;
    int loopIdx;
    DdNodePtr *bucketList;
    int bucketSize;
    DdNode *marker = &(manager->sentinel);
#ifdef DD_DEBUG
    int xVarIndex;
#endif

    /* Checks that posX and posY are not the projection functions.
    ** For posX it is sufficient to check whether there is only one
    ** node; indeed, if there is one node, it is the projection function
    ** and it cannot point to posY. Hence, if posY isn't just the projection
    ** function, it has one arc coming from a layer different from posX.
    */
    if (manager->subtables[posX].keys == 1) {
	return(0);
    }
    yVarIndex = manager->invperm[posY];
    if (manager->subtables[posY].keys == 1) {
	if (manager->vars[yVarIndex]->ref == 1)
	    return(0);
    }

    posSymPos = posSymNeg = 1;
    arcCount = 0;
    bucketSize = manager->subtables[posX].slots;
    bucketList = manager->subtables[posX].nodelist;
    for (loopIdx = 0; loopIdx < bucketSize; loopIdx++) {
	node = bucketList[loopIdx];
	while (node != marker) {
	    /* Find node1, node0, node11, node10, node01, node00. */
	    node1 = cuddT(node);
	    node0 = Cudd_Regular(cuddE(node));
	    negated = Cudd_IsComplement(cuddE(node));
	    if ((int) node1->index == yVarIndex) {
		arcCount++;
		n11 = cuddT(node1); n10 = cuddE(node1);
	    } else {
		if ((int) node0->index != yVarIndex) {
		    /* If node is an isolated projection function it is
		    ** allowed to bypass layer posY.
		    */
		    if (node1 != DD_ONE(manager) || node0 != DD_ONE(manager) || node->ref != 1)
			return(0); /* node bypasses layer posY */
		}
		n11 = n10 = node1;
	    }
	    if ((int) node0->index == yVarIndex) {
		arcCount++;
		n01 = cuddT(node0); n00 = cuddE(node0);
	    } else {
		n01 = n00 = node0;
	    }
	    if (negated) {
		n01 = Cudd_Not(n01);
		n00 = Cudd_Not(n00);
	    }

	    if (node1 != DD_ONE(manager) || node0 != DD_ONE(manager) || node->ref != 1) {
		posSymPos &= n01 == n10;
		posSymNeg &= n11 == n00;
		if ((posSymPos == 0) && (posSymNeg == 0))
		    return(0);
	    }

	    node = node->next;
	} /* while */
    } /* for */

    /* Calculate the total reference counts of posY */
    TotalRef = -1; /* -1 for projection function */
    bucketSize = manager->subtables[posY].slots;
    bucketList = manager->subtables[posY].nodelist;
    for (loopIdx = 0; loopIdx < bucketSize; loopIdx++) {
	node = bucketList[loopIdx];
	while (node != marker) {
	    TotalRef += node->ref;
	    node = node->next;
	}
    }

#if defined(DD_DEBUG) && defined(DD_VERBOSE)
    if (arcCount == TotalRef) {
	xVarIndex = manager->invperm[posX];
	(void) fprintf(manager->out,
		       "Found symmetry! x =%d\ty = %d\tPos(%d,%d)\n",
		       xVarIndex,yVarIndex,posX,posY);
    }
#endif

    return(arcCount == TotalRef);

} /* end of cuddSymmCheck */


/**Function********************************************************************

  Synopsis    [Symmetric sifting algorithm.]

  Description [Symmetric sifting algorithm.
  Assumes that no dead nodes are present.
    <ol>
    <li> Order all the variables according to the number of entries in
    each unique subtable.
    <li> Sift the variable up and down, remembering each time the total
    size of the DD heap and grouping variables that are symmetric.
    <li> Select the best permutation.
    <li> Repeat 3 and 4 for all variables.
    </ol>
  Returns 1 plus the number of symmetric variables if successful; 0
  otherwise.]

  SideEffects [None]

  SeeAlso     [cuddSymmSiftingConv]

******************************************************************************/
int
cuddSymmSifting(
  DdManager * manager,
  int  bottom,
  int  top)
{
    int		idx;
    int		*order;
    int		size;
    int		varPos;
    int		success;
    int		symVars;
    int		symGrps;
#ifdef DD_STATS
    int		prevSize;
#endif

    size = manager->size;

    /* Find order in which to sift variables. */
    order = NULL;
    var_entry = ALLOC(int,size);
    if (var_entry == NULL) {
	manager->errorCode = CUDD_MEMORY_OUT;
	goto ddSiftingMemError;
    }
    order = ALLOC(int,size);
    if (order == NULL) {
	manager->errorCode = CUDD_MEMORY_OUT;
	goto ddSiftingMemError;
    }

    for (idx = 0; idx < size; idx++) {
	varPos = manager->perm[idx];
	var_entry[idx] = manager->subtables[varPos].keys;
	order[idx] = idx;
    }

    qsort((void *)order,size,sizeof(int),(DD_QSFP)ddUniqueOrdering);

    /* Initialize the symmetry of each subtable to itself. */
    for (idx = bottom; idx <= top; idx++) {
	manager->subtables[idx].next = idx;
    }

    for (idx = 0; idx < ddMin(manager->siftMaxVar,size); idx++) {
	if (ddTotalNumberSwapping >= manager->siftMaxSwap)
	    break;
        if (util_cpu_time() - manager->startTime > manager->timeLimit) {
            manager->autoDyn = 0; /* prevent further reordering */
            break;
        }
	varPos = manager->perm[order[idx]];
#ifdef DD_STATS
	prevSize = manager->keys - manager->isolated;
#endif
	if (varPos < bottom || varPos > top) continue;
	if (manager->subtables[varPos].next == (unsigned) varPos) {
	    success = ddSiftingProcess(manager,varPos,bottom,top);
	    if (!success) goto ddSiftingMemError;
#ifdef DD_STATS
	    if (manager->keys < (unsigned) prevSize + manager->isolated) {
		(void) fprintf(manager->out,"-");
	    } else if (manager->keys > (unsigned) prevSize +
		       manager->isolated) {
		(void) fprintf(manager->out,"+"); /* should never happen */
	    } else {
		(void) fprintf(manager->out,"=");
	    }
	    fflush(manager->out);
#endif
	}
    }

    FREE(order);
    FREE(var_entry);

    ddCollectStats(manager, bottom, top, &symVars, &symGrps);

#ifdef DD_STATS
    (void) fprintf(manager->out, "\n#:S_SIFTING %8d: symmetric variables\n",
		   symVars);
    (void) fprintf(manager->out, "#:G_SIFTING %8d: symmetric groups",
		   symGrps);
#endif

    return(1+symVars);

ddSiftingMemError:

    if (var_entry != NULL) FREE(var_entry);
    if (order != NULL) FREE(order);

    return(0);

} /* end of cuddSymmSifting */


/**Function********************************************************************

  Synopsis    [Symmetric sifting to convergence algorithm.]

  Description [Symmetric sifting to convergence algorithm.
  Assumes that no dead nodes are present.
    <ol>
    <li> Order all the variables according to the number of entries in
    each unique subtable.
    <li> Sift the variable up and down, remembering each time the total
    size of the DD heap and grouping variables that are symmetric.
    <li> Select the best permutation.
    <li> Repeat 3 and 4 for all variables.
    <li> Repeat 1-4 until no further improvement.
    </ol>
  Returns 1 plus the number of symmetric variables if successful; 0
  otherwise.]

  SideEffects [None]

  SeeAlso     [cuddSymmSifting]

******************************************************************************/
int
cuddSymmSiftingConv(
  DdManager * manager,
  int  bottom,
  int  top)
{
    int		idx;
    int		*order;
    int		size;
    int		varPos;
    int		success;
    int		symVars;
    int		symGrps;
    int		classes;
    int		initialSize;
#ifdef DD_STATS
    int		prevSize;
#endif

    initialSize = manager->keys - manager->isolated;

    size = manager->size;

    /* Find order in which to sift variables. */
    order = NULL;
    var_entry = ALLOC(int,size);
    if (var_entry == NULL) {
	manager->errorCode = CUDD_MEMORY_OUT;
	goto ddConvSiftMemError;
    }
    order = ALLOC(int,size);
    if (order == NULL) {
	manager->errorCode = CUDD_MEMORY_OUT;
	goto ddConvSiftMemError;
    }

    for (idx = 0; idx < size; idx++) {
	varPos = manager->perm[idx];
	var_entry[idx] = manager->subtables[varPos].keys;
	order[idx] = idx;
    }

    qsort((void *)order,size,sizeof(int),(DD_QSFP)ddUniqueOrdering);

    /* Initialize the symmetry of each subtable to itself
    ** for first pass of converging symmetric sifting.
    */
    for (idx = bottom; idx <= top; idx++) {
	manager->subtables[idx].next = idx;
    }

    for (idx = 0; idx < ddMin(manager->siftMaxVar, manager->size); idx++) {
	if (ddTotalNumberSwapping >= manager->siftMaxSwap)
	    break;
        if (util_cpu_time() - manager->startTime > manager->timeLimit) {
            manager->autoDyn = 0; /* prevent further reordering */
            break;
        }
	varPos = manager->perm[order[idx]];
	if (varPos < bottom || varPos > top) continue;
	/* Only sift if not in symmetry group already. */
	if (manager->subtables[varPos].next == (unsigned) varPos) {
#ifdef DD_STATS
	    prevSize = manager->keys - manager->isolated;
#endif
	    success = ddSiftingProcess(manager,varPos,bottom,top);
	    if (!success) goto ddConvSiftMemError;
#ifdef DD_STATS
	    if (manager->keys < (unsigned) prevSize + manager->isolated) {
		(void) fprintf(manager->out,"-");
	    } else if (manager->keys > (unsigned) prevSize +
		       manager->isolated) {
		(void) fprintf(manager->out,"+");
	    } else {
		(void) fprintf(manager->out,"=");
	    }
	    fflush(manager->out);
#endif
	}
    }

    /* Sifting now until convergence. */
    while ((unsigned) initialSize > manager->keys - manager->isolated) {
	initialSize = manager->keys - manager->isolated;
#ifdef DD_STATS
	(void) fprintf(manager->out,"\n");
#endif
	/* Here we consider only one representative for each symmetry class. */
	for (varPos = bottom, classes = 0; varPos <= top; varPos++, classes++) {
	    while ((unsigned) varPos < manager->subtables[varPos].next) {
		varPos = manager->subtables[varPos].next;
	    }
	    /* Here varPos is the largest index in a group.
	    ** Groups consist of adjacent variables.
	    ** Hence, the next increment of varPos will move it to a new group.
	    */
	    idx = manager->invperm[varPos];
	    var_entry[idx] = manager->subtables[varPos].keys;
	    order[classes] = idx;
	}

	qsort((void *)order,classes,sizeof(int),(DD_QSFP)ddUniqueOrdering);

	/* Now sift. */
	for (idx = 0; idx < ddMin(manager->siftMaxVar,classes); idx++) {
	    if (ddTotalNumberSwapping >= manager->siftMaxSwap)
		break;
            if (util_cpu_time() - manager->startTime > manager->timeLimit) {
              manager->autoDyn = 0; /* prevent further reordering */
              break;
            }
	    varPos = manager->perm[order[idx]];
	    if ((unsigned) varPos >= manager->subtables[varPos].next) {
#ifdef DD_STATS
		prevSize = manager->keys - manager->isolated;
#endif
		success = ddConvergeSiftingProcess(manager,varPos,bottom,top);
		if (!success ) goto ddConvSiftMemError;
#ifdef DD_STATS
		if (manager->keys < (unsigned) prevSize + manager->isolated) {
		    (void) fprintf(manager->out,"-");
		} else if (manager->keys > (unsigned) prevSize +
			   manager->isolated) {
		    (void) fprintf(manager->out,"+");
		} else {
		    (void) fprintf(manager->out,"=");
		}
		fflush(manager->out);
#endif
	    }
	} /* for */
    }

    ddCollectStats(manager, bottom, top, &symVars, &symGrps);

#ifdef DD_STATS
    (void) fprintf(manager->out, "\n#:S_SIFTING %8d: symmetric variables\n",
		   symVars);
    (void) fprintf(manager->out, "#:G_SIFTING %8d: symmetric groups",
		   symGrps);
#endif

    FREE(order);
    FREE(var_entry);

    return(1+symVars);

ddConvSiftMemError:

    if (var_entry != NULL) FREE(var_entry);
    if (order != NULL) FREE(order);

    return(0);

} /* end of cuddSymmSiftingConv */


/*---------------------------------------------------------------------------*/
/* Definition of static functions                                            */
/*---------------------------------------------------------------------------*/



/**Function********************************************************************

  Synopsis    [Comparison function used by qsort.]

  Description [Comparison function used by qsort to order the variables
  according to the number of keys in the subtables.
  Returns the difference in number of keys between the two
  variables being compared.]

  SideEffects [None]

******************************************************************************/
static int
ddUniqueOrdering(
  int * ptrA,
  int * ptrB)
{
#if 0
    if (var_entry[*ptrB] == var_entry[*ptrA]) {
	return((*ptrA) - (*ptrB));
    }
#endif
    return(var_entry[*ptrB] - var_entry[*ptrA]);

} /* end of ddUniqueOrdering */


/**Function********************************************************************

  Synopsis    [Given minBound <= var <= maxBound moves var up and down between the
  boundaries.]

  Description [Given minBound <= var <= maxBound moves var up and down between the
  boundaries. Finds the best position and does the required changes.
  Assumes that var is not part of a symmetry group. Returns 1 if
  successful; 0 otherwise.]

  SideEffects [None]

******************************************************************************/
static int
ddSiftingProcess(
  DdManager * manager,
  int  var,
  int  minBound,
  int  maxBound)
{
    Move *step;
    Move *upSteps;	/* list of upward moves */
    Move *downSteps;	/* list of downward moves */
    int	 initialSize;
    int	 result;
    int  i;
    int  topbot;	/* index to either top or bottom of symmetry group */
    int  initGroupSize, finalGroupSize;


#ifdef DD_DEBUG
    /* check for previously detected symmetry */
    assert(manager->subtables[var].next == (unsigned) var);
#endif

    initialSize = manager->keys - manager->isolated;

    downSteps = NULL;
    upSteps = NULL;

    if ((var - minBound) > (maxBound - var)) {
	/* Will go down first, unless var == maxBound:
	** Look for consecutive symmetries above var.
	*/
	for (i = var; i > minBound; i--) {
	    if (!cuddSymmCheck(manager,i-1,i))
		break;
	    topbot = manager->subtables[i-1].next; /* find top of i-1's group */
	    manager->subtables[i-1].next = i;
	    manager->subtables[var].next = topbot; /* var is bottom of group so its */
					       /* next is top of i-1's group */
	    i = topbot + 1; /* add 1 for i--; new i is top of symm group */
	}
    } else {
	/* Will go up first unless var == minBound:
	** Look for consecutive symmetries below var.
	*/
	for (i = var; i < maxBound; i++) {
	    if (!cuddSymmCheck(manager,i,i+1))
		break;
	    /* find bottom of i+1's symm group */
	    topbot = i + 1;
	    while ((unsigned) topbot < manager->subtables[topbot].next) {
		topbot = manager->subtables[topbot].next;
	    }
	    manager->subtables[topbot].next = manager->subtables[i].next;
	    manager->subtables[i].next = i + 1;
	    i = topbot - 1; /* subtract 1 for i++; new i is bottom of group */
	}
    }

    /* Now var may be in the middle of a symmetry group.
    ** Find bottom of var's symm group.
    */
    while ((unsigned) var < manager->subtables[var].next)
	var = manager->subtables[var].next;

    if (var == minBound) { /* Sift down */

#ifdef DD_DEBUG
	/* var must be a singleton */
	assert((unsigned) var == manager->subtables[var].next);
#endif
	if (var == maxBound) return(1);	/* just one variable */

	initGroupSize = 1;

	downSteps = ddMoveDownward(manager,var,maxBound);
	    /* after this point var --> maxBound, unless early term */
	if (downSteps == MV_OOM) goto ddSiftingProcessMemError;
	if (downSteps == NULL) return(1);

	var = downSteps->y;
	/* Find bottom of var's group */
	i = var;
	while ((unsigned) i < manager->subtables[i].next) {
	    i = manager->subtables[i].next;
	}
#ifdef DD_DEBUG
	/* var should be the top of the symmetry group and i the bottom */
	assert((unsigned) i >= manager->subtables[i].next);
	assert((unsigned) var == manager->subtables[i].next);
#endif
	finalGroupSize = i - var + 1;

	if (initGroupSize == finalGroupSize) {
	    /* No new symmetry groups detected, return to best position */
	    result = ddBacktrackPermutation(manager,downSteps,initialSize);
	} else {
	    initialSize = manager->keys - manager->isolated;
	    upSteps = ddMoveUpward(manager,var,minBound);
	    result = ddBacktrackPermutation(manager,upSteps,initialSize);
	}
	if (!result) goto ddSiftingProcessMemError;

    } else if (cuddNextHigh(manager,var) > maxBound) { /* Sift up */
	/* Find top of var's symm group */
	i = var;				/* bottom */
	var = manager->subtables[var].next;	/* top */

	if (var == minBound) return(1); /* just one big group */

	initGroupSize = i - var + 1;

	upSteps = ddMoveUpward(manager,var,minBound);
	    /* after this point var --> minBound, unless early term */
	if (upSteps == MV_OOM) goto ddSiftingProcessMemError;
	if (upSteps == NULL) return(1);

	var = upSteps->x;
	/* Find top of var's group */
	i = manager->subtables[var].next;
#ifdef DD_DEBUG
	/* var should be the bottom of the symmetry group and i the top */
	assert((unsigned) var >= manager->subtables[var].next);
	assert((unsigned) i == manager->subtables[var].next);
#endif
	finalGroupSize = var - i + 1;

	if (initGroupSize == finalGroupSize) {
	    /* No new symmetry groups detected, return to best position */
	    result = ddBacktrackPermutation(manager,upSteps,initialSize);
	} else {
	    initialSize = manager->keys - manager->isolated;
	    downSteps = ddMoveDownward(manager,var,maxBound);
	    result = ddBacktrackPermutation(manager,downSteps,initialSize);
	}
	if (!result) goto ddSiftingProcessMemError;

    } else if ((var - minBound) > (maxBound - var)) { /* must go down first: shorter */

	downSteps = ddMoveDownward(manager,var,maxBound);
	/* at this point var == maxBound, unless early term */
	if (downSteps == MV_OOM) goto ddSiftingProcessMemError;

	if (downSteps != NULL) {
	    var = downSteps->y;	/* var is top here */
	    i = var;
	    while ((unsigned) i < manager->subtables[i].next) {
		i = manager->subtables[i].next;
	    }
	} else {
	    i = var;
	    while ((unsigned) i < manager->subtables[i].next) {
		i = manager->subtables[i].next;
	    }
	    var = manager->subtables[i].next;
	}
#ifdef DD_DEBUG
	/* var should be the top of the symmetry group and i the bottom */
	assert((unsigned) i >= manager->subtables[i].next);
	assert((unsigned) var == manager->subtables[i].next);
#endif
	initGroupSize = i - var + 1;

	upSteps = ddMoveUpward(manager,var,minBound);
	if (upSteps == MV_OOM) goto ddSiftingProcessMemError;

	if (upSteps != NULL) {
	    var = upSteps->x;
	    i = manager->subtables[var].next;
	} else {
	    i = var;
	    while ((unsigned) var < manager->subtables[var].next)
		var = manager->subtables[var].next;
	}
#ifdef DD_DEBUG
	/* var should be the bottom of the symmetry group and i the top */
	assert((unsigned) var >= manager->subtables[var].next);
	assert((unsigned) i == manager->subtables[var].next);
#endif
	finalGroupSize = var - i + 1;

	if (initGroupSize == finalGroupSize) {
	    /* No new symmetry groups detected, return to best position */
	    result = ddBacktrackPermutation(manager,upSteps,initialSize);
	} else {
	    while (downSteps != NULL) {
		step = downSteps->next;
		cuddDeallocMove(manager, downSteps);
		downSteps = step;
	    }
	    initialSize = manager->keys - manager->isolated;
	    downSteps = ddMoveDownward(manager,var,maxBound);
	    result = ddBacktrackPermutation(manager,downSteps,initialSize);
	}
	if (!result) goto ddSiftingProcessMemError;

    } else { /* moving up first: shorter */
	/* Find top of var's symmetry group */
	var = manager->subtables[var].next;

	upSteps = ddMoveUpward(manager,var,minBound);
	/* at this point var == maxBound, unless early term */
	if (upSteps == MV_OOM) goto ddSiftingProcessMemError;

	if (upSteps != NULL) {
	    var = upSteps->x;
	    i = manager->subtables[var].next;
	} else {
	    while ((unsigned) var < manager->subtables[var].next)
		var = manager->subtables[var].next;
	    i = manager->subtables[var].next;
	}
#ifdef DD_DEBUG
	/* var is bottom of the symmetry group and i is top */
	assert((unsigned) var >= manager->subtables[var].next);
	assert((unsigned) i == manager->subtables[var].next);
#endif
	initGroupSize = var - i + 1;

	downSteps = ddMoveDownward(manager,var,maxBound);
	if (downSteps == MV_OOM) goto ddSiftingProcessMemError;

	if (downSteps != NULL) {
	    var = downSteps->y;
	    i = var;
	    while ((unsigned) i < manager->subtables[i].next) {
		i = manager->subtables[i].next;
	    }
	} else {
	    i = var;
	    var = manager->subtables[var].next;
	}
#ifdef DD_DEBUG
	/* var should be the top of the symmetry group and i the bottom */
	assert((unsigned) i >= manager->subtables[i].next);
	assert((unsigned) var == manager->subtables[i].next);
#endif
	finalGroupSize = i - var + 1;

	if (initGroupSize == finalGroupSize) {
	    /* No new symmetries detected, go back to best position */
	    result = ddBacktrackPermutation(manager,downSteps,initialSize);
	} else {
	    while (upSteps != NULL) {
		step = upSteps->next;
		cuddDeallocMove(manager, upSteps);
		upSteps = step;
	    }
	    initialSize = manager->keys - manager->isolated;
	    upSteps = ddMoveUpward(manager,var,minBound);
	    result = ddBacktrackPermutation(manager,upSteps,initialSize);
	}
	if (!result) goto ddSiftingProcessMemError;
    }

    while (downSteps != NULL) {
	step = downSteps->next;
	cuddDeallocMove(manager, downSteps);
	downSteps = step;
    }
    while (upSteps != NULL) {
	step = upSteps->next;
	cuddDeallocMove(manager, upSteps);
	upSteps = step;
    }

    return(1);

ddSiftingProcessMemError:
    if (downSteps != MV_OOM) {
	while (downSteps != NULL) {
	    step = downSteps->next;
	    cuddDeallocMove(manager, downSteps);
	    downSteps = step;
	}
    }
    if (upSteps != MV_OOM) {
	while (upSteps != NULL) {
	    step = upSteps->next;
	    cuddDeallocMove(manager, upSteps);
	    upSteps = step;
	}
    }

    return(0);

} /* end of ddSiftingProcess */


/**Function********************************************************************

  Synopsis    [Given minBound <= var <= maxBound moves var up and down between the
  boundaries.]

  Description [Given minBound <= var <= maxBound moves var up and down between the
  boundaries. Finds the best position and does the required changes.
  Assumes that var is either an isolated variable, or it is the bottom of
  a symmetry group. All symmetries may not have been found, because of
  exceeded growth limit. Returns 1 if successful; 0 otherwise.]

  SideEffects [None]

