    if ((1 == curlx_inet_pton(AF_INET, hostname, addrbuf)) || \
        (1 == curlx_inet_pton(AF_INET6, hostname, addrbuf))) { \
      (hints).ai_flags = AI_NUMERICHOST; \
    } \
  } while(0)
