#ifdef DEBUG_ADDRINFO
static void dump_addrinfo(const struct Curl_addrinfo *ai)
{
  printf("dump_addrinfo:\n");
  for(; ai; ai = ai->ai_next) {
    char buf[INET6_ADDRSTRLEN];
    printf("    fam %2d, CNAME %s, ",
           ai->ai_family, ai->ai_canonname ? ai->ai_canonname : "<none>");
    Curl_printable_address(ai, buf, sizeof(buf));
    printf("%s\n", buf);
  }
}
#else
#define dump_addrinfo(x) Curl_nop_stmt
#endif

/*
 * Curl_sync_getaddrinfo() when built IPv6-enabled (non-threading and
 * non-ares version).
 *
 * Returns name information about the given hostname and port number. If
 * successful, the 'addrinfo' is returned and the fourth argument will point
 * to memory we need to free after use. That memory *MUST* be freed with
 * Curl_freeaddrinfo(), nothing else.
 */
struct Curl_addrinfo *Curl_sync_getaddrinfo(struct Curl_easy *data,
                                            const char *hostname,
                                            int port,
                                            int ip_version)
{
  struct addrinfo hints;
  struct Curl_addrinfo *res = NULL;
  int error;
  char sbuf[12] = {0};
  char *portstr = NULL;
  int family_preference = PF_INET;

  /* Determine address family based on IP version preference and stack capability */
  if((ip_version != CURL_IPRESOLVE_V4) && Curl_ipv6works(data))
    family_preference = PF_UNSPEC;

  memset(&hints, 0, sizeof(hints));
  hints.ai_family   = family_preference;
  hints.ai_socktype = (data->conn->transport == TRNSPRT_TCP) ?
                      SOCK_STREAM : SOCK_DGRAM;

  /* Set numeric host flag only if not using URL resolution on IPs */
  PREVENT_REVERSE_LOOKUP(hints, hostname);

  /* Prepare port string if needed */
  if(port) {
    msnprintf(sbuf, sizeof(sbuf), "%d", port);
    portstr = sbuf;
  }

  /* Perform DNS lookup */
  error = Curl_getaddrinfo_ex(hostname, portstr, &hints, &res);
  if(error) {
    infof(data, "getaddrinfo(3) failed for %s:%d", hostname, port);
    return NULL;
  }

  /* Apply port to resolved addresses if provided */
  if(port) {
    Curl_addrinfo_set_port(res, port);
  }

  /* Optional debug output */
  dump_addrinfo(res);
  return res;
}

