#include <iostream>
#include <vector>
#include <random>
using namespace std;

// Simulates the line-counting process for a given article and width
// Returns 0 if any word exceeds the width W
int countLines(const vector<int>& words, int maxWidth) {
    int lineCount = 1;
    long long currentLength = 0;

    for (int wordLen : words) {
        if (wordLen > maxWidth) return 0; // Invalid case

        if (currentLength + wordLen <= maxWidth) {
            currentLength += wordLen;
        } else {
            lineCount++;
            currentLength = wordLen;
        }
    }

    return lineCount;
}

void process() {
    const int N = 100000;

    // First query: all words of length 1
    cout << "? " << N;
    for (int i = 0; i < N; ++i) {
        cout << " 1";
    }
    cout << endl;

    int response1;
    cin >> response1;

    if (response1 == 0 || response1 == -1) {
        exit(0);
    }

    // Calculate bounds for possible width values
    int lowerBound, upperBound;

    if (response1 == 1) {
        lowerBound = N;
        upperBound = 100000;
    } else {
        lowerBound = (N + response1 - 1) / response1;  // ceil(N/response1)
        upperBound = (N - 1) / (response1 - 1);        // floor((N-1)/(response1-1))
    }

    // Clamp to problem constraints
    if (upperBound > 100000) upperBound = 100000;
    if (lowerBound > upperBound) lowerBound = upperBound;

    if (lowerBound == upperBound) {
        cout << "! " << lowerBound << endl;
        return;
    }

    // Second query: use random word lengths in [1, lowerBound]
    mt19937 rng(42); // Fixed seed for reproducibility
    vector<int> testWords(N);

    for (int i = 0; i < N; ++i) {
        testWords[i] = (rng() % lowerBound) + 1;
    }

    cout << "? " << N;
    for (int i = 0; i < N; ++i) {
        cout << " " << testWords[i];
    }
    cout << endl;

    int response2;
    cin >> response2;
    if (response2 == -1) {
        exit(0);
    }

    // Binary search for correct width value
    int result = upperBound;
    int left = lowerBound, right = upperBound;

    while (left <= right) {
        int mid = left + (right - left) / 2;
        int simulated = countLines(testWords, mid);

        if (simulated == response2) {
            result = mid;
            break;
        } else if (simulated < response2) {
            right = mid - 1;
        } else {
            left = mid + 1;
        }
    }

    cout << "! " << result << endl;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int testCaseCount;
    if (cin >> testCaseCount) {
        while (testCaseCount--) {
            process();
        }
    }

    return 0;
}

#include "PLUGIN_NAME.h"
