static const FName PLUGIN_NAMETabIdentifier("PLUGIN_NAME");

#define LOCTEXT_NAMESPACE "FPLUGIN_NAMEModule"

void FPLUGIN_NAMEModule::StartupModule()
{
	// Initialize styling and commands
	FPLUGIN_NAMEStyle::Initialize();
	FPLUGIN_NAMEStyle::ReloadTextures();
	FPLUGIN_NAMECommands::Register();

	// Prepare command list for UI actions
	PluginActionList = MakeShareable(new FUICommandList);

	// Bind window-open action to handler
	PluginActionList->MapAction(
		FPLUGIN_NAMECommands::Get().OpenPluginWindow,
		FExecuteAction::CreateRaw(this, &FPLUGIN_NAMEModule::HandlePluginButtonPress),
		FCanExecuteAction());

	// Hook into menu registration at startup
	UToolMenus::RegisterStartupCallback(FSimpleMulticastDelegate::FDelegate::CreateRaw(this, &FPLUGIN_NAMEModule::SetupToolMenus));

	// Register a standalone tab spawner
	FGlobalTabmanager::Get()->RegisterNomadTabSpawner(PLUGIN_NAMETabIdentifier, FOnSpawnTab::CreateRaw(this, &FPLUGIN_NAMEModule::GeneratePluginTab))
		.SetDisplayName(LOCTEXT("FPLUGIN_NAMETabTitle", "PLUGIN_NAME"))
		.SetMenuType(ETabSpawnerMenuType::Hidden);
}

void FPLUGIN_NAMEModule::ShutdownModule()
{
	// Clean up registered resources in reverse order of initialization
	UToolMenus::UnRegisterStartupCallback(this);
	UToolMenus::UnregisterOwner(this);

	FPLUGIN_NAMEStyle::Shutdown();
	FPLUGIN_NAMECommands::Unregister();

	FGlobalTabmanager::Get()->UnregisterNomadTabSpawner(PLUGIN_NAMETabIdentifier);
}

TSharedRef<SDockTab> FPLUGIN_NAMEModule::GeneratePluginTab(const FSpawnTabArgs& Args)
{
	const FText InstructionalText = FText::Format(
		LOCTEXT("WindowWidgetText", "Add code to {0} in {1} to override this window's contents"),
		FText::FromString(TEXT("FPLUGIN_NAMEModule::GeneratePluginTab")),
		FText::FromString(TEXT("PLUGIN_NAME.cpp"))
	);

	return SNew(SDockTab)
		.TabRole(ETabRole::NomadTab)
		[
			SNew(SBox)
			.HAlign(HAlign_Center)
			.VAlign(VAlign_Center)
			[
				SNew(STextBlock)
				.Text(InstructionalText)
			]
		];
}

void FPLUGIN_NAMEModule::HandlePluginButtonPress()
{
	FGlobalTabmanager::Get()->TryInvokeTab(PLUGIN_NAMETabIdentifier);
}

void FPLUGIN_NAMEModule::SetupToolMenus()
{
	// Scope ownership for safe cleanup
	FToolMenuOwnerScoped OwnerScope(this);

	// Extend main menu: add entry under Window > Layout
	{
		UToolMenu* MainMenuBar = UToolMenus::Get()->ExtendMenu("LevelEditor.MainMenu.Window");
		if (MainMenuBar)
		{
			FToolMenuSection& LayoutSection = MainMenuBar->FindOrAddSection("WindowLayout");
			LayoutSection.AddMenuEntryWithCommandList(
				FPLUGIN_NAMECommands::Get().OpenPluginWindow,
				PluginActionList
			);
		}
	}

	// Extend toolbar: add button under Settings section
	{
		UToolMenu* ToolBarMenu = UToolMenus::Get()->ExtendMenu("LevelEditor.LevelEditorToolBar");
		if (ToolBarMenu)
		{
			FToolMenuSection& SettingsSection = ToolBarMenu->FindOrAddSection("Settings");
			SettingsSection.AddEntry(
				FToolMenuEntry::InitToolBarButton(FPLUGIN_NAMECommands::Get().OpenPluginWindow)
					.SetCommandList(PluginActionList)
			);
		}
	}
}

