// Attempts to insert a symbolic operand in place of the immediate 'immVal' within MCInst MI.
// The immediate has already been adjusted for PC-relative offsets by the caller.
// If the instruction is a branch, IsBranch is true; otherwise false.
// Returns true if an operand was successfully added, false otherwise.
bool MCExternalSymbolizer::tryAddingSymbolicOperand(
    MCInst &inst,
    raw_ostream &commentStream,
    int64_t immVal,
    uint64_t instrAddr,
    bool IsBranch,
    uint64_t byteOffset,
    uint64_t opWidth,
    uint64_t instrLen) {

  struct LLVMOpInfo1 symInfo;
  std::memset(&symInfo, 0, sizeof(symInfo));
  symInfo.Value = immVal;

  // Try to get symbolic info via callback if available
  if (!GetOpInfo ||
      !GetOpInfo(DisInfo, instrAddr, byteOffset, opWidth, instrLen, 1, &symInfo)) {
    // Reset symInfo fields after failed GetOpInfo call
    std::memset(&symInfo, 0, sizeof(symInfo));

    // Fallback: use SymbolLookUp only if appropriate
    if (!SymbolLookUp || (opWidth == 1 && !IsBranch))
      return false;

    uint64_t refType;
    if (IsBranch)
      refType = LLVMDisassembler_ReferenceType_In_Branch;
    else
      refType = LLVMDisassembler_ReferenceType_InOut_None;

    const char *refName = nullptr;
    const char *symbolName = SymbolLookUp(DisInfo, immVal, &refType, instrAddr, &refName);

    if (symbolName) {
      symInfo.AddSymbol.Name = symbolName;
      symInfo.AddSymbol.Present = true;
      if (refType == LLVMDisassembler_ReferenceType_DeMangled_Name)
        commentStream << refName;
    } else if (IsBranch) {
      symInfo.Value = immVal;
    }

    // Print special reference types as comments
    if (refType == LLVMDisassembler_ReferenceType_Out_SymbolStub)
      commentStream << "symbol stub for: " << refName;
    else if (refType == LLVMDisassembler_ReferenceType_Out_Objc_Message)
      commentStream << "Objc message: " << refName;

    if (!symbolName && !IsBranch)
      return false;
  }

  const MCExpr *leftPart = nullptr;
  if (symInfo.AddSymbol.Present) {
    if (symInfo.AddSymbol.Name) {
      StringRef name(symInfo.AddSymbol.Name);
      MCSymbol *sym = Ctx.getOrCreateSymbol(name);
      leftPart = MCSymbolRefExpr::create(sym, Ctx);
    } else {
      leftPart = MCConstantExpr::create(static_cast<int>(symInfo.AddSymbol.Value), Ctx);
    }
  }

  const MCExpr *rightPart = nullptr;
  if (symInfo.SubtractSymbol.Present) {
    if (symInfo.SubtractSymbol.Name) {
      StringRef name(symInfo.SubtractSymbol.Name);
      MCSymbol *sym = Ctx.getOrCreateSymbol(name);
      rightPart = MCSymbolRefExpr::create(sym, Ctx);
    } else {
      rightPart = MCConstantExpr::create(static_cast<int>(symInfo.SubtractSymbol.Value), Ctx);
    }
  }

  const MCExpr *offsetExpr = nullptr;
  if (symInfo.Value != 0)
    offsetExpr = MCConstantExpr::create(symInfo.Value, Ctx);

  const MCExpr *finalExpr = nullptr;

  if (rightPart) {
    const MCExpr *lhs;
    if (leftPart)
      lhs = MCBinaryExpr::createSub(leftPart, rightPart, Ctx);
    else
      lhs = MCUnaryExpr::createMinus(rightPart, Ctx);
    if (offsetExpr)
      finalExpr = MCBinaryExpr::createAdd(lhs, offsetExpr, Ctx);
    else
      finalExpr = lhs;
  } else if (leftPart) {
    if (offsetExpr)
      finalExpr = MCBinaryExpr::createAdd(leftPart, offsetExpr, Ctx);
    else
      finalExpr = leftPart;
  } else {
    finalExpr = offsetExpr ? offsetExpr : MCConstantExpr::create(0, Ctx);
  }

  finalExpr = RelInfo->createExprForCAPIVariantKind(finalExpr, symInfo.VariantKind);
  if (!finalExpr)
    return false;

  inst.addOperand(MCOperand::createExpr(finalExpr));
  return true;
}

// Adds comments for PC-relative loads referencing literal pool entries or Objective-C constructs.
void MCExternalSymbolizer::tryAddingPcLoadReferenceComment(raw_ostream &commentStream,
                                                           int64_t value,
                                                           uint64_t instrAddr) {
  if (!SymbolLookUp) return;

  uint64_t refType = LLVMDisassembler_ReferenceType_In_PCrel_Load;
  const char *refName = nullptr;
  (void)SymbolLookUp(DisInfo, value, &refType, instrAddr, &refName);

  switch (refType) {
    case LLVMDisassembler_ReferenceType_Out_LitPool_SymAddr:
      commentStream << "literal pool symbol address: " << refName;
      break;
    case LLVMDisassembler_ReferenceType_Out_LitPool_CstrAddr:
      commentStream << "literal pool for: \"";
      commentStream.write_escaped(refName);
      commentStream << "\"";
      break;
    case LLVMDisassembler_ReferenceType_Out_Objc_CFString_Ref:
      commentStream << "Objc cfstring ref: @\"" << refName << "\"";
      break;
    case LLVMDisassembler_ReferenceType_Out_Objc_Message:
      commentStream << "Objc message: " << refName;
      break;
    case LLVMDisassembler_ReferenceType_Out_Objc_Message_Ref:
      commentStream << "Objc message ref: " << refName;
      break;
    case LLVMDisassembler_ReferenceType_Out_Objc_Selector_Ref:
      commentStream << "Objc selector ref: " << refName;
      break;
    case LLVMDisassembler_ReferenceType_Out_Objc_Class_Ref:
      commentStream << "Objc class ref: " << refName;
      break;
    default:
      break;
  }
}

namespace llvm {
MCSymbolizer *createMCSymbolizer(const Triple &TT, LLVMOpInfoCallback GetOpInfo,
                                 LLVMSymbolLookupCallback SymbolLookUp,
                                 void *DisInfo, MCContext *Ctx,
                                 std::unique_ptr<MCRelocationInfo> &&RelInfo) {
  assert(Ctx && "No MCContext provided for symbolic disassembly");
  return new MCExternalSymbolizer(*Ctx, std::move(RelInfo), GetOpInfo,
                                  SymbolLookUp, DisInfo);
}
}

