void run_kernel(const volatile struct RuntimeParams* params)
{
#ifdef RUNTIME_FORMATS
    const volatile FormatConfig& fmts = params->formats;
#endif

    // Set up unpacker for Float16_b format
    _llk_unpack_hw_configure_<is_fp32_dest_acc_en>(
        fmts.unpack_A_src, fmts.unpack_B_src, fmts.unpack_A_dst, fmts.unpack_B_dst,
        FACE_R_DIM, FACE_R_DIM, 4U /* num_faces */, 4U /* num_faces */);

    _llk_unpack_A_init_<BroadcastType::NONE, false, EltwiseBinaryReuseDestType::NONE, unpack_to_dest>(
        0U, 0U, FACE_R_DIM, 4U, fmts.unpack_A_src, fmts.unpack_A_dst);

    // Load each tile into register A via unpacker
    std::uint32_t tile_idx = 0U;
    while (tile_idx < params->TILE_CNT)
    {
        _llk_unpack_A_<BroadcastType::NONE, false, EltwiseBinaryReuseDestType::NONE, unpack_to_dest>(
            L1_ADDRESS(params->buffer_A[tile_idx]), fmts.unpack_A_src, fmts.unpack_A_dst);
        ++tile_idx;
    }
}
