using namespace ckernel;
using namespace ckernel::sfpu;

void run_kernel(const volatile struct RuntimeParams* params)
{
#ifdef RUNTIME_FORMATS
    const volatile FormatConfig& fmts = params->formats;
#endif

    // Initialize data copy from source A to destination
#ifdef ARCH_BLACKHOLE
    _llk_math_eltwise_unary_datacopy_init_<DataCopyType::A2D, is_fp32_dest_acc_en, BroadcastType::NONE, false, false>(4U, fmts.math);
#else
    _llk_math_eltwise_unary_datacopy_init_<DataCopyType::A2D, is_fp32_dest_acc_en, BroadcastType::NONE, false>(4U, fmts.math);
#endif

    _llk_math_pack_sync_init_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
    _llk_math_hw_configure_<is_fp32_dest_acc_en>(fmts.math, fmts.math);

    // Block until destination buffer region is ready
    _llk_math_wait_for_dest_available_<DstSync::SyncHalf>();

    // Process all tiles
    for (std::uint32_t idx = 0U; idx < params->TILE_CNT; ++idx)
    {
        LLK_ASSERT(
            idx < get_dest_max_tiles<DstSync::SyncHalf, is_fp32_dest_acc_en, DstTileShape::Tile32x32>(),
            "Block tile index exceeds maximum destination capacity");

        _llk_math_eltwise_unary_datacopy_<DataCopyType::A2D, DstSync::SyncHalf, is_fp32_dest_acc_en, BroadcastType::NONE, unpack_to_dest>(
            idx, fmts.math, fmts.math);
    }

    _llk_math_dest_section_done_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
}
#endif

#include "llk_math_eltwise_unary_sfpu.h"

#ifdef LLK_TRISC_PACK
#include "ckernel_sfpu_reduce_custom.h"
#include "llk_pack.h"
#include "llk_pack_common.h"
#include "params.h"

void run_kernel(const volatile struct RuntimeParams* params)
{
#ifdef RUNTIME_FORMATS
    const volatile FormatConfig& fmts = params->formats;
#endif

    // Configure packer hardware
#ifdef ARCH_BLACKHOLE
    _llk_pack_hw_configure_<is_fp32_dest_acc_en, false, false>(fmts.pack_src, fmts.pack_dst, 16U * 16U * 4U);
#else
    _llk_pack_hw_configure_<is_fp32_dest_acc_en, false>(fmts.pack_src, fmts.pack_dst, 16U * 16U * 4U);
#endif

    _llk_pack_init_<false, false>(fmts.pack_dst);

    // Prepare destination for packing
#ifdef ARCH_BLACKHOLE
    _llk_pack_dest_init_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
#else
    _llk_pack_dest_init_<DstSync::SyncHalf, false, false>();
#endif

    _llk_packer_wait_for_math_done_();

    // SFPU reduce setup
    _llk_math_eltwise_unary_sfpu_init_<SfpuType::reduce>();
    ckernel::sfpu::_init_reduce_max_col_subblock_4x2_<DataFormat::Float16_b>();
    _llk_math_eltwise_unary_sfpu_start_<DstSync::SyncHalf>(0U);
    ckernel::sfpu::_reduce_max_col_subblock_4x2_prologue_();
    ckernel::sfpu::_calculate_reduce_max_col_subblock_4x2_<PoolType::MAX, REDUCE_COL, DataFormat::Float16_b>(BLOCK_RT_DIM);
    ckernel::sfpu::_reduce_max_col_subblock_4x2_epilogue_();
    _llk_math_eltwise_unary_sfpu_done_();

    // Pack results back to L1 memory
    std::uint32_t tile_counter = 0U;
    while (tile_counter < params->TILE_CNT)
    {
        LLK_ASSERT(
            tile_counter < get_dest_max_tiles<DstSync::SyncHalf, is_fp32_dest_acc_en, DstTileShape::Tile32x32>(),
            "Block tile index exceeds maximum destination capacity");

        _llk_pack_<DstSync::SyncHalf, is_fp32_dest_acc_en, false>(
            tile_counter, L1_ADDRESS(params->buffer_Res[tile_counter]));
        ++tile_counter;
    }

    _llk_pack_dest_section_done_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
}
#endif

