PubAckPacket::PubAckPacket(ParsingInformation* parsingInfo, OnPubAckInternalCallback callbackHandler)
: _parsingInformation(parsingInfo)
, _callback(callbackHandler)
, _currentByteIndex(0)
, _packetIdHighByte(0)
, _packetIdValue(0) {
}

PubAckPacket::~PubAckPacket() {
}

void PubAckPacket::parseVariableHeader(char* buffer, size_t size, size_t* byteCounter) {
  char currentByte = buffer[(*byteCounter)++];

  if (_currentByteIndex++ == 0) {
    _packetIdHighByte = currentByte;
  } else {
    _packetIdValue = static_cast<uint16_t>(currentByte | (_packetIdHighByte << 8));
    _parsingInformation->bufferState = BufferState::NONE;
    _callback(_packetIdValue);
  }
}

