#include <fstream>
#include <iostream>
#include <omp.h>
#include <vector>
#include <algorithm>
#include "bench_utils.h"
#include "superkmeans/common.h"
#include "superkmeans/hierarchical_superkmeans.h"
#include "superkmeans/superkmeans.h"

int main(int argc, char* argv[]) {
    // Determine dataset name from command line or default to "yahoo"
    std::string input_dataset = (argc > 1) ? std::string(argv[1]) : "yahoo";

    auto param_it = bench_utils::DATASET_PARAMS.find(input_dataset);
    if (param_it == bench_utils::DATASET_PARAMS.end()) {
        std::cerr << "Error: Unknown dataset '" << input_dataset << "'\n";
        return EXIT_FAILURE;
    }

    const size_t sample_count = param_it->second.first;
    const size_t feature_dim  = param_it->second.second;
    const size_t cluster_count = 40000U; // Fixed number of clusters

    int max_iterations = 5;
    float subsample_ratio = 1.0f;

    const std::string data_path = bench_utils::get_data_path(input_dataset);
    const unsigned int num_threads = static_cast<unsigned int>(omp_get_max_threads());
    omp_set_num_threads(num_threads);

    std::cout << "=== Assign Benchmark ===" << std::endl;
    std::cout << "Dataset: " << input_dataset 
              << " (samples=" << sample_count 
              << ", features=" << feature_dim << ")\n";
    std::cout << "Clusters=" << cluster_count 
              << ", iterations=" << max_iterations 
              << ", sampling ratio=" << subsample_ratio << "\n";

    std::vector<float> dataset_points;
    try {
        dataset_points.resize(sample_count * feature_dim);
    } catch (const std::bad_alloc& ex) {
        std::cerr << "Memory allocation failed for " 
                  << (sample_count * feature_dim) << " floats: " << ex.what() << "\n";
        return EXIT_FAILURE;
    }

    std::ifstream input_stream(data_path, std::ios::binary);
    if (!input_stream) {
        std::cerr << "Unable to open file: " << data_path << "\n";
        return EXIT_FAILURE;
    }
    input_stream.read(reinterpret_cast<char*>(dataset_points.data()),
                      sample_count * feature_dim * sizeof(float));
    input_stream.close();

    // Configure hierarchical k-means
    skmeans::HierarchicalSuperKMeansConfig setup;
    setup.iters_mesoclustering = 3;
    setup.iters_fineclustering = 5;
    setup.iters_refinement     = 0;
    setup.verbose              = false;
    setup.n_threads            = num_threads;
    setup.unrotate_centroids   = true;
    setup.early_termination    = false;
    setup.sampling_fraction    = subsample_ratio;
    setup.use_blas_only        = false;

    bool is_spherical = std::find(
        bench_utils::ANGULAR_DATASETS.begin(),
        bench_utils::ANGULAR_DATASETS.end(),
        input_dataset
    ) != bench_utils::ANGULAR_DATASETS.end();

    if (is_spherical) {
        std::cout << "Using spherical (angular) distance metric\n";
        setup.angular = true;
    }

    skmeans::HierarchicalSuperKMeans<
        skmeans::Quantization::f32,
        skmeans::DistanceFunction::l2
    > model(cluster_count, feature_dim, setup);

    // Train the model
    bench_utils::TicToc train_timer;
    train_timer.Tic();
    auto cluster_centers = model.Train(dataset_points.data(), sample_count);
    train_timer.Toc();
    std::cout << "\nTraining finished in " << train_timer.GetMilliseconds() << " ms\n";

    // Fast assignment path (optimized)
    bench_utils::TicToc fast_timer;
    fast_timer.Tic();
    auto fast_assignments = model.FastAssign(
        dataset_points.data(), cluster_centers.data(), sample_count, cluster_count
    );
    fast_timer.Toc();
    double fast_duration = fast_timer.GetMilliseconds();
    std::cout << "\nFastAssign time: " << fast_duration << " ms\n";

    // Brute-force assignment path (reference)
    bench_utils::TicToc brute_timer;
    brute_timer.Tic();
    auto brute_assignments = model.Assign(
        dataset_points.data(), cluster_centers.data(), sample_count, cluster_count
    );
    brute_timer.Toc();
    double brute_duration = brute_timer.GetMilliseconds();
    std::cout << "BruteAssign time: " << brute_duration << " ms\n";

    // Compare assignments
    double speed_ratio = brute_duration / fast_duration;
    size_t agreement_count = 0;
    for (size_t idx = 0; idx < sample_count; ++idx) {
        if (fast_assignments[idx] == brute_assignments[idx]) {
            ++agreement_count;
        }
    }

    double match_rate = 100.0 * static_cast<double>(agreement_count) / static_cast<double>(sample_count);
    std::cout << "\nSpeedup: " << speed_ratio << "x\n";
    std::cout << "Cluster assignment agreement: " 
              << match_rate << "% (" << agreement_count << "/" << sample_count << ")\n";

    return EXIT_SUCCESS;
}

#include <execinfo.h>
