namespace Gorgon::Utils {

    namespace {
        // Helper function to extract and demangle symbol name from backtrace message
        std::string ExtractFunctionName(const std::string& msg) {
            size_t parenStart = msg.find('(');
            if (parenStart == std::string::npos) return "";

            size_t plusOrParenEnd = msg.find_first_of("+)", parenStart + 1);
            if (plusOrParenEnd == std::string::npos) return "";

            std::string mangled = msg.substr(parenStart + 1, plusOrParenEnd - parenStart - 1);
            return demangle(mangled).empty() ? mangled : demangle(mangled);
        }

        // Helper to parse addr2line output: filename:linenum [optional column]
        void ParseAddr2LineOutput(const std::string& raw, std::string& file, int& line) {
            size_t colonPos = raw.find(':');
            if (colonPos == std::string::npos || colonPos == 0) {
                file = "";
                line = 0;
                return;
            }

            file = raw.substr(0, colonPos);
            size_t spacePos = raw.find(' ', colonPos + 1);
            std::string numPart = (spacePos == std::string::npos)
                                  ? raw.substr(colonPos + 1)
                                  : raw.substr(colonPos + 1, spacePos - colonPos - 1);

            try {
                line = String::To<int>(numPart);
            } catch (...) {
                line = 0;
            }
        }

        // Perform actual reporting for one stack frame
        void ReportFrame(int index, void* addr, Console& console, const std::string& funcName) {
            int pipefd[2];
            if (pipe(pipefd) != 0) return;

            pid_t child = fork();
            if (child < 0) {
                return; // fork failed
            }

            if (child > 0) {
                // Parent process
                close(pipefd[1]);

                char buffer[1024];
                ssize_t bytesRead = read(pipefd[0], buffer, sizeof(buffer) - 1);
                close(pipefd[0]);

                if (bytesRead <= 0) {
                    wait(nullptr);
                    return;
                }
                buffer[bytesRead] = '\0';
                std::string output(buffer);

                std::string filename;
                int lineno = 0;
                ParseAddr2LineOutput(output, filename, lineno);

                // Normalize path components
                std::string dirPath;
                try {
                    dirPath = Filesystem::Canonical(filename);
                } catch (...) {
                    dirPath = filename;
                }

                std::string directory = Filesystem::GetDirectory(dirPath);
                if (!directory.empty() && directory.back() == '/') {
                    directory.pop_back();
                }
                std::string shortDir = Filesystem::GetFilename(directory);
                std::string shortFile = Filesystem::GetFilename(filename);

                // Print stack frame info
                console.SetColor(Console::Magenta);
                if ((index - 2) == 1) {
                    console.SetBold(true);
                }
                std::cout << "  [" << (index - 2) << "] ";
                console.SetBold(false);
                console.SetColor(Console::Default);

                if (!funcName.empty()) {
                    std::cout << "In function ";
                    console.SetColor(Console::Yellow);
                    std::cout << funcName << " ";
                }
                console.SetColor(Console::Default);
                std::cout << "at ";

                if ((index - 2) == 1) {
                    console.SetColor(Console::Red);
                }
                std::cout << "..." << shortDir << "/" << shortFile;
                console.SetBold(true);
                std::cout << ":" << lineno << std::endl;
                console.Reset();

                wait(nullptr);
            } else {
                // Child process
                close(pipefd[0]);
                dup2(pipefd[1], STDOUT_FILENO);
                dup2(pipefd[1], STDERR_FILENO);
                close(pipefd[1]);

                char addrStr[32];
                snprintf(addrStr, sizeof(addrStr), "%p", addr);

                execlp("addr2line", "addr2line", addrStr, "-e", Filesystem::ExePath().c_str(), nullptr);

                perror("addr2line not found or failed");
                _exit(EXIT_FAILURE);
            }
        }
    }

    void CrashHandler::Backtrace() {
        // Allocate trace buffer
        int totalSlots = depth + skip + 2;
        void** traceBuffer = static_cast<void**>(malloc(totalSlots * sizeof(void*)));
        if (!traceBuffer) return;

        int actualTraced = backtrace(traceBuffer, totalSlots);

        // Get symbolic info
        char** symbols = backtrace_symbols(traceBuffer, actualTraced);
        if (!symbols) {
            free(traceBuffer);
            return;
        }

        Console console;

        // Process frames: skip top frames as per 'skip'
#ifdef TEST
        for (int idx = 2; idx < skip + 2; ++idx) {
            if (idx >= actualTraced) break;
            std::string funcName = ExtractFunctionName(symbols[idx]);
            ReportFrame(idx, traceBuffer[idx], console, funcName);
        }
#endif

        for (int idx = skip + 2; idx < actualTraced; ++idx) {
            std::string funcName = ExtractFunctionName(symbols[idx]);
            ReportFrame(idx, traceBuffer[idx], console, funcName);
        }

        free(traceBuffer);
        free(symbols);
    }

}

