#   define getpid GetCurrentProcessId
#endif
#include "flow2d3d.h"
//------------------------------------------------------------------------------
#define MAGIC_NUMBER   310967156       // random number used for validation
enum MessageType {                    // message type enumeration
    MSG_HELLO = 9430,
    MSG_INIT,
    MSG_JOIN_LOCAL,
    MSG_JOIN_GLOBAL,
    MSG_DONE,
    MSG_DONE_ACK
};
struct NodeControlPacket {
    int         magic;                // sanity check value
    MessageType type;
    int         nodeId;               // ID of slave node
    int         totalNodes;
};
struct JoinExchangeData {
    int         magic;                // sanity check value
    MessageType type;
    int         joinCount;            // global count of joins
    struct {
        char        streamId [Stream::MAXHANDLE]; // lead stream identity string
    } entry [DD::MAXJOINS];
};
//------------------------------------------------------------------------------
static void
handleMasterStreamFailure (
    const char * msg
    ) {
    throw new Exception("MASTER Stream ERROR: %s", msg);
}
static void
handleSlaveStreamFailure (
    const char * msg
    ) {
    throw new Exception("SLAVE Stream ERROR: %s", msg);
}
static void
handleJoinStreamFailure (
    const char * msg
    ) {
    throw new Exception("Inter-iterator Stream ERROR: %s", msg);
}
static void
logMasterStreamEvent (
    const char * info
    ) {
    FLOW2D3D->log->Write (Log::DD_SENDRECV, "DD master stream: %s", info);
}
static void
logSlaveStreamEvent (
    const char * info
    ) {
    FLOW2D3D->log->Write (Log::DD_SENDRECV, "DD slave stream: %s", info);
}
static void
logJoinStreamEvent (
    const char * info
    ) {
    FLOW2D3D->log->Write (Log::DD_SENDRECV, "DD inter-iterator stream: %s", info);
}
//------------------------------------------------------------------------------
void
DD::MasterProcess (
    void
    ) {
#if defined (WIN32)
    throw new Exception("Remote execution is not supported on Microsoft Windows");
#else
    const char * hostPid = GetHostnamePID();
    char threadLabel [strlen(hostPid) + 100];
    snprintf(threadLabel, sizeof(threadLabel), "%s master", hostPid);
    this->log->RegisterThread(threadLabel);
    delete [] hostPid;

    this->log->Write(Log::ALWAYS, "Distributed DD master process started");

    const char * mainArgs = this->flow->DH->mainArgs;
    const char * exePath  = this->flow->DH->exePath;
    const char * remoteShellCmd = this->multiNode->GetAttrib("remoteShellCommand");
    if (remoteShellCmd == nullptr)
        remoteShellCmd = "ssh -n";

    const char * pwd = getenv("PWD");
    const char * libPath = getenv("LD_LIBRARY_PATH");
    if (libPath == nullptr) libPath = "";

    // Start slave processes on remote nodes
    int idx = 0;
    while (idx < this->nodeSet->numNodes) {
        Node * targetNode = this->nodeSet->node[idx];
        targetNode->stream = new Stream(Stream::TCPIP, &handleMasterStreamFailure, &logMasterStreamEvent);
        char * localHandle = targetNode->stream->LocalHandle();

        int maxLen = 10000;
        char remoteCmd[maxLen];
        int written = snprintf(remoteCmd, maxLen,
                    "%s %s 'cd %s; export LD_LIBRARY_PATH=%s; ulimit -c unlimited; %s -S %s %s' < /dev/null",
                        remoteShellCmd,
                        targetNode->hostname,
                        pwd,
                        libPath,
                        exePath,
                        localHandle,
                        mainArgs
                        );
        if (written >= maxLen)
            throw new Exception("Internal error: Remote command line too long in MasterProcess!");

        this->log->Write(Log::MAJOR, "Master spawning node %d slave process on \"%s\"", idx, targetNode->hostname);
        this->log->Write(Log::CONFIG_MINOR, "Master process executing shell command \"%s\"", remoteCmd);

        targetNode->remotePID = fork();
        if (targetNode->remotePID == 0) {
            if (system(remoteCmd) == 0)
                exit(0);
            else {
                this->log->Write(Log::ALWAYS, "Trouble running \"%s\"", remoteCmd);
                exit(1);
            }
        }
        ++idx;
    }

    // Ensure all slaves are actually running
    sleep(1);
    int verifyIdx = 0;
    while (verifyIdx < this->nodeSet->numNodes) {
        Node * node = this->nodeSet->node[verifyIdx];
        int status;
        int rc = waitpid(node->remotePID, &status, WNOHANG);
        if (rc != 0 && WIFEXITED(status))
            throw new Exception("Slave process for node %d on \"%s\" has exited prematurely", verifyIdx, node->hostname);
        ++verifyIdx;
    }

    // Wait for HELLO messages indicating readiness
    int helloIdx = 0;
    while (helloIdx < this->nodeSet->numNodes) {
        Node * node = this->nodeSet->node[helloIdx];
        this->log->Write(Log::MAJOR, "Master connecting to node %d", helloIdx);
        node->stream->Connect();
        NodeControlPacket pkt;
        node->stream->Receive((char*)&pkt, sizeof(pkt));
        if (pkt.magic != MAGIC_NUMBER)
            throw new Exception("Got malformed message from slave %d", helloIdx);
        if (pkt.type != MSG_HELLO)
            throw new Exception("Expected HELLO message from slave %d but got something else", helloIdx);
        this->log->Write(Log::MAJOR, "Master got HELLO message from node %d", helloIdx);
        ++helloIdx;
    }

    // Send each slave an initial message with its node ID
    int initIdx = 0;
    while (initIdx < this->nodeSet->numNodes) {
        Node * node = this->nodeSet->node[initIdx];
        NodeControlPacket pkt;
        pkt.magic = MAGIC_NUMBER;
        pkt.type = MSG_INIT;
        pkt.nodeId = initIdx;
        this->log->Write(Log::MINOR, "Master sending INITIAL message to node %d", initIdx);
        node->stream->Send((char*)&pkt, sizeof(pkt));
        ++initIdx;
    }

    // Collect JOIN_LOCAL messages and merge into global table
    JoinExchangeData globalJoin;
    globalJoin.joinCount = -1;
    int jdx = 0;
    while (jdx < DD::MAXJOINS) {
        globalJoin.entry[jdx].streamId[0] = '\0';
        ++jdx;
    }

    int collectIdx = 0;
    while (collectIdx < this->nodeSet->numNodes) {
        Node * node = this->nodeSet->node[collectIdx];
        JoinExchangeData localJoin;
        this->log->Write(Log::MAJOR, "Master waiting for JOIN_LOCAL message from node %d", collectIdx);
        node->stream->Receive((char*)&localJoin, sizeof(localJoin));
        if (localJoin.magic != MAGIC_NUMBER)
            throw new Exception("Got malformed message from slave %d", collectIdx);
        if (localJoin.type != MSG_JOIN_LOCAL)
            throw new Exception("Expected JOIN_LOCAL message from slave %d but got something else", collectIdx);
        this->log->Write(Log::MAJOR, "Master got JOIN_LOCAL message from node %d", collectIdx);

        if (globalJoin.joinCount < 0)
            globalJoin.joinCount = localJoin.joinCount;
        else if (globalJoin.joinCount != localJoin.joinCount)
            throw new Exception("Inconsistent numJoins values JOIN_LOCAL messages (%d != %d)", globalJoin.joinCount, localJoin.joinCount);

        int kdx = 0;
        while (kdx < globalJoin.joinCount) {
            if (localJoin.entry[kdx].streamId[0] != '\0')
                strcpy(globalJoin.entry[kdx].streamId, localJoin.entry[kdx].streamId);
            ++kdx;
        }
        ++collectIdx;
    }

    globalJoin.magic = MAGIC_NUMBER;
    globalJoin.type = MSG_JOIN_GLOBAL;

    int sendIdx = 0;
    while (sendIdx < this->nodeSet->numNodes) {
        Node * node = this->nodeSet->node[sendIdx];
        this->log->Write(Log::MAJOR, "Master sending JOIN_GLOAL message to node %d", sendIdx);
        node->stream->Send((char*)&globalJoin, sizeof(globalJoin));
        ++sendIdx;
    }

    // Wait for all slaves to terminate
    this->log->Write(Log::ALWAYS, "Master process has done its work and waiting for all slaves to terminate");

    int termIdx = 0;
    while (termIdx < this->nodeSet->numNodes) {
        Node * node = this->nodeSet->node[termIdx];
        pid_t pid = waitpid(node->remotePID, NULL, 0);
        if (pid != node->remotePID)
            throw new Exception("Internal error: Unexpected return value from waitpid in MasterProces!");
        delete node->stream;
        node->stream = nullptr;
        ++termIdx;
    }

    this->log->Write(Log::ALWAYS, "Master process has seen that all slaves have terminated, and is terminating");
#endif
}
//------------------------------------------------------------------------------
static void *   leader_thread_func       (void *);
static void *   follower_thread_func     (void *);
void
DD::SlaveProcess (
    void
    ) {
#if defined (WIN32)
    throw new Exception("Remote execution is not supported on Microsoft Windows");
#else
    char * hostPid = GetHostnamePID();
    char threadLabel[strlen(hostPid) + 100];
    snprintf(threadLabel, sizeof(threadLabel), "%s slave", hostPid);
    this->log->RegisterThread(threadLabel);

    // Connect to master and send HELLO message
    this->log->Write(Log::ALWAYS, "Slave process connecting to master on \"%s\" and sending HELLO", this->flow->DH->slaveArg);
    Stream * masterLink = new Stream(Stream::TCPIP, this->flow->DH->slaveArg, &handleSlaveStreamFailure, &logSlaveStreamEvent);
    NodeControlPacket pkt;
    pkt.magic = MAGIC_NUMBER;
    pkt.type = MSG_HELLO;
    masterLink->Send((char*)&pkt, sizeof(pkt));

    // Wait for INITIAL message with my node ID
    this->log->Write(Log::MAJOR, "Slave sent HELLO, now waiting for INITIAL message");
    masterLink->Receive((char*)&pkt, sizeof(pkt));
    if (pkt.magic != MAGIC_NUMBER)
        throw new Exception("Got malformed message from master");
    if (pkt.type != MSG_INIT)
        throw new Exception("Expected INITIAL message from master but got something else");
    this->nodeID = pkt.nodeId;

    snprintf(threadLabel, sizeof(threadLabel), "%s slave:%d", hostPid, this->nodeID);
    this->log->RenameThread(threadLabel);
    this->log->Write(Log::MAJOR, "Slave got INITIAL message");
    delete [] hostPid;

    this->role = ROLE_SLAVE;
    this->CreateFixedEntities();
    this->ReadConfig();

    // Setup minimum barrier iterator
    this->minbarCat = new Category(this, DD::minBarCategoryName);
    this->minbar = new Iterator(this, DD::minBarCategoryName, nullptr, this->minbarCat, &MinimumBarrier_Function);
    this->minbar->Place(this->nodeSet->node[0]);
    this->minbar->Detach();

    this->mapperList->Rewind();
    Iterator * mapper;
    while ((mapper = (Iterator *) this->mapperList->Next()) != nullptr)
        this->JoinIterators(mapper, this->minbar);

    // Determine join types: local, semi-remote, or remote
    JoinExchangeData exchangeTable;
    exchangeTable.magic = MAGIC_NUMBER;
    exchangeTable.type = MSG_JOIN_LOCAL;
    exchangeTable.joinCount = this->numJoins;
    int eidx = 0;
    while (eidx < DD::MAXJOINS) {
        exchangeTable.entry[eidx].streamId[0] = '\0';
        ++eidx;
    }

    int jid = 0;
    while (jid < this->numJoins) {
        Iterator * iter1 = this->iterator[this->join[jid].iter1].iterator;
        Iterator * iter2 = this->iterator[this->join[jid].iter2].iterator;

        if (iter1->node->nodeID == this->nodeID) {
            if (iter2->node->nodeID == this->nodeID)
                this->join[jid].local = true;
            else {
                if ((this->log->GetMask() & Log::DD_SENDRECV) == 0)
                    this->join[jid].stream = new Stream(Stream::TCPIP, &handleJoinStreamFailure);
                else
                    this->join[jid].stream = new Stream(Stream::TCPIP, &handleJoinStreamFailure, &logJoinStreamEvent);
                strcpy(exchangeTable.entry[jid].streamId, this->join[jid].stream->LocalHandle());
                this->join[jid].leader = true;
                this->log->Write(Log::CONFIG_MINOR, "Slave leading join %d; handle is \"%s\"", jid, exchangeTable.entry[jid].streamId);
            }
        } else if (iter2->node->nodeID == this->nodeID) {
            this->join[jid].follower = true;
        }
        ++jid;
    }

    // Send local join table to master
    masterLink->Send((char*)&exchangeTable, sizeof(exchangeTable));
    this->log->Write(Log::MAJOR, "Slave sent local joing exchange table; waiting for global union");

    memset(&exchangeTable, 0, sizeof(exchangeTable));
    masterLink->Receive((char*)&exchangeTable, sizeof(exchangeTable));
    if (exchangeTable.magic != MAGIC_NUMBER)
        throw new Exception("Got malformed message from master");
    if (exchangeTable.type != MSG_JOIN_GLOBAL)
        throw new Exception("Expected JOIN_GLOBAL message from master but got something else");
    if (exchangeTable.joinCount != this->numJoins)
        throw new Exception("Inconsistent numJoins value JOIN_GLOBAL message");
    delete masterLink;

    // Launch helper threads for joins
    this->leadFollowSync = new Semaphore("leadFollow", 0, this->log);
    int tidx = 0;
    while (tidx < this->numJoins) {
        if (this->join[tidx].leader) {
            if (pthread_create(&this->join[tidx].thid, nullptr, &leader_thread_func, (void*)(long)tidx) != 0)
                throw new Exception("Pthreads error: Cannot create leader thread %s", strerror(errno));
            this->leadFollowSync->PSem();
        }
        ++tidx;
    }

    tidx = 0;
    while (tidx < this->numJoins) {
        if (this->join[tidx].follower) {
            if (exchangeTable.entry[tidx].streamId[0] == '\0')
                throw new Exception("Slot %d in JOIN_GLOBAL message is empty", tidx);
            strcpy(this->join[tidx].handle, exchangeTable.entry[tidx].streamId);
            if (pthread_create(&this->join[tidx].thid, nullptr, &follower_thread_func, (void*)(long)tidx) != 0)
                throw new Exception("Pthreads error: Cannot create follower thread %s", strerror(errno));
        }
        ++tidx;
    }

    // Wait for all threads to finish
    delete this->leadFollowSync;
    this->leadFollowSync = nullptr;

    int joinIdx = 0;
    while (joinIdx < this->numJoins) {
        if (this->join[joinIdx].leader || this->join[joinIdx].follower) {
            this->log->Write(Log::CONFIG_MINOR, "Waiting for termination of join %d %s thread", joinIdx,
                             this->join[joinIdx].leader ? "leader" : "follower");
            if (pthread_join(this->join[joinIdx].thid, nullptr) != 0)
                throw new Exception("Pthreads error: Cannot join with thread, errno=%d", errno);
        }
        ++joinIdx;
    }

    this->log->Write(Log::CONFIG_MINOR, "All slave join threads have terminated");

    // Build category and iterator lists
    this->categoryList = new List();
    int catIdx = 0;
    while (catIdx < this->numCategories) {
        this->categoryList->Append((void*)this->category[catIdx].category);
        ++catIdx;
    }

    this->iteratorList = new List();
    int iterIdx = 0;
    while (iterIdx < this->numIterators) {
        this->iteratorList->Append((void*)this->iterator[iterIdx].iterator);
        ++iterIdx;
    }

    this->PrintJoinTable();
    this->InitializeLocalMessageBuffers();
    this->StartLocalIteratorThreads();     // returns when all have invoked their Ready methods
    if (this->mappersOnThisNode > 0)
        SetupMinimumBarrier();
    this->RunSimulation();
    this->log->Write(Log::ALWAYS, "Slave is terminating");
#endif
}
//------------------------------------------------------------------------------
static void *
leader_thread_func (
    void * arg
    ) {
    int jid = ((long)arg);         // index in join table
    DD * dd = FLOW2D3D->dd;
    dd->log->Write(Log::CONFIG_MINOR, "Leader thread for join %d starting", jid);
    try {
        dd->leadFollowSync->VSem();
        dd->join[jid].stream->Connect();
    }
    catch (Exception * ex) {
        dd->log->Write(Log::ALWAYS, "Exception in leader thread for join %d: %s", jid, ex->message);
        exit(1);
    }
    dd->log->Write(Log::CONFIG_MINOR, "Leader thread for join %d terminating", jid);
    return nullptr;
}
static void *
follower_thread_func (
    void * arg
    ) {
    int jid = ((long)arg);         // index in join table
    DD * dd = FLOW2D3D->dd;
    dd->log->Write(Log::CONFIG_MINOR, "Follower thread for join %d starting; handle = \"%s\"", jid, dd->join[jid].handle);
    try {
        if ((dd->log->GetMask() & Log::DD_SENDRECV) == 0)
            dd->join[jid].stream = new Stream(Stream::TCPIP, dd->join[jid].handle, &handleJoinStreamFailure);
        else
            dd->join[jid].stream = new Stream(Stream::TCPIP, dd->join[jid].handle, &handleJoinStreamFailure, &logJoinStreamEvent);
    }
    catch (Exception * ex) {
        dd->log->Write(Log::ALWAYS, "Exception in follower thread for join %d: %s", jid, ex->message);
        exit(1);
    }
    dd->log->Write(Log::CONFIG_MINOR, "Follower thread for join %d terminating", jid);
    return nullptr;
}

#include "Enemy.h"
#include <Gorgon/Filesystem.h>
#include <Gorgon/Graphics/Bitmap.h>
#include <Gorgon/Graphics/TextureAnimation.h>

namespace Assets {

    // Load an asteroid variant by type index.
    // File naming convention: astroid1.png, astroid2.png, etc.
    // Since internal indexing starts at 0, we offset by +1 for filenames.
    void Astroid::Load(int idx) {
        this->type = idx;

        std::string basepath = "Resources/astroid" + std::to_string(idx + 1);

        // First, try to load as a static image (no frame suffix)
        if (Gorgon::Filesystem::IsFile(basepath + ".png")) {
            Gorgon::Graphics::Bitmap tempBmp;
            tempBmp.Import(basepath + ".png");
            tempBmp.Prepare();
            image.SetAnimation(std::move(tempBmp));
        }
        // Otherwise, assume multi-frame animation
        else {
            Gorgon::Graphics::BitmapAnimationProvider sequence;
            int frameIndex = 1;

            // Dynamically collect frames until a file is missing
            while (true) {
                std::string filepath = basepath + "_" + std::to_string(frameIndex) + ".png";
                if (!Gorgon::Filesystem::IsFile(filepath)) {
                    break; // no more frames
                }

                Gorgon::Graphics::Bitmap frameBmp;
                frameBmp.Import(filepath);
                sequence.Add(std::move(frameBmp), 250); // 250 ms per frame

                ++frameIndex;
            }

            sequence.Prepare();
            image.SetAnimation(std::move(sequence));
        }
    }

    // Upload the loaded asteroid image(s) to GPU
    void Astroid::Prepare() {
        auto &animObj = image.GetAnimation();

        if (auto *singleFrame = dynamic_cast<Gorgon::Graphics::Bitmap*>(&animObj)) {
            singleFrame->Prepare();
        } 
        else if (auto *animFrames = dynamic_cast<Gorgon::Graphics::BitmapAnimationProvider*>(&animObj)) {
            animFrames->Prepare();
        }
    }

    // Utility: load all known asteroid variants sequentially
    void Astroid::LoadAll() {
        for (int counter = 0; counter < types; ++counter) {
            astroids.AddNew().Load(counter);
        }
    }

    // Utility: prepare (upload) all previously loaded asteroid variants
    void Astroid::PrepareAll() {
        for (int i = 0; i < types; ++i) {
            astroids[i].Prepare();
        }
    }

    // Static member definition — allocates storage for the collection
    Gorgon::Containers::Collection<Astroid> Astroid::astroids;
}

