#include <algorithm>
#include <numeric>
#include "mlir/IR/IRMapping.h"
#include "mlir/Support/LLVM.h"
#include "triton/Dialect/Triton/IR/Dialect.h"
#include "triton/Dialect/TritonGPU/IR/Dialect.h"
#include "triton/Dialect/TritonGPU/Transforms/Utility.h"

using namespace mlir;
using namespace mlir::triton::gpu;

// Renamed class for clarity (semantically equivalent)
TritonGPUTypeConverter::TritonGPUTypeConverter(MLIRContext *ctx,
                                               int warpCount,
                                               int threadsPerWarp,
                                               int ctaCount)
    : context(ctx), numWarps(warpCount), threadsPerWarp(threadsPerWarp),
      numCTAs(ctaCount) {
  // Identity conversion for non-tensor types
  addConversion([](Type type) { return type; });

  // Tensor layout assignment: attach default blocked encoding if missing
  addConversion([this](RankedTensorType tensorType) -> RankedTensorType {
    if (tensorType.getEncoding())
      return tensorType;

    auto shape = tensorType.getShape();
    auto encoding = getDefaultBlockedEncoding(
        this->context, shape, this->numWarps, this->threadsPerWarp, this->numCTAs);
    return RankedTensorType::get(shape, tensorType.getElementType(), encoding);
  });

  // Pointer-to-tensor handling: propagate layout to pointee tensor type
  addConversion([this](triton::PointerType ptrType) -> triton::PointerType {
    auto pointeeType = ptrType.getPointeeType();
    auto tensorPtrTarget = dyn_cast<RankedTensorType>(pointeeType);
    if (!tensorPtrTarget)
      return ptrType;

    auto updatedTensorType = convertType(tensorPtrTarget);
    return triton::PointerType::get(updatedTensorType, ptrType.getAddressSpace());
  });

  //
  // Materialization hooks
  //

  // Argument materialization: not expected in this lowering path
  addArgumentMaterialization([&](OpBuilder &builder,
                                 RankedTensorType tensorType,
                                 ValueRange inputs,
                                 Location loc) -> std::optional<Value> {
    llvm_unreachable("Argument rematerialization should not occur during Triton → TritonGPU lowering");
    return std::nullopt;
  });

  // Source materialization: also disallowed here
  addSourceMaterialization([&](OpBuilder &builder,
                               RankedTensorType tensorType,
                               ValueRange inputs,
                               Location loc) -> std::optional<Value> {
    llvm_unreachable("Source rematerialization is unsupported in Triton → TritonGPU conversion");
    return std::nullopt;
  });

  // Target materialization: insert layout conversion when needed
  addTargetMaterialization([&](OpBuilder &builder,
                               RankedTensorType desiredType,
                               ValueRange operands,
                               Location loc) {
    auto convOp = builder.create<triton::gpu::ConvertLayoutOp>(
        loc, desiredType, operands);
    return std::optional<Value>(convOp.getResult());
  });
}

//
// Conversion target setup
//

TritonGPUConversionTarget::TritonGPUConversionTarget(
    MLIRContext &mlirCtx,
    TritonGPUTypeConverter &typeConv)
    : ConversionTarget(mlirCtx) {
  // Legal dialects
  addLegalDialect<triton::gpu::TritonGPUDialect>();

  // Explicitly illegal SCF ops (not supported in target dialect)
  addIllegalOp<scf::ExecuteRegionOp, scf::ParallelOp, scf::ReduceOp,
               scf::ReduceReturnOp>();

  // Dynamically legal check for core dialects
  addDynamicallyLegalDialect<arith::ArithDialect, math::MathDialect,
                             triton::TritonDialect, cf::ControlFlowDialect,
                             scf::SCFDialect>([&](Operation *op) {
    bool allRegionsLegal = true;
    for (auto &region : op->getRegions()) {
      allRegionsLegal &= typeConv.isLegal(&region);
    }
    return allRegionsLegal && typeConv.isLegal(op);
  });

  // Special handling for DotOp layout requirements
  addDynamicallyLegalOp<triton::DotOp>([](triton::DotOp dotOp) -> bool {
    auto AType = cast<RankedTensorType>(dotOp.getA().getType());
    auto BType = cast<RankedTensorType>(dotOp.getB().getType());

    auto AEnc = AType.getEncoding();
    auto BEnc = BType.getEncoding();

    bool hasDotOperandEncoding =
        AEnc && isa<triton::gpu::DotOperandEncodingAttr>(AEnc) &&
        BEnc && isa<triton::gpu::DotOperandEncodingAttr>(BEnc);

    return hasDotOperandEncoding;
  });
}

