    cin.tie(nullptr);

    int rows, cols;
    if (!(cin >> rows >> cols)) return 0;

    long long total = 1LL * rows * cols;

    int current_start = 1;
    for (int row = 0; row < cols; ++row) {
        cout << "!";

        long long num = current_start;
        while (num <= total) {
