// Renamed type alias for clarity
using BlockToRegMap = DenseMap<MachineBasicBlock *, Register>;

static BlockToRegMap &getStoredValues(void *storage) {
  return *static_cast<BlockToRegMap*>(storage);
}

MachineSSAUpdater::MachineSSAUpdater(MachineFunction &MF,
                                     SmallVectorImpl<MachineInstr*> *newPHIs)
  : InsertedPHIs(newPHIs), TII(MF.getSubtarget().getInstrInfo()),
    MRI(&MF.getRegInfo()) {}

MachineSSAUpdater::~MachineSSAUpdater() {
  delete static_cast<BlockToRegMap*>(AV);
}

void MachineSSAUpdater::Initialize(const TargetRegisterClass *RC) {
  if (!AV)
    AV = new BlockToRegMap();
  else
    getStoredValues(AV).clear();
  VRC = RC;
}

void MachineSSAUpdater::Initialize(Register reg) {
  Initialize(MRI->getRegClass(reg));
}

bool MachineSSAUpdater::HasValueForBlock(MachineBasicBlock *BB) const {
  return getStoredValues(AV).find(BB) != getStoredValues(AV).end();
}

void MachineSSAUpdater::AddAvailableValue(MachineBasicBlock *BB, Register reg) {
  getStoredValues(AV)[BB] = reg;
}

Register MachineSSAUpdater::GetValueAtEndOfBlock(MachineBasicBlock *BB) {
  return GetValueAtEndOfBlockInternal(BB);
}

// Helper: look for an existing PHI node in BB that matches the given predecessor values
static Register FindMatchingPHI(
    MachineBasicBlock *BB,
    SmallVectorImpl<std::pair<MachineBasicBlock *, Register>> &predValues) {
  if (BB->empty())
    return Register();

  auto iter = BB->begin();
  if (!iter->isPHI())
    return Register();

  BlockToRegMap cachedPreds;
  for (const auto &entry : predValues)
    cachedPreds[entry.first] = entry.second;

  while (iter != BB->end() && iter->isPHI()) {
    bool matchFound = true;
    for (unsigned idx = 1, end = iter->getNumOperands(); idx < end; idx += 2) {
      Register srcReg = iter->getOperand(idx).getReg();
      MachineBasicBlock *srcBB = iter->getOperand(idx + 1).getMBB();
      if (cachedPreds[srcBB] != srcReg) {
        matchFound = false;
        break;
      }
    }
    if (matchFound)
      return iter->getOperand(0).getReg();
    ++iter;
  }
  return Register();
}

// Helper: insert a new instruction defining a virtual register at position I in BB
static MachineInstrBuilder CreateNewDef(
    unsigned opcode,
    MachineBasicBlock *BB,
    MachineBasicBlock::iterator pos,
    const TargetRegisterClass *regClass,
    MachineRegisterInfo *regInfo,
    const TargetInstrInfo *tii) {
  Register newVR = regInfo->createVirtualRegister(regClass);
  return BuildMI(*BB, pos, DebugLoc(), tii->get(opcode), newVR);
}

// Main logic: get value live in middle of block (handles mid-block uses)
Register MachineSSAUpdater::GetValueInMiddleOfBlock(
    MachineBasicBlock *BB, bool onlyExisting) {
  // If no local definition exists, delegate to end-of-block logic
  if (!HasValueForBlock(BB))
    return GetValueAtEndOfBlockInternal(BB, onlyExisting);

  // Handle case with no predecessors
  if (BB->pred_empty()) {
    if (onlyExisting)
      return Register();
    MachineInstr *undefDef = CreateNewDef(
        TargetOpcode::IMPLICIT_DEF,
        BB, BB->getFirstTerminator(), VRC, MRI, TII);
    return undefDef->getOperand(0).getReg();
  }

  // Collect values from all predecessors
  SmallVector<std::pair<MachineBasicBlock*, Register>, 8> predValues;
  Register commonValue;
  bool first = true;

  for (MachineBasicBlock *pred : BB->predecessors()) {
    Register val = GetValueAtEndOfBlockInternal(pred, onlyExisting);
    predValues.emplace_back(pred, val);
    if (first) {
      commonValue = val;
      first = false;
    } else if (val != commonValue) {
      commonValue = Register();
    }
  }

  // If all incoming values are identical, reuse it
  if (commonValue)
    return commonValue;

  // Try to reuse an existing PHI
  Register reusedPHI = FindMatchingPHI(BB, predValues);
  if (reusedPHI)
    return reusedPHI;

  // Cannot insert new instructions? Return $noreg
  if (onlyExisting)
    return Register();

  // Insert new PHI
  MachineBasicBlock::iterator loc = BB->empty() ? BB->end() : BB->begin();
  MachineInstrBuilder phiBuilder = CreateNewDef(
      TargetOpcode::PHI, BB, loc, VRC, MRI, TII);

  for (auto &[block, reg] : predValues)
    phiBuilder.addReg(reg).addMBB(block);

  // Check if PHI simplifies to constant
  if (unsigned constVal = phiBuilder->isConstantValuePHI()) {
    phiBuilder->eraseFromParent();
    return constVal;
  }

  // Record inserted PHI if requested
  if (InsertedPHIs)
    InsertedPHIs->push_back(phiBuilder);

  LLVM_DEBUG(dbgs() << "  Inserted PHI: " << *phiBuilder << "\n");
  return phiBuilder.getReg(0);
}

// Helper: find which predecessor corresponds to a PHI operand
static MachineBasicBlock *GetCorrespondingPred(const MachineInstr *phi, MachineOperand *op) {
  for (unsigned i = 1, e = phi->getNumOperands(); i < e; i += 2) {
    if (&phi->getOperand(i) == op)
      return phi->getOperand(i + 1).getMBB();
  }
  llvm_unreachable("Failed to locate corresponding predecessor in PHI node");
}

// Rewrite a use operand to refer to the correct SSA value
void MachineSSAUpdater::RewriteUse(MachineOperand &useOp) {
  MachineInstr *user = useOp.getParent();
  Register newVal;

  if (user->isPHI()) {
    MachineBasicBlock *sourceBB = GetCorrespondingPred(user, &useOp);
    newVal = GetValueAtEndOfBlockInternal(sourceBB);
  } else {
    newVal = GetValueInMiddleOfBlock(user->getParent());
  }

  useOp.setReg(newVal);
}

namespace llvm {

// Specialization of SSAUpdaterTraits for MachineSSAUpdater
template<>
class SSAUpdaterTraits<MachineSSAUpdater> {
public:
  using BlockType = MachineBasicBlock;
  using ValueType = Register;
  using PhiType = MachineInstr;
  using SuccIterator = MachineBasicBlock::succ_iterator;

  static SuccIterator succ_begin(BlockType *BB) { return BB->succ_begin(); }
  static SuccIterator succ_end(BlockType *BB) { return BB->succ_end(); }

  class PhiOperandIterator {
  private:
    PhiType *phiNode;
    unsigned currentIndex;

  public:
    explicit PhiOperandIterator(PhiType *P) : phiNode(P), currentIndex(1) {}
    PhiOperandIterator(PhiType *P, bool) : phiNode(P), currentIndex(P->getNumOperands()) {}

    PhiOperandIterator &operator++() { currentIndex += 2; return *this; }
    bool operator==(const PhiOperandIterator &other) const { return currentIndex == other.currentIndex; }
    bool operator!=(const PhiOperandIterator &other) const { return !(*this == other); }

    ValueType getIncomingValue() const { return phiNode->getOperand(currentIndex).getReg(); }
    BlockType *getIncomingBlock() const { return phiNode->getOperand(currentIndex + 1).getMBB(); }
  };

  static PhiOperandIterator phi_begin(PhiType *P) { return PhiOperandIterator(P); }
  static PhiOperandIterator phi_end(PhiType *P) { return PhiOperandIterator(P, true); }

  static void getPredecessors(BlockType *BB, SmallVectorImpl<BlockType*> *out) {
    append_range(*out, BB->predecessors());
  }

  static ValueType getUndefValue(BlockType *BB, MachineSSAUpdater *updater) {
    MachineInstr *def = CreateNewDef(
        TargetOpcode::IMPLICIT_DEF,
        BB, BB->getFirstNonPHI(),
        updater->VRC, updater->MRI, updater->TII);
    return def->getOperand(0).getReg();
  }

  static ValueType createEmptyPhi(BlockType *BB, unsigned /*numPreds*/, MachineSSAUpdater *updater) {
    MachineBasicBlock::iterator loc = BB->empty() ? BB->end() : BB->begin();
    MachineInstr *phi = CreateNewDef(
        TargetOpcode::PHI, BB, loc,
        updater->VRC, updater->MRI, updater->TII);
    return phi->getOperand(0).getReg();
  }

  static void addPhiOperand(PhiType *phi, ValueType val, BlockType *pred) {
    BuildMI(*pred->getParent(), phi, DebugLoc(), nullptr).addReg(val).addMBB(pred);
  }

  static PhiType *isPhiInstruction(MachineInstr *inst) {
    return inst && inst->isPHI() ? inst : nullptr;
  }

  static PhiType *valueIsPhi(ValueType reg, MachineSSAUpdater *updater) {
    return isPhiInstruction(updater->MRI->getVRegDef(reg));
  }

  static PhiType *valueIsNewPhi(ValueType reg, MachineSSAUpdater *updater) {
    PhiType *phi = valueIsPhi(reg, updater);
    return (phi && phi->getNumOperands() <= 1) ? phi : nullptr;
  }

  static ValueType getPhiResult(PhiType *phi) {
    return phi->getOperand(0).getReg();
  }
};

} // end namespace llvm

// Internal implementation: retrieve or construct SSA value at end of block
Register MachineSSAUpdater::GetValueAtEndOfBlockInternal(
    MachineBasicBlock *BB, bool onlyExisting) {
  BlockToRegMap &stored = getStoredValues(AV);
  Register existing = stored.lookup(BB);
  if (existing || onlyExisting)
    return existing;

  SSAUpdaterImpl<MachineSSAUpdater> impl(this, &stored, InsertedPHIs);
  return impl.GetValue(BB);
}

#include <iostream>
#include <vector>
using namespace std;

class Solution {
public:
    // Generate all possible subsets using backtracking
    void generateSubsets(vector<int>& input, vector<int>& current, int index, vector<vector<int>>& result) {
        if (index == input.size()) {
            result.push_back(current);
            return;
        }

        // Include the element at current index
        current.push_back(input[index]);
        generateSubsets(input, current, index + 1, result);

        // Exclude the element at current index (backtrack)
        current.pop_back();
        generateSubsets(input, current, index + 1, result);
    }

    vector<vector<int>> findSubsets(vector<int>& elements) {
        vector<vector<int>> allSubsets;
        vector<int> temp;
        generateSubsets(elements, temp, 0, allSubsets);
        return allSubsets;
    }
};

int main() {
    Solution solver;
    vector<int> data = {1, 2, 3};
    vector<vector<int>> output = solver.findSubsets(data);

    for (int i = 0; i < output.size(); ++i) {
        cout << "{ ";
        for (int j = 0; j < output[i].size(); ++j) {
            cout << output[i][j] << " ";
        }
        cout << "}" << endl;
    }

    return 0;
}

