int main(int, char**)
{
    // Initialize SDL subsystems
    if (!SDL_Init(SDL_INIT_VIDEO | SDL_INIT_GAMEPAD))
    {
        std::fprintf(stderr, "Failed to initialize SDL: %s\n", SDL_GetError());
        return 1;
    }

    // Determine display scaling factor for UI elements
    float dpi_scale = SDL_GetDisplayContentScale(SDL_GetPrimaryDisplay());

    // Create window with appropriate flags and size
    SDL_WindowFlags flags = SDL_WINDOW_RESIZABLE | SDL_WINDOW_HIDDEN | SDL_WINDOW_HIGH_PIXEL_DENSITY;
    SDL_Window* window = SDL_CreateWindow(
        "Dear ImGui SDL3 + SDL_GPU Demo",
        static_cast<int>(1280 * dpi_scale),
        static_cast<int>(800 * dpi_scale),
        flags
    );

    if (window == nullptr)
    {
        std::fprintf(stderr, "Failed to create window: %s\n", SDL_GetError());
        return 1;
    }

    SDL_SetWindowPosition(window, SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED);
    SDL_ShowWindow(window);

    // Initialize GPU device with multiple shader format support
    SDL_GPUDevice* gpu = SDL_CreateGPUDevice(
        SDL_GPU_SHADERFORMAT_SPIRV | SDL_GPU_SHADERFORMAT_DXIL | SDL_GPU_SHADERFORMAT_METALLIB,
        true,
        nullptr
    );

    if (gpu == nullptr)
    {
        std::fprintf(stderr, "Failed to create GPU device: %s\n", SDL_GetError());
        return 1;
    }

    // Bind window to GPU device
    if (!SDL_ClaimWindowForGPUDevice(gpu, window))
    {
        std::fprintf(stderr, "Failed to claim window for GPU: %s\n", SDL_GetError());
        return 1;
    }

    // Configure swapchain parameters
    SDL_SetGPUSwapchainParameters(gpu, window, SDL_GPU_SWAPCHAINCOMPOSITION_SDR, SDL_GPU_PRESENTMODE_VSYNC);

    // Initialize Dear ImGui context
    IMGUI_CHECKVERSION();
    ImGui::CreateContext();
    ImGuiIO& io = ImGui::GetIO();
    (void)io;

    // Enable input controls and docking features
    io.ConfigFlags |= ImGuiConfigFlags_NavEnableKeyboard;
    io.ConfigFlags |= ImGuiConfigFlags_NavEnableGamepad;
    io.ConfigFlags |= ImGuiConfigFlags_DockingEnable;
    io.ConfigFlags |= ImGuiConfigFlags_ViewportsEnable;

    // Apply dark color scheme
    ImGui::StyleColorsDark();

    // Adjust styling based on DPI scaling
    ImGuiStyle& imgui_style = ImGui::GetStyle();
    imgui_style.ScaleAllSizes(dpi_scale);
    imgui_style.FontScaleDpi = dpi_scale;
    io.ConfigDpiScaleFonts = true;
    io.ConfigDpiScaleViewports = true;

    // Modify style for multi-viewport support
    if (io.ConfigFlags & ImGuiConfigFlags_ViewportsEnable)
    {
        imgui_style.WindowRounding = 0.0f;
        imgui_style.Colors[ImGuiCol_WindowBg].w = 1.0f;
    }

    // Setup platform/renderer backends
    ImGui_ImplSDL3_InitForSDLGPU(window);
    ImGui_ImplSDLGPU3_InitInfo init_params = {};
    init_params.Device = gpu;
    init_params.ColorTargetFormat = SDL_GetGPUSwapchainTextureFormat(gpu, window);
    init_params.MSAASamples = SDL_GPU_SAMPLECOUNT_1;
    init_params.SwapchainComposition = SDL_GPU_SWAPCHAINCOMPOSITION_SDR;
    init_params.PresentMode = SDL_GPU_PRESENTMODE_VSYNC;
    ImGui_ImplSDLGPU3_Init(&init_params);

    // Font configuration (commented out examples)
    // style.FontSizeBase = 20.0f;
    // io.Fonts->AddFontDefault();
    // io.Fonts->AddFontFromFileTTF("c:\\Windows\\Fonts\\segoeui.ttf");
    // ... [other font loading options]

    // Application state variables
    bool show_demo_window = true;
    bool show_another_window = false;
    ImVec4 background_color = ImVec4(0.45f, 0.55f, 0.60f, 1.00f);

    // Main event loop
    bool running = true;
    while (running)
    {
        // Process events
        SDL_Event evt;
        while (SDL_PollEvent(&evt))
        {
            ImGui_ImplSDL3_ProcessEvent(&evt);
            if (evt.type == SDL_EVENT_QUIT)
                running = false;
            if (evt.type == SDL_EVENT_WINDOW_CLOSE_REQUESTED && evt.window.windowID == SDL_GetWindowID(window))
                running = false;
        }

        // Skip rendering when minimized
        if (SDL_GetWindowFlags(window) & SDL_WINDOW_MINIMIZED)
        {
            SDL_Delay(10);
            continue;
        }

        // Begin new frame
        ImGui_ImplSDLGPU3_NewFrame();
        ImGui_ImplSDL3_NewFrame();
        ImGui::NewFrame();

        // Render demo window
        if (show_demo_window)
            ImGui::ShowDemoWindow(&show_demo_window);

        // Render custom window
        {
            static float time_var = 0.0f;
            static int click_counter = 0;
            ImGui::Begin("Hello, world!");

            ImGui::Text("This is some useful text.");
            ImGui::Checkbox("Demo Window", &show_demo_window);
            ImGui::Checkbox("Another Window", &show_another_window);
            ImGui::SliderFloat("float", &time_var, 0.0f, 1.0f);
            ImGui::ColorEdit3("clear color", (float*)&background_color);

            if (ImGui::Button("Click Me"))
                click_counter++;

            ImGui::SameLine();
            ImGui::Text("counter = %d", click_counter);
            ImGui::Text("Application average %.3f ms/frame (%.1f FPS)", 1000.0f / io.Framerate, io.Framerate);
            ImGui::End();
        }

        // Render secondary window if active
        if (show_another_window)
        {
            ImGui::Begin("Another Window", &show_another_window);
            ImGui::Text("Hello from another window!");
            if (ImGui::Button("Close Me"))
                show_another_window = false;
            ImGui::End();
        }

        // Finalize frame and prepare for rendering
        ImGui::Render();
        ImDrawData* draw_data = ImGui::GetDrawData();
        const bool is_minimized = (draw_data->DisplaySize.x <= 0.0f || draw_data->DisplaySize.y <= 0.0f);

        SDL_GPUCommandBuffer* cmd_buf = SDL_AcquireGPUCommandBuffer(gpu);
        SDL_GPUTexture* swapchain_tex;
        SDL_WaitAndAcquireGPUSwapchainTexture(cmd_buf, window, &swapchain_tex, nullptr, nullptr);

        if (swapchain_tex != nullptr && !is_minimized)
        {
            ImGui_ImplSDLGPU3_PrepareDrawData(draw_data, cmd_buf);

            SDL_GPUColorTargetInfo target_info = {};
            target_info.texture = swapchain_tex;
            target_info.clear_color = SDL_FColor{ background_color.x, background_color.y, background_color.z, background_color.w };
            target_info.load_op = SDL_GPU_LOADOP_CLEAR;
            target_info.store_op = SDL_GPU_STOREOP_STORE;
            target_info.mip_level = 0;
            target_info.layer_or_depth_plane = 0;
            target_info.cycle = false;

            SDL_GPURenderPass* render_pass = SDL_BeginGPURenderPass(cmd_buf, &target_info, 1, nullptr);
            ImGui_ImplSDLGPU3_RenderDrawData(draw_data, cmd_buf, render_pass);
            SDL_EndGPURenderPass(render_pass);
        }

        // Handle multi-viewport updates
        if (io.ConfigFlags & ImGuiConfigFlags_ViewportsEnable)
        {
            ImGui::UpdatePlatformWindows();
            ImGui::RenderPlatformWindowsDefault();
        }

        SDL_SubmitGPUCommandBuffer(cmd_buf);
    }

    // Cleanup resources
    SDL_WaitForGPUIdle(gpu);
    ImGui_ImplSDL3_Shutdown();
    ImGui_ImplSDLGPU3_Shutdown();
    ImGui::DestroyContext();
    SDL_ReleaseWindowFromGPUDevice(gpu, window);
    SDL_DestroyGPUDevice(gpu);
    SDL_DestroyWindow(window);
    SDL_Quit();
    return 0;
}

