#include "modelpomo.h"
#include "modeldna.h"
#include "modelmixture.h"
#include <stdlib.h>
#include <assert.h>
#include <string.h>
#include <Eigen/Dense>
#include <unsupported/Eigen/MatrixFunctions>

class ModelPoMo : public ModelMarkov {
private:
    int popSize; // N
    int alleleCount; // n_alleles
    int connectionCount; // n_connections
    double epsilon;
    ModelMarkov* underlyingMutationModel;
    double* boundaryFrequencies;
    double* empiricalBoundaryFreqs;
    double heterozygosityValue;
    double scaleFactor;
    bool fixedParams;
    bool fixedHeteroEmpirical;
    bool fixedHeteroUser;
    bool fixedHetero;
    int samplingMode;

public:
    ModelPoMo(PhyloTree *tree) : ModelMarkov(tree) {
        initDefaults();
    }

    ModelPoMo(const char *modelName,
              std::string modelParameters,
              StateFreqType freqType,
              std::string freqParameters,
              PhyloTree *tree,
              std::string pomoHeterozygosity)
        : ModelMarkov(tree, true) {
        initialize(modelName, modelParameters, freqType, freqParameters, pomoHeterozygosity);
    }

    void initDefaults() {
        popSize = 0;
        alleleCount = 4;
        connectionCount = 6;
        epsilon = 1e-8;
        underlyingMutationModel = nullptr;
        boundaryFrequencies = nullptr;
        empiricalBoundaryFreqs = nullptr;
        heterozygosityValue = 0.0;
        scaleFactor = 1.0;
        fixedParams = false;
        fixedHeteroEmpirical = false;
        fixedHeteroUser = false;
        fixedHetero = false;
        samplingMode = 0;
    }

    void initializeMutationModel(const char *modelName,
                                std::string modelParameters,
                                StateFreqType freqType,
                                std::string freqParameters) {
        // Adjust alignment state count temporarily
        tree->alignment->numStates = alleleCount;

        try {
            if (verbosity >= VB_MED)
                std::cout << "Initializing PoMo DNA mutation model." << std::endl;

            std::string modelNameStr = modelName;
            if (isValidModelName(modelNameStr))
                underlyingMutationModel = getMutationModelByName(modelNameStr, tree, modelParameters, freqType, freqParameters);
            else
                underlyingMutationModel = new ModelDNA(modelName, modelParameters, freqType, freqParameters, tree);
        }
        catch (std::string errorMsg) {
            std::cout << "Error during initialization of the underlying mutation model of PoMo." << std::endl;
            std::cout << "PoMo only works with DNA models at the moment." << std::endl;
            handleError(errorMsg);
        }

        // Restore original state count
        tree->alignment->numStates = numStates;

        // Set reversibility based on mutation model
        isReversible = underlyingMutationModel->isReversible;
        if (!isReversible)
            setReversibility(isReversible);
    }

    void initializeSamplingMethod() {
        samplingMode = tree->alignment->pomoSamplingMethod;
        std::string samplingMethodName;

        switch (samplingMode) {
            case SAMPLING_SAMPLED:
                name += "+S";
                samplingMethodName = "Sampled";
                break;
            case SAMPLING_WEIGHTED_BINOM:
                name += "+WB";
                samplingMethodName = "Weighted binomial";
                break;
            case SAMPLING_WEIGHTED_HYPER:
                name += "+WH";
                samplingMethodName = "Weighted hypergeometric";
                break;
            default:
                handleError("Unsupported sampling method.");
        }

        fullName = "PoMo with N=" + convertIntToString(popSize) + " and " +
                  underlyingMutationModel->fullName + " mutation model; " +
                  "Sampling method: " + samplingMethodName + "; " +
                  convertIntToString(numStates) + " states in total;";
    }

    void initializeBoundaryFrequencies() {
        boundaryFrequencies = new double[alleleCount];
        empiricalBoundaryFreqs = new double[alleleCount];

        // Initialize boundary frequencies from mutation model
        for (int i = 0; i < alleleCount; i++)
            boundaryFrequencies[i] = underlyingMutationModel->stateFrequencies[i];

        // Estimate empirical frequencies from data
        estimateEmpiricalBoundaryFrequencies(empiricalBoundaryFreqs);

        // Set frequency type from mutation model
        freqType = underlyingMutationModel->freqType;

        // Apply frequency type rules
        switch (freqType) {
            case FREQ_EQUAL:
                for (int i = 0; i < alleleCount; i++)
                    boundaryFrequencies[i] = 1.0 / (double)alleleCount;
                break;
            case FREQ_ESTIMATE:
                for (int i = 0; i < alleleCount; i++)
                    boundaryFrequencies[i] = empiricalBoundaryFreqs[i];
                break;
            case FREQ_EMPIRICAL:
                for (int i = 0; i < alleleCount; i++)
                    boundaryFrequencies[i] = empiricalBoundaryFreqs[i];
                break;
            case FREQ_USER_DEFINED:
                if (boundaryFrequencies[0] == 0.0)
                    handleError("State frequencies not specified");
                break;
            case FREQ_UNKNOWN:
                handleError("No frequency type given.");
                break;
            default:
                handleError("Unknown frequency type.");
                break;
        }
    }

    void initializeFixedParameters(std::string modelParameters,
                                  std::string pomoHeterozygosity) {
        fixedParams = false;
        fixedHeteroEmpirical = false;
        fixedHeteroUser = false;
        fixedHetero = false;

        if (modelParameters.length() > 0)
            fixedParams = true;

        if (pomoHeterozygosity.length() > 0) {
            fixedHetero = true;
            std::cout << std::setprecision(5);

            if (pomoHeterozygosity == "EMP") {
                std::cout << "Level of polymorphism is fixed to the estimate from the data: ";
                std::cout << heterozygosityValue << "." << std::endl;
                fixedHeteroEmpirical = true;
            }
            else {
                std::cout << "Heterozygosity is fixed to the value given by the user: ";
                heterozygosityValue = convertDouble(pomoHeterozygosity.c_str());
                std::cout << heterozygosityValue << "." << std::endl;
                fixedHeteroUser = true;
            }
        }
    }

    void initialize(const char *modelName,
                   std::string modelParameters,
                   StateFreqType freqType,
                   std::string freqParameters,
                   std::string pomoHeterozygosity) {
        // Initialize model constants
        popSize = tree->alignment->virtualPopSize;
        alleleCount = 4;
        connectionCount = alleleCount * (alleleCount - 1) / 2;
        epsilon = 1e-8;

        // Verify PoMo state count matches expected
        ASSERT(numStates == (alleleCount + (alleleCount*(alleleCount-1)/2 * (popSize-1))) );

        // Main initialization sequence
        initializeMutationModel(modelName, modelParameters, freqType, freqParameters);
        initializeSamplingMethod();
        initializeBoundaryFrequencies();

        // Initialize heterozygosity and scale factor
        heterozygosityValue = estimateEmpiricalWattersonTheta();
        scaleFactor = 1.0;

        initializeFixedParameters(modelParameters, pomoHeterozygosity);
        setHeterozygosityBoundaries();
        setInitialMutationCoefficients();

        // Setup rate matrix
        ignoreStateFreq = true;
        normalizeMatrix = false;
        halfMatrix = false;

        delete [] rates;
        rates = new double[numStates * numStates];

        updatePoMoStatesAndRateMatrix();
        decomposeRateMatrix();

        // Build model name
        name = underlyingMutationModel->getName();
        name += "+P";
        name += "+N" + convertIntToString(popSize);

        if (verbosity >= VB_MED) {
            std::cout << "Initialized PoMo model." << std::endl;
            std::cout << "Model name: " << name << "." << std::endl;
            std::cout << fullName << std::endl;
        }

        if (verbosity >= VB_MAX)
            writeInfo(std::cout);
    }

    ~ModelPoMo() {
        delete underlyingMutationModel;
        delete [] boundaryFrequencies;
        delete [] empiricalBoundaryFreqs;
    }

    // Helper functions
    double computeBoundaryFrequencySum() {
        double sum = 0.0;
        for (int i = 0; i < alleleCount; i++)
            sum += boundaryFrequencies[i];

        if ((sum > 1.0 + epsilon) || (sum < 1.0 - epsilon))
            handleError("Calculation of boundary state frequencies faulty (maybe a numerical problem).");

        return sum;
    }

    double harmonicNumber(int n) {
        double result = 0.0;
        for (int i = 1; i <= n; i++)
            result += 1.0 / (double)i;
        return result;
    }

    void setInitialMutationCoefficients() {
        double* mutationRates = new double[alleleCount * alleleCount];
        memset(mutationRates, 0, alleleCount * alleleCount * sizeof(double));

        double lambdaPolySumNoMut = computePolyStateSumNoMut(mutationRates);
        if (lambdaPolySumNoMut <= 0) {
            outWarning("We discourage usage of PoMo on data without polymorphisms.");
            if (!fixedHeteroUser)
                handleError("Please fix the heterozygosity when population data is unavailable.");
        }

        normalizeMutationRates(mutationRates);
        delete [] mutationRates;
    }

    double computePolyStateSumNoMut(double* rates) {
        double polySum = 0.0;
        for (int i = 0; i < alleleCount; i++) {
            for (int j = 0; j < i; j++)
                polySum += 2 * boundaryFrequencies[i] * boundaryFrequencies[j];
        }
        polySum *= harmonicNumber(popSize - 1);
        return polySum;
    }

    double computePolyStateSum() {
        double polySum = 0.0;
        double temp;
        for (int i = 0; i < alleleCount; i++) {
            for (int j = 0; j < alleleCount; j++) {
                if (i != j) {
                    temp = boundaryFrequencies[i] * mutation_rate_matrix[i*alleleCount+j];
                    polySum += temp;
                }
            }
        }
        polySum *= harmonicNumber(popSize - 1);
        return polySum;
    }

    double computeNormalizationConstant() {
        double boundarySum = computeBoundaryFrequencySum();
        double polySum = computePolyStateSum();
        return 1.0 / (boundarySum + polySum);
    }

    void computeStateFrequencies() {
        double norm = computeNormalizationConstant();
        int state;

        for (state = 0; state < numStates; state++) {
            if (isBoundaryState(state))
                state_freq[state] = boundaryFrequencies[state] * norm;
            else {
                int i, a, b;
                decomposeState(state, i, a, b);
                state_freq[state] = boundaryFrequencies[a] * mutation_rate_matrix[a*alleleCount+b]/(popSize-i) + 
                                   boundaryFrequencies[b] * mutation_rate_matrix[b*alleleCount+a]/i;
                state_freq[state] *= norm;
            }
        }
    }

    void updatePoMoStatesAndRateMatrix() {
        computeStateFrequencies();

        double totalSum = 0.0;
        for (int i = 0; i < numStates; i++) {
            double rowSum = 0.0;
            for (int j = 0; j < numStates; j++) {
                if (i != j) {
                    rates[i*numStates+j] = computeBoundaryMutationProbability(i, j);
                    rowSum += rates[i*numStates+j];
                }
            }
            totalSum += state_freq[i] * rowSum;
            rates[i*numStates+i] = 0.0;
        }

        // Normalize rate matrix
        for (int i = 0; i < numStates; i++) {
            for (int j = 0; j < numStates; j++) {
                rates[i*numStates+j] /= totalSum;
            }
        }
    }

    void decomposeState(int state, int &count, int &allele1, int &allele2) {
        if (state < 4) {
            count = popSize;
            allele1 = state;
            allele2 = -1;
        } else if (state < 4 + (popSize-1)) {
            count = state - 3;
            allele1 = 0;
            allele2 = 1;
        } else if (state < 4 + 2*(popSize-1)) {
            count = state - 3 - (popSize-1);
            allele1 = 0;
            allele2 = 2;
        } else if (state < 4 + 3*(popSize-1)) {
            count = state - 3 - 2*(popSize-1);
            allele1 = 0;
            allele2 = 3;
        } else if (state < 4 + 4*(popSize-1)) {
            count = state - 3 - 3*(popSize-1);
            allele1 = 1;
            allele2 = 2;
        } else if (state < 4 + 5*(popSize-1)) {
            count = state - 3 - 4*(popSize-1);
            allele1 = 1;
            allele2 = 3;
        } else if (state < 4 + 6*(popSize-1)) {
            count = state - 3 - 5*(popSize-1);
            allele1 = 2;
            allele2 = 3;
        } else {
            handleError("State exceeds limit");
        }
    }

    bool isBoundaryState(int state) {
        return (state < 4);
    }

    bool isPolymorphicState(int state) {
        return !isBoundaryState(state);
    }

    double computeBoundaryMutationProbability(int state1, int state2) {
        ASSERT(state1 != state2);

        int c1=0, c2=0, a1=-1, a2=-1, a3=-1, a4=-1;
        decomposeState(state1, c1, a1, a2);
        decomposeState(state2, c2, a3, a4);

        if (a1 == a3 && (a2==a4 || a2==-1 || a4 == -1)) {
            ASSERT(c1 != c2);
            if (c1+1 == c2)
                return double(c1*(popSize-c1)) / double(popSize);
            else if (c1-1 == c2) {
                if (a2 == -1)
                    return mutation_rate_matrix[a1*alleleCount+a4];
                else
                    return double(c1*(popSize-c1)) / double(popSize);
            } else {
                return 0.0;
            }
        } else if (a1 == a4 && a2 == -1 && c2 == 1) {
            return mutation_rate_matrix[a1*alleleCount+a3];
        } else if (a2 == a3 && c1 == 1 && a4 == -1) {
            return double(c1*(popSize-c1)) / double(popSize);
        } else {
            return 0.0;
        }
    }

    int getDimensionCount() {
        if (fixedHetero)
            return underlyingMutationModel->getDimensionCount();
        else
            return underlyingMutationModel->getDimensionCount() + 1;
    }

    int getDimensionCountFreq() {
        return underlyingMutationModel->getDimensionCountFreq();
    }

    void setBounds(double *lower, double *upper, bool *check) {
        underlyingMutationModel->setBounds(lower, upper, check);

        if (!fixedHetero) {
            int dim = getDimensionCount();
            lower[dim] = minHeterozygosity;
            upper[dim] = maxHeterozygosity;
            check[dim] = false;
        }
    }

    void normalizeMutationRates(double* rates) {
        double* m = rates;
        underlyingMutationModel->getQMatrix(m);

        computeStateFrequencies();
        double poly = computePolyStateSum();
        double theta_bm = poly / harmonicNumber(popSize - 1);

        double correction = 1.0;

        double m_norm = scaleFactor * (heterozygosityValue / (theta_bm * (correction - harmonicNumber(popSize-1) * heterozygosityValue)));

        if (verbosity >= VB_MAX) {
            std::cout << "Normalization constant of mutation rates: " << m_norm << std::endl;
        }

        for (int i = 0; i < alleleCount; i++)
            for (int j = 0; j < alleleCount; j++) {
                m[i*alleleCount+j] *= m_norm;
            }
    }

    void setScaleFactor(double newScale) {
        scaleFactor = newScale;
        normalizeMutationRates(mutation_rate_matrix);
    }

    double getScaleFactor() {
        return scaleFactor;
    }

    bool getVariables(double *variables) {
        bool changed = false;
        changed = underlyingMutationModel->getVariables(variables);

        if (!fixedHetero) {
            int dim = getDimensionCount();
            changed |= (heterozygosityValue != variables[dim]);
            heterozygosityValue = variables[dim];
        }

        normalizeMutationRates(mutation_rate_matrix);
        updatePoMoStatesAndRateMatrix();
        return changed;
    }

    void setRates() {
        return;
    }

    void setVariables(double *variables) {
        underlyingMutationModel->setVariables(variables);
        if (!fixedHetero) {
            int dim = getDimensionCount();
            variables[dim] = heterozygosityValue;
        }
    }

    void report(ostream &out) {
        if (fixedParams)
            out << "User-defined model parameters." << endl;
        else
            out << "Model parameters." << endl;

        if (resetScale)
            setScaleFactor(1.0);
        else
            out << "The reported rates are scaled by a factor of " << scaleFactor << "." << endl;

        if (verbosity >= VB_MED) {
            out << "Rate matrix: " << endl;
            for (int i = 0; i < numStates; i++) {
                for (int j = 0; j < numStates; j++) {
                    out << std::setprecision(8);
                    out << std::setw(8) << rates[i*numStates+j] << " ";
                }
                out << std::endl;
            }
        }

        double* rs = NULL;
        double* es = NULL;
        if (isReversible) {
            rs = new double[connectionCount];
            es = new double[connectionCount];
        } else {
            rs = new double[2*connectionCount];
            es = new double[2*connectionCount];
        }

        rate_matrix_to_rates(mutation_rate_matrix, rs);
        rate_matrix_to_exchangeabilities(mutation_rate_matrix, es);

        mutation_model->report_rates(out, "Mutation    rates", rs);
        mutation_model->report_rates(out, "Exchangeabilities", es);

        delete [] rs;
        delete [] es;
    }

    void computeRateMatrix(double **r_matrix, double *s_freqs, int n_states) {
        for (int i = 0; i < n_states; i++) {
            for (int j = 0; j < n_states; j++) {
                r_matrix[i][j] = rates[i*n_states+j];
            }
        }
    }

    double targetFunction(double x[]) {
        getVariables(x);
        decomposeRateMatrix();
        tree->clearAllPartialLH();
        return -tree->computeLikelihood();
    }

    bool isUnstableParameters() {
        for (int i = 0; i < numStates; i++) {
            if (state_freq[i] < epsilon) return true;
        }
        return false;
    }

    void normalizeBoundaryFrequencies(double * bfs) {
        double sum = 0.0;
        for (int i = 0; i < alleleCount; i++)
            sum += bfs[i];
        for (int i = 0; i < alleleCount; i++)
            bfs[i] /= sum;

        if (verbosity >= VB_MAX) {
            std::cout << "The empirical frequencies of the boundary states are:" << std::endl;
            for (int i = 0; i < alleleCount; i++)
                std::cout << bfs[i] << " ";
            std::cout << std::endl;
        }

        checkBoundaryFrequencies(bfs);
    }

    void checkBoundaryFrequencies(double * bfs) {
        bool change = false;
        for (int i = 0; i < alleleCount; i++) {
            if (bfs[i] < POMO_MIN_BOUNDARY_FREQ) {
                bfs[i] = POMO_MIN_BOUNDARY_FREQ;
                outWarning("A boundary state has very low frequency.");
                change = true;
            }
            if (bfs[i] > POMO_MAX_BOUNDARY_FREQ) {
                bfs[i] = POMO_MAX_BOUNDARY_FREQ;
                outWarning("A boundary state has very high frequency.");
                change = true;
            }
        }
        if (change)
            normalizeBoundaryFrequencies(bfs);
    }

    void estimateEmpiricalBoundaryFrequencies(double * boundaryFreqs) {
        memset(boundaryFreqs, 0, sizeof(double)*alleleCount);

        if (samplingMode == SAMPLING_SAMPLED) {
            unsigned int absStateFreq[numStates];
            memset(absStateFreq, 0, sizeof(unsigned int)*numStates);
            tree->alignment->computeAbsoluteStateFreq(absStateFreq);

            int n, x, y;
            int sum[alleleCount];
            int totalSum = 0;
            memset(sum, 0, alleleCount * sizeof(int));

            for (int i = 0; i < numStates; i++) {
                decomposeState(i, n, x, y);
                sum[x] += n * absStateFreq[i];
                if (y >= 0) sum[y] += (popSize-n) * absStateFreq[i];
            }

            for (int i = 0; i < alleleCount; i++) {
                totalSum += sum[i];
            }

            for (int i = 0; i < alleleCount; i++) {
                boundaryFreqs[i] = (double) sum[i] / totalSum;
            }
        } else {
            for (Alignment::iterator it = tree->alignment->begin();
                 it != tree->alignment->end(); it++) {
                for (Pattern::iterator it2 = it->begin(); it2 != it->end(); it2++) {
                    int state = (int)*it2;
                    if (state < numStates)
                        handleError("Unknown PoMo state in pattern.");
                    else if ((unsigned int)state == tree->alignment->STATE_UNKNOWN)
                        continue;
                    state -= numStates;

                    int id1 = tree->alignment->pomo_sampled_states[state] & 3;
                    int id2 = (tree->alignment->pomo_sampled_states[state] >> 16) & 3;
                    int j1 = (tree->alignment->pomo_sampled_states[state] >> 2) & 16383;
                    int j2 = (tree->alignment->pomo_sampled_states[state] >> 18);

                    boundaryFreqs[id1] += j1 * (it->frequency);
                    boundaryFreqs[id2] += j2 * (it->frequency);
                }
            }
        }

        normalizeBoundaryFrequencies(boundaryFreqs);
    }

    double estimateEmpiricalWattersonTheta() {
        double theta_p = 0.0;
        int polyCount = 0;
        int fixCount = 0;
        double sumThetaW = 0.0;

        if (samplingMode == SAMPLING_SAMPLED) {
            unsigned int absStateFreq[numStates];
            memset(absStateFreq, 0, sizeof(unsigned int)*numStates);
            tree->alignment->computeAbsoluteStateFreq(absStateFreq);

            for (int i = 0; i < alleleCount; i++) fixCount += absStateFreq[i];
            for (int i = alleleCount; i < numStates; i++) polyCount += absStateFreq[i];

            theta_p = (double) polyCount / (double) (fixCount + polyCount);
        } else {
            for (Alignment::iterator it = tree->alignment->begin();
                 it != tree->alignment->end(); it++) {
                for (Pattern::iterator it2 = it->begin(); it2 != it->end(); it2++) {
                    int state = (int)*it2;
                    if (state < numStates)
                        handleError("Unknown PoMo state in pattern.");
                    else if ((unsigned int)state == tree->alignment->STATE_UNKNOWN)
                        continue;
                    state -= numStates;

                    int j1 = (tree->alignment->pomo_sampled_states[state] >> 2) & 16383;
                    int j2 = (tree->alignment->pomo_sampled_states[state] >> 18);

                    if (j2 == 0) fixCount += it->frequency;
                    else {
                        polyCount += it->frequency;
                        sumThetaW += (double) it->frequency / harmonicNumber(j1 + j2 - 1);
                    }
                }
            }

            double thetaWTemp = sumThetaW;
            sumThetaW = thetaWTemp / (double) (fixCount + polyCount);
            theta_p = sumThetaW;
        }

        return theta_p;
    }
};

