#include <iostream>
#include <vector>
#include <cmath>
#include <random>
#include <chrono>
#include <algorithm>
#include <utility>

// Fixed constants as per problem specification
const int MAX_NODES = 100;
const int WEEKS_LIMIT = 500000;

int node_count, week_count; // Will be assigned MAX_NODES and WEEKS_LIMIT respectively
std::vector<int> target_counts;

// Random number generator
std::mt19937 engine;

// Simulate the process and compute total absolute deviation from target counts
long long evaluate_solution(const std::vector<int>& transition_table) {
    std::vector<int> visit_counts(MAX_NODES, 0);
    int current_node = 0;

    for (int week = 0; week < WEEKS_LIMIT; ++week) {
        visit_counts[current_node]++;
        int occurrence = visit_counts[current_node];

        if (occurrence % 2 == 1) { // odd occurrence
            current_node = transition_table[current_node * 2];
        } else { // even occurrence
            current_node = transition_table[current_node * 2 + 1];
        }
    }

    long long deviation = 0;
    for (int i = 0; i < MAX_NODES; ++i) {
        deviation += std::abs(visit_counts[i] - target_counts[i]);
    }
    return deviation;
}

int main() {
    // Optimize I/O operations
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    // Initialize random engine with high-resolution timestamp
    engine.seed(std::chrono::high_resolution_clock::now().time_since_epoch().count());

    // Read input parameters
    std::cin >> node_count >> week_count;
    target_counts.resize(node_count);
    for (int i = 0; i < node_count; ++i) {
        std::cin >> target_counts[i];
    }

    // Step 1: Construct initial solution using Largest Remainder Method
    std::vector<int> transition(2 * node_count);
    {
        std::vector<double> ideal_distribution(node_count);
        for (int i = 0; i < node_count; ++i) {
            ideal_distribution[i] = static_cast<double>(target_counts[i]) / week_count * (2 * node_count);
        }

        std::vector<int> degrees(node_count, 0);
        int allocated = 0;
        std::vector<std::pair<double, int>> fractional_parts;
        fractional_parts.reserve(node_count);

        for (int i = 0; i < node_count; ++i) {
            degrees[i] = static_cast<int>(std::floor(ideal_distribution[i]));
            allocated += degrees[i];
            fractional_parts.emplace_back(ideal_distribution[i] - degrees[i], i);
        }

        // Sort descending by fractional part to prioritize largest remainders
        std::sort(fractional_parts.begin(), fractional_parts.end(),
                  [](const auto& a, const auto& b) { return a.first > b.first; });

        int remaining = 2 * node_count - allocated;
        for (int i = 0; i < remaining; ++i) {
            degrees[fractional_parts[i].second]++;
        }

        std::vector<int> expanded_list;
        expanded_list.reserve(2 * node_count);
        for (int i = 0; i < node_count; ++i) {
            for (int j = 0; j < degrees[i]; ++j) {
                expanded_list.push_back(i);
            }
        }

        // Shuffle to randomize assignment while preserving degree constraints
        std::shuffle(expanded_list.begin(), expanded_list.end(), engine);
        transition = expanded_list;
    }

    long long current_deviation = evaluate_solution(transition);
    std::vector<int> best_transition = transition;
    long long best_deviation = current_deviation;

    // Step 2: Apply Simulated Annealing for optimization
    double time_budget = 2.8;
    auto start_time = std::chrono::high_resolution_clock::now();

    double initial_temperature = 500.0;
    double final_temperature = 0.1;

    std::uniform_int_distribution<int> move_type_dist(0, 99);
    std::uniform_int_distribution<int> index_dist(0, 2 * node_count - 1);
    std::uniform_int_distribution<int> value_dist(0, node_count - 1);
    std::uniform_real_distribution<double> acceptance_prob_dist(0.0, 1.0);

    while (true) {
        auto now = std::chrono::high_resolution_clock::now();
        double elapsed_seconds = std::chrono::duration<double>(now - start_time).count();
        if (elapsed_seconds > time_budget) break;

        double temperature = initial_temperature * (1.0 - elapsed_seconds / time_budget) +
                             final_temperature * (elapsed_seconds / time_budget);

        std::vector<int> candidate = transition;

        int operation = move_type_dist(engine);
        int idx1, idx2;

        if (operation < 90) { // Swap operation (90% probability)
            idx1 = index_dist(engine);
            do {
                idx2 = index_dist(engine);
            } while (idx1 == idx2);
            std::swap(candidate[idx1], candidate[idx2]);
        } else { // Value change operation (10% probability)
            idx1 = index_dist(engine);
            int old_value = candidate[idx1];
            do {
                idx2 = value_dist(engine);
            } while (idx2 == old_value);
            candidate[idx1] = idx2;
        }

        long long new_deviation = evaluate_solution(candidate);

        // Acceptance probability based on Metropolis criterion
        double delta = static_cast<double>(current_deviation - new_deviation);
        double accept_prob = std::exp(delta / temperature);

        if (acceptance_prob_dist(engine) < accept_prob) {
            transition = candidate;
            current_deviation = new_deviation;

            if (current_deviation < best_deviation) {
                best_deviation = current_deviation;
                best_transition = transition;
            }
        }
    }

    // Step 3: Output final result
    for (int i = 0; i < node_count; ++i) {
        std::cout << best_transition[2 * i] << " " << best_transition[2 * i + 1] << "\n";
    }

    return 0;
}

#include "pugixml.hpp"
#include <iostream>
#include <string>

int main() {
    pugi::xml_document doc;
    if (!doc.load_file("xgconsole.xml")) return -1;

    // Prepare XPath variables for conditional node selection
    pugi::xpath_variable_set variableSet;
    variableSet.add("remote", pugi::xpath_type_boolean);

    // Build a reusable query to filter tools based on the 'AllowRemote' attribute
    pugi::xpath_query filteredToolsQuery("/Profile/Tools/Tool[@AllowRemote = string($remote)]", &variableSet);

    // Evaluate with remote = true
    variableSet.set("remote", true);
    pugi::xpath_node_set remoteTools = filteredToolsQuery.evaluate_node_set(doc);

    // Evaluate with remote = false
    variableSet.set("remote", false);
    pugi::xpath_node_set localTools = filteredToolsQuery.evaluate_node_set(doc);

    // Output specific nodes from each set
    std::cout << "Remote tool: ";
    remoteTools[2].node().print(std::cout);
    std::cout << "\nLocal tool: ";
    localTools[0].node().print(std::cout);

    // Alternative: evaluate directly without precompiled query
    pugi::xpath_node_set directLocalTools = doc.select_nodes(
        "/Profile/Tools/Tool[@AllowRemote = string($remote)]", 
        &variableSet
    );

    std::cout << "\nLocal tool (direct): ";
    directLocalTools[0].node().print(std::cout);
    std::cout << std::endl;

    return 0;
}

