class ErodeDilateFx final : public TStandardRasterFx {
  FX_PLUGIN_DECLARATION(ErodeDilateFx)
  TRasterFxPort m_sourceInput;
  TIntEnumParamP m_operationMode;
  TDoubleParamP m_effectRadius;

public:
  ErodeDilateFx() 
    : m_operationMode(new TIntEnumParam(0, "Square")), 
      m_effectRadius(0.0) {
    addInputPort("Source", m_sourceInput);
    bindParam(this, "type", m_operationMode);
    m_operationMode->addItem(1, "Circular");
    m_effectRadius->setMeasureName("fxLength");
    bindParam(this, "radius", m_effectRadius);
  }

  bool doGetBBox(double frame, TRectD &boundingBox,
                 const TRenderSettings &renderInfo) override;

  void doDryCompute(TRectD &regionOfInterest, double frame,
                    const TRenderSettings &ri) override;

  void doCompute(TTile &outputTile, double frame,
                 const TRenderSettings &ri) override;

  int getMemoryRequirement(const TRectD &rect, double frame,
                           const TRenderSettings &info) override;

  bool canHandle(const TRenderSettings &info, double frame) override {
    return isAlmostIsotropic(info.m_affine);
  }

private:
  // Helper: compute effective radius considering affine transform scaling
  double computeEffectiveRadius(double frame, const TRenderSettings &info) const {
    return m_effectRadius->getValue(frame) * std::sqrt(info.m_affine.det());
  }

  // Helper: determine whether operation is dilation or erosion
  bool isDilation(double radius) const { return radius >= 0.0; }
};

//-------------------------------------------------------------------
bool ErodeDilateFx::doGetBBox(double frame, TRectD &boundingBox,
                              const TRenderSettings &renderInfo) {
  if (!m_sourceInput.getFx()) return false;
  bool success = m_sourceInput->doGetBBox(frame, boundingBox, renderInfo);
  double radius = m_effectRadius->getValue(frame);
  boundingBox = boundingBox.enlarge(tceil(radius));
  return success;
}

//-------------------------------------------------------------------
void ErodeDilateFx::doCompute(TTile &outputTile, double frame,
                              const TRenderSettings &renderInfo) {
  if (!m_sourceInput.isConnected()) return;

  double radius = computeEffectiveRadius(frame, renderInfo);
  bool dilate   = isDilation(radius);
  TRop::ErodilateMaskType maskType = static_cast<TRop::ErodilateMaskType>(m_operationMode->getValue());

  if (dilate) {
    // Forward request to input and apply dilation directly
    m_sourceInput->compute(outputTile, frame, renderInfo);
    const TRasterP &ras = outputTile.getRaster();
    TRop::erodilate(ras, ras, radius, maskType);
  } else {
    // For erosion: need larger input region
    int padPixels = tceil(std::abs(radius));
    const TDimension &tileSize = outputTile.getRaster()->getSize();
    TRectD fullTileRect(outputTile.m_pos, TDimensionD(tileSize.lx, tileSize.ly));
    TRectD expandedRegion = fullTileRect.enlarge(padPixels);

    TDimension expandedSize(tround(expandedRegion.getLx()),
                            tround(expandedRegion.getLy()));

    TTile sourceTile;
    m_sourceInput->allocateAndCompute(sourceTile, expandedRegion.getP00(),
                                      expandedSize, outputTile.getRaster(),
                                      frame, renderInfo);

    const TRasterP &srcRaster = sourceTile.getRaster();
    TRop::erodilate(srcRaster, srcRaster, radius, maskType);

    // Copy back with negative offset to align with original tile position
    outputTile.getRaster()->copy(srcRaster, -TPoint(padPixels, padPixels));
  }
}

//-------------------------------------------------------------------
void ErodeDilateFx::doDryCompute(TRectD &regionOfInterest, double frame,
                                 const TRenderSettings &renderInfo) {
  if (!m_sourceInput.isConnected()) return;

  double radius = computeEffectiveRadius(frame, renderInfo);
  if (isDilation(radius)) {
    m_sourceInput->dryCompute(regionOfInterest, frame, renderInfo);
  } else {
    int padding = tceil(std::abs(radius));
    TRectD extendedRegion = regionOfInterest.enlarge(padding);
    m_sourceInput->dryCompute(extendedRegion, frame, renderInfo);
  }
}

//------------------------------------------------------------------
int ErodeDilateFx::getMemoryRequirement(const TRectD &rect, double frame,
                                        const TRenderSettings &info) {
  int baseMem = TRasterFx::memorySize(rect, 8); // One greymap per channel
  int extraMaps = (m_operationMode->getValue() == 0) ? 1 : 2;
  return extraMaps * baseMem;
}

