#include <vector>
using namespace std;

class Solution {
public:
    int minNumberOperations(vector<int>& target) {
        if (target.empty()) return 0;

        int totalOps = target[0];
        for (int i = 1; i < target.size(); ++i) {
            int diff = target[i] - target[i-1];
            if (diff > 0) {
                totalOps += diff;
            }
        }
        return totalOps;
    }
};

