#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, k;
    scanf("%d%d", &n, &k);

    vector<bool> seen(n + 1, false);
    int count = 0;

    for (int idx = 1; idx <= n; ++idx) {
        if (seen[idx]) continue;

        count++;

        // Reset memory
        printf("R\n");
        fflush(stdout);

        // Ask about element idx
        printf("? %d\n", idx);
        fflush(stdout);

        char answer;
        scanf(" %c", &answer);  // response not used

        // Check remaining elements for equivalence
        for (int other = idx + 1; other <= n; ++other) {
            if (seen[other]) continue;

            printf("? %d\n", other);
            fflush(stdout);
            scanf(" %c", &answer);

            if (answer == 'Y') {
                seen[other] = true;
            }
        }

        seen[idx] = true;
    }

    printf("! %d\n", count);
    fflush(stdout);

    return 0;
}

