	if (DevImpl->register_change_handler(this, &FDisplayClusterVrpnKeyboardInputDevice::OnButtonEvent) != 0)
	{
		UE_LOG(LogDisplayClusterInputVRPN, Error, TEXT("%s - failed to register VRPN event handler"), *ToString());
		return false;
