// Internal handling
////////////////////////////////////////////////////////////////////////////////////////////////

void VRPN_CALLBACK FDisplayClusterVrpnKeyboardInputDevice::OnButtonEvent(void* Context, vrpn_BUTTONCB const* Event)
{
	FDisplayClusterVrpnKeyboardInputDevice* Device = static_cast<FDisplayClusterVrpnKeyboardInputDevice*>(Context);

	int32 ButtonIndex = Event->button;
	FButtonState* StatePtr = Device->DeviceData.Find(ButtonIndex);
	if (!StatePtr)
	{
		StatePtr = &Device->DeviceData.Emplace(ButtonIndex);
		StatePtr->PreviousState = false;
	}

	// Note: In rare cases, a button may toggle multiple times per frame (e.g., due to noise).
	// We only record the final observed value at update time — acceptable for typical user input.
	const bool bIsPressed = (Event->state != 0);
	StatePtr->CurrentState = bIsPressed;

	UE_LOG(LogDisplayClusterInputVRPN, VeryVerbose, TEXT("Keyboard %s:%d - %d"), *Device->GetId(), ButtonIndex, Event->state);
}

