namespace {
    // Represents a cue point: position in frames and unique identifier
    struct CuePoint {
        CuePoint(int framePos, int uniqueId) : mFrame(framePos), mID(uniqueId) {}
        int mFrame; // offset 0x0, size 0x4
        int mID;    // offset 0x4, size 0x4
    };

    // Represents a label: name string and associated ID
    struct Label {
        Label(const String &name, int id) : mName(name), mID(id) {}
        class String mName; // offset 0x0, size 0xC
        int mID;            // offset 0xC, size 0x4
    };

    // Comparison function for sorting cue points by frame number
    bool CompareCuePoints(const CuePoint &first, const CuePoint &second) {
        return first.mFrame < second.mFrame;
    }
}

WaveFile::WaveFile(BinStream &bs) : mMarkers(), mRiffList(bs, true) {
    ReadFormat();
    ReadMarkers();
    ReadNumSamples();
}

WaveFile::~WaveFile() {}

void WaveFile::ReadFormat() {
    mRiffList.Reset();
    ChunkHeader *fmtChunk = static_cast<ChunkHeader*>(mRiffList.Next(kWaveFormatChunkID));
    MILO_ASSERT(fmtChunk != nullptr, 0x6e);

    IDataChunk formatData(mRiffList);
    formatData >> mFormat;
    formatData >> mNumChannels;
    formatData >> mSamplesPerSec;
    formatData >> mAvgBytesPerSec;
    formatData >> mBlockAlign;
    formatData >> mBitsPerSample;

    // Validate consistency of audio parameters
    MILO_ASSERT(mAvgBytesPerSec == mSamplesPerSec * mBlockAlign, 0x78);
    MILO_ASSERT(mBlockAlign == mNumChannels * (mBitsPerSample / 8), 0x79);
}

void WaveFile::ReadMarkers() {
    std::vector<CuePoint> cuePoints;
    std::vector<Label> labels;

    mRiffList.Reset();

    // Early exit if no cue chunk present
    if (!mRiffList.Next(kWaveCueChunkID)) {
        return;
    }

    int totalCueCount = 0;
    {
        IDataChunk cueChunk(mRiffList);
        cueChunk >> totalCueCount;

        int idx = 0;
        while (idx < totalCueCount) {
            int id, frame;
            cueChunk >> id >> frame;
            cuePoints.emplace_back(frame, id);
            cueChunk.Seek(0x10, BinStream::kSeekCur); // skip padding
            ++idx;
        }
    }

    if (totalCueCount == 0) {
        return;
    }

    mRiffList.Reset();

    // Attempt to read label data from additional chunk
    if (mRiffList.Next(kWaveAdditionalChunkID)) {
        IListChunk listChunk(mRiffList);
        int labelIdx = 0;
        while (labelIdx < totalCueCount) {
            listChunk.Next(kWaveLabelChunkID);
            IDataChunk labelData(listChunk);
            ChunkHeader *hdr = labelData.Header();
            int strLen = hdr->Length() - sizeof(int); // subtract ID field size

            int labelId;
            labelData >> labelId;

            String name;
            name.reserve(strLen);
            for (int i = 0; i < strLen; ++i) {
                char c;
                labelData >> c;
                name.push_back(c);
            }

            labels.emplace_back(name, labelId);
            ++labelIdx;
        }
    }

    // Sort cue points by frame number
    std::sort(cuePoints.begin(), cuePoints.end(), CompareCuePoints);

    // Match each sorted cue point with its corresponding label (if any)
    int markerIdx = 0;
    while (markerIdx < totalCueCount) {
        const CuePoint &cp = cuePoints[markerIdx];
        String matchedName;

        for (const auto &lbl : labels) {
            if (lbl.mID == cp.mID) {
                matchedName = lbl.mName;
                break;
            }
        }

        mMarkers.emplace_back(cp.mFrame, cp.mID, matchedName);
        ++markerIdx;
    }
}

void WaveFile::ReadNumSamples() {
    mRiffList.Reset();
    ChunkHeader *dataChunk = static_cast<ChunkHeader*>(mRiffList.Next(kWaveDataChunkID));
    MILO_ASSERT(dataChunk != nullptr, 0xEA);

    mNumSamples = dataChunk->Length() / mBlockAlign;
}

IListChunk &WaveFile::PrepareToProvideData() {
    mRiffList.Reset();
    ChunkHeader *dataChunk = static_cast<ChunkHeader*>(mRiffList.Next(kWaveDataChunkID));
    MILO_ASSERT(dataChunk != nullptr, 0x17e);
    return mRiffList;
}

WaveFileData::WaveFileData(WaveFile &wf)
    : IDataChunk(wf.PrepareToProvideData()), mWaveFile(wf) {}

WaveFileData::~WaveFileData() {}

