#include <errno.h>
#include <sys/ipc.h>
#include <sys/shm.h>

// Redefine region and context descriptors with alternative structure
#define GND (-1)        // null index

// Extended region descriptor with additional metadata for tracking
typedef struct {
    char    name [ESM_MAX_NAME];    // region name
    int     offset;                 // pointer to region relative to beginning of page
    int     pagenum;                // page number [0..ESM_MAX_PAGES]
    int     size;                   // actual size in bytes
    int     next;                   // linked-list pointer
    int     prev;                   // linked-list pointer
    int     flags;                  // additional status flags
} RD;

// Page descriptor with extended information
typedef struct {
    int     shmid;                  // UNIX shared memory ID
    int     size;                   // actual size in bytes
    int     usage_count;            // track how many regions use this page
} PD;

// Context descriptor with reordered fields for better cache locality
typedef struct {
    int     magic;                  // for utility to list all ESM contexts
    int     contextid;              // context id
    int     mutex;                  // mutual exclusion semaphore
    int     nregions;               // number of allocated regions
    int     npages;                 // number of pages
    int     pagesize;               // shared memory page size in 1K blocks
    RD      region [ESM_MAX_REGIONS];
    PD      page [ESM_MAX_PAGES];
    int     rdlist;                 // head of allocated region descriptors
    int     rdempty;                // head of empty regions (holes)
    int     rdfree;                 // head of free region descriptors
} CD;

// Semaphore operation structures
static struct sembuf Psem = { 0, -1, 0 };
static struct sembuf Vsem = { 0,  1, 0 };

// Semaphore macros with improved error handling
#define P(S,E)  { \
    if (semop ((S), &Psem, 1) != 0) { \
        SetError (thid, "Semaphore P-operation on %d fails: %s", (S), strerror (errno)); \
        return (E); \
    } \
}

#define V(S,E)  { \
    if (semop ((S), &Vsem, 1) != 0) { \
        SetError (thid, "Semaphore V-operation on %d fails: %s", (S), strerror (errno)); \
        return (E); \
    } \
}

// Memory management macros
#define DETACH(I,E)  { \
    if (shmdt ((I))) { \
        SetError (thid, "Cannot detach shared memory segment: %s", strerror (errno)); \
        return (E); \
    } \
}

#define DESTROY(I,E)  { \
    struct shmid_ds buf; \
    if (shmctl ((I), IPC_RMID, &buf) != 0) { \
        SetError (thid, "Cannot destroy shared memory segment: %s", strerror (errno)); \
        return (E); \
    } \
}

// Address calculation macro with explicit type casting
#define LOCALADDRESS(B,A) ( \
    (void *)(((char *)(B)) + (size_t)(A)) \
)

// Internal function declarations
static int AttachContext(int thid, int contextid);
static void PrintContextSegmentInfo(struct shmid_ds *segment, CD *cd, FILE *output);
static int AcquireRegionSlot(RD regions[], int *freehead);
static void ReleaseRegionSlot(RD regions[], int *freehead, int index);
static int FindRegionByName(RD regions[], int *head, const char *name);
static int FindHoleBySize(RD regions[], int *head, int required_size);
static void AddRegionToList(RD regions[], int *listhead, int newreg);
static void AddHoleToList(RD regions[], int *listhead, int newreg);
static void RemoveFromList(RD regions[], int *head, int index);

// Helper function to initialize region descriptor
static void InitializeRegionDescriptor(RD *rd) {
    memset((void *)rd, 0, sizeof(RD));
    rd->prev = GND;
    rd->next = GND;
    rd->flags = 0;
}

int ESM_Shared_Create(int thid, int pagesize) {
    // Check context limit
    if (NumContexts >= ESM_MAX_CONTEXTS) {
        SetError(thid, "Too many contexts (%d) for process; ESM_Create fails", ESM_MAX_CONTEXTS);
        return 0;
    }

    int ci = NumContexts++;

    // Create shared memory for context descriptor
    int contextid = shmget(IPC_PRIVATE, sizeof(CD), IPC_CREAT | SHM_R | SHM_W);
    if (contextid < 0) {
        SetError(thid, "Cannot create context descriptor segment in ESM_Create: %s", strerror(errno));
        return 0;
    }

    // Ensure non-zero context ID
    if (contextid == 0) {
        int newcontextid = shmget(IPC_PRIVATE, sizeof(CD), IPC_CREAT | SHM_R | SHM_W);
        if (newcontextid < 0) {
            SetError(thid, "Cannot create second non-zero context descriptor segment in ESM_Create: %s", strerror(errno));
            return 0;
        }
        DESTROY(contextid, ESM_ERROR);
        contextid = newcontextid;
    }

    // Attach context descriptor temporarily
    CD *cd = (CD *)shmat(contextid, NULL, 0);
    if ((long)cd == -1) {
        SetError(thid, "Cannot attach context descriptor segment in ESM_Create: %s", strerror(errno));
        DESTROY(contextid, 0);
        return 0;
    }

    // Create semaphore for synchronization
    int semid = semget(IPC_PRIVATE, 1, IPC_CREAT | SEM_A | SEM_R);
    if (semid < 0) {
        SetError(thid, "Cannot create context descriptor mutex semaphore in ESM_Create: %s", strerror(errno));
        DESTROY(contextid, 0);
        return 0;
    }

    // Initialize context descriptor
    cd->magic       = ESM_MAGIC;
    cd->contextid   = contextid;
    cd->pagesize    = pagesize;
    cd->npages      = 0;
    cd->nregions    = 0;
    cd->mutex       = semid;
    V(cd->mutex, 0);

    // Initialize region descriptors
    for (int i = 0; i < ESM_MAX_REGIONS; i++) {
        InitializeRegionDescriptor(&cd->region[i]);
        cd->region[i].prev = i-1;
        cd->region[i].next = i+1;
    }

    cd->region[0].prev = GND;
    cd->region[ESM_MAX_REGIONS-1].next = GND;
    cd->rdfree = 0;
    cd->rdlist = GND;
    cd->rdempty = GND;

    // Initialize page table
    for (int pi = 0; pi < ESM_MAX_PAGES; pi++) {
        PD *pd = &cd->page[pi];
        memset((void *)pd, 0, sizeof(PD));
        pd->usage_count = 0;
        Contexts[ci].pageaddr[pi] = NULL;
    }

    // Update process context table
    Contexts[ci].contextid = contextid;
    Contexts[ci].cd = cd;
    Contexts[ci].nattached = 0;

    return contextid;
}

int ESM_Shared_Delete(int thid, int ci, int contextid) {
    // Attach context if not already attached
    if (ci < 0) {
        ci = AttachContext(thid, contextid);
        if (ci < 0)
            return ESM_ERROR;
    }

    CD *cd = (CD *)Contexts[ci].cd;
    P(cd->mutex, ESM_ERROR);

    // Destroy all data pages
    for (int pi = 0; pi < cd->npages; pi++) {
        DETACH(Contexts[ci].pageaddr[pi], ESM_ERROR);
        DESTROY(cd->page[pi].shmid, ESM_ERROR);
    }

    // Destroy semaphore
    if (semctl(cd->mutex, 0, IPC_RMID) != 0) {
        SetError(thid, "Cannot remove semaphore (%d) associated with context descriptor (%d): %s",
                        cd->mutex,
                        contextid,
                        strerror(errno));
        return ESM_ERROR;
    }

    // Destroy context descriptor
    DETACH(cd, ESM_ERROR);
    DESTROY(contextid, ESM_ERROR);

    // Clear local context table entry
    Contexts[ci].contextid = 0;
    Contexts[ci].cd = NULL;
    Contexts[ci].nattached = 0;

    return ESM_OK;
}

void *ESM_Shared_Alloc(int thid, int ci, int contextid, const char *name, size_t size) {
    // Attach context if needed
    if (ci < 0) {
        ci = AttachContext(thid, contextid);
        if (ci < 0)
            return NULL;
    }

    CD *cd = (CD *)Contexts[ci].cd;
    P(cd->mutex, NULL);

    // Check if region already exists
    int reg = FindRegionByName(cd->region, &cd->rdlist, name);
    if (reg != GND) {
        // Region found
        if (size == 0 || size == (size_t)cd->region[reg].size) {
            void *paddr = Contexts[ci].pageaddr[cd->region[reg].pagenum];
            if (paddr == NULL) {
                V(cd->mutex, NULL);
                return NULL;
            } else {
                V(cd->mutex, NULL);
                return LOCALADDRESS(paddr, cd->region[reg].offset);
            }
        } else {
            V(cd->mutex, NULL);
            return NULL;
        }
    }

    // Region not found, need to allocate
    if (size <= 0) {
        V(cd->mutex, NULL);
        return NULL;
    }

    // Find suitable hole
    int hole = FindHoleBySize(cd->region, &cd->rdempty, (int)size);

    if (hole == GND) {
        // No suitable hole, create new page
        if (cd->npages == ESM_MAX_PAGES) {
            SetError(thid, "Page limit has been reached; try increasing page size");
            V(cd->mutex, NULL);
            return NULL;
        }

        hole = AcquireRegionSlot(cd->region, &cd->rdfree);
        if (hole == GND) {
            SetError(thid, "Region descriptors have been exhausted; cannot make hole");
            V(cd->mutex, NULL);
            return NULL;
        }

        int pi = cd->npages++;
        cd->page[pi].size = (int)max(size, 1024 * cd->pagesize);
        cd->page[pi].shmid = shmget(IPC_PRIVATE, cd->page[pi].size, IPC_CREAT | SHM_R | SHM_W);

        if (cd->page[pi].shmid <= 0) {
            SetError(thid, "Cannot create new page in ESM_Alloc: %s", strerror(errno));
            cd->npages--;
            V(cd->mutex, NULL);
            return NULL;
        }

        void *pageaddr = shmat(cd->page[pi].shmid, NULL, 0);
        if ((long)pageaddr == -1) {
            SetError(thid, "Cannot attach new page in ESM_Alloc: %s", strerror(errno));
            DESTROY(cd->page[pi].shmid, NULL);
            cd->npages--;
            V(cd->mutex, NULL);
            return NULL;
        }

        Contexts[ci].pageaddr[pi] = pageaddr;
        Contexts[ci].nattached++;
        cd->region[hole].pagenum = pi;
        cd->region[hole].offset = 0;
        cd->region[hole].size = cd->page[pi].size;
    } else {
        RemoveFromList(cd->region, &cd->rdempty, hole);
    }

    // Split hole and allocate region
    int newreg = AcquireRegionSlot(cd->region, &cd->rdfree);
    if (newreg == GND) {
        SetError(thid, "Region descriptors have been exhausted");
        V(cd->mutex, NULL);
        return NULL;
    }

    strncpy(cd->region[newreg].name, name, ESM_MAX_NAME - 1);
    cd->region[newreg].name[ESM_MAX_NAME - 1] = '\0';
    cd->region[newreg].size = (int)size;
    cd->region[newreg].pagenum = cd->region[hole].pagenum;
    cd->region[newreg].offset = cd->region[hole].offset;

    AddRegionToList(cd->region, &cd->rdlist, newreg);
    cd->nregions++;

    if ((cd->region[hole].size -= (int)size) > 0) {
        cd->region[hole].offset += (int)size;
        AddHoleToList(cd->region, &cd->rdempty, hole);
    } else {
        ReleaseRegionSlot(cd->region, &cd->rdfree, hole);
    }

    // Zero memory and return address
    void *addr = LOCALADDRESS(
        Contexts[ci].pageaddr[cd->region[newreg].pagenum],
        cd->region[newreg].offset
    );
    memset(addr, 0, size);
    V(cd->mutex, NULL);
    return addr;
}

int ESM_Shared_Free(int thid, int ci, int contextid, const char *name) {
    // Attach context if needed
    if (ci < 0) {
        ci = AttachContext(thid, contextid);
        if (ci < 0)
            return ESM_ERROR;
    }

    CD *cd = (CD *)Contexts[ci].cd;
    P(cd->mutex, ESM_ERROR);

    // Find region by name
    int reg = FindRegionByName(cd->region, &cd->rdlist, name);
    if (reg == GND) {
        SetError(thid, "Cannot find region \"%s\" in ESM_Free", name);
        V(cd->mutex, ESM_ERROR);
        return ESM_ERROR;
    }

    // Move region to holes list
    RemoveFromList(cd->region, &cd->rdlist, reg);
    memset((void *)cd->region[reg].name, 0, ESM_MAX_NAME);
    AddHoleToList(cd->region, &cd->rdempty, reg);
    cd->nregions--;

    // Coalesce adjacent holes
    // First pass: look for holes after current hole
    for (int r = cd->rdempty; r != GND; r = cd->region[r].next) {
        if (cd->region[r].pagenum != cd->region[reg].pagenum)
            continue;
        if (cd->region[reg].offset + cd->region[reg].size != cd->region[r].offset)
            continue;

        cd->region[reg].size += cd->region[r].size;
        RemoveFromList(cd->region, &cd->rdempty, r);
        RemoveFromList(cd->region, &cd->rdempty, reg);
        ReleaseRegionSlot(cd->region, &cd->rdfree, r);
        AddHoleToList(cd->region, &cd->rdempty, reg);
        break;
    }

    // Second pass: look for holes before current hole
    for (int r = cd->rdempty; r != GND; r = cd->region[r].next) {
        if (cd->region[r].pagenum != cd->region[reg].pagenum)
            continue;
        if (cd->region[r].offset + cd->region[r].size != cd->region[reg].offset)
            continue;

        cd->region[r].size += cd->region[reg].size;
        RemoveFromList(cd->region, &cd->rdempty, r);
        RemoveFromList(cd->region, &cd->rdempty, reg);
        ReleaseRegionSlot(cd->region, &cd->rdfree, reg);
        AddHoleToList(cd->region, &cd->rdempty, r);
        break;
    }

    V(cd->mutex, ESM_ERROR);
    return ESM_OK;
}

