using Scalar = double;

// Custom loss function: linear objective with parameters from sampler
template<typename Real>
class PortfolioLoss : public ROL::StdObjective<Real> {
public:
  Real value(const std::vector<Real>& weights, Real& /*tol*/) override {
    auto params = getParameter();
    return std::inner_product(weights.begin(), weights.end(), params.begin(), static_cast<Real>(0));
  }

  void gradient(std::vector<Real>& grad, const std::vector<Real>& /*weights*/, Real& /*tol*/) override {
    grad.assign(getParameter().begin(), getParameter().end());
  }

  void hessVec(std::vector<Real>& hv, const std::vector<Real>& /*v*/, const std::vector<Real>& /*x*/, Real& /*tol*/) override {
    std::fill(hv.begin(), hv.end(), static_cast<Real>(0));
  }
};

// Budget constraint: sum of weights equals 1
template<typename Real>
class WeightBudget : public ROL::StdConstraint<Real> {
public:
  void value(std::vector<Real>& c, const std::vector<Real>& x, Real& /*tol*/) override {
    Real total = std::accumulate(x.begin(), x.end(), static_cast<Real>(0));
    c[0] = total - static_cast<Real>(1);
  }

  void applyJacobian(std::vector<Real>& jv, const std::vector<Real>& v, const std::vector<Real>& /*x*/, Real& /*tol*/) override {
    jv[0] = std::accumulate(v.begin(), v.end(), static_cast<Real>(0));
  }

  void applyAdjointJacobian(std::vector<Real>& ajv, const std::vector<Real>& v, const std::vector<Real>& /*x*/, Real& /*tol*/) override {
    std::fill(ajv.begin(), ajv.end(), v[0]);
  }

  void applyAdjointHessian(std::vector<Real>& ahuv, const std::vector<Real>& /*u*/, const std::vector<Real>& /*v*/, const std::vector<Real>& /*x*/, Real& /*tol*/) override {
    std::fill(ahuv.begin(), ahuv.end(), static_cast<Real>(0));
  }
};

void displayResults(const std::vector<Scalar>& solution,
                    std::ostream& os) {
  size_t n = solution.size();
  os << "\nSolution vector:\n";
  os << "[ ";
  for (size_t i = 0; i < n - 1; ++i) {
    os << solution[i] << ", ";
  }
  os << solution[n - 1] << " ]\n\n";
}

int main(int argc, char* argv[]) {
  // Initialize MPI session
  ROL::GlobalMPISession mpiSession(&argc, &argv);

  // Control output verbosity based on command-line arguments
  int verboseLevel = argc - 1;
  bool verbose = verboseLevel > 0;
  ROL::Ptr<std::ostream> outputStream;
  ROL::nullstream dummyStream;

  if (verbose)
    outputStream = ROL::makePtrFromRef(std::cout);
  else
    outputStream = ROL::makePtrFromRef(dummyStream);

  int statusFlag = 0;

  try {
    // Load parameter list from XML file
    std::string configPath = "input_16.xml";
    auto paramListPtr = ROL::getParametersFromXmlFile(configPath);
    ROL::ParameterList globalParams = *paramListPtr;
    globalParams.sublist("General").set("Output Level", verbose ? 1 : 0);

    // Define problem dimensions and initial guess
    size_t numAssets = 10;
    ROL::Ptr<ROL::StdVector<Scalar>>
      currentWeights = ROL::makePtr<ROL::StdVector<Scalar>>(numAssets, 0.0);

    // Generate random bounds for each asset
    int sampleCount = 1000;
    Scalar offset = 0.0;
    std::vector<std::vector<Scalar>> assetBounds;

    for (size_t idx = 0; idx < numAssets; ++idx) {
      Scalar lower = -static_cast<Scalar>(rand()) / static_cast<Scalar>(RAND_MAX);
      Scalar upper =  static_cast<Scalar>(rand()) / static_cast<Scalar>(RAND_MAX);
      assetBounds.emplace_back(std::initializer_list<Scalar>{lower, upper});
      *outputStream << "Asset " << idx << ": Lower=" << lower << ", Upper=" << upper << "\n";
      offset += upper / static_cast<Scalar>(numAssets);
    }
    offset *= static_cast<Scalar>(0.35);

    // Setup sampling infrastructure
    ROL::Ptr<ROL::BatchManager<Scalar>>
      batchMgr = ROL::makePtr<ROL::BatchManager<Scalar>>();
    ROL::Ptr<ROL::SampleGenerator<Scalar>>
      mcSampler = ROL::makePtr<ROL::MonteCarloGenerator<Scalar>>(sampleCount, assetBounds, batchMgr);

    // Build components of optimization problem
    ROL::Ptr<ROL::Objective<Scalar>>
      objFunc = ROL::makePtr<PortfolioLoss<Scalar>>();
    objFunc->setParameter(mcSampler->getMyPoint(0));

    ROL::Ptr<ROL::Constraint<Scalar>>
      objAsConstr = ROL::makePtr<ROL::ConstraintFromObjective<Scalar>>(objFunc);
    ROL::Ptr<ROL::SingletonVector<Scalar>>
      multiplierObj = ROL::makePtr<ROL::SingletonVector<Scalar>>(0),
      upperBoundObj = ROL::makePtr<ROL::SingletonVector<Scalar>>(offset);
    ROL::Ptr<ROL::BoundConstraint<Scalar>>
      boundObj = ROL::makePtr<ROL::Bounds<Scalar>>(*upperBoundObj, false);

    ROL::Ptr<ROL::Constraint<Scalar>>
      budgetConstr = ROL::makePtr<WeightBudget<Scalar>>();
    ROL::Ptr<ROL::StdVector<Scalar>>
      multiplierBudget = ROL::makePtr<ROL::StdVector<Scalar>>(1, 0.0);

    // Construct stochastic optimization problem
    ROL::Ptr<ROL::StochasticProblem<Scalar>>
      optProblem = ROL::makePtr<ROL::StochasticProblem<Scalar>>(objFunc, currentWeights);
    optProblem->addLinearConstraint("Budget", budgetConstr, multiplierBudget);
    optProblem->addLinearConstraint("Loss", objAsConstr, multiplierObj, boundObj);

    // Finalize and verify deterministic setup
    optProblem->finalize(false, true, *outputStream);
    optProblem->check(true, *outputStream);

    std::vector<std::pair<std::string, std::vector<Scalar>>> results;

    // First scenario: Risk-neutral variance minimization
    optProblem->edit();
    ROL::ParameterList objParams;
    objParams.sublist("SOL").sublist("Objective").set("Type", "Deviation");
    objParams.sublist("SOL").sublist("Objective").sublist("Deviation Measure").set("Name", "Variance");
    optProblem->makeObjectiveStochastic(objParams, mcSampler);

    ROL::ParameterList conParams;
    conParams.sublist("SOL").sublist("Loss").set("Type", "Risk Neutral");
    optProblem->makeLinearConstraintStochastic("Loss", conParams, mcSampler, batchMgr);

    optProblem->finalize(false, true, *outputStream);
    optProblem->check(true, *outputStream);

    auto solver1 = ROL::makePtr<ROL::Solver<Scalar>>(optProblem, globalParams);
    solver1->solve(*outputStream);
    statusFlag += (solver1->getAlgorithmState()->statusFlag == ROL::EXITSTATUS_CONVERGED ? 0 : 1);
    displayResults(*currentWeights->getVector(), *outputStream);

    ROL::Ptr<ROL::Vector<Scalar>> savedWeights = currentWeights->clone();
    savedWeights->set(*currentWeights);
    results.emplace_back("Risk Neutral", *currentWeights->getVector());

    // Second scenario: Mean-value constraint
    optProblem->edit();
    optProblem->resetStochasticLinearConstraint("Loss");
    conParams.sublist("SOL").sublist("Loss").set("Type", "Mean Value");
    optProblem->makeLinearConstraintStochastic("Loss", conParams, mcSampler);

    optProblem->finalize(false, true, *outputStream);
    optProblem->check(true, *outputStream);

    auto solver2 = ROL::makePtr<ROL::Solver<Scalar>>(optProblem, globalParams);
    solver2->solve(*outputStream);
    statusFlag += (solver2->getAlgorithmState()->statusFlag == ROL::EXITSTATUS_CONVERGED ? 0 : 1);
    displayResults(*currentWeights->getVector(), *outputStream);

    savedWeights->axpy(-1.0, *currentWeights);
    statusFlag += (savedWeights->norm() > 100.0 * std::sqrt(ROL::ROL_EPSILON<Scalar>()) ? 1 : 0);
    results.emplace_back("Mean Value", *currentWeights->getVector());

    // Third scenario: CVaR-based risk-averse formulation
    optProblem->edit();
    conParams.sublist("SOL").sublist("Loss").set("Type", "Risk Averse");
    conParams.sublist("SOL").sublist("Loss").sublist("Risk Measure").set("Name", "CVaR");
    conParams.sublist("SOL").sublist("Loss").sublist("Risk Measure").sublist("CVaR").set("Confidence Level", 0.95);
    conParams.sublist("SOL").sublist("Loss").sublist("Risk Measure").sublist("CVaR").set("Convex Combination Parameter", 1.0);
    conParams.sublist("SOL").sublist("Loss").sublist("Risk Measure").sublist("CVaR").set("Smoothing Parameter", 1e-4);
    conParams.sublist("SOL").sublist("Loss").sublist("Risk Measure").sublist("CVaR").set("Distribution Name", "Parabolic");
    conParams.sublist("SOL").sublist("Loss").sublist("Risk Measure").sublist("CVaR").sublist("Distribution").set("Lower Bound", -0.5);
    conParams.sublist("SOL").sublist("Loss").sublist("Risk Measure").sublist("CVaR").sublist("Distribution").set("Upper Bound", 0.5);

    optProblem->removeLinearConstraint("Loss");
    optProblem->addConstraint("Loss", objAsConstr, multiplierObj, boundObj);
    optProblem->makeConstraintStochastic("Loss", conParams, mcSampler);

    optProblem->finalize(false, true, *outputStream);
    optProblem->check(true, *outputStream);

    auto solver3 = ROL::makePtr<ROL::Solver<Scalar>>(optProblem, globalParams);
    solver3->solve(*outputStream);
    statusFlag += (solver3->getAlgorithmState()->statusFlag == ROL::EXITSTATUS_CONVERGED ? 0 : 1);
    displayResults(*currentWeights->getVector(), *outputStream);
    results.emplace_back("bPOE", *currentWeights->getVector());

    // Output final comparison table
    *outputStream << std::scientific << std::setprecision(6);
    for (const auto& entry : results) {
      *outputStream << "  " << std::setw(20) << std::left << std::get<0>(entry);
      for (const auto& val : std::get<1>(entry))
        *outputStream << std::setw(18) << std::left << val;
      *outputStream << "\n";
    }
    *outputStream << "\n";

  } catch (const std::logic_error& e) {
    *outputStream << "Exception caught: " << e.what() << "\n";
    statusFlag = -1000;
  }

  if (statusFlag != 0)
    std::cout << "End Result: TEST FAILED\n";
  else
    std::cout << "End Result: TEST PASSED\n";

  return 0;
}

