    sensor_->read();
}

int QMC5883LCompassAdapter::fetchRawHeading() {
    return sensor_->getAzimuth();
}

int QMC5883LCompassAdapter::fetchFilteredHeading() {
    int currentReading = sensor_->getAzimuth();
    filteredAzimuth_ = static_cast<int>(
        (smoothingFactor_ * currentReading) + 
        ((1.0f - smoothingFactor_) * filteredAzimuth_)
    );
    return filteredAzimuth_;
}

