// MEX interface
#include "mex.h"

void mexFunction(int nlhs, mxArray *plhs[], int nrhs, const mxArray *prhs[])
{
    // Input pointer for extracting handle to arg struct
    long long *handle_ptr;

    // Process right-hand side inputs
    handle_ptr = mxGetData(prhs[0]);
    struct d_ocp_qcqp_ipm_arg *arg = reinterpret_cast<struct d_ocp_qcqp_ipm_arg*>(*handle_ptr);

    // Extract field name as C-string
    char *field_name = mxArrayToString(prhs[1]);

    // Check if the field corresponds to integer parameters
    bool is_integer_param = 
        (0 == strcmp(field_name, "iter_max"))  ||
        (0 == strcmp(field_name, "warm_start")) ||
        (0 == strcmp(field_name, "pred_corr"))  ||
        (0 == strcmp(field_name, "ric_alg"));

    if (is_integer_param)
    {
        // Get scalar integer value from MATLAB array
        double scalar_val = mxGetScalar(prhs[2]);
        int int_value = static_cast<int>(scalar_val);
        d_ocp_qcqp_ipm_arg_set(field_name, &int_value, arg);
    }
    else
    {
        // Assume real (double) value
        double *real_value = mxGetData(prhs[2]);
        d_ocp_qcqp_ipm_arg_set(field_name, real_value, arg);
    }

    // Free allocated string from mxArrayToString
    mxFree(field_name);

    return;
}

#include <vector>

class Solution {
public:
    std::vector<std::vector<int>> generate(int numRows) {
        std::vector<std::vector<int>> triangle;

        if (numRows == 0) return triangle;

        // Initialize first row
        triangle.push_back({1});

        // Generate remaining rows
        for (int row = 1; row < numRows; ++row) {
            std::vector<int> currentRow;

            // First element is always 1
            currentRow.push_back(1);

            // Calculate middle elements by summing adjacent elements from previous row
            const std::vector<int>& prevRow = triangle[row - 1];
            for (int col = 1; col < static_cast<int>(prevRow.size()); ++col) {
                currentRow.push_back(prevRow[col - 1] + prevRow[col]);
            }

            // Last element is always 1
            currentRow.push_back(1);

            triangle.push_back(currentRow);
        }

        return triangle;
    }
};

