#ifndef H5_NO_DEPRECATED_SYMBOLS

// Register a new property in a property list class (legacy API)
herr_t
H5Pregister1(hid_t cls_id, const char *name, size_t prop_size, void *default_value,
    H5P_prp_create_func_t create_cb, H5P_prp_set_func_t set_cb,
    H5P_prp_get_func_t get_cb, H5P_prp_delete_func_t delete_cb,
    H5P_prp_copy_func_t copy_cb, H5P_prp_close_func_t close_cb)
{
    H5P_genclass_t *prop_class;         /* Property list class to modify */
    H5P_genclass_t *original_class;     /* Original property class reference */
    herr_t result_status;               /* Return value */

    FUNC_ENTER_API(FAIL)
    H5TRACE10("e", "i*sz*xxxxxxx", cls_id, name, prop_size, default_value, create_cb,
             set_cb, get_cb, delete_cb, copy_cb, close_cb);

    /* Validate input parameters */
    if(NULL == (prop_class = (H5P_genclass_t *)H5I_object_verify(cls_id, H5I_GENPROP_CLS)))
        HGOTO_ERROR(H5E_ARGS, H5E_BADTYPE, FAIL, "not a property list class");
    if(!name || !*name)
        HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, FAIL, "invalid property name");
    if(prop_size > 0 && default_value == NULL)
        HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, FAIL, "non-zero sized properties require default value");

    /* Store original class before modification */
    original_class = prop_class;

    /* Attempt to register the property */
    if((result_status = H5P_register(&prop_class, name, prop_size, default_value, 
                                     create_cb, set_cb, get_cb, delete_cb, copy_cb, NULL, close_cb)) < 0)
        HGOTO_ERROR(H5E_PLIST, H5E_CANTREGISTER, FAIL, "unable to register property in class");

    /* Handle class substitution if needed */
    if(prop_class != original_class) {
        H5P_genclass_t *previous_class; /* Previous class being replaced */

        /* Replace the class in the ID system */
        if(NULL == (previous_class = (H5P_genclass_t *)H5I_subst(cls_id, prop_class)))
            HGOTO_ERROR(H5E_PLIST, H5E_CANTSET, FAIL, "unable to substitute property class in ID")

        HDassert(previous_class == original_class);

        /* Close the old class */
        if(H5P_close_class(original_class) < 0)
            HGOTO_ERROR(H5E_PLIST, H5E_CANTCLOSEOBJ, FAIL, "unable to close original property class after substitution")
    }

done:
    FUNC_LEAVE_API(result_status)
}   /* H5Pregister1() */

// Insert a temporary property into an existing property list (legacy API)
herr_t
H5Pinsert1(hid_t plist_id, const char *prop_name, size_t prop_size, void *initial_value,
    H5P_prp_set_func_t set_callback, H5P_prp_get_func_t get_callback,
    H5P_prp_delete_func_t delete_callback, H5P_prp_copy_func_t copy_callback,
    H5P_prp_close_func_t close_callback)
{
    H5P_genplist_t	*property_list;    /* Property list to modify */
    herr_t return_code;                 /* return value */

    FUNC_ENTER_API(FAIL)
    H5TRACE9("e", "i*sz*xxxxxx", plist_id, prop_name, prop_size, initial_value, 
             set_callback, get_callback, delete_callback, copy_callback, close_callback);

    /* Validate inputs */
    if(NULL == (property_list = (H5P_genplist_t *)H5I_object_verify(plist_id, H5I_GENPROP_LST)))
        HGOTO_ERROR(H5E_ARGS, H5E_BADTYPE, FAIL, "not a property list")
    if(!prop_name || !*prop_name)
        HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, FAIL, "invalid property name")
    if(prop_size > 0 && initial_value == NULL)
        HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, FAIL, "properties >0 size must have initial value")

    /* Insert the property into the list */
    if((return_code = H5P_insert(property_list, prop_name, prop_size, initial_value, 
                                  set_callback, get_callback, delete_callback, copy_callback, NULL, close_callback)) < 0)
        HGOTO_ERROR(H5E_PLIST, H5E_CANTREGISTER, FAIL, "unable to insert property in plist")

done:
    FUNC_LEAVE_API(return_code)
}   /* H5Pinsert1() */

#endif /* H5_NO_DEPRECATED_SYMBOLS */

#include "llvm/Transforms/Coroutines/CoroConditionalWrapper.h"
#include "CoroInternal.h"
#include "llvm/IR/Module.h"
using namespace llvm;

// Wrapper that conditionally executes the inner pass manager based on intrinsic presence
CoroConditionalWrapper::CoroConditionalWrapper(ModulePassManager &&PM)
    : innerPM(std::move(PM)) {}

PreservedAnalyses CoroConditionalWrapper::run(Module &M,
                                              ModuleAnalysisManager &AM) {
  // Skip execution if no coroutine intrinsics are declared in the module
  if (!coro::hasAnyCoroutineIntrinsics(M))
    return PreservedAnalyses::all();

  // Otherwise, delegate to the wrapped pass manager
  return innerPM.run(M, AM);
}

void CoroConditionalWrapper::printPipeline(
    raw_ostream &OS, function_ref<StringRef(StringRef)> MapClassName2PassName) {
  OS << "coro-conditional";
  OS << '(';
  innerPM.printPipeline(OS, MapClassName2PassName);
  OS << ')';
}

