#include "test/jemalloc_test.h"

TEST_BEGIN(test_sz_psz2ind_rewritten) {
	/*
	 * Verify page-sized size class mappings before the first regular group
	 * where all size classes are multiples of the page size.
	 * On x86_64 Linux, this covers 4096, 8192, 12288, and 16384,
	 * corresponding to indices 0 through 3.
	 */
	for (size_t group = 0; group < SC_NGROUP; group++) {
		for (size_t psz = group * PAGE + 1; psz <= (group + 1) * PAGE; psz++) {
			pszind_t index = sz_psz2ind(psz);
			expect_zu_eq(index, group,
			    "Expected index %zu for psz=%zu, got %u", group, psz, index);
		}
	}

	sc_data_t info;
	memset(&info, 0, sizeof(info));
	sc_data_init(&info);

	/*
	 * Determine the first regular size class whose size is at least the base
	 * page-multiple group start. For x86_64 Linux, this is 16384 bytes,
	 * located at global index 36.
	 */
	size_t start_psz = 1 << (SC_LG_NGROUP + LG_PAGE);
	size_t candidate_idx = 0;
	while (candidate_idx < SC_NSIZES &&
	    reg_size_compute(info.sc[candidate_idx].lg_base,
		info.sc[candidate_idx].lg_delta,
		info.sc[candidate_idx].ndelta) < start_psz) {
		candidate_idx++;
	}
	expect_zu_eq(
	    reg_size_compute(info.sc[candidate_idx].lg_base,
		info.sc[candidate_idx].lg_delta,
		info.sc[candidate_idx].ndelta),
	    start_psz, "Could not locate size class equal to %zu", start_psz);

	/*
	 * Examine subsequent size groups beyond the initial base region.
	 * To improve performance, step by PAGE/3 increments.
	 */
	size_t adjusted_idx = candidate_idx - SC_NGROUP;
	for (size_t psz = start_psz; psz <= 64 * 1024 * 1024; psz += PAGE / 3) {
		pszind_t idx = sz_psz2ind(psz);
		sc_t upper_bound_sc = info.sc[idx + adjusted_idx];
		expect_zu_gt(psz,
		    reg_size_compute(upper_bound_sc.lg_base,
			upper_bound_sc.lg_delta,
			upper_bound_sc.ndelta),
		    "psz=%zu mapped to idx=%u but exceeds upper bound", psz, idx);

		sc_t lower_bound_sc = info.sc[idx + adjusted_idx + 1];
		expect_zu_le(psz,
		    reg_size_compute(lower_bound_sc.lg_base,
			lower_bound_sc.lg_delta,
			lower_bound_sc.ndelta),
		    "psz=%zu mapped to idx=%u but below lower bound", psz, idx);
	}

	pszind_t final_idx = sz_psz2ind(SC_LARGE_MAXCLASS + 1);
	expect_lu_eq(final_idx, SC_NPSIZES,
	    "Expected final index %u for max+1, got %u", SC_NPSIZES, final_idx);
}
TEST_END

int main(void) {
	return test(test_sz_psz2ind_rewritten);
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <random>
#include <chrono>
using namespace std;

int main() {
    // Optimize I/O operations for speed
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    // Build adjacency list (1-indexed)
    vector<vector<int>> graph(n + 1);
    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        graph[u].push_back(v);
        graph[v].push_back(u);
    }

    // Best partition found: 0 or 1 for each vertex
    vector<int> best_partition(n + 1, 0);
    long long best_cut_value = -1;

    // Time budget management
    const double max_duration = 0.90; // seconds
    auto start = chrono::high_resolution_clock::now();

    // Random generator setup
    mt19937_64 rng(chrono::steady_clock::now().time_since_epoch().count());

    // Vertex ordering for local search
    vector<int> order(n);
    iota(order.begin(), order.end(), 1);

    // Current partition state
    vector<int> current(n + 1);

    // Repeated random restarts with local improvement
    while (true) {
        // Random initial assignment
        for (int i = 1; i <= n; ++i) {
            current[i] = rng() % 2;
        }

        // Local search: flip vertices that improve the cut
        bool changed = true;
        while (changed) {
            changed = false;
            shuffle(order.begin(), order.end(), rng);

            for (int node : order) {
                int same = 0, diff = 0;
                for (int neighbor : graph[node]) {
                    if (current[neighbor] == current[node]) {
                        ++same;
                    } else {
                        ++diff;
                    }
                }

                // Flip if more neighbors in own set
                if (same > diff) {
                    current[node] ^= 1;
                    changed = true;
                }
            }
        }

        // Evaluate current cut size
        long long cut_size = 0;
        for (int i = 1; i <= n; ++i) {
            if (current[i] == 0) {
                for (int j : graph[i]) {
                    if (current[j] == 1) {
                        ++cut_size;
                    }
                }
            }
        }

        // Update best solution if improved
        if (cut_size > best_cut_value) {
            best_cut_value = cut_size;
            best_partition = current;
        }

        // Check time limit
        auto now = chrono::high_resolution_clock::now();
        double elapsed = chrono::duration<double>(now - start).count();
        if (elapsed >= max_duration) break;
    }

    // Output final partition
    for (int i = 1; i <= n; ++i) {
        cout << best_partition[i];
        if (i < n) cout << ' ';
    }
    cout << '\n';

    return 0;
}

#include <iostream>
#include <array>
#include <string_view>
#include <magic_enum/magic_enum.hpp>
#include <magic_enum/magic_enum_iostream.hpp>

// Helper alias for underlying type
template <typename E>
using enum_underlying = magic_enum::underlying_type_t<E>;

// Generic function to convert enum to its integer representation
template <typename E>
auto to_int(E e) {
    return static_cast<enum_underlying<E>>(e);
}

// Generic function to get enum name as std::string_view
template <typename E>
std::string_view get_name(E e) {
    return magic_enum::enum_name(e);
}

// Generic function to cast from string (case-sensitive or not)
template <typename E>
auto parse_enum(std::string_view s, bool case_insensitive = false) {
    if (case_insensitive) {
        return magic_enum::enum_cast<E>(s, magic_enum::case_insensitive);
    }
    return magic_enum::enum_cast<E>(s);
}

// Generic function to cast from integer
template <typename E>
auto from_int(int val) {
    return magic_enum::enum_cast<E>(val);
}

// Custom bitwise OR for scoped enums (since magic_enum doesn't auto-enable this unless using namespace)
template <typename E>
E operator|(E lhs, E rhs) requires(magic_enum::is_scoped_enum_v<E>) {
    using U = enum_underlying<E>;
    return static_cast<E>(static_cast<U>(lhs) | static_cast<U>(rhs));
}

int main() {
    // Define enum type
    enum class Color : int { RED = -10, BLUE = 0, GREEN = 10 };

    // Example 1: Enum → name
    Color c1 = Color::RED;
    std::cout << get_name(c1) << '\n'; // RED

    // Example 2: All names
    constexpr auto color_names = magic_enum::enum_names<Color>();
    std::cout << "Color names:";
    for (const auto& name : color_names) {
        std::cout << ' ' << name;
    }
    std::cout << '\n';

    // Example 3: String → enum (case-sensitive & insensitive)
    auto parsed_blue = parse_enum<Color>("BLUE");
    if (parsed_blue.has_value()) {
        std::cout << "BLUE = " << to_int(parsed_blue.value()) << '\n'; // 0
    }

    auto parsed_blue_ci = parse_enum<Color>("blue", true);
    if (parsed_blue_ci.has_value()) {
        std::cout << "BLUE (case-insensitive) = " << to_int(parsed_blue_ci.value()) << '\n'; // 0
    }

    // Example 4: Integer → enum
    auto green_val = from_int<Color>(10);
    if (green_val.has_value()) {
        std::cout << "GREEN = " << magic_enum::enum_integer(green_val.value()) << '\n'; // 10
    }

    // Example 5: Enum → integer
    int red_int = magic_enum::enum_integer(Color::RED);
    std::cout << "RED = " << red_int << '\n'; // -10

    // Enable ostream operator for scoped enums
    using magic_enum::iostream_operators::operator<<;

    // Example 6: Output multiple enums via stream
    std::cout << "Colors: " << c1 << ' ' << parsed_blue_ci.value() << ' ' << green_val.value() << '\n';

    // Example 7: Count values
    std::cout << "Color enum size: " << magic_enum::enum_count<Color>() << '\n'; // 3

    // Example 8: Indexed access
    std::cout << "Color[0] = " << magic_enum::enum_value<Color>(0) << '\n'; // RED

    // Example 9: All values
    constexpr auto color_values = magic_enum::enum_values<Color>();
    std::cout << "Color values:";
    for (auto v : color_values) {
        std::cout << ' ' << v;
    }
    std::cout << '\n';

    // Example 10: Bitwise flags
    enum class Flags { A = 1, B = 2, C = 4, D = 8 };
    Flags flag = Flags::A | Flags::C;
    std::cout << flag << '\n'; // 5

    // Example 11: Unscoped vs scoped detection
    enum unscoped { red, green, blue };
    static_assert(magic_enum::is_unscoped_enum_v<unscoped>);
    static_assert(!magic_enum::is_unscoped_enum_v<Color>);
    static_assert(!magic_enum::is_unscoped_enum_v<Flags>);

    static_assert(!magic_enum::is_scoped_enum_v<unscoped>);
    static_assert(magic_enum::is_scoped_enum_v<Color>);
    static_assert(magic_enum::is_scoped_enum_v<Flags>);

    // Example 12: Entries (value-name pairs)
    constexpr auto color_entries = magic_enum::enum_entries<Color>();
    std::cout << "Color entries:";
    for (const auto& [val, name] : color_entries) {
        std::cout << ' ' << name << " = " << to_int(val);
    }
    std::cout << '\n';

    return 0;
}

