#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int q;
    if (!(cin >> q)) return 0;

    vector<unsigned long long> queries(q);
    for (int i = 0; i < q; ++i) {
        cin >> queries[i];
    }

    for (int qi = 0; qi < q; ++qi) {
        unsigned long long k = queries[qi];

        // Determine the sequence of operations to construct k from 1
        // 'D' represents doubling (equivalent to 'L'), 'I' represents increment after doubling (equivalent to 'S')
        vector<char> instructions;

        if (k == 0) {
            cout << "0\n\n";
            continue;
        }

        // Find position of most significant bit
        int highest_bit = 63 - __builtin_clzll(k);

        // Build operation sequence by traversing bits from second-highest to lowest
        for (int bit_pos = highest_bit - 1; bit_pos >= 0; --bit_pos) {
            instructions.push_back('D');  // Double current value

            // If current bit is set, add one after doubling
            if (k & (1ULL << bit_pos)) {
                instructions.push_back('I');
            }
        }

        int op_count = (int)instructions.size();
        cout << op_count << "\n";

        if (op_count == 0) {
            cout << "\n";
            continue;
        }

        // Compute relative values for each instruction
        vector<long long> relative_values(op_count);
        long long min_val = 0, max_val = -1;

        for (int i = 0; i < op_count; ++i) {
            if (instructions[i] == 'D') {
                max_val += 1;
                relative_values[i] = max_val;
            } else { // 'I'
                min_val -= 1;
                relative_values[i] = min_val;
            }
        }

        // Create permutation by ranking relative values
        vector<int> positions(op_count);
        iota(positions.begin(), positions.end(), 0);

        sort(positions.begin(), positions.end(), 
             [&](int a, int b) { return relative_values[a] < relative_values[b]; });

        vector<int> result(op_count);
        for (int rank = 0; rank < op_count; ++rank) {
            result[positions[rank]] = rank;
        }

        // Output the permutation
        for (int i = 0; i < op_count; ++i) {
            if (i > 0) cout << " ";
            cout << result[i];
        }
        cout << "\n";
    }

    return 0;
}

