#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <random>
#include <iomanip>

// Use a fixed seed for deterministic behavior of the randomized algorithm
std::mt19937 rng(42);

void solve() {
    int n, m;
    std::cin >> n >> m;

    // Initialize weights and mistake counters for each participant
    std::vector<long double> expert_weights(n, 1.0L);
    std::vector<int> error_counts(n, 0);

    for (int round = 0; round < m; ++round) {
        std::string predictions;
        std::cin >> predictions;

        // Determine the minimum number of errors among all participants
        int lowest_errors = *std::min_element(error_counts.begin(), error_counts.end());

        int final_prediction;

        // If any participant has zero errors so far, follow their prediction
        if (lowest_errors == 0) {
            int first_leader = -1;
            for (int i = 0; i < n; ++i) {
                if (error_counts[i] == 0) {
                    first_leader = i;
                    break;
                }
            }
            final_prediction = (predictions[first_leader] == '1') ? 1 : 0;
        } else {
            // Otherwise, use weighted random selection based on current expertise
            long double weight_for_zero = 0.0L;
            long double weight_for_one = 0.0L;

            for (int i = 0; i < n; ++i) {
                if (predictions[i] == '0') {
                    weight_for_zero += expert_weights[i];
                } else {
                    weight_for_one += expert_weights[i];
                }
            }

            long double combined_weight = weight_for_zero + weight_for_one;

            if (combined_weight <= 0.0L) {
                final_prediction = 0; // fallback guess
            } else {
                long double chance_of_one = weight_for_one / combined_weight;
                std::uniform_real_distribution<long double> selector(0.0L, 1.0L);
                final_prediction = (selector(rng) < chance_of_one) ? 1 : 0;
            }
        }

        std::cout << final_prediction << std::endl;

        int actual_result;
        std::cin >> actual_result;

        // Update weights and error counts based on performance
        for (int i = 0; i < n; ++i) {
            int expert_guess = (predictions[i] == '1') ? 1 : 0;
            if (expert_guess != actual_result) {
                error_counts[i]++;
                expert_weights[i] *= 0.5L;
            }
        }
    }
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);
    solve();
    return 0;
}

#include "test/jemalloc_test.h"
#include "jemalloc/internal/fxp.h"

// Helper to convert fixed-point to double for comparison
static double
fxp_to_double(fxp_t val) {
    uint32_t int_part = val >> 16;
    uint32_t frac_part = val & 0xFFFF;
    return (double)int_part + (double)frac_part / 65536.0;
}

// Check if two doubles are approximately equal
static bool
approx_equal(double a, double b) {
    // Use both absolute and relative tolerance checks
    double diff = fabs(a - b);
    return diff < 0.01 || (a != 0.0 && diff / fabs(a) < 0.01);
}

// Compare two fxp values via their double representations
static bool
fxp_approx_equal(fxp_t x, fxp_t y) {
    return approx_equal(fxp_to_double(x), fxp_to_double(y));
}

// Parse a string into an fxp_t value with error checking
static fxp_t
parse_fxp_strict(const char *input) {
    fxp_t result;
    bool parse_error = fxp_parse(&result, input, NULL);
    assert_false(parse_error, "Failed to parse valid FXP string: %s", input);
    return result;
}

// Test parsing accuracy against expected double value
static void
verify_parse_accuracy(const char *input_str, const char *parse_input) {
    double expected_val = strtod(input_str, NULL);
    fxp_t parsed_val;
    char *end_ptr;
    bool parse_err = fxp_parse(&parsed_val, parse_input, &end_ptr);

    expect_false(parse_err, "Unexpected parse failure");
    expect_ptr_eq(parse_input + strlen(input_str), end_ptr,
        "Did not consume entire input string");
    expect_true(approx_equal(fxp_to_double(parsed_val), expected_val),
        "Incorrect parsing of %s", input_str);
}

// Run multiple parsing scenarios for a given numeric string
static void
run_valid_parsing_tests(const char *number_str) {
    verify_parse_accuracy(number_str, number_str);

    char buffer[128];
    snprintf(buffer, sizeof(buffer), "%s_trailing_text", number_str);
    verify_parse_accuracy(number_str, buffer);

    snprintf(buffer, sizeof(buffer), "%s extra_space", number_str);
    verify_parse_accuracy(number_str, buffer);

    snprintf(buffer, sizeof(buffer), "%s:option:1", number_str);
    verify_parse_accuracy(number_str, buffer);
}

