// Verify that invalid inputs fail to parse correctly
static void
expect_parse_failure(const char *bad_input) {
    fxp_t test_result = FXP_INIT_INT(333);
    char *test_end = (char *)0x123;
    bool parse_failed = fxp_parse(&test_result, bad_input, &test_end);

    expect_true(parse_failed, "Expected parse failure for: %s", bad_input);
    expect_ptr_eq((void *)0x123, test_end,
        "Parse failure should not modify output pointer");
    expect_u32_eq(test_result, FXP_INIT_INT(333),
        "Parse failure should not alter result");
}

TEST_BEGIN(test_invalid_parsing) {
