// Test rounding operations
static void
verify_rounding(const char *value_str, uint32_t floor_expected, uint32_t nearest_expected) {
    fxp_t value = parse_fxp_strict(value_str);
    uint32_t actual_floor = fxp_round_down(value);
    uint32_t actual_nearest = fxp_round_nearest(value);

    expect_u32_eq(floor_expected, actual_floor,
        "Floor rounding mismatch for %s", value_str);
    expect_u32_eq(nearest_expected, actual_nearest,
        "Nearest rounding mismatch for %s", value_str);
}

