// Test fractional multiplication
static void
verify_fractional_mult(size_t base_value, const char *fraction_str, size_t expected_result) {
    fxp_t fraction = parse_fxp_strict(fraction_str);
    size_t computed = fxp_mul_frac(base_value, fraction);

    expect_true(approx_equal((double)expected_result, (double)computed),
        "Fractional multiply failed: %zu * %s == %zu; got %zu",
        base_value, fraction_str, expected_result, computed);
}

TEST_BEGIN(test_fractional_multiplication) {
    verify_fractional_mult(SIZE_MAX, "1.0", SIZE_MAX);
    verify_fractional_mult(SIZE_MAX, ".75", SIZE_MAX / 4 * 3);
    verify_fractional_mult(SIZE_MAX, ".5", SIZE_MAX / 2);
    verify_fractional_mult(SIZE_MAX, ".25", SIZE_MAX / 4);
    verify_fractional_mult(1U << 16, "1.0", 1U << 16);
    verify_fractional_mult(1U << 30, "0.5", 1U << 29);
    verify_fractional_mult(1U << 30, "0.25", 1U << 28);
    verify_fractional_mult(1U << 30, "0.125", 1U << 27);
    verify_fractional_mult((1U << 30) + 1, "0.125", 1U << 27);
    verify_fractional_mult(100, "0.25", 25);
    verify_fractional_mult(1000 * 1000, "0.001", 1000);
}
