             CGitInfo::Get()->GetMinorVersion(),
             CGitInfo::Get()->GetPatchVersion());

    const char* buildNumber = CGitInfo::Get()->GetBuildNumber();
    const char* buildDateStr = __DATE__ " " __TIME__;
    const char* gitBranch = CGitInfo::Get()->GetBranch();
    const char* gitCommit = CGitInfo::Get()->GetCommit();
    const char* kernelName = CGitInfo::Get()->GetKernelName();
    const char* archType = CGitInfo::Get()->GetArchType();

