    m_Graphics->ClearScreen(COLOR2D(255, 255, 255));

    // Header bar
    const char* titleText = "      Information";
    m_Graphics->DrawRect(0, 0, m_Display->GetWidth(), 30, COLOR2D(58, 124, 165));
    m_Graphics->DrawText(10, 8, COLOR2D(255, 255, 255), titleText, C2DGraphics::AlignLeft);

