    unsigned hammerX = 22;
    unsigned hammerY = 15;

    // Hammer head body
    m_Graphics->DrawRect(hammerX - 7, hammerY - 4, 10, 6, COLOR2D(255, 255, 255));
    // Claw part
    m_Graphics->DrawRect(hammerX - 9, hammerY - 3, 3, 2, COLOR2D(255, 255, 255));
    m_Graphics->DrawRect(hammerX - 10, hammerY - 2, 2, 2, COLOR2D(255, 255, 255));
    // Strike face
    m_Graphics->DrawRect(hammerX + 3, hammerY - 3, 2, 4, COLOR2D(255, 255, 255));
    // Handle
    m_Graphics->DrawRect(hammerX - 1, hammerY + 2, 2, 8, COLOR2D(255, 255, 255));
    // Grip texture lines
    m_Graphics->DrawLine(hammerX - 1, hammerY + 4, hammerX, hammerY + 4, COLOR2D(58, 124, 165));
    m_Graphics->DrawLine(hammerX - 1, hammerY + 6, hammerX, hammerY + 6, COLOR2D(58, 124, 165));
    m_Graphics->DrawLine(hammerX - 1, hammerY + 8, hammerX, hammerY + 8, COLOR2D(58, 124, 165));

    // Content area
    m_Graphics->DrawRect(5, 40, m_Display->GetWidth() - 10, 160, COLOR2D(235, 245, 255));
    m_Graphics->DrawRectOutline(5, 40, m_Display->GetWidth() - 10, 160, COLOR2D(58, 124, 165));

    // Layout parameters
    const unsigned int lineSpacing = 22;
    const unsigned int leftMargin = 15;
    unsigned int yPos = 55;

    // Version line
    char versionLine[64];
    snprintf(versionLine, sizeof(versionLine), "Version: %s", versionBuffer);
    m_Graphics->DrawText(leftMargin, yPos, COLOR2D(0, 0, 140), versionLine, C2DGraphics::AlignLeft);
    yPos += lineSpacing;

    // Build number line
    if (strlen(buildNumber) > 0) {
        char buildNumLine[64];
        snprintf(buildNumLine, sizeof(buildNumLine), "Build: %s", buildNumber);
        m_Graphics->DrawText(leftMargin, yPos, COLOR2D(0, 0, 140), buildNumLine, C2DGraphics::AlignLeft);
        yPos += lineSpacing;
    }

    // Build date label and value
    m_Graphics->DrawText(leftMargin, yPos, COLOR2D(0, 0, 140), "Build Date:", C2DGraphics::AlignLeft);
    yPos += 18;
    m_Graphics->DrawText(leftMargin + 10, yPos, COLOR2D(0, 0, 140), buildDateStr, C2DGraphics::AlignLeft);
    yPos += lineSpacing;

    // Kernel info
    char kernelLine[64];
    snprintf(kernelLine, sizeof(kernelLine), "Kernel: %s %s", kernelName, archType);
    m_Graphics->DrawText(leftMargin, yPos, COLOR2D(0, 0, 140), kernelLine, C2DGraphics::AlignLeft);
    yPos += lineSpacing;

    // Branch info
    char branchLine[64];
    const int maxBranchChars = 20;

    if (strcmp(gitBranch, "main") == 0) {
        snprintf(branchLine, sizeof(branchLine), "Branch: %.*s *", maxBranchChars, gitBranch);
    } else {
        if (strlen(gitBranch) > static_cast<size_t>(maxBranchChars)) {
            char truncatedBranch[32];
            snprintf(truncatedBranch, sizeof(truncatedBranch), "%.*s...", maxBranchChars - 3, gitBranch);
            snprintf(branchLine, sizeof(branchLine), "Branch: %s", truncatedBranch);
        } else {
            snprintf(branchLine, sizeof(branchLine), "Branch: %s", gitBranch);
        }
    }
    m_Graphics->DrawText(leftMargin, yPos, COLOR2D(0, 0, 140), branchLine, C2DGraphics::AlignLeft);
    yPos += lineSpacing;

    // Git commit hash
    char shortHash[16] = {0};
    strncpy(shortHash, gitCommit, 15);
    char hashLine[64];
    snprintf(hashLine, sizeof(hashLine), "Commit: %s", shortHash);
    m_Graphics->DrawText(leftMargin, 175, COLOR2D(0, 0, 140), hashLine, C2DGraphics::AlignLeft);

    // Navigation bar
    DrawNavigationBar("info");
    m_Graphics->UpdateDisplay();
}

