// Helper to convert enum MultiBufferStrategy to string representation
inline std::string toString(MultiBufferStrategy strategy) {
  switch (strategy) {
    case MultiBufferStrategy::NO_LIMIT:
      return "no-limit";
    case MultiBufferStrategy::ONLY_CUBE:
      return "only-cube";
    case MultiBufferStrategy::ONLY_VECTOR:
      return "only-vector";
    case MultiBufferStrategy::CUBE_NO_L0C:
      return "no-l0c";
    default:
      return "unknown";
  }
}

