void BiShengIRCompileMainConfig::collectHIVMCArgs() {
  std::vector<std::string> collected;
  auto &opts = cl::getRegisteredOptions();

  for (auto &[name, regOpt] : opts) {
    std::string valueStr = "";
#define GEN_OPTION_COLLECTION
#include "bishengir/Tools/bishengir-compile/CompileOptions.cpp.inc"
    if (!valueStr.empty()) {
      collected.emplace_back(name.str() + "=" + valueStr);
    }
  }

  // Append any pre-collected args from config
  const auto &preCollected = cliOptionsInstance->getHIVMCArgs();
  for (const auto &group : preCollected) {
    if (group.empty()) continue;
    for (const auto &arg : llvm::split(group, " ")) {
      collected.emplace_back(arg.str());
    }
  }

  cliOptionsInstance->setHIVMCArgs(collected);
}

void BiShengIRCompileMainConfig::registerCLOptions() {
  // Force initialization of the singleton to register all options
  (void)*cliOptionsInstance;
}

BiShengIRCompileMainConfig BiShengIRCompileMainConfig::createFromCLOptions() {
  BiShengIRCompileMainConfig::collectHIVMCArgs();
  return *cliOptionsInstance;
}

