namespace py = pybind11;

// Aliases for brevity and clarity
using namespace qdk::chemistry::algorithms;
using namespace qdk::chemistry::data;

// Result type alias: energy + wavefunction pair
using EnergyWavefunctionPair = std::pair<double, std::shared_ptr<Wavefunction>>;

// Trampoline class to support Python subclassing
class PMCBaseTrampoline
    : public ProjectedMultiConfigurationCalculator,
      public pybind11::trampoline_self_life_support {
public:
    // Override name() with pure Python override
    std::string name() const override {
        PYBIND11_OVERRIDE_PURE(std::string, ProjectedMultiConfigurationCalculator, name);
    }

    // Override aliases()
    std::vector<std::string> aliases() const override {
        PYBIND11_OVERRIDE(std::vector<std::string>,
                          ProjectedMultiConfigurationCalculator, aliases);
    }

    // Helper to replace settings from derived classes
    void update_settings(std::unique_ptr<Settings> updated) {
        _settings = std::move(updated);
    }

protected:
    // Core computation method — overridden by subclasses
    EnergyWavefunctionPair execute_impl(
        std::shared_ptr<Hamiltonian> hamiltonian,
        const std::vector<Configuration>& determinants) const override {
        PYBIND11_OVERRIDE_PURE(EnergyWavefunctionPair,
                               ProjectedMultiConfigurationCalculator,
                               _run_impl, hamiltonian, determinants);
    }
};

// Helper to bind algorithm factories generically
template<typename Factory, typename Base, typename Trampoline>
void bind_algorithm_factory_wrapper(py::module& m, const char* factory_name) {
    qdk::chemistry::python::bind_algorithm_factory<Factory, Base, Trampoline>(
        m, factory_name);
}

void bind_pmc(py::module& m) {
    // Bind abstract base class
    py::class_<ProjectedMultiConfigurationCalculator,
               PMCBaseTrampoline, py::smart_holder>
        pmc_class(m, "ProjectedMultiConfigurationCalculator",
                  R"(
Abstract base class for projected multi-configurational (PMC) calculations in quantum chemistry.
This class defines the interface for projecting the Hamiltonian onto user-specified determinants,
enabling integration with external determinant selection strategies while leveraging high-performance solvers.

To implement a custom PMC calculator, inherit from this class and override `_run_impl`.

Example:
    >>> import qdk_chemistry.algorithms as alg
    >>> class MyPMC(alg.ProjectedMultiConfigurationCalculator):
    ...     def __init__(self):
    ...         super().__init__()
    ...     def _run_impl(self, H, configs):
    ...         return 0.0, data.Wavefunction()
)");

    // Default constructor
    pmc_class.def(py::init<>(), R"(
Constructs an empty PMC calculator instance.
Typically called via `super().__init__()` in derived classes.
)");

    // Public run method
    pmc_class.def("run", &ProjectedMultiConfigurationCalculator::run,
                  R"(
Executes the projected multi-configurational calculation.

Args:
    hamiltonian (qdk_chemistry.data.Hamiltonian): System Hamiltonian
    configurations (list[qdk_chemistry.data.Configuration]): Determinant space

Returns:
    tuple[float, qdk_chemistry.data.Wavefunction]: Energy and wavefunction

Raises:
    RuntimeError: On failure
    ValueError: On invalid inputs
)",
                  py::arg("hamiltonian"), py::arg("configurations"));

    // Read-only settings accessor
    pmc_class.def("settings",
                  &ProjectedMultiConfigurationCalculator::settings,
                  R"(
Provides access to configuration parameters.

Returns:
    qdk_chemistry.data.Settings: Internal settings object
)",
                  py::return_value_policy::reference_internal);

    // Writable `_settings` property using named lambda helpers
    auto get_settings = [](PMCBaseTrampoline& calc) -> Settings& {
        return calc.settings();
    };

    auto set_settings = [](PMCBaseTrampoline& calc,
                           std::unique_ptr<Settings> new_settings) {
        calc.update_settings(std::move(new_settings));
    };

    pmc_class.def_property("_settings", get_settings, set_settings,
                           py::return_value_policy::reference_internal,
                           R"(
Allows derived classes to inject specialized Settings subclasses.

Example:
    >>> class CustomPMC(alg.ProjectedMultiConfigurationCalculator):
    ...     def __init__(self):
    ...         super().__init__()
    ...         self._settings = data.ElectronicStructureSettings()
)");

    // Algorithm metadata
    pmc_class.def("name", &ProjectedMultiConfigurationCalculator::name,
                  R"(
Returns the human-readable name of the algorithm.

Returns:
    str: Name of the algorithm
)");

    pmc_class.def("type_name", &ProjectedMultiConfigurationCalculator::type_name,
                  R"(
Returns the internal type identifier.

Returns:
    str: Type name string
)");

    // Factory binding
    bind_algorithm_factory_wrapper<
        ProjectedMultiConfigurationCalculatorFactory,
        ProjectedMultiConfigurationCalculator,
        PMCBaseTrampoline>(m, "ProjectedMultiConfigurationCalculatorFactory");

    // String representation
    pmc_class.def("__repr__", [](const ProjectedMultiConfigurationCalculator&) {
        return "<qdk_chemistry.algorithms.ProjectedMultiConfigurationCalculator>";
    });

    // Concrete implementation: Microsoft MACIS-based PMC
    py::class_<microsoft::MacisPmc, ProjectedMultiConfigurationCalculator,
               py::smart_holder>(m, "QdkMacisPmc", R"(
Concrete PMC calculator backed by Microsoft's MACIS library.

Implements projected multi-configurational calculations using deterministic
determinant spaces provided externally. Suitable for strongly-correlated systems.

Usage example:
    >>> pmc = alg.QdkMacisPmc()
    >>> pmc.settings().set("davidson_res_tol", 1e-8)
    >>> energy, wf = pmc.run(H, configs)

See Also:
    :class:`ProjectedMultiConfigurationCalculator`
)")
        .def(py::init<>(), R"(
Initializes with default MACIS configuration.
)");
}

