#include "locale/Language.h"
#include "Button.h"
#include "SmallButton.h"

ControlsScreen::ControlsScreen(Screen* prevScreen, Options* settings) {
    // Initialize fields with equivalent semantics
    title = L"Controls";
    activeKeyIndex = -1;
    previousScreen = prevScreen;
    gameSettings  = settings;
}

int ControlsScreen::getLeftOffset() const { 
    return (width / 2) - 155; 
}

void ControlsScreen::init() {
    Language* lang = Language::getInstance();
    int xOffset = getLeftOffset();

    // Iterate through key mappings using index-based loop
    for (int idx = 0; idx < Options::keyMappings_length; ++idx) {
        int row = idx >> 1;
        int col = idx % 2;

        buttons.emplace_back(new SmallButton(
            idx,
            xOffset + col * ROW_WIDTH,
            (height / 6) + 24 * row,
            BUTTON_WIDTH,
            20,
            gameSettings->getKeyMessage(idx)
        ));
    }

    // Add Done button at fixed position
    buttons.emplace_back(new Button(
        200,
        (width / 2) - 100,
        (height / 6) + 24 * 7,
        lang->getElement(L"gui.done")
    ));

    title = lang->getElement(L"controls.title");
}

void ControlsScreen::onButtonClick(Button* btn) {
    // Refresh all button labels to reflect current key bindings
    for (int i = 0; i < Options::keyMappings_length; ++i) {
        buttons[i]->msg = gameSettings->getKeyMessage(i);
    }

    if (btn->id == 200) {
        // Return to previous screen
        mcInstance->setScreen(previousScreen);
    } else {
        // Begin rebind process for selected key
        activeKeyIndex = btn->id;
        btn->msg = L"> " + gameSettings->getKeyMessage(btn->id) + L" <";
    }
}

void ControlsScreen::handleKeyPress(wchar_t ch, int vkCode) {
    if (activeKeyIndex >= 0) {
        // Update key binding and update UI
        gameSettings->setKey(activeKeyIndex, vkCode);
        buttons[activeKeyIndex]->msg = gameSettings->getKeyMessage(activeKeyIndex);
        activeKeyIndex = -1;
    } else {
        // Fall back to default handling
        Screen::handleKeyPress(ch, vkCode);
    }
}

void ControlsScreen::draw(int mouseX, int mouseY, float partialTicks) {
    drawBackground();
    drawCenteredText(font, title, width / 2, 20, 0xffffff);

    int leftX = getLeftOffset();
    for (int k = 0; k < Options::keyMappings_length; ++k) {
        int row = k >> 1;
        int col = k % 2;

        drawText(
            font,
            gameSettings->getKeyDescription(k),
            leftX + col * ROW_WIDTH + BUTTON_WIDTH + 6,
            (height / 6) + 24 * row + 7,
            0xffffffff
        );
    }

    Screen::draw(mouseX, mouseY, partialTicks);
}

