// Helper macros for constructing image brushes with consistent content path resolution
#define RESOLVE_ICON_PATH(RelativePath) FConcertFrontendStyle::ResolveIconPath(RelativePath)
#define MAKE_BRUSH(Path, Size, Color) new FSlateImageBrush(RESOLVE_ICON_PATH(Path), Size, Color)

FString FConcertFrontendStyle::ResolveIconPath(const FString& RelativePath)
{
	static const FString PluginContentDir = []() -> FString {
		if (auto Plugin = IPluginManager::Get().FindPlugin(TEXT("ConcertSyncClient")))
			return Plugin->GetContentDir();
		return FString{};
	}();

	return PluginContentDir.IsEmpty() ? FString{} : (PluginContentDir / RelativePath);
}

