#include <iostream>
#include <string>
#include <cmath>

#include <Teuchos_RCP.hpp>
#include <Teuchos_ParameterList.hpp>
#include <Teuchos_StandardCatchMacros.hpp>

#include <Intrepid2_Basis_HCURL_HEX_I1_FEM.hpp>
#include <Intrepid2_DefaultCubatureFactory.hpp>
#include <Intrepid2_FE_CURL.hpp>

#include <Shards_CellTopology.hpp>

#include <ROL_Ptr.hpp>
#include <ROL_Types.hpp>

// Type aliases for clarity
using RealT = double;
using DeviceT = Kokkos::DefaultExecutionSpace;

int main() {
  int errorFlag = 0;
  auto outStream = std::make_shared<std::ostream>(std::cout.rdbuf());

  try {
    // Load parameter list from XML file
    std::string config_file = "input_05.xml";
    Teuchos::RCP<Teuchos::ParameterList> params = Teuchos::rcp(new Teuchos::ParameterList());
    Teuchos::updateParametersFromXmlFile(config_file, params.ptr());

    // Initialize mesh and DOF manager
    MeshManager_Brick<RealT, DeviceT> mesh(*params);
    auto nodeCoords = mesh.getNodes();
    auto connectivity = mesh.getCellToNodeMap();

    *outStream << "Total nodes   : " << mesh.getNumNodes() << "\n";
    *outStream << "Total cells   : " << mesh.getNumCells() << "\n";
    *outStream << "Total edges   : " << mesh.getNumEdges() << "\n";

    ROL::Ptr<MeshManager<RealT, DeviceT>> meshPtr = ROL::makePtrFromRef(mesh);

    // Define basis and cubature
    using BasisType = Intrepid2::Basis_HCURL_HEX_I1_FEM<DeviceT, RealT, RealT>;
    auto basis = ROL::makePtr<BasisType>();

    shards::CellTopology cellTopo = basis->getBaseCellTopology();
    Intrepid2::DefaultCubatureFactory factory;
    int quadOrder = 4; // polynomial degree for cubature
    auto cubature = factory.create<DeviceT, RealT, RealT>(cellTopo, quadOrder);

    // Populate cell-wise nodal coordinates
    const unsigned numNodesPerCell = cellTopo.getNodeCount();
    const unsigned spaceDim = cellTopo.getDimension();
    Kokkos::View<RealT***, DeviceT> elemNodes("elemNodes", mesh.getNumCells(), numNodesPerCell, spaceDim);

    for (int icell = 0; icell < mesh.getNumCells(); ++icell) {
      for (unsigned inode = 0; inode < numNodesPerCell; ++inode) {
        for (unsigned idim = 0; idim < spaceDim; ++idim) {
          elemNodes(icell, inode, idim) = nodeCoords(connectivity(icell, inode), idim);
        }
      }
    }

    // Construct finite element object
    FE_CURL<RealT, DeviceT> fe(elemNodes, basis, cubature);

    // Prepare views for evaluation
    const int numQuadPts = cubature->getNumPoints();
    const int numBasis = basis->getCardinality();
    const int dim = cubature->getDimension();

    Kokkos::View<RealT****, DeviceT> vals1("vals1", mesh.getNumCells(), numQuadPts, dim);
    Kokkos::View<RealT****, DeviceT> vals2("vals2", mesh.getNumCells(), numQuadPts, dim);
    Kokkos::View<RealT****, DeviceT> curls1("curls1", mesh.getNumCells(), numQuadPts, dim);
    Kokkos::View<RealT****, DeviceT> curls2("curls2", mesh.getNumCells(), numQuadPts, dim);
    Kokkos::View<RealT**, DeviceT> coeffs1("coeffs1", mesh.getNumCells(), numBasis);
    Kokkos::View<RealT**, DeviceT> coeffs2("coeffs2", mesh.getNumCells(), numBasis);
    Kokkos::View<RealT*, DeviceT> integrals("integrals", mesh.getNumCells());

    // Set initial coefficients
    Kokkos::parallel_for(Kokkos::RangePolicy<int>(0, mesh.getNumCells()), KOKKOS_LAMBDA(int i) {
      coeffs1(i, 0) = static_cast<RealT>(1);
      coeffs2(i, 0) = static_cast<RealT>(1);
    });

    // Evaluate values and compute L2 inner product
    fe.evaluateValue(vals1, coeffs1);
    fe.evaluateValue(vals2, coeffs2);
    fe.computeIntegral(integrals, vals1, vals2);

    RealT valSum = static_cast<RealT>(0);
    for (int i = 0; i < mesh.getNumCells(); ++i) {
      valSum += integrals(i);
    }

    if (std::abs(valSum - static_cast<RealT>(4)/static_cast<RealT>(9)) > std::sqrt(ROL::ROL_EPSILON<RealT>())) {
      errorFlag = -1;
    }

    // Evaluate curls and compute their inner product
    fe.evaluateCurl(curls1, coeffs1);
    fe.evaluateCurl(curls2, coeffs2);
    fe.computeIntegral(integrals, curls1, curls2);

    RealT curlSum = static_cast<RealT>(0);
    for (int i = 0; i < mesh.getNumCells(); ++i) {
      curlSum += integrals(i);
    }

    if (std::abs(curlSum - static_cast<RealT>(8)/static_cast<RealT>(3)) > std::sqrt(ROL::ROL_EPSILON<RealT>())) {
      errorFlag = -1;
    }

    *outStream << std::setprecision(14)
               << "Value integral     = " << valSum << "\n"
               << "Curl-curl integral = " << curlSum << "\n";

  } catch (std::exception& e) {
    *outStream << "Exception caught: " << e.what() << "\n";
    errorFlag = -1000;
  }

  if (errorFlag != 0) {
    std::cout << "End Result: TEST FAILED\n";
  } else {
    std::cout << "End Result: TEST PASSED\n";
  }

  return errorFlag;
}

#include <vector>
using namespace std;

vector<int> subsetSums(vector<int>& arr) {
    vector<int> ans;
    int n = arr.size();

    // Iterate through all possible subsets using bit manipulation
    for (int mask = 0; mask < (1 << n); ++mask) {
        int sum = 0;
        // Calculate sum for current subset represented by mask
        for (int i = 0; i < n; ++i) {
            if (mask & (1 << i)) {
                sum += arr[i];
            }
        }
        ans.push_back(sum);
    }

    return ans;
}

