/*-------------------------------------------------------------------------
 * Function:    H5FD_extend_block
 *
 * Purpose:     Extend the EOA space of a file.
 *
 * NOTE:        Returns absolute file offset
 *
 * Return:      Success:    The address of the previous EOA.
 *              Failure:    The undefined address HADDR_UNDEF
 *
 * Programmer:  Bill Wendling
 *              Wednesday, 04. December, 2002
 *
 *-------------------------------------------------------------------------
 */
static haddr_t
H5FD_extend_block(H5FD_t *file, H5FD_mem_t type, hbool_t is_new, hsize_t req_size, haddr_t *frag_off, hsize_t *frag_len)
{
    hsize_t orig_size = req_size;
    haddr_t cur_eoa;
    hsize_t pad_bytes = 0;
    haddr_t alloc_start;

    FUNC_ENTER_NOAPI_NOINIT

    HDassert(file && file->cls);
    HDassert(type >= H5FD_MEM_DEFAULT && type < H5FD_MEM_NTYPES);
    HDassert(req_size > 0);

    cur_eoa = file->cls->get_eoa(file, type);
    if (!IS_VALID_OFFSET(cur_eoa))
        HGOTO_ERROR(H5E_VFL, H5E_CANTGET, HADDR_UNDEF, "could not retrieve current EOA")

    /* Align if needed */
    if (is_new && file->alignment > 1 && orig_size >= file->threshold) {
        hsize_t misalignment = cur_eoa % file->alignment;
        if (misalignment != 0) {
            pad_bytes = file->alignment - misalignment;
            if (frag_off) *frag_off = cur_eoa - file->base_addr;
            if (frag_len) *frag_len = pad_bytes;
        }
    }

    req_size += pad_bytes;

    if (OVERFLOW_CHECK(cur_eoa, req_size))
        HGOTO_ERROR(H5E_VFL, H5E_NOSPACE, HADDR_UNDEF, "address overflow during extension")

    alloc_start = cur_eoa + pad_bytes;
    cur_eoa += req_size;

    if (file->cls->set_eoa(file, type, cur_eoa) < 0)
        HGOTO_ERROR(H5E_VFL, H5E_NOSPACE, HADDR_UNDEF, "failed to update EOA")

    if (is_new && file->alignment && orig_size >= file->threshold)
        HDassert(!(alloc_start % file->alignment));

done:
    FUNC_LEAVE_NOAPI(alloc_start)
} /* H5FD_extend_block() */


/*-------------------------------------------------------------------------
 * Function:    H5FD_alloc_real
 *
 * Purpose:     Allocate space in the file with the VFD
 *
 * Return:      Success:    The format address of the new file memory.
 *              Failure:    The undefined address HADDR_UNDEF
 *
 * Programmer:  Robb Matzke
 *              Wednesday, August  4, 1999
 *
 *-------------------------------------------------------------------------
 */
haddr_t
H5FD_alloc_real(H5FD_t *file, hid_t dxpl_id, H5FD_mem_t mem_type, hsize_t size, haddr_t *frag_addr, hsize_t *frag_size)
{
    haddr_t result = HADDR_UNDEF;
    hbool_t use_driver_alloc = FALSE;

    FUNC_ENTER_NOAPI(HADDR_UNDEF)

#ifdef H5FD_ALLOC_DEBUG
HDfprintf(stderr, "%s: type = %u, size = %Hu\n", FUNC, (unsigned)mem_type, size);
#endif

    HDassert(file && file->cls);
    HDassert(mem_type >= H5FD_MEM_DEFAULT && mem_type < H5FD_MEM_NTYPES);
    HDassert(size > 0);

    use_driver_alloc = (file->cls->alloc != NULL);

    if (use_driver_alloc) {
        result = (file->cls->alloc)(file, mem_type, dxpl_id, size);
        if (!IS_VALID_OFFSET(result))
            HGOTO_ERROR(H5E_VFL, H5E_NOSPACE, HADDR_UNDEF, "driver allocation failed")
    } else {
        result = H5FD_extend_block(file, mem_type, TRUE, size, frag_addr, frag_size);
        if (!IS_VALID_OFFSET(result))
            HGOTO_ERROR(H5E_VFL, H5E_NOSPACE, HADDR_UNDEF, "EOA extension failed")
    }

    result -= file->base_addr;

done:
#ifdef H5FD_ALLOC_DEBUG
HDfprintf(stderr, "%s: ret_value = %a\n", FUNC, result);
#endif
    FUNC_LEAVE_NOAPI(result)
} /* H5FD_alloc_real() */


/*-------------------------------------------------------------------------
 * Function:    H5FD_alloc
 *
 * Purpose:     Wrapper for H5FD_alloc, to make certain EOA changes are
 *		reflected in superblock.
 *
 * Note:	When the metadata cache routines are updated to allow
 *		marking an entry dirty without a H5F_t*, this routine should
 *		be changed to take a H5F_super_t* directly.
 *
 * Return:      Success:    The format address of the new file memory.
 *              Failure:    The undefined address HADDR_UNDEF
 *
 * Programmer:  Quincey Koziol
 *              Friday, August 14, 2009
 *
 *-------------------------------------------------------------------------
 */
haddr_t
H5FD_alloc(H5FD_t *file, hid_t dxpl_id, H5FD_mem_t type, H5F_t *f, hsize_t size,
    haddr_t *frag_addr, hsize_t *frag_size)
{
    haddr_t res = HADDR_UNDEF;

    FUNC_ENTER_NOAPI(HADDR_UNDEF)

    HDassert(file && file->cls);
    HDassert(type >= H5FD_MEM_DEFAULT && type < H5FD_MEM_NTYPES);
    HDassert(size > 0);

    res = H5FD_alloc_real(file, dxpl_id, type, size, frag_addr, frag_size);
    if (!IS_VALID_OFFSET(res))
        HGOTO_ERROR(H5E_VFL, H5E_CANTALLOC, HADDR_UNDEF, "real alloc failed")

    if (H5F_super_dirty(f) < 0)
        HGOTO_ERROR(H5E_VFL, H5E_CANTMARKDIRTY, HADDR_UNDEF, "superblock not marked dirty")

done:
    FUNC_LEAVE_NOAPI(res)
} /* H5FD_alloc() */


/*-------------------------------------------------------------------------
 * Function:    H5FD_free_real
 *
 * Purpose:     Release space back to the VFD
 *
 * Return:      Success:        Non-negative
 *              Failure:        Negative
 *
 * Programmer:  Robb Matzke
 *              Wednesday, August  4, 1999
 *
 *-------------------------------------------------------------------------
 */
herr_t
H5FD_free_real(H5FD_t *file, hid_t dxpl_id, H5FD_mem_t type, haddr_t addr, hsize_t size)
{
    herr_t status = SUCCEED;
    haddr_t abs_addr;

    FUNC_ENTER_NOAPI_NOINIT

    HDassert(file && file->cls);
    HDassert(type >= H5FD_MEM_DEFAULT && type < H5FD_MEM_NTYPES);
    HDassert(size > 0);

#ifdef H5FD_ALLOC_DEBUG
HDfprintf(stderr, "%s: type = %u, addr = %a, size = %Hu\n", FUNC, (unsigned)type, addr, size);
#endif

    if (!IS_VALID_OFFSET(addr))
        HGOTO_ERROR(H5E_VFL, H5E_BADVALUE, FAIL, "invalid offset")

    abs_addr = addr + file->base_addr;

    if (abs_addr > file->maxaddr || OVERFLOW_CHECK(abs_addr, size))
        HGOTO_ERROR(H5E_VFL, H5E_BADVALUE, FAIL, "free region out of bounds")

    if (file->cls->free) {
#ifdef H5FD_ALLOC_DEBUG
HDfprintf(stderr, "%s: Letting VFD free space\n", FUNC);
#endif
        if ((file->cls->free)(file, type, dxpl_id, abs_addr, size) < 0)
            HGOTO_ERROR(H5E_VFL, H5E_CANTFREE, FAIL, "VFD free failed")
    } else if (file->cls->get_eoa) {
        haddr_t eoa = file->cls->get_eoa(file, type);
#ifdef H5FD_ALLOC_DEBUG
HDfprintf(stderr, "%s: eoa = %a\n", FUNC, eoa);
#endif
        if (eoa == abs_addr + size) {
            if (file->cls->set_eoa(file, type, abs_addr) < 0)
                HGOTO_ERROR(H5E_VFL, H5E_CANTSET, FAIL, "EOA truncation failed")
        } else {
#ifdef H5FD_ALLOC_DEBUG
HDfprintf(stderr, "%s: LEAKED MEMORY!!!\n", FUNC);
#endif
        }
    } else {
#ifdef H5FD_ALLOC_DEBUG
HDfprintf(stderr, "%s: LEAKED MEMORY!!! type = %u, addr = %a, size = %Hu\n", FUNC, (unsigned)type, addr, size);
#endif
    }

done:
    FUNC_LEAVE_NOAPI(status)
} /* H5FD_free_real() */


/*-------------------------------------------------------------------------
 * Function:    H5FD_free
 *
 * Purpose:     Wrapper for H5FD_free_real, to make certain EOA changes are
 *		reflected in superblock.
 *
 * Note:	When the metadata cache routines are updated to allow
 *		marking an entry dirty without a H5F_t*, this routine should
 *		be changed to take a H5F_super_t* directly.
 *
 * Return:      Success:        Non-negative
 *              Failure:        Negative
 *
 * Programmer:  Quincey Koziol
 *              Friday, August 14, 2009
 *
 *-------------------------------------------------------------------------
 */
herr_t
H5FD_free(H5FD_t *file, hid_t dxpl_id, H5FD_mem_t type, H5F_t *f, haddr_t addr,
    hsize_t size)
{
    herr_t status = SUCCEED;

    FUNC_ENTER_NOAPI(FAIL)

    HDassert(file && file->cls);
    HDassert(type >= H5FD_MEM_DEFAULT && type < H5FD_MEM_NTYPES);
    HDassert(size > 0);

    if (H5FD_free_real(file, dxpl_id, type, addr, size) < 0)
        HGOTO_ERROR(H5E_VFL, H5E_CANTFREE, FAIL, "real free failed")

    if (H5F_super_dirty(f) < 0)
        HGOTO_ERROR(H5E_VFL, H5E_CANTMARKDIRTY, FAIL, "superblock not marked dirty")

done:
    FUNC_LEAVE_NOAPI(status)
} /* H5FD_free() */


/*-------------------------------------------------------------------------
 * Function:    H5FD_try_extend_block
 *
 * Purpose:	Extend a block at the end of the file, if possible.
 *
 * Note:	When the metadata cache routines are updated to allow
 *		marking an entry dirty without a H5F_t*, this routine should
 *		be changed to take a H5F_super_t* directly.
 *
 * Return:	Success:	TRUE(1)  - Block was extended
 *                              FALSE(0) - Block could not be extended
 * 		Failure:	FAIL
 *
 * Programmer:  Quincey Koziol
 *              Thursday, 17. January, 2008
 *
 *-------------------------------------------------------------------------
 */
htri_t
H5FD_try_extend_block(H5FD_t *file, H5FD_mem_t type, H5F_t *f, haddr_t blk_end,
    hsize_t extra_requested)
{
    haddr_t eoa;
    htri_t extended = FALSE;

    FUNC_ENTER_NOAPI(FAIL)

    HDassert(file && file->cls);
    HDassert(type >= H5FD_MEM_DEFAULT && type < H5FD_MEM_NTYPES);
    HDassert(extra_requested > 0);
    HDassert(f);

    eoa = file->cls->get_eoa(file, type);
    if (!IS_VALID_OFFSET(eoa))
        HGOTO_ERROR(H5E_VFL, H5E_CANTGET, FAIL, "get_eoa failed")

    blk_end += file->base_addr;

    if (H5F_addr_eq(blk_end, eoa)) {
        if (HADDR_UNDEF == H5FD_extend_block(file, type, FALSE, extra_requested, NULL, NULL))
            HGOTO_ERROR(H5E_VFL, H5E_CANTEXTEND, FAIL, "extend failed")

        if (H5F_super_dirty(f) < 0)
            HGOTO_ERROR(H5E_VFL, H5E_CANTMARKDIRTY, FAIL, "mark superblock dirty failed")

        extended = TRUE;
    }

done:
    FUNC_LEAVE_NOAPI(extended)
} /* H5FD_try_extend_block() */

#include "CodeGenInstruction.h"
#include "CodeGenTarget.h"
#include "X86RecognizableInstr.h"
#include "llvm/TableGen/Record.h"
#include "llvm/TableGen/TableGenBackend.h"

using namespace llvm;

namespace {

class X86MnemonicTablesEmitter {
  CodeGenTarget Target;

  // Helper: Determine if an instruction should be included in mnemonic tables
  bool shouldIncludeInstruction(const CodeGenInstruction &Inst) const {
    const Record *Def = Inst.TheDef;
    if (!Def->isSubClassOf("X86Inst"))
      return false;

    X86Disassembler::RecognizableInstrBase RI(Inst);
    if (!RI.shouldBeEmitted())
      return false;

    std::string variantName = Def->getValueAsString("AsmVariantName");
    if (variantName == "NonParsable" || RI.Form == X86Local::PrefixByte)
      return false;

    return true;
  }

public:
  X86MnemonicTablesEmitter(RecordKeeper &R) : Target(R) {}

  void emit(raw_ostream &OS) {
    emitSourceFileHeader("X86 Mnemonic tables", OS);
    OS << "namespace llvm {\nnamespace X86 {\n\n";

    Record *asmWriter = Target.getAsmWriter();
    unsigned variant = asmWriter->getValueAsInt("Variant");

    StringMap<SmallVector<const CodeGenInstruction *, 0>> mnemonicMap;

    ArrayRef<const CodeGenInstruction *> instrList =
        Target.getInstructionsByEnumValue();

    for (size_t idx = 0; idx < instrList.size(); ++idx) {
      const CodeGenInstruction *instPtr = instrList[idx];
      if (!shouldIncludeInstruction(*instPtr))
        continue;

      std::string mnemonic = X86Disassembler::getMnemonic(instPtr, variant);
      mnemonicMap[mnemonic].push_back(instPtr);
    }

    OS << "#ifdef GET_X86_MNEMONIC_TABLES_H\n";
    OS << "#undef GET_X86_MNEMONIC_TABLES_H\n\n";

    for (auto &entry : mnemonicMap) {
      OS << "bool is" << entry.getKey() << "(unsigned Opcode);\n";
    }

    OS << "#endif // GET_X86_MNEMONIC_TABLES_H\n\n";

    OS << "#ifdef GET_X86_MNEMONIC_TABLES_CPP\n";
    OS << "#undef GET_X86_MNEMONIC_TABLES_CPP\n\n";

    for (auto &entry : mnemonicMap) {
      StringRef mnemonic = entry.getKey();
      auto &instructions = entry.getValue();

      OS << "bool is" << mnemonic << "(unsigned Opcode) {\n";
      if (instructions.size() == 1u) {
        const CodeGenInstruction *cgInst = instructions.front();
        OS << "\treturn Opcode == " << cgInst->TheDef->getName() << ";\n}\n\n";
      } else {
        OS << "\tswitch (Opcode) {\n";
        for (const CodeGenInstruction *cgInst : instructions) {
          OS << "\tcase " << cgInst->TheDef->getName() << ":\n";
        }
        OS << "\t\treturn true;\n\t}\n\treturn false;\n}\n\n";
      }
    }

    OS << "#endif // GET_X86_MNEMONIC_TABLES_CPP\n\n";
    OS << "} // end namespace X86\n} // end namespace llvm";
  }
};

} // anonymous namespace

