// Function to handle one test case
void process_case() {
    int total_words;
    std::cin >> total_words;

    std::set<std::string> collected_words;

    // Try each starting letter from 'a' to 'z'
    for (char start_char = 'a'; start_char <= 'z'; ++start_char) {
        if (collected_words.size() >= static_cast<size_t>(total_words)) {
            break;
        }

        std::string current_prefix(1, start_char);
        int requested_count = 1;

        // Use exponential search to find words with this prefix
        while (true) {
            if (collected_words.size() >= static_cast<size_t>(total_words)) {
                break;
            }

            std::cout << "query " << current_prefix << " " << requested_count << std::endl;

            int actual_count;
            std::cin >> actual_count;

            for (int i = 0; i < actual_count; ++i) {
                std::string word;
                std::cin >> word;
                collected_words.insert(word);
            }

            // If we got fewer words than requested, no more words exist for this prefix
            if (actual_count < requested_count) {
                break;
            }

            // Avoid requesting more than the total number of words
            if (requested_count == total_words) {
                break;
            }

            // Double the request size for next iteration
            requested_count *= 2;
            if (requested_count > total_words) {
                requested_count = total_words;
            }
        }
    }

    // Output the collected words
    std::cout << "answer";
    for (const auto& word : collected_words) {
        std::cout << " " << word;
    }
    std::cout << std::endl;
}

int main() {
    // Optimize I/O performance
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int test_cases;
    std::cin >> test_cases;

    while (test_cases-- > 0) {
        process_case();
    }

    return 0;
}

