// Cancel ongoing image decoding operation
void StaticIODeviceImageLoader::abort() const {
  if (nullptr != m_res) { 
    BackgroundImageDecoder::instance()->cancel(m_res->id()); 
  }
}

// Process image rendering with provided configuration
void StaticIODeviceImageLoader::render(const RenderConfig &cfg) {
  // Store decoded result from background decoder
  auto decoded_result = BackgroundImageDecoder::instance()->decode(std::move(m_data), cfg);
  m_res = std::move(decoded_result);

  // Set up signal connection for when data is ready
  auto* response_ptr = m_res.get();
  connect(response_ptr, &BackgroundImageDecodeResponse::dataDecoded, this,
          [this](const QPixmap &pixmap) { emit dataUpdated(pixmap); });
}

// Initialize loader with image data
StaticIODeviceImageLoader::StaticIODeviceImageLoader(QByteArray image_data) 
    : m_data(std::move(image_data)) {}

