// Mock implementation for testing demangling behavior
struct mock_demangle_backend
{
    static inline unsigned invocation_counter = 0;

    static char* perform_demangle(const char* mangled_input, char*, size_t*, int* status_out)
    {
        ++invocation_counter;

        // Check if input contains failure marker
        bool has_failure_tag = false;
        for (size_t idx = 0; mangled_input[idx] != '\0'; ++idx)
        {
            if (mangled_input[idx] == 'F' && 
                mangled_input[idx+1] == 'A' &&
                mangled_input[idx+2] == 'I' &&
                mangled_input[idx+3] == 'L')
            {
                has_failure_tag = true;
                break;
            }
        }

        if (has_failure_tag)
        {
            *status_out = -1;
            return nullptr;
        }

        std::string transformed = std::string("demangled_") + std::string(mangled_input);
        char* allocated_buffer = static_cast<char*>(std::malloc(transformed.size() + 1));
        std::memcpy(allocated_buffer, transformed.c_str(), transformed.size() + 1);
        *status_out = 0;
        return allocated_buffer;
    }
};

class demangle_test_suite : public ::testing::Test
{
protected:
    void SetUp() override { mock_demangle_backend::invocation_counter = 0; }
};

TEST_F(demangle_test_suite, basic_success_case)
{
    rocprofsys::utility::demangler<mock_demangle_backend> instance;
    std::string output = instance.demangle("symbol");
    EXPECT_EQ(output, "demangled_symbol");
    EXPECT_EQ(mock_demangle_backend::invocation_counter, 1u);
}

TEST_F(demangle_test_suite, error_handling_preserves_original)
{
    rocprofsys::utility::demangler<mock_demangle_backend> instance;
    std::string output = instance.demangle("symbol_FAIL");
    EXPECT_EQ(output, "symbol_FAIL");
    EXPECT_EQ(mock_demangle_backend::invocation_counter, 1u);
}

TEST_F(demangle_test_suite, empty_input_no_call_made)
{
    rocprofsys::utility::demangler<mock_demangle_backend> instance;
    std::string output = instance.demangle("");
    EXPECT_TRUE(output.empty());
    EXPECT_EQ(mock_demangle_backend::invocation_counter, 0u);
}

TEST_F(demangle_test_suite, repeated_requests_use_cached_result)
{
    rocprofsys::utility::demangler<mock_demangle_backend> instance;
    std::string first  = instance.demangle("symbol");
    std::string second = instance.demangle("symbol");
    std::string third  = instance.demangle("symbol");

    EXPECT_EQ(first, "demangled_symbol");
    EXPECT_EQ(first, second);
    EXPECT_EQ(second, third);
    EXPECT_EQ(mock_demangle_backend::invocation_counter, 1u);
}

TEST_F(demangle_test_suite, distinct_inputs_are_independently_cached)
{
    rocprofsys::utility::demangler<mock_demangle_backend> instance;
    std::string res_a = instance.demangle("symbolA");
    std::string res_b = instance.demangle("symbolB");
    std::string res_a_again = instance.demangle("symbolA");

    EXPECT_EQ(res_a, "demangled_symbolA");
    EXPECT_EQ(res_b, "demangled_symbolB");
    EXPECT_EQ(res_a, res_a_again);
    EXPECT_EQ(mock_demangle_backend::invocation_counter, 2u);
}

TEST_F(demangle_test_suite, string_view_support_works_correctly)
{
    rocprofsys::utility::demangler<mock_demangle_backend> instance;
    std::string storage = "symbol";
    std::string_view view{storage};
    std::string result = instance.demangle(view);
    EXPECT_EQ(result, "demangled_symbol");
    EXPECT_EQ(mock_demangle_backend::invocation_counter, 1u);
}

TEST_F(demangle_test_suite, template_syntax_for_type_demangling)
{
    rocprofsys::utility::demangler<mock_demangle_backend> instance;
    std::string result = instance.demangle<int>();
    EXPECT_NE(result.find("demangled_"), std::string::npos);
    EXPECT_FALSE(result.empty());
}

TEST_F(demangle_test_suite, failed_demangle_is_cached_as_well)
{
    rocprofsys::utility::demangler<mock_demangle_backend> instance;
    std::string first  = instance.demangle("FAIL_symbol");
    std::string second = instance.demangle("FAIL_symbol");

    EXPECT_EQ(first, "FAIL_symbol");
    EXPECT_EQ(first, second);
    EXPECT_EQ(mock_demangle_backend::invocation_counter, 1u);
}

TEST_F(demangle_test_suite, separate_instances_do_not_share_cache)
{
    rocprofsys::utility::demangler<mock_demangle_backend> inst1;
    rocprofsys::utility::demangler<mock_demangle_backend> inst2;

    inst1.demangle("symbol");
    inst2.demangle("symbol");

    EXPECT_EQ(mock_demangle_backend::invocation_counter, 2u);
}

