/*-------------------------------------------------------------------------
 * Function:	H5G_loc
 *
 * Purpose:	Acquire group location from an object identifier
 *
 * Return:	Success:	Non-negative value
 *		Failure:	Negative value
 *
 * Programmer:	Quincey Koziol
 *              Tuesday, September 13, 2005
 *
 *-------------------------------------------------------------------------
 */
herr_t
H5G_loc(hid_t obj_id, H5G_loc_t *location)
{
    herr_t      result = SUCCEED;
    FUNC_ENTER_NOAPI(FAIL)

    switch(H5I_get_type(obj_id)) {
        case H5I_FILE:
            {
                H5F_t *file_ptr;
                if(NULL == (file_ptr = (H5F_t *)H5I_object(obj_id)))
                    HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, FAIL, "invalid file ID")
                if(H5G_root_loc(file_ptr, location) < 0)
                    HGOTO_ERROR(H5E_SYM, H5E_BADVALUE, FAIL, "unable to create location for file")
            }
            break;

        case H5I_GENPROP_CLS:
        case H5I_GENPROP_LST:
            HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, FAIL, "property list does not have group location")

        case H5I_ERROR_CLASS:
        case H5I_ERROR_MSG:
        case H5I_ERROR_STACK:
            HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, FAIL, "error class/message/stack has no group location")

        case H5I_GROUP:
            {
                H5G_t *group_ptr;
                if(NULL == (group_ptr = (H5G_t *)H5I_object(obj_id)))
                    HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, FAIL, "invalid group ID")
                if(NULL == (location->oloc = H5G_oloc(group_ptr)))
                    HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, FAIL, "unable to get object location of group")
                if(NULL == (location->path = H5G_nameof(group_ptr)))
                    HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, FAIL, "unable to get path of group")
            }
            break;

        case H5I_DATATYPE:
            {
                H5T_t *dtype_ptr;
                if(NULL == (dtype_ptr = (H5T_t *)H5I_object(obj_id)))
                    HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, FAIL, "invalid type ID")
                if(NULL == (location->oloc = H5T_oloc(dtype_ptr)))
                    HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, FAIL, "unable to get object location of datatype")
                if(NULL == (location->path = H5T_nameof(dtype_ptr)))
                    HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, FAIL, "unable to get path of datatype")
            }
            break;

        case H5I_DATASPACE:
            HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, FAIL, "dataspace has no group location")

        case H5I_DATASET:
            {
                H5D_t *dataset_ptr;
                if(NULL == (dataset_ptr = (H5D_t *)H5I_object(obj_id)))
                    HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, FAIL, "invalid dataset ID")
                if(NULL == (location->oloc = H5D_oloc(dataset_ptr)))
                    HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, FAIL, "unable to get object location of dataset")
                if(NULL == (location->path = H5D_nameof(dataset_ptr)))
                    HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, FAIL, "unable to get path of dataset")
            }
            break;

        case H5I_ATTR:
            {
                H5A_t *attribute_ptr;
                if(NULL == (attribute_ptr = (H5A_t *)H5I_object(obj_id)))
                    HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, FAIL, "invalid attribute ID")
                if(NULL == (location->oloc = H5A_oloc(attribute_ptr)))
                    HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, FAIL, "unable to get object location of attribute")
                if(NULL == (location->path = H5A_nameof(attribute_ptr)))
                    HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, FAIL, "unable to get path of attribute")
            }
            break;

        case H5I_REFERENCE:
            HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, FAIL, "reference has no group location")

        case H5I_UNINIT:
        case H5I_BADID:
        case H5I_VFL:
        case H5I_NTYPES:
        default:
            HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, FAIL, "invalid object ID")
    }

done:
    FUNC_LEAVE_NOAPI(result)
}

