/*-------------------------------------------------------------------------
 * Function:	H5G_loc_find_by_idx_cb
 *
 * Purpose:	Callback for finding object by index order in group
 *
 * Return:	Non-negative on success/Negative on failure
 *
 * Programmer:	Quincey Koziol
 *              Monday, November 20, 2006
 *
 *-------------------------------------------------------------------------
 */
static herr_t
H5G_loc_find_by_idx_cb(H5G_loc_t H5_ATTR_UNUSED *grp_loc, const char H5_ATTR_UNUSED *name,
    const H5O_link_t H5_ATTR_UNUSED *lnk, H5G_loc_t *obj_loc, void *_udata,
    H5G_own_loc_t *own_loc)
{
    indexed_lookup_t *data = (indexed_lookup_t *)_udata;
    H5O_link_t found_link;
    hbool_t link_copied = FALSE;
    size_t remaining_links = H5L_NUM_LINKS;
    hbool_t obj_loc_valid = FALSE;
    hbool_t obj_exists = FALSE;
    herr_t ret_value = SUCCEED;

    FUNC_ENTER_NOAPI_NOINIT

    if(obj_loc == NULL)
        HGOTO_ERROR(H5E_SYM, H5E_NOTFOUND, FAIL, "group doesn't exist")

    if(H5G_obj_lookup_by_idx(obj_loc->oloc, data->idx_kind, data->iter_dir,
                data->offset, &found_link, data->dxpl) < 0)
        HGOTO_ERROR(H5E_SYM, H5E_NOTFOUND, FAIL, "link not found")

    link_copied = TRUE;

    if(H5G__link_to_loc(obj_loc, &found_link, data->result_loc) < 0)
        HGOTO_ERROR(H5E_SYM, H5E_CANTINIT, FAIL, "cannot initialize object location")

    obj_loc_valid = TRUE;

    if(H5G__traverse_special(obj_loc, &found_link, H5G_TARGET_NORMAL, &remaining_links, TRUE, 
                data->result_loc, &obj_exists, data->lapl, data->dxpl) < 0)
        HGOTO_ERROR(H5E_LINK, H5E_TRAVERSE, FAIL, "special link traversal failed")

done:
    if(link_copied)
        H5O_msg_reset(H5O_LINK_ID, &found_link);

    if(ret_value < 0 && obj_loc_valid)
        if(H5G_loc_free(data->result_loc) < 0)
            HDONE_ERROR(H5E_SYM, H5E_CANTRELEASE, FAIL, "can't free location")

    *own_loc = H5G_OWN_NONE;
    FUNC_LEAVE_NOAPI(ret_value)
}

