 * Function:	H5G_loc_get_comment_cb
 *
 * Purpose:	Callback for getting object comment
 *
 * Return:	Non-negative on success/Negative on failure
 *
 * Programmer:	Quincey Koziol
 *              Thursday, August 30, 2007
 *
 *-------------------------------------------------------------------------
 */
static herr_t
H5G_loc_get_comment_cb(H5G_loc_t H5_ATTR_UNUSED *grp_loc, const char H5_ATTR_UNUSED *name, 
    const H5O_link_t H5_ATTR_UNUSED *lnk, H5G_loc_t *obj_loc, void *_udata,
    H5G_own_loc_t *own_loc)
{
    comment_getter_t *data = (comment_getter_t *)_udata;
    H5O_name_t comment_msg;
    herr_t ret_value = SUCCEED;

    FUNC_ENTER_NOAPI_NOINIT

    if(obj_loc == NULL)
        HGOTO_ERROR(H5E_SYM, H5E_NOTFOUND, FAIL, "name doesn't exist")

    comment_msg.s = NULL;

    if(NULL == H5O_msg_read(obj_loc->oloc, H5O_NAME_ID, &comment_msg, data->dxpl)) {
	if(data->buffer && data->buf_capacity > 0)
            data->buffer[0] = '\0';
	data->actual_length = 0;
    } else {
        if(data->buffer && data->buf_capacity)
	   HDstrncpy(data->buffer, comment_msg.s, data->buf_capacity);
	data->actual_length = (ssize_t)HDstrlen(comment_msg.s);
	H5O_msg_reset(H5O_NAME_ID, &comment_msg);
    }

done:
    *own_loc = H5G_OWN_NONE;
    FUNC_LEAVE_NOAPI(ret_value)
}

