#include <cstdint>
#include <cstdlib>
#include <cstring>
#include <cstdio>

// Alternative hash function using different operations but preserving properties
static uint32_t alternative_hash(const uint8_t *input_data, size_t length) {
    // Initialize with a different constant to ensure non-zero result for zero input
    uint32_t hash_value = 0x7A6F5E4D;

    // Process each byte with modified mixing operations
    for (size_t idx = 0; idx < length; ++idx) {
        hash_value ^= input_data[idx];
        hash_value += (hash_value << 5);
        hash_value ^= (hash_value >> 12);
        hash_value += (hash_value << 8);
    }

    // Final mixing with different constants and shifts
    hash_value ^= (hash_value << 7);
    hash_value += (hash_value >> 9);
    hash_value ^= (hash_value << 4);

    return hash_value;
}

extern "C" int LLVMFuzzerTestOneInput(const uint8_t *input, size_t len) {
    // Require minimum input length for meaningful processing
    if (len < 14)
        return 0;

    // Calculate hash of all but last 4 bytes
    uint32_t computed_hash = alternative_hash(input, len - 4);

    // Extract expected hash from last 4 bytes
    const uint32_t *expected_ptr = reinterpret_cast<const uint32_t *>(&input[len - 4]);
    uint32_t expected_hash = *expected_ptr;

    // Check for collision
    if (computed_hash != expected_hash)
        return 0;

    // Report success when hash matches
    fprintf(stderr, "SUCCESS: Hash collision found! %08x == %08x\n", 
            computed_hash, expected_hash);
    abort();

    return 0;
}

#include "group_sum_matrix.h"
#include <cassert>

template <typename T>
IGL_INLINE void igl::group_sum_matrix(
  const Eigen::Matrix<int,Eigen::Dynamic,1> & G,
  const int k,
  Eigen::SparseMatrix<T>& A)
{
  // Determine number of vertices (entries in G)
  const int n = G.size();

  // Ensure group indices are valid: all values in G must be less than k
  assert(k > 0);
  assert(G.empty() || G.maxCoeff() < k);

  // Resize sparse matrix to have k rows (groups) and n columns (vertices)
  A.resize(k, n);

  // Insert entries into sparse matrix:
  // For each vertex j, set A(G(j), j) = 1 to indicate vertex j belongs to group G(j)
  for (int j = 0; j < n; ++j) {
    A.insert(G(j), j) = static_cast<T>(1);
  }

  // Compress the matrix to optimize storage and operations
  A.makeCompressed();
}

// Overload that automatically determines number of groups from input data
template <typename T>
IGL_INLINE void igl::group_sum_matrix(
  const Eigen::Matrix<int,Eigen::Dynamic,1> & G,
  Eigen::SparseMatrix<T>& A)
{
  // Compute number of groups as max index + 1 (assuming zero-based indexing)
  const int num_groups = G.empty() ? 0 : (G.maxCoeff() + 1);
  return group_sum_matrix(G, num_groups, A);
}

