      gpuNodeIdx++;
    }

    system->nodes[NET].count = 1;
    system->nodes[NET].nodes[0].type = NET;
    system->nodes[NET].nodes[0].id = 0x100;

    int netLinkIdx = 0;
    while (netLinkIdx < 3) {
      system->nodes[GPU].nodes[netLinkIdx].paths[NET] =
          (struct ncclTopoLinkList *)calloc(1, sizeof(struct ncclTopoLinkList));
      struct ncclTopoLink *link =
          (struct ncclTopoLink *)calloc(1, sizeof(struct ncclTopoLink));
      link->type = PATH_NET;
      link->remNode = &system->nodes[NET].nodes[0];
      system->nodes[GPU].nodes[netLinkIdx].paths[NET][0].count = 1;
      system->nodes[GPU].nodes[netLinkIdx].paths[NET][0].list[0] = link;
      system->nodes[GPU].nodes[netLinkIdx].paths[NET][0].type = PATH_PXB;
      system->nodes[GPU].nodes[netLinkIdx].paths[NET][0].bw = 200.0;
      netLinkIdx++;
