LoadingSpinner::LoadingSpinner(QWidget* parent)
    : QLabel(parent)
    , m_rotation(0)
{
    setMinimumSize(60, 60);
    setMaximumSize(60, 60);
    setContentsMargins(0, 0, 0, 0);

    m_timer = new QTimer(this);
    connect(m_timer, &QTimer::timeout, this, &LoadingSpinner::spin);
}

void LoadingSpinner::begin() {
    m_timer->start(50);
    setVisible(true);
}

void LoadingSpinner::end() {
    m_timer->stop();
    setVisible(false);
}

void LoadingSpinner::spin() {
    m_rotation = (m_rotation + 30) % 360;
    update();
}

void LoadingSpinner::paintEvent(QPaintEvent* event) {
    Q_UNUSED(event);

    QPainter painter(this);
    painter.setRenderHint(QPainter::Antialiasing, true);

    // Material Design 3 circular progress indicator
    QPen strokePen(Colors::toQColor(Colors::PRIMARY), 3);
    strokePen.setCapStyle(Qt::RoundCap);
    painter.setPen(strokePen);

    QRect arcRect(10, 10, 40, 40);
    int initialAngle = -m_rotation * 16;
    int sweepAngle = 270 * 16;
    painter.drawArc(arcRect, initialAngle, sweepAngle);
}

