struct Reference_WDF
{
    // Resistor network definitions
    chowdsp::wdft::ResistorT<float> R1 { 1.0e3f };
    chowdsp::wdft::ResistorT<float> R2 { 5.0e3f };
    chowdsp::wdft::WDFSeriesT<float, decltype(R1), decltype(R2)> S1 { R1, R2 };
    chowdsp::wdft::ResistorT<float> R3 { 4.0e3f };
    chowdsp::wdft::WDFSeriesT<float, decltype(S1), decltype(R3)> S2 { S1, R3 };
    chowdsp::wdft::ResistorT<float> R4 { 10.0e3f };
    chowdsp::wdft::ResistorT<float> R5 { 3.0e3f };
    chowdsp::wdft::WDFParallelT<float, decltype(R4), decltype(R5)> P1 { R4, R5 };
    chowdsp::wdft::WDFParallelT<float, decltype(S2), decltype(P1)> P2 { S2, P1 };

    // Capacitor network definitions
    chowdsp::wdft::CapacitorT<float> C1 { 1.0e-6f };
    chowdsp::wdft::CapacitorT<float> C2 { 5.0e-6f };
    chowdsp::wdft::WDFSeriesT<float, decltype(C1), decltype(C2)> S4 { C1, C2 };
    chowdsp::wdft::CapacitorT<float> C3 { 4.0e-9f };
    chowdsp::wdft::WDFSeriesT<float, decltype(S4), decltype(C3)> S5 { S4, C3 };
    chowdsp::wdft::CapacitorT<float> C4 { 10.0e-9f };
    chowdsp::wdft::CapacitorT<float> C5 { 3.0e-6f };
    chowdsp::wdft::WDFParallelT<float, decltype(C4), decltype(C5)> P3 { C4, C5 };
    chowdsp::wdft::WDFParallelT<float, decltype(S5), decltype(P3)> P4 { S5, P3 };

    // Combine resistor & capacitor branches
    chowdsp::wdft::WDFSeriesT<float, decltype(P2), decltype(P4)> S3 { P2, P4 };

    // Additional series stages
    chowdsp::wdft::ResistorT<float> R6 { 10.0e3f };
    chowdsp::wdft::WDFSeriesT<float, decltype(S3), decltype(R6)> S6 { S3, R6 };
    chowdsp::wdft::CapacitorT<float> C6 { 4.0e-6f };
    chowdsp::wdft::WDFSeriesT<float, decltype(S6), decltype(C6)> S7 { S6, C6 };

    // Parallel RC stage
    chowdsp::wdft::ResistorT<float> R7 { 10.0e3f };
    chowdsp::wdft::CapacitorT<float> C7 { 10.0e-6f };
    chowdsp::wdft::WDFParallelT<float, decltype(R7), decltype(C7)> P5 { R7, C7 };
    chowdsp::wdft::ResistorT<float> R8 { 100.0e3f };
    chowdsp::wdft::WDFParallelT<float, decltype(P5), decltype(R8)> P6 { P5, R8 };
    chowdsp::wdft::CapacitorT<float> C8 { 100.0e-9f };
    chowdsp::wdft::WDFParallelT<float, decltype(P6), decltype(C8)> P7 { P6, C8 };

    // Final串联 + load
    chowdsp::wdft::WDFSeriesT<float, decltype(S7), decltype(P7)> S8 { S7, P7 };
    chowdsp::wdft::ResistorT<float> Rl { 100.0e3f };
    chowdsp::wdft::WDFSeriesT<float, decltype(Rl), decltype(S8)> Sl { Rl, S8 };
    chowdsp::wdft::ResistorT<float> Rv2 { 5.0e3f };
    chowdsp::wdft::WDFSeriesT<float, decltype(Rv2), decltype(Sl)> Sv2 { Rv2, Sl };
    chowdsp::wdft::ResistorT<float> Rv1 { 10.0e3f };
    chowdsp::wdft::WDFSeriesT<float, decltype(Rv1), decltype(Sv2)> Sv1 { Rv1, Sv2 };

    chowdsp::wdft::IdealVoltageSourceT<float, decltype(Sv1)> Vin { Sv1 };

    void prepare(float sample_rate)
    {
        // No-op for reference implementation
    }

    float process(float input_voltage)
    {
        Vin.setVoltage(input_voltage);
        Vin.incident(Sv1.reflected());
        Sv1.incident(Vin.reflected());
        return chowdsp::wdft::voltage<float>(Rl);
    }
};

int main()
{
    std::cout << "Reductions Circuit test\n";
    static constexpr float sample_rate = 48000.0f;
    Reference_WDF ref_model {};
    ref_model.prepare(sample_rate);

    Impedances impedance_data {};
    calc_impedances(
        impedance_data,
        sample_rate,
        {
            .R2_value = ref_model.R2.wdf.R,
            .R4_value = ref_model.R4.wdf.R,
            .C2_value = ref_model.C2.C_value,
            .C4_value = ref_model.C4.C_value,
        });

    State simulation_state {};

    static constexpr int num_samples = 100;
    std::array<float, num_samples> reference_results {};
    float peak_deviation = 0.0f;

    int idx = 0;
    while (idx < num_samples)
    {
        const auto simulated_output = process(simulation_state, impedance_data, 1.0f);
        reference_results[idx] = ref_model.process(1.0f);
        const auto deviation = std::abs(simulated_output - reference_results[idx]);
        if (deviation > peak_deviation)
            peak_deviation = deviation;
        ++idx;
    }

    std::cout << "Peak Deviation: " << peak_deviation << '\n';
    if (peak_deviation > 1.0e-3f)
    {
        std::cout << "Deviation exceeds threshold... test failed!\n";
        return 1;
    }

    std::ofstream bin_file { "data.bin", std::ios::out | std::ios::binary };
    bin_file.write(reinterpret_cast<const char*>(reference_results.data()), num_samples * sizeof(float));
    bin_file.close();

#if RUN_BENCH
