    {
        event_aggregate agg {};
        float accumulator = 0.0f;
        for (int rep = 0; rep < num_repeats; ++rep)
        {
            for (int k = 0; k < batch_size; ++k)
                input_buffer[k] = distribution(rng);

            collector.start();
