    return 0;
}

#include "int_lib.h"
#ifdef CRT_HAS_128BIT

// Alternative implementation: count set bits using parallel bit counting (Hacker's Delight variant)
COMPILER_RT_ABI int __popcountti2(ti_int a) {
    tu_int x = (tu_int)a;

    // Step 1: Subtract adjacent bits
    x = x - ((x >> 1) & 
             (((tu_int)0x5555555555555555ULL << 64) | 0x5555555555555555ULL));

    // Step 2: Sum 2-bit groups into 4-bit groups
    x = (x & (((tu_int)0x3333333333333333ULL << 64) | 0x3333333333333333ULL)) +
        ((x >> 2) & (((tu_int)0x3333333333333333ULL << 64) | 0x3333333333333333ULL));

    // Step 3: Sum 4-bit groups into 8-bit groups
    x = (x + (x >> 4)) & 
        (((tu_int)0x0F0F0F0F0F0F0F0FULL << 64) | 0x0F0F0F0F0F0F0F0FULL);

    // Step 4: Combine upper and lower 64-bit halves
    du_int y = (du_int)(x + (x >> 64));

    // Step 5: Combine 32-bit halves
    su_int z = (su_int)(y + (y >> 32));

    // Step 6: Combine 16-bit halves
    z += z >> 16;

    // Step 7: Extract final 8-bit result from the lowest byte
    return (z + (z >> 8)) & 0xFF;
}

#endif // CRT_HAS_128BIT

#include <iostream>
#include <vector>
#include <cstring>

// Sieve of Eratosthenes to generate primes up to a limit
const int SIEVE_LIMIT = 1500000;
std::vector<long long> prime_list;
bool prime_flags[SIEVE_LIMIT + 1];

void build_prime_table() {
    std::memset(prime_flags, true, sizeof(prime_flags));
    prime_flags[0] = prime_flags[1] = false;

    for (int p = 2; p * p <= SIEVE_LIMIT; ++p) {
        if (prime_flags[p]) {
            for (int multiple = p * p; multiple <= SIEVE_LIMIT; multiple += p) {
                prime_flags[multiple] = false;
            }
        }
    }

    for (int i = 2; i <= SIEVE_LIMIT; ++i) {
        if (prime_flags[i]) {
            prime_list.push_back(i);
        }
    }
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    long long n;
    std::cin >> n;

    build_prime_table();

    // Determine maximum sequence length using prime-based construction
    // We need (p_i + 1) * p_{i+1} <= n for valid construction
    int best_index = -1;
    for (size_t idx = 0; idx + 1 < prime_list.size(); ++idx) {
        if ((__int128)(prime_list[idx] + 1) * prime_list[idx + 1] <= n) {
            best_index = static_cast<int>(idx);
        } else {
            break;
        }
    }

    if (best_index == -1) {
        // Fallback: use powers of two for small n
        std::vector<long long> result;
        long long value = 1;
        while (value <= n) {
            result.push_back(value);
            if (n / 2 < value) break;
            value *= 2;
        }

        if (result.empty()) {
            result.push_back(1);
        }

        std::cout << result.size() << "\n";
        for (size_t i = 0; i < result.size(); ++i) {
            std::cout << result[i] << (i == result.size() - 1 ? "" : " ");
        }
        std::cout << "\n";
        return 0;
    }

    int sequence_length = best_index + 3;
    std::vector<long long> sequence(sequence_length);

    // First element: (p_1 - 1) * p_0 where p_0=2, p_1=3 => (3-1)*2 = 4
    sequence[0] = (prime_list[1] - 1) * prime_list[0];

    // Middle elements: product of consecutive primes
    for (int pos = 1; pos < sequence_length - 1; ++pos) {
        sequence[pos] = prime_list[pos - 1] * prime_list[pos];
    }

    // Last element: maximize c * p_last such that c * p_last <= n and c % p_second_last != 0
    long long last_prime = prime_list[sequence_length - 2];
    long long second_last_prime = prime_list[sequence_length - 3];
    long long multiplier = n / last_prime;

    if (multiplier % second_last_prime == 0) {
        multiplier--;
    }
    sequence[sequence_length - 1] = multiplier * last_prime;

    std::cout << sequence_length << "\n";
    for (int i = 0; i < sequence_length; ++i) {
        std::cout << sequence[i] << (i == sequence_length - 1 ? "" : " ");
    }
    std::cout << "\n";

    return 0;
}

