		NewGraph->Schema = UDataprepGraphSchema::StaticClass();
		NewGraph->Initialize(FoundAsset);

		// Construct the editor widget bound to this graph and asset
		GraphEditor = SNew(SDataprepGraphEditor, FoundAsset)
			.Appearance(VisualStyle)
			.TitleBar(HeaderWidget)
			.GraphToEdit(NewGraph)
			.DataprepEditor(StaticCastSharedRef<FDataprepEditor>(this->AsShared()));
	}
}

