// Precomputed irreducible polynomials for GF(2^k), k = 1..15 (as integers)
const int irreducible_polys[] = {
    0, 
    3,      // k=1: x + 1
    7,      // k=2: x^2 + x + 1
    11,     // k=3: x^3 + x + 1
    19,     // k=4: x^4 + x + 1
    37,     // k=5: x^5 + x^2 + 1
    67,     // k=6: x^6 + x + 1
    131,    // k=7: x^7 + x + 1
    283,    // k=8: x^8 + x^4 + x^3 + x + 1
    515,    // k=9: x^9 + x + 1
    1033,   // k=10: x^10 + x^3 + 1
    2053,   // k=11: x^11 + x^2 + 1
    4105,   // k=12: x^12 + x^3 + 1
    8219,   // k=13: x^13 + x^4 + x^3 + x + 1
    16427,  // k=14: x^14 + x^5 + x^3 + x + 1
    32771   // k=15: x^15 + x + 1
};

// Multiply two elements in GF(2^k) modulo the given polynomial
int gf_multiply(int a, int b, int degree, int poly_mod) {
    int result = 0;
    for (int bit = 0; bit < degree; ++bit) {
        if ((b >> bit) & 1) {
            result ^= a;
        }
        bool high_bit_set = (a >> (degree - 1)) & 1;
        a <<= 1;
        if (high_bit_set) {
            a ^= poly_mod;
        }
        a &= ((1 << degree) - 1);
    }
    return result;
}

// Compute cube of an element in GF(2^k): a^3 = a * a * a
int gf_cube(int value, int deg, int mod_poly) {
    int square = gf_multiply(value, value, deg, mod_poly);
    return gf_multiply(square, value, deg, mod_poly);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int upper_bound;
    if (!(cin >> upper_bound)) return 0;

    vector<int> optimal_set;

    // Try algebraic construction using Sidon sets over GF(2^k)
    // S = { x * 2^k XOR x^3 } for x in GF(2^k)
    for (int k = 1; k <= 15; ++k) {
        // Early termination if field size is too large relative to n
        if ((1 << k) > upper_bound + 100 && k > 5) break;

        vector<int> candidate_set;
        int modulus = irreducible_polys[k];
        int field_size = 1 << k;

        int max_x = min(field_size, (upper_bound >> k) + 2);
        for (int x = 1; x < max_x; ++x) {
            int x_cubed = gf_cube(x, k, modulus);
            long long constructed_val = ((long long)x << k) ^ x_cubed;
            if (constructed_val >= 1 && constructed_val <= upper_bound) {
                candidate_set.push_back(static_cast<int>(constructed_val));
            }
        }

        if (candidate_set.size() > optimal_set.size()) {
            optimal_set = move(candidate_set);
        }
    }

    // For small inputs, use greedy algorithm to potentially improve results
    if (upper_bound < 500) {
        vector<int> greedy_set;
        greedy_set.push_back(1);
        vector<bool> xor_used(2048, false); // Track used XOR differences

        for (int candidate = 2; candidate <= upper_bound; ++candidate) {
            bool valid = true;
            for (int existing : greedy_set) {
                int diff = candidate ^ existing;
                if (diff < 2048 && xor_used[diff]) {
                    valid = false;
                    break;
                }
            }

            if (valid) {
                for (int existing : greedy_set) {
                    int diff = candidate ^ existing;
                    if (diff < 2048) xor_used[diff] = true;
                }
                greedy_set.push_back(candidate);
            }
        }

        if (greedy_set.size() > optimal_set.size()) {
            optimal_set = move(greedy_set);
        }
    }

    // Output result
    cout << optimal_set.size() << "\n";
    for (size_t idx = 0; idx < optimal_set.size(); ++idx) {
        cout << optimal_set[idx];
        if (idx != optimal_set.size() - 1) cout << " ";
    }
    cout << "\n";

    return 0;
}

