// Helper function to convert QRectF to QRect with proper rounding
inline QRect convertToRect(const QRectF& rect) {
    QPoint top_left = rect.topLeft().toPoint();
    QPoint bottom_right = rect.bottomRight().toPoint();
    bottom_right -= QPoint(1, 1);
    return QRect(top_left, bottom_right);
}

