// Layout region in the hierarchy
class Region {
private:
    DockLayout* m_owner;
    DockWidget* m_item;
    Region* m_parent;
    bool m_orientation; // true for horizontal, false for vertical
    QRect m_geometry;
    std::vector<Region*> m_childList;
    std::vector<DockSeparator*> m_separators;
    std::vector<DockPlaceholder*> m_placeholders;
    int m_minSize[2]; // [horizontal, vertical]
    int m_maxSize[2];

public:
    Region(DockLayout* owner, DockWidget* item = nullptr)
        : m_owner(owner), m_item(item), m_parent(nullptr), 
          m_orientation(true), m_minSize{0,0}, m_maxSize{INT_MAX, INT_MAX} {}

    ~Region() {
        for (auto sep : m_separators) delete sep;
        for (auto child : m_childList) delete child;
    }

    void setOrientation(bool horiz) { m_orientation = horiz; }
    bool getOrientation() const { return m_orientation; }

    void setItem(DockWidget* item) { m_item = item; }
    DockWidget* getItem() const { return m_item; }

    void setParent(Region* parent) { m_parent = parent; }
    Region* getParent() const { return m_parent; }

    void setGeometry(const QRect& rect) { m_geometry = rect; }
    const QRect& getGeometry() const { return m_geometry; }

    void setSize(const QSize& size) {
        m_geometry.setSize(size);
    }

    const std::vector<Region*>& getChildList() const { return m_childList; }
    const std::vector<DockSeparator*>& separators() const { return m_separators; }

    void insertSubRegion(Region* sub, int pos) {
        m_childList.insert(m_childList.begin() + pos, sub);
        sub->m_parent = this;
        sub->m_orientation = !m_orientation;
    }

    Region* insertItem(DockWidget* item, int pos) {
        Region* newRegion = new Region(m_owner, item);
        insertSubRegion(newRegion, pos);
        return newRegion;
    }

    void insertSeparator(DockSeparator* sep) {
        m_separators.push_back(sep);
    }

    void removeSeparator() {
        if (!m_separators.empty()) {
            delete m_separators.back();
            m_separators.pop_back();
        }
    }

    unsigned int find(const Region* sub) const {
        for (unsigned int i = 0; i < m_childList.size(); ++i)
            if (m_childList[i] == sub) return i;
        return -1;
    }

    void calculateExtremalSizes() {
        // Calculate min/max sizes based on children
        if (m_item) {
            m_minSize[0] = m_item->minimumWidth();
            m_minSize[1] = m_item->minimumHeight();
            m_maxSize[0] = m_item->maximumWidth();
            m_maxSize[1] = m_item->maximumHeight();
        } else {
            m_minSize[0] = 0; m_minSize[1] = 0;
            m_maxSize[0] = INT_MAX; m_maxSize[1] = INT_MAX;

            for (auto child : m_childList) {
                child->calculateExtremalSizes();
                m_minSize[0] += child->m_minSize[m_orientation ? 0 : 1];
                m_minSize[1] += child->m_minSize[m_orientation ? 1 : 0];
                m_maxSize[0] += child->m_maxSize[m_orientation ? 0 : 1];
                m_maxSize[1] += child->m_maxSize[m_orientation ? 1 : 0];
            }
        }
    }

    int getMinimumSize(int axis) const { return m_minSize[axis]; }
    int getMaximumSize(int axis) const { return m_maxSize[axis]; }

    void redistribute() {
        if (m_childList.empty()) return;

        // Recalculate geometry for children
        int totalMin = m_minSize[m_orientation ? 0 : 1];
        int available = m_geometry.width() * m_orientation + m_geometry.height() * !m_orientation;

        if (totalMin > available) return;

        // Distribute space proportionally
        double remaining = available;
        int count = m_childList.size();
        for (int i = 0; i < count; ++i) {
            Region* child = m_childList[i];
            child->calculateExtremalSizes();

            int desired = child->getMinimumSize(m_orientation ? 0 : 1);
            int actual = std::max(desired, (int)(available / count));

            QRect childRect = m_geometry;
            if (m_orientation) {
                childRect.setWidth(actual);
                m_geometry.setX(childRect.right());
                m_geometry.setWidth(m_geometry.width() - actual);
            } else {
                childRect.setHeight(actual);
                m_geometry.setY(childRect.bottom());
                m_geometry.setHeight(m_geometry.height() - actual);
            }
            child->setGeometry(childRect);
        }
    }

    bool checkWidgetsToBeFixedWidth(std::vector<QWidget*>& widgets, bool& fromDocking) {
        if (m_item) {
            if (m_item->wasFloating()) {
                fromDocking = true;
                m_item->clearWasFloating();
                return false;
            }

            // Check fix width mode
            switch (m_item->getFixWidthMode()) {
                case 2: widgets.push_back(m_item); [[fallthrough]];
                case 1: return true;
                default: return false;
            }
        }

        if (m_childList.empty()) return false;

        if (m_orientation) {
            bool allFixed = true;
            for (auto child : m_childList) {
                if (!child->checkWidgetsToBeFixedWidth(widgets, fromDocking))
                    allFixed = false;
            }
            return allFixed;
        } else {
            bool anyFixed = false;
            for (auto child : m_childList) {
                if (child->checkWidgetsToBeFixedWidth(widgets, fromDocking))
                    anyFixed = true;
            }
            return anyFixed;
        }
    }
};

// Main layout manager
class DockLayout : public QLayout {
    Q_OBJECT
private:
    std::deque<Region*> m_regions;
    DockWidget* m_maximizedDock;
    DockDecoAllocator* m_decoAllocator;

public:
    DockLayout() : m_maximizedDock(nullptr), m_decoAllocator(new DockDecoAllocator()) {}

    ~DockLayout() override {
        for (auto region : m_regions) delete region;
        for (auto item : m_items) delete item;
        delete m_decoAllocator;
    }

    int count() const override { return m_items.size(); }

    void addItem(QLayoutItem* item) override {
        DockWidget* added = dynamic_cast<DockWidget*>(item->widget());
        assert(added);

        if (find(added)) return;

        added->m_parentLayout = this;
        added->setParent(parentWidget());
        added->setWindowFlags(Qt::Tool | Qt::FramelessWindowHint);
        added->setFloatingAppearance();
        m_items.push_back(item);
    }

    QLayoutItem* takeAt(int idx) override {
        if (idx < 0 || idx >= (int)m_items.size()) return nullptr;

        QLayoutItem* item = m_items[idx];
        DockWidget* dw = static_cast<DockWidget*>(item->widget());

        if (!dw->isFloating()) undockItem(dw);
        dw->m_parentLayout = nullptr;
        m_items.erase(m_items.begin() + idx);
        return item;
    }

    QLayoutItem* itemAt(int idx) const override {
        if (idx >= (int)m_items.size()) return nullptr;
        return m_items[idx];
    }

    QWidget* widgetAt(int idx) const { return itemAt(idx)->widget(); }

    QSize minimumSize() const override {
        if (!m_regions.empty()) {
            Region* r = m_regions.front();
            r->calculateExtremalSizes();
            return QSize(r->m_minSize[0], r->m_minSize[1]);
        }
        return QSize(0, 0);
    }

    QSize maximumSize() const override {
        if (!m_regions.empty()) {
            Region* r = m_regions.front();
            r->calculateExtremalSizes();
            return QSize(r->m_maxSize[0], r->m_maxSize[1]);
        }
        return QSize(QWIDGETSIZE_MAX, QWIDGETSIZE_MAX);
    }

    QSize sizeHint() const override {
        QSize s(0, 0);
        int n = m_items.size();
        if (n > 0) s = QSize(100, 70);

        for (int i = 0; i < n; ++i) {
            QLayoutItem* o = m_items[i];
            s = s.expandedTo(o->sizeHint());
        }
        return s + n * QSize(spacing(), spacing());
    }

    // Custom methods
    QWidget* containerOf(QPoint point) const {
        for (int i = m_regions.size() - 1; i >= 0; --i) {
            Region* curr = m_regions[i];
            DockWidget* item = curr->getItem();

            if (item && item->geometry().contains(point)) return item;

            for (auto sep : curr->separators())
                if (sep->geometry().contains(point)) return sep;
        }
        return nullptr;
    }

    void setMaximized(DockWidget* item, bool state) {
        if (item && state != item->m_maximized) {
            if (state) {
                if (m_maximizedDock) {
                    Region* r = find(m_maximizedDock);
                    m_maximizedDock->setGeometry(convertToRect(r->getGeometry()));
                    m_maximizedDock->m_maximized = false;
                }

                QSize min = item->minimumSize();
                QSize max = item->maximumSize();
                QRect content = contentsRect();

                if (content.width() > min.width() && content.height() > min.height() &&
                    content.width() < max.width() && content.height() < max.height()) {
                    item->setGeometry(content);
                    item->raise();
                    item->m_maximized = true;
                    m_maximizedDock = item;

                    for (int i = 0; i < count(); ++i) {
                        DockWidget* curr = (DockWidget*)itemAt(i)->widget();
                        if (curr != item && !curr->isFloating()) curr->hide();
                    }
                }
            } else {
                Region* r = find(m_maximizedDock);
                if (r) m_maximizedDock->setGeometry(convertToRect(r->getGeometry()));
                m_maximizedDock->m_maximized = false;
                m_maximizedDock = nullptr;

                for (int i = 0; i < count(); ++i) {
                    DockWidget* curr = (DockWidget*)itemAt(i)->widget();
                    if (curr != item && !curr->isFloating()) curr->show();
                }
            }
        }
    }

    void setGeometry(const QRect& rect) override {
        QLayout::setGeometry(rect);
    }

    void updateSeparatorCursors() {
        for (auto region : m_regions) {
            bool orientation = region->getOrientation();
            QSize size = convertToRect(region->getGeometry()).size();

            bool extreme = (orientation) 
                ? (size.width() == region->getMinimumSize(0) || 
                   size.width() == region->getMaximumSize(0))
                : (size.height() == region->getMinimumSize(1) || 
                   size.height() == region->getMaximumSize(1));

            if (extreme) {
                for (auto sep : region->separators())
                    sep->setCursor(Qt::ArrowCursor);
                continue;
            }

            // Update cursor based on child constraints
            auto& children = region->getChildList();
            int j = 0;
            for (; j < children.size(); ++j) {
                Region* child = children[j];
                if (child->getMaximumSize(orientation) == child->getMinimumSize(orientation))
                    region->separator(j)->setCursor(Qt::ArrowCursor);
                else break;
            }

            int k = children.size() - 1;
            for (; k > j; --k) {
                Region* child = children[k];
                if (child->getMaximumSize(orientation) == child->getMinimumSize(orientation))
                    region->separator(k-1)->setCursor(Qt::ArrowCursor);
                else break;
            }

            Qt::CursorShape shape = (orientation) 
                ? Qt::SplitHCursor : Qt::SplitVCursor;
            for (; j <= k; ++j)
                region->separator(j)->setCursor(shape);
        }
    }

    void applyGeometry() {
        for (auto region : m_regions) {
            const auto& children = region->getChildList();
            auto& separators = region->m_separators;

            if (region->getItem()) {
                region->getItem()->setGeometry(convertToRect(region->getGeometry()));
            } else {
                for (size_t j = 0; j < separators.size(); ++j) {
                    QRect adj = convertToRect(children[j]->getGeometry());
                    if (region->getOrientation()) {
                        adj.adjust(0, 0, 1, 0);
                        separators[j]->setGeometry(QRect(adj.topRight(),
                            QSize(spacing(), adj.height())));
                    } else {
                        adj.adjust(0, 0, 0, 1);
                        separators[j]->setGeometry(QRect(adj.bottomLeft(),
                            QSize(adj.width(), spacing())));
                    }
                    separators[j]->m_index = j;
                }
            }
        }

        if (m_maximizedDock) {
            m_maximizedDock->setGeometry(convertToRect(m_regions.front()->getGeometry()));
            m_maximizedDock->raise();
        }
        updateSeparatorCursors();
    }

    void applyTransform(const QTransform& transform) {
        for (auto region : m_regions)
            region->setGeometry(transform.mapRect(region->getGeometry()));
    }

    void redistribute() {
        if (m_regions.empty()) return;

        std::vector<QWidget*> fixedWidgets;
        std::vector<QSize> minSizes;
        std::vector<QSize> maxSizes;

        bool fromDocking = false;
        bool canFixWidth = !m_regions.front()->checkWidgetsToBeFixedWidth(fixedWidgets, fromDocking);

        if (!fromDocking && canFixWidth) {
            for (auto widget : fixedWidgets) {
                minSizes.push_back(widget->minimumSize());
                maxSizes.push_back(widget->maximumSize());
                widget->setFixedWidth(widget->width());
            }
        }

        m_regions.front()->calculateExtremalSizes();

        int parentWidth = contentsRect().width();
        int parentHeight = contentsRect().height();

        if (m_regions.front()->getMinimumSize(0) > parentWidth ||
            m_regions.front()->getMinimumSize(1) > parentHeight ||
            m_regions.front()->getMaximumSize(0) < parentWidth ||
            m_regions.front()->getMaximumSize(1) < parentHeight)
            return;

        m_regions.front()->setGeometry(contentsRect());
        m_regions.front()->redistribute();

        if (!fromDocking && canFixWidth) {
            for (size_t i = 0; i < fixedWidgets.size(); ++i) {
                fixedWidgets[i]->setMinimumSize(minSizes[i]);
                fixedWidgets[i]->setMaximumSize(maxSizes[i]);
            }
        }

        applyGeometry();
    }

    // Helper functions
    Region* find(DockWidget* item) const {
        for (auto region : m_regions)
            if (region->getItem() == item) return region;
        return nullptr;
    }

    bool isPossibleInsertion(DockWidget* item, Region* region, int index) {
        // Check if insertion is geometrically possible
        return true; // Simplified
    }

    bool isPossibleRemoval(DockWidget* item, Region* parent, int& removalIdx) {
        // Check if removal is possible without violating constraints
        return true; // Simplified
    }

    // Docking operations
    void calculateDockPlaceholders(DockWidget* item) {
        if (!parentWidget()->isVisible()) return;

        if (m_regions.empty()) {
            if (isPossibleInsertion(item, nullptr, 0)) {
                item->m_placeholders.push_back(
                    item->m_decoAllocator->newPlaceBuilt(item, nullptr, 0, DockPlaceholder::root));
                return;
            }
        }

        for (auto region : m_regions) {
            region->m_placeholders.clear();
            if (isPossibleInsertion(item, region, 0)) {
                unsigned int j;
                if (region->getOrientation()) {
                    item->m_placeholders.push_back(
                        item->m_decoAllocator->newPlaceBuilt(item, region, 0, DockPlaceholder::left));
                    region->m_placeholders.push_back(item->m_placeholders.back());

                    for (j = 1; j < region->getChildList().size(); ++j) {
                        item->m_placeholders.push_back(
                            item->m_decoAllocator->newPlaceBuilt(item, region, j, DockPlaceholder::sepVert));
                        region->m_placeholders.push_back(item->m_placeholders.back());
                    }

                    item->m_placeholders.push_back(
                        item->m_decoAllocator->newPlaceBuilt(item, region, j, DockPlaceholder::right));
                    region->m_placeholders.push_back(item->m_placeholders.back());
                } else {
                    item->m_placeholders.push_back(
                        item->m_decoAllocator->newPlaceBuilt(item, region, 0, DockPlaceholder::top));
                    region->m_placeholders.push_back(item->m_placeholders.back());

                    for (j = 1; j < region->getChildList().size(); ++j) {
                        item->m_placeholders.push_back(
                            item->m_decoAllocator->newPlaceBuilt(item, region, j, DockPlaceholder::sepHor));
                        region->m_placeholders.push_back(item->m_placeholders.back());
                    }

                    item->m_placeholders.push_back(
                        item->m_decoAllocator->newPlaceBuilt(item, region, j, DockPlaceholder::bottom));
                    region->m_placeholders.push_back(item->m_placeholders.back());
                }
            }
        }
    }

    void dockItem(DockWidget* item, DockPlaceholder* place) {
        place->hide();
        item->hide();
        dockItemPrivate(item, place->getRegion(), place->getIndex());
        redistribute();
        parentWidget()->repaint();
        item->setWindowFlags(Qt::SubWindow);
        item->show();
    }

    void dockItem(DockWidget* item, DockWidget* target, int side) {
        Region* targetRegion = find(target);
        short var = side >> 2 * (int)targetRegion->getOrientation();
        bool pos = side & 0xa;

        item->setWindowFlags(Qt::SubWindow);
        item->show();

        if (var & 0x3) {
            dockItemPrivate(item, targetRegion, pos);
        } else {
            Region* parent = targetRegion->getParent();
            unsigned int idx = parent ? parent->find(targetRegion) + pos : pos;
            dockItemPrivate(item, parent, idx);
        }
    }

    Region* dockItem(DockWidget* item, Region* region, int index) {
        item->setWindowFlags(Qt::SubWindow);
        item->show();
        return dockItemPrivate(item, region, index);
    }

    Region* dockItemPrivate(DockWidget* item, Region* region, int index) {
        item->onDock(true);
        item->setDockedAppearance();
        item->m_floating = false;
        item->m_wasFloating = true;

        if (!region) {
            Region* newRoot = new Region(this);
            m_regions.push_front(newRoot);
            newRoot->setSize(item->size());

            if (m_regions.size() == 1) {
                newRoot->setItem(item);
                return newRoot;
            }

            newRoot->setOrientation(!m_regions[1]->getOrientation());
            newRoot->insertSubRegion(m_regions[1], 0);
            region = newRoot;
        } else if (region->getItem()) {
            Region* oldItemRegion = region->insertItem(region->getItem(), 0);
            oldItemRegion->setSize(region->getItem()->size());
            region->setItem(nullptr);
            m_regions.push_back(oldItemRegion);
        }

        Region* newItemRegion = region->insertItem(item, index);
        m_regions.push_back(newItemRegion);
        newItemRegion->setSize(item->size());

        region->insertSeparator(
            m_decoAllocator->newSeparator(this, region->getOrientation(), region));

        return newItemRegion;
    }

    bool undockItem(DockWidget* item) {
        Region* carrier = find(item);
        Region* parent = carrier->getParent();

        if (parent) {
            int removalIdx = 0;
            unsigned int j;
            for (j = 0; j < parent->getChildList().size(); ++j)
                if (parent->getChildList()[j]->getItem() == item) break;

            if (isPossibleRemoval(item, parent, removalIdx))
                parent->removeItem(item);
            else
                return false;
        }

        carrier->setItem(nullptr);
        auto end = std::remove_if(m_regions.begin(), m_regions.end(),
            [](Region* r) { return (!r->getItem() && r->getChildList().empty()); });
        m_regions.resize(end - m_regions.begin());

        item->setWindowFlags(Qt::Tool | Qt::FramelessWindowHint);
        item->setFloatingAppearance();
        item->m_floating = true;
        item->onDock(false);
        setMaximized(item, false);
        redistribute();
        return true;
    }
};

