unsigned int Opaque::safe_pred(const unsigned int value) {
    if (value == 0U) {
        throw std::logic_error("absurd case");
    }
    return value - 1U;
}

unsigned int Opaque::pred_of_succ(const unsigned int input) {
    const unsigned int incremented = input + 1U;
    return safe_pred(incremented);
}

bool Opaque::nat_eq_dec(const unsigned int first, const unsigned int second) {
    // Handle base cases: zero comparisons
    if (first == 0U) {
        return second == 0U;
    }

    if (second == 0U) {
        return false;
    }

    // Both are positive: recursively compare predecessors
    return nat_eq_dec(first - 1U, second - 1U);
}

bool Opaque::are_equal(const unsigned int left, const unsigned int right) {
    return nat_eq_dec(left, right);
}

