// Hook body wrapper: saves registers, calls callback, restores context
static __attribute__((naked)) void hookBody() {
    asm volatile (
        "mov r5, sp\n"
        "str r0, [r4, #0x0c]\n"
        "str r1, [r4, #0x10]\n"
        "str r2, [r4, #0x14]\n"
        "str r3, [r4, #0x18]\n"
        "str lr, [r4, #0x1c]\n"
        "str sp, [r4, #0x20]\n"
        "ldr r6, [r4, #0x4]\n"
        "bl lc_setCoreHookState\n"
        "mov r0, r4\n"
        "blx r6\n"
        "mov sp, r5\n"
        "add r6, r4, #0x24\n"
        "bx r6"
    );
}

u32 getStackPointerFromCtx(CoreHookContext *hookContext) {
    return hookContext->sp + 4 * 14;
}

// Restore stack and jump to return address
__attribute__((naked)) void hookReturnOverwrite(CoreHookContext *hookContext, u32 returnCallback) {
    asm volatile (
        "ldr sp, [r0, #0x20]\n"
        "add sp, sp, #0x10\n"
        "ldmia sp!, {r4-r12, lr}\n"
        "mov r2, r1\n"
        "ldr r1, [r0, #0x10]\n"
        "ldr r0, [r0, #0x0c]\n"
        "bx r2\n"
    );
}

// Main hooking function: patches target function with hook stub
void installFunctionHook(u32 funcTarget, u32 callbackAddr) {
    const u32 prologue[] = {
        0xE92D5FFF, // stmdb sp!, {r0-r12, lr}
        0xE59F4004, // ldr r4, [pc, #0x4]
        0xE5945000, // ldr r5, [r4, #0x0]
        0xE12FFF15, // bx r5
    };

    auto hookCtx = std::make_unique<CoreHookContext>();
    hookCtx->wrapCallbackAddress = (u32)hookBody;
    hookCtx->targetAddress = funcTarget;
    hookCtx->callbackAddress = callbackAddr;
    hookCtx->restoreIns = 0xE8BD5FFF; // ldmia sp!, {r0-r12, lr}
    hookCtx->jmpIns = 0xE51FF004;     // ldr pc, [pc, #-0x4]
    hookCtx->returnAddress = funcTarget + 4 * 5;

    // Save original instructions
    for (int i = 0; i < 5; ++i) {
        hookCtx->overwrittenIns[i] = *(((u32*)funcTarget) + i);
    }

    CoreHookContext* ctxPtr = hookCtx.get();
    activeHooks.push_back(std::move(hookCtx));

    // Patch target function
    *(u32*)funcTarget = prologue[0];
    *((u32*)funcTarget + 1) = prologue[1];
    *((u32*)funcTarget + 2) = prologue[2];
    *((u32*)funcTarget + 3) = prologue[3];
    *((u32*)funcTarget + 4) = (u32)ctxPtr;
}

