// Rate limiting for debug logging
#define MAX_LOG_CALLS 10
#define LOG_WINDOW_MS 1000
#define BAN_DURATION_MS 10000

static u64 log_window_start = 0;
static u64 log_ban_until = 0;
static int log_call_count = 0;

static bool isLogCallAllowed(void) {
    u64 currentTime = osGetTime();
    if (currentTime < log_ban_until)
        return false;

    if (currentTime - log_window_start > LOG_WINDOW_MS) {
        log_window_start = currentTime;
        log_call_count = 0;
    }

    log_call_count++;
    if (log_call_count >= MAX_LOG_CALLS) {
        log_ban_until = currentTime + BAN_DURATION_MS;
        return false;
    }
    return true;
}

extern "C" void GameDebugLogfHandler(u32 ukn1, u32 ukn2, const char* author, u32 ukn3, const char* fmt, ...) {
    va_list args;
    va_start(args, fmt);

    if (isLogCallAllowed() && strcmp(author, "BuildGeometry") != 0 && strcmp(author, "loadChunk") != 0) {
        char buffer[0x200] = {};
        int len = vsnprintf(buffer, sizeof(buffer), fmt, args);
        if (len > 0 && buffer[len - 1] == '\n')
            buffer[len - 1] = '\0';

        std::string prefix;
        if (ukn2 == 2)
            prefix = "[Game.Info] ";
        else if (ukn2 == 8)
            prefix = "[Game.Warn] ";
        else
            prefix = " ";

        Core::Debug::LogInfo(prefix + std::string(author) + ": " + buffer);
    }

    va_end(args);
}

static __attribute__((naked)) void GameDebugLogfWrapper(CoreHookContext* ctx) {
    asm volatile (
        "ldmia sp!, {r0-r12, lr}\n"
        "b GameDebugLogfHandler\n"
    );
}

