//--------------------------------------------------------------------------
// Custom plugin context for tracing instructions with a different control flow
struct trace_plugin_ctx : public plugmod_t, public event_listener_t
{
  int insn_counter = 0;
  const int max_traced_instructions = 20;

  ~trace_plugin_ctx()
  {
    // Event listeners are automatically cleaned up on module unload
  }

  virtual bool idaapi run(size_t) override;
  virtual ssize_t idaapi on_event(ssize_t notification_code, va_list args) override;
};

//--------------------------------------------------------------------------
// Event handler with refactored logic and variable names
ssize_t idaapi trace_plugin_ctx::on_event(ssize_t notification_code, va_list args)
{
  switch ( notification_code )
  {
    case dbg_process_start:
      // Reset the instruction counter at process start
      insn_counter = 0;
      break;

    case dbg_run_to:
      msg("tracer: reached entry point\n");
      enable_insn_trace(true);
      request_continue_process();
      run_requests();
      break;

    case dbg_trace:
      {
        // Extract thread ID and instruction pointer from arguments
        /*thid_t tid =*/ va_arg(args, thid_t);
        ea_t current_ip = va_arg(args, ea_t);
        msg("[%d] traced instruction at: %a\n", insn_counter, current_ip);

        if ( insn_counter == max_traced_instructions )
        {
          // Terminate tracing and suspend execution
          disable_step_trace();
          suspend_process();
          msg("execution suspended after tracing %d instructions\n", max_traced_instructions);
        }
        else
        {
          insn_counter++;
        }
      }
      break;

    case dbg_process_exit:
      unhook_event_listener(HT_DBG, this);
      break;
  }
  return 0;
}

//--------------------------------------------------------------------------
// Plugin initialization and debugger setup
bool idaapi trace_plugin_ctx::run(size_t)
{
  if ( !hook_event_listener(HT_DBG, this) )
  {
    warning("Failed to attach to debug events");
    return true;
  }

  if ( dbg == nullptr )
    load_debugger("win32", false);

  // Attempt to run to the program's entry point
  if ( !run_to(inf_get_start_ea()) )
    unhook_event_listener(HT_DBG, this);

  return true;
}

//--------------------------------------------------------------------------
// Plugin initialization function
static plugmod_t *idaapi init()
{
  // Restrict plugin to x86 PE executables only
  if ( PH.id != PLFM_386 || inf_get_filetype() != f_PE )
    return nullptr;

  return new trace_plugin_ctx;
}

