using ScalarType = double;
using IndexType = std::vector<ScalarType>::size_type;

void execute_validation(MPI_Comm comm, const ROL::Ptr<std::ostream>& log);

int main(int argc, char* argv[]) {
    using ROL::Ptr;
    using ROL::makePtr;
    using ROL::makePtrFromRef;

    ROL::GlobalMPISession session(&argc, &argv);
    int rank = ROL::GlobalMPISession::getRank();
    auto logger = ROL::makeStreamPtr(std::cout, argc > 1 && rank == 0);
    int status = 0;

    try {
        execute_validation(MPI_COMM_WORLD, logger);
    }
    catch (const std::exception& ex) {
        *logger << "Exception caught:\n" << ex.what() << "\n";
        status = -999;
    }

    if (rank == 0) {
        if (status != 0)
            std::cout << "Final Result: TEST FAILED\n";
        else
            std::cout << "Final Result: TEST PASSED\n";
    }

    return status;
}

void execute_validation(MPI_Comm comm, const ROL::Ptr<std::ostream>& log) {
    using ROL::Ptr;
    using ROL::makePtr;
    using ROL::makePtrFromRef;

    int totalRanks = -1;
    int myRank = -1;
    MPI_Comm_size(comm, &totalRanks);
    MPI_Comm_rank(comm, &myRank);

    *log << "Rank " << myRank << "/" << totalRanks << "\n";

    // Setup communication infrastructure
    Ptr<const ROL::PinTCommunicators> pintComms = makePtr<ROL::PinTCommunicators>(comm, 1);
    Ptr<const ROL::PinTVectorCommunication<ScalarType>> vecComm =
        makePtr<ROL::PinTVectorCommunication_StdVector<ScalarType>>();

    // Load parameters from XML
    Ptr<ROL::ParameterList> params = ROL::getParametersFromXmlFile("input_ex01.xml");

    uint spatialDim = params->get("Spatial Discretization", 64);
    uint timeSteps  = params->get("Temporal Discretization", 128);
    ScalarType endTime = params->get("End Time", 1.0);
    ScalarType dt = endTime / static_cast<ScalarType>(timeSteps);

    // Initialize dynamic constraint
    Ptr<ROL::DynamicConstraint<ScalarType>> dynModel =
        makePtr<Constraint_ParabolicControl<ScalarType>>(*params);

    // Create initial vectors
    Ptr<ROL::StdVector<ScalarType>> initControl =
        makePtr<ROL::StdVector<ScalarType>>(makePtr<std::vector<ScalarType>>(spatialDim + 2, 0.0));
    Ptr<ROL::StdVector<ScalarType>> initState =
        makePtr<ROL::StdVector<ScalarType>>(makePtr<std::vector<ScalarType>>(spatialDim, 0.0));

    // Build PinT vectors
    Ptr<ROL::PinTVector<ScalarType>> stateVec =
        ROL::buildStatePinTVector<ScalarType>(pintComms, vecComm, timeSteps, initState);
    Ptr<ROL::PinTVector<ScalarType>> ctrlVec =
        ROL::buildControlPinTVector<ScalarType>(pintComms, vecComm, timeSteps, initControl);

    int localSteps = ctrlVec->numOwnedSteps();
    auto timestamps = makePtr<std::vector<ROL::TimeStamp<ScalarType>>>(localSteps);

    for (IndexType k = 0; k < timestamps->size(); ++k) {
        (*timestamps)[k].t.resize(2);
        (*timestamps)[k].t[0] = k * dt;
        (*timestamps)[k].t[1] = (k + 1) * dt;
    }

    ROL::PinTConstraint<ScalarType> pintConstraint(dynModel, initState, timestamps);
    pintConstraint.applyMultigrid(2, pintComms, vecComm);

    ScalarType tolerance = 1e-10;

    // Clone test vectors
    auto residual = stateVec->clone();
    auto jacobianAction_u = residual->clone();
    auto direction_u = stateVec->clone();
    auto weight_u = stateVec->clone();
    auto direction_z = ctrlVec->clone();

    // Randomize all test vectors
    ROL::RandomizeVector<ScalarType>(*stateVec);
    ROL::RandomizeVector<ScalarType>(*ctrlVec);
    ROL::RandomizeVector<ScalarType>(*direction_u);
    ROL::RandomizeVector<ScalarType>(*weight_u);
    ROL::RandomizeVector<ScalarType>(*direction_z);

    pintConstraint.setGlobalScale(1.0);

    // --- Validation Tests ---

    // Test solve correctness
    {
        if (myRank == 0) *log << "Testing constraint solve...\n";
        double residualNorm = pintConstraint.checkSolve(*stateVec, *ctrlVec, *residual, true, *log);
        VERIFY_CONDITION(residualNorm < tolerance);
    }

    // Test Jacobian w.r.t. state
    {
        if (myRank == 0) *log << "Testing Jacobian w.r.t. state...\n";
        auto errors = pintConstraint.checkApplyJacobian_1(*stateVec, *ctrlVec, *direction_u, *jacobianAction_u, true, *log);
        VERIFY_CONDITION(errors[6][3] / errors[6][1] < 1e-6);
    }

    // Test Jacobian w.r.t. control
    {
        if (myRank == 0) *log << "Testing Jacobian w.r.t. control...\n";
        auto errors = pintConstraint.checkApplyJacobian_2(*stateVec, *ctrlVec, *direction_z, *jacobianAction_u, true, *log);
        VERIFY_CONDITION(errors[6][3] / errors[6][1] < 1e-6);
    }

    // Test adjoint consistency for state Jacobian
    {
        if (myRank == 0) *log << "Testing adjoint consistency (state)...\n";
        ScalarType error = pintConstraint.checkAdjointConsistencyJacobian_1(*weight_u, *direction_u, *stateVec, *ctrlVec, true, *log);
        VERIFY_CONDITION(error < 1e-8);
    }

    // Test adjoint consistency for control Jacobian
    {
        if (myRank == 0) *log << "Testing adjoint consistency (control)...\n";
        ScalarType error = pintConstraint.checkAdjointConsistencyJacobian_2(*weight_u, *direction_z, *stateVec, *ctrlVec, true, *log);
        VERIFY_CONDITION(error < 1e-8);
    }

    // Test inverse Jacobian (state)
    {
        ScalarType invError = pintConstraint.checkInverseJacobian_1(*jacobianAction_u, *direction_u, *stateVec, *ctrlVec, true, *log);
        VERIFY_CONDITION(invError < tolerance);
    }

    // Test inverse adjoint Jacobian (state)
    {
        ScalarType adjInvError = pintConstraint.checkInverseAdjointJacobian_1(*jacobianAction_u, *direction_u, *stateVec, *ctrlVec, true, *log);
        VERIFY_CONDITION(adjInvError < tolerance);
    }

    // Local operator validation (forward/backward time stepping approximations)
    {
        using ROL::PinTVector;
        auto trialVec = stateVec->clone();
        auto forwardResult = stateVec->clone();
        auto localForwardResult = stateVec->clone();
        auto adjointResult = stateVec->clone();
        auto localAdjointResult = stateVec->clone();

        PinTVector<ScalarType>& pintTrial = dynamic_cast<PinTVector<ScalarType>&>(*trialVec);
        PinTVector<ScalarType>& pintLocalFwd = dynamic_cast<PinTVector<ScalarType>&>(*localForwardResult);
        PinTVector<ScalarType>& pintLocalAdj = dynamic_cast<PinTVector<ScalarType>&>(*localAdjointResult);
        PinTVector<ScalarType>& pintAdjRes = dynamic_cast<PinTVector<ScalarType>&>(*adjointResult);

        ROL::RandomizeVector<ScalarType>(*trialVec);

        ScalarType innerTol = 1e-12;

        // Compute Jacobian actions
        pintConstraint.applyJacobian_1(*localForwardResult, *trialVec, *stateVec, *ctrlVec, innerTol);
        pintConstraint.applyAdjointJacobian_1(*localAdjointResult, *trialVec, *stateVec, *ctrlVec, innerTol);

        // Adjust RHS for subdomain solvers
        int numOwned = pintLocalFwd.numOwnedSteps();
        pintTrial.boundaryExchangeRightToLeft();

        if (myRank + 1 < totalRanks) {
            pintLocalFwd.getVectorPtr(2 * (numOwned - 1) + 1)->axpy(1.0, *pintTrial.getVectorPtr(2 * (numOwned - 1)));
            pintLocalAdj.getVectorPtr(2 * (numOwned - 1))->axpy(1.0, *pintTrial.getVectorPtr(2 * (numOwned - 1) + 1));
        }

        int level = 0;
        pintConstraint.invertTimeStepJacobian(dynamic_cast<PinTVector<ScalarType>&>(*forwardResult),
                                              dynamic_cast<const PinTVector<ScalarType>&>(*localForwardResult),
                                              dynamic_cast<const PinTVector<ScalarType>&>(*stateVec),
                                              dynamic_cast<const PinTVector<ScalarType>&>(*ctrlVec),
                                              innerTol,
                                              level);

        pintConstraint.applyJacobian_1_leveled_approx(*localForwardResult,
                                                      *forwardResult,
                                                      *stateVec,
                                                      *ctrlVec,
                                                      innerTol,
                                                      level);

        ScalarType trialNorm = trialVec->norm();
        ScalarType localFwdNorm = localForwardResult->norm();

        // Check forward step
        {
            forwardResult->axpy(-1.0, *trialVec);
            ScalarType diffNorm = forwardResult->norm();
            if (myRank == 0) {
                *log << "Forward step test: norm(trial) = " << trialNorm
                     << ", relative error = " << diffNorm / trialNorm << "\n";
            }
            VERIFY_CONDITION(diffNorm / trialNorm <= 1e-12);

            localForwardResult->axpy(-1.0, *localForwardResult);
            ScalarType localDiff = localForwardResult->norm();
            VERIFY_CONDITION(localDiff / localFwdNorm <= 1e-13);
        }

        // Adjoint step
        pintConstraint.invertAdjointTimeStepJacobian(dynamic_cast<PinTVector<ScalarType>&>(*adjointResult),
                                                     dynamic_cast<const PinTVector<ScalarType>&>(*localAdjointResult),
                                                     dynamic_cast<const PinTVector<ScalarType>&>(*stateVec),
                                                     dynamic_cast<const PinTVector<ScalarType>&>(*ctrlVec),
                                                     innerTol,
                                                     level);

        pintConstraint.applyAdjointJacobian_1_leveled_approx(*localForwardResult,
                                                             *adjointResult,
                                                             *stateVec,
                                                             *ctrlVec,
                                                             innerTol,
                                                             level);

        ScalarType adjNorm = localAdjointResult->norm();

        {
            adjointResult->axpy(-1.0, *trialVec);
            ScalarType adjDiff = adjointResult->norm();
            if (myRank == 0) {
                *log << "Adjoint step test: norm(trial) = " << trialNorm
                     << ", relative error = " << adjDiff / trialNorm << "\n";
            }
            VERIFY_CONDITION(adjDiff / trialNorm <= 1e-12);

            localForwardResult->axpy(-1.0, *localAdjointResult);
            ScalarType localAdjDiff = localForwardResult->norm();
            VERIFY_CONDITION(localAdjDiff / adjNorm <= 1e-13);
        }
    }
}

