#include "llvm/Passes/PassPlugin.h"
#include "llvm/Support/raw_ostream.h"
#include <cstdint>

using namespace llvm;

Expected<PassPlugin> PassPlugin::Load(const std::string &Path) {
  std::string ErrMsg;

  // Attempt to load the dynamic library from the given path
  auto LibHandle = sys::DynamicLibrary::getPermanentLibrary(Path.c_str(), &ErrMsg);
  if (!LibHandle.isValid()) {
    return make_error<StringError>(
        Twine("Failed to load plugin library '") + Path + "': " + ErrMsg,
        inconvertibleErrorCode());
  }

  PassPlugin PluginObj{Path, LibHandle};

  // Look up the required entry point symbol in the loaded library
  void *SymbolAddr = LibHandle.getAddressOfSymbol("llvmGetPassPluginInfo");
  if (!SymbolAddr) {
    return make_error<StringError>(
        Twine("Missing plugin entry point 'llvmGetPassPluginInfo' in '") + 
            Path + "'. This may be an outdated (legacy) plugin.",
        inconvertibleErrorCode());
  }

  // Cast and invoke the plugin's info callback
  using InfoFn = decltype(llvmGetPassPluginInfo)*;
  auto GetInfo = reinterpret_cast<InfoFn>(reinterpret_cast<intptr_t>(SymbolAddr));
  PluginObj.Info = GetInfo();

  // Validate API version compatibility
  if (PluginObj.Info.APIVersion != LLVM_PLUGIN_API_VERSION) {
    return make_error<StringError>(
        Twine("Incompatible API version for plugin '") + Path + 
            "'. Expected: " + Twine(LLVM_PLUGIN_API_VERSION) + 
            ", but got: " + Twine(PluginObj.Info.APIVersion) + ".",
        inconvertibleErrorCode());
  }

  // Ensure the registration callback is provided
  if (!PluginObj.Info.RegisterPassBuilderCallbacks) {
    return make_error<StringError>(
        Twine("Plugin '") + Path + "' provides no pass builder registration callback.",
        inconvertibleErrorCode());
  }

  return PluginObj;
}

