#include "ocs2_core/loopshaping/LoopshapingFilter.h"
#include <iostream>

namespace ocs2 {

Filter::Filter() {
    stateMatrix_.setZero(0, 0);
    inputMatrix_.setZero(0, 0);
    outputMatrix_.setZero(0, 0);
    feedthroughMatrix_.setZero(0, 0);
}

Filter::Filter(matrix_t A, matrix_t B, matrix_t C, matrix_t D)
    : stateMatrix_(std::move(A)),
      inputMatrix_(std::move(B)),
      outputMatrix_(std::move(C)),
      feedthroughMatrix_(std::move(D)),
      diagA_(stateMatrix_.diagonal()),
      diagB_(inputMatrix_.diagonal()),
      diagC_(outputMatrix_.diagonal()),
      diagD_(feedthroughMatrix_.diagonal()),
      numStates_(stateMatrix_.rows()),
      numInputs_(inputMatrix_.cols()),
      numOutputs_(outputMatrix_.rows()) {

    validateDimensions();

    // Precompute scaling terms using outer products of diagonals
    diagCC_ = diagC_ * matrix_t::Ones(diagC_.size(), 1) * diagC_.transpose();
    diagDC_ = diagD_ * matrix_t::Ones(diagD_.size(), 1) * diagC_.transpose();
    diagDD_ = diagD_ * matrix_t::Ones(diagD_.size(), 1) * diagD_.transpose();

    // Factorizations for solving linear systems
    if (!stateMatrix_.isEmpty()) {
        stateFactor_.compute(stateMatrix_);
    }
    feedthroughFactor_.compute(feedthroughMatrix_);

    // Full system factorization
    matrix_t fullSystem(numStates_ + numInputs_, numStates_ + numInputs_);
    fullSystem << stateMatrix_, inputMatrix_, outputMatrix_, feedthroughMatrix_;
    fullFactor_.compute(fullSystem);
}

void Filter::print() const {
    std::cerr << "Number of states: " << numStates_ << '\n';
    std::cerr << "Number of inputs: " << numInputs_ << '\n';
    std::cerr << "Number of outputs: " << numOutputs_ << '\n';

    auto displayMatrix = [](const std::string& label, const matrix_t& mat) {
        if (mat.isDiagonal()) {
            std::cerr << label << " (diagonal): \n" << mat.diagonal().transpose() << "\n";
        } else {
            std::cerr << label << ": \n" << mat << "\n";
        }
    };

    displayMatrix("A", stateMatrix_);
    displayMatrix("B", inputMatrix_);
    displayMatrix("C", outputMatrix_);
    displayMatrix("D", feedthroughMatrix_);
}

void Filter::findEquilibriumForOutput(const vector_t& y, vector_t& x, vector_t& u) const {
    // Solve [0; y] = [A B; C D] * [x; u]
    vector_t rhs(numStates_ + numOutputs_);
    rhs << vector_t::Zero(numStates_), y;
    vector_t solution = fullFactor_.solve(rhs);
    x = solution.head(numStates_);
    u = solution.tail(numInputs_);
}

void Filter::findEquilibriumForOutputGivenState(const vector_t& y, const vector_t& x, vector_t& u) const {
    // Solve y = C*x + D*u  =>  D*u = y - C*x
    vector_t residual = y;
    residual.noalias() -= outputMatrix_ * x;
    u = feedthroughFactor_.solve(residual);
}

void Filter::findEquilibriumForInput(const vector_t& u, vector_t& x, vector_t& y) const {
    // Given u, compute y = D*u + C*x, where A*x + B*u = 0 => x = -A^{-1}B*u
    y.noalias() = feedthroughMatrix_ * u;
    if (numStates_ > 0) {
        vector_t Bu = inputMatrix_ * u;
        x = -stateFactor_.solve(Bu);
        y.noalias() += outputMatrix_ * x;
    }
}

void Filter::validateDimensions() const {
    bool consistent = true;

    // State dimension checks
    consistent &= (numStates_ == stateMatrix_.rows());
    consistent &= (numStates_ == inputMatrix_.rows());
    consistent &= (numStates_ == outputMatrix_.cols());

    // Input dimension checks
    consistent &= (numInputs_ == inputMatrix_.cols());
    consistent &= (numInputs_ == feedthroughMatrix_.cols());

    // Output dimension checks
    consistent &= (numOutputs_ == outputMatrix_.rows());
    consistent &= (numOutputs_ == feedthroughMatrix_.rows());

    if (!consistent) {
        print();
        throw std::runtime_error("Loopshaping: Filter: Matrix dimensions are inconsistent.");
    }
}

