#include "rows_to_matrix.h"
#include <cassert>
#include <cstdio>
#include "max_size.h"
#include "min_size.h"

template <class Row, class Mat>
IGL_INLINE bool igl::rows_to_matrix(const std::vector<Row> & V, Mat & M)
{
  // Determine number of rows (vectors in the list)
  const int row_count = static_cast<int>(V.size());

  if (row_count == 0)
  {
    fprintf(stderr, "Error: rows_to_matrix() input vector is empty\n");
    return false;
  }

  // Check consistency of sizes across all rows
  const int expected_cols = igl::min_size(V);
  if (expected_cols != igl::max_size(V))
  {
    fprintf(stderr, "Error: rows_to_matrix() "
      "all rows must have identical size\n");
    return false;
  }

  assert(expected_cols != -1);

  // Prepare output matrix dimensions
  M.resize(row_count, expected_cols);

  // Fill the matrix row by row
  for (int idx = 0; idx < row_count; ++idx)
  {
    M.row(idx) = V[idx];
  }

  return true;
}
