#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    if (!(cin >> N)) return 0;

    vector<int> parent(N + 1, 0);
    for (int i = 2; i <= N; ++i) {
        cin >> parent[i];
    }

    // Construct a path decomposition where:
    // - Bags 1..N contain single vertices {1}, {2}, ..., {N}
    // - Bags N+1..2N-1 correspond to edges (u, parent[u]) for u=2..N
    // - The bags are connected in a path: C1 - E2 - C2 - E3 - C3 - ... - EN - CN

    int totalBags = 2 * N - 1;
    cout << totalBags << "\n";

    // Output vertex bags (C_j = {j})
    for (int j = 1; j <= N; ++j) {
        cout << 1 << " " << j << "\n";
    }

    // Output edge bags (E_u = {u, parent[u]})
    for (int u = 2; u <= N; ++u) {
        cout << 2 << " " << u << " " << parent[u] << "\n";
    }

    // Build the path of bags: C1 - E2 - C2 - E3 - C3 - ... - EN - CN
    vector<pair<int, int>> bagConnections;

    if (N >= 2) {
        // Connect C1 (bag 1) to E2 (bag N+1)
        bagConnections.emplace_back(1, N + 1);

        // For each u from 2 to N-1: connect E_u to C_u, then C_u to E_{u+1}
        for (int u = 2; u < N; ++u) {
            int edgeBag = N + (u - 1);   // E_u
            int vertexBag = u;           // C_u
            bagConnections.emplace_back(edgeBag, vertexBag);
            bagConnections.emplace_back(vertexBag, edgeBag + 1); // E_{u+1} = E_u + 1
        }

        // Connect last edge bag E_N to C_N
        bagConnections.emplace_back(N + (N - 1), N);
    }
    // For N == 1, no connections needed (only one bag)

    // Output all connections
    for (const auto& conn : bagConnections) {
        cout << conn.first << " " << conn.second << "\n";
    }

    return 0;
}

