// Unique message identifier for button interaction
static const uint32 MSG_BUTTON_PRESS = 'btnp';

class CounterWindow : public BWindow
{
public:
	CounterWindow(BRect frame)
		:
		BWindow(frame, "Counter Demo", B_TITLED_WINDOW, B_QUIT_ON_WINDOW_CLOSE),
		fPressCount(0)
	{
		// Create main container view
		BRect area = Bounds();
		BView* container = new BView(area, "container", B_FOLLOW_ALL, B_WILL_DRAW);
		container->SetViewColor(240, 240, 240);
		AddChild(container);

		// Interactive button positioned at top-left
		BRect btnFrame(15, 15, 115, 45);
		BButton* actionBtn = new BButton(btnFrame, "trigger", "Press Here", 
		                                new BMessage(MSG_BUTTON_PRESS));
		container->AddChild(actionBtn);

		// Status display field below the button
		BRect textRect(15, 55, 275, 75);
		fDisplay = new BStringView(textRect, "status", "Ready to count");
		fDisplay->SetFont(be_plain_font);
		container->AddChild(fDisplay);
	}

	virtual ~CounterWindow()
	{
	}

	virtual bool QuitRequested()
	{
		be_app->PostMessage(B_QUIT_REQUESTED);
		return true;
	}

	void MessageReceived(BMessage* msg) override
	{
		switch (msg->what) {
			case MSG_BUTTON_PRESS:
				fPressCount++;
				{
					BString displayText;
					displayText.SetToFormat("Pressed %d time%s", 
					                        fPressCount, 
					                        fPressCount == 1 ? "" : "s");
					fDisplay->SetText(displayText.String());
				}
				break;
			default:
				BWindow::MessageReceived(msg);
		}
	}
private:
	BStringView* fDisplay;
	int32 fPressCount;
};

class CounterApplication : public BApplication
{
public:
	CounterApplication()
		:
		BApplication("application/x-vnd.example-counterapp")
	{
	}

	virtual void ReadyToRun()
	{
		BRect windowRect(80, 80, 300, 180);
		CounterWindow* win = new CounterWindow(windowRect);
		win->Show();
	}
};

// Entry point of the application
int main()
{
	CounterApplication app;
	app.Run();
	return 0;
}

#include "jemalloc/internal/jemalloc_preamble.h"
#include "jemalloc/internal/jemalloc_internal_includes.h"
#include "jemalloc/internal/prof_stats.h"

// Configuration flag for profiling statistics collection
bool opt_prof_stats = false;

// Mutex for protecting statistics data
malloc_mutex_t prof_stats_mtx;

// Arrays to track current and cumulative statistics per size class
static prof_stats_t prof_stats_live[PROF_SC_NSIZES];
static prof_stats_t prof_stats_accum[PROF_SC_NSIZES];

// Helper function to acquire statistics lock
static inline void
acquire_prof_stats_lock(tsd_t *tsd) {
    if (opt_prof && opt_prof_stats) {
        malloc_mutex_lock(tsd_tsdn(tsd), &prof_stats_mtx);
    }
}

// Helper function to release statistics lock
static inline void
release_prof_stats_lock(tsd_t *tsd) {
    malloc_mutex_unlock(tsd_tsdn(tsd), &prof_stats_mtx);
}

// Update statistics when allocation occurs
void
prof_stats_inc(tsd_t *tsd, szind_t index, size_t requested_size) {
    cassert(config_prof);

    // Lock before modifying shared data
    acquire_prof_stats_lock(tsd);

    // Update both live and accumulated counters
    prof_stats_live[index].req_sum += requested_size;
    prof_stats_live[index].count++;

    prof_stats_accum[index].req_sum += requested_size;
    prof_stats_accum[index].count++;

    // Release lock after modifications complete
    release_prof_stats_lock(tsd);
}

// Update statistics when deallocation occurs
void
prof_stats_dec(tsd_t *tsd, szind_t index, size_t requested_size) {
    cassert(config_prof);

    // Lock before modifying shared data
    acquire_prof_stats_lock(tsd);

    // Decrement live counters only (accumulated is permanent)
    prof_stats_live[index].req_sum -= requested_size;
    prof_stats_live[index].count--;

    // Release lock after modifications complete
    release_prof_stats_lock(tsd);
}

// Retrieve current (live) statistics for a size class
void
prof_stats_get_live(tsd_t *tsd, szind_t index, prof_stats_t *out_stats) {
    cassert(config_prof);

    // Lock during read operation
    acquire_prof_stats_lock(tsd);

    // Copy current statistics to output parameter
    memcpy(out_stats, &prof_stats_live[index], sizeof(prof_stats_t));

    // Release lock after reading completes
    release_prof_stats_lock(tsd);
}

// Retrieve accumulated statistics for a size class
void
prof_stats_get_accum(tsd_t *tsd, szind_t index, prof_stats_t *out_stats) {
    cassert(config_prof);

    // Lock during read operation
    acquire_prof_stats_lock(tsd);

    // Copy accumulated statistics to output parameter
    memcpy(out_stats, &prof_stats_accum[index], sizeof(prof_stats_t));

    // Release lock after reading completes
    release_prof_stats_lock(tsd);
}

