// Helper to build intervals from ranges
inline std::vector<word_prop_interval> build_word_prop_intervals()
{
    std::vector<word_prop_interval> intervals;

    // Add ALetter intervals
    auto add_lette = [&](uint32_t start, uint32_t end) {
        intervals.emplace_back(start, end, word_property::ALetter);
    };

    add_lette(0x00f8, 0x01bb);
    add_lette(0x01c4, 0x0294);
    add_lette(0x03f7, 0x0482);
    add_lette(0x048a, 0x0530);
    add_lette(0x1100, 0x1249);
    add_lette(0x1401, 0x166d);
    add_lette(0x1e00, 0x1f16);
    add_lette(0xa016, 0xa48d);
    add_lette(0xa500, 0xa60c);
    add_lette(0xac00, 0xd7a4);
    add_lette(0xfbd3, 0xfd3e);
    add_lette(0xfe76, 0xfefd);
    add_lette(0x10600, 0x10737);
    add_lette(0x12000, 0x1239a);
    add_lette(0x12480, 0x12544);
    add_lette(0x13000, 0x1342f);
    add_lette(0x14400, 0x14647);
    add_lette(0x16800, 0x16a39);
    add_lette(0x1d552, 0x1d6a6);
    add_lette(0x1e800, 0x1e8c5);

    // Add ExtPict intervals
