#include <iostream>
#include <vector>
#include <algorithm>
#include <list>
using namespace std;

// Global data: number of elements and input array
int n;
vector<int> arr;

// Helper: perform binary search on sorted 'vals' to find first position >= target
int find_insert_pos(const vector<int>& vals, int target) {
    int left = 0, right = vals.size();
    while (left < right) {
        int mid = (left + right) / 2;
        if (vals[mid] < target)
            left = mid + 1;
        else
            right = mid;
    }
    return left;
}

// Extract indices forming longest monotonic subsequence from remaining elements
// decreasing=true means we want decreasing (by negating values internally)
vector<int> extract_lis_indices(const vector<int>& remaining_indices, bool decreasing) {
    vector<int> min_tails;      // stores transformed tail values
    vector<int> tail_positions; // stores original indices corresponding to tails
    vector<int> prev_idx(remaining_indices.size(), -1); // predecessor index in sequence

    for (size_t pos = 0; pos < remaining_indices.size(); ++pos) {
        int orig_idx = remaining_indices[pos];
        int val = arr[orig_idx];
        if (decreasing) val = -val;

        int k = find_insert_pos(min_tails, val);

        if (k == (int)min_tails.size()) {
            min_tails.push_back(val);
            tail_positions.push_back(orig_idx);
        } else {
            min_tails[k] = val;
            tail_positions[k] = orig_idx;
        }

        if (k > 0) {
            prev_idx[pos] = tail_positions[k - 1];
        }
    }

    // Reconstruct path by tracing backwards from last tail
    vector<int> result;
    if (tail_positions.empty()) return result;

    int curr = tail_positions.back();
    // Build list in reverse order then reverse it
    vector<int> temp;
    for (int i = (int)remaining_indices.size() - 1; i >= 0; --i) {
        if (remaining_indices[i] == curr) {
            temp.push_back(curr);
            // Move to predecessor — need to find its position in remaining_indices
            int pred = -1;
            for (int j = 0; j < (int)remaining_indices.size(); ++j) {
                if (remaining_indices[j] == curr && prev_idx[j] != -1) {
                    pred = prev_idx[j];
                    break;
                }
            }
            curr = pred;
            if (curr == -1) break;
        }
    }

    // Reverse to get correct order
    reverse(temp.begin(), temp.end());
    return temp;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> n)) return 0;
    arr.resize(n);
    for (int i = 0; i < n; ++i) cin >> arr[i];

    // We'll try all distinct permutations of {Inc, Inc, Dec, Dec}
    vector<int> order = {0, 0, 1, 1}; // 0=inc, 1=dec
    sort(order.begin(), order.end());

    long long max_covered = -1;
    vector<int> best_assignment(n, 3); // default assignment: d (3)

    do {
        // Track which indices are still available (as list for easy iteration)
        list<int> available;
        for (int i = 0; i < n; ++i) available.push_back(i);

        vector<int> owner(n, -1);
        long long total_len = 0;

        int inc_used = 0, dec_used = 0;

        for (int type : order) {
            int assign_to;
            if (type == 0) {
                assign_to = (inc_used++ == 0) ? 0 : 2; // first inc → a (0), second → c (2)
            } else {
                assign_to = (dec_used++ == 0) ? 1 : 3; // first dec → b (1), second → d (3)
            }

            // Convert list to vector for processing
            vector<int> remaining(available.begin(), available.end());
            vector<int> seq = extract_lis_indices(remaining, type == 1);

            total_len += seq.size();

            for (int idx : seq) {
                owner[idx] = assign_to;
                available.remove(idx);
            }
        }

        if (total_len > max_covered) {
            max_covered = total_len;
            for (int i = 0; i < n; ++i) {
                best_assignment[i] = (owner[i] == -1) ? 3 : owner[i];
            }
        }

    } while (next_permutation(order.begin(), order.end()));

    // Partition elements into four groups based on best_assignment
    vector<int> group_a, group_b, group_c, group_d;
    group_a.reserve(n); group_b.reserve(n); group_c.reserve(n); group_d.reserve(n);

    for (int i = 0; i < n; ++i) {
        switch (best_assignment[i]) {
            case 0: group_a.push_back(arr[i]); break;
            case 1: group_b.push_back(arr[i]); break;
            case 2: group_c.push_back(arr[i]); break;
            default: group_d.push_back(arr[i]);
        }
    }

    // Output sizes
    cout << group_a.size() << " " << group_b.size() << " "
         << group_c.size() << " " << group_d.size() << "\n";

    // Utility lambda to print vector with space separation
    auto print_group = [](const vector<int>& v) {
        for (size_t i = 0; i < v.size(); ++i) {
            if (i > 0) cout << " ";
            cout << v[i];
        }
        cout << "\n";
    };

    print_group(group_a);
    print_group(group_b);
    print_group(group_c);
    print_group(group_d);

    return 0;
}

