#include <iostream>

// Insertion sort implementation - rearranges array in ascending order
int main() {
    int arr[] = {5, 2, 8, 1, 9}; // sample array
    int n = sizeof(arr) / sizeof(arr[0]);

    for (int pos = 1; pos < n; ++pos) {
        int currentVal = arr[pos];
        int j = pos - 1;

        // Move elements of arr[0..pos-1], that are greater than currentVal,
        // to one position ahead of their current position
        while (j >= 0 && arr[j] > currentVal) {
            arr[j + 1] = arr[j];
            --j;
        }

        arr[j + 1] = currentVal;
    }

    // Print sorted array (optional)
    for (int i = 0; i < n; ++i) {
        std::cout << arr[i] << " ";
    }
    std::cout << std::endl;

    return 0;
}

#include <bits/stdc++.h>
using namespace std;
using llong = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int testCases;
    if (!(cin >> testCases)) return 0;

    while (testCases--) {
        int n, m;
        llong penalty;
        cin >> n >> m >> penalty;

        vector<llong> prefixA(n + 1, 0);
        for (int idx = 1; idx <= n; ++idx) {
            llong val;
            cin >> val;
            prefixA[idx] = prefixA[idx - 1] + val;
        }

        vector<llong> prefixB(m + 1, 0);
        for (int idx = 1; idx <= m; ++idx) {
            llong val;
            cin >> val;
            prefixB[idx] = prefixB[idx - 1] + val;
        }

        // Helper: find largest k such that prefixB[k] <= x
        auto countSegments = [&](llong x) -> int {
            if (x < 0) return 0;
            int lo = 0, hi = m;
            while (lo < hi) {
                int mid = (lo + hi + 1) / 2;
                if (prefixB[mid] <= x)
                    lo = mid;
                else
                    hi = mid - 1;
            }
            return lo;
        };

        // DP arrays: dpPrev holds previous layer, dpCurr computes current
        vector<llong> dpPrev(n + 1, LLONG_MIN / 4);
        vector<llong> dpCurr(n + 1, LLONG_MIN / 4);

        dpPrev[0] = 0; // base case: zero days processed

        // Divide & Conquer DP transition
        function<void(int, int, int, int)> solveRange = [&](int left, int right, int optL, int optR) {
            if (left > right) return;

            int center = (left + right) >> 1;
            llong bestVal = LLONG_MIN / 4;
            int bestSplit = optL;

            int upperBoundJ = min(center - 1, optR);
            for (int prev = optL; prev <= upperBoundJ; ++prev) {
                llong diff = prefixA[center] - prefixA[prev];
                llong candidate = dpPrev[prev] + countSegments(diff) - penalty;
                if (candidate > bestVal) {
                    bestVal = candidate;
                    bestSplit = prev;
                }
            }

            dpCurr[center] = bestVal;

            // Recurse left and right with updated bounds
            solveRange(left, center - 1, optL, bestSplit);
            solveRange(center + 1, right, bestSplit, optR);
        };

        // Compute dp for positions 1..n
        solveRange(1, n, 0, n - 1);

        cout << dpCurr[n] << '\n';
    }

    return 0;
}

