/*-------------------------------------------------------------------------
 * Function:    test_array_compound_array
 *
 * Purpose:     Tests 1-D array of compound datatypes (with array fields)
 *
 * Return:      None.
 *
 * Programmer:  Binh-Minh Ribler (using C version)
 *		January, 2016
 *
 * Modifications:
 *
 *-------------------------------------------------------------------------
 */
static void test_array_compound_array()
{
    SUBTEST("ArrayType::getArrayNDims & ArrayType::getArrayDims");

    typedef struct {        // Typedef for compound datatype */
        int i;
        float f[ARRAY1_DIM1];
    } s1_t;

    s1_t writeBuffer[SPACE1_DIM1][ARRAY1_DIM1];   // Data to be written
    s1_t readBuffer[SPACE1_DIM1][ARRAY1_DIM1];    // Data to be read back
    hsize_t dims_space[] = {SPACE1_DIM1};
    hsize_t dims_array[] = {ARRAY1_DIM1};

    int memberCount;       // Number of members in compound type
    int loopIdx;           // Loop counter
    hsize_t row, col, elem; // Indexing variables

    H5T_class_t dtypeClass; // Datatype class for field

    // Initialize write buffer
    for (row = 0; row < SPACE1_DIM1; ++row) {
        for (col = 0; col < ARRAY1_DIM1; ++col) {
            writeBuffer[row][col].i = static_cast<int>(row * 10 + col);
            for (elem = 0; elem < ARRAY1_DIM1; ++elem) {
                float value = static_cast<float>(row * 10.0 + col * 2.5 + elem);
                writeBuffer[row][col].f[elem] = value;
            }
        }
    }

    try {
        // Create File
        H5File file1(FILENAME, H5F_ACC_TRUNC);

        // Create dataspace for datasets
        DataSpace space(SPACE1_RANK, dims_space, nullptr);

        // Create compound datatype containing integer and float array
        CompType compoundType(sizeof(s1_t));
        compoundType.insertMember("i", HOFFSET(s1_t, i), PredType::NATIVE_INT);

        ArrayType floatArray(PredType::NATIVE_FLOAT, ARRAY1_RANK, dims_array);
        compoundType.insertMember("f", HOFFSET(s1_t, f), floatArray);
        floatArray.close();

        ArrayType arrCompound(compoundType, ARRAY1_RANK, dims_array);
        compoundType.close();

        // Create and write dataset
        DataSet dataset = file1.createDataSet("Dataset1", arrCompound, space);
        dataset.write(writeBuffer, arrCompound);

        dataset.close();
        arrCompound.close();
        space.close();
        file1.close();

        // Re-open file and dataset
        file1.openFile(FILENAME, H5F_ACC_RDONLY);
        dataset = file1.openDataSet("Dataset1");

        // Verify dataset is an array type
        DataType dsType = dataset.getDataType();
        dtypeClass = dsType.getClass();
        verify_val(dtypeClass == H5T_ARRAY, true, "dsType.getClass()", __LINE__, __FILE__);
        dsType.close();

        // Retrieve and validate array properties
        ArrayType checkedArrType = dataset.getArrayType();
        int rank = checkedArrType.getArrayNDims();
        verify_val(rank, ARRAY1_RANK, "checkedArrType.getArrayNDims()", __LINE__, __FILE__);

        hsize_t retrievedDims[H5S_MAX_RANK];
        checkedArrType.getArrayDims(retrievedDims);

        for (loopIdx = 0; loopIdx < rank; ++loopIdx) {
            if (retrievedDims[loopIdx] != dims_array[loopIdx]) {
                TestErrPrintf("Array dimension mismatch at index %d: expected %zd, got %zd\n",
                              loopIdx, dims_array[loopIdx], retrievedDims[loopIdx]);
            }
        }

        // Test copy constructor via getId()
        ArrayType copiedArr(checkedArrType.getId());
        int newRank = copiedArr.getArrayNDims();
        verify_val(newRank, ARRAY1_RANK, "copiedArr.getArrayNDims()", __LINE__, __FILE__);

        copiedArr.getArrayDims(retrievedDims);
        for (loopIdx = 0; loopIdx < newRank; ++loopIdx) {
            if (retrievedDims[loopIdx] != dims_array[loopIdx]) {
                TestErrPrintf("Copied array dimension mismatch at index %d: expected %zd, got %zd\n",
                              loopIdx, dims_array[loopIdx], retrievedDims[loopIdx]);
            }
        }

        // Check base compound type
        DataType baseType = checkedArrType.getSuper();
        dtypeClass = baseType.getClass();
        verify_val(dtypeClass == H5T_COMPOUND, true, "baseType.getClass()", __LINE__, __FILE__);

        CompType compCheck(baseType.getId());
        baseType.close();

        memberCount = compCheck.getNmembers();
        verify_val(memberCount, 2, "compCheck.getNmembers()", __LINE__, __FILE__);

        H5std_string fieldName = compCheck.getMemberName(1);
        if (HDstrcmp(fieldName.c_str(), "f") != 0) {
            TestErrPrintf("Field name mismatch: expected 'f', got '%s'\n", fieldName.c_str());
        }

        DataType fieldDataType = compCheck.getMemberDataType(1);
        dtypeClass = fieldDataType.getClass();
        verify_val(dtypeClass == H5T_ARRAY, true, "fieldDataType.getClass()", __LINE__, __FILE__);
        fieldDataType.close();

        ArrayType fieldArray = compCheck.getMemberArrayType(1);
        int fieldRank = fieldArray.getArrayNDims();
        verify_val(fieldRank, ARRAY1_RANK, "fieldArray.getArrayNDims()", __LINE__, __FILE__);

        HDmemset(retrievedDims, 0, sizeof(retrievedDims));
        fieldArray.getArrayDims(retrievedDims);

        for (loopIdx = 0; loopIdx < fieldRank; ++loopIdx) {
            if (retrievedDims[loopIdx] != dims_array[loopIdx]) {
                TestErrPrintf("Field array dimension mismatch at index %d: expected %zd, got %zd\n",
                              loopIdx, dims_array[loopIdx], retrievedDims[loopIdx]);
            }
        }

        fieldArray.close();
        compCheck.close();

        // Read data and compare
        dataset.read(readBuffer, checkedArrType);

        for (row = 0; row < SPACE1_DIM1; ++row) {
            for (col = 0; col < ARRAY1_DIM1; ++col) {
                if (writeBuffer[row][col].i != readBuffer[row][col].i) {
                    TestErrPrintf("Integer mismatch at [%zu][%zu]: wrote %d, read %d\n",
                                  row, col, writeBuffer[row][col].i, readBuffer[row][col].i);
                }
            }
        }

        // Cleanup
        checkedArrType.close();
        dataset.close();
        file1.close();
        PASSED();
    }
    catch (Exception& E) {
        issue_fail_msg("test_array_compound_array", __LINE__, __FILE__, E.getCDetailMsg());
    }
}

