/**************************************************************************/
/*!
    @brief  Execute a sequence of display initialization commands from flash
    @param  addr  Pointer to command list stored in program memory (PROGMEM)
*/
/**************************************************************************/
void Adafruit_ST77xx::displayInit(const uint8_t *addr) {
  uint8_t cmdCount = pgm_read_byte(addr++); // Number of commands
  while (cmdCount--) {                      // Process each command
    uint8_t command = pgm_read_byte(addr++);
    uint8_t argCount = pgm_read_byte(addr++);
    uint16_t delayMs = argCount & ST_CMD_DELAY;
    argCount &= ~ST_CMD_DELAY; // Remove delay flag bit

    sendCommand(command, addr, argCount);
    addr += argCount;

    if (delayMs) {
      delayMs = pgm_read_byte(addr++);
      if (delayMs == 255)
        delayMs = 500; // Special case: 255 → 500 ms
      delay(delayMs);
    }
  }
}

/**************************************************************************/
/*!
    @brief  Start up the ST77xx display controller via SPI
    @param  freq  Desired SPI clock rate (0 uses default)
*/
/**************************************************************************/
void Adafruit_ST77xx::begin(uint32_t freq) {
  if (!freq) {
    freq = DEFAULT_SPI_FREQ;
  }
  _freq = freq;
  invertOnCommand = ST77XX_INVON;
  invertOffCommand = ST77XX_INVOFF;
  initSPI(freq, spiMode);
}

/**************************************************************************/
/*!
    @brief  Common initialization routine for all ST77xx variants
    @param  cmdList  Initialization command table (NULL skips table)
*/
/**************************************************************************/
void Adafruit_ST77xx::commonInit(const uint8_t *cmdList) {
  begin();
  if (cmdList) {
    displayInit(cmdList);
  }
}

/**************************************************************************/
/*!
    @brief  Define rectangular address window for pixel transfers
    @param  x     Left column coordinate
    @param  y     Top row coordinate
    @param  w     Window width in pixels
    @param  h     Window height in pixels
*/
/**************************************************************************/
void Adafruit_ST77xx::setAddrWindow(uint16_t x, uint16_t y, uint16_t w,
                                    uint16_t h) {
  x += _xstart;
  y += _ystart;

  uint32_t colRange = ((uint32_t)x << 16) | (x + w - 1);
  uint32_t rowRange = ((uint32_t)y << 16) | (y + h - 1);

  writeCommand(ST77XX_CASET); // Column address set
  SPI_WRITE32(colRange);

  writeCommand(ST77XX_RASET); // Row address set
  SPI_WRITE32(rowRange);

  writeCommand(ST77XX_RAMWR); // RAM write
}

/**************************************************************************/
/*!
    @brief  Set display orientation and origin offset
    @param  m  Rotation index (0–3)
*/
/**************************************************************************/
void Adafruit_ST77xx::setRotation(uint8_t m) {
  uint8_t madctl = 0;
  rotation = m % 4; // Ensure valid range [0,3]

  switch (rotation) {
    case 0:
      madctl = ST77XX_MADCTL_MX | ST77XX_MADCTL_MY | ST77XX_MADCTL_RGB;
      _xstart = _colstart;
      _ystart = _rowstart;
      break;
    case 1:
      madctl = ST77XX_MADCTL_MY | ST77XX_MADCTL_MV | ST77XX_MADCTL_RGB;
      _ystart = _colstart;
      _xstart = _rowstart;
      break;
    case 2:
      madctl = ST77XX_MADCTL_RGB;
      _xstart = _colstart;
      _ystart = _rowstart;
      break;
    case 3:
      madctl = ST77XX_MADCTL_MX | ST77XX_MADCTL_MV | ST77XX_MADCTL_RGB;
      _ystart = _colstart;
      _xstart = _rowstart;
      break;
  }

  sendCommand(ST77XX_MADCTL, &madctl, 1);
}

/**************************************************************************/
/*!
    @brief  Adjust display column/row start offsets
    @param  col  Column offset value
    @param  row  Row offset value
*/
/**************************************************************************/
void Adafruit_ST77xx::setColRowStart(int8_t col, int8_t row) {
  _colstart = col;
  _rowstart = row;
}

/**************************************************************************/
/*!
    @brief  Turn display on or off
    @param  enable  true → ON, false → OFF
*/
/**************************************************************************/
void Adafruit_ST77xx::enableDisplay(boolean enable) {
  sendCommand(enable ? ST77XX_DISPON : ST77XX_DISPOFF);
}

/**************************************************************************/
/*!
    @brief  Enable/disable Tearing Effect output pin
    @param  enable  true → TE enabled, false → TE disabled
*/
/**************************************************************************/
void Adafruit_ST77xx::enableTearing(boolean enable) {
  sendCommand(enable ? ST77XX_TEON : ST77XX_TEOFF);
}

/**************************************************************************/
/*!
    @brief  Enter or exit sleep mode
    @param  enable  true → enter sleep, false → wake up
*/
/**************************************************************************/
void Adafruit_ST77xx::enableSleep(boolean enable) {
  sendCommand(enable ? ST77XX_SLPIN : ST77XX_SLPOUT);
}

