namespace {

// Renamed class: previously DAGDeltaAlgorithmImpl
class GraphReducerCore {
  friend class ActiveSetMinimizer;

public:
  using change_t = DAGDeltaAlgorithm::change_ty;
  using changeset_t = DAGDeltaAlgorithm::changeset_ty;
  using changesetlist_t = DAGDeltaAlgorithm::changesetlist_ty;
  using edge_t = DAGDeltaAlgorithm::edge_ty;

private:
  using node_vec_iter = std::vector<change_t>::iterator;
  using node_set_iter = std::set<change_t>::iterator;

  DAGDeltaAlgorithm &ParentDDA;
  std::vector<change_t> InitialNodes; // renamed from Roots

  mutable std::set<changeset_t> TestCache; // renamed FailedTestsCache

  // Dependency maps: predecessor/successor lists and closures
  std::map<change_t, std::vector<change_t>> PredList;
  std::map<change_t, std::vector<change_t>> SuccList;
  std::map<change_t, std::set<change_t>> PredClosureMap;
  std::map<change_t, std::set<change_t>> SuccClosureMap;

private:
  node_vec_iter pred_begin(change_t N) {
    assert(PredList.count(N) && "Invalid node in graph!");
    return PredList[N].begin();
  }

  node_vec_iter pred_end(change_t N) {
    assert(PredList.count(N) && "Invalid node in graph!");
    return PredList[N].end();
  }

  node_set_iter pred_closure_begin(change_t N) {
    assert(PredClosureMap.count(N) && "Invalid node in closure map!");
    return PredClosureMap[N].begin();
  }

  node_set_iter pred_closure_end(change_t N) {
    assert(PredClosureMap.count(N) && "Invalid node in closure map!");
    return PredClosureMap[N].end();
  }

  node_vec_iter succ_begin(change_t N) {
    assert(SuccList.count(N) && "Invalid node in graph!");
    return SuccList[N].begin();
  }

  node_vec_iter succ_end(change_t N) {
    assert(SuccList.count(N) && "Invalid node in graph!");
    return SuccList[N].end();
  }

  node_set_iter succ_closure_begin(change_t N) {
    assert(SuccClosureMap.count(N) && "Invalid node in closure map!");
    return SuccClosureMap[N].begin();
  }

  node_set_iter succ_closure_end(change_t N) {
    assert(SuccClosureMap.count(N) && "Invalid node in closure map!");
    return SuccClosureMap[N].end();
  }

  void NotifySearchState(const changeset_t &Active,
                         const changesetlist_t &Partitions,
                         const changeset_t &Mandatory) {
    ParentDDA.UpdatedSearchState(Active, Partitions, Mandatory);
  }

  bool RunSingleTest(const changeset_t &S) {
    LLVM_DEBUG({
      for (auto it = S.begin(), end = S.end(); it != end; ++it)
        for (auto it2 = succ_begin(*it), e2 = succ_end(*it); it2 != e2; ++it2)
          assert(S.count(*it2) && "Attempted invalid test set!");
    });
    return ParentDDA.ExecuteOneTest(S);
  }

public:
  GraphReducerCore(DAGDeltaAlgorithm &dda,
                   const changeset_t &nodes,
                   const std::vector<edge_t> &deps);

  changeset_t Minimize();

  bool EvaluateWithCaching(const changeset_t &active,
                           const changeset_t &mandatory);
};

// Helper class for minimizing active sets — renamed from DeltaActiveSetHelper
class ActiveSetMinimizer : public DeltaAlgorithm {
  GraphReducerCore &Reducer;
  const changeset_t &Mandatory;

protected:
  void OnSearchUpdate(const changeset_t &current,
                      const changesetlist_t &partitions) override {
    Reducer.NotifySearchState(current, partitions, Mandatory);
  }

  bool PerformTest(const changeset_t &candidate) override {
    return Reducer.EvaluateWithCaching(candidate, Mandatory);
  }

public:
  ActiveSetMinimizer(GraphReducerCore &core, const changeset_t &req)
      : DeltaAlgorithm(), Reducer(core), Mandatory(req) {}
};

} // anonymous namespace

GraphReducerCore::GraphReducerCore(
    DAGDeltaAlgorithm &dda, const changeset_t &nodes,
    const std::vector<edge_t> &deps)
    : ParentDDA(dda) {
  // Initialize node entries
  for (change_t node : nodes) {
    PredList.emplace(node, std::vector<change_t>());
    SuccList.emplace(node, std::vector<change_t>());
  }

  // Populate dependency edges
  for (const edge_t &dep : deps) {
    PredList[dep.second].push_back(dep.first);
    SuccList[dep.first].push_back(dep.second);
  }

  // Identify leaf nodes (no successors) as starting points
  for (change_t node : nodes)
    if (succ_begin(node) == succ_end(node))
      InitialNodes.push_back(node);

  // Compute successor closures via reverse topological traversal
  std::vector<change_t> worklist(InitialNodes.begin(), InitialNodes.end());
  while (!worklist.empty()) {
    change_t current = worklist.back();
    worklist.pop_back();
    std::set<change_t> &currentSuccs = SuccClosureMap[current];

    for (node_vec_iter it = pred_begin(current), ie = pred_end(current);
         it != ie; ++it) {
      SuccClosureMap[*it].insert(current);
      SuccClosureMap[*it].insert(currentSuccs.begin(), currentSuccs.end());
      worklist.push_back(*it);
    }
  }

  // Build predecessor closures by transposing successor closures
  for (change_t node : nodes)
    PredClosureMap.emplace(node, std::set<change_t>());

  for (change_t node : nodes)
    for (node_set_iter it = succ_closure_begin(node),
                       end = succ_closure_end(node);
         it != end; ++it)
      PredClosureMap[*it].insert(node);

  // Debug output
  LLVM_DEBUG({
    llvm::errs() << "-- GraphReducerCore --\n";
    llvm::errs() << "Nodes: [";
    for (auto it = nodes.begin(), end = nodes.end(); it != end; ++it) {
      if (it != nodes.begin()) llvm::errs() << ", ";
      llvm::errs() << *it;
      if (succ_begin(*it) != succ_end(*it)) {
        llvm::errs() << "(";
        for (auto it2 = succ_begin(*it), e2 = succ_end(*it); it2 != e2; ++it2) {
          if (it2 != succ_begin(*it)) llvm::errs() << ", ";
          llvm::errs() << "->" << *it2;
        }
        llvm::errs() << ")";
      }
    }
    llvm::errs() << "]\n";

    llvm::errs() << "Leaves: [";
    for (auto it = InitialNodes.begin(), end = InitialNodes.end(); it != end;
         ++it) {
      if (it != InitialNodes.begin()) llvm::errs() << ", ";
      llvm::errs() << *it;
    }
    llvm::errs() << "]\n";

    llvm::errs() << "Predecessor Closures:\n";
    for (change_t node : nodes) {
      llvm::errs() << format("  %-4d: [", node);
      for (auto it = pred_closure_begin(node), end = pred_closure_end(node);
           it != end; ++it) {
        if (it != pred_closure_begin(node)) llvm::errs() << ", ";
        llvm::errs() << *it;
      }
      llvm::errs() << "]\n";
    }

    llvm::errs() << "Successor Closures:\n";
    for (change_t node : nodes) {
      llvm::errs() << format("  %-4d: [", node);
      for (auto it = succ_closure_begin(node), end = succ_closure_end(node);
           it != end; ++it) {
        if (it != succ_closure_begin(node)) llvm::errs() << ", ";
        llvm::errs() << *it;
      }
      llvm::errs() << "]\n";
    }
    llvm::errs() << "\n\n";
  });
}

bool GraphReducerCore::EvaluateWithCaching(const changeset_t &active,
                                           const changeset_t &mandatory) {
  changeset_t extended(mandatory);
  extended.insert(active.begin(), active.end());

  for (change_t node : active)
    extended.insert(pred_closure_begin(node), pred_closure_end(node));

  if (TestCache.count(extended))
    return false;

  bool success = RunSingleTest(extended);
  if (!success)
    TestCache.insert(extended);

  return success;
}

GraphReducerCore::changeset_t GraphReducerCore::Minimize() {
  changeset_t activeSet(InitialNodes.begin(), InitialNodes.end());
  changeset_t requiredSet;

  while (!activeSet.empty()) {
    LLVM_DEBUG({
      llvm::errs() << "Graph_DD - " << activeSet.size()
                   << " active nodes, " << requiredSet.size()
                   << " required nodes\n";
    });

    ActiveSetMinimizer helper(*this, requiredSet);
    changeset_t minimized = helper.Run(activeSet);

    requiredSet.insert(minimized.begin(), minimized.end());

    activeSet.clear();
    for (change_t node : minimized) {
      for (node_vec_iter it = pred_begin(node), end = pred_end(node);
           it != end; ++it) {
        activeSet.insert(*it);
      }
    }
  }

  return requiredSet;
}

void DAGDeltaAlgorithm::anchor() {}

DAGDeltaAlgorithm::changeset_t
DAGDeltaAlgorithm::Run(const changeset_t &nodes,
                       const std::vector<edge_t> &deps) {
  return GraphReducerCore(*this, nodes, deps).Minimize();
}

