// Singleton instance initialization
Frustum* Frustum::frustum = new Frustum();

Frustum::Frustum() {
    _projectionMatrix = MemoryTracker::createFloatBuffer(16);
    _modelviewMatrix  = MemoryTracker::createFloatBuffer(16);
    _combinedClip     = MemoryTracker::createFloatBuffer(16);
}

Frustum::~Frustum() {
    delete _projectionMatrix;
    delete _modelviewMatrix;
    delete _combinedClip;
}

FrustumData* Frustum::getActiveFrustum() {
    updateFrustumGeometry();
    return frustum;
}

// Helper: Normalize a plane vector (A, B, C, D) to unit length
void Frustum::rescalePlane(float planes[6][4], int index) {
    float len = std::sqrt(
        planes[index][0] * planes[index][0] +
        planes[index][1] * planes[index][1] +
        planes[index][2] * planes[index][2]
    );
    if (len != 0.0f) {
        planes[index][0] /= len;
        planes[index][1] /= len;
        planes[index][2] /= len;
        planes[index][3] /= len;
    }
}

void Frustum::updateFrustumGeometry() {
    // Clear buffers before populating
    _projectionMatrix->clear();
    _modelviewMatrix->clear();
    _combinedClip->clear();

    // Retrieve current OpenGL matrices
    glGetFloat(GL_PROJECTION_MATRIX, _projectionMatrix);
    glGetFloat(GL_MODELVIEW_MATRIX,  _modelviewMatrix);

    // Extract raw matrix data
    _projectionMatrix->flip()->limit(16);
    _projectionMatrix->get(&_projData[0]);

    _modelviewMatrix->flip()->limit(16);
    _modelviewMatrix->get(&_modlData[0]);

    // Compute combined clip matrix: clip = modelview × projection
    // Row-major multiplication: each row i of clip is linear combination of proj rows weighted by modl[i][j]
    for (int r = 0; r < 4; ++r) {
        for (int c = 0; c < 4; ++c) {
            int idx = r * 4 + c;
            float acc = 0.0f;
            for (int k = 0; k < 4; ++k) {
                acc += _modlData[r * 4 + k] * _projData[k * 4 + c];
            }
            _clipData[idx] = acc;
        }
    }

    // Extract frustum planes from clip matrix
    // Right plane: column 3 minus column 0
    _frustum[RIGHT][0] = _clipData[3] - _clipData[0];
    _frustum[RIGHT][1] = _clipData[7] - _clipData[4];
    _frustum[RIGHT][2] = _clipData[11] - _clipData[8];
    _frustum[RIGHT][3] = _clipData[15] - _clipData[12];
    rescalePlane(_frustum, RIGHT);

    // Left plane: column 3 plus column 0
    _frustum[LEFT][0] = _clipData[3] + _clipData[0];
    _frustum[LEFT][1] = _clipData[7] + _clipData[4];
    _frustum[LEFT][2] = _clipData[11] + _clipData[8];
    _frustum[LEFT][3] = _clipData[15] + _clipData[12];
    rescalePlane(_frustum, LEFT);

    // Bottom plane: column 3 plus column 1
    _frustum[BOTTOM][0] = _clipData[3] + _clipData[1];
    _frustum[BOTTOM][1] = _clipData[7] + _clipData[5];
    _frustum[BOTTOM][2] = _clipData[11] + _clipData[9];
    _frustum[BOTTOM][3] = _clipData[15] + _clipData[13];
    rescalePlane(_frustum, BOTTOM);

    // Top plane: column 3 minus column 1
    _frustum[TOP][0] = _clipData[3] - _clipData[1];
    _frustum[TOP][1] = _clipData[7] - _clipData[5];
    _frustum[TOP][2] = _clipData[11] - _clipData[9];
    _frustum[TOP][3] = _clipData[15] - _clipData[13];
    rescalePlane(_frustum, TOP);

    // Back plane: column 3 minus column 2
    _frustum[BACK][0] = _clipData[3] - _clipData[2];
    _frustum[BACK][1] = _clipData[7] - _clipData[6];
    _frustum[BACK][2] = _clipData[11] - _clipData[10];
    _frustum[BACK][3] = _clipData[15] - _clipData[14];
    rescalePlane(_frustum, BACK);

    // Front plane: column 3 plus column 2
    _frustum[FRONT][0] = _clipData[3] + _clipData[2];
    _frustum[FRONT][1] = _clipData[7] + _clipData[6];
    _frustum[FRONT][2] = _clipData[11] + _clipData[10];
    _frustum[FRONT][3] = _clipData[15] + _clipData[14];
    rescalePlane(_frustum, FRONT);
}

