// Fuzzer entry point that checks for specific input pattern across multiple threads
extern "C" int LLVMFuzzerTestOneInput(const uint8_t *inputData, size_t inputSize) {
    auto checkCondition = [&] {
        if (inputSize >= 2 && inputData[0] == 'H') {
            std::cout << "BINGO; Found the target, exiting\n";
            abort();
        }
    };

    // Launch six threads to concurrently execute the check
    std::thread workerThreads[] = {
        std::thread(checkCondition),
        std::thread(checkCondition),
        std::thread(checkCondition),
        std::thread(checkCondition),
        std::thread(checkCondition),
        std::thread(checkCondition)
    };

    // Wait for all threads to complete
    for (auto &worker : workerThreads) {
        worker.join();
    }

    return 0;
}

