int main()
{
    pugi::xml_document doc;

    // Create root node and populate with child elements
    pugi::xml_node root = doc.append_child("node");

    // Insert a description element containing text content
    pugi::xml_node descNode = root.append_child("description");
    descNode.append_child(pugi::node_pcdata).set_value("Simple node");

    // Insert a parameter node before the description
    pugi::xml_node paramNode = root.insert_child_before("param", descNode);

    // Set attributes on the parameter node
    paramNode.append_attribute("name") = "version";
    paramNode.append_attribute("value") = 1.1;
    paramNode.insert_attribute_after("type", paramNode.attribute("name")) = "float";

    // Output the resulting XML document
    doc.print(std::cout);
}
