#include <gtest/gtest.h>

TEST(hsa, tables)
{
    using namespace rocprofiler::hsa;

    // Retrieve HSA API table version info
    auto ver_info = get_table_version();

    // Obtain individual HSA extension tables
    auto* core_tbl     = get_core_table();
    auto* amd_ext_tbl  = get_amd_ext_table();
    auto* fini_ext_tbl = get_fini_ext_table();
    auto* img_ext_tbl  = get_img_ext_table();
    auto* tool_tbl     = get_amd_tool_table();

#if ROCPROFILER_SDK_HSA_PC_SAMPLING > 0
    auto* pcs_tbl = get_pc_sampling_ext_table();
#endif

    // Get full HsaApiTable instance
    auto full_table = get_table();

    //------------------------------------------------------------------------//
    //  Validate against HSA header constants
    //------------------------------------------------------------------------//
    EXPECT_EQ(ver_info.major_id, HSA_API_TABLE_MAJOR_VERSION);
    EXPECT_EQ(ver_info.minor_id, sizeof(hsa_api_table_t));
    EXPECT_EQ(ver_info.step_id, HSA_API_TABLE_STEP_VERSION);

    EXPECT_EQ(core_tbl->version.major_id, HSA_CORE_API_TABLE_MAJOR_VERSION);
    EXPECT_EQ(core_tbl->version.minor_id, sizeof(hsa_core_table_t));
    EXPECT_EQ(core_tbl->version.step_id, HSA_CORE_API_TABLE_STEP_VERSION);

    EXPECT_EQ(amd_ext_tbl->version.major_id, HSA_AMD_EXT_API_TABLE_MAJOR_VERSION);
    EXPECT_EQ(amd_ext_tbl->version.minor_id, sizeof(hsa_amd_ext_table_t));
    EXPECT_EQ(amd_ext_tbl->version.step_id, HSA_AMD_EXT_API_TABLE_STEP_VERSION);

    EXPECT_EQ(fini_ext_tbl->version.major_id, HSA_FINALIZER_API_TABLE_MAJOR_VERSION);
    EXPECT_EQ(fini_ext_tbl->version.minor_id, sizeof(hsa_fini_ext_table_t));
    EXPECT_EQ(fini_ext_tbl->version.step_id, HSA_FINALIZER_API_TABLE_STEP_VERSION);

    EXPECT_EQ(img_ext_tbl->version.major_id, HSA_IMAGE_API_TABLE_MAJOR_VERSION);
    EXPECT_EQ(img_ext_tbl->version.minor_id, sizeof(hsa_img_ext_table_t));
    EXPECT_EQ(img_ext_tbl->version.step_id, HSA_IMAGE_API_TABLE_STEP_VERSION);

    EXPECT_EQ(tool_tbl->version.major_id, HSA_TOOLS_API_TABLE_MAJOR_VERSION);
    EXPECT_EQ(tool_tbl->version.minor_id, sizeof(hsa_amd_tool_table_t));
    EXPECT_EQ(tool_tbl->version.step_id, HSA_TOOLS_API_TABLE_STEP_VERSION);

#if ROCPROFILER_SDK_HSA_PC_SAMPLING > 0
    EXPECT_EQ(pcs_tbl->version.major_id, HSA_PC_SAMPLING_API_TABLE_MAJOR_VERSION);
    EXPECT_EQ(pcs_tbl->version.minor_id, sizeof(hsa_pc_sampling_ext_table_t));
    EXPECT_EQ(pcs_tbl->version.step_id, HSA_PC_SAMPLING_API_TABLE_STEP_VERSION);
#endif

    //------------------------------------------------------------------------//
    //  Cross-check consistency between retrieved components and full table
    //------------------------------------------------------------------------//
    EXPECT_EQ(full_table.version.major_id, ver_info.major_id);
    EXPECT_EQ(full_table.version.minor_id, ver_info.minor_id);
    EXPECT_EQ(full_table.version.step_id, ver_info.step_id);

    EXPECT_EQ(full_table.core_, core_tbl);
    EXPECT_EQ(full_table.amd_ext_, amd_ext_tbl);
    EXPECT_EQ(full_table.finalizer_ext_, fini_ext_tbl);
    EXPECT_EQ(full_table.image_ext_, img_ext_tbl);
}

