    std::cin.tie(nullptr);

    int start_depth;
    std::cin >> start_depth;

    if (start_depth == 0) {
        return 0;
    }

    int current_depth = start_depth;
    int previous_up_direction = -1;
    bool exit_reached;

    while (current_depth > 0) {
        int chosen_direction = -1;

        if (previous_up_direction == -1) {
            // Initial step: determine upward direction by testing colors
            // Try color 0 first
            std::cout << "move 0" << std::endl;
            std::cin >> exit_reached;
            if (exit_reached) return 0;

            std::cout << "query" << std::endl;
            int depth_after_move;
            std::cin >> depth_after_move;

            std::cout << "move 0" << std::endl; // Return to original position
            std::cin >> exit_reached;

            if (depth_after_move < current_depth) {
                chosen_direction = 0;
            } else {
                // Try color 1 as alternative
                std::cout << "move 1" << std::endl;
                std::cin >> exit_reached;
                if (exit_reached) return 0;

                std::cout << "query" << std::endl;
                std::cin >> depth_after_move;

                std::cout << "move 1" << std::endl; // Return to original position
                std::cin >> exit_reached;

                if (depth_after_move < current_depth) {
                    chosen_direction = 1;
                } else {
                    chosen_direction = 2;
                }
            }
        } else {
            // Subsequent steps: use knowledge of previous direction to test remaining options
            int option_a = (previous_up_direction + 1) % 3;
            int option_b = (previous_up_direction + 2) % 3;

            // Test option_a
            std::cout << "move " << option_a << std::endl;
            std::cin >> exit_reached;
            if (exit_reached) return 0;

            std::cout << "query" << std::endl;
            int new_depth;
            std::cin >> new_depth;

            std::cout << "move " << option_a << std::endl; // Return to original position
            std::cin >> exit_reached;

            if (new_depth < current_depth) {
                chosen_direction = option_a;
            } else {
                chosen_direction = option_b;
            }
        }

        // Final move in this level using determined direction
        std::cout << "move " << chosen_direction << std::endl;
        std::cin >> exit_reached;
        if (exit_reached) {
            return 0;
        }

        current_depth--;
        previous_up_direction = chosen_direction;
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <random>
#include <ctime>
using namespace std;

// Structure to represent an edge between two vertices
struct Edge {
    int from, to;
};

// Global configuration variables
int vertexCount, edgeCount;
vector<Edge> edgeList;
vector<vector<int>> adjacency; // adjacency[u] holds indices of edges incident to u
vector<int> optimalAssignment;  // Best vertex cover found so far
int minCoverSize;               // Size of the best vertex cover

void optimize() {
    const double maxTime = 1.9;
    clock_t startTime = clock();

    // Deterministic RNG with fixed seed for reproducibility
    mt19937 generator(1337);

    // Initialize with trivial solution: all vertices included
    optimalAssignment.assign(vertexCount + 1, 1);
    minCoverSize = vertexCount;

    // Precompute degrees for efficiency
    vector<int> originalDegree(vertexCount + 1, 0);
    for (const auto& e : edgeList) {
        originalDegree[e.from]++;
        originalDegree[e.to]++;
    }

    // Reusable buffers for each iteration
    vector<int> currentAssignment(vertexCount + 1);
    vector<int> dynamicDegree = originalDegree;
    vector<int> edgeStatus(edgeCount, 0);       // 0 = uncovered, 1 = covered
    vector<int> activeEdges(edgeCount);         // List of currently uncovered edge indices
    vector<int> edgePosition(edgeCount);        // Maps edge index -> position in activeEdges
    vector<int> coverageCount(edgeCount, 0);    // How many selected vertices cover each edge
    vector<int> selectedVertices;                // Vertices currently in the solution

    // Main loop: repeatedly generate candidate solutions within time limit
    while (true) {
        // Time check
        double elapsed = static_cast<double>(clock() - startTime) / CLOCKS_PER_SEC;
        if (elapsed > maxTime) break;

        // Reset state for new iteration
        fill(currentAssignment.begin(), currentAssignment.end(), 0);
        dynamicDegree = originalDegree;

        // Initialize active edge list
        for (int i = 0; i < edgeCount; ++i) {
            activeEdges[i] = i;
            edgePosition[i] = i;
            edgeStatus[i] = 0;
        }
        int remainingEdges = edgeCount;
        int currentCoverSize = 0;

        // Greedy construction phase
        while (remainingEdges > 0) {
            // Select random uncovered edge
            int randomIndex = generator() % remainingEdges;
            int edgeIndex = activeEdges[randomIndex];

            int u = edgeList[edgeIndex].from;
            int v = edgeList[edgeIndex].to;

            // Choose endpoint with higher dynamic degree (tie-break randomly)
            int chosenVertex;
            if (dynamicDegree[u] > dynamicDegree[v]) {
                chosenVertex = u;
            } else if (dynamicDegree[v] > dynamicDegree[u]) {
                chosenVertex = v;
            } else {
                chosenVertex = (generator() & 1) ? u : v;
            }

            // Add chosen vertex to solution
            currentAssignment[chosenVertex] = 1;
            currentCoverSize++;

            // Update status of incident edges
            for (int incidentEdge : adjacency[chosenVertex]) {
                if (edgeStatus[incidentEdge] == 1) continue;

                edgeStatus[incidentEdge] = 1;

                // Remove from active edges list in O(1)
                int pos = edgePosition[incidentEdge];
                int lastEdge = activeEdges[remainingEdges - 1];

                activeEdges[pos] = lastEdge;
                edgePosition[lastEdge] = pos;

                remainingEdges--;

                // Decrease degree of neighbor
                int neighbor = (edgeList[incidentEdge].from == chosenVertex) 
                             ? edgeList[incidentEdge].to 
                             : edgeList[incidentEdge].from;
                dynamicDegree[neighbor]--;
            }
        }

        // Optimization phase: remove redundant vertices
        fill(coverageCount.begin(), coverageCount.end(), 0);
        selectedVertices.clear();

        for (int i = 1; i <= vertexCount; ++i) {
            if (currentAssignment[i]) {
                selectedVertices.push_back(i);
                for (int eIdx : adjacency[i]) {
                    coverageCount[eIdx]++;
                }
            }
        }

        // Randomize removal order to explore different local optima
        shuffle(selectedVertices.begin(), selectedVertices.end(), generator);

        for (int vertex : selectedVertices) {
            bool canRemove = true;

            // Check if all incident edges are covered by at least one other vertex
            for (int eIdx : adjacency[vertex]) {
                if (coverageCount[eIdx] < 2) {
                    canRemove = false;
                    break;
                }
            }

            if (canRemove) {
                currentAssignment[vertex] = 0;
                currentCoverSize--;

                // Update coverage counts
                for (int eIdx : adjacency[vertex]) {
                    coverageCount[eIdx]--;
                }
            }
        }

        // Update global best if improved
        if (currentCoverSize < minCoverSize) {
            minCoverSize = currentCoverSize;
            optimalAssignment = currentAssignment;
        }
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    if (cin >> vertexCount >> edgeCount) {
        adjacency.resize(vertexCount + 1);
        edgeList.reserve(edgeCount);

        for (int i = 0; i < edgeCount; ++i) {
            int u, v;
            cin >> u >> v;
            edgeList.push_back({u, v});
            adjacency[u].push_back(i);
            adjacency[v].push_back(i);
        }

        optimize();

        // Output final assignment
        for (int i = 1; i <= vertexCount; ++i) {
            cout << optimalAssignment[i] << '\n';
        }
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    if (!(cin >> T)) return 0;

    while (T--) {
        int n;
        if (!(cin >> n)) return 0;

        // Fixed excluded index (1-based)
        const int fixedPos = 1;
        cout << fixedPos << '\n';
        cout.flush();

        // Query function: sends permutation and reads response
        auto performQuery = [&](const vector<int>& perm) -> int {
            cout << "?";
            for (int val : perm) cout << ' ' << val;
            cout << '\n' << flush;

            int result;
            if (!(cin >> result)) exit(0);
            if (result == -1) exit(0);
            return result;
        };

        // Number of queries: capped at min(10*n, 200)
        int numQueries = min(10 * n, 200);
        vector<vector<int>> queryPerms;
        queryPerms.reserve(numQueries);

        // Seed RNG deterministically for reproducibility
        mt19937 rng(712367 + n * 239017);

        // Generate random permutations
        vector<int> base(n);
        iota(base.begin(), base.end(), 1);
        for (int qIdx = 0; qIdx < numQueries; ++qIdx) {
            shuffle(base.begin(), base.end(), rng);
            queryPerms.push_back(base);
        }

        // Precompute positions: pos[q][value] = index in queryPerms[q]
        vector<vector<int>> valuePositions(numQueries, vector<int>(n + 1));
        for (int q = 0; q < numQueries; ++q) {
            for (int idx = 0; idx < n; ++idx) {
                valuePositions[q][queryPerms[q][idx]] = idx;
            }
        }

        // Perform all queries and store answers
        vector<int> observedAnswers(numQueries);
        for (int q = 0; q < numQueries; ++q) {
            observedAnswers[q] = performQuery(queryPerms[q]);
        }

        // Build cost matrix: cost[i][j] = penalty if p[i+1] = j+1
        const int INF_COST = 1e9;
        vector<vector<int>> penaltyMatrix(n, vector<int>(n, INF_COST));

        for (int src = 1; src <= n; ++src) {
            for (int dst = 1; dst <= n; ++dst) {
                if (src == dst) continue;

                int totalPenalty = 0;
                for (int q = 0; q < numQueries; ++q) {
                    int posSrc = valuePositions[q][src];
                    int posDst = valuePositions[q][dst];
                    bool contributes = (posSrc != fixedPos - 1 && posSrc < posDst);
                    // Penalize based on mismatch with observed answer
                    if (contributes) {
                        totalPenalty += (numQueries - observedAnswers[q]);
                    } else {
                        totalPenalty += observedAnswers[q];
                    }
                    if (totalPenalty >= INF_COST / 2) break;
                }
                penaltyMatrix[src - 1][dst - 1] = totalPenalty;
            }
        }

        // Hungarian algorithm to find minimal-cost assignment (derangement)
        vector<int> u(n + 1, 0), v(n + 1, 0), match(n + 1, 0), path(n + 1, 0);
        for (int i = 1; i <= n; ++i) {
            match[0] = i;
            int col = 0;
            vector<int> minVal(n + 1, INF_COST);
            vector<bool> used(n + 1, false);

            do {
                used[col] = true;
                int row = match[col];
                int delta = INF_COST, nextCol = 0;

                for (int c = 1; c <= n; ++c) if (!used[c]) {
                    int cur = penaltyMatrix[row - 1][c - 1] - u[row] - v[c];
                    if (cur < minVal[c]) {
                        minVal[c] = cur;
                        path[c] = col;
                    }
                    if (minVal[c] < delta) {
                        delta = minVal[c];
                        nextCol = c;
                    }
                }

                for (int c = 0; c <= n; ++c) {
                    if (used[c]) {
                        u[match[c]] += delta;
                        v[c] -= delta;
                    } else {
                        minVal[c] -= delta;
                    }
                }
                col = nextCol;
            } while (match[col] != 0);

            do {
                int prev = path[col];
                match[col] = match[prev];
                col = prev;
            } while (col);
        }

        // Reconstruct mapping: res[i] = j means p[i] = j
        vector<int> permResult(n + 1);
        for (int col = 1; col <= n; ++col) {
            int row = match[col];
            permResult[row] = col;
        }

        // Fix any fixed points (p[i] == i) by swapping in cycles
        vector<int> fixedPoints;
        for (int i = 1; i <= n; ++i) {
            if (permResult[i] == i) fixedPoints.push_back(i);
        }

        if (!fixedPoints.empty()) {
            int sz = fixedPoints.size();
            for (int idx = 0; idx < sz; ++idx) {
                int a = fixedPoints[idx];
                int b = fixedPoints[(idx + 1) % sz];
                swap(permResult[a], permResult[b]);
            }
        }

        // Output final answer
        cout << "!";
        for (int i = 1; i <= n; ++i) {
            cout << ' ' << permResult[i];
        }
        cout << '\n' << flush;
    }

    return 0;
}

#include <vector>
#include <queue>
#include <algorithm>
#include <limits>

class Solution {
public:
    double mincostToHireWorkers(std::vector<int>& quality, std::vector<int>& wage, int k) {
        const int n = quality.size();
        std::vector<std::pair<double, int>> workerData;
        workerData.reserve(n);

        // Precompute wage-to-quality ratios and store with quality
        for (int idx = 0; idx < n; ++idx) {
            double ratio = static_cast<double>(wage[idx]) / quality[idx];
            workerData.emplace_back(ratio, quality[idx]);
        }

        // Sort workers by their required ratio (ascending)
        std::sort(workerData.begin(), workerData.end());

        double bestCost = std::numeric_limits<double>::max();
        std::priority_queue<int> candidateQualities;

        int totalQuality = 0;

        // Iterate through each possible group leader (who sets the ratio)
        for (const auto& [ratio, q] : workerData) {
            candidateQualities.push(q);
            totalQuality += q;

            // Maintain only top k smallest qualities in the heap
            if (static_cast<int>(candidateQualities.size()) > k) {
                totalQuality -= candidateQualities.top();
                candidateQualities.pop();
            }

            // If we have exactly k candidates, compute cost with current ratio
            if (static_cast<int>(candidateQualities.size()) == k) {
                double cost = totalQuality * ratio;
                if (cost < bestCost) {
                    bestCost = cost;
                }
            }
        }

        return bestCost;
    }
};

