using namespace std;

// Helper macros for generating unique names
#define CAT_IMPL(s1, s2) s1##s2
#define CAT(s1, s2) CAT_IMPL(s1, s2)
#define UNIQUE_VAR(prefix) CAT(prefix, __COUNTER__)

// Interface for exception translators
struct ITranslator {
    virtual bool translate(string&) = 0;
};

// Template class implementing the translator interface
template<typename T>
class ExceptionTranslator : public ITranslator {
public:
    ExceptionTranslator(string(*handler)(T)) : m_handler(handler) {}

    bool translate(string& result) override {
        try {
            throw;
        } catch(T caughtEx) {
            result = m_handler(caughtEx);
            return true;
        } catch(...) {
            return false;
        }
    }

private:
    string(*m_handler)(T);
};

// Forward declaration of registration function
void registerTranslatorImpl(ITranslator* translator);

// Registration template function
template<typename T>
int registerTranslator(string(*handler)(T)) {
    static ExceptionTranslator<T> translator(handler);
    registerTranslatorImpl(&translator);
    return 0;
}

// Macro to define and register a translator
#define REGISTER_TRANSLATOR_2(name, type)                  \
    static string name(type);                              \
    static int UNIQUE_VAR(REG_) = registerTranslator(&name); \
    static string name(type)

#define REGISTER_TRANSLATOR(type) REGISTER_TRANSLATOR_2(UNIQUE_VAR(TRANS_), type)

// Storage for translator objects
vector<ITranslator*> translatorList;

// Implementation of the registration function
void registerTranslatorImpl(ITranslator* translator) {
    translatorList.push_back(translator);
}

// Main translation function
string processException() {
    // Try each registered translator
    string result;
    for(size_t i = 0; i < translatorList.size(); ++i) {
        if(translatorList[i]->translate(result)) {
            return result;
        }
    }

    // Fallback handlers for standard exceptions
    try {
        throw;
    } catch(exception& ex) {
        return ex.what();
    } catch(const string& msg) {
        return msg;
    } catch(const char* msg) {
        return msg;
    } catch(...) {
        return "Unknown exception!";
    }
}

// Define and register a translator for double values
REGISTER_TRANSLATOR(double& e) {
    return string("double value: ") + to_string(e);
}

