        throw 5.0;
        //throw runtime_error("error occurred!");
    } catch(...) {
        cout << processException() << endl;
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int N;
    cin >> N;

    const double MM = 10000.0;
    const double XX = 20001.0;

    // Initial slope estimation using two points
    double y1 = -300000000.0;
    double delta_init = 10000000.0;
    double y2 = y1 + delta_init;

    cout << "? " << XX << " " << y1 << endl;
    cout.flush();
    double f1;
    cin >> f1;

    cout << "? " << XX << " " << y2 << endl;
    cout.flush();
    double f2;
    cin >> f2;

    double slope_init = (f2 - f1) / delta_init;
    double W = -slope_init;
    double sum_wp = f1 + y1 * W;

    double current_slope = -W;
    double intercept = sum_wp;
    int last_a_index = -10001;

    vector<int> a_values, b_values;

    const double slope_threshold = 1e-4;
    const double epsilon = 0.4;
    const double diff_threshold = 3e-5;

    for (int m = 0; m < N; ++m) {
        // Binary search to find next 'a'
        int left = last_a_index + 1;
        int right = 10000;

        while (left < right) {
            int mid = (left + right) / 2;
            double test_y = mid * XX + MM;

            cout << "? " << XX << " " << test_y << endl;
            cout.flush();
            double val1;
            cin >> val1;

            double test_yp = test_y + epsilon;
            cout << "? " << XX << " " << test_yp << endl;
            cout.flush();
            double val2;
            cin >> val2;

            double local_slope = (val2 - val1) / epsilon;

            if (local_slope > current_slope + slope_threshold) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }

        // Verify candidate
        int candidate_a = left;
        double test_y = candidate_a * XX + MM;

        cout << "? " << XX << " " << test_y << endl;
        cout.flush();
        double val1;
        cin >> val1;

        double test_yp = test_y + epsilon;
        cout << "? " << XX << " " << test_yp << endl;
        cout.flush();
        double val2;
        cin >> val2;

        double local_slope = (val2 - val1) / epsilon;

        if (local_slope <= current_slope + slope_threshold) {
            continue;
        }

        int a_val = candidate_a;

        // Local binary search for precise p value
        double low_p = a_val * XX - MM;
        double high_p = a_val * XX + MM;
        int iterations = 0;
        const int max_iterations = 60;

        while ((high_p - low_p > 1e-10) && (iterations < max_iterations)) {
            ++iterations;
            double mid_p = (low_p + high_p) / 2.0;

            cout << "? " << XX << " " << mid_p << endl;
            cout.flush();
            double f_mid;
            cin >> f_mid;

            double expected = current_slope * mid_p + intercept;
            double difference = f_mid - expected;

            if (difference > diff_threshold) {
                high_p = mid_p;
            } else {
                low_p = mid_p;
            }
        }

        double approx_p = (low_p + high_p) / 2.0;
        long long a_int = llround(approx_p / XX);
        double remainder = approx_p - a_int * XX;
        double p_exact = a_int * XX + round(remainder);
        long long b_int = llround(p_exact - a_int * XX);

        a_values.push_back(static_cast<int>(a_int));
        b_values.push_back(static_cast<int>(b_int));

        // Update model parameters
        double aa = static_cast<double>(a_int);
        double weight = 1.0 / sqrt(aa * aa + 1.0);
        double old_exp = current_slope * p_exact + intercept;

        current_slope += 2.0 * weight;
        intercept = old_exp - current_slope * p_exact;

        last_a_index = static_cast<int>(a_int);
    }

    // Output final answer
    cout << "!";
    for (int a : a_values) cout << " " << a;
    for (int b : b_values) cout << " " << b;
    cout << endl;
    cout.flush();

    return 0;
}

