#include "ReduceUsingSimplifyCFG.h"
#include "llvm/Analysis/TargetTransformInfo.h"
#include "llvm/IR/Constants.h"
#include "llvm/IR/Instructions.h"
#include "llvm/Transforms/Utils/Local.h"

using namespace llvm;

// Simplify control flow by applying simplifyCFG to selected basic blocks
static void reduceUsingSimplifyCFG(Oracle &O, ReducerWorkItem &WorkItem) {
  Module &Program = WorkItem.getModule();
  SmallVector<BasicBlock *, 16> BlocksToProcess;

  // Collect basic blocks that should be simplified (those not marked for preservation)
  for (Function &Func : Program) {
    for (BasicBlock &BB : Func) {
      if (!O.shouldKeep()) {
        BlocksToProcess.push_back(&BB);
      }
    }
  }

  TargetTransformInfo TTI(Program.getDataLayout());

  // Apply simplification to each collected block
  for (BasicBlock *BB : BlocksToProcess) {
    simplifyCFG(BB, TTI);
  }
}

void llvm::reduceUsingSimplifyCFGDeltaPass(TestRunner &Test) {
  runDeltaPass(Test, reduceUsingSimplifyCFG, "Reducing using SimplifyCFG");
}

// Modify conditional branches to constant values and simplify resulting CFG
static void reduceConditionals(Oracle &O, ReducerWorkItem &WorkItem, bool ToTrue) {
  Module &M = WorkItem.getModule();
  SmallVector<BasicBlock *, 16> BlocksNeedingSimplification;

  for (Function &F : M) {
    for (BasicBlock &BB : F) {
      auto *Term = dyn_cast<BranchInst>(BB.getTerminator());

      // Skip non-conditional branches or blocks marked for preservation
      if (!Term || !Term->isConditional() || O.shouldKeep())
        continue;

      // Replace condition with true or false based on direction
      if (ToTrue) {
        Term->setCondition(ConstantInt::getTrue(Term->getContext()));
      } else {
        Term->setCondition(ConstantInt::getFalse(Term->getContext()));
      }

      BlocksNeedingSimplification.push_back(&BB);
    }
  }

  TargetTransformInfo TTI(M.getDataLayout());

  // Apply CFG simplification after branch modification
  for (BasicBlock *BB : BlocksNeedingSimplification) {
    simplifyCFG(BB, TTI);
  }
}

void llvm::reduceConditionalsTrueDeltaPass(TestRunner &Test) {
  runDeltaPass(
      Test,
      [](Oracle &O, ReducerWorkItem &WorkItem) {
        reduceConditionals(O, WorkItem, true);
      },
      "Forcing conditional branches to always take the true path");
}

void llvm::reduceConditionalsFalseDeltaPass(TestRunner &Test) {
  runDeltaPass(
      Test,
      [](Oracle &O, ReducerWorkItem &WorkItem) {
        reduceConditionals(O, WorkItem, false);
      },
      "Forcing conditional branches to always take the false path");
}

