namespace {

// Helper struct to hold vector data with its ID
struct VectorData {
    uint64_t id {0};
    std::vector<float> components;
};

// Compute squared Euclidean distance between two vectors
float computeSquaredDistance(const std::vector<float>& first, const std::vector<float>& second) {
    float result = 0.0f;
    size_t len = first.size();
    for (size_t idx = 0; idx < len; ++idx) {
        float diff = first[idx] - second[idx];
        result += diff * diff;
    }
    return result;
}

// Find k nearest neighbors using squared Euclidean distance
void getKNearestNeighbors(std::vector<uint64_t>& output,
                          const std::vector<VectorData>& candidates,
                          const std::vector<float>& target,
                          size_t count) {
    // Store distance and ID pairs in a temporary container
    struct DistanceEntry {
        float dist;
        uint64_t nodeId;
        bool operator<(const DistanceEntry& other) const { return dist < other.dist; }
    };

    std::vector<DistanceEntry> entries;
    entries.reserve(candidates.size());

    for (const auto& vec : candidates) {
        float d = computeSquaredDistance(vec.components, target);
        entries.push_back({d, vec.id});
    }

    // Partially sort to get top 'count' elements
    if (count > entries.size()) {
        count = entries.size();
    }
    std::partial_sort(entries.begin(), entries.begin() + count, entries.end());

    // Extract IDs of top-k results
    output.clear();
    for (size_t i = 0; i < count; ++i) {
        output.push_back(entries[i].nodeId);
    }
}

