                    << "ID mismatch at row " << i << ": expected " << expectedIds[i]
                    << ", got " << *idCol->at(i);
                ASSERT_TRUE(titleCol->at(i).has_value())
                    << "n.title is null at row " << i;
                ASSERT_EQ(*titleCol->at(i), expectedTitles[i])
                    << "Title mismatch at row " << i << ": expected " << expectedTitles[i]
                    << ", got " << *titleCol->at(i);
            }
            executed = true;
        });
    ASSERT_TRUE(res.isOk()) << "Query failed: " << res.getError();
    ASSERT_TRUE(executed);
}

int main(int argc, char** argv) {
    return turing::test::turingTestMain(argc, argv, [] {
        testing::GTEST_FLAG(repeat) = 1;
    });
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int b, w, x, y;
    if (!(cin >> b >> w >> x >> y)) return 0;

    // Handle the special case where black and white counts differ by at most 1
    if (abs(b - w) <= 1) {
        int rows = 1;
        int cols = b + w;
        cout << rows << " " << cols << "\n";

        bool firstIsBlack = (b >= w);
        int placedBlack = 0, placedWhite = 0;

        for (int pos = 0; pos < cols; ++pos) {
            bool shouldPlaceBlack = ((pos % 2 == 0) == firstIsBlack);

            if (shouldPlaceBlack) {
                if (placedBlack < b) {
                    cout << '@';
                    placedBlack++;
                } else {
                    cout << '.';
                    placedWhite++;
                }
            } else {
                if (placedWhite < w) {
                    cout << '.';
                    placedWhite++;
                } else {
                    cout << '@';
                    placedBlack++;
                }
            }
        }
        cout << "\n";
        return 0;
    }

    // General case: construct a 5-row grid
    int width = max(2 * b - 1, 2 * w - 1);
    int height = 5;
    vector<string> grid(height, string(width, '@'));

    // Fill top two rows with white cells
    for (int col = 0; col < width; ++col) {
        grid[0][col] = '.';
        grid[1][col] = '.';
    }

    // Place black islands in row 0 at even columns
    for (int i = 0; i < b; ++i) {
        int c = 2 * i;
        if (c < width) {
            grid[0][c] = '@';
            if (c + 1 < width) {
                grid[0][c + 1] = '.';
                grid[1][c + 1] = '.';
            }
        }
    }

    // Place white islands in row 3 at even columns
    for (int i = 0; i < w; ++i) {
        int c = 2 * i;
        if (c < width) {
            grid[3][c] = '.';
        }
    }

    // Connect upper black islands to lower black area
    int connectCol1;
    if (b == 1) {
        connectCol1 = 0;
    } else {
        connectCol1 = 2 * (b - 1);
    }
    if (connectCol1 < width) {
        grid[1][connectCol1] = '@';
    }

    // Connect white islands through middle separator row
    int connectCol2;
    if (b == 1) {
        connectCol2 = (w >= 2 ? 2 : 0);
    } else {
        connectCol2 = 0;
        if (connectCol2 == connectCol1 && w >= 2) {
            connectCol2 = 2;
        }
    }

    // Adjust if needed due to boundary or overlap issues
    if (connectCol2 >= width || connectCol2 % 2 != 0) {
        connectCol2 = (w > 0 ? 2 * (min(w - 1, (width - 1) / 2)) : 0);
    }

    // Ensure separator cell is white for connection
    if (connectCol2 < width) {
        grid[2][connectCol2] = '.';
    }

    // Output result
    cout << height << " " << width << "\n";
    for (const auto& row : grid) {
        cout << row << "\n";
    }

    return 0;
}

