void XmlBtPolarWriter::writeXMLBtPolar(BoatPolar *polarData)
{
    if (!polarData) return;

    setAutoFormatting(true);
    writeStartDocument();

    {
        writeDTD("<!DOCTYPE flow5>");
        writeStartElement("XflBoatPolar");

        {
            writeAttribute("version", "1.0");
            writeUnits();
            writeBtPolarContent(polarData);
        }

        writeEndElement();
    }

    writeEndDocument();
}

void XmlBtPolarWriter::writeBtPolarContent(BoatPolar const *polarData)
{
    QString tempString;
    writeStartElement("Polar");

    {
        writeTextElement("Polar_Name", QString::fromStdString(polarData->name()));
        writeComment("For scripts: if the boat's name is left blank, the analysis will be associated to all available boats");
        writeTextElement("Boat_Name", QString::fromStdString(polarData->boatName()));
        writeComment("Boat polars are necessarily of the control type");
        writeTheStyle(polarData->theStyle());
        writeTextElement("Method", xml::analysisMethod(polarData->analysisMethod()));

        writeStartElement("Reference_Dimensions");
        {
            writeComment("Available options are AUTO and CUSTOM");
            writeTextElement("Reference_Dimensions", xml::referenceDimension(polarData->referenceDim()));
            writeComment("The following fields are required only if dimensions are set to CUSTOM");

            double areaInUnit = polarData->referenceArea() * Units::m2toUnit();
            double chordInUnit = polarData->referenceChordLength() * Units::mtoUnit();

            writeTextElement("Reference_Area",         QString::asprintf("%11.5f", areaInUnit));
            writeTextElement("Reference_Chord_Length", QString::asprintf("%11.5f", chordInUnit));
        }
        writeEndElement();

        writeWakeData(*polarData);

        // Center of Gravity in current units
        double cogX = polarData->CoG().x * Units::mtoUnit();
        double cogY = polarData->CoG().y * Units::mtoUnit();
        double cogZ = polarData->CoG().z * Units::mtoUnit();

        tempString = QString::asprintf("%g, %g, %g", cogX, cogY, cogZ);
        writeTextElement("CoG", tempString);

        writeStartElement("Wind_gradient");
        {
            writeWindSpline(polarData->windSpline());
        }
        writeEndElement();

        writeFluidProperties(polarData->viscosity(), polarData->density());

        if (polarData->hasExtraDrag())
            writeExtraDrag(polarData->extraDragList());

        writeComment("Min and max values separated by a comma ,");

        writeTextElement("Boat_Speed", QString::asprintf(" %g, %g", polarData->VBtMin(),  polarData->VBtMax()));
        writeTextElement("TWS",        QString::asprintf(" %g, %g", polarData->qInfMin(), polarData->qInfMax()));
        writeTextElement("TWA",        QString::asprintf(" %g, %g", polarData->twaMin(),  polarData->twaMax()));
        writeTextElement("Phi",        QString::asprintf(" %g, %g", polarData->phiMin(),  polarData->phiMax()));
        writeTextElement("Ry",         QString::asprintf(" %g, %g", polarData->RyMin(),   polarData->RyMax()));

        writeStartElement("SailAngles");
        {
            int sailCount = polarData->sailAngleSize();
            for (int idx = 0; idx < sailCount; ++idx)
            {
                QString label, valueStr;
                label = QString::asprintf("Sail_%d", idx + 1);
                valueStr = QString::asprintf("%.3f,  %.3f", polarData->sailAngleMin(idx), polarData->sailAngleMax(idx));
                writeTextElement(label, valueStr);
            }
        }
        writeEndElement();
    }

    writeEndElement();
}

void XmlBtPolarWriter::writeWindSpline(BSpline const &splineCurve)
{
    writeTextElement("Degree", QString::asprintf("%d", splineCurve.degree()));

    int ptCount = splineCurve.ctrlPointCount();
    for (int i = 0; i < ptCount; ++i)
    {
        QPointF point = splineCurve.controlPoint(i);
        writeTextElement("Point", QString::asprintf("%g, %g", point.x(), point.y())); // meters only
    }
}

