#include "Buffer.h"
#include <cassert>

// Constructor: initializes buffer with given capacity
Buffer::Buffer(unsigned int capacity)
    : m_capacity(capacity),
      m_position(0),
      m_limit(capacity),
      hasBackingArray(false) {}

// Reset buffer state: position becomes 0, limit equals capacity
// This prepares the buffer for new data without clearing underlying storage
Buffer* Buffer::resetState() {
    m_position = 0;
    m_limit    = m_capacity;
    return this;
}

// Adjust the buffer's limit to a specified value
// Ensures position doesn't exceed the new limit
Buffer* Buffer::setLimit(unsigned int newLimit) {
    assert(newLimit <= m_capacity);
    m_limit = newLimit;

    // If current position exceeds new limit, move it back
    if (m_position > newLimit) {
        m_position = newLimit;
    }

    return this;
}

// Retrieve current limit value
unsigned int Buffer::getLimit() const { 
    return m_limit; 
}

// Set buffer position to specified index
Buffer* Buffer::setPos(unsigned int newPos) {
    assert(newPos <= m_limit);
    m_position = newPos;
    return this;
}

// Get current position in buffer
unsigned int Buffer::getPos() const { 
    return m_position; 
}

// Calculate how many elements remain between current position and limit
unsigned int Buffer::countRemaining() const { 
    return m_limit - m_position; 
}

