//*******************************************************
// Class VectorRn
VectorRn VectorRn::WorkVector;

double VectorRn::MaxAbs() const {
  double result = 0.0;
  double* currentPtr = x;
  long remaining = length;

  while (remaining > 0) {
    double val = *currentPtr;
    if (val > result) {
      result = val;
    } else if (-val > result) {
      result = -val;
    }
    currentPtr++;
    remaining--;
  }
  return result;
}

//*************************************************************************
// MatrixRmn
MatrixRmn MatrixRmn::WorkMatrix;  // Temporary work matrix

void MatrixRmn::SetDiagonalEntries(double value) {
  long diagLength = std::min(NumRows, NumCols);
  double* diagPtr = x;

  while (diagLength > 0) {
    *diagPtr = value;
    diagPtr += NumRows + 1;
    diagLength--;
  }
}

void MatrixRmn::SetDiagonalEntries(const VectorRn& diagonal) {
  long diagLength = std::min(NumRows, NumCols);
  assert(diagonal.length == diagLength);

  double* diagPtr = x;
  const double* sourcePtr = diagonal.x;

  while (diagLength > 0) {
    *diagPtr = *sourcePtr;
    sourcePtr++;
    diagPtr += NumRows + 1;
    diagLength--;
  }
}

void MatrixRmn::SetSuperDiagonalEntries(double value) {
  long sDiagLen = std::min(NumRows, static_cast<long>(NumCols - 1));
  double* targetPtr = x + NumRows;

  while (sDiagLen > 0) {
    *targetPtr = value;
    targetPtr += NumRows + 1;
    sDiagLen--;
  }
}

void MatrixRmn::SetSuperDiagonalEntries(const VectorRn& diagonal) {
  long sDiagLen = std::min(static_cast<long>(NumRows - 1), NumCols);
  assert(sDiagLen == diagonal.length);

  double* targetPtr = x + NumRows;
  const double* sourcePtr = diagonal.x;

  while (sDiagLen > 0) {
    *targetPtr = *sourcePtr;
    sourcePtr++;
    targetPtr += NumRows + 1;
    sDiagLen--;
  }
}

void MatrixRmn::SetSubDiagonalEntries(double value) {
  long sDiagLen = std::min(NumRows, NumCols) - 1;
  double* targetPtr = x + 1;

  while (sDiagLen > 0) {
    *targetPtr = value;
    targetPtr += NumRows + 1;
    sDiagLen--;
  }
}

void MatrixRmn::SetSubDiagonalEntries(const VectorRn& diagonal) {
  long sDiagLen = std::min(NumRows, NumCols) - 1;
  assert(sDiagLen == diagonal.length);

  double* targetPtr = x + 1;
  const double* sourcePtr = diagonal.x;

  while (sDiagLen > 0) {
    *targetPtr = *sourcePtr;
    sourcePtr++;
    targetPtr += NumRows + 1;
    sDiagLen--;
  }
}

void MatrixRmn::SetColumn(long colIndex, const VectorRn& column) {
  assert(NumRows == column.GetLength());
  double* destPtr = x + colIndex * NumRows;
  const double* sourcePtr = column.x;

  for (long i = NumRows; i > 0; i--) {
    *(destPtr++) = *(sourcePtr++);
  }
}

void MatrixRmn::SetRow(long rowIndex, const VectorRn& row) {
  assert(NumCols == row.GetLength());
  double* destPtr = x + rowIndex;
  const double* sourcePtr = row.x;

  for (long i = NumRows; i > 0; i--) {
    *destPtr = *sourcePtr;
    destPtr += NumRows;
    sourcePtr++;
  }
}

void MatrixRmn::SetSequence(const VectorRn& sequence, long startRow, long startCol,
                           long deltaRow, long deltaCol) {
  long length = sequence.length;
  assert(startRow >= 0 && startRow < NumRows && startCol >= 0 &&
         startCol < NumCols);
  assert(startRow + (length - 1) * deltaRow >= 0 &&
         startRow + (length - 1) * deltaRow < NumRows);
  assert(startCol + (length - 1) * deltaCol >= 0 &&
         startCol + (length - 1) * deltaCol < NumCols);

  double* destPtr = x + startRow + NumRows * startCol;
  const double* sourcePtr = sequence.x;
  long stride = deltaRow + NumRows * deltaCol;

  while (length > 0) {
    *destPtr = *sourcePtr;
    sourcePtr++;
    destPtr += stride;
    length--;
  }
}

void MatrixRmn::LoadAsSubmatrix(const MatrixRmn& source) {
  assert(source.NumRows <= NumRows && source.NumCols <= NumCols);
  int extraColStep = NumRows - source.NumRows;
  double* destPtr = x;
  const double* sourcePtr = source.x;

  for (long i = source.NumCols; i > 0; i--) {
    for (long j = source.NumRows; j > 0; j--) {
      *(destPtr++) = *(sourcePtr++);
    }
    destPtr += extraColStep;
  }
}

void MatrixRmn::LoadAsSubmatrixTranspose(const MatrixRmn& source) {
  assert(source.NumRows <= NumCols && source.NumCols <= NumRows);
  double* rowPtr = x;
  const double* sourcePtr = source.x;

  for (long i = source.NumCols; i > 0; i--) {
    double* destPtr = rowPtr;
    for (long j = source.NumRows; j > 0; j--) {
      *destPtr = *sourcePtr;
      destPtr += NumRows;
      sourcePtr++;
    }
    rowPtr++;
  }
}

double MatrixRmn::FrobeniusNorm() const { 
  return sqrt(FrobeniusNormSq()); 
}

void MatrixRmn::Multiply(const VectorRn& vector, VectorRn& result) const {
  assert(vector.GetLength() == NumCols && result.GetLength() == NumRows);
  double* outPtr = result.GetPtr();
  const double* rowPtr = x;

  for (long j = NumRows; j > 0; j--) {
    const double* inPtr = vector.GetPtr();
    const double* matPtr = rowPtr++;
    *outPtr = 0.0f;

    for (long i = NumCols; i > 0; i--) {
      *outPtr += (*inPtr) * (*matPtr);
      inPtr++;
      matPtr += NumRows;
    }
    outPtr++;
  }
}

void MatrixRmn::MultiplyTranspose(const VectorRn& vector, VectorRn& result) const {
  assert(vector.GetLength() == NumRows && result.GetLength() == NumCols);
  double* outPtr = result.GetPtr();
  const double* colPtr = x;

  for (long i = NumCols; i > 0; i--) {
    const double* inPtr = vector.GetPtr();
    *outPtr = 0.0f;

    for (long j = NumRows; j > 0; j--) {
      *outPtr += (*inPtr) * (*colPtr);
      inPtr++;
      colPtr++;
    }
    outPtr++;
  }
}

double MatrixRmn::DotProductColumn(const VectorRn& vector, long colNum) const {
  assert(vector.GetLength() == NumRows);
  double* colPtr = x + colNum * NumRows;
  double* vecPtr = vector.x;
  double result = 0.0;

  for (long i = NumRows; i > 0; i--) {
    result += (*colPtr) * (*vecPtr);
    colPtr++;
    vecPtr++;
  }
  return result;
}

MatrixRmn& MatrixRmn::AddToDiagonal(double value) {
  long diagLen = std::min(NumRows, NumCols);
  double* diagPtr = x;

  while (diagLen > 0) {
    *diagPtr += value;
    diagPtr += NumRows + 1;
    diagLen--;
  }
  return *this;
}

MatrixRmn& MatrixRmn::AddToDiagonal(const VectorRn& diagonal) {
  long diagLen = std::min(NumRows, NumCols);
  double* diagPtr = x;
  const double* diagValPtr = diagonal.x;

  while (diagLen > 0) {
    *diagPtr += *diagValPtr;
    diagValPtr++;
    diagPtr += NumRows + 1;
    diagLen--;
  }
  return *this;
}

MatrixRmn& MatrixRmn::MultiplyScalar(const MatrixRmn& source, double scaleFactor,
                                    MatrixRmn& destination) {
  long numCols = source.NumCols;
  double* destPtr = destination.x;

  for (long i = destination.NumCols; i > 0; i--) {
    double* srcPtr = source.x;
    for (long j = destination.NumRows; j > 0; j--) {
      *destPtr = *srcPtr * scaleFactor;
      destPtr++;
      srcPtr++;
    }
    srcPtr += source.NumRows;
  }
  return destination;
}

MatrixRmn& MatrixRmn::Multiply(const MatrixRmn& first, const MatrixRmn& second,
                              MatrixRmn& destination) {
  assert(first.NumCols == second.NumRows && first.NumRows == destination.NumRows &&
         second.NumCols == destination.NumCols);
  long commonDim = first.NumCols;
  double* secPtr = second.x;
  double* destPtr = destination.x;

  for (long i = destination.NumCols; i > 0; i--) {
    double* firPtr = first.x;
    for (long j = destination.NumRows; j > 0; j--) {
      *destPtr = DotArray(commonDim, firPtr, first.NumRows, secPtr, 1);
      destPtr++;
      firPtr++;
    }
    secPtr += second.NumRows;
  }
  return destination;
}

MatrixRmn& MatrixRmn::TransposeMultiply(const MatrixRmn& first, const MatrixRmn& second,
                                       MatrixRmn& destination) {
  assert(first.NumRows == second.NumRows && first.NumCols == destination.NumRows &&
         second.NumCols == destination.NumCols);
  long commonDim = first.NumRows;
  double* secPtr = second.x;
  double* destPtr = destination.x;

  for (long i = destination.NumCols; i > 0; i--) {
    double* firPtr = first.x;
    for (long j = destination.NumRows; j > 0; j--) {
      *destPtr = DotArray(commonDim, firPtr, 1, secPtr, 1);
      destPtr++;
      firPtr += first.NumRows;
    }
    secPtr += second.NumRows;
  }
  return destination;
}

MatrixRmn& MatrixRmn::MultiplyTranspose(const MatrixRmn& first, const MatrixRmn& second,
                                       MatrixRmn& destination) {
  assert(first.NumCols == second.NumCols && first.NumRows == destination.NumRows &&
         second.NumRows == destination.NumCols);
  long commonDim = first.NumCols;
  double* secPtr = second.x;
  double* destPtr = destination.x;

  for (long i = destination.NumCols; i > 0; i--) {
    double* firPtr = first.x;
    for (long j = destination.NumRows; j > 0; j--) {
      *destPtr = DotArray(commonDim, firPtr, first.NumRows, secPtr, second.NumRows);
      destPtr++;
      firPtr++;
    }
    secPtr++;
  }
  return destination;
}

void MatrixRmn::Solve(const VectorRn& b, VectorRn* solution) const {
  assert(NumRows == NumCols && NumCols == solution->GetLength() &&
         NumRows == b.GetLength());

  MatrixRmn& augmentedMat = GetWorkMatrix(NumRows, NumCols + 1);
  augmentedMat.LoadAsSubmatrix(*this);
  augmentedMat.SetColumn(NumRows, b);
  augmentedMat.ConvertToRefNoFree();

  double* solLast = solution->x + NumRows - 1;
  double* endRow = augmentedMat.x + NumRows * NumCols - 1;
  double* rhsPtr = endRow + NumRows;

  for (long i = NumRows; i > 0; i--) {
    double accum = *(rhsPtr--);
    double* rowPtr = endRow;
    double* solPtr = solLast;

    for (long j = NumRows - i; j > 0; j--) {
      accum -= (*rowPtr) * (*(solPtr--));
      rowPtr -= NumCols;
    }
    assert(*rowPtr != 0.0);
    *solPtr = accum / (*rowPtr);
    endRow--;
  }
}

void MatrixRmn::ConvertToRefNoFree() {
  long numIters = std::min(NumRows, NumCols);
  double* rowPtr1 = x;
  const long diagStep = NumRows + 1;
  long lenRowLeft = NumCols;

  while (numIters > 1) {
    double* rowPtr2 = rowPtr1;
    double maxAbs = fabs(*rowPtr1);
    double* rowPivot = rowPtr1;
    long i;

    for (i = numIters - 1; i > 0; i--) {
      const double& newVal = *(++rowPivot);
      if (newVal > maxAbs) {
        maxAbs = newVal;
        rowPtr2 = rowPivot;
      } else if (-newVal > maxAbs) {
        maxAbs = -newVal;
        rowPtr2 = rowPivot;
      }
    }

    if (rowPtr1 != rowPtr2) {
      double* to = rowPtr1;
      for (long i = lenRowLeft; i > 0; i--) {
        double temp = *to;
        *to = *rowPtr2;
        *rowPtr2 = temp;
        to += NumRows;
        rowPtr2 += NumRows;
      }
    }

    rowPtr2 = rowPtr1;
    for (i = numIters - 1; i > 0; i--) {
      rowPtr2++;
      double* to = rowPtr2;
      double* from = rowPtr1;
      assert(*from != 0.0);
      double alpha = (*to) / (*from);
      *to = 0.0;
      for (long j = lenRowLeft - 1; j > 0; j--) {
        to += NumRows;
        from += NumRows;
        *to -= (*from) * alpha;
      }
    }

    rowPtr1 += diagStep;
    lenRowLeft--;
  }
}

void MatrixRmn::CalcGivensValues(double a, double b, double* c, double* s) {
  double denomInv = sqrt(a * a + b * b);
  if (denomInv == 0.0) {
    *c = 1.0;
    *s = 0.0;
  } else {
    denomInv = 1.0 / denomInv;
    *c = a * denomInv;
    *s = -b * denomInv;
  }
}

void MatrixRmn::PostApplyGivens(double c, double s, long index) {
  assert(0 <= index && index < NumCols);
  double* colA = x + index * NumRows;
  double* colB = colA + NumRows;

  for (long i = NumRows; i > 0; i--) {
    double temp = *colA;
    *colA = (*colA) * c + (*colB) * s;
    *colB = (*colB) * c - temp * s;
    colA++;
    colB++;
  }
}

void MatrixRmn::PostApplyGivens(double c, double s, long idx1, long idx2) {
  assert(idx1 != idx2 && 0 <= idx1 && idx1 < NumCols && 0 <= idx2 &&
         idx2 < NumCols);
  double* colA = x + idx1 * NumRows;
  double* colB = x + idx2 * NumRows;

  for (long i = NumRows; i > 0; i--) {
    double temp = *colA;
    *colA = (*colA) * c + (*colB) * s;
    *colB = (*colB) * c - temp * s;
    colA++;
    colB++;
  }
}

void MatrixRmn::ComputeSVD(MatrixRmn& U, VectorRn& w, MatrixRmn& V) const {
  assert(U.NumRows == NumRows && V.NumCols == NumCols &&
         U.NumRows == U.NumCols && V.NumRows == V.NumCols &&
         w.GetLength() == std::min(NumRows, NumCols));

  VectorRn& superDiag = VectorRn::GetWorkVector(w.GetLength() - 1);

  MatrixRmn* leftMatrix;
  MatrixRmn* rightMatrix;
  if (NumRows >= NumCols) {
    U.LoadAsSubmatrix(*this);
    leftMatrix = &U;
    rightMatrix = &V;
  } else {
    V.LoadAsSubmatrixTranspose(*this);
    leftMatrix = &V;
    rightMatrix = &U;
  }

  CalcBidiagonal(*leftMatrix, *rightMatrix, w, superDiag);
  ConvertBidiagToDiagonal(*leftMatrix, *rightMatrix, w, superDiag);
}

void MatrixRmn::CalcBidiagonal(MatrixRmn& U, MatrixRmn& V, VectorRn& w,
                              VectorRn& superDiag) {
  assert(U.NumRows >= V.NumRows);

  const long rowStep = U.NumCols;
  const long diagStep = U.NumCols + 1;
  double* diagPtr = U.x;
  double* wPtr = w.x;
  double* superDiagPtr = superDiag.x;
  long colLengthLeft = U.NumRows;
  long rowLengthLeft = V.NumCols;

  while (true) {
    SvdHouseholder(diagPtr, colLengthLeft, rowLengthLeft, 1, rowStep, wPtr);
    if (rowLengthLeft == 2) {
      *superDiagPtr = *(diagPtr + rowStep);
      break;
    }

    SvdHouseholder(diagPtr + rowStep, rowLengthLeft - 1, colLengthLeft, rowStep,
                   1, superDiagPtr);
    rowLengthLeft--;
    colLengthLeft--;
    diagPtr += diagStep;
    wPtr++;
    superDiagPtr++;
  }

  int extra = 0;
  diagPtr += diagStep;
  wPtr++;
  if (colLengthLeft > 2) {
    extra = 1;
    colLengthLeft--;
    SvdHouseholder(diagPtr, colLengthLeft, 1, 1, 0, wPtr);
  } else {
    *wPtr = *diagPtr;
  }

  V.ExpandHouseholders(V.NumCols - 2, 1, U.x + U.NumRows, U.NumRows, 1);
  U.ExpandHouseholders(V.NumCols - 1 + extra, 0, U.x, 1, U.NumRows);
}

void MatrixRmn::SvdHouseholder(double* basePt, long colLength, long numCols,
                              long colStride, long rowStride,
                              double* retFirstEntry) {
  double* cPtr = basePt;
  double norm = 0.0;
  long i;

  for (i = colLength; i > 0; i--) {
    norm += Square(*cPtr);
    cPtr += colStride;
  }
  norm = sqrt(norm);

  double imageVal;
  if ((*basePt) < 0.0) {
    imageVal = norm;
    norm = 2.0 * norm * (norm - (*basePt));
  } else {
    imageVal = -norm;
    norm = 2.0 * norm * (norm + (*basePt));
  }
  norm = sqrt(norm);

  if (norm == 0.0) {
    cPtr = basePt;
    for (i = colLength; i > 0; i--) {
      *cPtr = 0.0;
      cPtr += colStride;
    }
    *retFirstEntry = 0.0;
    return;
  }

  *retFirstEntry = imageVal;
  *basePt -= imageVal;
  norm = 1.0 / norm;
  cPtr = basePt;
  for (i = colLength; i > 0; i--) {
    *cPtr *= norm;
    cPtr += colStride;
  }

  double* rPtr = basePt;
  for (long j = numCols - 1; j > 0; j--) {
    rPtr += rowStride;
    double dotP = DotArray(colLength, basePt, colStride, rPtr, colStride);
    AddArrayScale(colLength, basePt, colStride, rPtr, colStride, -2.0 * dotP);
  }
}

void MatrixRmn::ExpandHouseholders(long numXforms, int numZerosSkipped,
                                  const double* basePt, long colStride,
                                  long rowStride) {
  long numToTransform = NumCols - numXforms + 1 - numZerosSkipped;
  assert(numToTransform > 0);

  if (numXforms == 0) {
    SetIdentity();
    return;
  }

  long hDiagStride = rowStride + colStride;
  const double* hBase = basePt + hDiagStride * (numXforms - 1);
  const double* hDiagPtr = hBase + colStride * (numToTransform - 1);
  long i;

  double* diagPtr = x + NumCols * NumRows - 1;
  double* colPtr = diagPtr - (numToTransform - 1);

  for (i = numToTransform; i > 0; i--) {
    CopyArrayScale(numToTransform, hBase, colStride, colPtr, 1,
                  -2.0 * (*hDiagPtr));
    *diagPtr += 1.0;
    diagPtr -= (NumRows + 1);
    colPtr -= NumRows;
    hDiagPtr -= colStride;
  }

  double* colLastPtr = x + NumRows * NumCols - numToTransform - 1;
  for (i = numXforms - 1; i > 0; i--) {
    numToTransform++;
    hBase -= hDiagStride;
    colPtr = colLastPtr;

    for (long j = numToTransform - 1; j > 0; j--) {
      double dotProd2N = -2.0 * DotArray(numToTransform - 1, hBase + colStride,
                                        colStride, colPtr + 1, 1);
      *colPtr = dotProd2N * (*hBase);
      AddArrayScale(numToTransform - 1, hBase + colStride, colStride,
                   colPtr + 1, 1, dotProd2N);
      colPtr -= NumRows;
    }

    CopyArrayScale(numToTransform, hBase, colStride, colPtr, 1,
                  -2.0 * (*hBase));
    *colPtr += 1.0;
    colLastPtr--;
  }

  if (numZerosSkipped != 0) {
    assert(numZerosSkipped == 1);
    double* d = x;
    *d = 1;
    double* d2 = d;
    for (i = NumRows - 1; i > 0; i--) {
      *(++d) = 0;
      *(d2 += NumRows) = 0;
    }
  }
}

void MatrixRmn::ConvertBidiagToDiagonal(MatrixRmn& U, MatrixRmn& V, VectorRn& w,
                                       VectorRn& superDiag) const {
  long lastBidiagIdx = V.NumRows - 1;
  long firstBidiagIdx = 0;

  double aa = w.MaxAbs();
  double bb = superDiag.MaxAbs();
  double eps = 1.0e-15 * std::max(w.MaxAbs(), superDiag.MaxAbs());

  while (true) {
    bool workLeft = UpdateBidiagIndices(&firstBidiagIdx, &lastBidiagIdx, w, superDiag, eps);
    if (!workLeft) {
      break;
    }

    double* wPtr = w.x + firstBidiagIdx;
    double* sdPtr = superDiag.x + firstBidiagIdx;
    double extraOffDiag = 0.0;

    if ((*wPtr) == 0.0) {
      ClearRowWithDiagonalZero(firstBidiagIdx, lastBidiagIdx, U, wPtr, sdPtr, eps);
      if (firstBidiagIdx > 0) {
        if (NearZero(*sdPtr, eps)) {
