struct Example {
    int value;

    void modify() {
        value++;
        process();
        display();
        update();
        // Non-const member functions can call other non-const and const members
    }

    void display() const {
        // value++; // Not allowed: modifying member in const function
        // modify(); // Not allowed: calling non-const function from const context
        update();   // Allowed: only const functions can be called here
    }

    void update() const {
        // value++; // Not allowed: modifying member in const function
        // modify(); // Not allowed: calling non-const function from const context
        display();  // Allowed: only const functions can be called here
    }
};

void operateOnNonConst(Example& obj) {
    obj.modify(); // Allowed: non-const object can call any member
    obj.display();
    obj.update();
    // All member functions are accessible on non-const objects
}

void operateOnConst(const Example& obj) {
    // obj.modify(); // Not allowed: const object cannot call non-const members
    obj.display();  // Allowed: const member function
    obj.update();   // Allowed: const member function
    // Only const member functions can be invoked on const objects
}

