// Custom error-checking helper
inline void hip_check(hipError_t err, const char* file, int line) {
    if (err != hipSuccess) {
        std::unique_lock<std::mutex> lk{print_mutex};
        fprintf(stderr, "%s:%d :: HIP error: %s\n", file, line, hipGetErrorString(err));
        throw std::runtime_error("HIP API call failed");
    }
}
#define HIP_CHECK(CALL) hip_check((CALL), __FILE__, __LINE__)

namespace {
using lock_guard = std::unique_lock<std::mutex>;
std::mutex print_mutex{};

constexpr size_t TILE_SIZE = 32;

__global__
void matrix_transpose_kernel(const int* __restrict__ input,
                             int* __restrict__ output,
                             int rows,
                             int cols)
{
    __shared__ int tile[TILE_SIZE][TILE_SIZE];

    int global_row = blockIdx.y * blockDim.y + threadIdx.y;
    int global_col = blockIdx.x * blockDim.x + threadIdx.x;

    // Load tile from global memory
    if (global_row < rows && global_col < cols) {
        tile[threadIdx.y][threadIdx.x] = input[global_row * cols + global_col];
    }

    __syncthreads();

    // Transposed coordinates
    int transposed_row = blockIdx.x * blockDim.x + threadIdx.y;
    int transposed_col = blockIdx.y * blockDim.y + threadIdx.x;

    if (transposed_row < cols && transposed_col < rows) {
        output[transposed_row * rows + transposed_col] = tile[threadIdx.x][threadIdx.y];
    }
}

void run_transpose_task(int rank,
                        int thread_id,
                        int device_id,
                        size_t iterations,
                        size_t sync_interval)
{
    roctxRangePush("run_transpose_task");

    constexpr int M = 4960 * 2;
    constexpr int N = 4960 * 2;

    hipStream_t stream{};
    HIP_CHECK(hipSetDevice(device_id));
    HIP_CHECK(hipStreamCreate(&stream));

    {
        lock_guard lk{print_mutex};
        std::cout << "[transpose][" << rank << "][" << thread_id << "] Device: " << device_id
                  << ", dims: " << M << "x" << N << "\n";
    }

    // Initialize input/output matrices on host
    size_t total_elements = static_cast<size_t>(M) * N;
    size_t byte_count     = total_elements * sizeof(int);

    auto* host_input  = new int[total_elements];
    auto* host_output = new int[total_elements];

    // Seed RNG per thread/rank combination
    std::mt19937 rng_engine{static_cast<unsigned int>(
        std::random_device{}() * (rank + 1) * (thread_id + 1))};
    std::uniform_int_distribution<int> dist{0, 1000};

    for (size_t idx = 0; idx < total_elements; ++idx) {
        host_input[idx]  = dist(rng_engine);
        host_output[idx] = 0;
    }

    // Allocate device memory
    int* dev_input  = nullptr;
    int* dev_output = nullptr;
    HIP_CHECK(hipMalloc(&dev_input, byte_count));
    HIP_CHECK(hipMalloc(&dev_output, byte_count));
    HIP_CHECK(hipMemsetAsync(dev_input, 0, byte_count, stream));
    HIP_CHECK(hipMemsetAsync(dev_output, 0, byte_count, stream));

    // Copy input to device
    HIP_CHECK(hipMemcpyAsync(dev_input, host_input, byte_count, hipMemcpyHostToDevice, stream));
    HIP_CHECK(hipStreamSynchronize(stream));

    // Launch configuration
    dim3 grid_dim{(unsigned)(N / TILE_SIZE), (unsigned)(M / TILE_SIZE), 1};
    dim3 block_dim{TILE_SIZE, TILE_SIZE, 1};

    auto start_time = std::chrono::steady_clock::now();

    for (size_t iter = 0; iter < iterations; ++iter) {
        matrix_transpose_kernel<<<grid_dim, block_dim, 0, stream>>>(dev_input, dev_output, M, N);
        HIP_CHECK(hipGetLastError());
        if ((iter + 1) % sync_interval == 0) {
            HIP_CHECK(hipStreamSynchronize(stream));
        }
    }

    HIP_CHECK(hipStreamSynchronize(stream));
    auto end_time = std::chrono::steady_clock::now();

    // Copy result back
    HIP_CHECK(hipMemcpyAsync(host_output, dev_output, byte_count, hipMemcpyDeviceToHost, stream));
    HIP_CHECK(hipStreamSynchronize(stream));

    double elapsed_seconds =
        std::chrono::duration<double>{end_time - start_time}.count();
    double gigabytes_transferred = (byte_count * 2.0 * iterations) / (1LL << 30);
    double throughput_gbs        = gigabytes_transferred / elapsed_seconds;

    {
        lock_guard lk{print_mutex};
        std::cout << "[transpose][" << rank << "][" << thread_id << "] Time: "
                  << elapsed_seconds << " s\n";
        std::cout << "[transpose][" << rank << "][" << thread_id << "] Throughput: "
                  << throughput_gbs << " GB/s\n";
    }

    // Cleanup
    HIP_CHECK(hipStreamDestroy(stream));
    HIP_CHECK(hipFree(dev_input));
    HIP_CHECK(hipFree(dev_output));
    delete[] host_input;
    delete[] host_output;

    // Optional verification (sample check)
    verify_data(host_input, host_output, M, N);

    roctxRangePop();
}

void verify_data(const int* original, const int* transposed, int rows, int cols)
{
    std::srand(static_cast<unsigned>(std::time(nullptr)));
    for (int trial = 0; trial < 10; ++trial) {
        int r = std::rand() % rows;
        int c = std::rand() % cols;

        int expected = original[r * cols + c];
        int actual   = transposed[c * rows + r];

        if (expected != actual) {
            lock_guard lk{print_mutex};
            std::cerr << "Mismatch at (" << r << "," << c << "): expected=" << expected
                      << ", got=" << actual << "\n";
        }
    }
}

}  // anonymous namespace

void run_transpose(size_t num_threads, size_t num_iterations, size_t sync_every_n)
{
    roctxRangeStart("run_transpose");

    int world_rank = 0;
    int world_size = 1;

    printf("[transpose] Threads: %zu | Iterations: %zu | Sync every: %zu\n",
           num_threads,
           num_iterations,
           sync_every_n);

#if defined(USE_MPI)
    MPI_Comm_rank(MPI_COMM_WORLD, &world_rank);
    MPI_Comm_size(MPI_COMM_WORLD, &world_size);
#else
    (void)world_size;
#endif

    // Get available devices
    int device_count = 0;
    HIP_CHECK(hipGetDeviceCount(&device_count));
    printf("[transpose] Devices detected: %d\n", device_count);

    // Assign devices round-robin across ranks and threads
    std::vector<int> device_assignment(world_size * num_threads);
    for (int r = 0; r < world_size; ++r) {
        for (size_t t = 0; t < num_threads; ++t) {
            device_assignment[r * num_threads + t] = (r * num_threads + t) % device_count;
        }
    }

    int base_device_index = world_rank * num_threads;

    std::vector<std::thread> worker_threads;
    for (size_t t = 1; t < num_threads; ++t) {
        worker_threads.emplace_back(run_transpose_task,
                                    world_rank,
                                    static_cast<int>(t),
                                    device_assignment[base_device_index + t],
                                    num_iterations,
                                    sync_every_n);
    }

    // Run main thread task
    run_transpose_task(world_rank, 0, device_assignment[base_device_index],
                       num_iterations, sync_every_n);

    // Join all worker threads
    for (auto& th : worker_threads) {
        th.join();
    }

#if defined(USE_MPI)
    MPI_Barrier(MPI_COMM_WORLD);
#endif

    roctxRangeStop();
}

