// Perform a query and return the result
int makeQuery(const vector<int>& queryElements) {
    cout << "?";
    for (int val : queryElements) {
        cout << " " << val;
    }
    cout << endl;

    int response;
    cin >> response;
    if (response == -1) {
        exit(0);
    }
    return response;
}

// Main solver function
void determinePermutation() {
    int size;
    cin >> size;

    // Output k value
    cout << "1" << endl;

    // Arrays to store our permutation and inverse mapping
    vector<int> permutation(size + 1, 0);
    vector<int> inverseMap(size + 1, 0);

    // Process positions starting from index 2
    for (int pos = 2; pos <= size; ++pos) {
        // Create list of candidates excluding current position
        vector<int> options;
        for (int i = 1; i <= size; ++i) {
            if (i != pos) {
                options.push_back(i);
            }
        }

        // Binary search approach to find permutation value at this position
        while (!options.empty()) {
            if (options.size() == 1) {
                permutation[pos] = options[0];
                break;
            }

            // Split candidates into two groups
            int midPoint = options.size() / 2;
            vector<int> firstHalf, secondHalf;

            for (int i = 0; i < midPoint; ++i) {
                firstHalf.push_back(options[i]);
            }
            for (int i = midPoint; i < options.size(); ++i) {
                secondHalf.push_back(options[i]);
            }

            // Construct base query: [pos, 1, firstHalf, secondHalf]
            vector<int> baseQuery;
            baseQuery.push_back(pos);
            baseQuery.push_back(1);
            for (int val : firstHalf) baseQuery.push_back(val);
            for (int val : secondHalf) baseQuery.push_back(val);

            // Construct test query: [1, firstHalf, pos, secondHalf]
            vector<int> testQuery;
            testQuery.push_back(1);
            for (int val : firstHalf) testQuery.push_back(val);
            testQuery.push_back(pos);
            for (int val : secondHalf) testQuery.push_back(val);

            // Get responses from both queries
            int baseResult = makeQuery(baseQuery);
            int testResult = makeQuery(testQuery);
            int difference = testResult - baseResult;

            // Determine which half contains the target based on difference
            bool foundInFirstHalf = false;

            // Check if we have prior knowledge about the position
            if (inverseMap[pos] != 0 && inverseMap[pos] != 1) {
                // We know where the element should be
                bool knownInFirst = false;
                for (int val : firstHalf) {
                    if (val == inverseMap[pos]) {
                        knownInFirst = true;
                        break;
                    }
                }

                if (knownInFirst) {
                    foundInFirstHalf = (difference == 0);
                } else {
                    foundInFirstHalf = (difference == 1);
                }
            } else {
                // No prior knowledge, use default interpretation
                if (difference == 0 || difference == -1) {
                    foundInFirstHalf = true;
                }
            }

            // Update candidate list based on findings
            if (foundInFirstHalf) {
                options = firstHalf;
            } else {
                options = secondHalf;
            }
        }

        // Update inverse mapping
        if (permutation[pos] != 0) {
            inverseMap[permutation[pos]] = pos;
        }
    }

    // Find the missing value for position 1
    set<int> usedValues;
    for (int i = 2; i <= size; ++i) {
        if (permutation[i] != 0) {
            usedValues.insert(permutation[i]);
        }
    }

    for (int i = 1; i <= size; ++i) {
        if (usedValues.find(i) == usedValues.end()) {
            permutation[1] = i;
            break;
        }
    }

    // Output final permutation
    cout << "!";
    for (int i = 1; i <= size; ++i) {
        cout << " " << permutation[i];
    }
    cout << endl;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int testCases;
    if (cin >> testCases) {
        while (testCases--) {
            determinePermutation();
        }
    }

    return 0;
}

