// Test counters
static int total_tests = 0;
static int successful_tests = 0;

// Macro to check condition and print result
#define VERIFY(expr, description) do { \
    ++total_tests; \
    if (expr) { \
        ++successful_tests; \
        printf("  [OK] %s\n", description); \
    } else { \
        printf("  [ERROR] %s\n", description); \
