// Convert hex string to byte array
static void parse_hex_to_bytes(const char* hex_input, uint8_t* output_buffer, size_t buffer_size) {
    for (size_t idx = 0; idx < buffer_size; ++idx) {
        unsigned int temp_byte = 0;
#ifdef __clang__
#pragma clang diagnostic push
#pragma clang diagnostic ignored "-Wdeprecated-declarations"
#endif
        // NOLINTNEXTLINE(cert-err34-c) -- parsing 2-digit hex, overflow impossible
        if (sscanf(hex_input + idx * 2, "%02x", &temp_byte) != 1) temp_byte = 0;
#ifdef __clang__
#pragma clang diagnostic pop
#endif
        output_buffer[idx] = static_cast<uint8_t>(temp_byte);
    }
}

// HMAC-SHA512 test based on RFC 4231 Test Case 2
static void run_hmac_sha512_verification() {
    printf("\n--- HMAC-SHA512 Verification ---\n");

    const char* secret_text = "Jefe";
    const char* message_text = "what do ya want for nothing?";

    auto computed_result = hmac_sha512(
        reinterpret_cast<const uint8_t*>(secret_text), 4,
        reinterpret_cast<const uint8_t*>(message_text), 28
    );

    uint8_t reference_vector[64];
    parse_hex_to_bytes(
        "164b7a7bfcf819e2e395fbe73b56e0a387bd64222e831fd610270cd7ea250554"
        "9758bf75c05a994a6d034f65f8f0e6fdcaeab1a34d4a6b4b636e070a38bce737",
        reference_vector, 64
    );

    VERIFY(std::memcmp(computed_result.data(), reference_vector, 64) == 0,
           "RFC 4231 HMAC-SHA512 TC2 vector matches");
}

// BIP-32 master key generation test
static void run_master_key_generation_test() {
    printf("\n--- BIP-32 Master Key Generation ---\n");

    uint8_t entropy_seed[16];
    parse_hex_to_bytes("000102030405060708090a0b0c0d0e0f", entropy_seed, 16);

    auto [generated_master, success_flag] = bip32_master_key(entropy_seed, 16);

    VERIFY(success_flag, "Master key creation succeeded");
    VERIFY(generated_master.is_private, "Generated key is private");
    VERIFY(generated_master.depth == 0, "Master key depth is zero");

    // Expected chain code from BIP-32 Test Vector 1
    uint8_t expected_chain_code[32];
    parse_hex_to_bytes("873dff81c02f525623fd1fe5167eac3a55a049de3d314bb42ee227ffed37d508",
                       expected_chain_code, 32);
    VERIFY(std::memcmp(generated_master.chain_code.data(), expected_chain_code, 32) == 0,
           "Master chain code matches BIP-32 TV1");

    // Expected master private key
    uint8_t expected_private_key[32];
    parse_hex_to_bytes("e8f32e723decf4051aefac8e2c93c9c5b214313817cdb01a1494b917c8436b35",
                       expected_private_key, 32);
    VERIFY(std::memcmp(generated_master.key.data(), expected_private_key, 32) == 0,
           "Master private key matches BIP-32 TV1");
}

// Child key derivation test
static void run_child_key_derivation_test() {
    printf("\n--- BIP-32 Child Key Derivation ---\n");

    uint8_t seed_data[16];
    parse_hex_to_bytes("000102030405060708090a0b0c0d0e0f", seed_data, 16);

    auto [root_key, root_ok] = bip32_master_key(seed_data, 16);
    VERIFY(root_ok, "Root key ready for derivation");

    // Derive m/0' (hardened)
    auto [child_hardened, hardened_ok] = root_key.derive_hardened(0);
    VERIFY(hardened_ok, "Hardened derivation m/0' succeeded");
    VERIFY(child_hardened.depth == 1, "Child depth after m/0' is 1");
    VERIFY(child_hardened.is_private, "m/0' remains private");

    // Verify chain code against BIP-32 TV1
    uint8_t expected_cc[32];
    parse_hex_to_bytes("47fdacbd0f1097043b78c63c20c34ef4ed9a111d980047ad16282c7ae6236141",
                       expected_cc, 32);
    VERIFY(std::memcmp(child_hardened.chain_code.data(), expected_cc, 32) == 0,
           "m/0' chain code matches BIP-32 TV1");

    // Public key conversion and normal derivation
    auto public_version = child_hardened.to_public();
    VERIFY(!public_version.is_private, "to_public() correctly returns public key");

    auto [child_normal, normal_ok] = child_hardened.derive_normal(1);
    VERIFY(normal_ok, "Normal derivation m/0'/1 succeeded");
    VERIFY(child_normal.depth == 2, "m/0'/1 depth is 2");
}

// Path-based derivation test
static void run_path_based_derivation_test() {
    printf("\n--- BIP-32 Path Derivation ---\n");

    uint8_t initial_seed[16];
    parse_hex_to_bytes("000102030405060708090a0b0c0d0e0f", initial_seed, 16);

    auto [root_node, root_valid] = bip32_master_key(initial_seed, 16);
    VERIFY(root_valid, "Root node initialized for path tests");

    // Derive m/0'/1
    auto [intermediate_key, path_ok] = bip32_derive_path(root_node, "m/0'/1");
    VERIFY(path_ok, "Path m/0'/1 derived successfully");
    VERIFY(intermediate_key.depth == 2, "Path m/0'/1 depth equals 2");

    // Derive deeper path m/0'/1/2'
    auto [deep_key, deep_ok] = bip32_derive_path(root_node, "m/0'/1/2'");
    VERIFY(deep_ok, "Path m/0'/1/2' derived successfully");
    VERIFY(deep_key.depth == 3, "Path m/0'/1/2' depth equals 3");

    // Invalid path checks
    auto [_, invalid_empty] = bip32_derive_path(root_node, "");
    (void)_;
    VERIFY(!invalid_empty, "Empty path correctly rejected");

    auto [_2, invalid_prefix] = bip32_derive_path(root_node, "x/0");
    (void)_2;
    VERIFY(!invalid_prefix, "Path not starting with 'm' correctly rejected");
}

// Serialization test
static void run_serialization_test() {
    printf("\n--- BIP-32 Serialization ---\n");

    uint8_t seed_bytes[16];
    parse_hex_to_bytes("000102030405060708090a0b0c0d0e0f", seed_bytes, 16);

    auto [master_key, valid_init] = bip32_master_key(seed_bytes, 16);
    (void)valid_init;

    auto serialized_output = master_key.serialize();
    VERIFY(serialized_output.size() == 78, "Serialized key length is 78 bytes");

    // Check version bytes for xprv (0x0488ADE4)
    VERIFY(serialized_output[0] == 0x04 &&
           serialized_output[1] == 0x88 &&
           serialized_output[2] == 0xAD &&
           serialized_output[3] == 0xE4,
           "Serialized version matches xprv");

    // Depth field
    VERIFY(serialized_output[4] == 0, "Serialized depth is 0");

    // Fingerprint verification
    auto fingerprint_value = master_key.fingerprint();
    (void)fingerprint_value;
    VERIFY(fingerprint_value.size() == 4, "Fingerprint size is 4 bytes");
}

// Seed validation test
static void run_seed_validation_test() {
    printf("\n--- BIP-32 Seed Validation ---\n");

    // Short seed (8 bytes)
    uint8_t short_seed[8] = {1,2,3,4,5,6,7,8};
    auto [_, short_valid] = bip32_master_key(short_seed, 8);
    (void)_;
    VERIFY(!short_valid, "Seed shorter than 16 bytes rejected");

    // Valid 16-byte seed
    uint8_t sixteen_byte_seed[16];
    for (int i = 0; i < 16; ++i) sixteen_byte_seed[i] = static_cast<uint8_t>(i + 1);
    auto [key_16, valid_16] = bip32_master_key(sixteen_byte_seed, 16);
    (void)key_16;
    VERIFY(valid_16, "16-byte seed accepted");

    // Valid 64-byte seed
    uint8_t sixty_four_byte_seed[64];
    for (int i = 0; i < 64; ++i) sixty_four_byte_seed[i] = static_cast<uint8_t>(i + 1);
    auto [key_64, valid_64] = bip32_master_key(sixty_four_byte_seed, 64);
    (void)key_64;
    VERIFY(valid_64, "64-byte seed accepted");
}

// Main test runner
int test_bip32_run() {
    printf("=== HD Wallet (BIP-32) Test Suite ===\n");

    run_hmac_sha512_verification();
    run_master_key_generation_test();
    run_child_key_derivation_test();
    run_path_based_derivation_test();
    run_serialization_test();
    run_seed_validation_test();

    printf("\n=== Summary: %d/%d tests passed ===\n", successful_tests, total_tests);
    return (successful_tests == total_tests) ? 0 : 1;
}

#include <iostream>
