using namespace std;

int main() {
    vector<int> v = {1, 2, 3, 4, 5}; // vector of integers

    // Determine the larger and smaller of the first two elements
    int first = v[0];
    int second = v[1];
    int maxVal = (first > second) ? first : second;
    int minVal = (first < second) ? first : second;
    cout << maxVal << endl;
    cout << minVal << endl;

    // Swap the first two elements manually
    int temp = v[0];
    v[0] = v[1];
    v[1] = temp;

    cout << "After swapping: ";
    for(int i : v) {
        cout << i << " ";
    }
    cout << endl;

    // Find maximum and minimum elements using manual iteration
    int maxElement = v[0];
    int minElement = v[0];
    for (size_t i = 1; i < v.size(); ++i) {
        if (v[i] > maxElement) maxElement = v[i];
        if (v[i] < minElement) minElement = v[i];
    }
    cout << maxElement << endl;
    cout << minElement << endl;

    // Check if 6 exists in the vector using linear search
    bool found = false;
    for (int x : v) {
        if (x == 6) {
            found = true;
            break;
        }
    }
    cout << (found ? 1 : 0) << endl;

    // Count set bits using manual bit-counting method
    int n = 5;
    long int n2 = 5;
    long long n1 = 5;

    // Function to count set bits manually
    auto countBits = [](unsigned long long num) -> int {
        int count = 0;
        while (num > 0) {
            count += (num & 1);
            num >>= 1;
        }
        return count;
    };

    cout << countBits(n) << endl;
    cout << countBits(n2) << endl;
    cout << countBits(n1) << endl;

    return 0;
}

#include "pypangoio.h"

namespace py_pangolin
{
    // Constructor: initializes the queue and line type for the IO handler
    PyPangoIO::PyPangoIO(std::queue<InterpreterLine>& line_queue, InterpreterLineType line_type)
        : line_queue(line_queue), line_type(line_type)
    {
    }

    // Write method: accumulates text into a buffer and processes complete lines
    void PyPangoIO::write(const std::string& input_text)
    {
        buffer += input_text;

        size_t newline_pos = buffer.find('\n');
        while (newline_pos != std::string::npos) {
            // Extract the line up to the newline
            std::string complete_line = buffer.substr(0, newline_pos);

            // Push the completed line to the queue with its type
            line_queue.emplace(complete_line, line_type);

            // Remove the processed line from the buffer
            buffer = buffer.substr(newline_pos + 1);

            // Look for next newline in remaining buffer
            newline_pos = buffer.find('\n');
        }
    }

    // Flush method: no-op implementation as per original design
    void PyPangoIO::flush()
    {
        // Intentionally left empty — buffering handles line completion automatically
    }

    // Bind the PyPangoIO class to Python using pybind11
    void bind_pango_write_object(pybind11::module& module_handle)
    {
        pybind11::class_<PyPangoIO>(module_handle, "PyPangoIO")
            .def("write", &PyPangoIO::write)
            .def("flush", &PyPangoIO::flush);
    }
}

