class AdvanceSearchTableViewTest : public PlainTestSuite {
  Q_OBJECT
public:
private slots:
  void test_1() {
    // Prepare test data: list of file/folder entries
    QList<FsNodeEntry> testEntries{
        {"files 1.txt", false, "henry cavill superman"},
        {"files 2.txt", true, "Henry Cavill SUPERMAN"},
        {"folder", true, ""},
    };

    TDir tempDir;
    QCOMPARE(tempDir.createEntries(testEntries), static_cast<int>(testEntries.size()));
    QString rootPath = tempDir.path();
    QVERIFY(QFileInfo(rootPath).isDir());

    // Setup models
    AdvanceSearchModel sourceModel;
    sourceModel.initFilter(QDir::Filter::Dirs | QDir::Filter::Files | QDir::Filter::NoDotAndDotDot);
    sourceModel.initIteratorFlag(QDirIterator::IteratorFlag::Subdirectories);
    sourceModel.setRootPath(rootPath);

    SearchProxyModel proxyModel;
    proxyModel.initSearchMode(SearchTools::SearchModeE::NORMAL);
    proxyModel.initNameFilterDisables(false);  // hide non-matching items
    proxyModel.initFileNameFiltersCaseSensitive(Qt::CaseSensitivity::CaseInsensitive);
    proxyModel.initFileContentsCaseSensitive(Qt::CaseSensitivity::CaseInsensitive);

    AdvanceSearchTableView view{&sourceModel, &proxyModel};

    // Apply filter for "files" and "HENRY"
    proxyModel.startFilterWhenTextChanged("files", "HENRY");
    QCOMPARE(proxyModel.rowCount(), 2); // expect two matching rows

    // Test copy/cut selection handling
    {
      view.selectAll();
      QModelIndexList selectedNames = view.selectionModel()->selectedRows(0);
      QCOMPARE(selectedNames.size(), 2);

      auto mimeData = MimeDataHelper::GetMimeDataMemberFromSearchModel(sourceModel, proxyModel, selectedNames);
      QCOMPARE(mimeData.texts.size(), 2);
      QCOMPARE(mimeData.urls.size(), 2);
      QCOMPARE(mimeData.srcIndexes.size(), 2);

      QString expectedPaths = mimeData.texts.join('\n');
      QCOMPARE(expectedPaths.count("files 1.txt"), 1);
      QCOMPARE(expectedPaths.count("files 2.txt"), 1);
      QCOMPARE(expectedPaths.count('\n'), 1);

      // Simulate cut operation
      bool cutOk = MimeDataHelper::FillCutCopySomething<AdvanceSearchModel>(
          sourceModel, mimeData.srcIndexes, Qt::DropAction::MoveAction);
      QVERIFY(cutOk);
      QVERIFY(!sourceModel.mCutIndexes.isEmpty());
      QVERIFY(sourceModel.mCopyIndexes.isEmpty());

      // Simulate copy operation
      bool copyOk = MimeDataHelper::FillCutCopySomething<AdvanceSearchModel>(
          sourceModel, mimeData.srcIndexes, Qt::DropAction::CopyAction);
      QVERIFY(copyOk);
      QVERIFY(sourceModel.mCutIndexes.isEmpty());
      QVERIFY(!sourceModel.mCopyIndexes.isEmpty());

      // Try unsupported action (LinkAction)
      bool linkOk = MimeDataHelper::FillCutCopySomething<AdvanceSearchModel>(
          sourceModel, mimeData.srcIndexes, Qt::DropAction::LinkAction);
      QVERIFY(!linkOk);
      QVERIFY(sourceModel.mCutIndexes.isEmpty());
      QVERIFY(!sourceModel.mCopyIndexes.isEmpty()); // unchanged
    }

    // Test deletion behavior
    QSignalSpy trashSignalSpy(FileOpActs::GetInst().MOVE_TO_TRASHBIN,
                              &QAction::triggered);

    // First: no selection → no signal
    view.clearSelection();
    QKeyEvent deletePress{QEvent::KeyPress, Qt::Key_Delete, Qt::NoModifier, QString{}, false, 1};
    view.keyPressEvent(&deletePress);
    QCOMPARE(trashSignalSpy.count(), 0);

    // Second: select all → trigger deletion
    view.selectAll();
    view.keyPressEvent(&deletePress);
    QCOMPARE(trashSignalSpy.count(), 1);
  }
};

