struct NullMutex
{
  void lock() {}
  void unlock() {}
};

struct CounterMutex
{
  void lock() { ++lockCount_; }
  void unlock() { ++unlockCount_; }
  [[nodiscard]] int getLockCount() const { return lockCount_; }
  [[nodiscard]] int getUnlockCount() const { return unlockCount_; }

private:
  mutable int lockCount_ {0};
  mutable int unlockCount_ {0};
};

TEST(LockedRangeAdapter, createAndIterateNonConstContainerVector)
{
  std::vector<int> buffer {1, 2, 3, 4, 5, 6};
  NullMutex mtx;
  int result {0};
  auto lockedRange = makeLockedRange<std::lock_guard>(buffer, mtx);
  for (auto it = lockedRange.begin(); it != lockedRange.end(); ++it) {
    result += *it;
  }
  int expected = std::accumulate(buffer.begin(), buffer.end(), 0);
  EXPECT_EQ(result, expected);
}

