TEST(LockedRangeAdapter, stdMutexNonConstContainerVector)
{
  std::vector<int> buffer {1, 2, 3, 4, 5, 6};
  const size_t initialSum = std::accumulate(buffer.begin(), buffer.end(), 0);
  const size_t expectedFinalSum = initialSum + 2 * buffer.size();
  std::mutex mtx;
  std::thread t1([&buffer, &mtx]() {
    auto lockedRange = makeLockedRange<std::lock_guard>(buffer, mtx);
    for (auto it = lockedRange.begin(); it != lockedRange.end(); ++it) {
      ++(*it);
    }
  });
  std::thread t2([&buffer, &mtx]() {
    auto lockedRange = makeLockedRange<std::lock_guard>(buffer, mtx);
    for (auto it = lockedRange.begin(); it != lockedRange.end(); ++it) {
      ++(*it);
    }
  });
  t1.join();
  t2.join();
  std::lock_guard<std::mutex> guard(mtx);
  EXPECT_EQ(expectedFinalSum, std::accumulate(buffer.begin(), buffer.end(), 0));
}

TEST(LockedRangeAdapter, stdSharedMutexNonConstContainerVector)
{
  std::vector<int> buffer {1, 2, 3, 4, 5, 6};
  std::shared_mutex mtx;
  int readerSum {0};
  int sumBeforeWrite = std::accumulate(buffer.begin(), buffer.end(), 0);
  std::thread writer([&buffer, &mtx]() {
    auto lockedRange = makeLockedRange<std::lock_guard>(buffer, mtx);
    for (auto it = lockedRange.begin(); it != lockedRange.end(); ++it) {
      ++(*it);
    }
  });
  std::thread reader([&buffer, &mtx, &readerSum]() {
    auto lockedRange = makeLockedRange<std::lock_guard>(buffer, mtx);
    for (auto it = lockedRange.begin(); it != lockedRange.end(); ++it) {
      readerSum += *it;
    }
  });
  writer.join();
  reader.join();
  std::lock_guard<std::shared_mutex> guard(mtx);
  int sumAfterWrite = std::accumulate(buffer.begin(), buffer.end(), 0);
  EXPECT_TRUE(readerSum == sumBeforeWrite || readerSum == sumAfterWrite);
}

