TEST(SmartPtrIteratorAdapter, checkAdaptedIteratorInterface)
{
  using ValueType = int;
  using ContainerType = std::unique_ptr<ValueType>;
  using VectorType = std::vector<ContainerType>;
  VectorType storage;
  auto adaptedBegin = SmartPtrIteratorAdapter(storage.begin());
  auto adaptedEnd = SmartPtrIteratorAdapter(storage.end());

  static_assert(std::is_same_v<decltype(*adaptedBegin), ValueType*>,
                "Dereferencing the adapted iterator should yield a ptr to the underlying type.");
  static_assert(std::is_same_v<decltype(adaptedBegin.operator->()), ValueType&>,
                "Member access operator of the adapted iterator should yield a ref to the underlying type.");

  EXPECT_TRUE(adaptedBegin == adaptedEnd);
  EXPECT_FALSE(adaptedBegin != adaptedEnd);
}

TEST(SmartPtrIteratorAdapter, runtimeUniquePtr)
{
  std::array<int, 9> sourceData {0, 1, 21, 42, 10, 420, 40, 82, 27};
  std::vector<std::unique_ptr<int>> container;
  container.reserve(sourceData.size());
  for (int val : sourceData) {
    container.push_back(std::make_unique<int>(val));
  }

  int runningTotal {0};
  auto beginIt = SmartPtrIteratorAdapter(container.begin());
  auto endIt = SmartPtrIteratorAdapter(container.end());
  for (auto it = beginIt; it != endIt; ++it) {
    runningTotal += **it;
  }

  int expected = std::accumulate(sourceData.begin(), sourceData.end(), 0);
  EXPECT_EQ(runningTotal, expected);
}

