#include "quadrants/system/traceback.h"
#include <vector>
#include <iostream>
#include <string>
#include <sstream>
#include <cstdio>
#include <algorithm>
#include <memory>
#include <mutex>
#include "spdlog/fmt/bundled/color.h"

#if defined(__APPLE__) || (defined(__unix__) && !defined(__linux__))
#include <execinfo.h>
#include <cxxabi.h>
#endif

#ifdef _WIN64
#include <intrin.h>
#include <dbghelp.h>
#include "quadrants/platform/windows/windows.h"
#pragma comment(lib, "dbghelp.lib")

namespace internal_trace {
    void log_debug(const char* format, ...) {
        char buffer[1024];
        va_list args;
        va_start(args, format);
        vsnprintf(buffer, sizeof(buffer), format, args);
        OutputDebugStringA(buffer);
        va_end(args);
    }

    std::string extract_filename(const std::string& path) {
        size_t pos = path.find_last_of("/\\");
        return (pos == std::string::npos) ? path : path.substr(pos + 1);
    }

    struct CallFrame {
        uint64_t addr;
        std::string func_name;
        std::string mod_name;
        unsigned int line_num;
        std::string src_file;
    };

    inline std::vector<CallFrame> capture_stack() {
        DWORD machine_type = 
#if defined(_WIN64)
            IMAGE_FILE_MACHINE_AMD64;
#else
            IMAGE_FILE_MACHINE_I386;
#endif

        HANDLE proc = GetCurrentProcess();
        HANDLE thr = GetCurrentThread();

        if (!SymInitialize(proc, nullptr, TRUE)) {
            log_debug("SymInitialize failed.\n");
            return {};
        }

        SymSetOptions(SYMOPT_LOAD_LINES);

        CONTEXT ctx{};
        ctx.ContextFlags = CONTEXT_FULL;
        RtlCaptureContext(&ctx);

        STACKFRAME frame{};
#if defined(_WIN64)
        frame.AddrPC.Offset = ctx.Rip;
        frame.AddrFrame.Offset = ctx.Rbp;
        frame.AddrStack.Offset = ctx.Rsp;
#else
        frame.AddrPC.Offset = ctx.Eip;
        frame.AddrFrame.Offset = ctx.Ebp;
        frame.AddrStack.Offset = ctx.Esp;
#endif
        frame.AddrPC.Mode = frame.AddrFrame.Mode = frame.AddrStack.Mode = AddrModeFlat;

        std::vector<CallFrame> result;
        bool first_entry = true;

        while (StackWalk(machine_type, proc, thr, &frame, &ctx, nullptr,
                         SymFunctionTableAccess, SymGetModuleBase, nullptr)) {
            CallFrame cf{};
            cf.addr = frame.AddrPC.Offset;

            DWORD64 base = 0;
#if defined(_WIN64)
            base = SymGetModuleBase(proc, frame.AddrPC.Offset);
#else
            DWORD base32 = static_cast<DWORD>(base);
            base = base32;
#endif

            char module_path[MAX_PATH] = {};
            if (base && GetModuleFileNameA(reinterpret_cast<HMODULE>(base), module_path, MAX_PATH)) {
                cf.mod_name = extract_filename(module_path);
            } else {
                cf.mod_name = "Unknown Module";
            }

            char sym_buf[sizeof(IMAGEHLP_SYMBOL) + 256]{};
            auto sym = reinterpret_cast<PIMAGEHLP_SYMBOL>(sym_buf);
            sym->SizeOfStruct = sizeof(IMAGEHLP_SYMBOL) + 256;
            sym->MaxNameLength = 255;

            DWORD64 offset = 0;
            if (SymGetSymFromAddr(proc, frame.AddrPC.Offset, &offset, sym)) {
                cf.func_name = sym->Name;
            } else {
                DWORD err = GetLastError();
                log_debug("Symbol resolution failed at 0x%llx: %lu\n", frame.AddrPC.Offset, err);
                cf.func_name = "Unknown Function";
            }

            IMAGEHLP_LINE ln{};
            ln.SizeOfStruct = sizeof(IMAGEHLP_LINE);
            DWORD line_offset = 0;
            if (SymGetLineFromAddr(proc, frame.AddrPC.Offset, &line_offset, &ln)) {
                cf.src_file = ln.FileName;
                cf.line_num = ln.LineNumber;
            } else {
                DWORD err = GetLastError();
                log_debug("Line info unavailable for 0x%llx: %lu\n", frame.AddrPC.Offset, err);
                cf.line_num = 0;
            }

            if (!first_entry) {
                result.push_back(cf);
            }
            first_entry = false;
        }

        SymCleanup(proc);
        return result;
    }
} // namespace internal_trace
#endif

