namespace quadrants {

void print_traceback() {
#ifdef __APPLE__
    static std::mutex trace_lock;
    void* stack[128]{};
    int count = backtrace(stack, 128);
    char** symbols = backtrace_symbols(stack, count);

    std::vector<std::string> frames;
    for (int i = 0; i < count; ++i) {
        char func[1024]{}, mod[1024]{}, addr[48]{};
        int off = 0;
        sscanf(symbols[i], "%*s %s %s %s %*s %d", mod, addr, func, &off);

        int status = -1;
        char* demangled = abi::__cxa_demangle(func, nullptr, 0, &status);
        char buf[4096]{};
        snprintf(buf, sizeof(buf), "* %28s | %7d | %s", mod, off, demangled ? demangled : func);
        frames.emplace_back(buf);
        if (demangled) free(demangled);
    }
    free(symbols);

    frames.erase(frames.begin());
    std::reverse(frames.begin(), frames.end());

    std::lock_guard<std::mutex> lock(trace_lock);
    printf("\n");
    printf(
        "                            * Quadrants Core - Stack Traceback *        "
        " "
        "  "
        "                  \n");
    printf(
        "========================================================================"
        "==================\n");
    printf(
        "|                       Module |  Offset | Function                     "
        "                 |\n");
    printf(
        "|-----------------------------------------------------------------------"
        "-----------------|\n");

    for (const auto& f : frames) {
        const size_t col_start = 39;
        const size_t total_width = 86;
        const size_t func_col_width = total_width - col_start - 2;
        size_t idx = 0;
        for (; idx < f.size(); ++idx) {
            putchar(f[idx]);
            if (idx > col_start + 3 && ((idx - 3 - col_start) % func_col_width == 0)) {
                printf(" |\n ");
                for (size_t k = 0; k < col_start; ++k) putchar(' ');
                printf(" | ");
            }
        }
        size_t padding = func_col_width + 2 - ((idx - 3 - col_start) % func_col_width);
        for (size_t p = 0; p < padding; ++p) putchar(' ');
        printf("|\n");
    }
    printf(
        "========================================================================"
        "==================\n");
    printf("\n");

#elif defined(_WIN64)
    fmt::print(fg(fmt::color::magenta), "***********************************\n");
    fmt::print(fg(fmt::color::magenta),
               "* Quadrants Compiler Stack Traceback *\n");
    fmt::print(fg(fmt::color::magenta), "***********************************\n");

    auto frames = internal_trace::capture_stack();
    for (const auto& fr : frames) {
        fmt::print(fg(fmt::color::magenta), fmt::format("0x{:x}: ", fr.addr));
        fmt::print(fg(fmt::color::red), fr.func_name);
        if (!fr.src_file.empty())
            fmt::print(fg(fmt::color::magenta),
                       fmt::format("(line {} in {})", fr.line_num, fr.src_file));
        fmt::print(fg(fmt::color::magenta), fmt::format(" in {}\n", fr.mod_name));
    }

#else
    constexpr int MAX_FRAMES = 1024;
    void* buffer[MAX_FRAMES]{};
    int num_frames = backtrace(buffer, MAX_FRAMES);
    char** str_list = backtrace_symbols(buffer, num_frames);
    if (!str_list) {
        perror("backtrace_symbols");
        std::exit(EXIT_FAILURE);
    }

    fmt::print(fg(fmt::color::magenta), "***********************************\n");
    fmt::print(fg(fmt::color::magenta),
               "* Quadrants Compiler Stack Traceback *\n");
    fmt::print(fg(fmt::color::magenta), "***********************************\n");

    for (int i = 1; i < num_frames; ++i) {
        std::string entry(str_list[i]);
        size_t lparen = entry.find('(');
        size_t plus_pos = entry.rfind('+');
        std::string processed_line;

        if (lparen != std::string::npos && plus_pos != std::string::npos &&
            lparen < plus_pos && entry[lparen + 1] != '+') {
            std::string raw_name = entry.substr(lparen + 1, plus_pos - lparen - 1);
            int status = -1;
            char* demangled = abi::__cxa_demangle(raw_name.c_str(), nullptr, nullptr, &status);
            if (demangled) {
                std::string prefix = entry.substr(0, lparen);
                processed_line = fmt::format("{}: {}", prefix, demangled);
                free(demangled);
            } else {
                processed_line = entry;
            }
        } else {
            processed_line = entry;
        }

        fmt::print(fg(fmt::color::magenta), "{}\n", processed_line);
    }
    std::free(str_list);
#endif

    fmt::print(
        fg(fmt::color::orange),
        "\nInternal error occurred. Check out this page for possible solutions:\n"
        "https://docs.taichi-lang.org/docs/install\n");
}

