// Helper function to compute optimal circle resolution based on radius and pixel size
int calculateCircleSegments(double radius, double pixelSize = 1.0) {
    if (radius <= 0) return 4;

    double angleStep;
    double ratio = pixelSize * 0.5 / radius;

    // Clamp ratio to valid range for acos
    if (fabs(1.0 - ratio) <= 1.0)
        angleStep = acos(1.0 - ratio);
    else
        angleStep = M_PI_4;  // Default to 45 degrees

    if (angleStep == 0.0) angleStep = M_PI_4;

    int segments = static_cast<int>(M_2PI / angleStep);
    return (segments > 0) ? segments : 4;
}
}

double tglGetPixelSize2() {
    double modelview[16];
    glMatrixMode(GL_MODELVIEW);
    glGetDoublev(GL_MODELVIEW_MATRIX, modelview);

    // Compute determinant of 2D transformation part
    double det = fabs(modelview[0] * modelview[5] - modelview[1] * modelview[4]);
    if (det < TConsts::epsilon) det = TConsts::epsilon;
    return 1.0 / det;
}

TRectD tglGetBounds() {
    TAffine4 modelviewMatrix;
    TAffine4 projectionMatrix;

    glGetDoublev(GL_MODELVIEW_MATRIX, modelviewMatrix.a);
    glGetDoublev(GL_PROJECTION_MATRIX, projectionMatrix.a);

    return (projectionMatrix * modelviewMatrix).get2d().inv() * TRectD(-1.0, -1.0, 1.0, 1.0);
}

double tglGetTextWidth(const std::string &text, void *font) {
