void tglDrawSegment(const TPointD &start, const TPointD &end) {
    glBegin(GL_LINES);
    tglVertex(start);
    tglVertex(end);
    glEnd();
}

void tglDrawCircle(const TPointD &center, double radius) {
    if (radius <= 0) return;

    double pixelSize = sqrt(tglGetPixelSize2());
    int segments = std::max(4, calculateCircleSegments(radius, pixelSize));
    double angleStep = M_2PI / static_cast<double>(segments);

    double cosStep = cos(angleStep);
    double sinStep = sin(angleStep);

    glPushMatrix();
    glTranslated(center.x, center.y, 0.0);

    glBegin(GL_LINE_STRIP);

    double x = radius;
    double y = 0.0;
    glVertex2d(x, y);

    for (int i = segments - 1; i > 0; --i) {
        double tempX = x;
        x = cosStep * tempX - sinStep * y;
        y = sinStep * tempX + cosStep * y;
        glVertex2d(x, y);
    }

    glVertex2d(radius, 0.0);
    glEnd();

    glPopMatrix();
}

void tglDrawDisk(const TPointD &center, double radius) {
    if (radius <= 0) return;

    int slices = 60;
    double pixelSize = 1.0;
    if (slices <= 0) {
        slices = calculateCircleSegments(radius, pixelSize) >> 1;
    }

    glPushMatrix();
    glTranslated(center.x, center.y, 0.0);

    GLUquadric *quadric = gluNewQuadric();
    gluDisk(quadric, 0.0, radius, slices, 1);
    gluDeleteQuadric(quadric);

    glPopMatrix();
}

