void tglRgbOnlyColorMask() {
    tglMultColorMask(GL_TRUE, GL_TRUE, GL_TRUE, GL_FALSE);
    tglEnableBlending(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA);
}

void tglAlphaOnlyColorMask() {
    tglMultColorMask(GL_FALSE, GL_FALSE, GL_FALSE, GL_TRUE);
    tglEnableBlending(GL_ONE, GL_ONE_MINUS_SRC_ALPHA);
}

void tglEnableBlending(GLenum srcFactor, GLenum dstFactor) {
    glEnable(GL_BLEND);
    glBlendFunc(srcFactor, dstFactor);
}

void tglEnableLineSmooth(bool enable, double lineWidth) {
    if (enable) {
        glHint(GL_LINE_SMOOTH_HINT, GL_NICEST);
        glEnable(GL_LINE_SMOOTH);
        glLineWidth(lineWidth);
    } else {
        glDisable(GL_LINE_SMOOTH);
    }
}

void tglEnablePointSmooth(double pointSize) {
    glEnable(GL_BLEND);
    glEnable(GL_POINT_SMOOTH);
    glHint(GL_POINT_SMOOTH_HINT, GL_NICEST);
    glPointSize(pointSize);
}

void tglGetColorMask(GLboolean &red, GLboolean &green, GLboolean &blue, GLboolean &alpha) {
    GLboolean channels[4];
    glGetBooleanv(GL_COLOR_WRITEMASK, &channels[0]);
    red = channels[0];
    green = channels[1];
    blue = channels[2];
    alpha = channels[3];
}

void tglMultColorMask(GLboolean red, GLboolean green, GLboolean blue, GLboolean alpha) {
    GLboolean currentMask[4];
    glGetBooleanv(GL_COLOR_WRITEMASK, &currentMask[0]);

    glColorMask(
        red && currentMask[0],
        green && currentMask[1],
        blue && currentMask[2],
        alpha && currentMask[3]
    );
}

class GlFontManager {
    GlFontManager();
public:
    ~GlFontManager();
    static GlFontManager *getInstance();
    bool setFont(void *font = GLUT_BITMAP_TIMES_ROMAN_10);
    void drawText(std::wstring wtext);
private:
    static GlFontManager *m_instance;

    std::map<void *, double> m_fonts;
    void *m_currentFont;
    GLuint m_displayListBase;
};

GlFontManager *GlFontManager::m_instance = nullptr;

GlFontManager::GlFontManager() : m_currentFont(nullptr), m_displayListBase(0) {
    m_fonts.insert(std::make_pair(GLUT_BITMAP_8_BY_13, 13.0));
    m_fonts.insert(std::make_pair(GLUT_BITMAP_9_BY_15, 15.0));
    m_fonts.insert(std::make_pair(GLUT_BITMAP_TIMES_ROMAN_10, 10.0));
    m_fonts.insert(std::make_pair(GLUT_BITMAP_TIMES_ROMAN_24, 24.0));
    m_fonts.insert(std::make_pair(GLUT_BITMAP_HELVETICA_10, 10.0));
    m_fonts.insert(std::make_pair(GLUT_BITMAP_HELVETICA_12, 12.0));
    m_fonts.insert(std::make_pair(GLUT_BITMAP_HELVETICA_18, 18.0));

    bool success = setFont();
    assert(success);
}

GlFontManager::~GlFontManager() { 
    m_instance = nullptr; 
}

GlFontManager *GlFontManager::getInstance() {
    if (!m_instance) m_instance = new GlFontManager();
    return m_instance;
}

bool GlFontManager::setFont(void *font) {
    auto it = m_fonts.find(font);
    if (it != m_fonts.end()) {
        m_currentFont = font;

        glPushAttrib(GL_ALL_ATTRIB_BITS);
        glPushMatrix();

        m_displayListBase = glGenLists(256);
        glListBase(m_displayListBase);

        for (int i = 0; i < 256; ++i) {
            glNewList(m_displayListBase + i, GL_COMPILE);
            glutStrokeCharacter(GLUT_STROKE_ROMAN, i);
            glEndList();
        }

        glPopAttrib();
        glPopMatrix();
        return true;
    }
    return false;
}

void GlFontManager::drawText(std::wstring wtext) {
    if (!m_currentFont) return;

    std::string text = ::to_string(wtext);
    const char *textData = text.c_str();

    glListBase(m_displayListBase);
    glCallLists(static_cast<GLuint>(strlen(textData)), GL_BYTE, textData);
}

void tglDraw(const TCubic &cubic, int precision, GLenum mode) {
    CHECK_ERRORS_BY_GL;
    assert(mode == GL_POINT || mode == GL_LINE);

    float controlPoints[4][3] = {
        {cubic.getP0().x, cubic.getP0().y, 0.0f},
        {cubic.getP1().x, cubic.getP1().y, 0.0f},
        {cubic.getP2().x, cubic.getP2().y, 0.0f},
        {cubic.getP3().x, cubic.getP3().y, 0.0f}
    };

    CHECK_ERRORS_BY_GL;
    glMap1f(GL_MAP1_VERTEX_3, 0.0, 1.0, 3, 4, &controlPoints[0][0]);
    CHECK_ERRORS_BY_GL;
    glEnable(GL_MAP1_VERTEX_3);
    CHECK_ERRORS_BY_GL;
    glMapGrid1f(precision, 0.0, 1.0);
    CHECK_ERRORS_BY_GL;
    glEvalMesh1(mode, 0, precision);
    CHECK_ERRORS_BY_GL;
}

void tglDraw(const TRectD &rect, const std::vector<TRaster32P> &textures, bool blending) {
    double pixelSize2 = tglGetPixelSize2();

    unsigned int level = 1;
    while (pixelSize2 * level * level <= 1.0) level <<= 1;

    unsigned int textureCount = static_cast<unsigned int>(textures.size());
    if (level > textureCount) level = textureCount;
    level = textureCount - level;

    tglDraw(rect, textures[level], blending);
}

void tglDraw(const TRectD &rect, const TRaster32P &texture, bool blending) {
    CHECK_ERRORS_BY_GL;
    glPushAttrib(GL_ALL_ATTRIB_BITS);

    if (blending) {
        glEnable(GL_BLEND);
        glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA);
    }

    unsigned int texWidth = 1;
    unsigned int texHeight = 1;
    unsigned int originalWidth = static_cast<unsigned int>(texture->getLx());
    unsigned int originalHeight = static_cast<unsigned int>(texture->getLy());

    while (texWidth < originalWidth) texWidth <<= 1;
    while (texHeight < originalHeight) texHeight <<= 1;

    double widthRatio = 1.0;
    double heightRatio = 1.0;

    TRaster32P paddedTexture;
    if (texWidth != originalWidth || texHeight != originalHeight) {
        paddedTexture = TRaster32P(texWidth, texHeight);
        paddedTexture->fill(TPixel32(0, 0, 0, 0));
        paddedTexture->copy(texture);
        widthRatio = static_cast<double>(originalWidth) / static_cast<double>(texWidth);
        heightRatio = static_cast<double>(originalHeight) / static_cast<double>(texHeight);

        if (widthRatio > 1.0) widthRatio = 1.0;
        if (heightRatio > 1.0) heightRatio = 1.0;
    } else {
        paddedTexture = texture;
    }

    GLenum format =
#if defined(TNZ_MACHINE_CHANNEL_ORDER_BGRM)
        GL_BGRA_EXT;
#elif defined(TNZ_MACHINE_CHANNEL_ORDER_MBGR)
        GL_ABGR_EXT;
#elif defined(TNZ_MACHINE_CHANNEL_ORDER_RGBM)
        GL_RGBA;
#elif defined(TNZ_MACHINE_CHANNEL_ORDER_MRGB)
        GL_BGRA;
#else
#error "unknown channel order!"
#endif

    GLuint textureId;
    glGenTextures(1, &textureId);
    glBindTexture(GL_TEXTURE_2D, textureId);

    glPixelStorei(GL_UNPACK_ROW_LENGTH, paddedTexture->getWrap());
    paddedTexture.lock();

    glTexImage2D(GL_TEXTURE_2D, 0, 4, texWidth, texHeight, 0, format,
#ifdef TNZ_MACHINE_CHANNEL_ORDER_MRGB
                 GL_UNSIGNED_INT_8_8_8_8_REV,
#else
                 GL_UNSIGNED_BYTE,
#endif
                 paddedTexture->getRawData());

    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_CLAMP);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_CLAMP);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_LINEAR);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_LINEAR);
    glTexEnvf(GL_TEXTURE_ENV, GL_TEXTURE_ENV_MODE, GL_REPLACE);

    glEnable(GL_TEXTURE_2D);
    glHint(GL_PERSPECTIVE_CORRECTION_HINT, GL_NICEST);

    double rectWidth = rect.getLx();
    double rectHeight = rect.getLy();

    tglColor(TPixel32(0, 0, 0, 0));

    glPushMatrix();
    glTranslated(rect.x0, rect.y0, 0.0);

    glBegin(GL_POLYGON);
    glTexCoord2d(0, 0); tglVertex(TPointD(0.0, 0.0));
    glTexCoord2d(widthRatio, 0); tglVertex(TPointD(rectWidth, 0.0));
    glTexCoord2d(widthRatio, heightRatio); tglVertex(TPointD(rectWidth, rectHeight));
    glTexCoord2d(0, heightRatio); tglVertex(TPointD(0.0, rectHeight));
    glEnd();

    glDisable(GL_TEXTURE_2D);
    glPopMatrix();

    glPopAttrib();
    glDeleteTextures(1, &textureId);
    paddedTexture.unlock();
}

void tglBuildMipmaps(std::vector<TRaster32P> &rasters, const TFilePath &filepath) {
    assert(rasters.size() > 0);

    TRop::ResampleFilterType resampleFilter = TRop::ClosestPixel;
    TRasterP sourceRaster;
    TImageReader::load(filepath, sourceRaster);

    int sourceWidth = sourceRaster->getLx();
    int sourceHeight = sourceRaster->getLy();

    int targetWidth = 1;
    int targetHeight = 1;

    while (targetWidth < sourceWidth) targetWidth <<= 1;
    while (targetHeight < sourceHeight) targetHeight <<= 1;

    TRaster32P resizedRaster(targetWidth, targetHeight);

    double scaleX = static_cast<double>(targetWidth) / static_cast<double>(sourceWidth);
    double scaleY = static_cast<double>(targetHeight) / static_cast<double>(sourceHeight);

#ifndef SCALE_BY_GLU
    TRop::resample(resizedRaster, sourceRaster, TScale(scaleX, scaleY), resampleFilter);
#else
    sourceRaster.lock();
    gluScaleImage(GL_RGBA, sourceWidth, sourceHeight, GL_UNSIGNED_BYTE,
                  sourceRaster.getRawData(), targetWidth, targetHeight, GL_UNSIGNED_BYTE,
                  resizedRaster.getRawData());
    sourceRaster.unlock();
#endif

    rasters[0] = resizedRaster;

    int currentWidth = resizedRaster->getLx();
    int currentHeight = resizedRaster->getLy();

    for (int i = 1; i < static_cast<int>(rasters.size()); ++i) {
        targetWidth >>= 1;
        targetHeight >>= 1;

        if (targetWidth < 1) targetWidth = 1;
        if (targetHeight < 1) targetHeight = 1;

        rasters[i] = TRaster32P(targetWidth, targetHeight);

        scaleX = static_cast<double>(targetWidth) / static_cast<double>(currentWidth);
        scaleY = static_cast<double>(targetHeight) / static_cast<double>(currentHeight);

#ifndef SCALE_BY_GLU
        TRop::resample(rasters[i], resizedRaster, TScale(scaleX, scaleY), resampleFilter);
#else
        resizedRaster.lock();
        gluScaleImage(GL_RGBA, currentWidth, currentHeight, GL_UNSIGNED_BYTE,
                      resizedRaster.getRawData(), targetWidth, targetHeight, GL_UNSIGNED_BYTE,
                      rasters[i]->getRawData());
        resizedRaster.unlock();
#endif
    }
}

