#include <iostream>
#include <sstream>
#include <string>
#include <vector>
using namespace std;

int main() {
    int test_cases;
    cin >> test_cases;

    for (int case_num = 0; case_num < test_cases; ++case_num) {
        int nodes, edges, initial_node, moves_base;
        cin >> nodes >> edges >> initial_node >> moves_base;

        // Skip edge information
        for (int i = 0; i < edges; ++i) {
            int u, v;
            cin >> u >> v;
        }

        // Clear the newline buffer
        cin.ignore();

        bool finished = false;
        while (!finished) {
            string input_line;
            getline(cin, input_line);

            if (input_line.empty()) {
                continue;
            }

            // Check for termination commands
            if (input_line[0] == 'A' || input_line[0] == 'F') {
                finished = true;
                continue;
            }

            // Parse the current move instruction
            istringstream parser(input_line);
            int neighbor_count;
            parser >> neighbor_count;

            vector<int> neighbors(neighbor_count);
            vector<int> visited_flags(neighbor_count);

            for (int i = 0; i < neighbor_count; ++i) {
                parser >> neighbors[i] >> visited_flags[i];
            }

            // Determine next move: prefer unvisited neighbor first
            int selected_move = 1;  // Default to first option

            for (int idx = 0; idx < neighbor_count; ++idx) {
                if (visited_flags[idx] == 0) {
                    selected_move = idx + 1;
                    break;
                }
            }

            cout << selected_move << endl;
            cout.flush();
        }
    }

    return 0;
}

