#include <SDL3/SDL.h>
#include "SerialDevice.hpp"

// Thread entry point for serial device communication
int SDLCALL SerialDeviceThreadEntry(void *userData) {
    SerialDevice *instance = static_cast<SerialDevice*>(userData);
    instance->run_communication_loop();
    return 0;
}

SerialDevice::SerialDevice(const char *deviceName, const char *portIdentifier) {
    this->device_name = deviceName ? deviceName : "SerialDevice";
    this->port_identifier = portIdentifier ? portIdentifier : "UNK";

    // Launch the worker thread
    this->worker_thread = SDL_CreateThread(SerialDeviceThreadEntry, deviceName, this);
}

SerialDevice::~SerialDevice() {
    // Ensure cleanup only if not already handled by subclass
    if (worker_thread) {
        SDL_Log("SerialDevice: %s terminating", device_name);

        // Send shutdown signal to the device loop
        SerialMessage shutdown_msg = {MESSAGE_SHUTDOWN, 0};
        message_queue.send(shutdown_msg);

        // Wait for thread completion and release resources
        SDL_WaitThread(worker_thread, nullptr);
        worker_thread = nullptr;
    }
}

