void RecordPlayerTile::setRecord(
    Level* world,
    int    cx,
    int    cy,
    int    cz,
    int    recordId
) {
    if (world->isClientSide) {
        return;
    }

    auto tileEntity = world->getTileEntity(cx, cy, cz);
    auto recordEntity = std::dynamic_pointer_cast<RecordPlayerTile::Entity>(tileEntity);

    if (recordEntity) {
        recordEntity->record = recordId;
        recordEntity->setChanged();
        world->setData(cx, cy, cz, 1);
    }
}

void RecordPlayerTile::dropRecording(Level* world, int cx, int cy, int cz) {
    if (world->isClientSide) {
        return;
    }

    auto tileEntity = world->getTileEntity(cx, cy, cz);
    auto recordEntity = std::dynamic_pointer_cast<RecordPlayerTile::Entity>(tileEntity);

    if (!recordEntity) {
        return;
    }

    int currentRecord = recordEntity->record;
    if (currentRecord == 0) {
        return;
    }

    world->levelEvent(LevelEvent::SOUND_PLAY_RECORDING, cx, cy, cz, 0);
    // 4J-PB- the level event will play the music
    // world->playStreamingMusic(L"", cx, cy, cz);

    recordEntity->record = 0;
    recordEntity->setChanged();
    world->setData(cx, cy, cz, 0);

    float spread = 0.7f;
    double offsetX = world->random->nextFloat() * spread + (1.0f - spread) * 0.5;
    double offsetY = world->random->nextFloat() * spread + (1.0f - spread) * 0.2 + 0.6;
    double offsetZ = world->random->nextFloat() * spread + (1.0f - spread) * 0.5;

    auto itemStack = std::make_shared<ItemInstance>(currentRecord, 1, 0);
    auto droppedItem = std::make_shared<ItemEntity>(
        world,
        cx + offsetX,
        cy + offsetY,
        cz + offsetZ,
        itemStack
    );
    droppedItem->throwTime = 10;
    world->addEntity(droppedItem);
}

void RecordPlayerTile::onRemove(
    Level* world,
    int    cx,
    int    cy,
    int    cz,
    int    typeId,
    int    meta
) {
    dropRecording(world, cx, cy, cz);
    Tile::onRemove(world, cx, cy, cz, typeId, meta);
}

