#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    // Compute number of unique pairs (i, j) where i < j
    long long pairCount = 1LL * n * (n - 1) / 2;
    vector<int> edgeValues(pairCount);

    for (long long i = 0; i < pairCount; ++i) {
        cin >> edgeValues[i];
    }

    // Build symmetric matrix from input values
    vector<vector<int>> adjMatrix(n, vector<int>(n, 0));
    long long valueIndex = 0;

    for (int row = 0; row < n; ++row) {
        for (int col = row + 1; col < n; ++col) {
            int val = edgeValues[valueIndex++];
            adjMatrix[row][col] = val;
            adjMatrix[col][row] = val;
        }
    }

    // For each vertex i, compute bitwise AND of all edges incident to i
    vector<int> result(n);
    for (int vertex = 0; vertex < n; ++vertex) {
        int andResult = -1; // All bits set (~0)

        for (int neighbor = 0; neighbor < n; ++neighbor) {
            if (neighbor != vertex) {
                andResult &= adjMatrix[vertex][neighbor];
            }
        }
        result[vertex] = andResult;
    }

    // Output the result
    for (int i = 0; i < n; ++i) {
        if (i > 0) cout << ' ';
        cout << result[i];
    }
    cout << '\n';

    return 0;
}

