    int blackCount, whiteCount, rowsInput, colsInput;
    if (!(cin >> blackCount >> whiteCount >> rowsInput >> colsInput)) return 0;

    const int GRID_ROWS = 100, GRID_COLS = 100;
    vector<string> grid(GRID_ROWS, string(GRID_COLS, '#'));

    // Fill bottom half with white cells ('.')
    for (int row = 50; row < GRID_ROWS; ++row) {
        fill(grid[row].begin(), grid[row].end(), '.');
    }

    // Add white regions in top black area (avoiding the boundary between halves)
    int remainingWhite = whiteCount - 1;
    for (int r = 0; r < 49 && remainingWhite > 0; r += 2) {
        for (int c = 0; c < GRID_COLS && remainingWhite > 0; c += 2) {
            grid[r][c] = '.';
            --remainingWhite;
        }
    }

    // Add black regions in bottom white area (avoiding the boundary between halves)
    int remainingBlack = blackCount - 1;
    for (int r = 51; r < GRID_ROWS && remainingBlack > 0; r += 2) {
        for (int c = 0; c < GRID_COLS && remainingBlack > 0; c += 2) {
            grid[r][c] = '#';
            --remainingBlack;
        }
    }

    cout << GRID_ROWS << " " << GRID_COLS << "\n";
    for (int i = 0; i < GRID_ROWS; ++i) {
        cout << grid[i] << "\n";
    }

    return 0;
}

