#include <assert.h>
#include <math.h>
#include <mpi.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Generate an array of random floating-point values in [0, 1)
float* generate_random_array(int count) {
    float* data = (float*) malloc(sizeof(float) * count);
    assert(data != NULL);

    for (int idx = 0; idx < count; ++idx) {
        data[idx] = static_cast<float>(rand()) / static_cast<float>(RAND_MAX);
    }

    return data;
}

int main(int argc, char** argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s elements_per_process\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    int elements_per_rank = atoi(argv[1]);

    MPI_Init(nullptr, nullptr);

    int rank;
    MPI_Comm_rank(MPI_COMM_WORLD, &rank);

    int size;
    MPI_Comm_size(MPI_COMM_WORLD, &size);

    // Initialize RNG with unique seed per process
    srand(static_cast<unsigned>(time(nullptr)) ^ (rank + 1));

    float* random_values = generate_random_array(elements_per_rank);

    // Compute local sum
    float local_total = 0.0f;
    for (int i = 0; i < elements_per_rank; ++i) {
        local_total += random_values[i];
    }

    // Global sum across all processes
    float global_total;
    MPI_Allreduce(&local_total, &global_total, 1, MPI_FLOAT, MPI_SUM, MPI_COMM_WORLD);

    const int total_elements = elements_per_rank * size;
    float mean = global_total / total_elements;

    // Compute local sum of squared deviations from mean
    float local_variance_sum = 0.0f;
    for (int i = 0; i < elements_per_rank; ++i) {
        float diff = random_values[i] - mean;
        local_variance_sum += diff * diff;
    }

    // Reduce to root process
    float global_variance_sum;
    MPI_Reduce(&local_variance_sum, &global_variance_sum, 1, MPI_FLOAT, MPI_SUM, 0, MPI_COMM_WORLD);

    // Calculate and output standard deviation on root
    if (rank == 0) {
        float variance = global_variance_sum / total_elements;
        float stddev = sqrt(variance);
        printf("Mean: %f, Standard deviation: %f\n", mean, stddev);
    }

    free(random_values);
    MPI_Barrier(MPI_COMM_WORLD);
    MPI_Finalize();

    return 0;
}

#include <iostream>
#include <vector>
#include <utility>
using namespace std;

// Represents a segment [L, R] that may contain 'k' candidates
// 'offset' counts how many candidates exist strictly before L (i.e., in [0, L-1])
struct Segment {
    int left;
    int right;
    int count; 
    int prefixCount; 
};

void reportAnswer(int pos) {
    cout << "! " << pos << endl;
    exit(0);
}

pair<int, int> ask(int position) {
    cout << "? " << position << endl;
    int leftCount, rightCount;
    if (!(cin >> leftCount >> rightCount)) exit(0);
    if (leftCount == -1) exit(0); // Should not occur per problem constraints
    return make_pair(leftCount, rightCount);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    int minTotal = 2e9;
    vector<Segment> segments;

    // Start with a query at the middle index
    int center = (n - 1) / 2;
    pair<int, int> result = ask(center);
    int total = result.first + result.second;
    if (total == 0) reportAnswer(center);
    minTotal = total;

    // Initialize candidate segments based on first query
    if (result.first > 0) {
        segments.push_back({0, center - 1, result.first, 0});
    }
    if (result.second > 0) {
        segments.push_back({center + 1, n - 1, result.second, result.first});
    }

    while (!segments.empty()) {
        Segment current = segments.back();
        segments.pop_back();

        if (current.left > current.right) continue;

        int mid = (current.left + current.right) / 2;
        pair<int, int> res = ask(mid);
        int currentTotal = res.first + res.second;

        if (currentTotal == 0) reportAnswer(mid);

        if (currentTotal < minTotal) {
            // Found a better candidate — update best and reset search space
            minTotal = currentTotal;
            segments.clear();

            // New search space: only items better than this one
            if (res.first > 0) {
                segments.push_back({0, mid - 1, res.first, 0});
            }
            if (res.second > 0) {
                segments.push_back({mid + 1, n - 1, res.second, res.first});
            }
        } else {
            // Current item is not better — refine the current segment

            // Count of candidates in [current.left, mid - 1]
            int leftCandidates = res.first - current.prefixCount;

            // Remaining candidates go to the right side [mid + 1, current.right]
            int rightCandidates = current.count - leftCandidates;

            // Add subsegments for further exploration
            if (leftCandidates > 0) {
                segments.push_back({current.left, mid - 1, leftCandidates, current.prefixCount});
            }
            if (rightCandidates > 0) {
                // Offset for right segment = candidates before mid + candidates in [mid+1..mid] (none) + leftCandidates
                segments.push_back({mid + 1, current.right, rightCandidates, res.first});
            }
        }
    }

    // The algorithm guarantees finding the optimal position before reaching here
    return 0;
}

