ConsoleUIController ui;

void ConsoleUIController::init(S32 width, S32 height)
{
#ifdef _ENABLEIGGY
	// Common initialization steps
	preInit(width, height);

	/* At this point, Iggy has been initialized. We now need to establish drawing
     * callbacks so that Iggy can render using platform-specific APIs (here, via GCM).
     * For this, we use the GDraw implementation bundled with the Iggy SDK.
     *
     * Setup involves configuring memory pools for various resource types:
     * textures, vertex buffers, render targets, etc. Some resources must reside in
     * specific memory regions for optimal performance. In this setup:
     *   - Render targets go into local video memory and require tiling.
     *   - Dynamic vertex buffers are placed in main memory for speed.
     */

    // Allocate memory for render targets
    S32 rt_pool_size = 16 * 1024 * 1024; // 16 MiB
    void* rt_pool = RenderManager.allocVRAM(rt_pool_size, CELL_GCM_TILE_ALIGN_OFFSET);
    S32 rt_stride = cellGcmGetTiledPitchSize(width * 4);
    gdraw_GCM_SetRendertargetMemory(rt_pool, rt_pool_size, width, height, rt_stride);

    // Configure tile region for render target usage
    RenderManager.setTileInfo(rt_pool, rt_stride, CELL_GCM_COMPMODE_C32_2X1);

    // Texture and static vertex buffer allocations
    S32 tex_pool_size = 24 * 1024 * 1024;
    S32 vbuf_pool_size = 2 * 1024 * 1024;
    gdraw_GCM_SetResourceMemory(GDRAW_GCM_RESOURCE_texture, 200,
        RenderManager.allocVRAM(tex_pool_size, 128), tex_pool_size);
    gdraw_GCM_SetResourceMemory(GDRAW_GCM_RESOURCE_vertexbuffer, 1000,
        RenderManager.allocVRAM(vbuf_pool_size, 128), vbuf_pool_size);

    // Dynamic vertex buffer allocated from I/O memory (faster access)
    S32 dyn_vbuf_size = 128 * 1024;
    gdraw_GCM_SetResourceMemory(GDRAW_GCM_RESOURCE_dyn_vertexbuffer, 0,
        RenderManager.allocIOMem(dyn_vbuf_size, 128), dyn_vbuf_size);

    // Work area for internal GDraw data (shaders, etc.)
    void* gdraw_workspace = RenderManager.allocVRAM(GDRAW_GCM_LOCAL_WORKMEM_SIZE, 128);

    // Create GDraw context and register with Iggy
    gdraw_funcs = gdraw_GCM_CreateContext(
        gCellGcmCurrentContext, // Default GCM rendering context
        gdraw_workspace,        // Workspace in local VRAM
        64                      // Fence label index
    );
    IggySetGDraw(gdraw_funcs);

    // Audio initialization temporarily disabled due to known crash issue
    // TODO: 4J Stu - Re-enable once audio subsystem stabilized
    // IggyAudioUseDefault();

    // Finalize common initialization
    postInit();
#endif
}

void ConsoleUIController::render()
{
#ifdef _ENABLEIGGY
    // Set current backbuffer as render target
    gdraw_GCM_SetTileOrigin(RenderManager.getCurrentBackBufferSurface(), 0, 0);

    // Trigger scene rendering pipeline
    renderScenes();

    // Signal end of frame rendering to GDraw
    gdraw_GCM_NoMoreGDrawThisFrame();
#endif
}

CustomDrawData* ConsoleUIController::setupCustomDraw(UIScene* scene, IggyCustomDrawCallbackRegion* region)
{
    CustomDrawData* drawData = new CustomDrawData();
    drawData->x0 = region->x0;
    drawData->x1 = region->x1;
    drawData->y0 = region->y0;
    drawData->y1 = region->y1;

    // Retrieve transformation matrix and configure rendering state
    gdraw_GCM_BeginCustomDraw(region, drawData->mat);
    setupCustomDrawGameStateAndMatrices(scene, drawData);

    return drawData;
}

CustomDrawData* ConsoleUIController::calculateCustomDraw(IggyCustomDrawCallbackRegion* region)
{
    CustomDrawData* drawData = new CustomDrawData();
    drawData->x0 = region->x0;
    drawData->x1 = region->x1;
    drawData->y0 = region->y0;
    drawData->y1 = region->y1;

    // Compute custom draw matrix without modifying global state
    gdraw_GCM_CalculateCustomDraw_4J(region, drawData->mat);
    return drawData;
}

void ConsoleUIController::endCustomDraw(IggyCustomDrawCallbackRegion* region)
{
    restoreGameStateAndMatrices(); // Renamed helper for clarity
    gdraw_GCM_EndCustomDraw(region);
}

