GDrawTexture* ConsoleUIController::getSubstitutionTexture(int texId)
{
    /* Wrap an existing shader resource view as a GDraw texture.
     * This allows external rendering (e.g., video playback or dynamic UI) to feed into Iggy.
     * The wrapped texture remains under application control — GDraw will not manage its lifecycle. */
    CellGcmTexture* nativeTex = RenderManager.TextureGetTexture(texId);
    GDrawTexture* wrappedTex = gdraw_GCM_WrappedTextureCreate(nativeTex);
    return wrappedTex;
}

void ConsoleUIController::destroySubstitutionTexture(void* userData, GDrawTexture* handle)
{
    /* Release only the GDraw wrapper around the texture.
     * Actual texture memory must be freed separately by the caller. */
    gdraw_GCM_WrappedTextureDestroy(handle);
}

