void ConsoleUIController::init(
    ID3D11Device*           device,
    ID3D11DeviceContext*    context,
    ID3D11RenderTargetView* rtv,
    ID3D11DepthStencilView* dsv,
    S32                     width,
    S32                     height
) {
#ifdef USE_IGGY_RENDERER
    m_pRenderTargetView  = rtv;
    m_pDepthStencilView  = dsv;

    // Common initialization steps
    preInit(width, height);

    gdraw_funcs = gdraw_D3D11_CreateContext(device, context, width, height);
    if (!gdraw_funcs) {
        app.DebugPrintf("GDraw initialization failed!\n");
#ifndef _CONTENT_PACKAGE
        __debugbreak();
#endif
        app.FatalLoadError();
    }

    // Configure resource limits for GDraw (approximate memory usage on D3D)
    gdraw_D3D11_SetResourceLimits(
        GDRAW_D3D11_RESOURCE_vertexbuffer,
        5000,
        16 * 1024 * 1024
    );

    gdraw_D3D11_SetResourceLimits(
        GDRAW_D3D11_RESOURCE_texture,
        5000,
        128 * 1024 * 1024
    );

    gdraw_D3D11_SetResourceLimits(
        GDRAW_D3D11_RESOURCE_rendertarget,
        10,
        32 * 1024 * 1024
    );

    // Link GDraw with Iggy
    IggySetGDraw(gdraw_funcs);

    // Use DirectSound for audio output
    IggyAudioUseDirectSound();

    // Finalize shared setup
    postInit();
