unsigned int BoolNatTernaryPrecedenceSafe::branch_left(const bool b) {
    // Return base value plus conditional increment
    unsigned int result = 0;
    result += (b ? 1 : 0);
    return result;
}

unsigned int BoolNatTernaryPrecedenceSafe::branch_right(const bool b) {
    // Return offset value based on condition
    unsigned int base = 2;
    unsigned int offset = (b ? 0 : 1);
    return base + offset;
}

#include <iostream>
#include <string>
#include <memory>
#include <csignal>
#include <cstring>
#include <gz/transport/Node.hh>
#include <gz/msgs/image.pb.h>
#include <gst/gst.h>
#include <gst/app/gstappsrc.h>

// Global state variables
GstElement *main_pipeline = nullptr;
GMainLoop *event_loop = nullptr;
GstElement *source_element = nullptr;
bool caps_configured = false;

// Configuration parameters
std::string DEST_IP = "127.0.0.1";
int DEST_PORT = 5600;
int FPS_SETTING = 10;

// Signal handler for graceful shutdown
void handle_interrupt(int signal_code) {
    (void)signal_code;
    if (event_loop) g_main_loop_quit(event_loop);
}

// Check if NVIDIA encoder is available
bool has_nvidia_encoder() {
    GstElementFactory *factory = gst_element_factory_find("nvh264enc");
    bool present = (factory != nullptr);
    if (factory) gst_object_unref(factory);
    return present;
}

// Process incoming image frames from Gazebo
void frame_handler(const gz::msgs::Image &frame_msg) {
    if (!source_element) return;

    // Set caps only once on first valid frame
    if (!caps_configured) {
        GstCaps *caps = gst_caps_new_simple("video/x-raw",
            "format", G_TYPE_STRING, "RGB",
            "width", G_TYPE_INT, frame_msg.width(),
            "height", G_TYPE_INT, frame_msg.height(),
            "framerate", GST_TYPE_FRACTION, FPS_SETTING, 1,
            nullptr);

        gst_app_src_set_caps(GST_APP_SRC(source_element), caps);
        gst_caps_unref(caps);

        std::cout << "GStreamer initialized for resolution: "
                  << frame_msg.width() << "x" << frame_msg.height() << std::endl;
        caps_configured = true;
    }

    // Prepare buffer for GStreamer
    const size_t data_size = frame_msg.data().size();
    GstBuffer *buffer = gst_buffer_new_allocate(nullptr, data_size, nullptr);

    if (buffer) {
        gst_buffer_fill(buffer, 0, frame_msg.data().data(), data_size);
        GstFlowReturn result = gst_app_src_push_buffer(GST_APP_SRC(source_element), buffer);
        if (result != GST_FLOW_OK) {
            g_warning("Failed to push buffer into appsrc (flow: %d)", static_cast<int>(result));
        }
    } else {
        g_warning("Memory allocation failed for GStreamer buffer");
    }
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc < 3) {
        std::cerr << "Usage: " << argv[0] << " <gz_topic> <ip_address> [port] [fps]\n";
        return EXIT_FAILURE;
    }

    std::string topic_name = argv[1];
    DEST_IP = argv[2];
    if (argc > 3) DEST_PORT = std::stoi(argv[3]);
    if (argc > 4) FPS_SETTING = std::stoi(argv[4]);

    // Initialize GStreamer subsystem
    gst_init(&argc, &argv);

    // Set up Gazebo transport node
    gz::transport::Node node;

    // Build pipeline string conditionally based on hardware support
    std::string pipeline_desc;
    std::string endpoint = "host=" + DEST_IP + ",port=" + std::to_string(DEST_PORT);

    if (has_nvidia_encoder()) {
        std::cout << "Detected NVIDIA encoder — enabling GPU-accelerated encoding\n";
        pipeline_desc =
            "appsrc name=source ! queue max-size-buffers=1 leaky=downstream ! "
            "videoconvert ! nvh264enc preset=low-latency-hq zerolatency=true rc-mode=cbr bitrate=2048 qp-min=15 qp-max=35 gop-size=30 ! "
            "rtph264pay config-interval=1 mtu=1400 ! udpsink sync=false " + endpoint;
    } else {
        std::cout << "Falling back to CPU-based H.264 encoding\n";
        pipeline_desc =
            "appsrc name=source ! queue max-size-buffers=1 leaky=downstream ! "
            "videoconvert ! x264enc speed-preset=ultrafast tune=zerolatency bitrate=2048 key-int-max=30 ! "
            "rtph264pay config-interval=1 mtu=1400 ! udpsink sync=false " + endpoint;
    }

    // Launch pipeline
    GError *build_error = nullptr;
    main_pipeline = gst_parse_launch(pipeline_desc.c_str(), &build_error);
    if (!main_pipeline || build_error) {
        std::cerr << "Pipeline creation failed: " << (build_error ? build_error->message : "unknown") << "\n";
        if (build_error) g_error_free(build_error);
        return EXIT_FAILURE;
    }

    // Retrieve and configure appsrc element
    source_element = gst_bin_get_by_name(GST_BIN(main_pipeline), "source");
    g_object_set(source_element, "format", GST_FORMAT_TIME, nullptr);
    g_object_set(source_element, "is-live", TRUE, nullptr);
    g_object_set(source_element, "do-timestamp", TRUE, nullptr);
    g_object_set(source_element, "leaky-type", 2, nullptr); // Drop outdated buffers
    g_object_set(source_element, "max-bytes", 0U, nullptr);
    g_object_set(source_element, "max-buffers", 2U, nullptr);

    // Start pipeline
    gst_element_set_state(main_pipeline, GST_STATE_PLAYING);

    // Subscribe to Gazebo topic
    if (!node.Subscribe(topic_name, frame_handler)) {
        std::cerr << "Unable to subscribe to topic: " << topic_name << "\n";
        gst_element_set_state(main_pipeline, GST_STATE_NULL);
        gst_object_unref(source_element);
        gst_object_unref(main_pipeline);
        return EXIT_FAILURE;
    }

    std::cout << "Streaming '" << topic_name << "' to " << DEST_IP << ":" << DEST_PORT
              << " at " << FPS_SETTING << " FPS.\n";

    // Enter event loop
    event_loop = g_main_loop_new(nullptr, FALSE);
    std::signal(SIGINT, handle_interrupt);
    g_main_loop_run(event_loop);

    // Cleanup resources
    gst_element_set_state(main_pipeline, GST_STATE_NULL);
    gst_object_unref(source_element);
    gst_object_unref(main_pipeline);
    g_main_loop_unref(event_loop);

    return EXIT_SUCCESS;
}

