#include <iostream>
#include <vector>

// Computes the change in sum of squared differences when transferring 1 unit from i to j
long long compute_s2_delta(long long a_i, long long b_i, long long a_j, long long b_j) {
    long long diff_i = a_i - b_i;
    long long diff_j = a_j - b_j;

    // After operation: move 1 from i to j
    long long new_diff_i = (a_i - 1) - b_i;  // a_i decreases by 1
    long long new_diff_j = (a_j + 1) - b_j;  // a_j increases by 1

    return (new_diff_i * new_diff_i + new_diff_j * new_diff_j) - 
           (diff_i * diff_i + diff_j * diff_j);
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    std::cin >> n;

    std::vector<long long> a(n), b(n);
    long long total_a = 0, total_b = 0;

    for (int i = 0; i < n; ++i) {
        std::cin >> a[i];
        total_a += a[i];
    }

    for (int i = 0; i < n; ++i) {
        std::cin >> b[i];
        total_b += b[i];
    }

    if (total_a != total_b) {
        std::cout << "No\n";
        return 0;
    }

    std::vector<std::pair<int, int>> operations;

    // Attempt transformation with bounded iterations
    for (int iter = 0; iter < 40000; ++iter) {
        bool match_all = true;
        for (int idx = 0; idx < n; ++idx) {
            if (a[idx] != b[idx]) {
                match_all = false;
                break;
            }
        }

        if (match_all) {
            break;
        }

        long long min_delta = 0;
        int best_src = -1, best_dst = -1;

        for (int src = 0; src < n; ++src) {
            for (int dst = src + 1; dst < n; ++dst) {
                long long delta = compute_s2_delta(a[src], b[src], a[dst], b[dst]);

                if (delta < min_delta) {
                    min_delta = delta;
                    best_src = src;
                    best_dst = dst;
                }
            }
        }

        if (best_src != -1) {
            operations.emplace_back(best_src + 1, best_dst + 1);

            long long temp_a_src = a[best_src];
            long long temp_a_dst = a[best_dst];

            a[best_src] = temp_a_src - 1;
            a[best_dst] = temp_a_dst + 1;
        } else {
            break;
        }
    }

    bool success = true;
    for (int i = 0; i < n; ++i) {
        if (a[i] != b[i]) {
            success = false;
            break;
        }
    }

    if (success) {
        std::cout << "Yes\n";
        std::cout << operations.size() << "\n";
        for (const auto& op : operations) {
            std::cout << op.first << " " << op.second << "\n";
        }
    } else {
        std::cout << "No\n";
    }

    return 0;
}

