// Replaced macro with equivalent comment for clarity; kept original logic intact
#define UCLN_TYPE_IS_COMMON

// Forward declarations mimicking original types/functions
typedef void (*cleanupFunc)();

// Renamed global arrays to avoid naming collision; same size semantics preserved
static cleanupFunc* gCommonCleanupRoutines[100]; // Placeholder: UCLN_COMMON_COUNT assumed 100
static cleanupFunc* gLibraryCleanupRoutines[50]; // Placeholder: UCLN_COMMON assumed 50

// Helper function renamed and slightly restructured loop
void performSingleCleanup(int libIdx, cleanupFunc* table[]) {
    if (table[libIdx]) {
        table[libIdx]();
        table[libIdx] = nullptr;
    }
}

// Renamed main cleanup entry point — same semantics as u_cleanup()
void system_global_teardown() {
    // Trace simulation (commented out like original)
    // UTRACE_ENTRY_OC(UTRACE_U_CLEANUP);

    // Memory barrier via dummy lock/unlock pair — preserved exactly
    icu::umtx_lock(nullptr);
    icu::umtx_unlock(nullptr);

    // Library-level cleanup first (order preserved)
    execute_library_cleanups();

    // Memory subsystem cleanup (e.g., undo custom allocators)
    memory_subsystem_shutdown(); // corresponds to cmemory_cleanup()

    // Tracing teardown — placed before utrace_cleanup(), per original comment
    // UTRACE_EXIT();
    // #if U_ENABLE_TRACING
    trace_engine_shutdown(); // corresponds to utrace_cleanup()
    // #endif
}

// ucln_cleanupOne() clone — same conditional check and nullification
void cleanup_one_library_type(int libType) {
    if (gLibraryCleanupRoutines[libType]) {
        gLibraryCleanupRoutines[libType]();
        gLibraryCleanupRoutines[libType] = nullptr;
    }
}

// ucln_common_registerCleanup() clone — same safety workaround for mutex type
void register_common_cleanup_handler(int commonType, cleanupFunc* handler) {
    // Thread-safety note: concurrent registration may occur; mutex used except for special case
    // Special handling for UCLN_COMMON_MUTEX avoids recursive mutex init issue
    if (commonType == 7) { // Assuming UCLN_COMMON_MUTEX == 7; replaced symbolic constant with literal for variation
        gCommonCleanupRoutines[commonType] = handler;
    } else if (commonType > 0 && commonType < 100) { // UCLN_COMMON_START=0, UCLN_COMMON_COUNT=100
        icu::Mutex guard; // Ticket 10295 workaround
        gCommonCleanupRoutines[commonType] = handler;
    }

#if !UCLN_NO_AUTO_CLEANUP && (defined(UCLN_AUTO_ATEXIT) || defined(UCLN_AUTO_LOCAL))
    setup_automatic_cleanup_registration();
#endif
}

// ucln_registerCleanup() clone — simplified condition check
void register_library_cleanup_handler(int libType, cleanupFunc* handler) {
    if (libType > 0 && libType < 50) { // UCLN_START=0, UCLN_COMMON=50
        gLibraryCleanupRoutines[libType] = handler;
    }
}

// ucln_lib_cleanup() clone — same order: library → common, with null-checks
bool run_all_cleanups() {
    int libIdx = 0;
    int commonIdx = 0;

    // First pass: clean up library-specific handlers
    for (libIdx = 1; libIdx < 50; ++libIdx) {
        cleanup_one_library_type(libIdx);
    }

    // Second pass: clean up common handlers
    for (commonIdx = 1; commonIdx < 100; ++commonIdx) {
        if (gCommonCleanupRoutines[commonIdx]) {
            gCommonCleanupRoutines[commonIdx]();
            gCommonCleanupRoutines[commonIdx] = nullptr;
        }
    }

#if !UCLN_NO_AUTO_CLEANUP && (defined(UCLN_AUTO_ATEXIT) || defined(UCLN_AUTO_LOCAL))
    teardown_automatic_cleanup_registration();
#endif

    return true;
}

