// Read wake data
void Polar3dDlg::readWakeData(Polar3d &polar3d) const
{
    polar3d.setVortonWake(m_radVortonWake->isChecked());
    polar3d.setNXWakePanel4(m_intNumWakeX->value());
    polar3d.setTotalWakeLengthFactor(m_fldWakeLen->value());
    polar3d.setWakePanelFactor(m_fldWakeFactor->value());
    polar3d.setBufferWakeFactor(m_fldVPWBufferLen->value());
    polar3d.setVortonL0(m_fldVortonStep->value());
    polar3d.setVPWMaxLength(m_fldVPWMaxDist->value());
    polar3d.setVortonCoreSize(m_fldVortonCore->value());
    polar3d.setVPWIterations(m_intVPWIters->value());
}

// Set VPW units dynamically
void Polar3dDlg::setVPWUnits(Polar3d &polar3d)
{
    m_labVPWBufferUnit->setText(QString::asprintf("x reference chord = %9.3g", 
        polar3d.bufferWakeFactor() * polar3d.referenceChordLength() * Units::mtoUnit()) + Units::lengthUnitQLabel());
    m_labVPWStepUnit->setText(QString::asprintf("x reference chord = %9.3g", 
        polar3d.vortonL0() * polar3d.referenceChordLength() * Units::mtoUnit()) + Units::lengthUnitQLabel());
    m_labVPWCoreUnit->setText(QString::asprintf("x reference chord = %9.3g", 
        polar3d.vortonCoreSize() * polar3d.referenceChordLength() * Units::mtoUnit()) + Units::lengthUnitQLabel());
    m_labVPWDiscardUnit->setText(QString::asprintf("x reference chord = %9.3g", 
        polar3d.VPWMaxLength() * polar3d.referenceChordLength() * Units::mtoUnit()) + Units::lengthUnitQLabel());

    double l = polar3d.vortonL0() * polar3d.referenceChordLength() * double(polar3d.VPWIterations());
    l += polar3d.bufferWakeLength() * polar3d.referenceChordLength();
    m_labVPWMaxDistEst->setText(QString(QChar(0x21D2)) + QString::asprintf(" max. distance = %9.3g ", l * Units::mtoUnit()) + Units::lengthUnitQLabel());
}

// Method change handler
void Polar3dDlg::onMethod()
{
    readMethodData();
    enableControls();
    setPolar3dName();
}

// Disable vorton wake controls
void Polar3dDlg::disableVortonWake(Polar3d &polar3d)
{
    m_grpVortonWake->setEnabled(false);
    m_radPanelWake->setEnabled(false);
    m_radVortonWake->setEnabled(false);
    m_radPanelWake->setChecked(true);
    polar3d.setVortonWake(false);
}

