    // Generic handler for dynamic calls
    void Application::processDynamicCall(WinApplication* app, x86::CPU& cpu, uint32_t targetAddress)
    {
        NFS2_USE(cpu);
        NFS2_USE(app);

        // Perform the dynamic call using the provided target address
        app->dynamic_call(app->getMemory<x86::reg32>(targetAddress), cpu);
    }

    // Process all registered jump targets
    void Application::processAllJumpTargets(WinApplication* app, x86::CPU& cpu)
    {
        // Iterate through all jump targets and process each one
        for (size_t i = 0; i < sizeof(jumpTargets) / sizeof(jumpTargets[0]); ++i) {
            processDynamicCall(app, cpu, jumpTargets[i].address);
        }
    }

    // Alternative implementation using iterator-style processing
    void Application::handleJumpSequence(WinApplication* app, x86::CPU& cpu)
    {
        // Initialize counter for iteration
        size_t index = 0;
        const size_t totalTargets = sizeof(jumpTargets) / sizeof(jumpTargets[0]);

        // Process each target until we've handled them all
        while (index < totalTargets) {
            processDynamicCall(app, cpu, jumpTargets[index].address);
            ++index;
        }
    }
}

