ARMASMOutput::ARMASMOutput(MCStreamer &S, formatted_raw_ostream &OS,
                           MCInstPrinter &IP, bool Verbose)
    : ARMTargetStreamer(S), OutStream(OS), Disassembler(IP),
      ShowComments(Verbose) {}

void ARMASMOutput::prologueBegin() { OutStream << "\t.fnstart\n"; }
void ARMASMOutput::prologueEnd() { OutStream << "\t.fnend\n"; }
void ARMASMOutput::noUnwindInfo() { OutStream << "\t.cantunwind\n"; }
void ARMASMOutput::setPersonality(const MCSymbol *Handler) {
  OutStream << "\t.personality " << Handler->getName() << '\n';
}
void ARMASMOutput::setPersonalityIdx(unsigned Num) {
  OutStream << "\t.personalityindex " << Num << '\n';
}
void ARMASMOutput::dataSegment() { OutStream << "\t.handlerdata\n"; }
void ARMASMOutput::setFramePtr(unsigned FrameReg, unsigned StackReg, int64_t Delta) {
  OutStream << "\t.setfp\t";
  Disassembler.printRegName(OutStream, FrameReg);
  OutStream << ", ";
  Disassembler.printRegName(OutStream, StackReg);
  if (Delta)
    OutStream << ", #" << Delta;
  OutStream << '\n';
}
void ARMASMOutput::adjustStackPtr(unsigned Reg, int64_t Adjustment) {
  assert((Reg != ARM::SP && Reg != ARM::PC) &&
         "stack pointer or program counter cannot be used as operand");
  OutStream << "\t.movsp\t";
  Disassembler.printRegName(OutStream, Reg);
  if (Adjustment)
    OutStream << ", #" << Adjustment;
  OutStream << '\n';
}
void ARMASMOutput::reserveSpace(int64_t Bytes) {
  OutStream << "\t.pad\t#" << Bytes << '\n';
}
void ARMASMOutput::saveRegisters(const SmallVectorImpl<unsigned> &Regs, bool IsVec) {
  assert(!Regs.empty() && "register list must not be empty");
  if (IsVec)
    OutStream << "\t.vsave\t{";
  else
    OutStream << "\t.save\t{";
  Disassembler.printRegName(OutStream, Regs[0]);
  for (size_t i = 1; i < Regs.size(); ++i) {
    OutStream << ", ";
    Disassembler.printRegName(OutStream, Regs[i]);
  }
  OutStream << "}\n";
}
void ARMASMOutput::changeVendor(StringRef V) {}
void ARMASMOutput::addAttribute(unsigned Attr, unsigned Val) {
  OutStream << "\t.eabi_attribute\t" << Attr << ", " << Twine(Val);
  if (ShowComments) {
    StringRef Label = ELFAttrs::attrTypeAsString(
        Attr, ARMBuildAttrs::getARMAttributeTags());
    if (!Label.empty())
      OutStream << "\t@ " << Label;
  }
  OutStream << "\n";
}
void ARMASMOutput::addStringAttribute(unsigned Attr, StringRef Text) {
  switch (Attr) {
  case ARMBuildAttrs::CPU_name:
    OutStream << "\t.cpu\t" << Text.lower();
    break;
  default:
    OutStream << "\t.eabi_attribute\t" << Attr << ", \"";
    if (Attr == ARMBuildAttrs::also_compatible_with)
      OutStream.write_escaped(Text);
    else
      OutStream << Text;
    OutStream << "\"";
    if (ShowComments) {
      StringRef Label = ELFAttrs::attrTypeAsString(
          Attr, ARMBuildAttrs::getARMAttributeTags());
      if (!Label.empty())
        OutStream << "\t@ " << Label;
    }
    break;
  }
  OutStream << "\n";
}
void ARMASMOutput::addMixedAttribute(unsigned Attr, unsigned IntVal, StringRef StrVal) {
  switch (Attr) {
  default: llvm_unreachable("unsupported multi-value attribute in assembly mode");
  case ARMBuildAttrs::compatibility:
    OutStream << "\t.eabi_attribute\t" << Attr << ", " << IntVal;
    if (!StrVal.empty())
      OutStream << ", \"" << StrVal << "\"";
    if (ShowComments)
      OutStream << "\t@ "
                << ELFAttrs::attrTypeAsString(Attr,
                                              ARMBuildAttrs::getARMAttributeTags());
    break;
  }
  OutStream << "\n";
}
void ARMASMOutput::setArchitecture(ARM::ArchKind Arch) {
  OutStream << "\t.arch\t" << ARM::getArchName(Arch) << "\n";
}
void ARMASMOutput::addArchExtension(uint64_t Ext) {
  OutStream << "\t.arch_extension\t" << ARM::getArchExtName(Ext) << "\n";
}
void ARMASMOutput::recordObjectArch(ARM::ArchKind Arch) {
  OutStream << "\t.object_arch\t" << ARM::getArchName(Arch) << '\n';
}
void ARMASMOutput::specifyFPU(ARM::FPUKind FPUType) {
  OutStream << "\t.fpu\t" << ARM::getFPUName(FPUType) << "\n";
}
void ARMASMOutput::finalizeAttributes() {}
void ARMASMOutput::markTLSDescriptor(const MCSymbolRefExpr *SymExpr) {
  OutStream << "\t.tlsdescseq\t" << SymExpr->getSymbol().getName() << "\n";
}
void ARMASMOutput::declareThumbSymbol(MCSymbol *Sym, const MCExpr *Val) {
  const MCAsmInfo *MAI = Streamer.getContext().getAsmInfo();
  OutStream << "\t.thumb_set\t";
  Sym->print(OutStream, MAI);
  OutStream << ", ";
  Val->print(OutStream, MAI);
  OutStream << '\n';
}
void ARMASMOutput::outputInstruction(uint32_t Code, char Postfix) {
  OutStream << "\t.inst";
  if (Postfix)
    OutStream << "." << Postfix;
  OutStream << "\t0x" << Twine::utohexstr(Code) << "\n";
}
void ARMASMOutput::rawUnwindOps(int64_t Offset, const SmallVectorImpl<uint8_t> &Ops) {
  OutStream << "\t.unwind_raw " << Offset;
  for (uint8_t Op : Ops)
    OutStream << ", 0x" << Twine::utohexstr(Op);
  OutStream << '\n';
}
void ARMASMOutput::emitWinSEHAllocStack(unsigned Sz, bool Wide) {
  if (Wide)
    OutStream << "\t.seh_stackalloc_w\t" << Sz << "\n";
  else
    OutStream << "\t.seh_stackalloc\t" << Sz << "\n";
}

static void formatRegisterRange(formatted_raw_ostream &OS, ListSeparator &Sep, 
                                int Start, int End) {
  if (Start != End)
    OS << Sep << "r" << Start << "-r" << End;
  else
    OS << Sep << "r" << Start;
}

void ARMASMOutput::emitWinSEHSaveMask(unsigned Mask, bool Wide) {
  if (Wide)
    OutStream << "\t.seh_save_regs_w\t";
  else
    OutStream << "\t.seh_save_regs\t";
  ListSeparator Sep;
  int StartReg = -1;
  OutStream << "{";
  for (int I = 0; I <= 12; ++I) {
    if (Mask & (1 << I)) {
      if (StartReg < 0)
        StartReg = I;
    } else {
      if (StartReg >= 0) {
        formatRegisterRange(OutStream, Sep, StartReg, I - 1);
        StartReg = -1;
      }
    }
  }
  if (StartReg >= 0)
    formatRegisterRange(OutStream, Sep, StartReg, 12);
  if (Mask & (1 << 14))
    OutStream << Sep << "lr";
  OutStream << "}\n";
}
void ARMASMOutput::emitWinSEHSaveSP(unsigned Reg) {
  OutStream << "\t.seh_save_sp\tr" << Reg << "\n";
}
void ARMASMOutput::emitWinSEHSaveFPRange(unsigned First, unsigned Last) {
  if (First != Last)
    OutStream << "\t.seh_save_fregs\t{d" << First << "-d" << Last << "}\n";
  else
    OutStream << "\t.seh_save_fregs\t{d" << First << "}\n";
}
void ARMASMOutput::emitWinSEHSaveLR(int Offset) {
  OutStream << "\t.seh_save_lr\t" << Offset << "\n";
}
void ARMASMOutput::emitWinSEHPrologEnd(bool Fragmented) {
  if (Fragmented)
    OutStream << "\t.seh_endprologue_fragment\n";
  else
    OutStream << "\t.seh_endprologue\n";
}
void ARMASMOutput::emitWinSEHNop(bool Wide) {
  if (Wide)
    OutStream << "\t.seh_nop_w\n";
  else
    OutStream << "\t.seh_nop\n";
}
void ARMASMOutput::emitWinSEHEpilogStart(unsigned Condition) {
  if (Condition == ARMCC::AL)
    OutStream << "\t.seh_startepilogue\n";
  else
    OutStream << "\t.seh_startepilogue_cond\t"
              << ARMCondCodeToString(static_cast<ARMCC::CondCodes>(Condition)) << "\n";
}
void ARMASMOutput::emitWinSEHEpilogEnd() {
  OutStream << "\t.seh_endepilogue\n";
}
void ARMASMOutput::emitWinSEHCustomOpcode(unsigned Opcode) {
  int I;
  for (I = 3; I > 0; --I)
    if (Opcode & (0xffu << (8 * I)))
      break;
  ListSeparator Sep;
  OutStream << "\t.seh_custom\t";
  for (; I >= 0; --I)
    OutStream << Sep << ((Opcode >> (8 * I)) & 0xff);
  OutStream << "\n";
}

