class ARMELFStreamer : public MCELFStreamer {
public:
  friend class ARMELFOutput;
  ARMELFStreamer(MCContext &Ctx, std::unique_ptr<MCAsmBackend> Backend,
                 std::unique_ptr<MCObjectWriter> Writer,
                 std::unique_ptr<MCCodeEmitter> Encoder, bool ThumbMode,
                 bool AndroidPlatform)
      : MCELFStreamer(Ctx, std::move(Backend), std::move(Writer),
                      std::move(Encoder)),
        IsThumb(ThumbMode), IsAndroid(AndroidPlatform) {
    resetEHState();
  }
  ~ARMELFStreamer() override = default;

  void finalize() override;

  // Exception handling directives
  void prologueBegin();
  void prologueEnd();
  void noUnwindInfo();
  void setPersonality(const MCSymbol *Per);
  void setPersonalityIdx(unsigned idx);
  void dataSegment();
  void setFramePtr(unsigned NewFP, unsigned NewSP, int64_t Delta = 0);
  void adjustStackPtr(unsigned Reg, int64_t Delta = 0);
  void reserveSpace(int64_t Bytes);
  void saveRegisters(const SmallVectorImpl<unsigned> &Regs, bool IsVec);
  void rawUnwindOps(int64_t Offset, const SmallVectorImpl<uint8_t> &Ops);

  void emitFill(const MCExpr &NumBytes, uint64_t FillValue, SMLoc Loc) override {
    emitDataMappingMarker();
    MCObjectStreamer::emitFill(NumBytes, FillValue, Loc);
  }

  void changeSection(MCSection *Section, const MCExpr *Subsection) override {
    SectionMappingMarkers[getCurrentSection().first] = std::move(CurrentEMSInfo);
    MCELFStreamer::changeSection(Section, Subsection);
    auto It = SectionMappingMarkers.find(Section);
    if (It != SectionMappingMarkers.end()) {
      CurrentEMSInfo = std::move(It->second);
      return;
    }
    CurrentEMSInfo.reset(new MappingSymbolInfo(SMLoc(), nullptr, 0));
  }

  void emitInstruction(const MCInst &Inst, const MCSubtargetInfo &STI) override {
    if (IsThumb)
      emitThumbMappingMarker();
    else
      emitARMMappingMarker();
    MCELFStreamer::emitInstruction(Inst, STI);
  }

  void emitRawInstruction(uint32_t Code, char Postfix) {
    unsigned Size;
    char Buffer[4];
    const bool LittleEndian = getContext().getAsmInfo()->isLittleEndian();
    switch (Postfix) {
    case '\0':
      Size = 4;
      assert(!IsThumb);
      emitARMMappingMarker();
      for (unsigned II = 0; II < Size; ++II) {
        unsigned Idx = LittleEndian ? (Size - II - 1) : II;
        Buffer[Size - II - 1] = uint8_t(Code >> Idx * CHAR_BIT);
      }
      break;
    case 'n':
    case 'w':
      Size = (Postfix == 'n' ? 2 : 4);
      assert(IsThumb);
      emitThumbMappingMarker();
      for (unsigned II = 0; II < Size; II += 2) {
        unsigned Idx0 = LittleEndian ? II + 0 : II + 1;
        unsigned Idx1 = LittleEndian ? II + 1 : II + 0;
        Buffer[Size - II - 2] = uint8_t(Code >> Idx0 * CHAR_BIT);
        Buffer[Size - II - 1] = uint8_t(Code >> Idx1 * CHAR_BIT);
      }
      break;
    default:
      llvm_unreachable("invalid suffix");
    }
    MCELFStreamer::emitBytes(StringRef(Buffer, Size));
  }

  void emitBytes(StringRef Data) override {
    emitDataMappingMarker();
    MCELFStreamer::emitBytes(Data);
  }

  void flushPendingMappingMarker() {
    if (!CurrentEMSInfo->hasInfo())
      return;
    MappingSymbolInfo *MSI = CurrentEMSInfo.get();
    emitMappingSymbol("$d", MSI->Loc, MSI->Frag, MSI->Offset);
    CurrentEMSInfo->resetInfo();
  }

  void emitValueImpl(const MCExpr *Value, unsigned Size, SMLoc Loc) override {
    if (const MCSymbolRefExpr *SRE = dyn_cast_or_null<MCSymbolRefExpr>(Value)) {
      if (SRE->getKind() == MCSymbolRefExpr::VK_ARM_SBREL && !(Size == 4)) {
        getContext().reportError(Loc, "relocated expression must be 32-bit");
        return;
      }
      getOrCreateDataFragment();
    }
    emitDataMappingMarker();
    MCELFStreamer::emitValueImpl(Value, Size, Loc);
  }

  void emitAssemblerFlag(MCAssemblerFlag Flag) override {
    MCELFStreamer::emitAssemblerFlag(Flag);
    switch (Flag) {
    case MCAF_SyntaxUnified:
      return;
    case MCAF_Code16:
      IsThumb = true;
      return;
    case MCAF_Code32:
      IsThumb = false;
      return;
    case MCAF_Code64:
      return;
    case MCAF_SubsectionsViaSymbols:
      return;
    }
  }

  bool emitSymbolAttribute(MCSymbol *Symbol, MCSymbolAttr Attribute) override {
    bool Result = MCELFStreamer::emitSymbolAttribute(Symbol, Attribute);
    if (!IsThumb)
      return Result;
    unsigned Type = cast<MCSymbolELF>(Symbol)->getType();
    if ((Type == ELF::STT_FUNC || Type == ELF::STT_GNU_IFUNC) &&
        Symbol->isDefined())
      getAssembler().setIsThumbFunc(Symbol);
    return Result;
  };

private:
  enum MappingSymbolType {
    MST_None,
    MST_ARM,
    MST_Thumb,
    MST_Data
  };

  struct MappingSymbolInfo {
    explicit MappingSymbolInfo(SMLoc L, MCFragment *F, uint64_t O)
        : Loc(L), Frag(F), Offset(O), State(MST_None) {}
    void resetInfo() {
      Frag = nullptr;
      Offset = 0;
    }
    bool hasInfo() { return Frag != nullptr; }
    SMLoc Loc;
    MCFragment *Frag;
    uint64_t Offset;
    MappingSymbolType State;
  };

  void emitDataMappingMarker() {
    if (CurrentEMSInfo->State == MST_Data)
      return;
    else if (CurrentEMSInfo->State == MST_None) {
      MappingSymbolInfo *MSI = CurrentEMSInfo.get();
      auto *DF = dyn_cast_or_null<MCDataFragment>(getCurrentFragment());
      if (!DF)
        return;
      MSI->Loc = SMLoc();
      MSI->Frag = getCurrentFragment();
      MSI->Offset = DF->getContents().size();
      CurrentEMSInfo->State = MST_Data;
      return;
    }
    emitMappingSymbol("$d");
    CurrentEMSInfo->State = MST_Data;
  }

  void emitThumbMappingMarker() {
    if (CurrentEMSInfo->State == MST_Thumb)
      return;
    flushPendingMappingMarker();
    emitMappingSymbol("$t");
    CurrentEMSInfo->State = MST_Thumb;
  }

  void emitARMMappingMarker() {
    if (CurrentEMSInfo->State == MST_ARM)
      return;
    flushPendingMappingMarker();
    emitMappingSymbol("$a");
    CurrentEMSInfo->State = MST_ARM;
  }

  void emitMappingSymbol(StringRef Name) {
    auto *Sym = cast<MCSymbolELF>(getContext().getOrCreateSymbol(
        Name + "." + Twine(MappingCounter++)));
    emitLabel(Sym);
    Sym->setType(ELF::STT_NOTYPE);
    Sym->setBinding(ELF::STB_LOCAL);
  }

  void emitMappingSymbol(StringRef Name, SMLoc Loc, MCFragment *Frag,
                         uint64_t Offset) {
    auto *Sym = cast<MCSymbolELF>(getContext().getOrCreateSymbol(
        Name + "." + Twine(MappingCounter++)));
    emitLabelAtPos(Sym, Loc, Frag, Offset);
    Sym->setType(ELF::STT_NOTYPE);
    Sym->setBinding(ELF::STB_LOCAL);
  }

  void emitThumbFunc(MCSymbol *Func) override {
    getAssembler().setIsThumbFunc(Func);
    emitSymbolAttribute(Func, MCSA_ELF_TypeFunction);
  }

  // Exception handling helpers
  void resetEHState();
  void resetState() override;
  void emitPersonalityFixup(StringRef Name);
  void flushPendingOffset();
  void flushUnwindOpcodes(bool NoHandlerData);
  void enterEHSection(StringRef Prefix, unsigned Type, unsigned Flags,
                      SectionKind Kind, const MCSymbol &Fn);
  void enterExTabSection(const MCSymbol &FnStart);
  void enterExIdxSection(const MCSymbol &FnStart);
  void emitFixup(const MCExpr *Expr, MCFixupKind Kind);

  bool IsThumb;
  bool IsAndroid;
  int64_t MappingCounter = 0;
  DenseMap<const MCSection *, std::unique_ptr<MappingSymbolInfo>>
      SectionMappingMarkers;
  std::unique_ptr<MappingSymbolInfo> CurrentEMSInfo;

  // Exception handling state
  MCSymbol *ExTab;
  MCSymbol *FnStart;
  const MCSymbol *Personality;
  unsigned PersonalityIndex;
  unsigned FPReg;
  int64_t FPOffset;
  int64_t SPOffset;
  int64_t PendingOffset;
  bool UsedFP;
  bool CantUnwind;
  SmallVector<uint8_t, 64> UnwindOpcodes;
  UnwindOpcodeAssembler UnwindOpBuilder;
};
