using namespace std;

// Convert character to numeric index: 0-9 for digits, 10-35 for A-Z
inline int charToIndex(unsigned char c) {
    if (c >= '0' && c <= '9') return c - '0';
    return 10 + (c - 'A');
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string line1, line2;
    getline(cin, line1);
    getline(cin, line2);

    // Ensure S is the longer string and T is the shorter one
    bool firstIsLonger = line1.length() >= line2.length();
    string& source = firstIsLonger ? line1 : line2;
    string target = firstIsLonger ? line2 : line1;

    const size_t targetLen = target.length();

    // Frequency count for characters in target
    array<size_t, 36> freq{};
    for (unsigned char ch : target) {
        freq[charToIndex(ch)]++;
    }

    // Build position lists for each character in target
    array<vector<int>, 36> positions;
    for (int i = 0; i < 36; ++i) {
        positions[i].reserve(freq[i]);
    }
    for (int i = 0; i < (int)targetLen; ++i) {
        unsigned char ch = static_cast<unsigned char>(target[i]);
        positions[charToIndex(ch)].push_back(i);
    }

    // Reset tracking pointers for each character
    array<int, 36> indices{};
    int lastMatchedPos = 0;
    string result;
    result.reserve(targetLen);

    // Greedy matching: try to build subsequence from source matching target order
    for (unsigned char ch : source) {
        int idx = charToIndex(ch);
        auto& posList = positions[idx];
        int& currPtr = indices[idx];

        // Advance pointer past positions that are before current required position
        while (currPtr < (int)posList.size() && posList[currPtr] < lastMatchedPos) {
            ++currPtr;
        }

        // If we found a valid position, include this character
        if (currPtr < (int)posList.size()) {
            result.push_back(static_cast<char>(ch));
            lastMatchedPos = posList[currPtr] + 1;
            ++currPtr;

            // Early exit if we've matched all of target
            if (lastMatchedPos >= (int)targetLen) break;
        }
    }

    cout << result << '\n';
    return 0;
}

#include <iostream>
#include <vector>
#include <string>
#include <cmath>
#include <map>

// Fixed problem size as per guarantee
const int GRID_SIZE = 20;

struct Piece {
    int identifier;
    int row, col;
};

struct Action {
    char direction;
    int position;
    int depth;
    int expense;
    std::vector<int> pieces_affected;
};

struct Step {
    char dir;
    int idx;
};

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int dummy_input;
    std::cin >> dummy_input; // N is fixed at 20

    std::vector<std::string> board(GRID_SIZE);
    std::vector<Piece> pieces;
    std::map<std::pair<int, int>, int> piece_index;

    for (int i = 0; i < GRID_SIZE; ++i) {
        std::cin >> board[i];
        for (int j = 0; j < GRID_SIZE; ++j) {
            if (board[i][j] == 'x') {
                int id = static_cast<int>(pieces.size());
                pieces.push_back({id, i, j});
                piece_index[{i, j}] = id;
            }
        }
    }

    int total_pieces = static_cast<int>(pieces.size());
    std::vector<Action> possible_actions;

    // Generate upward actions
    for (int col = 0; col < GRID_SIZE; ++col) {
        std::vector<int> affected;
        for (int row = 0; row < GRID_SIZE; ++row) {
            if (board[row][col] == 'o') break;
            if (board[row][col] == 'x') {
                affected.push_back(piece_index.at({row, col}));
            }
            if (!affected.empty()) {
                possible_actions.push_back({'U', col, row, 2 * (row + 1), affected});
            }
        }
    }

    // Generate downward actions
    for (int col = 0; col < GRID_SIZE; ++col) {
        std::vector<int> affected;
        for (int row = GRID_SIZE - 1; row >= 0; --row) {
            if (board[row][col] == 'o') break;
            if (board[row][col] == 'x') {
                affected.push_back(piece_index.at({row, col}));
            }
            if (!affected.empty()) {
                possible_actions.push_back({'D', col, row, 2 * (GRID_SIZE - row), affected});
            }
        }
    }

    // Generate leftward actions
    for (int row = 0; row < GRID_SIZE; ++row) {
        std::vector<int> affected;
        for (int col = 0; col < GRID_SIZE; ++col) {
            if (board[row][col] == 'o') break;
            if (board[row][col] == 'x') {
                affected.push_back(piece_index.at({row, col}));
            }
            if (!affected.empty()) {
                possible_actions.push_back({'L', row, col, 2 * (col + 1), affected});
            }
        }
    }

    // Generate rightward actions
    for (int row = 0; row < GRID_SIZE; ++row) {
        std::vector<int> affected;
        for (int col = GRID_SIZE - 1; col >= 0; --col) {
            if (board[row][col] == 'o') break;
            if (board[row][col] == 'x') {
                affected.push_back(piece_index.at({row, col}));
            }
            if (!affected.empty()) {
                possible_actions.push_back({'R', row, col, 2 * (GRID_SIZE - col), affected});
            }
        }
    }

    std::vector<bool> status(total_pieces, false);
    int removed_count = 0;
    std::vector<Step> result_sequence;

    while (removed_count < total_pieces) {
        double best_score = -1.0;
        int selected_idx = -1;

        for (int i = 0; i < possible_actions.size(); ++i) {
            int gain = 0;
            for (int pid : possible_actions[i].pieces_affected) {
                if (!status[pid]) {
                    ++gain;
                }
            }
            if (gain == 0) continue;

            double current_score = static_cast<double>(gain) / std::sqrt(possible_actions[i].expense);
            if (current_score > best_score || 
               (current_score == best_score && selected_idx != -1 && 
                possible_actions[i].expense < possible_actions[selected_idx].expense)) {
                best_score = current_score;
                selected_idx = i;
            }
        }

        if (selected_idx == -1) break;

        const auto& chosen = possible_actions[selected_idx];

        if (chosen.direction == 'U') {
            for (int step = 0; step < chosen.depth / 2; ++step) {
                result_sequence.push_back({'U', chosen.position});
            }
            for (int step = 0; step < chosen.depth / 2; ++step) {
                result_sequence.push_back({'D', chosen.position});
            }
        } else if (chosen.direction == 'D') {
            for (int step = 0; step < (GRID_SIZE - chosen.depth / 2); ++step) {
                result_sequence.push_back({'D', chosen.position});
            }
            for (int step = 0; step < (GRID_SIZE - chosen.depth / 2); ++step) {
                result_sequence.push_back({'U', chosen.position});
            }
        } else if (chosen.direction == 'L') {
            for (int step = 0; step < chosen.depth / 2; ++step) {
                result_sequence.push_back({'L', chosen.position});
            }
            for (int step = 0; step < chosen.depth / 2; ++step) {
                result_sequence.push_back({'R', chosen.position});
            }
        } else if (chosen.direction == 'R') {
            for (int step = 0; step < (GRID_SIZE - chosen.depth / 2); ++step) {
                result_sequence.push_back({'R', chosen.position});
            }
            for (int step = 0; step < (GRID_SIZE - chosen.depth / 2); ++step) {
                result_sequence.push_back({'L', chosen.position});
            }
        }

        for (int pid : chosen.pieces_affected) {
            if (!status[pid]) {
                status[pid] = true;
                ++removed_count;
            }
        }
    }

    for (const auto& step : result_sequence) {
        std::cout << step.dir << " " << step.idx << "\n";
    }

    return 0;
}

