#include "stdafx.h"
#include "InputOutputStream.h"
#include "NbtIo.h"

CompoundTag *NbtIo::readCompressed(InputStream *sourceStream)
{
	MemSect(26);
	DataInputStream dataIn = DataInputStream(sourceStream); // Replaced GZIPInputStream equivalent
	CompoundTag *result = NbtIo::read((DataInput *)&dataIn);
	dataIn.close();
	MemSect(0);
	return result;
}

void NbtIo::writeCompressed(CompoundTag *tag, OutputStream *destStream)
{
	// Buffered output in 1024-byte segments for efficient file allocation during save
	BufferedOutputStream bufferedOut = BufferedOutputStream(destStream, 1024);
	DataOutputStream dataOut = DataOutputStream(&bufferedOut); // Replaced GZIPOutputStream equivalent
	NbtIo::write(tag, &dataOut);
	dataOut.close();
}

// Decompresses from a byte array without releasing the original buffer memory
CompoundTag *NbtIo::decompress(byteArray sourceBuffer)
{
	ByteArrayInputStream bais = ByteArrayInputStream(sourceBuffer);
	DataInputStream inputStream = DataInputStream(&bais); // Replaced GZIPInputStream equivalent
	CompoundTag *decodedTag = NbtIo::read((DataInput *)&inputStream);
	bais.reset(); // Prevents automatic deallocation of the underlying buffer upon scope exit
	inputStream.close();
	return decodedTag;
}

byteArray NbtIo::compress(CompoundTag *tag)
{
	ByteArrayOutputStream baos = ByteArrayOutputStream();
	DataOutputStream dataOut = DataOutputStream(&baos); // Replaced GZIPOutputStream equivalent
	NbtIo::write(tag, &dataOut);

	// Copy compressed data into new byte array
	byteArray output(baos.buf.length);
	for (size_t i = 0; i < baos.buf.length; ++i) {
		output[i] = baos.buf[i];
	}
	dataOut.close();
	return output;
}

CompoundTag *NbtIo::read(DataInput *input)
{
	Tag *parsedTag = Tag::readNamedTag(input);
	if (parsedTag && parsedTag->getId() == Tag::TAG_Compound) {
		return static_cast<CompoundTag*>(parsedTag);
	}
	delete parsedTag;
	return nullptr; // Root must be a named compound tag
}

void NbtIo::write(CompoundTag *tag, DataOutput *output)
{
	Tag::writeNamedTag(tag, output);
}

