        static constexpr const char testStr[] = ":\0:\0: It's unlikely that this string has an ARCADIA_ROOT as its prefix :\0:\0:";
        static constexpr auto testStaticBuf = STATIC_BUF(testStr);

        // Verify StripRoot preserves original content
        UNIT_ASSERT_VALUES_EQUAL(
            TStringBuf(testStr, sizeof(testStr) - 1),
            ::NPrivate::StripRoot(testStaticBuf).As<TStringBuf>()
        );

        // Confirm no root prefix is detected in the test string
        UNIT_ASSERT_VALUES_EQUAL(0, ::NPrivate::RootPrefixLength(testStaticBuf));

        // Test IsProperPrefix behavior with compile-time assertions
        static_assert(::NPrivate::IsProperPrefix(STATIC_BUF("foo"), STATIC_BUF("foobar")), 
                      R"(IsProperPrefix("foo", "foobar") failed)");
        static_assert(!::NPrivate::IsProperPrefix(STATIC_BUF("foobar"), STATIC_BUF("foo")), 
                      R"(IsProperPrefix("foobar", "foo") failed)");
        static_assert(!::NPrivate::IsProperPrefix(STATIC_BUF("name"), STATIC_BUF("name")), 
