void AnvilTile::setPlacedBy(
    Level*               level,
    int                  x,
    int                  y,
    int                  z,
    std::shared_ptr<Mob> placer
) {
    float yaw = placer->yRot;
    int rawDir = Mth::floor(yaw * 4.0f / 360.0f + 0.5f) & 3;
    int damage = level->getData(x, y, z) >> 2;

    // Rotate direction by +1 (clockwise)
    int adjustedDir = (rawDir + 1) % 4;

    // Set facing direction based on computed orientation
    switch (adjustedDir) {
        case 0:
            level->setData(x, y, z, Direction::NORTH | (damage << 2));
            break;
        case 1:
            level->setData(x, y, z, Direction::EAST | (damage << 2));
            break;
        case 2:
            level->setData(x, y, z, Direction::SOUTH | (damage << 2));
            break;
        case 3:
            level->setData(x, y, z, Direction::WEST | (damage << 2));
            break;
    }
}

bool AnvilTile::use(
    Level*                  level,
    int                     x,
    int                     y,
    int                     z,
    std::shared_ptr<Player> user,
    int                     clickedSide,
    float                   hitX,
    float                   hitY,
    float                   hitZ,
    bool                    silentOnly
) {
    if (level->isClientSide) {
        return true;
    }

    user->startRepairing(x, y, z);
    return true;
}

