void AnvilTile::updateShape(
    LevelSource*                level,
    int                         x,
    int                         y,
    int                         z,
    int                         overrideData,
    std::shared_ptr<TileEntity> overrideEntity
) {
    int orientation = level->getData(x, y, z) & 3;

    // Adjust bounding box depending on whether anvil lies along X or Z axis
    if (orientation == Direction::EAST || orientation == Direction::WEST) {
        setShape(0.0f, 0.0f, 2.0f / 16.0f, 1.0f, 1.0f, 1.0f - 2.0f / 16.0f);
    } else {
        setShape(2.0f / 16.0f, 0.0f, 0.0f, 1.0f - 2.0f / 16.0f, 1.0f, 1.0f);
    }
}

