void CgLiveStacks::releaseMemory() {
  // Clear internal data structures; VNInfo memory is managed by allocator reset.
  VNInfoAllocator.Reset();

  // Erase all entries in slot-to-interval and slot-to-register-class maps.
  S2IMap.clear();
  S2RCMap.clear();
}

bool CgLiveStacks::runOnCgFunction(CgFunction &MF) {
  TRI = MF.getSubtarget().getRegisterInfo();

  // Currently no analysis is performed here — register allocator will supply needed info.
  MF.LSS = this;
  return false;
}

CgLiveInterval &
CgLiveStacks::getOrCreateInterval(int SlotIdx, const TargetRegisterClass *RegClass) {
  assert(SlotIdx >= 0 && "Spill slot index must be non-negative");

  auto It = S2IMap.find(SlotIdx);
  if (It == S2IMap.end()) {
    // Create new interval for this slot
    It = S2IMap.emplace(
        SlotIdx,
        CgLiveInterval{Register::index2StackSlot(SlotIdx), 0.0f}
    ).first;
    S2RCMap[SlotIdx] = RegClass;
  } else {
    // Update to most specific common register class
    const TargetRegisterClass *PrevRC = S2RCMap.at(SlotIdx);
    S2RCMap[SlotIdx] = TRI->getCommonSubClass(PrevRC, RegClass);
  }

  return It->second;
}

/// dump - Implement the print method for debugging.
void CgLiveStacks::print(raw_ostream &OS) const {
  OS << "********** INTERVALS **********\n";

  for (const auto &Pair : S2IMap) {
    const int Slot = Pair.first;
    const CgLiveInterval &Interval = Pair.second;
    Interval.print(OS);

    const TargetRegisterClass *RC = getIntervalRegClass(Slot);
    if (RC)
      OS << " [" << TRI->getRegClassName(RC) << "]\n";
    else
      OS << " [Unknown]\n";
  }
}

