// Constants for LEGO Power Functions protocol timing
const uint16_t kLegoPfBitMark = 158;
const uint16_t kLegoPfHdrSpace = 1026;
const uint16_t kLegoPfZeroSpace = 263;
const uint16_t kLegoPfOneSpace = 553;
const uint32_t kLegoPfMinCommandLength = 16000;  // 16ms

#if SEND_LEGOPF
/// Send a LEGO Power Functions infrared command.
/// Status: Beta / Confirmed working.
/// @param[in] payload The data payload to transmit.
/// @param[in] bitCount Number of bits in the payload.
/// @param[in] repeatCount How many times to repeat the transmission.
/// @note When repeatCount > 0, at least five repetitions are sent per specification.
void IRsend::sendLegoPf(const uint64_t payload, const uint16_t bitCount,
                        const uint16_t repeatCount) {
  uint8_t channelIdentifier = ((payload >> (bitCount - 4)) & 0b11) + 1;

  if (repeatCount > 0) {
    // Handle repeated transmission mode
    if (channelIdentifier < 4) {
      space((4 - channelIdentifier) * kLegoPfMinCommandLength);
    }

    // Ensure minimum of 5 repeats as per spec
    uint16_t actualRepeats = std::max(repeatCount, static_cast<uint16_t>(5));
    for (uint16_t i = 0; i < actualRepeats; ++i) {
      // Vary inter-pulse gap based on repetition index and channel
      uint32_t interGap = ((i < 2) ? 5 : (6 + 2 * channelIdentifier)) * kLegoPfMinCommandLength;

      sendGeneric(kLegoPfBitMark, kLegoPfHdrSpace,
                  kLegoPfBitMark, kLegoPfOneSpace,
                  kLegoPfBitMark, kLegoPfZeroSpace,
                  kLegoPfBitMark, kLegoPfHdrSpace,
                  interGap,
                  payload, bitCount, 38000, true, 0, kDutyDefault);
    }
  } else {
    // Single transmission without repetition
    sendGeneric(kLegoPfBitMark, kLegoPfHdrSpace,
                kLegoPfBitMark, kLegoPfOneSpace,
                kLegoPfBitMark, kLegoPfZeroSpace,
                kLegoPfBitMark, kLegoPfHdrSpace,
                kLegoPfMinCommandLength * 5,
                payload, bitCount, 38000, true, 0, kDutyDefault);
  }
}
#endif  // SEND_LEGO

#if DECODE_LEGOPF
/// Decode an incoming LEGO Power Functions signal.
/// Status: Stable / Verified functionality.
/// @param[in,out] decodeData Pointer to storage for decoded results.
/// @param[in] startIndex Starting position in raw buffer for decoding.
/// @param[in] expectedBits Expected number of data bits.
/// @param[in] enforceStrict Whether to enforce strict format validation.
/// @return True if successful decoding occurs, false otherwise.
bool IRrecv::decodeLegoPf(decode_results* decodeData, uint16_t startIndex,
                          const uint16_t expectedBits, const bool enforceStrict) {
  // Validate expected bit count if strict mode is enabled
  if (enforceStrict && expectedBits != kLegoPfBits) return false;

  uint64_t extractedData = 0;

  // Attempt generic matching of header, data, and footer
  if (!matchGeneric(decodeData->rawbuf + startIndex, &extractedData,
                    decodeData->rawlen - startIndex, expectedBits,
                    kLegoPfBitMark, kLegoPfHdrSpace,
                    kLegoPfBitMark, kLegoPfOneSpace,
                    kLegoPfBitMark, kLegoPfZeroSpace,
                    kLegoPfBitMark, kLegoPfMinCommandLength,
                    true)) {
    return false;
  }

  // Perform LRC verification when strict mode is active
  if (enforceStrict) {
    uint16_t lrcCheckValue = extractedData;
    uint8_t calculatedLRC = 0xF;
    for (uint8_t j = 0; j < 4; ++j) {
      calculatedLRC ^= (lrcCheckValue & 0xF);
      lrcCheckValue >>= 4;
    }
    if (calculatedLRC != 0) return false;
  }

  // Populate decoded result structure
  decodeData->decode_type = LEGOPF;
  decodeData->bits = expectedBits;
  decodeData->value = extractedData;
  decodeData->address = ((extractedData >> (expectedBits - 4)) & 0b11) + 1;  // Channel ID
  decodeData->command = (extractedData >> 4) & 0xFF;  // Command field between channel and LRC

  return true;
}
#endif  // DECODE_LEGOPF

