int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    long long total_points;
    if (!(std::cin >> total_points)) return 0;

    // Compute grid dimension as ceiling of square root
    long long grid_size = static_cast<long long>(std::ceil(std::sqrt(static_cast<long double>(total_points))));
    double grid_dim = static_cast<double>(grid_size);

    std::cout.setf(std::ios::fixed);
    std::cout << std::setprecision(6) << grid_dim << "\n";

    long long printed_count = 0;
    for (long long row = 0; row < grid_size && printed_count < total_points; ++row) {
        for (long long col = 0; col < grid_size && printed_count < total_points; ++col) {
            double x_coord = static_cast<double>(col) + 0.5;
            double y_coord = static_cast<double>(row) + 0.5;
            double angle_val = 0.0;

            std::cout << x_coord << " " << y_coord << " " << angle_val << "\n";
            ++printed_count;
        }
    }

    return 0;
}

