// Alternative implementation for getting and setting the x87 FPU control word
// using inline assembly, with memory sanitizer exclusion when applicable.

#if defined(_Py_MEMORY_SANITIZER) && !defined(__clang__)
__attribute__((no_sanitize_memory))
#endif
unsigned short _Py_get_387controlword(void) {
    unsigned short control_word;
    __asm__ __volatile__ ("fnstcw %0" : "=m" (control_word));
    return control_word;
}

void _Py_set_387controlword(unsigned short control_word) {
    __asm__ __volatile__ ("fldcw %0" : : "m" (control_word));
}

#endif  // HAVE_GCC_ASM_FOR_X87

