#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <assert.h>
#include "dds/dds.h"

// Built-in topics used for monitoring endpoint discovery
static const dds_entity_t builtin_ep_topics[] = {
    DDS_BUILTIN_TOPIC_DCPSPUBLICATION,
    DDS_BUILTIN_TOPIC_DCPSSUBSCRIPTION
};

// Helper to format a topic key into a human-readable string
struct formatted_key {
    char buffer[36]; // e.g., "12345678:90abcdef:12345678:90abcdef"
};

static char* format_topic_key(struct formatted_key *buf, const dds_builtintopic_topic_key_t *key) {
    (void) snprintf(buf->buffer, sizeof(buf->buffer),
                    "%02x%02x%02x%02x:%02x%02x%02x%02x:"
                    "%02x%02x%02x%02x:%02x%02x%02x%02x",
                    key->d[0],  key->d[1],  key->d[2],  key->d[3],
                    key->d[4],  key->d[5],  key->d[6],  key->d[7],
                    key->d[8],  key->d[9],  key->d[10], key->d[11],
                    key->d[12], key->d[13], key->d[14], key->d[15]);
    return buf->buffer;
}

// Convert instance state enum to readable string
static const char* get_instance_state_label(dds_instance_state_t state) {
    switch (state) {
        case DDS_ALIVE_INSTANCE_STATE:             return "alive";
        case DDS_NOT_ALIVE_NO_WRITERS_INSTANCE_STATE: return "nowriters";
        case DDS_NOT_ALIVE_DISPOSED_INSTANCE_STATE:   return "disposed";
    }
    assert(false && "Unexpected instance state");
    return "";
}

// Process DCPSTopic samples; returns true if any non-builtin topic was found
static bool check_discovered_topics(dds_entity_t cond) {
#define MAX_SAMPLES 10
    void* sample_list[MAX_SAMPLES] = { NULL };
    dds_sample_info_t info_list[MAX_SAMPLES];

    int32_t count = dds_take(cond, sample_list, info_list, MAX_SAMPLES, MAX_SAMPLES);
    bool found_app_topic = false;

    for (int32_t idx = 0; idx < count; ++idx) {
        dds_builtintopic_topic_t const* topic = (dds_builtintopic_topic_t const*)sample_list[idx];
        struct formatted_key key_str;
        printf("%s: %s", get_instance_state_label(info_list[idx].instance_state),
               format_topic_key(&key_str, &topic->key));

        if (info_list[idx].valid_data) {
            printf(" %s %s", topic->topic_name, topic->type_name);
            if (strncmp(topic->topic_name, "DCPS", 4) != 0) {
                found_app_topic = true;
            }
        }
        printf("\n");
    }

    (void) dds_return_loan(cond, sample_list, count);
#undef MAX_SAMPLES
    return found_app_topic;
}

// Check if any non-built-in endpoints exist across publication/subscription topics
static bool check_builtin_endpoints(const dds_entity_t ep_conditions[]) {
    bool found_endpoint = false;

    for (size_t i = 0; i < sizeof(builtin_ep_topics)/sizeof(builtin_ep_topics[0]) && !found_endpoint; ++i) {
        void* single_sample = NULL;
        dds_sample_info_t info;
        int32_t taken = dds_take(ep_conditions[i], &single_sample, &info, 1, 1);

        if (taken > 0 && info.valid_data) {
            dds_builtintopic_endpoint_t const* ep = (dds_builtintopic_endpoint_t const*)single_sample;
            if (strncmp(ep->topic_name, "DCPS", 4) != 0) {
                found_endpoint = true;
            }
        }

        (void) dds_return_loan(ep_conditions[i], &single_sample, taken);
    }

    return found_endpoint;
}

int main(int argc, char** argv) {
    (void)argc;
    (void)argv;

    // Create participant
    dds_entity_t part = dds_create_participant(DDS_DOMAIN_DEFAULT, NULL, NULL);
    if (part < 0) {
        fprintf(stderr, "dds_create_participant failed: %s\n", dds_strretcode(part));
        return 1;
    }

    // Create waitset
    dds_entity_t ws = dds_create_waitset(part);
    if (ws < 0) {
        fprintf(stderr, "dds_create_waitset failed: %s\n", dds_strretcode(ws));
        dds_delete(part);
        return 1;
    }

    // Set up reader + condition for DCPSTopic
    dds_entity_t topic_reader = dds_create_reader(part, DDS_BUILTIN_TOPIC_DCPSTOPIC, NULL, NULL);
    if (topic_reader < 0) {
        if (topic_reader == DDS_RETCODE_UNSUPPORTED)
            fprintf(stderr, "Topic discovery not compiled in. Rebuild with ENABLE_TOPIC_DISCOVERY=ON\n");
        else
            fprintf(stderr, "Failed to create DCPSTopic reader: %s\n", dds_strretcode(topic_reader));
        dds_delete(part);
        return 1;
    }

    dds_entity_t topic_cond = dds_create_readcondition(topic_reader, DDS_ANY_STATE);
    (void) dds_waitset_attach(ws, topic_cond, 0);

    // Set up readers + conditions for DCPSPublication/Subscription
    dds_entity_t ep_readers[sizeof(builtin_ep_topics)/sizeof(builtin_ep_topics[0])];
    dds_entity_t ep_conds[sizeof(builtin_ep_topics)/sizeof(builtin_ep_topics[0])];

    for (size_t i = 0; i < sizeof(builtin_ep_topics)/sizeof(builtin_ep_topics[0]); ++i) {
        ep_readers[i] = dds_create_reader(part, builtin_ep_topics[i], NULL, NULL);
        ep_conds[i] = dds_create_readcondition(ep_readers[i], DDS_ANY_STATE);
        (void) dds_waitset_attach(ws, ep_conds[i], 0);
    }

    // Monitoring flags
    bool app_topic_found = false;
    bool app_endpoint_found = false;

    // Run monitoring for 10 seconds
    const dds_time_t deadline = dds_time() + DDS_SECS(10);

    while (dds_waitset_wait_until(ws, NULL, 0, deadline) > 0) {
        if (!app_topic_found && check_discovered_topics(topic_cond)) {
            app_topic_found = true;
        }

        if (!app_endpoint_found && check_builtin_endpoints(ep_conds)) {
            app_endpoint_found = true;

            // Clean up monitoring readers now that we know endpoints exist
            for (size_t i = 0; i < sizeof(ep_readers)/sizeof(ep_readers[0]); ++i) {
                (void) dds_delete(ep_readers[i]);
            }
        }

        // Early exit if both are confirmed
        if (app_topic_found && app_endpoint_found) break;
    }

    // Final warning if only endpoints were seen
    if (!app_topic_found && app_endpoint_found) {
        fprintf(stderr, "No topics discovered, but remote endpoints detected.\n"
                        "Is topic discovery enabled in your configuration?\n");
    }

    dds_delete(part);
    return 0;
}

