#include <TranslatorRoster.h>
#include <TranslatorFormats.h>
#include <DataIO.h>
#include <File.h>
#include <Entry.h>
#include <Message.h>
#include <iostream>

int main() {
    // Open the Markdown input file in read-only mode
    BFile inputMarkdown("./sample.md", B_READ_ONLY);
    if (inputMarkdown.InitCheck() != B_OK) {
        std::cerr << "Error: Unable to open sample.md for reading\n";
        return 1;
    }

    // Create or overwrite the output text file
    BFile outputTxt("./sample.txt", B_CREATE_FILE | B_ERASE_FILE | B_WRITE_ONLY);
    if (outputTxt.InitCheck() != B_OK) {
        std::cerr << "Error: Unable to create sample.txt for writing\n";
        return 1;
    }

    // Retrieve the default translator roster
    BTranslatorRoster* roster = BTranslatorRoster::Default();
    if (!roster) {
        std::cerr << "Error: Could not access the default translator roster\n";
        return 1;
    }

    // Set up message with file metadata for identification
    BMessage fileInfo;
    fileInfo.AddString("name", "./sample.md");
    fileInfo.AddString("BEOS:TYPE", "text/markdown");

    translator_info info;
    status_t identifyResult = roster->Identify(&inputMarkdown, &fileInfo, &info);

    if (identifyResult == B_OK) {
        const char* translatorName = nullptr;
        const char* translatorDesc = nullptr;
        int32 translatorVersion = 0;

        // Fetch detailed information about the selected translator
        if (roster->GetTranslatorInfo(info.translator, &translatorName, &translatorDesc, &translatorVersion) == B_OK) {
            std::cout << "Selected translator: " << translatorName 
                      << " (v" << translatorVersion << ")\n";
            std::cout << "Description: " << translatorDesc << "\n";
        } else {
            std::cerr << "Warning: Failed to retrieve translator details\n";
        }
    } else {
        std::cerr << "Error: Translation format identification failed (code: " 
                  << identifyResult << ")\n";
        return 1;
    }

    // Rewind the input file to the beginning before translation
    inputMarkdown.Seek(0, SEEK_SET);

    // Perform the actual translation from Markdown to plain text
    status_t translateStatus = roster->Translate(
        &inputMarkdown, 
        nullptr, 
        &fileInfo, 
        &outputTxt, 
        B_TRANSLATOR_TEXT
    );

    if (translateStatus != B_OK) {
        std::cerr << "Translation process failed with error code: " 
                  << translateStatus << "\n";
        return 1;
    } else {
        std::cout << "Success: Translated content saved to sample.txt\n";
    }

    return 0;
}

