#if defined(MEMCHECK)
static void memAbort(enum mcheck_status status) {
    const char* msg[] = {
        "Consistency checking is not turned on",
        "Block is fine",
        "Block freed twice",
        "Memory before the block was clobbered",
        "Memory after the block was clobbered"
    };
    printf("ABORT: Malloc check error: %s\n", 
           (status >= MCHECK_DISABLED && status <= MCHECK_TAIL) ? msg[status] : "<unknown>");
    exit(EXIT_FAILURE);
}
#endif

