// Main entry point — rewritten with equivalent logic but different variable naming and structure
int main(int argc, char* argv[], char* envp[]) {
#if defined(MEMCHECK)
    int rc = mcheck_pedantic(&memAbort);
    std::cout << "DEBUG: mcheck_pedantic returns " << rc << std::endl;
#endif

    try {
        DeltaresHydro* dhInstance = new DeltaresHydro(argc, argv, envp);
        if (!dhInstance->isReady()) {
            delete dhInstance;
            return EXIT_FAILURE;
        }

        dhInstance->execute();
        delete dhInstance;
        return EXIT_SUCCESS;
    }
    catch (const std::exception& ex) {
        std::cerr << "d_hydro ABORT: C++ Exception: " << ex.what() << std::endl;
        return EXIT_FAILURE;
    }
    catch (Exception* ex) {
        std::cerr << "d_hydro ABORT: " << ex->getMessage() << std::endl;
        delete ex;
        return EXIT_FAILURE;
    }
    catch (char const* str) {
        std::cerr << "ABORT in FLOW2D3D: " << str << std::endl;
        return EXIT_FAILURE;
    }
}

