      clock(nullptr), log(nullptr), config(nullptr), configfile(nullptr),
      start(nullptr), startComponent(nullptr), mainArgs(nullptr), ready(false) {

    exePath = strdup(argv[0]);

#if defined(HAVE_CONFIG_H)
    exeName = strdup(basename(argv[0]));
#else
    exeName = new char[1024];
    _splitpath(argv[0], nullptr, nullptr, exeName, nullptr);
#endif

    // Reconstruct command line arguments
    size_t totalLen = 0;
    for (int i = 1; i < argc; ++i)
        totalLen += strlen(argv[i]) + 1;

    mainArgs = new char[totalLen + 1];
    memset(mainArgs, 0, totalLen + 1);
    char* pos = mainArgs;
    for (int i = 1; i < argc; ++i) {
        size_t len = strlen(argv[i]);
        memcpy(pos, argv[i], len);
        pos += len;
        *pos++ = ' ';
    }

    // Parse options
    int opt;
    int logMask = static_cast<int>(Log::ALWAYS);
    FILE* logFile = stdout;

    while ((opt = getopt(argc, argv, "d:l:S:v?")) != -1) {
        switch (opt) {
            case 'd': {
                if (sscanf(optarg, "%i", &logMask) != 1)
                    throw new Exception("Invalid log mask (-d option)");
                break;
            }
            case 'l': {
                logFile = fopen(optarg, "w");
                if (!logFile)
                    throw new Exception("Cannot create log file \"%s\"", optarg);
                break;
            }
            case 'S': {
                slaveArg = optarg;
                break;
            }
            case 'v': {
                printAbout(exeName);
                done = true;
                return;
            }
            case '?': {
                printUsage(exeName);
                done = true;
                return;
            }
            default: {
                throw new Exception("Invalid command-line argument. Run \"%s -?\" for help.", exeName);
            }
        }
    }

    if (argc - optind != 1)
        throw new Exception("Improper usage. Run \"%s -?\" for help.", exeName);

    configfile = argv[optind];
    FILE* cfg = strcmp(configfile, "-") == 0 ? stdin : fopen(configfile, "r");
    if (!cfg)
        throw new Exception("Cannot open configuration file \"%s\"", configfile);

    config = new XmlTree(cfg);
    fclose(cfg);

    XmlTree* root = config->Lookup("/deltaresHydro");
    if (!root)
        throw new Exception("Configuration file \"%s\" lacks deltaresHydro root element", configfile);

    const char* starterName = "flow2D3D";
    start = root->Lookup(starterName);
    if (!start)
        throw new Exception("Missing configuration for start component \"%s\"", starterName);

#if defined(MONOLITHIC_FLOW2D3D)
    ready = FLOW2D3D_MonolithicInit(this);
#else
    XmlTree* libElem = start->Lookup("library");
    if (!libElem)
        throw new Exception("Start component \"%s\" missing library element", starterName);

    const char* libName = libElem->charData;

#if defined(HAVE_CONFIG_H)
#if defined(OSX)
    throw new Exception("ABORT: %s not yet supported on macOS", exeName);
#else
    char fullLib[512];
    if (strchr(libName, '/') == nullptr && strchr(libName, '.') == nullptr) {
        snprintf(fullLib, sizeof(fullLib), "lib%s.so", libName);
        libName = fullLib;
    }
    void* handle = dlopen(libName, RTLD_LAZY);
    if (!handle)
        throw new Exception("Failed to load library \"%s\": %s", libName, dlerror());
    // Assume symbol name known at compile time
    typedef bool (*EntryPoint)(DeltaresHydro*);
    EntryPoint ep = (EntryPoint)dlsym(handle, "FLOW2D3D_StartComponentEntry");
    if (!ep)
        throw new Exception("Symbol not found in library \"%s\"", libName);
    ready = ep(this);
#endif
#elif defined(WIN32)
    char libBuf[512];
    if (strchr(libName, '/') == nullptr && strchr(libName, '\\') == nullptr && strchr(libName, '.') == nullptr) {
        snprintf(libBuf, sizeof(libBuf), "%s.dll", libName);
        libName = libBuf;
    }
    HMODULE hMod = LoadLibraryA(libName);
    if (!hMod)
        throw new Exception("Failed to load DLL \"%s\": %lu", libName, GetLastError());

    using EntryFunc = bool(__cdecl*)(DeltaresHydro*);
    EntryFunc ep = (EntryFunc)GetProcAddress(hMod, "FLOW2D3D_StartComponentEntry");
    if (!ep)
        throw new Exception("Entry point not found in DLL \"%s\": %lu", libName, GetLastError());

    ready = ep(this);
    FreeLibrary(hMod);
#endif
#endif // MONOLITHIC_FLOW2D3D
}

//------------------------------------------------------------------------------
DeltaresHydro::~DeltaresHydro() {
    if (done) return;

    delete startComponent;
#if defined(HAVE_CONFIG_H)
    free(exeName);
#else
    delete[] exeName;
#endif
    delete clock;
    delete config;
    free(exePath);
    delete log;
    delete[] mainArgs;
}

//------------------------------------------------------------------------------
void DeltaresHydro::execute() {
    if (done) return;
    try {
        startComponent->Run();
    } catch (Exception* ex) {
        std::cerr << "#### d_hydro ABORT: " << ex->getMessage() << std::endl;
        delete ex;
    }
}

