//-*****************************************************************************
void CreateTestFile(const std::string &filename)
{
    AbcA::MetaData md;
    md.setUnique("name", "arkive");
    Alembic::AbcCoreOgawa::WriteArchive aw;
    AbcA::ArchiveWriterPtr archive = aw(filename, md);

    AbcA::ObjectWriterPtr root = archive->getTop();
    AbcA::ObjectWriterPtr deepestChild;

    // Build nested object hierarchy
    {
        md.set("name", "obj0");
        AbcA::ObjectWriterPtr child1 = root->createChild(AbcA::ObjectHeader("child0", md));

        md.set("name", "obj1");
        AbcA::ObjectWriterPtr child2 = child1->createChild(AbcA::ObjectHeader("child1", md));

        md.set("name", "obj2");
        deepestChild = child2->createChild(AbcA::ObjectHeader("child2", md));
    }

    // Prepare array property writer
    AbcA::CompoundPropertyWriterPtr props = deepestChild->getProperties();
    const AbcA::TimeSamplingType cyclicType(2, 2.0);
    const size_t sampleCount = 50;
    const Dimensions dims(sampleCount);
    const AbcA::DataType int32Type(Alembic::Util::kInt32POD, 1);

    // First array property with cyclic sampling
    AbcA::PropertyHeader arrHeader("intArrayProp", AbcA::kArrayProperty,
                                   AbcA::MetaData(), int32Type, cyclicType);
    AbcA::ArrayPropertyWriterPtr arrWriter = props->createArrayProperty(arrHeader);

    // Generate and write samples for first array property
    for (int s = 0; s < 7; ++s) {
        std::vector<int32_t> data;
        size_t len = (s == 1) ? 30 : (s == 5) ? 2 : (s == 6) ? 78 : sampleCount;
        for (size_t i = 0; i < len; ++i) {
            data.push_back(static_cast<int32_t>(i + s));
        }
        AbcA::ArraySample samp((const void*)data.data(), int32Type, Dimensions(len));
        arrWriter->setSample(s, static_cast<AbcA::chrono_t>(s), samp);
    }

    // Second array property with acyclic sampling
    AbcA::PropertyHeader acycHeader("secondArrayProp", AbcA::kArrayProperty,
                                    AbcA::MetaData(), int32Type,
                                    AbcA::TimeSamplingType(AbcA::TimeSamplingType::kAcyclic));
    AbcA::ArrayPropertyWriterPtr acycWriter = props->createArrayProperty(acycHeader);

    std::vector<int32_t> acycData0 = {0, 1};
    acycWriter->setSample(0, 0.0f, AbcA::ArraySample((const void*)acycData0.data(),
                                                     int32Type, Dimensions(2)));

    std::vector<int32_t> acycData1;
    for (int i = 0; i < 10; ++i) acycData1.push_back(i + 1);
    acycWriter->setSample(1, 0.5f, AbcA::ArraySample((const void*)acycData1.data(),
                                                     int32Type, Dimensions(10)));

    std::vector<int32_t> acycData2;
    for (int i = 0; i < 23; ++i) acycData2.push_back(i + 2);
    acycWriter->setSample(2, 2.3f, AbcA::ArraySample((const void*)acycData2.data(),
                                                     int32Type, Dimensions(23)));

    // Scalar property
    AbcA::PropertyHeader scalarHeader("scalarProp", AbcA::kScalarProperty,
                                      AbcA::MetaData(),
                                      AbcA::DataType(Alembic::Util::kFloat32POD, 1),
                                      cyclicType);
    AbcA::ScalarPropertyWriterPtr scalarWriter = props->createScalarProperty(scalarHeader);
    float value = 42.0f;
    scalarWriter->setSample(0, 0.0f, &value);
}

//-*****************************************************************************
void ReadTestFile(const std::string &filename)
{
    Alembic::AbcCoreOgawa::ReadArchive ar;
    AbcA::ArchiveReaderPtr archive = ar(filename);

    // Navigate to the deepest object
    AbcA::ObjectReaderPtr currentObj = archive->getTop();
    while (currentObj->getNumChildren() > 0) {
        currentObj = currentObj->getChild(0);
    }

    std::cout << "Reached final object: " << currentObj->getFullName() << std::endl;
    AbcA::CompoundPropertyReaderPtr props = currentObj->getProperties();
    std::cout << "Properties count: " << props->getNumProperties() << std::endl;

    // Locate properties by name
    AbcA::ScalarPropertyReaderPtr scalarProp;
    AbcA::ArrayPropertyReaderPtr arrayProp0;
    AbcA::ArrayPropertyReaderPtr arrayProp1;

    for (size_t i = 0; i < props->getNumProperties(); ++i) {
        AbcA::BasePropertyReaderPtr prop = props->getProperty(i);
        std::cout << "Found property: " << prop->getName() << std::endl;

        if (prop->isScalar()) {
            scalarProp = prop->asScalarPtr();
        } else if (prop->isArray()) {
            if (prop->getName() == "intArrayProp") {
                arrayProp0 = prop->asArrayPtr();
            } else if (prop->getName() == "secondArrayProp") {
                arrayProp1 = prop->asArrayPtr();
            }
        }
    }

    // Verify scalar property
    for (size_t s = 0; s < scalarProp->getNumSamples(); ++s) {
        float val = 0.0f;
        scalarProp->getSample(s, &val);
        TESTING_ASSERT(val == 42.0f);
        std::cout << scalarProp->getName() << " at sample " << s << ": " << val << std::endl;
    }

    // Process cyclic array property
    std::cout << "\nCyclic Array Property:" << std::endl;
    for (size_t s = 0; s < arrayProp0->getNumSamples(); ++s) {
        AbcA::ArraySamplePtr sample;
        arrayProp0->getSample(s, sample);
        const AbcA::TimeSampling ts = arrayProp0->getTimeSampling();
        size_t numElems = sample->getDimensions().numPoints();

        TESTING_ASSERT(ts.getSampleTime(s) == static_cast<AbcA::chrono_t>(s));
        std::cout << "Sample " << s << " at time " << ts.getSampleTime(s)
                  << " has " << numElems << " elements: ";

        int32_t* data = static_cast<int32_t*>(sample->getData());
        for (size_t j = 0; j < numElems; ++j) {
            TESTING_ASSERT(data[j] == static_cast<int32_t>(s + j));
            std::cout << data[j] << " ";
        }
        std::cout << std::endl;
        sample->reset();
    }

    // Process acyclic array property
    std::cout << "\nAcyclic Array Property:" << std::endl;
    for (size_t s = 0; s < arrayProp1->getNumSamples(); ++s) {
        AbcA::ArraySamplePtr sample;
        arrayProp1->getSample(s, sample);
        const AbcA::TimeSampling ts = arrayProp1->getTimeSampling();
        size_t numElems = sample->getDimensions().numPoints();

        std::cout << "Sample " << s << " at time " << ts.getSampleTime(s)
                  << " has " << numElems << " elements: ";

        int32_t* data = static_cast<int32_t*>(sample->getData());
        for (size_t j = 0; j < numElems; ++j) {
            TESTING_ASSERT(data[j] == static_cast<int32_t>(s + j));
            std::cout << data[j] << " ";
        }
        std::cout << std::endl;
        sample->reset();
    }
}

//-*****************************************************************************
int main(int, char**)
{
    const std::string archiveName("testArchive.abc");
    CreateTestFile(archiveName);
    ReadTestFile(archiveName);
    return 0;
}

