// Test constructor, getters, and setters for role classes
TEST(RoleTest, constructor_getter_setter) {
  RoleBase role_obj;
  EXPECT_EQ(role_obj.timestamp_ns(), 0);
  role_obj.set_timestamp_ns(123);
  EXPECT_EQ(role_obj.timestamp_ns(), 123);

  RoleWriter writer_obj;
  EXPECT_EQ(writer_obj.timestamp_ns(), 0);

  RoleServer server_obj;
  EXPECT_EQ(server_obj.timestamp_ns(), 0);

  RoleAttributes attrs;
  attrs.set_host_name("caros");
  attrs.set_process_id(12345);
  role_obj.set_attributes(attrs);
  EXPECT_EQ(role_obj.attributes().host_name(), "caros");
  EXPECT_EQ(role_obj.attributes().process_id(), 12345);

  RoleBase role_obj2(attrs, 321);
  EXPECT_EQ(role_obj2.timestamp_ns(), 321);

  RoleWriter writer_obj2(attrs, 321);
  EXPECT_EQ(writer_obj2.timestamp_ns(), 321);

  RoleServer server_obj2(attrs, 321);
  EXPECT_EQ(server_obj2.timestamp_ns(), 321);
}

// Test timestamp comparison logic: IsEarlierThan
TEST(RoleTest, is_earlier_than) {
  RoleBase role_first;
  role_first.set_timestamp_ns(123);
  RoleBase role_second;
  role_second.set_timestamp_ns(456);

  EXPECT_TRUE(role_first.IsEarlierThan(role_second));
  EXPECT_FALSE(role_second.IsEarlierThan(role_first));
}

// Test RoleBase matching behavior based on attributes
TEST(RoleTest, rolebase_match) {
  RoleAttributes base_attrs;
  base_attrs.set_host_name("caros");
  base_attrs.set_process_id(12345);
  base_attrs.set_node_id(1);

  RoleBase role_instance(base_attrs, 1234567);

  RoleAttributes match_attrs;
  EXPECT_TRUE(role_instance.Match(match_attrs));

  match_attrs.set_host_name("sorac");
  EXPECT_FALSE(role_instance.Match(match_attrs));

  match_attrs.set_host_name("caros");
  EXPECT_TRUE(role_instance.Match(match_attrs));

  match_attrs.set_process_id(54321);
  EXPECT_FALSE(role_instance.Match(match_attrs));

  match_attrs.set_process_id(12345);
  EXPECT_TRUE(role_instance.Match(match_attrs));

  match_attrs.set_node_id(2);
  EXPECT_FALSE(role_instance.Match(match_attrs));

  match_attrs.set_node_id(1);
  EXPECT_TRUE(role_instance.Match(match_attrs));
}

// Test RoleWriter matching with channel and id fields
TEST(RoleTest, rolewriter_match) {
  RoleAttributes base_attrs;
  base_attrs.set_host_name("caros");
  base_attrs.set_process_id(12345);
  base_attrs.set_node_id(1);

  RoleAttributes target_attrs(base_attrs);
  base_attrs.set_channel_id(2);
  base_attrs.set_id(3);

  RoleWriter writer_instance(base_attrs, 1234567);

  EXPECT_TRUE(writer_instance.Match(target_attrs));

  target_attrs.set_id(4);
  EXPECT_FALSE(writer_instance.Match(target_attrs));

  target_attrs.set_id(3);
  EXPECT_TRUE(writer_instance.Match(target_attrs));

  target_attrs.set_channel_id(3);
  EXPECT_FALSE(writer_instance.Match(target_attrs));

  target_attrs.set_channel_id(2);
  EXPECT_TRUE(writer_instance.Match(target_attrs));
}

// Test RoleServer matching with service_id field
TEST(RoleTest, roleserver_match) {
  RoleAttributes base_attrs;
  base_attrs.set_host_name("caros");
  base_attrs.set_process_id(12345);
  base_attrs.set_node_id(1);

  RoleAttributes target_attrs(base_attrs);
