// Helper macros for min/max operations
#ifndef min
#  define min(a,b) ((a) < (b) ? (a) : (b))
#  define max(a,b) ((a) > (b) ? (a) : (b))
#endif

// Platform-specific includes and definitions
#if defined(_WIN32)
#  include <windows.h>
#elif defined(__linux__)
#  include <dlfcn.h>
