// Type definitions based on platform
#if defined(_WIN32)
    typedef HMODULE DllHandle;
#elif defined(__linux__)
    typedef void* DllHandle;
#endif

struct SharedDLL {
    DllHandle dllHandle;
};

// String utility functions
char* strFcpy(char* str_1, int len) {
    int m = min(len, static_cast<int>(strlen(str_1)));
    char* str_2 = new char[m + 1];
    strncpy(str_2, str_1, m);
    str_2[m] = '\0';
    return str_2;
}

void RemoveTrailingBlanks_dll(char* String) {
    int i = strlen(String) - 1;
    while (i >= 0 && (String[i] == ' ' || String[i] == '\n' || String[i] == '\t')) {
        String[i] = '\0';
        i--;
    }
}

// Open shared library function
extern "C" long openSharedLibrary(long* sharedDLLHandle, char* library, long length_lib) {
    long error = 1;
    SharedDLL* tmpSharedDLL = nullptr;
    char* lib_name = strFcpy(library, length_lib);
    *sharedDLLHandle = 0;
    RemoveTrailingBlanks_dll(lib_name);

    tmpSharedDLL = new SharedDLL();

#if defined(_WIN32)
    tmpSharedDLL->dllHandle = LoadLibraryA(lib_name);
#elif defined(__linux__)
    tmpSharedDLL->dllHandle = dlopen(lib_name, RTLD_LAZY);
#endif

    if (tmpSharedDLL->dllHandle != nullptr) {
        error = 0;
        *sharedDLLHandle = reinterpret_cast<long>(tmpSharedDLL);
    }

    delete[] lib_name;
    return error;
}

// Close shared library function
extern "C" long closeSharedLibrary(long* sharedDLLHandle) {
    SharedDLL* sharedDLL = reinterpret_cast<SharedDLL*>(*sharedDLLHandle);

#if defined(_WIN32)
    FreeLibrary(sharedDLL->dllHandle);
#elif defined(__linux__)
    dlclose(sharedDLL->dllHandle);
#endif

    delete sharedDLL;
    return 0;
}

// Perform function from shared library
extern "C" long performFunction(
    long* sharedDLLHandle,
    char* function,
    long* sobekfirst,
    long* sobekdate,
    long* sobektime,
    long* sobektimestepsize,
    long* maxsobek,
    double* dllsobekh,
    double* dllsobekq,
    double* dllsobeksa,
    double* dllsobekwd,
    double* dllsobekcl,
    double* dllsobekcw,
    double* dllsobekgl,
    double* dllsobekgo,
    double* dllsobekfa,
    double* dllsobekqs,
    double* dllsobekvs,
    double* dllsobekhu,
    double* dllsobekhd,
    double* dllsobekdh,
    double* dllsobekpd,
    double* dllsobekpc,
    double* dllsobek1d2dbl,
    double* dllsobek1d2du,
    double* dllsobek1d2dv,
    double* dllsobek1d2dc,
    double* dllsobekvr,
    long* maxrr,
    double* dllrrh,
    long* maxrain,
    double* dllrainh,
    long* maxd3d,
    double* dlld3dh,
    double* dlld3dsal,
    long* maxlocwq,
    long* maxparwq,
    double** dllsobekwq,
    long* maxsetpoints,
    double* dllsobekc,
    double* dllsobeks,
    long* returncode,
    char** dllidsbr,
    char** dllidd3b,
    char** dllidpre,
    char** dllidd3d,
    char** dlllocidwq,
    char** dllparidwq,
    char** dllmeasid,
    long length_function,
    long length_dllidsbr,
    long length_dllidd3b,
    long length_dllidpre,
    long length_dllidd3d,
    long length_dlllocidwq,
    long length_dllparidwq,
    long length_dllmeasid) {

    long error = 1;
    SharedDLL* sharedDLL = reinterpret_cast<SharedDLL*>(*sharedDLLHandle);
    char* fun_name = strFcpy(function, length_function);
    RemoveTrailingBlanks_dll(fun_name);

    // Function pointer type definition
    typedef void* (*MyProc)(
        long*, long*, long*, long*, long*,
        double*, double*, double*, double*, double*, double*, double*, double*, double*, double*,
        double*, double*, double*, double*, double*, double*,
        double*, double*, double*, double*, double*,
        long*, double*,
        long*, double*,
        long*, double*, double*,
        long*, long*, double**,
        long*, double*, double*, long*,
        char**, char**, char**, char**, char**, char**, char**,
        long, long, long, long, long, long, long);

    MyProc proc = nullptr;

#if defined(_WIN32)
    proc = reinterpret_cast<MyProc>(GetProcAddress(sharedDLL->dllHandle, fun_name));
#elif defined(__linux__)
    proc = reinterpret_cast<MyProc>(dlsym(sharedDLL->dllHandle, fun_name));
#endif

    if (proc != nullptr) {
        error = 0;
        // Call the actual function
        proc(sobekfirst, sobekdate, sobektime, sobektimestepsize, maxsobek,
             dllsobekh, dllsobekq, dllsobeksa, dllsobekwd, dllsobekcl, dllsobekcw, dllsobekgl, dllsobekgo, dllsobekfa, dllsobekqs,
             dllsobekvs, dllsobekhu, dllsobekhd, dllsobekdh, dllsobekpd, dllsobekpc,
             dllsobek1d2dbl, dllsobek1d2du, dllsobek1d2dv, dllsobek1d2dc, dllsobekvr,
             maxrr, dllrrh,
             maxrain, dllrainh,
             maxd3d, dlld3dh, dlld3dsal,
             maxlocwq, maxparwq, dllsobekwq,
             maxsetpoints, dllsobekc, dllsobeks, returncode,
             dllidsbr, dllidd3b, dllidpre, dllidd3d, dlllocidwq, dllparidwq, dllmeasid,
             length_dllidsbr, length_dllidd3b, length_dllidpre,
             length_dllidd3d, length_dlllocidwq, length_dllparidwq, length_dllmeasid);
    }

    delete[] fun_name;
    return error;
}

