void expose_nvls_interface(nb::module_& module) {
  // Expose DeviceMulticastPointer and its nested types
  nb::class_<NvlsConnection::DeviceMulticastPointer>(module, "DeviceMulticastPointer")
      .def("get_device_ptr",
           [](NvlsConnection::DeviceMulticastPointer* self) { 
             return static_cast<uintptr_t>(reinterpret_cast<std::uintptr_t>(self->getDevicePtr())); 
           })
      .def("device_handle", &NvlsConnection::DeviceMulticastPointer::deviceHandle);

  nb::class_<NvlsConnection::DeviceMulticastPointer::DeviceHandle>(module, "DeviceHandle")
      .def(nb::init<>())
      .def_rw("devicePtr", &NvlsConnection::DeviceMulticastPointer::DeviceHandle::devicePtr)
      .def_rw("mcPtr", &NvlsConnection::DeviceMulticastPointer::DeviceHandle::mcPtr)
      .def_rw("size", &NvlsConnection::DeviceMulticastPointer::DeviceHandle::bufferSize)
      .def_prop_ro("raw", [](const NvlsConnection::DeviceMulticastPointer::DeviceHandle& handle) -> nb::bytes {
        return nb::bytes(reinterpret_cast<const char*>(&handle), sizeof(handle));
      });

  // Expose NvlsConnection class
  nb::class_<NvlsConnection>(module, "NvlsConnection")
      .def("bind_allocated_memory", &NvlsConnection::bindAllocatedMemory,
           nb::arg("devicePtr"), nb::arg("size"))
      .def("get_multicast_min_granularity", &NvlsConnection::getMultiCastMinGranularity);

  // Expose the standalone connect function
  module.def("connect_nvls_collective", &connectNvlsCollective,
             nb::arg("communicator"), nb::arg("allRanks"), nb::arg("bufferSize"));
}

#include <iostream>
#include <vector>
using namespace std;

// Global declarations
int N;
vector<int> graph[1005];       // Adjacency list for connections
int love_partner[1005];        // Stores L(u) for degree-3 nodes
bool matched[1005];            // Tracks if a chameleon has been assigned a color partner

// Query function: returns the number of distinct colors among the given chameleons
int perform_query(const vector<int>& participants) {
    if (participants.empty()) return 0;

    cout << "Query " << participants.size();
    for (int id : participants) cout << " " << id;
    cout << endl;

    int result;
    cin >> result;
    return result;
}

// Determine if node u is connected to any node in set s
bool has_connection(int u, const vector<int>& candidates) {
    if (candidates.empty()) return false;

    vector<int> test_set = candidates;
    test_set.push_back(u);
    int response = perform_query(test_set);

    // If response equals |candidates| + 1, no edges exist between u and candidates
    return response != (int)candidates.size() + 1;
}

// Recursively find all neighbors of u within candidate set using divide-and-conquer
void discover_neighbors(int u, const vector<int>& candidates) {
    // Early termination: max degree is 3
    if (graph[u].size() >= 3) return;

    // Skip if no connection possible
    if (!has_connection(u, candidates)) return;

    // Base case: single candidate must be neighbor
    if (candidates.size() == 1) {
        int v = candidates[0];
        graph[u].push_back(v);
        graph[v].push_back(u);
        return;
    }

    // Divide the candidate set
    int mid = candidates.size() / 2;
    vector<int> left(candidates.begin(), candidates.begin() + mid);
    vector<int> right(candidates.begin() + mid, candidates.end());

    discover_neighbors(u, left);
    discover_neighbors(u, right);
}

int main() {
    ios_base::sync_with_stdio(false);

    if (!(cin >> N)) return 0;

    // Partition vertices into independent sets to reduce query count
    vector<vector<int>> independent_groups;

    // Build graph by processing each vertex
    for (int i = 1; i <= 2 * N; ++i) {
        // Try to find neighbors among already processed vertices
        for (const auto& group : independent_groups) {
            discover_neighbors(i, group);
        }

        // Place i in first compatible independent set
        bool placed = false;
        for (auto& group : independent_groups) {
            bool conflict = false;
            for (int neighbor : graph[i]) {
                for (int member : group) {
                    if (neighbor == member) {
                        conflict = true;
                        break;
                    }
                }
                if (conflict) break;
            }

            if (!conflict) {
                group.push_back(i);
                placed = true;
                break;
            }
        }

        // Create new group if needed
        if (!placed) {
            independent_groups.push_back({i});
        }
    }

    // Identify love relationships for degree-3 nodes
    for (int i = 1; i <= 2 * N; ++i) {
        if (graph[i].size() == 3) {
            int a = graph[i][0], b = graph[i][1], c = graph[i][2];

            // Use query to determine which neighbor is L(i)
            if (perform_query({i, a, b}) == 1) {
                love_partner[i] = c;
            } else if (perform_query({i, a, c}) == 1) {
                love_partner[i] = b;
            } else {
                love_partner[i] = a;
            }
        }
    }

    // Output color pairings
    for (int i = 1; i <= 2 * N; ++i) {
        if (matched[i]) continue;

        // Find the color partner (non-love edge)
        for (int neighbor : graph[i]) {
            if (love_partner[i] != neighbor && love_partner[neighbor] != i) {
                cout << "Answer " << i << " " << neighbor << endl;
                matched[i] = true;
                matched[neighbor] = true;
                break;
            }
        }
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <map>
using namespace std;

map<vector<int>, int> memo;
int ask(const vector<int>& indices) {
    vector<int> sorted = indices;
    sort(sorted.begin(), sorted.end());

    if (memo.find(sorted) != memo.end()) {
        return memo[sorted];
    }

    cout << "? " << sorted.size();
    for (int idx : sorted) {
        cout << " " << idx;
    }
    cout << endl;
    cout.flush();

    int result;
    cin >> result;

    memo[sorted] = result;
    return result;
}

int main() {
    int n;
    cin >> n;

    // Determine which elements have same parity as element 1
    vector<int> sameParity(n + 1, 0);
    sameParity[1] = 1; // base case

    for (int i = 2; i <= n; ++i) {
        vector<int> pair = {1, i};
        sameParity[i] = ask(pair);
    }

    // Find potential endpoints (positions where removing that element gives answer 1)
    vector<int> candidates;
    for (int pos = 1; pos <= n; ++pos) {
        vector<int> allButPos;
        for (int j = 1; j <= n; ++j) {
            if (j != pos) {
                allButPos.push_back(j);
            }
        }
        if (ask(allButPos) == 1) {
            candidates.push_back(pos);
        }
    }

    // There should be exactly two candidates
    int first = candidates[0];
    int second = candidates[1];

    vector<int> permutation(n + 1, 0);
    permutation[first] = 1;
    permutation[second] = n;

    // Decide whether the first candidate has odd or even value
    bool firstIsOdd;
    if (first == 1) {
        firstIsOdd = true;
    } else {
        // Use query with {1, first} to determine relative parity
        firstIsOdd = (sameParity[first] == 1);
    }

    // Assign remaining values based on parity
    int nextEven = 2;
    int nextOdd = 3;

    for (int i = 2; i <= n; ++i) {
        if (i == first || i == second) continue;

        if (sameParity[i] == 1) { // same parity as 1
            if (firstIsOdd) {
                permutation[i] = nextOdd;
                nextOdd += 2;
            } else {
                permutation[i] = nextEven;
                nextEven += 2;
            }
        } else { // different parity from 1
            if (firstIsOdd) {
                permutation[i] = nextEven;
                nextEven += 2;
            } else {
                permutation[i] = nextOdd;
                nextOdd += 2;
            }
        }
    }

    cout << "! ";
    for (int i = 1; i <= n; ++i) {
        cout << permutation[i];
        if (i < n) cout << " ";
    }
    cout << endl;

    return 0;
}

