// Helper function to convert regex error codes to human-readable strings
static const char* __convert_regex_error_code(regex_constants::error_type err) {
    switch (err) {
        case regex_constants::error_collate:
            return "Invalid collating element name.";
        case regex_constants::error_ctype:
            return "Invalid character class name.";
        case regex_constants::error_escape:
            return "Invalid escaped character or trailing escape.";
        case regex_constants::error_backref:
            return "Invalid back reference.";
        case regex_constants::error_brack:
            return "Mismatched [ and ].";
        case regex_constants::error_paren:
            return "Mismatched ( and ).";
        case regex_constants::error_brace:
            return "Mismatched { and }.";
        case regex_constants::error_badbrace:
            return "Invalid range in {} expression.";
        case regex_constants::error_range:
            return "Invalid character range, e.g., [b-a].";
        case regex_constants::error_space:
            return "Insufficient memory for finite state machine conversion.";
        case regex_constants::error_badrepeat:
            return "Quantifier not preceded by valid regex.";
        case regex_constants::error_complexity:
            return "Match complexity exceeded limit.";
        case regex_constants::error_stack:
            return "Insufficient memory for match determination.";
        case regex_constants::__re_err_grammar:
            return "Invalid regex grammar requested.";
        case regex_constants::__re_err_empty:
            return "Empty regex not allowed in POSIX grammar.";
        case regex_constants::__re_err_parse:
            return "Parser did not consume entire regex.";
        default:
            break;
    }
    return "Unknown error";
}

// Constructor implementation for regex_error
regex_error::regex_error(regex_constants::error_type code)
    : runtime_error(__convert_regex_error_code(code)), __code_(code) {}

// Destructor
regex_error::~regex_error() throw() {}

