// Character class name mappings
struct __char_class_entry {
    const char* name_;
    regex_traits<char>::char_class_type flags_;
};

const __char_class_entry __char_class_table[] = {
    {"alnum", ctype_base::alnum},
    {"alpha", ctype_base::alpha},
    {"blank", ctype_base::blank},
    {"cntrl", ctype_base::cntrl},
    {"d", ctype_base::digit},
    {"digit", ctype_base::digit},
    {"graph", ctype_base::graph},
    {"lower", ctype_base::lower},
    {"print", ctype_base::print},
    {"punct", ctype_base::punct},
    {"s", ctype_base::space},
    {"space", ctype_base::space},
    {"upper", ctype_base::upper},
    {"w", regex_traits<char>::__regex_word},
    {"xdigit", ctype_base::xdigit}};

// Comparator for binary search on collation entries
struct __compare_by_name {
    bool operator()(const __collation_entry& entry, const char* name) const {
        return std::strcmp(entry.name_, name) < 0;
    }
    bool operator()(const __char_class_entry& entry, const char* name) const {
        return std::strcmp(entry.name_, name) < 0;
    }
};

} // namespace

// Convert collation name to character
std::string __get_collation_name(const char* name) {
    const __collation_entry* found = std::lower_bound(
        std::begin(__collation_table), 
        std::end(__collation_table), 
        name, 
        __compare_by_name{}
    );

    if (found != std::end(__collation_table) && 
        std::strcmp(name, found->name_) == 0) {
        return std::string(1, found->value_);
    }
    return std::string{};
}

// Convert character class name to flags
regex_traits<char>::char_class_type __get_classname(const char* name, bool ignore_case) {
    const __char_class_entry* found = std::lower_bound(
        std::begin(__char_class_table), 
        std::end(__char_class_table), 
        name, 
        __compare_by_name{}
    );

    regex_traits<char>::char_class_type result = 0;
    if (found != std::end(__char_class_table) && 
        std::strcmp(name, found->name_) == 0) {
        result = found->flags_;

        if (result == regex_traits<char>::__regex_word) {
            result |= ctype_base::alnum | ctype_base::upper | ctype_base::lower;
        } else if (ignore_case) {
            if (result & (ctype_base::lower | ctype_base::upper)) {
                result |= ctype_base::alpha;
            }
        }
    }
    return result;
}

// Specialization for char: match any character except newline
template <>
void __match_any_but_newline<char>::__exec(__state& state) const {
    if (state.__current_ != state.__last_) {
        switch (*state.__current_) {
            case '\r':
            case '\n':
                state.__do_   = __state::__reject;
                state.__node_ = nullptr;
                break;
            default:
                state.__do_ = __state::__accept_and_consume;
                ++state.__current_;
                state.__node_ = this->first();
                break;
        }
    } else {
        state.__do_   = __state::__reject;
        state.__node_ = nullptr;
    }
}

// Specialization for wchar_t: match any wide character except newline variants
template <>
void __match_any_but_newline<wchar_t>::__exec(__state& state) const {
    if (state.__current_ != state.__last_) {
        switch (*state.__current_) {
            case '\r':
            case '\n':
            case 0x2028:
            case 0x2029:
                state.__do_   = __state::__reject;
                state.__node_ = nullptr;
                break;
            default:
                state.__do_ = __state::__accept_and_consume;
                ++state.__current_;
                state.__node_ = this->first();
                break;
        }
    } else {
        state.__do_   = __state::__reject;
        state.__node_ = nullptr;
    }
}

