#define EUREKA_LOG(msg)  SCALE_LOG("EurekaPrecisaScale", msg)
#define EUREKA_WARN(msg) SCALE_WARN("EurekaPrecisaScale", msg)

class EurekaPrecisaScalePrivate {
public:
    ScaleBleTransport* transport = nullptr;
    bool serviceDetected = false;
    bool charSetupDone = false;
    QString deviceName;

    void resetState() {
        serviceDetected = false;
        charSetupDone = false;
    }
};

EurekaPrecisaScale::EurekaPrecisaScale(ScaleBleTransport* transport, QObject* parent)
    : ScaleDevice(parent)
    , d(new EurekaPrecisaScalePrivate)
{
    if (transport) {
        d->transport = transport;
        d->transport->setParent(this);
        connect(d->transport, &ScaleBleTransport::connected,
                this, &EurekaPrecisaScale::handleTransportConnected);
        connect(d->transport, &ScaleBleTransport::disconnected,
                this, &EurekaPrecisaScale::handleTransportDisconnected);
        connect(d->transport, &ScaleBleTransport::error,
                this, &EurekaPrecisaScale::handleTransportError);
        connect(d->transport, &ScaleBleTransport::serviceDiscovered,
                this, &EurekaPrecisaScale::handleServiceDiscovered);
        connect(d->transport, &ScaleBleTransport::servicesDiscoveryFinished,
                this, &EurekaPrecisaScale::handleServicesDiscoveryFinished);
        connect(d->transport, &ScaleBleTransport::characteristicsDiscoveryFinished,
                this, &EurekaPrecisaScale::handleCharacteristicsDiscoveryFinished);
        connect(d->transport, &ScaleBleTransport::characteristicChanged,
                this, &EurekaPrecisaScale::handleCharacteristicChanged);
        connect(d->transport, &ScaleBleTransport::logMessage,
                this, &ScaleDevice::logMessage);
    }
}

EurekaPrecisaScale::~EurekaPrecisaScale() {
    if (d->transport) {
        d->transport->disconnectFromDevice();
    }
    delete d;
}

void EurekaPrecisaScale::connectToDevice(const QBluetoothDeviceInfo& device) {
    if (!d->transport) {
        emit errorOccurred("No transport available");
        return;
    }

    d->deviceName = device.name();
    d->resetState();

    EUREKA_LOG(QString("Connecting to %1 (%2)")
               .arg(device.name())
               .arg(device.address().toString()));

    d->transport->connectToDevice(device);
}

void EurekaPrecisaScale::handleTransportConnected() {
    EUREKA_LOG("Transport connected, starting service discovery");
    d->transport->discoverServices();
}

void EurekaPrecisaScale::handleTransportDisconnected() {
    EUREKA_LOG("Transport disconnected");
    setConnected(false);
}

void EurekaPrecisaScale::handleTransportError(const QString& message) {
    EUREKA_WARN(QString("Transport error: %1").arg(message));
    emit errorOccurred("Eureka Precisa scale connection error");
    setConnected(false);
}

void EurekaPrecisaScale::handleServiceDiscovered(const QBluetoothUuid& uuid) {
    EUREKA_LOG(QString("Service discovered: %1").arg(uuid.toString()));
    if (uuid == Scale::Generic::SERVICE) {
        EUREKA_LOG("Found Generic service (used by Eureka Precisa)");
        d->serviceDetected = true;
    }
}

void EurekaPrecisaScale::handleServicesDiscoveryFinished() {
    EUREKA_LOG(QString("Service discovery finished, service found: %1").arg(d->serviceDetected));
    if (!d->serviceDetected) {
        EUREKA_WARN(QString("Eureka Precisa service %1 not found!").arg(Scale::Generic::SERVICE.toString()));
        emit errorOccurred("Eureka Precisa service not found");
        return;
    }
    d->transport->discoverCharacteristics(Scale::Generic::SERVICE);
}

void EurekaPrecisaScale::enableNotificationsAfterDelay() {
    if (!d->transport || !d->charSetupDone) return;
    EUREKA_LOG("Enabling notifications (200ms)");
    d->transport->enableNotifications(Scale::Generic::SERVICE, Scale::Generic::STATUS);
    // Set unit to grams
    EUREKA_LOG("Setting unit to grams");
    setUnitToGrams();
}

void EurekaPrecisaScale::handleCharacteristicsDiscoveryFinished(const QBluetoothUuid& serviceUuid) {
    if (serviceUuid != Scale::Generic::SERVICE) return;
    if (d->charSetupDone) {
        EUREKA_LOG("Characteristics already set up, ignoring duplicate callback");
        return;
    }

    EUREKA_LOG("Characteristics discovered");
    d->charSetupDone = true;
    setConnected(true);

    // de1app uses 200ms delay for Eureka Precisa
    EUREKA_LOG("Scheduling notification enable in 200ms (de1app timing)");
    QTimer::singleShot(200, this, [this]() {
        enableNotificationsAfterDelay();
    });
}

void EurekaPrecisaScale::handleCharacteristicChanged(const QBluetoothUuid& characteristicUuid,
                                                      const QByteArray& value) {
    if (characteristicUuid != Scale::Generic::STATUS) return;

    if (value.size() < 9) return;

    const uint8_t* data = reinterpret_cast<const uint8_t*>(value.constData());

    // Validate header
    if (data[0] != 0xAA || data[1] != 0x09 || data[2] != 0x41) {
        return;
    }

    // Extract weight: bytes 7–8 as little-endian unsigned short (tenths of gram)
    uint16_t rawWeight = static_cast<uint16_t>(data[7]) |
                         (static_cast<uint16_t>(data[8]) << 8);
    double weightVal = rawWeight / 10.0;

    // Apply sign from byte 6
    if (data[6] == 1) {
        weightVal = -weightVal;
    }

    setWeight(weightVal);
}

void EurekaPrecisaScale::sendCommand(const QByteArray& cmd) {
    if (!d->transport || !d->charSetupDone) return;

    // Eureka Precisa's FFF2 characteristic only supports Write Without Response
    d->transport->writeCharacteristic(Scale::Generic::SERVICE,
                                      Scale::Generic::CMD,
                                      cmd,
                                      ScaleBleTransport::WriteType::WithoutResponse);
}

void EurekaPrecisaScale::sendKeepAlive() {
    if (d->transport && d->charSetupDone)
        d->transport->enableNotifications(Scale::Generic::SERVICE, Scale::Generic::STATUS);
}

void EurekaPrecisaScale::tare() {
    sendCommand(QByteArray::fromHex("AA023131"));
}

void EurekaPrecisaScale::startTimer() {
    sendCommand(QByteArray::fromHex("AA023333"));
}

