    sendCommand(QByteArray::fromHex("AA023232"));
}

void EurekaPrecisaScale::beepTwice() {
    sendCommand(QByteArray::fromHex("AA023737"));
}

#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    vector<int> sortByBits(vector<int>& arr) {
        // Custom comparator: first by number of 1 bits, then by numeric value
        auto countBits = [](int x) {
            int cnt = 0;
            while (x > 0) {
                cnt += x & 1;
                x >>= 1;
            }
            return cnt;
        };

        sort(arr.begin(), arr.end(), [&](int a, int b) {
            int bitsA = countBits(a);
            int bitsB = countBits(b);

            if (bitsA == bitsB) {
                return a < b;  // smaller number first if same bit count
            }
            return bitsA < bitsB;  // fewer set bits come first
        });

        return arr;
    }
};

