// Determine the installation root directory by leveraging dynamic library info
std::filesystem::path get_install_prefix() {
  Dl_info dl_info;
  // Resolve the shared object file containing the anchor symbol
  dladdr(reinterpret_cast<void*>(&anchor::example_models_location_anchor), &dl_info);

  // Normalize the path to the loaded library
  std::filesystem::path lib_path = std::filesystem::path(dl_info.dli_fname).lexically_normal();

  // Traverse up two levels: from lib/roboplan_example_models/libname.so -> lib/ -> install_root/
  return lib_path.parent_path().parent_path();
}

// Construct the share directory path under the install prefix
std::filesystem::path get_package_share_dir() {
  return get_install_prefix() / "share";
}

// Build the full path to the models directory within the package
std::filesystem::path get_package_models_dir() {
  return get_package_share_dir() / "roboplan_example_models" / "models";
}

