#include "TreeCollection.h"
#include "MPIHelper.h"
using namespace std;

TreeCollection::TreeCollection(vector<string>& trees, vector<double>& scores, vector<int> &sourceProcID) {
    ASSERT(trees.size() == scores.size());
    this->treeStrings = move(trees);
    this->scores = move(scores);
    this->sourceProcID = move(sourceProcID);
}

pair<string, double> TreeCollection::getTree(int index) {
    ASSERT(treeStrings.size() == scores.size());
    return { treeStrings[index], scores[index] };
}

void TreeCollection::reset() {
    treeStrings.resize(0);
    scores.resize(0);
    sourceProcID.resize(0);
}

void TreeCollection::appendTrees(TreeCollection &otherTrees) {
    auto srcBegin = otherTrees.treeStrings.begin();
    auto srcEnd   = otherTrees.treeStrings.end();
    treeStrings.insert(treeStrings.end(), srcBegin, srcEnd);

    srcBegin = otherTrees.scores.begin();
    srcEnd   = otherTrees.scores.end();
    scores.insert(scores.end(), srcBegin, srcEnd);

    srcBegin = otherTrees.sourceProcID.begin();
    srcEnd   = otherTrees.sourceProcID.end();
    sourceProcID.insert(sourceProcID.end(), srcBegin, srcEnd);
}

void TreeCollection::appendTrees(CandidateSet &candidateTrees) {
    for (auto iter = candidateTrees.crbegin(); iter != candidateTrees.crend(); ++iter) {
        treeStrings.emplace_back(iter->second.tree);
        scores.emplace_back(iter->first);
        sourceProcID.push_back(MPIHelper::getInstance().getProcessID());
    }
}

size_t TreeCollection::countTrees() const {
    size_t count = treeStrings.size();
    ASSERT(count == scores.size());
    return count;
}

#include <iostream>
#include <vector>
#include <cmath>
#include <random>
#include <cstdint>
#include <limits>

using U64 = std::uint64_t;
using U128 = unsigned __int128;

U64 modulus;
int total_samples = 24000;

// Compute bit-length: floor(log2(x)) + 1, or 0 if x == 0
int count_bits(U64 val) {
    if (val == 0) return 0;
#if defined(__GNUC__) || defined(__clang__)
    return 64 - __builtin_clzll(val);
#else
    int cnt = 0;
    while (val >>= 1) ++cnt;
    return cnt + 1;
#endif
}

// Modular multiplication: (a * b) % modulus
U64 mod_mul(U64 a, U64 b) {
    return static_cast<U64>((U128)a * b % modulus);
}

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::cin >> modulus;

    // Preallocate storage for samples and observations
    std::vector<U64> base_vals(total_samples);
    std::vector<long long> observed_T(total_samples);

    // Initialize RNG with hardware seed
    std::mt19937_64 prng(std::random_device{}());
    std::uniform_int_distribution<U64> range_dist(2, modulus - 1);

    // Query phase: generate bases and collect responses
    for (int idx = 0; idx < total_samples; ++idx) {
        base_vals[idx] = range_dist(prng);
        std::cout << "? " << base_vals[idx] << '\n';
        std::cin >> observed_T[idx];
    }

    // Precompute powers and bit contributions per sample
    const int max_pow = 60;
    std::vector<std::vector<U64>> power_table(total_samples, std::vector<U64>(max_pow));
    std::vector<std::vector<int>> bit_contribs(total_samples, std::vector<int>(max_pow));
    std::vector<long long> base_sum_squares(total_samples, 0LL);

    for (int s = 0; s < total_samples; ++s) {
        U64 cur_base = base_vals[s];
        for (int p = 0; p < max_pow; ++p) {
            power_table[s][p] = cur_base;
            int len = count_bits(cur_base);
            bit_contribs[s][p] = len + 1;
            base_sum_squares[s] += static_cast<long long>(bit_contribs[s][p]) * bit_contribs[s][p];
            cur_base = mod_mul(cur_base, cur_base);
        }
    }

    // Recovery variables
    U64 recovered_d = 0ULL;
    std::vector<U64> running_r(total_samples, 1ULL);
    std::vector<long long> accumulated_C(total_samples, 0LL);

    // Bit-by-bit reconstruction
    for (int bit_pos = 0; bit_pos < max_pow; ++bit_pos) {
        long double sum_y_times_v = 0.0L;
        long double sum_v_squared = 0.0L;

        for (int sample_idx = 0; sample_idx < total_samples; ++sample_idx) {
            long long residual = observed_T[sample_idx] - base_sum_squares[sample_idx] - accumulated_C[sample_idx];
            long long v_val = static_cast<long long>(bit_contribs[sample_idx][bit_pos]) * (count_bits(running_r[sample_idx]) + 1);
            sum_y_times_v += static_cast<long double>(residual) * v_val;
            sum_v_squared += static_cast<long double>(v_val) * v_val;
        }

        long double beta_estimate = 0.0L;
        if (sum_v_squared > 1e-12L) {
            beta_estimate = sum_y_times_v / sum_v_squared;
        }

        int current_bit = (beta_estimate > 0.5L) ? 1 : 0;

        if (current_bit) {
            recovered_d |= (1ULL << bit_pos);
        }

        if (bit_pos < max_pow - 1) {
            if (current_bit) {
                for (int sample_idx = 0; sample_idx < total_samples; ++sample_idx) {
                    accumulated_C[sample_idx] += static_cast<long long>(bit_contribs[sample_idx][bit_pos]) * (count_bits(running_r[sample_idx]) + 1);
                    running_r[sample_idx] = mod_mul(running_r[sample_idx], power_table[sample_idx][bit_pos]);
                }
            }
        }
    }

    std::cout << "! " << recovered_d << '\n';
    return 0;
}

