// Helper to bind NonblockingFuture<T> with type-specific suffix
template <typename T>
void expose_nonblocking_future(nb::handle& parent_module, const std::string& suffix) {
    std::string class_name = "NonblockingFuture" + suffix;
    nb::class_<NonblockingFuture<T>> fut_cls(parent_module, class_name.c_str());
    fut_cls.def("ready", &NonblockingFuture<T>::ready)
           .def("get",   &NonblockingFuture<T>::get);
}

// Register core components: Bootstrap, TcpBootstrap, Transport, etc.
void register_core(nb::module_& mod) {
    auto& m = mod;

    // Expose version function
    m.def("version", &version);

    // Bootstrap interface binding
    nb::class_<Bootstrap> boot_cls(m, "Bootstrap");
    boot_cls.def("get_rank", &Bootstrap::getRank)
            .def("get_n_ranks", &Bootstrap::getNranks)
            .def("get_n_ranks_per_node", &Bootstrap::getNranksPerNode)
            .def("send",
                 [](Bootstrap* self, uintptr_t ptr, size_t sz, int peer, int tag) {
                     self->send(reinterpret_cast<void*>(ptr), sz, peer, tag);
                 }, nb::arg("data"), nb::arg("size"), nb::arg("peer"), nb::arg("tag"))
            .def("recv",
                 [](Bootstrap* self, uintptr_t ptr, size_t sz, int peer, int tag) {
                     self->recv(reinterpret_cast<void*>(ptr), sz, peer, tag);
                 }, nb::arg("data"), nb::arg("size"), nb::arg("peer"), nb::arg("tag"))
            .def("all_gather", &Bootstrap::allGather, nb::arg("allData"), nb::arg("size"))
            .def("barrier", &Bootstrap::barrier)
            .def("send", static_cast<void (Bootstrap::*)(const std::vector<char>&, int, int)>(&Bootstrap::send),
                 nb::arg("data"), nb::arg("peer"), nb::arg("tag"))
            .def("recv", static_cast<void (Bootstrap::*)(std::vector<char>&, int, int)>(&Bootstrap::recv),
                 nb::arg("data"), nb::arg("peer"), nb::arg("tag"));

    // UniqueId wrapper
    nb::class_<UniqueId>(m, "UniqueId");

    // TcpBootstrap subclass
    nb::class_<TcpBootstrap, Bootstrap> tcp_boot_cls(m, "TcpBootstrap");
    tcp_boot_cls.def(nb::init<int, int>(), "Do not use this constructor. Use create instead.")
                .def_static("create",
                            [](int rank, int nRanks) { return std::make_shared<TcpBootstrap>(rank, nRanks); },
                            nb::arg("rank"), nb::arg("nRanks"))
                .def_static("create_unique_id", &TcpBootstrap::createUniqueId)
                .def("get_unique_id", &TcpBootstrap::getUniqueId)
                .def("initialize",
                     static_cast<void (TcpBootstrap::*)(UniqueId, int64_t)>(&TcpBootstrap::initialize),
                     nb::call_guard<nb::gil_scoped_release>(), nb::arg("uniqueId"), nb::arg("timeoutSec") = 30)
                .def("initialize",
                     static_cast<void (TcpBootstrap::*)(const std::string&, int64_t)>(&TcpBootstrap::initialize),
                     nb::call_guard<nb::gil_scoped_release>(), nb::arg("ifIpPortTrio"), nb::arg("timeoutSec") = 30);

    // Transport enum
    nb::enum_<Transport> transport_enum(m, "Transport");
    transport_enum.value("Unknown", Transport::Unknown)
                  .value("CudaIpc", Transport::CudaIpc)
                  .value("Nvls", Transport::Nvls)
                  .value("IB0", Transport::IB0)
                  .value("IB1", Transport::IB1)
                  .value("IB2", Transport::IB2)
                  .value("IB3", Transport::IB3)
                  .value("IB4", Transport::IB4)
                  .value("IB5", Transport::IB5)
                  .value("IB6", Transport::IB6)
                  .value("IB7", Transport::IB7)
                  .value("NumTransports", Transport::NumTransports);

    // TransportFlags class
    nb::class_<TransportFlags> flags_cls(m, "TransportFlags");
    flags_cls.def(nb::init<>())
             .def(nb::init_implicit<Transport>(), nb::arg("transport"))
             .def("has", &TransportFlags::has, nb::arg("transport"))
             .def("none", &TransportFlags::none)
             .def("any", &TransportFlags::any)
             .def("all", &TransportFlags::all)
             .def("count", &TransportFlags::count)
             .def(nb::self | nb::self)
             .def(nb::self | Transport())
             .def(nb::self & nb::self)
             .def(nb::self & Transport())
             .def(nb::self ^ nb::self)
             .def(nb::self ^ Transport())
             .def("__ior__", [](TransportFlags& lhs, const TransportFlags& rhs) { return lhs |= rhs; }, nb::is_operator())
             .def("__iand__", [](TransportFlags& lhs, const TransportFlags& rhs) { return lhs &= rhs; }, nb::is_operator())
             .def("__ixor__", [](TransportFlags& lhs, const TransportFlags& rhs) { return lhs ^= rhs; }, nb::is_operator())
             .def(~nb::self)
             .def(nb::self == nb::self)
             .def(nb::self != nb::self);

    // RegisteredMemory
    nb::class_<RegisteredMemory> reg_mem_cls(m, "RegisteredMemory");
    reg_mem_cls.def(nb::init<>())
               .def("data", &RegisteredMemory::data)
               .def("size", &RegisteredMemory::size)
               .def("transports", &RegisteredMemory::transports)
               .def("serialize", &RegisteredMemory::serialize)
               .def_static("deserialize", &RegisteredMemory::deserialize, nb::arg("data"));

    // Connection
    nb::class_<Connection> conn_cls(m, "Connection");
    conn_cls.def("write", &Connection::write,
                 nb::arg("dst"), nb::arg("dstOffset"), nb::arg("src"), nb::arg("srcOffset"), nb::arg("size"))
            .def("update_and_sync",
                 [](Connection* self, RegisteredMemory dst, uint64_t doff, uintptr_t src, uint64_t nv) {
                     self->updateAndSync(dst, doff, reinterpret_cast<uint64_t*>(src), nv);
                 }, nb::arg("dst"), nb::arg("dstOffset"), nb::arg("src"), nb::arg("newValue"))
            .def("flush", &Connection::flush, nb::call_guard<nb::gil_scoped_release>(),
                 nb::arg("timeoutUsec") = (int64_t)3e7)
            .def("transport", &Connection::transport)
            .def("remote_transport", &Connection::remoteTransport);

    // Endpoint
    nb::class_<Endpoint> ep_cls(m, "Endpoint");
    ep_cls.def("transport", &Endpoint::transport)
          .def("serialize", &Endpoint::serialize)
          .def_static("deserialize", &Endpoint::deserialize, nb::arg("data"));

    // EndpointConfig
    nb::class_<EndpointConfig> ep_cfg_cls(m, "EndpointConfig");
    ep_cfg_cls.def(nb::init<>())
              .def(nb::init_implicit<Transport>(), nb::arg("transport"))
              .def_rw("transport", &EndpointConfig::transport)
              .def_rw("ib_max_cq_size", &EndpointConfig::ibMaxCqSize)
              .def_rw("ib_max_cq_poll_num", &EndpointConfig::ibMaxCqPollNum)
              .def_rw("ib_max_send_wr", &EndpointConfig::ibMaxSendWr)
              .def_rw("ib_max_wr_per_send", &EndpointConfig::ibMaxWrPerSend);

    // Context
    nb::class_<Context> ctx_cls(m, "Context");
    ctx_cls.def(nb::init<>())
           .def("register_memory",
                [](Context* self, uintptr_t ptr, size_t sz, TransportFlags tf) {
                    return self->registerMemory(reinterpret_cast<void*>(ptr), sz, tf);
                }, nb::arg("ptr"), nb::arg("size"), nb::arg("transports"))
           .def("create_endpoint", &Context::createEndpoint, nb::arg("config"))
           .def("connect", &Context::connect, nb::arg("local_endpoint"), nb::arg("remote_endpoint"));

    // Bind futures
    expose_nonblocking_future<RegisteredMemory>(m, "RegisteredMemory");
    expose_nonblocking_future<std::shared_ptr<Connection>>(m, "shared_ptr_Connection");

    // Communicator
    nb::class_<Communicator> comm_cls(m, "Communicator");
    comm_cls.def(nb::init<std::shared_ptr<Bootstrap>, std::shared_ptr<Context>>(),
                 nb::arg("bootstrap"), nb::arg("context") = nullptr)
            .def("bootstrap", &Communicator::bootstrap)
            .def("context", &Communicator::context)
            .def("register_memory",
                 [](Communicator* self, uintptr_t ptr, size_t sz, TransportFlags tf) {
                     return self->registerMemory(reinterpret_cast<void*>(ptr), sz, tf);
                 }, nb::arg("ptr"), nb::arg("size"), nb::arg("transports"))
            .def("send_memory_on_setup", &Communicator::sendMemoryOnSetup,
                 nb::arg("memory"), nb::arg("remoteRank"), nb::arg("tag"))
            .def("recv_memory_on_setup", &Communicator::recvMemoryOnSetup,
                 nb::arg("remoteRank"), nb::arg("tag"))
            .def("connect_on_setup", &Communicator::connectOnSetup,
                 nb::arg("remoteRank"), nb::arg("tag"), nb::arg("localConfig"))
            .def("remote_rank_of", &Communicator::remoteRankOf)
            .def("tag_of", &Communicator::tagOf)
            .def("setup", &Communicator::setup);
}

// Main module entry point
NB_MODULE(_mscclpp, m) {
    // List of registration functions in order
    auto reg_funcs = {
        register_env,
        register_error,
        register_proxy_channel,
        register_sm_channel,
        register_fifo,
        register_semaphore,
        register_utils,
        register_core,
        register_numa,
        register_nvls,
        register_executor,
        register_npkit,
        register_gpu_utils
    };

    // Iterate and invoke each registration function
    for (auto func : reg_funcs) {
        func(m);
    }
}

