FReply SMoviePipelineConfigPanel::HandleConfirmAction()
{
	if (LastUsedPresetIfUnchanged.IsValid())
	{
		OnConfigLoadedFromPreset.ExecuteIfBound(JobReference, ShotReference, LastUsedPresetIfUnchanged.Get());
	}
	else
	{
		OnConfigChanged.ExecuteIfBound(JobReference, ShotReference, TransientPreset);
	}
	return FReply::Handled();
}

bool SMoviePipelineConfigPanel::IsAcceptableToCommit() const
{
	EMoviePipelineValidationState MaxSeverity = EMoviePipelineValidationState::Valid;
	for (const UMoviePipelineSetting* Setting : TransientPreset->GetUserSettings())
	{
		int32 CurrentLevel = static_cast<int32>(MaxSeverity);
		int32 NewLevel = static_cast<int32>(Setting->GetValidationState());
		if (NewLevel > CurrentLevel)
		{
			MaxSeverity = static_cast<EMoviePipelineValidationState>(NewLevel);
		}
	}
	return static_cast<int32>(MaxSeverity) < static_cast<int32>(EMoviePipelineValidationState::Errors);
}

FReply SMoviePipelineConfigPanel::HandleCancelAction()
{
	TSharedPtr<SWindow> WindowPtr = FSlateApplication::Get().FindWidgetWindow(AsShared());
	if (WindowPtr.IsValid())
	{
		WindowPtr->RequestDestroyWindow();
	}
	return FReply::Handled();
}

FText SMoviePipelineConfigPanel::GetCurrentValidationMessage() const
{
	EMoviePipelineValidationState Severity = EMoviePipelineValidationState::Valid;
	for (const UMoviePipelineSetting* Setting : TransientPreset->FindSettings<UMoviePipelineSetting>())
	{
		int32 Current = static_cast<int32>(Severity);
		int32 Candidate = static_cast<int32>(Setting->GetValidationState());
		if (Candidate > Current)
		{
			Severity = static_cast<EMoviePipelineValidationState>(Candidate);
		}
	}

	switch (Severity)
	{
	case EMoviePipelineValidationState::Errors:
		return LOCTEXT("ValidationSettingError_Text", "One or more settings has a configuration error and must be resolved.");
	case EMoviePipelineValidationState::Warnings:
		return LOCTEXT("ValidationSettingWarning_Text", "One or more settings have validation warnings. This may produce undesired results.");
	default:
		return FText::GetEmpty();
	}
}

UMoviePipelineConfigBase* SMoviePipelineConfigPanel::CreateNewTransientPreset()
{
	static const TCHAR* TempPackagePath = TEXT("/Temp/MoviePipeline/PendingConfig");
	FString DesiredName = FString::Printf(TEXT("Pending_%s"), *StoredConfigClass->GetName());

	// Reuse existing transient preset if available
	UMoviePipelineConfigBase* Existing = FindObject<UMoviePipelineConfigBase>(nullptr, TEXT("/Temp/MoviePipeline/PendingConfig.PendingConfig"));
	if (Existing)
	{
		return Existing;
	}

	UPackage* NewPackage = CreatePackage(TempPackagePath);
	NewPackage->SetFlags(RF_Transient);
	NewPackage->AddToRoot();

	UMoviePipelineConfigBase* NewInstance = NewObject<UMoviePipelineConfigBase>(
		NewPackage,
		StoredConfigClass,
		*DesiredName,
		RF_Transient | RF_Transactional | RF_Standalone
	);
	return NewInstance;
}

