bool SMoviePipelineConfigPanel::OpenSaveFileDialog(const FString& DefaultPath, const FString& NameHint, FString& OutPackageName)
{
	FSaveAssetDialogConfig SaveConfig;
	SaveConfig.DefaultPath = DefaultPath;
	SaveConfig.DefaultAssetName = NameHint;
	SaveConfig.AssetClassNames.Add(StoredConfigClass->GetFName());
	SaveConfig.ExistingAssetPolicy = ESaveAssetDialogExistingAssetPolicy::AllowButWarn;
	SaveConfig.DialogTitleOverride = LOCTEXT("SaveConfigPresetDialogTitle", "Save Config Preset");

	FContentBrowserModule& CBModule = FModuleManager::LoadModuleChecked<FContentBrowserModule>("ContentBrowser");
	FString SelectedPath = CBModule.Get().CreateModalSaveAssetDialog(SaveConfig);

	if (!SelectedPath.IsEmpty())
	{
		OutPackageName = FPackageName::ObjectPathToPackageName(SelectedPath);
		return true;
	}
	return false;
}

bool SMoviePipelineConfigPanel::DetermineSaveLocation(const FString& BaseName, FString& OutFullPackageName)
{
	UMovieRenderPipelineProjectSettings* GlobalSettings = GetMutableDefault<UMovieRenderPipelineProjectSettings>();
	const FString DefaultDirectory = GlobalSettings->PresetSaveDir.Path;
	FString StartPath;
	FPackageName::TryConvertFilenameToLongPackageName(DefaultDirectory, StartPath);
	if (StartPath.IsEmpty())
	{
		StartPath = TEXT("/Game");
	}

	FString InitialName = BaseName;
	FString UniquePackagePath, UniqueAssetName;
	FAssetToolsModule& AssetTools = FModuleManager::LoadModuleChecked<FAssetToolsModule>("AssetTools");
	AssetTools.Get().CreateUniqueAssetName(StartPath / InitialName, TEXT(""), UniquePackagePath, UniqueAssetName);
	FString SuggestedName = FPaths::GetCleanFilename(UniqueAssetName);

	FString UserInputPath;
	FString FinalPath;

	bool bValidated = false;
	while (!bValidated)
	{
		if (!OpenSaveFileDialog(StartPath, SuggestedName, UserInputPath))
		{
			return false;
		}
		FinalPath = UserInputPath;

		FText ErrorMsg;
		bValidated = FFileHelper::IsFilenameValidForSaving(FinalPath, ErrorMsg);
	}

	GlobalSettings->PresetSaveDir.Path = FPackageName::GetLongPackagePath(UserInputPath);
	GlobalSettings->SaveConfig();
	OutFullPackageName = MoveTemp(FinalPath);
	return true;
}

void SMoviePipelineConfigPanel::ExecuteSaveAsPreset()
{
	FString PackagePath;
	if (!DetermineSaveLocation(TransientPreset->GetName(), PackagePath))
	{
		return;
	}

	FScopedTransaction Transaction(LOCTEXT("SaveAsPreset", "Save As Preset"));

	const FString AssetName = FPackageName::GetLongPackageAssetName(PackagePath);
	UPackage* TargetPackage = CreatePackage(*PackagePath);
	UMoviePipelineConfigBase* NewPreset = NewObject<UMoviePipelineConfigBase>(
		TargetPackage,
		StoredConfigClass,
		*AssetName,
		RF_Public | RF_Standalone | RF_Transactional
	);

	if (NewPreset)
	{
		NewPreset->CopyFrom(TransientPreset);
		NewPreset->MarkPackageDirty();

		UMoviePipelineOutputSetting* OriginalOutput = TransientPreset->FindSetting<UMoviePipelineOutputSetting>();
		UMoviePipelineOutputSetting* CopiedOutput = NewPreset->FindSetting<UMoviePipelineOutputSetting>();

		if (OriginalOutput && CopiedOutput && OriginalOutput->OutputDirectory.Path.Len() == 0)
		{
			CopiedOutput->OutputDirectory.Path = OriginalOutput->OutputDirectory.Path;
		}

		NewPreset->DisplayName = AssetName;
		FAssetRegistryModule::AssetCreated(NewPreset);

		FEditorFileUtils::EPromptReturnCode Result = FEditorFileUtils::PromptForCheckoutAndSave({ TargetPackage }, false, false);
		if (Result == FEditorFileUtils::EPromptReturnCode::PR_Success)
		{
			LastUsedPresetIfUnchanged = NewPreset;
		}
	}
}

void SMoviePipelineConfigPanel::HandleAnyObjectChange(UObject* ModifiedObject)
{
	if (ModifiedObject && (ModifiedObject->IsIn(TransientPreset) || ModifiedObject == TransientPreset))
	{
		LastUsedPresetIfUnchanged.Reset();
	}
}

void SMoviePipelineConfigPanel::HandlePresetImported(const FAssetData& ImportedAsset)
{
	FSlateApplication::Get().DismissAllMenus();
	UMoviePipelineConfigBase* ImportedPreset = CastChecked<UMoviePipelineConfigBase>(ImportedAsset.GetAsset());

	if (ImportedPreset)
	{
		FScopedTransaction Transaction(LOCTEXT("ImportPreset_Transaction", "Import Config Preset"));

		TransientPreset->Modify();
		TransientPreset->CopyFrom(ImportedPreset);
		LastUsedPresetIfUnchanged = ImportedPreset;
	}
}

