  char date_buffer[64];
  strftime(date_buffer, sizeof(date_buffer), "%a, %d %b %Y %H:%M:%S GMT", utc_time);

  absl::flat_hash_map<std::string, std::string> headers = {{"retry-after", date_buffer}};
  int64_t computed_delay = client.ParseRetryAfter(headers);

  EXPECT_GT(computed_delay, 55000);
  EXPECT_LE(computed_delay, 65000);
}

