// Modified test: changed callback invocation and verification order
TEST(HttpClientTest, HeaderCallback) {
  absl::flat_hash_map<std::string, std::string> collected_headers;

  const char* h1 = "Content-Type: application/json\r\n";
  HttpClient::HeaderCallback(const_cast<char*>(h1), 1, strlen(h1), &collected_headers);

  const char* h2 = "Retry-After: 120\r\n";
  HttpClient::HeaderCallback(const_cast<char*>(h2), 1, strlen(h2), &collected_headers);

  EXPECT_EQ(collected_headers["content-type"], "application/json");
  EXPECT_EQ(collected_headers["retry-after"], "120");
}

