// Alternative test structures for serialization (Type III clone with renamed fields and logic)
struct GreetingData {
  std::string text;
  bool operator==(const GreetingData& other) const { return text == other.text; }
};

struct PlanetRecord {
  int identifier;
  int sampleValue;
  bool operator==(const PlanetRecord& other) const { 
    return identifier == other.identifier && sampleValue == other.sampleValue; 
  }
};

// Glaze metadata with equivalent structure but different naming conventions
template <>
struct glz::meta<GreetingData> {
  using T = GreetingData;
  static constexpr auto value = glz::object("text", &T::text);
};

template <>
struct glz::meta<PlanetRecord> {
  using T = PlanetRecord;
  static constexpr auto value = glz::object("identifier", &T::identifier, "sampleValue", &T::sampleValue);
};

namespace aeronet::test {

class JsonSerializationValidation : public ::testing::Test {
 protected:
  void SetUp() override {}
  void TearDown() override {}
};

TEST_F(JsonSerializationValidation, EncodeBasicGreeting) {
  GreetingData greeting{"Hello, World!"};
  auto json = SerializeToJson(greeting);
  // Verify the JSON output is non-empty and contains expected content
  ASSERT_FALSE(json.empty());
  ASSERT_TRUE(json.find("Hello, World!") != std::string::npos);
}

TEST_F(JsonSerializationValidation, EncodePlanetaryData) {
  PlanetRecord record{42, 1234};
  auto json = SerializeToJson(record);
  ASSERT_FALSE(json.empty());
  ASSERT_TRUE(json.find("42") != std::string::npos);
  ASSERT_TRUE(json.find("1234") != std::string::npos);
}

