// Safe subtraction for natural numbers that prevents underflow
unsigned int NatSubUnderflowSafe::sub_checked(const unsigned int minuend,
                                              const unsigned int subtrahend) {
    // If subtrahend is greater than minuend, return 0 to avoid underflow
    if (subtrahend > minuend) {
        return 0;
    }
    return minuend - subtrahend;
}

// Alternative safe subtraction with operands in reversed order
unsigned int NatSubUnderflowSafe::sub_alt(const unsigned int first,
                                          const unsigned int second) {
    // Check if first operand exceeds second to prevent underflow
    if (first > second) {
        return 0;
    }
    return second - first;
}

