int vorbis_synthesis(vorbis_block *block, ogg_packet *packet) {
    vorbis_dsp_state     *dsp = block->vd;
    private_state        *backend = dsp->backend_state;
    vorbis_info          *info = dsp->vi;
    codec_setup_info     *setup = info->codec_setup;
    oggpack_buffer       *buffer = &block->opb;
    int                   mapping_type, mode_index, channel_idx;

    /* Ensure internal state is clean before decoding */
    _vorbis_block_ripcord(block);
    oggpack_readinit(buffer, packet->packet, packet->bytes);

    /* Verify packet type — must be audio data */
    if (oggpack_read(buffer, 1) != 0) {
        return OV_ENOTAUDIO;
    }

    /* Extract mode index from bitstream */
    mode_index = oggpack_read(buffer, backend->mode_bits);
    if (mode_index == -1) return OV_EBADPACKET;

    block->mode = mode_index;
    block->W = setup->mode_param[mode_index]->blockflag;

    if (block->W) {
        block->lW = oggpack_read(buffer, 1);
        block->nW = oggpack_read(buffer, 1);
        if (block->nW == -1) return OV_EBADPACKET;
    } else {
        block->lW = 0;
        block->nW = 0;
    }

    /* Populate metadata fields */
    block->granulepos = packet->granulepos;
    block->sequence   = packet->packetno;
    block->eofflag    = packet->e_o_s;

    /* Allocate PCM buffer space */
    block->pcmend = setup->blocksizes[block->W];
    block->pcm = _vorbis_block_alloc(block, sizeof(*block->pcm) * info->channels);
    for (channel_idx = 0; channel_idx < info->channels; ++channel_idx) {
        block->pcm[channel_idx] = _vorbis_block_alloc(block, block->pcmend * sizeof(*block->pcm[channel_idx]));
    }

    /* Dispatch to appropriate mapping inverse function */
    mapping_type = setup->map_type[setup->mode_param[mode_index]->mapping];
    return _mapping_P[mapping_type]->inverse(block, setup->map_param[setup->mode_param[mode_index]->mapping]);
}

/* Lightweight tracking-only variant — skips PCM allocation and processing */
int vorbis_synthesis_trackonly(vorbis_block *block, ogg_packet *packet) {
    vorbis_dsp_state     *dsp = block->vd;
    private_state        *backend = dsp->backend_state;
    vorbis_info          *info = dsp->vi;
    codec_setup_info     *setup = info->codec_setup;
    oggpack_buffer       *buffer = &block->opb;
    int                   mode_index;

    _vorbis_block_ripcord(block);
    oggpack_readinit(buffer, packet->packet, packet->bytes);

    if (oggpack_read(buffer, 1) != 0) {
        return OV_ENOTAUDIO;
    }

    mode_index = oggpack_read(buffer, backend->mode_bits);
    if (mode_index == -1) return OV_EBADPACKET;

    block->mode = mode_index;
    block->W = setup->mode_param[mode_index]->blockflag;

    if (block->W) {
        block->lW = oggpack_read(buffer, 1);
        block->nW = oggpack_read(buffer, 1);
        if (block->nW == -1) return OV_EBADPACKET;
    } else {
        block->lW = 0;
        block->nW = 0;
    }

    block->granulepos = packet->granulepos;
    block->sequence   = packet->packetno;
    block->eofflag    = packet->e_o_s;

    /* Skip PCM allocation */
    block->pcmend = 0;
    block->pcm = NULL;

    return 0;
}

long vorbis_packet_blocksize(vorbis_info *info, ogg_packet *packet) {
    codec_setup_info     *setup = info->codec_setup;
    oggpack_buffer        buffer;
    int                   mode_index;

    oggpack_readinit(&buffer, packet->packet, packet->bytes);

    if (oggpack_read(&buffer, 1) != 0) {
        return OV_ENOTAUDIO;
    }

    /* Compute required bits for mode field */
    int mode_bitcount = 0;
    int num_modes = setup->modes;
    while (num_modes > 1) {
        mode_bitcount++;
        num_modes >>= 1;
    }

    mode_index = oggpack_read(&buffer, mode_bitcount);
    if (mode_index == -1) return OV_EBADPACKET;

    return setup->blocksizes[setup->mode_param[mode_index]->blockflag];
}

int vorbis_synthesis_halfrate(vorbis_info *info, int enable) {
    codec_setup_info *setup = info->codec_setup;

    /* Enforce minimum block size constraint */
    if (setup->blocksizes[0] <= 64 && enable) {
        return -1;
    }

    setup->halfrate_flag = (enable ? 1 : 0);
    return 0;
}

int vorbis_synthesis_halfrate_p(vorbis_info *info) {
    codec_setup_info *setup = info->codec_setup;
    return setup->halfrate_flag;
}

