void LiteralExpression::cast(const LogicalType& targetType) {
    // Ensure type conversion is allowed before proceeding
    if (!value.isTypeChangePermitted()) {
        // LCOV_EXCL_START
        throw BinderException(
            std::format("Literal expression cannot be cast from {} to {}.",
                dataType.toString(), targetType.toString()));
        // LCOV_EXCL_STOP
    }

    // Update both the stored data type and the value's type information
    dataType = targetType.copy();
    value.updateDataType(targetType);
}

