// Type alias for symbol-stub pair
using SymbolStubPair = std::pair<MCSymbol *, MachineModuleInfoImpl::StubValueTy>;

// Comparison function to sort stub pairs by symbol name (lexicographically)
static int compareStubsBySymbolName(const SymbolStubPair *A, const SymbolStubPair *B) {
  return A->first->getName().compare(B->first->getName());
}

// Extract and sort stub entries from a DenseMap into a sorted list
MachineModuleInfoImpl::SymbolListTy MachineModuleInfoImpl::getSortedStubs(
    DenseMap<MCSymbol *, MachineModuleInfoImpl::StubValueTy> &Stubs) {
  // Initialize list with all entries from the map
  SymbolListTy Entries(Stubs.begin(), Stubs.end());

  // Sort the list using lexicographic ordering on symbol names
  array_pod_sort(Entries.begin(), Entries.end(), compareStubsBySymbolName);

  // Clear the original map after extracting and sorting
  Stubs.clear();

  return Entries;
}

