int main(int argc, char** argv) {
    int* deviceMemory = nullptr;
    int counterIdx = 0;

    if (argc > 1) {
        counterIdx = std::atoi(argv[1]);
    }

    prepare();

    // Initialize ROCprofiler infrastructure
    CHECK_ROCPROFILER(rocprofiler_initialize());

    rocprofiler_session_id_t profSession;
    CHECK_ROCPROFILER(rocprofiler_create_session(ROCPROFILER_NONE_REPLAY_MODE, &profSession));

    rocprofiler_buffer_id_t dataBuffer;
    auto bufferCallback = [](const rocprofiler_record_header_t* recHead,
                             const rocprofiler_record_header_t* endRec,
                             rocprofiler_session_id_t sessId,
                             rocprofiler_buffer_id_t bufId) {
        WriteBufferRecords(recHead, endRec, sessId, bufId);
    };
    CHECK_ROCPROFILER(rocprofiler_create_buffer(profSession, bufferCallback, 0x999999, &dataBuffer));

    // Define XGMI counter names
    std::vector<std::string> xgmiMetricNames = {
        "xgmi_link0_data_outbound", "xgmi_link1_data_outbound",
        "xgmi_link2_data_outbound", "xgmi_link3_data_outbound",
        "xgmi_link4_data_outbound", "xgmi_link5_data_outbound",
        "xgmi_link5_data_outbound", "xgmi_link6_data_outbound"
    };

    // Prepare counter input structure
    rocprofiler_counters_sampler_counter_input_t metricInput = {
        .name = const_cast<char*>(xgmiMetricNames[counterIdx].c_str()),
        .type = ROCPROFILER_COUNTERS_SAMPLER_XGMI_COUNTERS
    };

    uint32_t sampleInterval = 1000;   // ms
    uint32_t runTime = 5000;          // ms
    rocprofiler_counters_sampler_parameters_t samplerConfig = {
        .counters = &metricInput,
        .counters_num = 1,
        .sampling_rate = sampleInterval,
        .sampling_duration = runTime,
        .gpu_agent_index = 0
    };

    rocprofiler_filter_id_t filterHandle;
    [[maybe_unused]] rocprofiler_filter_property_t unusedProp = {};
    CHECK_ROCPROFILER(rocprofiler_create_filter(
        profSession,
        ROCPROFILER_COUNTERS_SAMPLER,
        rocprofiler_filter_data_t{.counters_sampler_parameters = samplerConfig},
        0,
        &filterHandle,
        unusedProp
    ));

    CHECK_ROCPROFILER(rocprofiler_set_filter_buffer(profSession, filterHandle, dataBuffer));

    // Device setup and memory allocation
    hipDeviceProp_t properties;
    HIP_CALL(hipGetDeviceProperties(&properties, 0));
    HIP_CALL(hipMalloc(reinterpret_cast<void**>(&deviceMemory), sizeof(int)));

    // Pre-profile kernels (not measured)
    kernelCalls('A');
    kernelCalls('B');

    std::cout << "Profiling: " << xgmiMetricNames[counterIdx]
              << " @ " << sampleInterval << " ms interval for " << runTime << " ms" << std::endl;

    // Start profiling session
    CHECK_ROCPROFILER(rocprofiler_start_session(profSession));

    // Kernels to be profiled
    kernelCalls('C');
    kernelCalls('D');
    kernelCalls('E');
    kernelCalls('F');

    // Cleanup host-side allocations
    HIP_CALL(hipFree(deviceMemory));

    // Let sampling run long enough
    sleep(6);

    // Stop and flush
    CHECK_ROCPROFILER(rocprofiler_terminate_session(profSession));
    CHECK_ROCPROFILER(rocprofiler_flush_data(profSession, dataBuffer));

    // Teardown
    CHECK_ROCPROFILER(rocprofiler_destroy_session(profSession));
    CHECK_ROCPROFILER(rocprofiler_finalize());

    return 0;
}

