// Compute maximum permissible layer height based on surface slope and allowed deviation
static inline float compute_layer_height_from_normal(const SlicingAdaptive::FaceZ &facet,
                                                       float max_allowed_deviation)
{
    // Use clamped formula: min( max_dev / 0.184, 1.44 * max_dev * sqrt(sin/cos) )
    const float sin_val = facet.n_sin;
    const float cos_val = facet.n_cos;

    if (cos_val <= 1e-5f)
        return FLT_MAX;

    const float adaptive_term = 1.44f * max_allowed_deviation * std::sqrt(sin_val / cos_val);
    const float clamp_term = max_allowed_deviation / 0.184f;

    return std::min(clamp_term, adaptive_term);
}

void SlicingAdaptive::clear()
{
    m_faces.clear();
}

void SlicingAdaptive::prepare(const ModelObject &obj)
{
    this->clear();

    TriangleMesh mesh = obj.raw_mesh();
    const ModelInstance &inst = *obj.instances.front();
    mesh.transform(inst.get_matrix(), inst.is_left_handed());

    // Gather all facets with their Z-extent and normal components
    m_faces.reserve(mesh.facets_count());
    for (const auto &face_idx : mesh.its.indices)
    {
        stl_vertex pts[3] = {
            mesh.its.vertices[face_idx[0]],
            mesh.its.vertices[face_idx[1]],
            mesh.its.vertices[face_idx[2]]
        };
        stl_vertex norm = face_normal_normalized(pts);

        float z_min = std::min({pts[0].z(), pts[1].z(), pts[2].z()});
        float z_max = std::max({pts[0].z(), pts[1].z(), pts[2].z()});

        float abs_z_comp = std::abs(norm.z());
        float horiz_mag = std::sqrt(norm.x() * norm.x() + norm.y() * norm.y());

        m_faces.emplace_back(FaceZ{{z_min, z_max}, abs_z_comp, horiz_mag});
    }

    // Sort facets by vertical span for efficient slicing
    std::sort(m_faces.begin(), m_faces.end(),
              [](const FaceZ &a, const FaceZ &b) { return a.z_span < b.z_span; });
}

// Determine next layer height given current print height and quality setting
float SlicingAdaptive::next_layer_height(const float layer_bottom, float quality_param, size_t &last_visited_face)
{
    float best_height = static_cast<float>(m_slicing_params.max_layer_height);

    // Compute effective max surface deviation based on quality factor
    double delta_min = m_slicing_params.min_layer_height;
    double delta_mid = m_slicing_params.layer_height;
    double delta_max = m_slicing_params.max_layer_height;

    double dev_threshold;
    if (quality_param < 0.5f)
        dev_threshold = lerp(delta_min, delta_mid, 2.0 * quality_param);
    else
        dev_threshold = lerp(delta_max, delta_mid, 2.0 * (1.0 - quality_param));

    float max_deviation = static_cast<float>(dev_threshold);

    // Phase 1: Find first intersecting facet and compute initial height bound
    size_t idx = last_visited_face;
    bool found_first = false;

    for (; idx < m_faces.size(); ++idx)
    {
        const auto &[z_lo, z_hi] = m_faces[idx].z_span;

        if (z_lo >= layer_bottom)
            break;

        if (z_hi > layer_bottom)
        {
            if (!found_first)
            {
                found_first = true;
                last_visited_face = idx;
            }

            if (z_hi < layer_bottom + EPSILON)
                continue;

            best_height = std::min(best_height, compute_layer_height_from_normal(m_faces[idx], max_deviation));
        }
    }

    // Enforce minimum printable layer height
    best_height = std::max(best_height, static_cast<float>(m_slicing_params.min_layer_height));

    // Phase 2: Refine height considering additional facets within tentative layer
    if (best_height > static_cast<float>(m_slicing_params.min_layer_height))
    {
        for (; idx < m_faces.size(); ++idx)
        {
            const auto &[z_lo, z_hi] = m_faces[idx].z_span;

            if (z_lo >= layer_bottom + best_height)
                break;

            if (z_hi < layer_bottom + EPSILON)
                continue;

            float candidate_height = compute_layer_height_from_normal(m_faces[idx], max_deviation);
            float vertical_offset = z_lo - layer_bottom;

            if (candidate_height < vertical_offset)
            {
                assert(vertical_offset < best_height + EPSILON);
#ifdef ADAPTIVE_LAYER_HEIGHT_DEBUG
                BOOST_LOG_TRIVIAL(trace) << "cusp computation, height reduced from " << best_height
                                         << " to " << vertical_offset << " due to z-diff";
#endif
                best_height = vertical_offset;
            }
            else if (candidate_height < best_height)
            {
#ifdef ADAPTIVE_LAYER_HEIGHT_DEBUG
                BOOST_LOG_TRIVIAL(trace) << "adaptive layer computation: height reduced from "
                                         << best_height << " to " << candidate_height;
#endif
                best_height = candidate_height;
            }
        }

        best_height = std::max(best_height, static_cast<float>(m_slicing_params.min_layer_height));
    }

#ifdef ADAPTIVE_LAYER_HEIGHT_DEBUG
    BOOST_LOG_TRIVIAL(trace) << "adaptive layer computation, bottom at z=" << layer_bottom
                             << ", quality=" << quality_param << ", final height=" << best_height;
#endif

    return best_height;
}

// Find distance to nearest horizontal facet above current Z
float SlicingAdaptive::horizontal_facet_distance(float z_pos)
{
    for (size_t i = 0; i < m_faces.size(); ++i)
    {
        const auto &[z_lo, z_hi] = m_faces[i].z_span;

        if (z_lo > z_pos + m_slicing_params.max_layer_height)
            break;

        if (z_lo > z_pos && std::abs(z_lo - z_hi) < EPSILON)
            return z_lo - z_pos;
    }

    // No nearby horizontal facet — fall back to max step or object top
    float remaining_height = m_slicing_params.object_print_z_height() - z_pos;
    return (remaining_height <= m_slicing_params.max_layer_height)
               ? std::max(remaining_height, 0.0f)
               : static_cast<float>(m_slicing_params.max_layer_height);
}

