namespace {

// Track seen exception addresses to avoid duplicate logging
std::unordered_set<uintptr_t> g_seen_exception_addresses;

// Check if exception address was seen before, and record it if not
// Returns true if address was already seen (should skip detailed logging)
bool CheckAndRecordExceptionAddress(uintptr_t addr) {
    utils::SRWLockExclusive guard(utils::g_seen_exception_addresses_lock);
    auto [it, inserted] = g_seen_exception_addresses.insert(addr);
    return !inserted;
}

// Helper function to print process information
void PrintProcessInfo() {
    try {
        LogInfo("=== PROCESS INFORMATION ===");

        // Process ID
        DWORD pid = GetCurrentProcessId();
        LogInfo("Process ID: {}", pid);

        // Thread ID
        DWORD tid = GetCurrentThreadId();
        LogInfo("Thread ID: {}", tid);

        // Process executable path
        wchar_t exe_path[MAX_PATH];
        if (GetModuleFileNameW(nullptr, exe_path, MAX_PATH)) {
            std::string narrow_path;
            int len_needed = WideCharToMultiByte(CP_UTF8, 0, exe_path, -1, nullptr, 0, nullptr, nullptr);
            if (len_needed > 0) {
                narrow_path.resize(len_needed - 1); // exclude null terminator
                WideCharToMultiByte(CP_UTF8, 0, exe_path, -1, &narrow_path[0], len_needed, nullptr, nullptr);
                LogInfo("Process Path: {}", narrow_path);
            }
        }

        // Command line
        LPSTR cmdline = GetCommandLineA();
        if (cmdline) {
            LogInfo("Command Line: {}", cmdline);
        }

        // Memory info
        HANDLE proc = GetCurrentProcess();
        PROCESS_MEMORY_COUNTERS_EX mem_counters{};
        if (GetProcessMemoryInfo(proc, reinterpret_cast<PROCESS_MEMORY_COUNTERS*>(&mem_counters), sizeof(mem_counters))) {
            double ws_mb = static_cast<double>(mem_counters.WorkingSetSize) / (1024.0 * 1024.0);
            double peak_mb = static_cast<double>(mem_counters.PeakWorkingSetSize) / (1024.0 * 1024.0);
            LogInfo("Process Memory - Working Set: {:.2f} MB, Peak: {:.2f} MB, Page Faults: {}", 
                    ws_mb, peak_mb, mem_counters.PageFaultCount);
        }

        LogInfo("=== END PROCESS INFORMATION ===");
    } catch (...) {
        LogInfo("=== PROCESS INFORMATION ERROR ===");
        LogInfo("Exception occurred while gathering process information");
        LogInfo("=== END PROCESS INFORMATION ===");
    }
}

// Helper function to print system information
void PrintSystemInfo() {
    try {
        LogInfo("=== SYSTEM INFORMATION ===");

        // OS Version
        HMODULE ntdll = GetModuleHandleW(L"ntdll.dll");
        if (ntdll) {
            using RtlGetVersionFn = NTSTATUS(WINAPI*)(OSVERSIONINFOEXW*);
            auto rtl_get_version = reinterpret_cast<RtlGetVersionFn>(GetProcAddress(ntdll, "RtlGetVersion"));
            if (rtl_get_version) {
                OSVERSIONINFOEXW os_info{};
                os_info.dwOSVersionInfoSize = sizeof(OSVERSIONINFOEXW);
                if (rtl_get_version(&os_info) == 0) {
                    std::ostringstream oss;
                    oss << "OS Version: Windows " << os_info.dwMajorVersion << "." << os_info.dwMinorVersion
                        << " Build " << os_info.dwBuildNumber;
                    if (os_info.wServicePackMajor > 0) {
                        oss << " SP" << os_info.wServicePackMajor;
                    }
                    LogInfo("%s", oss.str().c_str());
                }
            }
        }

        // CPU Info
        SYSTEM_INFO sys_info{};
        GetSystemInfo(&sys_info);
        const char* arch_name = "Unknown";
        switch (sys_info.wProcessorArchitecture) {
            case PROCESSOR_ARCHITECTURE_AMD64: arch_name = "x64"; break;
            case PROCESSOR_ARCHITECTURE_INTEL: arch_name = "x86"; break;
            case PROCESSOR_ARCHITECTURE_ARM:   arch_name = "ARM"; break;
            case PROCESSOR_ARCHITECTURE_ARM64: arch_name = "ARM64"; break;
            default: break;
        }
        LogInfo("CPU - Processors: {}, Architecture: {}", sys_info.dwNumberOfProcessors, arch_name);

        // System memory
        MEMORYSTATUSEX mem_status{};
        mem_status.dwLength = sizeof(mem_status);
        if (GlobalMemoryStatusEx(&mem_status)) {
            double total_gb = static_cast<double>(mem_status.ullTotalPhys) / (1024.0 * 1024.0 * 1024.0);
            double avail_gb = static_cast<double>(mem_status.ullAvailPhys) / (1024.0 * 1024.0 * 1024.0);
            LogInfo("System Memory - Total: {:.2f} GB, Available: {:.2f} GB, Load: {}%", 
                    total_gb, avail_gb, mem_status.dwMemoryLoad);
        }

        // Current time
        time_t raw_time;
        time(&raw_time);
        struct tm local_tm{};
        if (localtime_s(&local_tm, &raw_time) == 0) {
            char buf[64];
            strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &local_tm);
            LogInfo("Crash Time: {}", buf);
        }

        LogInfo("=== END SYSTEM INFORMATION ===");
    } catch (...) {
        LogInfo("=== SYSTEM INFORMATION ERROR ===");
        LogInfo("Exception occurred while gathering system information");
        LogInfo("=== END SYSTEM INFORMATION ===");
    }
}

