// Helper function to print list of loaded modules
void PrintLoadedModules() {
    try {
        LogInfo("=== LOADED MODULES ===");

        HANDLE proc = GetCurrentProcess();
        std::vector<HMODULE> mods(1024);
        DWORD bytes_needed = 0;

        if (!EnumProcessModules(proc, mods.data(), static_cast<DWORD>(mods.size() * sizeof(HMODULE)), &bytes_needed)) {
            LogInfo("Failed to enumerate process modules - Error: %lu", GetLastError());
            LogInfo("=== END LOADED MODULES ===");
            return;
        }

        size_t count = bytes_needed / sizeof(HMODULE);
        LogInfo("Total loaded modules: %zu", count);

        for (size_t i = 0; i < count; ++i) {
            wchar_t mod_path[MAX_PATH];
            if (GetModuleFileNameW(mods[i], mod_path, MAX_PATH)) {
                std::string narrow_path;
                int needed = WideCharToMultiByte(CP_UTF8, 0, mod_path, -1, nullptr, 0, nullptr, nullptr);
                if (needed > 0) {
                    narrow_path.resize(needed - 1);
                    WideCharToMultiByte(CP_UTF8, 0, mod_path, -1, &narrow_path[0], needed, nullptr, nullptr);

                    MODULEINFO info{};
                    if (GetModuleInformation(proc, mods[i], &info, sizeof(info))) {
                        uintptr_t base = reinterpret_cast<uintptr_t>(info.lpBaseOfDll);
                        LogInfo("  [{}] {} (Base: 0x{:X}, Size: {} bytes)", 
                                i, narrow_path, base, info.SizeOfImage);
                    } else {
                        LogInfo("  [{}] {}", i, narrow_path);
                    }
                }
            } else {
                LogInfo("  [{}] <Unknown Module> (Handle: 0x%p)", i, static_cast<void*>(mods[i]));
            }
        }

        LogInfo("=== END LOADED MODULES ===");
    } catch (...) {
        LogInfo("=== LOADED MODULES ERROR ===");
        LogInfo("Exception occurred while enumerating loaded modules");
        LogInfo("=== END LOADED MODULES ===");
    }
}

// Shared crash report: header, optional section context, version/system/process info,
// exception details, memory load, recent detour calls, undestroyed guards, stack trace, loaded modules.
void LogCrashReport(PEXCEPTION_POINTERS ex, const char* title, bool include_section_context) {
    LogInfo("%s", title);

    if (include_section_context) {
        const char* monitoring = g_continuous_monitoring_section.load(std::memory_order_acquire);
        const char* rendering = g_rendering_ui_section.load(std::memory_order_acquire);
        LogInfo("g_continuous_monitoring_section: %s", monitoring ? monitoring : "(null)");
        LogInfo("g_rendering_ui_section: %s", rendering ? rendering : "(null)");
    }

    PrintVersionInfo();
    PrintSystemInfo();
    PrintProcessInfo();

    if (ex && ex->ExceptionRecord) {
        const auto& rec = *ex->ExceptionRecord;
        LogInfo("Exception Code: 0x%08X", rec.ExceptionCode);
        LogInfo("Exception Flags: 0x%08X", rec.ExceptionFlags);
        LogInfo("Exception Address: 0x%p", rec.ExceptionAddress);
    }

    MEMORYSTATUSEX mem_status{};
    mem_status.dwLength = sizeof(mem_status);
    if (GlobalMemoryStatusEx(&mem_status)) {
        LogInfo("System Memory Load: %u%%", mem_status.dwMemoryLoad);
    }

    uint64_t now_ns = utils::get_real_time_ns();
    std::string recent_calls = detour_call_tracker::FormatRecentDetourCalls(now_ns, 256);
    LogInfo("=== RECENT DETOUR CALLS ===");
    exit_handler::WriteMultiLineToDebugLog(recent_calls, "Recent Detour Calls: <none recorded>");
    LogInfo("=== END RECENT DETOUR CALLS ===");

    std::string undestroyed = detour_call_tracker::FormatUndestroyedGuards(now_ns);
    LogInfo("=== UNDESTROYED DETOUR GUARDS (CRASH DETECTION) ===");
    exit_handler::WriteMultiLineToDebugLog(undestroyed, "Undestroyed Detour Guards: 0");
    LogInfo("=== END UNDESTROYED DETOUR GUARDS ===");

    LogInfo("=== GENERATING STACK TRACE ===");
    CONTEXT* ctx = ex ? ex->ContextRecord : nullptr;
    auto frames = stack_trace::GenerateStackTrace(ctx);
    LogInfo("=== STACK TRACE ===");
    for (const auto& line : frames) {
        LogInfo("%s", line.c_str());
    }
    LogInfo("=== END STACK TRACE ===");

    PrintLoadedModules();
    display_commander::logger::FlushLogs();
}
