#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    unsigned long long x;
    if (!(cin >> x)) return 0;

    // Construct a grid to encode the number x using bit representation
    const int size = 64;
    vector<vector<int>> grid(size, vector<int>(size, 0));

    // Fill lower-left triangular region in snake pattern (alternating row directions)
    for (int row = 0; row < size; ++row) {
        if (row % 2 == 0) {
            // Left-to-right fill
            for (int col = 0; col <= row; ++col) {
                grid[row][col] = 1;
            }
        } else {
            // Right-to-left fill within the first row+1 columns
            for (int col = 0; col <= row; ++col) {
                grid[row][row - col] = 1;
            }
        }
    }

    // Create a vertical corridor along the rightmost column
    for (int row = 0; row < size; ++row) {
        grid[row][size - 1] = 1;
    }

    // For each set bit in x, create horizontal extension from the snake path to the rightmost column
    for (int bit = 0; bit < size; ++bit) {
        if (((x >> bit) & 1ULL) == 0) continue;

        if (bit % 2 == 0) {
            // Even rows: extend from (bit, bit) to the right edge
            for (int col = bit; col < size; ++col) {
                grid[bit][col] = 1;
            }
        } else {
            // Odd rows: extend from (bit, size-1-bit) to the right edge
            for (int col = size - 1 - bit; col < size; ++col) {
                grid[bit][col] = 1;
            }
        }
    }

    // Output the grid
    cout << size << "\n";
    for (int i = 0; i < size; ++i) {
        for (int j = 0; j < size; ++j) {
            if (j > 0) cout << ' ';
            cout << grid[i][j];
        }
        cout << "\n";
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <climits>
using namespace std;

class Solution {
public:
    // Helper: determine smallest and largest bloom days
    pair<int, int> getMinAndMax(const vector<int>& days) {
        int minVal = INT_MAX;
        int maxVal = INT_MIN;
        for (int d : days) {
            if (d > maxVal) maxVal = d;
            if (d < minVal) minVal = d;
        }
        return make_pair(minVal, maxVal);
    }

    // Check if we can form at least 'm' bouquets by 'targetDay'
    bool canProduceBouquets(const vector<int>& bloomDays, int neededBouquets, int flowersPerBouquet, int targetDay) {
        int formed = 0;
        int currentStreak = 0;
        for (int day : bloomDays) {
            if (day <= targetDay) {
                ++currentStreak;
                if (currentStreak == flowersPerBouquet) {
                    ++formed;
                    currentStreak = 0;
                }
            } else {
                currentStreak = 0;
            }
        }
        return formed >= neededBouquets;
    }

    // Brute-force approach: try each day from min to max
    int bruteForceMinDays(vector<int>& bloomDays, int m, int k) {
        long long requiredFlowers = 1LL * m * k;
        if (requiredFlowers > bloomDays.size()) return -1;

        auto [lowBound, highBound] = getMinAndMax(bloomDays);

        for (int candidateDay = lowBound; candidateDay <= highBound; ++candidateDay) {
            if (canProduceBouquets(bloomDays, m, k, candidateDay)) {
                return candidateDay;
            }
        }
        return -1;
    }

    // Optimized: binary search over possible days
    int optimizedMinDays(vector<int>& bloomDays, int m, int k) {
        long long needed = 1LL * m * k;
        if (needed > bloomDays.size()) return -1;

        auto [minDay, maxDay] = getMinAndMax(bloomDays);
        int left = minDay;
        int right = maxDay;

        while (left < right) {
            int mid = left + (right - left) / 2;
            if (canProduceBouquets(bloomDays, m, k, mid)) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }
        return left;
    }
};

int main() {
    vector<int> bloomSchedule = {7,7,7,7,12,7,7};
    int bouquetCount = 2;
    int petalsPerBouquet = 3;

    Solution solver;
    int result = solver.optimizedMinDays(bloomSchedule, bouquetCount, petalsPerBouquet);
    cout << result << endl;

    return 0;
}

