    ASSERT_EQ(hipRes, hipSuccess);

    hipRes = hipHostMalloc(&proxyContext->fifoShm, proxyStateObj.buffSizes[NCCL_PROTO_SIMPLE], hipHostMallocDefault);
    ASSERT_EQ(hipRes, hipSuccess);

    hipRes = hipMalloc(&proxyContext->sendMem, sizeof(ncclSendMem));
    ASSERT_EQ(hipRes, hipSuccess);

    hipRes = hipHostMalloc(&proxyContext->recvMem, sizeof(ncclRecvMem), hipHostMallocDefault);
    ASSERT_EQ(hipRes, hipSuccess);

    hipRes = hipStreamCreateWithFlags(&proxyContext->streamHandle, hipStreamNonBlocking);
    ASSERT_EQ(hipRes, hipSuccess);

    for (int i = 0; i < NCCL_STEPS; ++i) {
      hipRes = hipEventCreate(&proxyContext->completionEvents[i]);
      ASSERT_EQ(hipRes, hipSuccess);
    }

    size_t shmSize = 2048;
    int useLegacy = 1;
    int tpProxyRank = 0;
    ncclShmIpcDesc_t shmDesc;
    void *hostPtr = nullptr;
    void *devicePtr = nullptr;

    ncclResult_t res = ncclShmAllocateShareableBuffer(shmSize, useLegacy, &shmDesc, &hostPtr, &devicePtr);
    ASSERT_EQ(res, ncclSuccess) << "Failed to allocate shareable buffer in SetUp()";
    proxyContext->ipcDescriptor = shmDesc;

    connObj = {
        .proxyAppend = {},
        .proxyAppendPtr = nullptr,
        .transportResources = proxyContext
    };
  }

  void TearDown() override {
    if (proxyContext) {
      if (proxyContext->streamHandle) {
        hipStreamDestroy(proxyContext->streamHandle);
      }
      for (int i = 0; i < NCCL_STEPS; ++i) {
        if (proxyContext->completionEvents[i]) {
          hipEventDestroy(proxyContext->completionEvents[i]);
        }
      }
      if (proxyContext->fifoDev) {
        hipFree(proxyContext->fifoDev);
      }
      if (proxyContext->ceMem) {
        hipHostFree(proxyContext->ceMem);
      }
      if (proxyContext->recvMem) {
        hipHostFree(proxyContext->recvMem);
      }
      if (proxyContext->fifoShm) {
        hipHostFree(proxyContext->fifoShm);
      }
    }
  }
};

