TEST_F(ShmTests, ProgressSenderProxy) {
  argsObj.state = ncclProxyOpReady;
  argsObj.protocol = NCCL_PROTO_SIMPLE;
  argsObj.nsubs = 1;
  argsObj.chunkSteps = 1;
  argsObj.sliceSteps = 1;
  argsObj.subs[0].nsteps = 4;
  argsObj.subs[0].connection = &connObj;

  ncclResult_t res = progressShmSender(&proxyStateObj, &argsObj);
  EXPECT_EQ(res, ncclSuccess);
  EXPECT_EQ(argsObj.state, ncclProxyOpProgress);
  EXPECT_EQ(argsObj.subs[0].base, 0);
  EXPECT_EQ(argsObj.subs[0].posted, 0);
  EXPECT_EQ(argsObj.subs[0].transmitted, 0);
  EXPECT_EQ(argsObj.subs[0].done, 0);

  for (int i = 0; i < argsObj.subs[0].nsteps; ++i) {
    proxyContext->ceMem->tail = i + 1;
    proxyContext->ceMem->connFifo[i % NCCL_STEPS].size =
        proxyStateObj.buffSizes[NCCL_PROTO_SIMPLE] / NCCL_STEPS;

    res = progressShmSender(&proxyStateObj, &argsObj);
    EXPECT_EQ(res, ncclSuccess);
    hipStreamSynchronize(proxyContext->streamHandle);

    res = progressShmSender(&proxyStateObj, &argsObj);
    EXPECT_EQ(res, ncclSuccess);
    EXPECT_GE(argsObj.subs[0].transmitted, i + 1);
    EXPECT_GE(argsObj.subs[0].done, i + 1);
  }

  EXPECT_EQ(argsObj.state, ncclProxyOpNone);
  EXPECT_EQ(argsObj.subs[0].transmitted, argsObj.subs[0].nsteps);
  EXPECT_EQ(argsObj.subs[0].done, argsObj.subs[0].nsteps);
  EXPECT_EQ(argsObj.done, argsObj.nsubs);
  EXPECT_EQ(proxyContext->recvMem->tail, argsObj.subs[0].base + argsObj.subs[0].done);
}

