TEST_F(ShmTests, SetupSenderProxy_Success) {
  ncclProxyConnection localConn;
  memset(&localConn, 0, sizeof(localConn));
  proxyStateObj.tpRank = 0;

  operationRequest req;
  req.byteCount = 1024;
  req.legacyMode = false;

  connectionDescriptor *resp = (connectionDescriptor *)calloc(1, sizeof(connectionDescriptor));

  int status = 0;
  int reqSz = sizeof(operationRequest);
  int respSz = sizeof(connectionDescriptor);

  ncclResult_t res = setupShmSender(&localConn, &proxyStateObj, &req,
                                    reqSz, resp, respSz, &status);

  EXPECT_EQ(res, ncclSuccess);
  EXPECT_NE(localConn.transportResources, nullptr);
  EXPECT_NE(resp->memRegion.hostAddr, nullptr);
  EXPECT_NE(resp->memRegion.devAddr, nullptr);

  proxyData *ctx = (proxyData *)localConn.transportResources;
  memset(&ctx->ipcDescriptor, 0, sizeof(ncclShmIpcDesc_t));
  memset(&resp->ipcDesc, 0, sizeof(ncclShmIpcDesc_t));
  EXPECT_EQ(memcmp(&ctx->ipcDescriptor, &resp->ipcDesc, sizeof(ncclShmIpcDesc_t)), 0);

  if (ctx) {
    ncclShmIpcClose(&ctx->ipcDescriptor);
    free(ctx);
    localConn.transportResources = nullptr;
  }
  free(resp);
}

