// Utility function to categorize files based on their existence and state
void GetMissingVsExistingFiles(const TArray<FString>& InFiles, 
                               TArray<FString>& OutMissingFiles, 
                               TArray<FString>& OutAllExistingFiles, 
                               TArray<FString>& OutOtherThanAddedExistingFiles)
{
    FGitSourceControlModule& GitSourceControl = FModuleManager::GetModuleChecked<FGitSourceControlModule>("GitSourceControl");
    FGitSourceControlProvider& Provider = GitSourceControl.GetProvider();

    TArray<TSharedRef<ISourceControlState, ESPMode::ThreadSafe>> LocalStates;
    Provider.GetState(InFiles, LocalStates, EStateCacheUsage::Use);

    for (const auto& State : LocalStates)
    {
        if (FPaths::FileExists(State->GetFilename()))
        {
            if (State->IsAdded())
            {
                OutAllExistingFiles.Add(State->GetFilename());
            }
            else
            {
                OutOtherThanAddedExistingFiles.Add(State->GetFilename());
                OutAllExistingFiles.Add(State->GetFilename());
            }
        }
        else
        {
            OutMissingFiles.Add(State->GetFilename());
        }
    }
}

// Worker for reverting local changes
FName FGitRevertWorker::GetName() const
{
    return "Revert";
}

bool FGitRevertWorker::Execute(FGitSourceControlCommand& InCommand)
{
    // Categorize files by their current state
    TArray<FString> MissingFiles;
    TArray<FString> AllExistingFiles;
    TArray<FString> OtherThanAddedExistingFiles;
    GetMissingVsExistingFiles(InCommand.Files, MissingFiles, AllExistingFiles, OtherThanAddedExistingFiles);

    // Handle missing files (added then deleted)
    if (MissingFiles.Num() > 0)
    {
        InCommand.bCommandSuccessful = GitSourceControlUtils::RunCommand(
            TEXT("rm"),
            InCommand.PathToGitBinary,
            InCommand.PathToRepositoryRoot,
            TArray<FString>(),
            MissingFiles,
            InCommand.InfoMessages,
            InCommand.ErrorMessages
        );
    }

    // Reset staged changes
    if (AllExistingFiles.Num() > 0)
    {
        InCommand.bCommandSuccessful = GitSourceControlUtils::RunCommand(
            TEXT("reset"),
            InCommand.PathToGitBinary,
            InCommand.PathToRepositoryRoot,
            TArray<FString>(),
            AllExistingFiles,
            InCommand.InfoMessages,
            InCommand.ErrorMessages
        );
    }

    // Revert working copy changes
    if (OtherThanAddedExistingFiles.Num() > 0)
    {
        InCommand.bCommandSuccessful = GitSourceControlUtils::RunCommand(
            TEXT("checkout"),
            InCommand.PathToGitBinary,
            InCommand.PathToRepositoryRoot,
            TArray<FString>(),
            OtherThanAddedExistingFiles,
            InCommand.InfoMessages,
            InCommand.ErrorMessages
        );
    }

    // Refresh file states after revert operations
    GitSourceControlUtils::RunUpdateStatus(
        InCommand.PathToGitBinary,
        InCommand.PathToRepositoryRoot,
        InCommand.Files,
        InCommand.ErrorMessages,
        States
    );

    return InCommand.bCommandSuccessful;
}

bool FGitRevertWorker::UpdateStates() const
{
    return GitSourceControlUtils::UpdateCachedStates(States);
}

