// Worker for updating file status information
FName FGitUpdateStatusWorker::GetName() const
{
    return "UpdateStatus";
}

bool FGitUpdateStatusWorker::Execute(FGitSourceControlCommand& InCommand)
{
    check(InCommand.Operation->GetName() == GetName());
    TSharedRef<FUpdateStatus, ESPMode::ThreadSafe> Operation = StaticCastSharedRef<FUpdateStatus>(InCommand.Operation);

    if (InCommand.Files.Num() > 0)
    {
        InCommand.bCommandSuccessful = GitSourceControlUtils::RunUpdateStatus(
            InCommand.PathToGitBinary,
            InCommand.PathToRepositoryRoot,
            InCommand.Files,
            InCommand.ErrorMessages,
            States
        );

        GitSourceControlUtils::RemoveRedundantErrors(InCommand, TEXT("' is outside repository"));

        if (Operation->ShouldUpdateHistory())
        {
            for (int32 Index = 0; Index < States.Num(); Index++)
            {
                FString& File = InCommand.Files[Index];
                TGitSourceControlHistory History;

                if (States[Index].IsConflicted())
                {
                    // Get history from MERGE_HEAD in case of conflicts
                    GitSourceControlUtils::RunGetHistory(
                        InCommand.PathToGitBinary,
                        InCommand.PathToRepositoryRoot,
                        File,
                        true,
                        InCommand.ErrorMessages,
                        History
                    );
                }

                // Get standard file history
                InCommand.bCommandSuccessful &= GitSourceControlUtils::RunGetHistory(
                    InCommand.PathToGitBinary,
                    InCommand.PathToRepositoryRoot,
                    File,
                    false,
                    InCommand.ErrorMessages,
                    History
                );

                Histories.Add(*File, History);
            }
        }
    }
    else
    {
        // If no specific files, get all modified files using project directory
        if (Operation->ShouldGetOpenedOnly())
        {
            TArray<FString> Files;
            Files.Add(FPaths::ConvertRelativePathToFull(FPaths::ProjectDir()));
            InCommand.bCommandSuccessful = GitSourceControlUtils::RunUpdateStatus(
                InCommand.PathToGitBinary,
                InCommand.PathToRepositoryRoot,
                Files,
                InCommand.ErrorMessages,
                States
            );
        }
    }

    return InCommand.bCommandSuccessful;
}

bool FGitUpdateStatusWorker::UpdateStates() const
{
    bool bUpdated = GitSourceControlUtils::UpdateCachedStates(States);

    FGitSourceControlModule& GitSourceControl = FModuleManager::LoadModuleChecked<FGitSourceControlModule>("GitSourceControl");
    FGitSourceControlProvider& Provider = GitSourceControl.GetProvider();

    // Apply stored history to file states
    for (const auto& History : Histories)
    {
        TSharedRef<FGitSourceControlState, ESPMode::ThreadSafe> State = Provider.GetStateInternal(History.Key);
        State->History = History.Value;
        State->TimeStamp = FDateTime::Now();
        bUpdated = true;
    }

    return bUpdated;
}

