#include <iostream>
#include <vector>
using namespace std;

const int MAX_LEVEL = 30;
int heap[MAX_LEVEL][MAX_LEVEL]; // represents the heap structure
struct Operation {
    int from_row, from_col, to_row, to_col;
};

vector<Operation> operations;

// Helper function to swap two elements and record the operation
void execute_exchange(int r1, int c1, int r2, int c2) {
    operations.push_back({r1, c1, r2, c2});
    int temp = heap[r1][c1];
    heap[r1][c1] = heap[r2][c2];
    heap[r2][c2] = temp;
}

int main() {
    // Read input values into the heap structure
    for (int row = 0; row < MAX_LEVEL; ++row) {
        for (int col = 0; col <= row; ++col) {
            cin >> heap[row][col];
        }
    }

    // Process heap using top-down approach with iterative sifting
    int operation_count = 0;
    const int LIMIT = 10000;

    // Start from the last non-leaf node and work backwards
    for (int start_row = MAX_LEVEL - 2; start_row >= 0; --start_row) {
        for (int start_col = 0; start_col <= start_row; ++start_col) {
            int current_row = start_row;
            int current_col = start_col;

            // Continue sifting down while within bounds and heap property violated
            while (current_row < MAX_LEVEL - 1 && operation_count < LIMIT) {
                int parent_val = heap[current_row][current_col];
                int left_child = heap[current_row + 1][current_col];
                int right_child = heap[current_row + 1][current_col + 1];

                // Determine smallest among parent and children
                int smallest_row = current_row;
                int smallest_col = current_col;

                if (left_child < parent_val) {
                    smallest_row = current_row + 1;
                    smallest_col = current_col;
                }

                if (right_child < heap[smallest_row][smallest_col]) {
                    smallest_row = current_row + 1;
                    smallest_col = current_col + 1;
                }

                // If parent is already smallest, heap property satisfied
                if (smallest_row == current_row && smallest_col == current_col) {
                    break;
                }

                // Perform swap and continue sifting
                execute_exchange(current_row, current_col, smallest_row, smallest_col);
                operation_count++;

                // Move to child position for next iteration
                current_row = smallest_row;
                current_col = smallest_col;
            }

            // Check limit after each element processing
            if (operation_count >= LIMIT) {
                break;
            }
        }

        // Check global limit after each row
        if (operation_count >= LIMIT) {
            break;
        }
    }

    // Output results
    cout << operations.size() << endl;
    for (const Operation& op : operations) {
        cout << op.from_row << " " << op.from_col << " " 
             << op.to_row << " " << op.to_col << endl;
    }

    return 0;
}

