// Helper function to verify person count matches expected value (8)
static void confirmPersonCountStar(Connection* conn) {
    auto result = conn->query("MATCH (a:person) RETURN COUNT(*)");
    ASSERT_TRUE(result->hasNext());
    auto tuple = result->getNext();
    ASSERT_EQ(tuple->getValue(0)->getValue<int64_t>(), 8);
    ASSERT_FALSE(result->hasNext());
}

