// Long-running query interruption test
static void runLengthyQuery(Connection* conn) {
    auto result = conn->query(
        "UNWIND RANGE(1,100000) AS x UNWIND RANGE(1, 100000) AS y RETURN COUNT(x + y);");
    ASSERT_FALSE(result->isSuccess());
    ASSERT_EQ(result->getErrorMessage(), "Interrupted.");
}

TEST_F(ApiTest, Interrupt) {
    std::thread lengthyThread(runLengthyQuery, conn.get());
    std::atomic<bool> completed{false};

    std::thread interrupter([&]() {
        while (!completed) {
#ifdef _WIN32
            Sleep(1000);
#else
            sleep(1);
#endif
            conn->interrupt();
        }
    });

    lengthyThread.join();
    completed = true;
    interrupter.join();
}
#endif

