std::size_t cudnn_get_workspace_size(int B, int T, int Hq, int Hkv, int HS, cudnnHandle_t handle);

/**
 * @brief Checks a cuDNN status code and exits on error.
 */
static void cuDNNCheck_(cudnnStatus_t error, const char *file, int line) {
    if (error != CUDNN_STATUS_SUCCESS) {
        printf("[CUDNN ERROR] at file %s:%d:\n%s\n", file, line, cudnnGetErrorString(error));
        exit(EXIT_FAILURE);
    }
}
#define cuDNNCheck(err) (cuDNNCheck_(err, __FILE__, __LINE__))

/**
 * @brief Checks a cuDNN frontend error object and exits on error.
 */
static void checkCudnnFE(const fe::error_object& e, const char *file, int line) {
    if(!e.is_good()) {
        printf("[CUDNN ERROR] at file %s:%d:\n%s\n", file, line, e.err_msg.c_str());
        exit(EXIT_FAILURE);
    }
}
#define checkCudnnFE(err) checkCudnnFE(err, __FILE__, __LINE__)

/**
 * @brief Unique identifiers for cuDNN graph tensors.
 */
enum TensorUIDs {
    Q_TENSOR_UID,
    K_TENSOR_UID,
    V_TENSOR_UID,
    SCALE_TENSOR_UID,
    OUTPUT_TENSOR_UID,
    STATS_TENSOR_UID,
    DOUTPUT_TENSOR_UID,
    DQ_TENSOR_UID,
    DK_TENSOR_UID,
    DV_TENSOR_UID
};

// Cache type definitions
using cache_fwd = std::map<std::tuple<int,int,int,int,int,int>, std::shared_ptr<fe::graph::Graph>>;
using cache_bwd = std::map<std::tuple<int,int,int,int,int>, std::shared_ptr<fe::graph::Graph>>;

/**
 * @brief Retrieves or constructs a forward attention graph.
 */
auto get_or_create_forward_graph(int B, int Hq, int Hkv, int T, int HS, bool inference_only, cudnnHandle_t handle) {
    thread_local cache_fwd fwd_cache;
    auto key = std::make_tuple(B, Hq, Hkv, T, HS, static_cast<int>(inference_only));
    auto it = fwd_cache.find(key);
    if (it != fwd_cache.end()) {
        return it->second;
    }

    auto graph = std::make_shared<fe::graph::Graph>();
    graph->set_io_data_type(fe::DataType_t::BFLOAT16)
          .set_intermediate_data_type(fe::DataType_t::FLOAT)
          .set_compute_data_type(fe::DataType_t::FLOAT);

    int total_heads = Hq + 2 * Hkv;

    // Define query tensor
    auto Q_tensor = graph->tensor(fe::graph::Tensor_attributes()
        .set_name("query")
        .set_dim({B, Hq, T, HS})
        .set_uid(Q_TENSOR_UID)
        .set_stride({total_heads * HS * T, HS, total_heads * HS, 1}));

    // Define key tensor
    auto K_tensor = graph->tensor(fe::graph::Tensor_attributes()
        .set_name("key")
        .set_dim({B, Hkv, T, HS})
        .set_uid(K_TENSOR_UID)
        .set_stride({total_heads * HS * T, HS, total_heads * HS, 1}));

    // Define value tensor
    auto V_tensor = graph->tensor(fe::graph::Tensor_attributes()
        .set_name("value")
        .set_dim({B, Hkv, T, HS})
        .set_uid(V_TENSOR_UID)
        .set_stride({total_heads * HS * T, HS, total_heads * HS, 1}));

    // Define attention scale tensor
    auto scale_tensor = graph->tensor(fe::graph::Tensor_attributes()
        .set_name("scale")
        .set_dim({1, 1, 1, 1})
        .set_stride({1, 1, 1, 1})
        .set_uid(SCALE_TENSOR_UID)
        .set_is_pass_by_value(true)
        .set_data_type(fe::DataType_t::FLOAT));

    // Configure SDPA operation
    auto sdpa_attrs = fe::graph::SDPA_attributes().set_name("scaled_dot_product_attention");
    sdpa_attrs.set_is_inference(inference_only);
    sdpa_attrs.set_attn_scale(scale_tensor);
    sdpa_attrs.set_causal_mask(true);

    // Create SDPA operation
    auto [output_tensor, stats_tensor] = graph->sdpa(Q_tensor, K_tensor, V_tensor, sdpa_attrs);

    // Set output properties
    output_tensor->set_output(true)
                  .set_dim({B, Hq, T, HS})
                  .set_stride({Hq * HS * T, HS, Hq * HS, 1})
                  .set_uid(OUTPUT_TENSOR_UID);

    if (!inference_only) {
        stats_tensor->set_output(true)
                    .set_data_type(fe::DataType_t::FLOAT)
                    .set_dim({B, Hq, T, 1})
                    .set_stride({Hq * T, T, 1, 1})
                    .set_uid(STATS_TENSOR_UID);
    }

    // Validate and build graph
    checkCudnnFE(graph->validate());
    checkCudnnFE(graph->build_operation_graph(handle));
    auto plans = graph->create_execution_plans({fe::HeurMode_t::A});
    checkCudnnFE(graph->check_support(handle));
    checkCudnnFE(graph->build_plans(handle));

    fwd_cache.insert({key, graph});
    return graph;
}

/**
 * @brief Retrieves or constructs a backward attention graph.
 */
auto get_or_create_backward_graph(int B, int Hq, int Hkv, int T, int HS, cudnnHandle_t handle) {
    thread_local cache_bwd bwd_cache;
    auto key = std::make_tuple(B, Hq, Hkv, T, HS);
    auto it = bwd_cache.find(key);
    if (it != bwd_cache.end()) {
        return it->second;
    }

    auto graph = std::make_shared<fe::graph::Graph>();
    graph->set_io_data_type(fe::DataType_t::BFLOAT16)
          .set_intermediate_data_type(fe::DataType_t::FLOAT)
          .set_compute_data_type(fe::DataType_t::FLOAT);

    int total_heads = Hq + 2 * Hkv;

    // Define input tensors
    auto Q_tensor = graph->tensor(fe::graph::Tensor_attributes()
        .set_name("query")
        .set_dim({B, Hq, T, HS})
        .set_uid(Q_TENSOR_UID)
        .set_stride({total_heads * HS * T, HS, total_heads * HS, 1}));

    auto K_tensor = graph->tensor(fe::graph::Tensor_attributes()
        .set_name("key")
        .set_dim({B, Hkv, T, HS})
        .set_uid(K_TENSOR_UID)
        .set_stride({total_heads * HS * T, HS, total_heads * HS, 1}));

    auto V_tensor = graph->tensor(fe::graph::Tensor_attributes()
        .set_name("value")
        .set_dim({B, Hkv, T, HS})
        .set_uid(V_TENSOR_UID)
        .set_stride({total_heads * HS * T, HS, total_heads * HS, 1}));

    auto O_tensor = graph->tensor(fe::graph::Tensor_attributes()
        .set_name("output")
        .set_dim({B, Hq, T, HS})
        .set_uid(OUTPUT_TENSOR_UID)
        .set_stride({Hq * HS * T, HS, Hq * HS, 1}));

    auto dO_tensor = graph->tensor(fe::graph::Tensor_attributes()
        .set_name("grad_output")
        .set_dim({B, Hq, T, HS})
        .set_uid(DOUTPUT_TENSOR_UID)
        .set_stride({Hq * HS * T, HS, Hq * HS, 1}));

    auto stats_tensor = graph->tensor(fe::graph::Tensor_attributes()
        .set_name("stats")
        .set_dim({B, Hq, T, 1})
        .set_uid(STATS_TENSOR_UID)
        .set_stride({Hq * T, T, 1, 1})
        .set_data_type(fe::DataType_t::FLOAT));

    auto scale_tensor = graph->tensor(fe::graph::Tensor_attributes()
        .set_name("scale")
        .set_dim({1, 1, 1, 1})
        .set_stride({1, 1, 1, 1})
        .set_uid(SCALE_TENSOR_UID)
        .set_is_pass_by_value(true)
        .set_data_type(fe::DataType_t::FLOAT));

    // Determine deterministic algorithm usage
    bool use_deterministic = false;
#if CUDNN_FRONTEND_MAJOR_VERSION > 1 || CUDNN_FRONTEND_MINOR_VERSION >= 5
    {
        int device_id;
        cudaGetDevice(&device_id);
        cudaDeviceProp props;
        cudaGetDeviceProperties(&props, device_id);
        int sm_version = props.major * 10 + props.minor;
        size_t cudnn_ver = cudnnGetVersion();
        if (sm_version < 100 || cudnn_ver >= 91800) {
            use_deterministic = true;
        }
    }
#endif

    // Configure backward SDPA operation
    auto sdpa_bwd_attrs = fe::graph::SDPA_backward_attributes().set_name("scaled_dot_product_attention_backward");
#if CUDNN_FRONTEND_MAJOR_VERSION > 1 || CUDNN_FRONTEND_MINOR_VERSION >= 5
    sdpa_bwd_attrs.set_deterministic_algorithm(use_deterministic);
#endif
    sdpa_bwd_attrs.set_causal_mask(true);
    sdpa_bwd_attrs.set_attn_scale(scale_tensor);

    // Create backward SDPA operation
    auto [dQ_tensor, dK_tensor, dV_tensor] = graph->sdpa_backward(Q_tensor, K_tensor, V_tensor, O_tensor, dO_tensor, stats_tensor, sdpa_bwd_attrs);

    // Set gradient output properties
    dQ_tensor->set_output(true)
             .set_dim({B, Hq, T, HS})
             .set_stride({total_heads * HS * T, HS, total_heads * HS, 1})
             .set_uid(DQ_TENSOR_UID);

    dK_tensor->set_output(true)
             .set_dim({B, Hkv, T, HS})
             .set_stride({total_heads * HS * T, HS, total_heads * HS, 1})
             .set_uid(DK_TENSOR_UID);

    dV_tensor->set_output(true)
             .set_dim({B, Hkv, T, HS})
             .set_stride({total_heads * HS * T, HS, total_heads * HS, 1})
             .set_uid(DV_TENSOR_UID);

    // Validate and build graph
    checkCudnnFE(graph->validate());
    checkCudnnFE(graph->build_operation_graph(handle));
    auto plans = graph->create_execution_plans({fe::HeurMode_t::A});
    checkCudnnFE(graph->check_support(handle));
    checkCudnnFE(graph->build_plans(handle));

    bwd_cache.insert({key, graph});
    return graph;
}

/**
 * @brief Executes the forward pass of scaled dot-product attention using cuDNN.
 */
void attention_forward_cudnn(nv_bfloat16* out,
                             float* stats,
                             const nv_bfloat16* inp,
                             std::byte* workspace,
                             cudnnHandle_t handle,
                             int B, int T, int Hq, int Hkv, int HS,
                             cudaStream_t stream) {
    bool inference_only = (stats == nullptr);
    cuDNNCheck(cudnnSetStream(handle, stream));

    auto graph = get_or_create_forward_graph(B, Hq, Hkv, T, HS, inference_only, handle);

    // Compute pointer offsets for Q, K, V
    const void* devPtrQ = inp;
    const void* devPtrK = inp + Hq * HS;
    const void* devPtrV = inp + (Hq + Hkv) * HS;

    float attn_scale_cpu = 1.0f / std::sqrt(static_cast<float>(HS));
    void* devPtrO = out;

    // Build variant pack
    std::unordered_map<int64_t, void*> variant_pack = {
        {Q_TENSOR_UID, (void*)devPtrQ},
        {K_TENSOR_UID, (void*)devPtrK},
        {V_TENSOR_UID, (void*)devPtrV},
        {SCALE_TENSOR_UID, &attn_scale_cpu},
        {OUTPUT_TENSOR_UID, devPtrO}
    };

    if (!inference_only) {
        variant_pack[STATS_TENSOR_UID] = stats;
    }

    // Execute graph
    checkCudnnFE(graph->execute(handle, variant_pack, workspace));
    CUDA_CHECK(cudaGetLastError());
}

/**
 * @brief Executes the backward pass of scaled dot-product attention using cuDNN.
 */
void attention_backward_cudnn(nv_bfloat16* dqkvr,
                              const float* stats,
                              const nv_bfloat16* o,
                              const nv_bfloat16* dout,
                              const nv_bfloat16* qkvr,
                              std::byte* workspace,
                              cudnnHandle_t handle,
                              int B, int T, int Hq, int Hkv, int HS,
                              cudaStream_t stream) {
    auto graph = get_or_create_backward_graph(B, Hq, Hkv, T, HS, handle);

    // Prepare tensor pointers
    void* devPtrQ = (void*)qkvr;
    void* devPtrK = (void*)(qkvr + Hq * HS);
    void* devPtrV = (void*)(qkvr + (Hq + Hkv) * HS);
    void* devPtrO = (void*)o;
    void* devPtrdO = (void*)dout;
    void* devPtrStats = (void*)stats;

    float attn_scale_cpu = 1.0f / std::sqrt(static_cast<float>(HS));
    void* devPtrdQ = dqkvr;
    void* devPtrdK = dqkvr + Hq * HS;
    void* devPtrdV = dqkvr + (Hq + Hkv) * HS;

    // Build variant pack
    std::unordered_map<int64_t, void*> variant_pack = {
        {Q_TENSOR_UID, devPtrQ},
        {K_TENSOR_UID, devPtrK},
        {V_TENSOR_UID, devPtrV},
        {OUTPUT_TENSOR_UID, devPtrO},
        {DOUTPUT_TENSOR_UID, devPtrdO},
        {STATS_TENSOR_UID, devPtrStats},
        {DQ_TENSOR_UID, devPtrdQ},
        {DK_TENSOR_UID, devPtrdK},
        {DV_TENSOR_UID, devPtrdV},
        {SCALE_TENSOR_UID, &attn_scale_cpu}
    };

    cuDNNCheck(cudnnSetStream(handle, stream));
    checkCudnnFE(graph->execute(handle, variant_pack, workspace));
    CUDA_CHECK(cudaGetLastError());
}

/**
 * @brief Gets the required GPU workspace size for attention operations.
 */
std::size_t cudnn_get_workspace_size(int B, int T, int Hq, int Hkv, int HS, cudnnHandle_t handle) {
    auto graph = get_or_create_backward_graph(B, Hq, Hkv, T, HS, handle);
    return graph->get_workspace_size();
}

/**
 * @brief Creates a new cuDNN handle.
 */
cudnnHandle_t create_cudnn_handle() {
    cudnnHandle_t handle;
    cuDNNCheck(cudnnCreate(&handle));
    return handle;
}

/**
 * @brief Destroys a cuDNN handle and releases associated resources.
 */
void destroy_cudnn_handle(cudnnHandle_t handle) noexcept {
    if (handle) {
        (void)cudnnDestroy(handle);
    }
}

