// Static member definitions
std::shared_ptr<EnderDragon> EnderDragonRenderer::bossInstance;
int                          EnderDragonRenderer::currentModel;

// Helper function to calculate rotation angle from direction vector
float calculateRotationAngle(float dx, float dz) {
    return (float)(-atan2(dz, dx) * 180.0f / M_PI - 90.0f);
}

// Helper function to calculate elevation angle
float calculateElevationAngle(float horizontalDist, float verticalDist) {
    return (float)(-atan2(horizontalDist, verticalDist) * 180.0f / M_PI - 90.0f);
}

EnderDragonRenderer::EnderDragonRenderer()
: MobRenderer(new DragonModel(0), 0.5f) {
    currentModel = 0;
    dragonModel  = static_cast<DragonModel*>(model);
    setArmor(model);
}

void EnderDragonRenderer::setupRotations(
    std::shared_ptr<Mob> _mob,
    float                bob,
    float                bodyRot,
    float                a
) {
    // Cast to EnderDragon type
    std::shared_ptr<EnderDragon> mob =
        std::dynamic_pointer_cast<EnderDragon>(_mob);

    // Get latency position components
    double      posData[3];
    doubleArray positions = doubleArray(posData, 3);
    mob->getLatencyPos(positions, 7, a);
    float yawRotation = posData[0];

    // Calculate tilt from dragon's orientation
    float pitchTilt = mob->getTilt(a);

    // Apply rotations in sequence
    glRotatef(-yawRotation, 0, 1, 0);
    glRotatef(pitchTilt, 1, 0, 0);
    glTranslatef(0, 0, 1);

    // Handle death animation rotation
    if (mob->deathTime > 0) {
        float timeFactor = (mob->deathTime + a - 1) / 20.0f * 1.6f;
        float fallEffect = std::sqrt(timeFactor);
        fallEffect = std::min(fallEffect, 1.0f);
        glRotatef(fallEffect * getFlipDegrees(mob), 0, 0, 1);
    }
}

void EnderDragonRenderer::renderModel(
    std::shared_ptr<Entity> _mob,
    float                   wp,
    float                   ws,
    float                   bob,
    float                   headRotMinusBodyRot,
    float                   headRotx,
    float                   scale
) {
    // Cast to EnderDragon type
    std::shared_ptr<EnderDragon> mob =
        std::dynamic_pointer_cast<EnderDragon>(_mob);

    // Render death effect when dragon is dying
    if (mob->dragonDeathTime > 0) {
        float transparency = mob->dragonDeathTime / 200.0f;

        // Configure depth and alpha testing
        glDepthFunc(GL_LEQUAL);
        glEnable(GL_ALPHA_TEST);
        glAlphaFunc(GL_GREATER, transparency);

        // Bind shuffle texture for death effect
        bindTexture(mob->customTextureUrl, TN_MOB_ENDERDRAGON_SHUFFLE);

        // Render model with special flag
        model->render(mob, wp, ws, bob, headRotMinusBodyRot, headRotx, scale, true);

        // Reset alpha test
        glAlphaFunc(GL_GREATER, 0.1f);
        glDepthFunc(GL_EQUAL);
    }

    // Bind main texture and render normal model
    bindTexture(mob->customTextureUrl, mob->getTexture());
    model->render(mob, wp, ws, bob, headRotMinusBodyRot, headRotx, scale, true);

    // Render hurt effect when dragon is damaged
    if (mob->hurtTime > 0) {
        glDepthFunc(GL_EQUAL);
        glDisable(GL_TEXTURE_2D);
        glEnable(GL_BLEND);
        glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA);
        glColor4f(1, 0, 0, 0.5f);

#ifdef __PSVITA__
        // Vita-specific rendering path
        model->render(mob, wp, ws, bob, headRotMinusBodyRot, headRotx, scale, true);
#else
        // Standard rendering path
        model->render(mob, wp, ws, bob, headRotMinusBodyRot, headRotx, scale, false);
#endif

        // Restore OpenGL state
        glEnable(GL_TEXTURE_2D);
        glDisable(GL_BLEND);
        glDepthFunc(GL_LEQUAL);
    }
}

void EnderDragonRenderer::render(
    std::shared_ptr<Entity> _mob,
    double                  x,
    double                  y,
    double                  z,
    float                   rot,
    float                   a
) {
    // Cast to EnderDragon type
    std::shared_ptr<EnderDragon> mob =
        std::dynamic_pointer_cast<EnderDragon>(_mob);

    // Update boss instance reference
    EnderDragonRenderer::bossInstance = mob;

    // Check if model needs updating
    if (currentModel != DragonModel::MODEL_ID) {
        delete model; // Clean up old model
        model        = new DragonModel(0);
        currentModel = DragonModel::MODEL_ID;
    }

    // Call parent render method
    MobRenderer::render(mob, x, y, z, rot, a);

    // Render healing beam if crystal is present
    if (mob->nearestCrystal != NULL) {
        float timeVar = mob->nearestCrystal->time + a;
        float heightFactor = sin(timeVar * 0.2f) / 2 + 0.5f;
        heightFactor = (heightFactor * heightFactor + heightFactor) * 0.2f;

        // Calculate relative positions
        float deltaX = static_cast<float>(mob->nearestCrystal->x - mob->x
                           - (mob->xo - mob->x) * (1 - a));
        float deltaY = static_cast<float>(heightFactor + mob->nearestCrystal->y - 1 - mob->y
                           - (mob->yo - mob->y) * (1 - a));
        float deltaZ = static_cast<float>(mob->nearestCrystal->z - mob->z
                           - (mob->zo - mob->z) * (1 - a));

        float horizDist = std::sqrt(deltaX * deltaX + deltaZ * deltaZ);
        float fullDist  = std::sqrt(deltaX * deltaX + deltaY * deltaY + deltaZ * deltaZ);

        // Reset color to prevent black beam issue
        glColor4f(1, 1, 1, 1);

        glPushMatrix();
        glTranslatef(static_cast<float>(x), static_cast<float>(y + 2), static_cast<float>(z));

        // Apply rotation transformations
        glRotatef(calculateRotationAngle(deltaX, deltaZ), 0, 1, 0);
        glRotatef(calculateElevationAngle(horizDist, deltaY), 1, 0, 0);

        // Add rotation animation for beam
        static float beamRotation = 0.0f;
        glRotatef(beamRotation, 0, 0, 1);
        beamRotation += 0.5f;
        if (beamRotation >= 360.0f) beamRotation = 0.0f;

        // Setup tesselator and lighting
        Tesselator* t = Tesselator::getInstance();
        Lighting::turnOff();
        glDisable(GL_CULL_FACE);
        glEnable(GL_BLEND);
        glBlendFunc(GL_SRC_ALPHA, GL_DST_ALPHA);

        // Bind beam texture
        bindTexture(TN_MOB_ENDERDRAGON_BEAM);
        glShadeModel(GL_SMOOTH);

        // Calculate texture coordinates
        float texV0 = 0.0f - (mob->tickCount + a) * 0.005f;
        float texV1 = fullDist / 32.0f - (mob->tickCount + a) * 0.005f;

        // Draw beam using triangle strip
        t->begin(GL_TRIANGLE_STRIP);
        int segments = 8;
        for (int i = 0; i <= segments; i++) {
            double angle = (i % segments) * M_PI * 2 / segments;
            float s = std::sin(i % segments * M_PI * 2 / segments) * 0.75f;
            float c = std::cos(i % segments * M_PI * 2 / segments) * 0.75f;
            float u = (i % segments) * 1.0f / segments;

            // Outer ring vertex
            t->vertexUV(s * 0.2f, c * 0.2f, 0, u, texV1);
            // Inner core vertex
            t->vertexUV(s, c, fullDist, u, texV0);
        }
        t->end();

        // Restore state
        glEnable(GL_CULL_FACE);
        glShadeModel(GL_FLAT);
        glDisable(GL_BLEND);
        glPopMatrix();
        Lighting::turnOn();
    }
}

void EnderDragonRenderer::additionalRendering(
    std::shared_ptr<Mob> _mob,
    float                a
) {
    // Cast to EnderDragon type
    std::shared_ptr<EnderDragon> mob =
        std::dynamic_pointer_cast<EnderDragon>(_mob);

    // Call parent rendering
    MobRenderer::additionalRendering(mob, a);

    Tesselator* t = Tesselator::getInstance();

    // Render death particles
    if (mob->dragonDeathTime > 0) {
        Lighting::turnOff();
        float deathProgress = ((mob->dragonDeathTime + a) / 200.0f);
        float overdrive = 0;
        if (deathProgress > 0.8f) {
            overdrive = (deathProgress - 0.8f) / 0.2f;
        }

        Random particleGenerator(432);
        glDisable(GL_TEXTURE_2D);
        glShadeModel(GL_SMOOTH);
        glEnable(GL_BLEND);
        glBlendFunc(GL_SRC_ALPHA, GL_ONE);
        glDisable(GL_ALPHA_TEST);
        glEnable(GL_CULL_FACE);
        glDepthMask(false);

        glPushMatrix();
        glTranslatef(0, -1, -2);

        // Calculate number of particles based on death progress
        int particleCount = static_cast<int>((deathProgress + deathProgress * deathProgress) / 2 * 60);

        for (int i = 0; i < particleCount; i++) {
            // Apply random rotations
            glRotatef(particleGenerator.nextFloat() * 360, 1, 0, 0);
            glRotatef(particleGenerator.nextFloat() * 360, 0, 1, 0);
            glRotatef(particleGenerator.nextFloat() * 360, 0, 0, 1);
            glRotatef(particleGenerator.nextFloat() * 360, 1, 0, 0);
            glRotatef(particleGenerator.nextFloat() * 360, 0, 1, 0);
            glRotatef(particleGenerator.nextFloat() * 360 + deathProgress * 90, 0, 0, 1);

            // Draw particle fan
            t->begin(GL_TRIANGLE_FAN);
            float distance = particleGenerator.nextFloat() * 20 + 5 + overdrive * 10;
            float width    = particleGenerator.nextFloat() * 2 + 1 + overdrive * 2;

            // Center point
            t->color(0xffffff, static_cast<int>(255 * (1 - overdrive)));
            t->vertex(0, 0, 0);

            // Triangle vertices
            t->color(0xff00ff, 0);
            t->vertex(-0.866f * width, distance, -0.5f * width);
            t->vertex(+0.866f * width, distance, -0.5f * width);
            t->vertex(0, distance, 1 * width);
            t->vertex(-0.866f * width, distance, -0.5f * width);
            t->end();
        }

        glPopMatrix();
        glDepthMask(true);
        glDisable(GL_CULL_FACE);
        glDisable(GL_BLEND);
        glShadeModel(GL_FLAT);
        glColor4f(1, 1, 1, 1);
        glEnable(GL_TEXTURE_2D);
        glEnable(GL_ALPHA_TEST);
        Lighting::turnOn();
    }
}

int EnderDragonRenderer::prepareArmor(
    std::shared_ptr<Mob> _mob,
    int                  layer,
    float                a
) {
    // Cast to EnderDragon type
    std::shared_ptr<EnderDragon> mob =
        std::dynamic_pointer_cast<EnderDragon>(_mob);

    // Set depth function for second layer
    if (layer == 1) {
        glDepthFunc(GL_LEQUAL);
    }

    // Only handle first layer
    if (layer != 0) return -1;

    // Bind eyes texture
    bindTexture(TN_MOB_ENDERDRAGON_ENDEREYES);

    float brightness = 1;
    glEnable(GL_BLEND);

    // Platform-specific alpha test handling
#ifdef _XBOX
    glDisable(GL_ALPHA_TEST);
#endif

    glBlendFunc(GL_ONE, GL_ONE);
    glDisable(GL_LIGHTING);
    glDepthFunc(GL_EQUAL);

    // Handle texture lighting if enabled
    if (SharedConstants::TEXTURE_LIGHTING) {
        int col = 0xf0f0;
        int u   = col % 65536;
        int v   = col / 65536;
        glMultiTexCoord2f(GL_TEXTURE1, u / 1.0f, v / 1.0f);
        glColor4f(1, 1, 1, 1);
    }

    glEnable(GL_LIGHTING);
    glColor4f(1, 1, 1, brightness);
    return 1;
}

