upb_CType to_fieldtype(upb_FieldType type) {
  switch (type) {
#define CASE(descriptor_type, type)           \
  case kUpb_FieldType_##descriptor_type: \
    return kUpb_CType_##type;
  CASE(Float,    Float);
  CASE(Double,   Double);
  CASE(Bool,     Bool);
  CASE(String,   String);
  CASE(Bytes,    Bytes);
  CASE(Message,  Message);
  CASE(Group,    Message);
  CASE(Enum,     Enum);
  CASE(Int32,    Int32);
  CASE(Int64,    Int64);
  CASE(UInt32,   UInt32);
  CASE(UInt64,   UInt64);
  CASE(SInt32,   Int32);
  CASE(SInt64,   Int64);
  CASE(Fixed32,  UInt32);
  CASE(Fixed64,  UInt64);
  CASE(SFixed32, Int32);
  CASE(SFixed64, Int64);
#undef CONVERT
  }
  zend_error(E_ERROR, "Unknown field type.");
  return 0;
}

