    zend_error(E_USER_ERROR, "Cannot get element at %ld.\n", index);
    return;
  }
  OneofDescriptor_FromOneofDef(&result, upb_MessageDef_Oneof(intern->msgdef, index));
  RETURN_COPY_VALUE(&result);
}

