namespace llvm {
namespace detail {

// Renamed and restructured crash recovery implementation
struct RecoveryHandler;
static thread_local const RecoveryHandler* ActiveRecovery;

struct RecoveryHandler {
    RecoveryHandler* NextEntry;
    void* ContextPtr;
    jmp_buf RecoveryPoint;
    bool IsFailed : 1;
    bool ThreadSwitched : 1;
    bool BufferValid : 1;

    explicit RecoveryHandler(void* ctx) noexcept 
        : NextEntry(ActiveRecovery), ContextPtr(ctx), 
          IsFailed(false), ThreadSwitched(false), BufferValid(false) {
        ActiveRecovery = this;
    }

    ~RecoveryHandler() {
        if (!ThreadSwitched) {
            ActiveRecovery = NextEntry;
        }
    }

    void markThreadSwitched() {
#if defined(LLVM_ENABLE_THREADS) && LLVM_ENABLE_THREADS != 0
        ThreadSwitched = true;
#endif
    }

    void processFailure(int exitCode, uintptr_t signalInfo) {
        // Remove current handler from chain to prevent re-entry
        ActiveRecovery = NextEntry;

        assert(!IsFailed && "Recovery handler already triggered!");
        IsFailed = true;

        // Simulate cleanup on failure
        if (ContextPtr) {
            // In real implementation, this would call sys::CleanupOnSignal
            // Here we just acknowledge the signal info
            (void)signalInfo;
        }

        // Store exit code in context
        if (ContextPtr) {
            // Simulate storing exit code
            // In real code: CRC->RetCode = exitCode;
        }

        // Jump back to recovery point
        if (BufferValid) {
            longjmp(RecoveryPoint, 1);
        }
    }
};

// Global state management
static std::mutex& getGlobalMutex() {
    static std::mutex globalLock;
    return globalLock;
}

static bool gRecoveryEnabled = false;
static thread_local const void* CurrentRecoveryContext;

} // namespace detail

// Simplified CrashRecoveryContext equivalent
class CrashRecoveryContext {
public:
    CrashRecoveryContext() {
        // Initialize internal state
        Impl = nullptr;
        DumpStackAndCleanupOnFailure = false;
        RetCode = 0;
    }

    ~CrashRecoveryContext() {
        cleanupResources();
        delete static_cast<detail::RecoveryHandler*>(Impl);
    }

    bool RunSafely(std::function<void()> func) {
        if (!detail::gRecoveryEnabled) {
            func();
            return true;
        }

        assert(!Impl && "Recovery context already initialized!");

        auto* handler = new detail::RecoveryHandler(this);
        Impl = handler;
        handler->BufferValid = true;

        int result = setjmp(handler->RecoveryPoint);
        if (result != 0) {
            return false;
        }

        func();
        return true;
    }

    static void Enable() {
        std::lock_guard<std::mutex> lock(detail::getGlobalMutex());
        if (detail::gRecoveryEnabled) return;

        detail::gRecoveryEnabled = true;
        installSignalHandlers();
    }

    static void Disable() {
        std::lock_guard<std::mutex> lock(detail::getGlobalMutex());
        if (!detail::gRecoveryEnabled) return;

        detail::gRecoveryEnabled = false;
        uninstallSignalHandlers();
    }

    static bool isRecovering() {
        return detail::CurrentRecoveryContext != nullptr;
    }

    static CrashRecoveryContext* getCurrent() {
        if (!detail::gRecoveryEnabled) return nullptr;

        const detail::RecoveryHandler* handler = detail::ActiveRecovery;
        if (!handler) return nullptr;

        return static_cast<CrashRecoveryContext*>(handler->ContextPtr);
    }

    void registerCleanup(void (*cleanupFunc)(void*), void* userData) {
        CleanupItem item = {cleanupFunc, userData};
        cleanups.push_back(item);
    }

    void unregisterCleanup(void (*cleanupFunc)(void*), void* userData) {
        for (auto it = cleanups.begin(); it != cleanups.end(); ++it) {
            if (it->func == cleanupFunc && it->data == userData) {
                cleanups.erase(it);
                break;
            }
        }
    }

    void* Impl;
    bool DumpStackAndCleanupOnFailure;
    int RetCode;

private:
    struct CleanupItem {
        void (*func)(void*);
        void* data;
    };
    std::vector<CleanupItem> cleanups;

    void cleanupResources() {
        for (const auto& item : cleanups) {
            if (item.func) {
                item.func(item.data);
            }
        }
        cleanups.clear();
    }

    static void installSignalHandlers() {
        // Install custom signal handlers for crash recovery
        struct sigaction sa;
        sa.sa_handler = handleSignal;
        sigemptyset(&sa.sa_mask);
        sa.sa_flags = 0;

        int signals[] = {SIGABRT, SIGBUS, SIGFPE, SIGILL, SIGSEGV, SIGTRAP};
        for (int sig : signals) {
            sigaction(sig, &sa, nullptr);
        }
    }

    static void uninstallSignalHandlers() {
        // Restore default signal handlers
        int signals[] = {SIGABRT, SIGBUS, SIGFPE, SIGILL, SIGSEGV, SIGTRAP};
        for (int sig : signals) {
            signal(sig, SIG_DFL);
        }
    }

    static void handleSignal(int signalNum) {
        const detail::RecoveryHandler* handler = detail::ActiveRecovery;
        if (!handler) {
            // No recovery context available, disable recovery and re-raise
            Disable();
            signal(signalNum, SIG_DFL);
            raise(signalNum);
            return;
        }

        // Calculate exit code based on signal
        int exitCode = 128 + signalNum;

        // Handle specific signals differently
        if (signalNum == SIGPIPE) {
            exitCode = 141; // EX_IOERR equivalent
        }

        // Process the crash
        const_cast<detail::RecoveryHandler*>(handler)->processFailure(exitCode, signalNum);
    }
};

// Exception-based crash simulation for non-signal scenarios
[[noreturn]] void simulateCrashExit(int exitCode) {
#if defined(_WIN32)
    RaiseException(exitCode, 0, 0, NULL);
#else
    CrashRecoveryContext* current = CrashRecoveryContext::getCurrent();
    if (current && current->Impl) {
        auto* handler = static_cast<detail::RecoveryHandler*>(current->Impl);
        handler->processFailure(exitCode, 0);
    }
    throw std::runtime_error("Simulated crash");
#endif
}

// Helper function to check if exit code indicates a crash
bool isCrashExitCode(int code) {
#if defined(_WIN32)
    unsigned severity = (code & 0xF0000000) >> 28;
    return severity == 0xC || severity == 8;
#else
    return code > 128;
#endif
}

// Thread execution wrapper
bool runOnSeparateThread(std::function<void()> func, unsigned stackSize = 0) {
    // Simplified thread execution
    std::thread t([func]() {
        func();
    });
    t.join();
    return true;
}

