    // Compute golden angle using inverse cosine of -1 (PI) and sqrt(5)
    const long double PI = acosl(-1.0L);
    const long double golden_angle = PI * (3.0L - sqrtl(5.0L));

    vector<array<long double, 3>> points;
    points.reserve(n);

    // Generate points on unit sphere using Fibonacci lattice method
    for (int idx = 0; idx < n; ++idx) {
        // Compute z-coordinate from index
        long double z_coord = 1.0L - 2.0L * ((static_cast<long double>(idx) + 0.5L) / static_cast<long double>(n));

        // Compute radial distance in xy-plane
        long double radius_xy = sqrtl(max(0.0L, 1.0L - z_coord * z_coord));

        // Compute azimuthal angle
        long double phi = golden_angle * idx;

        // Convert to Cartesian coordinates
        long double x_coord = radius_xy * cosl(phi);
        long double y_coord = radius_xy * sinl(phi);

        // Normalize point to lie exactly on unit sphere
        long double magnitude = sqrtl(x_coord * x_coord + y_coord * y_coord + z_coord * z_coord);
        if (magnitude > 0) {
            x_coord /= magnitude;
            y_coord /= magnitude;
            z_coord /= magnitude;
        }

        points.push_back({x_coord, y_coord, z_coord});
    }

    // Find minimum squared distance between any pair of points
    long double min_sq_dist = numeric_limits<long double>::max();
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            long double diff_x = points[i][0] - points[j][0];
            long double diff_y = points[i][1] - points[j][1];
            long double diff_z = points[i][2] - points[j][2];

            long double sq_dist = diff_x * diff_x + diff_y * diff_y + diff_z * diff_z;
            if (sq_dist < min_sq_dist) {
                min_sq_dist = sq_dist;
            }
        }
    }

    // Output minimum distance with high precision
    cout.setf(std::ios::fixed);
    cout << setprecision(12) << static_cast<double>(sqrtl(min_sq_dist)) << "\n";

    // Output all points
    for (int i = 0; i < n; ++i) {
        cout << setprecision(12)
             << static_cast<double>(points[i][0]) << " "
             << static_cast<double>(points[i][1]) << " "
             << static_cast<double>(points[i][2]) << "\n";
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Operation {
    int left, right, direction;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    vector<int> arr(n + 1), indexMap(n + 1);
    for (int i = 1; i <= n; ++i) {
        cin >> arr[i];
        indexMap[arr[i]] = i;
    }

    const int maxDirectionValue = 2;
    vector<Operation> operations;
    operations.reserve(n * n / 2);

    for (int targetValue = 1; targetValue <= n; ++targetValue) {
        int currentPos = indexMap[targetValue];
        while (currentPos > targetValue) {
            // Perform a leftward swap between positions currentPos-1 and currentPos
            operations.push_back({currentPos - 1, currentPos, 0});

            int val1 = arr[currentPos - 1];
            int val2 = arr[currentPos];

            swap(arr[currentPos - 1], arr[currentPos]);
            indexMap[val1] = currentPos;
            indexMap[val2] = currentPos - 1;

            --currentPos;
        }
    }

    cout << maxDirectionValue << " " << operations.size() << "\n";
    for (const auto& op : operations) {
        cout << op.left << " " << op.right << " " << op.direction << "\n";
    }

    return 0;
}

