#include <iostream>
#include <vector>
#include <algorithm>
#include <random>
#include <bitset>
using namespace std;

struct Edge {
    int u, v;
    int id;
};

int N, M;
vector<Edge> edges;
vector<vector<pair<int, int>>> adj; // u -> {v, edge_index}

// Global bitsets for solver
bitset<10000> current_mask;
bitset<10000> possible_v;
bitset<10000> all_ones;

struct QueryData {
    vector<int> in_time;
    vector<int> out_time;
    vector<int> dfs_order; // map dfs_index -> original_node
    int answer;
};

vector<QueryData> queries;

void perform_random_dfs(int root, vector<int>& order, vector<int>& in_time, vector<int>& out_time, mt19937& rng) {
    vector<bool> visited(N, false);
    vector<int> stack;
    stack.push_back(root);

    visited[root] = true;
    int timer = 0;

    // Pre-shuffle adjacency lists
    vector<vector<int>> shuffled_adj(N);
    for (int u = 0; u < N; ++u) {
        for (auto& p : adj[u]) {
            shuffled_adj[u].push_back(p.first);
        }
        shuffle(shuffled_adj[u].begin(), shuffled_adj[u].end(), rng);
    }

    // Iterative DFS with explicit stack to compute in/out times
    struct StackFrame {
        int node;
        int next_child_idx;
    };
    vector<StackFrame> dfs_stack;
    dfs_stack.push_back({root, 0});
    in_time[root] = timer++;
    order[in_time[root]] = root;

    while (!dfs_stack.empty()) {
        StackFrame& frame = dfs_stack.back();
        int u = frame.node;

        if (frame.next_child_idx < shuffled_adj[u].size()) {
            int v = shuffled_adj[u][frame.next_child_idx];
            frame.next_child_idx++;
            if (!visited[v]) {
                visited[v] = true;
                in_time[v] = timer++;
                order[in_time[v]] = v;
                dfs_stack.push_back({v, 0});
            }
        } else {
            out_time[u] = timer - 1;
            dfs_stack.pop_back();
        }
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> N >> M)) return 0;

    adj.resize(N);
    for (int i = 0; i < M; ++i) {
        int u, v;
        cin >> u >> v;
        edges.push_back({u, v, i});
        adj[u].push_back({v, i});
        adj[v].push_back({u, i});
    }

    mt19937 rng(1337);

    // Initialize bitset
    for (int i = 0; i < N; ++i) all_ones[i] = 1;

    const int num_queries = 250;
    vector<int> edge_directions(M);
    vector<int> in(N), out(N), order(N);

    for (int q = 0; q < num_queries; ++q) {
        int root = uniform_int_distribution<int>(0, N - 1)(rng);

        fill(in.begin(), in.end(), 0);
        fill(out.begin(), out.end(), 0);
        fill(order.begin(), order.end(), 0);

        perform_random_dfs(root, order, in, out, rng);

        // Determine edge directions based on DFS tree: direct from earlier to later in DFS order
        for (const auto& e : edges) {
            if (in[e.u] < in[e.v]) {
                edge_directions[e.id] = 0; // u -> v
            } else {
                edge_directions[e.id] = 1; // v -> u
            }
        }

        cout << "0 ";
        for (int i = 0; i < M; ++i) {
            cout << edge_directions[i];
            if (i != M - 1) cout << " ";
        }
        cout << "\n";

        int res;
        cin >> res;
        if (res == -1) return 0;

        QueryData qd;
        qd.in_time = in;
        qd.out_time = out;
        qd.dfs_order = order;
        qd.answer = res;
        queries.push_back(qd);
    }

    // Find A and B
    int candidate_A = -1, candidate_B = -1;

    for (int u = 0; u < N; ++u) {
        possible_v = all_ones;
        possible_v[u] = 0; // A != B

        bool found_valid = true;

        for (const auto& qd : queries) {
            int u_in = qd.in_time[u];
            int u_out = qd.out_time[u];
            bool must_be_in_subtree = (qd.answer == 1);

            // Iterate over remaining candidates
            for (int v = possible_v._Find_first(); v < N; v = possible_v._Find_next(v)) {
                int v_in = qd.in_time[v];
                bool is_in_subtree = (v_in >= u_in && v_in <= u_out);

                if (must_be_in_subtree != is_in_subtree) {
                    possible_v[v] = 0;
                }
            }

            if (possible_v.none()) {
                found_valid = false;
                break;
            }
        }

        if (found_valid) {
            candidate_A = u;
            candidate_B = possible_v._Find_first();
            break;
        }
    }

    cout << "1 " << candidate_A << " " << candidate_B << "\n";

    return 0;
}

#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
using namespace std;

// Definition of Interval (as provided)
class Interval {
public:
    int start, end;
    Interval(int s, int e) : start(s), end(e) {}
};

class Solution {
public:
    int minMeetingRooms(vector<Interval>& intervals) {
        // Sort intervals by start time using a custom comparator
        sort(intervals.begin(), intervals.end(), [](const Interval& x, const Interval& y) {
            return x.start < y.start;
        });

        // Min heap to track end times of ongoing meetings
        priority_queue<int, vector<int>, greater<int>> endTimeHeap;

        for (const auto& interval : intervals) {
            // If the earliest ending meeting has ended before or at the start of current meeting,
            // we can reuse that room (remove the ended meeting from heap)
            if (!endTimeHeap.empty() && endTimeHeap.top() <= interval.start) {
                endTimeHeap.pop();
            }

            // Add current meeting's end time to the heap
            endTimeHeap.push(interval.end);
        }

        // The size of the heap represents the maximum number of concurrent meetings
        return endTimeHeap.size();
    }
};

int main() {
    Solution sol;
    vector<Interval> meetings = {Interval(0, 30), Interval(5, 10), Interval(15, 20)};

    cout << "Minimum number of meeting rooms required: " 
         << sol.minMeetingRooms(meetings) << endl;

    // Expected output: 2
    // Reasoning: Intervals (0,30) and (5,10) overlap; (15,20) fits after (5,10) ends.
    return 0;
}

