    );

    // Create display label with formatted value
    auto valueLabel = Ui::labelMedium("{:.02}", value) | 
                      Ui::insets({0, 4}) | 
                      Ui::center();

    // Create increment button with lambda that adds step to current value
    auto incrementButton = Ui::button(
        [onChange, value, step](auto& n) {
            onChange(n, value + step);
        },
        Ui::ButtonStyle::subtle(),
        Mdi::PLUS
    );

    // Combine elements in horizontal flow and apply styling
    return Ui::hflow(decrementButton, valueLabel, incrementButton) |
           Ui::box({
               .borderRadii = 4,
               .borderWidth = 1,
               .borderFill = Ui::GRAY800,
           }) |
           Ui::focusable();
}
