/************************************************
Mass-spring system: nx/2 masses connected each other with springs (in a row), and the first and the last one to walls. nu (<=nx) controls act on the first nu masses. The system is sampled with sampling time Ts.
************************************************/
void mass_spring_system(double Ts, int nx, int nu, double *A, double *B, double *b, double *x0)
{
    int nx2 = nx*nx;
    int info = 0;
    int pp = nx/2; // number of masses

    /************************************************
    * build the continuous time system
    ************************************************/
    double *T; d_zeros(&T, pp, pp);
    int ii;
    for(ii=0; ii<pp; ii++) T[ii*(pp+1)] = -2;
    for(ii=0; ii<pp-1; ii++) T[ii*(pp+1)+1] = 1;
    for(ii=1; ii<pp; ii++) T[ii*(pp+1)-1] = 1;

    double *Z; d_zeros(&Z, pp, pp);
    double *I; d_zeros(&I, pp, pp); 
    for(ii=0; ii<pp; ii++) I[ii*(pp+1)]=1.0; // = eye(pp);

    double *Ac; d_zeros(&Ac, nx, nx);
    dmcopy(pp, pp, Z, pp, Ac, nx);
    dmcopy(pp, pp, T, pp, Ac+pp, nx);
    dmcopy(pp, pp, I, pp, Ac+pp*nx, nx);
    dmcopy(pp, pp, Z, pp, Ac+pp*(nx+1), nx);

    free(T);
    free(Z);
    free(I);

    d_zeros(&I, nu, nu); 
    for(ii=0; ii<nu; ii++) I[ii*(nu+1)]=1.0; //I = eye(nu);

    double *Bc; d_zeros(&Bc, nx, nu);
    dmcopy(nu, nu, I, nu, Bc+pp, nx);
    free(I);

    /************************************************
    * compute the discrete time system
    ************************************************/
    double *bb; d_zeros(&bb, nx, 1);
    dmcopy(nx, 1, bb, nx, b, nx);
    dmcopy(nx, nx, Ac, nx, A, nx);
    dscal_3l(nx2, Ts, A);
    expm(nx, A);

    double *T_temp; d_zeros(&T_temp, nx, nx);
    d_zeros(&I, nx, nx); 
    for(ii=0; ii<nx; ii++) I[ii*(nx+1)]=1.0; //I = eye(nx);

    dmcopy(nx, nx, A, nx, T_temp, nx);
    daxpy_3l(nx2, -1.0, I, T_temp);
    dgemm_nn_3l(nx, nu, nx, T_temp, nx, Bc, nx, B, nx);

    free(T_temp);
    free(I);

    int *ipiv = (int *) malloc(nx*sizeof(int));
    dgesv_3l(nx, nu, Ac, nx, ipiv, B, nx, &info);
    free(ipiv);
    free(Ac);
    free(Bc);
    free(bb);

    /************************************************
    * initial state
    ************************************************/
    if(nx==4)
    {
        x0[0] = 5;
        x0[1] = 10;
        x0[2] = 15;
        x0[3] = 20;
    }
    else
    {
        int jj;
        for(jj=0; jj<nx; jj++)
            x0[jj] = 1;
    }
}

int main()
{
    // local variables
    int ii, jj;
    int rep, nrep=1000;
    struct timeval tv0, tv1;

    // problem size
    int nx_ = 8; // number of states (it has to be even for the mass-spring system test problem)
    int nu_ = 3; // number of inputs (controllers) (it has to be at least 1 and at most nx/2 for the mass-spring system test problem)
    int N  = 5; // horizon length

    // stage-wise variant size
    int nx[N+1];
#if KEEP_X0
    nx[0] = nx_;
#else
    nx[0] = 0;
#endif
    for(ii=1; ii<=N; ii++)
        nx[ii] = nx_;

    int nu[N+1];
    for(ii=0; ii<N; ii++)
        nu[ii] = nu_+2*nx[ii]/2;

    nu[N] = 2*nx[N]/2; // soft constraints

#if 1
    int nb[N+1];
#if KEEP_X0
    nb[0] = nu[0]+nx[0]/2;
#else
    nb[0] = nu[0];
#endif
    for(ii=1; ii<N; ii++)
        nb[ii] = nu[1];//+nx[1]/2;
    nb[N] = nu[N];//+nx[N]/2;

    int ng[N+1];
    ng[0] = 0;
    for(ii=1; ii<N; ii++)
        ng[ii] = 2*nx[ii]/2;
    ng[N] = 2*nx[N]/2;

    int ns[N+1];
    ns[0] = 0;
    for(ii=1; ii<N; ii++)
        ns[ii] = 0;
    ns[N] = 0;//nx[N]/2;
#elif 0
    int nb[N+1];
    nb[0] = 0;
    for(ii=1; ii<N; ii++)
        nb[ii] = 0;
    nb[N] = 0;

    int ng[N+1];
#if KEEP_X0
    ng[0] = nu[0]+nx[0]/2;
#else
    ng[0] = nu[0];
#endif
    for(ii=1; ii<N; ii++)
        ng[ii] = nu[1]+nx[1]/2;
    ng[N] = nx[N]/2;
#else
    int nb[N+1];
    nb[0] = nu[0] + nx[0]/2;
    for(ii=1; ii<N; ii++)
        nb[ii] = nu[ii] + nx[ii]/2;
    nb[N] = nu[N] + nx[N]/2;

    int ng[N+1];
#if KEEP_X0
    ng[0] = nx[0]/2;
#else
    ng[0] = 0;
#endif
    for(ii=1; ii<N; ii++)
        ng[ii] = nx[1]/2;
    ng[N] = nx[N]/2;
#endif

    /************************************************
    * dynamical system
    ************************************************/
    double *A; d_zeros(&A, nx_, nx_); // states update matrix
    double *B; d_zeros(&B, nx_, nu_); // inputs matrix
    double *b; d_zeros(&b, nx_, 1); // states offset
    double *x0; d_zeros(&x0, nx_, 1); // initial state
    double Ts = 0.5; // sampling time

    mass_spring_system(Ts, nx_, nu_, A, B, b, x0);

    for(jj=0; jj<nx_; jj++)
        b[jj] = 0.0;

    for(jj=0; jj<nx_; jj++)
        x0[jj] = 0;

    x0[0] = 2.5;
    x0[1] = 2.5;

    double *b0; d_zeros(&b0, nx_, 1);
    dgemv_n_3l(nx_, nx_, A, nx_, x0, b0);
    daxpy_3l(nx_, 1.0, b, b0);

    double *B1; d_zeros(&B1, nx[2], nu[1]);
    for(jj=0; jj<nu_; jj++)
        for(ii=0; ii<nx_; ii++)
            B1[ii+nx_*jj] = B[ii+nx_*jj];

#if PRINT
    d_print_mat(nx_, nx_, A, nx_);
    d_print_mat(nx_, nu_, B, nx_);
    d_print_mat(nx[2], nu[1], B1, nx[2]);
    d_print_mat(1, nx_, b, 1);
    d_print_mat(1, nx_, x0, 1);
    d_print_mat(1, nx_, b0, 1);
#endif

    /************************************************
    * cost function
    ************************************************/
    double *Q; d_zeros(&Q, nx_, nx_);
    for(ii=0; ii<nx_; ii++) Q[ii*(nx_+1)] = 0.0;

    double *R0; d_zeros(&R0, nu[0], nu[0]);
    for(ii=0; ii<nu_; ii++) R0[ii*(nu[0]+1)] = 2.0;

    double *R1; d_zeros(&R1, nu[1], nu[1]);
