#include <gtest/gtest.h>
#include <jonssonic/effects/compressor.h>

using namespace jnsc::effects;

class CompressorTest : public ::testing::Test {
  protected:
    static constexpr size_t channels = 2;
    static constexpr size_t frameSize = 8;
    static constexpr float fs = 48000.0f;
    Compressor<float> compressor;

    void SetUp() override { 
        compressor.prepare(channels, fs); 
    }
};

TEST_F(CompressorTest, PrepareInitializes) {
    EXPECT_EQ(compressor.getNumChannels(), channels);
    EXPECT_FLOAT_EQ(compressor.getSampleRate(), fs);
    EXPECT_TRUE(compressor.isPrepared());
}

TEST_F(CompressorTest, ResetFunctionality) {
    compressor.reset();
    SUCCEED();
}

TEST_F(CompressorTest, BlockProcessing) {
    float inputSignal[channels][frameSize] = {};
    float detectorSignal[channels][frameSize] = {};
    float processedOutput[channels][frameSize] = {};

    const float* inputPointers[channels] = {inputSignal[0], inputSignal[1]};
    const float* detectorPointers[channels] = {detectorSignal[0], detectorSignal[1]};
    float* outputPointers[channels] = {processedOutput[0], processedOutput[1]};

    compressor.processBlock(inputPointers, detectorPointers, outputPointers, frameSize);

    for (size_t ch = 0; ch < channels; ++ch)
        for (size_t sample = 0; sample < frameSize; ++sample)
            EXPECT_FLOAT_EQ(processedOutput[ch][sample], 0.0f);
}

TEST_F(CompressorTest, ParameterSetting) {
    compressor.setThreshold(-18.0f, true);
    compressor.setAttackTime(5.0f, true);
    compressor.setReleaseTime(50.0f, true);
    compressor.setRatio(2.5f, true);
    compressor.setKnee(3.0f, true);
    compressor.setOutputGain(2.0f, true);
    SUCCEED();
}

TEST_F(CompressorTest, GainReductionRetrieval) {
    float reduction = compressor.getGainReduction();
    EXPECT_GE(reduction, 0.0f);
}

