using namespace std;

// Helper function to run a race and get the winner
int conductRace(const vector<int>& participants) {
    cout << "?";
    for (int p : participants) {
        cout << " " << p;
    }
    cout << endl;

    int winner;
    cin >> winner;
    return winner;
}

void processCase() {
    int n;
    if (!(cin >> n)) return;

    // Build adjacency list: children[u] holds nodes known to be slower than u
    vector<vector<int>> children(n * n + 1);

    // Track current candidates for top positions
    vector<int> candidates;

    // Phase 1: Initial grouping into n groups of size n
    int id = 1;
    for (int groupIdx = 0; groupIdx < n; ++groupIdx) {
        vector<int> group;
        for (int member = 0; member < n; ++member) {
            group.push_back(id++);
        }

        int groupWinner = conductRace(group);
        candidates.push_back(groupWinner);

        // Attach all non-winners as children of the winner
        for (int member : group) {
            if (member != groupWinner) {
                children[groupWinner].push_back(member);
            }
        }
    }

    // Prepare result list for top (n^2 - n + 1) elements
    vector<int> sortedOrder;
    int neededCount = n * n - n + 1;

    for (int pos = 0; pos < neededCount; ++pos) {
        // Reduce candidate pool to single element by pairwise races
        while (candidates.size() > 1) {
            vector<int> raceEntries;
            vector<int> activeCandidates;

            // Select up to n candidates for this round
            int pickCount = min((int)candidates.size(), n);
            for (int i = 0; i < pickCount; ++i) {
                raceEntries.push_back(candidates[i]);
                activeCandidates.push_back(candidates[i]);
            }

            // Fill remaining slots with known slower elements (descendants)
            if (raceEntries.size() < n) {
                int fillNeeded = n - raceEntries.size();

                for (int root : activeCandidates) {
                    if (fillNeeded <= 0) break;

                    queue<int> bfsQueue;
                    bfsQueue.push(root);

                    while (!bfsQueue.empty() && fillNeeded > 0) {
                        int node = bfsQueue.front();
                        bfsQueue.pop();

                        for (int child : children[node]) {
                            raceEntries.push_back(child);
                            fillNeeded--;
                            if (fillNeeded <= 0) break;
                            bfsQueue.push(child);
                        }
                    }
                }
            }

            // Run the race
            int newWinner = conductRace(raceEntries);

            // Update candidate list
            vector<int> nextRound;

            // Add candidates not involved in this race
            for (size_t i = pickCount; i < candidates.size(); ++i) {
                nextRound.push_back(candidates[i]);
            }

            // Add the winner of this round
            nextRound.push_back(newWinner);

            // Attach losers as children of the winner
            for (int loser : activeCandidates) {
                if (loser != newWinner) {
                    children[newWinner].push_back(loser);
                }
            }

            candidates = nextRound;
        }

        // Current best is the only remaining candidate
        int currentBest = candidates[0];
        sortedOrder.push_back(currentBest);

        // Replace current best with its direct descendants as new candidates
        candidates.clear();
        for (int child : children[currentBest]) {
            candidates.push_back(child);
        }
    }

    // Output final sorted sequence
    cout << "!";
    for (int val : sortedOrder) {
        cout << " " << val;
    }
    cout << endl;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int testCases;
    if (cin >> testCases) {
        while (testCases--) {
            processCase();
        }
    }

    return 0;
}

