// Function to send a query and receive response from interactor
long long performQuery(int node, int distance) {
    if (distance <= 0) return 0;
    cout << "? " << node << " " << distance << endl;
    long long result;
    cin >> result;
    return result;
}

int main() {
    int height;
    if (!(cin >> height)) return 0;

    // Total number of nodes in perfect binary tree: n = 2^height - 1
    int totalNodes = (1 << height) - 1;
    long long bestEstimate = 0;

    // Determine how many nodes to sample based on query limit constraints
    int sampleCount = min(totalNodes, 400);

    // For each sampled node, compute the sum over all valid distances (Scan operation)
    for (int node = 1; node <= sampleCount; ++node) {
        long long scanSum = 0;
        // Maximum possible distance in tree is 2 * height
        for (int dist = 1; dist <= 2 * height; ++dist) {
            scanSum += performQuery(node, dist);
        }
        // Keep track of maximum scan value observed (approximates S)
        if (scanSum > bestEstimate) {
            bestEstimate = scanSum;
        }
    }

    // Output final estimate for total weight sum
    cout << "! " << bestEstimate << endl;
    return 0;
}

