double ArcBall::s_sphereRadius = 0.7;

ArcBall::ArcBall()
{
    m_Quat.a  = 0.0;
    m_Quat.qx = 0.0;
    m_Quat.qy = 0.0;
    m_Quat.qz = 0.0;

    // Initialize with pseudo iso viewpoint: first apply base orientation, then yaw offset
    Quaternion qBase;
    qBase.fromEulerAngles(ROLL, PITCH, YAW);
    Quaternion qYaw(-30.0, Vector3d(0.0, 0.0, 1.0));
    setQuat((qBase * qYaw).a, (qBase * qYaw).qx, (qBase * qYaw).qy, (qBase * qYaw).qz);

    m_Start.set(0.0, 0.0, 1.0);
    m_Current = m_Start;
}

void ArcBall::applyRotation(Quaternion const &rotQ, bool invertOrder)
{
    if (invertOrder) {
        // Post-multiply: current rotation followed by new one
        m_Quat = m_Quat * rotQ;
    } else {
        // Pre-multiply: new rotation applied before current
        m_Quat = rotQ * m_Quat;
    }
}

/** update current arcball rotation based on mouse movement */
void ArcBall::move(double xView, double yView)
{
    getSpherePoint(xView, yView, m_Current);

    // Skip if movement is negligible
    double dx = m_Current.xf() - m_Start.xf();
    double dy = m_Current.yf() - m_Start.yf();
    double dz = m_Current.zf() - m_Start.zf();
    if (dx*dx + dy*dy + dz*dz < 1e-12) return;

    // Compute unit vectors for start and current positions
    Vector3d uStart = m_Start;
    uStart.normalize();
    Vector3d uCurrent = m_Current;
    uCurrent.normalize();

    // Build incremental rotation quaternion from uStart to uCurrent
    Quaternion deltaRot;
    deltaRot.from2UnitVectors(uStart, uCurrent);

    // Apply relative rotation to the initial state
    m_Quat = deltaRot * m_QuatStart;
}

void ArcBall::rotateCrossPoint(float &outAngleDeg, float &axisX, float &axisY, float &axisZ)
{
    Vector3d refAxis(1.0, 0.0, 0.0);
    Vector3d currVec = m_Current;
    currVec.normalize();

    double dotProd = refAxis.dot(currVec);
    // Clamp dot product to [-1, 1] to avoid NaN in acos
    dotProd = std::max(-1.0, std::min(1.0, dotProd));

    double halfCos = std::sqrt((1.0 + dotProd) * 0.5);
    outAngleDeg = static_cast<float>(2.0 * std::acos(halfCos) * 180.0 / M_PI);

    // Compute rotation axis as cross product: refAxis × currVec
    Vector3d rotAxis(
        refAxis.yf() * currVec.zf() - refAxis.zf() * currVec.yf(),
        refAxis.zf() * currVec.xf() - refAxis.xf() * currVec.zf(),
        refAxis.xf() * currVec.yf() - refAxis.yf() * currVec.xf()
    );

    double len = rotAxis.norm();
    if (len > 1e-12) {
        rotAxis /= len;
    }

    axisX = static_cast<float>(rotAxis.xf());
    axisY = static_cast<float>(rotAxis.yf());
    axisZ = static_cast<float>(rotAxis.zf());
}

void ArcBall::setQuat(double realPart, double imagX, double imagY, double imagZ)
{
    m_Quat.a  = realPart;
    m_Quat.qx = imagX;
    m_Quat.qy = imagY;
    m_Quat.qz = imagZ;
}

void ArcBall::start(double xView, double yView)
{
    getSpherePoint(xView, yView, m_Start);
    m_Current = m_Start;
    m_QuatStart = m_Quat;
}

/** maps viewport coordinates to point on sphere surface */
void ArcBall::getSpherePoint(double xv, double yv, Vector3d &ptOut)
{
    double rSq = s_sphereRadius * s_sphereRadius;
    double distSq = xv*xv + yv*yv;

    if (distSq <= rSq) {
        ptOut.set(xv, yv, std::sqrt(rSq - distSq));
    } else {
        ptOut.set(xv, yv, 0.0);
    }

    ptOut.normalize();
}

