DoubleIntegratorInterface::DoubleIntegratorInterface(const std::string& taskFile, const std::string& libDir, bool verbose) {
  // Validate task file path
  boost::filesystem::path taskPath(taskFile);
  if (!taskPath.empty() && boost::filesystem::exists(taskPath)) {
    std::cerr << "[DoubleIntegratorInterface] Task configuration loaded from: " << taskPath << std::endl;
  } else {
    throw std::invalid_argument("[DoubleIntegratorInterface] Task file missing: " + taskPath.string());
  }

  // Ensure output directory exists
  boost::filesystem::path libPath(libDir);
  if (!boost::filesystem::exists(libPath)) {
    boost::filesystem::create_directories(libPath);
  }
  std::cerr << "[DoubleIntegratorInterface] Library directory prepared at: " << libPath << std::endl;

  // Load system parameters
  loadData::loadEigenMatrix(taskFile, "initialState", initialState_);
  loadData::loadEigenMatrix(taskFile, "finalGoal", finalGoal_);

  // Configure DDP/MPC solvers
  ddpSettings_ = ddp::loadSettings(taskFile, "ddp", verbose);
  mpcSettings_ = mpc::loadSettings(taskFile, "mpc", verbose);

  // Initialize reference manager
  referenceManagerPtr_ = std::make_shared<ReferenceManager>();

  // Build optimal control problem
  // Cost matrices
  matrix_t stateWeight(STATE_DIM, STATE_DIM);
  matrix_t inputWeight(INPUT_DIM, INPUT_DIM);
  matrix_t finalStateWeight(STATE_DIM, STATE_DIM);

  loadData::loadEigenMatrix(taskFile, "Q", stateWeight);
  loadData::loadEigenMatrix(taskFile, "R", inputWeight);
  loadData::loadEigenMatrix(taskFile, "Q_final", finalStateWeight);

  std::cerr << "State cost matrix Q:\n" << stateWeight << "\n";
  std::cerr << "Input cost matrix R:\n" << inputWeight << "\n";
  std::cerr << "Terminal cost matrix Qf:\n" << finalStateWeight << "\n";

  // Add running and terminal costs
  problem_.costPtr->add("stage_cost", 
                        std::make_unique<QuadraticStateInputCost>(stateWeight, inputWeight));
  problem_.finalCostPtr->add("terminal_cost", 
                             std::make_unique<QuadraticStateCost>(finalStateWeight));

  // Linear system dynamics: x_dot = A x + B u
  matrix_t dynA(STATE_DIM, STATE_DIM);
  dynA << 0.0, 1.0,
          0.0, 0.0;

  matrix_t dynB(STATE_DIM, INPUT_DIM);
  dynB << 0.0,
          1.0;

  problem_.dynamicsPtr = std::make_unique<LinearSystemDynamics>(dynA, dynB);

  // Set up trajectory rollout
  auto rolloutParams = rollout::loadSettings(taskFile, "rollout", verbose);
  rolloutPtr_ = std::make_unique<TimeTriggeredRollout>(*problem_.dynamicsPtr, rolloutParams);

  // Default state initializer for MPC warm-start
  linearSystemInitializerPtr_ = std::make_unique<DefaultInitializer>(INPUT_DIM);
}

