// Count regular bracket substrings in a given string
int count_valid_bracket_substrings(const string& str) {
    int len = str.length();
    int count = 0;

    for (int start = 0; start < len; ++start) {
        int balance = 0;
        for (int end = start; end < len; ++end) {
            if (str[end] == '(') {
                balance++;
            } else {
                balance--;
            }

            if (balance < 0) break;
            if (balance == 0) count++;
        }
    }

    return count;
}

// Generate a distinguishing pattern for m variables
vector<int> generate_distinguishing_pattern(int num_vars) {
    while (true) {
        int pattern_length = 14 + rand() % 8;
        vector<int> pattern(pattern_length);

        for (int i = 0; i < pattern_length; ++i) {
            if (rand() % 3 == 0) {
                pattern[i] = -1; // filler position
            } else {
                pattern[i] = rand() % num_vars; // variable index
            }
        }

        map<int, int> seen_results;
        bool is_valid = true;
        int total_states = 1 << num_vars;

        for (int state_mask = 0; state_mask < total_states; ++state_mask) {
            string constructed_string = "";

            for (int pos : pattern) {
                if (pos == -1) {
                    constructed_string += ')';
                } else {
                    if ((state_mask >> pos) & 1) {
                        constructed_string += '(';
                    } else {
                        constructed_string += ')';
                    }
                }
            }

            int result = count_valid_bracket_substrings(constructed_string);

            if (seen_results.find(result) != seen_results.end()) {
                is_valid = false;
                break;
            }

            seen_results[result] = state_mask;
        }

        if (is_valid) {
            return pattern;
        }
    }
}

// Send query and receive response
int send_query(const vector<int>& positions) {
    cout << "0 " << positions.size();
    for (int idx : positions) {
        cout << " " << idx;
    }
    cout << endl;

    int response;
    cin >> response;

    if (response == -1) {
        exit(0); // Error condition
    }

    return response;
}

void solve_problem_instance(int n) {
    // Determine first character s[0]
    bool first_char_is_closing = false;
    vector<int> batch_indices;

    for (int i = 2; i <= n; ++i) {
        batch_indices.push_back(i);
        batch_indices.push_back(1);

        if (batch_indices.size() >= 900 || i == n) {
            int result = send_query(batch_indices);
            if (result > 0) {
                first_char_is_closing = true;
            }
            batch_indices.clear();
        }
    }

    char first_char = first_char_is_closing ? ')' : '(';

    // Prepare pattern for decoding 6 variables at a time
    int var_count = 6;
    vector<int> base_pattern = generate_distinguishing_pattern(var_count);

    // Build lookup table for decoding
    map<int, int> result_to_mask;
    int total_states = 1 << var_count;

    for (int mask = 0; mask < total_states; ++mask) {
        string test_string = "";
        for (int pos : base_pattern) {
            if (pos == -1) {
                test_string += ')';
            } else {
                if ((mask >> pos) & 1) {
                    test_string += '(';
                } else {
                    test_string += ')';
                }
            }
        }
        result_to_mask[count_valid_bracket_substrings(test_string)] = mask;
    }

    string result(n, ' ');
    result[0] = first_char;

    // Process remaining characters in chunks of size up to 6
    for (int start_idx = 2; start_idx <= n; start_idx += var_count) {
        int chunk_size = min(var_count, n - start_idx + 1);
        vector<int> current_chunk_indices;

        for (int j = 0; j < chunk_size; ++j) {
            current_chunk_indices.push_back(start_idx + j);
        }

        // Pad with first position if needed
        while (current_chunk_indices.size() < var_count) {
            current_chunk_indices.push_back(1);
        }

        vector<int> query_positions;

        if (first_char == ')') {
            // Use original pattern: fillers are ')'
            for (int pos : base_pattern) {
                if (pos == -1) {
                    query_positions.push_back(1);
                } else {
                    query_positions.push_back(current_chunk_indices[pos]);
                }
            }
        } else {
            // Reverse pattern when filler is '('
            vector<int> reversed_pattern = base_pattern;
            reverse(reversed_pattern.begin(), reversed_pattern.end());
            for (int pos : reversed_pattern) {
                if (pos == -1) {
                    query_positions.push_back(1);
                } else {
                    query_positions.push_back(current_chunk_indices[pos]);
                }
            }
        }

        int query_result = send_query(query_positions);
        int decoded_mask = result_to_mask[query_result];

        for (int j = 0; j < chunk_size; ++j) {
            int bit_value = (decoded_mask >> j) & 1;
            char character;

            if (first_char == ')') {
                // Bit 1 means '('
                character = (bit_value ? '(' : ')');
            } else {
                // Bit 1 means ')', bit 0 means '('
                character = (bit_value ? ')' : '(');
            }

            result[start_idx + j - 1] = character;
        }
    }

    cout << "1 " << result << endl;
}

