#include <iostream>
#include <vector>
#include <queue>
using namespace std;

int n;
vector<vector<int>> graph;
vector<int> indegree;

// Query function to compare two elements
bool compare(int a, int b) {
    cout << "? " << a << " " << b << endl;
    char response;
    cin >> response;
    return response == '<';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;

    // Initialize data structures
    graph.resize(n + 1);
    indegree.assign(n + 1, 0);

    // Build edges for consecutive pairs
    for (int i = 1; i < n; ++i) {
        if (compare(i, i + 1)) {
            graph[i].push_back(i + 1);
            indegree[i + 1]++;
        } else {
            graph[i + 1].push_back(i);
            indegree[i]++;
        }
    }

    // Build edges for pairs with gap of 2
    for (int i = 1; i <= n - 2; ++i) {
        if (compare(i, i + 2)) {
            graph[i].push_back(i + 2);
            indegree[i + 2]++;
        } else {
            graph[i + 2].push_back(i);
            indegree[i]++;
        }
    }

    // Topological sort using Kahn's algorithm with min-heap
    vector<int> topo_order;
    priority_queue<int, vector<int>, greater<int>> min_heap;

    // Find all nodes with no incoming edges
    for (int node = 1; node <= n; ++node) {
        if (indegree[node] == 0) {
            min_heap.push(node);
        }
    }

    // Process nodes in topological order
    while (!min_heap.empty()) {
        int current = min_heap.top();
        min_heap.pop();
        topo_order.push_back(current);

        for (int neighbor : graph[current]) {
            indegree[neighbor]--;
            if (indegree[neighbor] == 0) {
                min_heap.push(neighbor);
            }
        }
    }

    // Assign values according to topological order
    vector<int> result(n + 1);
    int current_value = 1;
    for (int node : topo_order) {
        result[node] = current_value++;
    }

    // Output the result
    cout << "!";
    for (int i = 1; i <= n; ++i) {
        cout << " " << result[i];
    }
    cout << endl;

    return 0;
}

#include "testing/testing.hpp"
