UNIT_TEST(NumHiZeroBits64)
{
  // Count leading zeros in 64-bit integers
  TEST_EQUAL(bits::NumHiZeroBits64(0), 64, ());
  TEST_EQUAL(bits::NumHiZeroBits64(0xFFFFFFFFFFFFFFFFULL), 0, ());
