void freeaddrinfo(struct addrinfo *p)
{
    // Count the number of entries in the list
    size_t count = 0;
    struct addrinfo *current = p;
    while (current != NULL) {
        count++;
        current = current->ai_next;
    }

    // Calculate base address of the buffer
    struct aibuf *buf = (struct aibuf *)((char *)p - offsetof(struct aibuf, ai));

    // Adjust buffer pointer based on slot offset
    buf -= buf->slot;

    // Acquire lock for thread-safe reference counting
    LOCK(buf->lock);

    // Update reference count and free if no longer referenced
    if (!(buf->ref -= count)) {
        free(buf);
    } else {
        UNLOCK(buf->lock);
    }
}

