#include <bits/stdc++.h>
using namespace std;

typedef vector<int> Perm;

// Custom hash for vector<int> to use in unordered_map
struct PermHash {
    size_t operator()(const Perm& p) const {
        size_t h = 0;
        for (int x : p) {
            h ^= hash<int>()(x) + 0x9e3779b9 + (h << 6) + (h >> 2);
        }
        return h;
    }
};

struct State {
    Perm perm;
    int op_x, op_y;     // operation applied to reach this state
    int parent_idx;     // index of parent state in BFS queue
    int depth;          // number of operations used so far

    State(const Perm& p, int x, int y, int par, int d)
        : perm(p), op_x(x), op_y(y), parent_idx(par), depth(d) {}
};

// Apply operation (x, y): suffix of length y → front, middle part, prefix of length x → end
Perm apply_operation(const Perm& p, int x, int y) {
    int n = p.size();
    if (x + y >= n) return p; // invalid operation
    Perm res(n);
    // Suffix of length y becomes prefix
    copy(p.end() - y, p.end(), res.begin());
    // Middle part: from index x to n-y-1
    copy(p.begin() + x, p.begin() + x + (n - x - y), res.begin() + y);
    // Prefix of length x becomes suffix
    copy(p.begin(), p.begin() + x, res.begin() + n - x);
    return res;
}

// BFS solver for small n (≤9), returns best reachable permutation and operations
pair<Perm, vector<pair<int,int>>> bfs_solve(const Perm& start, int max_depth) {
    int n = start.size();
    unordered_map<Perm, int, PermHash> visited; // perm → state index
    vector<State> states;
    states.emplace_back(start, -1, -1, -1, 0);
    visited[start] = 0;

    queue<int> q;
    q.push(0);

    int best_idx = 0;
    Perm best_perm = start;

    while (!q.empty()) {
        int idx = q.front(); q.pop();
        const State& cur = states[idx];

        // Update best if current perm is lexicographically smaller
        if (cur.perm < best_perm) {
            best_perm = cur.perm;
            best_idx = idx;
        }

        // Stop expanding if we've reached max depth
        if (cur.depth >= max_depth) continue;

        // Try all valid (x, y) pairs: x ≥ 1, y ≥ 1, x + y < n
        for (int x = 1; x < n; ++x) {
            for (int y = 1; x + y < n; ++y) {
                Perm next_perm = apply_operation(cur.perm, x, y);
                if (visited.find(next_perm) == visited.end()) {
                    int new_idx = states.size();
                    states.emplace_back(next_perm, x, y, idx, cur.depth + 1);
                    visited[next_perm] = new_idx;
                    q.push(new_idx);
                }
            }
        }
    }

    // Reconstruct operations
    vector<pair<int,int>> ops;
    int cur = best_idx;
    while (states[cur].parent_idx != -1) {
        ops.emplace_back(states[cur].op_x, states[cur].op_y);
        cur = states[cur].parent_idx;
    }
    reverse(ops.begin(), ops.end());
    return {best_perm, ops};
}

// Greedy solver for larger n (>9)
vector<pair<int,int>> greedy_solve(Perm p, int max_ops) {
    int n = p.size();
    vector<pair<int,int>> ops;

    // Try to minimize lex order step-by-step
    for (int step = 0; step < max_ops; ++step) {
        bool improved = false;
        int best_x = -1, best_y = -1;
        Perm best_next = p;

        // Try all (x, y) and pick the one giving smallest lex perm
        for (int x = 1; x < n; ++x) {
            for (int y = 1; x + y < n; ++y) {
                Perm candidate = apply_operation(p, x, y);
                if (candidate < best_next) {
                    best_next = candidate;
                    best_x = x;
                    best_y = y;
                    improved = true;
                }
            }
        }

        if (!improved) break;

        ops.emplace_back(best_x, best_y);
        p = best_next;
    }

    return ops;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    Perm p(n);
    for (int i = 0; i < n; ++i) {
        cin >> p[i];
    }

    vector<pair<int,int>> operations;
    int max_allowed_ops = 4 * n;

    if (n <= 9) {
        auto result = bfs_solve(p, max_allowed_ops);
        operations = move(result.second);
    } else {
        operations = greedy_solve(p, max_allowed_ops);
    }

    cout << operations.size() << '\n';
    for (auto& [x, y] : operations) {
        cout << x << ' ' << y << '\n';
    }

    return 0;
}

