void CritParticle::tick()
{
    int attempts = 0;
    while (attempts < 16)
    {
        double dx = random->nextFloat() * 2.0 - 1.0;
        double dy = random->nextFloat() * 2.0 - 1.0;
        double dz = random->nextFloat() * 2.0 - 1.0;

        // Skip if outside unit sphere
        if (dx*dx + dy*dy + dz*dz > 1.0)
        {
            attempts++;
            continue;
        }

        double posX = targetEntity->x + dx * targetEntity->bbWidth / 4.0;
        double posY = targetEntity->bb->y0 + targetEntity->bbHeight / 2.0 + dy * targetEntity->bbHeight / 4.0;
        double posZ = targetEntity->z + dz * targetEntity->bbWidth / 4.0;

        level->addParticle(particleKind, posX, posY, posZ, dx, dy + 0.2, dz);

        attempts++;
    }

    age++;
    if (age >= maxAge)
    {
        remove();
    }
}

