void TransConstraint::SetScaleVectorOnTransform(RndTransformable *xfm, Vector3 &scaleVec) {
    MILO_ASSERT(xfm, 0x80);
    Vector3 euler;
    Hmx::Matrix3 rotMat;
    Transform worldXfm = xfm->WorldXfm();
    MakeEuler(worldXfm.m, euler);
    MakeRotMatrix(euler, rotMat, true);
    Scale(rotMat, scaleVec, rotMat);
    worldXfm.m = rotMat;
    xfm->SetWorldXfm(worldXfm);
}

void TransConstraint::SnapToParent() {
    if (mParent && mChild) {
        Vector3 parentPos = mParent->WorldXfm().v;
        Vector3 childPos = mChild->WorldXfm().v;

        int axis = 0;
        while (axis < 3) {
            if (mTracks[axis]) {
                childPos[axis] = parentPos[axis];
            }
            ++axis;
        }

        mChild->SetWorldPos(childPos);

        if (mAffectScale) {
            Vector3 parentScale;
            MakeScale(mParent->WorldXfm().m, parentScale);
            Vector3 childScale;
            MakeScale(mChild->WorldXfm().m, childScale);

            int dim = 0;
            while (dim < 3) {
                if (mTracks[dim]) {
                    childScale[dim] = parentScale[dim];
                }
                ++dim;
            }

            SetScaleVectorOnTransform(mChild, childScale);
        }
    }
}

