// Benchmark for Hadamard Gate operation to evaluate memory bandwidth usage
static void BM_HadamardMemoryTest(benchmark::State &state) {
  int qubit_count = state.range(0);

  // Initialize quantum register outside the timing loop to exclude allocation overhead
  try {
    QuantumRegister reg(qubit_count);

    for (auto _ : state) {
      // Apply Hadamard gate to first qubit - a memory-intensive operation
      reg.applyHadamard(0);

      // Ensure compiler doesn't optimize away the computation
      benchmark::DoNotOptimize(reg.getStateVector().data());
      benchmark::ClobberMemory();
    }

    // Compute data volume processed: each element is complex (16 bytes)
    // For N qubits: 2^N amplitudes, each read once and written once => 2 * 2^N * 16 bytes
    uint64_t amplitude_count = 1ULL << qubit_count;
    double total_bytes = static_cast<double>(amplitude_count) * 16.0 * 2.0;

    state.SetBytesProcessed(static_cast<int64_t>(state.iterations()) * 
                            static_cast<int64_t>(total_bytes));

  } catch (const std::exception &e) {
    state.SkipWithError("Memory allocation failed or insufficient system resources");
  }
}

// Register benchmarks with different system sizes:
// 20 qubits → ~16 MB, 25 qubits → ~512 MB, 28 qubits → ~4 GB
BENCHMARK(BM_HadamardMemoryTest)
    ->Arg(20)
    ->Arg(25)
    ->Arg(28)
    ->Unit(benchmark::kMillisecond);

BENCHMARK_MAIN();

