// Determine if this InlineAttempt should be committed (true) or only used for analysis (false)
bool InlineAttempt::isEnabled() {
  // Root function: always committed.
  if (Callers.empty()) {
    return true;
  }

  // Path condition functions are symbolic and produce no runtime code.
  if (isPathCondition) {
    return false;
  }

  // Otherwise, commit if shared or explicitly enabled.
  return isShared() || enabled;
}

// PeelIteration instances are always committed.
bool PeelIteration::isEnabled() {
  return true;
}

// PeelAttempt follows its own 'enabled' flag.
bool PeelAttempt::isEnabled() {
  return enabled;
}

// Attempt to set the commit status ('enabled') for an InlineAttempt.
void InlineAttempt::setEnabled(bool en, bool skipStats) {
  // Root cannot be disabled.
  if (Callers.empty()) {
    return;
  }

  // Shared contexts cannot currently be disabled.
  if (isShared()) {
    return;
  }

  // Path conditions never commit anyway.
  if (isPathCondition) {
    return;
  }

  enabled = en;
  if (!skipStats) {
    pass->getRoot()->collectStats();
  }
}

void PeelIteration::setEnabled(bool en, bool skipStats) {
  assert(false && "Individual iteration disabling not yet supported");
}

void PeelAttempt::setEnabled(bool en, bool skipStats) {
  enabled = en;
}

// Check whether this InlineAttempt commits in a *different* residual function than its parent.
bool InlineAttempt::commitsOutOfLine() {
  // No parent: root call → must commit out-of-line.
  if (isRootMainCall()) {
    return true;
  }

  for (SmallVector<ShadowInstruction *, 1>::const_iterator it = Callers.begin(),
                                                            end = Callers.end();
       it != end; ++it) {
    ShadowInstruction *caller = *it;
    FunctionRoot *parentRoot = caller->parent->IA->getFunctionRoot();

    // If CommitF exists and differs from parent's CommitF, then out-of-line commit occurred.
    if (CommitF && parentRoot->CommitF && parentRoot->CommitF != CommitF) {
      return true;
    }
  }

  return false;
}

// PeelIterations always commit in the same function as their parent.
bool PeelIteration::commitsOutOfLine() {
  return false;
}

// Determine if this InlineAttempt *must* be committed as a standalone residual function.
bool InlineAttempt::mustCommitOutOfLine() {
  // Root naturally requires its own residual function.
  if (isRootMainCall()) {
    return true;
  }

  // Vararg functions need real va_list support.
  if (F.isVarArg()) {
    return true;
  }

  // Shared functions require separate callable unit.
  if (isShared()) {
    return true;
  }

  // User-specified split point?
  if (pass->splitFunctions.find(&F) != pass->splitFunctions.end()) {
    return true;
  }

  // Handle failed return paths — especially for invokes.
  if (hasFailedReturnPath()) {
    for (uint32_t i = 0, limit = Callers.size(); i < limit; ++i) {
      if (isa<InvokeInst>(Callers[i])) {
        return true;
      }
    }
  }

  return false;
}

bool PeelIteration::mustCommitOutOfLine() {
  return false;
}

// Verify that all ancestor contexts are enabled.
bool IntegrationAttempt::allAncestorsEnabled() {
  // First check self.
  if (!isEnabled()) {
    return false;
  }

  // Get unique parent context.
  IntegrationAttempt *parentCtx = getUniqueParent();

  // If there's no unique parent (e.g., shared), assume safe.
  if (!parentCtx) {
    return true;
  }

  // Recursively verify ancestors.
  if (!parentCtx->allAncestorsEnabled()) {
    return false;
  }

  return true;
}

