namespace infiniop_test::sub {

struct Test::Attributes {
    std::shared_ptr<Tensor> input_a;
    std::shared_ptr<Tensor> input_b;
    std::shared_ptr<Tensor> output_c;
    std::shared_ptr<Tensor> expected_result;
};

std::shared_ptr<Test> Test::build(
    std::unordered_map<std::string, std::vector<uint8_t>> attr_map,
    std::unordered_map<std::string, std::shared_ptr<Tensor>> tensor_map,
    double rel_tol, double abs_tol) {

    auto test_obj = std::make_shared<Test>(rel_tol, abs_tol);
    test_obj->_attributes = new Attributes();

    // Validate required tensors exist
    const char* required_keys[] = {"a", "b", "c", "ans"};
    for (const auto& key : required_keys) {
        if (tensor_map.find(key) == tensor_map.end()) {
            throw std::runtime_error("Invalid Test: missing tensor '" + std::string(key) + "'");
        }
    }

    test_obj->_attributes->input_a = tensor_map["a"];
    test_obj->_attributes->input_b = tensor_map["b"];
    test_obj->_attributes->output_c = tensor_map["c"];
    test_obj->_attributes->expected_result = tensor_map["ans"];

    return test_obj;
}

std::shared_ptr<infiniop_test::Result> Test::run(
    infiniopHandle_t handle, infiniDevice_t dev, int dev_id, size_t pre_runs, size_t num_runs) {

    infiniopSubDescriptor_t op_descriptor;

    // Move tensors to target device
    auto src_a = _attributes->input_a->to(dev, dev_id);
    auto src_b = _attributes->input_b->to(dev, dev_id);
    auto dst_c = _attributes->output_c->to(dev, dev_id);

    // Create operation descriptor
    CHECK_OR(infiniopCreateSubDescriptor(handle, &op_descriptor,
                                         dst_c->desc(),
                                         src_a->desc(),
                                         src_b->desc()),
             return TEST_FAILED(OP_CREATION_FAILED, "Failed to create sub descriptor."));

    // Query workspace requirements
    size_t scratch_size;
    CHECK_OR(infiniopGetSubWorkspaceSize(op_descriptor, &scratch_size),
             return TEST_FAILED(OP_CREATION_FAILED, "Failed to query workspace size."));

    // Allocate workspace memory
    void* scratch_mem;
    CHECK_OR(infinirtMalloc(&scratch_mem, scratch_size),
             return TEST_FAILED(OP_CREATION_FAILED, "Failed to allocate scratch memory."));

    // Perform forward pass
    CHECK_OR(infiniopSub(op_descriptor, scratch_mem, scratch_size,
                         dst_c->data(),
                         src_a->data(),
                         src_b->data(),
                         nullptr),
             return TEST_FAILED(OP_EXECUTION_FAILED, "Sub operation failed during execution."));

    // Validate result
    try {
        allClose(dst_c, _attributes->expected_result, _rtol, _atol);
    } catch (const std::exception& err) {
        return TEST_FAILED(RESULT_INCORRECT, err.what());
    }

    // Benchmark timing
    double duration = 0.0;
    duration = benchmark(
        [=]() {
            infiniopSub(
                op_descriptor, scratch_mem, scratch_size,
                dst_c->data(),
                src_a->data(),
                src_b->data(),
                nullptr);
        },
        pre_runs, num_runs);

    return TEST_PASSED(duration);
}

