// Timing parameters for ClimaButler IR protocol
const uint16_t kClimaButlerBitMark = 511;    // microseconds
const uint16_t kClimaButlerHdrMark = kClimaButlerBitMark;
const uint16_t kClimaButlerHdrSpace = 3492;  // microseconds
const uint16_t kClimaButlerOneSpace = 1540;  // microseconds
const uint16_t kClimaButlerZeroSpace = 548;  // microseconds
const uint32_t kClimaButlerGap = kDefaultMessageGap;  // microseconds (estimated)
const uint16_t kClimaButlerFreq = 38000;     // Hz (approximate)

#if SEND_CLIMABUTLER
/// Transmit a ClimaButler formatted command.
/// Status: STABLE / Verified operation.
/// @param[in] payload The IR command data.
/// @param[in] bitCount Number of bits in the command.
/// @param[in] repeatCount How many times to repeat transmission.
void IRsend::sendClimaButler(const uint64_t payload, const uint16_t bitCount,
                             const uint16_t repeatCount) {
  enableIROut(kClimaButlerFreq);

  // Repeat the transmission as requested
  for (uint16_t repetition = 0; repetition <= repeatCount; repetition++) {
    // Send header pulse/space followed by data bits
    sendGeneric(kClimaButlerHdrMark, kClimaButlerHdrSpace,
                kClimaButlerBitMark, kClimaButlerOneSpace,
                kClimaButlerBitMark, kClimaButlerZeroSpace,
                kClimaButlerBitMark, kClimaButlerHdrSpace,
                payload, bitCount, kClimaButlerFreq, true, 0, kDutyDefault);

    // End with footer mark and gap
    mark(kClimaButlerBitMark);
    space(kClimaButlerGap);
  }
}
#endif  // SEND_CLIMABUTLER

#if DECODE_CLIMABUTLER
/// Decode incoming ClimaButler IR signal.
/// Status: STABLE / Verified operation.
/// @param[in,out] results Pointer to storage for decoded results.
/// @param[in] startIdx Position in raw buffer where decoding should begin.
/// @param[in] expectedBits Expected number of data bits.
/// @param[in] enforceStrict Whether to require exact bit count match.
/// @return True if decoding successful, false otherwise.
bool IRrecv::decodeClimaButler(decode_results *results, uint16_t startIdx,
                               const uint16_t expectedBits, const bool enforceStrict) {
  // Check minimum buffer length requirement
  if (results->rawlen < 2 * expectedBits + kHeader + 2 * kFooter - startIdx)
    return false;  // Signal too short for valid ClimaButler message

  // Validate bit count if strict mode enabled
  if (enforceStrict && expectedBits != kClimaButlerBits)
    return false;

  // Attempt to decode header and data portion
  uint16_t consumed = matchGeneric(results->rawbuf + startIdx, &(results->value),
                                   results->rawlen - startIdx, expectedBits,
                                   kClimaButlerHdrMark, kClimaButlerHdrSpace,
                                   kClimaButlerBitMark, kClimaButlerOneSpace,
                                   kClimaButlerBitMark, kClimaButlerZeroSpace,
                                   kClimaButlerBitMark, kClimaButlerHdrSpace);

  if (!consumed) return false;  // Header/data pattern not found

  // Move past the decoded header+data section
  startIdx += consumed;

  // Verify footer mark
  if (!matchMark(results->rawbuf[startIdx++], kClimaButlerBitMark))
    return false;

  // Check final gap duration
  if (results->rawlen <= startIdx && !matchAtLeast(results->rawbuf[startIdx],
                                                   kClimaButlerGap))
    return false;

  // Mark as successfully decoded ClimaButler protocol
  results->decode_type = decode_type_t::CLIMABUTLER;
  results->bits = expectedBits;
  results->command = 0;
  results->address = 0;
  return true;
}
#endif  // DECODE_CLIMABUTLER

