// Custom implementation of atoi function to convert string to integer
int my_atoi(const char *str)
{
    int result = 0;
    int sign = 1;

    // Skip leading whitespace characters
    while (isspace(*str)) {
        str++;
    }

    // Handle optional sign
    if (*str == '-') {
        sign = -1;
        str++;
    } else if (*str == '+') {
        str++;
    }

    // Process digits and build the result as a negative number to handle INT_MIN safely
    while (isdigit(*str)) {
        result = 10 * result - (*str - '0');
        str++;
    }

    // Return with appropriate sign
    return sign * result;
}

