using namespace std;

// Constants and declarations
const int MAX_VERTICES = 1005;
int vertexCount, edgeCount;
bitset<MAX_VERTICES> adjacency[MAX_VERTICES];
vector<int> currentClique;
vector<int> optimalClique;
int maxCliqueSize = 0;
clock_t startTime;
const double MAX_TIME = 1.95; // Slightly under 2 seconds

// Reusable arrays for greedy coloring
static int colorUsage[MAX_VERTICES];
static int colorMarker = 0;

/**
 * Recursive search for maximum clique using pruning strategies.
 * candidates: bitset representing potential vertices to consider
 */
void findMaxClique(bitset<MAX_VERTICES> candidates) {
    // Time check
    if ((double)(clock() - startTime) / CLOCKS_PER_SEC > MAX_TIME) return;

    int remaining = candidates.count();

    // Base case: no more candidates
    if (remaining == 0) {
        if (currentClique.size() > maxCliqueSize) {
            maxCliqueSize = currentClique.size();
            optimalClique = currentClique;
        }
        return;
    }

    // Pruning: upper bound check based on remaining candidates
    if (currentClique.size() + remaining <= maxCliqueSize) return;

    // Extract candidate vertices into a list
    vector<int> nodeOrder;
    nodeOrder.reserve(remaining);
    for (int v = 1; v <= vertexCount; ++v) {
        if (candidates[v]) nodeOrder.push_back(v);
    }

    // Greedy coloring heuristic for upper bound estimation
    vector<int> assignedColor(vertexCount + 1, 0);
    int usedColors = 0;

    for (int node : nodeOrder) {
        colorMarker++;

        // Mark colors used by adjacent already-colored nodes
        for (int neighbor : nodeOrder) {
            if (neighbor == node) continue;
            if (assignedColor[neighbor] != 0 && adjacency[node][neighbor]) {
                colorUsage[assignedColor[neighbor]] = colorMarker;
            }
        }

        // Find first available color
        int c = 1;
        while (colorUsage[c] == colorMarker) c++;
        assignedColor[node] = c;
        if (c > usedColors) usedColors = c;
    }

    // Pruning: chromatic number bound
    if (currentClique.size() + usedColors <= maxCliqueSize) return;

    // Sort nodes by color (ascending)
    sort(nodeOrder.begin(), nodeOrder.end(), [&](int a, int b) {
        return assignedColor[a] < assignedColor[b];
    });

    // Process in reverse order (higher colors first)
    for (int idx = (int)nodeOrder.size() - 1; idx >= 0; --idx) {
        // Periodic time check
        if ((double)(clock() - startTime) / CLOCKS_PER_SEC > MAX_TIME) return;

        int node = nodeOrder[idx];
        int nodeColor = assignedColor[node];

        // Pruning: color-based bound
        if (currentClique.size() + nodeColor <= maxCliqueSize) break;

        // Include this node in the current clique
        currentClique.push_back(node);

        // Remove node from candidate set
        candidates[node] = 0;

        // Recurse with neighbors only
        findMaxClique(candidates & adjacency[node]);

        // Backtrack
        currentClique.pop_back();
    }
}

int main() {
    // Input reading
    if (scanf("%d %d", &vertexCount, &edgeCount) != 2) return 0;

    for (int i = 0; i < edgeCount; ++i) {
        int u, v;
        scanf("%d %d", &u, &v);
        if (u >= 1 && u <= vertexCount && v >= 1 && v <= vertexCount) {
            adjacency[u][v] = 1;
            adjacency[v][u] = 1;
        }
    }

    startTime = clock();

    // Initialize candidate set with all vertices
    bitset<MAX_VERTICES> initialCandidates;
    for (int i = 1; i <= vertexCount; ++i) {
        initialCandidates.set(i);
    }

    findMaxClique(initialCandidates);

    // Output result
    vector<int> output(vertexCount + 1, 0);
    for (int v : optimalClique) {
        output[v] = 1;
    }

    for (int i = 1; i <= vertexCount; ++i) {
        printf("%d\n", output[i]);
    }

    return 0;
}

