UNIT_TEST(RebuildIndexSmokeTest)
{
  Platform & platformRef = GetPlatform();
  classificator::Initialize();

  // Open existing map file for reading
  FilesContainerR sourceMap(platformRef.GetReader("minsk-pass" DATA_FILE_EXTENSION));

  // Prepare buffer for serialized index
  vector<uint8_t> newIndexBuffer;

  {
    // Use features from original container to generate new index
    FeaturesVectorTest featureSource(sourceMap);
    MemWriter<vector<uint8_t>> indexSerializer(newIndexBuffer);

    // Generate and serialize the index data
    indexer::ConstructIndex(featureSource.GetHeader(), 
                            featureSource.GetVector(), 
                            indexSerializer, 
                            "smoke_test_index_build");
  }

  // Prepare target file path and remove any pre-existing file
  string const targetName = "smoke_test_index_build" DATA_FILE_EXTENSION;
  string const targetPath = platformRef.WritablePathForFile(targetName);
  FileWriter::RemoveFile(targetPath);

  // Reconstruct MWM with updated index
  {
    FilesContainerW targetWriter(targetPath);
    vector<string> sectionNames;
    sourceMap.ForEachTag(base::MakeBackInsertFunctor(sectionNames));

    // Copy all sections except the old index
    for (size_t idx = 0; idx < sectionNames.size(); ++idx)
    {
      if (sectionNames[idx] != INDEX_FILE_TAG)
        targetWriter.Write(sourceMap.GetReader(sectionNames[idx]), sectionNames[idx]);
    }
    // Insert newly built index
    targetWriter.Write(newIndexBuffer, INDEX_FILE_TAG);
  }

  // Validate that the rebuilt index is functional
  {
    FrozenDataSource dataSource;
    UNUSED_VALUE(dataSource.Register(platform::LocalCountryFile::CreateForTesting("smoke_test_index_build")));

    // Trigger actual parsing by iterating over features at scale 15
    dataSource.ForEachInScale([](FeatureType &) { return true; }, 15);
  }

  // Cleanup temporary test file
  FileWriter::RemoveFile(targetPath);
}

