#define DEBUG_TYPE "lowerinvoke"

STATISTIC(NumReplacedInvokes, "Number of invoke instructions lowered");

namespace {

class LowerInvokeLegacyPass : public FunctionPass {
public:
  static char ID; // Pass identification, replacement for typeid

  explicit LowerInvokeLegacyPass() : FunctionPass(ID) {
    initializeLowerInvokeLegacyPassPass(*PassRegistry::getPassRegistry());
  }

  bool runOnFunction(Function &F) override;
};

} // anonymous namespace

char LowerInvokeLegacyPass::ID = 0;

INITIALIZE_PASS(LowerInvokeLegacyPass, "lowerinvoke",
                "Lower invoke and unwind, for unwindless code generators",
                false, false)

static bool processFunction(Function &F) {
  bool Modified = false;

  for (BasicBlock &BB : F) {
    if (InvokeInst *II = dyn_cast<InvokeInst>(BB.getTerminator())) {
      SmallVector<Value *, 16> Arguments(II->args());
      SmallVector<OperandBundleDef, 1> BundleList;
      II->getOperandBundlesAsDefs(BundleList);

      // Create a regular call instruction with the same properties
      CallInst *ReplacementCall = CallInst::Create(
          II->getFunctionType(),
          II->getCalledOperand(),
          Arguments,
          BundleList,
          "",
          II
      );

      ReplacementCall->takeName(II);
      ReplacementCall->setCallingConv(II->getCallingConv());
      ReplacementCall->setAttributeList(II->getAttributes());
      ReplacementCall->setDebugLoc(II->getDebugLoc());

      // Replace all uses of the invoke with the new call
      II->replaceAllUsesWith(ReplacementCall);

      // Add an unconditional branch to the normal destination
      BranchInst::Create(II->getNormalDest(), II);

      // Update PHI nodes in the exception destination by removing this block as predecessor
      II->getUnwindDest()->removePredecessor(&BB);

      // Remove the original invoke instruction
      II->eraseFromParent();

      ++NumReplacedInvokes;
      Modified = true;
    }
  }

  return Modified;
}

bool LowerInvokeLegacyPass::runOnFunction(Function &F) {
  return processFunction(F);
}

namespace llvm {

char &LowerInvokePassID = LowerInvokeLegacyPass::ID;

// Public interface to the pass
FunctionPass *createLowerInvokePass() { 
  return new LowerInvokeLegacyPass(); 
}

PreservedAnalyses LowerInvokePass::run(Function &F,
                                       FunctionAnalysisManager &AM) {
  bool Changed = processFunction(F);

  if (!Changed)
    return PreservedAnalyses::all();

  return PreservedAnalyses::none();
}

} // namespace llvm

#include <iostream>
