#include <nlohmann/json.hpp>
#include <vector>

using json = nlohmann::json;

int main() {
    // Prepare a byte vector containing JSON array [1,2,3] followed by extra characters
    std::vector<std::uint8_t> data = {'[', '1', ',', '2', ',', '3', ']', 'e', 'x', 't', 'r', 'a'};

    // Extract only the valid JSON portion (first 7 bytes)
    auto begin = data.begin();
    auto end = begin + 7;

    // Parse the JSON and format output with indentation
    json parsed = json::parse(begin, end);
    std::cout << std::setw(4) << parsed << "\n\n";

    return 0;
}

#include <bpf/bpf.h>

struct cgroup {
    int identifier;
};

struct trace_cgroup_args {
    unsigned long cgroup_ptr;
    unsigned long path_ptr;
};

SEC("raw_tracepoint/cgroup_mkdir")
int trace_cgroup_create(struct trace_cgroup_args* args) {
    struct cgroup* group = (struct cgroup*)args->cgroup_ptr;
    if (!group) {
        return 0;
    }
    int gid = BPF_CORE_READ(group, identifier);
    BPF_PRINTK("cgroup created, id: %d, path: %s\n", gid, (const char*)args->path_ptr);
    return 0;
}
