#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <chrono>
#include <random>
using namespace std;

struct City {
    int id;
    int x, y;
};

int N;
vector<City> cities;
vector<int> tour; // size N+1
vector<bool> prime_flags;

inline double distance(int a, int b) {
    long long dx = cities[a].x - cities[b].x;
    long long dy = cities[a].y - cities[b].y;
    return sqrt(static_cast<double>(dx * dx + dy * dy));
}

inline double penalty_factor(int step_num, int city_id) {
    if (step_num % 10 == 0 && !prime_flags[city_id]) 
        return 1.1;
    return 1.0;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> N)) return 0;

    cities.resize(N);
    for (int i = 0; i < N; ++i) {
        cities[i].id = i;
        cin >> cities[i].x >> cities[i].y;
    }

    // Sieve of Eratosthenes for prime detection
    prime_flags.assign(N + 1, true);
    prime_flags[0] = prime_flags[1] = false;
    for (int p = 2; p * p <= N; ++p) {
        if (prime_flags[p]) {
            for (int multiple = p * p; multiple <= N; multiple += p)
                prime_flags[multiple] = false;
        }
    }

    // Construct initial bitonic-like path based on input order
    tour.reserve(N + 1);
    tour.push_back(0);

    // Even-indexed cities in increasing order
    for (int idx = 2; idx < N; idx += 2)
        tour.push_back(idx);

    // Odd-indexed cities in decreasing order
    int start_odd = (N % 2 == 0) ? N - 1 : N - 2;
    for (int idx = start_odd; idx >= 1; idx -= 2)
        tour.push_back(idx);

    tour.push_back(0);

    auto start = chrono::steady_clock::now();

    // Tunable parameters
    const int window_len = 25;
    const int prime_search_range = 40;
    bool changed = true;

    while (true) {
        // Time limit check: ~1850ms max
        auto now = chrono::steady_clock::now();
        auto elapsed = chrono::duration_cast<chrono::milliseconds>(now - start).count();
        if (elapsed > 1850) break;

        changed = false;

        // Phase 1: Local 2-opt improvement with windowing
        for (int i = 1; i < N - 1; ++i) {
            if ((i & 4095) == 0) {
                auto now = chrono::steady_clock::now();
                auto elapsed = chrono::duration_cast<chrono::milliseconds>(now - start).count();
                if (elapsed > 1850) goto finish;
            }

            int end_j = min(N - 1, i + window_len);
            for (int j = i + 1; j <= end_j; ++j) {
                double old_cost = 0.0;
                double new_cost = 0.0;

                // Compute cost before reversal
                for (int k = i; k <= j + 1; ++k) {
                    old_cost += distance(tour[k-1], tour[k]) * penalty_factor(k, tour[k-1]);
                }

                // Compute cost after reversal
                for (int k = i; k <= j + 1; ++k) {
                    int src_idx = k - 1;
                    int dst_idx = k;

                    int src_node = (src_idx < i) ? tour[src_idx] : 
                                   (src_idx > j) ? tour[src_idx] : 
                                   tour[i + j - src_idx];
                    int dst_node = (dst_idx < i) ? tour[dst_idx] : 
                                   (dst_idx > j) ? tour[dst_idx] : 
                                   tour[i + j - dst_idx];

                    double mult = (k % 10 == 0 && !prime_flags[src_node]) ? 1.1 : 1.0;
                    new_cost += distance(src_node, dst_node) * mult;
                }

                if (new_cost < old_cost - 1e-9) {
                    reverse(tour.begin() + i, tour.begin() + j + 1);
                    changed = true;
                }
            }
        }

        // Phase 2: Prime-aware local search to reduce penalties
        for (int target_step = 10; target_step <= N; target_step += 10) {
            if ((target_step & 511) == 0) {
                auto now = chrono::steady_clock::now();
                auto elapsed = chrono::duration_cast<chrono::milliseconds>(now - start).count();
                if (elapsed > 1850) goto finish;
            }

            int pos = target_step - 1; // position in tour[]
            if (prime_flags[tour[pos]]) continue;

            int low = max(1, pos - prime_search_range);
            int high = min(N - 1, pos + prime_search_range);

            for (int alt_pos = low; alt_pos <= high; ++alt_pos) {
                if (alt_pos == pos || !prime_flags[tour[alt_pos]]) continue;

                int idx_a = pos;
                int idx_b = alt_pos;
                if (idx_a > idx_b) swap(idx_a, idx_b);

                vector<int> affected_steps;
                affected_steps.push_back(idx_a);
                affected_steps.push_back(idx_a + 1);
                if (idx_b != idx_a + 1) {
                    affected_steps.push_back(idx_b);
                }
                affected_steps.push_back(idx_b + 1);

                double prev_cost = 0.0;
                for (int s : affected_steps) {
                    if (s > N) continue;
                    prev_cost += distance(tour[s-1], tour[s]) * penalty_factor(s, tour[s-1]);
                }

                swap(tour[idx_a], tour[idx_b]);

                double curr_cost = 0.0;
                for (int s : affected_steps) {
                    if (s > N) continue;
                    curr_cost += distance(tour[s-1], tour[s]) * penalty_factor(s, tour[s-1]);
                }

                if (curr_cost < prev_cost - 1e-9) {
                    changed = true;
                    break;
                } else {
                    swap(tour[idx_a], tour[idx_b]); // revert
                }
            }
        }

        if (!changed) break;
    }

finish:
    cout << tour.size() << "\n";
    for (int node : tour) {
        cout << node << "\n";
    }
    return 0;
}

