// Static initialization for delete queues
int                           SparseLightStorage::deleteQueueIndex;
XLockFreeStack<unsigned char> SparseLightStorage::deleteQueue[3];

void SparseLightStorage::staticCtor() {
    // Initialize all three lock-free stacks used for deferred deletion
    for (int idx = 0; idx < 3; ++idx) {
        deleteQueue[idx].Initialize();
    }
}

// Constructor: Initializes storage with either all-zero or all-15 sky data
SparseLightStorage::SparseLightStorage(bool sky) {
#ifdef _XBOX
    unsigned char* rawMem = (unsigned char*)
        XPhysicalAlloc(128 * 128, MAXULONG_PTR, 4096, PAGE_READWRITE);
#else
    unsigned char* rawMem = (unsigned char*)malloc(128 * 128);
#endif

    unsigned char* indicesPtr = rawMem;
    unsigned char* dataPtr    = rawMem + 128;

    // Set first index based on sky flag
    indicesPtr[127] = sky ? ALL_15_INDEX : ALL_0_INDEX;

    // Fill remaining indices sequentially
    for (int i = 0; i < 127; ++i) {
        indicesPtr[i] = static_cast<unsigned char>(i);
    }

    // Zero out the data region
    XMemSet(dataPtr, 0, 128 * 127);

    // Pack pointer and count into 64-bit value
#pragma warning(disable : 4826)
    dataAndCount = (static_cast<std::int64_t>(127) << 48) |
                   (reinterpret_cast<std::int64_t>(indicesPtr) & 0x0000ffffffffffffL);
#pragma warning(default : 4826)

#ifdef LIGHT_COMPRESSION_STATS
    count = 127;
#endif
}

// Alternate constructor: Minimal allocation for special cases
SparseLightStorage::SparseLightStorage(bool sky, bool /*unused*/) {
    unsigned char* indicesPtr = (unsigned char*)malloc(128);

    // Fill all entries with same value
    for (int i = 0; i < 128; ++i) {
        indicesPtr[i] = sky ? ALL_15_INDEX : ALL_0_INDEX;
    }

    // Store only pointer, no planes allocated yet
#pragma warning(disable : 4826)
    dataAndCount = reinterpret_cast<std::int64_t>(indicesPtr) & 0x0000ffffffffffffL;
#pragma warning(default : 4826)

#ifdef LIGHT_COMPRESSION_STATS
    count = 0;
#endif
}

// Destructor: Properly frees memory depending on allocation method
SparseLightStorage::~SparseLightStorage() {
    unsigned char* basePtr =
        reinterpret_cast<unsigned char*>(dataAndCount & 0x0000ffffffffffff);

#ifdef _XBOX
    if (reinterpret_cast<std::uintptr_t>(basePtr) >= MM_PHYSICAL_4KB_BASE) {
        XPhysicalFree(basePtr);
    } else {
        free(basePtr);
    }
#else
    free(basePtr);
#endif
}

// Copy constructor: Deep copy of existing storage
SparseLightStorage::SparseLightStorage(SparseLightStorage* source) {
    std::int64_t srcDataAndCount = source->dataAndCount;
    unsigned char* srcBase       =
        reinterpret_cast<unsigned char*>(srcDataAndCount & 0x0000ffffffffffff);
    int srcPlaneCount = static_cast<int>((srcDataAndCount >> 48) & 0xffff);

    size_t totalSize = 128 * (srcPlaneCount + 1);
    unsigned char* dstBase = (unsigned char*)malloc(totalSize);

    // Ensure visibility before memcpy completes (Vita workaround)
#pragma warning(disable : 4826)
    dataAndCount = ((srcDataAndCount & 0xffff000000000000L) |
                    (reinterpret_cast<std::int64_t>(dstBase) & 0x0000ffffffffffffL));
#pragma warning(default : 4826)

    XMemCpy(dstBase, srcBase, totalSize);

#ifdef LIGHT_COMPRESSION_STATS
    count = srcPlaneCount;
#endif
}

// Populate storage from external byte array
void SparseLightStorage::setData(byteArray dataIn, unsigned int inOffset) {
    int           allocCount = 0;
    unsigned char localIndices[128];

    // First pass: determine which planes need actual storage
    for (int y = 0; y < 128; ++y) {
        bool allZero   = true;
        bool allFifteen = true;

        for (int xz = 0; xz < 256; ++xz) {
            int pos   = (xz << 7) | y;
            int slot  = pos >> 1;
            int part  = pos & 1;
            unsigned char val =
                (dataIn[slot + inOffset] >> (part * 4)) & 15;

            if (val != 0)      allZero = false;
            if (val != 15)     allFifteen = false;
        }

        if (allZero) {
            localIndices[y] = ALL_0_INDEX;
        } else if (allFifteen) {
            localIndices[y] = ALL_15_INDEX;
        } else {
            localIndices[y] = static_cast<unsigned char>(allocCount++);
        }
    }

    // Allocate new memory block
    size_t memSize = 128 * (allocCount + 1);
    unsigned char* newMem = (unsigned char*)malloc(memSize);
    unsigned char* indicesNew = newMem;
    unsigned char* dataNew    = newMem + 128;

    XMemCpy(indicesNew, localIndices, 128);

    // Second pass: copy actual plane data
    for (int y = 0; y < 128; ++y) {
        if (indicesNew[y] < ALL_0_INDEX) {
            int part = y & 1;
            unsigned char* src = &dataIn[(y >> 1) + inOffset];
            unsigned char* dst = &dataNew[128 * indicesNew[y]];

            for (int xz = 0; xz < 128; ++xz) {
                unsigned char low  = (*src >> (part * 4)) & 15;
                src += 64;
                unsigned char high = (*src >> (part * 4)) & 15;
                src += 64;
                *dst++ = static_cast<unsigned char>((high << 4) | low);
            }
        }
    }

    // Update internal state atomically
#pragma warning(disable : 4826)
    std::int64_t newDataAndCount =
        (static_cast<std::int64_t>(allocCount) << 48) |
        (reinterpret_cast<std::int64_t>(newMem) & 0x0000ffffffffffffL);
#pragma warning(default : 4826)

    updateDataAndCount(newDataAndCount);
}

// Extract lighting data into external buffer
void SparseLightStorage::getData(byteArray retArray, unsigned int retOffset) {
    XMemSet(retArray.data + retOffset, 0, 16384);

    unsigned char* indices;
    unsigned char* data;
    getPlaneIndicesAndData(&indices, &data);

    for (int y = 0; y < 128; ++y) {
        unsigned char idx = indices[y];

        if (idx == ALL_0_INDEX) {
            continue;
        } else if (idx == ALL_15_INDEX) {
            int part = y & 1;
            unsigned char fillVal = static_cast<unsigned char>(15 << (part * 4));
            unsigned char* out = &retArray.data[(y >> 1) + retOffset];

            for (int xz = 0; xz < 256; ++xz) {
                *out |= fillVal;
                out += 64;
            }
        } else {
            int part = y & 1;
            unsigned char* src = &data[128 * idx];
            unsigned char* dst = &retArray.data[(y >> 1) + retOffset];

            for (int xz = 0; xz < 128; ++xz) {
                unsigned char valLow  = *src & 15;
                unsigned char valHigh = (*src >> 4) & 15;
                *dst |= static_cast<unsigned char>(valLow << (part * 4));
                dst += 64;
                *dst |= static_cast<unsigned char>(valHigh << (part * 4));
                dst += 64;
                src++;
            }
        }
    }
}

// Retrieve single light value
int SparseLightStorage::get(int x, int y, int z) {
    unsigned char* indices;
    unsigned char* data;
    getPlaneIndicesAndData(&indices, &data);

    unsigned char planeIdx = indices[y];
    if (planeIdx == ALL_0_INDEX) return 0;
    if (planeIdx == ALL_15_INDEX) return 15;

    int tileIndex = x * 16 + z;
    int byteIndex = tileIndex / 2;
    int bitShift  = (tileIndex % 2) * 4;

    unsigned char byteVal =
        data[128 * planeIdx + byteIndex];
    return (byteVal >> bitShift) & 15;
}

// Set single light value
void SparseLightStorage::set(int x, int y, int z, int val) {
    unsigned char* indices;
    unsigned char* data;
    getPlaneIndicesAndData(&indices, &data);

    unsigned char planeIdx = indices[y];
    if (planeIdx >= ALL_0_INDEX) {
        // Special case handling
        if ((val == 0 && planeIdx == ALL_0_INDEX) ||
            (val == 15 && planeIdx == ALL_15_INDEX)) {
            return;
        }
        addNewPlane(y);
        getPlaneIndicesAndData(&indices, &data);
    }

    int tileIndex = x * 16 + z;
    int byteIndex = tileIndex / 2;
    int bitShift  = (tileIndex % 2) * 4;
    int mask      = 0xf0 >> bitShift;

    unsigned char* target = &data[128 * indices[y] + byteIndex];
    *target = static_cast<unsigned char>((*target & mask) | (val << bitShift));
}

// Set entire storage to maximum brightness
void SparseLightStorage::setAllBright() {
    unsigned char* indices = (unsigned char*)malloc(128);
    for (int i = 0; i < 128; ++i) {
        indices[i] = ALL_15_INDEX;
    }

#pragma warning(disable : 4826)
    std::int64_t newDataAndCount =
        (static_cast<std::int64_t>(0) << 48) |
        (reinterpret_cast<std::int64_t>(indices) & 0x0000ffffffffffffL);
#pragma warning(default : 4826)

    updateDataAndCount(newDataAndCount);
}

// Write region of lighting data
int SparseLightStorage::setDataRegion(
    byteArray dataIn,
    int       x0, int y0, int z0,
    int       x1, int y1, int z1,
    int       offset
) {
    unsigned char* pucIn = &dataIn.data[offset];
    for (int x = x0; x < x1; ++x) {
        for (int z = z0; z < z1; ++z) {
            int startY = y0 & ~1;
            int len    = (y1 - y0) / 2;
            for (int i = 0; i < len; ++i) {
                int y = startY + i * 2;
                set(x, y,     z, *pucIn & 15);
                set(x, y + 1, z, (*pucIn >> 4) & 15);
                ++pucIn;
            }
        }
    }
    return static_cast<int>(pucIn - &dataIn.data[offset]);
}

// Read region of lighting data
int SparseLightStorage::getDataRegion(
    byteArray dataInOut,
    int       x0, int y0, int z0,
    int       x1, int y1, int z1,
    int       offset
) {
    unsigned char* pucOut = &dataInOut.data[offset];
    for (int x = x0; x < x1; ++x) {
        for (int z = z0; z < z1; ++z) {
            int startY = y0 & ~1;
            int len    = (y1 - y0) / 2;
            for (int i = 0; i < len; ++i) {
                int y = startY + i * 2;
                unsigned char low  = static_cast<unsigned char>(get(x, y,     z));
                unsigned char high = static_cast<unsigned char>(get(x, y + 1, z));
                *pucOut = static_cast<unsigned char>((high << 4) | low);
                ++pucOut;
            }
        }
    }
    return static_cast<int>(pucOut - &dataInOut.data[offset]);
}

// Add a new plane at given Y coordinate
void SparseLightStorage::addNewPlane(int y) {
    bool success = false;
    do {
        std::int64_t current = dataAndCount;
        int          oldCount = (current >> 48) & 0xffff;
        unsigned char* oldData =
            reinterpret_cast<unsigned char*>(current & 0x0000ffffffffffff);

        unsigned char curPlane = oldData[y];
        if (curPlane < ALL_0_INDEX) {
            return; // Already allocated
        }

        int prefillValue = (curPlane == ALL_15_INDEX) ? 255 : 0;
        int newCount     = oldCount + 1;

        size_t newSize = 128 * (newCount + 1);
        unsigned char* newData = (unsigned char*)malloc(newSize);
        XMemCpy(newData, oldData, 128 * oldCount + 128);
        XMemSet(newData + 128 * oldCount + 128, prefillValue, 128);
        newData[y] = static_cast<unsigned char>(oldCount);

#pragma warning(disable : 4826)
        std::int64_t updated =
            (static_cast<std::int64_t>(newCount) << 48) |
            (reinterpret_cast<std::int64_t>(newData) & 0x0000ffffffffffffL);
#pragma warning(default : 4826)

        std::int64_t prev = InterlockedCompareExchangeRelease64(
            &dataAndCount, updated, current);

        if (prev == current) {
            success = true;
            queueForDelete(oldData);
#ifdef LIGHT_COMPRESSION_STATS
            count = newCount;
#endif
        } else {
            queueForDelete(newData);
        }
    } while (!success);
}

// Helper to extract pointers from packed value
void SparseLightStorage::getPlaneIndicesAndData(
    unsigned char** planeIndices,
    unsigned char** data
) {
    unsigned char* base =
        reinterpret_cast<unsigned char*>(dataAndCount & 0x0000ffffffffffff);
    *planeIndices = base;
    *data         = base + 128;
}

// Queue memory for deferred deletion
void SparseLightStorage::queueForDelete(unsigned char* ptr) {
    deleteQueue[deleteQueueIndex].Push(ptr);
}

// Perform garbage collection of queued memory
void SparseLightStorage::tick() {
    int freeIndex = (deleteQueueIndex + 1) % 3;
    unsigned char* item = nullptr;

    do {
        item = deleteQueue[freeIndex].Pop();
        if (item) {
#ifdef _XBOX
            if (reinterpret_cast<std::uintptr_t>(item) >= MM_PHYSICAL_4KB_BASE) {
                XPhysicalFree(item);
            } else {
                free(item);
            }
#else
            free(item);
#endif
        }
    } while (item);

    deleteQueueIndex = (deleteQueueIndex + 1) % 3;
}

// Atomically replace current storage
void SparseLightStorage::updateDataAndCount(std::int64_t newDataAndCount) {
    bool done = false;
    do {
        std::int64_t old = dataAndCount;
        unsigned char* oldPtr =
            reinterpret_cast<unsigned char*>(old & 0x0000ffffffffffff);

        std::int64_t result = InterlockedCompareExchangeRelease64(
            &dataAndCount, newDataAndCount, old);

        if (result == old) {
            done = true;
            queueForDelete(oldPtr);
        }
    } while (!done);
}

// Attempt compression of stored planes
int SparseLightStorage::compress() {
    std::int64_t current = dataAndCount;
    unsigned char* base =
        reinterpret_cast<unsigned char*>(current & 0x0000ffffffffffff);
    unsigned char* planes = base + 128;
    int currentCount = (current >> 48) & 0xffff;

    unsigned char newIndices[128];
    bool changed = false;
    int neededPlanes = 0;

    for (int i = 0; i < 128; ++i) {
        unsigned char idx = base[i];
        if (idx == ALL_0_INDEX || idx == ALL_15_INDEX) {
            newIndices[i] = idx;
        } else {
            unsigned char* planeData = &planes[128 * idx];
            bool allZero = true;
            bool allFifteen = true;

            for (int j = 0; j < 128; ++j) {
                if (planeData[j] != 0) allZero = false;
                if (planeData[j] != 255) allFifteen = false;
            }

            if (allZero) {
                newIndices[i] = ALL_0_INDEX;
                changed = true;
            } else if (allFifteen) {
                newIndices[i] = ALL_15_INDEX;
                changed = true;
            } else {
                newIndices[i] = static_cast<unsigned char>(neededPlanes++);
            }
        }
    }

    if (changed) {
        size_t newMemSize = 128 * (neededPlanes + 1);
        unsigned char* newMem = (unsigned char*)malloc(newMemSize);
        XMemCpy(newMem, newIndices, 128);

        unsigned char* newData = newMem + 128;
        for (int i = 0; i < 128; ++i) {
            if (newIndices[i] < ALL_0_INDEX) {
                XMemCpy(newData, &planes[128 * base[i]], 128);
                newData += 128;
            }
        }

#pragma warning(disable : 4826)
        std::int64_t updated =
            (static_cast<std::int64_t>(neededPlanes) << 48) |
            (reinterpret_cast<std::int64_t>(newMem) & 0x0000ffffffffffffL);
#pragma warning(default : 4826)

        std::int64_t prev = InterlockedCompareExchangeRelease64(
            &dataAndCount, updated, current);

        if (prev != current) {
            queueForDelete(newMem);
        } else {
            queueForDelete(base);
#ifdef LIGHT_COMPRESSION_STATS
            count = neededPlanes;
#endif
        }
        return neededPlanes;
    } else {
        return currentCount;
    }
}

// Check if currently compressed (fewer than full planes)
bool SparseLightStorage::isCompressed() {
    int cnt = (dataAndCount >> 48) & 0xffff;
    return cnt < 127;
}

// Serialization methods
void SparseLightStorage::write(DataOutputStream* dos) {
    int cnt = (dataAndCount >> 48) & 0xffff;
    dos->writeInt(cnt);

    unsigned char* ptr =
        reinterpret_cast<unsigned char*>(dataAndCount & 0x0000ffffffffffff);
    byteArray wrapper(ptr, 128 * (cnt + 1));
    dos->write(wrapper);
}

void SparseLightStorage::read(DataInputStream* dis) {
    int cnt = dis->readInt();
    unsigned char* ptr = (unsigned char*)malloc(128 * (cnt + 1));
    byteArray wrapper(ptr, 128 * (cnt + 1));
    dis->readFully(wrapper);

#pragma warning(disable : 4826)
    std::int64_t updated =
        (static_cast<std::int64_t>(cnt) << 48) |
        (reinterpret_cast<std::int64_t>(ptr) & 0x0000ffffffffffffL);
#pragma warning(default : 4826)

    updateDataAndCount(updated);
}

