#include <iostream>
#include <vector>
#include <cstdlib>
using namespace std;

// Global state tracking variables
int initialDepth;
int currentDepth;
int moveCount = 0;

// Constants for safety and move limits
const int MAX_MOVES_ALLOWED = 100000;
const int SAFETY_MARGIN = 95000;

// Function to query the depth (distance to exit)
int getDepth() {
    cout << "query" << endl;
    int d;
    if (!(cin >> d)) exit(0);
    return d;
}

// Function to move along edge of color c
void traverseEdge(int c) {
    cout << "move " << c << endl;
    int result;
    if (!(cin >> result)) exit(0);
    moveCount++;
    if (result == 1) {
        // Exit reached
        exit(0);
    }
}

// History of upward moves taken
vector<int> pathHistory;

// The edge color that leads back down from the current node
int incomingEdge = -1;

// Safely ascend one level using at most 3 moves and 1 query
void safeAscent() {
    // Determine candidate edges: all except the one leading down
    vector<int> options;
    for (int col = 0; col < 3; ++col) {
        if (col != incomingEdge) {
            options.push_back(col);
        }
    }

    // Try first option
    int tryColor = options[0];
    traverseEdge(tryColor);

    // Check if we moved up or down
    int newDepth = getDepth();
    if (newDepth < currentDepth) {
        // Success: moved up
        currentDepth = newDepth;
        incomingEdge = tryColor;
        pathHistory.push_back(tryColor);
    } else {
        // Failed: moved down instead, so revert and try the other option
        traverseEdge(tryColor); // Go back

        int altColor = options[1];
        traverseEdge(altColor);

        // This must be the correct upward move
        currentDepth--;
        incomingEdge = altColor;
        pathHistory.push_back(altColor);
    }
}

// First step to determine which direction is upward (since incomingEdge is unknown initially)
void firstMove() {
    // Try color 0
    traverseEdge(0);
    int d = getDepth();
    if (d < currentDepth) {
        currentDepth = d;
        incomingEdge = 0;
        pathHistory.push_back(0);
        return;
    }
    traverseEdge(0); // Revert

    // Try color 1
    traverseEdge(1);
    d = getDepth();
    if (d < currentDepth) {
        currentDepth = d;
        incomingEdge = 1;
        pathHistory.push_back(1);
        return;
    }
    traverseEdge(1); // Revert

    // Must be color 2
    traverseEdge(2);
    currentDepth--;
    incomingEdge = 2;
    pathHistory.push_back(2);
}

int main() {
    // Read starting depth
    if (!(cin >> initialDepth)) return 0;
    currentDepth = initialDepth;

    // Already at exit?
    if (currentDepth == 0) return 0;

    // Perform first move to establish orientation
    firstMove();

    // Continue until reaching the root (exit)
    while (currentDepth > 0) {
        // If approaching move limit, switch to safe mode
        if (moveCount > SAFETY_MARGIN) {
            safeAscent();
            continue;
        }

        // Attempt pattern-based batching for efficiency
        int bestPeriod = -1;
        int historySize = pathHistory.size();

        // Look for repeating patterns in recent moves (up to length 20)
        for (int P = 1; P <= 20 && 2 * P <= historySize; ++P) {
            bool isPattern = true;
            for (int i = 0; i < P; ++i) {
                if (pathHistory[historySize - P + i] != pathHistory[historySize - 2 * P + i]) {
                    isPattern = false;
                    break;
                }
            }
            if (isPattern) {
                bestPeriod = P;
                break;
            }
        }

        if (bestPeriod != -1) {
            int batchLength = min(bestPeriod, currentDepth);

            // Build predicted sequence
            vector<int> predictedMoves;
            for (int i = 0; i < batchLength; ++i) {
                predictedMoves.push_back(pathHistory[historySize - bestPeriod + i]);
            }

            // Execute batch
            for (int col : predictedMoves) {
                traverseEdge(col);
            }

            // Verify with a single query
            int actualDepth = getDepth();

            if (actualDepth == currentDepth - batchLength) {
                // Prediction was correct
                currentDepth = actualDepth;
                incomingEdge = predictedMoves.back();
                pathHistory.insert(pathHistory.end(), predictedMoves.begin(), predictedMoves.end());
            } else {
                // Prediction failed — backtrack and fall back to safe ascent
                for (int i = batchLength - 1; i >= 0; --i) {
                    traverseEdge(predictedMoves[i]);
                }
                safeAscent();
            }
        } else {
            // No pattern found — use safe method
            safeAscent();
        }
    }

    return 0;
}

