#include "TakesCoreLog.h"
#include "TakeMetaData.h"
#include "TakeData.h"
#include "LevelSequence.h"
#include "MovieSceneToolsModule.h"
#include "Modules/ModuleManager.h"

class FTakesCoreModule : public IModuleInterface
{
public:
	virtual void StartupModule() override
	{
		// Load required module early to avoid dependency issues
		FModuleManager::Get().LoadModuleChecked("LevelSequence");

		// Initialize take metadata on the LevelSequence CDO
		ULevelSequence* SequenceCDO = GetMutableDefault<ULevelSequence>();
		UTakeMetaData* MetaData = SequenceCDO->FindOrAddMetaData<UTakeMetaData>();
		MetaData->SetFlags(RF_Transient);

		// Store weak reference to CDO for safe cleanup later
		StoredSequenceCDO = SequenceCDO;

		// Prepare and register take data with Sequencer integration
		TakeDataHandle = MakeShareable(new FTakesCoreTakeData);
		FMovieSceneToolsModule& ToolsModule = FModuleManager::Get().GetModuleChecked<FMovieSceneToolsModule>("MovieSceneTools");
		ToolsModule.RegisterTakeData(TakeDataHandle.Get());
	}

	virtual void ShutdownModule() override
	{
		// Safely unregister take data before potential CDO destruction
		if (TakeDataHandle.IsValid())
		{
			FMovieSceneToolsModule::Get().UnregisterTakeData(TakeDataHandle.Get());
			TakeDataHandle.Reset();
		}

		// Clean up metadata from CDO if still valid
		if (ULevelSequence* ValidCDO = StoredSequenceCDO.Get())
		{
			ValidCDO->RemoveMetaData<UTakeMetaData>();
		}
	}

private:
	// Weak pointer to prevent dangling references during shutdown
	TWeakObjectPtr<ULevelSequence> StoredSequenceCDO;

	// Shared ownership of take data implementation
	TSharedPtr<IMovieSceneToolsTakeData> TakeDataHandle;
};

IMPLEMENT_MODULE(FTakesCoreModule, TakesCore);
DEFINE_LOG_CATEGORY(LogTakesCore);

