namespace engine::monitor {

//-------------------------------------------------------------------------
/// @details
///		Core monitoring loop: periodically checks whether to refresh stats.
///		Runs until cancellation or explicit stop via m_started flag.
///	@param[in] none
///		No parameters needed; uses internal state.
//-------------------------------------------------------------------------
void Monitor::runMonitoringCycle() noexcept {
    for (;;) {
        // Wait before next check
        async::sleep(100ms);

        // Skip update if insufficient time has elapsed since last update
        if ((time::now() - m_lastUpdate) < 2.5s) continue;

        // Perform update only if monitor is still active
        if (m_started) {
            refreshMonitorState();
        }

        // Record current timestamp as latest update point
        m_lastUpdate = time::now();

        // Continue loop until cancelled externally
        if (async::cancelled()) break;
    }
}

//-------------------------------------------------------------------------
/// @details
///		Launches background thread responsible for periodic updates.
///		Ensures idempotency by asserting against double-start.
//-------------------------------------------------------------------------
void Monitor::initiateMonitoring() noexcept {
    // Defensive programming: prevent accidental re-initialization
    ASSERT(!m_started);

    // Initialize worker thread with descriptive name and binding
    m_updateThread = async::Thread{_location, "Status",
                                   _bind(&Monitor::runMonitoringCycle, this)};

    // Kick off execution
    m_updateThread->start();

    // Mark as active
    m_started = true;
}

//-------------------------------------------------------------------------
/// @details
///		Activate counters inherited from base class hierarchy.
//-------------------------------------------------------------------------
void Monitor::enableCounters() noexcept { Parent::enableCounters(); }

//-----------------------------------------------------------------
///	@details
///		Logs a warning message internally, up to a cap of 25 entries.
///		Maintains thread-safety using scoped lock.
///	@param[in]
///		Error code to store
//-----------------------------------------------------------------
Error Monitor::warn(Error &&ccode) noexcept {
    auto guard = lock();
    if (m_warnings.size() < 25u) {
        m_warnings.push_back(_mv(ccode));
    }
    return ccode;
}

//-----------------------------------------------------------------
///	@details
///		Logs an error message internally, up to a cap of 25 entries.
///		Maintains thread-safety using scoped lock.
///	@param[in]
///		Error code to store
//-----------------------------------------------------------------
Error Monitor::reportError(Error &&ccode) noexcept {
    auto guard = lock();
    if (m_errors.size() < 25u) {
        m_errors.push_back(_mv(ccode));
    }
    return ccode;
}

//-----------------------------------------------------------------
///	@details
///		Handles exit condition logging; currently identity operation.
///	@param[in]
///		Error code to pass through
//-----------------------------------------------------------------
Error Monitor::exitCode(Error &&ccode) noexcept { return ccode; }

//-----------------------------------------------------------------
///	@details
///		Callback invoked when crash dump file is generated.
///		Currently unused in base implementation.
///	@param[in]	location
///		Source location of crash event
///	@param[in]	path
///		Path to generated crash dump file
//-----------------------------------------------------------------
void Monitor::onCrashDumpCreated(Location location,
                                 const file::Path &path) noexcept {
    // Intentionally left blank in base class
}

//-----------------------------------------------------------------
///	@details
///		Sets arbitrary JSON metadata for reporting purposes.
///		Thread-safe assignment under lock.
///	@param[in]	info
///		JSON object containing additional info
//-----------------------------------------------------------------
void Monitor::setInfo(const json::Value &info) noexcept {
    auto guard = lock();
    m_info = info;
}

//-----------------------------------------------------------------
///	@details
///		Sets performance metrics in JSON format.
///		Thread-safe assignment under lock.
///	@param[in]	metrics
///		JSON object containing metric data
//-----------------------------------------------------------------
void Monitor::setMetrics(const json::Value &metrics) noexcept {
    auto guard = lock();
    m_metrics = metrics;
}

//-----------------------------------------------------------------
///	@details
///		Placeholder for status string output.
///		Currently no-op in base class.
///	@param[in]	status
///		Status text to display
//-----------------------------------------------------------------
void Monitor::setStatusText(TextView status) noexcept {}

//-----------------------------------------------------------------
///	@details
///		Reports service availability status (up/down).
///		Currently no-op in base class.
///	@param[in]	status
///		Boolean indicating service health
//-----------------------------------------------------------------
void Monitor::setServiceHealth(bool status) noexcept {}

//-----------------------------------------------------------------
///	@details
///		Raw key-value logging hook for custom formatting.
///		Currently no-op in base class.
///	@param[in]	key
///		Key label
///	@param[in]	value
///		Value payload
//-----------------------------------------------------------------
void Monitor::logCustomEntry(TextView key, TextView value) noexcept {}

//-----------------------------------------------------------------
///	@details
///		Outputs generic object representation (size + identifier).
///		Currently no-op in base class.
///	@param[in]	name
///		Object name/key
///	@param[in]	size
///		Size in bytes
//-----------------------------------------------------------------
void Monitor::logObject(TextView name, uint64_t size) noexcept {}

//-------------------------------------------------------------------------
/// @details
///		Determines whether this instance serves as application-level monitor.
///		Overridden in subclasses like App.hpp.
//-------------------------------------------------------------------------
bool Monitor::isApplicationMonitor() noexcept { return false; }

//-----------------------------------------------------------------
///	@details
///		Handles dependency download progress reporting.
///		Base version does nothing.
///	@param[in]	data
///		JSON structure describing download state
//-----------------------------------------------------------------
void Monitor::reportDependencyDownload(const json::Value &data) noexcept {
    // Default behavior: ignore
}

//-------------------------------------------------------------------------
/// @details
///		Stops counter collection and ensures final flush.
///		Delegates to parent first, then performs final sync.
//-------------------------------------------------------------------------
void Monitor::disableCounters() noexcept {
    Parent::disableCounters();
    refreshMonitorState(); // Final push of pending counts
}

//-------------------------------------------------------------------------
/// @details
///		Gracefully shuts down monitoring infrastructure:
///		- Signals termination to worker thread
///		- Joins and cleans up thread resources
///		- Resets internal flags
//-------------------------------------------------------------------------
void Monitor::terminateMonitoring() noexcept {
    if (!m_started) return;

    // Signal shutdown to worker
    m_started = false;

    if (m_updateThread) {
        m_updateThread->cancel();
        m_updateThread->join();
        m_updateThread.reset();
    }

    // Ensure consistent final state
    m_started = false;

    // Optional: log completion summary (commented out)
    // LOGT("Completed {} in {}", this, m_status.elapsed());
    // LOGT("Total count: {}, size: {}",
    //      MONITOR(completed).count,
    //      MONITOR(completed).size);
    // LOGTT(Perf, "Scan completed in {}", time::now() - start);
}

