#include <iostream>
#include <vector>
#include <string>
#include <numeric>
#include <algorithm>

struct Client {
    int client_id;
    std::string full_name;
    int years_old;
    std::vector<int> transaction_amounts;
    int join_year;
    std::string account_status;
};

struct SummaryClient {
    std::string name;
    int expenditure;
    int years_as_member;
    std::string category;
};

struct AnalysisOutput {
    std::vector<SummaryClient> summary_clients;
    int overall_sales;
    int number_of_clients;
    double mean_purchase;
};

AnalysisOutput analyze_client_data(const std::vector<Client>& clients) {
    std::vector<Client> active_clients;
    for (const auto& client : clients) {
        if (client.account_status == "active" && client.years_old >= 25) {
            active_clients.push_back(client);
        }
    }

    std::vector<SummaryClient> client_summaries;
    for (const auto& client : active_clients) {
        SummaryClient sc;
        sc.name = client.full_name;

        int spent = 0;
        for (int amount : client.transaction_amounts) {
            spent += amount;
        }
        sc.expenditure = spent;

        sc.years_as_member = 2026 - client.join_year;

        if (sc.expenditure < 500) {
            sc.category = "Bronze";
        } else if (sc.expenditure < 1000) {
            sc.category = "Silver";
        } else {
            sc.category = "Gold";
        }

        client_summaries.push_back(sc);
    }

    int total_sales = 0;
    for (const auto& summary : client_summaries) {
        total_sales += summary.expenditure;
    }

    AnalysisOutput output;
    output.summary_clients = client_summaries;
    output.overall_sales = total_sales;
    output.number_of_clients = static_cast<int>(client_summaries.size());

    if (output.number_of_clients > 0) {
        output.mean_purchase = static_cast<double>(total_sales) / output.number_of_clients;
    } else {
        output.mean_purchase = 0.0;
    }

    return output;
}

int main() {
    std::vector<Client> clients = {
        {1, "Alice", 30, {200, 400, 150}, 2019, "active"},
        {2, "Bob", 22, {100, 50}, 2021, "active"},
        {3, "Charlie", 28, {500, 600}, 2020, "inactive"},
        {4, "Diana", 35, {300, 200, 100}, 2018, "active"}
    };

    auto analysis = analyze_client_data(clients);

    std::cout << "Processed Clients:\n";
    for (const auto& client : analysis.summary_clients) {
        std::cout << client.name << ", total_spent: " << client.expenditure
                  << ", loyalty_years: " << client.years_as_member
                  << ", tier: " << client.category << "\n";
    }

    std::cout << "Total Revenue: " << analysis.overall_sales << "\n";
    std::cout << "User Count: " << analysis.number_of_clients << "\n";
    std::cout << "Average Spending: " << analysis.mean_purchase << "\n";

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <random>
#include <numeric>
#include <chrono>

using namespace std;

// Process each test case to identify two pens with ink
void processTestCase() {
    int n;
    if (!(cin >> n)) return;

    // Create initial list of pen IDs from 0 to n-1
    vector<int> candidates(n);
    iota(candidates.begin(), candidates.end(), 0);

    // Randomize the order using current time as seed
    unsigned seed = chrono::system_clock::now().time_since_epoch().count();
    shuffle(candidates.begin(), candidates.end(), default_random_engine(seed));

    // Store confirmed pens that have passed at least one test
    vector<int> verified;

    // Function to query a pen's ink status
    auto checkPen = [&](int id) -> int {
        cout << "0 " << id << endl;
        int result;
        cin >> result;
        return result;
    };

    // Continue until only 2 pens remain
    while (candidates.size() + verified.size() > 2) {
        if (candidates.empty()) {
            // Only verified pens remain - direct comparison needed
            int first = verified.back(); verified.pop_back();
            int second = verified.back(); verified.pop_back();

            if (checkPen(first) == 0) {
                // First pen has no ink, keep second
                verified.push_back(second);
            } else {
                // First pen has ink, test second
                if (checkPen(second) == 0) {
                    // Second pen has no ink, keep first
                    verified.push_back(first);
                } else {
                    // Both have ink, keep both
                    verified.push_back(first);
                    verified.push_back(second);
                }
            }
        } else {
            // Take a candidate for testing
            int challenger = candidates.back(); candidates.pop_back();

            if (verified.empty()) {
                // No verified pens yet, test two candidates against each other
                int opponent = candidates.back(); candidates.pop_back();

                if (checkPen(challenger) == 0) {
                    // Challenger failed, opponent remains unverified
                    candidates.push_back(opponent);
                } else {
                    // Challenger succeeded, test opponent
                    if (checkPen(opponent) == 0) {
                        // Opponent failed, promote challenger to verified
                        verified.push_back(challenger);
                    } else {
                        // Both succeeded, promote both
                        verified.push_back(challenger);
                        verified.push_back(opponent);
                    }
                }
            } else {
                // Use a verified pen as reference
                int reference = verified.back(); verified.pop_back();

                // Test challenger first (more likely to fail)
                if (checkPen(challenger) == 0) {
                    // Challenger failed, reference remains verified
                    verified.push_back(reference);
                } else {
                    // Challenger succeeded, test reference
                    if (checkPen(reference) == 0) {
                        // Reference failed, replace with challenger
                        verified.push_back(challenger);
                    } else {
                        // Both succeeded, keep both
                        verified.push_back(challenger);
                        verified.push_back(reference);
                    }
                }
            }
        }
    }

    // Collect remaining pens
    vector<int> finalPens;
    finalPens.insert(finalPens.end(), candidates.begin(), candidates.end());
    finalPens.insert(finalPens.end(), verified.begin(), verified.end());

    // Output the final answer
    cout << "1 " << finalPens[0] << " " << finalPens[1] << endl;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int testCases;
    if (cin >> testCases) {
        while (testCases--) {
            processTestCase();
        }
    }

    return 0;
}

