void DirectorySnapshotDiff::clear() {
	// Reset all container states by clearing each list
	FilesCreated.clear();
	FilesModified.clear();
	FilesMoved.clear();
	FilesDeleted.clear();
	DirsCreated.clear();
	DirsModified.clear();
	DirsMoved.clear();
	DirsDeleted.clear();
}

bool DirectorySnapshotDiff::hasChanges() const {
	// Check if any of the change lists contain elements
	return !(FilesCreated.empty() && FilesModified.empty() && FilesMoved.empty() &&
			 FilesDeleted.empty() && DirsCreated.empty() && DirsModified.empty() &&
			 DirsMoved.empty() && DirsDeleted.empty());
}

