#define SOL_ALL_SAFETIES_ON 1
#include <sol/sol.hpp>
#include <string>
#include <tuple>

int main(int, char*[]) {
    sol::state lua;
    lua.open_libraries(sol::lib::base);

    // Define a Lua-callable function that returns a tuple of its arguments
    lua["process_values"] = [](int x, int y, sol::object z) {
        return std::make_tuple(x, y, z);
    };

    // Test with integer third argument
    std::tuple<int, int, int> test_result1 = lua["process_values"](100, 200, 300);
    const std::tuple<int, int, int> expected1(100, 200, 300);
    SOL_ASSERT(test_result1 == expected1);

    // Test with string third argument
    std::tuple<int, int, std::string> test_result2 = lua["process_values"](100, 200, "BARK BARK BARK!");
    const std::tuple<int, int, std::string> expected2(100, 200, "BARK BARK BARK!");
    SOL_ASSERT(test_result2 == expected2);

    // Test using sol::tie for unpacking
    int val_a, val_b;
    std::string val_c;
    sol::tie(val_a, val_b, val_c) = lua["process_values"](100, 200, "bark");
    SOL_ASSERT(val_a == 100);
    SOL_ASSERT(val_b == 200);
    SOL_ASSERT(val_c == "bark");

    // Test from within Lua script
    lua.script(R"(
        x, y, z = process_values(150, 250, "woofbark")
        assert(x == 150)
        assert(y == 250)
        assert(z == "woofbark")
    )");

    return 0;
}

