////////////////////////////////////////////////////////////////////////////////
/// Test parsing a single attribute name without expansion
////////////////////////////////////////////////////////////////////////////////
TEST(AttributeNameParserTest, test_simpleString) {
  std::string src = "test";
  std::vector<AttributeName> parsed;
  ParseAttributeString(src, parsed, false);

  ASSERT_EQ(parsed.size(), 1U);
  EXPECT_EQ(parsed[0].name, src);
  EXPECT_FALSE(parsed[0].should_expand);
}

////////////////////////////////////////////////////////////////////////////////
/// Test parsing two-level nested attributes
////////////////////////////////////////////////////////////////////////////////
TEST(AttributeNameParserTest, test_subAttribute) {
  std::string src = "foo.bar";
  std::vector<AttributeName> parsed;
  ParseAttributeString(src, parsed, false);

  ASSERT_EQ(parsed.size(), 2U);
  EXPECT_EQ(parsed[0].name, "foo");
  EXPECT_FALSE(parsed[0].should_expand);
  EXPECT_EQ(parsed[1].name, "bar");
  EXPECT_FALSE(parsed[1].should_expand);
}

////////////////////////////////////////////////////////////////////////////////
/// Test parsing three-level nested attributes
////////////////////////////////////////////////////////////////////////////////
TEST(AttributeNameParserTest, test_subsubAttribute) {
  std::string src = "foo.bar.baz";
  std::vector<AttributeName> parsed;
  ParseAttributeString(src, parsed, false);

  ASSERT_EQ(parsed.size(), 3U);
  EXPECT_EQ(parsed[0].name, "foo");
  EXPECT_FALSE(parsed[0].should_expand);
  EXPECT_EQ(parsed[1].name, "bar");
  EXPECT_FALSE(parsed[1].should_expand);
  EXPECT_EQ(parsed[2].name, "baz");
  EXPECT_FALSE(parsed[2].should_expand);
}

////////////////////////////////////////////////////////////////////////////////
/// Test parsing an expandable attribute at top level
////////////////////////////////////////////////////////////////////////////////
TEST(AttributeNameParserTest, test_expandAttribute) {
  std::string src = "foo[*]";
  std::vector<AttributeName> parsed;
  ParseAttributeString(src, parsed, true);

  ASSERT_EQ(parsed.size(), 1U);
  EXPECT_EQ(parsed[0].name, "foo");
  EXPECT_TRUE(parsed[0].should_expand);
}

////////////////////////////////////////////////////////////////////////////////
/// Test parsing nested attribute with expansion on last component
////////////////////////////////////////////////////////////////////////////////
TEST(AttributeNameParserTest, test_expandSubAttribute) {
  std::string src = "foo.bar[*]";
  std::vector<AttributeName> parsed;
  ParseAttributeString(src, parsed, true);

  ASSERT_EQ(parsed.size(), 2U);
  EXPECT_EQ(parsed[0].name, "foo");
  EXPECT_FALSE(parsed[0].should_expand);
  EXPECT_EQ(parsed[1].name, "bar");
