#include <iostream>
#include <vector>
using namespace std;

int main() {
    int R, H;
    cin >> R >> H; // R=75, H=1 in the official test, but we read anyway.

    // Moduli for the tests. Their sum is 30.
    vector<int> moduli = {13, 7, 5, 3, 2};

    // Send all robots at once.
    for (int m : moduli) {
        for (int r = 0; r < m; ++r) {
            // Collect all positions p such that p % m == r.
            vector<int> positions;
            for (int p = 1; p <= 1000; ++p) {
                if (p % m == r) {
                    positions.push_back(p);
                }
            }

            // Output the query for this robot.
            cout << "? " << positions.size();
            for (int pos : positions) {
                cout << " " << pos;
            }
            cout << endl;
            cout.flush();
        }
    }

    // Wait for the results.
    cout << "@" << endl;
    cout.flush();

    int L;
    cin >> L;
    vector<int> responses(L);
    for (int i = 0; i < L; ++i) {
        cin >> responses[i];
    }

    // Decode: split responses according to the moduli.
    vector<vector<int>> positive_residues(moduli.size()); // residues with answer 1 for each modulus
    int response_index = 0;
    for (int i = 0; i < moduli.size(); ++i) {
        int m = moduli[i];
        for (int r = 0; r < m; ++r) {
            if (responses[response_index + r] == 1) {
                positive_residues[i].push_back(r);
            }
        }
        response_index += m;
    }

    // Precompute residues for numbers 1..1000 for each modulus.
    vector<vector<int>> residue_table(1001, vector<int>(moduli.size()));
    for (int num = 1; num <= 1000; ++num) {
        for (int mi = 0; mi < moduli.size(); ++mi) {
            residue_table[num][mi] = num % moduli[mi];
        }
    }

    // Brute-force search over all unordered pairs (x,y), x <= y.
    int first_num = -1, second_num = -1;
    for (int x = 1; x <= 1000; ++x) {
        for (int y = x; y <= 1000; ++y) {
            bool valid_pair = true;
            for (int mi = 0; mi < moduli.size(); ++mi) {
                int m = moduli[mi];
                int rx = residue_table[x][mi];
                int ry = residue_table[y][mi];

                // Verify coverage matches expected residues
                for (int r = 0; r < m; ++r) {
                    bool covered = (rx == r || ry == r);
                    bool should_cover = false;
                    for (int rr : positive_residues[mi]) {
                        if (rr == r) {
                            should_cover = true;
                            break;
                        }
                    }
                    if (covered != should_cover) {
                        valid_pair = false;
                        break;
                    }
                }
                if (!valid_pair) break;
            }
            if (valid_pair) {
                first_num = x;
                second_num = y;
                break;
            }
        }
        if (first_num != -1) break;
    }

    // Output the answer.
    cout << "! " << first_num << " " << second_num << endl;
    cout.flush();
    return 0;
}

#include "llvm/Transforms/IPO/EmbedBitcodePass.h"
#include "llvm/Bitcode/BitcodeWriter.h"
#include "llvm/Bitcode/BitcodeWriterPass.h"
#include "llvm/IR/PassManager.h"
#include "llvm/Pass.h"
#include "llvm/Support/ErrorHandling.h"
#include "llvm/Support/MemoryBufferRef.h"
#include "llvm/Support/raw_ostream.h"
#include "llvm/TargetParser/Triple.h"
#include "llvm/Transforms/IPO/ThinLTOBitcodeWriter.h"
#include "llvm/Transforms/Utils/ModuleUtils.h"
#include <memory>
#include <string>

using namespace llvm;

PreservedAnalyses EmbedBitcodePass::run(Module &M, ModuleAnalysisManager &AM) {
  // Check if bitcode has already been embedded
  if (M.getGlobalVariable("llvm.embedded.module", /*AllowInternal=*/true))
    report_fatal_error("Bitcode embedding can only be performed once",
                       /*gen_crash_diag=*/false);

  Triple targetTriple(M.getTargetTriple());

  // Verify the target object format is ELF
  if (targetTriple.getObjectFormat() != Triple::ELF)
    report_fatal_error(
        "This bitcode embedding functionality is currently limited to ELF format",
        /*gen_crash_diag=*/false);

  std::string bufferData;
  raw_string_ostream outputStream(bufferData);

  // Write appropriate bitcode based on LTO mode
  if (IsThinLTO) {
    ThinLTOBitcodeWriterPass(outputStream, /*ThinLinkOS=*/nullptr).run(M, AM);
  } else {
    BitcodeWriterPass(outputStream, /*ShouldPreserveUseListOrder=*/false, EmitLTOSummary)
        .run(M, AM);
  }

  // Embed the generated bitcode into the module
  embedBufferInModule(M, MemoryBufferRef(bufferData, "ModuleData"), ".llvm.lto");

  return PreservedAnalyses::all();
}

