#include <math.h>
#include <assert.h>
#include "PeakFinder.h"
using namespace soundtouch;

// Helper macro to compute maximum of two values
#define MAX_VAL(x, y) (((x) > (y)) ? (x) : (y))

PeakFinder::PeakFinder()
{
    minPos = maxPos = 0;
}

// Locate the base level (ground) of a peak by moving from 'peakpos' in 'direction'
// until the signal starts rising again after a minimum
int PeakFinder::findGround(const float *data, int peakpos, int direction) const
{
    float referenceValue;
    int lowestIndex;
    int currentIndex;
    int ascentCounter;
    float slope;

    ascentCounter = 0;
    referenceValue = data[peakpos];
    lowestIndex = peakpos;
    currentIndex = peakpos;

    while ((currentIndex > minPos) && (currentIndex < maxPos))
    {
        int previousIndex;
        previousIndex = currentIndex;
        currentIndex += direction;

        slope = data[currentIndex] - data[previousIndex];

        if (slope <= 0.0f)
        {
            // Moving downward or flat: continue descent
            if (ascentCounter > 0)
            {
                ascentCounter--;
            }

            if (data[currentIndex] < referenceValue)
            {
                lowestIndex = currentIndex;
                referenceValue = data[currentIndex];
            }
        }
        else
        {
            // Moving upward: increment ascent counter
            ascentCounter++;
            if (ascentCounter >= 6) break;  // Sustained ascent indicates next peak region
        }
    }

    return lowestIndex;
}

// Determine where the waveform crosses a specified amplitude level,
// starting from 'peakpos' and proceeding in 'direction'
int PeakFinder::findCrossingLevel(const float *data, float threshold, int peakpos, int direction) const
{
    float currentPeak;
    int index;

    currentPeak = data[peakpos];
    assert(currentPeak >= threshold);

    index = peakpos;
    while ((index >= minPos) && (index < maxPos))
    {
        if (data[index + direction] < threshold) 
            return index;   // Level crossing detected

        index += direction;
    }

    return -1;  // No crossing found within bounds
}

// Compute weighted center of mass for data segment between firstPos and lastPos
double PeakFinder::calcMassCenter(const float *data, int firstPos, int lastPos) const
{
    int i;
    double weightedSum;
    double amplitudeSum;

    weightedSum = 0.0;
    amplitudeSum = 0.0;

    for (i = firstPos; i <= lastPos; ++i)
    {
        weightedSum += static_cast<double>(i) * static_cast<double>(data[i]);
        amplitudeSum += static_cast<double>(data[i]);
    }

    if (amplitudeSum < 1e-6) 
        return 0.0;

    return weightedSum / amplitudeSum;
}

// Estimate precise center of a peak using local mass distribution around it
double PeakFinder::getPeakCenter(const float *data, int peakIndex) const
{
    float peakMagnitude;           // Height of the peak
    int leftCross, rightCross;     // Indices where peak crosses cutting level
    float cutThreshold;            // Threshold value for level crossing
    float baselineMagnitude;       // Estimated ground level
    int baseLeft, baseRight;       // Bottom positions of the peak hump

    // Find base positions on both sides
    baseLeft = findGround(data, peakIndex, -1);
    baseRight = findGround(data, peakIndex, 1);

    baselineMagnitude = MAX_VAL(data[baseLeft], data[baseRight]);
    peakMagnitude = data[peakIndex];

    // Validate peak significance
    if (baselineMagnitude < 1e-6) 
        return 0.0;                    // Insufficient signal strength
    if ((peakMagnitude / baselineMagnitude) < 1.3) 
        return 0.0;                    // Peak too shallow relative to baseline

    // Define detection threshold at 70% of peak above baseline
    cutThreshold = 0.70f * peakMagnitude + 0.30f * baselineMagnitude;

    // Locate level crossings
    leftCross = findCrossingLevel(data, cutThreshold, peakIndex, -1);
    rightCross = findCrossingLevel(data, cutThreshold, peakIndex, 1);

    if ((leftCross < 0) || (rightCross < 0)) 
        return 0.0;   // Incomplete peak structure

    // Return center of mass within crossing bounds
    return calcMassCenter(data, leftCross, rightCross);
}

// Main method to detect most prominent peak position in given range
double PeakFinder::detectPeak(const float *data, int lowBound, int highBound) 
{
    int i;
    int candidateIndex;          // Index of current strongest peak
    double bestPosition, tempScore;

    minPos = lowBound;
    maxPos = highBound;

    // Identify global maximum
    candidateIndex = minPos;
    bestPosition = data[minPos];

    for (i = minPos + 1; i < maxPos; ++i)
    {
        if (data[i] > bestPosition)
        {
            bestPosition = data[i];
            candidateIndex = i;
        }
    }

    // Refine with mass-center calculation
    double refinedPosition = getPeakCenter(data, candidateIndex);
    bestPosition = refinedPosition;

    // Check for harmonic interference: possibly misidentified overtones
    for (i = 2; i < 10; ++i)
    {
        double alternateScore;
        int estimatedIndex;
        int roundedRefined, roundedAlt;

        estimatedIndex = static_cast<int>(refinedPosition / static_cast<double>(i) + 0.5);
        if (estimatedIndex < minPos) 
            break;

        alternateScore = getPeakCenter(data, estimatedIndex);

        roundedRefined = static_cast<int>(refinedPosition + 0.5);
        roundedAlt = static_cast<int>(alternateScore + 0.5);

        double comparisonFactor = 2.0 * (data[roundedAlt] - data[roundedRefined]) / 
                                  (data[roundedAlt] + data[roundedRefined]);

        if (fabs(comparisonFactor) < 0.1)
        {
            // Likely fundamental frequency instead of harmonic
            bestPosition = alternateScore;
        }
    }

    return bestPosition;
}

