// Base class for capture detection strategies
class CaptureStrategy {
public:
  virtual ~CaptureStrategy() = default;
  virtual bool shouldProcess(const Use *U) { return true; }
  virtual bool isSafeToSkip(Instruction *I) { return false; }
  virtual bool handleCapture(const Use *U) = 0;
  virtual void handleTooManyUses() = 0;
  virtual bool shouldContinue() const = 0;
};

// Simple capture detection strategy
class BasicCaptureStrategy : public CaptureStrategy {
public:
  explicit BasicCaptureStrategy(bool trackReturns)
      : returnsCapture(trackReturns), hasCaptured(false) {}

  bool handleCapture(const Use *U) override {
    if (isa<ReturnInst>(U->getUser()) && !returnsCapture)
      return false;
    LLVM_DEBUG(dbgs() << "Detected capture via: " << *U->getUser() << "\n");
    hasCaptured = true;
    return true;
  }

  void handleTooManyUses() override {
    LLVM_DEBUG(dbgs() << "Aborted due to excessive uses\n");
    hasCaptured = true;
  }

  bool shouldContinue() const override { return !hasCaptured; }

private:
  bool returnsCapture;
  bool hasCaptured;
};

// Time-based capture detection (before specific point)
class TemporalCaptureStrategy : public CaptureStrategy {
public:
  TemporalCaptureStrategy(const Instruction *target, const DominatorTree *domTree,
                          bool includeTarget, const LoopInfo *loops)
      : targetInstr(target), domTree(domTree), includeTarget(includeTarget),
        loopInfo(loops), hasCaptured(false) {}

  bool isSafeToSkip(Instruction *I) override {
    if (targetInstr == I && !includeTarget)
      return true;
    if (!domTree->isReachableFromEntry(I->getParent()))
      return true;
    return !isPotentiallyReachable(I, targetInstr, nullptr, domTree, loopInfo);
  }

  bool handleCapture(const Use *U) override {
    auto *inst = cast<Instruction>(U->getUser());
    if (isa<ReturnInst>(inst) && !shouldTrackReturns())
      return false;
    if (isSafeToSkip(inst))
      return false;
    hasCaptured = true;
    return true;
  }

  void handleTooManyUses() override { hasCaptured = true; }
  bool shouldContinue() const override { return !hasCaptured; }

private:
  bool shouldTrackReturns() const { return true; }

  const Instruction *targetInstr;
  const DominatorTree *domTree;
  bool includeTarget;
  const LoopInfo *loopInfo;
  bool hasCaptured;
};

// Earliest capture location tracking
class EarliestCaptureStrategy : public CaptureStrategy {
public:
  EarliestCaptureStrategy(Function &func, const DominatorTree &dt)
      : dt(dt), funcRef(func), earliest(nullptr), hasCaptured(false) {}

  bool handleCapture(const Use *U) override {
    auto *inst = cast<Instruction>(U->getUser());
    if (isa<ReturnInst>(inst) && !shouldTrackReturns())
      return false;

    if (!earliest)
      earliest = inst;
    else
      earliest = dt.findNearestCommonDominator(earliest, inst);

    hasCaptured = true;
    return false; // Continue exploring
  }

  void handleTooManyUses() override {
    hasCaptured = true;
    earliest = &*funcRef.getEntryBlock().begin();
  }

  bool shouldContinue() const override { return true; }

  Instruction *getEarliest() const { return earliest; }

private:
  bool shouldTrackReturns() const { return true; }

  const DominatorTree &dt;
  Function &funcRef;
  Instruction *earliest;
  bool hasCaptured;
};

// Main capture detection engine
bool llvm::PointerMayBeCaptured(const Value *V, bool trackReturns,
                                bool /*storeCaptures*/, unsigned maxUses) {
  assert(!isa<GlobalValue>(V) && "Global values cannot be captured locally");

  LLVM_DEBUG(dbgs() << "Analyzing capture for: " << *V << " = ");

  BasicCaptureStrategy strategy(trackReturns);
  PointerMayBeCaptured(V, &strategy, maxUses);

  if (strategy.hasCaptured) {
    ++TotalCapturedPointers;
  } else {
    ++TotalNonCapturedPointers;
    LLVM_DEBUG(dbgs() << "not captured\n");
  }

  return strategy.hasCaptured;
}

bool llvm::PointerMayBeCapturedBefore(const Value *V, bool trackReturns,
                                      bool /*storeCaptures*/, const Instruction *I,
                                      const DominatorTree *DT, bool includeI,
                                      unsigned maxUses, const LoopInfo *LI) {
  assert(!isa<GlobalValue>(V) && "Global values cannot be captured locally");

  if (!DT)
    return PointerMayBeCaptured(V, trackReturns, true, maxUses);

  TemporalCaptureStrategy strategy(I, DT, includeI, LI);
  PointerMayBeCaptured(V, &strategy, maxUses);

  if (strategy.hasCaptured) {
    ++CapturedBeforeCount;
  } else {
    ++NotCapturedBeforeCount;
  }

  return strategy.hasCaptured;
}

Instruction *llvm::FindEarliestCapture(const Value *V, Function &F,
                                       bool trackReturns, bool /*storeCaptures*/,
                                       const DominatorTree &DT, unsigned maxUses) {
  assert(!isa<GlobalValue>(V) && "Global values cannot be captured locally");

  EarliestCaptureStrategy strategy(F, DT);
  PointerMayBeCaptured(V, &strategy, maxUses);

  if (strategy.hasCaptured) {
    ++CapturedBeforeCount;
  } else {
    ++NotCapturedBeforeCount;
  }

  return strategy.getEarliest();
}

// Determine how a specific use affects pointer capture
UseCaptureKind llvm::DetermineUseCaptureKind(
    const Use &use,
    function_ref<bool(Value *, const DataLayout &)> isDereferenceableOrNull) {
  Instruction *user = dyn_cast<Instruction>(use.getUser());
  if (!user)
    return UseCaptureKind::MAY_CAPTURE;

  switch (user->getOpcode()) {
  case Instruction::Call:
  case Instruction::Invoke: {
    auto *call = cast<CallBase>(user);

    // Read-only, no-throw, void-returning calls don't capture
    if (call->onlyReadsMemory() && call->doesNotThrow() &&
        call->getType()->isVoidTy())
      return UseCaptureKind::NO_CAPTURE;

    // Intrinsics that pass through without capturing
    if (isIntrinsicReturningPointerAliasingArgumentWithoutCapturing(call, true))
      return UseCaptureKind::PASSTHROUGH;

    // Volatile memory operations may capture
    if (auto *mem = dyn_cast<MemIntrinsic>(call))
      if (mem->isVolatile())
        return UseCaptureKind::MAY_CAPTURE;

    // Callee operand doesn't capture
    if (call->isCallee(&use))
      return UseCaptureKind::NO_CAPTURE;

    // Non-nocapture parameters don't capture
    if (call->isDataOperand(&use) &&
        !call->doesNotCapture(call->getDataOperandNo(&use)))
      return UseCaptureKind::MAY_CAPTURE;

    return UseCaptureKind::NO_CAPTURE;
  }

  case Instruction::Load: {
    auto *load = cast<LoadInst>(user);
    return load->isVolatile() ? UseCaptureKind::MAY_CAPTURE : UseCaptureKind::NO_CAPTURE;
  }

  case Instruction::VAArg:
    return UseCaptureKind::NO_CAPTURE;

  case Instruction::Store: {
    auto *store = cast<StoreInst>(user);
    // Storing to the pointer or volatile store captures
    return (use.getOperandNo() == 0 || store->isVolatile()) 
           ? UseCaptureKind::MAY_CAPTURE 
           : UseCaptureKind::NO_CAPTURE;
  }

  case Instruction::AtomicRMW: {
    auto *armw = cast<AtomicRMWInst>(user);
    return (use.getOperandNo() == 1 || armw->isVolatile())
           ? UseCaptureKind::MAY_CAPTURE
           : UseCaptureKind::NO_CAPTURE;
  }

  case Instruction::AtomicCmpXchg: {
    auto *acxi = cast<AtomicCmpXchgInst>(user);
    return (use.getOperandNo() == 1 || use.getOperandNo() == 2 || acxi->isVolatile())
           ? UseCaptureKind::MAY_CAPTURE
           : UseCaptureKind::NO_CAPTURE;
  }

  case Instruction::GetElementPtr:
    return user->getType()->isVectorTy() 
           ? UseCaptureKind::MAY_CAPTURE 
           : UseCaptureKind::PASSTHROUGH;

  case Instruction::BitCast:
  case Instruction::PHI:
  case Instruction::Select:
  case Instruction::AddrSpaceCast:
    return UseCaptureKind::PASSTHROUGH;

  case Instruction::ICmp: {
    unsigned idx = use.getOperandNo();
    unsigned otherIdx = 1 - idx;

    if (auto *nullPtr = dyn_cast<ConstantPointerNull>(user->getOperand(otherIdx))) {
      if (nullPtr->getType()->getAddressSpace() == 0) {
        if (isNoAliasCall(use.get()->stripPointerCasts()))
          return UseCaptureKind::NO_CAPTURE;

        if (!user->getFunction()->nullPointerIsDefined()) {
          auto *obj = user->getOperand(idx)->stripPointerCastsSameRepresentation();
          const DataLayout &DL = user->getModule()->getDataLayout();
          if (isDereferenceableOrNull && isDereferenceableOrNull(obj, DL))
            return UseCaptureKind::NO_CAPTURE;
        }
      }
    }
    return UseCaptureKind::MAY_CAPTURE;
  }

  default:
    return UseCaptureKind::MAY_CAPTURE;
  }
}

// Core analysis engine using iterative worklist approach
void llvm::PointerMayBeCaptured(const Value *V, CaptureStrategy *strategy,
                                unsigned maxUses) {
  assert(V->getType()->isPointerTy() && "Only pointers can be captured");

  if (maxUses == 0)
    maxUses = getDefaultMaxUsesToExploreForCaptureTracking();

  SmallVector<const Use *, 20> worklist;
  DenseSet<const Use *> seen;

  // Add initial uses to worklist
  for (const Use &U : V->uses()) {
    if (seen.size() >= maxUses) {
      strategy->handleTooManyUses();
      return;
    }
    if (seen.insert(&U).second && strategy->shouldProcess(&U))
      worklist.push_back(&U);
  }

  // Process all uses in worklist
  while (!worklist.empty()) {
    const Use *current = worklist.pop_back_val();

    switch (DetermineUseCaptureKind(*current, 
        [&](Value *v, const DataLayout &dl) { 
          return strategy->isDereferenceableOrNull(v, dl); 
        })) {
    case UseCaptureKind::NO_CAPTURE:
      continue;
    case UseCaptureKind::MAY_CAPTURE:
      if (strategy->handleCapture(current))
        return;
      continue;
    case UseCaptureKind::PASSTHROUGH:
      // Recursively process uses of this instruction
      for (const Use &U : current->getUser()->uses()) {
        if (seen.size() >= maxUses) {
          strategy->handleTooManyUses();
          return;
        }
        if (seen.insert(&U).second && strategy->shouldProcess(&U))
          worklist.push_back(&U);
      }
      continue;
    }
  }
}

bool llvm::isNonEscapingLocalObject(
    const Value *V, SmallDenseMap<const Value *, bool, 8> *cache) {
  if (cache) {
    auto result = cache->insert({V, false});
    if (!result.second)
      return result.first->second;
  }

  if (isIdentifiedFunctionLocal(V)) {
    bool result = !PointerMayBeCaptured(V, false, true);
    if (cache)
      (*cache)[V] = result;
    return result;
  }

  return false;
}

#include "test_ffb_common.h"
#include "src/Config.h"
#include <fstream>
#include <string>

namespace FFBEngineTests {

TEST_CASE(test_slope_config_migration, "Regression") {
    std::cout << "Test: Slope Config Migration (Issue #104)" << std::endl;

    // 1. Generate a legacy configuration file with deprecated keys
    std::ofstream legacyFile("old_slope_config.ini");
    legacyFile << "[Presets]" << std::endl;
    legacyFile << "[Preset:LegacySample]" << std::endl;
    legacyFile << "slope_negative_threshold=-0.88" << std::endl; // Obsolete key name
    legacyFile << "slope_detection_enabled=1" << std::endl;
    legacyFile.close();

    // 2. Initialize engine and load the legacy config
    FFBEngine engine;
    engine.m_slope_min_threshold = -0.3f; // Reset to known default

    Config::m_config_path = "old_slope_config.ini";
    Config::LoadPresets(); // Trigger migration logic during loading
    Config::ApplyPreset(static_cast<int>(Config::presets.size()) - 1, engine);

    // 3. Validate that migration occurred correctly
    ASSERT_NEAR(engine.m_slope_min_threshold, -0.88f, 0.001f);
    ASSERT_NEAR(Config::presets.back().slope_min_threshold, -0.88f, 0.001f);

    // Cleanup temporary files
    std::remove("old_slope_config.ini");
}

TEST_CASE(test_slope_persistence_new_key, "Regression") {
    std::cout << "Test: Slope Persistence New Key (Issue #104)" << std::endl;

    FFBEngine engine;
    engine.m_slope_min_threshold = -0.55f;
    engine.m_slope_detection_enabled = true;

    // Save current state using updated key names
    Config::Save(engine, "new_slope_config.ini");

    // Manually inspect saved file for correct key usage
    std::ifstream configFile("new_slope_config.ini");
    std::string contentLine;
    bool hasNewKey = false;
    bool hasDeprecatedKey = false;

    while (std::getline(configFile, contentLine)) {
        if (contentLine.find("slope_min_threshold=-0.55") != std::string::npos) {
            hasNewKey = true;
        }
        if (contentLine.find("slope_negative_threshold=") != std::string::npos) {
            hasDeprecatedKey = true;
        }
    }
    configFile.close();

    // Verify only new key is present in output
    ASSERT_TRUE(hasNewKey);
    ASSERT_FALSE(hasDeprecatedKey);

    // Clean up test file
    std::remove("new_slope_config.ini");
}

