/* Autocorrelation-based LPC coefficient computation (Levinson-Durbin algorithm) */
/* Input : n samples of time-domain data
   Output: m LPC coefficients, residual energy */
float vorbis_lpc_from_data(float *data, float *lpci, int n, int m) {
    double *aut = (double*)alloca(sizeof(double) * (m + 1));
    double *lpc = (double*)alloca(sizeof(double) * m);
    double residual_error;
    int i, j;

    /* Compute autocorrelation values for lags 0 to m */
    for (j = 0; j <= m; ++j) {
        double acc = 0.0;
        for (i = j; i < n; ++i)
            acc += static_cast<double>(data[i]) * data[i - j];
        aut[j] = acc;
    }

    /* Initialize error with zero-lag autocorrelation */
    residual_error = aut[0];

    /* Levinson-Durbin recursion to compute LPC coefficients */
    for (i = 0; i < m; ++i) {
        double reflection = -aut[i + 1];

        if (residual_error == 0.0) {
            memset(lpci, 0, m * sizeof(*lpci));
            return 0.0f;
        }

        /* Apply Durbin's recursion formula */
        for (j = 0; j < i; ++j)
            reflection -= lpc[j] * aut[i - j];

        reflection /= residual_error;

        /* Update LPC coefficients using reflection coefficient */
        lpc[i] = reflection;

        /* Symmetric update of intermediate coefficients */
        for (j = 0; j < i / 2; ++j) {
            double temp = lpc[j];
            lpc[j] += reflection * lpc[i - 1 - j];
            lpc[i - 1 - j] += reflection * temp;
        }

        /* Handle middle coefficient for odd-length updates */
        if (i % 2 == 1)
            lpc[j] += lpc[j] * reflection;

        /* Update residual error */
        residual_error *= (1.0 - reflection * reflection);
    }

    /* Copy computed double-precision coefficients to output buffer */
    for (j = 0; j < m; ++j)
        lpci[j] = static_cast<float>(lpc[j]);

    return static_cast<float>(residual_error);
}

/* Apply LPC prediction filter to generate output samples */
void vorbis_lpc_predict(float *coeff, float *prime, int m, float *data, long n) {
    /* Parameters:
       coeff[0..m-1] : LPC prediction coefficients
       prime[0..m-1] : initial conditions (buffer size must be at least n+m-1)
       data[0..n-1]  : output signal samples */

    long i, j;
    float prediction;
    float *buffer = (float*)alloca(sizeof(float) * (m + n));

    /* Initialize buffer with either provided initial values or zeros */
    if (!prime) {
        for (i = 0; i < m; ++i)
            buffer[i] = 0.0f;
    } else {
        for (i = 0; i < m; ++i)
            buffer[i] = prime[i];
    }

    /* Generate remaining samples using LPC prediction */
    for (i = 0; i < n; ++i) {
        prediction = 0.0f;
        long data_index = i;
        long coeff_index = m;

        /* Compute predicted value as negative weighted sum of past samples */
        for (j = 0; j < m; ++j)
            prediction -= buffer[data_index++] * coeff[--coeff_index];

        /* Store new sample in buffer and write to output */
        data[i] = buffer[data_index] = prediction;
    }
}

