// Bit-field manipulation helper for GOFF record flags
class Flags {
  uint8_t Value;

  static constexpr uint8_t encodeBits(uint8_t StartBit, uint8_t Width,
                                      uint8_t Data, uint8_t Existing) {
    assert(StartBit < 8 && "Start bit must be in [0,7]");
    assert(StartBit + Width <= 8 && "Bit range exceeds byte boundary");

    const uint8_t Mask = ((1u << Width) - 1u) << (7u - StartBit - Width + 1u);
    const uint8_t ShiftedData = (Data << (7u - StartBit - Width + 1u)) & Mask;

    assert((ShiftedData & ~Mask) == 0 && "Data overflows allocated bits");

    return (Existing & ~Mask) | ShiftedData;
  }

public:
  constexpr Flags() : Value(0) {}

  constexpr Flags(uint8_t StartBit, uint8_t Width, uint8_t Data)
      : Value(encodeBits(StartBit, Width, Data, 0)) {}

  void update(uint8_t StartBit, uint8_t Width, uint8_t Data) {
    Value = encodeBits(StartBit, Width, Data, Value);
  }

  constexpr operator uint8_t() const { return Value; }
};

// Standard flag definitions for GOFF records
constexpr uint8_t RecordContinued = Flags(0, 1, 1);   // High-order bit set
constexpr uint8_t IsContinuation = Flags(1, 1, 1);    // Second bit set

// Stream class to handle physical record formatting and logical record boundaries
class GOFFOstream : public raw_ostream {
  raw_pwrite_stream &UnderlyingStream;
  size_t BytesRemainingInLogicalRecord;
#ifndef NDEBUG
  size_t PaddingSize = 0;
#endif
  uint32_t LogicalRecordCount;
  GOFF::RecordType ActiveRecordType;
  bool NewRecordStarted;
  char Buffer[GOFF::RecordContentLength];

  size_t bytesLeftInCurrentPhysicalRecord() const {
    size_t remainder = BytesRemainingInLogicalRecord % GOFF::RecordContentLength;
    return remainder ? remainder : GOFF::RecordContentLength;
  }

  static void emitRecordHeader(raw_ostream &OS, GOFF::RecordType Type,
                               size_t RemainingBytes, uint8_t Flags) {
    uint8_t TypeAndFlags = Flags | (static_cast<uint8_t>(Type) << 4);
    if (RemainingBytes > GOFF::RecordLength)
      TypeAndFlags |= RecordContinued;

    OS << static_cast<unsigned char>(GOFF::PTVPrefix)
       << static_cast<unsigned char>(TypeAndFlags)
       << static_cast<unsigned char>(0); // Version field
  }

  void padFinalRecord();
  void write_data(const char *Ptr, size_t Size) override;
  uint64_t get_pos() const override { return UnderlyingStream.tell(); }

public:
  explicit GOFFOstream(raw_pwrite_stream &OS)
      : UnderlyingStream(OS), BytesRemainingInLogicalRecord(0),
        LogicalRecordCount(0), NewRecordStarted(false) {
    SetBuffer(Buffer, sizeof(Buffer));
  }

  ~GOFFOstream() override { finalize(); }

  raw_pwrite_stream &getStream() { return UnderlyingStream; }

  void beginRecord(GOFF::RecordType Type, size_t ContentSize);
  void finalize() { padFinalRecord(); }
  uint32_t getLogicalRecordCount() const { return LogicalRecordCount; }

  template <typename T>
  void writeBigEndian(T value) {
    value = support::endian::byte_swap<T>(value, llvm::endianness::big);
    write(reinterpret_cast<const char *>(&value), sizeof(value));
  }
};

void GOFFOstream::beginRecord(GOFF::RecordType Type, size_t Size) {
  padFinalRecord();

  ActiveRecordType = Type;
  BytesRemainingInLogicalRecord = Size;

#ifdef NDEBUG
  size_t padding;
#else
  PaddingSize = 0;
#endif

  size_t mod = Size % GOFF::RecordContentLength;
  if (mod != 0) {
    padding = GOFF::RecordContentLength - mod;
    BytesRemainingInLogicalRecord += padding;
#ifndef NDEBUG
    PaddingSize = padding;
#endif
  }

  NewRecordStarted = true;
  ++LogicalRecordCount;
}

void GOFFOstream::padFinalRecord() {
  size_t bufferUsed = GetNumBytesInBuffer();
  assert(bufferUsed <= BytesRemainingInLogicalRecord &&
         "Buffer overflow detected");

  size_t remaining = BytesRemainingInLogicalRecord - bufferUsed;
  if (remaining > 0) {
    assert(remaining == PaddingSize && "Incorrect padding calculation");
    assert(remaining < GOFF::RecordLength && "Too much padding required");
    write_zeros(remaining);
  }

  flush();
  assert(BytesRemainingInLogicalRecord == 0 && "Incomplete record flush");
  assert(GetNumBytesInBuffer() == 0 && "Buffer not cleared after flush");
}

void GOFFOstream::write_data(const char *Ptr, size_t Size) {
  assert(Size <= BytesRemainingInLogicalRecord && "Write exceeds record size");
  assert(BytesRemainingInLogicalRecord > 0 && "No active record");

  if ((BytesRemainingInLogicalRecord % GOFF::RecordContentLength) == 0) {
    emitRecordHeader(UnderlyingStream, ActiveRecordType,
                     BytesRemainingInLogicalRecord,
                     NewRecordStarted ? 0 : IsContinuation);
    NewRecordStarted = false;
  }

  size_t index = 0;
  while (Size > 0) {
    size_t chunkSize = bytesLeftInCurrentPhysicalRecord();
    if (chunkSize > Size)
      chunkSize = Size;

    UnderlyingStream.write(Ptr + index, chunkSize);
    index += chunkSize;
    Size -= chunkSize;
    BytesRemainingInLogicalRecord -= chunkSize;

    if (Size > 0) {
      emitRecordHeader(UnderlyingStream, ActiveRecordType,
                       BytesRemainingInLogicalRecord);
    }
  }
}

