void GOFFObjectWriter::writeHeaderRecord() {
  Output.beginRecord(GOFF::RT_HDR, /*ContentSize=*/57);

  Output.write_zeros(1);       // Reserved
  Output.writeBigEndian<uint32_t>(0); // Target Hardware Environment
  Output.writeBigEndian<uint32_t>(0); // Target Operating System Environment
  Output.write_zeros(2);       // Reserved
  Output.writeBigEndian<uint16_t>(0); // CCSID
  Output.write_zeros(16);      // Character Set Name
  Output.write_zeros(16);      // Language Product ID
  Output.writeBigEndian<uint32_t>(1); // Architecture Level
  Output.writeBigEndian<uint16_t>(0); // Module Properties Length
  Output.write_zeros(6);       // Reserved
}

void GOFFObjectWriter::writeTerminationRecord() {
  uint8_t entryFlags = GOFF::END_EPR_None;
  uint8_t addressMode = 0;
  uint32_t esdid = 0;

  // TODO: Populate entry point information when available.

  Output.beginRecord(GOFF::RT_END, /*ContentSize=*/13);
  Output.writeBigEndian<uint8_t>(Flags(6, 2, entryFlags)); // Indicator flags
  Output.writeBigEndian<uint8_t>(addressMode);             // AMODE
  Output.write_zeros(3);                                   // Reserved
  Output.writeBigEndian<uint32_t>(0);                      // Record Count (zeroed per spec)
  Output.writeBigEndian<uint32_t>(esdid);                  // ESDID of entry point
  Output.finalize();
}

uint64_t GOFFObjectWriter::generateObject(MCAssembler &Asm,
                                          const MCAsmLayout &Layout) {
  uint64_t initialOffset = Output.get_pos();

  writeHeaderRecord();
  writeTerminationRecord();

  LLVM_DEBUG(dbgs() << "Wrote " << Output.getLogicalRecordCount()
                    << " logical records.\n");

  return Output.get_pos() - initialOffset;
}

std::unique_ptr<MCObjectWriter>
llvm::createGOFFObjectWriter(std::unique_ptr<MCGOFFObjectTargetWriter> MOTW,
                             raw_pwrite_stream &OS) {
  return std::make_unique<GOFFObjectWriter>(std::move(MOTW), OS);
}

