#include "xdelta3_wrapper.h"
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>

extern "C"
{
    int xd3_main_cmdline(int argc, char** argv);
    extern void (*xprintf_message_func)(const char* msg);
}

static std::string captured_output;

static void capture_message(const char* msg) {
    captured_output += msg;
}

std::string get_xd3_messages() {
    return captured_output;
}

int run_xd3_command(const std::vector<std::string>& args) {
    // Allocate space for argument pointers: one extra for nullptr terminator
    char** arg_list = new char*[args.size() + 2];

    // Set first argument as program name
    arg_list[0] = new char[8] {'x', 'd', 'e', 'l', 't', 'a', '3', '\0'};

    int index = 1;
    for (const auto& param : args) {
        size_t length = param.length() + 1;
        arg_list[index] = new char[length];

        // Copy characters manually instead of using std::copy
        for (size_t i = 0; i < param.length(); ++i) {
            arg_list[index][i] = param[i];
        }
        arg_list[index][length - 1] = '\0';
        ++index;
    }

    arg_list[index] = nullptr;

    // Redirect output and clear previous messages
    xprintf_message_func = &capture_message;
    captured_output.clear();

    // Execute the main command-line handler
    int result = xd3_main_cmdline(index, arg_list);

    // Restore original message handler
    xprintf_message_func = nullptr;

    // Clean up allocated memory
    for (int i = 0; i < index; ++i) {
        delete[] arg_list[i];
    }
    delete[] arg_list;

    return result;
}

#include <iostream>
#include <vector>
#include <bitset>
#include <random>
using namespace std;

// Fixed problem size
const int PROBLEM_SIZE = 1000;

// Gaussian elimination structures
bitset<PROBLEM_SIZE> gaussian_basis[PROBLEM_SIZE];
int equation_results[PROBLEM_SIZE];
bool pivot_exists[PROBLEM_SIZE];
int solution_bits[PROBLEM_SIZE];

void process_problem() {
    int input_size;
    if (!(cin >> input_size)) return;

    // Reset pivot tracking
    for (int i = 0; i < PROBLEM_SIZE; ++i) {
        pivot_exists[i] = false;
    }

    // Initialize random number generator with fixed seed
    mt19937 rng(5489);
    int equations_collected = 0;

    // Collect enough independent equations to solve the system
    while (equations_collected < PROBLEM_SIZE) {
        // Random modulus in range [40, 51]
        int modulus = 40 + (rng() % 12);

        // Generate random mask of length 'modulus'
        vector<int> mask(modulus);
        for (int i = 0; i < modulus; ++i) {
            mask[i] = rng() & 1;  // Equivalent to rng() % 2
        }

        // Build equation vector from mask
        bitset<PROBLEM_SIZE> eq_vector;
        for (int i = 0; i < PROBLEM_SIZE; ++i) {
            if (mask[i % modulus]) {
                eq_vector.set(i);
            }
        }

        // Check linear independence and find pivot
        bitset<PROBLEM_SIZE> temp_vec = eq_vector;
        int pivot_index = -1;

        for (int pos = 0; pos < PROBLEM_SIZE; ++pos) {
            if (temp_vec.test(pos)) {
                if (pivot_exists[pos]) {
                    temp_vec ^= gaussian_basis[pos];
                } else {
                    pivot_index = pos;
                    break;
                }
            }
        }

        // Process new independent equation
        if (pivot_index != -1) {
            int num_states = 2 * modulus;

            // Send query request
            cout << "1" << endl;

            // Build state transition tables
            vector<int> state_trans_0(num_states), state_trans_1(num_states);
            for (int s = 0; s < num_states; ++s) {
                int position = s % modulus;
                int parity = s / modulus;
                int next_pos = (position + 1) % modulus;

                // Transition on input '0' (parity unchanged)
                state_trans_0[s] = next_pos + parity * modulus;

                // Transition on input '1' (parity flips if mask[position] == 1)
                int next_parity = parity ^ mask[position];
                state_trans_1[s] = next_pos + next_parity * modulus;
            }

            // Output transition tables
            cout << num_states;
            for (int x : state_trans_0) cout << " " << x;
            for (int x : state_trans_1) cout << " " << x;
            cout << endl;

            // Read final state result
            int final_state;
            cin >> final_state;

            // Determine parity from final state
            int observed_parity = (final_state >= modulus) ? 1 : 0;

            // Update basis with new equation
            int current_result = observed_parity;
            temp_vec = eq_vector;
            for (int idx = 0; idx < PROBLEM_SIZE; ++idx) {
                if (temp_vec.test(idx)) {
                    if (pivot_exists[idx]) {
                        temp_vec ^= gaussian_basis[idx];
                        current_result ^= equation_results[idx];
                    } else {
                        // Store new basis vector and RHS value
                        gaussian_basis[idx] = temp_vec;
                        equation_results[idx] = current_result;
                        pivot_exists[idx] = true;
                        equations_collected++;
                        break;
                    }
                }
            }
        }
    }

    // Back-substitution to determine solution bits
    for (int i = PROBLEM_SIZE - 1; i >= 0; --i) {
        int val = equation_results[i];
        for (int j = i + 1; j < PROBLEM_SIZE; ++j) {
            if (gaussian_basis[i].test(j)) {
                val ^= solution_bits[j];
            }
        }
        solution_bits[i] = val;
    }

    // Output final guess
    cout << "0" << endl;
    for (int i = 0; i < PROBLEM_SIZE; ++i) {
        cout << solution_bits[i];
    }
    cout << endl;
}

int main() {
    process_problem();
    return 0;
}

