// Function to compute the sum of two integers
int computeSum(int X, int Y) { 
    return X + Y; 
}

// Function to compute the difference of two integers
int computeDiff(int X, int Y) { 
    return X - Y; 
}

int main(int argc, char **argv) {
    int first = 42;
    int second = first++;  // second gets original value of first (42), then first becomes 43
    int result;

    if (argc > 0) {
        // Use addition function when command-line arguments are present
        int (*operation)(int, int) = &computeSum;
        result = operation(first, second);
    } else {
        // Use subtraction function otherwise
        int (*operation)(int, int) = &computeDiff;
        result = operation(first, second);
    }

    return result;
}

