#include "binder/bound_statement_visitor.h"
#include "binder/bound_explain.h"
#include "binder/copy/bound_copy_from.h"
#include "binder/copy/bound_copy_to.h"
#include "binder/query/bound_regular_query.h"
#include "common/cast.h"

using namespace lbug::common;

namespace lbug {
namespace binder {

void BoundStatementVisitor::visit(const BoundStatement& stmt) {
    switch (stmt.getStatementType()) {
    case StatementType::QUERY: {
        visitRegularQuery(stmt);
    } break;
    case StatementType::CREATE_SEQUENCE: {
        visitCreateSequence(stmt);
    } break;
    case StatementType::DROP: {
        visitDrop(stmt);
    } break;
    case StatementType::CREATE_TABLE: {
        visitCreateTable(stmt);
    } break;
    case StatementType::CREATE_TYPE: {
        visitCreateType(stmt);
    } break;
    case StatementType::ALTER: {
        visitAlter(stmt);
    } break;
    case StatementType::COPY_FROM: {
        visitCopyFrom(stmt);
    } break;
    case StatementType::COPY_TO: {
        visitCopyTo(stmt);
    } break;
    case StatementType::STANDALONE_CALL: {
        visitStandaloneCall(stmt);
    } break;
    case StatementType::EXPLAIN: {
        visitExplain(stmt);
    } break;
    case StatementType::CREATE_MACRO: {
        visitCreateMacro(stmt);
    } break;
    case StatementType::TRANSACTION: {
        visitTransaction(stmt);
    } break;
    case StatementType::EXTENSION: {
        visitExtension(stmt);
    } break;
    case StatementType::EXPORT_DATABASE: {
        visitExportDatabase(stmt);
    } break;
    case StatementType::IMPORT_DATABASE: {
        visitImportDatabase(stmt);
    } break;
    case StatementType::ATTACH_DATABASE: {
        visitAttachDatabase(stmt);
    } break;
    case StatementType::DETACH_DATABASE: {
        visitDetachDatabase(stmt);
    } break;
    case StatementType::USE_DATABASE: {
        visitUseDatabase(stmt);
    } break;
    case StatementType::CREATE_GRAPH: {
        visitCreateGraph(stmt);
    } break;
    case StatementType::USE_GRAPH: {
        visitUseGraph(stmt);
    } break;
    case StatementType::STANDALONE_CALL_FUNCTION: {
        visitStandaloneCallFunction(stmt);
    } break;
    case StatementType::EXTENSION_CLAUSE: {
        visitExtensionClause(stmt);
    } break;
    default:
        UNREACHABLE_CODE;
    }
}

void BoundStatementVisitor::visitUnsafe(BoundStatement& stmt) {
    switch (stmt.getStatementType()) {
    case StatementType::QUERY: {
        visitRegularQueryUnsafe(stmt);
    } break;
    default:
        break;
    }
}

void BoundStatementVisitor::visitCopyFrom(const BoundStatement& stmt) {
    auto& copyFromStmt = dynamic_cast_checked<const BoundCopyFrom&>(stmt);
    if (copyFromStmt.getInfo()->source->type == ScanSourceType::QUERY) {
        auto* querySrc = dynamic_cast_checked<BoundQueryScanSource*>(copyFromStmt.getInfo()->source.get());
        visit(*querySrc->statement);
    }
}

void BoundStatementVisitor::visitCopyTo(const BoundStatement& stmt) {
    auto& copyToStmt = dynamic_cast_checked<const BoundCopyTo&>(stmt);
    visitRegularQuery(*copyToStmt.getRegularQuery());
}

void BoundStatementVisitor::visitRegularQuery(const BoundStatement& stmt) {
    auto& regQuery = dynamic_cast_checked<const BoundRegularQuery&>(stmt);
    uint32_t idx = 0u;
    uint32_t count = regQuery.getNumSingleQueries();
    while (idx < count) {
        visitSingleQuery(*regQuery.getSingleQuery(idx));
        ++idx;
    }
}

void BoundStatementVisitor::visitRegularQueryUnsafe(BoundStatement& stmt) {
    auto& regQuery = stmt.cast<BoundRegularQuery>();
    uint32_t idx = 0u;
    uint32_t count = regQuery.getNumSingleQueries();
    while (idx < count) {
        visitSingleQueryUnsafe(*regQuery.getSingleQueryUnsafe(idx));
        ++idx;
    }
}

void BoundStatementVisitor::visitSingleQuery(const NormalizedSingleQuery& singleQ) {
    uint32_t partIdx = 0u;
    uint32_t numParts = singleQ.getNumQueryParts();
    while (partIdx < numParts) {
        visitQueryPart(*singleQ.getQueryPart(partIdx));
        ++partIdx;
    }
}

void BoundStatementVisitor::visitSingleQueryUnsafe(NormalizedSingleQuery& singleQ) {
    uint32_t partIdx = 0u;
    uint32_t numParts = singleQ.getNumQueryParts();
    while (partIdx < numParts) {
        visitQueryPartUnsafe(*singleQ.getQueryPartUnsafe(partIdx));
        ++partIdx;
    }
}

void BoundStatementVisitor::visitQueryPart(const NormalizedQueryPart& qPart) {
    uint32_t readIdx = 0u;
    uint32_t numReads = qPart.getNumReadingClause();
    while (readIdx < numReads) {
        visitReadingClause(*qPart.getReadingClause(readIdx));
        ++readIdx;
    }

    uint32_t updIdx = 0u;
    uint32_t numUpdates = qPart.getNumUpdatingClause();
    while (updIdx < numUpdates) {
        visitUpdatingClause(*qPart.getUpdatingClause(updIdx));
        ++updIdx;
    }

    if (qPart.hasProjectionBody()) {
        visitProjectionBody(*qPart.getProjectionBody());
        if (qPart.hasProjectionBodyPredicate()) {
            visitProjectionBodyPredicate(qPart.getProjectionBodyPredicate());
        }
    }
}

void BoundStatementVisitor::visitQueryPartUnsafe(NormalizedQueryPart& qPart) {
    uint32_t readIdx = 0u;
    uint32_t numReads = qPart.getNumReadingClause();
    while (readIdx < numReads) {
        visitReadingClauseUnsafe(*qPart.getReadingClause(readIdx));
        ++readIdx;
    }

    uint32_t updIdx = 0u;
    uint32_t numUpdates = qPart.getNumUpdatingClause();
    while (updIdx < numUpdates) {
        visitUpdatingClause(*qPart.getUpdatingClause(updIdx));
        ++updIdx;
    }

    if (qPart.hasProjectionBody()) {
        visitProjectionBody(*qPart.getProjectionBody());
        if (qPart.hasProjectionBodyPredicate()) {
            visitProjectionBodyPredicate(qPart.getProjectionBodyPredicate());
        }
    }
}

void BoundStatementVisitor::visitExplain(const BoundStatement& stmt) {
    const BoundExplain& explainStmt = stmt.constCast<BoundExplain>();
    visit(*explainStmt.getStatementToExplain());
}

void BoundStatementVisitor::visitReadingClause(const BoundReadingClause& rClause) {
    switch (rClause.getClauseType()) {
    case ClauseType::MATCH: {
        visitMatch(rClause);
    } break;
    case ClauseType::UNWIND: {
        visitUnwind(rClause);
    } break;
    case ClauseType::TABLE_FUNCTION_CALL: {
        visitTableFunctionCall(rClause);
    } break;
    case ClauseType::LOAD_FROM: {
        visitLoadFrom(rClause);
    } break;
    default:
        UNREACHABLE_CODE;
    }
}

void BoundStatementVisitor::visitReadingClauseUnsafe(BoundReadingClause& rClause) {
    switch (rClause.getClauseType()) {
    case ClauseType::MATCH: {
        visitMatchUnsafe(rClause);
    } break;
    case ClauseType::UNWIND: {
        visitUnwind(rClause);
    } break;
    case ClauseType::TABLE_FUNCTION_CALL: {
        visitTableFunctionCall(rClause);
    } break;
    case ClauseType::LOAD_FROM: {
        visitLoadFrom(rClause);
    } break;
    default:
        UNREACHABLE_CODE;
    }
}

void BoundStatementVisitor::visitUpdatingClause(const BoundUpdatingClause& uClause) {
    switch (uClause.getClauseType()) {
    case ClauseType::SET: {
        visitSet(uClause);
    } break;
    case ClauseType::DELETE_: {
        visitDelete(uClause);
    } break;
    case ClauseType::INSERT: {
        visitInsert(uClause);
    } break;
    case ClauseType::MERGE: {
        visitMerge(uClause);
    } break;
    default:
        UNREACHABLE_CODE;
    }
}

