} // namespace lbug

#include "llvm/Demangle/Demangle.h"
#include "llvm/Demangle/StringViewExtras.h"
#include "llvm/Demangle/Utility.h"
#include <cctype>
#include <cstring>
#include <limits>
#include <string_view>

using namespace llvm;
using llvm::itanium_demangle::OutputBuffer;
using llvm::itanium_demangle::starts_with;

namespace {

// Structure to hold demangling state and data
struct DLangDemangler {
  const std::string_view SourceString;
  int MostRecentReference;

  explicit DLangDemangler(std::string_view Input) 
    : SourceString(Input), MostRecentReference(Input.length()) {}

  // Main entry point for demangling
  const char* processMangledName(OutputBuffer *Output);

private:
  // Core parsing functions
  void processMangledSymbol(OutputBuffer *Output, std::string_view &Input);
  void processQualifiedName(OutputBuffer *Output, std::string_view &Input);
  void processIdentifier(OutputBuffer *Output, std::string_view &Input);
  void processLName(OutputBuffer *Output, std::string_view &Input, unsigned long Length);
  bool processType(std::string_view &Input);

  // Number and reference decoding
  void extractNumber(std::string_view &Input, unsigned long &Result);
  bool extractBackrefPosition(std::string_view &Input, long &Result);
  bool extractBackref(std::string_view &Input, std::string_view &Result);

  // Back reference handlers
  void processSymbolBackref(OutputBuffer *Output, std::string_view &Input);
  void processTypeBackref(std::string_view &Input);

  // Helper functions
  bool isValidSymbolStart(std::string_view Input);
};

} // anonymous namespace

void DLangDemangler::extractNumber(std::string_view &Input, unsigned long &Result) {
  if (Input.empty() || !std::isdigit(Input.front())) {
    Input = {};
    return;
  }

  unsigned long Value = 0;
  do {
    unsigned long Digit = Input[0] - '0';

    // Overflow check
    if (Value > (std::numeric_limits<unsigned int>::max() - Digit) / 10) {
      Input = {};
      return;
    }

    Value = Value * 10 + Digit;
    Input.remove_prefix(1);
  } while (!Input.empty() && std::isdigit(Input.front()));

  if (Input.empty()) {
    Input = {};
    return;
  }

  Result = Value;
}

bool DLangDemangler::extractBackrefPosition(std::string_view &Input, long &Result) {
  if (Input.empty()) {
    Input = {};
    return false;
  }

  unsigned long Value = 0;
  while (!Input.empty() && std::isalpha(Input.front())) {
    // Overflow protection
    if (Value > (std::numeric_limits<unsigned long>::max() - 25) / 26)
      break;

    Value *= 26;

    if (Input[0] >= 'a' && Input[0] <= 'z') {
      Value += Input[0] - 'a';
      if ((long)Value <= 0)
        break;
      Result = Value;
      Input.remove_prefix(1);
      return true;
    }

    Value += Input[0] - 'A';
    Input.remove_prefix(1);
  }

  Input = {};
  return false;
}

bool DLangDemangler::extractBackref(std::string_view &Input, std::string_view &Result) {
  if (Input.empty() || Input.front() != 'Q') {
    Result = {};
    return false;
  }

  const char *QPosition = Input.data();
  long RefPosition;

  Input.remove_prefix(1);
  if (!extractBackrefPosition(Input, RefPosition)) {
    Input = {};
    return false;
  }

  if (RefPosition > (QPosition - SourceString.data())) {
    Input = {};
    return false;
  }

  Result = std::string_view(QPosition - RefPosition, RefPosition);
  return true;
}

void DLangDemangler::processSymbolBackref(OutputBuffer *Output, std::string_view &Input) {
  unsigned long Length;
  std::string_view Backref;

  if (!extractBackref(Input, Backref)) {
    Input = {};
    return;
  }

  extractNumber(Backref, Length);
  if (Backref.empty() || Backref.length() < Length) {
    Input = {};
    return;
  }

  processLName(Output, Backref, Length);
  if (Backref.empty())
    Input = {};
}

void DLangDemangler::processTypeBackref(std::string_view &Input) {
  if (Input.data() - SourceString.data() >= MostRecentReference) {
    Input = {};
    return;
  }

  int SavedRefPos = MostRecentReference;
  MostRecentReference = Input.data() - SourceString.data();

  std::string_view Backref;
  if (!extractBackref(Input, Backref)) {
    Input = {};
    return;
  }

  if (Backref.empty()) {
    Input = {};
    return;
  }

  if (!processType(Backref))
    Input = {};

  MostRecentReference = SavedRefPos;
  if (Backref.empty())
    Input = {};
}

bool DLangDemangler::isValidSymbolStart(std::string_view Input) {
  if (Input.empty())
    return false;

  if (std::isdigit(Input.front()))
    return true;

  if (Input.front() != 'Q')
    return false;

  std::string_view Temp = Input.substr(1);
  long RefPos;
  if (!extractBackrefPosition(Temp, RefPos))
    return false;

  if (RefPos > (Input.data() - SourceString.data()))
    return false;

  return std::isdigit(Input.data()[-RefPos]);
}

void DLangDemangler::processMangledSymbol(OutputBuffer *Output, std::string_view &Input) {
  // Skip "_D" prefix
  Input.remove_prefix(2);

  processQualifiedName(Output, Input);
  if (Input.empty()) {
    Input = {};
    return;
  }

  // Handle artificial symbols ending with 'Z'
  if (Input.front() == 'Z') {
    Input.remove_prefix(1);
  } else if (!processType(Input)) {
    Input = {};
  }
}

void DLangDemangler::processQualifiedName(OutputBuffer *Output, std::string_view &Input) {
  bool FirstComponent = true;

  while (!Input.empty()) {
    // Skip anonymous symbols (leading zeros)
    if (!Input.empty() && Input.front() == '0') {
      while (!Input.empty() && Input.front() == '0')
        Input.remove_prefix(1);
      continue;
    }

    if (!FirstComponent)
      *Output << '.';
    FirstComponent = false;

    processIdentifier(Output, Input);

    // Check if there are more components
    if (Input.empty() || !isValidSymbolStart(Input))
      break;
  }
}

void DLangDemangler::processIdentifier(OutputBuffer *Output, std::string_view &Input) {
  if (Input.empty()) {
    Input = {};
    return;
  }

  if (Input.front() == 'Q') {
    processSymbolBackref(Output, Input);
    return;
  }

  unsigned long Length;
  extractNumber(Input, Length);
  if (Input.empty()) {
    Input = {};
    return;
  }

  if (!Length || Input.length() < Length) {
    Input = {};
    return;
  }

  // Handle fake parent symbols (__S...)
  if (Length >= 4 && starts_with(Input, "__S")) {
    size_t SuffixLen = Input.length() - Length;
    std::string_view Remaining = Input.substr(3);

    while (Remaining.length() > SuffixLen && std::isdigit(Remaining.front()))
      Remaining.remove_prefix(1);

    if (Remaining.length() == SuffixLen) {
      Input.remove_prefix(Length);
      processIdentifier(Output, Input);
      return;
    }
  }

  processLName(Output, Input, Length);
}

bool DLangDemangler::processType(std::string_view &Input) {
  if (Input.empty()) {
    Input = {};
    return false;
  }

  switch (Input.front()) {
    case 'i': // int type
      Input.remove_prefix(1);
      return true;

    case 'Q': // back referenced type
      processTypeBackref(Input);
      return true;

    default:
      Input = {};
      return false;
  }
}

void DLangDemangler::processLName(OutputBuffer *Output, std::string_view &Input, unsigned long Length) {
  switch (Length) {
    case 6:
      if (starts_with(Input, "__initZ")) {
        Output->prepend("initializer for ");
        Output->setCurrentPosition(Output->getCurrentPosition() - 1);
        Input.remove_prefix(Length);
        return;
      }
      if (starts_with(Input, "__vtblZ")) {
        Output->prepend("vtable for ");
        Output->setCurrentPosition(Output->getCurrentPosition() - 1);
        Input.remove_prefix(Length);
        return;
      }
      break;

    case 7:
      if (starts_with(Input, "__ClassZ")) {
        Output->prepend("ClassInfo for ");
        Output->setCurrentPosition(Output->getCurrentPosition() - 1);
        Input.remove_prefix(Length);
        return;
      }
      break;

    case 11:
      if (starts_with(Input, "__InterfaceZ")) {
        Output->prepend("Interface for ");
        Output->setCurrentPosition(Output->getCurrentPosition() - 1);
        Input.remove_prefix(Length);
        return;
      }
      break;

    case 12:
      if (starts_with(Input, "__ModuleInfoZ")) {
        Output->prepend("ModuleInfo for ");
        Output->setCurrentPosition(Output->getCurrentPosition() - 1);
        Input.remove_prefix(Length);
        return;
      }
      break;
  }

  *Output << Input.substr(0, Length);
  Input.remove_prefix(Length);
}

const char* DLangDemangler::processMangledName(OutputBuffer *Output) {
  std::string_view CurrentInput(SourceString);
  processMangledSymbol(Output, CurrentInput);
  return CurrentInput.data();
}

char *llvm::dlangDemangle(std::string_view MangledName) {
  // Validate input
  if (MangledName.empty() || !starts_with(MangledName, "_D"))
    return nullptr;

  OutputBuffer Demangled;

  // Special case for main function
  if (MangledName == "_Dmain") {
    Demangled << "D main";
  } else {
    DLangDemangler Parser(MangledName);
    const char *Remaining = Parser.processMangledName(&Demangled);

    // Verify complete demangling
    if (Remaining == nullptr || *Remaining != '\0') {
      std::free(Demangled.getBuffer());
      return nullptr;
    }
  }

  // Add null terminator
  if (Demangled.getCurrentPosition() > 0) {
    Demangled << '\0';
    Demangled.setCurrentPosition(Demangled.getCurrentPosition() - 1);
    return Demangled.getBuffer();
  }

  std::free(Demangled.getBuffer());
  return nullptr;
}

