// Helper to write config file content and load it
void WriteAndLoadConfig(FFBEngine& engine, const char* filename, const char* content) {
    std::ofstream ofs(filename);
    ofs << content;
    ofs.close();
    Config::Load(engine, filename);
}

TEST_CASE(test_config_legacy_migrations, "Config") {
    FFBEngine engine;

    // Migration 1: understeer > 2.0 → scaled down by 100
    {
        const char* fname = "tmp_legacy_understeer_v2.ini";
        WriteAndLoadConfig(engine, fname, "understeer=150.0\n");
        ASSERT_NEAR(engine.m_understeer_effect, 1.5, 0.001);
        std::remove(fname);
    }

    // Migration 2: max_torque_ref > 40.0 → wheelbase_max_nm = 60 - max_torque_ref, target_rim_nm = 30 - max_torque_ref/2
    {
        const char* fname = "tmp_legacy_torque_high_v2.ini";
        WriteAndLoadConfig(engine, fname, "max_torque_ref=50.0\n");
        ASSERT_NEAR(engine.m_wheelbase_max_nm, 15.0, 0.001);
        ASSERT_NEAR(engine.m_target_rim_nm, 10.0, 0.001);
        std::remove(fname);
    }

    // Migration 3: max_torque_ref <= 40.0 → both set to original value
    {
        const char* fname = "tmp_legacy_torque_low_v2.ini";
        WriteAndLoadConfig(engine, fname, "max_torque_ref=20.0\n");
        ASSERT_NEAR(engine.m_wheelbase_max_nm, 20.0, 0.001);
        ASSERT_NEAR(engine.m_target_rim_nm, 20.0, 0.001);
        std::remove(fname);
    }
}

