TEST_CASE(test_engine_calculate_force_fallbacks, "Physics") {
    FFBEngine engine;
    TelemInfoV01 telemetry = CreateBasicTestTelemetry();
    InitializeEngine(engine);

    // Simulate missing tire load over many frames
    telemetry.mWheel[0].mTireLoad = 0.0;
    telemetry.mWheel[1].mTireLoad = 0.0;
    telemetry.mLocalVel.z = 10.0;
    for (int i = 0; i < 25; ++i) {
        engine.calculate_force(&telemetry, "GT3", "911", 0.0f);
    }

    // Now drop speed to trigger fallback branch
    telemetry.mLocalVel.z = 0.0;
    engine.calculate_force(&telemetry, "GT3", "911", 0.0f);
    telemetry.mLocalVel.z = 10.0;

    // Trigger suspension force warning
    telemetry.mWheel[0].mSuspForce = 0.0;
    telemetry.mWheel[1].mSuspForce = 0.0;
    for (int i = 0; i < 55; ++i) {
        engine.calculate_force(&telemetry, "GT3", "911", 0.0f);
    }

    // Restore one sensor temporarily
    telemetry.mWheel[0].mSuspForce = 1000.0;
    engine.calculate_force(&telemetry, "GT3", "911", 0.0f);
    telemetry.mWheel[0].mSuspForce = 0.0;

    // Trigger suspension deflection warning
    telemetry.mWheel[0].mSuspensionDeflection = 0.0;
    telemetry.mWheel[1].mSuspensionDeflection = 0.0;
    for (int i = 0; i < 55; ++i) {
        engine.calculate_force(&telemetry, "GT3", "911", 0.0f);
    }

    // Restore one sensor again
    telemetry.mWheel[0].mSuspensionDeflection = 0.01;
    engine.calculate_force(&telemetry, "GT3", "911", 0.0f);
}

