TEST_CASE(test_engine_extra_branches, "Physics") {
    FFBEngine engine;
    TelemInfoV01 telemetry = CreateBasicTestTelemetry();
    InitializeEngine(engine);

    // Debug batch handling
    auto emptyBatch = engine.GetDebugBatch();
    ASSERT_TRUE(emptyBatch.empty());

    for (int i = 0; i < 110; ++i) {
        engine.calculate_force(&telemetry, "GT3", "911", 0.1f);
    }
    auto fullBatch = engine.GetDebugBatch();
    ASSERT_FALSE(fullBatch.empty());
    ASSERT_EQ(static_cast<int>(fullBatch.size()), 100);

    // Signal conditioning frequency crossing
    FFBCalculationContext context;
    context.dt = 0.0025;
    context.car_speed = 10.0;
    telemetry.mElapsedTime = 0.1;
    FFBEngineTestAccess::CallApplySignalConditioning(engine, 1.0, &telemetry, context);
    telemetry.mElapsedTime = 0.2;
    FFBEngineTestAccess::CallApplySignalConditioning(engine, -1.0, &telemetry, context);
    telemetry.mElapsedTime = 0.3;
    FFBEngineTestAccess::CallApplySignalConditioning(engine, 1.0, &telemetry, context);

    // Wheel radius edge case
    telemetry.mWheel[0].mStaticUndeflectedRadius = 5;
    FFBEngineTestAccess::CallApplySignalConditioning(engine, 1.0, &telemetry, context);

    // Speed gate validation (upper < lower)
    engine.m_speed_gate_lower = 10.0f;
    engine.m_speed_gate_upper = 5.0f;
    engine.calculate_force(&telemetry, "GT3", "911", 0.1f);

    // Logging path
    SessionInfo session;
    session.vehicle_name = "LogCar";
    AsyncLogger::Get().Start(session, "tmp_log_extra_v2");
    engine.calculate_force(&telemetry, "GT3", "911", 0.1f);
    AsyncLogger::Get().Stop();
    std::filesystem::remove_all("tmp_log_extra_v2");

    // Delta time zero branch
    telemetry.mDeltaTime = 0.0;
    engine.calculate_force(&telemetry, "GT3", "911", 0.1f);

    // Rear grip approximation fallback
    telemetry.mWheel[2].mTireLoad = 0.0;
    telemetry.mWheel[3].mTireLoad = 0.0;
    engine.calculate_force(&telemetry, "GT3", "911", 0.1f);
}

TEST_CASE(test_async_logger_api_boost, "Diagnostics") {
    SessionInfo session;
    session.vehicle_name = "BoostCar";
    session.track_name = "BoostTrack";
    const char* logPath = "tmp_boost_logs_v2/";

    // Start twice — second call should be no-op
    AsyncLogger::Get().Start(session, logPath);
    AsyncLogger::Get().Start(session, logPath);

    LogFrame frame;
    memset(&frame, 0, sizeof(frame));

    // Set marker and log once
    AsyncLogger::Get().SetMarker();
    AsyncLogger::Get().Log(frame);
    frame.marker = true;
    AsyncLogger::Get().Log(frame);

    // Decimation test
    frame.marker = false;
    for (int i = 0; i < 10; ++i) {
        AsyncLogger::Get().Log(frame);
    }

    // Buffer overflow simulation
    for (int i = 0; i < 850; ++i) {
        AsyncLogger::Get().Log(frame);
    }

    // Stop logger multiple times and try logging after stop
    AsyncLogger::Get().Stop();
    AsyncLogger::Get().Stop();
    AsyncLogger::Get().Log(frame);

    std::filesystem::remove_all("tmp_boost_logs_v2");
}

