// Pass implementation to rename functions annotated with RenameFuncAttr
struct FunctionRenamer : public impl::HACCRenameFunctionBase<FunctionRenamer> {
public:
  void runOnOperation() override;
};

void FunctionRenamer::runOnOperation() {
  auto module = getOperation();

  // Traverse all function operations in the module
  module.walk([&](func::FuncOp func) {
    // Check if the function carries the renaming annotation
    auto renameAnnotation = func->getAttrOfType<hacc::RenameFuncAttr>(
        hacc::RenameFuncAttr::name);

    if (!renameAnnotation)
      return; // Skip functions without the annotation

    // Extract the intended new name
    auto targetNameSymbol = renameAnnotation.getTargetName();
    if (targetNameSymbol.name.empty()) {
      func.emitError("target function name is empty");
      signalPassFailure();
      return;
    }

    // Ensure no symbol collision exists at the target name
    auto existingFunc = SymbolTable::lookupNearestSymbolFrom(
        func, targetNameSymbol);
    if (existingFunc) {
      func.emitError()
          << "cannot rename to @" << targetNameSymbol.getValue()
          << ": a function with that name already exists";
      signalPassFailure();
      return;
    }

    // Perform symbol replacement across the entire module
    auto oldSymAttr = func.getSymNameAttr();
    if (failed(SymbolTable::replaceAllSymbolUses(oldSymAttr,
                                                 targetNameSymbol.getAttr(),
                                                 module))) {
      func.emitError("failed to update all symbol references during rename");
      signalPassFailure();
      return;
    }

    // Finalize: update internal name and strip the annotation
    func.setSymName(targetNameSymbol.getAttr());
    func->removeAttr(hacc::RenameFuncAttr::name);
  });
}

// Factory function to instantiate the pass
std::unique_ptr<Pass> mlir::hacc::createRenameFuncPass() {
  return std::make_unique<FunctionRenamer>();
}

#include "NodeEdgeView.h"

namespace db {

// Returns the number of outgoing edges connected to this node
size_t NodeEdgeView::getOutEdgeCount() const {
    return _outCount;
}

// Returns the number of incoming edges connected to this node
size_t NodeEdgeView::getInEdgeCount() const {
    return _inCount;
}

// Appends a list of outgoing edge records and updates the total count
void NodeEdgeView::addOuts(std::span<const EdgeRecord> outs) {
    _outEdgeSpans.emplace_back(outs);
    _outCount += outs.size();
}

// Appends a list of incoming edge records and updates the total count
void NodeEdgeView::addIns(std::span<const EdgeRecord> ins) {
    _inEdgeSpans.emplace_back(ins);
    _inCount += ins.size();
}

}

