using namespace Valdi;

namespace ValdiTest {

TEST(AutoMalloc, UsesStackBufferWhenRequestedSizeFitsInlineCapacity) {
    AutoMalloc<uint32_t, 16> buffer(8);
    EXPECT_FALSE(buffer.allocated());
    EXPECT_NE(nullptr, buffer.data());

    for (size_t idx = 0; idx < 8; ++idx) {
        buffer.data()[idx] = 42;
    }

    for (size_t idx = 0; idx < 8; ++idx) {
        EXPECT_EQ(static_cast<uint32_t>(42), buffer.data()[idx]);
    }
}

TEST(AutoMalloc, AllocatesHeapMemoryWhenRequestExceedsInlineCapacity) {
    AutoMalloc<uint32_t, 16> buffer(32);
    EXPECT_TRUE(buffer.allocated());
    EXPECT_NE(nullptr, buffer.data());

    for (size_t idx = 0; idx < 32; ++idx) {
        buffer.data()[idx] = 42;
    }

    for (size_t idx = 0; idx < 32; ++idx) {
        EXPECT_EQ(static_cast<uint32_t>(42), buffer.data()[idx]);
    }
}

TEST(AutoMalloc, SupportsDynamicResizingWithProperMemoryManagement) {
    AutoMalloc<uint32_t, 16> buffer;
    EXPECT_FALSE(buffer.allocated());
    EXPECT_EQ(nullptr, buffer.data());

    buffer.resize(8);
    EXPECT_FALSE(buffer.allocated());
    EXPECT_NE(nullptr, buffer.data());

    auto* initialPtr = buffer.data();

    buffer.resize(32);
    EXPECT_TRUE(buffer.allocated());
    EXPECT_NE(nullptr, buffer.data());
    EXPECT_NE(initialPtr, buffer.data());

    initialPtr = buffer.data();

    buffer.resize(30);
    EXPECT_TRUE(buffer.allocated());
    EXPECT_EQ(initialPtr, buffer.data());

    buffer.resize(31);
    EXPECT_TRUE(buffer.allocated());
    EXPECT_EQ(initialPtr, buffer.data());
}

