// Renamed helper functions
void display_message() {
    std::cout << "some function!" << std::endl;
}

void alternate_action() {
    std::cout << "some other function!" << std::endl;
}

// Renamed struct with equivalent members
struct data_holder {
    int value = 30;

    double compute_result() {
        return 24.5;
    }
};

int main(int argc, char* argv[]) {
    (void)argc; // suppress unused parameter warning
    (void)argv;

    std::cout << "=== functions (all) ===" << std::endl;

    sol::state vm; // renamed 'lua' to 'vm'
    vm.open_libraries(sol::lib::base);

    // Insert instance of data_holder into Lua state
    vm.set("obj", data_holder{});

    // Bind plain functions under new names
    vm["func_a"] = display_message;
    vm.set_function("func_b", &alternate_action);

    // Bind member function only
    vm["method_x"] = &data_holder::compute_result;

    // Bind member function with pre-bound instance
    vm.set_function(
        "method_y", &data_holder::compute_result, data_holder{});

    // Bind member variable as getter/setter function
    vm["field_x"] = &data_holder::value;

    // Bind member variable with pre-bound instance
    vm.set_function(
        "field_y", &data_holder::value, data_holder{});

    // Execute embedded script (unchanged logic, just updated identifiers)
    vm.script(R"(
func_a() -- prints: some function!
func_b() -- prints: some other function!

-- requires passing instance for unbound methods
print(method_x(obj)) -- 24.5

-- no instance needed: already bound
print(method_y()) -- 24.5

-- requires instance for unbound fields
print(field_x(obj)) -- 30

-- no instance needed: already bound
print(field_y()) -- 30

-- can set via instance
field_x(obj, 212)

-- can set without instance (pre-bound)
field_y(254)

print(field_x(obj)) -- 212
print(field_y()) -- 254
)");

    std::cout << std::endl;
    return 0;
}

