// Convert ASCII hex digit to numeric value
unsigned char asciiDigitToHex(char digit) {
    if (digit >= 'a' && digit <= 'f') {
        return digit - 'a' + 10;
    } else if (digit >= 'A' && digit <= 'F') {
        return digit - 'A' + 10;
    } else {
        return digit - '0';
    }
}

// Parse 32-character hex string into 16-byte binary buffer
void parseHex16(const char *input, unsigned char *output) {
    const char *src = input;
    unsigned int val;
    int idx = 0;
    while (idx < 16) {
        val = asciiDigitToHex(src[1]) | (asciiDigitToHex(src[0]) << 4);
        *output++ = static_cast<unsigned char>(val);
        src += 2;
        ++idx;
    }
}

// Simple LCG-based PRNG with optional seed reset
long random(long l) {
    static long seed = 0xEB;
    if (l != 0)
        seed = l;
    seed = seed * 0x19660E + 0x3C6EF35F;
    return seed;
}

