// Generate 8 x 32-bit masher values using PRNG
void KeyChain::getMasher(unsigned char *uc) {
    unsigned int *masher_p = reinterpret_cast<unsigned int *>(uc);
    unsigned int test_val = 1;
    bool needs_swap = NEEDS_BYTESWAP(&test_val, 1);
    int counter = 0;
    while (counter < 8) {
        *masher_p = random((counter == 0) ? 0xEB : 0);
        if (needs_swap) {
            BYTESWAP_32BIT(masher_p);
        }
        ++masher_p;
        ++counter;
    }
}

// XOR two 32-byte buffers as 8 x 32-bit words
void mash(unsigned char *uc1, unsigned char *uc2) {
    unsigned int *ui1 = reinterpret_cast<unsigned int *>(uc1);
    unsigned int *ui2 = reinterpret_cast<unsigned int *>(uc2);
    for (int i = 0; i < 8; ++i) {
        ui1[i] ^= ui2[i];
    }
}

// Circular left rotation index modulo 32
int roll(int i) {
    i += 19;
    i %= 32;
    return i;
}

// Swap two characters
void swap(char &c1, char &c2) {
    char tmp = c1;
    c1 = c2;
    c2 = tmp;
}

// Shuffle operations on 32-byte character buffer
void shuffle1(char *c) {
    for (int i = 0; i < 8; ++i) {
        swap(c[roll(i * 4)], c[i * 4 + 2]);
        swap(c[roll(i * 4 + 3)], c[i * 4 + 1]);
    }
}

void shuffle2(char *c) {
    for (int i = 0; i < 8; ++i) {
        swap(c[(7 - i) * 4 + 1], c[i * 4 + 2]);
        swap(c[(7 - i) * 4], c[i * 4 + 3]);
    }
}

void shuffle3(char *c) {
    for (int i = 0; i < 8; ++i) {
        swap(c[roll((7 - i) * 4 + 1)], c[i * 4 + 2]);
        swap(c[(7 - i) * 4], c[i * 4 + 3]);
    }
}

void shuffle4(char *c) {
    for (int i = 0; i < 8; ++i) {
        swap(c[(7 - i) * 4 + 1], c[i * 4 + 2]);
        swap(c[roll((7 - i) * 4)], c[i * 4 + 3]);
    }
}

void shuffle5(char *c) {
    for (int i = 0; i < 8; ++i) {
        swap(c[(7 - i) * 4 + 1], c[roll(i * 4 + 2)]);
        swap(c[(7 - i) * 4], c[i * 4 + 3]);
    }
}

void shuffle6(char *c) {
    for (int i = 0; i < 8; ++i) {
        swap(c[(7 - i) * 4 + 1], c[i * 4 + 2]);
        swap(c[(7 - i) * 4], c[roll(i * 4 + 3)]);
    }
}

// Composite shuffle: apply all six shuffles sequentially
void supershuffle(char *c) {
    shuffle1(c);
    shuffle2(c);
    shuffle3(c);
    shuffle4(c);
    shuffle5(c);
    shuffle6(c);
}

// Opaque predicate: increments internal counter (used for anti-analysis)
void opaquePredicate() {
    static int callCount = 0;
    ++callCount;
}

// Safe copy with embedded opaque predicate calls
void memcpy_cs(unsigned char *dest, const unsigned char *src, unsigned int len) {
    int idx = 0;
    while (idx < static_cast<int>(len)) {
        opaquePredicate();
        dest[idx] = src[idx];
        ++idx;
    }
}

// Apply supershuffle then XOR with mask
void revealKey(long *lp, unsigned char *uc) {
    for (int i = 0; i < 14; ++i) {
        supershuffle(reinterpret_cast<char*>(lp));
    }
    mash(reinterpret_cast<unsigned char*>(lp), uc);
}

// Core key derivation: reveal + copy
void getKeyImpl(unsigned char *uc1, char *c, unsigned char *uc2) {
    revealKey(reinterpret_cast<long*>(uc1), uc2);
    memcpy_cs(reinterpret_cast<unsigned char*>(c), uc1, 32);
}

// Public API: derive key at index i
void KeyChain::getKey(unsigned int idx, unsigned char *out1, unsigned char *mask) {
    unsigned char tempBuffer[32];
    char charBuffer[32];
    memcpy_cs(tempBuffer, &hiddenKeys[idx * 32], 32);
    getKeyImpl(tempBuffer, charBuffer, mask);
    parseHex16(charBuffer, out1);
}

// Return number of available keys
unsigned int KeyChain::getNumKeys() { return 12; }

