struct LoopInvariantOptimizer {
  bool processLoop(Loop *L, AAResults *AA, LoopInfo *LI, DominatorTree *DT,
                   AssumptionCache *AC, TargetLibraryInfo *TLI,
                   TargetTransformInfo *TTI, ScalarEvolution *SE, MemorySSA *MSSA,
                   OptimizationRemarkEmitter *ORE, bool LoopNestMode = false);

  LoopInvariantOptimizer(unsigned LicmMssaOptCap,
                         unsigned LicmMssaNoAccForPromotionCap,
                         bool LicmAllowSpeculation)
      : MssaOptCap(LicmMssaOptCap),
        NoAccPromotionCap(LicmMssaNoAccForPromotionCap),
        AllowSpeculation(LicmAllowSpeculation) {}

private:
  unsigned MssaOptCap;
  unsigned NoAccPromotionCap;
  bool AllowSpeculation;
};

struct LegacyLICMPassImpl : public LoopPass {
  static char ID;

  LegacyLICMPassImpl(
      unsigned LicmMssaOptCap = SetLicmMssaOptCap,
      unsigned LicmMssaNoAccForPromotionCap = SetLicmMssaNoAccForPromotionCap,
      bool LicmAllowSpeculation = true)
      : LoopPass(ID), Optimizer(LicmMssaOptCap, LicmMssaNoAccForPromotionCap,
                                LicmAllowSpeculation) {
    initializeLegacyLICMPassImplPass(*PassRegistry::getPassRegistry());
  }

  bool runOnLoop(Loop *L, LPPassManager &LPM) override {
    if (skipLoop(L))
      return false;

    LLVM_DEBUG(dbgs() << "Running LICM on Loop with header block "
                      << L->getHeader()->getNameOrAsOperand() << "\n");

    Function *F = L->getHeader()->getParent();
    auto *SE = getAnalysisIfAvailable<ScalarEvolutionWrapperPass>();
    MemorySSA *MSSA = &getAnalysis<MemorySSAWrapperPass>().getMSSA();

    OptimizationRemarkEmitter ORE(F);

    return Optimizer.processLoop(
        L, &getAnalysis<AAResultsWrapperPass>().getAAResults(),
        &getAnalysis<LoopInfoWrapperPass>().getLoopInfo(),
        &getAnalysis<DominatorTreeWrapperPass>().getDomTree(),
        &getAnalysis<AssumptionCacheTracker>().getAssumptionCache(*F),
        &getAnalysis<TargetLibraryInfoWrapperPass>().getTLI(*F),
        &getAnalysis<TargetTransformInfoWrapperPass>().getTTI(*F),
        SE ? &SE->getSE() : nullptr, MSSA, &ORE);
  }

  void getAnalysisUsage(AnalysisUsage &AU) const override {
    AU.addPreserved<DominatorTreeWrapperPass>();
    AU.addPreserved<LoopInfoWrapperPass>();
    AU.addRequired<TargetLibraryInfoWrapperPass>();
    AU.addRequired<MemorySSAWrapperPass>();
    AU.addPreserved<MemorySSAWrapperPass>();
    AU.addRequired<TargetTransformInfoWrapperPass>();
    AU.addRequired<AssumptionCacheTracker>();
    getLoopAnalysisUsage(AU);
    LazyBlockFrequencyInfoPass::getLazyBFIAnalysisUsage(AU);
    AU.addPreserved<LazyBlockFrequencyInfoPass>();
    AU.addPreserved<LazyBranchProbabilityInfoPass>();
  }

private:
  LoopInvariantOptimizer Optimizer;
};
} // namespace

PreservedAnalyses LICMPass::run(Loop &L, LoopAnalysisManager &AM,
                                LoopStandardAnalysisResults &AR, LPMUpdater &) {
  if (!AR.MSSA)
    report_fatal_error("LICM requires MemorySSA (loop-mssa)",
                       /*GenCrashDiag*/false);

  OptimizationRemarkEmitter ORE(L.getHeader()->getParent());
  LoopInvariantOptimizer Optimizer(Opts.MssaOptCap, Opts.MssaNoAccForPromotionCap,
                                   Opts.AllowSpeculation);

  if (!Optimizer.processLoop(&L, &AR.AA, &AR.LI, &AR.DT, &AR.AC, &AR.TLI, &AR.TTI,
                             &AR.SE, AR.MSSA, &ORE))
    return PreservedAnalyses::all();

  auto PA = getLoopPassPreservedAnalyses();
  PA.preserve<MemorySSAAnalysis>();
  return PA;
}

