#include <iostream>
#include <vector>
#include <cmath>
#include <numeric>
#include <algorithm>

// Disjoint Set Union with union-by-size and path compression
struct DSU {
    std::vector<int> parent;
    std::vector<int> size;
    int num_components;

    DSU(int n) : parent(n), size(n, 1), num_components(n) {
        std::iota(parent.begin(), parent.end(), 0);
    }

    DSU(const DSU& other) = default;

    int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    void merge(int x, int y) {
        int root_x = find(x);
        int root_y = find(y);

        if (root_x == root_y) return;

        if (size[root_x] < size[root_y]) {
            std::swap(root_x, root_y);
        }

        parent[root_y] = root_x;
        size[root_x] += size[root_y];
        --num_components;
    }
};

struct Coordinate {
    int x_coord;
    int y_coord;
};

struct Connection {
    int node_a;
    int node_b;
    int approx_dist; // Rounded Euclidean distance
};

// Edge in the component graph
struct ComponentConnection {
    int comp_a;
    int comp_b;
    double weight;

    bool operator<(const ComponentConnection& other) const {
        return weight < other.weight;
    }
};

double compute_distance(const Coordinate& p1, const Coordinate& p2) {
    long long diff_x = p1.x_coord - p2.x_coord;
    long long diff_y = p1.y_coord - p2.y_coord;
    return std::sqrt(static_cast<double>(diff_x * diff_x + diff_y * diff_y));
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    const int TOTAL_POINTS = 400;
    const int TOTAL_CONNECTIONS = 1995;

    std::vector<Coordinate> points(TOTAL_POINTS);
    for (int idx = 0; idx < TOTAL_POINTS; ++idx) {
        std::cin >> points[idx].x_coord >> points[idx].y_coord;
    }

    std::vector<Connection> connections(TOTAL_CONNECTIONS);
    for (int idx = 0; idx < TOTAL_CONNECTIONS; ++idx) {
        std::cin >> connections[idx].node_a >> connections[idx].node_b;
        connections[idx].approx_dist = static_cast<int>(
            std::round(compute_distance(points[connections[idx].node_a], 
                                       points[connections[idx].node_b]))
        );
    }

    DSU dsu(TOTAL_POINTS);

    for (int step = 0; step < TOTAL_CONNECTIONS; ++step) {
        int threshold;
        std::cin >> threshold;

        int a = connections[step].node_a;
        int b = connections[step].node_b;
        int root_a = dsu.find(a);
        int root_b = dsu.find(b);

        if (root_a == root_b) {
            std::cout << "0\n";
            continue;
        }

        // Compute dynamic scaling factor based on progress
        double progress_ratio = static_cast<double>(step) / (TOTAL_CONNECTIONS - 1);
        double scale_factor = 1.4 + 1.6 * progress_ratio * progress_ratio;

        std::vector<ComponentConnection> candidate_edges;
        if (step < TOTAL_CONNECTIONS - 1) {
            candidate_edges.reserve(TOTAL_CONNECTIONS - step - 1);
        }

        for (int next_idx = step + 1; next_idx < TOTAL_CONNECTIONS; ++next_idx) {
            int ra = dsu.find(connections[next_idx].node_a);
            int rb = dsu.find(connections[next_idx].node_b);

            if (ra != rb) {
                candidate_edges.push_back({
                    ra, rb, 
                    scale_factor * connections[next_idx].approx_dist
                });
            }
        }

        std::sort(candidate_edges.begin(), candidate_edges.end());

        double min_path_weight = 1e30; // Very large number

        if (!candidate_edges.empty()) {
            DSU temp_dsu = dsu;
            for (const auto& edge : candidate_edges) {
                if (temp_dsu.find(edge.comp_a) != temp_dsu.find(edge.comp_b)) {
                    temp_dsu.merge(edge.comp_a, edge.comp_b);

                    if (temp_dsu.find(root_a) == temp_dsu.find(root_b)) {
                        min_path_weight = edge.weight;
                        break;
                    }
                }
            }
        }

        if (static_cast<double>(threshold) < min_path_weight) {
            std::cout << "1\n";
            dsu.merge(a, b);
        } else {
            std::cout << "0\n";
        }
    }

    return 0;
}

