namespace {
constexpr int test_port = 19021;

// Helper function to send data with null terminator
bool send_message(const std::shared_ptr<dap::Writer>& writer, const std::string& message) {
    return writer->write(message.c_str(), message.length()) && writer->write("\0", 1);
}

// Helper function to receive data until null terminator
std::string receive_message(const std::shared_ptr<dap::Reader>& reader) {
    char buffer;
    std::string result;

    while (reader->read(&buffer, 1) > 0) {
        if (buffer == '\0') {
            break;
        }
        result.push_back(buffer);
    }

    return reader->isOpen() ? result : "<stream closed>";
}
}  // anonymous namespace

TEST(Network, ClientServerCommunication) {
    dap::Chan<bool> completion_flag;
    auto server_instance = dap::net::Server::create();

    if (!server_instance->start(
            test_port,
            [&](const std::shared_ptr<dap::ReaderWriter>& rw) {
                ASSERT_EQ(receive_message(rw), "client to server");
                ASSERT_TRUE(send_message(rw, "server to client"));
                completion_flag.put(true);
            },
            [&](const char* error_message) { 
                FAIL() << "Server encountered error: " << error_message; 
            })) {
        FAIL() << "Failed to initialize server";
        return;
    }

    // Execute multiple client connections
    int connection_count = 0;
    while (connection_count < 5) {
        auto client_connection = dap::net::connect("localhost", test_port);
        ASSERT_NE(client_connection, nullptr) 
            << "Client connection attempt " << connection_count << " failed";

        ASSERT_TRUE(send_message(client_connection, "client to server"));
        ASSERT_EQ(receive_message(client_connection), "server to client");

        completion_flag.take();
        connection_count++;
        std::this_thread::sleep_for(std::chrono::seconds(1));
    }

    server_instance.reset();
}

TEST(Network, ServerStopRestartFunctionality) {
    dap::Chan<bool> sync_channel;
    auto connection_handler = [&](const std::shared_ptr<dap::ReaderWriter>& rw) {
        ASSERT_EQ(receive_message(rw), "client to server");
        ASSERT_TRUE(send_message(rw, "server to client"));
        sync_channel.put(true);
    };

    auto error_handler = [&](const char* err) { 
        FAIL() << "Server error occurred: " << err; 
    };

    auto server = dap::net::Server::create();

    // Initial server startup
    if (!server->start(test_port, connection_handler, error_handler)) {
        FAIL() << "Initial server startup failed";
        return;
    }

    // Multiple stop calls to test idempotency
    server->stop();
    server->stop();
    server->stop();

    // Restart server after stops
    if (!server->start(test_port, connection_handler, error_handler)) {
        FAIL() << "Server restart failed";
        return;
    }

    // Test client connection after restart
    auto client = dap::net::connect("localhost", test_port);
    ASSERT_NE(client, nullptr) << "Connection after restart failed";

    ASSERT_TRUE(send_message(client, "client to server"));
    ASSERT_EQ(receive_message(client), "server to client");

    sync_channel.take();

    // Cleanup with multiple stop calls
    server->stop();
    server->stop();
    server->stop();
    server.reset();
}
